(window.GIM_TUR_P=window.GIM_TUR_P||{})["SCM.6"]={"from":339,"s":[["\u0010y0\u0011 מִצְוָה לָתֵת שְׂכַר שָׂכִיר בִּזְמַנּוֹ, וְאִם אֵחֲרוֹ עוֹבֵר בְּלָאו; \u0010y1\u0011 אֶחָד שְׂכַר אָדָם אוֹ בְהֵמָה אוֹ כֵלִים. אֲבָל עַל שְׂכַר קַרְקַע, יֵשׁ מִי שֶׁאוֹמֵר שֶׁאֵינוֹ עוֹבֵר.\nכָּל הַכּוֹבֵשׁ שְׂכַר שָׂכִיר \u0010y2\u0011 כְּאִלּוּ נוֹטֵל נִשְׁמָתוֹ, \u0010y3\u0011 וְעוֹבֵר בַּחֲמִשָּׁה לָאוִין וַעֲשֵׂה.\nאֵיזֶהוּ זְמַנּוֹ, שְׂכִיר יוֹם \u0010y4\u0011 יֵשׁ לוֹ זְמַן לִתְּנוֹ לוֹ כָּל הַלַּיְלָה; לֹא נְתָנוֹ לוֹ, עוֹבֵר עָלָיו בַּבֹּקֶר מִשּׁוּם בַּל תָּלִין \u0005(וַיִּקְרָא יט, יג)\u0006. שְׂכִיר לַיְלָה זְמַנּוֹ לִתֵּן לוֹ כָּל הַיּוֹם; לֹא נְתָנוֹ לוֹ, עוֹבֵר עָלָיו בָּעֶרֶב \u0010y5\u0011 מִשּׁוּם בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ. \u0005(דְּבָרִים כד, טו)\u0006 \u0005הַגָּה: וּפוֹעֲלִים דִּידָן, שֶׁאֵין עוֹשִׂין מְלָאכָה עַד הַלַּיְלָה, \u0010y6\u0011 כֵּיוָן שֶׁשָּׁקְעָה עָלָיו חַמָּה עוֹבֵר עָלָיו מִשּׁוּם בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ; בַּלַּיְלָה, וְאִם עָשָׂה מְלָאכָה עַד הַלַּיְלָה, יֵשׁ לוֹ זְמַן כָּל הַלַּיְלָה \u0010y7\u0011 אַף עַל פִּי שֶׁלֹּא שְׂכָרוֹ\u0006 \u0005(בְּפֵרוּשׁ כֵּן, וַדַּאי)\u0006 \u0005אַדַּעְתָּא דְּהָכִי אַגְרֵהּ\u0006 \u0005(נִמּוּקֵי יוֹסֵף בְּשֵׁם תּוֹסָפוֹת פֶּרֶק הַמְקַבֵּל)\u0006.\nשְׂכִיר שָׁעוֹת, אִם כָּלָה שְׂכִירוּתוֹ בַּיּוֹם \u0010y8\u0011 יֵשׁ לוֹ תַּשְׁלוּם כָּל אוֹתוֹ יוֹם; אִם כָּלָה בַּלַּיְלָה, יֵשׁ לוֹ תַּשְׁלוּם כָּל אוֹתוֹ הַלַּיְלָה.\nשְׂכִיר שַׁבָּת, שְׂכִיר חֹדֶשׁ, שְׂכִיר שָׁנָה, שְׂכִיר שָׁבוּעַ, יָצָא בַּיּוֹם גּוֹבֶה כָּל אוֹתוֹ הַיּוֹם; יָצָא בַּלַּיְלָה גּוֹבֶה כָּל אוֹתוֹ הַלַּיְלָה.\nנָתַן טַלִּיתוֹ לְאֻמָּן לְתַקְּנָהּ בְּקַבְּלָנוּת, וּגְמָרָהּ, \u0010y9\u0011 כָּל זְמַן שֶׁהַטַּלִּית בְּיַד הָאֻמָּן אֵינוֹ עוֹבֵר. נְתָנוֹ לוֹ אֲפִלּוּ בַּחֲצִי הַיּוֹם כֵּיוָן שֶׁשָּׁקְעָה עָלָיו חַמָּה, עוֹבֵר \u0010y10\u0011 מִשּׁוּם בַּל תָּלִין, \u0010y11\u0011 \u0010c0\u0011 \u0005(וַיִּקְרָא יט, יג)\u0006 שֶׁקַּבְּלָנוּת הִיא כִּשְׂכִירוּת לְפָרְעוֹ בִּזְמַנּוֹ:\nהָאוֹמֵר לִשְׁלוּחוֹ: צֵא וּשְׂכֹר לִי פּוֹעֲלִים, וּשְׂכָרָם, וְאָמַר לָהֶם: שְׂכַרְכֶם עַל \u0010y12\u0011 בַּעַל הַבַּיִת, אֵין שׁוּם אֶחָד מֵהֶם עוֹבֵר עַל בַּל תָּלִין, וּמִיהוּ, בַּעַל הַבַּיִת עוֹבֵר מִשּׁוּם אַל תֹּאמַר לְרֵעֲךָ לֵךְ וָשׁוּב \u0005(מִשְׁלֵי ג, כח)\u0006. אִם אֵינוֹ טָרוּד \u0010y13\u0011 וּמְכַוֵּן לִדְחוֹתָם. וְאִם לֹא אָמַר: שְׂכַרְכֶם עַל בַּעַל הַבַּיִת, אֲפִלּוּ לֹא אָמַר לָהֶם שְׂכַרְכֶם עָלַי, אֶלָּא שְׂכָרָם סְתָם, הוּא חַיָּב בִּשְׂכָרָם, לְפִיכָךְ, הוּא עוֹבֵר מִשּׁוּם בַּל תָּלִין \u0005(וַיִּקְרָא יט, יג)\u0006. \u0005הַגָּה: \u0010y14\u0011 מִיהוּ, אִם הַפּוֹעֲלִים יוֹדְעִים שֶׁאֵין הַמְּלָאכָה שֶׁלּוֹ, אֵין הַשָּׁלִיחַ עוֹבֵר בִּסְתָם\u0006 \u0005(טוּר ס\"ז בְּשֵׁם הָרֹא\"שׁ שֶׁהָיָה אוֹמֵר כֵּן לְדַעַת הרמ\"ה)\u0006. \u0010y15\u0011\nעָבַר זְמַנּוֹ, אֵין בַּעַל הַבַּיִת עוֹבֵר מִשּׁוּם בַּל תָּלִין \u0005(וַיִּקְרָא יט, יג)\u0006. וּמִכָּל מָקוֹם חַיָּב לִתֵּן לוֹ מִיָּד, וּבְכָל עֵת שֶׁיִּשְׁהֶא עוֹבֵר עַל לָאו שֶׁל דִּבְרֵיהֶם, שֶׁנֶּאֱמַר אַל תֹּאמַר לְרֵעֲךָ וְגוֹ' \u0005(מִשְׁלֵי ג, כח)\u0006.\nשָׂכִיר שֶׁמַּכִּיר בְּבַעַל הַבַּיִת שֶׁאֵין דַּרְכּוֹ לִהְיוֹת בְּיָדוֹ מָעוֹת אֶלָּא בְּיוֹם הַשּׁוּק, אֵינוֹ עוֹבֵר בְּבַל תָּלִין \u0010y16\u0011 \u0005(וַיִּקְרָא יט, יג)\u0006, אֲפִלּוּ יֵשׁ לוֹ מָעוֹת; וּמִיּוֹם הַשּׁוּק וְאֵילָךְ, אִם אֵינוֹ נוֹתֵן לוֹ עוֹבֵר מִשּׁוּם אַל תֹּאמַר לְרֵעֲךָ וְגוֹ' \u0005(מִשְׁלֵי ג, כח)\u0006. \u0005הַגָּה: וְהוּא הַדִּין הָנֵי שֶׁאֵין דַּרְכָּן לְשַׁלֵּם עַד שֶׁיְּחַשְּׁבוּ עִם הַפּוֹעֲלִים, אֵינָם עוֹבְרִים \u0010y17\u0011 עַד שֶׁיְּחַשְּׁבוּ עִמָּהֶם\u0006 \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַמְקַבֵּל)\u0006.\nאֵין בַּעַל הַבַּיִת עוֹבֵר מִשּׁוּם בַּל תָּלִין \u0010y18\u0011 \u0005(וַיִּקְרָא יט, יג)\u0006, אֶלָּא אִם כֵּן תְּבָעוֹ הַשָּׂכִיר; לֹא תְּבָעוֹ, \u0010y19\u0011 אוֹ שֶׁתְּבָעוֹ וְלֹא הָיָה לוֹ מָעוֹת לִתֵּן לוֹ, \u0010c1\u0011 אוֹ שֶׁהִמְחָהוּ אֵצֶל שֻׁלְחָנִי לִתֵּן לוֹ וְקִבֵּל עָלָיו לִתֵּן לוֹ, אֵינוֹ עוֹבֵר, אֲפִלּוּ אֵין לְבַּעַל הַבַּיִת בְּיַד שֻׁלְחָנִי כְּלוּם. \u0010y20\u0011 וּמִכָּל מָקוֹם, אִם רָצָה הַשָּׂכִיר לַחֲזֹר בּוֹ שֶׁלֹּא לְקַבֵּל מֵהַשֻּׁלְחָנִי אֶלָּא מִבַּעַל הַבַּיִת, הָרְשׁוּת בְּיָדוֹ. \u0005הַגָּה: וְאִם קָנוּ מִיָּדוֹ, לֹא יוּכַל לַחֲזֹר בּוֹ (הָרֹא\"שׁ שָׁם וְטוּר, וְע\"ל ר\"ס צ\"א)\u0006.\nדִּינֵי שָׂכִיר שֶׁנִּשְׁבַּע וְנוֹטֵל, נִתְבָּאֵר בְּסִימָן פ\"ט:",["\u0003מצוה לתת שכר שכיר בזמנו כו' \u0004 ילפי' לה מדכתיב לא תבא עליו השמש ובסמוך יתבאר דהכובש שכר שכיר עובר בחמש' לאוין מ\"מ לא כתב הרמב\"ם והט\"ו כאן אלא דעובר בלאו משום דאינך לאוין אינו עובר אא\"כ אין דעתו לשלם לו כלל משא\"כ בלאו דלא תבא כו' דעובר מיד שעבר זמנו אף שדעתו לשלם לו ולא כע\"ש ששינה ל' הרמב\"ם והט\"ו וכתב ז\"ל מ\"ע ליתן שכר שכיר בזמנו דכתיב לא תעשוק כו' עד ואם אחרו עובר בלאו דכתיב בה כמו שיתבאר לפנינו ולא דק דב\"ה שאינו נותן בזמנו ודעתו ליתן לאחר זמנו אינו עובר משום לא תעשוק אלא משום לא תבא עליו השמש וגם לא דק לחלק בין הא למ\"ש בסמוך:","\u0003אחד שכר אדם כו' \u0004 ילפינן לה מדכתיב לא תעשוק שכר שכיר עני ואביון מאחיך מגרך אשר בארצך בשערך דמדכתי' לא תעשוק שכר כו' אשר בארצך ילפי' שעל כל אשר בארצך חייב על שכר אדם או בהמ' או כלים מיהו על שכר קרקע כתב הטור בשם הרמ\"ה (והוא היש מי אומר שכתב המחבר) דאינו עובר דדרשינן אשר בארצך ולא ארצך ממש:","\u0003כאלו נוטל נשמתו \u0004 ילפי' לה בגמרא מדכתיב גבי שכירות כי אליו הוא נושא את נפשו ופליגי בגמ' חד אמר נפשו של נגזל וחד אמר נפשו של גזלן ובפריש' כתבתי ראיות דכל אחד ועפ\"ר מ\"ש מזה:","\u0003ועובר בחמשה לאוין ועשה בגמ' מני להו והן לא תגזול (דלגופא לא איצטרך דנילף מריבית ואונאה ע\"ש בר\"פ א\"נ) לא תעשוק שכר שכיר ולא תעשוק את רעיך לא תלין לא תבא עליו השמש ועשה דביומו תתן שכרו. ואע\"ג דקצתם כתיבי בשכיר יום וקצתם בשכיר לילה וכמו שיתבאר מ\"מ ס\"ל להרמב\"ם והט\"ו שכתבו דעובר בחמשה לאוין (ומשמע דעובר ממש בהן בבל איחור שכר שכיר) דכיון דשם שכירות חד הוא נתחייב גם בשכיר יום אמה שנ' בשכיר לילה וכן איפכא וכן כ' ב\"י עפ\"ר:\u0004","\u0003יש לו זמן לתנו כל הלילה כו' \u0004 דמ\"ש לא תבא עליו השמש ע\"כ לא איירי בשכיר יום דהא שכירות אין משתלמת אלא לבסוף והיינו משתשקע השמש ואיך כ' רחמנא לא תבא עליו השמש אלא ע\"כ בשכיר לילה איירי דשכירתו ניתן להתבע בסוף הלילה ונתן התורה זמן לב\"ה להשתדל דמי השכירות כל היום ואזהריה התורה שלא יבא עליו השמש ליתן לו ומ\"ש לא תלין פעולת שכיר אתך עד בקר מיירי בשכיר יום ויש לו זמן כל הלילה רק שיתנו לו קודם אור הבוקר כן הוא בגמ' ורש\"י ועפ\"ר:","\u0003משום ביומו תתן שכרו \u0004 כן הוא ל' הגמ' והפוסקים ונ' דנקטי רישא דקרא ואחריו מיד כתיב לא תבא עליו השמש וכוונתו דעובר בתרוייהו בעשה ולא תעשה הכתובים במקרא זא\"ז וע\"ל סימן צ\"ז ובי\"ד ס\"ס כ\"ח כתבתי שדרך הגמ' לנקוט רישא דקרא וכוונתו לסיפ' דקרא וכ\"ש כאן דכונתו לתרוייהו וק\"ל:","\u0003וכיון ששקעה עליו החמה כו' \u0004 דה\"ל כשכיר שעות או שכיר שנה דבסעיפים שאחר זה:","\u0003אע\"פ שלא שכרו אדעת' דהכי \u0004 פי' ששכרו לעשות לו כסתם פועלים והרי פועלים דידן אינן עושין מלאכה עד הלילה:","\u0003יש לו תשלום כל אותו יום \u0004 פי' ולא יותר כיון דכלה מלאכתו קודם שקיעת החמה חל עליו האזהרות דביומו תתן שכרו ולא תבא עליו השמש וזהו הטעם דשכיר שבת כו' דבסעיף שאחר זה:","\u0003כל זמן שהטלית ביד האומן כו' \u0004 דאז אין פעולת שכיר מוטל על ב\"ה לעבור עליו שהרי תופס משלו כנגדו:","\u0003משום בל תלין כו' \u0004 כן הוא שם בברייתא ובטור וקשה דמשום ביומו תתן שכרו הל\"ל ובפרישה כתבתי משום דרוב שכיר יום אינן עוברין משום ביומו תתן כו' וכנ\"ל אלא משום בל תלין מ\"ה נקטינהו ג\"כ כאן כאלו אמר חיוב' דבל תלין דעלמא הוא חל כאן מיד ששקעה החמה אבל אין לתרץ ולומר דהרמב\"ם והטור סבירא לי' דהגמ' נקט משום דס\"ל דעובר בכל א' בכל ה' לאוין וכנ\"ל ס\"ב ומ\"ה נקטו בל תלין לרבותא דאפי' אותו עובר וכ\"ש משום ביומו תתן שכרו דז\"א דהא כבר כתבתי דגם להרמב\"ם והטור אינו עובר בחמשתן אלא הכובש שכרו ואין דעתו ליתנו להשכיר כלל משא\"כ כאן דלא איירי בכובש וק\"ל:","\u0003שקבלנות היא כשכירות \u0004 כ\"כ לאפוקי ממ\"ד אומן קונה בשבח כלי דאליביה כשהשביחו עשה השבח לעצמו וכשאח\"כ מסר הכלי עם השבח לב\"ה הרי הוא כמכר לו הפועל משלו ולא מחשבי הדמים שכר פעולה אלא כהלואה קמל\"ן דקיימא לן דאין אומן קונה בשבח כלי (וכמ\"ש לעיל סי' ש\"ו ס\"ב) וה\"ל שכר פעולה לגביה ב\"ה:","\u0003אין שום א' מהן עובר \u0004 דהא הב\"ה לא שכרם והשליח אין פעולתו עליו אלא א\"ל שבע\"ה יתן להם:","\u0003ומכוין לדחותו \u0004 פי' שאינו טרוד אלא מכוין לדחותו:","\u0003מיהו אם הפועלים יודעים כו' \u0004 דומי' דהכי כתב הט\"ו בריש סי' של\"ו בשכרו לעשות בשל חבירו סתם כו'. וע\"ד שפרשתיהו שם דר\"ל דהפועל ידע שהוא אינו שלו ועפ\"ר:","\u0003עבר זמנו אין כו' \u0004 בגמ' ילפי' לה מדכתיב לא תלין פעולת שכיר אתך עד בוקר דלא ה\"ל למימר עד בקר דלא תלין ג\"כ עד בקר משמע אלא להכי כתבו ללמדינו דאינו עובר אלא עד בקר ראשון:","\u0003אפי' יש לו מעות \u0004 פי' ואפי' תבעו בבקר ראשון דהא מתחלה מייאש נפשו שלא יתן לו עד יום השוק ואז לאו בר אעבור' לאו הוא וכנ\"ל:","\u0003עד שיחשבו עמהן וכתב שם דאפי' תבעו בזמנו בדבר שודאי חייב לו בלא חשבון מ\"מ לאו בר חיוב הוא כיון דלא הגיע זמן פרעונו עד שיחשבו והרי עדיין לא חשבו.\u0004","\u0003אא\"כ תבעו כו' \u0004 הכי דרשו מדכתיב לא תלין אתך מדעתך לאפוקי כשלא תבעו דאז השהייה היא מדעתו דפועל:","\u0003או שתבעו כו' או שהמחהו כו' דדרשינן אתך שיש לך אתך. אתך ולא כשהמחהו אצל חנוני.\u0004","\u0003ומ\"מ אם רצה השכיר \u0004 פי' ואפי' אם לא חזר החנוני מליתן לו מ\"מ כיון שאין לו בידו כלום ולא נתחייב לו במעמד ג' ואם רצה החנוני יכול לחזור בו מ\"ה גם הפועל יכול לחזור בו:"],["\u0003 שקבלנות היא כו' \u0004 בסמ\"ע כ' הטעם דאין אומן קונה בשבח כלי עיין בא\"ע סי' כ\"ח סט\"ו שם כתוב ב' דעות בזה ור\"י ס\"ל דקונה היינו משום חשש קדושין חוששין גם לדעת ר\"י ומקודשת מספק אבל לענין ממונא הכריע דלא כר\"י וכן פסק ב\"י שם ס\"ב אמנם דברי הטור בשם הרא\"ש צ\"ע וסתרי אהדדי ודו\"ק ועיין במפרשים האחרוני' ולעיל סי' ש\"ו ס\"ב כתבתי דהך דהכא מיירי אפי' למ\"ד אומן קונה בשבח כלי ע\"ש:","\u0003 או שהמחהו אצל שולחני כו' \u0004 ל' ספר חסידים סימן תתרע\"א אם תשכיר סופר לכתוב לך תתנה עמו שלא תהיה בבל תלין פעולת שכיר שמא כשיתבע לא יהי' לך ליתן לו ואע\"פ שתעשה תנאי עמו תתן לו כשיתבע אם תוכל ואין בזה מתנה על מ\"ש בתורה שהרי אמרו חכמים אדם מתנה עם פועל להאכילו לחם צר ומים לחץ אע\"פ שחייב להאכילו כסעודת שלמה עכ\"ל (עיין לעיל סי' קכ\"ו ס\"ב) ומ\"ש שם:"]],["הַשּׁוֹאֵל מֵחֲבֵרוֹ בְּהֵמָה אוֹ מִטַּלְטְלִים וְנֶאֶנְסוּ בְּיָדוֹ, כְּגוֹן שֶׁמֵּת אוֹ נִשְׁבַּר אוֹ נִשְׁבָּה, חַיָּב. \u0005הַגָּה: \u0010y0\u0011 \u0010c0\u0011 וְדַוְקָא שֶׁאֵרַע הָאֹנֶס מִכֹּחַ הַשּׁוֹאֵל; אֲבָל אִם אֵרַע הָאֹנֶס מִכֹּחַ הַמַּשְׁאִיל, פָּטוּר. \u0010c1\u0011 וְלָכֵן מִי שֶׁיֵּשׁ לוֹ מַשְׁכּוֹן אֵצֶל גּוֹי, וְהִשְׁאִילוֹ לַחֲבֵרוֹ לִקַּח עָלָיו עוֹד מָעוֹת, וְנִשְׂרַף הַמַּשְׁכּוֹן, פָּטוּר הַשּׁוֹאֵל, \u0010c2\u0011 דְּהָא בְּלָאו הָכִי הָיָה נִשְׂרָף מִכֹּחַ הַמַּשְׁאִיל (מָרְדְּכַי פֶּרֶק הַשּׁוֹאֵל)\u0006. \u0010y1\u0011 וְאֵין צָרִיךְ לוֹמַר שֶׁחַיָּב בִּגְנֵבָה וַאֲבֵדָה. אֲבָל כָּל קִלְקוּל שֶׁאֵרַע בָּהּ מֵחֲמַת מְלָאכָה שֶׁשְּׁאָלָהּ בִּשְׁבִילָה, לֹא מִבַּעְיָא אִם הֻכְחְשָׁה מֵחֲמַת מְלָאכָה שֶׁהוּא פָּטוּר, \u0010y2\u0011 אֶלָּא אֲפִלּוּ מֵתָה מֵחֲמַת מְלָאכָה, פָּטוּר; וְהוּא שֶׁלֹּא יְשַׁנֶּה לַעֲשׂוֹת בָּהּ דָּבָר אַחֵר חוּץ מֵהַמְּלָאכָה שֶׁשְּׁאָלָהּ בִּשְׁבִילָהּ; שֶׁאִם שִׁנָּה וְעָשָׂה בָּהּ מְלָאכָה אַחֶרֶת חוּץ מֵהַמְּלָאכָה שֶׁשְּׁאָלָהּ בִּשְׁבִילָהּ, \u0010y3\u0011 אֲפִלּוּ הִיא קַלָּה מִמֶּנָּה, תָּלִינָן דְּמֵחֲמַת אוֹתָהּ מְלָאכָה שֶׁשִּׁנָּה מֵתָה. \u0010y4\u0011 וַאֲפִלּוּ בְּאוֹתָהּ מְלָאכָה עַצְמָהּ אֶפְשָׁר לְשַׁנּוֹת, כְּגוֹן שֶׁשְּׁאָלָהּ לַחֲרֹשׁ, וְחָרַשׁ בָּהּ בַּיּוֹם וּבַלַּיְלָה שֶׁלֹּא כְּדֶרֶךְ כָּל הָאָרֶץ.\nנִכְחַשׁ הַבָּשָׂר מֵאֵלָיו, \u0010y5\u0011 \u0010c3\u0011 וְסוֹפוֹ לַחֲזֹר, פָּטוּר. אֲבָל אִם נִכְחֲשָׁה מֵאֵלֶיהָ וּמֵתָה אַחַר כָּךְ, שֶׁהוּא חַיָּב לְשַׁלֵּם, \u0010y6\u0011 כֵּיוָן שֶׁאֵינָהּ בְּעַיִן מְשַׁלֵּם כְּמוֹ שֶׁהָיְתָה בִּשְׁעַת שְׁאֵלָה.\nהַשּׁוֹאֵל בְּהֵמָה מֵחֲבֵרוֹ לֵילֵךְ דֶּרֶךְ יָדוּעַ, וּבָאוּ עָלָיו לִסְטִים בְּאוֹתוֹ הַדֶּרֶךְ, אוֹ חַיּוֹת רָעוֹת, וַאֲנָסוּהָ מִמֶּנּוּ, חָשִׁיב שַׁפִּיר מֵתָה מַחֲמַת מְלָאכָה. \u0005הַגָּה: \u0010c4\u0011 וְיֵשׁ חוֹלְקִין בְּזֶה וּסְבִירָא לְהוּ דְּלָא מִקְרֵי מֵחֲמַת מְלָאכָה, דַּהֲרֵי אַף בְּלֹא הֲלִיכַת הַדֶּרֶךְ אֶפְשָׁר שֶׁיָּבֹא לָהּ אֹנֶס כָּזֶה (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. אֲבָל הַמַּשְׁאִיל לַחֲבֵרוֹ שׁוּנְרָא לִרְדֹּף עַכְבָּרִים, \u0010y7\u0011 \u0010c5\u0011 וַאֲכָלוּהָ הָעַכְבָּרִים, מִקְרֵי מֵחֲמַת מְלָאכָה, דְּבָא לָהּ הָאֹנֵס מֵחֲמַת הַמְּלָאכָה, וְכָל כַּיּוֹצֵא בָּזֶה \u0005(טוּר)\u0006. בְּהֵמָה שֶׁנִּתְיַגְּעָה בִּמְלַאְכְתָּהּ וְנִתְחַמְּמָה וָמֵתָה אַחַר כָּךְ, אוֹ נִכְשְׁלָה בַדֶּרֶךְ וְנָפְלָה וָמֵתָה, מִקְרֵי מֵחֲמַת מְלָאכָה. וְדַוְקָא שֶׁהִרְגִּישׁ בְּעוֹדוֹ בַּמְלָאכָה, אֲבָל אִם לֹא הִרְגִּישׁ מִיָּד, \u0010c6\u0011 לֹא יָכוֹל לִשָּׁבַע דְּמֵתָה מֵחֲמַת מְלָאכָה, דְּדִילְמָא בְּלָאו הָכִי נַמֵּי הָיְתָה מֵתָה \u0005(שָׁם בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.\nהַשּׁוֹאֵל בְּהֵמָה, חַיָּב בִּמְזוֹנוֹתֶיהָ \u0010c7\u0011 מִשָּׁעָה שֶׁמְּשָׁכָהּ עַד סוֹף יְמֵי שְׁאִילָתָהּ. \u0005הַגָּה: \u0010c8\u0011 וְיֵשׁ אוֹמְרִים דְּלָא בָּעִינָן מְשִׁיכָה, אֶלָּא \u0010y8\u0011 מִיָּד שֶׁנִּסְתַּלְּקוּ הַבְּעָלִים (טוּר כְּדַעַת הר\"י וְהָרֹא\"שׁ)\u0006 וע\"ל רֵישׁ סִימָן רצ\"א וש\"ז. וְאִם כָּחַשׁ בְּשָׂרָהּ כְּחָשָׁא דְּלָא הָדַּר, חַיָּב לְשַׁלֵּם מַה שֶּׁפָּחֲתָה בְדָמִים. וְאִם הָיָה הַכַּחַשׁ מֵחֲמַת מְלָאכָה, פָּטוּר, וְיִשָּׁבַע שְׁבוּעַת הַשּׁוֹמְרִים שֶׁמֵּחֲמַת מְלָאכָה כָּחֲשָׁה.\nהַשּׁוֹאֵל פָּרָה מֵחֲבֵרוֹ, וְשִׁלְּחָהּ לוֹ הַמַּשְׁאִיל בְּיַד בְּנוֹ אוֹ בְּיַד שְׁלוּחוֹ אוֹ בְּיַד עַבְדּוֹ, אֲפִלּוּ שִׁלְחָהּ לוֹ בְּיַד בְּנוֹ אוֹ בְּיַד עַבְדּוֹ אוֹ בְּיַד שְׁלוּחוֹ שֶׁל שׁוֹאֵל, וּמֵתָה קֹדֶם שֶׁתִּכָּנֵס לִרְשׁוּת הַשּׁוֹאֵל, הֲרֵי זֶה פָּטוּר. וְאִם אָמַר לוֹ הַשּׁוֹאֵל: שַׁלְּחָהּ לִי בְּיַד בְּנִי אוֹ בְּיַד עַבְדִּי, אוֹ בְּיַד שְׁלוּחִי אוֹ בְּיַד בִּנְךָ, \u0010y9\u0011 אוֹ בְּיַד עַבְדְּךָ הָעִבְרִי אוֹ בְּיַד שְׁלוּחֲךָ, אוֹ שֶׁאָמַר לוֹ הַמַּשְׁאִיל: הֲרֵינִי מְשַׁלְּחָהּ לְךָ בְּיַד בִּנְךָ אוֹ עַבְדְּךָ, אוֹ בְּיַד שְׁלוּחֲךָ אוֹ בְּיַד בְּנִי, אוֹ בְּיַד עַבְדִּי הָעִבְרִי אוֹ בְּיַד שְׁלוּחִי, וְאָמַר לוֹ הַשּׁוֹאֵל: שְׁלַח, וְשִׁלְּחָהּ וָמֵתָה בַּדֶּרֶךְ, הֲרֵי זֶה חַיָּב.\nשִׁלְּחָהּ לוֹ הַמַּשְׁאִיל בְּיַד עַבְדּוֹ הַכְּנַעֲנִי, אַף עַל פִּי שֶׁאָמַר לֵהּ הַשּׁוֹאֵל: שְׁלַח, וָמֵתָה, פָּטוּר, שֶׁיָּדוֹ כְּיַד רַבּוֹ וַעֲדַיִן לֹא יָצְאָה מֵרְשׁוּת הַמַּשְׁאִיל.\nאָמַר לוֹ הַשּׁוֹאֵל: \u0010y10\u0011 \u0010c9\u0011 הַכִּישָׁהּ בְּמַקֵּל וְהִיא תָּבֹא מֵאֵלֶיהָ, וְעָשָׂה הַמַּשְׁאִיל כָּךְ, אֵין הַשּׁוֹאֵל חַיָּב בָּהּ עַד שֶׁתִּכָּנֵס לִרְשׁוּתוֹ.\nוְכֵן בְּשָׁעָה שֶׁמַּחֲזִירָהּ הַשּׁוֹאֵל לַבְּעָלִים, אִם שִׁלְּחָהּ בְּיַד אַחֵר וָמֵתָה קֹדֶם שֶׁהִגִּיעַ לִרְשׁוּת הַמַּשְׁאִיל, הֲרֵי זֶה חַיָּב, שֶׁעֲדַיִן הִיא בְּאַחֲרָיוּת הַשּׁוֹאֵל. \u0005וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין אִם הֶחֱזִירָהּ \u0010y11\u0011 לְיַד אֵשֶׁת הַמַּשְׁאִיל וְנֶאֶנְסָה, חַיָּב (בֵּית יוֹסֵף מס\"ב בְּשֵׁם הָרַשְׁבָּ\"א)\u0006 \u0005(וְעַיֵּן לְעֵיל בְּסִימָן ע\"ב סל\"א וּבְס\"ס ק\"כ מ\"ש מִזֶּה)\u0006, וְעַיֵּן לְעֵיל סִימָן רצ\"א סָעִיף כ\"א. וְאִם שִׁלְּחָהּ מִדַּעַת הַמַּשְׁאִיל עַל יְדֵי אַחֵר וָמֵתָה, פָּטוּר. שִׁלְּחָהּ בְּיַד עַבְדּוֹ הַכְּנַעֲנִי, אַף עַל פִּי שֶׁאָמַר לוֹ הַמַּשְׁאִיל: שְׁלַח, אִם מֵתָה בַּדֶּרֶךְ, חַיָּב, שֶׁיַּד הָעֶבֶד כְּיַד רַבּוֹ וַעֲדַיִן לֹא יָצְאָה מִיַּד הַשּׁוֹאֵל. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהֶחֱזִירָהּ תּוֹךְ יְמֵי \u0010c10\u0011 שְׁאִילָתָהּ; אֲבָל אִם הֶחֱזִירָהּ אַחַר יְמֵי שְׁאִילָתָהּ, יָצְתָה מִדִּין שְׁאִילָה \u0010y12\u0011 וַהֲרֵי הוּא כְּשׁוֹמֵר שָׂכָר. וְהוּא הַדִּין אִם הִיא עֲדַיִן בְּבֵיתוֹ שֶׁל שׁוֹאֵל, כֵּיוָן שֶׁעָבְרוּ יְמֵי שְׁאִילָתָהּ יָצָא מִדִּין שׁוֹאֵל וַהֲרֵי הוּא כְּשׁוֹמֵר שָׂכָר. \u0005הַגָּה: וְאִם אָמַר לוֹ: שְׁלַח, וְעַד שֶׁלֹּא הִסְפִּיק לִשְׁלֹחַ מֵת, לֹא יִשְׁלַח, \u0010y13\u0011 דְּהָא נָפַל קַמֵּי יָתְמֵי; \u0010y14\u0011 וְאִם שָׁלַח, סָפֵק אִם חַיָּב בְּאַחֲרָיוּתוֹ (מָרְדְּכַי ר\"פ הַשּׁוֹאֵל)\u0006.",["\u0003ודוקא שאירע אונס מחמת השואל כו' \u0004 ע' בע\"ש שכ' ז\"ל אבל אם אירע שלא מחמת השואל כגון השואל בית מחבירו ונשרף באונס אינו חייב לשלמו עכ\"ל ולא דק דבכה\"ג בל\"ה פטור משום דאין דין שומרים בעבדים וקרקעות וכמ\"ש בע\"ש בעצמו בסי' ש\"א ס\"א:","\u0003וא\"צ לומר שחייב בגניבה ואבידה \u0004 עפ\"ר שם כתבתי לשון הגמרא דפרק השואל דהוצרך לומר חייב שואל בגניבה ואבידה מק\"ו דש\"ש אבל לא נלמוד מדחייב רחמנא לשואל בשבורה ומתה דה\"א דוקא שבורה ומתה דא\"א לבעלים להחזירה ולהביאה משא\"כ בגניבה ואבידה דה\"א דהבעלים יטריחו להדר אחר הגנב ולהדר' לרשותו קמ\"ל ומ\"ה הוצרך הטור והמחבר לכתוב ואצ\"ל ולא סמכו אפשיטותו דכ\"ש הוא מחיוב אונסין:","\u0003אלא אפי' מתה כו' \u0004 דכיון דלא שינה בה וברשות בעלים עבד בה מלאכה הבעלים הפסידו לנפשם דלא הי' להם להשאיל פרה למלאכ' שאינה יכולה לעמוד בה:","\u0003אפי' היא קלה \u0004 עיין לעיל סי' ש\"ח ושי\"א דמסקנת הרא\"ש והטור הוא דמותר לשנות הבהמ' למלאכ' אחרת שאינו כבידה ממנה וכ\"ש לקלה ממנה. וא\"ל דבשואל דכל הנאה דידיה החמירו דאין טעם לדבר כיון דעכ\"פ מחמת מלאכ' מתה ובמתה מחמת מלאכ' פטריה רחמנא לשואל ומ\"ש זה מהא דכתב הטור והמחבר בסי' שמ\"ב בשואל שהשאיל לאחרים ונפסד מחמת מלאכה דכשיש להשואל ראייה שלא שינה בה השני מאשר השאיל והרשה לו עליה דפטור השואל לכן נראה דל\"ק כאן דלא ישנה אפי' לקלה ממנו אלא קאמר שאם שינה אפי' דבר קל אזי תלינן דמחמת השינוי מתה ומיידי דוקא באה יש לפנינו איזה ענין שנוכל לתלות בו ולו' שמחמת השינוי מתה וכעין שכ' הטור והמחבר בד\"ס ש\"ט ס\"ב בהשוכר בהמה להוליכה למקום ידוע והוליכה למקום אחר דאמרי' אם אויר המקום משונה תלינן בו המיתה וגם בסי' רצ\"א בדין תחלתו בפשיעה וסיפו באונם דחייב בו הש\"ח אם יש צד לפנינו לתלות האונס בהפשיע' אפי' בצד רחוק וכמ\"ש שם ודוק:","\u0003ואפי' באותה מלאכ' עצמה אפש' לשנות \u0004 פי' מיקרי שינוי להתחייב בה.","\u0003וסופו לחזור פטור \u0004 דאין דין שבת בבהמה ועפ\"ר שם כתבתי דאפי' למ\"ד שכ' הט\"ו בשמו ס\"ס ש\"ז דחייב ה\"מ התם דכ' דנולד המכה בפשיע' ומכחה נכחש אבל הכא כתב דנכחש מאליה ואליבא דמ\"ד דחייב לעיל איירי כאן דנכחש כן באונס אע\"ג דשואל הוא וחייב באונסין מ\"מ כיון דיחזור לבסוף ס\"ל דפטור ולא כב\"י דהביא כאן על דברי הטור אותו פלוגת' וכתב דס\"ל להטור כחכמי צרפת דפטרי ואחריו נמשך ג\"כ מור\"ם והע\"ש וכמ\"ש ג\"כ בס\"ס ש\"ז והנלע\"ד כתבתי ודו\"ק:","\u0003כיון שאינה בעין כו' \u0004 דאמרי' תחילת כחישתה תחילת מיתתה הוא ומאות' שעה נתחייב לשלם:","\u0003ואכלוה העכברים כו' \u0004 כן הוא בגמרא בפ' השואל בלישנ' קמא ובטור כ' בשם הרא\"ש דאפי' אכלה השונרא עכברים טובא וחביל ומת ג\"כ פטור דה\"ל כמתה מחמת מלאכה ואע\"ג דלאו מחמת מלאכ' ממש היא כולי האי דהא לרדוף העכברים שאלה לו ולא לאכול מהן מ\"מ כיון דאינה מתה אלא מחמת אכילה מקרי מחמת מלאכה וכן הוא בגמ' שם באיכא דאמרי וה\"ל למור\"ם לכתוב זה ומינה נלמד במכ\"ש להא דבשע' רדיפ' חברו עליה העכברי' ואפשר דס\"ל להלכ' כלישנא קמא מיהו בת\"ה סי' שכ\"ח משמע איפכ' דבאכל' עכברים טובא ומתה הוי מתה מחמת מלאכ' טפי מרדפוה עכברים וחברו עכברים עליה ואכלוה וי\"ל דמ\"ה נקט מור\"ם לרבותא ודוק ☜ וה\"ה אם שאל כלים להלחם עם השונאים ונפלו בני העיר ביד השונאים ולקחו הכלי זיין הוה מחמת מלאכ' ופטור כ\"כ בת\"ה סי' שכ\"ח ד\"מ ר\"ס זה:","\u0003מיד שנסתלקו הבעלים כו' \u0004 ואע\"ג דהמשאיל יכול לחזור בו כל זמן שלא משך הבהמה מ\"מ כיון דלא חזר בו ונסתלק הבעל משמיר' הבהמה מחמת שקיבל השומר שמירתו עליו נתחייב באונסין:","\u0003או ביד עבדך העברי \u0004 לאפוקי כנעני וכמ\"ש המחבר בסעיף שאחר זה.","\u0003הכישה במקל כו' כן דעת הרמב\"ם ובטור כתב שהרא\"ש חולק על זה ועפ\"ר שם כתבתי טעם פלוגתתן והמחבר סתם בדעת הרמב\"ם וכן פסק בבית יוסף ע\"ש.\u0004","\u0003ליד אשת המשאיל כו'. \u0004 אף על גב דכל המפקיד על דעת אשתו ובניו הוא מפקיד וכמ\"ש הטור והמחבר לעיל בסי' רצ\"א שואל דכל הנא' שלו שאני ועמ\"ש שס עוד מזה ובסימן רצ\"א סעיף כ\"א ובסי' ע\"ב סל\"א:","\u0003והרי הוא כשומר שכר. \u0004 דהואיל ונהנ' ממנה בימי שאילתה תקנו שישאר עליה לפחות כש\"ש עד שיבא ליד בעליה.","\u0003דהא נפל קמי יתמי כו'. \u0004 עיין מ\"ש הט\"ו לעיל בסי' קכ\"ב בדין שליחות דלא יתן אפי' לשלוחו בעדים בלא הרשאה מה\"ט דלמא ימות כו' ע\"ש:","\u0003ומ\"ש ואם שלח ספק אם חייב כו'. \u0004 מל' המרדכי שם וע' בטור ובדברי המחבר דכתב בסי' קכ\"ב ס\"ז דגם בהרשא' אם לא הקנהו על גבי קרקע נתבטלה ההרשאה אם מת המפקיד:"],["\u0003 ודוקא שאירע אונס מחמת השואל \u0004 ע' בסמ\"ע סק\"א במה שהשיג על הע\"ש שכ' לאפוקי השואל בית מחבירו ונשרף כו' משום דבכה\"ג בלא\"ה פטור דאין דין שומרין בקרקעות יפה השיג עליו ועוד יש להשיג עליו דשאל בית האונס הוי מכח השואל כיון דברשותו הוא ודוק:","\u0003 ולכן מי שיש לו כו' \u0004 ועוד איתא מרדכי שם טעם אחר דלא נקנה לו המשכון כיון שלא משכנו ומביאו הסמ\"ע לעיל סוף סי' ע\"ב סעיף קטן קכ\"ז וע\"ש:","\u0003 דהא בלא\"ה נשרף מכח המשאיל כו' \u0004 כדלעיל סימן ע\"ב סעיף מ\"ד:","\u0003 וסופו לחזור פטור \u0004 עיין בסמ\"ע ס\"ק ו' עד ולא כב\"י כו' דברי הב\"י וסייעתו נכונים והעיקר דגם כאן יש חולקין דחייב והוי ספיקא דדינא וכמש\"ל סי' ש\"ז ס\"ו ע\"ש:","\u0003 ויש חולקין כו' \u0004 וכן נרא' לי עיקר וכמ\"ש הרמב\"ן ומביאו ב\"י וז\"ל והא דאמרי' מתה מחמת מלאכ' דפטור קשי' לי מיגרע גרע כיון דכי מתה מחמ' מיתת עצמ' חייב אע\"ג דמלאך המות הוא דקטל' ומה לי הכא ומ\"ל התם כי מתה מחמת מלאכ' דשואל דמ\"מ איהו גרם לה היכא מיפטר וי\"ל דשואל ודאי חייב באונסי' אבל לא בפשיע' דמשאיל וכאן משאיל פשע בה שהשאילו למלאכ' והיא אינה יכול' לסבול אות' וכן כתב הרשב\"א והריב\"ש סי' תכ\"ג א\"כ כאן שלא פשע המשאיל חייב השואל ול\"ד לשונרא דקטלוה עכברים דהשאיל' לצורך עכברים ודוק עיין בתשו' רשד\"ם סי' תל\"ה:","\u0003 ואכלוה העכברי' כו' \u0004 וה\"ה אם שלח כלים להלחם עם השונאים ונפלו בני העיר ביד השונאים ולקחו הכלי זיין הוי מחמת מלאכה ופטור כן כתב בת\"ה סי' שכ\"ח ומביאו ד\"מ ר\"ס זה והביאו ג\"כ בסמ\"ע והבי' ראיה מהך דינא דחברו עליה עכברים וקטלוה ואינו נראה בעיני דהכא מיקרי שפיר מתה מחמת מלאכ' שמחמת שתרצה לעשות מלאכת' בעצמה להרוג העכברים חברו עליה וקטלוה וא\"כ פשע המשאיל אבל בכלי המלחמ' ודאי אין הכלים עצמם עושים המלאכ' רק הבעל מלחמ' וקרי מתה מחמת מלאכ' הבעל מלחמ' שלא נצח מלחמה ומחמת כן נלקחו מהם הכלי זיין ולא פשע המשאיל והלכך על הכלים ה\"ל אונסים וחייב כן נ\"ל ונ\"ל דהת\"ה סובר כהמחבר בס\"ג אבל להיש חולקין חייב ודוק וכן עיקר:","\u0003 לא יוכל לישבע כו' \u0004 ולכך חייב והמחבר השמיט זה משום שתמה בספרו ב\"ה על הרא\"ש וטור וז\"ל יש לתמוה דאטו משום שמא מחייבי' ליה אדרבה זה ראי' לומר דכיון דמתה בדרך מסתמא מחמת מלאכה מתה ואינו צריך לישבע אלא שמתה בדרך ופטור עכ\"ל ולק\"מ דכל שומר צריך לישבע שיודע בבירור אבל כשא\"י א\"כ חייב ש\"ד ואין נשבעין ש\"ד באינו יודע וכמ\"ש לעיל סי' רצ\"א סכ\"ו וכן בכמה דוכתי ואפשר עיקר סברתו דמסתמא מחמת מלאכה מתה אבל ג\"ז אינו כיון דלא הרגיש בה עיפא וטורח הדרך גם ר\"י נ\"ל ח\"ג כ' כהרא\"ש גם בת\"ה סי' של\"ג הביא דברי הרא\"ש וטור בסתם וכן עיקר ובב\"י וד\"מ הביאו דברי הנ\"י פ' הגוזל ומאכיל והר\"ב השמיטו ונראה דלא ס\"ל כוותיה משום דהרא\"ש וטור שהעתיק כאן דבריהם פליגי עליה וכמ\"ש לעיל סי' רצ\"א ע\"ש ודוק:","\u0003 משעה שמשכ' \u0004 וכן כיון שמשך הבהמ' או הכלי חייב באונסים אע\"ג שלא נשתמש בהן וכ\"ש הוא מחזרה דלקמן סי' שמ\"א ס\"ה כדמוכח בש\"ס פ' האיש מקדש (קידושין דף מ\"ז ע\"ב) וכן הוא בתוס' שם להדיא ע\"ש והכי מוכח מהרא\"ש ושאר פוסקים ועוד העליתי לעיל סי' ע\"ב ס\"ד ס\"ק ל' דמי שהפקיד כלי אצל חבירו בין שהוא ש\"ח או ש\"ש ואח\"כ נתן לו רשות להשתמש בו הוי שואל אע\"פ שעדיין לא נשתמש בו ע\"ש עיין בתשו' הרא\"ן ששון סי' קמ\"ד:","\u0003 וי\"א דלא בעינן משיכה כו' \u0004 ועיין בתשובת ן' לב ס\"א כלל י\"ז סימן צ\"ו דיכול המוחזק לו' קים לי כהרמב\"ם עיין בתשובת ר\"ל ן' חביב סימן צ\"ד:","\u0003 הכיש' במקל כו' \u0004 כן הוא דעת הרמב\"ם ובטור כתב שהרא\"ש חולק על זה והמחבר סתם כדעת הרמב\"ם וכן פסק בבית יוסף וכן כתב בסמ\"ע וכן עיקר דכן הוא דעת ר\"ח והתוספו' וה\"ה והר\"ן ונ\"י ונרא' דאף הרא\"ש לא פסק כן אלא משום דאזל לשטתו דסביר' ליה דמיד שנסתלקו הבעלי' חייב השומר בשמירתו וכן משמע להדיא מדבריו פ' השואל שהביא בית יוסף לעיל ר\"ס ש\"ז אבל למאן דפסק התם דאינו חייב עד שימשוך א\"כ ה\"ה הכא אם כן קשה על הרב רמ\"א דכאן סתם כהרמב\"ם ומחבר ולעיל הביא דעת הרא\"ש וכן מוכח להדיא מדברי ה' המגיד והנ\"י שהבאתי לעיל סי' רצ\"א סעיף א' [ב] דלמ\"ד הכישה במקל חייב [פטור] כ\"ש דבעלמא בעיא משיכה ע\"ש וצ\"ע. וכ' עוד בנ\"י בשם הר\"ן שאפי' אמר בפי' הכישה במקל ואתחייב אני לך פטור ומביאו ב\"י וד\"מ:","\u0003 אבל אם החזירה אחר כו' \u0004 עיין בתשובת ר\"ש כהן ס\"ב סי' ק\"ך:"]],["הַשּׁוֹאֵל \u0010c0\u0011 מֵחֲבֵרוֹ כְּלִי אוֹ בְהֵמָה סְתָם, הֲרֵי \u0010y0\u0011 הַמַּשְׁאִיל \u0005תּוֹבְעוֹ\u0006 בְּכָל עֵת שֶׁיִּרְצֶה. שְׁאָלוֹ לִזְמַן קָצוּב, כֵּיוָן שֶׁמָּשַׁךְ וְזָכָה בוֹ, אֵין הַבְּעָלִים יְכוֹלִים לְהַחֲזִירוֹ מִתַּחַת יָדוֹ עַד סוֹף יְמֵי \u0010y1\u0011 הַשְּׁאִילָה; וַאֲפִלּוּ מֵת הַשּׁוֹאֵל, הֲרֵי הַיּוֹרְשִׁים מִשְׁתַּמְּשִׁים בַּשְּׁאִילָה עַד סוֹף הַזְּמַן.\nהַשּׁוֹאֵל פּוּנְדָק \u0010y2\u0011 מֵחֲבֵרוֹ לְלִינָה, אֵין פָּחוֹת מִיּוֹם אֶחָד; לִשְׁבִיתָה, אֵין פָּחוֹת מִשְּׁנֵי יָמִים; לְנִשּׂוּאִין, אֵין פָּחוֹת מִשְּׁלֹשִׁים יוֹם. שָׁאַל חָלוּק מֵחֲבֵרוֹ לֵילֵךְ בּוֹ לְבֵית הָאָבֵל, כְּדֵי שֶׁיֵּלֵךְ וְיַחֲזֹר; שְׁאָלוֹ לְבֵית הַמִּשְׁתֶּה, כָּל אוֹתוֹ הַיּוֹם; שְׁאָלוֹ לַעֲשׂוֹת הַמִּשְׁתֶּה שֶׁלּוֹ, \u0010y3\u0011 אֵין פָּחוֹת מִשִּׁבְעָה יָמִים. \u0010y4\u0011 \u0005וְיֵשׁ אוֹמְרִים לְבֵית הָאָבֵל אֵינוֹ רַשַּׁאי לִטְּלוֹ עַד שֶׁיֵּצְאוּ יְמֵי אֲבֵלוּת, וּבָרֶגֶל עַד שֶׁיֵּצְאוּ יְמֵי הָרֶגֶל, וּבַמִּשְׁתֶּה עַד שֶׁיֵּצְאוּ יְמֵי הַמִּשְׁתֶּה (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְעַיִּןִ בִּי\"ד סִימָן ש\"מ.\nהִנִּיחַ לָהֶם אֲבִיהֶם פָּרָה שְׁאוּלָה, \u0010y5\u0011 מִשְׁתַּמְּשִׁים בָּהּ \u0010y6\u0011 כָּל יְמֵי \u0010y7\u0011 שְׁאִילָתָהּ, וְאֵין חַיָּבִין בְּאָנְסֶיהָ אֲפִלּוּ נִשְׁתַּמְּשׁוּ בָהּ; אֲבָל חַיָּבִים עָלֶיהָ \u0010c1\u0011 כְּשׁוֹמֵר שָׂכָר \u0005(וע\"ל סִימָן ע\"ב ס\"י)\u0006, \u0010c2\u0011 אֲפִלּוּ לֹא נִשְׁתַּמְּשׁוּ בָהּ; וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אָמַר הַמַּשְׁאִיל לַיְתוֹמִים: הַחֲזִירוּ לִי הַפָּרָה שֶׁהִשְׁאַלְתִּי אֶת אֲבִיכֶם אוֹ קַבְּלוּ עֲלֵיכֶם חִיּוּב \u0010y8\u0011 \u0010c3\u0011 אֳנָסִים, שׁוֹמְעִין לוֹ:\nחָשְׁבוּ שֶׁהִיא שֶׁל אֲבִיהֶם, וּטְבָחוּה וַאֲכָלוּהָ, מְשַׁלְּמִים דְּמֵי בָּשָׂר בְּזוֹל, \u0010y9\u0011 שֶׁהוּא שְׁנֵי שְׁלִישִׁים, \u0010y10\u0011 וְהָעוֹר יְשַׁלְּמוּ \u0010y11\u0011 \u0010c4\u0011 כֻּלּוֹ. וְאִם הִנִּיחַ לָהֶם נְכָסִים \u0010y12\u0011 \u0010c5\u0011 וּטְבָחוּה, מְשַׁלְּמִים דָּמֶיהָ מִנְּכָסָיו.\nהַשּׁוֹאֵל כְּלִי מֵחֲבֵרוֹ לַעֲשׂוֹת בּוֹ מְלָאכָה פְּלוֹנִית, כֵּיוָן שֶׁמָּשַׁךְ הַשּׁוֹאֵל, \u0010y13\u0011 אֵין הַמַּשְׁאִיל יָכוֹל לְהַחֲזִירוֹ מִתַּחַת יָדוֹ עַד שֶׁיַּעֲשֶׂה בּוֹ אוֹתָהּ מְלָאכָה. וְכֵן אִם שָׁאַל מִמֶּנּוּ בְּהֵמָה לֵילֵךְ בָּהּ לְמָקוֹם פְּלוֹנִי, אֵינוֹ יָכוֹל לְהַחֲזִירָהּ מִיַּד הַשּׁוֹאֵל עַד שֶׁיֵּלֵךְ בָּהּ לְשָׁם וְיַחֲזֹר.\nהַשּׁוֹאֵל כְּלִי מֵחֲבֵרוֹ לְהִשְׁתַּמֵּשׁ בּוֹ, וְאָמַר לֵהּ: הַשְׁאִילֵנִי דָּבָר פְּלוֹנִי בְּטוֹבָתְךָ; \u0010y14\u0011 כְּלוֹמַר, אֵין אַתָּה מַשְׁאִיל לִי דָּבָר זֶה כְּדֶרֶךְ כָּל הַמַּשְׁאִילִין, אֶלָּא כְּפִי טוֹבַת לִבְּךָ וְנִדְבוּתְךָ שֶׁאֵינְךָ מַקְפִּיד עַל הַזְּמַן; אִם קָנוּ מִיַּד הַמַּשְׁאִיל עַל זֶה, הֲרֵי הַשּׁוֹאֵל מִשְׁתַּמֵּשׁ בּוֹ לְעוֹלָם, עַד שֶׁיִּתְבַּטֵּל הַכְּלִי מִלַּעֲשׂוֹת מְלַאכְתּוֹ, \u0010y15\u0011 וְיַחֲזִיר שְׁבָרָיו אוֹ שְׁיָרָיו; \u0010y16\u0011 וְאֵין הַשּׁוֹאֵל רַשַּׁאי לַחֲזֹר וּלְתַקֵּן הַכְּלִי אוֹ לַעֲשׂוֹתוֹ פַּעַם אַחֶרֶת. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהָאוֹמֵר: הַשְׁאִילֵנִי כְּלִי זֶה בְּטוּבוֹ, שָׁאוּל הוּא לְעוֹלָם, דִּבְטוּבוֹ מַשְׁמָע כָּל זְמַן שֶׁהוּא טוֹב; \u0010y17\u0011 וַאֲפִלּוּ הֶחֱזִירוֹ לַמַּשְׁאִיל, חוֹזֵר וְנוֹטְלוֹ מִמֶּנּוּ כְּשֶׁיִּצְטָרֵךְ. וְדַוְקָא שֶׁקָּנוּ מִן הַמַּשְׁאִיל, אֲבָל לֹא קָנוּ מִן הַמַּשְׁאִיל, אֵינוֹ נוֹטְלוֹ מִמֶּנּוּ כְּשֶׁהֶחֱזִירוֹ. \u0010y18\u0011 נִשְׁבָּר, מַחֲזִיר לוֹ שְׁבָרָיו (טוּר ס\"ה בְּשֵׁם הָרֹא\"שׁ)\u0006.\nהָאוֹמֵר לַחֲבֵרוֹ: הַשְׁאִילֵנִי קַרְדֹּם לַעֲדֹר בּוֹ הַפַּרְדֵּס הַזֶּה, עוֹדֵר בּוֹ אוֹתוֹ הַפַּרְדֵּס בִּלְבַד, וְאֵינוֹ רַשַּׁאי לַעֲדֹר בּוֹ פַּרְדֵּס אַחֵר, \u0010y19\u0011 אֲפִלּוּ הוּא כָּמוֹהוּ. אָמַר לוֹ: פַּרְדֵּס, סְתָם, עוֹדֵר בּוֹ פַּרְדֵּס אֶחָד אֵי זֶה שֶׁיִּרְצֶה, אֲפִלּוּ אֵינוֹ שֶׁלּוֹ. שְׁאָלוֹ לַעֲדֹר בּוֹ \u0010y20\u0011 פַּרְדֵּסִים הַרְבֵּה שֶׁלּוֹ, עוֹדֵר בּוֹ כָּל פַּרְדֵּסִים שֶׁלּוֹ; וַאֲפִלּוּ נִשְׁחַת כָּל הַבַּרְזֶל בָּעֲדִירָה, מַחֲזִיר לוֹ הַנִּצָּב שֶׁל עֵץ. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּדַוְקָא בְּאוֹתָהּ שָׁנָה, אֲבָל לֹא בְּשָׁנָה אַחֶרֶת.\nהָאוֹמֵר לַחֲבֵרוֹ: הַשְׁאִילֵנִי שֹׁקֶת זֶה, וְנָפַל, אֵינוֹ יָכוֹל לַחֲזֹר וְלִבְנוֹתוֹ. אָמַר לֵהּ: הַשְׁאִילֵנִי שֹׁקֶת, סְתָם, וְנָפַל, חוֹזֵר וּבוֹנֶה עַד שֶׁיַּשְׁקֶה כָּל שְׂדוֹתָיו. אָמַר לֵהּ: הַשְׁאִילֵנִי מְקוֹם \u0010y21\u0011 שֹׁקֶת, הֲרֵי זֶה בּוֹנֶה בְּכָל מָקוֹם שֶׁיִּרְצֶה בְּקַרְקַע הַמַּשְׁאִיל, וּבוֹנֶה מְקוֹם הַשֹּׁקֶת שֶׁיַּסְפִּיק לוֹ לְהַשְׁקוֹת מִמֶּנָּה כָּל שְׂדוֹתָיו אוֹ כָּל בְּהֵמוֹתָיו לְפִי מַה שֶּׁהִתְנָה עִם הַמַּשְׁאִיל, וְהוּא שֶׁלָּקַח מִמֶּנּוּ בְּקִנְיָן עַל זֶה:",["\u0003המשאיל תבעו בכל עת כו' \u0004 דדוק' לסתם הלואה דלהוצא' נתנה נתנו חכמים שיעור ל' יום וכמ\"ש הט\"ו לעיל ר\"ס ע\"ג משא\"כ בשאל' דהדרא בעינא ולאפוקי מדעת ר\"ת שמדמהו לסתם הלוא' ועד\"ר:","\u0003ואפי' מת השואל כו'. \u0004 בסמוך ס\"ג יתבאר זה:","\u0003ללינה אין פחות מיום א' \u0004 כפול לעיל בסי' שי\"ב ס\"ד.","\u0003אין פחות מז' ימים \u0004 בטור כתב בשם הרמב\"ם בזה לשלשים יום אבל בנ\"י כתב שהגירסא הנכונה ברמב\"ם הוא ז' ימים וכמ\"ש המחבר:","\u0003וי\"א לבית האבל אינו רשאי כו' \u0004 בטו' כ\"כ בשם הרא\"ש ומהתימא על המחבר שכאן סתם וכתב דברי הרמב\"ם ובי\"ד סימן ש\"ס סל\"ה סתם וכתב דברי הרא\"ש שכתב מור\"ם ז\"ל כאן בשם י\"א לחוד ובאמת שמור\"ם כתב שם בי\"ד אדברי המחבר ז\"ל ובח\"מ סימן שמ\"א לא פסק כן עד כאן לשונו ולעד\"נ ליישב דאינו מוכח מדברי הרמב\"ם דפליג אדברי הרא\"ש דנוכל לפרש מ\"ש לבית האבל כדי שילך ויחזור היינו ז' ימים דכל ז' ימי האבילות הוא שוהה שם ואח\"כ הוא חוזר ומ\"ש לבית המשתה כל אותו היום היינו כשאין המשתה אלא יום אח' וס\"ל נמי דאם דרך להיות יותר משהה בידו יותר עד כלות ימי המשתה והיינו כדברי הרא\"ש וכן משמע לשון הטור שכתב אדברי הרמב\"ם שהן כדברי המחבר כאן ז\"ל וא\"א הרא\"ש הביאו בל' אחר כו' ור\"ל הביא התוספתא שכתב ב' דינין הללו בלשון אחר משמע דס\"ל דאין הכרח לו' דפליגי בדין אלא שהביאו בל' אחר ובל' מבואר יותר וק\"ל:","\u0003משתמשים בה כו' \u0004 ול\"ד למקבל שמת שיכול הנותן לסלק לבנו אפי' בתוך הזמן ואפי' אם גם הבן בקי באותו עסק או המלאכה כמ\"ש הטור והמחבר לעיל סי' שכ\"ט דשאני שאילה דכל ימי השאלה היא כקנוי לו שהרי כל הנאה דידיה וחייב אפי' באונסין ומש\"ה בניו יורשין אותו ממנו עד כלות הזמן:","\u0003כל ימי שאילתה \u0004 וה\"ה אם שאלה למלאכ' ידוע בלי זמן משתמשין בה זמן הראוי לאותו מלאכה וכך כתב הטור והמחבר בסמוך בס\"ה:","\u0003ואין חייבין באונסים כו' \u0004 שהרי לא קבלו כלום על נפשם אבל בגניבה ואבידה חייבין כיון דנהנין ממנו ה\"ל כשומר שכר או כשוכר אפי' לא נשתמשו בה עדיין כיון דהרשות בידם להשתמש בה באותו זמן:","\u0003שומעין לו. \u0004 דאדעתא דהכי בא בשאלה ליד אביהן ומ\"ה גם הם לא ישתמשו בה להנאתן בע\"כ אם לא שיקבלו עליהן אונסים כאביהן וע\"ל ס\"ס שמ\"ו:","\u0003שהיא ב' שלישים \u0004 דיכולין לומר אם ידענו שאינו של אבינו לא היינו אוכלים בשר אבל ב' שלישים משלמין שכן דרך בני אדם לקנות בשר בזול ולאכול אף אם בל\"ה לא היו אוכלין בשר:","\u0003והעור ישלמו כולו \u0004 פירוש הרשות בידן אם רוצים להחזיק העור בידן ולשלם דמי שוויה לבעליה שהרי קנאו בשינוי טביחה וההפשטה אבל אם רוצים מחזירין העור לבעלים בעין ועפ\"ר:","\u0003ואם הניח להן אביהם נכסים \u0004 המחבר סתם וכתב נכסים ובכלל נכסים הוא אפי' מטלטלים וכמ\"ש הטור והמחבר בס\"ס רי\"ח ובסי' רמ\"ח וע\"ש וה\"ט דבתר תקנת חכמים שתקנו דיתומים מחוייבים לשלם חוב אביהן אפי' ממטלטלים שירשו וכמ\"ש הטור והמחבר בסי' ק\"ז אין חילוק בין אחריות נכסים למטלטלים וכ\"כ הטור:","\u0003וטבחוה דקדק לכתוב וטבחוה והיא סברת הרא\"ש שכתב הטור בשמו כן ולאפוקי מדעת הרמב\"ם דס\"ל דאפי' מת בידם חייבים לשלם כיון שאחריות נכסים בידן מאביהן וס\"ל כלישנא קמא בגמ' דהשיעבוד חל אנכסיו משעת משיכה אבל הרא\"ש ס\"ל כלישנא בתרא דהשיעבוד לא חל אנכסיו כ\"א עד שעת מיתה או שעת שאר אונסין שנעשה בו ואז כבר מת אביהן אבל אם טבחוה ואכלוה דנהנו ממנה וגם היה פשיעה מאביהן דהיה לו להודיע לבניו שהיא שאולה בידו מ\"ה חייבים לשלמה ולא מחוייבים גם אמיתה מטעם תחלתו בפשיעה דה\"ל להודיען דלמא יאכלוה וסופו באונס מיתה דחייב כיון דאונס דמיתה לא בא מחמת הפשיעה:\u0004","\u0003אין המשאיל יכול להחזיר' מתחת ידו כו'. \u0004 אף על גב דכבר כ' בסעיף א' דסי' זה דמיד שמשך אין הבעלים יכולים להחזירו מתחת ידו כו' חזרו וכתבו דל\"ת כיון דלא שאלו לזמן קצוב יכול המשאיל לומר לא עלתה על דעתו שישהה כ\"כ זמן בלאכה זו ומה\"נ חזר וכתבו הטור בס\"ז ע\"ש:","\u0003כלומר אין אתה משאיל לי כו' כן הוא ל' הרמב\"ם ובדרישה כתבתי בשם הב\"י דבזה נסתלק תמיהת הרא\"ש שהביא הטור על הרי\"ף וכ' ז\"ל ולא נהירא לי דבשביל שא\"ל בטובתך לא יצא מכלל שאל' סתם אלא כך הוא ל' בני אדם עשה עמי טובה והשאילני כליך עכ\"ל שי\"ל שגם הרי\"ף פירשוהו כהרמב\"ם וכוונתו דהגמ' דאמר כשא\"ל השאילני בטובה משתמש בו לעולם מיירי דוק' בשואל שמכיר להמשאיל שהוא איש טוב ואינו רגיל להקפיד על הזמן ומשאיל לו סתם ע\"פ דברו אליו כן מ\"ה שאול בידו לעולם. ומ\"ש כלו' אין אתה משאיל לי כו' היא כאלו כל' הגמ' דהשאילני בטובתך כו' מיירי במשאיל שי\"ל עליו שכוונת השואל היה בהיות שאני מכירך שאין אתה כשאר משאילין כו' והיינו במכיר לו ויכול להיות שהרא\"ש מודה בזה ותמיהתו אינו אלא על הרי\"ף דמשמע ליה דס\"ל דמהני באומ' כן אפי' לסתם בני אדם שאינו מכירו אם מקפיד אם לא ולפ\"ז נראה דמ\"ש מור\"ם וי\"א דהאומר השאילני כו' לא כתב כן לפלוגתא עם דעת הרמב\"ם שכ' המחבר אלא מר אמר חדא ומר אמר חדא ול\"פ:\u0004","\u0003ויחזור שבריו או שיריו \u0004 שבריו הוא כפשוטו כשנשב' הכלי לחתיכו' ושיריו פי' דלא נשבר אלא נתמעך ונתמעט גוף הכלי מרוב תשמישו עד שנשא' בו מעט מהרבה וק\"ל:","\u0003ואין השואל רשאי כו' \u0004 דאם יתקנו ויחזו' וישתמש בו יקלקל הכלי לגמרי והוא לא השאיל לו אלא כלי זה כמות שהוא וכ\"כ הנ\"י לדעת הרי\"ף ולאפוקי מדעת הר\"ן שכתב שלדעת הרי\"ף דפי' דא\"ל השאלני בטובתך יכול לחזור ולתקנו ולהשתמש בו ועד\"ר:","\u0003ואפי' החזירו להמשאיל כו' \u0004 זהו דוקא כשא\"ל השאילני בטובו דהכלי אבל אי א\"ל השאילני בטובתך לא ובטור מסיק וכ' דאם ירצה המשאיל לקחנו מיד השואל שלא בשעת מלאכתו יכול השואל לעכבו מיהו לית ליה לשואל רשות להשאיל לאחריני ועפ\"ר מילתא בטעמא:","\u0003נשבר מחזיר לו שבריו. \u0004 פי' ואינו חוזר ומתקנו וקאי גם אהרישא כשנשאר בידו שלא להחזירו להמשאיל וכ\"כ הטור וסיים בטעמו ז\"ל דלא השאילו אלא כ\"ז שהוא בטובו:","\u0003אפי' הוא כמוהו בדרישה כתבתי דלהרא\"ש והטור דכתבו בסי' ש\"ח ושי\"א דיכול לשנו' לדבר שהוא כמוהו צ\"ל דמ\"ש הטור כאן דאין רשאין לשנות ר\"ל דשינוי שלו אינו ברשו' להיות פטור בשבורה מחמת מלאכה דבכה\"ג דנתקלקל אמרינן דמצא' הקפידה מקום לנוח ונחה ע\"ש בדריש':\u0004","\u0003פרדסי' הרבה שלו \u0004 בטור כ' אפי' א\"ל כרמים סתם ולא א\"ל תיבת הרבה ולא תיבת שלו אפ\"ה חופר בו אפי' הרבה ודוק' כרמים שלו ולא של אחרים והטעם דחופר בו הרבה משום דהוא מוחזק יכול לו' דסתם כרמים הרב' נמי משמע והטעם דאינו יכול לחפור בו של אחרים כמו ברישא משום דא\"כ אין לדבר סוף משא\"כ ברישא באומר לו לחפור כרם סתם דאין לו רשות לחפור בו אלא כרם א' מ\"ה חופר בו א' אפי' אינו שלו:","\u0003בונה בכ\"מ שירצה \u0004 ז\"ל הגמ' כרי ואזיל כמה גרגותני בארעא עד דמתרמי ליה כו' וכן הוא ברמב\"ם ובקיצור פסקי הרא\"ש ולא נזכר בשום מקום דהברירה ביד השואל לחפור באיזה מקום שירצה ואדרבה קי\"ל דיד בעל השטר על התחתונה בין בלוקח בין במקבלי מתנה לכן נראה דגם דעת הטור והמחבר במ\"ש ובונה בכ\"מ שירצה ור\"ל חופר זא\"ז בכ\"מ עד שימצא בא' מים שיספיק לו לדבר שהשאילו עבורו ועפ\"ר:"],["\u0003 השואל מחבירו כו' \u0004 וכן דעת הרא\"ש פ\"ק דמכות וכן כתב הרב המגיד שם שכן הכריחו הרמב\"ן והרשב\"א כפירוש רש\"י בשבת פ' שואל ושכן עיקר וכ\"פ הר\"ן שם:","\u0003 כש\"ש כו' \u0004 ובתשובת רשד\"ם סי' ע\"ו כ' שנראה דעת הרא\"ש דוקא שנשתמשו בה ע\"ש ואינו נלפע\"ד ע\"ש:","\u0003 אפי' לא נשתמשו בה כו' \u0004 ודוקא שואל אבל שוכר אפי' נגנב פטור פי' ר\"י מהרי\"ח הג\"א פ' השואל:","\u0003 שומעין לו. \u0004 וכ\"פ מהרש\"ל פ\"י דב\"ק סי' ג':","\u0003 ואם הניח להם כו' \u0004 כתב הסמ\"ע המחבר סתם וכ' נכסים ובכלל נכסים אפי' מטלטלים כו' לשון המחבר הוא ממש ל' הרמב\"ם לפי הדפוס שעם הכסף משנה ושאר דפוסים ואף על פי שהועתק בב\"י לשון רמב\"ם אחריות נכסים. היינו כפי מקצת דפוסים אבל מדברי הרב המגיד שם ומביאו ב\"י מבואר דהית' גירסתו ברמב\"ם רק נכסים וע\"כ כ' דאף על גב דבש\"ס משמע בהניח קרקע דוקא מ\"מ כיון דהאידנא איכא תקנת הגאונים כתב הרמב\"ם סתם נכסים כו' ע\"ש:","\u0003 וטבחוה כו' \u0004 עיין בסמ\"ע ס\"ק י\"ג אבל הרא\"ש ס\"ל כלישנא בתרא כו' וכן דעת הרמב\"ן והרשב\"א והמרדכי והנ\"י ור' ירוחם נ\"ל ח\"א וכ\"פ מהרש\"ל פ' הגוזל סימן ג' מיהו דעת הסמ\"ג עשין צ\"ב כהרמב\"ם וכן נלפע\"ד דעת הרי\"ף פ' השואל ע\"ש ודוק ונ\"ל שטעמם משום דללישנא בתרא צ\"ל דזה הוי פשיעה מה שלא צוה ובפ' המוכר את הבית קי\"ל דאמרינן אימר מלאך המות הוא דאנסיה ע\"ש ורבא גופיה ס\"ל הכי התם ע\"ש ודוק היטב ומ\"ש הש\"ג פ' השואל לדעת הרמב\"ם דגם הוא ס\"ל כשאר פוסקים לא נהירא כלל ע\"ש ומה שתמה הרב המגיד על הרמב\"ם דבפ\"ג מהל' גניבה פסק הרמב\"ם בעצמו כרב פפא דפטור ונדחקו האחרונים מאוד ליישב זה ובפרט מ\"ש בכ\"מ דהרמב\"ם לא גריס ופליגא דר\"פ וכן היינו דר\"פ וזהו דבר שאין לו שחר ועוד דא\"כ היאך שייך הך מימרא דרבא בפ' אלו נערות והלא כבר סדרו חכמי התלמוד מימרא זו בפ' הגוזל א\"ו משום דבפ' אלו נערות איתא גופא מימרא דר\"פ סדרו חכמי התלמוד מימרא דרבא למימר דללישנא קמא פליג אר\"פ וללישנא בתרא היינו דרב פפא גם מהרש\"ל כתב שם שהיא שגגה אצל הרמב\"ם ולפע\"ד לק\"מ דס\"ל להרמב\"ם דע\"כ לא קאמרי בש\"ס ודלא כר\"פ אלא במאי דס\"ל לר\"פ דפטור אף מקרן וכדאיתא בש\"ס פ' אלו נערות ור\"פ פרה אתי לאשמועי' כו' ומשני ר\"פ אתי לאשמועינן דאפי' בקרן לא מחייב אלא משעת אונסים ע\"ש אבל בהא דס\"ל לר\"פ דפטור מכפל פשיטא דליכא מאן דפליג עליה דאפי' תימא דחייב משעת שאלה היינו בקרן אבל בכפל פשיט' דאינו חייב אלא משעת גניבה וע\"כ דקדק הרמב\"ם בהלכות גניבה וכ' פטור מכפל ודוק כי זה ברור (ואע\"פ שרש\"י פי' באלו נערות דכפל לא שייך בשואל כיון דשואל חייב בגניב' ואבידה מ\"מ הרמב\"ם לא ס\"ל הכי אלא ס\"ל כיון שטבחו דרך גניבה ה\"ל גנב וכן מדוקדק ל' הרמב\"ם ע\"ש ודוק):"]],["אֵין הַשּׁוֹאֵל רַשַּׁאי לְהַשְׁאִיל, \u0010y0\u0011 אֲפִלּוּ שָׁאַל סֵפֶר תּוֹרָה, \u0010y1\u0011 שֶׁעוֹשֶׂה מִצְוָה בִּשְׁאִילָתוֹ, אֵינוֹ רַשַּׁאי לְהַשְׁאִיל לַאֲחֵרִים; \u0010c0\u0011 וְאִם הִשְׁאִיל לַאֲחֵרִים, אֲפִלּוּ נִתְקַלְקֵל מֵחֲמַת הַמְּלָאכָה שֶׁשָּׁאֲלוֹ \u0010y2\u0011 \u0010c1\u0011 \u0010c2\u0011 בִּשְׁבִילָהּ, חַיָּב, אֶלָּא אִם כֵּן יֵשׁ לוֹ רְאָיָה שֶׁיָּכוֹל לִפָּטֵר בָּהּ אִלּוּ הָיָה בְיָדוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן רצ\" א \u0005(סָעִיף כ\"ו)\u0006. \u0005הַגָּה: מִיהוּ, דָּבָר שֶׁאִי אֶפְשָׁר לְהַבְרִיחַ וְלִכְפֹּר בּוֹ, כְּגוֹן בַּיִת אוֹ סְפִינָה, מֻתָּר לְהַשְׁאִיל\u0006 \u0005(תְּשׁוּבוֹת רַשְׁבָּ\"א אֶלֶף נ\"ג וְאֶלֶף קמ\"ה)\u0006. \u0005וע\"ל סִימָן שט\"ז.\u0006",["\u0003אין השואל רשאי להשאיל כו' \u0004 פי' אפי' לאותו דבר שנשאל לו והיינו דוקא במטלטלים משום דהשני יכול להבריחם וכדמסיק מור\"ם בהגהתו ע\"ז:","\u0003שעושה מצוה כו' \u0004 ולא אמרי' בזה מסתמא דניחא ליה לאינש למיעבד מצוה בממוניה:","\u0003אא\"כ יש לו ראי' כו' \u0004 פי' דאם יש לו ראיה שמתה אצל השני מחמת מלאכה ואלו היה עושה בבית שואל הראשון אותה מלאכה היתה ג\"כ מתה בה פטור גם השני ועיין מה שכתב בסמ\"ע בר\"ס ש\"מ סק\"ד לישב דל\"ת מכאן למ\"ש שם:"],["\u0003 ואם השאיל לאחרים כו' \u0004 ואם המשאיל רגיל להשאיל לאותו אחר פטור כשישבע האחר מיהו היכא דרגיל להפקיד אצל אותו אחר צ\"ע אי נימא כיון דרגיל להפקיד אצלו תו ליכא למימ' את מהימנת לי בשבועה האיך לא מהימן לי או דלמא מצי למימר דוקא להפקיד מהימן לי אבל בהא דשמא שינה ונאנס' לא מהימן לי ומסתבר' דפטור ודוק:","\u0003 חייב כו' \u0004 לפרוע משעת שאלה לאחרים ונ\"מ הדין שכתבתי לקמן סי' שד\"מ ס\"ד ודוק היטב נראה לי:","\u0003 אא\"כ יש לו \u0004 וכ' הריטב\"א ומיהו ש\"ח או שומר שכר שאין לו רשות להשתמש בפקדון אם השכירו או השאילו לכ\"ע חייב באונסי' כדין שולח יד בפקדון והיינו דנקט שוכר ושואל עכ\"ל ב\"י:"]],["הַשּׁוֹאֵל חֵפֶץ אוֹ כָּל דָּבָר, לִזְמַן, \u0010y0\u0011 מִיָּד כְּשֶׁיִּכְלֶה הַזְּמַן חוֹזֵר הַדָּבָר הַשָּׁאוּל לִרְשׁוּת הַמַּשְׁאִיל לְהִפָּטֵר הַשּׁוֹאֵל מֵאֳנָסִים, אֲפִלּוּ הוּא עֲדַיִן בְּבֵיתוֹ. וּמִכָּל מָקוֹם, חַיָּב הוּא בִּגְנֵבָה וַאֲבֵדָה כְּדִין שׁוֹמֵר שָׂכָר. וְאִם שָׁלְחוֹ לוֹ בְּתוֹךְ הַזְּמַן בְּיַד עַבְדּוֹ אוֹ שְׁלוּחוֹ שֶׁל מַשְׁאִיל אוֹ שֶׁל שׁוֹאֵל, נִתְבָּאֵר בְּסִימָן ש\"מ.\nשׁוֹמֵר שָׂכָר לִזְמַן, כֵּיוָן שֶׁכָּלָה זְמַנּוֹ כָּלְתָה שְׁמִירָתוֹ. וַאֲפִלּוּ הִיא עֲדַיִן בְּבֵיתוֹ, אֵינוֹ עָלֶיהָ אֶלָּא שׁוֹמֵר חִנָּם:",["\u0003מיד כשיכלה הזמן כו' \u0004 כבר כתבו הטור והמחבר לעיל ס\"ס ש\"מ ובפרישה כתבתי שם טעם הטור דכתבו ב\"פ והוא דבס\"ס ש\"מ אשמועינן דאפי' שלחו לו בשלוחו ונאנסה בדרך לא תאמר דס\"ל תחלתו בפשיע' בשליחתו ע\"י שליח וסופו באונס ולחייב באונסין ובסי' זה קמ\"ל דאפי' לא שלחו לו אלא הוא עדיין בביתו אפ\"ה חייב בגניב' ואביד' כש\"ש ואף שהמחב' כ' שני הדינין לעיל ס\"ס ש\"מ צ\"ל דחזר וכתבו כאן משום דנמשך אחר ל' הטו' דכתבו כאן מטעם שכתבתי:"],[]],["טָעַן הַשּׁוֹאֵל שֶׁמֵּתָה מֵחֲמַת מְלָאכָה, אִם הוּא בְּמָקוֹם שֶׁעֵדִים מְצוּיִים, אֵינוֹ נִפְטָר \u0010y0\u0011 עַד שֶׁיָּבִיא עֵדִים שֶׁהוּא כִּדְבָרָיו, וְשֶׁלֹּא שִׁנָּה בּוֹ. וְאִם הוּא בְּמָקוֹם שֶׁאֵין עֵדִים מְצוּיִים, יִשָּׁבַע, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן רצ\"ד. וְאִם הִתְנָה שֶׁלֹּא יִשָּׁבַע אוֹ שֶׁלֹּא יְשַׁלֵּם אִם נִגְנְבָה אוֹ נֶאֶנְסָה, הַכֹּל לְפִי תְנָאוֹ. \u0005הַגָּה: אֲפִלּוּ לֹא קָנוּ קִנְיָן עַל כָּךְ, דְּכָל תְּנַאי שׁוֹמְרִים \u0010y1\u0011 קַיָּם אֲפִלּוּ בְּלֹא קִנְיָן (מָרְדְּכַי פֶּרֶק הַשּׁוֹאֵל)\u0006. וְדַוְקָא דְּאַתְנֵי קֹדֶם שֶׁבָּאָה הַשְּׁמִירָה לְיָדוֹ, אֲבָל לְאַחַר שֶׁשִּׁעְבֵּד \u0010y2\u0011 נַפְשֵׁהּ לָא מָצִי לְאַתְנוּיֵי בִּדְבָרִים בְּעָלְמָא \u0005(מָרְדְּכַי פֶּרֶק הַחוֹבֵל)\u0006.\nכְּשֶׁיְּשַׁלֵּם הַשּׁוֹאֵל, \u0010y3\u0011 שָׁמִין לוֹ הַשְּׁבָרִים, שֶׁאִם שָׁאַל כְּלִי וְנִשְׁבַּר שָׁמִין לוֹ הַשְּׁבָרִים כְּמוֹ שֶׁהָיוּ שָׁוִים \u0010y4\u0011 בִּשְׁעַת הַשְּׁבִירָה וְנוֹתְנִים לַבְּעָלִים, וּמַשְׁלִים עֲלֵיהֶם. \u0010y5\u0011 וְאִם הֻזְלוּ בֵּין שְׁעַת שְׁבִירָה לִשְׁעַת הַעֲמָדָה בַּדִּין, שָׁמִין אוֹתָם כְּמוֹ שֶׁהָיוּ שָׁוִין בִּשְׁעַת שְׁבִירָה. וְכֵן אִם שָׁאַל בְּהֵמָה וָמֵתָה, שָׁמִין כַּמָּה הָיְתָה שָׁוָה הַנְּבֵלָה בְּשָׁעָה שֶׁמֵּתָה, וְנוֹתֵן לוֹ, וּמַשְׁלִים לוֹ עָלֶיהָ. \u0005הַגָּה: \u0010y6\u0011 נִגְנְבוּ הַשְׁבָרִים אוֹ נֶאֶבְדוּ (וַאֲפִלּוּ נֶאֶנְסוּ)\u0006, הַשּׁוֹאֵל חַיָּב, אֶלָּא אִם כֵּן אָמַר לַמַּשְׁאִיל: טֹל אֶת שֶׁלְּךָ \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַשּׁוֹאֵל וּבַב\"י ס\"ס זֶה)\u0006.\nרְאוּבֵן הִשְׁאִיל חֵפֶץ לְשִׁמְעוֹן, וְהִפְסִידוֹ, אָמַר שִׁמְעוֹן לִרְאוּבֵן: הִשָּׁבַע כַּמָּה הָיָה שָׁוֶה וְאֶפְרְעֶנּוּ לְךָ, וְהֵשִׁיב בַּעַל הַחֵפֶץ: הִשָּׁבַע אַתָּה וְהִפָּטֵר, יִשָּׁבַע בְּעָלָיו וְיִפְרַע שֶׁכְּנֶגְדּוֹ עַל פִּי שְׁבוּעָתוֹ, וְאִם לֹא יִשָּׁבַע לֹא יִפְרַע שֶׁכְּנֶגְדּוֹ, \u0010y7\u0011 \u0010c0\u0011 וְאֵינוֹ נִקְרָא מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע שֶׁמְּשַׁלֵם. \u0010c1\u0011\nהַשּׁוֹאֵל פָּרָה מֵחֲבֵרוֹ, שְׁאָלָהּ חֲצִי יוֹם וּשְׂכָרָהּ חֲצִי יוֹם, \u0010y8\u0011 אוֹ שְׁאָלָהּ הַיּוֹם וּשְׂכָרָהּ לְמָחָר, אוֹ שָׁאַל אַחַת וְשָׂכַר אַחַת \u0005(וָמֵתָה אַחַת)\u0006 מֵהֶן; \u0010y9\u0011 הַמַּשְׁאִיל אוֹמֵר: שְׁאוּלָה מֵתָה, בַּיּוֹם שֶׁהָיְתָה שְׁאוּלָה מֵתָה, בְּשָׁעָה שֶׁהָיְתָה שְׁאוּלָה מֵתָה, וְהַשּׂוֹכֵר אוֹמֵר: אֵינִי יוֹדֵעַ; \u0010y10\u0011 אוֹ שֶׁאָמַר הַשּׁוֹמֵר: שְׂכוּרָה מֵתָה, בְּיוֹם שֶׁהָיְתָה שְׂכוּרָה מֵתָה, בְּשָׁעָה שֶׁהָיְתָה שְׂכוּרָה מֵתָה, וְהַמַּשְׁאִיל אוֹמֵר: אֵינִי יוֹדֵעַ; אוֹ שֶׁזֶּה אוֹמֵר: אֵינִי יוֹדֵעַ, וְזֶה אוֹמֵר: אֵינִי יוֹדֵעַ; הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. \u0010c2\u0011 וְאִם לֹא הָיְתָה שָׁם רְאָיָה, \u0010c3\u0011 בִּזְמַן שֶׁהַמַּשְׁאִיל טוֹעֲנוֹ וַדַּאי, \u0010y11\u0011 יִשָּׁבַע \u0005(הַשּׂוֹכֵר)\u0006 [הַשּׁוֹמֵר] שֶׁשְּׂכוּרָה מֵתָה, אוֹ \u0010y12\u0011 שֶׁאֵינוֹ יוֹדֵעַ. וּבִזְמַן שֶׁהַמַּשְׁאִיל אוֹמֵר: אֵינִי יוֹדֵעַ, יִשָּׁבַע הַשּׁוֹמֵר שְׁבוּעַת הַשּׁוֹמְרִים שֶׁמֵּתָה \u0005(כְדַרְכָּהּ)\u0006, \u0010c4\u0011 וְעַל יְדֵי גִּלְגּוּל יִשָּׁבַע הַשּׁוֹמֵר שֶׁשְּׂכוּרָה מֵתָה \u0010y13\u0011 אוֹ שֶׁאֵינוֹ יוֹדֵעַ. וְהוּא הַדִּין אִם זֶה אוֹמֵר: שְׁאוּלָה מֵתָה, וְזֶה אוֹמֵר: שְׂכוּרָה מֵתָה; אוֹ זֶה אוֹמֵר: אֵינִי יוֹדֵעַ, וְזֶה אוֹמֵר: אֵינִי יוֹדֵעַ:",["\u0003עד שיביא עדים \u0004 כבר כתבו הטור והמחב' ג\"כ לעיל בשאר שומרים ויליף לכולהו מדכתיב אין רואה שבועת ה' תהיה בין שניהם הא יש רואה לא נפטר בשבועה אלא בעדים ועמ\"ש מזה בסי' רצ\"ד ורצ\"ו:","\u0003קיים אפי' בלא קנין \u0004 כבר כתבו הטו' והמחב' בעצמו לעיל בס\"ס שט\"ו לענין תנאי של שכירות ע\"ש:","\u0003לא מצי לאתנויי בדברים בעלמא \u0004 ומה\"ט פסק שם במרדכי בראובן שאומר לשמעון אותן י' לטרי' שאתה חייב לי יהיו בידך למחצית שכר ונתעסק שמעון ונאנסו דשמעון חייב באונסין כבתחלה כיון דבתורת שאלה אתיא לידי' וע\"ש בד\"מ (ובש\"ע) הביאו לעיל ס\"ס ק\"ך ובסי' קע\"ו ע\"א וגם בסי' זה ע\"ש:","\u0003שמין לו השברים כו' \u0004 ילפינן לה מדכתיב והמת יהי' לו וקי\"ל לו לניזק קאמר שהוא צריך לטפל במכירת נביל' וכן הדין בכל המזיקין אבל בגנב וגזלן אין הדין כן וכמ\"ש הטור והמחבר לקמן סימן שנ\"ד ושס\"ב והטעם כתבתי שם:","\u0003בשעת השביר' דאז חל עליו חיוב התשלומין:\u0004","\u0003ואם הוזלו כו' וכ\"ש אם הוקרו דהא לא יהיה להמשאיל הפסד כיון שהוקרו.\u0004","\u0003נגנבו השברים \u0004 לפי גירסת הספרים נראה דדוקא נגנבו קאמר ומשום דאף שכלתה שאלתו משע' שנשברה ואינה ראוי' לדבר שאילתו מ\"מ עליו לשל' למשאיל דמי הכלי שנשבע דעדיין הוא ש\"ש עלי' וכמ\"ש בסימן שמ\"ג אבל נאנסו השברי' מידו פטור כיון דכלת' שמירתו ועיין בנ\"י בפרק השואל (דפוס גדול סוף דף קי\"ט) דכ' ז\"ל והסכימו האחרונים ז\"ל לדעת הרמב\"ן ז\"ל שאם א\"ל שואל למשאיל טול שברים שלך ונאנס לאחר מכן שנאבדו לגמרי הוה כאלו נאנסו ברשות משאיל כו' ע\"ש דמשמע דאי לא א\"ל טול שברים שלך חייב אפי' באונסין ואף די\"ל דשם מיירי דנאבד הכלי או מתה הבהמ' בתוך ימי שאלת' דאיכא תרתי לגריעותא חדא שהוא תוך זמנו והשני דאף אחר שנשבר ואינה ראוי' לשאלתו עדיין דין שומר עליו מ\"ה כל זמן שאין השואל מודיע למשאיל בא וטול שאיני חפץ עוד בהכלי או בהבהמה דין שואל עליו להתחייב באונסין ומור\"ם כאן מיירי כשכבר כלה הזמן אבל זה הוא קצת דוחק דסתם שביר' הוא מחמת מלאכתו ובתוך הזמן אפי' הכי משמע דדוקא בגניב' ואבידה חייב הא בנאנס' פטור ובנ\"י הנ\"ל כתב דחייב וגם ק' דמדכ' הנ\"י דטול מהני בנאנס' משמע דבנגנבה לא מהני מה שא\"ל קודם לכן טול ומטעם שכתבתי דאע\"ג דהודיעו לו שאינו חפץ עוד בהכלי מ\"מ דין ש\"ש עליו וכ\"כ בד\"מ בסי' זה אהאי דינא ע\"ש וא\"כ תימא על מ\"ש מור\"ם כאן בהג\"ה אנגנבו או נאבדו חייב אא\"כ א\"ל למשאיל טול את שלך דמשמע דאפי' מגניבה פטור בא\"ל טול גם זה יש ליישב ולומר דבלאו הכי צריכין נמי לחלק וליישב דל\"ת דברי הרמב\"ן אהדדי דכאן בנ\"י הנ\"ל משמע דס\"ל להרמב\"ן דאף דא\"ל טול אכתי חייב בגניב' ואבדה כדין ש\"ש וכמ\"ש ולעיל ס\"ס ק\"ך כ' הטור בשם הרמב\"ן ופסקו המחבר להלכ' בהלוא' דדינו כשואל דאם א\"ל בא וטול מעותיך והלה מסרב ונגנבו או נאבדו הלוה פטור וכתבתי בפריש' ודרישה בסמ\"ע בס\"ס ק\"ך דבא וטול דהתם קאי אמ\"ש שם לפני זה דאם א\"ל הלוה הילך מעותיך ולא רצה לקבלם וזרקו לפניו ונגנבו משם דפטור הלוה דאזה מסיק שם וכ' ז\"ל וכן נמי כי א\"ל הנה מעותך צרורים ומונחים בביתי וטול כו' ר\"ל וכן נמי אף דלא זרקום לפניו כשא\"ל תחלה הילך מעותך אלא שלא רצה לקבלם א\"ל הנה אחזור מעותי לביתי ואניחם צרורים וכשתרצה בא לביתי וטול אות' ונגנבו מביתו בכה\"ג דוקא פטור הלוה אפי' אגניבה ואביד' ומ\"ש הטור והמחבר שם בא וטול ר\"ל הכן נפשך לקבל מעותך ואני אביא לך אותם מביתי שהן צרורים ומונחים שם והלה מסרב לקבלם בכה\"ג דוקא פטור ע\"ש. והנה י\"ל דמכעין זה מיירי מ\"ש מור\"ם כאן בש\"ע דפטור בא\"ל טול אפי' מגניב' ואביד' והנ\"י הנ\"ל מיירי בבא וטול כפשוטו דבכה\"ג פטור מאונסין ולא מגניב' ואביד' וכמ\"ש ג\"כ הטור בסי' קצ\"ח ע\"ש. ומיהו גם זה דוחק חדא דא\"כ לא ה\"ל למור\"ם לסתום אלא לפרש. ועוד כיון דרך מור\"ם שלא לכתוב בהגהותיו שום דין שלא כתב מקורו בד\"מ ובד\"מ הביא כאן בדין זה דברי הנ\"י וכתב עליו בד\"מ דדוקא בנאנסו פטור בדא\"ל טול ולא באם נגנבו או נאבדו וכנ\"ל ובהגהותיו לא הזכיר אותו דין דנאנסו כלל אלא כתב דין אחר דאם נגנבו או נאבדו חייב ואם א\"ל טול כו' ואם תפרשהו הטול כמ\"ש הרי דין זה לא נזכר בד\"מ כלל לכן נרא' דצריכין להגיה בהג\"ה וכצ\"ל חייב וגם אם נאנסו חייב אא\"כ אמר טול ע\"כ ור\"ל דאם אמר טול פטור בנאנסו לחוד ובזה א\"ש הכל ומ\"ש מור\"ם בסי' ע\"ד בהג\"ה ס\"ג דגם בא\"ל טול חייב אפי' באונסין לק\"מ דשאני הלוא' דלא שייך לומר גבי' כלתה שמירתו וחייב באונסין עד שיפרע לו דמי הלואתו ודו\"ק:","\u0003ואינו נקרא מחויב שבוע' \u0004 עד\"ר שם כתבתי דמיירי דהמשאיל עצמו לא הי' טוען ברי כך וכך הי' שוה אלא שמא הוא שוה כ\"כ והפסדת אותו ויכול להיו' שאין בהפסדו ש\"פ ואף אם בודאי ש\"פ מ\"מ כיון שלא תבעוהו בו בברי לא אמרי' מתוך שאיל\"מ א\"נ מיירי שהלוה טוען ואומר סלע או שתים יודע אני שהפסדתי והריני נותן לך והילך ויות' מזה איני יודע אם הפסדתי השבע וטול והמשאיל אינו טוען בברי שהפסיד יותר מ\"ה פשוט להרא\"ש דלא הוה בכלל מחויב שבועה ואי\"ל דמשלם כיון דהמשאיל גופו אינו טוען ברי בהמותר ובמה שמודה א\"ל הילך וק\"ל. ולא כע\"ש שכתב ז\"ל ואין זה נקרא מחויב שבועה ואיל\"מ אע\"ג דיש כאן ג\"כ שבועת שומרים שהיא שבועת התורה כמ\"ש טעמו בסי' שמ\"ה בעז\"ה עכ\"ל ר\"ל דשם תירץ למה לא אמרי' מתוך שאינו יכול לישבע משלם כשטוען על הגלגול איני יודע ומתרץ כיון שעיקר השבועה באה על טענת התובע שטען שמא לא מתה כדרכה כו' ובכה\"ג דעיקר השבוע' היא באה על טענת שמא שטוען התובע לא אמרי' בה משואיל\"מ וכן תי' המ\"מ וכמ\"ש בסמוך אבל אין הנדון דומה לראיה דלא כ' המ\"מ דבכה\"ג לא אמרי' משואיל\"מ אלא כשבא לגלגל ואגלגול א\"י לישבע משא\"כ כאן דאעיקר תביעתו טען אינו יודע עד\"ר ודו\"ק:","\u0003או שאלה היום ושכרה למחר \u0004 ☜ ובנ\"י בשם תלמידי רשב\"א דבלילה שבנתיים אם דרך השואל שבהמות לנים אצלו אחר השאלה גם כאן הוא שואל על הלילה ואם נאנסה בליל' חייב ואם אין דרך שילינו הבהמות אצלו מזמן השאלה אינו אצלו אלא כשוכר ופטור מאונסים וחייב בגניב' ואביד' עכ\"ל ד\"מ ה': ה\"ג ושכר אחת ומתה אחת מהן וכן היא ברמב\"ם:","\u0003המשאיל אומר שאולה מתה כו'. \u0004 במאי דסיים לפני זה פתח ואזיל מלמטה למעלה דכנגד סיפא דשאל א' ושכר א' ור\"ל דאח' מהן מתה קאמר דטענ' המשאיל עליו לומ' אותה דשאלה מתה והנשארת שעומדת חי היא השכורה וכנגד המציעתא שאלה היום ושכרה למחר קאמר דטענת המשאיל הוא שמתה ביום השאלה וחייב עליה באונס מיתה ונגד הרישא בשאלה חצי היום כו' קאמר בטוען המשאיל בשעה שהית' שאולה מתה והשוכר משיב על טענת המשאיל דאינו יודע אימת מתה או איזה מתה:","\u0003או שאמר השומר שכורה מתה כו' גם בכאן פירשו כנ\"ל דאם שכר א' ושאל אחת ומתה האחת לבדה אומר השואל אני פטור מתשלומין כי זו שמתה שכורה היתה ואותה של שאלה היא העומדת וקיימת חי וכן אינך וק\"ל:\u0004","\u0003ישבע השומר ששכורה מתה. \u0004 פי' ישבע היסת דהוא כופר הכל גם באומר איני יודע אם שכורה מתה דה\"ל כאומר הלויתיך מנה ולא פרעתני וזה אומר איני יודע אם הלוותני שהרי אם שכורה מתה לא נתחייב לו דבר שהרי השאול' מחזיר בעין וכן אם היתה א' חצי יום בשאל' וחצי יום בשכירות אם מתה בשעת שכירות כבר אזדא השאלה ולא נתחיייב לו דבר וכ\"כ הכ\"מ דשבועות הללו ר\"ל היסת:","\u0003ובזמן שהמשאיל אומר איני יודע ישבע השומר שבועת השומרים שמתה כדרכה (כצ\"ל כדרכה וכן הוא ברמב\"ם) וע\"י הגלגול ישבע השומר ששכור' מתה או שאינו יודע כו' \u0004 המחבר נקט שיט' לנפשיה כי הרמב\"ם והטור לא כ\"כ אלא אחר שכתבו תחלה ואם אין לו ראיה ישבע השומר שבשעת שכירות מתה או שאינו יודע כתבו ז\"ל אמר המשאיל בימי שאלה מתה והשוכר אומר בימי שכירות מתה ישבע השוכר שמתה כדרכה ויגלגל עליו שביום שהית' שכורה מתה עכ\"ל. משמע מדבריהם דדוקא כששניהם טוענים ברי הוא דמגלגלין עליו ש\"ח דביום שהית' שכורה מתה אבל אם א' מהם טוען שמא אין מגלגלין עליו ש\"ח וכ\"כ הרא\"ש בהדיא בפ' השואל אהאי דינא מילתא בטעמא כתבתי לשונו בדרישה. והא דאין מגלגלין על טענת שמא דנתבע דגלגול מסוטה ילפינן ובסוטה האשה נתבעת טוענת ברי שלא נטמאתי ועל טענת התובע דמגלגלין אפי' בשמא כמו בסוטה היינו דוקא כשיש רגלים לדבר לאותו שטוען שמא שהרי בקינא לה ונסתרה דמגלגלין עליה שלא נטמא' כבר רגלים יש לדבר מדקינא לה ועברה ונסתר' בפעם הזה ע\"ש שהאריך משא\"כ בטענת שמא דהמשאיל דהכא שטוען ואומר שמא שאולה מתה דאין רגלים לטענתו שאומר ששאולה מתה יותר מלומר ששכור' מתה אבל מדברי המחבר מוכח שס\"ל שלעולם מגלגלין עליו ש\"ח שהרי כתב ובזמן שהמשאיל אומר איני יודע ישבע כו' עד וע\"י גלגול ישבע השומר ששכורה מתה או שאינו יודע וה\"ה אם זה אומר שאולה מתה וזה אומר שכורה מתה או זה אומר איני יודע וזה אומר איני יודע ור\"ל דג\"כ דינו כנ\"ל דמגלגלין ומשביעינן ליה ש\"ח הרי לפנינו דס\"ל דבין המשאיל טוען אינו יודע והשואל ברי או בין שניהם טוענים ברי או בין ב' טוענים שמא מגלגלין עליו ש\"ח וזהו דלא כהרא\"ש וכמשמעות הרמב\"ם דס\"ל דכשהמשאיל טוען איני יודע בין שהשואל טוען ברי או טוען ג\"כ אינו יודע אין מגלגלין כנ\"ל שוב מצאתי שהרמב\"ם כ' בפי' משניות שלו בפ' השואל עלה דהאי משנ' דמביאין לידי ש\"ח ע\"י גלגול זה אף כשטוענים שניהם איני יודע ובודאי משם ראה המחבר לכתוב מ\"ש כאן ודוק. וכדי ליישב דברי המחבר דלכאור' דבריו סותרין זא\"ז דהתחיל וכתב אם אין שם ראיה בזמן שהמשאיל טוענו ודאי ישבע השומר ששכור' מתה ור\"ל שבועת היסת ומטעם שכתבתי לעיל וכמ\"ש הב\"י ובכ\"מ בהדיא וסיים וכתב וה\"ה אם זה אומר שאול' מתה וזה אומר שכורה מתה ור\"ל דג\"כ מגלגלין עליו ש\"ח צריכים לומר דברישא מיירי כשמאמין המשאיל לשואל דכדרכה מתה דאז אין שייך גלגול ובסיפא מיירי כשאינו מאמינו (וכ\"כ התוס' והרא\"ש שם בפ' השואל סברא זו ליישב הסוגיא והבאתי לשונם בדרישה) וברישא ובסיפא כתב רבותא דברישא אשמועינן רבותא אף על גב דהמשאיל טוען ודאי אפי' הכי בהיסת שישבע ששכורה מתה או שאינו יודע נפטר הואיל שמאמינו שכדרכה מתה ולא אמרי' דה\"ל כאומר ודאי הלויתיך וזה אומר לא ידעתי אם פרעתיך וכ\"ש כשהמשאיל טוען שמא או ששניהם טוענים שמא ובסיפא דאיירי באינו מאמינו כתב ז\"ל ובזמן שהמשאיל טוען איני יודע גם כן לרבותא כ\"כ דאף על גב דהמשאיל טוען איני יודע והשומר טוען ודאי או שטוענים שניהם ברי אפ\"ה מגלגלין עליו עליו ש\"ח: והמחבר שכתב בזה דאינו האמינו ג' בבות דמגלגלין. הא' כשהמשאיל טוען שמא והשואל ברי. ב' כששניהם טוענין ברי. ג' כששניהן טוענין שמא ק' למה לא כ' כן נמי כשהמשאיל טוען ודאי והשואל שמא דמגלגלין עליו באינו מאמינו וא\"ל שטעמו משום דס\"ל ג\"כ בזה כסברת הרא\"ש הנ\"ל דאין מגלגלין בכה\"ג כיון דילפי' מסוטה דשבועת הנתבע היה ברי וכנ\"ל דא\"כ כששניהם טוענין שמא נמי למה כתב דמגלגלין גם קשה דסיים המחבר וכתב או שזה אומר איני יודע וז\"א איני יודע דהוא כפל דברים שהרי כבר כ' ז\"ל ובזמן שהמשאיל אמר איני יודע ישבע השומר כו' וע\"י גלגול ישבע כו' \"או שאינו יודע ואם נאמר שיש חסרון וט\"ס בדברי המחבר ושכצ\"ל וע\"י גלגול ישבע השומר ששכורה מתה או שאינו יודע כשטענתן הוא איפכא אזי לק\"מ דבהג\"ה זו מיושב הכל דאין כאן כפל גם כ' לפ\"ז דין הרביעי שמגלגלין כשהמשאיל טוען ברי והשואל שמא אלא שק' להגיה הספרים ודוק:","\u0003או שאינו יודע \u0004 הא דלא אמרינן בכהא דה\"ל מחייב שבועה ואיל\"מ תירץ המ\"מ בפ\"ג דשאלה בשם הראשונים ז\"ל כיון שעיקר תביעת המשאיל שמשביעו עליו היא איני יודע שהרי אינו טוען ברי שלא מתה כדרכה אע\"ג שבגלגול טוען ברי דהשאולה מתה לא אמרי' בכה\"ג מתוך שאיל\"מ עכ\"ל. והב\"י הביאו על דברי הטור בסי' שמ\"ה ובאמת לדברי הרא\"ש והטור א\"צ להאי תירוצא חדא שהן סוברין שאין מגלגלין כלל אטענת נתבע כשהוא אומר אינך יודע וכמ\"ש לפני זה ועוד דאפי' במקום שמגלגלין ס\"ל דלא אמרינן מתוך שאיל\"מ בשבועה הבאה ע\"י גלגול וכמ\"ש הטור בסי' ע\"ה בסי\"ח וי\"ט בשם הרא\"ש והמחבר כתבו שם ג\"כ בסט\"ו ע\"ש אלא שמסיק שם וכ' דיש חולקין וס\"ל בזמן שנתחייב ש\"ד והוא טוען על הגלגולים איני יודע קרינן ביה שפיר מחויב שבועה ואיל\"מ ע\"ש ודוק:"],["\u0003 ואינו נקרא משואי\"ל שמשלם \u0004 בסמ\"ע סק\"ח עד ויותר מזה איני יודע אם הפסדתי כו' והמשאיל אינו טוען ברי כו' לא הוי בכלל משואי\"ל כו' לא ידענא למה כתב דהמשאיל אינו טוען ברי דהא אפי' טוען ברי כיון דאומר לו הילך א\"כ אינו חייב על השאר רק היסת שא\"י ולא ה\"ל משואיל\"מ כדאיתא לעיל סי' ע\"ב טובא זימני וכן בכמה דוכתי ויכול להפך על שכנגדו וע\"ק דע\"כ מיירי שטיען המשאיל ברי דאל\"כ אין השואל חייב שבוע' כלל כיון שטוענו שמא כדלעיל סי' ע\"ה סי\"ז וי\"ח וגם קשה כשהמשאיל אינו טוען ברי היאך ישבע ליטול והב\"ח כתב דטעמי' דהרא\"ש הכא דלא אמרינן בנפקד משואיל\"מ דלא ה\"ל לידע כדלעיל סי' רצ\"ח בטור וה\"נ בשואל לא ה\"ל לידע כיון דה\"ל להחזיר לאחר ימי השאלה עכ\"ל וק' דהא לא כתב הרא\"ש שם ולא ה\"ל לידע אלא בהפקיד אצלו בשק וכמ\"ש הרא\"ש שם דמעשים בכל יום שמפקיד אצל חבירו בשקים ומרצופים ואינו יודע מה בתוכו אבל בשאר מפקיד כתב הרא\"ש להדיא בפרק שבועות הדיינים כשאומר איני יודע ה\"ל משואי\"ל משלם והבאתיו לעיל סי' ע\"ב ע\"ש ואפש' דדוקא במפקיד שאומר א\"י כמה היה ס\"ל להרא\"ש הכי דה\"ל לידע כמה היה א\"נ באומ' א\"י כמה הי' שוה ובמלוה על המשכון דה\"ל לדקדק בשביל הלואתו כמה הי' שוה משא\"כ הכא דלא ה\"ל לדקדק כמה הי' שוה או אפשר דסבירא לי' להב\"ח דהרא\"ש בפ' שבועת הדיינים מיירי דוקא כשערבן עם פירותיו ס\"ל דה\"ל לידע וכמש\"ל בסמ\"ע סי' רצ\"ב ס\"ק ל\"ו ע\"ש ומיהו המחבר ודאי לא ס\"ל כהב\"ח דהא איהו פסק לעיל סי' צ' ס\"י וסי' רצ\"ח דאפי' בשק ה\"ל משואיל\"מ וכן העליתי לעיל בחבורי סי' ע\"ב סי\"ב סקנ\"א דבכל ענין ה\"ל משואיל\"מ ולי נרא' דכאן מיירי ששמעון אומר שלא הפסידו כלל וכך היה מתחלה ומ\"ש והפסידו שראובן אומר כן:","\u0003 השואל פרה כו' \u0004 עיין בנ\"י בשם הרא\"ה ועיין במהרש\"ל פ\"י דב\"ק סי' ג' ועיין מש\"ל סי' רצ\"א סעיף ט' באריכות עיין בתשו' ר\"ש כהן ס\"ג סימן י\"ז:","\u0003 ואם לא הית' שם ראיה כו' \u0004 בעיר שושן כתב דדברי המחבר מגומגמין גם הסמ\"ע האריך לישב דבריו והניחם בגמגום וגרם להם זה מפני שחשבו דבאומר המשאיל איני יודע איזהו מתה צריך לישבע היסת וחשבו שגם דעת המחבר כן וכ\"כ בע\"ש להדיא ותימא דהא דין פשוט הוא ומוסכם מכל הפוסקים דאין משביעין אפי' היסת על טענת שמא ואפי' בטוען א\"י אם פרעת לי אפי' הנתבע משיב ג\"כ שמא וכמו שנתבאר לעיל סי' ע\"ה סי\"ז וי\"ח וכ\"ש היכא דהוי כאומר א\"י אם אתה חייב וכדמוכח בש\"ס פ' השואל וכמ\"ש התו' שם דף צ\"ז ע\"ב ד\"ה והלה אומר כו' ואף שבע\"ש דחק ליישב אינו נראה כלל ע\"ש וכך הוא דעת המחבר דבטוען המשאיל א\"י אצ\"ל אפי' היסת וכמו שאבאר אבל באמת נעלם מהן דברי המחבר שבספרו בדק הבית וז\"ל הרמב\"ם השואל פרה והשומרין כו' והשומר אמר איני יודע או שאמר השואל שכורה מתה והמשאיל אומר איני יודע או שאמר זה א\"י וזה איני יודע המע\"ה ואם לא היה שם ראי' ישבע השומר ששכורה מתה או שא\"י ויפטר זה אומר שאולה וזה אומר שכור' ישבע השומר על השכורה שמתה כדרכה ויגלגל שהשכורה מתה עכ\"ל וכתב בב\"ה ע\"ז וז\"ל על מ\"ש ואם אין לו ראי' ישבע השוכר ששכור' מתה וכשטוען א\"י ישבע שהוא כדבריו ויש לתמוה היכן מצינו שבוע' על טענת שמא וי\"ל כיון שהא צריך לישבע שבועת השומרים נשבע ע\"י גלגול ששכור' מתה או שאינו יודע ואע\"פ שיש לטעון ע\"ז ממה שסיים בה הרמב\"ם זה אומר שאול' וזה אומר שכורה ישבע השומר על השכורה שמתה כדרכה ויגלגל עליו שהשכורה היא שמתה ואם איתא היינו דינא קמא וא\"כ אמאי לא ערבינהו י\"ל משום דבדינא קמא איכא תרי גווני א' שהשומר טוען ודאי והמשאיל ספק אי בהפך ובהאי בבא כל א' טוען ודאי מש\"ה לא ערבינהו עכ\"ל הרי להדיא דבטוען המשאיל שמא אינו נשבע אפי' היסת וע\"ש בכ\"מ שהשבוע' זו שכתב הרמב\"ם בג' חלוקות אלו היינו היסת היינו בטוען המשאיל ברי וג' חלוקות אלו דקאמר ר\"ל שאל' חצי היום ושכרה חצי היום או שאלה למחר ושכרה היום או שאל אחת ושכר אחת (שוב ראיתי בספר גדולי תרומ' דף קס\"ח ע\"ג שלא הבין כן הג' חלוקות לכן תמה על הכ\"מ אמאי ישבע היסת בחלוק' כשטוען שמא והניח בתימא ולע\"ד כמ\"ש) ומעתה כך הם המשך דברי המחבר בש\"ע כאן בזמן שהמשאיל טוענו ודאי ישבע השומר היסת אפי' בלא גלגול ונ\"מ כגון שמאמינו או שיש עדים שמתה כדרכה צריך לישבע היסת ששכור' מתה או שאינו יודע כיון שהמשאיל טוענו ברי ובזמן שהמשאיל אומר איני יודע אז א\"י להשביעו היסת בלא גלגול אם מאמינו או יש עדים שמתה כדרכה דאין נשבעין על טענת שמא רק כשצריך השומר לישבע שמתה כדרכ' אז ישבע ג\"כ ששכור' מתה או שאינו יוד' וה\"ה אם זה אומ' ברי ששאול' מתה וזה אומ' שכורה מתה אע\"ג דבלא גלגול חייב היסת מ\"מ ודאי דיכול לגלגל עליו ש\"ד או זה אומר איני יודע ט\"ס הוא וצ\"ל או זה אומר שאול' מתה וזה אומר איני יודע כך הם המשך דברי המחבר בלי ספק ומעת' נתיישב כל מה שהקש' בסמ\"ע ודו\"ק. ומעתה גם מ\"ש הע\"ש דגם דעת המחבר כאן כשטוען המשאיל אינו יודע א\"י לגלגל עליו נמי ליתא וכמבואר ג\"כ להדיא מדבריו בבדק הבית שהבאתי ודוק. ונמצא לענין דינא בדעת הרמב\"ם יפה כוון המחבר דהרמב\"ם כתב להדיא בפי' המשניות אפי' בזה אומר איני יודע מגלגלין עליו וכן מוכח להדיא בה\"ה שהבאתי לקמן לעיל סי' ע\"ב ס\"ק ל\"ט דלהרמב\"ם אף בטוען השואל א\"י מגלגלין (וכן היא דעת הריטב\"א בפ\"ק דקידושין ושאר פוסקי' ע\"ש) אבל בטור שכתב כל' הרמב\"ם אי אפשר לומר כן שהרי הרא\"ש כתב בפ' השואל דבין טוען המשאיל א\"י ובין טוען השומר א\"י אין מגלגלין וכ\"פ הטור לעיל סי' צד וכמ\"ש שם ובע\"כ צ\"ל דמ\"ש הטור כאן ישבע שהוא כדבריו קאי אהיכא דטוען המשאיל ברי ולפי שהדינים אלו אין מקומם כאן ועיקרם לעיל סי' ע\"ה סתם כאן הדברי' וכן ברמב\"ם י\"ל כן ודוק:","\u0003 בזמן שהמשאיל טוענו ודאי כו' \u0004 בע\"ש בסי' זה ובסי' שמ\"ה כתב דהיינו שטוענו ודאי פשעת ולא מתה כדרכה והלכך אם השואל טוען איני יודע אם שאול' או שכור' מתה כיון שיש עליו דין גלגול ה\"ל משואיל\"מ ודוקא היכא שעיקר התביע' היא שמא נשבע על הגלגול וכמ\"ש לקמן בשם הרב המגיד ופי' גם דברי המחבר כן ולא נהירא דהדבר ברור דפי' דברי המחבר הן כמ\"ש גם דינו ליתא כיון שטוען ברי שפשעת א\"כ אינו חייב ש\"ד כלל וכמ\"ש למעלה סי' ע\"ב ס\"ק ע\"ח דאינו חייב שבועת השומרים רק בטוען התובע ספק דרמי רחמנא שבועה עליה דשמא מעיז הוא כיון דהלה א\"י אם טוען אמת או לא וכן מוכח בדברי הרב המגיד גופי' מדכתב בפשיטות כיון שעל עיקר התביע' אינו טוען המשאיל ברי כו' משמע דפשיטא דמיירי שעל עיקר התביע' אינו טוען ברי דאל\"כ אינו חייב ש\"ד כלל דאלת\"ה אכתי לא תירץ הרב המגיד קושייתו בברי ודוק אלא הדבר פשוט דכל היכא דאמרינן הכי ישבע שבועת השומרים שמתה כדרכה היינו כשהמשאיל א\"י אם מתה כדרכה או בפשיעה וכדין שאר שבועת השומרין דעלמא שאינו בטוען התובע ברי ודוק:","\u0003 וע\"י גלגול כו' או שא\"י כו' \u0004 אין להקשות דלעיל סי' ע\"ה סט\"ו כתב המחבר די\"א אם טוען בגלגול אינו יודע ה\"ל משואיל\"מ די\"ל כמ\"ש ה\"ה ומביאו ב\"י סי' שמ\"ה דכאן כיון שעיקר התביעה שמשביע עליו הוא א\"י שהרי אינו טוען ברי שלא מתה כדרכה אע\"פ שבגלגול טוען ברי שהשאולה מתה לא אמרי' בכה\"ג משואיל\"מ אלא א\"י ופטור עכ\"ל וכך היא דעת המחבר ועמ\"ש לעיל סי' ע\"ב ס\"ק ל\"ט ונראה שגם דעת הרמב\"ן בס' המלחמות כן שעל מ\"ש בס' המאור דהא דזכה בגדול לא קאי רק אכסות ולא אעבד כדמוכח ממתני' דהשואל ב' פרות דלא אמרינן משואיל\"מ בגלגול כתב עליו הרמב\"ן מידי כסות קתני ודעתו דאף על העבד חייב מכח משוא ל\"מ ולא דחה דברי בעל המאור גבי ב' פרות משמע דגבי פרות מודה ליה כיון שעיקר התביע' היא שמא ובעבד פליג עליה כיון שעיקר התביעה היא ברי ע\"ש ודוק אבל דעת הרא\"ש דאין מגלגלין א\"י כלל וכ\"פ המחבר גופיה לעיל סי' צ\"ד ס\"ב וס\"ט וכבר כתבתי שם שדבריו שם סותרים לדבריו שבכאן וצ\"ע:"]],["שָׁאַל שְׁתֵּי פָּרוֹת, חֲצִי הַיּוֹם בִּשְׁאִילָה וַחֲצִי הַיּוֹם בִּשְׂכִירוּת, הַמַּשְׁאִיל אוֹמֵר: בִּזְמַן הַשְּׁאִילָה מֵתָה, וַהֲלָה אוֹמֵר: אַחַת מֵתָה בִּזְמַן הַשְּׁאִילָה וְהָאַחֶרֶת אֵינִי יוֹדֵעַ, \u0010y0\u0011 מִתּוֹךְ שֶׁאֵינוֹ יָכוֹל לִשָּׁבַע יְשַׁלֵּם הַשְּׁתַּיִם. \u0010y1\u0011\nוְכֵן אִם מָסַר לוֹ שְׁלֹשָׁה פָרוֹת, שְׁתַּיִם שְׁאוּלוֹת וְאַחַת שְׂכוּרָה, וְהַמַּשְׁאִיל אוֹמֵר: שְׁתַּיִם הַשְּׁאוּלוֹת הֵן שֶׁמֵּתוּ, וְהַשּׁוֹאֵל אוֹמֵר אַחַת הַשְּׁאוּלָה מֵתָה וַדַּאי, אֲבָל הַשְּׁנִיָּה שֶׁמֵּתָה, אֵינִי יוֹדֵעַ אִם הַשְּׁאוּלָה הִיא אוֹ הַשְּׂכוּרָה, מִתּוֹךְ שֶׁאֵינוֹ יָכוֹל לִשָּׁבַע, שֶׁהֲרֵי אוֹמֵר: אֵינִי יוֹדֵעַ, יְשַׁלֵּם הַשְּׁתַּיִם:",["\u0003מתוך שאינו יכול לישבע משלם \u0004 הטעם דהא הודה לו במקצת טענתו דתבעו בב' פרות שאולו' שמתו בזמן השאל' ושחייב לו עליהן באונסיהן והנתבע מודה לו בא' ועל השניי' חייב לישבע ש\"ד כדין מודה במקצת ואינו יכול לישבע מ\"ה משלם משא\"כ בשאל לו א' והשכיר לו א' ומתה הא' והשניה עומדת חי שבסי' שלפני זה דשם אין טענתן אלא על הא' דהרי על העודנ' חי א\"ל הילך וקחנה לך ואין כאן מודה מקצת וק\"ל:","\u0003וכן אם מסר לו ג' פרות כו' \u0004 פי' ומתו שנים מהן וא' נשאר' חי ומחזיר' לו ותבעו בשתים שמתו והוא מודה לו בא' מהן שחייב ה\"ל ג\"כ מודה מקצת ומתוך שאינו יכול לישבע על השניה משלם:"],[]],["הַשּׁוֹאֵל, וְהָיָה הַמַּשְׁאִיל עִם הַשּׁוֹאֵל בִּמְלַאכְתּוֹ בְּשָׁעָה שֶׁמָּשַׁךְ הַדָּבָר הַשָּׁאוּל, אֲפִלּוּ נִגְנַב אוֹ נֶאֱבַד בִּפְשִׁיעָה, פָּטוּר, \u0010y0\u0011 שֶׁנֶּאֱמַר: אִם בְּעָלָיו עִמּוֹ לֹא יְשַׁלֵּם. \u0005(שְׁמוֹת כב, יד)\u0006 לֹא שְׁנָא הָיָה עִמּוֹ בַּשְּׁאִילָה שֶׁהִשְׁאִיל אֶת עַצְמוֹ לַעֲשׂוֹת מְלַאכְתּוֹ, לֹא שְׁנָא הָיָה עִמּוֹ בַּשְּׂכִירוּת שֶׁהִשְׂכִּיר עַצְמוֹ לוֹ, לֹא שְׁנָא הָיָה עִמּוֹ בְּאוֹתָהּ מְלָאכָה שֶׁל הַדָּבָר הַשָּׁאוּל, לֹא שְׁנָא בִּמְלָאכָה אַחֶרֶת; אֲפִלּוּ אָמַר לוֹ: הַשְׁקֵנִי מַיִם, וְהִשְׁקָהוּ וְהִשְׁאִיל לוֹ פָּרָתוֹ בְּעוֹד שֶׁהוּא מַשְׁקֵהוּ, הָוֵי שְׁאִילָה בִּבְעָלִים. \u0010y1\u0011 אֲבָל אִם מָשַׁךְ תְּחִלָּה וְאַחַר כָּךְ הִשְׁקָהוּ, לָא הָוֵי שְׁאִילָה בִּבְעָלִים.\nלֹא שְׁנָא אִם בָּאוּ שְׁאִילַת הַבְּעָלִים עִם שְׁאִילַת הַפָּרָה כְּאֶחָד, לֹא שְׁנָא הָיָה הוּא שָׁאוּל אוֹ שָׂכוּר לוֹ וְאַחַר כָּךְ הִשְׁאִיל לוֹ פָּרָתוֹ, פָּטוּר, \u0010y2\u0011 אֲפִלּוּ לֹא הָיָה עִמּוֹ בִּשְׁעַת שְׁבִירָה וּמִיתָה; אֲבָל אִם לֹא הָיָה עִמּוֹ בִּשְׁעַת שְׁאִילָה וְאַחַר כָּךְ שָׁאַל אֶת הַבְּעָלִים אוֹ הִשְׂכִּירָם, אֵין זֶה שְׁאִילָה בִּבְעָלִים, אַף עַל פִּי שֶׁהָיָה עִמּוֹ בִּשְׁעַת שְׁבִירָה וּמִיתָה.\nשָׁאַל הַבַּעַל, וְנִתְרַצָּה לִהְיוֹת שָׁאוּל לוֹ, אַף עַל פִּי שֶׁלֹּא הִתְחִיל בִּמְלֶאכֶת הַשּׁוֹאֵל בִּשְׁעַת מְשִׁיכַת הַפָּרָה, \u0010y3\u0011 אֶלָּא מַזְמִין וּמֵכִין עַצְמוֹ לָלֶכֶת, חָשִׁיב שַׁפִּיר עִמּוֹ בִּמְלַאכְתּוֹ. אֲבָל \u0010c0\u0011 בַּאֲמִירָה שֶׁאוֹמֵר לִהְיוֹת שָׁאוּל לוֹ, וְלֹא הֵכִין עַצְמוֹ לִמְלַאכְתּוֹ, לָא הָוֵי שְׁאִילָה בִּבְעָלִים.\nהִשְׁאִיל לוֹ בְּהֶמְתּוֹ אוֹ הִשְׂכִּירָהּ לוֹ לְמַשּׂוֹי, וְהָלַךְ עִמָּהּ לְסַעֲדָהּ וּלְהַטְעִינָהּ, הָוֵי שְׁאִילָה בִּבְעָלִים, אַף עַל פִּי שֶׁמֵּעַצְמוֹ נִשְׁאַל לוֹ. \u0010y4\u0011 \u0005וּדְלָא כַּיֵּשׁ חוֹלְקִין בְּזֶה (מָרְדְּכַי רֵישׁ פֶּרֶק הַשּׁוֹאֵל)\u0006. וְאִם לֹא הָלַךְ אֶלָּא לִרְאוֹת שֶׁלֹּא יוֹסִיף הַמַּשֹּׁוֹי, אֵין זֶה שְׁאִילָה בִּבְעָלִים. \u0005וְכֵן אִם תָּפַס לוֹ הַשטעגר\"ב, הָוֵי \u0010y5\u0011 לְתַקָּנַת בְּהֶמְתּוֹ וְלֹא מִקְרֵי שְׁאִילָה בִּבְעָלִים (מָרְדְּכַי הַנַּ\"ל בְּשֵׁם ראבי\"ה)\u0006. \u0010c1\u0011\nאָמַר לוֹ: שְׁמֹר לִי וְאֶשְׁמֹר לְךָ, אוֹ: שְׁמֹר לִי הַיּוֹם וְאֶשְׁמֹר לְךָ לְמָחָר, \u0010y6\u0011 נִתְבָּאֵר בְּסִימָן ש\"ה.\nהָאוֹמֵר לִשְׁלוּחוֹ: צֵא וְהִשָּׁאֵל עִם פָּרָתִי, אֵינָהּ שְׁאִילָה בִבְעָלִים, שֶׁנֶּאֱמַר: אִם בְּעָלָיו עִמּוֹ \u0010y7\u0011 \u0005(שְׁמוֹת כב, יד)\u0006, הַבְּעָלִים עַצְמָם וְלֹא שָׁלִיחַ. \u0010y8\u0011 \u0010c2\u0011 \u0005וְיֵשׁ חוֹלְקִין וְאוֹמְרִים \u0010c3\u0011 דִּשְׁלוּחוֹ שֶׁל אָדָם כְּמוֹתוֹ (טוּר ס\"ט בְּשֵׁם הרמ\"ה)\u0006. וְאִם אָמַר לְעַבְדּוֹ הַכְּנַעֲנִי: צֵא וְהִשָּׁאֵל עִם פָּרָתִי, הֲרֵי זֶה שְׁאִילָה בִּבְעָלִים, \u0010y9\u0011 שֶׁיַּד הָעֶבֶד כְּיַד רַבּוֹ. \u0005הַגָּה: \u0010y10\u0011 נִשְׁאַל לוֹ הָעֶבֶד בְּלֹא דַּעַת רַבּוֹ, לֹא מִקְרֵי שְׁאִילָה בִּבְעָלִים (רַמְבַּ\"ם וְהַמַּגִּיד פֶּרֶק ב' \u0010y11\u0011 דִּשְׁאִילָה)\u0006.\nשֻׁתָּפִים שֶׁשָּׁאַל אֶחָד \u0010y12\u0011 מֵחֲבֵרוֹ, הָוֵי שְׁאִילָה בִבְעָלִים:\nהָאוֹמֵר \u0010y13\u0011 לַחֲבֵרוֹ: הַשְׁאִילֵנִי הַיּוֹם וְאַשְׁאִילְךָ לְמָחָר, אֵינוֹ שְׁאִילָה בִּבְעָלִים.\nשָׁאַל מֵהָאִשָּׁה פָּרָה נִכְסֵי מְלוֹג, וְנִשְׁאַל לוֹ בַּעְלָהּ: אוֹ אִשָּׁה שֶׁשָּׁאֲלָה פָּרָה לְצֹרֶךְ נִכְסֵי מְלוֹג שֶׁלָּהּ וְנִשְׁאַל בַּעַל הַפָּרָה לְבַעְלָהּ, לָא הָוֵי שְׁאִילָה בִּבְעָלִים, מִשּׁוּם \u0010y14\u0011 דְּקִנְיַן פֵּרוֹת לָאו כְּקִנְיַן הַגּוּף דָּמֵי.\nשָׁאַל פָּרָה \u0010y15\u0011 \u0010c4\u0011 לְרָבְעָהּ אוֹ לֵרָאוֹת \u0005בָּה,\u0006 אוֹ לַעֲשׂוֹת בָּהּ פָּחוֹת מִשְּׁוֵה פְרוּטָה, אוֹ שֶׁשָּׁאַל שְׁתֵּי פָּרוֹת לַעֲשׂוֹת בָּהֶן שְׁוֵה פְּרוּטָה, \u0010c5\u0011 הֲרֵי זֶה סָפֵק, וְאֵין מוֹצִיאִין מִיָּדוֹ: \u0010y16\u0011\nשָׁאַל מִשְּׁנֵי שֻׁתָּפִים וְנִשְׁאַל לוֹ אֶחָד מֵהֶם, וְכֵן הַשֻּׁתָּפִים שֶׁשָּׁאֲלוּ וְנִשְׁאַל לְאֶחָד מֵהֶם, הֲרֵי זֶה סָפֵק אִם הִיא שְׁאִילָה בִּבְעָלִים אִם לָאו. לְפִיכָךְ, אִם מֵתָה אֵינוֹ מְשַׁלֵּם, \u0010c6\u0011 וְאִם תָּפְסוּ הַבְּעָלִים אֵין מוֹצִיאִין מִיָּדָם. \u0010y17\u0011 \u0010c7\u0011 וְאִם פָּשַׁע בָּהּ, יֵשׁ \u0010c8\u0011 מְחַיְּבִים וְיֵשׁ פּוֹטְרִים:\nמְלַמֵּד תִּינוֹקוֹת, וְהַנּוֹטֵעַ לִבְנֵי הַמְּדִינָה, וְהַמַּקִּיז לָהֶם דָּם, וְהַסוֹפֵר שֶׁלָּהֶם, כָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶם, בְּיוֹם שֶׁהוּא יוֹשֵׁב בּוֹ לַעֲשׂוֹת בִּמְלַאכְתּוֹ, אִם הִשְׁאִיל אוֹ הִשְׂכִּיר לְאֶחָד מֵאֵלּוּ שֶׁהוּא עוֹסֵק בִּמְלַאכְתָּם הֲרֵי זוֹ שְׁמִירָה בִּבְעָלִים, וַאֲפִלּוּ פָּשַׁע בָּהּ הַשּׁוֹמֵר פָּטוּר. אֲבָל הוּא שֶׁשָּׁאַל אוֹ שָׂכַר מֵהֶם, חַיָּב, שֶׁאֵינָם שְׁאוּלִים לוֹ. וְיֵשׁ אוֹמְרִים שֶׁבִּזְמַן הָרָאוּי לַמְּלָאכָה, אַף עַל פִּי שֶׁאֵינָם עֲסוּקִים בָּהּ, לְפִי שֶׁאֵינוֹ רַשַּׁאי לְהִשָּׁמֵט מֵהַמְּלָאכָה הַהִיא בְּכָל עֵת שֶׁצְּרִיכִים לוֹ, הָוֵי לְגַבַּיְהוּ שְׁאִילָה בִּבְעָלִים; אֲפִלּוּ אִם צָרִיךְ לָתֵת לוֹ שָׂכָר, מִכָּל מָקוֹם מֻכְרָח הוּא לַעֲשׂוֹת לוֹ מְלַאכְתּוֹ, \u0010y18\u0011 מִידִי דְּהָוָה אַשֻּׁתָּפִים שֶׁשָּׂכְרוּ שְׂכִיר חֹדֶשׁ אוֹ שָׁנָה, דִּבְכָל שָׁעָה הָוֵי שְׁאִילָה בִּבְעָלִים לְכָל אֶחָד מֵהֶם.\nהָרַב הַשּׁוֹנֶה לְתַלְמִידָיו, אִם הֵם צְרִיכִים לִלְמֹד עִמּוֹ בְּכָל מַסֶכְתָּא שֶׁיִּרְצֶה הוּא, וְאַף אִם הִתְחִילוּ מַסֶכְתָּא אַחַת יָכוֹל לְשַׁנּוֹתָהּ לְאַחֶרֶת, אָז הָווּ הֵם כִּשְׁאוּלִים לוֹ, שֶׁהֵם עִמּוֹ בִּמְלָאכָה, וְאִם שָׁאַל מֵהֶם הָוֵי שְׁאִילָה בִּבְעָלִים. וְאִם הוּא צָרִיךְ לִלְמֹד עִמָּהֶם בְּכָל מָקוֹם שֶׁיִּרְצוּ, \u0010y19\u0011 אָז הוּא נִשְׁאַל לָהֶם; וַאֲפִלּוּ שֶׁלֹּא בִּשְׁעַת הַלִּמּוּד, כֵּיוָן שֶׁצָּרִיךְ לִלְמֹד עִמָּהֶם בְּכָל עֵת שֶׁיִּרְצוּ. וְאִם הַדָּבָר תָּלוּי בִּשְׁנֵיהֶם, שֶׁהַמַּסֶכְתָּא שֶׁהִתְחִיל יִגְמְרוּ, וְאֵין הָרַב יָכוֹל לְשַׁנּוֹת הַמַּסֶכְתָּא שֶׁלֹּא מִדַּעַת הַתַּלְמִידִים, וְלֹא הַתַּלְמִידִים בְּלֹא דַּעַת הָרַב, אָז אֵינָם שְׁאוּלִים זֶה לָזֶה כְּלָל. וְלִפְנֵי הַמּוֹעֲדִים, שֶׁדֶּרֶךְ לִדְרֹשׁ לָעָם הִלְכוֹת הַמּוֹעֵד, הוּא נִשְׁאַל לָהֶם. \u0005הַגָּה: וְכֵן הַדִּין בִּשְׁלִיחַ צִבּוּר עִם קָהָל שֶׁלּוֹ, דְּאִם הַקָּהָל אֵינָן יְכוֹלִין לְהִשָּׁמֵט מִמֶּנּוּ הֵם כִּשְׁאוּלִין לוֹ; וְאִם הוּא אֵינוֹ יָכוֹל לְהִשָּׁמֵט מֵהֶן, הוּא נִשְׁאַל לָהֶן (בֵּית יוֹסֵף בְּשֵׁם הָרַשְׁבַּ\"ץ)\u0006. \u0010y20\u0011\nשְׁאָלָהּ בִּבְעָלִים וּשְׂכָרָהּ שֶׁלֹּא בִּבְעָלִים, \u0010y21\u0011 פָּטוּר, שֶׁהַשְּׂכִירוּת תָּלוּי \u0010y22\u0011 בַּשְּׁאִילָה. אֲבָל אִם שְׂכָרָהּ בִּבְעָלִים \u0010y23\u0011 וְחָזַר וּשְׁאָלָהּ שֶׁלֹּא בִּבְעָלִים, אוֹ שְׁאָלָהּ בִּבְעָלִים וְחָזַר וּשְׂכָרָהּ שֶׁלֹּא בִּבְעָלִים וְחָזַר וּשְׁאָלָהּ שֶׁלֹּא בִּבְעָלִים, אוֹ שֶׁשָּׂכְרָהּ בִּבְעָלִים וְחָזַר וּשְׁאָלָהּ שֶׁלֹּא בִּבְעָלִים וְחָזַר וְשָׂכְרָהּ שֶׁלֹּא בִּבְעָלִים, \u0010c9\u0011 כָּל אֵלּוּ סָפֵק שְׁמִירָה בִּבְעָלִים הוּא. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם שְׂכָרָהּ בִּבְעָלִים וְחָזַר וּשְׁאָלָהּ שֶׁלֹּא בִּבְעָלִים, מִקְרֵי שְׁמִירָה בִּבְעָלִים (טוּר סי\"ו בְּשֵׁם הָרֹא\"שׁ)\u0006.\nיֵשׁ אוֹמְרִים שֶׁאִם שְׂכָרָהּ בִּבְעָלִים וְחָזַר וּשְׂכָרָהּ שֶׁלֹּא בִּבְעָלִים, הֲוֵי שְׁנִיָּה בִּבְעָלִים כְּמוֹ הָרִאשׁוֹנָה; אֲבָל אִם רִאשׁוֹנָה שֶׁלֹּא בִּבְעָלִים וּשְׁנִיָּה בִּבְעָלִים, \u0010y24\u0011 אֵין הָרִאשׁוֹנָה גּוֹרֶרֶת אֶת הַשְּׁנִיָּה לִהְיוֹת שֶׁלֹּא בִּבְעָלִים.\nבַּעַל בְּנִכְסֵי מְלוֹג שֶׁל אִשְׁתּוֹ, אֲפִלּוּ פָּשַׁע בָּהֶם וְנֶאֶבְדוּ, פָּטוּר, \u0010y25\u0011 \u0010c10\u0011 שֶׁהִיא עִמּוֹ בִּמְלַאכְתּוֹ. \u0010y26\u0011\nאִשָּׁה שֶׁשָּׁאֲלָהּ וְאַחַר כָּךְ נִשֵּׂאת, הֲרֵי הַבַּעַל כְּלוֹקֵחַ וְאֵין לוֹ דִּין שׁוֹמֵר; לְפִיכָךְ, אִם הַדָּבָר הַשָּׁאוּל בְּהֵמָה וָמֵתָה, הַבַּעַל פָּטוּר אַף עַל פִּי שֶׁהוּא מִשְׁתַּמֵּשׁ בָּהּ כָּל יְמֵי שְׁאִילָתָהּ, אֲפִלּוּ פָּשַׁע, מִפְּנֵי שֶׁהוּא כְּלוֹקֵחַ. \u0005הַגָּה: \u0010y27\u0011 \u0010c11\u0011 אֲבָל לֹא מִפְטָר מִטַּעַם שְׁמִירָה בִבְעָלִים, \u0010y28\u0011 דְּהָא אֵין הַחֵפֶץ שֶׁלָּהּ רַק שָׁאוּל בְּיָדָהּ (ד\"ע מִדִּיּוּק הַטּוּר)\u0006. וְכֵן גַּזְלָן שֶׁהִפְקִיד אוֹ הִשְׁאִיל דָּבָר הַנִּגְזָל, אַף עַל פִּי שֶׁהָיָה בִּמְלֶאכֶת הַשּׁוֹאֵל, חַיָּב שׁוֹאֵל בָּאֳנָסִין, דְּלָא מִקְרֵי שְׁאִילָה בִּבְעָלִים אֶלָּא \u0010c12\u0011 בְּבַעַל הַחֵפֶץ עַצְמוֹ \u0005(מָרְדְּכַי ר\"פ הַגּוֹזֵל בַּתְרָא)\u0006. \u0010y29\u0011 וְהָאִשָּׁה חַיֶּבֶת לְשַׁלֵּם כְּשֶׁיִּהְיֶה לָהּ מָמוֹן \u0005(וְע\"ל סִימָן תכ\"ד ס\"י)\u0006. \u0010c13\u0011 \u0010c14\u0011 וְאִם הוֹדִיעַ [ה] אֶת בַּעְלָהּ שֶׁהִיא שְׁאוּלָה, הֲרֵי זֶה נִכְנַס תַּחְתֶּיהָ. \u0005הַגָּה: וְדַוְקָא שֶׁנִּשְׁתַּמֵּשׁ בָּהּ לְאַחַר שֶׁהוֹדִיעָתוֹ (טוּר ס\"\u0006 ךָ \u0005בְּשֵׁם הָרַמְבַּ\"ם פ\"ב דִּשְׁאִילָה)\u0006, אוֹ שֶׁקִּבֵּל עָלָיו לִהְיוֹת הוּא הַשּׁוֹאֵל \u0005(שָׁם בְּשֵׁם הָרַאֲבַ\"ד)\u0006. \u0010y30\u0011\nלוֹקֵחַ בְּהֵמָה לִשְׁלֹשִׁים יוֹם, שׁוֹמֵר חִנָּם עָלֶיהָ.\nכָּל אֵלּוּ הַחִלּוּקִים שֶׁל שְׁאִילָה בִּבְעָלִים, נוֹהֲגִין גַּם כֵּן בְּכָל הַשּׁוֹמְרִים:",["\u0003שנא' אם בעליו עמו \u0004 בגמ' פ' השואל דף צ\"ה יליף מדיוקא דקרא דכתיב אם בעליו עמו לא ישלם וקאי אמ\"ש לפני זה דאיירי משאלה ושבורה ומיתה דמשמע דוקא דבעלים עמו בתרוייהו בשאלה ובשבורה או מיתה הא הוה בחד מנייהו ולא באידך חייב ומדכתיב בעליו אין עמו ישלם משמע דאינו בשום א' מתרוייהו הא הוה בחד מנייהו פטור וקאמר הא דמשמע דאם היה בחד מנייהו פטור היינו אם היה בשעת שאלה אף דלא היה בשעת שבירה או מיתה והא דמשמע דבעינן שיהא בתרוייהו היינו דאף אם היה עמו בשעת שבורה ומיתה חייב אם לא היה עמו בשעת שאלה ושם יהיב טעמא דלא אמרינן איפכא וכתבתיהו בדרישה ע\"ש ומשואל ילפינן לכל השומרים וכמ\"ש הטור והמחב' בס\"ס זה גם כתבו כן לעיל במקומן בדין שאר שומרין ולא כע\"ש שכתב כאן דהא דבעינן שיהא עמו בשעת שאלה ולא בשעת שבירה ומיתה נילף ממשמעות הקרא דאם בעליו עמו דמשמע דקאי אוכי ישאל דלע ל מיני' ואשתמיטת' מיני' הגמ' הנ\"ל ע\"ש ודוק:","\u0003אבל אם משך תחלה ואח\"כ השקהו כו' \u0004 ה\"ה אם עשה עמו אח\"כ מלאכה גמורה אלא נקט זה משום רבותא דהשקהו בשעת שאלה דפטור:","\u0003אפי' לא הי' עמו בשעת כו' \u0004 כבר כתבתי הלימוד לזה מדיוקא דקרא:","\u0003אלא מזמין ומכין כו' \u0004 והיינו דוק' כשהבטיחו לעשו' מלאכתו ולא קבע לו השואל לזה זמן אבל אם קבע לו השואל זמן אימתי יעש' מלאכתו אף שהו' מוכן לא מיקרי שאל' בבעלי' כ\"כ הטו' בשם הרמ\"ה ונרא' דגם הרא\"ש מוד' בזה ועפ\"ר:","\u0003ודלא כיש חולקין כו' \u0004 עד\"מ שם הביא דעת המרדכי דס\"ל דבעינן שהשואל יבקש ממנו לעשות מלאכה זו:","\u0003לתקנת בהמתו \u0004 דאם יעלה על הבהמה בלא תפיסת הש\"טעגרב יכאיב לה:","\u0003נתבאר בסי' ש\"ה \u0004 ע\"ש דכ' הטור והמחבר דשמור לי ואשמור לך מיד הוה שמירה בבעלים ופטור מכל דבר ובשמור לי היום ואשמור לך למחר לא הוה שמירה בבעלים ודין ש\"ש עלי' דאם נגנב מיד השומר היום מחויב לשלם לו דהא מקבל הנא' על שמירתו דישמרנו לו בעל הפרה או של הכלי למחר וע\"ש בסי' ש\"ה דנתבא' נמי דין שאול לי ואשאל לך אי הוה שאלה בבעלים ופטור או לא ויש פלוגתא בזה ומ\"ה לא כ' כאן דין שאול לי ואשאילך ובסמוך ס\"ו [ס\"ח] כ' דין השאילני היום ואשאילך למחר דלא הוה שאלה בבעלים הרי דנקט דינים הברורים ומפלוגתא לא איירי:","\u0003הבעלים עצמן ולא שליח \u0004 אע\"ג דקי\"ל בכ\"מ שלוחו של אדם כמותו שאני הכא דכתיב ב\"פ בעליו עמו דמשמע דדקדק הכ' דוקא הבעלים עצמן:","\u0003ויש חולקין כו' \u0004 עד\"ר והגד\"מ שם שכתבתי טעם לדברי מור\"ם למה הביא דעת החולקין ולא פסק כהרי\"ף והרמב\"ם וכמ\"ש המחבר ע\"ש.","\u0003שיד עבד כיד רבו \u0004 ואע\"ג דאינו בר מצות ועד\"ר:","\u0003נשאל לו העבד בלא דעת רבו כו' \u0004 פי' ול\"ת שגם לזה מקרי ידו כיד רבו:","\u0003ששאל א' מהן מחבירו \u0004 פי' אפי' לצרכו שאינו לצורך השותפות וקאמר ששאל א' מהן דאלו שניהן שאלו זה מזה ה\"ל כדין השאילני ואשאילך דאפי' באנשי' שאינן שותפין ה\"ל שמיר' בבעלי' לחר מ\"ד וכ\"כ בב\"י ע\"ש וזהו דלא כמ\"ש המ\"מ וכ\"מ ע\"ש:","\u0003הוה שאלה בבעלים \u0004 דתמיד הן יחד בעסק השותפות:","\u0003השאילני היום כו' אינה שאלה בבעלים \u0004 ור\"ל דאינו פטור אבל מ\"מ אינו עליה אלא ש\"ש וכמ\"ש לעיל סי' ש\"ה ס\"ו:","\u0003דקנין פירות כו' \u0004 פי' דבעל בנכסי מלוג אשתו אין לו אלא פירות כ\"ז היותם יחד ואינו נקרא בעל במלאכתו:","\u0003לרבע' או להראותו בה כו' \"עד ה\"ז ספק \u0004 פי' דהן איבעיא דלא איפשטא בגמ' וז\"ל הגמ' לרבעה מהו כדשיילי אינשי בעינן ולהכי לא שיילי אינשי א\"ד טעמא מאי משום הנאה והכא אית לי' הנאה להראות בו עשיר ויקיפו לו מהו ממונא בעינא והא איכא או דלמא בעינא ממונא מינה דשאלה גופא והא ליכא פחות משום פרוטה מהו מי אמרינן ממונא בעינן והא איכא או דלמא כל פחות מש\"פ לאו כלום הוא שאל ב' פרות מהו מי אמרינן זיל בתר שואל ומשאיל והאיכא א\"ד זיל בתר פרות ובכל חדא וחדא ליכא ממונא תיקו וכל הנך איבעיות פירש\"י והטור לענין אי הוי לשואל דין שואל להתחייב באונסין או לא אבל אי שאלינהו בבעלים לא קמבעיא להו בהו דפשיטא דפטור באונסין אבל הרמב\"ם פי' גם הני איבעית לענין שאלה בבעלים וכמ\"ש המ\"מ שם והמחבר סתם דבריו כדי לפרש בו איזה פי' שנרצה ודוק:","\u0003שאל משני שותפין כו' \u0004 ג\"ז איבעיא דלא איפשטא וז\"ל הגמ' כולו בעליו בעינן והא ליכא א\"ד מההיא דידיה מיהא מיפטר שותפין ששאלו כו' כולו שואל בעינן והא ליכא א\"ד מההיא פלגא דשיילי מיהת מיפטר עכ\"ל:","\u0003ואם פשע בה יש מחייבין \u0004 טעמו דס\"ל דפושע כמזיק בידים הוא וכל שאין לנו ראיה ברורה דהוה פשיעה בבעלים לפטרו חייב לשלם והטו' ס\"ל דאין לחלק בין פשיע' בבעלי' לגניב' ואביד' בבעלי' וכיוצ' בזה כתבו הטו' והמחב' פלוגתתן לעיל בס\"ס ס\"ו ע\"ש:","\u0003מידי דהוה אשותפין ששכרו שכיר חדש כו' \u0004 פי' מידי דהוה שנים ששכרו בשותפו' שכיר לחדש שיהא שכיר למלאכת שניהן לעשות לכל א' מלאכת עצמו באיזה שצריך לו ושותפין דקאמר ר\"ל שהן שותפין בשכיר חדש זה אבל אינו ר\"ל שהן שותפין בדבר אחר ושוכרין שכיר חדש זה לעשות להן בדבר ההוא דא\"כ ל\"ד לשתלא ומקיז דם ואינך דקחשיב דהרי שם בני המדינה אינן משותפין בו יחד בכלום וק\"ל ועפ\"ר:","\u0003אז הוא נשאל להם כו' \u0004 ואפי' שלא בשעת הלימוד כיון שצריך ללמד עמהן בכל עת שירצו כ\"כ ג\"כ הטור ועד\"ר שדקדקתי מדכתב כן בהוא נשאל להן ולא כ\"כ בהן נשאלין לו דמחשב שאלה בבעלים אפי' בשעה שאינן לומדין וגם הרשב\"ץ דקדק לכתוב בש\"ץ השאיל להן (שכ' מור\"ם דינו בסמוך בהג\"ה) דמחשב הוא להן שאלה בבעלים בכל אותו יום אפי' שלא בשעת תפלה ובהן שאולין לו לא כ' ששאולין לו אלא בשעת תפלה וכתבתי דנראה דה\"ט דברב וש\"ץ שעושים פעולת הלימוד והנגינה דתפילה נראה בהן הפעולה יותר ומ\"ה מחשבין פועלים ועמהן במלאכתן יותר ע\"ש:","\u0003שאלה בבעלים ושכרה שלא בבעלים פטור כו' \u0004 פי' שלאחר שכלה זמן השאלה שהיתה מתחלה בבעלים לא החזיר להמשאיל אלא עומדת עדיין בחצירו וחזר ושכרה לזמן מה שלא בבעלים ונגנבה או נאבד' באותו זמן של השכירות:","\u0003פטור שהשכירות תלוי בשאלה \u0004 פי' אין לך דין חיוב שוכר שלא תהא חייב עליו השואל וכיון דהשואל הי' פטור בזמן שאלתו כיון שהשאיל בבעלים הרי הוא כאלו ימי השאלה הגיעו עד סוף זמן השכירו' ופטו' אם נגנב' או נאבד' וכ\"ש אם נאנס' שהרי השוכ' פטור באונסים:","\u0003אבל אם שכרה כו' \u0004 בזה איבעי' בגמ' כיון דדין שאלה נתחלק מדין שכירו' שהרי שואל חייב באונסין ולא שוכר לא יהנה השכירו' שהי' בבעלים למה שנאנס בימי השאל' שהי' שלא בבעלים ואע\"ג דלא חזר ומשכה מחדש מ\"מ כיון דעדיין עומדת בחצירו מיד ששאלה ממנו חל עליו חייב דין שואל להתחייב אפי' באונסין א\"ד כיון דשייך דין שואל בדין שכירות בחיוב גניב' ואביד' כאלו שייכי בכול' דמי:","\u0003וחזר ושאלה שלא בבעלים כו' \u0004 אבעיות הללו פירש\"י והרא\"ש דגם הן באת\"ל דשאלה בשכירות ג\"כ מישך שייכי הואיל ושייכי במקצת מ\"מ כאן כיון דצריכין לו' תרתי מישך שייכי דהיינו שכירו' בשאל' ושאלה בשכירו' כולי האי לא אמרי' א\"ד אמרי' כיון דבראשונ' שואל בבעלי' חזר' שאל' בתריית' למקומ' לשאל' הראשונ' וכן בשכר' ראשונ' בבעלים חזרה השכירות אחרונ' למקומ' ולשכירות הראשון וזהו טעם הי\"א דכ' מור\"ם אם שכרה בבעלים וחזר ושאלה שלא בבעלים מיקרי שמירה בבעלים כיון דגרסי' בגמ' באיבעי' שלישי' את\"ל וכל את\"ל ה\"ל פשיטות דאיבעי' שלפני זה אבל הרמב\"ם לא גרס את\"ל מה\"נ כ' המחבר שהוא בספק:","\u0003אין הראשונ' גוררת את השנייה כו' \u0004 כלו' ל\"ת כיון דבעינן דיהא תחלת השכירות או השאלה בבעלים ואי לא הוה מתחילתו בבעלים אע\"פ שאח\"כ בשעת שבירה ומיתה הוה בבעלים חייב כמ\"ש הטו' והמחב' בסי' זה בס\"ב וה\"נ נחשב הכל כשכירות א' והרי מתחלתו שלא בבעלי' הי' קמ\"ל כיון דכלו ימי שכירו' הראשונ' ה\"ל זה כשכירו' חדשה והיה בבעלים ופטו' אע\"ג דאם הוה שכירות הראשונ' בבעלים ושניה שלא בבעלים אמרי' דמחשב הכל לשכירו' א' ופטו' בשומרין הולכין להקל וכ\"כ הטור ע\"ש:","\u0003שהוא עמו במלאכתו \u0004 פי' אפי' שאלה ממנו בשעה שאינה עוסקת עמו במלאכתו פטו' כיון דהיא מוכנת ועומדת לעסוק במלאכתו תדיר משא\"כ איפכא כשהיא שואלת ממנו דמחשב כאלו שאלה מאחר ואינה פטורה אא\"כ שאלה ממנו בשעה שעוסק במלאכתה והטור מסיק וכ' בזה ז\"ל אפי' היו שכורין או שאולין בידו ממנה קודם שנשאה שלא בבעלים ואח\"כ נשאה מאותה שעה ואילך חשוב שאלה או שכירות בבעלים ונסתלק שאלה או שכירות הראשון שלא הי' בבעלים ופטור עכ\"ל:","\u0003אשה ששאלה ואח\"כ נשאת כו' \u0004 כן הוא ל' הרמב\"ם ספ\"ב דשאל' וכתב שם המ\"מ ז\"כ דהוא איבעיא דאפשט' כו' וצ\"ל דאע\"ג דאיבעיא בגמ' הוא אי שכר' הוא מאחר ונשאת כו' ס\"ל להרמב\"ם דל\"ד \"שכר' אלא ה\"ה אי \"שאלה וכ\"כ הנ\"י האיבעי' וכ\"כ ב\"י ועד\"ר:","\u0003אבל לא מיפטר מכח שמירה בבעלים. \u0004 כ\"כ גם בד\"מ והוא תמוה דנראה מוכח מל' הטור דגם בכה\"ג פטור מפשיעה מכח שמירה בבעלים דאי מה\"ט דלוקח הוי לחוד הוי מחייב אפשיעה כדין ש\"ח דומיא דלוקח לל' יום כמ\"ש הט\"ו אחר זה (ואי משום שמירה בבעלים לחוד בכה\"ג דאין לו עסק עם האשה אלא עם המשכיר היה חייב מ\"ה צריך הטעם דלוקח הוה) וכן כתבו התו' והטו' בהדי' דין לוקח לשלשים יום דחייב כדין ש\"ח אדין זה דבעל בנכסי אשתו לוקח הוא ול\"ד בנכסי אשתו של עצמ' אלא אף אפרה ששכר' ונשאת כ\"כ ע\"ש וכ' דמ\"מ בעל פטור משום דה\"ל שמיר' בבעלים ועמ\"ש בפרישה ישוב לדברי הטור והמחבר שאזלו בשטת ר\"י והרא\"ש וחלקתי \"בין אם שאלה או שכר' היא הפרה כל ימי חיות' דהפרה או כל ימי חיותה דהאשה (דומה למ\"ש הטור והמחב' בסי' שמ\"א בא\"ל השאלני בטובך ע\"ש) דבכה\"ג פטו' הבעל אפי' פשע בה ונגנבה משום לוקח ולא משום פשיעה בבעלים כיון דהפר' עכ\"פ אינה שלה ומזה איירי המחבר ומור\"ם כאן וגם הטור בסי\"ט. ובין שכרה או שאל' לזמן כגון לל' יום דבכה\"ג אף שהוא לוקח חייב בפשיעה דלא עדיף מלוקח ממש לזמן וכמ\"ש ר\"י והטור בסכ\"א וא\"כ לק\"מ ודוק:","\u0003דהא אין החפץ שלה רק שאול בידה כו' \u0004 כבר כתבתי דס\"ל דל\"ד \"שכר' היא אמרו בגמ' אלא ה\"ה שאלה היא ומ\"ה הוצרך לומר דהטעם הוא משום דאין החפץ שלה ולא משום שלא תיקח היא דמי המיתה מהשואל ולא תתננה למשכיר שלה כלום דהיינו עושה סחורה בפרתו של חבירו ודוק:","\u0003והאש' חייבת לשלם כו' \u0004 ע\"ל סי' תכ\"ד ס\"י דאם יש לה נ\"מ או נצ\"ב או תוספות על כתוב' דאורייתא דחייבת למכור בטובת הנאה אלא דמיירי כאן באין לה וסמך אמ\"ש ל' בסי' תכ\"ד וכן משמע בד\"מ ע\"ש. וגם בגמ' פ' החובל (בבא קמא דף פ\"ט ע\"א) דפריך אדין חבלה תזבין נכ\"מ ותתן ליה ומשני בדלית לה ומדפשט להמקשן כ\"כ דביש לה נ\"מ דמחויבת לזבין ולשלם משמע דס\"ל בשאר חיובי מחויבת למכור נכ\"מ ולשלם דאל\"ה לא ה\"ל למקשן להקשו' כ\"כ בפשיטות ודוק ועד\"ר:","\u0003לוקח בהמה לל' יום כו' \u0004 הטעם כיון דאינו לוקח גמור:"],["\u0003 באמירה כו' \u0004 כ\"כ הטור ולפע\"ד אינו מוכרח בהרא\"ש דמ\"ש הרא\"ש והיינו אמירה דלעיל ר\"ל דמוכח התם דלא בעינן עידן עבידתייהו ממש והוא הדין דלא בעינן הכנה אלא דבש\"ס קאמר בעידן עבידתייהו פי' הרא\"ש כן וכן משמע בתוס' ר\"פ השואל וכן משמע ל' ר\"י נ\"ל ח\"ג וז\"ל שאלה בבעלים מיקרי מזמן שמכיני' עצמן ללכת כו' כי בעלים באמירה עכ\"ל ובתו' פ' חז\"ה דף מ\"ג ע\"ב ובמרדכי שם גבי מה שהקשו דא\"ל שמור לי היום כו' וא\"ת אכתי שמירה בבעלים היא דאמרי' בריש השואל דבעלים באמיר' ותירצו דשאני התם דבאמיר' משעבד עצמו ליכנס במלאכתם מיד אבל הכא לא משתעבד עד למחר עכ\"ל מוכח דבאמירה אף בלא הכנה הוי שמירה בבעלים ודוק:","\u0003 א\"ל שמור לי היום כו'. \u0004 עיין בתשו' הר\"ן סי' כ':","\u0003 וי\"ח כו' \u0004 עיין בסמ\"ע ס\"ק ט' שכתב שבדרישה כתב טעם החולקין והטעם ברור שכבר השיג הרא\"ש על הרי\"ף בדברים נכונים וכן שאר אחרונים השיגו על הרי\"ף והרמב\"ם בזה כדאית' בנ\"י ע\"ש:","\u0003 דשלוחו של אדם כמותו \u0004 כלו' דמספיקא לא מפקינן ממונא ואמרי' שלוחו של אדם כמותו וכן מוכח בש\"ס ופוסקים וכ\"כ הנ\"י בשם הר\"ן להדי' ולפ\"ז אם תפס המשאיל לא מפקינן מיניה אפי' להיש חולקין וכן עיקר:","\u0003 לרבעה כו'. \u0004 עיין בסמ\"ע ס\"ק ט\"ז שמביא אבעיות דש\"ס ומסיים בתיקו כו' וזה אינו אלא בש\"ס ובפוסקים הוא בעיא דלא איפשטא אבל לא סלקא בתיקו ונ\"מ דאם תפס המשאיל אין מוציאין מידו אבל אי הוי סלקו בתיקו מוציאין מידו וכמש\"ל סי' כ\"ה ס\"ב לדעת הרא\"ש וטור וכן כתבתי שם בשם רש\"ל (וכן כתבתי לקמן ס\"ס שצ\"א לדעת הטור ע\"ש) וכ\"כ הטור כאן להדיא ואף לענין אונסין אי תפס לא מפקינן מיניה שוב הארכתי בזה בספרי תקפו כהן:","\u0003 הרי זה ספק כו'. \u0004 אם חייב באונסי' אבל חייב בגנבה ואבדה כיון דאיכא ש\"פ לשואל כדין ש\"ש כ\"כ הרא\"ש וכ\"כ הרא\"ש בשם הרמ\"ה ומשמע מכאן דאין ש\"ש חייב בגנבה ואבדה אא\"כ שכרו ש\"פ:","\u0003 ואם תפסו הבעלים כו' \u0004 תימא על הר\"ב שסתם כאן כמחבר ולעיל סימן ר\"ב ס\"ג וכן סי' תי\"ג ס\"א הביא דעת היש חולקין דבבעי' דלא נפשט' לא מהני תפיסה וכן קשה על הע\"ש:","\u0003 ואם פשע כו'. \u0004 עיין בסמ\"ע ס\"ק י\"ח וכן הוא בה' המגיד דזה תלוי בפלוגתתן דלעיל (הג\"ה ס\"ס ס\"ו) עיין בתשובת ר\"י לבית לוי סי' נ\"א:","\u0003 ויש פוטרים \u0004 וכן עיקר וכדלעיל סי' ס\"ו ס\"מ ור\"ס ש\"א:","\u0003 כל אלו ספק שמירה בבעלים הוא. \u0004 וכ' הטור ואי תפס מפקינן מיניה וכ' ב\"י וב\"ח שיש ט\"ס בדבריו וצ\"ל לא מפקינן מיניה כדלעיל סי\"א ואחריו הגיהו כן בטור ולפע\"ד י\"ל כי אדרבה בכונה כ' הטור כאן מפקינן מיניה דהנך בעיות סלקא בש\"ס בתיקו וכבר כ' הרא\"ש בפרק כיצד הרגל דהיכ' דסלק' בתיקו [לא] מהני תפיס' וכמ\"ש הטו' גופו בשמו לקמן סי' שפ\"ח ס\"א וס\"ד וכ\"כ סי' ש\"ץ סס\"א בשם ר\"י ול\"ד לדלעיל סי\"א דלא סלק' בתיקו וכמ\"ש שוב מצאתי בטור קלף ישן נושן לא מפקינן מיני' וכן העליתי בספרי תקפו כהן דאין לחלק בין תיקו לבעי' דלא איפשט' לדע' הרא\"ש וע\"ש שהארכתי בזה:","\u0003 שהוא עמו במלאכתו כו'. \u0004 עיין בתשובת מהרי\"ט סי' ש\"ל:","\u0003 אבל לא מפטר מטעם שמירה בבעלי' כו' \u0004 כ' בסמ\"ע ס\"ק כ\"ח שהוא תמוה דנרא' מוכח מל' הטור דגם בכה\"ג פטור מכח שמיר' בבעלי' דאי מה\"ט דלוקח הוי לחוד הוי מחייב אפשיע' כדין לוקח בהמ' לל' יום ואי משום שמיר' בבעלי' לחוד בכה\"ג דאין לו עסק עם האשה אלא עם המשכיר היה חייב מ\"ה צריך הטעם דלוקח הוה כו' ולא ידענ' מאי קשיא ליה דגם כוונת מור\"ם כן הוא דמשו' שמיר' בבעלי' לחוד לא מפט' אי לא הוי כלוקח ונ\"מ בגזלן שהפקיד כו' ודוק: גם מה שתירץ הסמ\"ע דבשכרה או שאלה לזמן כגון לשלשים יום דבכה\"ג אף שהוא לוקח חייב בפשיעה דלא עדיף מלוקח לזמן כו' וכ' שכתב כן לדברי הטור והמחבר דאזלי בשטת הרא\"ש ע\"ש לא ידעתי מי הזקיקו לזה וגם לא נהירא כלל דכיון שהוא לוקח אינו שומר של המשאיל רק שומר של אשתו ופטו' מפשיע' לדעת הרא\"ש וטור דהוי שמירה בבעלים ואין טעם כלל לחלק בין שאל' הפרה כל ימיה ובין שאלה לזמן ול\"ד ללוקח בהמה לל' יום דהוה שומר של משאיל ואין המשאיל עמו. והכי מוכח להדיא ממ\"ש הרא\"ש וטור דלענין בעל בנכסי אשתו לא נ\"מ מידי והוצרכו לדחוק דיש נ\"מ בדברי ר\"י בלוקח בהמה לל' יום ואם איתא ה\"ל לפרש כפשוטו דנ\"מ בשאל' לל' יום ונשאת אלא ודאי פשיטא דהבעל פטור בכל ענין לסברתם ודוק כך נ\"ל לדעת הרא\"ש וטור וכן דעת מור\"ם בהג\"ה אם נא' דס\"ל כוותייהו:","אבל באמת דברי הרא\"ש והטו' תמוהין לי דהיכא קאמרי דמשום שמירה בבעלים פטור דהא אמרי' בש\"ס (פ' השואל דף צ\"ו ע\"ב) בשאלה ונישאת דלר' יוסי דקי\"ל כוותיה דאמר תחזו' פרה לבעילים הראשוני' לא שייך כאן שמיר' בבעלים דה\"ל כמאן דשאיל מבעלי' הראשוני' ומייתי לה הרי\"ף והרא\"ש התם וא\"כ נהי דמסקינן דבעל לוקח הוה מ\"מ לפי מה שפי' ר\"י דמ\"מ ש\"ח הוי א\"כ בפשיע' חייב דכשומ' של בעלים הראשוני' הוא להתחייב בפשיע' (ודוחק גדול לו' דדוקא בשוכר שהשאיל אמרי' כן לר' יוסי משא\"כ הכא ודוק) ונרא' דס\"ל להרא\"ש וטו' דהא דקאמרי' בש\"ס דלר' יוסי לא הוי שמיר' בבעלים היינו מקמי דקאמרי' בעל לוקח הוי אבל לבתר דמסיק דלוקח הוי א\"כ אפי' לר' יוסי אין לבעל דין עם בעלים הראשוני' כלל רק עם האשה והוי שמיר' בבעלי' אבל אין זה עיקר אלא נראה כמ\"ש דלפי' ר\"י אף למאי דמסקי' דלוקח הוי לא הוי שמיר' בבעלי' וחייב בפשיעה (שוב ראיתי במע\"מ פ' השואל בזה באריכות ע\"ש) וכן משמע פשט דברי התוספו' דר\"י אסוגיא דשמעת' קאי דהבעל חייב בפשיע' ע\"ש בתוס' וכן משמע להדיא בנ\"י שאביא לקמן דלהתוס' חייב כאן בפשיע' וכן משמע להדי' באגודה וז\"ל בעל בנכסי אשתו לא שואל ולא שוכר הוי אלא לוקח הוי מתקנת אוש' פר\"י שומר חנם הוא חייב בפשיע' וכן הלוקח בהמ' לל' דלא שואל ולא שוכר הוי ואפ\"ה חייב בפשיע' עכ\"ל משמע להדי' דגם הבעל בנכסי אשתו ששאל' פרה חייב בפשיע' אלמא דלא הוי שמיר' בבעלים והיינו מטעמא דפרישית וכן כ' בהגהות מיימוני פ\"ב מהלכות שאלה אמ\"ש הרמב\"ם אשה ששאלה ואח\"כ נישאת כו' אפי' פשע מפני שהוא כלוקח וז\"ל אבל ר\"י אומר דחייב בפשיעה כש\"ח ומשלם למשכיר לרבי יוסי דאמר תחזו' פרה לבעלים הראשוני' עכ\"ל ונרא' דגם הרמב\"ם סובר כן דלא הוי שמיר' בבעלי' אלא דס\"ל דאפי' ש\"ח לא הוי אלא לוקח ממש והיינו שכ' ואפי' פשע מפני שהוא כלוקח משמע משום דהוא כלוקח פטור אפי' פשע וכ\"כ הנ\"י וז\"ל דאגרה פרה כו' והדר נסבה כו' לוקח הוי ואין עליו חיוב כדין שומר כלל כו' וכן דעת הרמב\"ן דפטור לגמרי ואפי' מפשיע' וכן הראב\"ד כ' דלא מחייב ולא מידי לבעלים וכן דעת הרשב\"א והר\"ן שפטור אפי' מפשיעה אע\"פ שלא אמרו כן בתוס' עכ\"ל. וא\"כ דברי מור\"ם בהג\"ה ברורים בזה כמ\"ש אבל לא מפטר מטעם דהוי שמירה בבעלים כו' רק שלפ\"ז צ\"ל דס\"ל להרמב\"ם וסייעתו דכיון דהוי לוקח א\"כ אפי' ש\"ח לא הוי והיאך סתם לקמן סי\"ח כהמחבר דלוקח בהמ' לל' יום הוי ש\"ח והלא בתוס' מבואר דלמדו כן מדברי ר\"י דס\"ל בשאל' ונישאת הוי ש\"ח וצ\"ל דס\"ל למור\"ם דגם הרמב\"ם מודה בזה ולא קאמר הרמב\"ם אלא בבעל בנכסי אשתו דהוי לוקח גמור כל ימיה דאשה וגם דהא כשתמו' הרי הם שלו לגמרי למפרע א\"כ הוי כלוקח גמור משא\"כ בלוקח לל' יום ודוק:","\u0003 בבעל החפץ עצמו כו' \u0004 ע\"ל סי' רצ\"א בסמ\"ע ס\"ק מ\"ח וע' ביש\"ש פ\"י דב\"ק סי' מ':","\u0003 ואם הודיע כו' \u0004 ואם שאל אבן טוב לרפואה ונגנב פטור הבעל אך אם שאל לה בגד על החתונה לפי כבוד' ועשרה מסתמא ניחא לבעל וחייב אפי' באונסי' אבל לא בגד חשוב מערכה אם לא שנושאת ונותנת בתוך הבית מהרש\"ל ב\"ק פ\"ח סי' ל\"א וע\"ש:"]],["שָׁאַל פָּרָה בִּסְתָם, וְהִזִּיק שׁוֹרוֹ שֶׁל שׁוֹאֵל \u0010y0\u0011 לְשׁוֹרוֹ שֶׁל מַשְׁאִיל, אֲפִלּוּ אִם הוּא תָּם, מְשַׁלֵּם נֶזֶק שָׁלֵם, שֶׁאֲפִלּוּ אִם הֻזַּק מִשּׁוֹר דְּעָלְמָא צָרִיךְ לְשַׁלֵּם, דְּמִסְתָמָא צָרִיךְ לְשָׁמְרוֹ שֶׁלֹּא יֻזַּק וְשֶׁלֹּא יַזִּיק. וְאִם קִבֵּל עָלָיו שְׁמִירָתוֹ שֶׁלֹּא יַזִּיק, \u0010y1\u0011 אֲבָל לֹא שֶׁלֹּא \u0010y2\u0011 יֻזַּק, וְהִזִּיקוֹ שׁוֹרוֹ שֶׁל שׁוֹאֵל, תָּם מְשַׁלֵּם חֲצִי נֶזֶק, וּמוּעָד נֶזֶק שָׁלֵם. וְאִי אַזְקֵהּ תּוֹרָא דְּמַשְׁאִיל לְתוֹרָא דְשׁוֹאֵל, וְהַשְּׁאִילָה הָיְתָה בִּסְתָם, בֵּין תָּם בֵּין מוּעָד פָּטוּר. \u0010y3\u0011 וְאִי אַזִּיק לְתוֹרָא דְּעָלְמָא, שׁוֹאֵל בָּעֵי לִשְׁלוּמֵי, שֶׁעָלָיו מֻטָּל לְשָׁמְרוֹ שֶׁלֹּא יַזִּיק. וְאִם קִבֵּל עָלָיו לְשָׁמְרוֹ שֶׁלֹּא \u0010y4\u0011 יֻזָּק אֲבָל לֹא שֶׁלֹּא יַזִּיק, וְהִזִּיק לְשׁוֹרוֹ שֶׁל שׁוֹאֵל, מְשַׁלֵּם לוֹ הַמַּשְׁאִיל, תָּם חֲצִי נֶזֶק, וּמוּעָד נֶזֶק שָׁלֵם:",["\u0003לשורו של משאיל \u0004 פי' שור זה שהשאיל מהמשאיל ניזק משורו של שואל שהוא שלו לחלוטין:","\u0003אבל לא שלא יוזק. \u0004 כן הוא נמי ל' הטור ובפריש' כתבתי דנרא' אפי' אם לא פי' דבריו מכיון דמסתמ' עליו לשומרו שלא יזיק ושלא יוזק והוא פרט וקבלו עליו שלא יזיק ה\"ל כאלו התנה ואמר שלא קבל עליו שלא יוזק וכן הוא משמעות ל' רש\"י בספ\"ק דב\"ק ומיהו לדינא נרא' דאף אם התנה בפירוש שלא ישמרנו שלא יוזק אפ\"ה צריך לשלם באם הזיקו שורו תם חצי נזק דה\"ל להשואל לשמור שורו שלא יזיק דלא גרע שורו של משאיל משור דעלמא וק\"ל:","\u0003ה\"ג והזיקו שור של שואל \u0004 ולא לשור:","\u0003ואי אזיק לתורא דעלמא שואל בעי לשלומי \u0004 נראה דמשלם כפי הדין שהיה המשאיל צריך לשלם דהיינו תם ח\"נ ומועד נ\"ש דהא לא קיבל עליו אלא להיות במקום המשאיל ולהיו' חיובו עליו:","\u0003אבל לא שלא יזיק כו' \u0004 ה\"נ פירושו כמ\"ש לעיל דכל שפרט ואמר שלא יוזק לחוד ה\"ל כאלו פי' ואמר אבל לא שלא יזיק ועפ\"ר:"],[]],["\u0003הלכות גניבה\u0004\n\u0010y0\u0011 \u0010c0\u0011 אָסוּר לִגְנֹב, אֲפִלּוּ כָּל שֶׁהוּא, דִּין תּוֹרָה. וְאָסוּר לִגְנֹב אֲפִלּוּ דֶּרֶךְ שְׂחוֹק, \u0010y1\u0011 וַאֲפִלּוּ עַל מְנַת לְהַחֲזִיר אוֹ כְּדֵי \u0010y2\u0011 לְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל אוֹ כְּדֵי לְצַעֲרוֹ, הַכֹּל אָסוּר, כְּדֵי שֶׁלֹּא יַרְגִּיל עַצְמוֹ בְּכָךְ.\nכָּל הַגּוֹנֵב אֲפִלּוּ שְׁוֵה פְרוּטָה עוֹבֵר \u0010y3\u0011 עַל לָאו דְּלֹא תִגְנֹבוּ \u0005(וַיִּקְרָא יט, יא)\u0006 וְחַיָּב לְשַׁלֵּם, אֶחָד הַגּוֹנֵב מָמוֹן יִשְׂרָאֵל \u0010y4\u0011 \u0010c1\u0011 אוֹ הַגּוֹנֵב מָמוֹן שֶׁל גּוֹיִים, וְאֶחָד הַגּוֹנֵב מִגָּדוֹל אוֹ מִקָּטָן. \u0005הַגָּה: טָעוּת גּוֹי, כְּגוֹן לְהַטְעוֹתוֹ בְּחֶשְׁבּוֹן אוֹ לְהַפְקִיעַ הַלְוָאָתוֹ, מֻתָּר, וּבִלְבַד שֶׁלֹּא יִוָּדַע לוֹ, דְּלֵיכָּא חִלּוּל הַשֵּׁם (טוּר ס\"ג)\u0006. \u0010y5\u0011 \u0010c2\u0011 וְיֵשׁ אוֹמְרִים דְּאָסוּר לְהַטְעוֹתוֹ, אֶלָּא אִם טָעָה מֵעַצְמוֹ, שָׁרִי. \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006.\nאֵיזֶהוּ גַּנָּב, הַלּוֹקֵחַ מָמוֹן אָדָם בְּסֵתֶר \u0010y6\u0011 וְאֵין הַבְּעָלִים יוֹדְעִים. אֲבָל אִם לָקַח בְּגָלוּי וּבְפַרְהֶסְיָא, אֵין זֶה גַּנָּב, אֶלָּא גַּזְלָן.\nמִשָּׁעָה שֶׁמָּשַׁךְ הַגְּנֵבָה נַעֲשָׂה עָלֶיהָ גַּנָּב. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁמְּשָׁכָהּ \u0010y7\u0011 חוּץ מֵרְשׁוּת הַבְּעָלִים, אֲבָל כָּל זְמַן שֶׁהִיא בִּרְשׁוּת הַבְּעָלִים אֵינוֹ חַיָּב עַד שֶׁיַּגְבִּיהֶנָּה. וְאִם הִכְנִיסָהּ לִרְשׁוּתוֹ, \u0010y8\u0011 אֲפִלּוּ לְגַגּוֹ חֲצֵרוֹ וְקַרְפֵּיפוֹ, אִם הִיא מִשְׁתַּמֶּרֶת, חַיָּב, אַף עַל פִּי שֶׁלֹּא מָשַׁךְ וְלֹא הִגְבִּיהַ. \u0005הַגָּה: \u0010y9\u0011 אֵימָתַי גַּנָּב חַיָּב בְּכֶפֶל וְאַרְבַּע וַחֲמִשָּׁה, עַיֵּן בִּפְנִים; וְלֹא כְּתָבָן הַמְחַבֵּר הַזֶּה, לְפִי שֶׁהוּא קְנָס וְאֵינוֹ נוֹהֵג \u0010y10\u0011 \u0010c3\u0011 הָאִדָּנָא. מִיהוּ, יֵשׁ נַפְקוּתָא אִם תָּפַס, וְעַיֵּן לְעֵיל סִימָן א' ס\"ה:\u0006\nתַּשְׁלוּמֵי \u0010y11\u0011 גְּנֵבָה, אִם יֵשׁ לוֹ מִטַּלְטְלִים יוֹרְדִים לָהֶם; וְאִם אֵין לוֹ מִטַּלְטְלִין אֶלָּא קַרְקָעוֹת, יוֹרְדִים לָהֶם \u0010y12\u0011 וְגוֹבִין מֵהָעִדִּית שֶׁלּוֹ, כִּשְׁאָר נְזִיקִין.\nמִי שֶׁגָּנַב \u0010y13\u0011 וְהִגְבִּיהַּ הַגְּנֵבָה, וּבָא אַחֵר וְסִיַּע לְהוֹלִיכָהּ מִשָּׁם, פָּטוּר זֶה הַשֵּׁנִי.\nרְאוּבֵן שֶׁרָאָה שִׁמְעוֹן שֶׁנִּכְנָס לְבֵית לֵוִי \u0010y14\u0011 וְגָנַב חֵפֶץ אֶחָד, וּבָא אוֹתוֹ חֵפֶץ לְיַד רְאוּבֵן וְהֶחֱזִירוֹ \u0005לְשִׁמְעוֹן,\u0006 אֵין לֵוִי יָכוֹל לְהוֹצִיא מִמֶּנּוּ בַּדִּין. \u0005הַגָּה: \u0010y15\u0011 וְדַוְקָא שֶׁשִּׁמְעוֹן יֵשׁ לוֹ שׁוּם טַעֲנָה נֶגֶד לֵוִי, אֲבָל אִם אֵין לוֹ טַעֲנָה עֲלֵיהֶם רַק גְּנָבָם \u0010y16\u0011 וְזֶה יוֹדֵעַ רְאוּבֵן, אִם הֶחֱזִירָהּ לְשִׁמְעוֹן הַגַּנָּב, \u0010y17\u0011 חַיָּב לְשַׁלֵּם לְלֵוִי, דְּהָוֵי לֵהּ לְהָשִׁיב הָאֲבֵדָה לַבְּעָלִים (מָרְדְּכַי פֶּרֶק הַסְפִינָה, וְכֵן מַשְׁמָע מִתְּשׁוּבַת הָרֹא\"שׁ)\u0006.\nרְאוּבֵן תָּבַע לְשִׁמְעוֹן שֶׁנִּכְנָס לְחַדְרוֹ וְגָנַב סְפָרָיו וְהוֹצִיאָם מֵרְשׁוּתוֹ, וְהֵשִׁיב שִׁמְעוֹן: אֱמֶת הָיָה שֶׁהוֹצֵאתִים, אֲבָל כָּךְ הָיָה הַמַּעֲשֶׂה: שֶׁבִּקְּשָׁתָנִי קְרוֹבָתִי כַּלָּתְךָ לְהוֹצִיאָם כִּי לֹא יָכְלָה שְׂאֵתָם, וְלֹא יָדַעְתִּי שֶׁל מִי הָיוּ, וְגַם לֹא הִגְבַּהְתִּים אַךְ הִיא הִגְבִּיהָתָם וּנְתַנְתָּם לִי; \u0010y18\u0011 שִׁמְעוֹן חַיָּב לְהַחֲזִירָם, כִּי מַה לּוֹ לִכָּנֵס לְחַדְרוֹ לְהוֹצִיא הַסְפָרִים, וְנִכָּר הַדָּבָר שֶׁכִּוֵּן לְסַיֵּעַ לִגְזֹל לְחָמִיהָ. וּמַה שֶּׁטּוֹעֵן שֶׁהִיא הִגְבִּיהָתָם וּנְתַנְתָּם לוֹ, מִכָּל מָקוֹם הֲרֵי טוֹעֵן שֶׁהָיוּ כְּבֵדִים וְלֹא יָכְלָה שְׂאֵתָם, וְכֵיוָן שֶׁלֹּא יָכְלָה לְהוֹצִיאָם מִשָּׁם אִם לֹא סִיְּעָהּ, הֲוָה לֵהּ כְּאִלּוּ הוֹצִיאָם הוּא, וְיִגְבֶּה רְאוּבֵן מִמִּי שֶׁיִּרְצֶה: מִכַּלָּתוֹ שֶׁהוֹדֵית לוֹ שֶׁהֵם בִּרְשׁוּתָהּ; וְאִם יִרְצֶה, יִגְבֶּה מִשִּׁמְעוֹן. \u0005הַגָּה: וְכֵן אִם הִטְמִין הַגַּנָּב הַגְּנֵבָה וְהֻצְרַךְ לָצֵאת מִן הָעִיר עַד שֶׁאֵינוֹ יָכוֹל לְהַבְרִיחַ הַגְּנֵבָה, וְשָׁלַח אַחַר כָּךְ אִישׁ אֶחָד לְהָבִיא לוֹ הַגְּנֵבָה, הַשָּׁלִיחַ חַיָּב לְשַׁלֵּם, דְּהוּא עִקַּר הַגַּנָּב, מֵאַחַר שֶׁיָּדַע שֶׁהוּא גְּנֵבָה (מָרְדְּכַי פֶּרֶק הַסְפִינָה)\u0006 \u0010c4\u0011 הַמַּרְאֶה לַחֲבֵרוֹ לִגְנֹב אוֹ שָׁלְחוֹ לִגְנֹב, אֵין הַמְשַׁלֵּחַ חַיָּב \u0005(תְּרוּמַת הַדֶּשֶׁן סִימָן שט\"ו)\u0006, דְּאֵין שָׁלִיחַ לִדְבַר עֲבֵרָה \u0005(ד\"ע)\u0006. מִיהוּ, אִם הַשָּׁלִיחַ אֵינוֹ בַּר חִיּוּבָא, \u0010y19\u0011 \u0010c5\u0011 \u0010c6\u0011 דְּהַמְשַׁלֵּחַ חַיָּב \u0005(מָרְדְּכַי פ\"ק דִּמְצִיעָא)\u0006. וְעַיֵּן בְּאֶבֶן הָעֵזֶר סִימָן פ\"ו בְּאִשָּׁה שֶׁמָּכְרָה אוֹ מִשְׁכְּנָהּ וְהַבַּעַל אוֹמֵר שֶׁגָּנְבָה מִמֶּנּוּ:",["\u0003אסור לגנוב אפי' כל שהוא דכמו שחצי שעורין לענין איסור חלב ודם אסור מן התור' אע\"ג דאין לוקין עליו כמבואר במקומו בי\"ד ובא\"ח מהלכות יוכ\"פ כן חצי שיעור לענין ממון ג\"כ אסור מן התורה אע\"ג דאין לוקין עליו:\u0004","\u0003ואפי' ע\"מ להחזיר \u0004 פי' ולא גנבו אלא למיקט ולצערו כן פי' ב\"י דברי הטור אבל המחבר דכ' אחר זה כדי לצערו צ\"ל דמ\"ש ע\"מ להחזיר ר\"ל שלקחו לצורכו ולהחזיר' בעינו אח\"כ.","\u0003לשלם תשלומי כפל \u0004 פירש\"י שרוצה לההנותו ויודע בו שלא יקבלנו ממנו:","\u0003על לאו דלא תגנובו \u0004 פי' לא תגנובו הכ' בפ' קדושים דמיירי בגניבת ממון דנלמד מעניינו דכ' בצדו לא תכחשו ולא תשקרו אבל לא תגנוב הכתוב בעשרת הדברות איירי בגונב נפשות דחייב עליה מיתה נלמד ג\"כ מענינו דכ' בצדו לא תרצח לא תנאף.","\u0003או הגונב ממון של עכו\"ם \u0004 דומיא דגזל העכו\"ם דאסור:","\u0003וי\"א דאסור להטעותו ולמדו זה מדאסרו אפי' גניבת דעת עכו\"ם:\u0004","\u0003ואין הבעלי' יודעי' \u0004 ואפי' יודעי' מזה כיון שהגנב מטמין עצמו כדי שלא יראהו נקרא גנב כ\"כ הטו' ולאפוקי הבא לגזול מיד הבעלים דנקרא גזלן כמו שכ' בבניהו ויגזול את החנית מידו ונ\"מ דאין הגזלן חייב בכפל ולא בד' וה' אם טבח ומכר:","\u0003חוץ מרשות הבעלים מיירי דמשכה במקום שקונה משיכה דהיינו בסימטא ובחצר שהיא של שניהם וכ\"ש כשמשכה לרשותו וכמ\"ש לעיל סי' קנ\"ז:\u0004","\u0003אפי' לגגו חצירו כו' דנפקא לן בגמ' מכפל המצא תמצא בידו:\u0004","\u0003אימת חייב הגנב בכפל כו' \u0004 עיין בטור שכ' ז\"ל בד\"א שחייב בכפל ד' וה' שבאו עדים שגנב וטבח ומכר אבל אם הודה מעצמו אינו משלם אלא הקרן דכתיב אשר ירשיעון אלהים פרט למרשיע את עצמו ואפי' מוד' בקנס ואח\"כ באו עדים פטור ולא אמרי' דלא הוד' אלא כדי לפטו' מהקנס דידע דיבואו עדים ובלבד שמתחייב עצמו בקרן כגון שהוד' שגנב וטבח ומכר שנמצא מחייב עצמו בהודאתו בקרן קודם שבאו העדים אבל אם לא אמר שגנב קודם שבאו העדי' ולאחר שבאו עדים שגנב הקדים נפשו והודה שטבח ומכר ואח\"כ באו עדים ומעידים עליו שטבח ומכר חייב ד' וה' ואין מוד' בקנס פטור אא\"כ הודה בפני ב\"ד של ג' מומחין וכשהן יושבין במקום ב\"ד אבל אם הודה בפני ב' מומחין אפי' כשהן יושבין בב\"ד או בפני ג' חוץ לב\"ד אינו מועיל להפטר מהקנס לפיכך האידנ' שאין לנו ב\"ד מומחין הראויין לדון דיני קנסו' אינו מועיל להפטר מהקנס עכ\"ל הטור עוד כ' הטור כמה כרטי דיני חיוב כפל ד' וה' בסי' ש\"ן ושנ\"א ושנ\"ב והשמיט' ג\"כ המחבר מה\"ט דאינן נוהגים:","\u0003מיהו יש נפקותא אם תפס כו' \u0004 זה כתב ג\"כ הטור בס\"ס שמ\"ט דמ\"ה כ' קצת פרטי דינים בסי' זה ובסי' ש\"ן ושנ\"א ושנ\"ב ואפשר דהמחבר פסק כהרמ\"ה שכ' הטור בשמו שם בס\"ס שמ\"ט שלא מהני תפיס' בקנסא לא בכדי נזקו ולא בכפל ד' וה' שהוא יתר מנזקו דתקנתא עבדי ליה רבנן לניזק ולא עבדי תקנתא להרויח על ממוניה כו' ומ\"ה השמיטן המחבר. ומור\"ם ז\"ל ס\"ל כהרא\"ש שהטור כ' שם עליו שהרא\"ש חלק על דבריו וס\"ל דלאו תקנתא היא דמדאורייתא מחייב ליה אלא שאין לנו דיין בבבל שיכפנו ליתן וכל כה\"ג עביד אינשן דינא לנפשיה לתפוס בשיעו' כפל ד' וה' ואין מוציאין מידו כו' ע\"ש וק\"ל:","\u0003אם יש לו מטלטלין כו' \u0004 דכל המטלטלין אפי' סובין משתלם מהן אפי' בניזקין אפי' יש לו כסף ומזומני' דכל מטלטלין מיקרי מיטב שבאם לא יוכל למכרן כאן יכול לטלטלן למקום אחר וכמו שכתבו הטור והמחב' לקמן סי' תי\"ט ושם נתבא' דשמין לו המטלטלין למוכרן לפי מקומו ושעתו וכמ\"ש הטור והמחב' ג\"כ לעיל סי' ק\"ג ע\"ש מ\"ש בפרישה וסמ\"ע:","\u0003וגובין מהעידית \u0004 כשאר נזיקין דכתיב בהו בפ' משפטים מיטב שדהו ומיטב כרמו ישלם והיינו דוקא כשאין לו להשתל' ממנו אלא קרקע וקרקע אינו יכול לטלטלה למכרה במקום אחר לכך הזקיקה התור' לשלם מן העידית שלו שיש עליה קופצים לקנותו או יחזיק הניזק לעצמו כמ\"ש ג\"כ בסי' תי\"ט ועיין בטור שסיים וכ' ז\"ל ואם אין לו לא מקרקעי ולא מטלטלים בזמן שהיובל נוהג דבר תורה מוכר את עצמו ומשלם לזה הקרן (פי' ולא הכפל דכתיב ונמכר בגניבתו ולא בכפלו וכמ\"ש בר\"ס ל\"ח) אבל בזמן הזה אינו נמכר שאין תורת עבד עברי נוהג אלא בזמן שהיובל נוהג עכ\"ל:","\u0003והגביה הגניבה. \u0004 פי' וע\"י הגבהה קנאה והגנב הי' יכול להוציא את הגניב' זולת זה המסייע ונמצא שהיתה גנובה ועומדת זולתו ומסיים הרא\"ש והטור הביאו בזה ז\"ל ובהא דאמרי' גזל ולא נתייאשו הבעלי' ובא אחר וגזלו רצה מזה גובה רצה מזה גובה היינו דוקא כשהשני גזלה מהראשון וכיון דלא נתייאשו הבעלים ה\"ל כאלו גזלו מהבעלים אבל היכא שלא בא לגזול אלא לסייע והוא כבר קנאתה בהגבהה לא. עוד כ' טעם אחר לפטור כשלא ידע שהוא גניבה ע\"ש:","\u0003וגנב חפץ אחד כו' \u0004 אע\"פ שכ' עליה מור\"ם דאיירי דיש לו טענה על מה שלקחה מ\"מ כ' ל' וגנב כיון שאין ידוע לראובן שטענתו אמת וחזקה הוא שכל מה שהוא בבית האדם הוא שלו וגם הוא הלך שם בחשאי:","\u0003ודוקא ששמעון יש לו שום טענה כו' \u0004 ומסיי' בזה הרא\"ש והטור וכ' ז\"ל ובכהא אינו חייב משום שומר אבידה להחזירו ליד בעלים כיון ששמעון אומר שיש לו תביעה עליו ואם יחזירו ראובן ללוי ויתפוס שמעון אח\"כ משל ראובן לא היה מחזירו לו ואין ראובן חייב להציל ממון לוי בממונו עכ\"ל:","\u0003וזה יודע ראובן \u0004 פי' יודע שאין לו טענה עליו:","\u0003חייב לשלם ללוי \u0004 ואע\"פ ששמעון כבר הגביה להגניבה והוציאה וקנאה בהגבהה ובסעיף שלפני זה פטר לשמעון מה\"ט היינו דוקא שפטרו ממה שסייע בהוצאתו ואחר שהוציא להגניב' בא הגנב ונטלו מידו משא\"כ בזה שמיירי ששמעון מעצמו החזיר ליד ראובן הגניבה והיה יכול להחזיקו בידו ולהחזיר ליד הבעלים מ\"ה חייב מדין שומר אבידה וק\"ל:","\u0003שמעון חייב להחזיר לו כי מה לו ליכנס כו'. \u0004 פי' מ\"ה אף אם יש לו שום טענה לקרובתו למה גנבו מ\"מ כיון שהוא אינו יודע אם האמת אתה לא היה לו לכנס לבית חבירו ולסייע לה להוציאו ואף שלא היו שם עדים על ההוצאה וכדמשמע מל' תשובת שמעון שכ' הטור והמחבר ז\"ל והשיב שמעון אמת הוא שהוצאתי כו' דמדקאמר אמת משמע שזולת הודאתו לא היה ראובן יכול לברר הדבר בעדים אבל בדין שלפני זה מיירי שלא נכנס שמעון לסייע על הגניבה אלא שתבעו ראובן על שבא לידו והחזירו ליד הגנב ואף שבטור משמע שהמעשה היה שנכנס ג\"כ וסייעו להוציאו הא כ' שם טעמים אחרים לפטרו על ההוצאה והוא כיון שהגנב כבר הגביהו והי' יכול להוציאו לבדו ועוד שם טען שמעון שידע שהאמת אתו ע\"ש ודו\"ק:","\u0003י\"א דהמשלח חייב דאין שייך לו' כאן דסבר המשלח דלא יעשה השליח מה שבקש ממנו מטעם דדברי הרב ודברי התלמיד דברי מי שומעין כיון דאינו בר חיוב ☜ ובד\"מ הביא דברי המרדכי פ\"ק דב\"מ דכ' בשם מוהר\"ם ז\"ל ואם אמר קח לי שור בבית פלוני שהוא שלי ונמצא אח\"כ שלא היה שלו אלא לגנבו נתכוון חייב המשלח באחריות השור במשיכת השליח דהא השליח לא ידע שהוא גניבה ושהנ\"י כ' בפרק מרובה דהשליח חייב דאין שליח לדבר עבירה אפי' במקום שאין השליח יודע אם עשה איסור:\u0004"],["\u0003 אסור לגנוב כו'. \u0004 בש\"ס ריש ב\"ק משמע דגנב חייב לשלם מעידית כמזיק וכ\"כ הרי\"ף והרא\"ש והנמוקי יוסף וכן מהרש\"ל שם סי' ו' וע\"ש וכן הוא לקמן סי' שפ\"ה ושפ\"ח סעיף ב' ועמ\"ש לקמן סי' ת\"ך ס\"ג:","\u0003 או הגונב ממון של עכו\"ם. \u0004 משמע מכאן דאסור דאורייתא וכ\"כ מהרש\"ל פ' הגוזל דס\"ל להרמב\"ם וטור וסמ\"ג שכתבו בל' הזה דאסור מדאורייתא ע\"ש וקשה מכאן על מ\"ש הרב בהג\"ה בא\"ע ריש סי' כ\"ח קדש' בגזל או בגניבת עכו\"ם הוי מקודשת דהא אינה צריכה להחזיר רק משו' קידוש השם עכ\"ל ומה שהוציא הרב שם כן מתשובת מהרי\"ו סי' קל\"ח כשתעיין בתשוב' רי\"ו שם תראה שאינו כן וצ\"ע ועמש\"ל ר\"ס שנ\"ט:","\u0003 וי\"א דאסור להטעותו וכו' \u0004 ע' ביש\"ש פ\"י דב\"ק סי' ך' (הג\"ה שפסק שם סי\"א וכ' שם דמ\"מ יאמר לו ישראל ראה שעל חשבונך אני סומך וגם הפקע' הלוא' אינו מותר אלא כשחייב לשלם לו דרך מכס או דרך חוב אבל מה שהוא דרך מקח אסור עכ\"ל וע\"ש):","\u0003 מיהו יש נפקותא כו'. \u0004 עיין בסמ\"ע ס\"ק י\"א וע\"ל סי' א' ס\"ק י\"ח:","\u0003 המרא' לחבירו לגנוב או שלחו כו'. \u0004 בכל הפוסקים ליתא אלא השולח את חברו לגנוב אבל לא הזכירו מהמראה לחברו לגנוב רק הרב ערבב שניהם יחד ואזל לטעמי' שכתב בד\"מ וז\"ל ובת\"ה סי' שט\"ו כתב ראובן הראה לגנב מפורסם מחתרת של לוי לגנוב מתוכו ראובן פטור דהוי גרמא בניזקין כו' וצ\"ע דהא בלא\"ה פטור משום דאין שלד\"ע עכ\"ל ולמ\"ש הרב לעיל ר\"ס קפ\"ה דהיכא דאין השליח בר חיובא יש שלד\"ע וכ\"כ כאן בשם י\"א פשיטא דלק\"מ דאשמועי' הת\"ה הכא דאפי' היכא דאין השליח בר חיובא פטור המראה משום גרמא ואפי' למה שהעליתי שם דאפי' היכא שאין השליח ב\"ח אין שלד\"ע נמי לק\"מ דאשמועינן דסד\"א דאע\"ג דאין שלד\"ע חייב וכדאמרי' במאן דמראה ממון חברו לעכו\"ם חייב כדלקמן סי' שפ\"ח דלאו משום שליחות מחייבינן ליה דהא אינו שלוחו אלא אע\"ג דלאו שלוחו הוא חייב מדיני דגרמי קמ\"ל דהכא לא הוי גרמי אלא גרמא וכן הוא להדיא הפלפול בכל התשובה בת\"ה לחלק דל\"ד לדלקמן סימן שפ\"ח ע\"ש וז\"ב עיין בתשובת מהר\"ם מלובלין סי' פ\"א דף נ' ע\"ג:","\u0003 י\"א דהמשלח כו' \u0004 לא ידענא למה כ' בל' י\"א דהא לא הביא בד\"מ מי שחולק ע\"ז גם לעיל ר\"ס קפ\"ב כ' הרב\"י כן בפשיטות מיהו כבר כתבתי שם דמה שהוציא הר\"ב כן מהגהת מיי' ומרדכי אינו מוכרח והעלתי שם לדינא דאין חילוק בין השליח בר חיובא או לא ולעולם אין שלד\"ע רק גבי חצר ע\"ש: כתב בד\"מ וסמ\"ע שהמרדכי פ\"ק דמציעא כ' בשם מהר\"מ ז\"ל (עמש\"ל דלא כתב כן בשם מוהר\"מ ז\"ל והד\"מ סימן ע\"ה טעה במרדכי ע\"ש) אם אמר קח לי שור בבית פלוני שהוא שלי ונמצא אח\"כ שלא היה שלו אלא לגנבו נתכוין חייב המשלח באחריות השור במשיכ' השליח דהא השליח לא ידע שהוא גנבה והנ\"י כתב בפ' מרובה דהשליח חייב דאין שלד\"ע אפי' במקום שאין השליח יודע אם עשה איסור עכ\"ל ומ\"ש בשם הנ\"י דהשליח חייב ליתא דלא כתב הנ\"י שם רק דמ\"מ המשלח פטור אבל שיהא השליח חייב אין לזה טעם כלל וכן מבואר להדיא ביש\"ש פרק מרובה סי' ל\"ג דלכ\"ע השליח פטור בשלא ידע ע\"ש:","ומהרש\"ל שם השיג על הנ\"י והטיח דברים כנגדו ופסק כהמרדכי ולפע\"ד שלא כדת השיג עליו ונר' עיקר כדעת נ\"י דמ\"ש התוס' פרק מרובה ואחריהם נמשך מהרש\"ל שם דכיון דלא ידע הוי כמו חצר דבין למ\"ד דהיכא דלאו בר חיובא הוא חייב ובין למ\"ד דבע\"כ מותיב לה חייב אינו נראה חדא דלישנא דלאו בר חיובא משמע דגבר' לאו בר חיובא הוא והכא הא גברא בר חיובא הוא וכן לישנא דאי בעי עביד אי בעי לא עביד משמע שהשליח בידו לעשות או לא וה\"נ ביד השליח לעשות או לא דאל\"כ הכי הל\"ל כי אמרי' אין שלד\"ע במזיד אבל שוגג לא ועוד דע\"כ מה שהוציאו כן מהמשנה דפ' מרובה כפי פי' רש\"י לפע\"ד אין פי' המשנ' כן דא\"כ ל\"ל לתלמוד' להקשו' בפ\"ק דמציעא אריש לקיש דאמר חצר משום שליחות אתרבאי משמע דלר' יוחנן לק\"מ והא בלא\"ה תיקשי כן אמתני' דמרובה אפי' בלא ברייתא דהמצא תמצא בידו תקשי בפשיטות הא אין שלד\"ע וא\"כ כמו שמוכרח לתרץ המשנה כן יתורץ דברי ריש לקיש א\"ו אין הפי' במשנה דמרוב' דהמשלח חייב במשיכת השליח אלא כמו שפירשו שאר רוב המפרשים או כמ\"ש הנ\"י וא\"כ כיון שלא נזכר דין בזה במשנה ובשום מקום בש\"ס מנ\"ל לחייב המשלח וגם מה שמשמע מדברי מהרש\"ל שם שהראב\"ד מפרש המשנה כרש\"י ליתא דנהי דהראב\"ד לא מפרש כהרמב\"ם מ\"מ גם כרש\"י לא מפרש ע\"ש מבואר כך בדבריו להדי' במ\"ש ואף לאו בגנב אלא מילתא באפי' נפשי' קאמר ע\"ש ונראה דלהכי אינו מפרש המשנה בגנב משום דאין שלד\"ע וכמ\"ש הנ\"י גם מ\"ש מהרש\"ל דיואב מזיד הוי לא משמע כן מפשטא דקרא ומפשטא דש\"ס ומכ\"ש לפי מה דאמרי' בפ' האיש מקדש דמורד במלכות הוי א\"כ מה היה לו ליואב לעשות כיון שכ' לו דוד כן היה מוכרח לעשות כן לפי שהיה סבור שדוד הרגו כדין כי אולי היה מורד במלכות ומה שהמציא לו התחבולה להורגו ולא הרגו כפשוטו ע\"פ סנהדרין אולי היה לו לדוד איזה טעם כאשר באמת היה לו טעם שלא יחשדהו שהרגו בשביל אשתו גם מ\"ש מהרש\"ל שם דהלא למסקנא לפי שמאי הזקן באמת נענש דוד והוה כאלו הרגו בחרבו ולת\"ק דסבר דלא נענש היינו מטעם דמורד במלכות הוה כו' ונראה מדברי מהרש\"ל שם שזה עיקר סמיכתו שסמוך להשיג על הנ\"י והאריך שם לתמוה על הנ\"י ע\"ש ולפע\"ד אין זה כלום דהא אמרי' בהדי' התם בש\"ס טעמא דשמאי הזקן משום דס\"ל דבכל דוכתי יש שלד\"ע וא\"נ שאני התם דגלי רחמנא אותו הרגת בחרב בני עמון ואם איתא הא אפי' ס\"ל בכל דוכתי אין שלד\"ע ולא גלי לן הכא קרא מידי ניחא כיון דיואב היה שוגג ה\"ל כמו חצר ומכאן הוא עיקר הוכחת הנ\"י דאפי' שוגג אין שלד\"ע דכן מוכח להדי' בפשיטות וכמ\"ש והא דאיצטריך בש\"ס התם לת\"ק לטעמ' דמורד במלכות הוה לאו למימר' דאי לאו הוה מורד במלכות הוי חייב לת\"ק דהא משמע התם בש\"ס להדיא דס\"ל לת\"ק בכל דוכתא אין שלד\"ע אלא משום דאל\"כ הוי חייב בדיני שמים וכדקאמר בש\"ס התם מכלל שת\"ק סבר אפי' בדיני שמים נמי פטור בתמיה אלא דינא רבה ודינא זוטא איכא בינייהו והשתא א\"ש לישנא דאי אתה נענש עליו ומשמע בדיני שמים דאל\"כ הל\"ל אי אתה חייב עליו א\"ו פשיטא דלא בא הנביא לו' לדוד אי אתה חייב כו' מיתה על אוריה החתי דפשיט' דאינו חייב מיתה בלא\"ה שהרי לא היו עדים והתראה על הריגת אוריה ועוד אפי' חייב מיתה מי ידין את דוד המלך במיתה אלא נתן הנביא בא לו' שאין אתה נענש עליו אף בידי שמים ולהכי הוצרך לישנ' דמורד במלכות דאל\"ה אף דאין שלד\"ע הי' נענש בי\"ש והשת' עלו דברי נ\"י כהוגן דמוכח להדי' בפ' האיש מקדש דאפי' השליח שוגג אין שלד\"ע ובר מן דין יש כמה ראיות להנ\"י חדא שהרי התו' עצמם שם הקשו ע\"ז וז\"ל אבל ק\"ק היכ' יליף מה מכירה ע\"י אחר אף טביחה ע\"י אחר דילמ' דוק' כסבור שהוא שלו כיון דליכ' יתיר עכ\"ל ומה שתירץ מהרש\"ל שם דמאח' דמדמי טביח' למכיר' א\"כ נימא מה מכיר' ע\"י אחר אף טביחה ע\"י אחר אף שידוע שגנוב לאו מילת' היא דהא גם התו' הרגישו בזה וע\"כ כתבו כיון דליכ' יתור כלו' דאי הוי שום יתור הוי אמרי' דאתי להיקש ואין היקש למחצה אבל השת' דליכ' יתור אלא דאמרי' דומי' דמכיר' וכמ\"ש רש\"י אין מכיר' אלא בשנים מוכר ולוקח א\"כ ה\"נ נימא דבטביח' מיירי בשנים ומ\"מ מיירי בגוני דמחייב בעלמ' דהיינו כשלא ידע ובר מן דין ג\"כ ק' דמאי פריך וכי זה חוטא וזה מתחייב ומ\"ש התו' ומהרש\"ל דהאמת משני הוא דוחק דמ\"מ קשה על המקש' מאי פריך דגם בש\"ס פ' האיש מקדש (קידושין דף מ\"ב ע\"ב) במאי דפריך התם ממעיל' נימא אין שלד\"ע נראה כן עיקר דהא אין מעילה אלא בשוגג וכמ\"ש התוס' שם ומ\"ש התוס' שם דהתם מיירי אפי' בנזכר השליח קשה מ\"מ מנ\"ל למקשה להוכיח דילמ' בנזכרו שניהם לא חייב שום אחד מהן השליח פטור משום דה\"ל מזיד והבע\"ה פטור משום אין שלד\"ע ומ\"ש התוס' דמוכח מבריית' אחרת קשה דה\"ל להמקש' להבי' לאות' בריית' ואמאי הביא המתני' דמעילה הא ממתני' לא מוכח מידי רק מבריית' ואותה בריית' לא הביא כלל וגם מ\"ש מהרש\"ל שם דהאמת משני הוא דוחק דמ\"מ קשה מאי פריך המקשה ועוד לפי' התוס' שם רישא דלא עשה שליח שליחותו שליח מעל מוכרח דמיירי בלא נזכר שליח וסיפ' דעשה שליחותו בע\"הב מעל מיירי לפי' התוס' אף בנזכר שליח וא\"כ לא הוי ריש' דומי' דסיפ' וא\"כ מנ\"ל למקשה להוכיח הא טפי מסתבר לו' דסיפא מיירי דומי' דריש' בלא נזכר השליח דוק' ואם קושייתו מכח הבריית' ה\"ל להבי' הבריית' ועוד נלפע\"ד דהאי דיוק' דדייק' התוס' מהבריית' מדקתני נזכרו שניהם משמע הא נזכר שליח לבד בעה\"ב מעל איכ' למידחי דאה\"נ דבעה\"ב לא מעל והא דלא תנא נזכר שליח לבד חנוני מעל היינו משום דעיקר דינ' אתא לאשמועינן דאותו שנזכר לא מעל משום דאין מעילה במזיד ושאע\"פ שאותו שנזכר לא מעל חברו שלא נזכר מעל ולהכי לא תני לה משום דאם נזכר השליח לבד הא דלא מעל בעה\"ב הוא משום דאין שלד\"ע ולא משום דאין מעילה במזיד ובהא לא מיירי התנא וא\"כ קשה מנ\"ל להמקשה ולתוספת להוכיח מהך בריית' דילמ' אין ה\"נ דאין שלד\"ע ובריית' דין מעיל' אתי לאשמועינן ובפרט דהך בריית' שנוייה בתוספת' דמשמע התם כמו שפירשתי דהכי איתא התם בתוספת' דמעילה פ' שני נזכר בעה\"ב שהוא של הקדש ולא נזכר השליח שליח מעל נזכרו שניהן שניהם לא מעלו וחנוני מעל כשיוציא נזכרו שלשתן שלשתן לא מעלו והמקח תפוס להקדש כו' ע\"כ אלמא דבריית' לא אתי לאשמועינן אלא דין דנזכר דאין מעילה במזיד וא\"ל דה\"ט דאין שלד\"ע הוא משום דברי הרב ודברי התלמיד דברי מי שומעין וכדאית' בקידושין שם וכשהשליח שוגג לא שייך ה\"ט מ\"מ שייך האי טעמא כיון דלא היה השליח מחויב בדבר לעשות היה לו לחוש שמא יש עבירה בדבר ודברי הרב ודברי התלמיד דברי מי שומעין ועי\"ל דהא דאמרי' בש\"ס טעמ' דאין שלד\"ע משום דברי הרב ודברי התלמיד דברי מי שומעין היינו מעיקר' דס\"ד דמסברא קי\"ל אין שלד\"ע אבל לבתר דמסיק משום דהוי מעיל' ושליחות יד או טביחה ב' כתובים הבאים כא' ואין מלמדין וא\"כ אפי' בלא טעמא דדברי הרב כו' שפיר ילפי' מדאיצטריך רחמנא למיכתב ב' כתובים דיש שלד\"ע ש\"מ דבעלמ' אין שלד\"ע וגזירת הכתו' הוא וכה\"ג איתא טובא בתלמוד דב' כתובי' הבאים כא' אין מלמדין אפי' ליכא טעמ' בהכי בעלמ' ודוק (הג\"ה ובריטב\"א בקידושין כ' נמי דהאי טעמ' דדברי הרב כו' ל\"ד רק שעל הרוב הוא שייך כו' וע\"ש) הלכך עיקר כהנ\"י וגם כי הנ\"י לא מעצמו אמר כן שהרי כ' שכ\"כ האחרוני' ונאמן הוא בכך שכן דעת האחרונים שוב מצאתי בחידושי הריטב\"א פ\"ק דמציעא כ' ג\"כ וז\"ל וקי\"ל דאין שלד\"ע וקשה מכאן למה שפירש\"י בפ' מרובה דהגנב חייב במשיכתו ואמאי והא אין שלד\"ע ואפי' כשהשליח שוגג כדמשמע הכא ובמסכ' קידושין בפ' הא\"מ להדיא ואנו אין לנו כפירש\"י אלא שם בפ' מרוב' פירשתי בע\"א עכ\"ל הרי להדיא כדעת הנ\"י ואע\"פ שהאגודה פ\"ק דמציעא והגהות מיימוני רפ\"ב דשלוחין כתבו דברי ר\"י מ\"מ העיקר כהנ\"י וריטב\"א וכן משמע דעת בעל תי\"ט פרק מרובה ע\"ש ועיין בתשוב' ן' לב ס\"ג סוף סי' ל\"ח דף ל\"ז ע\"ד ומה שהקשה שם לק\"מ ע\"ש מיהו לענין דינא גם מהר\"י ן' לב שם גופא כתב וז\"ל הא קמן בהדיא דאיכא דס\"ל דאפי' ידעי' בודאי שהשליח לא ידע שהוא שלד\"ע אפ\"ה פטור המשלח כיון דאי בעי עביד אי בעי לא עביד וכמו שנראה ממ\"ש הנ\"י בשם האחרונים שנחלקו על פי' רש\"י והתוס' כו' עכ\"ל שוב מצאתי בתשו' ר\"י טראני בסי' קי\"ו האריך ג\"כ להקשות על דברי הנ\"י בשם האחרונים ולפע\"ד לק\"מ וכמ\"ש גם לענין דינא מסיק שם סוף סוף האחרונים אמרו וידעו מאיזה טעם אמרו ע\"ש אחר שכתבתי כל זה הקר' יי' לפני חדושי ריטב\"א ממסכת קידושין וראיתי שם שכ' ג\"כ כדברי הנ\"י להדיא באריכות ע\"ש וכ\"כ התוס' רי\"ד בקידושין דאפי' בשוגג אין שליח לדבר עבירה ודלא כהתוספת שם ע\"ש בריב\"ש סי' ר\"ס:"]],["\u0010y0\u0011 אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה שֶׁגָּנְבוּ חַיָּבִים לְשַׁלֵּם, \u0010y1\u0011 אֶלָּא שֶׁאֵשֶׁת אִישׁ שֶׁגָּנְבָה אִם אֵין הַקֶּרֶן בְּעַיִן אוֹ חִלּוּפָיו, אֵין לָהּ מִמַּה לְשַׁלֵּם \u0010y2\u0011 עַד שֶׁתִּתְאַלְמֵן אוֹ תִּתְגָּרֵשׁ.\nאֵשֶׁת רְאוּבֵן הִשְׁאִילָה לְאֵשֶׁת שִׁמְעוֹן חֲפָצִים, וְיָצָא קוֹל בָּעִיר שֶׁנִּגְנְבוּ, אִם שִׁמְעוֹן מוֹדֶה שֶׁהַחֲפָצִים בָּאוּ לִרְשׁוּתוֹ וְאֵינוֹ יוֹדֵע מַה נַּעֲשָׂה בָּהֶם, \u0010y3\u0011 צָרִיךְ לִשָּׁבַע שֶׁאֵינָם בִּרְשׁוּתוֹ \u0010y4\u0011 וְשֶׁלֹּא שָׁלַח בָּהֶם יַד, \u0010c0\u0011 וְגַם הָאִשָּׁה תִּשָּׁבַע שֶׁאֵינָם בִּרְשׁוּתָהּ, וְיִכְתְּבוּ עָלֶיהָ פְּסַק דִּין שֶׁחַיֶּבֶת לְשַׁלֵּם לָהּ הַחֲפָצִים לִכְשֶׁתִּתְאַלְמֵן אוֹ תִתְגָּרֵשׁ \u0005(וְע\"ל ס\"ס צ\"ז)\u0006. \u0010y5\u0011\nקָטָן שֶׁגָּנַב, \u0010y6\u0011 מַחֲזִירִין קֶרֶן לַבְּעָלִים אִם הוּא בְּעַיִן; וְאִם אֵינוֹ בְּעַיִן, פָּטוּר אַף \u0010c1\u0011 לְאַחַר שֶׁיַּגְדִּיל: \u0010y7\u0011\nעֶבֶד שֶׁגָּנַב, מַחֲזִירִין קֶרֶן לַבְּעָלִים אִם הוּא בְּעַיִן; וְאִם אֵינוֹ בְּעַיִן, \u0010y8\u0011 אֵין בְּעָלָיו חַיָּב לְשַׁלֵּם. נִשְׁתַּחְרֵר הָעֶבֶד, חַיָּב לְשַׁלֵּם, אִם יֵשׁ לוֹ.\nרָאוּי לְבֵית דִּין לְהַכּוֹת הַקְּטַנִּים כְּפִי כֹחַ הַקָּטָן עַל הַגְּנֵבָה, כְּדֵי שֶׁלֹּא יִהְיוּ רְגִילִים בָּהּ. וְכֵן אִם הִזִּיקוּ שְׁאָר נְזָקִים. וְכֵן מַכִּים הָעֲבָדִים אִם הִזִּיקוּ, \u0010y9\u0011 מַכָּה רַבָּה, שֶׁלֹּא יִהְיוּ מְשֻׁלָּחִים לְהַזִּיק:",["\u0003א' האיש וא' האשה. \u0004 כלומר אע\"פ דכתיב בפ' משפטי' איש כי יגנוב שור או שה וטבחו או מכרו חמש' בקר ישלם תחת השור כו' איש ל\"ד קאמר דהושווה אשה לאיש לכל עונשין שבתורה ולא כתיב איש אלא למעוטי קטן וכדמסיק וה\"ה לכל דכוותי' דהיינו חרש שוטה:","\u0003אלא שאשת איש שגנבה כו' \u0004 נקט א\"א לאפוקי אלמנה וגרושה ובתול' גדול' דיש להן ממה לשלם מיד משא\"כ אשה שיש לה בעל דכל אשר לה הכניס' מסתמא לבעלה ובס\"ס שמ\"ו נתבא' דאם יש להנכסי מלוג חייב' למכור מיד בטוב' הנא' ולשל' הקרן ע\"ש בדריש' ובסי' תכ\"ד ס\"י:","\u0003עד שתתאלמן או תתגרש \u0004 פי' יקח פסק דין מיד עלי' שנתחייב' לשלם לו קרן וכפל מיד כשיהי' לה וכמ\"ש הטור והמחבר בסעיף שאחר זה ואף שכ' הטור כאן ז\"ל עד שתתאלמן או תתגרש ויתבענ' אינו ר\"ל שאז יתבענ' ויקח פסק דין עליה אלא ר\"ל אז יתבענ' להוצי' מידה בפסק דין שבידו מעכשיו ומ\"ה השמיט המחבר תיבת ויתבענה כדי שלא נטעה בו ולא כע\"ש שכ' תיב' ויתבענ' מה שהשמיט בעל הש\"ע בכוון והוסיף וגרע בזה:","\u0003צריך לישבע שאינם ברשותו. \u0004 אף שהוא טענת ספק ובטור ובתשו' הרא\"ש כ' בזה המעש' ז\"ל וגם חושדין לשמעון עצמו שיודע מה שנעש' בו ושמא עדיין הן ברשותו כו' ומשמע דבני העיר היו חושדין אותו לפי ראו' עיניהן ולפ\"ז י\"ל דמ\"ה השביעוהו אבל המחבר שלא העתיקו ודאי ס\"ל בלה\"נ משביעין אותו ונראה דה\"ט כיון שבא לרשותו ועכשיו אינן יש כאן ריעותא ומשביעין על טענת ספק כזה במקום ריעותא ככל שבועות שומרין שהן ספק ומטע' שכתבתי בסי' רצ\"ד כיון שודאי בא לידו ועכשיו אינו. ומה\"נ צריך לישבע שלא פשע בה אע\"ג דלא קיבלהו עליו שמיר'. ובאמר הנח לפני [לפניך] כ' הטור והמחבר בר\"ס רצ\"א דאפי' ש\"ח לא הוה שאני התם דאמר הנח לפני [לפניך] וגילה דעתו דלא יסמוך עליו משא\"כ כאן ועפ\"ר מ\"ש עוד מזה:","\u0003ושלא שלח בה יד. \u0004 בטור כ' גם שלא פשע בה שנגנב וכ\"כ מור\"ם לעיל בהג\"ה ס\"ס צ\"ו:","\u0003קטן שגנב כו' \u0004 ה\"ט כיון דאינו בר דעת וה\"ה חרש ושוט' ועל שלשתן אמרו שפגיעתן רעה וע' פרישה:","\u0003מחזירין הקרן כו' \u0004 ואין זה בכלל אין נזקקין לנכסי קטן כו' אם הוא מפורסם וידוע שהגניבה בא לידו וכמ\"ש בסי' ק\"י:","\u0003עבד שגנב כו' \u0004 דעבד ג\"כ אין לו ממון דמה שקנה עבד קנה רבו:","\u0003אין בעליו חייבין לשלם. \u0004 ז\"ל הטור אין בעליו חייבין לשלם ולא כל דבר שמזיק כיון שהוא בן דעת ובעלים אינן יכולין לשמרו שאם יקניטנו ילך וידליק גדישו של חבירו ונמצא מחייב רבו מנה בכל יום:","\u0003מכה רבה \u0004 דהיינו כפי כוחו דעבד כמו קטן ומשום דסתם עבד יכול לסבול מכה רבה מ\"ה נקט גבי' מכה רבה:"],["\u0003 וגם האשה תשבע כו'. \u0004 ע\"ל ס\"ס צ\"ו בזה:","\u0003 לאחר שיגדיל. \u0004 ע\"ל סימן צ\"ו ס\"ג:"]],["\u0010y0\u0011 \u0010c0\u0011 \u0010c1\u0011 גָּנַב חֶלְבּוֹ שֶׁל חֲבֵרוֹ וַאֲכָלוֹ, מְשַׁלֵּם לוֹ דְּמֵי חֶלְבּוֹ.",["\u0003גנב חלבו כו' עד דמי חלבו \u0004 ולא אמרי' דקים לי' בדרב' מיני' כיון דחייב מלקות וכרת אאכילת חלב יפטור ממנו כדין הגונב כיס בשבת וגררו לר\"ה דפטור מתשלומי ממון וכמ\"ש הטור והמחבר בר\"ס שאחר זה דלא דמי דהכא חיוב ממון בא מיד שהגביה החלב לגונבו וחיוב מלקות וכרת לא חל עליו אלא אח\"כ בשע' אכיל' ובב\"י כ' דאליב' דכ\"ע חייב ג\"כ בתשלומי כפל והמחבר לא כתבו כאן דלא איירי בדין כפל ד' וה' שאינן נוהגין בזמן הזה וכמ\"ש מור\"ם בסי' שמ\"ח בהג\"ה ס\"ד ועמ\"ש שם והנ' אעתיק קצת חידושי דינין שכ' הטור סי' זה. הא' אע\"ג דקי\"ל בעלמ' דאין שליח לדבר עביר' בדין זה אם גנב ואמר לשלוחו צא טבחו או מכרו המשלח חייב והטעם דטביח' דומיא דמכירה והמכירה א\"א אם לא ע\"י אחר דהיינו הלוקח והגנב חייב ה\"נ בטביח' ע\"י שליח וכמ\"ש הטור בס\"ד ע\"ש בפריש'. הב' אע\"ג דלענין איסור שבת לא קי\"ל כר' יוחנן הסנדלר דאמר המבשל בשבת בשוגג לא יאכל הוא אפי' במ\"ש אלא אחרים ובמזיד אפי' לאחרים ואפי' למ\"ש איסור עולמית אלא כר\"מ או כר' יודא דפליגי וכמ\"ש בא\"ח סי' שי' ח בכאן לענין טביחה ומכיר' קי\"ל כר' יוחנן הסנדלר ומחשבינן לי' לשחיט' שאינו ראוי' ופטור מיני' בד' וה' והטעם כתבתי בדרישה סי\"ח משום דזה תליא בפלוגתא דרבינא ורב אחא וקי\"ל בכל מקום שפליגי הלכה כדברי המיקל מהן ומ\"ה אזלינן בזה ובזה לקולא עד\"ר שהארכתי בזה. הג' דאע\"ג דק\"ל בזה כר\"י הסנדלר לפטרו מד' וה' בשחיטה שאינה ראויה מ\"מ בשחטה ונמצאת טריפה חייב בד' וה' וכמ\"ש הטור בסי\"ג והטעם כתבתי שם בפרישה משום דיש לחלק בין נמצא טרפ' אחר שחיטה דלא ידע מטריפות בשעת שחיטה והוה אז שחיטה ראוי' לבין שוחט בשבת ובין לנוחר ומעקר או עשאה נבילה דידע מנייהו בשע' שחיטה ע\"ש וע' בהגהתי לע\"ש שהשגתי עליו במ\"ש בסי' זה בג' ד' מקומות:"],["\u0003 גנב חלבו כו'. \u0004 עיין בסמ\"ע סק\"א עד דלא דמי דהכא חיוב ממון בא מיד שהגביה כו' וכן כתב הע\"ש ולא הוצרכו לזה דבש\"ס לא אמרינן הכי אלא לרבי נחוניא בן הקנה דס\"ל דחייבי כריתות פטור מתשלומין אבל לדידן דלא קי\"ל כרבי נחוניא הכא בלא\"ה חייב ומ\"מ נ\"מ מטעם זה אלו התרו בו דקי\"ל דאין לוקה ומשלם ואפי' הכי כאן משלם ולוקה דמשעת הגבהה חייב בכפל ומלקי לא לקי עד שעת אכילה וכה\"ג אמרינן לעיל סי' של\"ח ס\"ד ופשוט הוא ומ\"ש ע\"ש בסמ\"ע דקי\"ל כר\"י הסנדלר כו' מ\"מ בשחטה ונמצאת טרפה כו' באמת כן הוא בטור דכ' בתחלה סתם השוחט ונמצאת טרפה חייב ואח\"כ כתב בשוחט ע\"י אחר בשבת דלדעת הרא\"ש פטור משום שחיטה שאינה ראויה כר' יוחנן הסנדלר עכ\"ל ואחריו נמשך הע\"ש אבל תמוה הוא בעיני דהא אמרי' בש\"ס במרובה (דף ע\"א ע\"א וע\"ב) ופ' אלו נערות (כתובות דף ל\"ו) דמאן דפטר בטובח ע\"י אחר בשבת סבר לה כר' שמעון דאמר השוחט את הטרפה פטור ולא כרבנן דמתני' א\"כ אנן דקי\"ל כרבנן חייב והא דפסק הרא\"ש כר' יוחנן הסנדלר היינו לענין מבשל בשבת דאסור וה\"ה דהשוחט בשבת אסורה אבל מ\"מ לענין גניבה דלא מיירי רבי יוחנן הסנדלר קי\"ל כרבנן דמתני' ובאמת נראה שהטור לא עיין בש\"ס ול' הרא\"ש אטעייה שכ' הרא\"ש וז\"ל גנב ומכר בשבת דליכ' חיוב מיתה במכיר' פטור גנב וטבח ביה\"כ חייב בש\"ס פריך והקי\"ל דאינו לוקה ומשלם ומוקי לה בטובח ע\"י אחר וכי זה חוטא וזה מתחייב אמר רבא אמר קרא וטבחו או מכרו מה מכירה ע\"י אחר אף טביחה ע\"י אחר ואפ\"ה בשבת פטור דשחיטה שאינה ראויה היא כר\"י הסנדלר עכ\"ל והבין הטור דכוונת הרא\"ש לו' דמתני' מיירי בטובח ע\"י אחר וחייב ביה\"כ ופטור בשבת מטעם שחיטה שאינה ראויה וכ\"כ הטור בקצור פסקי הרא\"ש להדיא וז\"ל גנב וטבח ומכר בשבת היכא דליכ' חיוב מית' גנב וטבח ומכר ביה\"כ ע\"י אחר חייב עכ\"ל והא ודאי ליתא מכמה טעמים אלא הרא\"ש נקט ל' הש\"ס בקצרה וכן דרכו של הרא\"ש במס' ב\"ק לקצר ל' הש\"ס למי שבקי קצת בל' הרא\"ש דב\"ק ומ\"ש בטובח ע\"י אחר קאי אברייתא דמייתי בש\"ס התם ומ\"ש ואפ\"ה בשבת פטור ר\"ל דאע\"ג דבטובח ע\"י אחר חייב דיש שלד\"ע גבי טביח' מ\"מ בשבת פטור לחכמים דברייתא מטעם שחיטה שאינה ראויה כר' יוחנן הסנדלר ולא הוצרך הרא\"ש להביא כל זה אלא לאשמועי' דבטביחה יש שלד\"ע ולהביא אח\"כ שקלא וטרי' אי הלכ' כר\"י הסנדלר או לא שוב ראיתי במהרש\"ל פ' מרוב' סי' ך' הבין דברי הרא\"ש כפשוטו והאריך לתמו' עליו ובחנ' טרח דהדבר פשוט דכוונת הרא\"ש כמו שכתבתי וכמו שפי' מהרש\"ל שם דברי הרי\"ף כן יש לפ' דברי הרא\"ש וכה\"ג אשכחן טובא בהרא\"ש שמקצר ל' הש\"ס וראי' לדברי שהרי רי\"ו תלמיד הרא\"ש שנמשך תמיד אחר דברי הרא\"ש כ' בנתיב ל\"א ח\"ג וז\"ל גנב וטבח בשבת פטור ואם טבח ע\"י שליח חייב אבל גנב ביה\"כ וטבח ע\"י אחר או הוא בעצמו בלא התראה חייב דאין כאן מלקות דאם הי' שם מלקות אין לוקה ומשלם ולעולם במיתת ב\"ד אפי' הוא שוגג אינו משלם וכן גנב וטבח הוא בעצמו ביה\"כ והתרו בו פטור עכ\"ל וכן עיקר וכ\"פ מהרש\"ל:","כתב הרמב\"ם פ\"ג מהלכות גניבה וז\"ל גנב תרומה מבעלי' הישראלי' שהפרישוה אינו משלם תשלומי כפל שאין להם בה אלא טובת הנאה וטובת הנאה אינו ממון עכ\"ל והיינו כדאית' בסוגי' דס\"פ האיש מקדש דטובת הנאה אינה ממון דהכי סלקא שמעתת' התם וכ\"כ הרב המגיד שם וכ\"כ עוד הרמב\"ם פ\"ה מהלכות אישות דטובת הנאה אינה ממון וכתב ה\"ה שם דהיינו כיון דהכי סלקא שמעתתא דסוף פרק האיש מקדש וי\"ח ודעת רבינו נראה עיקר עכ\"ל והי\"ח הוא ר\"ח והביאוהו הרא\"ש והר\"ן ס\"פ האיש מקדש ומשמע שם ג\"כ שמסכימין לזה גם הרא\"ש מסיים על דברי ר\"ח וכן הלכה וכ\"כ הריטב\"א שם בשם ר\"ח והרמב\"ן ומשמע שם שגם הוא מסכים לזה וכן הביא הב\"י לעיל סי' ל\"ז מחו' י\"ד תשובת הריטב\"א ופסקו ר\"ח והרמב\"ן דטובת הנאה ממון כו' וטעם ר\"ח והרמב\"ן שם משום דרבא דהוא בתרא ס\"ל בס\"פ בתרא נדרים (דף פ\"ה ע\"א) דטובת הנאה ממון וכדקתני במתני' התם קונם כהנים ולוים אלו נהנים לי יטלו אחרים אבל הני לא ולפ\"ז היה קשה על הרמב\"ם שהרי גם הוא פסק בפ\"ז מהלכות נדרים דין י\"א כמתני' דנדרים אבל אחרי העיון נראה דעת הרמב\"ם עיקר חדא דאפי' תימא דרבא ס\"ל הכי מ\"מ כיון דסתמא דש\"ס סלקא בהכי בס\"פ האיש מקדש דכ\"ע טובת הנאה אינה ממון א\"כ נקטינן כסתמא דש\"ס דאינהו בתראי טפי מרבא ובע\"כ צ\"ל דס\"ל לש\"ס דס\"פ האיש מקדש דש\"ה בנדרים וכמ\"ש לקמן דאל\"כ תיקשי על סתמא דש\"ס דס\"פ האיש מקדש דמתני' דנדרים אתיא דלא כמאן ועוד נראה דגם רבא ס\"ל טובת הנאה אינו ממון אלא דלא ניחא ליה לאוקמ' מתני' דנדרים כרב יהושיע דהתם דרישא ר' יוסי בר יהודה וסיפא רבי אלא ס\"ל דבמתני' כ\"ע מודה מטעם דבנדרים שאני כיון דאפי' ויתור אסור במודר הנאה וכן מחמירים בנדרים בעלמא טובא א\"כ אפי' תימא אינה ממון מ\"מ הנאה מיה' איתא כמו בויתור וכה\"ג וכ\"כ הכ\"מ פ\"ז מה' נדרים בשם רבי מאיר בר שמעון המעילי שהביא ג\"כ שמפרק אלו עוברין מוכח דטובת הנאה אינה ממון ע\"ש וכ\"פ מהרש\"ל פ\"ט דב\"ק סי' ס\"א כהרמב\"ם דטובת הנאה אינה ממון ודשאני בהך דנדרים אלא שחילוקו שם אינו ברור כ\"כ ע\"ש תדע דאל\"כ הא בע\"כ רבא גופיה מודה דר' ור' יוסי תרוייהו ס\"ל דטובת הנאה אינו ממון וכדמשמע בש\"ס בנדרים התם א\"כ היאך מוקי רבא מתני' דלא כמאן א\"י כדפי' וגם הטור י\"ד סי' של\"א כתב דטובת הנאה אינה ממון וכ\"כ הטור ברמזי פסקי הרא\"ש ס\"פ האיש מקדש וז\"ל הילכתא טובת הנאה אינה ממון והמקדש בה אינה מקודשת עכ\"ל ואע\"פ שיש לתמוה ע\"ז דהא הרא\"ש כ' שם בשם ר\"ח דהוי ממון והי' נראה למחוק תיבת אינה שני פעמים אך כיון שבדקתי בכמה דפוסין ונמצא כן אינה ממון וגם הטור כ' בעצמו בי\"ד סי' של\"א אינה ממון נראה יותר שזהו אינו מדברי הרא\"ש רק שאיזה תלמיד הוסיפו בסוף הפרק אחר דברי הרא\"ש או הטור הבין דמ\"ש הרא\"ש בשם ר\"ח ר\"ל דאע\"ג דקי\"ל בעלמא דטובת הנאה אינה ממון קי\"ל בנדרים דממון הוא ואע\"ג דל' ר\"ח לא משמע כן מ\"מ אפשר דהטור הבין כן שוב ראיתי במרדכי פרק שבועות הדיינים הביא תשובת מהר\"מ ב\"ב שכ' דנראה דטובת הנאה אינה ממון כעולא ורב אסי דפ\"ב דקידושין ואע\"ג דרבא בתרא הוא ומוקי מתני' בפ' בתרא דנדרי' דטובת הנא' ממון היינו דלא בעי לאוקמי כחד תנא משום דקשיא לי' רישא לסיפא ומיהו רבא גופא איהו סבר דטובת הנאה אינה ממון עכ\"ל (והוא בתשובת מהר\"מ ד\"פ סי' רפ\"א ולכאורה אין הבנה לדבריו ועוד דהיכן מצינו לרבא דטובת הנאה אינה ממון אבל למאי דפירשתי ניחא דיש קצת ט\"ס בדבריו וצ\"ל היינו דבעי לאוקמא כחד תנא ור\"ל דרבא לא ס\"ל כרבי הושעי' דרישא רבי יוסי וסיפא רבי אלא בעי לאוקמי כולא מתני' כחד תנא ומיהו רבא גופא סבר טובת הנאה אינה ממון בעלמא דהא משמע התם דרבא גופא ס\"ל דרבי ורבי יוסי תרוייהו ס\"ל טובת הנאה אינה ממון אלא דס\"ל דבנדרים שאני וכמ\"ש וגם בתשו' מהרי\"ק סוף שורש קס\"א הביא תשובת מהר\"מ הנ\"ל בקצרה ומביאו מהר\"ם פדאוה בתשובת סי' ס\"ה (וכן הוא בתשו' מהר\"ם פ\"ק דמציעא המתחלת אשר שאלת בראובן שיש לו חצי מעשר כו') וכן נראה דעת הרב לעיל סי' ס\"ז ס\"ט וסי' פ\"ז סל\"ז וסי' רע\"ז ס\"ו וכן עיקר ומהר\"ם מטיקטין כתב בגליון המרדכי פ' שבועות הדיינים וז\"ל האשר\"י שלהי פרק האיש מקדש פוסק בשם ר\"ח הלכה טובת הנאה ממון וכן בשאלתות פרשת קרח ע\"כ (הג\"ה ועיין לעיל סי' ר\"ד ומ\"ש מחז\"ל שם):"]],["יֵשׁ גַּנָּב שֶׁפָּטוּר מִלְּשַׁלֵּם. וְאֵיזֶה, זֶה שֶׁבָּא עִם הַתַּשְׁלוּמִין חִיּוּב מִיתָה; \u0010y0\u0011 כְּגוֹן הַגּוֹנֵב כִּיס בְּשַׁבָּת \u0010y1\u0011 וְלֹא הִגְבִּיהוֹ בִּרְשׁוּת הַבְּעָלִים \u0010y2\u0011 אֶלָּא הָיָה מְגָרְרוֹ וּמוֹצִיאוֹ מֵרְשׁוּת הַבְּעָלִים לִרְשׁוּת הָרַבִּים וְאִבְּדוֹ שָׁם, \u0005הַגָּה: \u0010y3\u0011 \u0010c0\u0011 אֲבָל אִם אִבְּדוֹ אַחַר כָּךְ חַיָּב, וְכָל שֶׁכֵּן אִם עֲדַיִן הוּא בְּעַיִן שֶׁחַיָּב לְהַחֲזִירוֹ (טוּר וְהַמ\"מ פ\"ג דִּגְּנֵבָה בְּשֵׁם י\"מ ורמ\"ה וְהָרַמְבַּ\"ן ז\"ל)\u0006. וְיֵשׁ אוֹמְרִים שֶׁאִם אֵינוֹ בְּעַיִן \u0010y4\u0011 בְּכָל עִנְיָן פָּטוּר מִלְּשַׁלֵּם \u0005(הַמַּגִּיד פֶּרֶק ג' דִּגְּנֵבָה וּבְשֵׁם רַשִׁ\"י וְהָרַמְבַּ\"ם)\u0006, הֲרֵי זֶה פָּטוּר מִתַּשְׁלוּמִין, שֶׁאִסוּר שַׁבָּת וְאִסוּר גְּנֵבָה וְהֶזֵּק בָּאִים כְּאֶחָד. אֲבָל אִם גַּנָּב כִּיס בְּשַׁבָּת וְהִגְבִּיהוֹ שָׁם בִּרְשׁוּת הַיָּחִיד, וְאַחַר כָּךְ הוֹצִיאוֹ לִרְשׁוּת הָרַבִּים וְהִשְׁלִיכוֹ לַנָּהָר, חַיָּב לְשַׁלֵּם, שֶׁהֲרֵי נִתְחַיֵּב בְּאִסוּר גְּנֵבָה קֹדֶם שֶׁיִּתְחַיֵּב בְּאִסוּר סְקִילָה; \u0010y5\u0011 וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:",["\u0003כגון הגונב כיס בשבת כו' \u0004 בסי' ש\"ן כתב הטור עוד ענין אחר דפטור אף מקרן משום דקם ליה בדרבה מיני' והוא כגון שהית' בהמה שאולה או שכורה בידו וטבחה בשבת לשם גניבה דחיוב גניבה ואיסור שבת באים כא' ועפ\"ר:","\u0003ולא הגביהו ברשות הבעלים \u0004 דאלו הגביהו הגנב קנאה דהגבה' קונה בכ\"מ וכדמסי' המחב':","\u0003אלא הי' מגררו ומוציאו כו' \u0004 ל' הטו' ע\"פ הגמ' כן הוא והי' מגררו ומוציאו מרשו' בעלי' לר\"ה וחיבר ידו למפתן הבית תוך ג' סמוך לארץ והפילו לתוכו שאיסו' גניב' ואיסו' שבת באין כא' כו' וה\"ט משו' דאם לא הוציאו מרשות בעלים לר\"ה לא הי' כאן חיוב מית' דהוצא' שבת ואלו לא חיבר ידו למפתן הבית לא הי' כאן חיוב ממון דגניב' דהמושך מרשות בעלי' לרשות הרבי' ולא הגבהו לא קנאה במשיכה דמשיכ' אינו קונ' כ\"א בסימט' או בחצר של שניהן או ברשותו וכמ\"ש הטור והמחבר בסי' קצ\"ז לכך צ\"ל שמשכו מרשות בעלים וגררו והפילו מיד כשיצא מן הבית לתוך ידו דידו הוה כרשותו וקנאו לו וג\"כ הוה כר\"ה כיון שהוא בר\"ה נמצא דאיסור גניבה ואיסור שבת באים כא' ומ\"ש שחיבר ידו לתוך ג' ה\"ה כשהי' מונחת על הארץ בר\"ה ולמעלה ממנה רק שלא יהא גבוה מן הארץ ג\"ט דאלו הי' גבוה ג\"ט נמצא קודם שבא הכיס לידו היה צריך להגביהו תחלה ג\"ט מהארץ בעודו ברשות בעלים כדי להניחו לידו ואז קנאה מיד בהגבהה קודם ביאת איסור שבת שאינו חל עליו עד שהוציאו מרשות בעלים והניחו לידו שהוא בר\"ה והא דאמרו דחיבר ידו להמפתן כו' ה\"ה אם ידו רחוק קצת מהמפתן דאף דאיסו' שבת הי' בא תחלה כיון שהיא תוך ג' וכלבוד דמי מ\"מ כשבא הכיס אח\"כ לידו כבר חיוב מיתה עליו וקם ליה בדרבה מיני' אלא שיש בזה פלוגת' כמ\"ש מור\"ם מ\"ז בהג\"ה משא\"כ כשחיבר ידו להמפתן דבאין החיובים כא' דפטור לכ\"ע ועפ\"ר ודוק:","\u0003אבל אם אבדו אח\"כ חייב \u0004 כצ\"ל דכל שלא בא עליו חיוב מיתה וחיוב תשלומין יחד חייב וכאן נמי כל זמן שהכיס עם המעו' הוא בעין ברשותו דמריה קאי ולא חל עליו חיוב ממון עד שעת תבירה ואתביר' לאו חיוב מיתה הוא:","\u0003בכל ענין פטור מלשלם \u0004 טעמייהו דמיד שהוציא הכיס חייב מיתה ולא פקע מיניה האיסור ותו לא חל עליו חיוב ממון כיון דהוא חייב מיתה דקלב\"מ:","\u0003וכן כל כיוצא בזה \u0004 בטור כ' כגון הבא במחתרת כו' ע\"ש:"],["\u0003 אבל אם אבדו אח\"כ כו' \u0004 צ\"ע מנ\"ל הא ובטור ליתא כן אלא גבי מחתרת משום דמיד שיוצא ממחתרת תו לא מחייב מיתה אבל הכא י\"ל כיון דעדיין עומד בחיוב המיתה דשבת פטור כשאבדו ודוק:"]],["הִפְקִיד לִשְׁנַיִם, \u0010y0\u0011 וְטָעֲנוּ: נִגְנַב, וְהוֹדָה הָאֶחָד וְעַל הַשֵּׁנִי בָּאוּ עֵדִים, בֵּין שְׁנֵיהֶם מְשַׁלְּמִים הַקֶּרֶן.",["\u0003וטענו נגנב והודה הא' כו' \u0004 בטור כ' ז\"ל וטענו נגנב ונשבעו שניהן והודה הא' וכן הוא ברמב\"ם והמחבר השמיטו הא דנשבעו שניהן משום דלא נקטי הן הא דנשבעו אלא משום חיוב כפל וחומש דהשומר שטען טענת גנב והוכחש בעדים שמעידים שהי' בידו אינו חייב בכפל עד שנשבע תחלה וכמ\"ש ל' הגמ' בפריש' והמחבר לאכ' דין כפל וחומש וכמ\"ש בסי' שמ\"ח וש\"ן מ\"ה לא כ' נמי הא דנשבעו דלענין חיוב תשלומי קרן א\"צ שבוע' ולא ידעתי למה הוצרך המחבר לכתוב זה דבין שניהן משלמין הקרן דפשוט הוא להגמ' והרמב\"ם לא כתבהו אלא אגב דין כפל וחומש ע\"ש:"],[]],["נִשְׁתַּנָּה שֵׁם הַגְּנֵבָה בְּיַד הַגַּנָּב, \u0010c0\u0011 כְּגוֹן שֶׁגָּנַב טָלֶה וְנַעֲשָׂה אַיִל; עֵגֶל וְנַעֲשָׂה שׁוֹר, \u0010y0\u0011 קְנָאָהּ בְּשִׁנּוּי הַשֵּׁם, וְאֵין לְהַחֲזִיר אֶלָּא דָּמֶיהָ וּמְשַׁלֵּם כְּמוֹ שֶׁהָיְתָה שָׁוָה בִּשְׁעַת הַגְּנֵבָה. וְכֵן כָּל שִׁנּוּי כַּיּוֹצֵא בָּזֶה, שֶׁאֵינוֹ \u0010y1\u0011 חוֹזֵר לִבְרִיָּתוֹ; אֲבָל שִׁנּוּי הַחוֹזֵר, אֵינוֹ קוֹנֶה אֲפִלּוּ מִדְּרַבָּנָן. וּבְסִימָן ש\"ס יִתְבָּאֵר אֵיזֶה שִׁנּוּי הַחוֹזֵר.\nנִתְיָאֲשׁוּ הַבְּעָלִים \u0010y2\u0011 \u0010c1\u0011 מֵהַגְּנֵבָה, אֵינוֹ קוֹנֶה, וְצָרִיךְ לְהַחֲזִירָהּ. וְאִם יֵשׁ עִם הַיֵּאוּשׁ שִׁנּוּי הַשֵּׁם \u0010y3\u0011 שֶׁחוֹזֵר לִבְרִיָּתוֹ, יֵשׁ אוֹמְרִים שֶׁקּוֹנֶה וְאֵינוֹ צָרִיךְ לְהַחֲזִיר אֶלָּא דָּמֶיהָ.\nאִם יֵשׁ עִם הַיֵּאוּשׁ \u0010y4\u0011 \u0010c2\u0011 שִׁנּוּי רְשׁוּת, בֵּין שֶׁנִּתְיָאֲשׁוּ וְאַחַר כָּךְ מָכַר הַגַּנָּב בֵּין שֶׁנִּתְיָאֲשׁוּ אַחַר שֶׁמָּכַר, \u0010y5\u0011 \u0010c3\u0011 קָנָה, \u0005וְיֵשׁ חוֹלְקִין (טוּר ס\"ו בְּשֵׁם הָרֹא\"שׁ וְרַשִׁ\"י וּמָרְדְּכַי ר\"פ הַגּוֹזֵל בַּתְרָא וּבֵית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006 וְע\"ל סִימָן שנ\"ו לְעִנְיַן שֶׁאֵין הַקּוֹנֶה צָרִיךְ לְהַחֲזִיר גּוּף הַגְּנֵבָה, אֲבָל מַחֲזִיר דָּמִים \u0010y6\u0011 \u0010c4\u0011 אִם לָקַח מִגַּנָּב \u0010c5\u0011 מְפֻרְסָם. \u0005וְיֵשׁ אוֹמְרִים דְּאֵין צָרִיךְ לִתֵּן לוֹ דָּמִים, דְּקָנָה לְגַמְרֵי (טוּר ס\"ה בְּשֵׁם ר\"י וּבְשֵׁם רַשִׁ\"י וְרַשְׁבָּ\"א)\u0006. וְאִם לֹא הָיָה גַּנָּב \u0010y7\u0011 מְפֻרְסָם, אֵינוֹ נוֹתֵן כְּלָל, לֹא חֵפֶץ וְלֹא דָּמִים, מִפְּנֵי תַּקָּנַת הַשּׁוּק, כְּמוֹ שֶׁיִּתְבָּאֵר בְּסִימָן שנ\"ו.\nאֵין נִקְרָא שִׁנּוּי רְשׁוּת אֶלָּא בְּמוֹכֵר אוֹ נוֹתֵן; אֲבָל אִם מֵת וְהוֹרִישׁוֹ לְבָנָיו, לֹא, \u0010y8\u0011 דִּרְשׁוּת יוֹרֵשׁ לָאו כִּרְשׁוּת לוֹקֵחַ דָּמֵי. וְיִתְבָּאֵר בְּסִימָן שס\" א. וְשָׁם יִתְבָּאֵר עוֹד אֵי זֶה נִקְרָא שִׁנּוּי רְשׁוּת.",["\u0003קנאה בשינוי השם כו' \u0004 דכתיב בגזילה והשיב הגזלה אשר גזל ודרשי' מיתורא דאשר גזל דא\"צ להשיב בעינה אלא כשהיא עדין בעין ולא כשנשתנ' בידו אחר הגזיל' דאז קנא' בהשינוי וא\"צ להחזי' אלא דמי' וגם הכפל משלם כשעת הגניב' בזה השינוי דטלה ונעש' איל אבל בשאר שינוי ויוקרא וזולא יתבאר דינייהו בסי' שנ\"ד וע\"ש:","\u0003חוזר לברייתו \u0004 פי' דיחזיר להיו' כמו שהיתה מתחלה:","\u0003אינו קונה \u0004 וצריך להחזיר' בטור מסיק וכ' בזה ז\"ל ונ' לא\"א הרא\"ש ז\"ל כיון דרבא מספקא ליה אי קני דאוריית' או דרבנן נהי דלא קי\"ל כותי' בהא דמספקא ליה אי קני דאוריי' אלא כעולא ור' יוחנן דסברי לא קנה מ\"מ אם קדש בו אשה צריכ' גט מספק דשמא קונה מדרבנן עכ\"ל ומן התימא שלא כ' מור\"ם דעתו לפחות לדעת י\"א וצ\"ל דסמך אמ\"ש בא\"ע בדין קידש אשה:","\u0003שחוזר לברייתו \u0004 פי' אפי' אם חוזר לברייתו וכ\"כ הטור:","\u0003שינוי רשות \u0004 פי' כגון שמכרה או נתנה לאחר או לא' מבניו בחייו:","\u0003ויש חולקין כו' \u0004 כ\"כ הטור בסי' זה בשם הרא\"ש דס\"ל דבעי' שיהא היאוש קודם השינוי רשות ע\"ש:","\u0003אם לקח מגנב מפורסם \u0004 המחבר נמשך אחר ל' הרמב\"ם דס\"ל דלא עשו תקנת השוק בגנב מפורסם כמ\"ש הטור והמחבר בשמו בסי' שנ\"ו ס\"ב מ\"ה נקט גנב מפורסם צריך ליתן להנגזל דמי הגניבה לאחר יאוש משא\"כ כשלקחו מגנב שאינו מפורסם שכן עשו תקנת השוק שהנגזל יתזיר ללוקח מה שנתן בעדם מ\"ה כאן שלקחו לאחר יאוש א\"צ להחזיר הלוקח כלל דאפוכי מטרת' למה ליה דהלוקח יתן לו דמי שוויו והבעלים יצטרכו לחזור ליתן לו הדמים משום תק\"ה ועד\"ר בסי' ש\"מ ס\"ב דשם כתבתי דאפי' לסברת הרמב\"ם הנ\"ל שייך חזרת דמים מהלוקח להנגזל אף לאחר יאוש ואפי' בגנב שאינו מפורסם והוא שדרך הגנב להוזיל הדברים שמוכר ליתנם בפחות משווי' ואותו מותר עד כדי שווי' צריך להחזיר הלוקח להנגזל ולפ\"ז אצ\"ל דאיירי דין זה דוקא בגנב מפורסם וע\"ש שישבתי בזה כמה קושיות:","\u0003אינו נותן כלל כו' \u0004 וכ' במרדכי פ' הגוזל מיהו אם בא להחזיר ואמר איני חפץ בממון שאינו שלי צריך להחזיר לבעלים הראשונים עכ\"ל ד\"מ ו':","\u0003דרשות יורש לאו כרשו' לוקח דברא כרעא דאבוה הוא:\u0004"],["\u0003 כגון שגנב טלה ונעשה איל כו'. \u0004 מהרש\"ל פרק מרובה תמה ע\"ז דבש\"ס פ' מרובה מסיק להדיא דאע\"ג דשנוי השם חשוב קונה מ\"מ טלה ונעשה איל לא הוי שינוי שם דאיל בן יומו קרוי איל כדכתיב את אילי צאנך לא אכלתי וכן עגל ונעשה שור לא הוי שינוי שם דשור בן יומו קרוי שור כדכתיב שור או כשב כו' כי יולד אלא דטלה ונעשה איל עגל ונעשה שור קונה משום שינוי מעשה ע\"כ דבריו ע\"ש שהאריך ולפע\"ד דברי הרא\"ש והטור (וכ\"פ רבי ירוחם נל\"א ח\"ג וח\"ד) והמחבר נכונים דודאי בכ\"מ הולכים אחר ל' בני אדם אפי' לקולא והכא הרי עינינו רואות שאין קורין לבן יומו איל או שור ובש\"ס שם נמי משמע הכי דאל\"כ לא הוי מתקיף ר' זירא כולי האי וליקנינהו בשינוי השם משמע דפשיט' ליה דאין קורין שור ואיל רק לגדולים ורבא הכי קמשני שור בן יומו אשכחן דקרי שור כדכתיב שור או כשב כו' ואיל בן יומו אשכחן דקרי איל כדכתי' אילי צאנך גו' וכיון דאשכחן בקרא הכי א\"כ י\"ל דבזמן ר' אילעאי נמי הוי קורין כן אבל ודאי השתא אין קורין כן וא\"כ הוי שינוי שם וכה\"ג ממש איתא בנדרים פ' הנודר מן המבושל גבי הנודר מן המבושל אם אסור בצלי דמעיקר' הוי בעי למימר כיון דאשכחן בתורה דצלי קרוי מבושל ותנא לישנ' דאוריית' נקט ובתר הכי מסקי' וכן מוסכם מכל הפוסקים דאע\"ג דבל' תורה נקרא כן מ\"מ הולכים אחר לשון בני אדם לפי המקום הזמן ע\"ש ופשיט' דל\"ד בנדרים הוא כן אלא ה\"ה בכל שאר מילי וכדאמרינן גבי אדר ראשון ושני לענין נדרים ושטרות וכתובות ושאר דברים עיין בי\"ד בספרי שפתי כהן סי' ר\"ך ס\"ק י\"ז וזה ברור:","\u0003 אינו קונה כו' \u0004 (עיין בסמ\"ע ס\"ק ג' ועיין במהרש\"ל מה שנתעורר בזה על הרא\"ש ועיין מ\"ש מ\"ח ז\"ל בא\"ע סי' כ\"ח):","\u0003 שינוי רשות כו'. \u0004 עיין בתשו' רשד\"ם סי' ע':","\u0003 וי\"ח. \u0004 דבעינן היאוש קודם שינוי רשות והם הרא\"ש פ' הגוזל בתרא והטור וכ\"כ ב\"י בשם הרשב\"א וכן הוא בתשובת רשב\"א סי' תתקס\"ח וכן נ\"ל שהוא דעת רש\"י פרק הגוזל בתרא (בבא קמא דף קט\"ו ע\"א) ע\"ש וכן משמע לי מפירש\"י פרק הנזקין דף נ\"ה ע\"א שכ' יאוש כדי לא קנה יאוש לבדו בלא שינוי רשות אחר היאוש עכ\"ל וכן דעת המרדכי והאגודה ר\"פ הגוזל בתרא וכן נראה דעת התוס' פ' מרובה (בבא קמא דף ע\"ב) סוף ד\"ה אמר עולא כו' וכ\"כ בהגהות אשר\"י בשם ר\"י וכן דעת הרז\"ה בס' המאור והרמב\"ן בס' המלחמות פ' הגוזל בתרא וכן עיקר וכ\"פ הרב לקמן סימן שנ\"ז ס\"ג ומהרש\"ל פ' מרובה סי' ז' והגוזל בתרא סי' כ\"ז ול\"א ועוד נראה ראי' דהא קי\"ל (לעיל סי' רס\"ב ס\"ד) כאביי דיאוש ש\"מ לא הוי יאוש ובש\"ס פרק אלו מציאות (בבא מציעא דף כ\"ב ריש ע\"א) מוכח להדי' דלפ\"ז לא מהני יאוש אא\"כ ידוע שנתייאש קודם לכן דפריך התם לאביי ת\"ש הגנב וגזלן שנטל מזה ונתן לזה מה שנטל נטל ומה שנתן נתן בשלמ' גזלן דקחזי ליה ומייאש אלא גנב מי קחזי ליה דמייאש תרגמ' ר\"פ בלסטים מזוין ע\"כ ואפשר הרמב\"ם מחלק בין מכר למתנה אבל אין נ\"ל לחלק דהא קי\"ל רשות מקבל מתנה כרשות לוקח דמי וכדלקמן סי' שס\"א ס\"ה ולפ\"ז נ\"ל דגם דעת הרי\"ף דבעי' היאוש קודם שינוי רשות ודלא כמהרש\"ל פרק הגוזל בתרא סי' ל\"א לדעת הרי\"ף שסמך עצמו אמה שהביאו בפ' א\"מ הלכה רווחת כאביי דיאוש של\"מ לא הוי יאוש הואיל ובאיסור' אתי לידיה א\"כ פשיט' דלפ\"ז ל\"מ שינוי רשות קודם יאוש ולפ\"ז הא דק\"ל לקמן סי' שס\"א ושס\"ח סתם גניבה הוי יאוש בעלים היינו כשידוע שהבעלים ידעו מהגניבה דאז אמרינן מסתמא נתייאשו הבעלים אבל אי לא ידעינן שידעו מהגניבה לא הוי יאוש וכדמוכח מההיא דגנב שנטל מזה כו' וכ\"כ האגודה פרק א\"מ גנב דלא ידעו בעלים שנגנב להן ונתן לזה חייב להחזיר לבעלים הראשונים דהוי ליה יאוש ש\"מ אבל אם כבר ידעו הבעלים קנה ע\"כ וכ\"כ בהגה\"א שם:","\u0003 אם לקח מגנב מפורסם כו'. \u0004 ע' בסמ\"ע ס\"ק ז' עד דשם כתבתי דאפי' לסברת הרמב\"ם הנ\"ל שייך חזרת דמים מהלוקח לנגזול כו'. וכ\"כ הד\"מ והסמ\"ע והב\"ח לקמן סי' שכ\"ו ס\"ג דלהרמב\"ם אף בגנב שאינו מפורסם צריך הלוקח להחזיר לבעלים היתרון בדמי שוויו על דמי לקיחתו אף שקנהו ביאוש ושינוי רשות והשיגו כולם על המחבר שכתב דלהרמב\"ם אין הלוקח מחזיר כלום בגנב שאינו מפורסם ואני אומר כולם שלא כדת השיגו עליו כי הדין עם המחבר והגירס' שנמצ' בספרי הרמב\"ם ואם לא היה גנב מפורסם אינו נותן כלל לא חפץ ולא דמים כו' הוא אמת (וכ\"כ ה' המ' שזאת הגירס' בהרמב\"ם היא בדוקה) דאמרינן בש\"ס פ' חזקת הבתים (בבא בתרא דף מ\"ד ע\"א) וכן כתבו כל הפוסקים (וכמו שנתבאר לעיל סי' ל\"ז סעיף י\"ז) והרמב\"ם גופיה ריש פרק ט\"ז מהלכות עדות דאם מכר הגזלן שדה ללוי אין הנגזל יכול להעיד עליה שנוגע בעדות שיוציאנה מיד הלוקח אבל אם מכר הגזלן טלית מעיד עליה שהרי אין טלית זו חוזרת לנגזל לעולם שכבר קנאה הלוקח ביאוש ושינוי רשות ואם איתא שעכ\"פ צריך להחזיר לו המותר אין לך נוגע בעדות גדולה מזו ודוחק לו' דהתם מיירי שידוע שלא קנה רק כפי מה ששוה עכשיו (ודין גנב וגזלן אחד הוא כדלקמן ר\"ס שס\"ח ע\"ש) א\"ו אין צריך כלום ומיירי התם בגזלן שאינו מפורסם כן נ\"ל בדעת הרמב\"ם ברור:","\u0003 וי\"א דאין צריך כו' \u0004 דברי הר\"ב והסמ\"ע כאן וסי' שנ\"ו ס\"ק י\"ג ושאר דוכתי' צל\"ע דלפי מה שס\"ל להמחבר ולפי מה שהוכחתי דדוק' בגנב מפורסם ס\"ל להרמב\"ם דצריך להחזיר הדמים א\"כ ליכא מאן דפליג עליה ומ\"ש הטור שר\"י חולק היינו לפי הבנתו בהרמב\"ם דגם בגנב שאינו מפורסם צריך להחזיר דמים ועיין בתוס' פרק מרובה (בבא קמא דף ס\"ז ע\"ב) משמע להדי' דס\"ל לר\"י דהיכ' דבאיסור' אתי לידיה ל\"מ יאוש ושינוי רשות וצריך להחזיר הדמים א\"כ בגנב מפורסם נמי באיסור' אתי לידיה (וא\"כ גם מ\"ש בב\"י כאן על מ\"ש הטור בשם ר\"י וז\"ל כן נראה שהיא דעת רש\"י ממ\"ש בפרק הגוזל בתרא על משנת המכיר כליו כו' היינו ג\"כ לפי הבנת הטור דהרמב\"ם מיירי אף בגנב שאינו מפורסם אבל לפי מ\"ש המחבר ולפי מה שהוכחתי לא מוכח מרש\"י מידי שיחלוק על הרמב\"ם דבמשנה המכיר כליו כו' איירי בגנב שאינו מפורסם כדמשמע בש\"ס ע\"ש שוב ראיתי בב\"ח שכתב שכוונת הב\"י ממ\"ש רש\"י באוקימת' דרב זביד כו' ואע\"פ שלשון ב\"י לא משמע כן שהרי כתב שכן משמע ממ\"ש רש\"י על משנת דהמכיר כו' וגם לא ידעתי מי הזקיקו להבין כך כוונת הב\"י שהרי כוונת הב\"י כפשוטו מדכתב רש\"י במשנה ולפני יאוש מיירי משמע דס\"ל דא\"צ להחזיר הדמים דאל\"כ הלא מצי מיירי לאחר יאוש ומ\"מ צריך להחזיר הדמים מ\"מ אפילו יהיה כדברי הב\"ח גם שם לא משמע מידי דמיירי התם ג\"כ בסתם גנב שאינו מפורסם ע\"ש סוף דבר בדינו של הרמב\"ם והמחבר בגנב מפורסם לא ראיתי מי שחולק עליו) וצ\"ע עוד נ\"ל דמ\"ש הרמב\"ם ומחזיר הדמים היינו המותר ששוה ממה שנתן דאל\"כ מ\"ש דמים או חפץ והשת' א\"ש מ\"ש הרב המגיד וז\"ל ואפשר שגם ע\"ז תמה הר\"א ז\"ל שכיון שקנה הלוקח ביאוש ושינוי רשות למה יתן דמים אפילו היה גנב מפורסם וצ\"ע עכ\"ל ולפע\"ד העיקר כמ\"ש הרב המגיד בתחלה דהר\"א לא תמה רק על הגירס' שהיה לפניו (והיא גירסת הטור) וע\"ז כ' שהוא שבוש המעתיק אבל לפי גירסא זו לק\"מ וטעם הרמב\"ם נכון (ובב\"י סי' שנ\"ו כ' טעם אחר לדעת הרמב\"ם וכבר האריך הב\"ח שם להקשות עליו אבל לפי הטעם שכתבתי לק\"מ והוא נכון ודוק) דכיון דקנה מגנב מפורסם א\"כ באיסור' אתי לידיה ולא הוי ש\"ר גמור ומחזיר מותר הדמים ששוה וכעין זה ממש כ' בעל המאור פ' הגוזל בתרא גבי נטלו מוכסים חמורו ונתנו לו אחרת הרי הוא שלו ומחזיר המותר לבעלים הראשונים דכיון דבטעות אתי לידיה לא הוי שינוי רשות גמור והיינו דאמרינן מ\"ט יאוש כדי לא קנה ובאיסור' אתי לידיה עכ\"ל ואע\"ג דהתם קי\"ל דאינו מחזיר כלום וכדלקמן סי' שס\"ט ס\"ח היינו מטעם דקי\"ל דהתם הוי שינוי רשות גמור וכמה שכתב בעל המאור שם משא\"כ הכא וא\"כ דינו של הרמב\"ם והמחבר אמת ואין חולק עליו ודוק:"]],["הָיְתָה הַגְּנֵבָה בְּיַד הַגַּנָּב \u0010c0\u0011 \u0010c1\u0011 וְהִשְׁבִּיחָה מֵאֵלֶיהָ, כְּגוֹן כִּבְשָׂה שֶׁהָיְתָה מְעֻבֶּרֶת בִּשְׁעַת גְּנֵבָה, וְיָלְדָה; אוֹ שֶׁהָיְתָה טְעוּנָה בִּשְׁעַת גְּנֵבָה, וּגְזָזָהּ, \u0010y0\u0011 מְשַׁלֵּם אוֹתָהּ וְאֶת גִּזּוֹתֶיה וְאֶת וְלָדוֹתֶיהָ. וְאִם אַחַר יֵאוּשׁ יָלְדָה וּגְזָזָהּ, \u0010y1\u0011 \u0010c2\u0011 מְשַׁלֵּם כִּשְׁעַת הַגְּנֵבָה. הוֹצִיא עָלֶיהָ וְהִשְׁבִּיחָה, כְּגוֹן שֶׁפִּטְּמָהּ, הֲרֵי הַשֶּׁבַח שֶׁל גַּנָּב אֲפִלּוּ לִפְנֵי יֵאוּשׁ, וּכְשֶׁמַּחֲזִיר הַגְּנֵבָה נוֹטֵל הַשֶּׁבַח מֵהַבְּעָלִים. \u0005הַגָּה: \u0010c3\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ שָׁבְחָה מֵאֵלֶיהָ הוּא שֶׁל גַּנָּב, אֲפִלּוּ קֹדֶם יֵאוּשׁ, \u0010y2\u0011 \u0010c4\u0011 וְכָל שֶׁכֵּן אִם גָּנַב כִּבְשָׂה וְנִתְעַבְּרָה אֵצֶל גַּנָּב דְּהַשֶּׁבַח שֶׁל גַּנָּב, אֲפִלּוּ תְּבָעוּהָ הַבְּעָלִים קֹדֶם שֶׁיָּלְדָה, הוֹאִיל וּגְנָבָהּ רֵיקָנִית (טוּר ס\"א בְּשֵׁם הָרֹא\"שׁ וְהָרַאֲבַ\"ד)\u0006.\nהַגְּנֵבָה עַצְמָהּ שֶׁהִיא \u0010y3\u0011 בְּיַד הַגַּנָּב, וְלֹא נִשְׁתַּנֵּית, חוֹזֶרֶת לַבְּעָלִים בֵּין לִפְנֵי יֵאוּשׁ בֵּין לְאַחַר יֵאוּשׁ, אֶלָּא שֶׁלְּאַחַר יֵאוּשׁ הַשֶּׁבַח לַגַּנָב, כְּמוֹ שֶׁיִתְבָּאֵר. נִשְׁתַּנֵּית הַגְּנֵבָה בְּיַד הַגַּנָּב, קְנָאָהּ וְקָנָה שִׁבְחָהּ, אֲפִלּוּ לִפְנֵי יֵאוּשׁ, וְאֵינוֹ מְשַׁלֵּם אֶלָּא דָּמִים \u0005(הָרֹא\"שׁ)\u0006. וְיִתְבָּאֲרוּ פְּרָטֵי דִּינִין אֵלּוּ בְּסִימָן שס\"ב.\nגָּנַב בְּהֵמָה אוֹ כְּלִי וְכַיּוֹצֵא בָּהֶם, וּבִשְׁעַת גְּנֵבָה הָיְתָה שָׁוָה אַרְבָּעָה, וְעַכְשָׁיו בְּעֵת הַעֲמָדָה בַּדִּין שָׁוָה שְׁנַיִם, \u0010y4\u0011 מְשַׁלֵּם קֶרֶן כִּשְׁעַת גְּנֵבָה. הָיְתָה שָׁוָה בִּשְׁעַת גְּנֵיבָה שְׁנַיִם \u0010y5\u0011 וּבִשְׁעַת הַעֲמָדָה בַּדִּין אַרְבָּעָה, אִם שָׁחַט אוֹ מָכַר \u0010y6\u0011 אוֹ שָׁבַר הַכְּלִי אוֹ אִבְּדוֹ, מְשַׁלֵּם כִּשְׁעַת הַעֲמָדָה בַּדִּין; וְאִם מֵתָה הַבְּהֵמָה אוֹ אָבַד הַכְּלִי מֵאֵלָיו, מְשַׁלֵּם כִּשְׁעַת \u0010y7\u0011 הַגְּנֵבָה.\nגָּנַב כְּחוּשָׁה וְהִשְׁמִינָה, אוֹ שְׁמֵנָה וְהִכְחִישָׁה, מְשַׁלֵּם כִּשְׁעַת גְּנֵבָה. \u0005הַגָּה: וְהָא דְּגָנַב כְּחוּשָׁה וְהִשְׁמִינָה מְשַׁלֵּם כִּשְׁעַת הַגְּנֵבָה, דַּוְקָא שֶׁהוֹצִיא עָלֶיהָ הוֹצָאוֹת, אֲבָל נִתְפַּטְּמָה מִמֵילָא \u0010y8\u0011 \u0010c5\u0011 הָוֵי כְּאִלּוּ הוּקְרָה, וְאִם שְׁחָטָהּ מְשַׁלֵּם כִּשְׁעַת הַעֲמָדָה בַדִּין (טוּר ס\"ד)\u0006.\nגָּנַב כְּלִי, וּשְׁבָרוֹ אוֹ פִּחֲתוֹ אוֹ נִשְׁבַּר אוֹ נִפְחַת \u0010y9\u0011 מֵאֵלָיו, אֵין אוֹמְרִים יִתֵּן לַבְּעָלִים הַשְּׁבָרִים וְיַשְׁלִים עֲלֵיהֶם, אֶלָּא הוּא יִטֹּל הַשְּׁבָרִים וְיִתֵּן לַבְּעָלִים כְּלִי שָׁלֵם אוֹ דָּמָיו \u0005(וְכֵן כָּתַב לְקַמָּן סִימָן שס\"ג)\u0006. \u0010c6\u0011 \u0005וְדַוְקָא דְּאִית לֵהּ מָעוֹת, אֲבָל אִי לֵית לֵהּ לָא גְּרִיעֵי שְׁבָרִים אֵלּוּ מִשְּׁאָר מִטַּלְטְלִין\u0006 \u0005(נִמּוּקֵי יוֹסֵף פ\"ק דב\"ק)\u0006. \u0010y10\u0011 וְאִם רָצוּ הַבְּעָלִים לִטֹּל הַכְּלִי הַשָּׁבוּר וִישַׁלֵּם לָהֶם הַפְּחָת, \u0010c7\u0011 שׁוֹמְעִין לָהֶם.\nגָּנַב אוֹ גָּזַל וְלֹא נִתְיָאֲשׁוּ הַבְּעָלִים, \u0010y11\u0011 אֵינָם יְכוֹלִים לְהַקְדִּישׁ לֹא הַגַּנָּב וְהַגַּזְלָן וְלֹא הַבְּעָלִים, אֲפִלּוּ אִם יֵשׁ לָהֶם עֵדֵי גְּנֵיבָה וּגְזֵלָה שֶׁיְּכוֹלִים לְהוֹצִיאוֹ בְּדַיָּנִים. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמִטַּלְטְלִים; אֲבָל בְּקַרְקַע, אִם יֵשׁ לַבְּעָלִים עֵדִים שֶׁיְּכוֹלִים לְהוֹצִיאוֹ בְּדַיָּנִים, יְכוֹלִים הַבְּעָלִים לְהַקְדִּישׁוֹ:",["\u0003משלם אותה ואת כו' \u0004 הרמב\"ם ס\"ל דלידה וגיזה לא מחשב שינוי לקנות גוף הבהמ' ולא השבח ע\"י דה\"ל כשינוי החוזר דהרי חזרו להיות מעובר' וטעינ' מגיז' ומ\"ה אפי' נתעבר' אצל הגנב וגם ילד' אצלו ס\"ל להרמב\"ם דלא קנא' וכ\"כ הטו' בהדי' בשמו ומ\"ש משל' אות' ל\"ד קאמ' משלם דמשמע דנותן דמי' בעדה אלא נוטל הכבשה בעינה כיון שלא קנאה בשינוי והי\"א שכ' מור\"ם ס\"ל כשתחזר' להיו' מעוברת או טעונ' גיז' ה\"ל כפני' חדשו' ולא מיקרי שינוי החוזר אלא מחשב שינוי גמו' והשבח הוא שלו וגם הכבש' בעינ' תשאר' בידו שקנא' בהשינוי אלא שמשלם להגנב דמיה:","\u0003משלם כשעת גניב' \u0004 פי' אם הית' טעונ' קצת בשעת גניב' ונשתה' ביד הגנב עד שנתרב' בגיז' ובולד' וצ\"ל דהרמב\"ם מחלק דכל שעד יין לא גזז' וילד' דאז הבהמ' עם הגיז' והולד צריך להחזיר להנגנב והנגנב צריך ליתן להגנב דמי השבח שנשבח ביד הגנב ואם כל הגיזה נתגדלת מיום שבא ליד גנב צריך לשלם לגנב כל השבח בדמים ואם כבר ילד' אצל הגנב אזי מחזיק הגנב גם בפרה אגב ולדה והוא נותן דמי השבח כמו שהיה בשעת הגניבה להנגנב ועפר\"ד מ\"ש עוד בזה חילוקי דינים לדעת הרמב\"ם בהשביחה לאחר יאוש:","\u0003וכ\"ש אם גנב כבשה ונתעברה כו' \u0004 צ\"ע דהמחבר כתב זה בלשון כ\"ש והטו' כ' בל' \"ולא \"עוד לרבותא ע\"ש בס\"א:","\u0003ביד הגנב ולא נשתנית כו' \u0004 לדעת הרמב\"ם לא מיקרי שינוי אלא בגנב טלה ונעשה איל עגל ונעשה שור והדומה לו ולא גיזה ולידה וכמ\"ש הטור והמחבר בסי' שנ\"ג משום דא\"א לחזור לכמו' שהי':","\u0003משלם קרן כשעת גניבה כו' \u0004 דקדק לכתוב הקרן ור\"ל ולא כפל וד' וה' ולא ביאר המחבר דינם איך ישלמו וגם לא חילק בין כפל לד' וה' בהוקר או הוזל בין טביחה להעמדה בדין ובין הי' בשעת גניבה בזול והוקר בשעת העמדה בדין ולא חילק נמי בדין כפל וד' וה' בין נשבר או מתה מאליו או טבחו ומכרו משום שהן קנס ומקנס לא איירי המחבר ובטור ביאר דינם משום שיש נ\"מ אם תפס וכמ\"ש בסימנים הנ\"ל. וטעם דברים הללו הוא זה שכ' בבבא ראשונ' שצריך לשלם ד' בעד הקרן עכ\"פ לא חילק בין שברו או טובחו בידי' או נשבר מאליו משום דכל הגזלנין משלמין כשעת הגזיל' ועוד דכתיב בפ' משפטים אם המצ' תמצ' בידו הגניב' משור ועד חמור עד שה (ועד שלמה) חיים שנים ישלם ודרשי' תיבת חיים אגניב' הנזכרת אחייה להגניב' פי' שישלם להגניב' כעין שגנב. מיהו בסיפ' אם היתה בשעת גניבה בזול ואח\"כ הוקר שם מחלקינן שפיר דאם טבח או מכרו להבהמה או שבר להכלי בידים בשעת היוקר משלם הקרן כשע' היוקר משום דאז הית' התחל' הגניב' והוצאת' מהעולם דהא אי לא טבחו או שברו הי' מחזירו לבעליו בעינו אבל ברישא דהוזלה בשעה שטבחה או שבר' בידי' לא אמרינן דהתחיל הגניבה משעת טביח' דא\"כ יהא חוטא נשכר דאלו לא טבחה בידים אלא מתה מאליו הי' צריך לשלם ד' ועכשיו ששברה בידים לא ישלם אלא ב' ובשעת העמדה בדין ד' דקאמר לאו דוקא קאמר דאין ענין חיוב קרן לשעת העמדה בדין כ\"א לשעת התחלת הגניב' או לשע' הוצאתו מן העולם דהיינו בשעת טביחה או שבורה וכנ\"ל אלא לשון הגמ' נקט ומיירי כשעמד השער בשוה משעת שבירה או טביחה עד שעת העמד' בדין. ועד\"ר שכתבתי טעם למה נקט העמדה בדין בקרן:","\u0003[ובשעת העמדת הדין בדפוס יחד עם ס\"ק ה'] \u0004 דקדק לכתוב הקרן ור\"ל ולא כפל וד' וה' ולא ביאר המחבר דינם איך ישלמו וגם לא חילק בין כפל לד' וה' בהוקר או הוזל בין טביחה להעמדה בדין ובין הי' בשעת גניבה בזול והוקר בשעת העמדה בדין ולא חילק נמי בדין כפל וד' וה' בין נשבר או מתה מאליו או טבחו ומכרו משום שהן קנס ומקנס לא איירי המחבר ובטור ביאר דינם משום שיש נ\"מ אם תפס וכמ\"ש בסימנים הנ\"ל. וטעם דברים הללו הוא זה שכ' בבבא ראשונ' שצריך לשלם ד' בעד הקרן עכ\"פ לא חילק בין שברו או טובחו בידי' או נשבר מאליו משום דכל הגזלנין משלמין כשעת הגזיל' ועוד דכתיב בפ' משפטים אם המצ' תמצ' בידו הגניב' משור ועד חמור עד שה (ועד שלמה) חיים שנים ישלם ודרשי' תיבת חיים אגניב' הנזכרת אחייה להגניב' פי' שישלם להגניב' כעין שגנב. מיהו בסיפ' אם היתה בשעת גניבה בזול ואח\"כ הוקר שם מחלקינן שפיר דאם טבח או מכרו להבהמה או שבר להכלי בידים בשעת היוקר משלם הקרן כשע' היוקר משום דאז הית' התחל' הגניב' והוצאת' מהעולם דהא אי לא טבחו או שברו הי' מחזירו לבעליו בעינו אבל ברישא דהוזלה בשעה שטבחה או שבר' בידי' לא אמרינן דהתחיל הגניבה משעת טביח' דא\"כ יהא חוטא נשכר דאלו לא טבחה בידים אלא מתה מאליו הי' צריך לשלם ד' ועכשיו ששברה בידים לא ישלם אלא ב' ובשעת העמדה בדין ד' דקאמר לאו דוקא קאמר דאין ענין חיוב קרן לשעת העמדה בדין כ\"א לשעת התחלת הגניב' או לשע' הוצאתו מן העולם דהיינו בשעת טביחה או שבורה וכנ\"ל אלא לשון הגמ' נקט ומיירי כשעמד השער בשוה משעת שבירה או טביחה עד שעת העמד' בדין. ועד\"ר שכתבתי טעם למה נקט העמדה בדין בקרן:","\u0003או שבר הכלי או אבדו סתם \u0004 משום דקי\"ל סתם אבידה ה\"ל כפשיע' אם לא שכ' בצדו שנשבר \"מאליו דה\"ל כאלו כ' דידוע דנאבד שלא בפשיע' וק\"ל וע\"ל סי' שס\"ב ס\"ס י' מ\"ש שם:","\u0003גנב כחושה והשמינ' כו' \u0004 מיירי דפטמה הגנב בהוצאותיו וכמ\"ש מור\"ם ע\"ז ומשום דא\"ל הגנב אנא מפטמינא ואתה תשקול הפיטמא ואי הית' שמינ' והכחיש' אפי' מתה מעצמה מצי א\"ל הנגנב מה לי מתה כולה מה לי מתה פלגא וכל הגזלנין משלמין כשעת הגזילה:","\u0003הוי כאלו הוקרה \u0004 וכבר נתבאר דאם הוקרה ממילא ומתה מעצמה דמשלם כדמעיקרא בזול ואם שחט' בידים משלם כשעת שחיט' ביוקר וה\"נ בפיטום דממילא. זהו ביאור דברי המחבר שקיצר וכ' דין קרן ולא דין כפל וד' וה' ובע\"ש כ' ג\"כ דיני כפל וד' וה' ולקח שטה לנפשו וכ' ז\"ל מדכתיב חיים שנים ישלם דרשו אחייה לקרן כעין שגנב ר\"ל בעד הגניבה ישלם כמו שהיתה שוה בחיים כשגנב אותה ואע\"ג דעכשיו היא מתה ואינה שוה כ\"כ כמו שהיתה בחיים כשגנבה לפיכך אמרו גנב בהמה או כלים וכיוצא בזה שהיתה שוה בשעת גניב' ד' ועכשיו בשעת העמדה בדין אינו שוה אלא ב' ושחטה או מכרה או שבר הכלי בידים משלם קרן כשעת הגניבה וזהו החייהו לקרן כעין שגנב וכפל וד' וה' כשעת העמדה בדין שכן משמע קרא אשר ירשיעון אלקים ישלם שנים בשעה שמרשיעו הדיין דהיינו בגמר דין חל עליו חיוב השנים דהוא הכפל וה\"ה בד' וה' שהן קנס אבל שבר הכלי בידים שהוא הקרן אע\"פ שהוזל קודם ששברו משלם קרן כשעת הגניבה דאל\"כ יהיה חוטא נשכר ואם היתה שוה בשעת הגניבה שנים ובשעת העמדה בדין ד' אם טבח ומכר או שבר הכלי או אבדו בידים משלם קרן כשעת הגניבה וכפל וד וה' כשעת העמדה בדין ואם מתה הבהמה מאליה ואבד הכלי מאליו משלם הכל קרן וכפל וד' וה' כשעת הגניבה כיון שאינו בעין בשעת העמדה בדין עכ\"ל ע\"ש ודבריו מגומגמין טובא כי הם נגד סוגיות הגמרא דפ' מרובה (דף פ\"ה ע\"א) ונגד מ\"ש הרא\"ש שם ונגד מ\"ש הטור כאן. דשם בפ' מרובה גרסינן אמר רב קרן כעין שגנב תשלומי כפל ותשלומי ד' וה' כשעת העמדה בדין ומוקי לה הגמ' שם דמיירי דמתחלה היה שוה ד' זוז ולבסוף שוה זוז דאלו הוה איפכא הא אמר רבא האי מאן דגזל חביתא דחמרא מחברי' מעיקרא שוה זוז ולבסוף שוה ד' זוז תברה או שתיי' משלם ד' איתבר ממילא משלם זוז (וגם רב מאיתבר ממילא מיירי ע\"ש והוא מטעם שכתבתי לעיל) וכ' הרא\"ש דה\"ט דמשלם כפל וד' וה' כשעת העמדה משום דמגניב' וחיים דרשי' דוקא אחייה לקרן כעין שגנב הא כפל ד' וה' כשעת העמדה בדין דלגופיה לא אצטריך כדפרישית אלא לדיוקא ועוד דסברא הוא דקרן נתחייב כשעת (גניב' אבל כפל ד' וה' לא נתחייב עד) העמד' בדין דאי מודה מפטר ובשעת העמדה בדין דכפל כמשמעותיו בשויו עתה כשיגמר הדין אבל לענין ד' וה' שמין כמה הי' שוה בשעת טביחה ומכירה דההיא שעתא קמחייב ואם נתייקרה אחר הטביח' קודם העמד' בדין לא משלם כי השתא דאפי' קרן אם נתייקר' ואיתבר ממילא משלם כדמעיקר' כיון דהשת' לאו מידי עביד וכן אם הוזל אזלינן בתר עידן טביח' ומכיר' עכ\"ל הרא\"ש בקיצו' והביאו ג\"כ הב\"י ז\"ל וצ\"ל דמ\"ש הרא\"ש וכן אם הוזל בין טביחה ומכירה להעמד' בדין אזלינן בתר טביח' ולא אמרי' כיון דאלו הי' מודה אחר הטביחה קודם העמד' בדין הי נפטר מקנס ד' וה' ה\"ט משום דלא בכל ענין מפטר ממנו דהרי אם באו עדים והעידו על הגניב' ואח\"כ הודה על טביח' ומכיר' לא הי' נפטר מד' וה' כמו שנתבא' לעיל בסי' שמ\"ח וכדברי הרא\"ש הנ\"ל כ' הטור בסי' זה בהדי' \"והרי יש בזה שני סתירות על דברי ע\"ש הנ\"ל. הא' דמשוה דין כפל ד' וה' יחד דבשניהן חיובן הוא כשעת העמדה בדין ויליף לה מדכתי' אשר ירשיעון אלקים וכנ\"ל וז\"א דהא מבואר דברי הרא\"ש הנ\"ל והטור דאם הוקר או הוזל בין טביח' או מכיר' לשעת העמד' בדין דלענין ד' וה' אזלינן בתר שעת טביחה ומכיר' וכפל משלם כשעת העמדה בדין וכתב הטעם בצדו וכנ\"ל. השני מ\"ש דאם מתחל' הי' שוה שנים ואח\"כ ד' ואף אם שתייה או תברה בידים דמשלם הקרן כמו שהי' בתחלה וכ' עוד בס\"ד דאם גנב בהמה וכחש' או נתפטמה מאיליה דדינו כיוקרא וזולא ומשלם הקרן כשעת גניבה הרי לפנינו דס\"ל דאפי' נתפטמה מאיליה דה\"ל כהוקרה אפי' הכי כשטבח' ומכר' אינו משלם הקרן אלא כמו שהיתה תחלה בזול וזהו כנגד מימרא דרבה הנ\"ל וכל הפוסקים דסבירא להו דבכה\"ג אזלינן בתר שעה שהוציאו מן העולם בידים ומשלם קרן ארבע' גם הע\"ש עצמו כ' בסי' ש\"ס ס\"י בדין גזיל' דבכה\"ג משלם ארבע ואנן קי\"ל בכל הנהו דינא דגזיל' וגניבה שווין וגם הגמ' הנ\"ל הוכיח מדברי רבה הנ\"ל דאיירי בגזיל' על דברי רב הנ\"ל דאיירי מגניב' וכנ\"ל ש\"מ דגזילה וגניבה שווין הם גם דברי הע\"ש סותרין זא\"ז דכ' מתחלה באם הי' שוה בשעת הגניב' ארבע' ובשעת שחיט' ב' דמשלם קרן ד' שלא יהא חוטא נשכר משמע דלולי ה\"ט לא היה משלם אלא ב' כמו שהי' שוה בשעת שחיט' שמוציאו מן העולם ולא אזלינן בתר שעת גניבה ואח\"כ כ' כשהי' שוה מתחל' שנים ואח\"כ ד' ושחט' דמשלם הקרן שנים כמו שהי' בשעת הגניב' ולא אזל בתר שעת השחיט' אף דשם שייך טעמא דלא יהא חוטא נשכר ואף שהרמב\"ם פ\"א דגניב' כ' שם בדין י\"ד וז\"ל היה שוה בשעת גניבה ב' ובשעת העמד' בדין ד' ואם שחט או שבר הכלי משלם תשלומי כפל ד' וה' כשעת העמדה בדין עכ\"ל אין לדקדק מלשונו מדלא כ' שגם קרן כשעת העמד' בדין שס\"ל שמשלם קרן כשעת גניב' וז\"א דהא רבה הנ\"ל אמר דבכה\"ג משלם ארבע וא\"ל דהרמב\"ם איירי כשלא הוקרה בין שעת גניבה לשעת טביח' או שביר' אלא גם בשעת טביח' ושביר' שוה רק שנים כדמעיקרא וקודם העמד' בדין נתיקר' ומ\"ה לא כ' קרן בהדי כפל ד' וה' משום דבקרן אזלינן בתר שעה שמוציאו מן העולם ובכפל ד' וה' ס\"ל דאזלינן בתר שעת העמד' בדין שנתייקר ושוה ד' ומטעם דכ' הע\"ש הנ\"ל דילפינן מאשר ירשיעון אלקים ותאמר שבזה נתיישב ג\"כ הע\"ש הנ\"ל דג\"כ מיירי בהכי דזהו נגד סברת הרא\"ש והטור הנ\"ל וגם דרך הרמב\"ם הוא למשוך בכל דבריו אחר דברי הגמ' ואם כוונתו כמ\"ש ק' דהניח כאן דברי רבה הנ\"ל הנזכר בגמ' וכתב עניינים שלא נזכרו בגמ' כלל וגם סתם דבריו בלי טעם דה\"ל למכתב דמ\"ה בכפל ד' וה' אזלינן בתר שעת העמדה בדין דכתי' אשר ירשיעון אלקים בפרט שדין זה שישלם כפל ד' וה' בד' שבשעת גניבה ובשעת טביחה ושבירה שהוציאו מן העולם לא היה שוה אלא שנים הוא נגד הסברא והל\"ל דזה נלמד מקרא דאשר ירש עון כו' ועוד דהוא נגד הגמ' דקאמרינן שם בסוגיא דאם גנב טלה ונעשה איל וטבחו או מכרו אחר שנעשה איל דאינו חייב בד' וה' מטעם דמיד שנשתנה ונעש' איל קנאו הגנב בהשינוי והטביחה ומכירה ברשותו נעשה. ה\"נ נימא מיד שטבחו ומכרו שנשתנה מכמות שהיה עומד ברשותו ותו אף דנתיקרה ברשותו נתיקר' ולא ישלם אלא כמו שהיתה בשעת טביחה וע\"כ צ\"ל דהרמב\"ם דלא כ' קרן הוא מרוב פשיטותו וק\"ו מכפל הוא או שצריכין להגיה בדבריו ולכתוב ג\"כ קרן גם המ\"מ כ' שם על דברי הרמב\"ם ז\"ל ובכה\"ג הקרן והכפל שווין וכדמוכח התם וכ\"כ בהל' עכ\"ל הרי לפנינו דגם המ\"מ בא ללמדינו דלא תטעה בדברי הרמב\"ם לו' מדלא הזכיר קרן שדינו חלוק מדין כפל אלא דינם שוה הן וגם מה שסיים הע\"ש הנ\"ל וכ' ז\"ל ואם מתה הבהמה מאיליה ואבד הכלי מאיליו משלם הכל קרן וכפל ד' וה' כשעת הגניבה כיון שאינו בעין עכ\"ל לא דק בענינו כלל דמאחר דמת ונאבד מאליו לא שייך בזה חיוב ד' וה' כלל גם בהרמב\"ם ובטור ליתא גם מה שסיים בטעמו וכ' כיון שאינו בעין קשה מה לי אם היא בעין או לא הלא קרא דאשר ירשיעון אלקים דיליף מיניה דבכפל אזלינן בתר העמדה בדין קאי אפי' אכשאין הגניבה בעין אך כשהנגנב תבעו לשלם לו דמי גניבתו:","\u0003אין אומרים יתן לבעלים השברים כו' \u0004 אע\"ג דבנזקין אמרי' כן כמ\"ש הט\"ו בסי' שפ\"ז התם ה\"ט דכתיב והמת יהיה לו וק\"ל כמ\"ד לו לניזק וכמ\"ש שם אבל בגנב כתיב חיים שנים ישלם וכן בגזילה יתבאר בסי' שס\"ב דהדין כן משום דכתיב ביה והשיב את הגזילה אשר גזל ודרשי' כעין שגזל:","\u0003ואם רצה הבעלים כו' עד שומעין לו \u0004 המ\"מ תמה על זה וכ' וצ\"ע למה לא אמרי' שקנאה הגנב בשינוי וכ' אולי מיירי ששמו עליו פי' שלא נשבר מהכלי אלא מעט ועדיין שם הראשון נשאר ע\"ג הכלי ועמ\"ש בס\"ס שס\"ב ישוב אחר לקושיא זו דהמ\"מ:","\u0003אינם יכולים להקדישו כו' \u0004 הגנב והגזלן לפי שאינו שלו והבעל לפי שאינו ברשותו וכתיב ואיש כי יקדיש את ביתו מה ביתו ברשותו אף כל דוקא שהוא ברשותו:"],["\u0003 היתה הגניבה ביד הגנב כו'. \u0004 עיין ביש\"ש פ' הגוזל קמא סי' ד':","\u0003 כגון כבשה שהיתה מעוברת כו'. \u0004 לא ידענא מה חילוק יש בזה ס\"ס ילדה וגם על הרב המגיד קשה כן והראב\"ד לא כ' אלא דהי' אפשר לו' כן דמשלם וולדה וגיזותיה היינו כמו פרה העומדת לילד אע\"פ שקנה ומ\"מ אח\"כ חזר בו ממ\"ש הרמב\"ם גופיה לקמן בהלכות גזלה וא\"כ קשה ג\"כ על הרב המגיד שכ' שפשט הוא שכוונת הרמב\"ם בשהיתה מעוברת בשעת גניבה ואין כאן מקום להשגה עכ\"ל דהרי הרמב\"ם כתב בפ\"ג מהלכות גזלה ואע\"פ שנתעברה או נטענה ביד הגזלן הואיל ולא נתייאשו הבעלים ולא נשתנית הגזלה היא ברשות בעליה עדיין עכ\"ל וכן קשה על המחבר שכתב ג\"כ בסי' שס\"ב ס\"ח כדברי הרמב\"ם אלא נראה דגם בה' גנבה כוונת הרמב\"ם אפי' נתעברה או נטענה וכן משמע מפשט ל' הרמב\"ם דה' גנבה ע\"ש וכ\"כ הטור כאן בשמו ודברי הרב המגיד והמחבר צ\"ע:","\u0003 משלם כשעת הגנב' כו' \u0004 מיהו מ\"ש הטור בשם הרמב\"ם דהפר' והולד לגנב תמיה לי מנ\"ל הא וברמב\"ם לא משמע כן דהא כתב דגוף הבהמה לא קנה אלא בשינוי וכיון דהרמב\"ם לא חשיב ליה האי שנוי א\"כ פשיטא דצריך להחזיר גוף הפרה ודו\"ק:","\u0003 וי\"א דאפי' שבח הבאה מאליה כו'. \u0004 ל' הר\"ב מגומגם דפשיטא דאף הרב המגיד וסייעתו לא פליגי אהרמב\"ם אלא דהרמב\"ם ס\"ל דלידה וגזיזה לא הוי שינוי ולהכי צריך ג\"כ יאוש בעלים ואינהו ס\"ל דהוי שינוי אבל פשיטא בשבח דעלמא הבא מאלי' ולא נשתנית פשיטא דאינו של גנב קודם יאוש דבמאי לקני וגם הראיה שהביא הרב המגיד מפרק המפקיד שם מיירי בהדיא בשבח שנותנין [שנשתנה] כגון לידה וגזיזה ע\"ש בפרק המפקיד וצ\"ל דגם הר\"ב ה\"ק אפי' שבח הבא מאלי' כגון לידה וגזיזה חשיב שינוי והוא של הגנב אפילו קודם יאוש וכ\"כ הע\"ש וז\"ל וי\"א דאפי' שבח הבא מאליו כגון מעוברת וילדה טעונה וגזזה הוא של הגנב ואפילו קודם יאוש שקנאן בשינוי שאין לך שינוי גדול מזה מעיקרא גופא מליא והשתא גופא סריקא עכ\"ל ולפ\"ז מ\"ש הטור דהראב\"ד והרא\"ש פליגי ארמב\"ם אינו אלא במה דס\"ל דלידה וגזיזה לא הוי שינוי וכן נראה להדיא בר' ירוחם נל\"א ריש ח\"ד אבל במה דס\"ל דביאוש אפי' בלא שינוי קונה השבח דממילא ובלא יאוש לא קנה (ומיהו עדיין צ\"ע בזה בה' המ' ובש\"ס) לא אשכחן דפליגי עליה ואדרבה בהשגת הראב\"ד פ\"א דגנב' ופ\"ג דגזלה מבואר דמודים ליה בזה (עיין לקמן בטור סי' שס\"ב) דלא כהב\"ח שכתב דבתרתי פליג הרא\"ש גם דלא כסמ\"ע לקמן סי' שס\"ב ס\"ק ג' ע\"ש ודוק עיין ביש\"ש פ' הגוזל קמא ס\"ס ד' וסי' ו':","\u0003 וכ\"ש אם גנב כבשה ונתעברה כו' \u0004 צ\"ע דהמחבר כתב (צ\"ל דמור\"ם כתב זה כו') בלשון כ\"ש והטור כתב בלשון \"ולא עוד לרבותא ע\"ש בסעיף א' עכ\"ל סמ\"ע לא דק דגם בטור מבואר דכ\"ש הוא כשנתעברה ביד הגנב רק שכתב שם ולא עוד אפי' תבעוה הבעלים קודם שילדה כו' ור\"ל פשיטא תבעו אחר לידה אלא אפי' תבעו קודם לידה ומ\"מ כ\"ש היא אם נתעברה ביד גנב מגנבה מעוברת ודוק:","\u0003 הוי כאלו הוקר' \u0004 עיין בסמ\"ע ס\"ק ט' שהאריך להשיג על הע\"ש עד וזה אינו דהא מבוא' בדברי הרא\"ש כו' ע\"ש אמנם גם מהרש\"ל ביש\"ש פ\"ז דב\"ק סי' ג' פסק דלא כהרא\"ש ולעולם אפי' ד' וה' אינו משלם אלא כשעת העמדה בדין ע\"ש ועיין ע\"ש עד וכפל ד' וה' כשע' הגניב' כו' זו היא שיט' הרמב\"ם וטור בתשלומי כפל אמנם מהרש\"ל שם פסק כשיטת ר\"י בתוס' דכפל משלם כשעת בדין אפי' איתבר ממילא ע\"ש וק\"ל:","\u0003 ודוקא דאית ליה מעות כו' \u0004 (הג\"ה) לכאורה דברי הרב ק' להולמן דזו הוא שיטת הרמ\"ה שמביא בנ\"י ומביאו ג\"כ בסמ\"ע ס\"ס שס\"ב דס\"ל הא דאמרי' בש\"ס אין שמין לא לגנב ולא לגזלן היינו דאינו נותן לו השברים בשומא כמו שהיתה שוה בשעת הגניבה אבל אם רוצה ליתן לו השברים כמו שהם שוים עכשיו יכול ליתן לו וכן דעת התוס' בשם ה\"ר שמואל בפ' השואל סוף דף צ\"ו ד\"ה זיל שלים ליה כו' ע\"ש אבל לדעת רש\"י ותוס' ואשר\"י והטור קאי אשברים שאין יכול ליתן לו השברים רק הכלי שלם או דמיו לא קי\"ל כהרמ\"ה וכמבואר בנ\"י וכן משמע להדי' מדברי מהרש\"ל פ\"א דב\"ק סי' פ\"ט ועוד דלו יהא שפסק כהרמ\"ה הי' לו לפסוק שאפי' יש לו מעות יכול ליתן השברים והרמ\"ה שחילק בכך לטעמי' אזיל דס\"ל דבכל מזיקין אם יש לו מעות צריך ליתן לו מעות אבל אנן דלא קי\"ל כוותי' לקמן סי' תי\"ט דאפי' יש לו מעות נותן לו אפי' סובין וכמ\"ש מ\"ח ז\"ל לקמן סי' תי\"ט לאפוקי מדברי הרמ\"ה א\"כ ה\"ה הכא וכן משמע מדברי תוס' הנ\"ל וכמבואר להדיא בב\"י בשם הרמ\"ה דס\"ל דאין חילוק בין גנב וגזלן לשאר ניזקין רק לענין שומא ע\"ש וצ\"ל דהרב בא להוציא מדברי הרמ\"ה דהיכא דאין לו מעות וגם אין יכול ליתן לו הכלי שלם וזה רוצ' ליקח מטלטלין שבזה גם רש\"י וסייעתו מודי' שיכול ליתן לו השברים בתוך שאר מטלטלים כמבוא' בהרמ\"ה דלא גרע שברים אלו משאר מטלטלין וזה פשוט ודוק:","\u0003 שומעין להן \u0004 עיין בסמ\"ע מ\"ש בשם המ\"מ ומהרש\"ל פ\"ק דב\"ק סי' כ\"ט שדחה זה ע\"ש וצ\"ע:"]],["הַגּוֹנֵב חֵפֶץ מִבֵּית חֲבֵרוֹ וְהֶחֱזִירוֹ לִמְקוֹמוֹ, וְלֹא יָדְעוּ הַבְּעָלִים שֶׁהֶחֱזִירוֹ, אִם יָדְעוּ הַבְּעָלִים שֶׁנִּגְנַב מֵהֶם, אַף עַל פִּי שֶׁהֶחֱזִירוֹ \u0010y0\u0011 הַגַּנָּב, לֹא נִפְטַר, וְהוּא בְּאַחֲרָיוּתוֹ עַד שֶׁיֵּדְעוּ הַבְּעָלִים, כְּגוֹן שֶׁיִּמְנֶה חֲפָצָיו וְיִמְצָאֵם שְׁלֵמִים. וּמִיהוּ, כְּשֶׁמְּנָאָם נִפְטַר אַף עַל פִּי שֶׁלֹּא יָדְעוּ הַבְּעָלִים בְּשָׁעָה שֶׁהֶחֱזִירוֹ. לְפִיכָךְ, גָּנַב לוֹ מָעוֹת וְהִבְלִיעַ לוֹ בְּחֶשְׁבּוֹן \u0010y1\u0011 וּנְתָנָם לְתוֹךְ כִּיסוֹ, אִם יוֹדֵעַ מִנְיַן הַמָּעוֹת שֶׁלּוֹ, יָצָא, שֶׁאָדָם עָשׂוּי לְמַשְׁמֵשׁ בּוֹ בְּכָל שָׁעָה וַהֲרֵי מָצָא שֶׁהֶחֱזִיר לוֹ בִּכְלַל מָעוֹתָיו. אֲבָל אִם זְרָקָן לְכִיסוֹ שֶׁאֵין בּוֹ כְּלוּם, לֹא יָצָא, וְחַיָּב בְּאַחֲרָיוּת הַגְּזֵלָה עַד שֶׁיּוֹדִיעֶנּוּ שֶׁהֶחֱזִיר לְכִיס פְּלוֹנִי. וְאִם לֹא יָדְעוּ הַבְּעָלִים שֶׁנִּגְנַב מֵהֶם, מִיָּד כְּשֶׁהֶחֱזִירָם לִמְקוֹמָם יָצָא אַף עַל פִּי שֶׁלֹּא מְנָאוּם הַבְּעָלִים. \u0010y2\u0011\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּדָבָר שֶׁאֵין בּוֹ רוּחַ חַיִּים. אֲבָל הַגּוֹנֵב טָלֶה מִן הָעֵדֶר, וְיָדְעוּ בוֹ הַבְּעָלִים, וְהֶחֱזִירוֹ לָעֵדֶר שֶׁלֹּא מִדַּעַת בְּעָלִים, וּמֵת אוֹ נִגְנַב, חַיָּב בְּאַחֲרָיוּתוֹ. \u0010y3\u0011 וְאִם מָנוּ אֶת הַצֹּאן וְהִיא שְׁלֵמָה, פָּטוּר. וְאִם לֹא יָדְעוּ הַבְּעָלִים לֹא בִגְנֵבָתוֹ וְלֹא בַחֲזָרָתוֹ, אַף עַל פִּי שֶׁמָּנוּ אֶת הַצֹּאן וְהִיא שְׁלֵמָה, חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיּוֹדִיעַ אֶת הַבְּעָלִים כְּדֵי שֶׁיִּשְׁמְרוּ אֶת הַטָּלֶה הַגָּנוּב; שֶׁהֲרֵי לִמְּדוֹ דֶּרֶךְ אַחֶרֶת חוּץ מִדֶּרֶךְ שְׁאָר הַצֹּאן שֶׁבְּעֵדֶר זֶה.\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּפְטָר כְּשֶׁמַּחֲזִיר לִמְקוֹמוֹ, בְּגַנָּב הַגּוֹנֵב מִבֵּית הַבְּעָלִים. \u0010y4\u0011 אֲבָל שׁוֹמֵר שֶׁגָּנַב מֵרְשׁוּת עַצְמוֹ, כְּגוֹן שֶׁהֻפְקַד אִתּוֹ כִּיס אוֹ טָלֶה \u0010y5\u0011 \u0010c0\u0011 וְיֵשׁ עֵדִים שֶׁגָּנְבוֹ, אַף עַל פִּי שֶׁיֵּשׁ עֵדִים שֶׁהֶחֱזִירוֹ לִמְקוֹמוֹ חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיּוֹדִיעַ לַבְּעָלִים; שֶׁהֲרֵי כָּלְתָה שְׁמִירָתוֹ וְאֵינוֹ עוֹד שׁוֹמֵר עָלָיו, וַהֲרֵי הוּא כְּאִלּוּ לֹא הֶחֱזִירוֹ עַד שֶׁיּוֹדִיעַ לַבְּעָלִים:",["\u0003הגנב לא נפטר כו' \u0004 דלא הוה השבה מעליא דכיון דידעו הבעלים שנגנב' נתייאשו מלשומר' עוד ואף שהחזירה הא לא ידע הבעל מזה שישמרנו:","\u0003ונתנם לתוך כיסו אם יודע כו' \u0004 כן הוא ל' הטור והרא\"ש שאפי' החזירו לכיסו שיש לו בה מעות לא נפטר עד שידע כמה מעות הי' בו כבר נמצא כשימשמש בה ידע שהוחזר לו הגניב' שהרי יש בו מותר אבל הרי\"ף והרמב\"ם ס\"ל דמהני כשנתן המעו' לכיסו שיש בו מעו' דמסתמ' אדם יודע כמה יש לו מעו' כיון דרגיל למשמש בכיסו תמיד והביאו הב\"י וד\"מ דעתם וכ' שכן עיקר וכן הוא מדויק ממ\"ש המחבר אח\"ז שכ' ז\"ל אבל אם זרקן לכיסו שאין בו כלום לא יצא כו' משמע הא יש בו מעו' יצא בחזרתו אפי' מסתמ' והיינו כמ\"ש והמחבר נקט בריש' ל' הטור ובסיפא ל' הרי\"ף והרמב\"ם דאלו הטור כ' בסיפא ז\"ל אבל אם זרקן לתיבתו (ר\"ל אפי' יודע מנין המעות שבו כיון שאין אדם עשוי למשמש בה) או לכיסו שלא ידע מנין המעות שהי' לו לא יצא כו' הרי דכ' גם בסיפ' דאף דיש בו מעות כל שלא ידע בו לא יצא והיינו לשיטתו הנ\"ל וצ\"ע מ\"ש עוד מזה:","\u0003במד\"א כו' אבל הגונב טלה כו' \u0004 דין טלה לא נשתנ' מדין גונב מעו' הנ\"ל כ\"א בלא ידעו הבעלי' לא מהגניב' ולא מהחזר' שבשאר דברי' שאין בהן רוח חיים נפטר מיד בהחזר' מה שא\"כ בדברי' שיש בהן רוח חיים משום דאנקט' להו נגרי ברייתא וכדמסיק המחבר בטעמו וק\"ל:","\u0003ואם מנו את הצאן כו' \u0004 דכיון דידעו מהגניבה ידעו שלמדו לילך דרך אחר וישמרנו שמירה מעליא יותר משאר הצאן (הג\"ה בב\"י יש מי שכ' שאם הי' הטל' שגנב נקוד וטלוא ואין כמותו בעדר אם ידעו הבעלים בגניבתו והחזירו לעדר אע\"פ שלא מנו הצאן פטור שהרי הוא ניכר כו' עכ\"ל ע\"ש שהאריך ד\"מ ב'):","\u0003אבל שומר שגנב מרשות עצמו כו' \u0004 פי' אף שגנב דבר שאין בו רוח חיים דגם בגנב בדבר שיש בו רוח חיים אין שייך טעם דלמדו דרך אחרת שכיון שהחזירו למקומו והוא ידע שגנבה ישמרנו מעצמו טובא שלא ילך בדרך אחרת ויתאבד מ\"ה הוצרך גם בטלה לטעם אחר והוא כיון דגנבו מסתמא לא ניחא לבעל הבהמ' שיהא הוא שומר עלי שאינו נאמן בעיניו נמצא אף שמחזיר' למקומ' לא מיחשב חזרה:","\u0003ויש עדים שגנבו כו' \u0004 בפריש' כתבתי דמש\"ה דקדקו הרמב\"ם והטור וכתבו שיש עדים כו' דאי לאו הכי כיון שהחזיר הגניב' מעצמו הרי ראינו שעשה תשובה ולא היינו אומרים שלא ניחא לבעלים להיות שומר עליה עוד משא\"כ כשראו עדים שנגנב' אמרי' דהחזירו מיראת העדים ובזה נסתלקה תמיהת בעל ש\"ג וכמ\"ש בפריש' ע\"ש:"],["\u0003 ויש עדים שגנבו כו'. \u0004 בפריש' כתבתי דמ\"ה דקדקו הרמב\"ם והטור וכתבו שיש עדים כו' דאל\"ה כיון שהחזיר הגניבה מעצמו הרי ראינו שעשה תשוב' ולא היינו אומרים שלא ניחא ליה לבעלים להיו' שומר עלי' וכו' עכ\"ל סמ\"ע וכ\"כ הב\"ח ולפע\"ד הא דנקטו עדים היינו לאפוקי שאלו כופר שלא גנב או משום סיפא לאשמועי' רבותא דאע\"ג דאיכא עדים שהחזירו חייב וברמב\"ם פשיט' דלא נקט עדים אלא לו' דחייב בכפל ע\"ש מוכח כן להדיא אבל באמת ה\"ה במודה שגנבו דדינו כיש עדים לענין דחייב באחריותו עד שיודיע לבעלים ויש להוכיח קצת כן מדהוצרך בפרק המפקיד (בבא מציעא דף מ\"א) לאוקמי מתני' רישא ר\"י וסיפא ר\"ע ולא אוקמא כולה כר\"ע ורישא דליכא עדים וסיפא דאיכא עדים ע\"ש ודוק. וגם שאר כל הפוסקים כתבו בסתמא דצריך דעת בעלים ולא הזכירו עדים וקושית הש\"ג מעיקר' לאו קושיא היא דכיון דמיד שגנב כלתה ליה שמירתו ואינו עוד שומר עליו א\"כ מה בכך שיעשה אח\"כ תשובה מ\"מ צריך להחזירו ליד הבעלים עצמו כיון דכלתה שמירתו ודוק שוב ראיתי במע\"מ כ' כה\"ג ע\"ש:"]],["\u0010c0\u0011 אָסוּר לִקְנוֹת מֵהַגַּנָּב הַחֵפֶץ שֶׁגָּנַב, וְעָוֹן גָּדוֹל הוּא, \u0010y0\u0011 שֶׁהֲרֵי מַחֲזִיק יְדֵי עוֹבְרֵי עֲבֵרָה וְגוֹרֵם לוֹ לִגְנֹב גְּנֵבוֹת אֲחֵרוֹת; \u0010y1\u0011 שֶׁאִם לֹא יִמְצָא לוֹקֵחַ, אֵינוֹ גּוֹנֵב. \u0010y2\u0011 \u0005(וְכֵן אָסוּר לְסַיֵּעַ לַגַּנָב בְּשׁוּם דָּבָר כְּדֵי שֶׁיִּגְנֹב (בֵּית יוֹסֵף בְּשֵׁם רִיבָ\"שׁ סִימָן ק\"ח)\u0006.\nהַגּוֹנֵב וּמָכַר \u0010c1\u0011 וְלֹא נִתְיָאֲשׁוּ הַבְּעָלִים \u0005וְע\"ל סִימָן שס\"ח,\u0006 \u0010y3\u0011 וְאַחַר כָּךְ הֻכַּר הַגַּנָּב וּבָאוּ עֵדִים שֶׁזֶּה הַחֵפֶץ שֶׁמָּכַר פְּלוֹנִי \u0010c2\u0011 הוּא גָּנְבוֹ בְּפָנֵינוּ, חוֹזֵר הַחֵפֶץ לַבְּעָלִים וְהַבְּעָלִים נוֹתְנִים לַלּוֹקֵחַ דָּמִים שֶׁנָּתַן לַגַּנָב, \u0010y4\u0011 \u0010c3\u0011 מִפְּנֵי תַּקָּנַת הַשּׁוּק, וְהַבְּעָלִים חוֹזְרִים וְעוֹשִׂים דִּין עִם הַגַּנָּב. \u0010y5\u0011 \u0010c4\u0011 וְאִם גַּנָּב מְפֻרְסָם הוּא, לֹא עָשׂוּ בּוֹ תַּקָּנַת הַשּׁוּק \u0005(טוּר ס\"ד בְּשֵׁם רִי\"ף וְרַמְבַּ\"ם)\u0006, וְאֵין הַבְּעָלִים נוֹתְנִים לַלּוֹקֵחַ כְּלוּם, אֶלָּא חוֹזֵר הַלּוֹקֵחַ וְעוֹשֶׂה דִּין עִם הַגַּנָּב וּמוֹצִיא מִמֶּנּוּ דָּמִים שֶׁנָּתַן לוֹ. \u0005הַגָּה: \u0010y6\u0011 \u0010c5\u0011 וְיֵשׁ אוֹמְרִים דְּאַף בְּגַנָּב מְפֻרְסָם עָשׂוּ תַּקָּנַת הַשּׁוּק וְצָרִיךְ לְהַחֲזִיר לַלּוֹקֵחַ מָעוֹתָיו, אֶלָּא אִם כֵּן יָדַע הַלּוֹקֵחַ \u0010y7\u0011 שֶׁזֶּה הַדָּבָר שֶׁקָּנָה גָּנוּב, שֶׁאָז צָרִיךְ לְהַחֲזִיר בְּלֹא דָּמִים (טוּר בְּשֵׁם הָרֹא\"שׁ וְר\"י)\u0006. \u0010y8\u0011 \u0010c6\u0011 וַאֲפִלּוּ הַגַּנָּב \u0005(אֵין צָרִיךְ)\u0006 לְהַחֲזִיר לוֹ מָעוֹתָיו, \u0010y9\u0011 דְּוַדַּאי נָתַן לוֹ לְשֵׁם מַתָּנָה, הוֹאִיל וְיָדַע שֶׁאֵינוֹ שֶׁלּוֹ וּקְנָאָהּ \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010c7\u0011 וְאִם אָמַר הַלּוֹקֵחַ: לְטוֹבָה נִתְכַּוַּנְתִּי, נֶאֱמָן וְצָרִיךְ לְהַחֲזִיר לוֹ מָעוֹתָיו אֲפִלּוּ בְּגַנָּב מְפֻרְסָם, לְכֻלֵּי עָלְמָא \u0005(מָרְדְּכַי וְתוֹסָפוֹת פֶּרֶק הַנַּ\"ל וְהַגָּהוֹת מַיְמוֹנִי פ\"ה דִּגְּנֵבָה)\u0006.\nנִתְיָאֲשׁוּ הַבְּעָלִים מֵהַגְּנֵבָה, בֵּין שֶׁנִּתְיָאֲשׁוּ וְאַחַר כָּךְ מָכַר, בֵּין שֶׁנִּתְיָאֲשׁוּ אַחַר שֶׁמָּכַר, קָנָה לוֹקֵחַ בְּיֵאוּשׁ וְשִׁנּוּי \u0005(רְשׁוּת)\u0006 \u0005וְיֵשׁ אוֹמְרִים דְּאִם נִתְיָאֵשׁ לְאַחַר שֶׁמָּכַר לֹא קָנָה לוֹקֵחַ, דְּאֵין יֵאוּשׁ וְשִׁנּוּי רְשׁוּת קוֹנֶה אֶלָּא\u0006 \u0005(אִם)\u0006 \u0005נִתְיָאֵשׁ קֹדֶם שֶׁמָּכַר\u0006 \u0005(טוּר סִימָן שנ\"ג בְּשֵׁם הָרֹא\"שׁ)\u0006, \u0005וְכֵן נִרְאֶה לִי לְהוֹרוֹת,\u0006 \u0005(וְע\"ל סִימָן שס\"ג)\u0006 וְאֵינוֹ מַחֲזִיר הַגְּנֵבָה עַצְמָהּ לִבְעָלֶיהָ, אֶלָּא נוֹתֵן לָהֶם הַדָּמִים \u0010y10\u0011 אִם לָקַח מִגַּנָּב מְפֻרְסָם; אוֹ אֵינוֹ נוֹתֵן כְּלָל, לֹא חֵפֶץ וְלֹא דָּמִים, אִם לֹא הָיָה זֶה הַמּוֹכֵר גַּנָּב מְפֻרְסָם. \u0005הַגָּה: פֵּרוּשׁ, דַּהֲרֵי הַבְּעָלִים צְרִיכִין לִתֵּן לַלּוֹקֵחַ דְּמֵי הַמִּקָּח מִשּׁוּם תַּקָּנַת הַשּׁוּק, וְלָכֵן הַמּוֹתָר מִדְּמֵי הַמִּקָּח צָרִיךְ לִתֵּן לוֹ לְפִי סְבָרָא זוֹ, \u0010y11\u0011 אֶלָּא דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּיֵאוּשׁ וְשִׁנּוּי רְשׁוּת קוֹנֶה לְגַמְרֵי \u0010y12\u0011 וְאֵין צָרִיךְ לִתֵּן לוֹ אֲפִלּוּ הַדָּמִים. וְע\"ל סִימָן שנ\"ג:\u0006\nבִּזְמַן שֶׁהַלּוֹקֵחַ עוֹשֶׂה דִּין עִם בַּעַל הַבַּיִת, אִם אֵין עֵדִים בְּכַמָּה קָנָה, \u0010y13\u0011 נִשְׁבָּע הַלּוֹקֵחַ בִּנְקִיטַת חֵפֶץ בְּכַמָּה לָקַח, וְנוֹטֵל מֵהַבְּעָלִים.\nבִּזְמַן שֶׁהַלּוֹקֵחַ עוֹשֶׂה דִּין עִם הַגַּנָּב, וְהוּא אוֹמֵר: בְּכָךְ וְכָךְ לָקַחְתִּי מִמְּךָ, וְהוּא אוֹמֵר: לֹא מָכַרְתִּי לְךָ אֶלָּא בְּפָחוֹת מִזֶּה, הַלּוֹקֵחַ נִשְׁבָּע בִּנְקִיטַת חֵפֶץ, \u0010y14\u0011 וְנוֹטֵל מֵהַגַּנָּב.\nגָּנַב וּפָרַע בְּחוֹבוֹ, גָּנַב \u0010y15\u0011 וּפָרַע \u0010y16\u0011 בְּהֶקֵּפוֹ, אֵין בְּזֶה תַּקָּנַת הַשּׁוּק, אֶלָּא הַבְּעָלִים נוֹטְלִים הַגְּנֵבָה בְּלֹא דָּמִים וְיִשָּׁאֵר חוֹב אֵלּוּ עַל הַגַּנָּב, כְּמוֹ שֶׁהָיָה.\nמִשְׁכֵּן הַגְּנֵיבָה, \u0010y17\u0011 בֵּין שֶׁמִּשְׁכְּנָהּ יֶתֶר עַל דָּמֶיהָ אוֹ בְּפָחוֹת מִדָּמֶיהָ, הַבְּעָלִים נוֹתְנִים \u0010c8\u0011 לְבַעַל הַמַּשְׁכּוֹן \u0005מָעוֹתָיו\u0006 וְחוֹזְרִים וְעוֹשִׂים דִּין עִם הַגַּנָּב, \u0010y18\u0011 אֶלָּא אִם כֵּן הָיָה גַּנָּב מְפֻרְסָם, כְּמוֹ שֶׁנִּתְבָּאֵר. \u0005הַגָּה: וְכֵן אֻמָּן שֶׁנּוֹתְנִין לוֹ כֵּלִים לְתַקֵּן, וְהִשְׁכִּינָם, \u0010y19\u0011 צְרִיכִין הַבְּעָלִים לִתֵּן לוֹ מָעוֹתָיו אֲבָל לֹא הָרִבִּית שֶׁעוֹלָה עָלָיו, דְּלָא עָשׂוּ תַקָּנַת הַשּׁוּק עַל הָרִבִּית. וַאֲפִלּוּ לְמָאן דְּאָמַר: אֻמָּן קוֹנֶה בִּשְׁבַח כְּלִי, לֹא נֹאמַר דַּהֲרֵי הוּא שֶׁל אֻמָּן וְלֹא שֶׁל בְּעָלִים, דְּמִכָּל מָקוֹם צָרִיךְ לְהַחֲזִירוֹ לַבְּעָלִים מִכֹּחַ דִּינָא דְּמַלְכוּתָא, \u0010c9\u0011 דְּהָכִי נְהִיגֵי עַכְשָׁיו לְהַחֲזִיר כָּל גְּנֵבָה אֲפִלּוּ לְאַחַר יֵאוּשׁ וְשִׁנּוּי רְשׁוּת מִכֹּחַ דִּינָא דְּמַלְכוּתָא, (וְע\"ל סִימָן ש\"ו ס\"ב)\u0006 וּבְמָקוֹם שֶׁנָּהֲגוּ שֶׁיִּתֵּן לוֹ הָרִבִּית, צָרִיךְ לִתֵּן לוֹ גַּם הָרִבִּית \u0005(תְּרוּמַת הַדֶּשֶׁן סִימָן ש\"ט, וְעי' (שָׁם)\u0006 סִימָן קל\"ו) וְעַיֵּן לְקַמָּן סִימָן שס\"ח.\nהַלּוֹקֵחַ מִגַּנָּב שֶׁאֵינוֹ \u0010y20\u0011 מְפֻרְסָם, בֵּין שֶׁלָּקַח מִמֶּנּוּ שְׁוֵה מֵאָה בְּמָאתַיִם אוֹ שְׁוֵה מָאתַיִם בְּמֵאָה, הֲרֵי זֶה נוֹטֵל הַדָּמִים מִבַּעַל הַבַּיִת וְאַחַר כָּךְ מַחֲזִיר הַגְּנֵבָה, מִפְּנֵי תַּקָּנַת הַשּׁוּק, כְּמוֹ שֶׁנִּתְבָּאֵר:\nהָיָה נוֹשֶׁה בְּגַנָּב מֵאָה זוּז, וְגָנַב וְהֵבִיא לְבַעַל חוֹבוֹ, וְנָתַן לוֹ מֵאָה אֲחֵרִים, הֲרֵי הַגְּנֵבָה חוֹזֶרֶת לִבְעָלֶיהָ, וְאוֹמְרִים \u0005לוֹ:\u0006 לֵךְ וּתְבַע הַגַּנָּב בְּמָאתַיִם, שֶׁלֹּא נָתַתָּ לוֹ הַמֵּאָה הָאֲחֵרִים מִפְּנֵי הַחֵפֶץ שֶׁהֵבִיא לְךָ בִּלְבַד, כְּשֵׁם שֶׁהֶאֱמַנְתּוֹ בָּרִאשׁוֹנָה, הֶאֱמַנְתּוֹ בָּאַחֲרוֹנָה. וְהָנֵי מִלֵּי כְּשֶׁנָּתַן לוֹ הַחֵפֶץ סְתָם, אֲבָל אִם פֵּרַשׁ וְאָמַר: הַלְוֵנִי עַל חֵפֶץ זֶה מָנֶה, וַדַּאי זוֹ הִיא מַשְׁכּוֹנָא שֶׁעָשׂוּ בָּהּ תַּקָּנַת הַשּׁוּק, \u0010c10\u0011 וְיַחֲרִימוּ סְתָם שֶׁכָּךְ הָיָה.\nלָקַח מִגַּנָּב שֶׁאֵינוֹ מְפֻרְסָם, בְּמֵאָה, וּמָכַר לְאַחֵר בְּמֵאָה וְעֶשְׂרִים, וְהֻכַּר הַגַּנָּב, בַּעַל הַגְּנֵבָה נוֹתֵן לְזֶה הָאַחֲרוֹן מֵאָה וְעֶשְׂרִים, וְנוֹטֵל גְּנֵבָתוֹ, וְחוֹזֵר הַבַּעַל וְנוֹטֵל מֵהַמּוֹכֵר עֶשְׂרִים שֶׁהִרְוִיחַ, וְנוֹטֵל הַמֵּאָה מֵהַגַּנָּב. וְאִם גַּנָּב מְפֻרְסָם הוּא, \u0010c11\u0011 \u0010c12\u0011 נוֹטֵל \u0010y21\u0011 הַמֵּאָה וְעֶשְׂרִים מֵהַתַּגָּר שֶׁלָּקַח מֵהַגַּנָּב, וְהוֹלֵךְ הַתַּגָּר וְתוֹבֵעַ הַגַּנָּב בְּמֵאָה שֶׁל קֶרֶן. וְהוּא הַדִּין אִם מָכַר הַשֵּׁנִי לַשְּׁלִישִׁי וְהַשְּׁלִישִׁי לָרְבִיעִי, אֲפִלּוּ מֵאָה, שֶׁהוּא נוֹטֵל מִכָּל אֶחָד וְאֶחָד מַה שֶּׁנִּשְׂכַּר, וְנוֹטֵל הַקֶּרֶן מֵהַגַּנָּב. וְכָל הַדְּבָרִים הָאֵלוּ לִפְנֵי יֵאוּשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר. \u0005הַגָּה: יִשְׂרָאֵל שֶׁקָּנָה מִן הַגַּנָּב וּמְכָרוֹ לְיִשְׂרָאֵל אַחֵר, וּבָא גּוֹי וְאָמַר שֶׁנִּגְנַב מִמֶּנּוּ, וְהוֹצִיאוֹ מִלּוֹקֵחַ שֵׁנִי בְּדִינֵיהֶם, אִם הַגַּנָּב מְפֻרְסָם צָרִיךְ הַיִּשְׂרָאֵל רִאשׁוֹן לְהַחֲזִיר לַשֵּׁנִי מָעוֹתָיו; וְאִם אֵינוֹ מְפֻרְסָם, אֵין צָרִיךְ לְהַחֲזִיר לַשֵּׁנִי מָעוֹתָיו, \u0010y22\u0011 דְּיָכוֹל לוֹמַר: שֶׁמָּא הַגּוֹי מְשַׁקֵּר (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. וְעַיֵּן לְעֵיל סִימָן רכ\"ד.",["\u0003שהרי מחזיק ידי עוברי עביר' \u0004 בגמ' אמרו משל ע\"ז דאמרו אינשי לא עכברא גנב אלא חורא גנב:","\u0003שאם לא ימצא לוקח אינו גונב \u0004 אע\"ג דאפש' לגנב להוליכו במקום אחר שלא יכירו אותו שהוא גנב מ\"מ לא יהיו מצוי' לגנוב וה\"ק כשלא ימצא לוקח מהגנב ודאי לא היו גונבים מ\"ה כל אדם יחדל מלקנו' כדי שלא יהא רגיל לגנוב ועפ\"ר:","\u0003וכן אסור לסייע כו' \u0004 רומז למ\"ש הריב\"ש סי' ק\"ח דכ' ז\"ל אותו נפח שעשה לאשת ראובן שני מפתחו' בהסתר פני' מבעלם ונתנה לו שכר הרבה עבורם ראוי לעונשו על בלי הגיד לבעל' שכבר היה לו להבין שלא על חנם רבתה במחיר שני המפתחות אלא שהיתה כוונתה לגנוב מנכסי בעלה וסייע בגניבת' כו':","\u0003ואח\"כ הוכר הגנב \u0004 לרבות' כ\"כ דאע\"ג דהוכר הגנב לא אמרי' דיחזירנו הלוקח להבעלים בלא דמים ויוציא מעותיו מהגנב וכ\"ש אם לא הוכר הגנב ועפ\"ר:","\u0003מפני תקנ' השוק \u0004 פי' מפני שקנאו בפרהסי' בשוק ואם לא יחזירו לו דמים נמצא שלא יקנה אדם מחבירו דבר מחשש שמא גנובה הוא ויוציאנ' מידו בלא דמים:","\u0003ואם גנב מפורסם כו' דלא הי' לו לקנות ממנו דבר דמסתמא הנמצא בידו גנוב הוא:\u0004","\u0003דאף בגנב מפורסם כו' בדרישה כתבתי דפליגי בגרסת הטור בגמ' ונוסחה ופירוש' ע\"ש:\u0004","\u0003שזה החפץ שמוכר פלוני הוא גנבו \u0004 פי' פלוני זה שמכרו לו הוא עצמו גנבו ומכר לו הכלי שגנב:","\u0003ואפי' הגנב רוצ' כו' \u0004 כן הוא בס\"י וט\"ס הוא וה\"ג ואפי' הגנב א\"צ להחזיר וכן מצאתי כתוב בהגהות מור\"ם ז\"ל שהועתק מכתיבת ידו:","\u0003דודאי נתן לו לשם מתנה \u0004 וכיוצא בזה איתא בגמ' וטור והמחבר הביאו לקמן סי' שע\"ג בקנה שדה מגזלן ע\"ש:","\u0003אם לקח מגנב מפורסם \u0004 הרמב\"ם לטעמי' אזיל דס\"ל דלא עשו תקנת השוק בגנב מפורסם וס\"ל נמי דאין יאוש ושינוי רשות קונה לגמרי כ\"א שא\"צ להחזיר הגניבה בעינ' אבל דמי שווי' צריך הלוקח ליתן לבעלי' אבל בקנה מגנב שאינו מפורסם דאז אף אם לא נתייאשו הבעלי' צריכין הבעלי' עכ\"פ להחזיר להלוקח מה שנתן להגנב בעדה השת' שנתייאש וקנה גוף הבהמה ביאוש ושינוי רשות אף דמי הגניב' א\"צ הלוקח ליתן להבעלים דהרי הבעלים היו צריכין ליתן לו דמי שויו וכדמסיק מור\"ם בטעמא ומסיק נמי וכ' וז\"ל ולכן המותר מדמי' כו' ור\"ל כיון דמן הדין על הלוקח להחזיר לבעל הגניבה דמי שוויה אלא מפני שעל בעלים ליתן להלוקח מה שנתן להגנב א\"צ ליתן להלוקח דמי שויו הלכך כל היתרון בדמי שויו על דמי לקיחתו צריך הלוקח ליתן להבעל ומור\"ם כתב בד\"מ סברא זו כדי לישב נוסחא דהרמב\"ם הכתובה בכל ספרי הטור בשם הרמב\"ם והב\"י כ' עלי' שהיא נוסחא משובשת וכ' הנוסחא בע\"א וע\"פ אותו נוסח כתב המחבר ג\"כ כאן סתם דבקונה מגנב שאינו מפורסם אינו מחזיר כלל ולא הזכיר דעליו ליתן להנגנב המותר ממה שנתן הוא בעדו אלא שמור\"ם מאהבת הקיצור כ' סברתו אדברי המחבר מאחר די\"ל דגם הב\"י והמחבר מודים לזה לדינא אלא שהם מיירי בלוקח שלא קנה אותו בזול בפחות משויו ובפרישה כתבתי שבסברא זו שכ' מור\"ם שיחזיר המותר מיושבים כמה קושיות בטור ובדברי הרמב\"ם ע\"ש:","\u0003ומ\"ש מור\"ם אלא דיש חולקים כו' \u0004 הוא דעת ר\"י והרא\"ש הנ\"ל בטור ובהמחבר בס\"ס שנ\"ג וגם בסי' זה כתבם הטור:","\u0003וא\"צ ליתן לו אפילו הדמים \u0004 פי' בין קנה מגנב מפורסם או אינו מפורס' כיון דנתייאש קודם שלקחה דה\"ל יאוש ואח\"כ שינוי רשות אפילו שוה החפץ יותר הרבה מהדמים שנתן להגנב א\"צ ליתן לבעל החפץ כלום שקנהו לגמרי:","\u0003נשבע הלוקח כו' \u0004 שכיון שהוא מוחזק הר\"ז נשבע ונוטל:","\u0003ונוטל מהגנב אף ע\"ג דטוען ברי מ\"מ כיון דכל גנב חשוד הוא על השבועה כמ\"ש בטור ובדברי המחבר לעיל סי' צ\"ב מ\"ה אינו נשבע על מה שאומר ונפטר:\u0004","\u0003ופרע בהקיפו \u0004 פי' שלקח קודם לכן מחנוני א' בהקפה כמה ענינים ועתה נותן לו גניבה זו בהקפתו:","\u0003אין בזה תקנת השוק \u0004 דלא תקנו אלא היכא שנתן לו עתה בשעה שבא לידו דמים בעדו מה שאין כן זה דאמרינן כמו שהאמינו כבר יאמינו גם עתה:","\u0003בין שמשכנו יותר על דמיה \u0004 פי' ואין דרך העולם להלוות על משכון יותר על דמיה כיון דאסור להשתמש בו דנימא חביב היה עליו כמו במכר בסעיף שאחר זה מ\"מ כיון דעכשיו בשעה שבא לידו נתן לו הדמים אמרי' שלא נתן לו באמנה אלא מפני שידע בו שלא יניח המשכון ויפדהו ושייך בו תק\"ה שלא ימנעו בני אדם להלוות זה לזה:","\u0003אלא א\"כ הי' גנב מפורסם \u0004 כמו שנתבאר פי' בס\"ב נתבאר זה ושם כ' מור\"ם די\"א דגם בגנב מפורסם עשו תק\"ה אא\"כ ידע שזה החפץ גנוב הוא ע\"ש:","\u0003צריכים הבעלים כו' \u0004 וכ' במשרים נתיב כ\"ג ח\"ו ז\"ל אשה שלותה על משכנות שהיו של בעלה שלא מדעתו לא קנאם המלוה ומחזיר לבעלים בלא דמים ולא שייך הכא תקנת השוק ודוקא שלא ידע הבעל שמשכנה אותם אבל אם משכנם בידיעת הבעל אימר נתרצה ודוקא בידוע שהוא משל בעל כו' ע\"ש שהאריך בדין אשה שנושא' ונותנת בתוך הבית וד\"מ סימן שמ\"ח סי\"ג הביאו ע\"ש:","\u0003בין שלקח ממנו שוה מאה במאתים \u0004 ולא אמרי' דבמתנה נתן לו כיון דנתן לו כ\"כ הרבה וכן בלקח שוה מאתים במאה לא אמרי' שהבין שגנוב הוא בידו כיון דזבנו כ\"כ בזול אלא כיון דדרך העולם הוא לפעמים כשאדם צריך למעות מוזיל במכירתו או כשצריך לחפץ כזה מוסיף טובא על דמי שוויו מ\"ה עשו בו תקנת השוק:","\u0003נוטל המאה ועשרים מהתגר \u0004 ס\"ל דבעל הגניבה עכ\"פ צריך ליתן לשמעון לוקח הב' ק\"ך זהובים מפני תק\"ה דהא לא ידע שראובן לוקח הראשון קנהו מהגנב מפורסם וחוזר ונוטל כל הק\"ך זהובים מראובן שהוא ידע שגנב מפורסם הוא ועיין בטור שלא כ\"כ אלא כתבו בסוף סימן זה שבזה בעל החפץ נוטל מהלוקח שני בלא דמים והוא נוטל מלוקח ראשון כל הדמים שנתן לו ולוקח ראשון עושה דין עם הגנב במה שנתן לו עכ\"ל ובפרישה כתבתי טעם לדבריו כיון דמן הדין אין צריך להחזיר להלוקח דמיו אפילו בלוקח מגנב שאינו מפורסם אלא מפני תק\"ה מחזירין ובכה\"ג לא תקנוהו ובפרט כיון שהוכר הגנב ויכול הלוקח להוציא מידו מה שנתן לו:","\u0003שיכול לומר שמא העכו\"ם משקר אבל אם הוא גנב מפורסם לא אמרינן דהעכו\"ם משקר דהא הטעם הוא דלא עשאו תק\"ה בגנב מפורסם משום דלא היה לו לקנותו ממנו וזה הטעם שייך ג\"כ בזה לפי דעת החולקין הנ\"ל דגם בגנב מפורסם עשו תק\"ה אם לא שידע שזה החפץ גנוב הוא גם בזה נ\"ל דמיירי בהכי:\u0004"],["\u0003 אסור לקנות מהגנב כו' \u0004 עיין בבעל התרומות שער מ\"ט חלק י\"ג מדינים אלו ובתשובת ר\"ש כהן ס\"ב סימן ז':","\u0003 ולא נתייאשו הבעלים \u0004 אבל סתם גניבה הוי יאוש בעלים אם נודע שהבעלים ידעו מהגניבה וכמ\"ש לעיל סי' שנ\"ג סעיף ג' מיהו היינו בגנב ישראל אבל בגנב עכו\"ם אפי' סתמא לא הוי יאוש וכמש\"ל סי' שס\"ח ע\"ש:","\u0003 הוא גנבו בפנינו כו' \u0004 לפמ\"ש לקמן ס\"ס שס\"א דטענינן ליורשי גזלן לקוח במגו דהחזרתי כל היכא דליכא עדי ראה א\"כ צ\"ל דכאן בכל הסי' מיירי דאיכא עדים שראוהו ביד הלוקח דאל\"כ הוי טענינן ללוקח כי היכא דטענינן ליורש אף בדמים ודוק:","\u0003 מפני תקנת השוק \u0004 עיין מש\"ל סי' קכ\"ו בשם תשובת ר\"מ אלשיך ותלמוד לכאן שאם בא הדבר הגנוב אחר שנמכר לבעלים א\"צ לשלם ללוקח מעותיו אף שידוע שקנהו מתחלה דלא שייך ביה תקנת השוק כיון שהוא עתה ביד בעלים הראשונים ואף ששם חלקתי עליו מ\"מ כאן מודינ' עיין בתשובת רשד\"ם סי' רי\"ב ותי\"ד שפסק דבעבדים ובהמה לא עשו תקנת השוק ואין דבריו מוכרחים ובתשובת מהרא\"ן ששון סי' רי\"ח כ' דעבדי כמטלטלי בענין תקנת השוק צ\"ע:","כתב ב\"י וז\"ל כ' הרשב\"א דבמתנה לא שייך תקנת השוק ובסי' ס' כתבתי שדעת הרא\"ש דבמתנה נמי עשו תקנת השוק ומביאו ד\"מ גם בר\"ס ס' כ' וממ\"ש הרא\"ש בתשובה שכבר נהגו בכל הארץ הזאת שאין מגבין לב\"ח ממטלטלין שמכר או שנתן הלוה מפני תקנת השוק משמע דס\"ל דבמתנה נמי איכא משום תקנת השוק ואין כן דעת הרשב\"א כמ\"ש בסי' שנ\"ו ומ\"מ סוגיין דעלמ' בהא כהרא\"ש ואע\"פ שאפשר שטעמם מפני שלא ראו חולק עליו מ\"מ כדאי הוא הרא\"ש לסמוך עליו כו' עכ\"ל ומביאו ד\"מ שם ואין דבריו נכונים דודאי הרא\"ש מודה כאן דבמתנה לא שייך תקנת השוק דהיאך יעלה על הדעת שעשו תקנת השוק דהא אפי' במכר צריך להחזיר מדינ' בלא כלום אלא שעשו תקנת השוק דאל\"כ לא יקנה אדם מחבירו מחשש גנבה וזה לא שייך במתנ' וגם תימה דודאי מתנ' גרע מגנב ופרע בחובו או בהיקפו דלא עשו תקנת השוק (וכ\"כ הבית חדש בי\"ד בקונטרס אחרון סי' קע\"ז סעיף כ\"א דנתנו במתנ' גרע מגנב ופרע בהיקפו וכן מוכח להדיא בתשו' רש\"י שבמרדכי פ' שבועות הדייני' ובתשובי' מיימוני לס' משפטים סי' ב' ומביאו ב\"י לעיל סי' ע\"ב מחו' ב' דבמתנה לא עשו תקנת השוק ע\"ש וכן ראיתי בס' ראבי\"ה סי' אלף י\"ח שכתב וז\"ל ומיהו אם הקדישו או נתנו במתנה לא עשו ולא כלום דבהקדש ומתנ' לא שייך תקנת השוק דהוי כגנב ופרע בחובו או בהיקפו דלא עשו בו תקנת השוק עכ\"ל ופשוט הוא) ולא קאמר הרא\"ש התם אלא בשעבד לו מטלטלי אג\"ק דנהגו עכשיו דאין מגבין לב\"ח ממטלטלי שמכר או נתן דאל\"כ לא יקנה אדם שום מטלטלים מחבירו לכך אמרי' דמ\"ש בשטר חוב דשעבד לו מטלטלי אג\"ק לא מהני לענין זה שיטרוף מהלקוחות וכמאן דלא כתיב דמי והלכך כיון דכמאן דלא כתיב דמי פשיטא נמי שאין טורפין ממה שנתן הלוה במתנ' משא\"כ הכא בכליו שהם ידועים שהיו שלו וזה גנבם ונתנם במתנה פשיטא שמוציאין מידו בחנם תדע שהרי מדינא פשיטא דלא שייך תקנ' השוק במטלטלים שמכר הלוה וכדאיתא בש\"ס וכל הפוסקים וכמ\"ש הרא\"ש גופיה שם דהיכא דאין מנהג ידוע יש להגבות לב\"ח מטלטלים שמכר הלוה ועוד דהא הרא\"ש כ' דאין מגבין מהן לב\"ח כלל ואלו הכא מגבין לו ומחזיר הדמים א\"ו דהרא\"ש כ' מסברא דנפשיה שנהגו לעשות תקנת השוק בזה שלא לגבות מטלטלים שמכר או שנתן משא\"כ הכא א\"כ הרא\"ש והרשב\"א לא פליגי כלל ודלא כב\"י וד\"מ וכן עיקר וכ\"כ בתשו' ר\"מ אלשיך סי' י\"ז דבמתנה לא שייך תקנ' השוק ע\"ש ועיין לעיל סי' רנ\"ב שגם הסמ\"ע שם ס\"ק ו' כ' בפשיטו' דבמתנה שייך תקנ' השוק והשגתי שם עליו באריכות ע\"ש (שוב מצאתי בתשובת מבי\"ט ח\"א בשאלו' השניות סי' ג' ריש דף ק\"ח שכ' דהרא\"ש מודה לדינו של הרשב\"א והרשב\"א אינו מודה לדברי הרא\"ש ע\"ש ולא הבנתי דבריו):","\u0003 ואם גנב מפורס' כו' \u0004 אבל אם אינו גנב מפורסם רק שמפרסים לרשע בדברים אחרים צריך ליתן דמים הכי מוכח בש\"ס גבי הא דמשני בחנן בישא נהי דאיפרסם לבישותא לגניבותא לא איפרסם וכ\"כ רב האי גאון במשפטי שבועו' שער י\"ט:","\u0003 וי\"א דאף בגנב כו' \u0004 וכ\"פ מהרש\"ל פ' הגוזל בתרא סי' ל\"ב ול\"נ עיקר להמחבר לפי שכ\"נ להדיא דעת הרי\"ף שהביא מימרא דרבא ולא כב\"י שכ' דלא מוכח מהרי\"ף מידי וכ\"כ הסמ\"ג והגה\"מ והמרדכי ושאר פוסקים לדע' הרי\"ף וכן הנ\"י הבין כן דעת הרי\"ף רק מה שתמה שם על הרא\"ש לק\"מ ע\"ש וא\"כ כיון דהרי\"ף והרמב\"ם מסכימים לדעת א' וגם בש\"ס משמע כדבריה' וכ\"פ בשערי הרי\"ף שער כ' דין ט\"ז וכ\"פ בס' משפטי שבועות לרבינו האי גאון שער י\"ט וכ\"כ בבה\"ע דף ס\"ט ע\"ד וכ\"פ בתשובת הגאונים סי' מ\"ב וכ\"פ ראב\"ן ומביאו המרדכי שם וכ\"כ בעה\"ת שער מ\"ט חי\"ג וכן נראה מתשו' מהרש\"ל אע\"ג שמהרש\"ל שם כ' דלא מוכח מדבריו מידי מ\"מ דבריו דחוקים ע\"ש וגם אישתמיטתיה למהרש\"ל תשובת מהר\"מ אחרת במרדכי בפ' הספינה דכתב להדיא וז\"ל ושכתבת לפטור לאה משום תקנ' השוק הא ליתא דלא עשו תקנת השוק אגנב וגזלן מפורסם כו' וגם דעת הרשב\"א כן וכמו שמבוא' מדבריו שמביא ב\"י גבי גזלן אם דינו כגנב מפורסם ע\"ש וכן בריב\"ש ס\"ס שצ\"ג ע\"ש וכ\"נ דעת הראב\"ד והרב המגיד וכן הוא בתו' שלפנינו וכן נראה דעת נ\"י שם וגם ר' ירוחם שהוא תלמיד הרא\"ש כ' בסתם (בנל\"א ח\"ג) דגנב מפורסם לא עשו בו תקנת השוק ולא הזכיר דעת הרא\"ש כלל וגם הטור נראה אע\"פ שהביא כאן סברת ר' ירוחם [ר\"י] דעשו תקנת השוק בגנב מפורסם מ\"מ לענין דינא ס\"ל דלא עשו תקנת השוק שהרי לקמן סי' שס\"ט כ' בסתם שהלוקח מגזלן דינו כלוקח מגנב שאם הוא גזלן מפורס' צריך להחזירו לבעליו והוא יתבע מגזלן ואם אינו מפורסם שעשו בו תקנת השוק כו' ודוחק לו' דדוקא בגזלן ס\"ל הכי ועוד דלא מצינו חילוק בזה בשום פוסק ועוד דהל' שכ' דינו כלוקח מהגנב משמע שגם בגנב הדין כן הילכך נראה כיון דתקנת השוק היא תקנה ומדינא צריך להחזיר בחנם אין לך אלא מה שתיקנו והבו דלא לוסיף עלה ונקטינן דבגנב מפורסים לא עשו בו תקנת השוק עיין בבעל המאור פ' הגוזל בתרא דבלוקח מעכו\"ם לא עשו תקנת השוק (וכן הוא בתשובת הגאונים סי' רצ\"ו ע\"ש) והרמב\"ן בס' המלחמות חולק עליו וכ' וכך מצינו בתשובה לרבינו שרירא גאון ז\"ל שדין תקנת השוק כלוקח מעכו\"ם וא\"צ לפנים עכ\"ל וכן הוא בהגהות מיימוני רפ\"ה מהל' גניבה וכן משמע לכאורה מדברי התוס' פ' הגוזל בתרא (בבא קמא דף קי\"ד ע\"ב) וכן משמע מדברי ראב\"ן שבמרדכי פ' הגוזל בתרא ומביאו ב\"י ס\"ס זה וכן נראה להדיא מדברי תשובת רבינו גרשום שבמרדכי ר\"פ אלו מציאות וכן משמע להדיא בתרומות הדשן סי' ש\"ט וכן נראה משאר פוסקים שלא חילקו וכן עיקר ועיין בתשובת רא\"ן ששון בלוקח מאומן אי עשו תקנת השוק:","\u0003 ואפי' הגנב א\"צ להחזיר מעותיו כו' \u0004 נ\"ל שזהו שגג' דהמרדכי כ' להדיא דהיינו דוקא למ\"ד הכיר בה שאינו שלו ולקחה כו' הוי מעות מתנה וכן הוא בהגהת מיימוני מהל' גניבה דהיינו דוקא למ\"ד הכיר בה שאינו שלו ולקחה כו' והיינו כשמואל פ\"ק דמציעא דף ט\"ו ע\"ב ולא כתבו שם כן אלא להחזיק דבריהם שכתבו שם לפני זה ע\"ש ואנן קי\"ל כרב דמעות יש לו וכדפסק רבא התם הלכתא וכ\"פ כל הפוסקים וכדלקמן סי' שע\"ג א\"כ הכא צריך הגנב להחזיר לו מעותיו ותמהני מאד על הסמ\"ע שכ' על דברי מהרמ\"א וכיוצא בזה איתא בש\"ס וטור ומחבר לקמן סי' שע\"ג בקנה שדה מגזלן עכ\"ל דאדרבה נהפוך הוא שם וכ\"פ מהרש\"ל פרק הגוזל בתרא ס\"ס ל\"ב להדיא כדפי' ע\"ש ואלמלא שאיני כדאי לחלוק על המרדכי והגהת מיימוני ומהרש\"ל הייתי אומר דאפילו שמואל מודה כאן דדוקא בקרקע שאינה נגזלת אמרי' אדם יודע שקרקע אין לו ונתן לו לשם מתנה משא\"כ הכא י\"ל דהלוקח סובר שיקנה המטלטלים ביאוש ושינוי רשות ואע\"ג דע\"כ מיירי הכא דלא נתייאש דאל\"כ סתם גניבה הוי יאוש מ\"מ הלוקח סבר דנתייאש ודוחק לו' כיון דהלוקח יודע שהוא גנב אינו קונה ביאוש ושינוי רשות דאין טעם לחלק בכך וכן מבואר להדיא מדברי הב\"ח בא\"ע ר\"ס כ\"ח דאפי' ידע שגנוב הוא או גזול הוא בידו קונה ביאוש ושינוי רשות. ואפשר דהמרדכי והגהת מיימוני ומהרש\"ל מיירי כשהלוקח ידע שלא נתייאשו הבעלי' ואף בזה צ\"ע די\"ל דהלוקח סבר שמא נתייאש אח\"כ ואף למ\"ד דשינוי רשות ואח\"כ יאוש לא קני מ\"מ אין זה פשוט דהא הרמב\"ם והרבה פוסקים סוברים דקני וכ\"כ התוס' כה\"ג ממש פ\"ק דמציעא וז\"ל ושמואל סבר כו' ונתן לשם מתנה אבל בערכין גבי המוכר שדהו בשנת היובל עצמו דאמר שמואל מעות חוזרים ליכא למימר אדם יודע שאין מכר ביובל דאין זה פשוט דהא אמר רב מכירה ויצאה עכ\"ל וכ\"כ התו' בפ' השולח דמ\"ה ע\"א ובפ\"ט דערכין דף ל' ע\"א ומוכח כן בש\"ס שם (וכה\"ג כתבו התוס' פ' שור שנגח ד' וה' ריש (בבא קמא דף מ\"ה) גבי שור הנסקל דלא הוי המעות מתנה דאין הכל בקיאים בדין שור הנסקל כו' ע\"ש) ועוד יש לחלק דשאני מטלטלים דהלוקח חושב שמא לא ימצא הגנב ולא יודע המטלטלים היכן הם משא\"כ בקרקע דכל היכא דאיתיה ברשותיה דמרא איתא. ואף דק\"ל כרב מ\"מ כתבתי זה משום דלגבי מקדש אחותו קי\"ל כשמואל דהמעות מתנה [וכמ\"ש] הרמב\"ם והמחבר בא\"ע סי' נ' ס\"ב והיינו מטעמא דמחלקים בין אינש נוכרא' לאחותו וכמ\"ש הרא\"ש פ\"ק דמציעא וז\"ל מהא דפסק רבא דמעות יש לו אין לדקדק דהלכה כרב במקדש אחותו דדילמא שאני בין אחותו לנוכראה עכ\"ל וא\"כ להמרדכי וסייעתו אם היה הגנב אחיו או אחותו היה נראה שהמעות מתנה ולדידי אין המעות מתנה וכן נ\"ל עיקר ודוק. וגם בלא\"ה במקדש את אחותו גופיה כ' ראב\"ן דף קל\"ה ע\"א וז\"ל וכיון דרב אסי סבר כרב אע\"ג דהלכתא כשמואל בדיני נ\"ל דבהא הלכתא כרב עכ\"ל וכך נראה דעת הרי\"ף שלא הביא פלוגתא דרב ושמואל במקדש את אחותו בשום מקום אלא ודאי ס\"ל דקי\"ל כרב והלכך כיון שהביא פלוגתייהו גבי הכיר בה שאינו שלו ה\"ה בעלמא ואף ע\"ג דבש\"ס עביד צריכותא מ\"מ כיון דלפי האמת פליגי בתרווייהו לא הוצרך להביאו כן נראה דעת הרי\"ף. מיהו מה שהביא ראב\"ן ראי' דרב אסי סבר כוותיה אינו ראי' דנראה דהוי גריס בש\"ס בקידושין דאתמר בדלי\"ת וכבר דחו שם התוס' גירסא זו והוכיחו דגרסי' איתמר ע\"ש. מיהו בלא\"ה י\"ל דהלכה כרב מטעם דכיון דרב ושמואל גופייהו ס\"ל דאין חילוק בין אינש דעלמא לאחותו מנ\"ל לפלוגי בהכי א\"כ כיון דגבי הכיר בה שאינו שלו פסק רבא כרב ה\"ה במקדש את אחותו ודוק. שוב מצאתי בב\"ח סי' שע\"ג האריך לפרש דברי המרדכי ומ\"ש שם בישוב הראשון אינו נכון אלא הדבר פשוט כמו שמסיק הב\"ח שם ודלא כהרמ\"ה ע\"ש:","\u0003 ואם אמר הלוקח כו' \u0004 וכ\"כ התוספות פ' הגוזל בתרא (בבא קמא דף קי\"ד ע\"ב) וז\"ל וא\"ת בלא תקנת השוק יטול מה שנתן דמצי אמר להציל נתכוונתי להשיב אבידה וי\"ל דמיירי שהיה יכול לתבוע מבני אדם שלנו בתוך ביתו אפילו לא היה זה קונה אותם עכ\"ל אלמא דאם לא היה יכול לתבעו נאמן הלוקח והבאתי דברי התוס' ללמוד מדבריהם דהיכא דהיה יכול להוציא מהגנב אף אם לא היה זה קונה א\"צ להחזיר מעותיו:","\u0003 לבעל המשכון מעותיו כו' \u0004 משמע דצריך ליתן לו אף היותר (וי\"ל להפך) וכ\"פ מהרש\"ל סי' ל\"ב דא\"צ ליתן אלא כדי שווים ופי כך ל' הרמב\"ם והביא ראיות ועיקר:","\u0003 דהכי נהיגי עכשיו כו' \u0004 מכח דינא דמלכותא כו' ואף ע\"ג שהוכחתי לעיל סימן ע\"ג סי\"ד באריכות דלא אמרינן דינא דמלכותא מה שהוא נגד דין תורתינו מ\"מ דיינין הכי שפיר בלישנא דהכי נהיגי עכשיו כלו' דגם בישראל נהיגי כן ובת\"ה א\"ש טפי דכתב דהכי דייני עתה כו' ואע\"ג דמנהג גרוע שהוא נגד דין תורה לא אזלינן בתריה וכמש\"ל סי' ע\"ב ס\"ק ל\"ה וכמה דוכתי י\"ל דהאי מנהג הוא שנתקן כך ופשיטא דיש ביד הדור לתקן תקנות ועוד דגם בדינא דמלכותא הוא כן ודוק:","\u0003 ויחרימו סתם שכך היה כו' \u0004 צ\"ע מנ\"ל הא דסגי בחרם סתם ואדרבה מסתבר דצריך לישבע כדין כל הנשבעין ונוטלים וכ\"כ המ\"מ להדיא ומביאו ב\"י. שוב ראיתי בס' ב\"ה שכ' על דברי הרב המגיד וז\"ל ואיני יודע שבועה זו למה כיון שאין הלה טוען ברי אין כאן אלא חרם סתם עכ\"ל ואיני יודע למה אינו יודע דהא כשבא ליטול צריך לישבע אפילו בשמא כדלעיל ס\"ד וכ\"כ לעיל סי' ע\"ב ס\"ק ס\"ז בשם ר' ירוחם ובשם הרבה פוסקים דכל היכא דטוען על הכלי כדי דמיו צריך לישבע אפילו התובע טוען שמא ע\"ש:","\u0003 נוטל המא' ועשרים \u0004 עיין בסמ\"ע ס\"ק כ\"ב דעת הטור בזה ור' ירוחם פסק בנל\"א ח\"ד כהרמב\"ם והמחבר וכ\"פ מהרש\"ל שם סימן ל\"ה ועיקר ועיין בש\"ג פרק כל הנשבעין דף ש\"ל ע\"א מדיני' אלו שבסי' זה:"]],["\u0010c0\u0011 בַּעַל הַבַּיִת שֶׁאֵינוֹ עָשׂוּי לִמְכֹּר אֶת כֵּלָיו, \u0010y0\u0011 וְיָצָא לוֹ שֵׁם גְּנֵבָה בָּעִיר, וְהִכִּיר כֵּלָיו וּסְפָרָיו בְּיַד אֲחֵרִים, אוֹ שֶׁהָיָה עָשׂוּי לִמְכֹּר וְהָיוּ כֵּלָיו אֵלּוּ שֶׁהִכִּיר מִכֵּלִים הָעֲשׂוּיִים לְהַשְׁאִיל וּלְהַשְׂכִּיר, \u0010y1\u0011 \u0010c1\u0011 \u0010c2\u0011 \u0010c3\u0011 \u0010c4\u0011 \u0010c5\u0011 אִם בָּאוּ עֵדִים שֶׁזֶּה כֵּלָיו שֶׁל זֶה, יִשָּׁבַע זֶה שֶׁהֵם בְּיָדוֹ, בִּנְקִיטַת חֵפֶץ, בְּכַמָּה לָקַח, וְיִטֹּל מִבַּעַל הַבַּיִת וְיַחֲזִיר לוֹ כֵלָיו. \u0010y2\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּכֵיוָן שֶׁהוּא טוֹעֵן גְּנוּבִים אִתְּרַע לֵהּ חֲזָקָה דַּעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר, שֶׁהֲרֵי הוּא אֵינוֹ טוֹעֵן כֵּן, וְלָכֵן חָיְשֵׁינָן שֶׁמָּא מְכָרָן (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010y3\u0011 הָיָה בַּעַל הַבַּיִת עָשׂוּי לִמְכֹּר אֶת כֵּלָיו וְלֹא הָיוּ מֵהַדְּבָרִים הָעֲשׂוּיִים לְהַשְׁאִיל וּלְהַשְׂכִּיר, אַף עַל פִּי שֶׁיָּצָא לוֹ שֵׁם גְּנֵבָה בָּעִיר וְהֻכְּרוּ כֵּלָיו, אֵינוֹ מַחֲזִירָן מִיַּד לָקוֹחוֹת, שֶׁמָּא הוּא מְכָרָן לַאֲחֵרִים. אֲבָל אִם בָּאוּ בְּנֵי אָדָם וְלָנוּ בְּתוֹךְ בֵּיתוֹ, וְעָמַד וְזָעַק בַּלַּיְלָה: נִגְנְבוּ כֵּלַי וּסְפָרַי, וּבָאוּ בְּנֵי אָדָם וּמָצְאוּ מַחְתֶּרֶת חֲתוּרָה וּבְנֵי אָדָם שֶׁלָּנוּ בְּתוֹךְ בֵּיתוֹ יוֹצְאִים וּצְרוֹרוֹת שֶׁל כֵּלִים עַל כִּתְפֵיהֶם, וְהַכֹּל אוֹמְרִים: הַלָּלוּ כֵּלָיו וּסְפָרָיו שֶׁל פְּלוֹנִי, הֲרֵי זֶה נֶאֱמָן, וְיִשָּׁבַע זֶה שֶׁהַכֵּלִים בְּיָדוֹ בִּנְקִיטַת חֵפֶץ כַּמָּה הוֹצִיא, וְיִטֹּל מִבַּעַל הַגְּנֵבָה, וְיַחֲזִיר לוֹ כֵּלָיו.\nדִּין מִי שֶׁנִּכְנַס לְבֵית חֲבֵרוֹ וְהוֹצִיא כֵלִים תַּחַת בְּגָדָיו, נִתְבָּאֵר בְּסִימָן צ'.\nרְאוּבֵן שֶׁנִּגְנְבוּ כֵּלָיו אוֹ נֶאֶבְדוּ אוֹ נְטָלוּהוּ לִסְטִים, וּבָאוּ לְיַד גּוֹי, וּקְנָאָם יִשְׂרָאֵל אַחֵר בְּפָחוֹת מִשָּׁוְיָם, וּבָאוּ הַבְּעָלִים וּתְבָעוּם מִיַּד זֶה שֶׁקְּנָאָם, יִתְבָּאֵר בְּסִימָן שס\"ח.",["\u0003ויצא לו שם גניב' בעיר כו' \u0004 ובפריש' כתבתי והוכחתי שהאי יצא לו שם גניבה בעיר היינו דוקא שהוא צועק כלי (של) פלוני שסימנו כך וכך אבדתי ואח\"כ ראה כלי כזה ביד בע\"ה אחר וז\"ש והכיר כליו כו' שהכל רואין שיש לכלי זה אותן סימנים שצעק עליו שנגנב מידו:","\u0003אם באו עדים שזה כליו של זה כו' \u0004 דביצא לו שם גניבה בעיר לא סגי דדילמא ראה אותן ביד זה בסימניו ועשה ערמה לצעוק איך שנגנב ממנו כדי להוציאו מידו ומ\"מ צריכין ג\"כ שיצא לו שם גניבה בעיר דאל\"כ יש לחוש דלמא אף שאינו רגיל למכור שמא הי' צריך למעות ומכרו מיהו בכלים העשוין להשאיל ולהשכיר כ' הטור וגם הנ\"י בשם הרמב\"ם דאף אם לא יצא לו שם גניבה בעיר נשבע שהן שלו ולא מכרן לו ומוציאן מיד הלוקח והב\"י כ' שהוא טעות בידו ודגם זה אמ\"ש הרמב\"ם ברישא דיצא לו שם גניבה בעיר קאי ובדרישה כתבתי דנראה דאינו טעות ושהטור ונ\"י מפרשים דברי הרמב\"ם קאי איצא לו שם גניבה בעיר דא\"כ ה\"ל לערבינהו וליתננהו הכי בע\"ה שאינו עשוי למכור כליו או שעשוי למכור והיו כלים שעשוים להשאיל ולהשכיר ויצא לו שם גניבה בעיר והכיר אח\"כ כליו וספריו כו' וגם הראב\"ד כ' דאפילו בלא יצא לו שם גניבה דינא הכי אלא שאז צריך לישבע שלא מכרן אלא גנובין הן מידו והביאו ג\"כ הד\"מ ע\"ש:","\u0003דכיון שהוא טוען גנובין כו' \u0004 ע\"ל ס\"ס קל\"ג בטור ובדברי המחבר וגם בסי' צ':","\u0003הי' בע\"ה עשוי למכור כליו כו' \"עד אבל אם באו בני אדם ולנו כו' \u0004 עיין בטור שכ' דברים הללו באיש שאינו עשוי למכור כליו ואין עדים שמכירין שהן כליו של פלו' וגם לא ראו הכלים בשעה שהוציאן האנשים שהיו טמונין ובעשוי למכור ג\"כ כתב דמהני אף שאינן מכירין שהיו של פלוני הצועק רק שבעינן בזה עדים שראו הכלים שהיו נושאין בשעת הוצאה מהחתיר' בסימנים הללו שזה צועק שאז נגנבו מידו ואז מצטרפין הג' דברים הללו. הא' שראו שבני אדם שלנו בביתו יצאו דרך החתיר'. השני שראו שנושאים כלים עליהן כעין הכלים שצעק זה שנגנב מידו. השלישי שגם עתה אנו רואים ביד הנתבע כלי כזה בסימנים הללו ואמרי' דודאי שלו הן ואחר זה כ' הטור דברי הרמב\"ם הללו שכתב המחבר בל' פלוגת' וכתבתי בפריש' ודריש' ההוכחות שלא פליגי לדינא אלא מר אמר חדא ומר אמר חדא כל א' לפי שטתו בפי' השמעתת' וגם מור\"ם ז\"ל בד\"מ כ\"כ והמחבר השמיט דברי הטור שהן בנוין ע\"פ פירש\"י והתוס' והרא\"ש כמ\"ש שם משום דס\"ל דפליגי שם הרמב\"ם כמ\"ש בב\"י ע\"ש דהרבה להקשות ולתמו' על דברי הטור ובדריש' ישבתי כל תמיהותיו ע\"פ עיון השמעת' וישובו ע\"ש ודוק ועוד השמיט המחבר מ\"ש הטור דלשיטת הרמב\"ם והראב\"ד איירי אפי' בלאחר יאוש דגם בזה הלך לשטתו דבב\"י תמה על דברי הראב\"ד בזה ובדריש' כתבתי דלק\"מ וגם בד\"מ רמזי בקיצור וע\"ש עוד מ\"ש בתמיהתו והכל ישבתי בדריש' בס\"ד:"],["\u0003 בעל הבית כו' \u0004 ע' בש\"ג פ' כל הנשבעין דף שס\"ט ע\"ב מדיני' אלו שבסי' זה:","\u0003 אם באו עדים כו' \u0004 ע' מ\"ש בסמ\"ע ס\"ק ב' דברי רמב\"ם דלא קאי איצא לו שם גניב' בעיר כו' וכן פי' הב\"ח ותימא דא\"כ דעת הרמב\"ם דבדברים העשויים להשאיל ולהשכיר אפי' לא יצא לו שם גנבה ואפי' הבעל הבית עשוי ג\"כ למכור כליו מוציאין מידו וא\"כ בע\"כ שצ\"ל דהיינו משום מגו דאל\"כ למה יהיה עשוי להשאיל ולהשכיר עדיף מאינו עשוי למכור או לא יצא לו שם גנבה דלא סגי אלא בדאיכא תרתי לטיבות' וכ\"כ הב\"ח להדיא להרמב\"ם דהיינו משום מגו וקשה דהרי הרמב\"ם לא הזכיר מגו כלל. דהרי נפקא מינה לדינא היכא דליכא עדי ראה וכמו שאכתוב לקמן ועוד דא\"כ ודאי טעו הטור והנ\"י בדעת הרמב\"ם שהרי כ' הרמב\"ם להדיא בפ\"ח מטוען דין ה' על כלים העשוי' להשאיל ולהשכיר וראו עתה בידו וז\"ל אין כל הדברים האלו אמורים אלא שהי' בעל הכלי טוען אני הפקדתיו אצלך או השאלתיהו אצלך אבל אם טען שכלי זה הי' שלי ונגנב או אבד או נגזל והביא עדים שהי' ידוע לו וזה שתחת ידו אומר איני יודע אבל אחרים מכרוהו לי או נתנוהו לי במתנ' אע\"פ שהוא מדברים העשוים להשאיל ולהשכיר מעמידי' אותו בידו יצא לבעלים הראשונים שם מכליהן שנגנבו ישבע זה בנק\"ח כמה הוציא ויטול ויחזור הכלי לבעלים הראשונים כמו שבארנו בה' גנבה עכ\"ל הרי להדיא דבלא יצא לו שם גנבה ס\"ל להרמב\"ם אף בדברים העשוים להשאיל ולהשכיר דאין מוציאין מידו. ועוד תימא דאי כהבנת הסמ\"ע והב\"ח בטור לדעת הרמב\"ם דאפי' בלא יצא לו שם גנבה ועשוי למכור כליו מוציאין מידו מטעם מגו א\"כ היאך כ' הטור ע\"ז ולא נהירא לא\"א הרא\"ש ז\"ל דכיון שהוא אומר גנובים אתרע לה חזקה דעשוי' להשאיל ולהשכיר כו' דא\"כ לדעת הרא\"ש אפי' דאית ליה מגו דשאלה ושכירות לא מהימן לומר גנובים והא ודאי ליתא דמ\"ש הרא\"ש בפרק כל הנשבעין דכיון דאומר גנובים אתרע לה חזקה דשאלה ושכירות מיירי התם להדיא בטוען שהוא עצמו גנבן כהך דינא דלעיל סי' צ' סוף סעיף י\"א ועלה מסיק ובמגו דשאלה ושכירות לא מחזיקינן אינשי בגנבי משא\"כ הכא איפכא מסתברא דאדם אחר שהוא גנב גנבם ומכרם וכ\"כ הרא\"ש גופיה ובפ' כל הנשבעים גבי ספרא דאגדתא וז\"ל במכיר כליו וספריו ויצא לו שם גניבה בעיר כו' ואמאי בעי כולי האי להימניה במגו דאי בעי אמר שאולים הן בידך ואין האחר נאמן לומר לקוחים הן בידי דעשוים להשאיל ולהשכיר ולא שייך לומר אחזוקי' אינשי בגנבי לא מחזקינן שהרי אינו אומר שהוא גנבם אלא נגנבו ממני וכמה גנבי איכא בעלמא לכך נדחק רש\"י לפרש דספרים אין עשוים להשאיל ולהשכיר ור\"ת תירץ דיש ספרים עשויים להשאיל ולהשכיר ויש שאינן עשוים והדבר תלוי בראות עיני הדיינים עכ\"ל הרא\"ש הרי להדיא דעת הרא\"ש להפך וגם הנ\"י בפ' הגוזל בתרא מביא דברי הרא\"ש אלו ע\"ש וכן כתבתי לעיל ס\"ס קל\"ג בשם התוס' והרבה פוסקים ע\"ש:","אלא הדבר ברור דס\"ל להטור ונ\"י (וכן משמע בנ\"י דכתב אחר דברי הרמב\"ם כתב הרא\"ש וא\"ת כו' וליהמני' במגו כו' משמע דהרמב\"ם לא מיירי ממגו ואע\"ג דבנ\"י דפוס וינציא' איתא וכ\"כ הרא\"ש כו' פשוט הוא דט\"ס הוא כדמשמע מפשט לשונו אלא צ\"ל כמו שהוא בדפוס קראקא ושאר דפוסים ע\"ש) דהרמב\"ם לא מיירי כלל ממגו דהרי לא הזכיר כלל מגו. ומ\"ש הרמב\"ם או שהיה עשוי למכור כליו והיה מדברים העשוים להשאיל ולהשכיר כו' קאי אויצא שם גניב' וכדמשמע מפשט דבריו וכמו שפי' ה' המ' דבריו דאל\"כ הל\"ל רבותא או שהי' עשוי למכור ולא יצא לו שם גניבה והי' מדברים העשוים להשאיל ולהשכיר כו' ועוד דהרי בפ\"ח מטוען כ' להדיא דבלא יצא לו שם גנבה אע\"פ שהוא מדברים העשוים להשאיל ולהשכיר אין מוציאין מידו וכמו שהבאתי לשונו לעיל (או) א\"ו איצא לו שם גנבה דכ' ברישא קאי ודלא כהסמ\"ע והב\"ח וס\"ל להרמב\"ם דלעולם אין מוציאין מידו אלא בדאיכא תרתי לטיבותא דהיינו שהבע\"ה אינו עשוי למכור כליו ויצא לו שם גנבה או שהי' עשוי למכור והיו כלים אלו מדברים העשוים להשאיל ויצא לו שם גנבה ואז נאמן אפילו היכא דלית מגו כגון דליכא עדי ראה דאז אי הוה טען המחזיק לקוחין הן בידי הי' נאמן במגו דהחזרתי אפ\"ה כיון דאיכא תרתי לטיבותא מוציאים מידו ומחזיר לו הדמים דכי היכא דביצא לו שם גנבה ואינו עשוי למכור דמוציאין מידו דפשיטא דהיינו אפי' בדליכא עדי ראה והי' יכול לטעון החזרתי ה\"ה בעשוי למכור והי' הכלים מדברים העשוים להשאיל ולהשכיר דאיכא נמי תרתי לטיבותא והשתא בדברים העשוים להשאיל ולהשכיר ואינו עשוי למכור אע\"פ שלא יצא לו שם גנבה נמי מוציאין מידו כיון דאיכא תרתי לטיבותא ומ\"ש הרמב\"ם בפ\"ח מטוען דבלא יצא לו שם גנבה אין מוציאין מידו אפילו בדברים העשוים להשאיל ולהשכיר מיירי בעשוי למכור ומ\"ש הטור בדעת הרמב\"ם אפילו לא יצא לו שם גנבה חד מתרי נקט ולא בא אלא לומר דלהרמב\"ם איכא מעליותא בכלים העשויים להשאיל ולהשכיר אפילו ליכא מגי וה\"ה דה\"מ למימר אפילו עשוי למכור ויצא שם גנבה וכדאיתא ברמב\"ם אלא דרבותא נקט ודוק (ומעתה ה' המ' והנ\"י והטור כולם שוים בדעת הרמב\"ם דמ\"ש ה' המ' דקאי אויצא לו שם גנבה היינו משום דמיירי בעשוי למכור כליו אבל באינו עשוי למכור י\"ל דס\"ל דלא בעי' יצא לו שם גנבה לדעת הרמב\"ם כיון דאיכא נמי תרתי לטיבותא):","\u0003והשתא קאמר הטור שפיר ולא נהירא לא\"א הרא\"ש ז\"ל כו'\u0004 דבהרא\"ש מוכח להדיא דהיכא דלית ליה מגו לא נ\"מ בדברים העשוים להשאיל ולהשכיר דכיון דטוען גנובים אתרע לה חזקה דשאל' ושכירות (ואין להקשות דא\"כ מאי מקשה הרא\"ש בהנשבעין במכיר כליו וספריו ולהימני' במגו הא התם מיירי אפי' היכא דלית לי' מגו כיון דליכא עדי ראה דקושיא זו קשה בלאו הכי על הרא\"ש ותוס' ופוסקי' דהרי הרא\"ש כ' להדיא בס\"פ המקבל דהיכא דליכא עדי ראה נאמן אף בדברים העשוי' להשאיל ולהשכיר לו' לקוח במגו דהחזרתי והוא פשוט ומוסכם מכל הפוס' ומוכח בש\"ס פ' חז\"ה א\"ו צ\"ל דהכי מקשים דה\"ל לאשמועינן בפ' הגוזל דהיכא דאיכא עדי ראה לא בעי כולי האי כיון דמיירי בדברי' העשויים להשאיל ולהשכי' ודוק) ולא הוצרך הטור לבאר כאן דבאית ליה מגו כגון דאיכ' עדי ראה נאמן לטעון גנובים במגו דשאל' ושכירו' גם להרא\"ש משום דבכל הסי' כאן לא מיירי מזה רק מיירי אפי' בדליכא עדי ראה ובמ\"ש מיד אח\"כ ולמעל' בסי' צ' כתבתי גנב שנכנס לבית חבירו והוציא כלים תחת בגדיו עכ\"ל בזה כלל היכא דאית ליה מגו נאמן לו' גנובים במגו דשאל' ושכירות וכמ\"ש לעיל סי' צ' ס\"ק י\"ט דהטור ס\"ל שם הכי ע\"ש ודוק:","והשתא ברור כשמש בצהרים דהרמב\"ם והרא\"ש פליגי לענין דינא דלא כמ\"ש ב\"י דל\"פ דאפי' תימא דלהרמב\"ם בעינן יצא לו שם גנבה אפי' באינו עשוי למכור מ\"מ במ\"ש דבדברים שעשוים להשאיל ולהשכיר מוציאין מידו אפי' עשוי למכור והיינו אפי' היכ' דל\"ל מגו וכמו שהוכחתי למעל' וכדמוכח נמי להדי' מדבריו בפ\"ח מטוען שהבאתי לעיל דחילק בין טוען שאולים לטוען גנובים בדברים העשוים להשאיל ולהשכיר ואיכא עדי ראה אלמא דבטוען גנובים אינו נאמן אף ע\"ג דאית ליה מגו דהי' יכול לטעון שאולים אלמא דלהרמב\"ם ס\"ל דמגו כי האי לא אמרי' וכמ\"ש הרב המ' לדעתו א\"כ ע\"כ הא דכתב דבדברים העשוים להשאיל ולהשכיר מוציאין מידו ע\"כ לאו מטע' מגו אתי עלה ולהרא\"ש היכא דליכ' מגו לא נ\"מ בדברים העשוים להשאיל ולהשכיר דכיון דטוען גנובי' אתרע לה חזקה דשאלה ושכירות וזה ברור:","\u0003והשתא א\"ש מ\"ש מור\"ם בהג\"ה וי\"א דכיון שהוא טוען גנובים כו'\u0004 דאף ע\"פ שהמחבר לא הזכיר דבדברים העשוים להשאיל ולהשכיר מוציאין מידו אפי' לא יצא לו שם גנבה ואדרבא משמע מפשט דבריו דבעי' יצא לו שם גנבה וכמ\"ש בב\"י להדיא מ\"מ גם בעשוי למכור כליו פליג הרא\"ש דעשוי להשאיל ולהשכיר לא מעלה ולא מוריד כשטוען גנובים במקום דלית ליה מגו לטעון שאולים כגון דליכא עדי ראה דהדבר פשוט דבכל הסי' כאן מיירי בדליכא עדי ראה ואפ\"ה ביצא לו שם גנב' בעיר ואינו עשוי למכור כליו מוציאים מידו וכן דעת הר\"ן בפ' כל הנשבעין דהיכא דלית ליה להטוען מגו אינו נאמן לומר גנובים בדברים העשוים להשאיל ולהשכיר דכיון דטוען גנובים אתרע לה חזקה דשאלה ושכירות וכן היכא דאית ליה מגו וטוען שהוא גנבן מטע' דאחזוקי אינשי בגנבי לא מחזיקינן אא\"כ הוא מוחזק כבר בגנב ע\"ש בר\"ן וכן עיקר ודלא כהעיר שושן שכתב רק כדברי המחבר דיש חילוק בין כלים העשוים להשאיל ולהשכיר וכתב וז\"ל וכן אפי' אם הוא עשוי למכור כליו הואיל ודרך אלו הכלים להשאילן ולהשכירן והי' יכול לטעון ללוקח זה השאלתים או השכרתי' לך והוא אינו טוען כן אלא נגנבו ממנו וגם יצא לו שם גנבה בעיר כו' עכ\"ל והא ליתא דודאי בכל הסי' כאן מיירי דהלוקח הי' יכול לטעון לקחתי ממך במגו דהחזרתי כגון דליכא עדי ראה ואפ\"ה ביצא לו שם גניבה מוציאין ממנו ואם כדבריו דהטעם הוא משום מגו א\"כ בלא יצא לו שם גנבה נמי וכמ\"ש בס\"ס קנ\"ג בשם התוס' והגהות מיימוני והסמ\"ג א\"ו כדאמ' ועיין עוד בס\"ס קל\"ג מ\"ש מדינים אלו ושם כתבתי כללי הדיני' בקצרה השייכים לכאן ע\"ש. שוב ראיתי במהרש\"ל פרק הגוזל בתרא סי' ל' האריך להשיג על הטור וכתב שהטור טעה בדברי הרמב\"ם וכמ\"ש הב\"י גם כתב שטע' טעות גדול בדברי הרא\"ש כי הרא\"ש לא פליג על הרמב\"ם ע\"ש שהאריך ולפע\"ד דברי הטור נכונים ואין כאן טעות כלל והדבר ברור דהרא\"ש פליג על הרמב\"ם וכמ\"ש מיהו לענין דינא גם מהרש\"ל שם מסכים לכל מ\"ש וכתב ג\"כ דבדברים העשוים להשאיל ולהשכיר נאמן במגו אפילו לא יצא לו שם גנב' ועשוי למכור כליו רק דבלא יצא שם גנבה אינו נאמן אלא בשבועה שלא מכרן וביצא לו שם גנבה אפי' בשבוע' אין נאמן והיינו כדברי הראב\"ד בהשגות עיין שם: (שוב מצאתי בשלטי גבורים פ' כל הנשבעי' (דף שכ\"ט ע\"ב) שתמה ג\"כ על הטור בזה וכתב כמה דברי' שאינם נראים לפע\"ד והנלע\"ד כתבתי):"]],["כָּל דָּבָר שֶׁחֶזְקָתוֹ שֶׁהוּא גָּנוּב, אָסוּר לִקַּח אוֹתוֹ. \u0010y0\u0011 וְכֵן אִם \u0010y1\u0011 רֹב אוֹתוֹ דָּבָר שֶׁהוּא גָּנוּב, אֵין לוֹקְחִין אוֹתוֹ. לְפִיכָךְ, אֵין לוֹקְחִין מֵהָרוֹעִים צֶמֶר אוֹ חָלָב אוֹ גְּדָיִים. אֲבָל לוֹקְחִים מֵהֶם \u0010y2\u0011 חָלָב וּגְבִינָה בַּמִּדְבָּר, אֲבָל לֹא בְּיִּשּׁוּב. וּמֻתָּר לִקַּח מֵהָרוֹעִים \u0010y3\u0011 ד' צֹאן אוֹ ד' גִּזּוֹת שֶׁל צֶמֶר מֵעֵדֶר קָטָן, אוֹ חֲמִשָּׁה מֵעֵדֶר גָּדוֹל, שֶׁאֵין חֶזְקָתוֹ שֶׁהוּא גָּנוּב. כְּלָלוֹ שֶׁל דָּבָר: \u0010y4\u0011 כָּל שֶׁהָרוֹעֶה מוֹכְרוֹ אִם הָיָה בַּעַל הַבַּיִת מַרְגִּישׁ בּוֹ, מֻתָּר לְלוֹקְחוֹ; וְאִם לָאו, אָסוּר.\nאֵין לוֹקְחִין עֵצִים אוֹ פֵּרוֹת מִשּׁוֹמְרֵי פֵּרוֹת, אֶלָּא בִּזְמַן שֶׁהֵם יוֹשְׁבִים וּמוֹכְרִים וְהַסַלִּים וְהַפֶּלֶס בִּפְנֵיהֶם, שֶׁהֲרֵי הַדָּבָר גָּלוּי וְיֵשׁ לוֹ קוֹל; וְהוּא שֶׁיִּהְיֶה עַל פֶּתַח הַגִּנָּה.\nוְכֻלָּם שֶׁאָמְרוּ: הַטְמֵן, אָסוּר לָקַחַת מֵהֶם. \u0010c0\u0011\nמֻתָּר לִקַּח מֵהָאָרִיס, שֶׁהֲרֵי יֵשׁ לוֹ חֵלֶק בַּפֵּרוֹת וּבָעֵצִים. \u0005הַגָּה: \u0010y5\u0011 \u0010c1\u0011 וְיֵשׁ אוֹמְרִים דְּדַוְקָא לְאַחַר שֶׁחָלְקוּ, דִּסְתָמָא שֶׁלּוֹ הוּא מוֹכֵר; אֲבָל קֹדֶם חֲלֻקָּה אָסוּר, דְּחָיְשֵׁינָן שֶׁלֹּא יִתֵּן לְבַעַל הַבַּיִת נֶגֶד מַה שֶּׁנָּטַל (טוּר סכ\"א \u0010c2\u0011 [ב'])\u0006.\nאֵין לוֹקְחִין מֵהַנָּשִׁים וּמֵהָעֲבָדִים וּמֵהַקְּטַנִּים, אֶלָּא דְּבָרִים שֶׁחֶזְקָתָן שֶׁהֵם שֶׁלָּהֶם מִדַּעַת הַבְּעָלִים; \u0010c3\u0011 כְּגוֹן נָשִׁים שֶׁמָּכְרוּ \u0010y6\u0011 כְּלֵי פִשְׁתָּן בַּגָּלִיל, אוֹ עֲגָלִים בַּשָּׁרוֹן. וְלוֹקְחִים בֵּיצִים וְתַרְנְגוֹלִים בְּכָל מָקוֹם, \u0005(מִכָּל אָדָם)\u0006 ; וְכֻלָּם שֶׁאָמְרוּ: הַטְמֵן, אָסוּר. \u0005הַגָּה: מַעֲשֶׂה בְּאִשָּׁה אַחַת שֶׁהֶחֱזִיקָה בְּשֶׁל יְתוֹמִים, וְגָזְרוּ שֶׁלֹּא יִשָּׂא אוֹתָהּ שׁוּם אָדָם, כְּדֵי שֶׁלֹּא לְהַחֲזִיק יְדֵי עוֹבְרֵי עֲבֵרָה (פִּסְקֵי מהרא\"י סִימָן ר\"ס וְרס\"א)\u0006 \u0005(וְהֵבִיאוֹ גַּם כֵּן לְעֵיל סִימָן ט\"ו)\u0006.\nלוֹקְחִים מֵהַבַּדָּדִים \u0005(וְכָתַב ה\"ה פֵּרוּשׁ, בַּעֲלֵי בֵּית הַבַּד וְשׂוֹכְרִין אוֹתָן לַעֲשׂוֹת בּוֹ שֶׁמֶן, וְרַשִׁ\"י פֵרַשׁ בַּעֲלֵי בֵּית הַבַּד שֶׁתַּגָּרִין הֵן בַּשֶּׁמֶן וְלוֹקְחִים מִן נְשֵׁיהֶן בַּמִּדָּה שֶׁהִיא בְּפַרְהֶסְיָא)\u0006, זֵיתִים בַּמִּדָּה וְשֶׁמֶן בַּמִּדָּה, אֲבָל לֹא זֵיתִים מוּעָטִים וְשֶׁמֶן מוּעָט שֶׁחֶזְקָתָן גְּנֵבָה, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:\nמוֹכִין \u0010y7\u0011 שֶׁהַכּוֹבֵס מוֹצִיא הֲרֵי אֵלּוּ שֶׁלּוֹ; \u0010y8\u0011 וְשֶׁהַסוֹרֵק מוֹצִיא הֲרֵי אֵלּוּ שֶׁל בַּעַל הַבַּיִת, \u0005דְּכָל מַה שֶּׁמַּקְפִּיד עָלָיו בַּעַל הַבַּיִת הוּא שֶׁלּוֹ (טוּר ס\"ב)\u0006.\nהַכּוֹבֵס \u0010y9\u0011 נוֹטֵל ג' חוּטִין וְהֵם שֶׁלּוֹ; \u0010y10\u0011 יֶתֶר מִכָּאן, שֶׁל בַּעַל הַבַּיִת. וְאִם הָיָה \u0010y11\u0011 שָׁחוֹר עַל גַּבֵּי לָבָן, נוֹטֵל אֶת הַכֹּל וְהֵם שֶׁלּוֹ: \u0010y12\u0011\nהַחַיָּט שֶׁשִּׁיֵּר מֵהַחוּט כְּדֵי מְשִׁיכַת מַחַט, וְשִׁיֵּר מֵהַבֶּגֶד מַטְלִית שֶׁהִיא שָׁלֹשׁ אֶצְבָּעוֹת עַל שָׁלֹשׁ אֶצְבָּעוֹת, חַיָּב לְהַחֲזִירָהּ לַבְּעָלִים; פָּחוֹת מִכָּאן, שֶׁלּוֹ.\nנְסֹרֶת שֶׁהֶחָרָשׁ מוֹצִיא \u0010y13\u0011 בְּמַעֲצָד, שֶׁלּוֹ; \u0010y14\u0011 בְּכָשִׁיל, שֶׁל בַּעַל הַבַּיִת. וְאִם הָיָה עוֹשֶׂה אֵצֶל בַּעַל הַבַּיִת, אַף הַנְּסֹרֶת שֶׁל בַּעַל הַבַּיִת. \u0005וְכֵן בִּשְׁאָר מְלָאכוֹת, כָּל שֶׁבַּעַל הַבַּיִת מַקְפִּיד עָלָיו, הוּא שֶׁל בַּעַל הַבַּיִת; שֶׁאֵינוֹ מַקְפִּיד, הוּא שֶׁל פּוֹעֵל (טוּר שָׁם)\u0006.\nבְּכָל הַדְּבָרִים וְכַיּוֹצֵא בָּהֶם, הוֹלְכִים אַחַר מִנְהַג הַמְּדִינָה.\nכָּל אֻמָּן שֶׁמָּכַר דָּבָר מֵהַדְּבָרִים שֶׁאֵינָם שֶׁלּוֹ בְּהִלְכוֹת מְדִינָה, \u0010y15\u0011 כְּגוֹן מוֹכִין שֶׁמְּכָרָן הַסוֹרֵק, בְּמָקוֹם שֶׁנָּהֲגוּ שֶׁיִּהְיֶה שֶׁל בַּעַל הַבַּיִת, אָסוּר לִקַּח מִמֶּנּוּ; אֲבָל לוֹקְחִים מִמֶּנּוּ כַּר מָלֵא מוֹכִין. \u0010y16\u0011 \u0005דַּהֲרֵי נִשְׁתַּנָּה בְּיַד הַגַּנָּב; \u0010c4\u0011 וְאַף עַל גַּב דְּשִׁנּוּי הַחוֹזֵר אֵינוֹ קוֹנֶה, מִכָּל מָקוֹם בְּסָפֵק גְּנֵבָה מֻתָּר בְּכִי הַאי גַּוְנָא, וְכָל כַּיּוֹצֵא בָּזֶה (הַמַּגִּיד פ\"ו דִּגְּנֵבָה)\u0006. וְאִם מָכַר הָאֻמָּן דְּבָרִים שֶׁהֵם שֶׁלּוֹ בְּהִלְכוֹת הַמְּדִינָה, לוֹקְחִים מִמֶּנּוּ. וְאִם אָמַר: הַטְמֵן, אָסוּר:",["\u0003וכן אם רוב אותו דבר \"שהוא גנוב כו' \u0004 בטור כ' או שרוב דבר ההוא גנוב והמחבר העתיק ל' הרמב\"ם דר\"פ ו' דגזילה ור\"ל הן שחזקת אותו דבר עצמו הוא גנוב הן שאין חזקת אותן דבר עצמו הוא גנוב אלא רוב דבר ההוא הוא בחזקת גנוב וכמו שמפרש ואזיל כגון שקונה מהרועה חלב וגיזה ורוב רועים מוכרים אותן הדברים בלי ידיעת בעלי הצאן:","\u0003רוב אותו דבר שהוא גנוב \u0004 עד\"ר שם כתבתי לחלק בין הא להא דאיתא בגמ' וכתבו ג\"כ הטור והמחבר לקמן בסימן שס\"ט דמותר לקנות מהגזלן אפילו מיעוט ממינו הוא משלו ורובו גזול דשאני התם דמ\"מ יש בידו משל היתר מיעוט ממינו משא\"כ כאן דכשנאמר דזה הרועה הוא מן הרוב המוכרים שלא ברשות בעליהם נמצא שכל דבר ההוא שבידו הוא גזול וק\"ל:","\u0003חלב וגבינה במדבר \u0004 ל' הטור מפני שטורח הוא לב\"ה להביאו לישוב ומניחו לו עכ\"ל ודוקא חלב וגבינה אבל גדיים אין חילוק בין מדבר לישוב:","\u0003ד' צאן כו' \u0004 שחסרונן ניכר טובא בעדר קטן ולא מילא לבו של הרועה למכור כ\"כ בלי רשות בעלים משא\"כ בפחות מזה שאינו ניכר כ\"כ ואף אם יוכר חסרונן יכול להשמט בב' ג' ולו' שמתו או נגנבו משא\"כ בהרבה:","\u0003כל שהרועה מכרו אם היה ב\"ה \"מרגיש בו מותר ללוקחו ואם לאו אסור \u0004 המחבר קיצר בהעתקתו דסוף ל' הרמב\"ם ובזה נתן מכשול לפני המעייני' לטעות בביאור ריש דבריו ולפרש דמ\"ש כל שהרועה מכרו אם הי' ב\"ה מרגיש בו דר\"ל אף אם הי' הב\"ה מרגיש בו ועומד בצדו היה מוכרו בכה\"ג דוקא מותר לקנות ממנו כו' ואין כוונת הרמב\"ם לזה כי שם סיים אריש דבריו וכ' ז\"ל אם היה הב\"ה \"מרגיש בו ואם אין הב\"ה מרגיש בו \"אסור עכ\"ל מסוף דבריו הללו נלמד לריש דבריו דמ\"ש אם הי' ב\"ה מרגיש כו' דר\"ל אם אותו דבר שהוא מוכר הוא דבר שירגיש בו ב\"ה בחסרונו ויהיה נתפס עליו הרועה כגנב אם לא מכרו מדעתו מותר לקנות ממנו ואם לא מרגיש אסור לקנות ממנו וק\"ל:","\u0003דדוקא לאחר שחלקו כו' \u0004 לשון הטור אינו כן אלא ז\"ל בד\"א בסתם שתלינן לו' שכבר חלקו ומחלקו מכר אבל אם ידוע לו שלא חלקו אסור כו' \"ומדברי מור\"ם משמע דמסתם אסור ולא תלינן לומר שכבר חלקו והוא דיעה שלישית לא מצאתי' בשום מקום:","\u0003כלי פשתן בגליל כו' \u0004 עפ\"ר שם כתבתי דללשון שני דפרש\"י ה\"ק גליל הי' מקום שגדל וצמח שם פשתן הרבה והי' בזול ודרך אנשים של גליל שלא להקפיד על נשותיהן לקנות לעצמן פשתן ולעשות ממנו בגד פשתן ומוכרן לצורך עצמו וכן שרון הי' מקום גידול לבהמות הרבה והיו הנשים קונין ומוכרין לנפשם ברשות בעליהם וכן נראה שהוא פי' דברי הרמב\"ם ושל המחבר שהעתיק ל' הרמב\"ם:","\u0003ה\"ג שהכובס מוציא בסמך \u0004 וכ\"כ בטור ופי' דרך שטיפתו נופלין מעליו:","\u0003ושהסורק מוציא. \u0004 בא\"ח סי' ש\"א כתבתי פירושו בפרישה והוא שדרך סורקים כשנעשה הבגד היינו לאחר האריגה הוא לוקח הבגד ומותחו ע\"ג יתידות וסורקו בקוצים כדי שלא יהא נרא' חוטי האריגה אלא יכסה אותו הצמר היוצאין מחוטי האריגה והוא נוי של בגד וע\"י אותו סריקה נשמט ונשאר ג\"כ צמר הרבה בקוצים וכיון שהן הרבה יש קפידא בזה והן של ב\"ה:","\u0003נוטל ג' חוטין כו'. \u0004 ז\"ל הטור דרך אורגי בגדים לארוג בשפת הבגד ג' חוטין והן של כובס עכ\"ל ונ\"ל שהן הן שקורין בל\"א בענד\"ר וכנהוג בזמנינו והכביס' היא השריי' ואז מסירין אותן החוטין הנקראי' בענד\"ר מ\"ה קאמר שנשארו להכובס שבזמנם הי' רגיל הוא להסיר' והוא דבר מועט ואין דרך בע\"ה להקפיד עליהן:","\u0003יתר מכאן שלב\"ה. \u0004 פי' ואין להכובס אפי' ג' חוטין מהן וכ\"כ הטור בהדיא ע\"ש ודומה לזה כ' הטור והמחבר לעיל בסי' רי\"ח ורכ\"ט וש\"ל ולקמן ר\"ס שס\"ג ובשאר דוכתי וכמ\"ש שם מילתא בטעמא ע\"ש:","\u0003שחור ע\"ג לבן \u0004 דהשחור מגנה את הלבן רש\"י:","\u0003מהחוט כדי משיכת מחט כו' \u0004 ז\"ל הטור החייט ששייר מהחוט מלא מחט וחוץ למחט כו' וכן אם שייר מהמטלית בשחותכין אותו להשוותו ג' אצבעות הן של ב\"ה פחות מכן כו' והמחבר העתיק לשון הרמב\"ם שכ\"כ בפ\"ו דגניבה והמ\"מ כ' דהרמב\"ם תפס לשון הירושלמי והוא הוא השיעור הנזכר בהגמ' ושהטעם הוא דכל שנשאר מלא מחט וחוץ למחט כמלא מחט ראוי לתפור בו קצת ומקפיד עליו הבע\"ה וע\"ש בהשגת הראב\"ד על דברי הרמב\"ם בזה:","\u0003במעצד כו'. \u0004 הוא הנקרא בל\"א בריי\"ט ה\"ק והוא המפיל נסורת דקים וטורח על הב\"ה להביאן לביתו ומ\"ה הן שלו משא\"כ כשעושה בבית בע\"ה דאז אין טורח וקפיד ב\"ה אפי' אשפאים דקים ובטור כ' עוד ז\"ל וכן היוצא מתחת המקדח ומתחת הרהיטני והניגרר במגיר':","\u0003בכשיל על ב\"ה. \u0004 פירוש שבו פוסק עץ דבר ניכר וחשוב מעץ אחר גדול ממנו מ\"ה הוא של ב\"ה ובטור כ' ז\"ל וכן הנפסק במגירה כו' והוא מה\"ט ג\"כ:","\u0003כגון מוכין שמוכר הסורק כו'. \u0004 עמ\"ש לפני זה בס\"ז:","\u0003דהרי נשתנה ביד הגנב. \u0004 פי' דאין שם מוכין עליו אלא שם כר וזהו שמסיק וכ' ואע\"ג דשינוי החוזר כו' ר\"ל וזה ג\"כ שינוי החוזר הוא שהרי יכול להוציא המוכין מהכר ויהי' שם מוכין עליו כבתחלה ומשני כיון דאין המוכין ודאי גנובים ביד הסורק אלא ספק התירו לקנות ממנו בשינוי כל דהוא כזה והוא מדברי המ\"מ ע\"ש ועמ\"ש בדרי' ע\"ז:"],["\u0003 מותר ליקח מן האריס כו' \u0004 מדברי התוס' פרק אלו מציאות (בבא מציעא דף כ\"ב) סוף ע\"א והגהת אשר\"י והגהת מרדכי שם מבואר דאם אדם נותן לאכול לחברו מדבר שאינו שלו אלא של חברו אע\"פ שיודע שחברו יתרצה אסור לאכלו דהלכה כאביי דיאוש ש\"מ לא הוי יאוש ואע\"ג דהשתא ניח' ליה מעיקרא לא הוי ניח' ליה ואי לאו דמסתפינ' הייתי אומר שמותר ויאוש שלא מדעת שאני שגם אח\"כ אינו מייאש אלא משום שאינו יודע היכן הוא ובע\"כ הוא מתייאש א\"כ אמרי' מעיקרא באיסורא אתי לידי' דבמה יקנה אי ביאוש הא השת' אינו מתייאש ואלו הי' יודע שהוא אצלו לא מתייאש משא\"כ הכא כיון שידוע שיתרצ' א\"כ השתא נמי בהיתרא אתי לידיה דמסתמ' אינו מקפיד על זה ואע\"ג דבש\"ס שם מדמה תרומה וטומא' ליאוש שלא מדעת טעמ' אחרינ' איכא התם דלענין תרומה וטומא' ידיעה ממש בעינן ע\"ש ודוק ועיין בס' אגודת אזוב דף ק\"י ועיין בתשובת מהרי\"ט סי' ק\"ן:","\u0003 וי\"א דדוק' לאחר שחלקו \u0004 עיין בסמ\"ע ס\"ק ו' עד ומדברי מור\"ם משמע דמסתם אסור כו' ולי נראה דגם כוונת מור\"ם כהטור וכ\"כ הב\"ח ופסק כן ע\"ש:","\u0003 אין לוקחין מהנשים כו' \u0004 עיין בתשובת מהרא\"ן ששון סי' קצ\"ח:","\u0003 כגון נשים שמכרו כו' \u0004 עיין בתשו' מהרי\"ט סי' קל\"ט דף קפ\"ה ע\"ב ובתשובות מבי\"ט ח\"ב סי' רמ\"ב:","\u0003 ואע\"ג דשנוי החוזר כו' \u0004 עיין בב\"ח ס\"ס ש\"ס דפסק דלא כהרב המגיד וריב\"ש ול\"נ דאין הכרעתו מוכרחת בזה גם ביש\"ש פסק כהרב המגיד:"]],["\u0003הלכות גזילה\u0004\n\u0010y0\u0011 \u0010c0\u0011 אָסוּר לִגְזֹל אוֹ \u0010y1\u0011 לַעֲשֹׁק אֲפִלּוּ כָּל שֶׁהוּא, \u0010y2\u0011 בֵּין מִיִּשְׂרָאֵל \u0010c1\u0011 בֵּין מִגּוֹי; וְאִם הוּא דָּבָר דְּלֵיכָּא מַאן דְּקָפִּיד בֵּהּ, שָׁרִי; כְּגוֹן לִטֹּל מֵהַחֲבִילָה אוֹ מֵהַגָּדֵר לַחֲצוֹץ בּוֹ \u0010y3\u0011 שִׁנָּיו; וְאַף זֶה אוֹסֵר בַּיְרוּשַׁלְמִי, מִמִּדַּת חֲסִידוּת.\nאָסוּר \u0010y4\u0011 לִגְזֹל, אֲפִלּוּ עַל מְנַת לְשַׁלֵּם דָּבָר יָפֶה מִמֶּנּוּ. \u0010c2\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, \u0010y5\u0011 דְּהַיְנוּ אִם \u0005אֵין\u0006 הַתַּשְׁלוּמִין בְּעַיִן, \u0010y6\u0011 שֶׁאִם הֵם בְּעַיִן כֵּיוָן שֶׁהֵם יָפִים מֵהַדָּבָר שֶׁלּוֹקֵחַ זְכוּת הוּא \u0005(לָהֶם)\u0006 \u0010y7\u0011 \u0010c3\u0011 [לוֹ] וִיזַכֶּה אוֹתָם לַבְּעָלִים עַל יְדֵי אַחֵר.\nכָּל הַגּוֹזֵל אֶת חֲבֵרוֹ, אֲפִלּוּ שְׁוֵה \u0010y8\u0011 פְרוּטָה, כְּאִלּוּ נוֹטֵל נַפְשׁוֹ.\nאֲפִלּוּ הוּא בְּסַכָּנַת מָוֶת וְצָרִיךְ לִגְזֹל אֶת חֲבֵרוֹ כְּדֵי לְהַצִּיל נַפְשׁוֹ, שֶׁלֹּא יִקָּחֶנּוּ \u0010y9\u0011 אֶלָּא עַל דַּעַת לְשַׁלֵּם. \u0005(וְע\"ל סִימָן ש\"פ ס\"ג)\u0006.\nאֲפִלּוּ הַלּוֹקֵחַ בִּשְׁאִילָה, שֶׁלֹּא מִדַּעַת הַבְּעָלִים, נִקְרָא גַּזְלָן. \u0010y10\u0011\nהַחוֹטֵף מַשְׁכּוֹן מִיַּד הַלּוֶֹה שֶׁלֹּא בִּרְשׁוּת \u0010y11\u0011 \u0010c4\u0011 בֵּית דִּין, הֲרֵי זֶה גַּזְלָן, אַף עַל פִּי שֶׁהוּא חַיָּב לוֹ. וְאֵין צָרִיךְ לוֹמַר אִם נִכְנַס לְתוֹךְ בֵּית חֲבֵרוֹ וּמִשְׁכְּנוֹ.\nאֵיזֶהוּ גַזְלָן, \u0010y12\u0011 הַלּוֹקֵחַ מָמוֹן הָאָדָם בְּחָזְקָה, כְּגוֹן שֶׁחָטַף מִיָּדוֹ מִטַּלְטְלִים, אוֹ שֶׁנִּכְנַס לִרְשׁוּתוֹ שֶׁלֹּא לִרְצוֹן הַבְּעָלִים וְנָטַל מִשָּׁם כֵּלִים, אוֹ שֶׁתָּקַף בְּעַבְדּוֹ אוֹ בִּבְהֶמְתּוֹ וְנִשְׁתַּמֵּשׁ בָּהֶם, אוֹ שֶׁיָּרַד לְתוֹךְ שָׂדֵהוּ וְאָכַל פֵּרוֹתֶיהָ, וְכָל כַּיּוֹצֵא בָּזֶה.\nאֵיזֶהוּ עוֹשֵׁק, זֶה שֶׁבָּא מָמוֹן חֲבֵרוֹ לְתוֹךְ יָדוֹ בִּרְצוֹן הַבְּעָלִים, וְכֵיוָן שֶׁתְּבָעוּהוּ כָּבַשׁ הַמָּמוֹן בְּחָזְקָה וְלֹא הֶחֱזִירוֹ; כְּגוֹן שֶׁהָיָה לוֹ בְּיַד חֲבֵרוֹ הַלְוָאָה אוֹ שְׂכִירוּת, וְהוּא תוֹבְעוֹ, וְאֵינוֹ יָכוֹל לְהוֹצִיא מִמֶּנּוּ מִפְּנֵי שֶׁהוּא אַלָּם וְקָשֶׁה.\nהַכּוֹפֶה אֶת חֲבֵרוֹ לִמְכֹּר אֶת שֶׁלּוֹ, וְנוֹתֵן לוֹ דָּמָיו, אָסוּר, \u0010y13\u0011 אֲבָל אֵין לוֹ דִּין גַּזְלָן לִפָּסֵל מִדְּאוֹרַיְתָא, אֶלָּא מִדְּרַבָּנָן, \u0010y14\u0011 כְּמוֹ שֶׁנִּתְבָּאֵר. \u0010y15\u0011\nכָּל הַחוֹמֵד עַבְדּוֹ אוֹ אֲמָתוֹ, אוֹ בֵּיתוֹ אוֹ כֵּלָיו שֶׁל חֲבֵרוֹ, אוֹ כָּל דָּבָר שְׁאֶפְשָׁר שֶׁיִּקְנֵהוּ מִמֶּנּוּ, וְהִכְבִּיד עָלָיו רֵעִים \u0010y16\u0011 וְהִפְצִיר בּוֹ עַד שֶׁלְּקָחוֹ מִמֶּנּוּ, הֲרֵי זֶה עוֹבֵר בְּלֹא \u0010y17\u0011 תַחְמֹד \u0005(שְׁמוֹת כ, יד)\u0006. כָּל הַמִּתְאַוֶּה בֵּיתוֹ אוֹ אִשְׁתּוֹ וְכֵלָיו שֶׁל חֲבֵרוֹ וְכָל כַּיּוֹצֵא בָּזֶה, כֵּיוָן שֶׁחָשַׁב בְּלִבּוֹ \u0010y18\u0011 אֵיךְ יִקְנֶה דָּבָר זֶה וְנִפְתֶּה בְּלִבּוֹ בַּדָּבָר, עָבַר בְּלֹא תַעֲשֶׂה שֶׁל לֹא תִתְאַוֶּה \u0005(דְּבָרִים ה, יח)\u0006, וְאֵין תַּאֲוָה אֶלָּא בַּלֵּב בִּלְבַד.\nהַתַּאֲוָה מֵבִיא לִידֵי חִמּוּד, וְהַחִמּוּד מֵבִיא לִידֵי גָזֵל; שֶׁאִם לֹא רָצוּ הַבְּעָלִים לִמְכֹּר אַף עַל פִּי שֶׁהִרְבָּה לָהֶם בְּדָמִים וְהִפְצִיר בְּרֵעִים, יָבֹא לִידֵי גָּזֵל, שֶׁנֶּאֱמַר: וְחָמְדוּ בָתִּים וְגָזָלוּ \u0005(מִיכָה ב, ב)\u0006. וְאִם עָמְדוּ הַבְּעָלִים בְּפָנָיו לְהַצִּיל מָמוֹנָם אוֹ מְנָעוּהוּ מִלִּגְזֹל יָבֹא לִידֵי שְׁפִיכוּת דָּמִים, צֵא וּלְמַד מִמַּעֲשֵׂה אַחְאָב וְנָבוֹת.\nהָא לָמַדְתָּ, שֶׁהַמִּתְאַוֶּה עוֹבֵר בְּלָאו אֶחָד. וְהַקּוֹנֶה דָּבָר שֶׁהִתְאַוָּה בְּהֶפְצֵר שֶׁהִפְצִיר בַּבְּעָלִים עוֹבֵר בִּשְׁנֵי לָאוִין, לְכָךְ נֶאֱמַר: לֹא תַחְמֹד \u0005(שְׁמוֹת כ, יד)\u0006 וְלֹא תִתִאַוֶּה \u0005(דְּבָרִים ה, יח)\u0006 וְאִם גָּזַל, עוֹבֵר בִּשְׁלֹשָׁה לָאוִין:",["\u0003אסור לגזול או לעשוק כו'. \u0004 דגם לא תעשוק את רעך כתיב ובסמוך סעיף ז' ח' יתבאר מה בין גזל לעשק וכן הוא בטור שם:","\u0003אפי' כל שהוא \u0004 דחצי שיעור הוא איסור דאורייתא כמו שאסור חצי שיעור באיסורין:","\u0003בין מישראל בין מעכו\"ם. \u0004 דגזל העכו\"ם וגניבתן אסור ולא התירו אלא להטעותן בחשבון והפקעת הלוואתו ודוקא בדבר שלא יוודע לו כגון שהיה חייב לאבי העכו\"ם וכמ\"ש בר\"ס שמ\"ח ומור\"ם כתב שם בהג\"ה דעת האומר דאפי' בכה\"ג אסור כ\"א בהטעה מעצמו ע\"ש:","\u0003ואף זה אוסר \u0004 בירושלמי הטעם כתב הנ\"י דאלו עושה כן כל אחד נמצא החבילה כלה והגדר נהרס עכ\"ל:","\u0003אפי' ע\"מ לשלם כו' \u0004 בגמ' יליף לה מדכתיב חבול ישיב רשע גזילה ישלם ר\"ל אע\"ג דגזילה ישלם רשע מיקרי עפ\"ר:","\u0003דהיינו אם אין כו' \u0004 הטעם שמא לא יהיה לו במה לשלם אח\"כ כ\"כ הרא\"ש:","\u0003שאם הן בעין כו' \u0004 פי' והן מין אחר והגזלן צריך למין זה שגוזל כעין מעשה שהי' שהיו בעלי דוד צריכין שעורין לבהמתן והיו רוצים לשלם תחתיהם עדשים שלא היו ראוים לבהמתם:","\u0003ויזכה אותם להבעלים ע\"י אחר \u0004 פי' אם אין הבעלים כאן אמרי' מסתמא ניחא ליה וזכין לאדם שלא בפניו אבל כשאינו בעין אף שקיבל אנפשו ליתן לו דבר הטוב ממנו מסתמא לא ניח' לבעלים לירד עמו בדינא ודיינא ולפעמי' לא יהי' לו במה לו לשלם ואם היו הבעלים כאן ואומרים ניח' לנו בשלנו ולא בדבר אחר אף הטוב ממנו נראה פשוט דלכ\"ע אסור:","\u0003כאלו נוטל נפשו. \u0004 שנא' וקבע את קובעיה' נפש ולעיל בסי' שמ\"ח ושל\"ט כתבתי דיש פלוגת' בזה אם נפשו של גזלן או נפשו של נגזל קאמר:","\u0003אלא על דעת לשלם. \u0004 פי' אבל על דעת לשלם מותר כיון שהוא בסכנת נפש דאין לך דבר שעומד בפני פקוח נפש טור ועפ\"ר:","\u0003החוטף משכון כו' \u0004 ע\"ל בר\"ס צ' בדברי הטור והמחבר מ\"ש:","\u0003הרי זה גזלן בטור כתוב ונקר' גזלן ר\"ל שהוא בכלל איסור גזילה וגם הוא פסול לעדות ולשבועה אבל עיקר הגזיל' דאזהר הכתוב עליו לא מיירי בחוטף למשכנו על מה שחייב לו אלא כמ\"ש המחבר בסעיף שאחר זה ז\"ל איזה גזלן כו' ושם בא לחלק מה בין גזלן לעשק הכתובי' בסוף פ' ויקרא או גזל או עשק בפ' אשם גזילות ע\"ש ועד\"ר:\u0004","\u0003הלוקח ממון האדם בחזקה כו' \u0004 כדכתיב ויגזול את החנית מיד המצרי:","\u0003אבל אין לו דין גזלן לפסול מדאורייתא \u0004 פי' אף דהוא עובר בלאו דלא תחמוד (וכמ\"ש בסעיף שאח\"ז וכ\"כ בטור) מ\"מ אינו נפסל לעדות ולשבועה דלא תחמוד לאינשי בלא דמי משמע להו ודלא ☜ כע\"ש שכתב ז\"ל שאינו עובר על לאו דאורייתא וע\"ל סי' ל\"ד מ\"ש עוד מזה:","\u0003כמו שנתבאר בסי' ל\"ד נתבאר שם בטור ובדברי המחבר בסי\"ג דאינן פסולין כ\"א מדרבנן ע\"ש:\u0004","\u0003כל החומד עבדו כו' \u0004 הא דהתחיל הרמב\"ם והמחב' באיסור לאו דלא תחמוד קודם שכ' איסור לאו דלא תתאוה אף שהמחשב' \"דתאר קודם למעשה דחמוד דכן כתבוהו אחר זה משום דבמאי דסיים פתח דבסעיף ט' סיים וכ' דהכופה את חבירו למכור כו' הוא בלאו דלא תחמוד וכמ\"ש מ\"ה כ' ברישא ביאור דאותו לאו דהוא כל החומד כו':","\u0003והפציר בו עד שלקחו \u0004 אבל בלא לקיחה אינו עובר בלא תחמוד כ\"כ ברמב\"ם בהדיא ולמדו שם מדכתיב לא תחמוד כסף וזהב עליהן \"ולקחת לך:","\u0003כל המתאוה ביתו וכו' \u0004 שם ברמב\"ם מסיים בזה ז\"ל וכן כל כיוצא מזה מדברים \"שאפשר לקנותן ממנו כו' אבל הטור כ' בשם הרמב\"ם לשון אחר ז\"ל וכל כיוצא באלו מדברים שאי \"אפשר לקנותן. ועפ\"ר שכתבתי ביאורו וטעם דנוסח' הראשונ' נ\"ל דלדוקא כ' שאפשר לקנותו דאלו דברים שאי אפשר לקנותן אינו עובר בלא תתאוה כיון דלא יבואו לידי מעשה כמו דאינו עובר על לא תחמוד כל שלא בא לידי לקיחה והטור כ' רבותא דאפי' בדברים שא\"א לקנותן עובר כ\"ש בדברים האפשריים ודוק:","\u0003איך יקנה דבר זה \u0004 גם באשת חברו שייך זה שיגרום שיגרשנה בעלה והוא ישאנ' ואפשר דמפני שהוא קשה יותר משאר דברים וצריך עליו מחשב' טפי מ\"ה נקטו הרמב\"ם והמחבר בלאו דלא תתאוה:"],["\u0003 אסור לגזול או לעשוק \u0004 בש\"ס ריש ב\"ק משמע דבגזלן חייב לשלם מעידיות כמזיק וכ\"פ הרי\"ף והרא\"ש והנ\"י שם וכן מהרש\"ל שם סי' ו' וכן ה\"ה לקמן סי' שפ\"ה וסי' שפ\"ח ס\"ב ועמ\"ש לקמן סי' ת\"ך ס\"ג:","\u0003 בין מעכו\"ם. \u0004 כ' הכ\"מ דדייק הרמב\"ם לכתו' אסור לגזלו או לעשקו גבי עכו\"ם ולא כ' שעובר עליו לומר שאין איסור זה מן התורה ומדברי הרמב\"ם ריש הל' גנבה שהעתיק המחבר לעיל ר\"ס שמ\"ח לא משמע כן וכן כ' מהרש\"ל פרק הגוזל שמדברי הרמב\"ם אלו וסמ\"ג משמע שאסור מן התורה מיהו לענין דינא הכריע מהרש\"ל שם כפירש\"י בסנהדרין דאינו אלא מדרבנן ע\"ש ועמ\"ש לעיל ר\"ס שמ\"ח עיין בתשו' רמ\"א ר\"ס ט':","\u0003 ויש מי שאומר כו' \u0004 ואע\"ג דאמרינן לעיל ר\"ס שמ\"ח דאסור לגנוב ע\"מ לשלם כפל התם מיירי בשאינו מזכה לו ע\"י אחר דאם מזכה לו ע\"י אחר לאו גנבה מיקרי כיון שהאחר יודע מזה כן נ\"ל והב\"ח תירץ בדוחק:","\u0003 ויזכה אותם לבעלים כו' \u0004 ודוקא שידוע שזכות הוא לו כגון בדבר העומד לימכר אבל בחפצי ביתו לא כן כ' הטור ומשמע מדבריו דהרא\"ש מיירי בכה\"ג ובהכי ניחא דל\"ק כל מה שהקשה מהרש\"ל פרק הכונס סי' כ\"ז על הרא\"ש ובהכי ניחא נמי דהתוספות פרק הכונס ריש (בבא קמא דף ס\"א) לא פליגי לענין דינא אהרא\"ש ע\"ש ודוק ונראה דמ\"ש הטור בדבר העומד לימכר ר\"ל שידוע בבירור שהבעל לא יחזיקנו בעצמו רק ימכרנו ודו\"ק:","\u0003 הרי זה גזלן כו' \u0004 הרב בס' בדק הבית לעיל סי' ל\"ד כ' על דברי הרמב\"ם אלו וז\"ל ומשמע לי שאינו נפסל לעדות בכך משום דלא משמע להו לאינשי דליהוי גזלן בהכי עכ\"ל ולא ידעתי אמאי כ' כן בפשיטות דהא מדברי הראב\"ד והרב המגיד והטור משמע דלהרמב\"ם שם נפסל לעדות ומסכים הרב המגיד שם לדברי הרמב\"ם וגם קשה בנכנס לבית חברו דהא הטור כ' לעיל ר\"ס צ' בשם הר' ישעיה דמיפסל בהכי והביאו המחבר גופיה שם סעיף א' מיהו בחוטף משכון נראה דיפה כ' לדינא וכן מוכח מדברי רשב\"ם פ' חזקת הבתים (בבא בתרא דף ל\"ד) וכ\"כ ראב\"ן להדיא בסי' כ\"ו ד' י\"ד ע\"ג וע\"ד ע\"ש מיהו מדברי הראב\"ד בהשגות ספ\"ג מהלכות גזילה ומדברי הרב המגיד שם משמע דלהרמב\"ם בהנך תרתי מיפסל לעדות אך שהראב\"ד משיג שם עליו דלא הוי גזלן אלא בדאשתכח שאינו חייב לו ומביא הטור דברי הרמב\"ם והשגת הראב\"ד בקצרה ע\"ש מיהו המגדול עוז שם מיישב דברי הרמב\"ם דלא קראו גזלן אלא לקנותו להעמיד באחריותו ולא שיפסל לעדות ושבוע' ע\"ש שהאריך וכן נראה עיקר לדינא עכ\"פ בחוטף משכון ודלא כהסמ\"ע ס\"ק י\"ב שנמשך אחר הבנת הראב\"ד בהרמב\"ם לענין דינא ודוק ומוכח בדברי רשב\"ם וראב\"ן שם אפי' בסתם חוטף משכון ואינו מברר שחייב לו לא מיפסל ע\"ש ודו\"ק:"]],["כָּל הַגּוֹזֵל \u0010y0\u0011 חַיָּב לְהַחֲזִיר הַגְּזֵלָה עַצְמָהּ, שֶׁנֶּאֱמַר: וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל \u0005(וַיִּקְרָא ה, כג)\u0006. וְאִם אָבְדָה אוֹ נִשְׁתַּנֵּית, \u0010y1\u0011 מְשַׁלֵּם דָּמֶיהָ, בֵּין שֶׁהוֹדָה מִפִּי עַצְמוֹ \u0010y2\u0011 בֵּין שֶׁבָּאוּ עָלָיו עֵדִים שֶׁגָּזַל. אֲפִלּוּ גָּזַל קוֹרָה וּבְנָאָהּ בְּבִירָה גְדוֹלָה, הוֹאִיל וְלֹא נִשְׁתַּנֵּית, דִּין תּוֹרָה הוּא שֶׁיַּהֲרֹס כָּל הַבִּנְיָן וְיַחֲזֹר הַקּוֹרָה לַבְּעָלִים; אֲבָל תִּקְּנוּ חֲכָמִים, מִפְּנֵי תַּקָּנַת הַשָּׁבִים, שֶׁיִּהְיֶה נוֹתֵן אֶת דָּמֶיהָ וְלֹא יַפְסִיד הַבִּנְיָן. אֲפִלּוּ גָזַל קוֹרָה \u0010y3\u0011 וַעֲשָׂאָהּ בְּסֻכּוֹת הֶחָג, וּבָא בַּעַל הַקּוֹרָה וְתוֹבְעָהּ בְּתוֹךְ הֶחָג, נוֹתֵן לוֹ אֶת דָּמֶיהָ. אֲבָל אַחַר הֶחָג, הוֹאִיל וְלֹא נִשְׁתַּנֵּית \u0010y4\u0011 וְלֹא בְּנָאָהּ בְּטִיט, מַחֲזִיר אֶת הַקּוֹרָה עַצְמָהּ. \u0005הַגָּה: גָּזַל קַרְקַע וּבָנָה עָלֶיהָ בִּנְיָנִים גְּדוֹלִים, צָרִיךְ לִסְתֹּר הַכֹּל וּלְהָשִׁיב קַרְקַע לַבְּעָלִים, \u0010y5\u0011 דְּלָא עָשׂוּ תַקָּנַת הַשָּׁבִים בְּקַרְקַע (ר' יְרוּחָם נל\"א ח\"ו)\u0006.\nהַגּוֹזֵל פָּחוֹת מִשְּׁוֵה פְרוּטָה, \u0010y6\u0011 אַף עַל פִּי שֶׁעָבַר, אֵינוֹ בְּתוֹרַת הֲשָׁבָה.\nגָּזַל \u0010y7\u0011 ג' אֲגֻדּוֹת שָׁווֹת שְׁלֹשָׁה פְרוּטוֹת, וְהוּזְלוּ וַהֲרֵי שְׁלָשְׁתָּן שָׁווֹת ב' פְּרוּטוֹת, וְהֶחֱזִיר לוֹ שְׁתַּיִם, חַיָּב לְהַחֲזִיר הַשְּׁלִישִׁית הוֹאִיל וּבִתְחִלָּתָהּ הָיְתָה שָׁוָה פְּרוּטָה.\nגָּזַל שְׁתַּיִם שָׁווֹת פְּרוּטָה, וְהֶחֱזִיר אַחַת, \u0010y8\u0011 אַף עַל פִּי שֶׁגְּזֵלָה אֵין כָּאן, מִצְוַת הֲשָׁבַת גְּזֵלָה אֵין כָּאן.\nנִשְׁתַּנֵּית הַגְּזֵלָה, אַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ הַבְּעָלִים, אֵין צָרִיךְ לְהַחֲזִיר אֶלָּא דָּמֶיהָ כְּמוֹ שֶׁהָיְתָה שָׁוָה בִּשְׁעַת הַגְּזֵלָה, וְהוּא שֶׁלֹּא יְהֵא שִׁנּוּי הַחוֹזֵר לִבְרִיָּתוֹ. כֵּיצַד, הַגּוֹזֵל עֵצִים וְדִבְּקָם בְּמַסְמֵרִים וְעָשָׂה מֵהֶם תֵּבָה, אֵינוֹ שִׁנּוּי, שֶׁהֲרֵי אֶפְשָׁר לְפָרְקָן וְחוֹזְרִים לוּחוֹת כְּשֶׁהָיוּ. \u0010y9\u0011 גָּזַל עָפָר וַעֲשָׂאוֹ לְבֵנָה, לֹא קָנָה, שֶׁאִם יָדוֹק הַלְּבֵנָה תַּחֲזֹר עָפָר כְּשֶׁהָיְתָה. גָּזַל לָשׁוֹן שֶׁל מַתֶּכֶת \u0010y10\u0011 \u0010c0\u0011 וַעֲשָׂאוֹ מַטְבֵּעַ, לֹא קָנָה, שֶׁאִם יַתִּיךְ הַמַּטְבֵּעַ \u0010y11\u0011 יַחֲזֹר לָשׁוֹן כְּשֶׁהָיָה; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010y12\u0011\nאֲבָל הַגּוֹזֵל עֵצִים וְשִׁפָּן וּקְצָצָן, אוֹ חָקַק בָּהֶם וְעָשָׂה כֵּלִים, אוֹ שֶׁגָּזַל \u0010y13\u0011 \u0010c1\u0011 צֶמֶר וּצְבָעוֹ אוֹ נִפְּצוֹ \u0010c2\u0011 אוֹ לִבְּנוֹ אוֹ עֲשָׂאוֹ לְבָדִים, אוֹ שֶׁגָּזַל לְבֵנָה וַעֲשָׂאָהּ עָפָר, אוֹ אֲבָנִים וְסִתְּתָן, אוֹ מָעוֹת וְהִתִּיכָן, הֲרֵי זֶה שִׁנּוּי בְּיָדוֹ, שֶׁאִם יַעֲשֶׂה מָעוֹת אֲחֵרוֹת פָּנִים חֲדָשׁוֹת הֵן, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005וְאֵין נִקְרָא \u0010y14\u0011 \u0010c3\u0011 שִׁנּוּי אֶלָּא אִם כֵּן נִשְׁתַּנָּה שֵׁם הַגְּזֵלָה מִכֹּחַ הַשִּׁנּוּי (טוּר ס\"ד)\u0006.\nהַגּוֹזֵל מָעוֹת יְשָׁנוֹת וְשִׁפָּן וְחִדְּשָׁן, לֹא קָנָה, שֶׁהֲרֵי מִתְיַשְּׁנִין וְחוֹזְרִים כְּשֶׁהָיוּ. גָּזַל מָעוֹת חֲדָשִׁים וְיִשְּׁנָן, קָנָה, שֶׁאִם יְחַדְּשֵׁם פָּנִים חֲדָשׁוֹת הֵם. \u0010y15\u0011 \u0010c4\u0011 \u0005גָּזַל אֲבָנִים וְסִתְּתָן, קָנָה. צֶמֶר, וּצְבָעוֹ אוֹ לִבְּנוֹ בְּעִנְיָן שֶׁאֵינוֹ חוֹזֵר לִבְרִיָּתוֹ, קָנָה (טוּר שָׁם)\u0006.\nגָּזַל דֶּקֶל מְחֻבָּר וּקְצָצוֹ, לֹא קָנָה; אֲפִלּוּ כְּרָתוֹ חוּלְיוֹת חוּלְיוֹת. עֲשָׂאוֹ קוֹרוֹת, קָנָה.\nגָּזַל קוֹרוֹת גְּדוֹלוֹת וַעֲשָׂאָן קְטַנּוֹת, לֹא קָנָה. קְצָצָן לוּחוֹת עַד שֶׁנִּשְׁתַּנָה שְׁמָם, קָנָה.\nגָּזַל לוּלָב \u0010y16\u0011 וְהִפְרִיד עָלָיו, קָנָה הֶעָלִין. גָּזַל עָלִים \u0010y17\u0011 וַעֲשָׂאָן חוּפְיָא, קָנָה. \u0005טָלֶה וְנַעֲשָׂה אַיִל, עֵגֶל וְנַעֲשָׂה שׁוֹר, קָנָה (טוּר שָׁם)\u0006.",["\u0003חייב להחזיר הגזילה כו' \u0004 דוקא הגזילה ולא כפל דאין כפל כ\"א בגנב:","\u0003משלם דמי' ילפינן מדכתיב אשר גזל דדוקא אם כשהיא כאשר גזלה צריך להחזירה בעינה הא אם נשתנית שינוי שאינו חוזר לכמות שהית' כבר קנאה בשינוי ואין עליו אלא חוב דמי שוויה כמו שהית' בשעת הגזיל' וכמו שנתבאר בהל' גניבה ששוין הן בזה:\u0004","\u0003בין שבאו עליו עדים כו' \u0004 ולא כדין גנב שבאו עליו עדים שגנב דחייב לשלם כפל כמו שנתבאר בטור סי' שמ\"ח ע\"ש:","\u0003ועשאה בסוכות החג \u0004 פי' אף דסוכה בנין עראי הוא מ\"מ המצוה קובעה כל ז' ימי החג לעשותו כבנין קבוע:","\u0003ולא בנאה בטיט דטיט מחשבי' לבנין קבע וע\"ל בטור בס\"ס קנ\"ז ובס\"ס רי\"ד בטור ובדברי המחבר:\u0004","\u0003דלא עשו תקנת השבים בקרקע \u0004 דכיון דהוא דבר קבוע ועומד ה\"ל למידע דשל הנגזל הוא ולא ה\"ל לקנותו:","\u0003אע\"פ שעבר \u0004 דהתורה אזהריה גם אחצי שיעור וכמ\"ש בר\"ס שנ\"ט:","\u0003שלש אגודות שוות ג' פרוטות כו' \u0004 וכ\"ש אם גזל א' שוה פרוטה והוזלה דצריך להשיב אותה או דמיה ש\"פ כמו שהיתה מתחלה אלא לרבותא נקט ג' אגודות כו' דאע\"ג דכבר קיים מצות השבה במה שהחזיר שתים אפ\"ה צריך להחזיר השלישי כ\"כ התו' והטור סיים בזה וכתב ז\"ל וכ\"ש אם גזל ב' אגודות שוות שני פרוטות והוזלו ועמדו על א' והחזיר לו א' שצריך להחזיר לו גם השני שהרי לא קיים מצות השבה כלל עכ\"ל:","\u0003אע\"פ שגזילה אין כאן כו' \u0004 הטור כ\"כ בשם הרמ\"ה בתוס' ביאור ז\"ל אע\"פ שאין כאן גזילה ואין ב\"ד נזקקין לכופו בתורת ממון (דאין ב\"ד נזקקין בתחלת דין לפחות מש\"פ כמ\"ש הט\"ו לעיל בסי' ו') מצות השבה אין כאן ומכין אותו עד שתצא נפשו או מקיים מצות השבה עכ\"ל ועד\"ר מ\"ש מזה:","\u0003גזל עפר ועשאה לבינה \u0004 עפ\"ר שם כתבתי דדעת הרשב\"א דדוקא שיבשן בחמה ולא כשצרפן אותו בכבשן דאז א\"א לכותשן לעפר דק כבתחלה ובדרישה כתבתי דמל' הטור משמע אפי' שרפן בכבשן וה\"ט דבעפר דאינו חשוב אין קפיד' אף כשלא הוחזר לגמרי דק וכתוש כבראשונה משא\"כ בנמטי להעשות צמר דקפדינן אצמר דהיא דבר חשוב להעשו' בו מלאכתו הראשונה:","\u0003ועשא' מטבע כו' \u0004 ☜ ובאם עשה ממנו כלי כסף יש בו פלוגתא התוס' ס\"ל דקנה והרשב\"א חולק וד\"מ ד' הביאם ע\"ש:","\u0003יחזור לשון כשהיה \u0004 ואף דא\"א לצמצם אין קפיד' בנסכא משא\"כ כשגזל מטבע ושינהו לנסכא דאם יבא לחזור לעשות מטבע היה פנים חדשות דא\"א לצמצם לעשות כבראשונה ובזה יש קפידא וכן בגזל לבינה ועשה ממנה עפר וכמ\"ש בסעיף שאח\"ז:","\u0003אבל הגוזל עצים ושיפן וקצצן כו' \u0004 בטור ס\"ז כתב דשיפוי לא מיקרי שינוי אא\"כ שיפן ונעשה בזה שינוי שם כגון שיפה העץ ועש' ממנו מכתשת ודוחק לומר שכוונת המחבר היה שעבד תרתי ששיפן וקצצן:","\u0003צמר וצבעו היינו בצבע שאינו יכול להעבירה \u0004 וכמ\"ש בס\"ס שנ\"ח:","\u0003נשתנה שם הגזיל' \u0004 ומה\"ט כתב המחבר עצמו אחר זה בס\"ט בגזל קורות גדולות ועשה מהן קטנות דלא קנה ובקצצן עד שנשתנה שמן קנה:","\u0003גזל אבנים וסתתן כו' צמר וצבעו או לבנו כו' \u0004 כל זה כבר כתב ג\"כ המחבר בס\"ו ונראה דמור\"ם הנמשך אחר ל' הטור וסדרו אשתמיטת' מיניה מ\"ש המחבר לפני זה על סדר הרמב\"ם וכיוצא בזה מצינו טובא בדברי מור\"ם כפלים מה\"ט:","\u0003והפריד עליו כו' \u0004 דיש לו שינוי השם ומקרי הוצא כיון שנתקן מהשדרה:","\u0003ועשאו חופיא \u0004 הוא כעין מכבדות שלנו שמכבדין בו עפר החדרי' דמעיקרא מקרי הוצא והשתא חופיא:"],["\u0003 ועשאו מטבע כו' \u0004 ובאם עשו ממנו כלי כסף יש בו פלוגתא התוס' ס\"ל דקנה והרשב\"א חולק עכ\"ל סמ\"ע ולחנם הביא דברי התוספות דהתוס' עצמם מדמי לה לנסרים ועשאו תיבה למ\"ד דשינוי החוזר הוי שינוי וא\"כ אנן דקי\"ל דשינוי החוזר לא הוי שינוי וכמ\"ש הפוסקים והטור בנסרים וכה\"ג א\"כ ה\"ה בעשה ממנו כלי לא הוי שינוי וכן הוא בראב\"ן דף ך' ע\"ב וכ\"פ מהרש\"ל ריש הגוזל וכן עיקר:","\u0003 צמר וצבעו. \u0004 היינו בצבע שא\"י להעביר וכמ\"ש בס\"ס שצ\"ח עכ\"ל סמ\"ע וכוון למ\"ש בהג\"ה שם דשינוי החוזר אינו קונה וטפי ה\"ל ללמוד ממ\"ש הרמב\"ם והט\"ו בכאן סעיף ה' וגם בסעיף ז' בצבעו כתבו כן להדיא ומלעיל ס\"ס שנ\"ח אין ראי' כ\"כ דהא ר' ירוחם ס\"ל דשינוי החוזר (אינו) קונה ואפ\"ה פסק דאע\"ג דיכול להעבירו הוי שינוי מיהו לענין דינא לא נראה כר' ירוחם ולא מטעמא שהקשה בב\"ח מנ\"ל לחלק בין צביעה ללבון דזה ל\"ק כלל דהא רבנן דפליגי עליה דר\"ש ס\"ל הכי דלבון לא הוי שינוי וצביע' הוי שינוי אפילו יכול להעבירו וכדאיתא בש\"ס ריש הגוזל קמא ונראה שזהו טעמו של ר' ירוחם שפסק כרבנן אבל באמת נראה דהיינו דוקא למ\"ד שינוי החוזר קונה אבל למאי דקי\"ל דאינו קונה א\"כ כשיכול להעבירו לא הוי שינוי וכן מוכח להדיא בתוס' פ' מרובה סוף (בבא קמא דף ס\"ה) וכן הוא בראב\"ן דף פ\"ט ע\"ב:","\u0003 או לבנו כו' \u0004 תימה דבש\"ס ריש הגוזל אמרי' דלבנו לא הוי שינוי כמו בראשית הגז וכ\"פ המחבר עצמו בי\"ד סי' של\"ג ס\"ג מיהו ברמב\"ם לק\"מ דכ' ונפצו ולבנו ובהלכות בכורים פ\"י גבי ראשית הגז לא כ' רק לבנו לחוד ונראה דס\"ל דלר' חייא דקאמר דכבריה כברויה בגפרית היינו דבתר הנפוץ מלבנו וכ\"פ הרא\"ש וטור ומהרש\"ל דדוקא בלבנו ע\"י גפרית הוי שינוי אבל על המחבר שכ' או לבנו קשה וצריך לומר דט\"ס הוא בספרי המחבר וכן בע\"ש:","\u0003 אלא א\"כ נשתנה שם הגזילה כו' \u0004 טור. ובספר ת\"ח חולק בלא טענה מוכרח' גם מה שהביא ראיה מהרמב\"ם והמחבר שכתבו סתמא דשפוי מועיל דהוי שינוי ולא חילקו אינו ראיה דהא כתבו אח\"כ בס\"ט עד שנשתנה שמם כו' א\"כ גם מ\"ש ושיפן ר\"ל שנשתנה שמם מחמת השפוי וכ\"כ בע\"ש הילכך אין לנו אלא דברי התוס' והרא\"ש והטור והרב וכ\"פ מהרש\"ל:","\u0003 גזל אבנים וסתתן כו' \u0004 דברי הר\"ב נתבארו בדברי המחבר בסמוך סעיף ו' ולכאורה הם אך למותר וגם הם מגומגמין במ\"ש או ליבנו בענין שאינו חוזר לברייתו וגם בב\"ח כ\"כ דהיכא שייך בליבון חוזר לברייתו ובטור איתא צמר ולבנו בגפרית או צבעו בענין שאינו חוזר לברייתו קנה עכ\"ל וקאי רק אצבעו לחוד דאתי לאפוקי היכא דיכול להעביר הצבע ע\"י צפון כדאיתא בש\"ס ומ\"ש ולבנו בגפרית היינו כברי' כברוי' דבש\"ס דאל\"כ לא הוי ליבון מעליא ולא הוי שינוי אפי' אינו חוזר ועיין בש\"ס פ' הגוזל מוכח להדיא כדברי:"]],["\u0010y0\u0011 יֵאוּשׁ לְחוּד לֹא קָנָה.\nיֵאוּשׁ \u0010y1\u0011 עִם שִׁנּוּי הַשֵּׁם גָּרוּעַ שֶׁחוֹזֵר לִבְרִיָּתוֹ, יֵשׁ אוֹמְרִים שֶׁקּוֹנֶה \u0010y2\u0011 וְאֵינוֹ צָרִיךְ לְהַחֲזִיר אֶלָּא דָּמֶיהָ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּיָדוּעַ שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים. אֲבָל \u0010y3\u0011 סְתָם גְּזֵלָה לָא הֲוֵי יֵאוּשׁ בְּעָלִים.\nיֵאוּשׁ עִם שִׁנּוּי רְשׁוּת, קָנָה, וְנִתְבָּאֲרוּ מִשְׁפָּטָיו בְּסִימָן שנ\"ג.\nלָא הֲוֵי \u0010y4\u0011 \u0010c0\u0011 שִׁנּוּי, אֶלָּא אִם כֵּן מְכָרוֹ אוֹ נְתָנוֹ לְאַחֵר. \u0010c1\u0011 \u0005יֵשׁ אוֹמְרִים (נִמּוּקֵי יוֹסֵף פֶּרֶק חז\"ה)\u0006 דְּאִם מְכָרוֹ בְּאַחֲרָיוּת \u0010c2\u0011 אוֹ נְתָנוֹ בְּטָעוּת אוֹ בְעַל כָּרְחוֹ, לֹא מִקְרֵי שִׁנּוּי רְשׁוּת \u0005(תְּשׁוּבַת רַשְׁבָּ\"א סִימָן תתקס\"ח)\u0006, אֲבָל אִם בָּא אַחֵר וּנְטָלוֹ מִבֵּית הַגַּזְלָן שֶׁלֹּא מֵרְצוֹנוֹ, כְּאִלּוּ נְטָלוֹ מִבֵּית הַבְּעָלִים, אִם יִרְצֶה הַנִּגְזָל גּוֹבֶה מֵהָרִאשׁוֹן אוֹ מֵהַשֵּׁנִי, אוֹ אִם יִרְצֶה יִגְבֶּה חֲצִי מִזֶּה וַחֲצִי מִזֶּה. וְאִם פְּרָעוֹ הַשֵּׁנִי לָרִאשׁוֹן, אוֹ שֶׁהַגַּזְלָן הָרִאשׁוֹן מָחַל לַשֵּׁנִי, אֵינוֹ כְּלוּם, \u0010y5\u0011 כִּי אֵין דִּינוֹ שֶׁל שֵׁנִי אֶלָּא עִם הַבְּעָלִים, לֹא שְׁנָא אִם יָדַע הַשֵּׁנִי שֶׁהוּא גָּזוּל בְּיַד הַגַּזְלָן, לֹא שְׁנָא שֶׁלֹּא יָדַע; וַאֲפִלּוּ אִם אֲכָלוֹ הַשֵּׁנִי, חַיָּב לְשַׁלֵּם לַבְּעָלִים.\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁלֹּא נִתְיָאֲשׁוּ. אֲבָל אִם נִתְיָאֲשׁוּ וּבָא אֶחָד וַאֲכָלוֹ, פָּטוּר; נְהִי שֶׁאִם הָיָה בְּעַיִן הָיָה חַיָּב לְהַחֲזִירוֹ, \u0010y6\u0011 עַתָּה שֶׁאֲכָלוֹ, פָּטוּר.\nמֵת וְהוֹרִישׁ הַגְּזֵלָה לְבָנָיו, \u0010y7\u0011 לָא הֲוֵי שִׁנּוּי רְשׁוּת, אֶלָּא הָוֵי כְּאִלּוּ אֲבִיהֶם קַיָּם, שֶׁאִם הוּא בְּעַיִן וְלֹא נִשְׁתַּנֵּית, צְרִיכִים לְהַחֲזִירָהּ אֲפִלּוּ נִתְיָאֲשׁוּ הַבְּעָלִים; וְאִם נִשְׁתַּנֵּית וְהִיא קַיֶּמֶת, נוֹתְנִים דָּמֶיהָ. אֲבָל אִם אֲכָלוּהָ, בֵּין בְּחַיֵּי הָאָב בֵּין לְאַחַר מוֹתוֹ, אִם קֹדֶם יֵאוּשׁ אֲכָלוּהָ חַיָּבִים לְשַׁלֵּם; \u0010y8\u0011 לְאַחַר יֵאוּשׁ פְּטוּרִים, אִם לֹא הִנִּיחַ אֲבִיהֶם נְכָסִים; \u0010y9\u0011 אֲבָל אִם הִנִּיחַ אֲבִיהֶם נְכָסִים, אֲפִלּוּ אֲכָלוּהָ אַחַר יֵאוּשׁ חַיָּבִים לְשַׁלֵּם. וְכֵן אִם מְכָרָהּ הָאָב אוֹ נְתָנָהּ לְאַחֵר, אִם הִנִּיחַ נְכָסִים חַיָּבִים לְשַׁלֵּם. וְאֵין חִלּוּק בְּזֶה \u0010y10\u0011 בֵּין גְּדוֹלִים לִקְטַנִּים. \u0010y11\u0011 \u0010c3\u0011 וְאִם אָמְרוּ הַגְּדוֹלִים: יוֹדְעִים אָנוּ \u0010c4\u0011 שֶׁעָשָׂה אָבִינוּ חֶשְׁבּוֹן עִמְּךָ וְלֹא נִשְׁאַר לְךָ כְּלוּם בְּיָדוֹ, \u0010c5\u0011 נֶאֱמָנִים. וְיֵשׁ אוֹמְרִים דְּהָנֵי מִלֵּי כְּשֶׁאֵין יָדוּעַ שֶׁגְּזָלָהּ אֲבִיהֶם, אֶלָּא עַל פִּיהֶם; \u0010y12\u0011 \u0010c6\u0011 אֲבָל אִם הָיוּ עֵדִים שֶׁגְּזָלָהּ, אֵינָם נֶאֱמָנִים.\nהַגּוֹזֵל אֶת חֲבֵרוֹ בְּעֵדִים, יֵשׁ אוֹמְרִים שֶׁאֵינוֹ צָרִיךְ לְהַחֲזִיר לוֹ בְּעֵדִים, \u0010y13\u0011 \u0010c7\u0011 וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ:",["\u0003יאוש לחוד לא קנה \u0004 הטור מסיק וכתב בזה ז\"ל מיהו אם קידש בו האשה צריכה גט עכ\"ל וכ\"כ הטור בשם הרא\"ש בסי' שנ\"ג והמחבר השמיטו כאן ושם ועיין מ\"ש שם:","\u0003עם שינוי שם גרוע כו' \u0004 פי' אפילו אם הוא גרוע:","\u0003ואינו צריך להחזיר כו' \u0004 כבר נתבאר בסי' שלפני זה:","\u0003סתם גזילה לא הוי יאוש כו' \u0004 שהרי יודע מי גוזלו ויוציאנו ממנו במשפט משא\"כ בסתם גניבה דכיון דלא ידעו הבעלים מי גנבו מייאשו ממנו וע\"ל בטור ובדברי המחבר בר\"ס שס\"ח דמחלק בין גזלן ישראל לגזלן עכו\"ם:","\u0003אא\"כ מכרו וכו'. \u0004 ונראה דאז אפילו אם ידע הלוקח או המקבל שגזילה היא אפ\"ה מיקרי שינוי רשות וקנאו וכן הוכחתי לקמן סי' שס\"ט וכן מוכח נמי ממה שמסיק הטור והמחבר כאן אדין שאחר זה אם בא אחר ונטלו מבית הגזלן דל\"ש אם ידע השני שהוא גזל ביד הגזלן ל\"ש לא ידע מכלל דברישא במכרו הגזלן לאחר הוי שינוי רשות אפילו ידע הגזלן דאי הרישא בלא ידע מיירי לא הוצרך לכתו' בסיפא האי ל\"ש הנ\"ל דהא על לא ידע דרישא קאי וזהו דלא כדמוכח מדברי ב\"י שם דס\"ל דבכה\"ג לא מיקרי שינוי רשות ועפ\"ר:","\u0003כי אין דינו של שני אלא עם הבעלים. \u0004 פי' עם הנגזל מ\"ה כשירצה הנגזל מוציאו מהשני דמחשב גזלן שלו כיון שהגזילה עתה בידו:","\u0003עתה שאכלו פטור. \u0004 ג\"ז ילפינן מדכתי' והשיב את הגזלה אשר גזל דוקא כשהוא כעין שגזלו ולא כשנאכל ואם אינו ענין לגזלן עצמו דהא מחויב לשלם עכ\"פ הן או דמיהן תנהו לבנו דגזלן או לאחר שגזלו מהגזלן אם אכלוהו ועיין פרישה:","\u0003לא הוי שינוי רשות \u0004 דברא כרעא דאבוה הוא ולא מחשב כלוקח:","\u0003לאחר יאוש פטורים \u0004 כתבתי טעמו בסעיף שלפני זה ע\"ש ובהטור:","\u0003אבל אם הניח אביהם נכסים \u0004 דאז נכסי אבוהון משועבד להנגזל מיד בשעת הגזילה וסתם המחבר כאן וכת' נכסים משום דבזמן הזה אפילו מטלטלי דיתמי משועבדים לב\"ח ונגזל וכ\"כ הטור בפירושו בסימן שע\"א גם בסי' זה:","\u0003בין גדולים לקטנים כו' \u0004 דלעדי גזילה נזקקין אפי' יתומים קטנים כמ\"ש הטור והמחבר בסי' ק\"י וכ\"כ בה\"ת בשער י\"ד ד\"מ סי' כ\"ח ס\"ט הביאו וכ\"ש אם הגזילה עצמה בעינה דמוציאים אותה מיד הקטנים וכמ\"ש הטור גם כאן ע\"ש:","\u0003ואם אמרו הגדולים כו' נאמנים. \u0004 דנאמנים במגו דאלו רצו היו אומרים החזרנו לך ואפילו למ\"ד הגוזל בעדים צריך להחזירו בעדים וכמ\"ש המחבר בסעיף שאחר זה ה\"מ גזלן עצמו אבל בניו נאמנים. ודוקא אם אמרו הגדולים קאמר שבעינן שיטענו הן בעצמן ☜ ודוקא בברי משא\"כ אם טוענין שמא החזיר לך או לקחו אבינו אינן נאמנין בשמא ואנן לא טענינן להו בדבר שאינו מצוי כ\"כ רי\"ו נכ\"ו ח\"ג ד\"מ ע\"ש:","\u0003אבל אם היו עדים שגזלה כו'. \u0004 טעמא משום דמיגו דאנו החזרנו לך ה\"ל מיגו דהעזה טפי ממה שאמרו ידענו שאבינו עשה עמך חשבון ולא פש לך גביה:","\u0003וי\"א שצריך \u0004 ס\"ל דדוקא \"במלוה לחבירו בעדים א\"צ לפורעו בעדים משום דתחלתו היה כדי לפרוע משא\"כ בגזלן וע\"ל סי' ע\"ה:"],["\u0003 אלא א\"כ מכרו כו' \u0004 עיין בסמ\"ע ס\"ק ה' ועמ\"ש לעיל סי' שנ\"ג ס\"ג לדעת הרמב\"ם ומ\"ש בשם בעל המאור ע\"ש:","\u0003 י\"א דאם מכרו באחריות כו' \u0004 אף שהנ\"י כ\"כ לא נהירא וכבר השגתי עליו לעיל סי' ל\"ז סעיף י\"ז ס\"ק כ\"ט ע\"ש:","\u0003 או נתנו בטעות כו' \u0004 וכ\"ה בחדושי הרשב\"א פ' הניזקין דף פ\"א ע\"ב מיהו איתא שם דאם נתנו לו על דעת חליפי שלו הוי שינוי רשות וכן משמע מדברי הרמב\"ם והמחבר לקמן סי' שס\"ט סעיף ה' ועיין בב\"י שם מיהו מדברי בעל המאור פ' הגוזל בתרא דף מ\"ג ע\"א מוכח להדיא דאפילו בטעות הוי שינוי רשות ע\"ש וגם הרמב\"ם שם משמע דמודי ליה בזה ע\"ש ומיהו בתשובת רשב\"א סימן תתקס\"ח איתא לחד שנוי' דאפילו בחליפות לא הוי שינוי כיון שנתנו לו בע\"כ ע\"ש ומדברי הרמב\"ם והמחבר דלעיל לא משמע כן וכל זה צ\"ע:","\u0003 ואם אמרו הגדולים כו' \u0004 ע' בסמ\"ע ס\"ק י\"ב עד ואנן לא טענינן להו בדבר שאינו מצוי כ\"כ רי\"ו נכ\"ו ח\"ג עכ\"ל והוא כדעת הרא\"ש פ' הגוזל בתרא ע\"ש אבל הרמב\"ן בס' המלחמו' שם כ' דטענינן להו לקוח במגו דהחזרתי אלא מיירי שראוהו עתה לאחר מיתה ביד היתומים הילכך בשמא לא טענינן להו לקוח דאב גופיה כה\"ג לא הוי מהימן אבל כשטוענין ברי נאמנים כיון שלא ראוהו ביד היתומים קודם שירדו לדין דהיו נאמנים לטעון אנו החזרנוהו נאמנים גם עכשיו במגו עכ\"ד בקצר' וכ\"כ הנ\"י בשמו ובשם הרא\"ה וכ\"פ הריטב\"א בפ' הכותב ומשמע שם בהרא\"ש והרמב\"ן דלטעמייהו אזלי במ\"ש בפ' המוכר את הבית דס\"ל שם להרא\"ש דלא טענינן ליתמי נאנסו כיון דהיא טענה דלא שכיח ולהרמב\"ן ס\"ל התם דטענינן להו נאנסו דגם מידי דלא שכיח טעני' להו (מיהו כשטוענים ברי נראה דהרא\"ש מודה להרמב\"ן דנאמנים כל זמן שלא ראו עתה בידו קודם שירדו לדין או שראו לאחר מיתה) ע\"ש משמע כן מדבריהם להדיא וא\"כ למאי דקי\"ל גבי נאנסו דהוי ספיקא דדינא כדלעיל סי' ק\"ח ס\"ד ה\"ה הכא א\"כ הד\"מ והסמ\"ע שכתבו כאן דברי ר' ירוחם לא כוונו יפה דודאי איכא דפליגי עליה והילכך מספיקא לא מפקינן מנייהו ודו\"ק (וכ\"ש לפמ\"ש לעיל סימן ק\"ח דנלפע\"ד עיקר כהרמב\"ן וסייעתו ע\"ש):","\u0003 שעשה אבינו חשבון כו' \u0004 ואפילו אמרו אבינו אמר לנו שעשה עמך חשבון נאמנים כדלעיל סי' רצ\"ז בהג\"ה:","\u0003 נאמנים כו' \u0004 מיהו צריכים לישבע היסת לפי הטעם שכתבתי בסי' רצ\"ז כיון שטוענים ברי ודלא כסמ\"ע שם ס\"ק י\"ב ע\"ש:","\u0003 אבל אם היו עדים שגזלו כו' \u0004 טעמו משום דמגו דאנו החזרנו לך ה\"ל מגו דהעז' טפי ממה שאמרו ידענו שעשה אבינו עמך חשבון ולא פש לך גביה עכ\"ל סמ\"ע והוא מדברי עיר שושן ולפע\"ד לא כוונו יפה דהא ודאי אמרי' מגו בכה\"ג כמש\"ל סימן פ\"א סכ\"ג ובס\"ס פ\"ב בדיני מגו אות ו' ובסימן צ\"ג ס\"ב ע\"ש וגרם להם זה מפני שחשבו שלדעת הי\"א אפילו יכולים לטעון החזרנו לך אין נאמנים דאל\"כ במאי פליגי וזה אינו דהא הי\"א הוא הטור ודבריו לקוחים מהרא\"ש ר\"פ הגוזל ומאכיל (ובב\"י לא הביא דברי הרא\"ש) ובדברי הרא\"ש משמע להדיא שיש להם כל כח אביהן וז\"ל ומיירי בלא ידעינן שבאתה הגזילה ליד אביהן אלא על פיהם דאלו הוי ידעי' בעדים שבאתה הגזילה ליד אביהן לא היו נאמנים לומר שאביהם שילם הגזילה כיון שידוע שבתורת גזילה באתה לידו ועודה בידו דאב גופא לא הוי מהימן למימר החזרתי' לך ולקחתי' ממך וכן בפקדון אם יש עדים שהופקד לידו וראו עדיין בידו לא מהימן לומר לקחתי ממך אלא באין עדים אלא על פיהם מיירי עכ\"ל ומ\"ש כיון שידוע שבתורת גזילה באה לידו ועודה בידו כו' ר\"ל וידוע שעודה בידו וכדכתב אח\"כ וראו עדיין בידו וכ\"כ בס' מע\"מ וז\"ל ועודה בידו כלומר ביד יורשיו דמיירי דעדים ראוהו דלא יכול למימר החזרתי וכה\"ג נמי בדידיה וכדמסיים דאב גופיה כו' עכ\"ל וכן מוכח להדיא מדברי מהרש\"ל שם סי' ו' שדעת הרא\"ש כן שכתב דלא הוי צריך הרא\"ש לאוקמי בהכי אלא לאוקמי באין גזל הקיימת ואפ\"ה נאמנים שפיר במגו דהחזירה לך אבא או אנו החזרנו לך אף שיש עדים שבאתה הגזלה ליד אביהם עכ\"ל וגם דעת התוס' דנאמנים במגו דהחזרנו ומביאם ב\"י וכ\"כ הבעל המאור והרמב\"ן בס' המלחמות ר\"פ הגוזל בתרא להדיא (וכ\"פ מהרש\"ל) ולמה נימא דהרא\"ש פליג עלייהו בזה ומ\"ש המחבר וי\"א דה\"מ כו' היינו משום דבש\"ס איתא סתם נאמנים ואפשר לו' דאפי' ידוע שבאתה הגזלה לידי אביהן וידוע דעודה בידן אע\"ג דלית להו מגו משום דטענ' עשה אבינו חשבון טענה מעליותא הוא ובאו הי\"א לפרש דלא מהימני אלא במגו ודו\"ק ע' בתשובת מהרי\"ט סי' ט\"ו ע\"ב וקי\"ב דף ק\"מ קמ\"א וברשד\"ם סי' קצ\"ח ור':","\u0003 וי\"א שצריך. \u0004 כ\"כ הרב המגיד פ\"ד מהל' גזיל' והריב\"ש סי' שצ\"ב בשם הרמב\"ם ולפע\"ד לא מוכח מהרמב\"ם מידי ע\"ש שוב מצאתי בכ\"מ ג\"כ דלא מוכח מהרמב\"ם מידי ולענין דינא פשיטא דקי\"ל דא\"צ שכן דעת הר\"ן פ' הנשבעין והנ\"י פח\"ה וכ\"כ הריב\"ש שם שרבו כמו רבו החולקים על הרמב\"ם ושכן דעת הרמ\"ה וכ\"כ הריטב\"א ר\"פ האשה שנתארמלה שאע\"פ שיש לדחות ראיית הרמ\"ה מ\"מ דינו אמת וכן דעת הראב\"ד והרמב\"ן וכ\"כ בס' התרומות שער מ\"ט וכ\"כ ר' ירוחם נ\"ג ח\"ב בשם הפוסקים הנ\"ל ובשם רשב\"א וכ\"כ הרב המגיד שכן דעת חכמי הדורו' שוב מצאתי בבדק הבית סי' צ' כ' ג\"כ כיון דרבוותא סוברים דא\"צ ואין הוכח' מהרמב\"ם הכי נקטינן וכן עיקר לדינא וכ\"כ בפשיטות בסמ\"ע לעיל סי' ק\"ז ס\"ק ט\"ו וכ\"כ בתשובת דברי ריבות סי' רע\"ו ודלא כב\"ח שם שפסק דהוי ספיקא דדינא ע\"ש:"]],["הַגְּזֵלָה שֶׁלֹּא נִשְׁתַּנֵּית, אֶלָּא הֲרֵי הִיא כְּמוֹ שֶׁהָיְתָה, \u0010y0\u0011 אַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה וְאַף עַל פִּי שֶׁמֵּת הַגַּזְלָן וַהֲרֵי הִיא בְּיַד בָּנָיו, הֲרֵי זוֹ חוֹזֶרֶת לִבְעָלֶיהָ בְּעַצְמָהּ. וְאִם נִשְׁתַּנֵּית בְּיַד הַגַּזְלָן, אַף עַל פִּי שֶׁעֲדַיִן לֹא נִתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה, קְנָאָהּ \u0010y1\u0011 בְּשִׁנּוּי, וּמְשַׁלֵּם דָּמֶיהָ כִּשְׁעַת הַגְּזֵלָה.\nנִתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה וְלֹא נִשְׁתַּנֵּית, קָנָה הַגַּזְלָן כָּל הַשֶּׁבַח \u0010y2\u0011 שֶׁהִשְׁבִּיחַ אַחַר יֵאוּשׁ, \u0010y3\u0011 וְאֵינוֹ מְשַׁלֵּם אֶלָּא כִּשְׁעַת הַגְּזֵלָה; וְדָבָר זֶה מִדִּבְרֵיהֶם, מִפְּנֵי תַּקָּנַת הַשָּׁבִים. וּכְשֶׁמַּחֲזִיר לוֹ \u0010y4\u0011 הַגְּזֵלָה, שָׁמִין לוֹ הַשֶּׁבַח וְנוֹטֵל מִן הַנִּגְזָל.\nמְכָרָהּ הַגַּזְלָן אוֹ נְתָנָהּ בְּמַתָּנָה, אַף עַל פִּי שֶׁלֹּא נִשְׁתַּנֵּית הַגְּזֵילָה, אֵינָהּ חוֹזֶרֶת בְּעַצְמָהּ מִיַּד הַלּוֹקֵחַ. הוֹאִיל וְנִתְיָאֲשׁוּ הַבְּעָלִים, בֵּין לִפְנֵי מְכִירָה וּנְתִינָה בֵּין לְאַחַר מְכִירָה וּנְתִינָה, קְנָאָהּ הַלּוֹקֵחַ בְּיֵאוּשׁ וְשִׁנּוּי רְשׁוּת. \u0010y5\u0011 \u0010c0\u0011 \u0005וְיֵשׁ חוֹלְקִין, וְעַיֵּן לְעֵיל סִימָן שנ\"ג. (טוּר סִימָן שנ\"ג בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010c1\u0011\nהַגּוֹזֵל וְהִשְׁבִּיחַ וּמָכַר אוֹ הוֹרִישׁ לִפְנֵי יֵאוּשׁ, מַה שֶּׁהִשְׁבִּיחַ הוֹרִישׁ, \u0010y6\u0011 וּמַה שֶּׁהִשְׁבִּיחַ מָכַר, וְקָנָה לוֹקֵחַ אוֹ יוֹרֵשׁ אֶת הַשֶּׁבַח, וְנוֹטֵל דְּמֵי הַשֶּׁבַח מֵהַנִּגְזָל, וּמַחֲזִיר הַגְּזֵלָה, וְחוֹזֵר הַנִּגְזָל וְנוֹטֵל \u0010y7\u0011 דְּמֵי הַשֶּׁבַח מֵהַגַּזְלָן, \u0010y8\u0011 שֶׁהֲרֵי לֹא נִתְיָאֵשׁ. \u0010y9\u0011 וְכֵן אִם הִשְׁבִּיחַ הַלּוֹקֵחַ אוֹ הַיּוֹרֵשׁ, נוֹטֵל הַשֶּׁבַח מֵהַנִּגְזָל.\nמָכַר הַגַּזְלָן \u0010y10\u0011 לְגוֹי, וְהִשְׁבִּיחַ הַגּוֹי, הַשֶּׁבַח חוֹזֶרֶת לַבְּעָלִים. \u0010y11\u0011\nמָכַר הַגּוֹי לְיִשְׂרָאֵל אַחַר שֶׁהִשְׁבִּיחַ, הוֹאִיל וְהַגַּזְלָן יִשְׂרָאֵל וְזֶה שֶׁבְּיָדוֹ יִשְׂרָאֵל, קָנָה הַשֶּׁבַח. \u0010y12\u0011 \u0010c2\u0011 וְאִם תָּפַס הַנִּגְזָל, אֵין מוֹצִיאִין מִיָּדוֹ.\nכְּבָר נִתְבָּאֵר שֶׁהַגְּזֵלָה שֶׁהִשְׁבִּיחָה אַחַר יֵאוּשׁ אוֹ אַחֵר שֶׁנִּשְׁתַּנֵּית, הַשֶּׁבַח לַגַּזְלָן אַף עַל פִּי שֶׁהִשְׁבִּיחָה מֵאֵלֶיהָ. כֵּיצַד, גָּזַל פָּרָה וְנִתְעַבְּרָה אֶצְלוֹ, בֵּין שֶׁיָּלְדָה קֹדֶם שֶׁתְּבָעוֹ בַּדִּין בֵּין שֶׁעֲדַיִן לֹא יָלְדָה; גָּזַל רָחֵל וְנִטְעֲנָה אֶצְלוֹ, בֵּין שֶׁגְּזָזָהּ קֹדֶם שֶׁתְּבָעוֹ בַּדִּין, בֵּין שֶׁעֲדַיִן לֹא גְּזָזָהּ; הוֹאִיל וְנִתְיָאֲשׁוּ הַבְּעָלִים, \u0010y13\u0011 מְשַׁלֵּם כִּשְׁעַת הַגְּזֵלָה. וְאִם יָלְדָה וּגְזָזָהּ, הַגִּזּוֹת וְהַוְּלָדוֹת שֶׁל גַּזְלָן. \u0010y14\u0011 וְאִם עֲדַיִן לֹא יָלְדָה וְלֹא גְּזָזָהּ, שָׁמִין לוֹ, וְנוֹטֵל הַשֶּׁבַח מֵהַנִּגְזָל וּמַחֲזִיר הַבְּהֵמָה עַצְמָהּ.\nגָּזַל פָּרָה מְעֻבֶּרֶת, וְנִתְיָאֲשׁוּ הַבְּעָלִים, וְאַחַר כָּךְ יָלְדָה, רָחֵל טְעוּנָה, וְנִתְיָאֲשׁוּ הַבְּעָלִים, וְאַחַר כָּךְ גְּזָזָהּ, מְשַׁלֵּם \u0010y15\u0011 דְּמֵי פָּרָה הָעוֹמֶדֶת לֵילֵד וּדְמֵי רָחֵל הָעוֹמֶדֶת לִגָּזֵז. וְאִם לִפְנֵי יֵאוּשׁ וְקֹדֶם שֶׁנִּשְׁתַּנֵּית יָלְדָה אוֹ גְּזָזָהּ, הֲרֵי הַגִּזּוֹת וְהַוְּלָדוֹת שֶׁל בְּעָלִים; וְאַף עַל פִּי שֶׁנִּתְעַבְּרָה אוֹ נִטְעֲנָה בְּיַד הַגַּזְלָן, הוֹאִיל וְלֹא נִתְיָאֲשׁוּ הַבְּעָלִים וְלֹא נִשְׁתַּנֵּית הַגְּזֵלָה, הִיא בִּרְשׁוּת בְּעָלֶיהָ אַף עַל פִּי שֶׁהַגַּזְלָן חַיָּב בָּאֳנָסִים. \u0005הַגָּה: כָּל אֵלֶּה דִבְרֵי הָרַמְבַּ\"ם, \u0010y16\u0011 אֲבָל יֵשׁ חוֹלְקִין, וּכְמוֹ שֶׁנִּתְבָּאֵר רֵישׁ סִימָן שנ\"ד ושנ\"ו. וַאֲפִלּוּ שִׁנּוּי הַחוֹזֵר לִבְרִיָּתוֹ, כְּגוֹן עָפָר וַעֲשָׂאוֹ לְבֵנִים, אַף עַל גַּב דְּלָא קָנָה כְּדִלְעֵיל סִימָן ש\"ס, שֶׁבַח מִיהָא קָנָה, וְצָרִיךְ לְהַחֲזִיר לוֹ שִׁבְחוֹ (טוּר ס\"א)\u0006.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּשֶׁבַח הַבָּא מֵאֵלָיו, כְּגוֹן גִּזּוֹת וּוְלָדוֹת. אֲבָל אִם הָיְתָה כְּחוּשָׁה \u0010c3\u0011 וְהוֹצִיא עָלֶיהָ וּפִטְּמָהּ, אֲפִלּוּ לִפְנֵי יֵאוּשׁ, נוֹטֵל מֵהַנִּגְזָל שְׁבַח הַפִּטּוּם, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִשֶּׁבַח שֶׁיֵּשׁ בּוֹ הוֹצָאָה.\nגְּזֵלָה שֶׁלֹּא נִשְׁתַּנֵּית וְהוּקְרָה, \u0010c4\u0011 אַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה, הֲרֵי זוֹ חוֹזֶרֶת לַבְּעָלִים וְאֵין לַגַּזְלָן בָּהּ כְּלוּם, שֶׁלֹּא תִקְּנוּ לַגַּזְלָן אֶת הַשֶּׁבַח אַחַר יֵאוּשׁ, אֶלָּא כְּגוֹן שְׁבַח גִּזּוֹת וּוְלָדוֹת, אֲבָל שְׁבַח הַיֹּקֶר, אִם הָיְתָה הַגְּזֵלָה חוֹזֶרֶת בְּעֵינֶיהָ אֵינוֹ זוֹכֶה בָּהּ. \u0010y17\u0011 הַגּוֹזֵל חָבִית שֶׁל יַיִן מֵחֲבֵרוֹ וַהֲרֵי הִיא שְׁוֵה דִינָר בִּשְׁעַת הַגְּזֵלָה, וְהוּקְרָה אֶצְלוֹ וְעָמְדָה בְּאַרְבָּעָה, שִׁבֵּר הֶחָבִית אוֹ שָׁתָה אוֹתָהּ, אוֹ מְכָרָהּ אוֹ נְתָנָהּ בְּמַתָּנָה אַחַר שֶׁהוּקְרָה, מְשַׁלֵּם אַרְבָּעָה כִּשְׁעַת הוֹצָאָה מִן הָעוֹלָם, \u0010y18\u0011 שֶׁאִלּוּ הִנִּיחָה הָיְתָה חוֹזֶרֶת \u0010y19\u0011 בְּעַצְמָהּ. נִשְׁבְּרָה מֵעַצְמָהּ אוֹ אָבְדָה, מְשַׁלֵּם דִּינָר כִּשְׁעַת הַגְּזֵלָה.\nהָיְתָה שָׁוָה בִּשְׁעַת הַגְּזֵלָה אַרְבָּעָה, וּבִשְׁעַת הוֹצָאָה מִן הָעוֹלָם דִּינָר, מְשַׁלֵּם אַרְבָּעָה כִּשְׁעַת \u0010y20\u0011 הַגְּזֵלָה, בֵּין שֶׁשִּׁבְּרָהּ אוֹ שְׁתָאָהּ בֵּין שֶׁנִּשְׁבְּרָה אוֹ אָבְדָה מֵאֵלֶיהָ, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nהַגּוֹזֵל אֶשְׁכּוֹל שֶׁל תְּמָרִים, וּבוֹ חֲמִשִּׁים תְּמָרִים, וְאִם יִמָּכְרוּ כֻּלָּם בְּיַחַד אֵינוֹ שָׁוֶה אֶלָּא מ\"ט פְּרוּטוֹת וְאִם יִמָּכְרוּ כָּל אַחַת בִּפְנֵי עַצְמָהּ יִשְׁווּ \u0010y21\u0011 חֲמִשִּׁים, אֵינוֹ מְשַׁלֵּם אֶלָּא מ\"ט:\nהַגּוֹזֵל כְּלִי וּשְׁבָרוֹ, \u0010y22\u0011 \u0010c5\u0011 אֵין אוֹמְרִים יִתֵּן הַשְּׁבָרִים וְיַשְׁלִים עֲלֵיהֶם, וְדִינוֹ כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן שנ\"ד \u0005(ס\"ה, ע\"ש)\u0006.",["\u0003אע\"פ שנתיאשו הבעלים כו'. \u0004 דביאוש לבד לא קנה אם לא בהדי שינוי רשות ורשות יורש לאו שינוי רשות מיקרי כמ\"ש לעיל:","\u0003ומשלם דמיה \u0004 פי' הגזלן להנגזל דבגזלן לא שייך ביה תקנת השוק מ\"ה צריך ליתן להנגזל כל דמי הגזילה:","\u0003שהשביח לאחר יאוש כן \u0004 הוא דעת הרמב\"ם דבעינן יאוש אבל הרא\"ש והטור וסייעתיהו ס\"ל דאפי' לא נתייאש ג\"כ דינא הכי וכ\"כ מור\"ם בהגהותיו סוף סעיף ח' דיש חולקין וקאי גם אזה שכ' המחבר כאן ועד\"ר.","\u0003ואינו משלם אלא כשעת הגזילה. \u0004 פי' אם הוא בענין שאין צריך לחזור הגזילה בעינה אזי משלם הוא להנגזל דמי הגזיל' אבל על הרוב מחזיר בעינה וע\"ז מסיק וכ' ז\"ל וכשמחזיר כו' שמין לו השבח ונוטל מהנגזל כיון דבגזלן עצמו מיירי דמוציאין מידו דא\"צ ליתן הנגזל לגזלן אלא שבחו ובסעיף ד' דמיירי שם בדמכרו לאחר שם ל\"ד קאמר דנוטל דמי שבח מהנגזל דהא גם קרנו נוטל מהנגזל אלא לרבותא קאמר דאפי' דמי שבחו נוטל מהנגזל וכ\"ש דמי קרנו ועפ\"ר:","\u0003[שמין לו בדפוס יחד עם ס\"ק ד']. \u0004 פי' אם הוא בענין שאין צריך להחזיר הגזילה בעינה אזי משלם הוא להנגזל דמי הגזילה אבל על הרוב מחזיר בעינה וע\"ז מסיק וכ' ז\"ל וכשמחזיר כו' שמין לו השבח ונוטל מהנגזל כיון דבגזלן עצמו מיירי דמוציאין מידו דא\"צ ליתן הנגזל לגזלן אלא שבחו ובסעיף ד' דמיירי שם בדמכרו לאחר שם ל\"ד קאמר דנוטל דמי שבח מהנגזל דהא גם קרנו נוטל מהנגזל אלא לרבותא קאמר דאפי' דמי שבחו נוטל מהנגזל וכ\"ש דמי קרנו ועפ\"ר:","\u0003ויש חולקין \u0004 פי' דס\"ל דבעינן שיהא היאוש דוקא קודם שינוי רשות וכמ\"ש בס\"ס שנ\"ג ושנ\"ו ושס\"ה:","\u0003ומה שהשביח מכר \u0004 פי' בזה עדיף כח לוקח ויורש מהגזלן עצמו דהן קנו השבח שנשבח אף שלא נתייאש הנגזל. ובעודו ביד הגזלן לא יקנה הגזלן השבח לסברת הרמב\"ם וה\"ט דס\"ל דתקנה התקינו רבנן בזה ללוקח וליורש משא\"כ לרש\"י והרא\"ש דס\"ל דהא דלוקח ויורש זכו בשבח היינו מכח שזכה בו ג\"כ הגזלן בכה\"ג ואפילו נשבח קודם היאוש ומשום תקנת השבים ועפ\"ר:","\u0003דמי השבח \u0004 כבר כתבתי בסעיף שלפני זה דר\"ל אפי' דמי השבח:","\u0003ומ\"ש שהרי לא נתייאש \u0004 קאי אמ\"ש ומחזיר הגזיל' וה\"ט דלא נתייאש דאלו נתייאש הי' מחזיק בהגזילה עצמה:","\u0003וכן אם השביח הלוקח כו' \u0004 בע\"ש כתב דבז' דהשביחו היורש או הלוקח אין הנגזל חוזר על הגזלן שהרי לא הושבחה בידו עכ\"ל ולא ידעתי טעם נכון לחלק ביניהן דהרי כאן בשבח שהושבח מאיליה מיירי וכמ\"ש בסמוך ס\"ט ויכול הנגזל לומר לולי שגזלתני גם בביתי היה נשבח ונהי דתקינו רבנן לשלם להלוקח והיורש השבח. הגזלן עכ\"פ צריך להחזיר כאלו הי' נשבח ביד הגזלן לסברת הרמב\"ם וצ\"ל דס\"ל לבעל ע\"ש דדוקא כשהושבח' הגזילה בידו דהגזלן ומכרה דאז כבר קיבל הגזלן מהלוקח גם בעד השבח בזה קאמר דחוזר הנגזל ומוציא מגזלן אותן דמי שבח שקיבל משא\"כ כשלא נשבח ביד הגזלן והשתא א\"ש דכתב המחבר לשון וכן אם השביח הלוקח כו' דקמ\"ל דאע\"ג דבזה אין הנגזל חוזר על הגזלן דמי השבח אפ\"ה הנגזל צריך ליתן להלוקח גם דמי השבח ויפסיד הנגזל דמי השבח מכיסו מיהו כל זה אינו מוכרח והא דכתב \"וכן כו' דקמל\"ן בזה דאע\"ג דלית בזה משום תק\"ה דהא לא נשבח ביד הגזלן אפ\"ה צריך הנגזל ליתן דמי השבח להלוקח:","\u0003והשביח העכו\"ם דתקנתא לעכו\"ם שיקנה השבח לא עבדי:\u0004","\u0003מכרה העכו\"ם לישראל כו' \u0004 זהו איבעי' בגמרא מי תמרי' הואיל דהישראל שני אתי מכח העכו\"ם שמכר לו לא עדיף מיניה א\"ד הואיל ומעיקרא ישראל כו' ולא איפשטא האבעי' ומ\"ה המע\"ה:","\u0003ואם תפס הנגזל כו' וכ\"כ הרא\"ש והטור ובדרישה כתבתי דאף דבספיק' ס\"ל דלא מהני תפיסה מ\"מ בספיקא דתלמוד' מודים דמהני בהו תפיסה ועמ\"ש שם עוד ודו\"ק:\u0004","\u0003משלם כשעת הגזילה \u0004 ר\"ל זהו עכ\"פ שאין הנגזל זוכה בהשבח כ\"א כמות שהיתה בשע' גזילה ומפרש ואזיל שלפעמים גם גוף הגזילה נשאר ביד הגזלן ומשלם לנגזל דמיה היינו כשכבר ילדה וגזזה דכיון דזכה בגיזה וולדה זכה ג\"כ בעצמה ולפעמים נוטל הנגזל הכל ונותנין להגזלן דמי השבח והיינו כשעדיין לא גזזה וילדה ועמ\"ש בסי' שנ\"ד מזה קצת בהוכחה ובביאור יותר טוב בע\"א:","\u0003ואם עדיין לא ילדה כו' \u0004 דס\"ל להרמב\"ם דעיבור וטעונה גיזה לא מחשב שינוי ואפי' לידה עצמה ס\"ל דלא ה\"ל דין שינוי גמור אלא כשנוי החוזר וכמ\"ש בסעיף שאחר זה:","\u0003דמי פרה העומד' לילד \u0004 ר\"ל אף אם הגיע זמנה לילד בשעת גזילה אפ\"ה אינו משלם כאלו ילדה בשעת גזילה כי ידוע שלא היתה הבהמה שוה כ\"כ קודם לידה שיש בה חשש סכנ' לפרה עצמה וג\"כ שמא יהיה הולד נפל כמו שהיתה שוה אחר לידה ואם גזלה בתחלת או באמצע עבורה אינו משלם כ\"כ כמו שהבהמה שוה בעת שהיא עומדת לילד דהיינו גמר עיבור אלא הכל לפי שומת שוויי':","\u0003אבל יש חולקין \u0004 ר\"ל חולקין עם הרמב\"ם במ\"ש דלא קנה הגזלן השבח שנשבח קודם שנתייאשו הבעלים וס\"ל להחולקין דקנה ול\"מ שינוי גמור אלא אפי' בשינוי החוזר קנו (הבעלים) השבח וכדמסיק ונראה דה\"ה אם אין בו שינוי כלל כגון גזלה כשהיא מעוברת או טעונה בגיזה ונשתה' ביד הגזלן ונתרב' עליו הגיזה או הולד אע\"פ שהוציאו מידו בעוד' טעונה או מעוברת משלם לו העודף כשיעור שנשבח בידו ועמ\"ש בסי' שס\"ג ס\"ה:","\u0003הגוזל חבית יין כו' \u0004 הטור כתבו בל' לפיכך דמכח טעם הנ\"ל דאין הגזלן זוכה בהשבח דיוקר' מסיק האי דינא:","\u0003שאלו הניחה כו'. \u0004 פי' וכיון שהית' חוזרת בעינ' נמצא דהוקרה ברשות דהנגזל ואע\"ג דכל הגזלנין אין משלמין אלא כשעת גזילה הא עיקר גזילה נעשית בשע' ששתאה או מכרה או שבר החבית דהא עד הנה ברשות הנגזל הוה קאי להדרה בעינה מן הדין ועתה קלקלה וגרם שלא הוחזרה לידו בעין משא\"כ כשנשברה מעצמה וכדמסיק וק\"ל:","\u0003נשבר' מעצמה או אבדה \u0004 האי אבדה ג\"כ אמעצמה קאי אבל סתם אבידה מקרי פשיע' וכמ\"ש לעיל בסי' שנ\"ד ס\"ג ע\"ש:","\u0003בין ששברה או שתאה כו' \u0004 שלא יהא חוטא נשכר דאלו נשברה מעצמה היה צריך לשלם ד' כשעת הגזילה ועכשיו שנשברה בידים לא יתחייב אלא דינר וכבר נתבאר כל זה לעיל בסי' שנ\"ד:","\u0003אינו משלם אלא מ\"ט. \u0004 זהו כעין מ\"ש הטור והמחבר לקמן בסי' שצ\"ד דבהמה שאכלה פירות מחוברים רואים כמה הפסיד' ושמין מי שבא לקנות ס' חלקים כדי אותו חלק מה שאכלה כמה היה נותן בה קודם אכילתן וכמה היה פוחת בשביל אכילתן וכן נותן לניזק וזה קולא הוא למזיק ולגזלן ולמדוהו מדכתיב וביער בשדה אחר דמה שנבער מהשדה ישומו אותו בהדי שדה אחר ע\"ש ועפ\"ר:","\u0003אין אומרים יתן השברים כו' \u0004 כבר נתבאר זה בס\"ס שנ\"ד והר\"ן פ\"ק דב\"ק (דף ו') כתב בשם הרמ\"ה דהיינו דוק' אם יש לו מעות דאם אין לגנב או לגזלן מעות לשלם אפי' יש לו מקרקעי או מטלטלים א\"צ לשלם לו מהן אלא שיימינן לו אלו השברין והמותר ישלים לו מהמטלטלים ועפ\"ר שכתבתי שבזה מיושב מ\"ש הרמב\"ם והטור שם בסי' שנ\"ד בגניבה וגם כאן בגזילה דאם הבעלים רוצים בהשברים שומעין להן וצריך הגזלן ליתן לו. והקשה המ\"מ אמאי צריך ליתן לו השברים הא כבר קנאום הגזלן או הגנב בשינוי וכתבתי די\"ל דמיירי כשאין להגזלן מעות ובא לשלם להנגזל במטלטלין בזה קאמר דיכול הנגזל לומר הואיל ובאת לשלם לי במטלטלין שלא כדיני שדיני במעות דוקא לפחות תן לי שברי כלי שלי שבהן ניחא לי טפי מבשאר מטלטלים וק\"ל ועיין בתוס' דפ' השואל (סוף דף צ\"ו) בד\"ה זיל שלים ליה כו':"],["\u0003 וי\"ח \u0004 דבעינן דוקא היאוש קודם שינוי רשות וכן עיקר וכמש\"ל סי' שנ\"ג ס\"ג:","\u0003 הגוזל והשביח כו' \u0004 ע' בס' החנוך מצו' קכ\"ה:","\u0003 ואם תפס הנגזל כו' \u0004 וכ\"כ הרא\"ש והטור עכ\"ל סמ\"ע טעות הוא דלא כ' הרא\"ש כן גם מ\"ש דבספיקא דתלמודא מודי' ליתא ואדרבה בספיקא דתלמודא ס\"ל להרא\"ש וטור דאפי' תפס מפקינן מיניה וכמש\"ל סי' שמ\"ו אמ\"ש בס\"ק ט\"ו ולקמן סי' שפ\"ח והאמת היא דהטור העתיק כאן ל' הרמב\"ם וסמך עצמו אמ\"ש לקמן סי' שפ\"ח וש\"צ וכ\"כ מהרש\"ל פ' הגוזל קמא סי' ו' וז\"ל כ' הטור ואי תפס נגזל לא מפקינן מיניה וזו היא סברת רמב\"ם אבל ר\"י והרא\"ש לא ס\"ל הכי אלא אי תפס מפקינינן מיניה כאשר כתבתי בפ' כיצד סי' ה' והטור גופא כ' בסי' שפ\"ח גבי מסור שכן דעת א\"א הרא\"ש ז\"ל והכא לפום ריהטא כ' דעת הרמב\"ם עכ\"ל וכן מוכרח לומר לעיל בטור סי' ש\"ב ס\"ח שהעתיק דברי הרמב\"ם וסמך עצמו אלקמן סי' שפ\"ח וש\"ץ ע\"ש:","\u0003 והוציא עליה ופטמה כו'. \u0004 אבל נתפטמה מאליה דינה כהוקרה וכדלעיל סי' שנ\"ד ס\"ד בהג\"ה וא\"כ אפי' אחר יאוש הוא של נגזל:","\u0003 אע\"פ שנתייאשו כו' \u0004 ומהרש\"ל פ' מרובה סי' ז' (וכ\"פ פ' הגוזל קמא סי' ד' וסי' ו') פסק דהיכא דנתייקר' אחר שנתייאש הוי של גזלן לפי שהי' גורס בטור אבל נתייאשו הבעלים קוד' שנתייקר' או נתפטמה מאליה הוי של גזלן וכ' שטעם הטור דס\"ל דיאוש קונה מדרבנן משום תקנת השבים ושייך תקנת השבים בכה\"ג ולפע\"ד גירסא זו אינה נכונה אלא הגירסא היא בטור אפי' נתייאשו הבעלים קודם שנתייקרה או נתפטמ' מאליה הוי של נגזל וכ\"כ הב\"ח דמ\"ש בטור אבל נתייאשו הבעלים קודם שנתייקרה או נתפטמה מאליה הוי של גזלן ט\"ס הוא וצ\"ל של נגזל עכ\"ל וע\"ש בטור מוכח כן מדבריו דאל\"כ ברישא ה\"ל לערבינהו וליתנינהו והכי ה\"ל למיכתב אבל אם נתייקר' או נתפטמה מאליה כל זמן שלא נשתנית או שלא נתייאש השבח של נגזל כו' ומדכתב כ\"ז שלא נשתנית השבח של נגזל אפי' נתייאשו הבעלים כו' משמע דלעולם היא של נגזל אא\"כ נשתנית וממ\"ש הטור לעיל סי' שנ\"ג דיאוש קונה מדרבנן אין ראיה דהא מהרש\"ל גופא שם ובפ' הגוזל בתרא סי' כ\"ז כ' דהרמב\"ם סבר דיאוש לחידיה קנה מדרבנן ואפ\"ה כ' הרמב\"ם דנתייקר' אחר שנתייאש הוי של נגזל ש\"מ דס\"ל דנתייקרה שאני וכן משמע להדיא ממ\"ש הטור לעיל סי' שנ\"ד ס\"ד גבי גנב דאם נתייקרה או נתפטמה משלם כדהשתא ולא חילק בין לפני יאוש או לאחר יאוש ובפרט דסתם גנבה יאוש בעלים הוא וכמ\"ש סי' שנ\"ג ועוד דאמאי נימא דהטור פליג על הרמב\"ם בנתייקר' אחר יאוש וגם הסמ\"ג עשין ע\"ג ד' ק\"ן ע\"ב כ' כהרמב\"ם וכ\"כ ר\"י נל\"א ריש ח\"ד וכן עיקר:","\u0003 אין אומרים יתן השברים כו' \u0004 ע' בסמ\"ע ס\"ק כ\"ג במ\"ש ליישב קושיות המ\"מ ואין לשון הרמב\"ם והמחבר מורין כן ודו\"ק:"]],["גָּזַל בְּהֵמָה וְהִזְקִינָה אוֹ כָּחֲשָׁה כַּחַשׁ שֶׁאֵינוֹ יָכוֹל לַחֲזֹר, כְּגוֹן חֳלָאִים שֶׁאֵין לָהֶם רְפוּאוֹת \u0010c0\u0011 תְּעָלָה, אוֹ שֶׁגָּזַל מַטְבֵּעַ וְנִסְדַּק אוֹ פְּסָלוֹ הַמֶּלֶךְ, \u0005וְיֵשׁ אוֹמְרִים דְּמַטְבֵּעַ אֲפִלּוּ פְסָלָהּ הַמֶּלֶךְ אוֹמֵר לוֹ: הֲרֵי שֶׁלְּךָ לְפָנֶיךָ (טוּר ס\"א בְּשֵׁם הָרֹא\"שׁ)\u0006, \u0010y0\u0011 אוֹ שֶׁגָּזַל פֵּרוֹת וְהִרְקִיבוּ כֻלָּם, אוֹ שֶׁגָּזַל יַיִן וְהֶחֱמִיץ, \u0010y1\u0011 הֲרֵי זֶה כְּמוֹ שֶׁגָּזַל כְּלִי וּשְׁבָרוֹ, וּמְשַׁלֵּם כִּשְׁעַת הַגְּזֵלָה. אֲבָל אִם גָּזַל בְּהֵמוֹת וְכִחֲשׁוּ כַּחַשׁ שֶׁאֶפְשָׁר \u0010y2\u0011 \u0010c1\u0011 לַחֲזֹר, אוֹ שֶׁגָּזַל עֲבָדִים \u0010c2\u0011 וְהִזְקִינוּ, אוֹ שֶׁגָּזַל \u0010c3\u0011 מַטְבֵּעַ וְנִפְסַל \u0010c4\u0011 בִּמְדִינָה זוֹ וַהֲרֵי הוּא יוֹצֵא בִּמְדִינָה אַחֶרֶת, אוֹ שֶׁגָּזַל \u0010c5\u0011 פֵּרוֹת וְהִרְקִיבוּ מִקְצָתָם, \u0010y3\u0011 אוֹ תְּרוּמָה וְנִיטְמֵאת, אוֹ שֶׁגָּזַל חָמֵץ וְעָבַר עָלָיו הַפֶּסַח, אוֹ בְּהֵמָה \u0010y4\u0011 וְנֶעֶבְדָה בָּהּ עֲבֵרָה, אוֹ נִפְסְלָה מִלִּקָּרֵב, אוֹ שֶׁהָיְתָה יוֹצֵאת לִסָקֵל, אוֹמֵר לוֹ: \u0010c6\u0011 הֲרֵי שֶׁלְּךָ לְפָנֶיךָ, וּמַחֲזִיר אוֹתָהּ בְּעַצְמָהּ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהֶחֱזִיר הַגְּזֵלָה. אֲבָל אִם נִשְׂרְפָה הַגְּזֵלָה אוֹ אָבְדָה \u0010y5\u0011 אַחַר שֶׁנֶּאֶסְרָה בַּהֲנָאָה, חַיָּב לְהַחֲזִיר לוֹ דָּמֶיהָ כִּשְׁעַת הַגְּזֵלָה.\nהַגּוֹזֵל בְּהֵמָה וְנָשָׂא עָלֶיהָ מַשָּׂא, אוֹ רָכַב עָלֶיהָ אוֹ חָרַשׁ אוֹ דָשׁ בָּהּ וְכַיּוֹצֵא בָּזֶה וְהֶחֱזִירָהּ לִבְעָלֶיהָ, אַף עַל פִּי שֶׁעָבַר \u0010y6\u0011 בְּלֹא תַּעֲשֶׂה, אֵינוֹ חַיָּב לְשַׁלֵּם כְּלוּם, שֶׁהֲרֵי לֹא \u0010y7\u0011 הִפְסִידָהּ וְלֹא הִכְחִישָׁהּ. וְאִם הֻחְזַק אָדָם זֶה לִגְזֹל אוֹ לַעֲשֹׁק אוֹ לַעֲשׂוֹת מַעֲשִׂים אֵלּוּ פַּעַם אַחַר פַּעַם, \u0010y8\u0011 קוֹנְסִין אוֹתוֹ, וַאֲפִלּוּ בְּחוּץ לָאָרֶץ, וְשָׁמִין הַשָּׂכָר אוֹ הַשֶּׁבַח שֶׁהִשְׁבִּיחַ בַּבְּהֵמָה וּמְשַׁלֵּם לַנִּגְזָל. \u0010c7\u0011\nהַתּוֹקֵף עַבְדּוֹ שֶׁל חֲבֵרוֹ וְעָשָׂה בּוֹ \u0010y9\u0011 מְלָאכָה, וְלֹא בִּטְּלוֹ מִמְּלָאכָה אַחֶרֶת, פָּטוּר, שֶׁנּוֹחַ לוֹ לָאָדָם שֶׁלֹּא יִלְמַד עַבְדּוֹ דַרְכֵי \u0010y10\u0011 \u0010c8\u0011 הַבַּטָּלָה. וְאִם בִּטְּלוֹ מִמְּלָאכָה אַחֶרֶת, מְשַׁלֵּם לוֹ כְּפוֹעֵל.\nהַתּוֹקֵף סְפִינָתוֹ שֶׁל חֲבֵרוֹ וְעָשָׂה בָּהּ מְלָאכָה, אִם אֵינָהּ עֲשׂוּיָה לְשָׂכָר, שָׁמִין כַּמָּה פִיחֲתָה וּמְשַׁלֵּם. \u0010y11\u0011 וְאִם הִיא עֲשׂוּיָה לְשָׂכָר, אִם יָרַד לָהּ בְּתוֹרַת שְׂכִירוּת, הוֹאִיל וְיָרַד שֶׁלֹּא בִּרְשׁוּת, אִם רָצָה הַבַּעַל לִטֹּל שְׂכָרָהּ, נוֹטֵל; רָצָה לִטֹּל פְּחָתָהּ, נוֹטֵל. \u0010c9\u0011 וְאִם יָרַד לָהּ בְּתוֹרַת גָּזֵל, נוֹתֵן הַפְּחָת, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְהוּא הַדִּין אִם נְטָלָהּ עַל דַּעַת שְׁאִילָה שֶׁלֹּא מִדַּעַת, גַּזְלָן הָוֵי. \u0005הַגָּה: \u0010y12\u0011 וְאִם שְׂכָרָהּ הַגַּזְלָן לְאַחֵר, צָרִיךְ לְהַחֲזִיר הַשָּׂכָר לַבְּעָלִים, הוֹאִיל וְעוֹמֶדֶת לְהִשָּׂכֵר (טוּר ס\"ה בְּשֵׁם הרמ\"ה)\u0006. וע\"ל סוֹף סִימָן ש\"ח מִדִּינִין אֵלּוּ. \u0010c10\u0011\nהַדָּר בַּחֲצַר חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ, \u0010y13\u0011 שֶׁאָמַר לוֹ: צֵא, וְלֹא יָצָא, חַיָּב לִתֵּן לוֹ כָּל שְׂכָרוֹ. וְאִם לֹא אָמַר לוֹ: צֵא, אִם אוֹתָהּ חָצֵר אֵינָהּ עֲשׂוּיָה לְשָׂכָר, \u0010y14\u0011 אֵינוֹ צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר, \u0010y15\u0011 \u0005וְאַף עַל פִּי שֶׁהוֹצִיא אֶת בַּעַל הַבַּיִת בְּעַל כָּרְחוֹ מִן הַבַּיִת וְהוּא דָּר בּוֹ (מָרְדְּכַי פֶּרֶק כֵּיצַד הָרֶגֶל)\u0006. וַאֲפִלּוּ הָיָה רָגִיל לְהַשְׂכִּירוֹ, רַק שֶׁעַכְשָׁיו לֹא עָבִיד לְמֵיגָר, בָּתַר הַאי שַׁעְתָּא אַזְלֵינָן \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַנַּ\"ל)\u0006, אַף עַל פִּי שֶׁדֶּרֶךְ זֶה הַדָּר לִשְׂכֹּר מָקוֹם לְעַצְמוֹ, שֶׁזֶּה נֶהֱנֶה וְזֶה אֵינוֹ חָסֵר. \u0005הַגָּה: וְדַוְקָא שֶׁכְּבָר דָּר בּוֹ, אֲבָל לֹא יוּכַל לְכֹפוֹ לְכַתְּחִילָה שֶׁיַּנִּיחֶנּוּ לָדוּר בּוֹ, אַף עַל פִּי דְכוֹפִין עַל מִדַּת סְדוֹם בְּמָקוֹם שֶׁזֶּה נֶהֱנֶה וְזֶה אֵינוֹ חָסֵר, הָנֵי מִלֵּי בְּדָבָר דְּאִי בָעֵי לֵהָנוֹת לֹא יוּכַל לֵהָנוֹת. אֲבָל בְּכִי הַאי גַוְנָא דְּאִי בָעֵי בַעַל חָצֵר לֵהָנוֹת וּלְהַרְוִיחַ לְהַשְׂכִּיר חֲצֵרוֹ הָיָה יָכוֹל, אֶלָּא שֶׁאֵינוֹ רוֹצֶה, אֵין כּוֹפִין אוֹתוֹ לַעֲשׂוֹת בְּחִנָּם (מָרְדְּכַי וְנ\"י פֶּרֶק הַנַּ\"ל)\u0006. וְאִם הֶחָצֵר עֲשׂוּיָה לְשָׂכָר, אַף עַל פִּי שֶׁאֵין דֶּרֶךְ זֶה לִשְׂכֹּר, צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר, \u0010y16\u0011 שֶׁהֲרֵי חִסְרוֹ מָמוֹן. \u0005הַגָּה: מִיהוּ, אִם לֹא הָיָה דָּר בּוֹ, אֶלָּא שֶׁגְּזָלוֹ מִמֶּנּוּ, פָּטוּר לְשַׁלֵּם הַשְּׂכִירוּת (טוּר ס\"ו בְּשֵׁם הָרֹא\"שׁ וּלְאַפּוֹקֵי מהרמ\"ה)\u0006. וּסְתָם בָּתִּים בַּזְּמַן הַזֶּה קַיְּמֵי לְאַגְרָא, וְאַף עַל גַּב דְּעֲדַיִן לֹא הִשְׂכִּירוֹ מֵעוֹלָם \u0005(מָרְדְּכַי פֶּרֶק כֵּיצַד הָרֶגֶל וְהַגָּהוֹת מַיְמוֹנִי פ\"ג דִּגְזֵלָה, וְעַיֵּן בַּת\"ה סִימָן שי\"ז)\u0006.\nיֵשׁ אוֹמְרִים דִּכְשֶׁאֵין הֶחָצֵר עוֹמֵד לְשָׂכָר דְּאַמְרֵינָן דְּאֵינוֹ צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר, אִם חִסְרוֹ אֲפִלּוּ דָבָר מוּעָט, כְּגוֹן שֶׁהָיָה הַבַּיִת חָדָשׁ וְזֶה חִסְרוֹ בַּמֶּה שֶׁהִשְׁחִירוֹ, אַף עַל פִּי שֶׁאֵין הֶפְסֵד אוֹתוֹ שַׁחֲרוּרִית אֶלָּא מוּעָט, \u0010y17\u0011 עַל יָדוֹ מְגַלְגְּלִין עָלָיו כָּל הַשָּׂכָר כְּפִי מַה שֶּׁנֶּהֱנָה. \u0010y18\u0011 \u0005וְאִם כֵּן אִם אֵין דֶּרֶךְ זֶה לִשְׂכֹּר, פָּטוּר, דְּהָא לֹא נֶהֱנָה. וְיֵשׁ חוֹלְקִין (ר' יְרוּחָם ני\"ב שְׁתֵּי הַדֵּעוֹת)\u0006.\nיֵשׁ אוֹמְרִים דְּהָא דְאַמְרִינָן דִּכְשֶׁהֶחָצֵר אֵינוֹ עוֹמֵד לְשָׂכָר אֵינוֹ צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר, דַּוְקָא שֶׁלֹּא גִּלָּה הַדָּר בְּדַעְתּוֹ שֶׁהָיָה רְצוֹנוֹ לִתֵּן לוֹ שָׂכָר אִם לֹא יַנִּיחֶנּוּ לָדוּר בּוֹ בְּחִנָּם. \u0010y19\u0011 אֲבָל אִם גִּלָּה בְּדַעְתּוֹ כֵּן, צָרִיךְ לִתֵּן לוֹ שָׂכָר:\nיֵשׁ אוֹמְרִים דְּהָא דְּאַמְרֵינָן דִּבְחָצֵר שֶׁאֵינוֹ עוֹמֵד לְשָׂכָר אֵינוֹ צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר, אֲפִלּוּ אִם שְׂכָרוֹ מֵאַחֵר \u0010y20\u0011 שֶׁהָיָה סָבוּר שֶׁהוּא שֶׁלּוֹ, וְנִמְצָא שֶׁאֵינוֹ שֶׁלּוֹ, אֵין צָרִיךְ לִתֵּן לוֹ שָׂכָר, אַף עַל פִּי שֶׁנִּכְנָס עַל דַּעַת לִתֵּן לוֹ שָׂכָר. \u0010y21\u0011 וַאֲפִלּוּ אִם נְתָנוֹ לְזֶה שֶׁשְּׂכָרוֹ מִמֶּנּוּ, צָרִיךְ לְהַחֲזִירוֹ. \u0010y22\u0011 וְאִם נָתַן לוֹ הַשָּׂכָר, כֵּיוָן שֶׁהוּא בָּרוּר שֶׁבְּטָעוּת יְהַב לֵהּ, חַיָּב לְהַחֲזִירוֹ. \u0010y23\u0011\nיֵשׁ אוֹמְרִים שֶׁזֶּה שֶׁאָמַרְנוּ בֶּחָצֵר הָעֲשׂוּיָה לְשָׂכָר חַיָּב לְהַעֲלוֹת לוֹ שָׂכָר, אֲפִלּוּ שְׂכָרוֹ מֵרְאוּבֵן וְנָתַן לוֹ הַשָּׂכָר, וְנִמְצֵאת שֶׁאֵינוֹ שֶׁלּוֹ אֶלָּא שֶׁל שִׁמְעוֹן, \u0010c11\u0011 צָרִיךְ לִתֵּן לְשִׁמְעוֹן שְׂכָרוֹ, \u0005הַגָּה: וְדַוְקָא שֶׁשִּׁמְעוֹן אוֹ שְׁלוּחָיו בְּכָאן וְהָיוּ מִשְׁתַּדְּלִין לְהַשְׂכִּירוֹ. אֲבָל אִם אֵינוֹ בָּעִיר וְאֵין מִי שֶׁמִּשְׁתַּדֵּל לְהַשְׂכִּירוֹ, הָוֵי כְּחָצֵר דְּלָא קַיְמָא לְאַגְרָא, וְאַף עַל פִּי שֶׁשָּׂכְרוֹ מֵרְאוּבֵן אֵין צָרִיךְ לִתֵּן לְשִׁמְעוֹן כְּלוּם, וּכְמוֹ שֶׁנִּתְבָּאֵר (הַגָּהוֹת מַיְמוֹנִי פֶּרֶק ג' דִּגְזֵלָה)\u0006, וְיַחֲזֹר וְיִתְבַּע מֵרְאוּבֵן מַה שֶּׁנָּתַן לוֹ. וַאֲפִלּוּ שָׂכְרוֹ מֵרְאוּבֵן בְּפָחוֹת מִכְּדֵי דָמָיו, צָרִיךְ לִתֵּן לְשִׁמְעוֹן כָּל הַשָּׂכָר הָרָאוּי לִתֵּן לוֹ, וְיַחֲזֹר וְיִתְבַּע מֵרְאוּבֵן מַה שֶּׁנָּתַן לוֹ. וְאִם שָׂכְרוֹ מֵרְאוּבֵן בְּדָמִים יְקָרִים, וְנִמְצָא הַבַּיִת שֶׁל שִׁמְעוֹן, לֹא יִפְרַע לוֹ אֶלָּא כְּפִי מַה שֶּׁשּׂוֹכְרִים אֲחֵרִים. וַאֲפִלּוּ אִם נָתַן כְּבָר לִרְאוּבֵן, אֵינוֹ נוֹטֵל שִׁמְעוֹן אֶלָּא כְּפִי מַה שֶּׁשּׂוֹכְרִים אֲחֵרִים. וּמִיהוּ, אִם בָּאוּ הַדָּמִים לְיַד שִׁמְעוֹן, וְהוּא טוֹעֵן שֶׁלֹּא הָיָה שׂוֹכְרָהּ בְּפָחוֹת, מִסְפֵיקָא לָא מַפְקִינָן מִנֵּהּ. \u0005הַגָּה: יִשְׂרָאֵל שֶׁבָּרַח מִן הָעִיר, וְלָקַח (הַשַּׂר)\u0006 בֵּיתוֹ וְהִשְׁאִילוֹ לְיִשְׂרָאֵל אַחֵר, אֵין צָרִיךְ לְהַעֲלוֹת שָׂכָר לַבְּעָלִים, דְּהָא לֹא קַיְמָא לְאַגְרָא, דְּאִי לָא הָוֵי דָּר בּוֹ יִשְׂרָאֵל הַשֵּׁנִי דָּר בּוֹ גּוֹי \u0005(הג\"מ פ\"ג דִּגְזֵלָה וּמָרְדְּכַי פֶּרֶק כֵּיצַד הָרֶגֶל)\u0006. הַשּׂוֹכֵר בַּיִת מֵחֲבֵרוֹ וְחָזַר וְהִשְׂכִּירוֹ לַאֲחֵרִים בְּיוֹתֵר מִמַּה שֶׁשָּׂכְרוֹ, אִם הָיָה לוֹ רְשׁוּת לְהַשְׂכִּירוֹ לַאֲחֵרִים בְּעִנְיָן שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שט\"ז, הַמּוֹתָר הוּא שֶׁלּוֹ. וְאִם לֹא הָיָה לוֹ רְשׁוּת לְהַשְׂכִּירוֹ, הַמּוֹתָר לַבְּעָלִים \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַנַּ\"ל)\u0006. \u0010c12\u0011 הָאוֹמֵר לַחֲבֵרוֹ: דּוּר בַּחֲצֵרִי, אֵין צָרִיךְ לִתֵּן לוֹ שָׂכָר \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַשְׁבַּ\"ץ)\u0006. שְׁנֵי שֻׁתָּפִין בְּבַיִת, וְהִשְׂכִּיר אֶחָד מִן הַשֻּׁתָּפִין כָּל הַבַּיִת שֶׁלֹּא מִדַּעַת שֻׁתָּפוֹ, צָרִיךְ הַשּׂוֹכֵר לִתֵּן לַשֻּׁתָּף הַשֵּׁנִי חֶלְקוֹ \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַשְׁבָּ\"א)\u0006 \u0010y24\u0011 ; אֲבָל אִם לֹא שָׂכַר כָּל הַבַּיִת, רַק חֵלֶק הַשֻׁתָּף שֶׁהִשְׂכִּיר לוֹ, אֵין צָרִיךְ לִתֵּן לַשֵּׁנִי כְּלוּם \u0005(ד\"ע)\u0006. \u0010c13\u0011\nמִי שֶׁהָיָה לוֹ \u0010y25\u0011 צֶמֶר וְסַמָּנִים שְׁרוּיִין, וּבָא אֶחָד וּגְזָלָן וְצָבַע הַצֶּמֶר \u0010c14\u0011 בַּסַמָּנִים, וְהוּזַל צֶמֶר הַצָּבוּעַ בְּעִנְיָן שֶׁאֵינוֹ שָׁוֶה אֶלָּא כְּמוֹ שֶׁהָיָה שָׁוֶה בִּהְיוֹתוֹ לָבָן, וְשׁוֹאֵל הַנִּגְזָל מֵהַגַּזְלָן דְּמֵי סַמָּנִים, \u0010y26\u0011 \u0010c15\u0011 פָּטוּר. \u0010y27\u0011 \u0010c16\u0011 וְאִם תָּפַס הַנִּגְזָל, אֵין מוֹצִיאִין מִיָּדוֹ:",["\u0003או שגזל פירות והרקיבו כולם. \u0004 האי כולם ל\"ד קאמר שהרי אחר זה כתב דדוקא דהרקיבו מקצתן אומר לו הש\"ל אלא רובן ככולן ומחצה על מחצה נידון כרוב:","\u0003כמו שגזל כלי ושברו \u0004 דין זה כתב הטור והמחבר בסי' שלפני זה בסי\"א ושם נתבאר דיש חילוק בין נשבר מאליו לנשבר בידי' לענין אם הוקר אחר הגזילה דמשלם כשע' שהוציא' מן העולם וכאן לא כחש' והפסיד' בידי' וה\"ל לדמותו לגזל כלי ונשבר מאיליו אלא משום דכאן לא איירי בהוקרה ואדרב' נפחת בדמי' מ\"ה נמי דקדק וכת' ושברו לדבר הפשוט דכמו כששבר הכלי בידים דהוא פשיט' דאינו יכול לומר הרי שלך לפניך כן נמי בהני:","\u0003או שגזל עבדים והזקינו \u0004 אע\"ג דכשהזקינו אינ' שוים לכלום ודומ' לבהמה והזקינה הנ\"ל אפ\"ה יכול לו' הרי שלך לפניך מטעם דעבד (לפי' רשב\"ם דוק' במילי דאורייתא כגזל ואונאה ושבועה) דומה לקרקע כמ\"ש והתנחלתם אות' לבניכ' לרשת אחוזה ואחוזה זו קרקע וקרקע אינ' נגזלת אלא לעולם בחזקת הנגזל קאי הן לטוב' כגון אם השביח' או אכל פירותי' (וכמ\"ש בסי' שע\"א גם בסי' זה לענין שכירות) הן לרעה כגון שנתקלקל מאליו כמו כאן משא\"כ בהמ' ושאר מטלטלים דברשות הגזלן קאי מיד שגזלן לטובה לענין שבח שקנאוהו הגזלן וכן לענין קלקול דצריך לשלמו כשעת הגזילה אלא דפסיד' דהדר לא מיקרי פסידא:","\u0003או תרומה ונטמאת או שגזל חמץ כו' \u0004 הטעם דאלו אף שנפסלו אצל הגזלן לגמרי מ\"מ תבואת תרומה ולחם חמץ לא נשתנה משאר תבואות ולחמין והרי הן כמו שהיו בשעת הגזילה וכמו שהן עכשיו שאר תבואות ולחמין מ\"ה מצי א\"ל הש\"ל משא\"כ בפסלתו מלכות כיון דצורת מטבע זו אינה יוצאה כלל בכל מדינות המלך ונטבעה צורה אחרת במקומה הרי ניכר הפסידה ועפ\"ר:","\u0003ונעבדה בה עבירה. \u0004 כגון רובע ונרבע או נעבדה לעכו\"ם או מוקצה:","\u0003אחר שנאסרה בהנאה כו' \u0004 רבותא קאמר דאפילו הני דכבר נאסרו בהנאה ואף אם לא נשרפו לא היה יכול להנות מהן מ\"מ כיון שנאבדו ואינו יכול להחזירו בעין צריך לשלם כ\"ש באינך הנ\"ל:","\u0003אינו חייב לשלם כלום \u0004 פי' אע\"פ שגם בעל הבהמה היה צריך לבהמה זו לעשות בה מלאכתו ובטלו ממנו אפ\"ה כיון דלא הפסידה יכול להחזירה בעינ' דקי\"ל דגזלן אינו משלם אלא כשעת הגזיל':","\u0003ומ\"ש ולא הכחישה. \u0004 כ\"כ גם בטור ואפשר דר\"ל בלא כחשה דאינו חוזר דאילו חוזר כבר נתבאר בר\"ס זה דמצי למימר הרי שלך לפניך וגם י\"ל דבכהאי דעשה בה מלאכה ונהנ' ממנ' ה\"ל כמ\"ש בסמוך בס\"ז דאם דר בבית דלא עביד למיגר והשחירו דצריך לשלם לו הכל אע\"ג דאפשר לחזור ללבנו מיהו זה קצת דוחק:","\u0003קונסין אותו ואפי' בחוצה לארץ כו' \u0004 כבר נתבאר זה בטור ובדברי המחבר בריש הספר בסי' ב' ושם מסקי וכתבו דהיינו דוקא גדול הדור או טובי העיר שהמחום בית דין עליהם ע\"ש:","\u0003ולא בטלו ממלאכ' אחרת \u0004 פי' ממלאכת רבו דהעבד:","\u0003ואם בטלו ממלאכה אחרת משלם כו' \u0004 כבר כתבתי בס\"א דה\"ט דעבדים דינם כקרקע ואינם נגזלים ומ\"ה אין אומרים בהו דמשלם בהן כשעת הגזיל' ובפריש' כתבתי דאפי' הרי\"ף דחולק בגוזל עבד וס\"ל דדינו כמטלטלים וכמ\"ש הטור בשמו כאן דלא נטלו לשם גזל אלא לעשות מלאכתו מודה דצריך לשלם לו דמי בטילתו:","\u0003ואם היא עשוי' לשכר כו'. \u0004 פי' בזה יד בעל הספינה על העליונה כיון דזה התוקף דעתו לשלם נוטל ממנו שכירות אם ירצה ואם אינו רוצה נוטל ממנו פחת הכלי כיון דנטלו שלא ברשות וכדין גזלן דמשלם כשעת הגזילה אבל אם נוטל ממנו השכירות אינו נוטל ג\"כ הפחת דהרי נפחת' מחמת מלאכה וכדין כל שוכר:","\u0003ואם שכרה הגזלן לאחר כו' \u0004 הטעם דדוקא בשבח הגזילה שנשבח בידו דהגזלן או הבאים מכחו דהיינו יורש ולוקח תקנו שיקנה הגזלן מפני תקנת השבים דכל שנשבח ברשותו אעפ\"י שנשבח מאיליו (ואפי' לא הי' בו שינוי כלל כגון שגזלה כשהית' מעוברת או טעונה והוציאה מידו בעוד שהיתה טעונה או מעוברת רק שנשתהא ביד הגזלן ונתרבת' ברשותו הגיזה והולד בעיבורה וכמ\"ש בסי' שס\"ב ס\"ח בהג\"ה ע\"ש) הרי הוא כאלו השביחו בידו וכן אם עשה בה הוא מלאכה תקנו שלא יוציאנו מידו שכר בדנחית בתורת גזילה משום תקנת השבים אלא משלם כעין שגזל משא\"כ בשכר זה שבא לידו מעלמא ואינו נשבח בגופו הרי הוא כהוקר הכלי דבו לא תקנו משום תקנת השבים שיצטרך ליתן לו הנגזל כפי מה שנתיקר ועפ\"ר ודרישה מ\"ש עוד מזה:","\u0003שאמר לו צא כו' \u0004 בכה\"ג בכל ענין אפי' בחצר דלא קיימא לאגרא וגברא דלא עביד למיגר צריך לשלם לו כל שכרו כיון דגילה דעתו דלא ניחא ליה ביה ואין אומרים בכה\"ג כופין על מדת סדום וכמ\"ש בסמוך:","\u0003אין צריך להעלות לו שכר \u0004 אע\"פ דכאן לא שייך טעם הנ\"ל בס\"ד בעבד דניח לו לאדם שלא ילמוד עבדו דרכי הבטלה מ\"מ שייך טעמא אחרינא והוא דאמרי' ביתא מיתבא יתיב ושאייה יוכת שער ומה\"ט ג\"כ נוח לו מסתמא שידירו בו גמרא ועפ\"ר:","\u0003אעפ\"י שהוציא את בעל הבית כו' \u0004 פי' זה שנכנס לדור בו הוציא לב\"ה שדר בו מהבית והוא דר בו במקומו מ\"מ אין זה אלא גרמא בעלמא כ\"כ המרדכי וד\"מ:","\u0003שהרי חסרו ממון \u0004 ואין זה מחשב גרמא בניזקין כיון דזה דר בו ואכל את כספו ואע\"ג דלא נהנה בו מ\"מ אכלו משא\"כ בגזל מחבירו ולא דר בו דלא אכלה ולא נהנה ממנו כיון דלא דר בו דזה מחשב גרמא ופטור וכמ\"ש מור\"ם מיד אחר זה ז\"ל מיהו אם לא היה דר בו כו':","\u0003על ידו מגלגלין כו' \u0004 פי' כיון דעכ\"פ צריך לשלם מה שחסרו מגלגלין ג\"כ ע\"י אותו המעט כל מה שנהנה וצריך לשלם הכל:","\u0003וא\"כ אם אין דרך זה כו' \u0004 ר\"ל כיון שהטעם דמגלגלין עליו הכל הוא כיון דנהנה א\"כ היכא דלא נהנה כגון שהוא גברא דלא עביד לאגורי אין מגלגלין עליו ואין נוטל בו אלא מה שחסרו:","\u0003אבל אם גילה בדעתו כן כו' \u0004 בטור כ' ז\"ל אבל אם גילה דעתו שהיה נותן לו שכר קודם שיצא ממנו ובפרישה כתבתי דכוונתו כמ\"ש כאן בש\"ע ותיבת קודם אינו מדוקדק כולי האי:","\u0003שהיה סבור שהוא שלו בנ\"י \u0004 כ' דזה שהשכיר לו סבור שהוא שלו והוא גברא דעביד להשכיר בתים שלו ומ\"ה השכירו בדמים בסברו שהוא שלו ונראה דכן פי' דברי הטור והמחבר:","\u0003אפי' אם נתנו לזה ששכרו כו' \u0004 ז\"ל הנ\"י הטעם דכי היכי דגבי משכיר מקח טעות הוא שהרי נתברר שאינו שלו לגבי שוכר נמי מקח טעות הוא כיון דאגר ממאן דלית לי' זכות בגוה לא משתעבד מכח האי שכירות לחד מינייהו וכמאן דלא אגר ליה דמי וחייב להחזיר לו השכירות דמחילה בטעות כה\"ג לאו מחילה הוא עכ\"ל ומה\"ט נמי לא אמרי' בזה דיהני גילוי דעתו שנתן שכירות כדאמרינן בסעיף שקודם לו דשאני הכא דהוה שכירות בטעות ובטילה מעיקרא ועפ\"ר מ\"ש עוד דלא מהני הגילוי דעת אלא כשגילה דעתו ליתן שכירות לזה שהוא בעל הבית ולא כשגילה דעתו ליתנו לאחר:","\u0003ואם נתן לו השכר כו' \u0004 ר\"ל אף אם נתן לו השכר כיון כו':","\u0003שזה שאמרנו בחצר העשוי' לשכר כו' בטור כ' ז\"ל ובחצר דקיימא לאגרא וגברא דעבד למיגר שחייב ליתן לו שכר ועפ\"ר דכתבתי דנראה דאו או קאמר וכל חד כפי דינו שנתבאר:\u0004","\u0003אבל אם לא שכר כל הבית כו' \u0004 אין צריך ליתן לשני כלום ואין לדמות זה למ\"ש הטור והמחבר לעיל סוף סי' קכ\"ב בשני שותפים שהיו להם חוב אצל א' והוציא שותף א' חצי החוב דמצי שותף השני לומר לו מאן פלג לך וצריך לחלק עמו. י\"ל דשאני התם דהלוו או הקיפו לו יחד משא\"כ בבית שדרים בו יחד או עומד להשכיר שכשהשכירו הא' יכיל לומר להשני דור עם זה שהשכרתיהו לו או השכיר ג\"כ חלקך לאחר ובלה\"נ לק\"מ דכאן לא איירי בשותף המשכיר מה יהי' דינו עם שותפו אלא מיירי בדין השוכר משותף א' אם צריך ליתן גם להשני חלקו:","\u0003צמר וסמנים שרוים כו' \u0004 אבל אם לא היו הסמנין שרויין אלא גזל צבע כמו שהי' והוא שחקן ודקקן ושרינהו קנאה בשנוי:","\u0003פטור ואם תפס כו' \u0004 איבעי' דלא איפשטא הוא בגמ' אי חזותא מילתא היא ומקרי השבה מעליא או לא ומשום הכי המע\"ה וע' מה שכתבתי בסי' שלפני זה בפרישה ובסמ\"ע שבכה\"ג דהוא ספיקא דתלמודא גם הרא\"ש מודה דאין מוציאין מיד התופס:","\u0003ואם תפס כו' \u0004 הטור מסיק בזה וכ' ז\"ל אבל אם גזל סמני' שרויים וצבע בהן צמרו של הגזלן חייב לשלם דמיהם מנין ואפי' לא השביח בהן צמרו עכ\"ל והטעם כיון דהצמר של הגזלן א\"א להשיב הסמנין לחוד להנגזל בלא הצמר והצמר עם הסמנין ודאי לא ישיב לו בחנם וק\"ל:"],["\u0003 או שגזל מטבע ונסדק כו' \u0004 ע' בתשו' רשד\"ם סי' צ\"ג:","\u0003 או שגזל עבדים כו' \u0004 דעבדא כקרקע דמי והרי\"ף הגיה בסוף ימיו דבעבדים והזקינו א\"י לומר הרי שלך לפניך מדקי\"ל כר' נחמן דאמר בפ\"ק דב\"ק דאין גובים מן העבדים וכבר חלקו כל הפוסקים עליו ובאמת בלאו הכי בע\"כ צריך לחלק דכי יחלוק רב נחמן אכל הני דקי\"ל דעבדא כמקרקע דמי לענין שבועה ואונאה וקנין ופדיון בכור וכמה דוכתי והנה התוס' פ\"ק דב\"ק דף י\"ב ע\"א כתבו דבכל מילי דאורייתא קי\"ל דכקרקע דמי אבל במילי דרבנן כמטלטלי דמי לכך אין גובים מן העבדים דשעבוד' דרבנן ופרוזבל נמי דרבנן וקנין דאגב נמי דרבנן דקרא דערים בצורות אסמכתא היא וכ\"כ הרא\"ש פ' הגוזל קמא בשם רשב\"ם ומביאו ב\"י ס\"א ואחריו נמשך מהרש\"ל פ\"ק דב\"ק סי' ל\"ג ופ' הגוזל קמא סי' ח' וכ\"כ ה\"ה פ' ג' מה\"ג וז\"ל טעם העבדים מפני שדינן כקרקע שאינו נגזלת והכי פסק רב בש\"ס וכן עיקר וכבר כתבו המפרשים דבכל דין תורה דינם כקרקע עכ\"ל ואין נ\"ל כן דדוחק לחלק בין מילי דאורייתא למילי דרבנן דכל דתקון רבנן כעין דאורייתא תקון ועוד דדוחק הוא לומר דקרא דערים בצורות אסמכתא הוא. ועוד דא\"כ היכא קאמר התם בש\"ס פ\"ק דב\"ק להך לישנא דאמר עבדא כמקרקעי דמי ל\"ל עומדים בתוכה הא להך לישנא דעבדא כמטלטלי דמי תיקשי הכי דהא התם מילי דאורייתא הוא ואמת שהתוס' שם הרגישו בזה וכתבו דבלאו הכי פריך שפיר אבל לפענד\"נ דלא יתכן כלל לומר בכאן בלא\"ה פריך שפיר דהא קאמר בהדיא דלהך לישנא דכמטלטלי דמי ניחא ולא פריך ליה אלא ממאי דקי\"ל דלא בעינן צבורים ע\"ש וגם בדעת הרמב\"ם נלפע\"ד דא\"א לומר כמ\"ש ה' המ' דא\"כ יהי' טעמו דר' נחמן משום דשעבודא דרבנן והרי הרמב\"ם פסק דשעבודא דאורייתא. וכן מוכח מכל הפוס' שהבאתי לעיל סי' ל\"ט ס\"ק ב' שפסקו שעבודא דאורייתא דלא כהתו' והרא\"ש בזה שהרי כולם פסקו הך דר' נחמן ובאמת מוכרח לפסוק כר' נחמן דהא קי\"ל הלכה כרב נחמן בדיני ועוד דהכי הוא מסקנא דשמעתא פ\"ק דב\"ק ועוד דהכי מסקי' להדיא בפ' יש נוחלין (בבא בתרא סוף דף קכ\"ח) א\"ל רבינא לרב אשי דרב נחמן מאי א\"ל אין גובין מתנינן לה וכן אמר רב נחמן כו' וא\"כ לפי דברי התוס' והרא\"ש וה' המ' יהי' מוכרח לומר דקי\"ל שעבודא לאו דאורייתא ותקשי לכל הפוסקים שהבאתי לעיל סי' ל\"ט שפסקו שעבודא דאורייתא וגם הרא\"ש גופיה כתב בכמה דוכתי דשעבודא דאורייתא וכן פסק מהרש\"ל גופיה וכמ\"ש לעיל סי' ל\"ט ס\"ק ב' בשמו אלא נ\"ל דאשכחן בכמה דוכתי דלענין ב\"ח שאני דלא סמיך דעתיה עליה וא\"כ הכא נמי נהי דעבדא כמקרקעי דמי היינו לענין דינין הכתובים בתורה אבל לענין סמיכת הב\"ח כיון דיכול לברוח לא סמכ' דעתי' עליה וכמטלטלי דמי וכן לענין פרוזבל לא סמיך עליה וכן לענין קנין אגב לא סמיך דעתיה דלוקח לקנות בו המטלטלים כיון שלא עשה שום קנין במטלטלי' עצמן רק שיזכה בהן אגב העבד והעבד גופיה יכול לברוח ושוב עיינתי בפירשב\"ם פ' יש נוחלין ונלפע\"ד דגם כוונת רשב\"ם כן ודלא כמ\"ש הרא\"ש בשמו וז\"ל שם בדף קכ\"ח ע\"א ורב נחמן אמר אין גובין דנהי דאיתקיש לקרקעות כדכתי' והתנחלתם הני מילי לדברים הכתובים בתורה כגון לקנותן בכסף ובשטר ובחזקה ושלא לישבע עליהן ושאין בהן אונאה אבל לענין ב\"ח כמטלטלי דמי דאין ב\"ח סומך אלא על קרקעות שאין יכולים ליאבד ולא לזוז ממקומן אבל עבדים לא סמכה דעתיה הלכך לא משתעבדי ליה עכ\"ל. וכ\"כ הבעל המאור פ' י\"נ דף רי\"ח סוף ע\"א ע\"ש שהביא שם דברי רשב\"ם הנ\"ל אות באות וכ' שנראין דבריו ומ\"ש הבעל המאור שם וההיא דאמר רב הלכה כרבי מאיר אף היא מדברים הכתובים בתורה ר\"ל לאפוקי דלא שייך התם לו' דלא סמיך דעתיה וכן מ\"ש הבעל המאור ודינא דעבדים בדבר שאינו מן התורה כמטלטלי דניידי כו' נ\"ל דר\"ל בדבר שאינו תלוי בדין תורה רק באומדן דעתי' אי סמיך עליה או לא וכ\"כ הנ\"י פי\"נ וז\"ל ב\"ח גם לא יגבה מן העבדים אע\"ג דאתקיש לקרקעו' כדנפק' לן מוהתנחלתם אותם וטעמ' משום דדוק' בקרקעו' שהוא דבר קיים הוא דב\"ח סמיך עלייהו אבל לא במטלטלי' ועבדי עכ\"ל וכ\"מ להדי' מדברי הרמב\"ן שכ' בספר המלחמו' פ' הגוזל קמא דף ל\"ח ע\"ב וז\"ל אבל יותר נראין דברי הרי\"ף הראשונים שפסק הרב והרוצה לסמוך על העיקר יסמוך על דברי ר\"ש הצרפתי הכתובי' בס' המאור הזה בפי\"נ עכ\"ל והרי הרמב\"ן פסק דשעבוד' דאוריית' אלא וודאי כוונתו כמ\"ש דשאני ב\"ח ודכותי' דלא סמכי דעתייהו עליה ושוב מצאתי בנ\"י פ' הגוזל קמא להדיא כדברי ע\"ש במ\"ש וכ' הרא\"ה ז\"ל כו':","\u0003 והזקינו \u0004 נ\"ל הא דנקט הזקינו ל\"ד אלא ה\"ה נשרפו ואינן בעולם כלל לדידן דקי\"ל עבדי כמקרקעי דמי וכמו שהוכחתי לק' סי' שפ\"ו ס\"ק י\"ג מן הש\"ס והרמב\"ם וה' המ' וסמ\"ג ע\"ש והראב\"ד כ' בהשגות רפ\"ט מה' גזיל' וז\"ל ה\"מ לענין כחיש' אע\"ג דלא הדר גזילה מיה' בעינא איתא ואומר לו הרי שלך לפניך אבל מ\"מ נגזלים הם ונקנים ביאוש דכתיב וישב ממנו שבי ואמרי העבד שנשבה ופדאוהו לשם ב\"ח ואחר יאוש לא ישתעבד לא לראשון ולא לשני אלמא לאו כקרקע דמי דהא קני נפשיה ביאוש הלכך כשמת העבד או נשרף משלם את דמיו שהרי משמת אין שלו לפניו וכשמת לגזלן מת עכ\"ל ונראה דאף דבמה דס\"ל להראב\"ד דכשם שאין קרקע נגזלת כך אין יאוש לקרקע והא בהא תליא נראין דבריו והיינו כדעת רש\"י והתו' ר\"פ לולב הגזול ושאר הרבה פוסקים לקמן ר\"ס שע\"א ולעיל סי' ל\"ז סעיף י\"ז (ועיין בב\"ח שם סי' ל\"ז ודלא כתוספות והרא\"ש פח\"ה מ\"מ בהא דס\"ל להראב\"ד דכשנשרף העבד חייב אין דבריו נלפע\"ד דהא עבד איתקש לקרקע והיאך נימ' דהוקש לחצאין לענין כחש דלא הדר' ולא לענין נשרף אלא ודאי משמע דאיתקש לגמרי לקרקע דברשותא דמארי' קמא קאי וה\"ל כאלו לא גזלה הכי משמע פשט' דש\"ס פ' הגוזל בתר' (בבא קמא סוף דף קי\"ז) ופ' שבועות הפקדון (שבועות סוף דף ל\"ז) והכי משמע נמי בפ' הגוזל קמא (בבא קמא דף צ\"ז ע\"א) גבי הא דקאמר בעשה בו מלאכ' פטור ואי ס\"ד עבדא כמקרקעי דמי אמאי פטור ברשותי' דמארי' קאי ע\"ש והא דאמרי' בהשולח (דף ל\"ז ע\"א) דעבד שנשבה כו' אחר יאוש לא ישתעבד וילפי' לה מדכתיב וישב ממנו שבי נראה דש\"ה דגלי לן קרא דמהני בה יאוש אבל מ\"מ ל\"ש בתורת גזל' ועוד י\"ל דגם בעבד גופי' לא מהני יאוש והתם דמהני יאוש היינו בעבד שנשבה במלחמ' שאני דגלי לן קרא דחזקת מלחמ' מהני ואפי' בקרקע גופ' מהני חזקת מלחמ' וכדילפי' התם מעמון ומואב טהרו בסיחון וכבר האריך הרשב\"א בפ' השולח בחדושיו דף נ\"ט סוף ע\"א להוכיח כל זה ומשמע להדי' מדברי הרשב\"א שם דאין יאוש לעבד כמו שאין יאוש לקרקע ושאני התם דגלי לן קרא דחזקת מלחמ' מהני וא\"כ לפי זה ודאי אף נשרף העבד פטור הגזלן כמו בקרקע דעבד אינו נגזל כמו קרקע וכ\"מ מדברי ראב\"ן בפ' הגוזל דף פ\"ט ריש ע\"ג וז\"ל עבדים והזקינו אומר לו הרי שלך לפניך דעבדא כמקרקעי דמי אינו נגזל כמו קרקע דאינה נגזלת כו' וכן הלכה עכ\"ל וכן נ\"ל עיקר:","\u0003 מטבע ונפסל כו' \u0004 והוא בעין דאל\"כ משלם כשעת הגזלה דהיינו מטבע החדש' תו' פרק הגוזל (בבא קמא דף צ\"ז) ריש ע\"ב ור' ירוחם נל\"א ח\"ד וכ\"כ מהרש\"ל סי' י\"ב והוא פשוט:","\u0003 במדינ' זו כו' \u0004 והתו' והרא\"ש והטור ורבי' ירוחם שם פסקו דאפי' פסלתו מלכות א\"ל הרי שלך לפניך וכ\"פ בש\"ג וכ\"פ מהרש\"ל שם (והיינו כהי\"א שבהג\"ה) וכ' שאפי' פסלו בכל המלכות שבעולם שאינו יוצאות כלל ע\"ש:","\u0003 והרקיבו מקצתם כו' \u0004 אבל הרקיבו כולם משלם כשעת הגזילה ש\"ס וכתב בהג\"א פי' שהרקיבו עם הכנימה אבל אם הרקיבו מחמת התולעת הרי הן כבריאי' והכי איתא בירושלמי מא\"ז עכ\"ל ר\"ל דאל\"כ אין טעם לחלק בין כולן למקצתן וק\"ל ולפ\"ז מ\"ש בסמ\"ע ס\"ק א' אינו מכוון ודוק:","\u0003 הרי שלך לפניך. \u0004 מה שפסק מהרש\"ל פ' הגוזל קמא סי' ך' דאין אומרים באיסורי הנאה הרי שלך לפניך רק גבי גזלן ולא גבי שומר אינו נראה לפענ\"ד וכל דבריו אינם מחוורין לפענ\"ד בראש מ\"ש תימא בעיני שרישא דברי הכל וסיפא דמתני' הוי ר' יעקב כו' לא קשה מידי דהא לא אמרינן דרישא רבנן לחוד דנימא דמתני' אתיא כתרי תנאי אלא כולה מתני' אתיא כר' יעקב ורישא אתיא אפי' כרבנן וכן הוא סוגית התלמוד בכמה מקומות עצמו מספר וגם מדברי התוס' פ' שש\"נ דף מ\"ה מוכח להדיא דס\"ל דסיפא ר' יעקב ורישא דברי הכל ע\"ש והכי משמע לישנא דגמ' חמץ ועבר עליו הפסח כו' ולא קאמר מני מתני' ר' יעקב היא כו' אלא ודאי משום דהאי מתני' בלאו הכי ר' יעקב היא אלא דבחמץ ועבר עליו הפסח כו' בעי תלמודא לאשכוחי תנא דאמרי' באיסורי הנאה הרי שלך לפניך ומסיק דכ\"ע מודו בהכי. עוד כ' מהרש\"ל שם אלא נראה בעיני כו' אבל גבי גזלן לא שייך ה\"ט כו' ע\"ש שמחלק בין גזלן לשומר ומזיק ומלבד מה שאין השכל נותן דשומר ומזיק יגרע מגזלן לענין זה דבריו תמוהין שהרי להדיא מסיק בגמ' והשיב את הגזילה אשר גזל יחזיר כעין שגזל מכאן אמרו כו' מאן שמעת ליה דאמר עד שלא נגמר דינו אין משנגמר דינו לא רבנן וקתני דחמץ ועבר הפסח כו' וכמדומה לי שמהרש\"ל אגב חורפיה לא ראה סוף הסוגיא וכן מוכח מסוגיא דפ' הנזקין וכל שאר דבריו אינן מחוזרין וכמו שהשגתי עליו בספרי:","\u0003 התוקף עבדו של חבירו כו' \u0004 מוכח מסעיף זה וסעיף שאח\"כ דמטלטלין דנגזלין אם גזלן ועשה בהן מלאכה ולא פחתן אפי' קיימא לאגרא פטור כיון דגזלן ברשות הגזלן הוי ובדידיה דנפשיה קעביד מלאכה ודוק וכן משמע לקמן סי' שע\"א ס\"ב:","\u0003 ואם בטלו ממלאכה אחרת כו'. \u0004 עיין בסמ\"ע ס\"ק י\"א עד ובדרישה כתבתי דאפי' הרי\"ף דחולק בגוזל עבדים וס\"ל דינו כמטלטלי וכמ\"ש הטור בשמו בכאן דלא נטלו לשם גזל אלא לעשות מלאכתו מודה דצריך לשלם דמי בטילתו עכ\"ל וצ\"ע דבש\"ס לא משמע הכי אלא נראה דכשחזר בו הרי\"ף ופסק עבדי כמטלטלי חזר בו גם מהך דמייתי בתר הכי בתוקף עבדו וכ\"כ בש\"ג פ' הגוזל סוף דף ל\"ה להדיא ובס' מע\"מ פ' הגוזל קמא האריך בזה וכן בס' לח\"מ פ\"ג מה' גזלה האריך קצת בזה ואין להאריך בזה כיון דלענין דינא כל הפוסקים חולקים על הרי\"ף וס\"ל עבדי כמקרקעי וגם הרמב\"ן בס' המלחמות נושא כליו של הרי\"ף כ' בפרק הגוזל קמא שיותר נראין דברי הרי\"ף הראשונים וכן עיקר:","\u0003 ואם ירד לה בתורת גזל כו' \u0004 עיין בס' מגדל דוד:","\u0003 הדר בחצר חבירו כו' \u0004 עיין בתשוב' סי' תמ\"ו ותס\"ד ובתשו' מהרא\"ן ששון סי' קכ\"ט:","\u0003 צריך ליתן לשמעון שכרו כו' \u0004 ואע\"פ ששלמו ימי שכירתו כ\"כ הרמב\"ן בחדושיו פ' חזקת הבתים דף כ\"ה ע\"ד בחדושיו:","\u0003 האומר לחבירו דור בחצירי כו' \u0004 והב\"ח פסק דהמע\"ה דבת\"ה סי' שי\"ז בשם מהרי\"ח חולק ע\"ז הביאו מור\"ם ס\"ס רמ\"ו ע\"ש בסמ\"ע והיינו דוקא בחצר דקיימא לאגרא וגברא דעביד למיגר משא\"כ בגברא דלא עביד למיגר גם הב\"ח מודה דפטור מאחר דזה אינו חסרו מדעתו כן נ\"ל ודוק בת\"ה ובב\"ח וע\"ל סימן רמ\"ו כתבתי דדברי ת\"ה בשם מהרי\"ח צ\"ע עיין בי\"ד סי' קס\"ו:","\u0003 מי שהיה לו כו' \u0004 כ' בס' ת\"ח פ' הגוזל עצים וז\"ל והא דלא מוקי לה כגון דגזל הצמר וצבעו בצבע שלו דמבעיא ליה אי אמרי' יש שבח סמנין ע\"ג צמר וצריך הנגזל לשלם לגזלן דמי הצבע כשמחזיר לו הגזלה דגזלן שהשביח קנה השבח כדאמרינן לעיל או אין שבח סמנין ע\"ג צמר מצי אמר ליה לית לך גבאי ולא מידי משום דבעי לאוקמי אליבא דכ\"ע אפי' למ\"ד שינוי החוזר לברייתו כגון גזל צמר וצבעו אע\"ג דאפשר להעבירו ע\"י צפון קני' וכיון דקני גזלן את הצמר א\"צ להחזירו אלא משלם דמי הצמר כשעת הגזלה עכ\"ל ולפי דבריו לדידן דקי\"ל לעיל סי' ש\"ס דלא הוי שינוי וכמ\"ש בסעיף ו' ה\"מ למבעי הכי וה\"ל ספיקא דדינא אבל אין דבריו נ\"ל אלא נ\"ל דאפי' למ\"ד לא הוי שינוי ולא קני' ליה גזלן מ\"מ פשיטא דבכה\"ג צריך לשלם לגזלן כדין יורד שלא ברשות השבח או ההוצאה ואין נ\"מ בין יש שבח סמנים או אין שבח סמנים בזה ועיין בתוס' שם סוף דף ק' גבי מה שהקשו שם על הירושלמי מ\"ש מיורד ברשות ובהרא\"ש שם וע\"ל ס\"ס שע\"ב ודוק:","\u0003 והוזל הצמר \u0004 פי' שהוזל אח\"כ דאם הוזל בשעת הצביעה חייב וכמ\"ש לקמן:","\u0003 פטור ובנ\"י \u0004 פ' הגוזל כ' דהא לא אתיא אלא אליבא דמאן דלא דאין דינא דגרמי אבל למאן דדאין דינא דגרמי דקי\"ל כותיה חייב דהא אותבינהו בדוכתא דלא מצי למישקלינהו עכ\"ל ואין כן דעת כל הפוסקים אלא נראה דכיון דבשעה שצבע הצמר היתה שוה כפי הצמר והסמנין אלא שאח\"כ הוזל א\"כ בשעת צביעה לא הזיקו כלל וליכא כאן גרמי דממילא הוזל אח\"כ ואומר לו הש\"ל וכן יראה להדיא מדברי בעל המאור שכ' דאוקימתא דצבע בהו קופא ליתא לדידן דדיינינן דינא דגרמי אלמא דאוקימתא דזל צבעא איתא אפי' לדידן וכ\"כ הרמב\"ן בס' המלחמות שם וז\"ל אמר הכותב הבו ליה אפריון לבעל המאור ז\"ל דהיינו דכ' רבינו הגדול ז\"ל בעיא דזל צבעא פי' דזל לאחר שצבעו ולא כ' דצבע בהו קופ' עכ\"ל ואולי הנ\"י הבין דזל צבעא היינו בשעה שצבעו ודוק עיין בסמ\"ע ס\"ק כ\"ז ומ\"ש לעיל סי' שס\"ב ס\"ו:","\u0003 ואם תפס הנגזל כו' \u0004 הטור מסיק בזה וכתב ז\"ל אבל אם גזל סמנים שרוים וצבע בהן צמרו של הגזלן חייב לשלם דמי הסמנים ואפי' לא השביח עכ\"ל והביאו בסמ\"ע ס\"ק כ\"ז והוא מהש\"ס פ' הגוזל (בבא קמא דף ק\"א ע\"א) נימא לי' הב לי סמנאי דאפסדתינהו כו' ובב\"י ובב\"ח לא נרשם מאין הוציא הטור דין זה:"]],["\u0010c0\u0011 מִי שֶׁהֵעִידוּ עָלָיו שֶׁנִּכְנַס לְבֵיתוֹ שֶׁל פְּלוֹנִי בְּפָנָיו וְנָטַל כֵּלִים, וְאֵין יָדוּעַ כַּמָּה נָטַל, \u0010y0\u0011 נִתְבָּאֲרוּ מִשְׁפָּטָיו בְּסִימָן צ'.\nרָאוּהוּ עֵדִים שֶׁנִּכְנַס לְתוֹךְ בֵּית חֲבֵרוֹ, שֶׁלֹּא בִפְנֵי בַעַל הַבַּיִת, וְנָטַל מִשָּׁם כֵּלִים, אַף עַל פִּי שֶׁהוֹצִיאָם מְגֻלִּים, וְאַף עַל פִּי שֶׁהַבַּעַל הַבַּיִת הַזֶּה עָשׂוּי לִמְכֹּר אֶת כֵּלָיו, אִם טָעַן וְאָמַר: דֶּרֶךְ גָּזֵל לְקָחָם, וַהֲלָה אוֹמֵר: בִּרְשׁוּתְךָ בָּאתִי וְאַתָּה מְכַרְתָּם לִי אוֹ נְתַתָּם לִי, אוֹ: בְּחוֹב שֶׁיֵּשׁ לִי אֶצְלְךָ תְּפַסְתִּים, אֵינוֹ נֶאֱמָן, שֶׁכָּל הַנִּכְנָס לְבֵית חֲבֵרוֹ שֶׁלֹּא בְּפָנָיו וְנָטַל כֵּלִים מִשָּׁם, וְהוֹצִיאָם בִּפְנֵי עֵדִים הֲרֵי זֶה בְּחֶזְקַת גַּזְלָן; לְפִיכָךְ, מַחֲזִיר הַכֵּלִים לְבַעַל הַבַּיִת וְאֵין כָּאן שְׁבוּעָה, שֶׁהֲרֵי הָעֵדִים רָאוּ מַה גָּזַל; וְאַחַר שֶׁיַּחֲזִיר חוֹזֵר וְתוֹבֵעַ אֶת בַּעַל הַבַּיִת בְּכָל מַה שֶּׁיִּטְעֹן, וְהַדִּין בֵּינֵיהֶם.\nוְכֵן אִם הָיָה שָׁם עֵד אֶחָד בִּלְבַד, וּבַעַל הַבַּיִת טוֹעֵן שֶׁגָּזוּל הוּא כְּלִי זֶה בְּיָדוֹ, וַהֲלָה אוֹמֵר: לָקוּחַ הוּא בְּיָדִי, אוֹ: בְּחוֹב גְּבִיתִיו, אוֹ: שֶׁלִּי הָיָה וּפִקָּדוֹן הוּא אֶצְלְךָ, הֲרֵי זֶה חַיָּב לְהַחֲזִיר הַכְּלִי לִבְעָלָיו בְּלֹא שְׁבוּעָה, שֶׁאִלּוּ הָיוּ שְׁנֵי עֵדִים הָיָה חַיָּב לְשַׁלֵּם, וְעַכְשָׁיו שֶׁאֵין שָׁם אֶלָּא עֵד אֶחָד \u0010y1\u0011 \u0010y2\u0011 חַיָּב שְׁבוּעָה, וְאֵינוֹ יָכוֹל לִשָּׁבַע שֶׁהֲרֵי אֵינוֹ מַכְחִישׁ אֶת הָעֵד, וְכָל הַמְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע, מְשַׁלֵּם. לְפִיכָךְ, אִם כָּפַר וְאָמַר: לֹא נִכְנַסְתִּי לְבֵיתוֹ וְלֹא נָטַלְתִּי כְלוּם, הוֹאִיל וְאֵין שָׁם אֶלָּא עֵד אֶחָד וְהוּא מַכְחִישׁוֹ, הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הַתּוֹרָה שֶׁלֹּא לָקַח מִבֵּיתוֹ כְּלוּם, וְנִפְטָר. \u0005(ע\"ל סִימָן צ' ס\"ג)\u0006.\nחָטַף לְשׁוֹן כֶּסֶף מִיַּד חֲבֵרוֹ בִּפְנֵי עֵד אֶחָד, וְאָמַר: חָטַפְתִּי \u0010y3\u0011 וְדִידִי חָטַפְתִּי, חַיָּב לְהַחֲזִיר.\nחָטַף מִמֶּנּוּ זְהוּבִים בִּפְנֵי עֵד אֶחָד, \u0010y4\u0011 וְהוּא אוֹמֵר: שֶׁלִּי חָטַפְתִּי וְעֶשְׂרִים הָיוּ, אַף עַל פִּי שֶׁאֵין הָעֵד יוֹדֵעַ כַּמָּה חָטַף, הֲרֵי זֶה מְשַׁלֵּם הָעֶשְׂרִים, שֶׁהֲרֵי יָדַע בְּוַדַּאי שֶׁזְּהוּבִים חָטַף, וְנִמְצָא שֶׁהוּא מְחֻיָּב שְׁבוּעָה שֶׁאֵינוֹ יָכוֹל לִשָּׁבַע, וּמְשַׁלֵּם:\nאָמַר הַחוֹטֵף: עֶשְׂרִים חָטַפְתִּי וְשֶׁלִּי הֵם, וְהַנִּגְזָל אוֹמֵר: מֵאָה חָטַף, מְשַׁלֵּם הָעֶשְׂרִים שֶׁהוֹדָה בָהֶם, \u0010y5\u0011 \u0010c1\u0011 וְעַל הַשְּׁאָר נִשְׁבָּע הֶסֵת.\nנִכְנַס לְבֵיתוֹ שֶׁל חֲבֵרוֹ שֶׁלֹּא בְּפָנָיו וְנָטַל מִשָּׁם כֵּלִים בִּפְנֵי עֵד אֶחָד, וְאֵין הָעֵד יוֹדֵעַ כַּמָּה נָטַל, בַּעַל הַבַּיִת אוֹמֵר: עֶשְׂרִים כֵּלִים הָיוּ בְבֵיתִי, וְגַזְלָן אוֹמֵר: לֹא נָטַלְתִּי אֶלָּא עֲשָׂרָה וְהֵם שֶׁלִּי, חַיָּב לְהַחֲזִיר הָעֲשָׂרָה, \u0010y6\u0011 מִפְּנֵי שֶׁהוּא מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע, וְאֵינוֹ נִשְׁבָּע עַל הַשְׁאָר אֲפִלּוּ שְׁבוּעַת הֶסֵת, מִפְּנֵי שֶׁאֵינוֹ יָכוֹל לִטְעֹן עַל הַגַּזְלָן טַעֲנַת וַדַּאי.\n\u0005(כָּפוּל לְעֵיל סִימָן ע\"ה ס\"ח)\u0006 הָאוֹמֵר לַחֲבֵרוֹ: גְּזַלְתַּנִי מֵאָה, אִם אָמַר: לֹא גָּזַלְתִּי, נִשְׁבָּע הֶסֵת; וְאִם הוֹדָה שֶׁגְּזָלוֹ חֲמִשִּׁים, מְשַׁלֵּם חֲמִשִּׁים, וְנִשְׁבָּע שְׁבוּעַת הַתּוֹרָה עַל הַשְּׁאָר, כִּשְׁאָר הַנִּשְׁבָּעִים, \u0010y7\u0011 שֶׁהֲרֵי לֹא הֻחְזַק גַּזְלָן בְּעֵדִים.\nוְכֵן הַטּוֹעֵן אֶת חֲבֵרוֹ שֶׁנִּכְנַס לְבֵיתוֹ וּגְזָלוֹ כֵּלִים, וְהוּא אוֹמֵר: דֶּרֶךְ מַשְׁכּוֹן לְקַחְתִּים בְּחוֹבִי שֶׁיֵּשׁ לִי אֶצְלְךָ, וּבַעַל הַבַּיִת אוֹמֵר: אֵין לְךָ בְּיָדִי כְּלוּם, אַף עַל פִּי שֶׁהוֹדָה \u0010y8\u0011 שֶׁמִּשְׁכְּנוֹ שֶׁלֹּא בִּרְשׁוּת, \u0010y9\u0011 הוֹאִיל וְאֵין שָׁם \u0005(עֵדִים)\u0006 מְעִידִים שֶׁגָּזַל, הֲרֵי זֶה נִשְׁבָּע וְגוֹבֶה חוֹבוֹ מֵהַמַּשְׁכּוֹן:",["\u0003נתבארו משפטיו בסי' צ' \u0004 ע\"ש בטור בריש הסי' ובס\"ך ושם בס\"ך אהא דכתב שם ז\"ל לפיכך כל אלו החלוקים שייכים ג\"כ בנגזל שנכנס לבית למשכנו כו' כתבתי דיש חילוק בין אם שמעו ממנו שנכנס למשכנו שלא ברשות שיש עליו תורת גזלן ואח\"כ טוען את שלי לקחתי או לא נטלתי אלא אלו דבזה הנגזל נשבע ונוטל בכל ענין ובין אם זה שחשוד לגזלן נכנס והוציא כלים טוען ואומר לקחתיהו מידו דב\"ה דבזה נשתנה דינו במקצת ע\"ש בפר\"ד וסמ\"ע מ\"ש וכל זה דוקא שראוהו עדים שנכנס (בפני) הב\"ה ונוטל כלים מביתו אבל אם ראוהו עדים שנכנס לבית חבירו שלא בפניו יש לו דין אחר כתבו הט\"ו כאן בסעיף שאח\"ז וגם שם בסי' צ' כתבו בסעיף כ\"א ע\"ש אלא משום דכאן מקור דדיני גזילה חזר וכתבו אצל שאר דיני גזילה:","\u0003חייב שבועה ואינו יכול לישבע כו' \u0004 כבר נתבאר זה בכמה מקומות דכמו שהאמינה התורה שני עדים להתחייב למי שמעידין עליו לקיים כפי עדותן כן האמינה התורה לעד א' להביא למי שהעיד עליו להשבע שאינו כדברי העד וכל שאינו רוצ' להשבע שאינו כדברי העד צריך לשלם כאלו העידו עליו שנים וכיון שהעד מעיד שראוהו נכנס שלא בפניו ונטל משם כלי וזה הודה שנכנס ונטל והרי אינו יכול לישבע שהעד משקר שהרי מודה לו תו לא מהמנינן ליה ששלו נטל או שבחובו גבהו אלא דינו כאלו ראוהו שנים שנכנס הי' צריך להחזירו לו עכ\"פ כנ\"ל ואין לומר שיהא נאמן ששלו נטל במיגו שהי' נשבע כנגדו שלא נטל כלום או במיגו דהחזרתי לך זהו מחשב כמגו במקום חזקה כיון דמודה שנטלו בפניו וחזקה הוא שכל כה\"ג משל ב\"ה הוא נוטל וגם הוה מגו דהעזה נגד העד ועפ\"ר וד\"מ:","\u0003חייב שבועה ואינו יכול כו' \u0004 עד משלם הא דכ' הט\"ו לעיל בסי' צ' ס\"ג ז\"ל הי' עד א' מעידו כו' \"עד ה\"ז נשבע שלא גזלו ופטור שאני התם דהעד לא ראה מה שהוציא ואפי' שנים בכה\"ג דלא ראו מה שהוציא אין הב\"ה הנגזל נוטל כ\"א בשבועה כמ\"ש שם ובכה\"ג לא אמרי' כל ששנים מחייבים אותו ממון א' מחייבו שבועה ומתוך שאיל\"מ כיון דהשנים לא מחייבים אותו ממון כ\"א בשבועה משא\"כ כאן דמיירי דהעד ראה מה שהוציא דבכה\"ג בשני עדים מחייבים אותו ממון בנכנס שלא בפניו או שנכנס למשכנו מ\"ה אמרי' כאן מתוך שאינו יכול לישבע נגד העד משלם וק\"ל ועמ\"ש עוד מזה בסמוך סעיף ז':","\u0003ודידי חטפתי חייב להחזיר. \u0004 הוא ג\"כ מטעם הנ\"ל דה\"ל מחויב שבועה נגד העד שלא חטף ואינו יכול לישבע שהרי מודה שחטף וכ\"כ בטור בהדיא:","\u0003והוא אומר שלי חטפתי ועשרים היו כו' \u0004 פי' וגם התובע מודה לו שלא היו אלא עשרים אלא שטוען שחטפו מידו בזרוע ולא הי' של החוטף מעולם:","\u0003ועל השאר נשבע היסת. \u0004 הרמב\"ם מסיים בטעמו ז\"ל ואינו נשבע שבועה דאוריתא כמודה מקצת דהרי לא הודה בכלום שהרי אומר דידי חטפתי עכ\"ל והטור הביאו ע\"ש ול\"ד זה להא דר' חייא דאמר הכופר בכל ועדים מעידים במקצת שה\"ל כמודה מקצת דלא גרע העדאת עדים מהודאות פיו וחייב שבועה דאורייתא על המותר במלוה ובפקדון הוחזק כפרן וצריך לשלם הכל וכמ\"ש הט\"ו בר\"ס ע\"ה דשאני התם דאיכא עכ\"פ העדאת עדים במקצת משא\"כ כאן דאין העדים יודעים כמה חטף וגם ליכא העדאת פיו שהרי אומר דידי חטפתי וכנ\"ל די לנו במה שנתחייבו לשלם במה שהודה ולא להוסיף עליו חובה ע\"י כן במה שלא הודה:","\u0003מפני שהוא מחויב שבועה כו' \u0004 הטעם שהרי עכ\"פ ראה העד שהוציא כלים אף שאינו יודע כמה הוא הלא הוא בעצמו מודה שהוציא עשרה ואף שהפה שאסר הוא הפה שהתיר לומר שלי הוא מיגו כזה הוא במקום חזק' שכל מה שבבית האדם הוא בחזקת שלו וכנ\"ל אבל הראב\"ד השיג ע\"ז והטור הביאו וכתב כיון שהב\"ה לא היה בביתו כשנטלם ואינו יכול לטעון עליו טענת ודאי שנטלם וגם העד אינו יודע כמה נטל ואם שלו נטל אינו מקרי מחויב שבועה ע\"ש ול\"ד למ\"ש הראב\"ד וכתבו הטור בשמו בס\"ס ע\"ה והמחבר שם בסכ\"ג דאדם יכול לתבוע לחבירו ע\"פ ע\"א ולהביאו לש\"ד אע\"פ שאין ידוע להתובע בעצמו דשאני התם דעכ\"פ הוא ידוע לעד שחייב לו משא\"כ כאן דאין העד מעיד אלא שראוהו נכנס ונטל אבל אינו יודע אם שלו נטל או לא וכמה נטל והרמב\"ם אפשר דס\"ל דאין לחלק בין הא לדין ההוא דעכ\"פ העד מעיד שנכנס ונטל שלא בפניו וחזק' הוא דכל שלא בפניו נטל דבר שאינו שלו:","\u0003שהרי לא הוחזק גזלן בעדים ואין אדם משים עצמו רשע \u0004 וע\"ל סי' צ\"ב ס\"ח מדין זה וגם בס\"ס ל\"ד:","\u0003שמשכנו שלא ברשות \u0004 פי' וכל הממשכן שלא ברשות דינו כגזלן וכמ\"ש הט\"ו ר\"ס צ' ובסי' שנ\"ט ע\"ש:","\u0003הואיל ואין שם עדים \u0004 הרמב\"ם מסיים בזה וטור הביאו ז\"ל שהפה שאסר הוא הפה שהתיר ונשבע בנק\"ח כיון שנשבע ונוטל עכ\"ל וע\"ל סי' ע\"ב די\"א דבטוען משכון הוא בידי בכך וכך אינו נשבע אלא היסת כיון שהוא מוחזק ע\"ש בטור סי\"א אבל המחבר פסק שם סי\"ז דנשבע בנק\"ח:"],["\u0003 מי שהעידו עליו כו' \u0004 עמ\"ש באורך לעיל סימן צ':","\u0003 ועל השאר נשבע היסת כו' \u0004 ע\"ל סי' פ\"ז ס\"ה:"]],["\u0010c0\u0011 הַגּוֹזֵל אֶחָד מֵחֲמִשָּׁה \u0010y0\u0011 וְאֵינוֹ יוֹדֵע לְאֵיזֶה מֵהֶם גָּזַל, כָּל אֶחָד מֵהֶם אוֹמֵר: אוֹתִי גָּזַל, אַף עַל פִּי שֶׁאֵין שָׁם עֵדִים שֶׁגָּזַל, הֲרֵי \u0010y1\u0011 כָּל אֶחָד מֵהֶם נִשְׁבָּע שֶׁזֶּה גְּזָלוֹ, \u0010c1\u0011 וּמְשַׁלֵּם גְּזֵלָה לְכָל אֶחָד וְאֶחָד.\nאָמַר לִשְׁנַיִם: גָּזַלְתִּי אֶת אֶחָד מִכֶּם \u0010y2\u0011 וְאֵינִי יוֹדֵעַ אֵיזֶהוּ, אֵינוֹ נוֹתֵן אֶלָּא מָנֶה, \u0010c2\u0011 וְהֵם חוֹלְקִים בֵּינֵיהֶם, מֵאַחַר שֶׁהֵם לֹא הָיוּ יוֹדְעִים שֶׁנִּגְזְלוּ, \u0010c3\u0011 אֶלָּא עַל פִּיו; וְעִם כָּל זֶה \u0010y3\u0011 \u0010c4\u0011 אִם בָּא לָצֵאת יְדֵי שָׁמַיִם, חַיָּב לְשַׁלֵּם כָּל הַגְּזֵלָה לְכָל אֶחָד וְאֶחָד. \u0010y4\u0011 אֲבָל שְׁנַיִם שֶׁתָּבְעוּ אֶת אֶחָד, וְכָל אֶחָד מֵהֶם אוֹמֵר לוֹ: גְּזַלְתַּנִי מָנֶה, וְהוּא מֵשִׁיב: אֱמֶת שֶׁגָּזַלְתִּי אֶת אֶחָד מִכֶּם מָנֶה, אֲבָל אֵינִי יוֹדֵעַ לְאֵיזֶה מִכֶּם, \u0010c5\u0011 חַיָּב לְשַׁלֵּם לְכָל אֶחָד מֵהֶם מָנֶה. \u0005הַגָּה: \u0010y5\u0011 וְכֵן אִם גָּזַל לִשְׁנַיִם, לְאֶחָד מָנֶה וּלְאֶחָד מָאתַיִם, וְכָל אֶחָד מֵהֶם תּוֹבְעוֹ מָאתַיִם, וְהוּא אֵינוֹ יוֹדֵעַ לְמִי גָזַל מָאתַיִם, \u0010c6\u0011 נוֹתֵן לְכָל אֶחָד מָאתַיִם. \u0010c7\u0011 גָּזַל לְאֶחָד, וְאֵינוֹ יוֹדֵע אִם הֶחֱזִיר לוֹ, אַף עַל פִּי שֶׁאֵין תּוֹבֵעַ אוֹתוֹ, חַיָּב לְשַׁלֵּם לוֹ אִם בָּא לָצֵאת יְדֵי שָׁמַיִם. אֲבָל אִם אָמַר לְאֶחָד: אֵינִי יוֹדֵעַ אִם גְּזַלְתִּיךָ אִם לָאו, אֲפִלּוּ בְּבָא לָצֵאת יְדֵי שָׁמַיִם אֵינוֹ חַיָּב לְשַׁלֵּם לוֹ (טוּר)\u0006.",["\u0003ואינו יודע לאיזה מהם גזל כו' \u0004 עיין בטור ובדברי המחבר שכ' כעין דין זה בסי' ע\"ו לענין הלואה ובסי' ש' לענין פקדון ושם פירשתי טעמם ונימוקים של דברים הללו:","\u0003כל א' מהן נשבע. \u0004 פי' בנק\"ח ואע\"פ שאין זה הגזלן טוען כנגדו ברי שלא גזלו מ\"מ כיון דברי לו שלא גזל אלא לא' מהם והרי שניהם באים ליטול הטילו חז\"ל שבועה על התובעין וכדין הנשבע ונוטל:","\u0003ואיני יודע איזהו כו' \u0004 פי' וגם הן אין תובעין אותו לומר כל אחד בברי אני הוא הנגזל שגזלת מידי:","\u0003אם בא לצאת ידי שמים חייב לשלם לכל א' משא\"כ בהלוא' ופקדון שנתבאר דינם בסי' ע\"ו וש' דדוקא בהפקידו או הלוהו שניהן א' מנה וא' מאתים חייב ליתן לכל אחד מאתים בבא לצי\"ש ולא בהפקיד א' משנים מנה ולא ידע איזהו אלא שכתב שם די\"ח לחייב גם בזה לצי\"ש:\u0004","\u0003אבל שנים שתבעו את א' כו' \u0004 אין זה מל' הטור ולא מלשון הרמב\"ם דפ\"ד דגזילה שכתב שם ג\"כ דינים שלפני זה וכפל דברים הוא שהרי כתבוה כבר המחבר בס\"א:","\u0003וכן אם גזל לשנים כו' \u0004 זהו קאי גם אמ\"ש המחבר בס\"א והוא הוא וכן סדרן הטור גבי אהדדי כל אחד מהם תובעו מאתים כו' ואם לא תבעו אלא הוא אמר מעצמו כן כבר כתב המחבר דחייב ליתן לכל אחד בבבא לצי\"ש באם אמר שגזל אחד מהן וכ\"ש בזה שגזל לשניהן וכנ\"ל:"],["\u0003 הגוזל כו' \u0004 עיין בתשו' מהר\"ש כהן ספר ג' סימן נ\"ז:","\u0003 ומשלם גזלה לכל אחד וא' \u0004 והבעל המאור פרק הגוזל עצים ופ' המפקיד פסק כר\"ט דמניח גזילה ביניהם ומסתלק ואע\"פ שהרמב\"ן בס' המלחמות השיב שם עליו מ\"מ המעיין היטב יראה שאין הוכחה ברורה לסתור דבריו ונ\"ל כונת בעל המאור שבכל הספרים לא גרסי' אלא אמר רבא שאני מתני' כו' ומאן דגרס אלא הוא משום דסבר דכר\"ע נמי אתי מתני' וליתא אלא ס\"ל לש\"ס דלא מיתוק' מתני' כר' עקיבא דאפי' לא נשבע ובאו עדים נמי כך נ\"ל כוונתו שרצונו להקשות כן לר' עקיבא ודוק. ומ\"ש הרמב\"ן שם וז\"ל ומקצת הנוסחאות שאין בהם אלא אין להקפיד עליהם ויש לנו כיוצא בהם הרבה בש\"ס במסכת פסחים פ' אלו דברים אמר רב הונא ברי' דרב יושיע הב\"ע כגון שהפרישו קודם חצות ודחייה והדר גרסי' א\"ר פפא הא מני ר' אליעזר היא ושם בפסחים בפ' ואלו עוברין הב\"ע שבשלו בעצי מוקצה ובפ' שנים אוחזין ואי בעית אימא בשבח המגיע לכתפים כו' וראוי הי' לומר אלא עכ\"ל אין מכל זה ראיה דבהך דסוף פ' אלו דברים (דף ס\"ג ע\"ב) איתא בהדיא אלא אמר רב פפא וכן בפירוש רש\"י שם בפשיטות וכן בפרק אלו עוברין שם (פסחים דף מ\"ז ע\"ב) איתא אלא וגם מה שהביא מפרק שנים אוחזין אינו ראיה כ\"כ ע\"ש. וגם בתוס' פ' הגוזל (בבא קמא דף ק\"ד ע\"א) כתבו להדיא דלהספרים דלא גרסי' אלא לא אתי מתני' כר' עקיבא וע\"ש. גם מ\"ש הרמב\"ן שם שהבעל המאור טעה במה שהביא ראיה מדברי רבינו האי גאון לפע\"ד ליתא אלא המעיין הטוב בדברי רבינו האי גאון שם ספר מקח וממכר שער ל\"ט יראה דס\"ל כבעל המאור דאל\"כ לאיזה צורך הביא כל הך סוגיא דועוד מותיב רבא מעשה בחסיד אחד כו' אלא לעולם מתני' ר\"ט כו' וגם למה לא הביא שנויא דרבא דשאני מתני' כיון דידע למאן גזליה כו' וגם ל\"ל למימר דהיכא דנשבע בין לר' טרפון בין לר\"ע חייב להחזיר לכל א' וא' אלא משמע דס\"ל דמסקנת הש\"ס דמתני' כר\"ט וע\"כ הוצרך להביא ראיה דאף לר\"ט חייב בנשבע וכן משמע להדיא בבעל הלכות גדולות דף צ' ריש ע\"ד דמסקנת הש\"ס דמתני' כר\"ט וע\"ש ועוד נ\"ל דאפי' לגירסת הספרים דגרסי אלא אמר רבא י\"ל דלא הדר אלא אמאי דקאמ' דר\"ט מיירי דוקא בלא נשבע ומוד' בנשבע מטעמא דכתיב לאשר הוא לו יתננו ביום אשמתו אלא ר\"ט מיירי אפי' בנשבע וכמו שפי' רש\"י ושאני מתני' כיון דידע למאן גזליה ואודי ליה מיפטר והא דמחייב במתני' בנשבע היינו משום דבעי כפרה ולא מיכפר ליה עד דמטי לידי' אבל לא הדר ממאי דקאמר דמתני' אתא כר\"ט ולא כר\"ע ועוד דאפי' אתי מתני' כר\"ט וכר\"ע דלמא הלכה כר\"ט ומ\"ש הרמב\"ן דקי\"ל הלכ' כר\"ע מחבירו נגד ר\"ט אף שכ\"כ ג\"כ הרי\"ף והרא\"ש בכמה דוכתי מ\"מ אינו מוכרח כ\"כ דהא בש\"ס פ' הכותב (כתובות דף פ\"ד) ע\"ב אמרי' לחד אי בעית אימא דס\"ל לרבי יוחנן דר' טרפון רבו הוה והלכה כר\"ע נגד ר\"ע ואף דקאמ' התם בש\"ס דקאמר ר' יוחנן על ריש לקיש מה אעשה שכנגדי חלוק עלי היינו שלא יכול לבטל דבריו אבל מ\"מ מידי ספיקא לא נפקא ומכ\"ש הכא דאיתא להדיא בש\"ס ס\"פ האשה שלום דטעמא דר\"ע הוא משום דקניס כיון דעביד איסורא א\"כ כיון דר\"ע לאו דינא קאמר אלא קנסא דלמא בהא לא קי\"ל הלכה כר\"ע מחבירו ואפשר שזהו כוונת הנ\"י פ' המפקיד שכ' בשם הראב\"ד והר\"ז ז\"ל דכיון דר\"ע לא מחייב אלא משום קנס א\"כ האידנ' דלא דייני דיני קנסות קי\"ל כר\"ט דלכאור' קשה דהא ודאי קנס כזה שייך גם האידנ' אלא י\"ל שכוונתם כמ\"ש וא\"כ נראה נהי דרוב הפוסקים פסקו כר\"ט מ\"מ מצי הגזלן המוחזק לו' קים לי כהבעל המאור ורב האי גאון והלכות גדולות והראב\"ד ז\"ל כן נ\"ל:","\u0003 והם חולקים ביניהם כו' \u0004 כ\"כ הרמב\"ם ור' ירוחם ומשמע דמדינא חולקים ולא אמרי' יהא מונח עד שיבא אליהו דליכא למימר דחולקי' כשיסכימו שניהם דא\"כ מאי קמ\"ל פשיטא ועוד דא\"כ גם בפקדון לעיל סי' ש' וכן במקח לעיל סי' רכ\"ב ס\"ב אמאי לא אשמועינן הרמב\"ם והמחבר דחולקין כשירצו ועוד דהא הרמב\"ם ס\"ל דכל היכא דתנן יהא מונח עד שיבא אליהו היינו שיהא מונח בידו וכ\"כ ר\"י וכמ\"ש בסי' רכ\"ב שם וא\"כ אמאי כתבו כאן נותן מנה א\"ו הכא דינא הוא דנותן מנה וחולקי' ולא אמרי' יהא מונח עד שיבא אליהו דדוק' לעיל סי' ש' וסי' רכ\"ב דתבעי לי' ודאי חד מנייהו רמאי אמרי' הכי משא\"כ הכא כיון שהם עצמם אינם יודעים שנגזלו א\"כ ליכא רמאי לכך חולקים וע' בש\"ס ובאשר\"י ריש פ' שנים אוחזין ודוק:","\u0003 אלא על פיו \u0004 כלו' וגם עכשיו אינם יודעים בברי:","\u0003 אם בא לצאת ידי שמים כו' \u0004 ובפקדון כה\"ג אף לצאת י\"ש פטור כדלעיל סי' ש' סעיף י' בהג\"ה מטעם דהמפקיד עצמו ה\"ל למידק כמ\"ש הרא\"ש פ' המפקיד וכ' בספר מעדני מלך שם הטעם לחלק בין פקדון לגזל הייגו שסובר גברא אלמא הוא דגזליה ולא שכיח דהדר ולכך לא תבע ליה עכ\"ל וקשה לי על דבריו דע\"כ ה\"ה כשלא תבעו מתחלה רק אחר שאומר שגזל לאחד מהם אומר כל אחד אותי גזל נמי דין תבעי ליה יש לו דלא תלי בתבעי ליה תחלה כלום רק כשטוען הנגזל או המפקיד ברי כדמוכח בש\"ס פרק המפקיד ובפוסקים שם וא\"כ בגזל נמי ע\"כ מיירי שגם עכשיו אינו טוען ברי וא\"כ לא שייך לו' שסובר גברא אלמא הוא כו' שהרי הוא רואה שרוצה להחזיר אלא נ\"ל דגזלתי דומיא דאביו של אחד מכם הפקיד אצלי קתני דהיינו גזלתי לאחד מכם ואיני יודע להכי לא קתני אחד מכם הפקיד אצלי מנה משום דכשהפקיד ודאי יודע וה\"ל כתובעו עכשיו ולפ\"ז כשידוע לו שגזלו בפניו וידע מזה ואינו יודע לאיזה מהן גזל ולא תבעי ליה עכשיו מניח גזלה ביניהם ומסתלק ופטור אף לצאת י\"ש ודוק:","\u0003 חייב לשלם לכל אחד מהם מנה \u0004 אחר שישבע כל אחד:","\u0003 נותן לכל אחד מאתים אחר שישבע כל אחד \u0004 וכ\"כ רבי' ירוחם נל\"א ריש ח\"ד והוא פשוט ואם גם הם אינם יודעים יהא מונח בידו עד שיבוא אליהו כ\"כ ר' ירוחם ונ\"ל הא דלא אמרי' בכאן חולקים ביניהם כמו דבסמוך משום דכיון דכל חד תובע במנה א\"כ יש לחוש לרמאי דאמאי ידע ממנה ולא ידע מאידך מנה ולפ\"ז אם כל אחד אומר איני יודע מהגזלה כלל דינא ג\"כ דחולקין כאן כמו בסמוך ודוק:","\u0003 גזל לאחד ואינו יודע אם החזיר כו' \u0004 ע\"ל סימן ע\"ה סעיף י' שם כתבו הטור והמחבר דינים אלו:"]],["גַּזְלָן מְפֻרְסָם \u0005שֶׁעֲסָקָיו בְּכָךְ \u0010y0\u0011 וּתְשׁוּבָתוֹ קָשָׁה\u0006 הַבָּא לַעֲשׂוֹת תְּשׁוּבָה מֵעַצְמוֹ, \u0010y1\u0011 אִם אֵין \u0010y2\u0011 \u0010c0\u0011 הַגְּזֵלָה קַיֶּמֶת אֵין מְקַבְּלִין מִמֶּנּוּ, כְּדֵי שֶׁלֹּא יִמָּנַע מִלַּעֲשׂוֹת תְּשׁוּבָה; \u0010y3\u0011 וְאִם רָצָה לָצֵאת יְדֵי שָׁמַיִם וְהֶחֱזִיר, אֵין מוֹחִין בְּיַד הַנִּגְזָל מִלְּקַבְּלוֹ. \u0005הַגָּה: וְכֵן אִם לֹא בָּא לַעֲשׂוֹת תְּשׁוּבָה מֵעַצְמוֹ, רַק שֶׁהַנִּגְזָל צָרִיךְ לְתָבְעוֹ, מְחַיְּבִים אוֹתוֹ לְהַחֲזִיר (טוּר ס\"א)\u0006.\nהָרוֹעִים וְהַגַּבָּאִים וְהַמּוֹכְסִים, תְּשׁוּבָתָן קָשָׁה מִפְּנֵי שֶׁגָּזְלוּ אֶת הָרַבִּים וְאֵין יוֹדְעִים לְמִי יַחְזְרוּ, לְפִיכָךְ יַעֲשׂוּ בּוֹ \u0010y4\u0011 צָרְכֵי רַבִּים, כְּגוֹן בּוֹרוֹת שִׁיחִין וּמְעָרוֹת. \u0005הַגָּה: \u0010y5\u0011 גַּזְלָן שֶׁהֶחֱזִיר, אִם צָרִיךְ דַּעַת בְּעָלִים, דִּינוֹ כְּמוֹ בְּגַנָּב (טוּר ס\"ג)\u0006. וְעַיֵּן לְעֵיל סִימָן שנ\"ה:\nהָיָה כְּלִי בְּיַד בְּנוֹ שֶׁל בַּעַל הַבַּיִת אוֹ בְּיַד עַבְדּוֹ, \u0010y6\u0011 וּלְקָחוֹ אֶחָד מֵהֶם וְנִשְׁתַּמֵּשׁ בּוֹ, הֲרֵי זֶה שׁוֹאֵל שֶׁלֹּא מִדַּעַת, וְנַעֲשָׂה בִּרְשׁוּתוֹ, וְנִתְחַיֵב בָּאֳנָסִין עַד שֶׁיַּחֲזִירֶנּוּ לַבְּעָלִים. \u0010y7\u0011 לְפִיכָךְ, אִם הֶחֱזִירוֹ לַקָּטָן שֶׁהָיָה בְיָדוֹ, וְאָבַד מִמֶּנּוּ אוֹ נִשְׁבַּר, חַיָּב לְשַׁלֵּם.\nהַגּוֹזֵל אֶת חֲבֵרוֹ בַּיִּשּׁוּב, וּבָא לְהַחֲזִיר לוֹ בַּמִּדְבָּר, לֹא יָצָא; \u0010y8\u0011 וְאִם יִרְצֶה הַנִּגְזָל לֹא יִקָּחֶנּוּ עַד שֶׁיַּגִּיעַ לְיִשּׁוּב; אֲבָל אִם מַחֲזִירוֹ בַּיִּשּׁוּב, אֲפִלּוּ אֵינוֹ בְּאוֹתוֹ מָקוֹם שֶׁגְּזָלוֹ, יָצָא:",["\u0003ותשובתו קשה \u0004 דגזלן כי האי כל אשר לו לא יספיק ל' כשיחזיר לכל א' מה שגזלו ואף אם הגזלן הוא עשיר מ\"מ כיון דיצטרך לבזבז ולהוציא מידי ממון הרבה לא יחזיר בתשובה גם אינו יודע למי ישיב כיון שעסקיו בכך וגזל הרבה:","\u0003אם אין הגזילה קיימת \u0004 אפי' אם היא קיימת אם בנה עליה בנין אין צריך להחזיר וכדברי הלל דאמר אם גנב קורה וקבעה בבנין א\"צ לקעקע ולעקור כל הבנין בשביל חזרת הקורה אלא משלם אות' לבעליו מיהו דוקא בכה\"ג שגנב דבר המטלטל אבל אם הסיג גבול רעהו בקרקע ובנה כותל בשל חבירו אפי' בנה עליה בנינים גדולים חייב לסתור הכל שלא עשו תקנת השבים בקרקע כ\"כ רי\"ו בשם הגאונים והביאו מור\"ם בד\"מ בסי' זה ובהגה' מור\"ם ר\"ס ש\"ס והם כתבוהו לענין גזלן שאינו מפורסם לענין חזרה ונראה דה\"ה וכ\"ש הוא לענין גזלן מפורסם:","\u0003אין מקבלין ממנו \u0004 פי' חז\"ל תקנו שלא יקבלו ממנו כדי לפתוח לו פתח לדרכי התשובה והמקבל ממנו אין רוח חכמים נוחה הימנו כן היא לשון הגמרא והטור ופי' אין רוח חכמה וחסידות בקרבו:","\u0003ואם רצה לצי\"ש כו' \u0004 פי' דאומר הגזלן אע\"פ שאינך רוצה לקבלו ממני ומחלת לי אני רוצה להחזיר לך כדי לצי\"ש אזי אין מוחין כו' ודומה לזה איתא בגמרא וכתבו הטור והמחבר בסימן ע\"ז גבי שמיטה דצריך המלוה לומר ללוה הבא לפרעו אחר שביעית משמט אני ואם אמר לו הלוה אעפ\"כ יכול לקבלו:","\u0003צרכי רבים \u0004 דאז גם הנגזל יהנה מן הדברים הנעשי' מדמי הגזילה:","\u0003גזלן שהחזיר אם צריך דעת בעלים דינו כמו בגנב כו' \u0004 שם בסי' שנ\"ה נתבאר דאם לא ידעו הבעלים מגניבה א\"צ ג\"כ לידע מהחזר' ודין זה אין שייך בגזלן שסתם גזיל' הוא שגוזל מיד הנגזל ונמצא דהנגזל ידע מהגזיל' ולא הי' למור\"ם לכתוב אלא גזלן שהחזיר צריך להחזיר' מדעת בעלים וע\"ד שנתבאר בסי' שנ\"ה בגנב וכ\"כ בטור ס\"ג ע\"ש:","\u0003ולקטו אחד מהם ונשתמש כו' \u0004 מדלא כתב חטף מיד א' כל' הטור וגם לא כתב שלקחו מיד בנו הקטן משמע דס\"ל דאפי' לקחו מיד בנו הגדול של בע\"ה ברשותו דבנו אפ\"ה מיקרי שואל שלא מדעת ונתחייב באונסין כיון שאינו של בנו אלא של אביו:","\u0003לפיכך אם החזירו לקטן שהיה בידו כו' \u0004 כן הוא ל' הרמב\"ם שם בספ\"ג דגזילה ור\"ל אפי' היה כבר בידו דקטן מדעת אביו והוא לקחו מידו ונשתמש בו והחזירו לידו וכן איתא בגמרא בשלח אחד ביד בנו קטן צלוחית לקנות שמן כו' וכתבו הטור והמחבר לעיל בסי' קפ\"א ע\"ש. ושם ברמב\"ם כתב עוד דגם בהחזירו לעבד דינו הכי שחייב באחריותו וכתב המ\"מ שם ע\"ז ז\"ל דעבד כקטן כל זמן שלא החזירו ליד בעלים וזה ברור עכ\"ל וכ\"כ הטור והמחבר בסי' רצ\"א סכ\"א דעבד אפי' גדול דינו כקטן ודוקא בהחזירו לקטן הוא דחייב באונסין הא אם לקחו מיד בנו הגדול והחזירו לידו פטור מאונסין כמ\"ש מור\"ם לעיל ר\"ס רצ\"ב בהג\"ה וז\"ל אם החזירו למקום שנטלו משם חזר להיות דינו כשומר הואיל ולא הוה מתחל' רק שואל בעלמא כו' ע\"ש והוא מהמרדכי דפ' הגוזל ושם ג\"כ אשואל שלא מדעת קאי:","\u0003ואם ירצה הנגזל כו' \u0004 כלומר ברצון הנגזל תליא ול\"ת אף אם ירצה הנגזל לקחתו אינו יוצא הגזלן עד שיחזירנ' לו במקום שנגזל וכ\"כ ב\"י ועמ\"ש עוד מזה בפריש':"],["\u0003 אין מקבלין ממנו כו' \u0004 וכתב בספר חסידים סימן תתרפ\"ז דוקא כשהנגזל אין חייב לאחרים אבל אם הנגזל חייב לאחרים ואין לו מה לפרוע יש לקבל כדי שיפרע לבעלים חובות שלו ע\"כ:"]],["הַגּוֹזֵל אֶת \u0010y0\u0011 חֲבֵרוֹ, אַף עַל פִּי שֶׁכָּפַר בּוֹ, הוֹאִיל וְלֹא נִשְׁבָּע, \u0010c0\u0011 אִם חָזַר וְהוֹדָה \u0010y1\u0011 \u0010c1\u0011 אֵינוֹ חַיָּב לִרְדֹּף אַחַר הַבְּעָלִים לְהַחֲזִיר לָהֶם, אֶלָּא יְהֵא בְּיָדוֹ \u0010c2\u0011 עַד שֶׁיָּבוֹאוּ, \u0010y2\u0011 \u0010c3\u0011 \u0005וְיוֹדִיעַ אוֹתָם (טוּר ס\"א)\u0006 וְיִטְּלוּ אֶת שֶׁלָּהֶם. \u0010y3\u0011 \u0010c4\u0011 אֲבָל אִם נִשְׁבַּע עַל שְׁוֵה פְרוּטָה וָמַעְלָה, חַיָּב לִרְדֹּף אַחַר הַבְּעָלִים עַד שֶׁיַּחֲזִיר לָהֶם, אֲפִלּוּ הֵם בְּאִיֵּי הַיָּם, \u0010c5\u0011 מִפְּנֵי שֶׁכְּבָר נִתְיָאֲשׁוּ מֵאַחַר שֶׁנִּשְׁבַּע, וְאֵינָם בָּאִים עוֹד לְתוֹבְעוֹ.\nאֲפִלּוּ הֶחֱזִיר הַגְּזֵלָה כֻּלָּהּ, חוּץ מִשְּׁוֵה פְרוּטָה, חַיָּב הַגַּזְלָן לְהוֹלִיכָהּ אַחַר הַנִּגְזָל. \u0010y4\u0011 וְלֹא יִתֵּן לֹא לִבְנוֹ שֶׁל נִגְזָל וְלֹא לִשְׁלוּחוֹ, אֶלָּא אִם כֵּן עָשָׂה הַנִּגְזָל \u0010c6\u0011 הַשָּׁלִיחַ בְּעֵדִים. וְכֵן \u0010y5\u0011 אִם עָשׂוּ בֵּית דִּין שָׁלִיחַ בְּעֵדִים, וְנָתַן לוֹ, יָצָא; \u0010c7\u0011 וְאֵין צָרִיךְ לוֹמַר אִם נָתַן לְבֵית דִּין, שֶׁיָּצָא.\nהֶחֱזִיר לוֹ כָּל הַגְּזֵלָה, אוֹ שֶׁמָּחַל לוֹ עָלֶיהָ, חוּץ מִפָּחוֹת שְׁוֵה פְרוּטָה, אֵינוֹ צָרִיךְ לְהוֹלִיךְ אַחֲרָיו \u0010y6\u0011 אֶלָּא יָבֹא הַנִּגְזָל וְיִטֹּל הַשְּׁאָר. וְאַף עַל פִּי שֶׁהַגְּזֵלָה עַצְמָהּ \u0010y7\u0011 קַיֶּמֶת, אֵין חוֹשְׁשִׁין שֶׁמָּא תִּתְיַקֵּר וְנִמְצָא הַנִּשְׁאַר שָׁוֶה פְּרוּטָה.\nמֵת הַנִּגְזָל, כְּשֶׁבָּא הַגַּזְלָן לַעֲשׂוֹת תְּשׁוּבָה יַחֲזִיר לְיוֹרְשָׁיו, אִם הַגְּזֵלָה בְּעַיִן. וְאִם אֵינָהּ בְּעַיִן \u0005(אוֹ שֶׁנִּשְׁתַּנֵּית)\u0006, יַחֲזִיר לָהֶם דָּמֶיהָ כְּשֵׁם שֶׁהָיָה מַחֲזִיר לְמוֹרִישָׁם.\n\u0005(טוּר הֵבִיאוֹ \u0010y8\u0011 בס\"ה)\u0006 הַגּוֹזֵל אֶת אָבִיו וְנִשְׁבַּע לוֹ, מֵת הָאָב, אִם אֵין הַגְּזֵלָה קַיֶּמֶת אוֹ נִשְׁתַּנֵּית \u0010y9\u0011 עוֹשֶׂה חֶשְׁבּוֹן עִם אֶחָיו \u0010y10\u0011 עַל הַקֶּרֶן; וְאִם הַגְּזֵלָה קַיֶּמֶת, חַיָּב לְהוֹצִיא הַגְּזֵלָה עַצְמָהּ מִתַּחַת יָדוֹ, \u0010y11\u0011 \u0010c8\u0011 \u0010c9\u0011 לְפִיכָךְ, נוֹתֵן הַגְּזֵלָה לְאֶחָיו וְעוֹשֶׂה עִמָּהֶם חֶשְׁבּוֹן. \u0010y12\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאֵינוֹ נוֹטֵל כְּלוּם נֶגֶד \u0010y13\u0011 הַגְּזֵלָה. וְאִם הוּא עָנִי וְלֹא יָכוֹל לְוַתֵּר חֶלְקוֹ, לֹוֶה מֵאֲחֵרִים וְהֵם בָּאִים נֻפְרָעִים מֵחֶלְקוֹ (טוּר ס\"ה)\u0006. וְאִם אֵין לוֹ אַחִים, שֶׁנִּמְצָא זֶה הַגַּזְלָן לְבַדּוֹ הוּא הַיּוֹרֵשׁ, מוֹצִיא הַגְּזֵלָה מִתַּחַת יָדוֹ לְבָנָיו. וְאִם אֵין בָּנִים לְזֶה הַבֵּן הַגַּזְלָן, נוֹתְנָם לְבַעַל חוֹבוֹ בְּהַלְוָאָתוֹ \u0010y14\u0011 אוֹ לִצְדָקָה, הוֹאִיל וְיָצְאָה גְּזֵלָה עַצְמָהּ מִתַּחַת יָדוֹ, נִפְטַר אַף עַל פִּי שֶׁנְּתָנָהּ מַתָּנָה אוֹ פְּרָעָהּ בְּחוֹבוֹ, וְהוּא שֶׁיּוֹדִיעֵם וְיֹאמַר: זֶה גֶּזֶל אַבָּא. \u0010y15\u0011 \u0005וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּאִם אֵין לַגַּזְלָן (בָּנִים)\u0006 [אַחִים] נוֹתֵן לַאֲחֵי אָבִיו \u0005(טוּר)\u0006.\nהַגּוֹזֵל אֶת הַגֵּר וְנִשְׁבַּע לוֹ, וּמֵת הַגֵּר בְּלֹא יוֹרְשִׁים, אֲפִלּוּ הוֹדָה לַגֵּר וּזְקָפוֹ עָלָיו בְּמִלְוָה, \u0010y16\u0011 אַף עַל פִּי שֶׁזָּכָה \u0010y17\u0011 בַּגְּזֵלָה, חַיָּב לְהוֹצִיאָהּ מִתַּחַת יָדוֹ:",["\u0003אע\"פ שכפר בו כו' \u0004 פי' ול\"ת כיון שכפר בו נתייאש הנגזל ולא יתבענו עוד וכדמסיק המחבר כשכבר נשבע:","\u0003אינו חייב לרדוף כו' \u0004 ג\"ז מפני תקנת השבים הוא ועפ\"ר:","\u0003ויודיע אותם \u0004 ז\"ל הטור אלא יודיענו לומר לי כך וכך גזלתיך בא וקחנו עכ\"ל דלכאורה משמע מל' הטור דצריך לשלוח להודיעו במקום שהוא שם שכך וכך גזלתיו אלא שאין צריך לטפל בשליחות הגזילה שם ולקבל עליו אחריות הדרך אבל בל' הרמב\"ם מוכח דלא סבירא ליה הכי אלא שיהא בידו עד שיבואו מעצמן ומור\"ם שהוסיף לכתוב ויודיע אותם כוונתו שבבואם לעיר הגזלן אזי הגזלן מודיע אותם שכך וכך גזלם ושיטלם מידו כי הוא יתן להן וק\"ל:","\u0003אבל אם נשבע כו' \u0004 דכתיב לאשר הוא לו יתננו ובנשבע לשקר מיירי כדכתיב שם בפרש' ביום אשמתו דהיינו שמביא קרבן אשם על שבועתו מיהו אי לאו מפני תקנת השבים מן הראוי היה להתחייב הגזלן להביא אחריו למקום שהוא שם אפי' לא נשבע מאחר שמצינו שקפיד עליו קרא:","\u0003ולא יתן לא לבנו כו' \u0004 בפרישה כתבתי דנ\"ל דגם ברישא בלא נשבע אסור לתנו לבנו כו' אלא אורחא דמילתא נקט דכל שלא נשבע דא\"צ לשלח הגזילה למקום שהנגזל שם מסתמא מחזיקו בידו עד שיבא וק\"ל:","\u0003אם עשו הב\"ד שליח בעדים כו' \u0004 ג\"ז מפני תקנת השבים הקילו עליו שלא יצטרך הרבה בהוצאת הדרך כן פירש\"י ויהי' ביד שליח ב\"ד עד שיבא הנגזל ויקחנו מידו והגזלן פטור מהאחריות מיד שמסרו לשליח ב\"ד ועפ\"ר:","\u0003אלא יבא הנגזל ויטול השאר \u0004 כן הוא ל' הרמב\"ם ור\"ל אף שהוא פחות מש\"פ בתורת השבה הוא כיון דמתחל' גזל יותר מש\"פ ולא החזיר כולו אלא שאינו מחויב להוציא עליה הוצאה בהשבתה ועוד דגם פחות מש\"פ איסור גזל יש בו כמ\"ש הטור והמחבר בר\"ס שנ\"ט אלא שאין הב\"ד נזקקין לפחות מש\"פ להוציאו מידו וכן עיקר ועד\"ר:","\u0003אין חוששין שמא תתייקר. \u0004 ואם נתייקר כ' הטור בשם ר\"י דא\"צ להחזירו כיון שפעם א' לא היתה ש\"פ ושהרמ\"ה כ' שצריך להחזיר לו:","\u0003הגוזל את אביו ונשבע לו \u0004 הב\"י נסתפק אם דוקא נשבע לו קאמר כו' ובד\"מ הכריע דדוקא נשבע לו קאמר וכתבתיהו בדרישה ע\"ש:","\u0003עושה חשבון עם אחיו \u0004 פי' כיון שאין הגזילה עוד בעין בידו אין עליו אלא חוב לשלם לאחיו חלקם ודי לו בזה שעושה חשבון עמהם ואומר להם כך וכך הוא בידי ממון אבינו קחו חלקכם מידי או טלו כל א' מכם כסך זה מהירושה ממקום אחר יותר ממנו והמותר נחלק בשוה משא\"כ כשהגזילה עדיין בעין בידו דאז צריך להוציא' בעין מידו לקיים תורת השב' וחוזר ונוטל כדי חלקו ממקום אחר וזהו שסיים וכ' ז\"ל ועושה עמהן חשבון:","\u0003ומ\"ש על הקרן במשנה וברמב\"ם פ\"ח כ' על הקרן ועל החומש אלא מפני שאין חומש נוהג בזמן הזה מ\"ה לא הזכירו הטור וגם המחבר החומש ועפ\"ר:\u0004","\u0003לפיכך נותן הגזילה לאחיו כו' עד ואם אין לו אחים כו' \u0004 ז\"ל המשנה הגוזל את אביו ונשבע לו ומת ה\"ז משלם הקרן והחומש לבניו ולאחיו ואם אינו רוצה או שאין לו לוה וב\"ח באין ונפרעין ובגמ' אמר ר' יוסי ואפי' לארנקי של צדקה ע\"כ והנה הרמב\"ם והמחבר פירשו מ\"ש שיחזרו לבניו ולאחיו ר\"ל דהגזלן וס\"ל דהמשנה ל\"ד קתני מה שהקדים בניו לאחיו דאחיו דגזלן שהם יורשי הנגזל הן קודמין להשיב להן הגזילה ממה שישיבו הגזלן לבניו והתוס' ג\"כ פירשו דבניו ואחיו אשל גזלן קאי אבל ס\"ל דהמשנה דוקא קתני (פי' המשנה דקתני שמשלם לבניו ולאחיו מחלק הגזלן קאמר) דלענין חלקו של גזלן מהגזילה בניו דעצמו קרובים לשלו יותר מאביו דבניו מכח אבוה דאבוהן קאתי לירש חלק הגזלן מהגזילה ורש\"י והרא\"ש והטור ס\"ל דבניו ואחיו דמתני' פי' בניו ואחיו של הנגזל וכאלו אמר שהגזלן ישיב לאחיו (שהן בניו של הנגזל) ולאחיו של הנגזל שהן אחי אבי הגזלן והן הי\"א שכ' מור\"ם בסמוך בס\"ה ועמ\"ש שם:","\u0003וי\"א דאינו נוטל כלום \u0004 פי' הוא בעצמו לא יטול מהן אלא המלוה יטול אם הגזלן עני כדמסיק ועפ\"ר ודרישה שם כתבתי טעם פלוגתתן:","\u0003ואם הוא עני ואין לו כו' \u0004 כן פי' הטור ל' המשנה הנ\"ל דקתני ואם אין לו כו' פי' דאין לו להגזלן לוותר אז יבא המלוה ונפרע מהאחין מדמי הגזילה כדי חלקו שקיבל ומ\"ש לוה ר\"ל לוה כדי שיעור שעלה על חלקו מדמי הגזילה ומחזיק דמי הלואה בידו והמלוה חוזר ונוטל מיד האחים כדי חלקו ושאר ב' חלקים ישארו ביד אחיו שהרי הוא חלקן וע\"ד כן נתן הגזלן לידם אבל הרמב\"ם והמחבר פי' מ\"ש ואם אין לו כו' ר\"ל שאין לו אחים ולא בנים אזי לוה מאחרים כדי כל הגזילה ומחזיק המעות לעצמו והב\"ח בא ויפרע מידו ומוצא מידו כל הגזילה ויצא ידי השבה בזה הואיל והגזילה עכ\"פ יצאה מתחת ידו וכ\"ש אם כבר בחיי אביו נתחייב זה הגזלן ולאחרים שיוצא בזה במה שפורע לב\"ח בהגזילה כיון שאין לו בנים ולא אחים ונלמד מדבריו דס\"ל דא\"צ להשיב הגזילה בעינה לשאר יורשיו זולת אחיו ובניו משא\"כ לפי' הטור דלעולם צריך להשיב הגזילה או כדי דמי הגזילה ליורשי אביו הקרוב קרוב קודם אלא דמחולקים המה בזה דכשמחזיר הגזילה לאחי אביו וכ\"ש להרחוקים יותר אז לוה הגזלן מהמלוה כדי כל הגזילה וחוזר המלוה ונפרע מאותן קרובים שהשיב להן הגזילה כיון שהוא לבדו היורש לאביו ולא אותן קרובין משא\"כ כשיש לגזלן אחים שהן יורשים דאביו כמוהו דאינו לוה ונפרע אלא כדי חלקו וכנ\"ל ועפר\"ד שם ביארתי עוד טעם פלוגתתן באר היטב וממ\"ש נתבאר שהתו' לא אזלי לדינא בשטת הרמב\"ם אלא בשטת רש\"י והרא\"ש אלא שבפי' יחזירנו לבניו או לאחיו הוא דפי' ע\"ד פי' הרמב\"ם אבל לא מטעמו ודינו משום דס\"ל דבניו קרובים יותר ליטול כפי חלק המגיע להגזלן מהגזילה יותר מאחיו וכנ\"ל וכמ\"ש הכל בדרישה בטוב טעם ע\"ש ולא כהב\"י וכ\"מ וד\"מ שכתבו דהתוס' ס\"ל כהרמב\"ם ע\"ש שוב אמרו לי שבבדק הבית כתוב ג\"כ שהתו' לא ס\"ל כהרמב\"ם ע\"ש:","\u0003או לצדקה \u0004 גם לשטת הי\"א שהן רש\"י והרא\"ש ס\"ל דכשמחזיר לצדקה כדי לצאת ידי השבה והיינו כשאין יורש בנמצא ידוע להנגזל כ\"א במרחקים (וכמ\"ש הטור ועפ\"ר) דאזי יכול ללות מאחר קודם שיתננו לצדקה ויחזור המלוה לגבות מהצדקה ע\"ד שנתבאר לעיל ס\"ס קי\"ז וכל זה ביררתי בדרישה ופרישה ע\"ש ודוק:","\u0003ויש חולקין \u0004 וס\"ל דאם אין לגזלן בנים נותן לאחי אביו כן הוא בס\"י ונוסח זה נראה דאינו נכון אלא ה\"ג ואם אין לגזלן אחים נותן לאחי אביו והוא שטת רש\"י ואשר\"י וטור וכמ\"ש לעיל בפי' המשנה דקתני בניו ואחיו דבניו ר\"ל בניו של נגזל שהן אחיו של גזלן ואחיו ר\"ל אחי אביו של גזלן שהן אחיו של נגזל וא\"ל שמור\"ם כ\"כ לפי' התו' הנ\"ל דס\"ל דבניו של גזלן הן קודמין דא\"כ הל\"ל ואם אין לגזלן בנים יתנהו לאחיו של גזלן ולמה כ' דיתנהו לאחי אביו (אחיו) אלא מחוורתא כדכתיבנא ודוק:","\u0003אע\"פ שזכה בגזילה \u0004 דכיון דזקפו עמו במלוה נעשו נכסי הגר ונכסיהן הפקר לאחר מיתה וכל הקודם להחזיק בהן זכה:","\u0003חייב להוציא' מתחת ידו. \u0004 פי' ליתנו לצדקה שבזמן הבית היה צריך ליתנו לכהנים שהן זכו בהן משלחן גבוה שנ' (בפ' נשא) האשם המושב לה' לכהן ובזמן הזה שאין קרבן אשם שעוסקים בו הכהנים ואין שייך שלחן גבוה מ\"ה נותנו לארנקי של צדקה וחולקים ממנו לכל עניים בשוה:"],["\u0003 אם חזר והודה \u0004 אע\"פ שבא לצאת ידי שמים אינו חייב לרדוף אחריו כן איתא להדיא בש\"ס פ' הגוזל (בבא קמא דף ק\"ד) כ\"ש כשלא הודה רק שבאו עדים שגזל לו אינו חייב לרדוף אחריו רק שיודיענו:","\u0003 אינו חייב לרדוף כו' \u0004 כ' הסמ\"ע דהיינו מפני תקנת השבים ולא נהירא דבש\"ס משמע דמדינא אינו חייב לרדוף אחריו אלא דבנשבע כיון דצריך להביא קרבן להתכפר לא סגי עד דמטא לידי' וה\"ה האידנא אע\"ג דאין קרבן מ\"מ אינו יוצא ידי כפרתו עד דמטא לידי' וכ\"כ הרא\"ש:","\u0003 עד שיבואו ויודיע אותם \u0004 משמע מדברי הטור והרא\"ש דצריך לשלוח להודיעו במקום שהוא שם וכ\"כ הב\"ח לדעת הטור וגם הסמ\"ע כתב שלכאורה משמע כן מל' הטור רק שכתב דמל' הרמב\"ם והמחבר משמע דלא ס\"ל הכי אלא שיהא בידו עד שיבואו מעצמן ומור\"ם שהוסיף לכתוב ויודיע אותם כונתו שבבואם לעיר הגזלן אזי הגזלן מודיע אותם שכך וכך גזלם ושיטלם מידו כי הוא יתן להם עכ\"ל וכ\"כ בב\"ח לדעת הרמב\"ם וכן נראה מדברי מהרש\"ל ותוספות י\"ט שהבאתי לקמן לדעת הרמב\"ם נלפע\"ד דגם הרמב\"ם והמחבר מודים דצריך לשלוח להודיע לו ולא באו אלא לו' דאינו חייב לרדוף אחריו וזה שהגיה הרב ויודיע אותם וכן משמע בע\"ש ע\"ש וכן משמע לפע\"ד בש\"ס ריש דף ק\"ד גבי האי דקאמר כיון דידע למאן גזלה ואודי ליה כמאן דאמר ליה יהיו לי בידך דמי כו' משמע דוקא דאודי ליה שהודיעו ואז כמאן דא\"ל יהיו לי בידך דמי דאל\"כ חייב לצאת ידי שמים לכ\"ע ולפ\"ז צריך לעשות כל מה דאפשר שיודיע לו דכל זמן שאינו מודיע לו אינו יוצא ידי שמים לרבי טרפון ולר\"ע אף מדינא חייב ודוק:","\u0003 ויודיע אותם \u0004 כתב הב\"ח דהטור מפרש הא דמסיק רבא בש\"ס (ריש דף ק\"ד) כיון דידע למאן גזלי' ואודי ליה כו' הלכך נשבע כו' דדוקא בהודה לו קודם שהלך למדי אבל בכפר בו ולא הודה בפניו אלא לאחר שהלך למדי הודה בפני ב\"ד אע\"ג דאינו חייב להוליכם אחריו למדי מ\"מ צריך שיודיענו לומר כך וכך גזלתיך כו' ע\"כ ולחנם דחק די\"ל דהטור מפרש בלא הודה לו בפניו אלא דס\"ל דנהי דא\"צ להוליך אחריו למדי מ\"מ צריך שיודה לו ויודיענו וכמש\"ל. גם מה שנראה מדבריו דאף בהוד' לו בפניו כשנשבע צריך להלוך אחריו למדי ליתא ואישתמיטתי' דברי התוספות דף ק\"ד ע\"א שכתבו וז\"ל ומיהו אין נראה דמיירי הכא כשהודה בפניו דא\"כ אפי' נשבע נמי א\"צ להוליך אחריו למדי ויכול להביא כפרה דכיון דהוד' לו בפניו והניחו בידו והלך הרי הוא כהפקידו בידו ואמאי יהא צריך להוליכו אחריו אלא ודאי מיירי כשהודה שלא בפניו אלא בפני עדים עכ\"ל עמ\"ש לקמן:","\u0003 אבל אם נשבע כו' \u0004 כת' הסמ\"ע ס\"ק ד' דכתיב לאשר הוא לו יתננו כו' ובנשבע לשקר מיירי כו' וכ\"כ בע\"ש וליתא דבש\"ס מסיק טעמא דנשבע כיון דבעי כפרה לא סגי עד דמטא לידיה ואולי מפרשים דש\"ס מפרש טעמא דקרא אבל לא היו צריכים לזה ודוק:","\u0003 מפני שכבר נתייאשו מאחר שנשבע ואינם באים עוד לתובעו. \u0004 הוא ל' הרמב\"ם וכ\"כ הסמ\"ג דף קל\"א ע\"ד וכ' התוס' י\"ט דלפ\"ז באינו נשבע אפי' להודיעו א\"צ משמע דסובר דלהרמב\"ם בנשבע סגי כשיודיענו וכ\"כ מהרש\"ל פ' הגוזל סי' ל\"ה לדעת הרמב\"ם ולא נ\"ל דהא כ' חייב לרדוף אחריו כו' אלא נ\"ל שר\"ל דאף שמודיעו אינו בא זה לתובעו שחושב מאחר שכבר נשבע ונתייאשתי לא יחזיר לי אע\"פ שמודיע לי. מיהו תימה למה המציא טעם חדש מלבו דהא בש\"ס משמע להדיא דטעמא הוא כיון דנשבע ובעי כפרה לא סגי עד דמטא לידיה וכ\"כ הרא\"ש ומהרש\"ל שם ולפ\"ז אפי' יודע הגזלן בבירור שלא נתייאש צריך להוליך אחריו ולא סגי כשמודיע לו ודברי הרמב\"ם והסמ\"ג והמחבר צ\"ע:","וכותב מהרש\"ל שם דאפי' הודיעו לו וזהו שלח לו יהיו לי בידך אפ\"ה כיון דנשבע לא סגי עד דעביד השבה מעליא ע\"כ. וכן משמע בש\"ס גבי הא דקאמר התם הלכך נשבע אע\"ג דקאמר ליה יהיו לי בידך כיון דבעי כפרה לא סגי עד דמטא לידיה. מיהו היינו דקאמר ליה הכי ע\"י שלוחו אבל בפניו לא דכיון שהניחו בידו והלך לו הרי הוא כהפקידו בידו וכמ\"ש לעיל בשם התוס':","\u0003 השליח בעדים \u0004 כדלעיל סי' קכ\"א ס\"ב:","\u0003 וא\"צ לומר אם נתן לב\"ד שיצא \u0004 והיינו דוקא כשנותן לב\"ד שישלחוהו לידו מתי שירצו ולא שהשליח או הב\"ד ישמרו בידם עד שיבוא דוקא בעצמו ובזה ניחא הא דכתבו התוס' דף ק\"ד ע\"א דבנתן ביד ב\"ד מהני וכ\"כ מהרש\"ל שם סי' ל\"ה לדעת התוס' ובדף ק\"ג ע\"א הקשו על פירש\"י אלא ודאי לא הקשו אלא על מה דמשמע מפירש\"י דהשליח ב\"ד שומר' בידו עד שיבוא הנגזל. ובזה מיושב מה שהקשה מהרש\"א בדברי התוס' דף ק\"ד בד\"ה אמר כו' וע\"ש ודוק ועיין בסמ\"ע ס\"ק ו':","\u0003 לפיכך נותן הגזילה \u0004 ע' בסמ\"ע ס\"ק י\"ב עד ולא כהב\"י כו' ולא ידעתי מי הגיד לו זה דגם בב\"י אינו מפרש דברי התוספות כהרמב\"ם אלא בפי' לבניו או לאחיו אבל במה שהרמב\"ם מפרש ואם אינו רוצה בו אין לו כו' אין לו חבר להתוס' עמו וכמבואר בתוס' שכתבו להדיא לוה ואח\"כ נותן לבניו כו' וזהו דלא כהרמב\"ם ואין לזה גילוי דעת בב\"י וכ\"מ גם מ\"ש לו שבב\"ה כ' שתוס' לא ס\"ל כהרמב\"ם כו' עיינתי שם ולא כתב מזה כלום באשר שפשוט הוא רק ששם כתב שקושיות הטור אינה קושיא על הרמב\"ם וכ\"כ בכ\"מ בפי' לבניו או לאחיו שלא כסדר הוא דגם התוס' מפרשים כרמב\"ם ושקר אמרו לו וברור ודוק ואפשר דכוונת הסמ\"ע בזה שלא כב\"י שמשוה פי' רמב\"ם ותוס' אהדדי ואינו נכון:"]],["\u0005(ע\"ל סִימָן שפ\"א ס\"ג)\u0006 \u0010c0\u0011 הַמַּצִּיל \u0010y0\u0011 מִיַּד לִסְטִים יִשְׂרָאֵל, הֲרֵי אֵלּוּ שֶׁלּוֹ, מִפְּנֵי שֶׁסְתַם הַדָּבָר שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים. וְאִם יָדַע שֶׁלֹּא נִתְיָאֲשׁוּ, חַיָּב לְהַחֲזִיר. \u0010y1\u0011 אֲבָל הַמַּצִּיל מִיַּד לִסְטִים גּוֹי אוֹ מוֹכֵס \u0010y2\u0011 גּוֹי, חַיָּב לְהַחֲזִיר, שֶׁסְתַם הַדָּבָר שֶׁלֹּא נִתְיָאֲשׁוּ הַבְּעָלִים; וְאִם נִתְיָאֲשׁוּ, הֲרֵי אֵלּוּ שֶׁלּוֹ. וּמִפְּנֵי מָה אָמְרוּ: סְתָם לִסְטִים יִשְׂרָאֵל נִתְיָאֲשׁוּ הַבְּעָלִים וּסְתָם גּוֹי לֹא נִתְיָאֲשׁוּ, מִפְּנֵי שֶׁהַבְּעָלִים יוֹדְעִים שֶׁגּוֹיִם מַחֲזִירִין מִיַּד הַגַּזְלָן, אַף עַל פִּי שֶׁאֵין שָׁם עֵדִים שֶׁגָּזַל אֶלָּא בִּרְאָיוֹת רְעוּעוֹת וּבְאֹמֶד הַדַּעַת. \u0005הַגָּה: \u0010y3\u0011 \u0010c1\u0011 וּסְתַם גְּנֵבָה הָוֵי יֵאוּשׁ אֲפִלּוּ בְּגוֹי, וְאִם כֵּן הַקּוֹנֶה מִן הַגַּנָּב לֹא הָיָה צָרִיךְ לְהַחֲזִיר הַגְּנֵבָה אֶלָּא אִם כֵּן יָדְעֵינָן דְּלָא נִתְיָאֵשׁ, דְּהָא קְנָאָהּ בְּיֵאוּשׁ וְשִׁנּוּי רְשׁוּת, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שנ\"ג. מִיהוּ, נָהֲגוּ לְהַחֲזִיר כָּל גְּנֵבָה (ת\"ה סִימָן ש\"ט)\u0006, וְאֵין לְשַׁנּוֹת מִן הַמִּנְהָג \u0005(טוּר)\u0006, וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שנ\"ו. וְאֵין חִלּוּק בְּזֶה בֵּין גַּנָּב לְגַזְלָן, דִּבְכָל עִנְיָן מַחֲזִיר דָּמָיו וְנוֹטֵל אֶת שֶׁלּוֹ, כֵּן נִרְאֶה לִי. \u0010y4\u0011 וְעַיֵּן לְעֵיל סִימָן רל\"ו הַקּוֹנֶה קַרְקַע גְּזוּלָה:",["\u0003מיד לסטים ישראל הרי אלו שלו כו' עד שהעכו\"ם מחזירין כו' \u0004 פי' דייני עכו\"ם מחזירין בדיניהן לפי אומד הדעת בלא עדים וז\"ל הגמ' פ' הגוזל בתרא עכו\"ם דייני בגייאות אבל דייני ישראל מימר אמרי מ\"ה מייאש ופרש\"י בגייאות בגיאות ובזרוע מימר אמר צא תן לו ואין חובטין לו במקלות ל\"א דאמרי' לנגזל מי יימר כדקאמרת הבא עדים דגנבי מינך עכ\"ל והמחבר כתב כלשנא בתרא שדייני העכו\"ם מחזירין מיד הגזלן אף בלא עדים וכו' וצ\"ל מדחילקו הטור והמחבר גם הגמ' בין לסטים עכו\"ם או ליסטים ישראל ולא חילקו בין דיין עכו\"ם ובין דיין ישראל שהרי לפי טעם הנ\"ל הכל תלוי בדיינים איך מיציאין הממון משום דכל לסטים או גנב ישראל נידון בדייני ישראל שתבעו הנגזל להגזלן בדין ישראל משא\"כ בלסטי' עכו\"ם שצריך לתובעו הנגזל אף שהוא ישראל בפני דייני עכו\"ם וק\"ל ועפ\"ר:","\u0003אבל המציל מיד לסטים עכו\"ם או מוכס עכו\"ם חייב להחזי' כו' \u0004 כן כת' הרמב\"ם רפ\"ו דגזילה גם בפ\"ה מגזילה דין ט' וי\"א דימה מוכס עכו\"ם ללסטים וכתב המ\"מ שם ז\"ל דעת הרב כשהמוכס מכו\"ם אע\"פ שהוא עומד מחמת המלך מסתמא הוא כמוכס שאין לו קצבה שסתמא יותר מן הדין הוא נוטל ופי' רבינו כן אוקימתא דרב אשי (דאיתא בפ' הגוזל בתרא דף י\"ד ע\"א ע\"ש) דאמר במוכס עכו\"ם עסקינן כו' ולא כן פרשו שאר מפרשים עכ\"ל המ\"מ. ונראה שגם כן דעת הטור הוא כשאר מפרשים ומ\"ה לא הזכיר בדין זה מוכס עכו\"ם:","\u0003ומ\"ש הרמב\"ם והמחבר חייב להחזיר שסתם הדבר שלא נתייאשו הבעלים כו' \u0004 צ\"ע הא כ' המחבר בסי' שס\"ט ס\"ה והוא מדברי הרמב\"ם שכ\"כ פ\"ה דגזילה ד\"י ז\"ל נטלו מוכסים כסותו (או חמורו כן הוא ברמב\"ם) והחזירו לו אחרת ה\"ז שלו מפני שזהו כמכירה היא וחזקתה שנתייאשו הבעלים ממנו ואינו יודע בודאי שזו גזילה כו' ע\"ש הרי לפנינו דס\"ל דחזקה הוא דנתייאשו הבעלים ממנו אפי' במוכס עכו\"ם דשם מפורש דבמוכס עכו\"ם איירי וגם כאן שסתם וכ' המציל מהלסטים איירי שמציל כסותו או חמורו והדומה לו ועל הטור לק\"מ שאף שגם הוא כתב בסי' שס\"ט ס\"ז האי דינא (והוא מהמשנה) דמוכס שנתן לא' טלית במקום טליתו דמותר להחזיקו מפני שנתייאשו הבעלים ממנו ולא חילק בין מוכסן עכו\"ם למוכסן ישראל אע\"ג דגם הוא ס\"ל דבלסטים עכו\"ם אין הבעלים מתייאשי' משום דדיני בגיאות וכמ\"ש כאן בר\"ס שס\"ח די\"ל דהוא ס\"ל דבמוכסין מתייאשין הבעלים טפי כיון דכל מוכסן בא מתחלה ברשות ליקח מהבעלים מכסו ואף שנוטל יותר מ\"מ בקל יוכל להתנצל ולו' לא לקחתי יותר או ליתן טעם למה לקח יותר מה שא\"כ בלסטים דעלמא אבל הרמב\"ם והמחבר דמשוו לסטים עכו\"ם ומוכסין עכו\"ם וכתבו אשניהם שהבעלים אינם מתייאשים אליבייהו צ\"ע ואין לתרץ ולו' דדוקא בנטל ממנו כסות והחזירו לו אחרת קאמר דמותר ומשום דנתייאש בצירוף טעם דסיים שם וכ' דאינו יודע בודאי שזו גזולה משא\"כ במציל מלסטים דמיירי בידוע שזו גזולה כגון שגזלו כתבי' וכן מוכסין מיירי שבא עליו בעקיפין בפני כל ותאמר שבכה\"ג דוקא אין דרכו להתיאש בסוברו שהיום או מחר יתבענו לדין מה שא\"כ כשהמוכסן נטלו ממנו ואינו מפורסם דאז ייאש נפשו ממנו דז\"א דהא לא כתבו הרמב\"ם והמחבר (שם בטלית) בסיום לשונם שהגזילה אינו ידוע אלא ז\"ל וא\"י בודאי שזו גזולה דנתינ' טעם זה קאי אזה שנתן לו המוכס טלי' תחת טליתו דמ\"ה מות' להחזיקו משום דנתייאש ממנו בעל הראשון וגם בהיתר אתא לידו בשעה שנתנו לו המוכסין כיון שלא ידע אז זה המקבלו ממנו שגזולה הי' ביד המוכס וכמ\"ש הכ\"מ שם (ואני כתבתי טעם אחר בדרי' ובסמ\"ע שם סי' שס\"ט שלא כתבו הרמב\"ם האי דלא ידע כו' אלא לטעמו ומ\"ה לא כתבוהו הטור ע\"ש) ונר' ליישב אחר שנקדים לכתוב שני דקדוקים שיש לדקדק בדברי הרמב\"ם הנ\"ל במ\"ש ז\"ל מפני שזו כמכירה היא וחזקת' שנתייאשו הבעלים ממנה. הא' במה שהקדי' לכתוב מפני שזו כמכירה קודם וחזקתו שנתייאשו הבעלים דמשמע דהיאוש תלוי במפני דהוה כמכירה. השני במ\"ש תיבת ממנה שנתייאשו הבעלים ממנה וע\"פ הדקדוקים נראה דס\"ל דודאי סתם נגזל מלסטים עכו\"ם או ממוכסים עכו\"ם אינו מיאש מטעם דעכו\"ם דייני בגיאות' ומה\"ט המציל מהן צריך להחזירו ודוקא בזה שנטלו המוכס ונתנו לאחר תחת כסותו דה\"ל כמכירה בזה קאמר דנתייאשי הבעלים ממנה דכיון דרואה דה\"ל כאלו כבר נמכר ויצא מתחת יד המוכס אזי מייאש נפשו מלהדר אחר כסותו או חמורו זה שהן ביד זה שקיבל מהמוכס ודעתו להעמיד המוכס בדין על דמי הטלית וז\"ש נתייאשו הבעלים ממנה דדוקא ממנה נתייאשו ולא מדמי' להוציא מיד המוכס. והרמב\"ם לטעמיה דס\"ל דייאוש ושינוי רשות קוני' אפי' הוי היאוש אחר שינוי רשות והטור דס\"ל כדעת ר\"י והרא\"ש דבעינן שיהי' היאוש קודם שינוי הרשות כבר כתבתי דאליבייהו לק\"מ:","\u0003וסתם גניבה הוי יאוש כו' \u0004 הטעם דבגניבה דלא ידע הנגנב מי גנבו מידו דיחזור עליו להוציא מידו מ\"ה מייאש אפי' בגנב שהוא עכו\"ם משא\"כ בלסטים שלקחו מידו בזרוע בפניו:","\u0003וע\"ל סי' רל\"ו כו' \u0004 מראה מקום זה כתבו המחבר גופו בס\"ס שע\"ד ע\"ש וגם מור\"ם חזר וכתבו בסי' שע\"א בס\"ס א':"],["\u0003 המציל מיד לסטים \u0004 עיין בתשובת מהרשד\"ם סי' קנ\"ז:","\u0003 וסתם גנבה הוי יאוש אפי' בעכו\"ם \u0004 באמת הרב נמשך אחרי הטור דלסטים היינו גזלן ובזה יש חילוק בין עכו\"ם לישראל אבל בגנב סתמא הוי יאוש אפי' בעכו\"ם כן כתב הטור לדעת הרא\"ש אבל באמת דברי הטור תמוהים שהרי הרא\"ש לא העתיק אלא הש\"ס ובע\"כ מוכרח לו' כמ\"ש הטור בשם י\"א דבגנב יש חילוק בין עכו\"ם לישראל דבעכו\"ם לא הוי סתמיה יאוש ובגזלן אפי' ישראל סתמא לא הוי יאוש ע\"ש. ולסטים דבש\"ס והרמב\"ם (וסמ\"ג) ושאר פוסקים היינו גנב וכן מוכח בש\"ס פ' הגוזל בתרא (בבא קמא דף קי\"ד ע\"א) להדיא דלסטים דהתם היינו גנב דקאמר אי ר' שמעון קשיא גנב וכן פי' רש\"י שם אלא דרבה בעי למימר דלסטים היינו גזלן ולא קי\"ל הכי (והכי אשכחן נמי בש\"ס ספ\"ק דביצה דלסטים סתמא היינו גנב דקאמר התם לא קשיא הא דמנטרי מחמת גנבי והא דלא מנטרי מחמת גנבי מהו דתימא רוב גנבי ישראל נינהו ולא מזלזלי בהו קמ\"ל ע\"כ) וכן מוכח בכמה הוכחו' מדברי הרמב\"ם אלו שהעתיק המחבר כאן דלסטים היינו גנב ומוכסין היינו גזלן וכדאי' בש\"ס שם ודוק. ועוד תימה לפי הבנת הטור הא דפליגי ר\"ש ורבנן וקי\"ל כרבנן (דסתם גניבה הוי יאוש בעלים וסתם גזלה לא הוי יאוש בעלים ולא כר\"ש דס\"ל להפך) היינו בעכו\"ם וכמ\"ש הב\"י והב\"ח והא ודאי ליתא דהא לענין טומאה פליגי והיינו בישראל ועוד דא\"כ היכא בעי למיפשט התם דרבי דקאמר גנב כגזלן היינו כגזלן דר' שמעון אכל הנך דמייתי התם הא כולהו מיירי בגזלן ישראל ובהא אפי' רבנן מודו לדעת הטור דסתמא הוי יאוש. וכן מסיק התם ממאי דתני ר' חייבים להחזיר מפני כבוד אביהן הא לאו כבוד אביהן לא ש\"מ רבי גזלן דר\"ש קאמר ש\"מ ואם איתא הא התם בגזלן ישראל שאני אלא ודאי פלוגתא דר\"ש ורבנן נמי בישראל מיירי ועלה קאי ר' וקאמר אומר אני גנב כגזלן וא\"כ אנן דקי\"ל כרבנן דר\"ש סתם גזלן דישראל לא הוי יאוש וסתם גנבה הוי יאוש ואם כן הא דקאמר בש\"ס לעיל אמתני' דהמציל מן הלסטים ל\"ש אלא עכו\"ם אבל לסטים ישראל בסתמא נמי מייאש לסטים דהתם היינו גנב וכדמוכח התם בש\"ס להדיא וכ\"כ בעל המאור פ' הגוזל בתרא וז\"ל ומאי דאמרי' דקי\"ל כרבנן דאמרי סתם גנבה הוי יאוש ה\"מ בגנב ישראל אבל בגנב עכו\"ם דדייני בגיאות' בסתמ' לא הוי יאוש עד דשמעינן דמייאש כדתנן המציל מן הלסטים אם נתייאשו הבעלים הרי אלו שלו ואוקימנא בלסטים עכו\"ם אבל בלסטים ישראל סתמא הוי יאוש וסוגיא דשמעתין מוכס היינו גזלן לסטים היינו גנב עכ\"ל (וכן הוא בתשו' הרשב\"א סי' תתקס\"ח ע\"ש) ואף הרמב\"ן בספר המלחמות שם לא נחלק עליו בזה וברור הוא דגם דעת הרא\"ש כן וכ\"כ התוס' פ' הגוזל בתרא (בבא קמא דף קי\"ד ע\"ב) להדיא דגנבים עכו\"ם מסתמ' לא מייאש כיון דדייני בגיאות' כדאמ' לעיל עכ\"ל ומביאם ב\"י לעיל סי' שנ\"ז וכן מוכח להדיא מדברי ר' ירוחם שכ' נל\"א ח\"ג סתם גנבה יאוש בעלים הוא אבל לא סתם גזלה עד דשמעינן דמייאש קמא פרק י' עד כאן לשונו ואחר כך כ' בחלק ד' נטלו מוכסים חמורו או לסטים כסותו ונתנו לו אחר גזול הרי אלו שלו דמסתמא מייאש בלסטים ישראל אבל בלסטים עכו\"ם מסתמא לא מייאש כו' סתם גזלן לא הוי יאוש בעלים עד דשמעינ' דמייאש עד כאן לשונו וכן מוכח דעת הרי\"ף שלא הביא פלוגתא דר\"ש ורבנן רק הביא הא דאמרינן בש\"ס לא שנו אלא בלסטים עכו\"ם אבל ישראל במסתמא הוי יאוש. אלא ודאי ס\"ל כדפי' ולכך לא הוצרך להביא פלוגתא דר\"ש ורבנן דאי לאשמועינן דסתם גנבה בישראל הוי יאוש הוא מבואר בש\"ס הנ\"ל ואי לאשמועינן דסתם גזלה לא הוי יאוש כבר כתב זה בפ' האיש מקדש דלית דחש לדר\"ש דאמר סתם גזלה הוי יאוש בעלים. וע\"ק על הטור אמאי דאמרי' בר\"פ לולב הגזול ל\"מ קאמר ל\"מ שאול דלאו דידיה היא אבל גזול אימא סתם גזילה יאוש בעלים הוא וכדידיה דמי יקמ\"ל ומייתי לה הרא\"ש בפ' הגוזל בתרא שם ומייתי מינה ראיה דק\"ל כעולא דר\"ש ורבנן בשתמא הוא דפליגי ולא כרבא דאמר בידוע פליגי אלמא דסתם גזילה אפי' בישראל לא הוי יאוש בעלים. ועוד ראייה מדאמרי' פ' האיש מקדש (קידושין דף נ\"ב ע\"א) ההיא איתתא דהוי קא משיא כרעא במשיכלא דמיא אתא ההוא גברא חטיף זוזי מחבריה ושדא לה אמר לה מיקדשת לי אתא לקמיא דרבא אמר לית דחש להא דר\"ש דאמר סתם גזילה יאוש בעלים הוי: ומייתי לה הרי\"ף והרא\"ש התם. ואע\"פ שהב\"ח הרגיש בזה וכתב דהך דפ' האיש מקדש לא מיירי אלא לענין קידושין דאורייתא. מ\"מ לא נהירא כלל דהרי כל הפוסקים כתבו סתמא דאינה מקודשת כלל משמע אפילו מדרבנן וכן משמע לישנא דלית דחש לדר\"ש דאפי' מדרבנן אינה מקודשת. ועוד דאין טעם לדבר כלל לומר דמדרבנן סתמא הוי יאוש דבשלמא לעיל בסי' שנ\"ג שפיר אמרי' דאף על גב דמדאורייתא יאוש כדי לא קני מדרבנן קני דהפקר ב\"ד הפקר אבל לענין סתמא כיון דאמרי' דסתם בני אדם דעת' שאין מתייאשים מן הגזיל' היאך יאמרו חכמים דסתמ' הוי יאוש וכי ישנו חכמי' דעת בני אדם וגם לא מצינו בשום פוסק סבר' דמדרבנן סתמ' הוי יאוש. ועוד דמ\"מ ק' כל שאר הקושיות שהקשתי לעיל על הטור אלא העיקר כדפי' וגם הטור גופיה כתב בסי' ל\"ז סי\"א גבי עדות ושמעי' לנגזל דאייאש קודם שנמכר כו' משמע להדי' דוק' שמעי' דאייאש הא בסתמ' לא הוי יאוש אע\"ג דמיירי בגזלן ישראל וכ\"כ בסי' שס\"א ס\"ד אבל סתמ' קי\"ל סתם גזיל' לא הוי יאוש בעלים כו' ומשמע התם להדי' דמיירי בגזלן ישראל. וגם בתשו' רבינו מאיר במרדכי פ' הגוזל בתרא משמע להדי' דבגנב עכו\"ם מסתמא לא הוי יאוש ומפרש לסטים היינו גנב וכמ\"ש אך מ\"ש שם דהתוספת' מיירי באנס ישראל לכאורה צ\"ע דמה בכך הא גזלן אפי' ישראל בסתמ' לא הוי יאוש וצ\"ל דה\"ק מיירי באנס ישראל ואתיא התוספת' כר\"ש אבל אי הוה מיירי באנס עכו\"ם הוה אתי' דלא כמאן דמשמ' ליה דאפי' ר\"ש מוד' דבעכו\"ם לא הוי בסתמ' יאוש כי היכא דלרבנן בגנב ישראל דהוי סתמ' יאוש וגנב עכו\"ם לא הוי בסתמ' יאוש ה\"ה גזלן לר\"ש דגזלן לר\"ש הוי כמו גנב לרבנן ודוק. וכל מה שכתבתי נ\"ל ברור ולא הוצרכתי להאריך רק מפני שהטור כאן אגב ריהטיה לא דק ונמשך אחרי הרב מהרמא\"י והסמ\"ע לא הרגיש כלל בדבר ואדרבה כתב לעיל סי' שס\"א ס\"ק ד' כדברי הטור וגם הב\"ח לא כוון יפה. וגם בשלטי גבורים פרק הגוזל בתר' דף מ\"ד ע\"א כתב וז\"ל מיימ' פרק ו' מה\"ג וסמ\"ג עשין ע\"ג והרא\"ש וטור ח\"מ סי' שס\"ח כתבו דגנב בין יהיה הגנב ישראל בין יהיה הגנב עכו\"ם בכל ענין הוי בסתם יאוש בעלים וגזלן ולסטים אם הם ישראלי' הוי נמי בסתם יאוש בעלים אבל גזלן ולסטי' עכו\"ם לא הוי בסתם יאוש בעלים כו' והטור כתב בשם י\"מ כו' עכ\"ל וכ\"כ הש\"ג פרק אלו מציאות ד' ע\"א ע\"ב וז\"ל מיהו הא דאמרי' דסתם גזלה לא הוי יאוש איכ' פלוגת' אי הוי אפי' בגזלן ישראל או דוק' בלסטים עכו\"ם דרוב הפוסקים הסכימו דלסטים ישראל הוי כגנב דסתמ' הוי יאוש בעלים וגנב נמי פליגי אי דוק' בגנבי ישראל הוי בסתמ' יאוש בעלים או אפי' בגנב עכו\"ם כדלעיל עכ\"ל וגם בב\"ח כ' כן בשם הרמב\"ם והרא\"ש: ולפע\"ד כולם שגו וטעו דודאי דעת הרמב\"ם והסמ\"ג והרא\"ש כדעת הי\"מ שהביא הטור ואי אפשר לחלוק על הי\"מ ודבריהם נכונים וברורי'. שוב ראיתי במהרש\"ל פרק הגוזל בתרא סי' כ\"ז כתב להדי' כדברי ע\"ש שהאריך בדברי' נכוני' רק מ\"ש שם להוכיח דפלוגת' דר\"ש ורבנן איירי בישראל דאל\"כ מאי פריך תלמודא לרבה ממתני' דנטלו את חמורו נימא דמתני' איירי בישראל דהא רב אשי דקאמר ל\"ש אלא לסטים עכו\"ם כו' דוק' אסיפ' ולא ארישא עכ\"ל נלפע\"ד דאינה הוכחה די\"ל דלענין ידוע שנתייאש אין לחלק בין עכו\"ם לישראל ועוד די\"ל דבלא\"ה משני שפיר אבל מה שכתבתי למעלה היא הוכחה גמורה ודוק ועיין בתשו' ר' משה אלשיך סי' קי\"ב:"]],["אָסוּר לִקְנוֹת דָּבָר הַגָּזוּל מֵהַגַּזְלָן, וְאָסוּר \u0010y0\u0011 לְסַעֲדוֹ עַל שִׁנּוּיוֹ כְּדֵי שֶׁיִּקְנֵהוּ, שֶׁכָּל הָעוֹשֶׂה דְּבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶם מַחֲזִיק יְדֵי עוֹבְרֵי עֲבֵרָה וְעוֹבֵר עַל וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשֹׁל. \u0005(וַיִּקְרָא יט, יד)\u0006 וְהַלּוֹקֵחַ מִמֶּנּוּ מִטַּלְטְלִין, \u0010y1\u0011 \u0010c0\u0011 דִּינוֹ כְּלוֹקֵחַ מֵהַגַּנָּב, שֶׁנִּתְבָּאֵר בְּסִימָן שנ\"ו.\nאָסוּר לֵהָנוֹת בַּדָּבָר הַגָּזוּל, וַאֲפִלּוּ לְאַחַר יֵאוּשׁ; וְהוּא שֶׁיָּדַע בְּוַדַּאי שֶׁדָּבָר זֶה הוּא הַגְּזֵלָה עַצְמָהּ. כֵּיצַד, יָדַע שֶׁבְּהֵמָה זוֹ גְּזוּלָה, אָסוּר לִרְכֹּב עָלֶיהָ אוֹ לַחֲרֹשׁ בָּהּ; גָּזַל בַּיִת אוֹ שָׂדֶה, אָסוּר לַעֲבֹר בְּתוֹכָהּ אוֹ לִכָּנֵס בָּהּ בַּחַמָּה מִפְּנֵי הַחַמָּה, וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים, וְאִם דָּר בָּהּ \u0010y2\u0011 חַיָּב לְהַעֲלוֹת שָׂכָר לַבְּעָלִים, אִם הָיְתָה עֲשׂוּיָה לְשָׂכָר; \u0010y3\u0011 גָּזַל דְּקָלִים וְעָשָׂה מֵהֶם גֶּשֶׁר, אָסוּר לַעֲבֹר עָלָיו, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005מִיהוּ, אִם מְסָרוֹ לָרַבִּים, מֻתָּר לֵהָנוֹת מִמֶּנּוּ, דְּהָא הָוֵי יֵאוּשׁ עִם שִׁנּוּי רְשׁוּת (הַמַּגִּיד פ\"ה)\u0006. אֲבָל מֶלֶךְ שֶׁכָּרַת אִילָנוֹת שֶׁל בַּעֲלֵי בָתִּים וְעָשָׂה מֵהֶם גֶּשֶׁר, מֻתָּר לַעֲבֹר עָלָיו, אֲפִלּוּ שֶׁצִּוָּה הַמֶּלֶךְ לַעֲבָדָיו לִכְרֹת מִכָּל אֶחָד וְאֶחָד דָּבָר יָדוּעַ, וְהָלְכוּ הֵם וְכָרְתוּ הַכֹּל מֵאֶחָד, מֻתָּר. וְכֵן אִם הָרַס בָּתִּים וְעָשָׂה דֶּרֶךְ אוֹ חוֹמָה, מֻתָּר לֵיהָנוֹת בָּהּ, וְכֵן כָּל כַּיּוֹצֵא \u0005(בָּזֶה)\u0006, שֶׁדִּין הַמֶּלֶךְ דִּין; וְהוּא שֶׁיְּהֵא מַטְבְּעוֹ יוֹצֵא בְּאוֹתָם הָאֲרָצוֹת, שֶׁהֲרֵי הִסְכִּימוּ עָלָיו בְּנֵי אוֹתָהּ הָאָרֶץ וְסָמְכָה דַעְתָּם שֶׁהוּא אֲדוֹנֵיהֶם וְהֵם לוֹ עֲבָדִים, שֶׁאִם לֹא כֵּן הֲרֵי הוּא כְּגַזְלָן בַּעַל זְרוֹעַ.\nאָסוּר לֵהָנוֹת מֵהַגַּזְלָן \u0005שֶׁהֻחְזַק מָמוֹנוֹ שֶׁבָּא בִּגְזֵלָה (טוּר ס\"ה)\u0006. \u0010y4\u0011 וְאִם הָיָה מִעוּט שֶׁלּוֹ, אַף עַל פִּי שֶׁרֹב מָמוֹנוֹ גָּזוּל, מֻתָּר לֵהָנוֹת מִמֶּנּוּ, עַד שֶׁיֵּדַע בְּוַדַּאי שֶׁדָּבָר זֶה גָּזוּל בְּיָדוֹ:\nבְּנֵי אָדָם שֶׁחֶזְקָתָם גַּזְלָנִים וְחֶזְקַת כָּל מָמוֹנָם גָּזֵל מִפְּנֵי שֶׁמְּלַאכְתָּם מְלֶאכֶת גַּזְלָנִים, כְּגוֹן הַמּוֹכְסִים וְהַלִּסְטִים, אָסוּר לֵהָנוֹת מֵהֶם, \u0010y5\u0011 שֶׁחֶזְקַת מְלָאכָה זוֹ שֶׁהִיא גָּזֵל. \u0010y6\u0011 וְאֵין מְצָרְפִים דִּינָרִים מֵהַתֵּבָה שֶׁלָּהֶם, שֶׁהַכֹּל בְּחֶזְקַת גְּזֵלָה. אֲבָל מִמַּה שֶׁיֵּשׁ לוֹ בַּבַּיִת אוֹ בַּשּׁוּק שֶׁלֹּא בְּתֵבַת הַמּוֹכְסִים, מֻתָּר לְצָרֵף. וַאֲפִלּוּ מִתֵּבָתוֹ, אִם הוּא חַיָּב לָתֵת לוֹ חֲצִי דִינָר וְאֵין לוֹ אֶלָּא דִינָר, נוֹתְנוֹ לוֹ וְלוֹקֵחַ מִמֶּנּוּ חֲצִי דִינָר אֲפִלּוּ מִתֵּבַת הַמוֹכְסִין, מִפְּנֵי שֶׁהוּא כְּמַצִּיל מִיָּדוֹ.\nנָטְלוּ מוֹכְסִין כְּסוּתוֹ וְהֶחֱזִירוּ לוֹ אַחֶרֶת, הֲרֵי אֵלּוּ שֶׁלּוֹ, מִפְּנֵי שֶׁזּוֹ כִּמְכִירָה הִיא, וְחֶזְקָתָהּ שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה, \u0010y7\u0011 \u0010c1\u0011 וְאֵינוֹ יוֹדֵע בְּוַדַּאי שֶׁזּוֹ גְּזוּלָה. וְאִם הָיָה וָתִיק וּמַחֲמִיר עַל עַצְמוֹ, מַחֲזִירָן לַבְּעָלִים הָרִאשׁוֹנִים. \u0005וּבְיָדוּעַ שֶׁלֹּא נִתְיָאֲשׁוּ הַבְּעָלִים, צָרִיךְ לְהַחֲזִירוֹ לַבְּעָלִים בְּחִנָּם (מָרְדְּכַי ר\"פ הַגּוֹזֵל בַּתְרָא)\u0006.\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהַמּוֹכֵס כְּלִסְטִים, בִּזְמַן שֶׁהַמּוֹכֵס גּוֹי, אוֹ מוֹכֵס הָעוֹמֵד מֵאֵלָיו, אוֹ מוֹכֵס הָעוֹמֵד מֵחֲמַת הַמֶּלֶךְ וְאֵין לוֹ קִצְבָה, אֶלָּא לוֹקֵחַ מַה שֶּׁיִּרְצֶה. אֲבָל מוֹכֵס שֶׁפְּסָקוֹ הַמֶּלֶךְ לִטֹּל דָּבָר קָצוּב, \u0005וַאֲפִלּוּ צִוָּה שֶׁיִּשְׂרָאֵל יִתֵּן יוֹתֵר מִגּוֹי, מִכָּל מָקוֹם מִקְרֵי דָּבָר קָצוּב לְכָל אִישׁ (מַהֲרִי\"ק שֹׁרֶשׁ קצ\"ה)\u0006, וְהֶעֱמִיד מוֹכֵס יִשְׂרָאֵל לִגְבּוֹתוֹ לַמֶּלֶךְ, וְנוֹדַע שֶׁאָדָם זֶה נֶאֱמָן, וְאֵינוֹ מוֹסִיף כְּלוּם עַל מַה שֶּׁגָּזַר הַמֶּלֶךְ, אֵינוֹ בְּחֶזְקַת גַּזְלָן, מִשּׁוּם דְּדִינָא דְמַלְכוּתָא דִּינָא. וְלֹא עוֹד, אֶלָּא שֶׁהַמַּבְרִיחַ מִמֶּכֶס זֶה, עוֹבֵר \u0005עַל לֹא תִגְזֹל (וַיִּקְרָא יט, יג)\u0006, מִפְּנֵי שֶׁהוּא גוֹזֵל אֶת הַמֶּלֶךְ, בֵּין שֶׁהָיָה מֶלֶךְ יִשְׂרָאֵל בֵּין שֶׁהָיָה מֶלֶךְ \u0010y8\u0011 גּוֹי. וְכֵן אִם יִשְׂרָאֵל קָנָה הַמֶּכֶס מֵהַמֶּלֶךְ, הַמַּבְרִיחַ עַצְמוֹ הֲרֵי זֶה גוֹזֵל יִשְׂרָאֵל שֶׁקְּנָאוֹ. \u0005וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ יָדוּעַ דְּהַיִּשְׂרָאֵל לוֹקֵחַ יוֹתֵר מִן הַקִּצְבָה, מִכָּל מָקוֹם אָסוּר לְהַבְרִיחַ מִמֶּנּוּ דָּבָר הַקָּצוּב, \u0010y9\u0011 דְּהָוֵי כְּגוֹזֵל מִן הַגַּזְלָן, דְּאָסוּר (בֵּית יוֹסֵף)\u0006. אֲבָל אִם קְנָאוֹ גוֹי, מֻתָּר, מִשּׁוּם דְּהָוֵי כְּהַפְקָעַת הַלְוָאָתוֹ דְּשָׁרִי בְּמָקוֹם דְּלֵיכָּא חִלּוּל הַשֵּׁם. \u0005הַגָּה: \u0010c2\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ הַמּוֹכֵס יִשְׂרָאֵל, אִם לֹא קְנָאוֹ לְעַצְמוֹ רַק גּוֹבֶה לַמֶּלֶךְ, אַף עַל גַּב דְּאָסוּר לְהַבְרִיחַ מִכֹּחַ דִּינָא דְמַלְכוּתָא, מִכָּל מָקוֹם אִם אָדָם מַבְרִיחַ אֵין לַמּוֹכֵס לָכֹף אוֹתוֹ לִתֵּן, דְּהָוֵי כְּהַפְקָעַת הַלְוָאָתוֹ דְשָׁרִי. מִיהוּ, אִם יֵשׁ בָּזֶה מִשּׁוּם יִרְאַת הַמֶּלֶךְ, וַדַּאי יָכוֹל לָכֹף אוֹתוֹ (רַ\"ן פֶּרֶק ד' דִּנְדָרִים)\u0006. \u0010c3\u0011\nוְכֵן מֶלֶךְ שֶׁשָּׂם מַס עַל בְּנֵי הָעִיר אוֹ עַל כָּל אִישׁ וָאִישׁ, דָּבָר קָצוּב מִשָּׁנָה לְשָׁנָה; אוֹ עַל כָּל שָׂדֶה וְשָׂדֶה דָּבָר קָצוּב, אוֹ שֶׁגָּזַר שֶׁכָּל מִי שֶׁיַּעֲבֹר עַל דָּבָר זֶה יִלָּקְחוּ כָּל נְכָסָיו לְבֵית הַמֶּלֶךְ, אוֹ כָּל מִי שֶׁיִּמָּצֵא בַּשָּׂדֶה בִּשְׁעַת הַגֹּרֶן, הוּא יִתֵּן הַמַּס שֶׁעָלֶיהָ \u0010y10\u0011 בֵּין שֶׁהָיָה הוּא בַּעַל הַשָּׂדֶה בֵּין שֶׁאֵינוֹ בַּעַל הַשָּׂדֶה, וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ, אֵינוֹ גָּזֵל, וְיִשְׂרָאֵל שֶׁגָּבָה אוֹתָם לַמֶּלֶךְ אֵינוֹ בְּחֶזְקַת גַּזְלָן, וַהֲרֵי הוּא כָּשֵׁר, וְהוּא שֶׁלֹּא יוֹסִיף וְלֹא יְשַׁנֶּה וְלֹא יִקַּח לְעַצְמוֹ כְּלוּם. \u0010c4\u0011\nוְכֵן מֶלֶךְ שֶׁכָּעַס עַל אֶחָד מֵעֲבָדָיו וְשַׁמָּשָׁיו מִבְּנֵי הַמְּדִינָה וְלָקַח שָׂדֵהוּ אוֹ חֲצֵרוֹ, אֵינוֹ גָּזֵל, וּמֻתָּר לֵהָנוֹת בָּהּ; וְהַלּוֹקְחָהּ מֵהַמֶּלֶךְ הֲרֵי הִיא שֶׁלּוֹ, וְאֵין הַבְּעָלִים מוֹצִיאִין אוֹתָהּ מִיָּדוֹ. \u0005(וכ\"כ לְעֵיל ס\"ס רל\"ז)\u0006 אֲבָל מֶלֶךְ שֶׁלָּקַח שָׂדֶה אוֹ חָצֵר שֶׁל אֶחָד מִבְּנֵי הַמְּדִינָה שֶׁלֹּא כַּדִּינִים שֶׁחָקַק, הֲרֵי זֶה גַּזְלָן, וְהַלּוֹקֵחַ מִמֶּנּוּ מוֹצִיאִין הַבְּעָלִים מִיָּדוֹ. כְּלָלוֹ שֶׁל דָּבָר: כָּל דִּין שֶׁיַּחֲקֹק אוֹתוֹ הַמֶּלֶךְ לַכֹּל וְלֹא יִהְיֶה לְאָדָם אֶחָד בִּפְנֵי עַצְמוֹ, אֵינוֹ גָּזֵל; \u0010c5\u0011 וְכָל שֶׁיִּקַּח מֵאִישׁ זֶה בִּלְבַד, שֶׁלֹּא כַּדָּת הַיָּדוּעַ לַכֹּל, אֶלָּא חָמַס אֶת זֶה, הֲרֵי זֶה גָּזֵל. \u0005הַגָּה: \u0010c6\u0011 וְאִם חָקַק לְבַעַל אֻמָּנוּת אֶחָד, כְּגוֹן שֶׁחָקַק לַמַּלְוֶה בְרִבִּית אֵיזֶה דָבָר, יֵשׁ אוֹמְרִים דְּלָא אָמְרִינָן בֵּהּ דִּינָא דְמַלְכוּתָא דִּינָא, הוֹאִיל וְאֵינוֹ חָקוּק לַכֹּל (מַהֲרִי\"ק שֹׁרֶשׁ ס\"ו)\u0006. יֵשׁ אוֹמְרִים דְּלָא אָמְרִינָן דִּינָא דְמַלְכוּתָא דִּינָא \u0010c7\u0011 אֶלָּא בְּמִסִּים וּמְכָסִים הַתְּלוּיִים בְּקַרְקַע, \u0010y11\u0011 כִּי הַמֶּלֶךְ גּוֹזֵר שֶׁלֹּא יָדוּרוּ בְּאַרְצוֹ כִּי אִם בְּדֶרֶךְ זֶה, אֲבָל בִּשְׁאָר דְּבָרִים, לֹא \u0005(הָרֹא\"שׁ פֶּרֶק ד' דִנְדָרִים בְּשֵׁם הר\"מ וּמָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּאָמְרֵינָן בְּכָל דָּבָר דִּינָא דְמַלְכוּתָא דִינָא \u0005(מָרְדְּכַי שָׁם בְּשֵׁם הַתוס' ות\"ה סִימָן ש\"ט)\u0006, וְלָכֵן הַמַּלְוֶה עַל הַמַּשְׁכּוֹן \u0010y12\u0011 יָכוֹל לְמָכְרוֹ אַחַר שָׁנָה, הוֹאִיל וְכֵן דִּינָא דְמַלְכוּתָא \u0005(שָׁם בְּשֵׁם ר\"י בַּר פֶּרֶץ)\u0006 ; וְכֵן הוּא עִקָּר, וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שנ\"ו סָעִיף ז':\nלְפִיכָךְ, גַּבָּאֵי הַמֶּלֶךְ וְשׁוֹטְרָיו שֶׁמּוֹכְרִים הַשָּׂדוֹת בְּמַס הַקְּצוּבָה עַל הַשָּׂדוֹת, מִמְכָּרָן מִמְכָּר. אֲבָל מַס שֶׁעַל כָּל אִישׁ וְאִישׁ, אֵינוֹ גּוֹבֶה אֶלָּא מִן הָאָדָם עַצְמוֹ. וְאִם מָכְרוּ הַשָּׂדֶה בְּמַס שֶׁעַל הָרֹאשׁ, הֲרֵי זֶה אֵינוֹ מִמְכָּר אֶלָּא אִם כֵּן הָיָה דִּין הַמֶּלֶךְ כָּךְ. \u0005וְע\"ל סִימָן ס\"ח מִדִּינָא דְמַלְכוּתָא, גַּם בְּסִימָן ק\"ד סָעִיף ב' מִדִּין זֶה.\u0006\nמֶלֶךְ שֶׁהָיוּ דִּינָיו שֶׁכָּל שֶׁלֹּא יִתֵּן הַמַּס שֶׁעַל \u0010y13\u0011 הַשָּׂדֶה, תִּהְיֶה הַשָּׂדֶה לְנוֹתֵן הַמַּס, וּבָרַח בַּעַל הַשָּׂדֶה מִפְּנֵי הַמַּס, וּבָא זֶה וְנָתַן מַס שֶׁעָלֶיהָ לַמֶּלֶךְ, וְאָכַל פֵּרוֹתֶיהָ, אֵין זֶה גָּזֵל, אֶלָּא אוֹכֵל \u0010y14\u0011 פֵּרוֹת וְנוֹתֵן הַמַּס עַד שֶׁיַּחְזְרוּ הַבְּעָלִים, שֶׁדִּין הַמֶּלֶךְ דִּין הוּא, כְּמוֹ שֶׁאָמַרְנוּ. \u0005הַגָּה: \u0010y15\u0011 וְכֵן הוּא חָק הַמֶּלֶךְ \u0010y16\u0011 שֶׁכָּל מִי שֶׁיִּמָּצֵא בַּשָּׂדֶה יִתֵּן בְּעַד בְּנֵי הַבִּקְעָה וְהוּא יַחֲזֹר וְיִגְבֶּה מֵהֶם אוֹ שֶׁיָּכוֹל לִגְבּוֹת מַס הַשָּׁנָה מֵאֶחָד (טוּר ס\"ט)\u0006.\nוְכֵן מֶלֶךְ שֶׁגָּזַר שֶׁכָּל מִי שֶׁיִּתֵּן מַס הַקָּצוּב עַל הָאִישׁ יִשְׁתַּעְבֵּד בְּזֶה שֶׁלֹּא נָתַן, וּבָא יִשְׂרָאֵל וְנָתַן הַמַּס שֶׁעַל יִשְׂרָאֵל זֶה הֶעָנִי, \u0010y17\u0011 הֲרֵי זֶה עוֹבֵד בּוֹ יוֹתֵר מִדַּאי, \u0010y18\u0011 שֶׁדִּין הַמֶּלֶךְ דִּין, אֲבָל אֵינוֹ עוֹבֵד בּוֹ כְּעֶבֶד. \u0005הַגָּה: יִשְׂרָאֵל שֶׁהָיָה \u0010c8\u0011 חַיָּב לְגוֹי, וְהַגּוֹי מָכַר הַשְּׁטָר לְיִשְׂרָאֵל, אַף עַל פִּי שֶׁאָסוּר לָדוּן עִם יִשְׂרָאֵל חֲבֵרוֹ בִּפְנֵי גּוֹיִים וְאַף עַל פִּי שֶׁבָּא מִכֹּחַ גּוֹי, מִכָּל מָקוֹם דַּיָּנֵי יִשְׂרָאֵל יִפְסְקוּ לְיִשְׂרָאֵל זֶה מַה שֶּׁהָיָה הַגּוֹי מַרְוִיחַ לִפְנֵי דַּיָּנֵי גּוֹיִים, הוֹאִיל וְיִשְׂרָאֵל זֶה בָּא מִכֹּחוֹ הֲרֵי הוּא כָּמוֹהוּ בְּכָל מַה שֶּׁהָיָה יָכוֹל לִזְכּוֹת לִפְנֵי דַּיָּנֵי גּוֹיִים שֶׁהוּא דִּינָא דְמַלְכוּתָא (תְּשׁוּבַת הָרֹא\"שׁ כְּלָל י\"ח סִימָן א' וְכֵן נִרְאֶה לִי ס\"ס כ\"ו)\u0006. \u0010y19\u0011 הַנּוֹשֵׂא אִשָּׁה בְּמָקוֹם שֶׁדָּנִין בְּדִינֵי גּוֹיִים, וּמֵתָה אִשְׁתּוֹ, לֹא יוּכַל אֲבִי אִשְׁתּוֹ אוֹ שְׁאָר יוֹרְשֶׁיהָ לוֹמַר: כָּל הַנּוֹשֵׂא אִשָּׁה, עַל דַּעַת הַמִּנְהָג הוּא נוֹשֵׂא, וְנָדוּן הַדָּבָר בְּדִינֵי גּוֹיִים דְּאִם מֵתָה יוֹרְשָׁהּ בַּעְלָהּ אוֹ כַּדּוֹמֶה לָזֶה, וְלֵיכָּא בְּזֶה מִשּׁוּם דִּינָא דְמַלְכוּתָא \u0005(בֵּית יוֹסֵף בְּסִימָן כ\"ו בְּשֵׁם תְּשׁוּבַת הָרַשְׁבָּ\"א)\u0006, \u0010y20\u0011 \u0010c9\u0011 דְּלָא אַמְרִינָן דִּינָא דְּמַלְכוּתָא אֶלָּא בְּדָבָר שֶׁיֵּשׁ בּוֹ הֲנָאָה לַמֶּלֶךְ, אוֹ שֶׁהוּא לְתַקָּנַת בְּנֵי הַמְּדִינָה, אֲבָל לֹא שֶׁיִּדּוֹנוּ בְּדִינֵי גּוֹיִים, דְּאִם כֵּן בָּטְלוּ כָּל דִּינֵי יִשְׂרָאֵל \u0005(מַהֲרִי\"ק שֹׁרֶשׁ קפ\"ח בְּשֵׁם רַשְׁבָּ\"א)\u0006.",["\u0003לסעדו על שינויו \u0004 פי' כדי שיצא מיד הגזלן ויהיה שינוי רשות ויקנהו אח\"כ ביאוש ושיניי רשות וגם בלא שינוי רשות קנהו אם נשתנה גמור שאינו חוזר או אפי' חוזר אם יש יאוש עם שינוי השם וכמ\"ש בסי' שנ\"ג ושס\"א ואסור לסעדו שיבא לידי אחד מהשינויי' הללו:","\u0003דינו כלוקח מן הגנב \u0004 פי' לענין אם נעשה בו תק\"ה אי לא ואם יש חילוק בין גנב מפורסם או לא ע\"ש ר\"ס שנ\"ו ושם עוד חילוקים בזה:","\u0003חייב להעלות שכר לבעלים. \u0004 דקרקע בחזקת בעליה עומדת וכמ\"ש בסי' שס\"ג ושע\"א:","\u0003גזל דקלים כו' עד אסור לעבור עליו \u0004 כאן שייך הג\"ה של מור\"ם ז\"ל הנדפס בס\"י אחר זה ז\"ל מיהו אם מסרו לרבים מותר כו' וכ\"כ המ\"מ כתבתי ל' בפרישה דבכה\"ג אף במקום דלית ביה דינא דמלכות' דינא מותר וכן מצאתי בהגהות דכתיבת יד מור\"ם ז\"ל הג\"ה זו אדינא דגזל דקלי':","\u0003ואם היה מיעוט שלו כו' \u0004 וע\"ל ר\"ס שנ\"ח שפסק הט\"ו וגם הרמב\"ם דאסור לקנות מהגנב דבר שרובו בחזקת גנוב ושם בדרישה כתבתי דיש לחלק דברועי' ואינך דלשם דהן בחזקת גנבים ומסתמא כל מה שבידם היא בחזקת גנוב כי כל מלאכתן בזה אלא שיש מיעוט רועים שאינן גנבים כלל ותלינן לזה שבא לקנות ממנו בהרוב משא\"כ כאן מיירי בידוע בו שיש בידו שלזה מיעוט ממון שאינו גזול ועמ\"ש שם עוד מזה:","\u0003שחזקת מלאכה זו שהיא גזול \u0004 כך היא הגירס' הנכונה גם ברמב\"ם וכן הוא לפנינו ברמב\"ם בדפוס גדול וקטן ופי' מלאכה זו של מוכסין ולא כב\"י שהביא ל' הרמב\"ם כתוב בו ז\"ל שחזקת מאכל זה שהיא גזול ומחלק בבית יוסף להרמב\"ם בין דבר מאכל שהוא בחזקת גזול מסתמ' טפי וזה אינו ועיין דרישה מ\"ש עוד בישוב דברי הרמב\"ם:","\u0003ואין מצרפי' דינרין מהתיבה שלהם כו' \u0004 דוק' בצירוף שאין לו הנאה כ\"כ יש חילוק בין מהתיבה שלהן שהוא ממעות המכס בעצמו דאסור ובין צירוף שיש לו ממעות שבביתו דמותר אבל בשאר הנאות גדולות כתב לפני זה דאפי' ממה שיש לו בבית אסור ליהנות ממנו וק\"ל:","\u0003ואינו יודע בודאי שזו גזולה \u0004 כ\"כ הרמב\"ם בפ\"ה דגזילה ואזיל לשטתו דס\"ל אם ידע הלוקח שגזולה היא היה צריך הלוקח ליתן להנגזל דמי שווי' כי כן סבירא להו להרי\"ף והרמב\"ם בכל שינוי רשות ויאוש דאף דקנה הלוקח מ\"מ צריך ליתן הדמים וכמ\"ש המחבר בשמם בסי' שנ\"ו ושס\"א ובאינך מקומות ומהתימה על מור\"ם ז\"ל שלא כתב כאן שלדעת י\"א שהזכיר שם והם ר\"י והרא\"ש אפי' ידע הלוקח שזו ודאי גזולה אפי' הכי הוא שלו וע' דרישה שהארכתי בזה לברר הדברים גם כתבתי לזה הוכחה לעיל בסמ\"ע בסי' שס\"א ע\"ש ונראה שמור\"ם ג\"כ בשיטת הב\"י והכ\"מ אזיל שכתבו שמטעם אחר כ' הרמב\"ם דמיירי שאינו יודע שזו גזולה ע\"פ סוגיא דהגוזל בתרא (דף קי\"ד ע\"א) ע\"ש וכתבתיהו בדרישה ומ\"ה סתם מור\"ם כאן דבריו אבל בדרישה כתבתי הנלע\"ד לסתור דבריהן וגם ע' לעיל בסי' שס\"ח מ\"ש בסמ\"ע בביאור דברי הרמב\"ם והמחבר:","\u0003וכן אם ישראל קנה כו' \u0004 פי' ול\"ת דוקא כשגבאו להמלך דאז הוי משום דינא דמלכותא טפי:","\u0003דהוי כגוזל מן הגזלן וע\"ז אמרי אינשי בתר גנבא גניב וטעמא טעים ועפ\"ר שם כתבתי דנראה דבמקום שהמוכסין מאמינים להסוחרים במה שאומרי' לפניהן שאין להן סחורה אלא כך וכך אזי מותר לשנות להגיד לפניהן באופן שלא יפסדו דהיינו דרך משל אם יש להן מ' אמות בגד ומן הדין אין להם ליתן מהם מכס אלא ל' גדולים וכשידוע להמוכסן שיש מ' אמות יכריחו ליתן לו מהן מ' גדולים מותר להן לשנות ולומר להמוכס שאין להן אלא ל' אמות ולא יתנו לו אלא ל' גדולים וכל כיוצא בזה ומה\"נ דקדק המחבר וכ' ז\"ל אסור להבריח ממנו דבר הקצוב כו' הא המותר מותר להבריח:\u0004","\u0003בין שהיה כו' \u0004 ז\"ל הטור וכן המס שיש לו לגבות מבעל' השדות אפי' לא נשאר שם רק א' וגבה ממנו בשביל כולם אינו גזל לפי שאין עליו לטרוח לגבות מעט מעט מכל א' ואחד וזה שנטלו ממנו יגבה מכל בעלי השדות מכל א' חלקו (וכתבו מור\"ם ז\"ל בסמוך ס\"ס י' וצ\"ל דהוא בכלל מ\"ש המחבר כאן ודו\"ק) בד\"א בבעלי השדות אבל האריס אין להן למשכנו בשביל בעלי השדות עכ\"ל והטעם מפורש בגמ' כיון דאין לאריס חלק בגוף הקרקע אין עליו לפרוע חלק בע\"ה ע\"כ ומזה יש ללמוד דמ\"ש הרמב\"ם והמחבר כאן בין שאינו בעל השדה דר\"ל שאינו בעל השדה זו כ\"א בעל שדה שבצדה אבל מ\"מ יש לו חלק ג\"כ בגוף השדה מ\"ה פורע בשביל האחרים מן דינא דמלכותא משא\"כ כשאין לו חלק בהקרקע כלל דאז לא גרע מאריס דאין גובין ממנו:","\u0003כי המלך גוזר שלא ידורו בארצו \u0004 הטעם שהארץ היא מיוחדת שהיא של המלך וכל אדם יכול לעשות בשלו מה שירצה וכן סיים הרא\"ש בשם הרמ\"ה שם בטעמו ז\"ל ואף הדיוט שיש לו קרקע כך דינא שלא יהנה אדם מארצו שלא מדעתו וקצבתו עכ\"ל והביאו בד\"מ ע\"ש:","\u0003יוכל למכרו אחר שנה כו' \u0004 וכ\"כ לעיל בסי' ע\"ג סי\"ד בהג\"ה והוא מהמשנ' פ' הגוזל והא דהוצרך לכתוב דמשום דינא דמלכותא מותר למוכר' אחר שנה משום דל\"ת כיון דמשכנו משכון של עכו\"ם ונותן להמלוה ממנו ריבי' אסור למוכרו ולהביא להממשכן ליד היזק מעכו\"ם שיעליל עליו משא\"כ במשכן לו משכון של ישראל דמותר למוכרו בסוף ל' להתראתו א\"ל במקום שאין מוכרין משכנות ש\"ע תוך שנה וכמ\"ש מור\"ם בהג\"ה לעיל בסי' ע\"ג סי\"ד ומ\"ה כתב שם דבתוך השנה לא ימכרו דמשמע דהסברא היא דאפי' בתוך השנה מותר למוכרו וכאן הוצרך לכתוב דלאחר שנה מותר למוכרו וק\"ל:","\u0003תהיה השדה לנותן המס \u0004 פי' בימיהן היו גוף השדות למלך וישראל ועכו\"ם היה מנהגם להחזיק בהן לחרוש ולזרען ונותנין כל שנה חוק קצוב מס ממנו למלך ואכזה אמר שאם היה דין המלך שלא יתן מס כו' אין זה גזל ובודאי אם היה גוף השדה של ישראל אז אף אם צריך ליתן מס דבר קצוב למלך אינו יכול להפקיע מידו כל פירותיו בשביל שלא נתן המס:","\u0003ונותן המס עד שיחזרו הבעלים כו' \u0004 עפ\"ר וד\"מ שם כתב דכה\"ג שגוף השדה של המלך אפי' לקחו הגזבר ונתנו לאחר שיהיה בידו לעולם אין זה גזל דמאחר דגופו של השדה הוא של מלך ולא בא ליד זה כ\"א עבור המס והרי לא נתן המס וכאלו לא בא לידו דמי:","\u0003וכן הוא חוק המלך כו' \u0004 כ\"כ הטור והוא מהגמרא וכמ\"ש בפרישה ועמ\"ש לעיל בסמוך שנ\"ל שהוא בכלל מ\"ש המחבר בס\"ז ז\"ל בין שהיה הוא בעל השדה בין שאינו בעל השדה ע\"ש:","\u0003שכל מי שימצא בשדה יתן בעד בני כל הבקעה כו' \u0004 כבר כתבו ג\"כ המחבר בס\"ז במ\"ש שם או כל מי שימצ' בשדה בשעת הגורן הוא יתן המס כו' אלא שלא ביאר שם דהוא יחזור ויגבה כו' אבל פשוט הוא:","\u0003ה\"ז עובד בו כו' כעבד כו' \u0004 כ\"כ הרמב\"ם והטור וכ' ב\"י דר\"ל דלא יעבוד בו עבודת עבד כנעני דהיינו להוליך אחריו כליו לבית המרחץ או לחלוץ מנעליו וכמ\"ש לא תעבוד בו עבודת עבד ואף שבישראל שלא נמכר לעבד עברי מותר להשתעבד בו אפי' בכאלו וכמ\"ש הרמב\"ם בפ\"ה דעבדי' ומטעם דלא אסרה התורה שיעבוד זה אלא בעבד עברי מפני שנפש' שפילה ה\"נ כיון דמדינ' דמלכותא הרשות נתונה להשתעבד בהם דינו כעבד עברי ואסור להשתעבד בהן עבודת עבד כנעני הכי נראה לי:","\u0003שדין המלך דין \u0004 הטו' מסיק בס\"ס זה וכתב וז\"ל כ' הרמב\"ם בד\"א במלך שטבעו יוצא באותן ארצו' והסכימו עליו שהוא אדוניהן והם עובדי' לו אבל אם אין טבעו יוצא הרי הוא כגזלן בעל זרוע לכל דבר הוא ועבדיו עכ\"ל וכתבו המחבר בקצר' לפני זה בס\"ב ע\"ש:","\u0003הנושא אשה במקום שדנין בדיני עכו\"ם כו' \u0004 ומתה אשתו לא יוכל אבי אשתו כו' וא\"ת הא כתב מור\"ם בהג\"ה בר\"ס רמ\"ח ז\"ל ואם עשה צוואה במקום שנהגו לדון בדיני עכו\"ם ובאו אחר כך לדון בדיני ישראל לא אמרי' דירושה אין לה הפסק עכ\"ל והוא מהריב\"ש סי' נ\"ב ושם בתשוב' מפורש דאיירי שיצא זה הבא לירש למקום אחר שדנין בו בדיני ישראל ואפ\"ה פסק שנילך אחר מקום שנעשה בו הצוואה וידונו בדיני עכו\"ם וי\"ל דשאני התם דכיון דהמצוה מת באותו מקום שדנין בדיני עכו\"ם ועש' צוואה סתם ואחריו לפלוני אמרי' דודאי דעתו היה כמו שמורגל בפי הבריות דמפרשי' ואחריו לפלוני כפשוטו ואפי' אם הראשון ראוי לירש ומ\"ה פסק שדנין בדיני עכו\"ם משא\"כ כאן בהנוש' אשה דבשעה שנשאו זא\"ז לא הי' שעת הירושה ולא היה אז שום גילוי דעת שנשא' אדעתא דמנהגא והבעל עומד עתה לפנינו ואומר שלא היה דעתו ? לישא ע\"ד שאם תמות שלא ירשנה דבזה ודאי לא עקרי דין תורה ומסיק מור\"ם וכתב (והוא מתשובת רשב\"א) וליכא בזה משום דינ' דמלכותא כו' ר\"ל של\"ת אף שלא נאמר שמתחלה נשאה אדעת' דהכי מ\"מ הלא במקום שדרו שם דנו בו בדיני עכו\"ם ובעכו\"ם אין הבעל יורש את אשתו וכשיבואו עתה לדין ידונו להן כן ועלינו לקיים דינם מכח דינא דמלכותא דינא ע\"ז כתב כיון דדין זה פסוק ועומד מד\"ת שבעל יורש את אשתו א\"צ הבעל לירד עם אבי אשתו לפני דייני עכו\"ם כי אין דינ' דמלכות' דינא אלא כו' והב\"ד יכופו לאבי אשתו שלא ילך לפני דייני עכו\"ם וק\"ל:","\u0003דלא אמרי' דינא דמלכותא אלא בדבר שיש בו הנאה למלך כו'. \u0004 עיין בד\"מ שהביא לשון הרשב\"א קצת בל' אחר ז\"ל דלא אמרי' דינא דמלכותא דינא אלא במה שהוא מדיני מלוכה אבל דינים שדנים בערכאות אין אלו ממשפט המלוכה אלא הערכאות דנין בעצמן כמו שמצאו בספרי דייניהן שאם אי אתה אומר כן בטלתם ח\"ו דיני ישראל עכ\"ל ועוד הבי' לפני זה דעת מהרי\"ק והמרדכי וכתב שכולם שווים בזה ע\"ש. ונראה דר\"ל דאפי' אם גזר המלך בהדי' לילך בתר דיני הערכאות דאין על דייני ישראל לקיים זה מכח זה דעלינו לקיים מן הדין דינ' דמלכותא דעל כזה לא אמרו אלא על דברי' מחוקי המלוכה ולפי זה צ\"ל דגם מ\"ש מור\"ם לפני זה בס\"ח ז\"ל ויש חולקין וס\"ל דבכל דבר אמרי' דד\"ד ושכן הוא עיקר ג\"כ כוונתו למ\"ש רשב\"א הנ\"ל ומ\"ש בכל דבר ר\"ל אף שאינו ממסים וארנוניות והא ראיה דגם בד\"מ כתב תחלה שלדעת המרדכי בשם התוס' אמרי' בכל דבר דינא ד\"ד וכתב מיד עלי' הא דכתב מהרי\"ק דאפי' לאותן דעות היינו דוקא לענין הנהגות של משפטי המלכים כו' ע\"ש ודו\"ק:"],["\u0003 דינו כלוקח מן הגנב כו' \u0004 שאם הוא גזלן מפורסם צריך להחזירו לבעלים והוא יתבע לגזלן ואם אינו מפורסם עשו בו תקנת השוק שנוטל דמיו מן הנגזל ומחזיר לו הגזלה והנגזל חוזר ותובע מן הגזלן עכ\"ל טור וכ\"כ הרמב\"ם ספ\"ח מהלכות גזלה שם וכ\"כ הרב המגיד שם וכ\"פ ר\"י נל\"א ח\"ד וכ\"כ הרא\"ה בס' החנוך מצוה רל\"ו וכן נראה להדיא מדברי תשו' מהר\"מ שבמרדכי ס\"פ הספינ' ע\"ש וכ\"פ בעה\"ת שער מ\"ט חלק י\"ג וכתב ג\"כ שכ\"כ הראב\"ד ע\"ש ועיקר דלא כמ\"ש ב\"י סי' שנ\"ו בשם הרשב\"א וכ\"כ הריב\"ש ס\"ס שצ\"ג בשם קצת מפרשים דבגזלן אע\"פ שאינו מפורסם לא עשו בו תקנת השוק דקול יוצא לגזלה וה\"ל כגנב מפורסם ע\"ש:","\u0003 ואינו יודע בודאי שזו גזולה כו' \u0004 עיין בסמ\"ע ס\"ק ח' עד כי כן ס\"ל להרי\"ף כו' נ\"ל שצ\"ל להראב\"ד או להרמב\"ן עיין בטור סי' שנ\"ג וב\"י שם:","\u0003 וי\"א דאפי' המוכס ישראל כו' \u0004 עיין בתשובת רשד\"ם סי' קצ\"א:","\u0003 וכן מלך ששם מס כו' \u0004 עיין בב\"י במה שחולק על הנ\"י ומדברי מהרש\"ל פ\"י דב\"ק סי' כ\"א מבואר שפוסק כנ\"י ועיין בתשובת רמ\"א סי' פ\"ו דף קע\"ג ע\"ג ודוק מיהו אישתמיטתי' למהרש\"ל שם דברי הטור שבסי' זה (ס\"י) וגם הרמב\"ם רמזו במ\"ש בכל שנה כו' ע\"ש:","\u0003 וכן מלך שכעס כו' \u0004 עיין בתשו' ן' לב ס\"ד דף ס\"ד וברשד\"ם סי' נ\"ה ובתשו' רמ\"א סי' ק\"ט:","\u0003 וכל שיקח מאיש זה כו' \u0004 עיין בתשו' ר\"מ אלשיך ר\"ס ס\"ה וסי' ס\"ז דף קכ\"ב ובתשו' ר\"ש כהן ס\"ב סימן פ\"א:","\u0003 ואם חקק כו' \u0004 עיין בתשוב' מהרא\"ן ששון סימן קצ\"ג ובתשו' ן' לב ס\"ג סי' ק\"י:","\u0003 אלא במסים כו' \u0004 עיין בתשו' רשד\"ם סי' רכ\"ד:","\u0003 והעכו\"ם מכר השטר כו' \u0004 ה\"ה אם נתן במתנה לישראל ויש לו עדים וראי' שנתנו לו כ\"כ בתשו' מהר\"מ מלובלין סי' כ\"ב באריכות ע\"ש:","\u0003 דלא אמרי' דינא דמלכותא כו' \u0004 ע\"ל ס\"ס ע\"ד:"]],["יֵשׁ דְּבָרִים שֶׁאָסְרוּ חֲכָמִים מִשּׁוּם גָּזֵל, וְהָעוֹבֵר עֲלֵיהֶם הֲרֵי זֶה גַּזְלָן מִדִּבְרֵיהֶם: מַפְרִיחֵי יוֹנִים וּמְשַׂחֲקִים בְּקֻבְיָא. מַפְרִיחֵי יוֹנִים כֵּיצַד, לֹא יַפְרִיחַ אָדָם בְּתוֹךְ הַיִּשּׁוּב, שֶׁהֲרֵי לוֹקֵחַ מָמוֹן אֲחֵרִים שֶׁלֹּא כַּדִּין, מִפְּנֵי שֶׁמְּשַׁלֵחַ זָכָר \u0010y0\u0011 וְיָבִיא נְקֵבָה מִשּׁוֹבָךְ אַחֵר, אוֹ נְקֵבָה וְתָבִיא זָכָר; וְלֹא יוֹנִים בִּלְבַד, אֶלָּא כָּל הָעוֹשֶׂה כָּזֶה בִּשְׁאָר עוֹפוֹת \u0010y1\u0011 אוֹ חַיָּה אוֹ בְּהֵמָה, הֲרֵי זֶה גַּזְלָן מִדִּבְרֵיהֶם.\nהַמְשַׂחֲקִים בְּקֻבְיָא כֵּיצַד, אֵלּוּ שֶׁמְּשַׂחֲקִים בְּעֵצִים אוֹ בִּצְרוֹרוֹת אוֹ בָּעֲצָמוֹת, וְעוֹשִׂים תְּנַאי בֵּינֵיהֶם שֶׁכָּל הַנּוֹצֵחַ אֶת חֲבֵרוֹ בְּאוֹתוֹ שְׂחוֹק יִקַּח כָּךְ וְכָךְ. וְכֵן הַמְשַׂחֲקִים בִּבְהֵמָה אוֹ בְּחַיָּה אוֹ בְּעוֹפוֹת, וְעוֹשִׂים \u0005(תְּנַאי)\u0006 שֶׁכָּל שֶׁתְּנַצֵּחַ בְּהֶמְתּוֹ אוֹ תָרוּץ יוֹתֵר יִקַּח מֵחֲבֵרוֹ כָּךְ וְכָךְ, וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ, הַכֹּל אָסוּר, \u0010y2\u0011 וְגָזֵל מִדִּבְרֵיהֶם הוּא.\n\u0005(טוּר הֵבִיאוֹ בס\"ו)\u0006 יֵשׁ מִי שֶׁאוֹמֵר, \u0010y3\u0011 שֶׁהַמְשַׂחֵק בְּקֻבְיָא עִם הַגּוֹי אֵין בּוֹ מִשּׁוּם גָּזֵל, אֲבָל יֵשׁ בּוֹ אִסוּר עוֹסֵק בִּדְבָרִים בְּטֵלִים, שֶׁאֵין רָאוּי לָאָדָם שֶׁיַּעֲסֹק כָּל יָמָיו, אֶלָּא בְּדִבְרֵי חָכְמָה וְיִשּׁוּבוֹ שֶׁל עוֹלָם. וְחָלְקוּ עָלָיו לוֹמַר שֶׁאֵינוֹ פָסוּל \u0010y4\u0011 אֶלָּא אִם כֵּן אֵין לוֹ אֻמָּנוּת אַחֶרֶת. \u0005הַגָּה: אֲבָל אִם יֵשׁ לוֹ אֻמָּנוּת אַחֶרֶת, אֲפִלּוּ מְשַׂחֵק עִם יִשְׂרָאֵל אֵינוֹ פָסוּל (טוּר)\u0006. וע\"ל סִימָן ר\"ז \u0005(סָעִיף י\"ג)\u0006. וּכְבָר פָּשַׁט הַמִּנְהָג כַּסְּבָרָא הָאַחֲרוֹנָה לִשְׂחוֹק בְּקֻבְיָא, וְאֵין פָּסוּל אֶלָּא מִי שֶׁאֵין לוֹ אֻמָּנוּת אֶלָּא הוּא. וְאִם שָׂחַק עִמּוֹ בַּאֲמָנָה אִם חַיָּב לְשַׁלֵּם, עַיִּןִ לְעֵיל סִימָן ר\"ז \u0005(וְשָׁם)\u0006. \u0010y5\u0011\nהַפּוֹרֵשׁ מְצוּדָה שֶׁאֵין לָהּ בֵּית קִבּוּל, וְצָד חַיָּה אוֹ עוֹף אוֹ דָגִים, וּבָא אַחֵר וּנְטָלָהּ, הֲרֵי זֶה גָּזֵל מִדִּבְרֵיהֶם. \u0005וְאִם יֵשׁ לוֹ בֵּית קִבּוּל, הֲרֵי זֶה גַּזְלָן דְּאוֹרַיְתָא (טוּר ס\"ט)\u0006.\nעָנִי הַמְנַקֵּף בְּרֹאשׁ הַזַּיִת זֵיתִים שֶׁל שִׁכְחָה, וְנָפְלוּ לָאָרֶץ, עַד שֶׁלֹּא נְטָלָם בְּיָדוֹ אִם בָּא אַחֵר וּנְטָלָם הֲרֵי זֶה גָּזֵל מִדִּבְרֵיהֶם. \u0005וְאִם כְּבָר בָּאוּ לְיָדוֹ, הֲרֵי זֶה גָּזֵל גָּמוּר וּמוֹצִיאִין מִיָּדוֹ (טוּר ס\"י)\u0006. \u0010c0\u0011\nהַגּוֹזֵל נְחִיל דְּבוֹרִים אוֹ שֶׁמְּנָעָם מִבְּעָלָיו אִם בָּאוּ לִרְשׁוּתוֹ, הֲרֵי זֶה גָּזֵל מִדִּבְרֵיהֶם.\nכָּל מִי שֶׁיֵּשׁ בְּיָדוֹ גָּזֵל מִדִּבְרֵיהֶם אֵינוֹ יוֹצֵא מִיָּדוֹ בְּדַיָּנִים:",["\u0003ויביא נקבה משובך אחר \u0004 פי' ואין זה גזל גמור שגם בעל השובך שבאים משם לא זכה בהן קנין גמור דמעלמא קאתו להתם ורבו לשם אלא שחכמים אסרוה משום סרך גזל:","\u0003או חיה או בהמה \u0004 בדריש' כתבתי ל' הגמרא שם מפורש דדוקא בהמה דשור הבר אמרו דאין בו אלא משום גזל מדבריהם דהוא כמין חיה והולך ביערים ומביא עמו דבר הפקר וקראו בהמה מפני שיש מ\"ד שהוא מין בהמה לענין איסור חלב שבו משא\"כ שאר בהמות דאינן הולכין ליערים אלא בין שאר בהמות דיש להם בעלים ומה שמביאין עמהם יש בו משום גזל גמור:","\u0003וגזל מדבריהן הוא כן. \u0004 הוא דעת הרמב\"ן וכמ\"ש ג\"כ הטור בשמו בסי' ל\"ד ובסי' ר\"ז גם בסי' זה ובשני המקומות כתבתי דאין טעמו משום דפסק כרמי בר חמא דאמר דיש בו אסמכתא דאליביה הוה גזל גמור אלא פסק ג\"כ כרב ששת דאמר איסורא הוא משום דאינו יודע בישובו של עולם אלא שפירש דבריו דכיון שאינו יודע בישובו של עולם מסתמא אין לו ממון אלא מה שמרויח בשחוק זה ושחוק זה אסרו חז\"ל משום גזל דאינו מוחל לו שכנגדו בעין יפה אע\"פ שאינו גזל גמור וכל גזל דבריהן אינו פסול מחמתו אם לא שאוכל ממנו וכמו שכתבתי בסי' ל\"ד ומטעם זה אף שיש לו מלאכה אלא שאינה מספקת לו לאכילתו ולשאר צרכיו וצריך לאכול ג\"כ ממה שמרויח מהשחוק ה\"ז פסול ודוקא במשחק עם ישראל אבל עם עכו\"ם לא גזרו עליו רבנן כיון שאינו גזל גמור והחולקים עם הרמב\"ם ס\"ל דטעם פיסול משחק בקוביא ואינך הוא משום שכיון שאינו יודע בישובו של עולם לידע כמה קשה הרווחת המעות על ב\"א ניקל בעיניו להעיד שקר ומה\"ט אף שיש לו ממון אחר ואינו אוכל מזה הוא פסול ושאם יש לו מלאכה אחרת אפי' כל דהו שאינה מספק' הואיל ויודע ע\"י כמה קשה הרווחת הממון אינו מעיד שקר ואינו פסול לשום דבר ☜ וזהו דלא כמ\"ש הב\"י בשני המקומות הנ\"ל ובע\"ש הלך אחריו ע\"ש. וממ\"ש יתבאר לך דמ\"ש המחבר בסעיף שאחר זה ז\"ל \"וחלקו \"עליו וכו' קאי אמ\"ש בסוף סעיף זה דאסור \"וגזל \"מדבריהן \"הוא דאזה חלקו וס\"ל דאינו פסול משום גזל דאז הוי פסול אפי' יש לו אומנות שאינו מספיק וכמ\"ש ודו\"ק:","\u0003שהמשחק בקוביא עם העכו\"ם אין בו משום גזל \u0004 אע\"ג דגזל עכו\"ם אסור היינו גזל דאורייתא ועוד דהעכו\"ם לא מחשב זה לגזל אלא דעתו להקנותו למי שכנגדו בכה\"ג אלא שבישראל אסרוה מטעם שכתבתי:","\u0003אא\"כ אין לו אומנות אחרת \u0004 והטעם כמ\"ש דאז אינו יודע כמה טורח יש לאדם בממונו ונקל בעיניו להעיד שקר וכדומה לו להפסיד ממון חבירו:","\u0003הפורש מצודה כו' עני המנקף כו' \u0004 שני הדינין נכפלו בטור ובדברי המחבר לעיל בסי' רע\"ג בסי\"ד וט\"ז ע\"ש:"],["\u0003 הגוזל נחיל דבורים כו' \u0004 עיין בתשובת מהרא\"ן ששון סי' רכ\"א:"]],["\u0010y0\u0011 \u0010c0\u0011 קַרְקַע אֵינָהּ נִגְזֶלֶת לְעוֹלָם, אֶלָּא בִּרְשׁוּת בְּעָלֶיהָ עוֹמֶדֶת. \u0010c1\u0011 אֲפִלּוּ נִמְכְּרָה לְאֶלֶף, זֶה אַחַר זֶה, וְנִתְיָאֲשׁוּ הַבְּעָלִים, הֲרֵי זוֹ חוֹזֶרֶת לַנִּגְזָל בְּלֹא דָּמִים. וְכָל מִי שֶׁיָּצְאָה מִתַּחַת יָדוֹ, חוֹזֵר עַל זֶה שֶׁמְּכָרָהּ לוֹ, וְחוֹזֵר הַמּוֹכֵר הַשֵּׁנִי עַל הַמּוֹכֵר הָרִאשׁוֹן, עַד שֶׁיַּחֲזִיר הַלּוֹקֵחַ מֵהַגַּזְלָן עַל הַגַּזְלָן וְיִטֹּל מִמֶּנּוּ. \u0005וְע\"ל סִימָן רל\"ו אִם לְקָחָהּ מִגּוֹי גַּזְלָן מַה דִּינוֹ:\u0006 \u0010y1\u0011\nלְפִיכָךְ, אִם אֵרַע בָּהּ קִלְקוּל הַבָּא \u0010c2\u0011 מֵאֵלָיו, כְּגוֹן שֶׁשְּׁטָפָהּ נָהָר, אֵין אַחֲרָיוּת הַהֶפְסֵד עַל הַגַּזְלָן, שֶׁבְּחֶזְקַת בְּעָלֶיהָ עוֹמֶדֶת, וְאוֹמֵר לוֹ: הֲרֵי שֶׁלְּךָ לְפָנֶיךָ. אֲבָל אִם הִפְסִידָהּ הַגַּזְלָן בְּיָדוֹ, כְּגוֹן שֶׁחָפַר בָּהּ בּוֹרוֹת שִׁיחִין וּמְעָרוֹת, אוֹ שֶׁקָּצַץ אֶת הָאִילָנוֹת וְשִׁחֵת אֶת הַמַּעְיָנוֹת וְהָרַס אֶת הַבִּנְיָן, \u0010y2\u0011 חַיָּב לְהַעֲמִיד לוֹ בַּיִת אוֹ שָׂדֶה כְּמוֹ שֶׁהָיוּ בִּשְׁעַת הַגְּזֵלָה, אוֹ יְשַׁלֵּם דְּמֵי מַה שֶּׁהִפְסִיד. \u0005הַגָּה: וּכְשֵׁם שֶׁהַקַּרְקַע בְּחֶזְקַת הַנִּגְזָל שֶׁיָּכוֹל לוֹמַר: הֲרֵי שֶׁלְּךָ לְפָנֶיךָ, כֵּן הוּא בִּרְשׁוּתוֹ לְטוֹבָתוֹ, דְּאַף עַל גַּב דִּלְגַבֵּי מִטַּלְטְלִין \u0010c3\u0011 אֵינוֹ מְשַׁלֵּם אֶלָּא כִּשְׁעַת גְּזֵלָה, גַּבֵּי קַרְקַע אֵינוֹ כֵּן, אֶלָּא אִם נִשְׁתַּמֵּשׁ \u0010c4\u0011 וְאָכַל פֵּרוֹתֶיהָ צָרִיךְ לְשַׁלֵּם מַה שֶּׁנֶּהֱנֶה מִמֶּנָה (טוּר)\u0006.\nגָּזַל שָׂדֶה וּנְטָלוּהָ מְצִיקִין בְּכֹחַ הַמֶּלֶךְ, אִם מַכַּת מְדִינָה הִיא, כְּגוֹן שֶׁלָּקַח הַמֶּלֶךְ שָׂדוֹת אוֹ בָּתִּים שֶׁל כָּל אַנְשֵׁי הַמְּדִינָה, אוֹמֵר לוֹ: הֲרֵי שֶׁלְּךָ לְפָנֶיךָ. וְאִם מֵחֲמַת הַגַּזְלָן נִלְקְחָה, חַיָּב לְהַעֲמִיד לוֹ שָׂדֶה אַחֶרֶת.\nאָנַס הַמֶּלֶךְ אֶת הַגַּזְלָן וְאָמַר לוֹ: הַרְאֵה לָנוּ אֶת כָּל מַה שֶּׁיֵּשׁ לְךָ, וְהֶרְאָהוּ שָׂדֶה זוֹ שֶׁגָּזַל בִּכְלַל שְׂדוֹתָיו, וּנְטָלָהּ הַמֶּלֶךְ, \u0010c5\u0011 חַיָּב לְהַעֲמִיד לוֹ שָׂדֶה אַחֶרֶת כְּמוֹתָהּ, אוֹ נוֹתֵן דָּמֶיהָ:",["\u0003קרקע אינה נגזלת \u0004 כלו' אף שבמטלטלין נתבאר לעיל בסי' שנ\"ג ושס\"א ובסימני' שאחריו דנקנים להלוקח ביאוש ושנוי רשות לגמרי ואפי' אין בהם לא יאוש ולא שינוי רשות עכ\"פ תקנו שלא יוציא הנגזל מיד הלוקח עד שיתן לו כדי הדמים שנתן הלוקח כנגדן להגזלן משום תקנת השוק אבל בגזילת קרקע לא קנהו ביאוש ושינוי רשות דהקרקע לעולם בחזקת בעלי' עומדת וגם לית בו משום תקנת השוק להחזיר לו דמיו דתקנת השוק הוא כדי שלא ימנע אדם מלקנות דבר בשוק מיראה שמא הוא גנוב או גזול ואין לעמוד עליו משא\"כ בקרקע דבקל יודע של מי הי' הקרקע וק\"ל:","\u0003לפיכך אם אירע כו' \u0004 פי' כיון דאין הקרקע נגזלת ובחזקת בעליה עומדת לפיכך בין נתקלקלה ממילא או נשתבחה מאיליה הקלקול והשבח הוא להנגזל:","\u0003חייב להעמיד לו שדה אחרת \u0004 דפשע באשר הראה לו גם את זו כיון דהמלך לא אנסו אלא להראות את שלו וזו לאו שלו הוא ודומה לזה כ' הטור והמחבר לקמן בסי' שפ\"ח בריש דין מסור:"],["\u0003 קרקע כו' \u0004 וה\"ה עבדים שהוקשו לקרקעות וכמ\"ש לעיל סי' שס\"ג וה\"ה שטרות וכמ\"ש לקמן סי' שפ\"ו ס\"ק י\"ג ע\"ש:","\u0003 אפי' נמכרה כו' ונתייאשו כו' \u0004 ואע\"ג דדעת התו' והרא\"ש פרק ח\"ה גבי ולוקמה בגזלן ריש דף מ\"ד דיאוש מהני לקרקע כדאי' בירושלמי מ\"מ נמשך הטור אחר דברי הרמב\"ם משום דכן דעת רשב\"ם פ' ח\"ה שם וכ\"ד רש\"י ותו' והגה' אשר\"י ר\"פ לולב הגזול וכ\"פ הסמ\"ג דף קנ\"ב ע\"א ובהגהת מיימוני ספ\"ח מה' גזלה וז\"ל גרסי' בירושלמי וכי קרקע נגזלת א\"ר אילא אעפ\"כ יש יאוש לקרקע ואין הש\"ס שלנו סובר כן ע\"כ והיינו הנך רבנן דהגוזל בתרא (סוף דף קי\"ז) דסתם מתני' כוותייהו כל זה הוא מדברי הב\"ח לעיל סי' ל\"ז סעיף י' וכאן בסי' זה ודבריו נכונים אך מ\"ש והיינו הנך רבנן דברייתא כו' לא נהירא דהא קאמר בירושלמי אע\"פ שקרקע אין נגזלת יש יאוש לקרקע ורבנן לא קאמרי אלא דאין נגזלת אם כן אף לרבנן קאמר הכי בירושל' אלא מ\"ש ש\"ס שלנו ר\"ל סוגי' דר\"פ לולב הגזול וסוגי' דפ' ח\"ה שם גבי ולוקמה בגזלן מוכח התם כפי' רשב\"ם כי פי' תוס' שם דחוק וכן הוא בתוס' ר\"פ לולב הגזול ע\"ש:","\u0003 כגון ששטפ' נהר. \u0004 אפי' עקרה לגמרי או שירד עליה אש ושרפה לגמרי דכיון דבא ההפסד מאליו ברשות הנגזל הוא וכמ\"ש לקמן סי' שפ\"ו ס\"ק י\"ג:","\u0003 אינו משלם אלא כשעת הגזילה. \u0004 ואם עשה מלאכה בכלי ונהנה אפי' קיימא לאגרא פטור וכדלעיל סי' שס\"ג ס\"ג:","\u0003 ואכל פירותיה \u0004 או דר בבית או השכירה ולקח השכר וכה\"ג צריך לשלם מה שנהנה ממנה וע\"ל סי' שס\"ג סעי' ו':","\u0003 חייב להעמיד לו שדה אחרת כמות' \u0004 ע\"ל סי' שפ\"ז ס\"ק א' שהעליתי דדין זה קנס הוא מדרבנן ונ\"מ לענין שאם מתלא קנסו בנו אחריו ועוד נ\"מ בזה ע\"ש:"]],["גָּזַל קַרְקַע \u0010y0\u0011 וְהִפְסִידָהּ בְּיָדוֹ אוֹ שֶׁאָכַל פֵּרוֹתֶיהָ, כְּשֶׁבַּעַל הַשָּׂדֶה גּוֹבֶה דְּמֵי מַה שֶּׁהִפְסִיד הַגַּזְלָן אוֹ דְּמֵי פֵרוֹת שֶׁאָכַל, גּוֹבֶה מִנְּכָסִים בְּנֵי חוֹרִין, \u0010y1\u0011 מִפְּנֵי שֶׁהִיא כְּמִלְוָה עַל פֶּה. \u0010y2\u0011 \u0010c0\u0011 וְאִם עָמַד הַגַּזְלָן בַּדִּין וְנִתְחַיֵּב לְשַׁלֵּם, וְאַחַר כָּךְ מָכַר, גּוֹבֶה מִנְּכָסִים מְשֻׁעְבָּדִים. וְאִם לֹא עָמַד בַּדִּין אֶלָּא עַל אֶחָד מֵהֶם, אֵינוֹ מוֹעִיל לַשֵּׁנִי לִהְיוֹת טוֹרֵף מִמְּשַׁעְבְּדֵי.\nוְהוּא הַדִּין אִם \u0010y3\u0011 גְּזָלוּהוּ מֵהַגַּזְלָן מַחֲמָתוֹ, שֶׁחַיָּב לְהַעֲמִיד לוֹ שָׂדֶה. אִם עָמַד בְּדִין וְאַחַר כָּךְ מָכַר, גּוֹבֶה הַנִּגְזָל מִמַּה שֶׁמָּכַר.\nגָּזַל שָׂדֶה וְהִשְׁבִּיחָהּ, וְהַנִּגְזָל בָּא לְטוֹרְפָהּ, שָׁמִין לוֹ וְיָדוֹ עַל הַתַּחְתּוֹנָה; אִם הַשֶּׁבַח יֶתֶר עַל הַהוֹצָאָה נוֹטֵל הַהוֹצָאָה בִלְבַד מֵהַנִּגְזָל; וְאִם הַהוֹצָאָה יְתֵרָה עַל הַשֶּׁבַח, אֵין לוֹ מֵהַהוֹצָאוֹת אֶלָּא שִׁעוּר הַשֶּׁבַח:",["\u0003והפסידה בידו \u0004 פי' לאפוקי הפסד דממילא דאין עליו לשלמו כיון דאין קרקע נגזלת וכמ\"ש בסי' שלפני זה:","\u0003מפני שהיא כמלוה ע\"פ \u0004 י\"מ שמ\"ה כ' הטור והמחבר \"כמלוה \"בכף הדמיון ללמדינן דאע\"פ דהוא מלוה הכתובה בתורה שכל גזלן מחויב לשלם כל מה שהפסיד אפ\"ה אינו גובה אלא מנכסים בנ\"ח כיון דאין לו קול כמה הפסיד וכמה פירות אכל אבל ז\"א דא\"כ הל\"ל כן גם בגזל מטלטלים אלא מ\"ה כ\"כ ללמדינו דאעפ\"י דגזילת קרקע גופא יש לו קול מ\"מ הפסד פירותיה אין לו קול וכמלוה ע\"פ דמי:","\u0003ואם עמד הגזלן וכו' \u0004 דמעשה ב\"ד יש לו קול וכמ\"ש בסי' ל\"ט וס\"א:","\u0003גזלוהו מהגזלן מחמתו \u0004 פי' שלא הי' מכת מדינה או שצו' עליו המלך להראות שדותיו והראה גם את זו שחייב להעמיד לו כו' וכמו שכתב המחבר בסוף סי' שלפני זה בס\"ג:"],["\u0003 ואם עמד הגזלן בדין ונתחייב לשלם כו' \u0004 והוא בענין שאין הגזלן יכול לומר פרעתי דאל\"כ אינו גובה מנכסים משועבדים כמו שהוכחתי לעיל סי' ע\"ט ס\"ק ל' ואפי' גזל בעדים הא קיי\"ל דא\"צ להחזיר לו בעדים וכמ\"ש לעיל ס\"ס שס\"א:"]],["\u0010c0\u0011 גָּזַל שָׂדֶה וּמְכָרָהּ וְהִשְׁבִּיחָהּ הַלּוֹקֵחַ, אִם הַשֶּׁבַח יוֹתֵר עַל הַהוֹצָאָה \u0010y0\u0011 נוֹטֵל הַהוֹצָאָה מִבַּעַל הַשָּׂדֶה, \u0005וְיֵשׁ אוֹמְרִים אֲפִלּוּ לֹא הָיְתָה עֲדִיפָא מִבְּשָׁעָה שֶׁגְּזָלָהּ, \u0010y1\u0011 כְּגוֹן שֶׁהִכְסִיפָהּ הַגַּזְלָן, אֲפִלּוּ הָכִי נוֹטֵל הַיְצִיאָה מֵהַנִּגְזָל (נִמּוּקֵי יוֹסֵף בפ\"ק דִּמְצִיעָא בְּשֵׁם הָרַ\"ן)\u0006, \u0010y2\u0011 וְיֵשׁ חוֹלְקִין \u0005(שָׁם בְּשֵׁם רַשִׁ\"י)\u0006, וְהַקֶּרֶן \u0010y3\u0011 \u0010c1\u0011 עִם שְׁאָר הַשֶּׁבַח נוֹטֵל מֵהַגַּזְלָן. הַקֶּרֶן, גּוֹבֶה מִנְּכָסִים \u0010c2\u0011 מְשֻׁעְבָּדִים, וּשְׁאָר הַשֶּׁבַח מִנְּכָסִים בְּנֵי חוֹרִין. וְאִם הִכִּיר בָּהּ שֶׁהִיא גְזוּלָה כְּשֶׁלְּקָחָהּ, אֵינוֹ נוֹטֵל מֵהַגַּזְלָן \u0010y4\u0011 \u0010c3\u0011 אֶלָּא הַקֶּרֶן בִּלְבַד, \u0010c4\u0011 וּמַפְסִיד שְׁאָר הַשֶּׁבַח הַיָּתֵר עַל הַהוֹצָאָה. הָיְתָה הַהוֹצָאָה יְתֵרָה עַל הַשֶּׁבַח, בֵּין שֶׁהִכִּיר בָּהּ שֶׁהָיְתָה גְזוּלָה בֵּין שֶׁלֹּא הִכִּיר, \u0010c5\u0011 אֵין לוֹ מֵהַהוֹצָאָה אֶלָּא שִׁעוּר הַשֶּׁבַח, וְנוֹטְלוֹ מִבַּעַל הַשָּׂדֶה, \u0010c6\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּהוֹאִיל וְיָדַע שֶׁאֵינָה שֶׁלּוֹ, הִפְסִיד אֲפִלּוּ הַהוֹצָאָה (טוּר ס\"א בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006. \u0010y5\u0011 וְיֵשׁ אוֹמְרִים דְּאִם קִבֵּל אַחֲרָיוּת בְּהֶדְיָא צָרִיךְ לִתֵּן כְּפִי מַה שֶּׁקִּבֵּל עָלָיו \u0005(שָׁם בְּשֵׁם הרמ\"ה וּתְשׁוּבַת הָרַשְׁבָּ\"א בְסִימָן אֶלֶף קנ\"ה וְכֵן כָּתַב הָרִיבָ\"שׁ בְּסִימָן ר\"ן בִּשְׁמוֹ וְהַמ\"מ פ\"ט דִּגְזֵלָה בְּשֵׁם יֵשׁ אוֹמְרִים)\u0006. וְיֵשׁ חוֹלְקִין \u0005(שָׁם בְּשֵׁם אָבִיו הָרֹא\"שׁ וְהַמַּגִּיד פֶּרֶק ח' דִּגְזֵלָה ונ\"י פֶרֶק קַמָּא דִמְצִיעָא, וְגַם הָרַ\"ן כָּתַב דְּלָא מְחֻוָּר בְּעֵינָיו)\u0006. וְהַקֶּרֶן נוֹטֵל מֵהַגַּזְלָן מִנְּכָסִים מְשֻׁעְבָּדִים.\nהַפֵּרוֹת שֶׁאָכַל לוֹקֵחַ בְּעוֹד שֶׁהָיְתָה בְּיָדוֹ, צָרִיךְ לְשַׁלֵּם אוֹתָם לַנִּגְזָל, וְדִינוֹ בָּהֶם עִם הַגַּזְלָן כְּדִינוֹ שֶׁל שֶׁבַח, שֶׁאִם יָדַע שֶׁהָיְתָה גְּזוּלָה גּוֹבֶה אוֹתָם מֵהַגַּזְלָן מִנְּכָסִים בְּנֵי חוֹרִין, וְאִם יָדַע שֶׁהָיְתָה גְזוּלָה \u0010c7\u0011 \u0010c8\u0011 אֵינוֹ גּוֹבֶה מֵהֶם כְּלוּם.\nאִם טָעַן הַמּוֹכֵר שֶׁהַלּוֹקֵחַ יָדַע שֶׁהָיְתָה גְּזוּלָה, וְהַלּוֹקֵחַ טָעַן שֶׁלֹּא יָדַע, \u0010y6\u0011 עַל הַמּוֹכֵר לְהָבִיא רְאָיָה:",["\u0003נוטל ההוצאה מבעל השדה דהא גם כשהיתה ביד הנגזל הי' צריך להוציא הוצאה זו מכיסו:\u0004","\u0003כגון שהכסיפ' הגזלן \u0004 פי' בשעה שהית' ביד הגזלן הכסיפ' ונגרע' ממה שהיתה בשעת הגזילה ואח\"כ מכרה ללוקח זה והשביח' הלוקח עד שחזרה להיות כמו שהיתה בשעת הגזילה:","\u0003ויש חולקין \u0004 טעמן הוא כיון דאם נשאר בידו לא הי' צריך להוצאה זו נמצא דהוצאה זו דין הוצא' היתיר' על השבח יש לו עליו:","\u0003עם שאר השבח נוטל מהגזלן \u0004 דהיו רגילין לכתוב אחריות עמליהן ושבחיהון ואפי' לא כתב ככתוב דמי וכמ\"ש בס\"ס מ\"ב:","\u0003אלא הקרן בלבד \u0004 ז\"ל הטור כיון דידע הלוקח בשעה שלקחה דגזולה היתה לא נתן לו הדמים בשביל' בתורת מקח אלא בהלואה ואם היה נוטל יותר ממה שנתן לו הי' מחזי כריבית עכ\"ל ובשבח דממילא כ\"ע ס\"ל דאינו נוטל אבל בשבח דע\"י הוצא' פליגי דהרי\"ף ס\"ל דנוטל דמי ההוצאה וידו על התחתונה דכיון דהוציא דמי ההוצאה נוסף על דמי הקרן לא מחזי ריבית במה שחוזר ולוקח כמה שהוציא וכדמסיק המחבר והי\"א והרא\"ש ס\"ל דגם זה אינו נוטל וכמ\"ש מור\"ם בהג\"ה:","\u0003דאם קיבל אחריות בהדיא כו' \u0004 בטור כ' בשם הרמ\"ה בעל סברא זו דהיינו דוקא כשקיבל עליו אחריות דשבח בפירוש וג\"כ קנו מני' ע\"ז אי אית לי' קרקע (דאז לא מחזי כריבית מה שגובה בקרקע כ\"א כשגובה מעות כעין שנתן לו דה\"ל כהלואה כנ\"ל ועפ\"ר) אבל אי לא קיבל עליו אחריות דשבח בפירוש אף על גב דקיבל עליו אחריות דזביני מסתמא מאי דקיבל עליו קיבל ומאי דלא קיבל עליו לא קיבל עכ\"ל וע\"ש בטור דמשמע דאפי' להרא\"ש דחולק וס\"ל דאפי' קיבל בפי' עליו השבח דאינו נוטל שבח ל\"פ אם יש לו קרקעי ומטעם שכתבתי ומהתימ' על הגאונים המחבר ומהרי\"ק שלא כתבו דין זה דאם יש לו קרקע כלל:","\u0003על המוכר להביא ראייה \u0004 דחזקה הוא דלא שדי אינש זוזי בכדי ובודאי לא ידע שהיא גזולה בשעה שקנאה:"],["\u0003 גזל שדה כו' \u0004 עיין בתשו' מבי\"ט ח\"א בשאלות השניות סי' כ\"ז דף קי\"א:","\u0003 עם שאר השבח \u0004 אפי' לא פירש לו השבח דאחריות ט\"ס הוא בין בקרן בין בשבח:","\u0003 ושאר השבח מנכסים בני חורין \u0004 עיין מזה לעיל סי' קט\"ו ס\"א:","כתב בכלבו סי' קכ\"ג אות י\"ב וז\"ל ראובן קנה משמעון חומש בזקוק והוסיף והוציא בנקודה ובמסורה והשביחו ועמד על ג' זקוקי' שנתייקר ואח\"כ נמצא גזול ביד המוכר וטרפו הנגזל מיד ראובן הלוקח וחזר ראובן על שמעון לתבוע הכל דין הוא שישלם שמעון ג' זקוקים כרב דאמר המוכר שדה שאינו שלו אפי' שבח יש לו כן פסק רבא עכ\"ל והוא מדברי ראב\"ן פ\"ק דמציעא ד' צ\"ג ע\"א ואין דבריו נראין לי דהך דפסק רבא פ\"ק דמציעא דוקא בקרקע הוא אבל לא במטלטלים וכדאית' פרק הגוזל קמא ובתוס' שם ובהרא\"ש פרק קמא דמציע' עיש ודו\"ק וכן לעיל שנ\"ד ובסי' שס\"ב ס\"ח בהג\"ה ע\"ש:","\u0003 אלא הקרן בלבד \u0004 וקרן מיהא שקול אף שידע שגזלה וכן במטלטלים הדין כן וכמ\"ש הב\"ח והאריך בזה וכבר כתבתי בזה לעיל סי' שנ\"ו:","\u0003 ומפסיד שאר השבח כו' \u0004 כתב הסמ\"ע ס\"ק ה' דבשבח דממילא כ\"ע ס\"ל דאינו נוטל אבל בשבח שע\"י הוצאה פליגי דהרי\"ף ס\"ל דנוטל דמי ההוצאה וידו על התחתונה וכדמסיק המחבר והי\"א והרא\"ש ס\"ל דגם בזה אינו נוטל כמ\"ש מור\"ם בהג\"ה עכ\"ל וכבר השגתי על זה לקמן ס\"ק ז':","\u0003 אין לו מההוצאה כו' \u0004 ע' בתשו' מהר\"ש כהן ס' ב' סי' פ\"א ובתשו' מהרשד\"ם סי' רס\"ד:","\u0003 וי\"א דהואיל וידוע שאינו שלו הפסיד אפי' ההוצא': \u0004 אף שהטור כתב כן הוא תמוה לפע\"ד דהלא אפי' הגזלן עצמו נוטל ההוצאה וכמ\"ש הטור גופיה בס\"ס הקודם והוא פשוט כמ\"ש ה' המ' וב\"י בס\"ס הקודם גם מ\"ש הטור כן בשם התוס' והרא\"ש הוא תמוה לפע\"ד דלא אמרו התו' והרא\"ש אלא דאין לו שבח היתר על ההוצא' ופליגי על הרי\"ף במה דמשמע לי' להרא\"ש מדבריו דאפי' השבח היתר על ההוצאה נוטל כיון דבא השבח מחמת הוצאה ולא השבח ממילא (ודלא כמו שהבין הטור מדבריו) והיינו דכתב הרא\"ש דלא נטל שבחא מטעם דכיון דקרקע אינה נגזלת לא עביד רבנן תקנתא דליקנינהו ואי בשבח שכנגד הוצאה לא צריך לתקנתא דרבנן דליקנינהו אלא שלו הוא נוטל כדין יורד שלא ברשות דנוטל ההוצאה לכ\"ע אע\"ג דלא קני לארעא והיינו נמי דמסיים הרא\"ש וכן כתב הרז\"ה והנה ז\"ל הרז\"ה בס' המאור וכל דברי הרי\"ף ז\"ל בזו השמועה אינם נכונים כו' דאפי' שבח דמחמת הוצאה לית ליה מהנגזל לעולם אלא הוצאה שיש שבח כנגדה וההוא דאמר רבא מה שהשביח מכר מה שהשביח הוריש לענין גזילת מטלטלים אתמר דגזלן קונה בשינוי ואין זו ראיה לגזלת קרקע דקרקע אינה נגזלת וכ\"כ ה\"ר אפרים עכ\"ל וכן משמע להדיא בתוס' פ' הגוזל קמא ע\"ש בדף צ\"ה ע\"א ד\"ה דאתא בעל ארעא כו' ובדף צ\"ו ד\"ה כל זכות כו' ועור דהא כתב הרא\"ש שם לעיל מיניה כשני עמודים לפני זה וז\"ל והדין דינא דלוקח בהדי נגזל וגזלן היכא דזבין לוקח ארעא מגזלן ולא ידע שהיתה גזולה ואשבח ואתא נגזל ואפק' מידא דלוקח שקול נגזל לכולא שבחא ושיימינן לשבחא אי הוה יותר על ההוצאה שקול ההוצאה מנגזל כדין יורד שלא ברשות ומותר השבח שקול מגזלן ואם ידע שהיתה גזולה אין לו אלא הוצאה בלבד מנגזל ואעפ\"י שידע שהיא גזולה יהיב ליה נגזל הוצאה כמו יורד שלא ברשות ומותר השבח לא שקיל מגזלן כדפסק רבא בהכיר בה שאינו שלו דאין לו שבח עכ\"ל הרי להדיא דההוצאה נוטל עכ\"פ ולדעת הטור נצטרך לומר דלעיל כתב כן לשטת הרי\"ף וזה דוחק גדול אלא הדבר פשוט דההוצאה נוטל עכ\"פ לכ\"ע וכן משמע להדיא בבעל העיטור במאמר אחריות דף י' ע\"ב שהביא שם דברי הרי\"ף והשיג עליו ככל השגות הרז\"ה והרא\"ש באריכות וכתב שכ\"כ ה\"ר אפרים ע\"ש ואח\"כ כתב בריש עמוד ג' הכיר בה שאינו שלו ולקחה אפי' יש לו לגזלן קרקע או קנו מידו אין לו אלא הוצאה מנגזל בלבד ושאר שבחא פסיד ליה כדרבא דאמר הכיר בה שאינו שלו ולקח' מעות יש לו שבח אין לו אלא הוצאת שבח מנגזל הדין הוא דינא דלוקח מגזלן עכ\"ל הרי להדיא דהוצאה שקיל מנגזל עכ\"פ לכ\"ע: וגם מ\"ש בב\"י אחר דברי הרא\"ש דהרמב\"ם בפ\"ט מה' גזילה (הם דבריו שהעתיק המחבר כאן) הם כדברי הרי\"ף וכן הלכה עכ\"ל אינו נכון דאדרבה דעת הרמב\"ם כהרא\"ש אלא שי\"ל שהרמב\"ם סובר דהרי\"ף מיירי בשבח שכנגד הוצאה וכמו שמפרש הרמב\"ן בספר המלחמות דברי הרי\"ף כן ומ\"מ זכינו לדין דשבח שכנגד הוצאה נוטל עכ\"פ מהנגזל ודלא כהטור והר\"ב וכ\"כ ר' ירוחם נל\"א ח\"ד בפשיטות דההוצא' נוטל מהנגזל ע\"ש (וכ\"כ המרדכי ר\"פ הגוזל קמא) וכן עיקר:","\u0003 אינו גובה מהם כלום \u0004 עיין בתשו' ר\"מ אלשיך סימן כ\"ג:"]],["הַגּוֹזֵל שָׂדֶה וּמְכָרָהּ אוֹ נְתָנָהּ לְאַחֵר, \u0010y0\u0011 שֶׁאֵין מַעֲשָׂיו כְּלוּם כְּמוֹ שֶׁנִּתְבָּאֵר, אִם אַחַר כָּךְ קְנָאָהּ הַגַּזְלָן מֵהַנִּגְזָל, \u0010y1\u0011 נִתְקַיְּמָה בְּיַד הַלּוֹקֵחַ מֵהַגַּזְלָן אוֹ בְּיַד הַמְקַבֵּל הַמַּתָּנָה מִמֶּנּוּ, שֶׁמִּפְּנֵי זֶה טָרַח הַגַּזְלָן לִקְנוֹתָהּ, כְּדֵי לַעֲמֹד בְּנֶאֱמָנוּתוֹ. \u0010y2\u0011 לְפִיכָךְ, אִם לֹא קְנָאָהּ עַד שֶׁתָּבַע הַלּוֹקֵחַ אֶת הַגַּזְלָן, כְּגוֹן שֶׁמָּכַר לוֹ הַשָּׂדֶה שֶׁאֵינָהּ שֶׁלּוֹ וְנִתְחַיֵּב לְשַׁלֵּם וְהִתְחִיל בֵּית דִּין לְהַכְרִיז עַל נִכְסֵי הַגַּזְלָן כְּדֵי לְהַגְבּוֹת מֵהֶם לַלּוֹקֵחַ, וְאַחַר כָּךְ קְנָאָהּ הַגַּזְלָן מֵהַנִּגְזָל, לֹא נִתְקַיְּמָה בְּיַד הַלּוֹקֵחַ וְיָכוֹל הַגַּזְלָן עַצְמוֹ אוֹ יוֹרְשָׁיו לָתֵת לוֹ מָעוֹתָיו וּלְהוֹצִיאָהּ מִיָּדוֹ.\nלְקָחָהּ הַגַּזְלָן מֵהַנִּגְזָל אַחַר שֶׁמְּכָרָהּ כְּשֶׁהִיא גְזוּלָה, וְחָזַר וּמְכָרָהּ לְאַחֵר אוֹ נְתָנָהּ בְּמַתָּנָה אוֹ הוֹרִישָׁהּ, \u0010y3\u0011 הֲרֵי זֶה גִּלָּה דַעְתּוֹ שֶׁאֵינוֹ רוֹצֶה לְהַעֲמִידָהּ בְּיַד זֶה שֶׁלְּקָחָהּ מִמֶּנּוּ כְּשֶׁהָיְתָה גְּזוּלָה. וְכֵן אִם נָפְלָה לַגַּזְלָן בִּירֻשָּׁה, לֹא נִתְקַיְּמָה בְּיַד הַלּוֹקֵחַ. \u0005הַגָּה: וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּאִם מְכָרָהּ אוֹ נְתָנָהּ לְאַחַר שֶׁקְּנָאָהּ, הַלּוֹקֵחַ רִאשׁוֹן קָנָה. אֲבָל אִם מְכָרָהּ אוֹ נְתָנָהּ קֹדֶם שֶׁקְּנָאָהּ, לֹא קָנָה לוֹקֵחַ רִאשׁוֹן (טוּר ס\"ב וּבֵית יוֹסֵף בְּשֵׁם רַשִׁ\"י)\u0006. וְכָל זֶה לֹא מַיְרֵי אֶלָּא בְּשֶׁלֹּא הִכִּיר בָּהּ שֶׁהִיא גְּזוּלָה, וּקְנָאָהּ. אֲבָל אִם הִכִּיר בָּהּ וּקְנָאָהּ, לֹא קָנָה לוֹקֵחַ \u0005(הַמַּגִּיד פ\"ט דִּגְזֵלָה וְרַ\"ן וְנִמּוּקֵי יוֹסֵף פֶּרֶק קַמָּא דְּבָבָא מְצִיעָא)\u0006.\nגְּבָאָהּ הַגַּזְלָן בְּחוֹבוֹ, אִם יֵשׁ לַנִּגְזָל קַרְקַע אַחֶרֶת \u0010y4\u0011 וְאָמַר לֵהּ הַגַּזְלָן: זוֹ אֲנִי גוֹבֶה בְּחוֹבִי, הֲרֵי זֶה מִתְכַּוֵּן לְהַעֲמִידָהּ בְּיַד הַלּוֹקֵחַ. וְאִם אֵין לַנִּגְזָל קַרְקַע אֶלָּא זוֹ, לִגְבּוֹת חוֹבוֹ הוּא שֶׁנִּתְכַּוֵּן.\nנְתָנוּהָ הַבְּעָלִים לַגַּזְלָן, מַתָּנָה, קְנָאָהּ הַלּוֹקֵחַ, שֶׁאִלּוּ לֹא טָרַח לַבְּעָלִים לֹא הָיוּ נוֹתְנִים לוֹ בְּמַתָּנָה, וּמִפְּנֵי זֶה טָרַח, \u0010y5\u0011 כְּדֵי שֶׁיִּזְכֶּה בָּהּ בַּדִּין וְיַעֲמֹד בְּנֶאֱמָנוּתוֹ וְתִתְקַיֵּם בְּיַד הַלּוֹקֵחַ. \u0005הַגָּה: וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּעַל הַלּוֹקֵחַ לְהָבִיא רְאָיָה שֶׁכִּוֵּן לְהַעֲמִידָהּ בְּיָדוֹ, וְאֵין מוֹצִיא מִיַּד הַגַּזְלָן. וְכֵן נִרְאֶה לִי עִקָּר (טוּר ס\"ד בְּשֵׁם הָרֹא\"שׁ, וְנ\"י פ\"ק דִּמְצִיעָא וְהַמַּגִּיד פ\"ח דִּגְזֵילָה)\u0006.\nדִּין גַּזְלָן שֶׁמֵּבִיא עֵדִים שֶׁלָּקַח שָׂדֶה מֵהַנִּגְזָל, נִתְבָּאֵר בְּסִימָן קנ\" א.\nגּוֹי שֶׁאָנַס שָׂדֶה מִיִּשְׂרָאֵל וּמְכָרָהּ לְיִשְׂרָאֵל אַחֵר, נִתְבָּאֵר בְּסִימָן רל\"ו.",["\u0003שאין מעשיו כו' \u0004 פי' שהנגזל יכול להוציאה מידו בלא דמים כמו שנתבאר בסי' שע\"א ובסימנים שאחריו:","\u0003נתקיימה ביד הלוקח כו' \u0004 ז\"ל הטור ולא אמרי' שקנה הגזלן כחו של נגזל וכמו שהנגזל יכול להוציאה מיד הלוקח כך יוציאנו גם הגזלן מידו ויתן לו מעותיו אלא אמרינן שמפני זה טרח כו' וכמ\"ש המחבר:","\u0003לפיכך אם לא קנאה כו' \u0004 דבכה\"ג הרי ראינו דלא בעי למיקם בהימנותיה מדלא טרח לזביני או לשלם קודם שתבעו:","\u0003הרי גילה דעתו שאינו כו' \u0004 דאי קנאו כדי למיקם בהימנותיה ולהעמידה ביד לוקח ראשון לא הי' מוכר' אח\"כ להאחר והחולקין ס\"ל דמיד שקנאה מהנגזל זכה בה הראשון ושוב לא מצי לבטל זכותיה במה שחזר ומכרה לאחר משא\"כ אם חזר הגזלן ומכרה לאחר קודם שקנאה מהנגזל דכ\"ע מודים דמהני גילוי דעת במה שמכרה להשני דלא זכה בה הראשון בשעה שקנאה אחר כך מהנגזל וכדמסיק מור\"ם והוא מהגמרא:","\u0003וא\"ל הגזלן זו כו' \u0004 ז\"ל הטור ולא רצה לגבות חובו אלא מזאת כו' ובפרישה כתבתי דלאו דוקא קאמר הטור אלא אפי' גבאו משדה זו סתמא ג\"כ אמרינן דעתו היה להעמיד ביד הלוקח ומ\"ה דקדק המחבר והשמיט הני תיבות \"דלא \"רצה \"אלא \"זאת דהרי בסיפא דוקא באין לנגזל קרקע אחרת אלא זו אמרי' דלא מהני וק\"ל ולא כע\"ש שהניח ל' הש\"ע ותפס ל' הטור וכתב \"ולא \"רצה \"אלא \"זאת:","\u0003כדי שיזכה בה בדין \u0004 פי' שעד הנה היתה בידו בגזלנות' והיה נקרא גזלן על מכירתו משא\"כ לאחר שיקבלהו במתנה שיהיה בידו בדין ולא בתורת גזלנות':"],[]],["\u0010c0\u0011 הַיּוֹרֵד לְתוֹךְ שְׂדֵה חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וּנְטָעָהּ, אִם הָיְתָה שָׂדֶה הָעֲשׂוּיָה \u0010y0\u0011 לִטַּע, אוֹמְדִין כַּמָּה אָדָם רוֹצֶה לִתֵּן בְּשָׂדֶה זוֹ לְנוֹטְעָהּ, וְנוֹטֵל מִבַּעַל הַשָּׂדֶה. וְאִם אֵינָהּ עֲשׂוּיָה לִטַּע, שָׁמִין לוֹ \u0010y1\u0011 וְיָדוֹ עַל הַתַּחְתּוֹנָה. \u0005הַגָּה: \u0010y2\u0011 סְתָם כֶּרֶם עָשׂוּי לִטַּע (רִיבָ\"שׁ סִימָן תתקט\"ו)\u0006. הָעוֹשֶׂה טוֹבָה לַחֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, עַיֵּן לְעֵיל סִימָן רס\"ד. וְכֵן הַלּוֹמֵד עִם חֲבֵרוֹ בְּלֹא דַעַת הָאָב, עַיֵּן לְעֵיל סִימָן של\"ה \u0010c1\u0011 \u0005(סָעִיף א')\u0006.\nאָמַר לֵהּ בַּעַל הַשָּׂדֶה: עֲקֹר אִילָנְךָ וָלֵךְ, \u0010y3\u0011 שׁוֹמְעִין לוֹ. אֲבָל אִם אָמַר הַנּוֹטֵעַ: הֲרֵינִי עוֹקֵר אִילָנִי, אֵין שׁוֹמְעִין לוֹ, \u0010y4\u0011 מִפְּנֵי שֶׁמַּכְחִישׁ הָאָרֶץ.\nהַיּוֹרֵד לְתוֹךְ שְׂדֵה חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת וְנָטַע אוֹ בָּנָה, וְאַחַר כָּךְ בָּא בַּעַל הַשָּׂדֶה וְהִשְׁלִים הַבִּנְיָן, אוֹ שֶׁשָּׁמַר הַנְּטִיעוֹת וְכַיּוֹצֵא בְּאֵלּוּ הַדְּבָרִים, שֶׁמַּרְאֶה שֶׁדַּעְתּוֹ נוֹטָה לְמַה שֶּׁעָשָׂה זֶה וּבִרְצוֹנוֹ בָּא הַדָּבָר, שָׁמִין \u0010c2\u0011 וְיָדוֹ עַל הָעֶלְיוֹנָה. \u0005הַגָּה: \u0010y5\u0011 \u0010c3\u0011 מִיהוּ, אִם אָמַר לוֹ תְּחִלָּה: עֲקֹר אִילָנְךָ וָלֵךְ, יָכוֹל בַּעַל הָאִילָן לַעֲשׂוֹת, אַף עַל פִּי שֶׁחוֹזֵר בַּעַל הַשָּׂדֶה אַחַר כָּךְ (נִמּוּקֵי יוֹסֵף פֶּרֶק הַשּׁוֹאֵל)\u0006.\nהַיּוֹרֵד לִשְׂדֵה חֲבֵרוֹ בִּרְשׁוּת, אֲפִלּוּ נָטַע שָׂדֶה שֶׁאֵינָהּ עֲשׂוּיָה \u0010y6\u0011 לִטַּע, שָׁמִין לוֹ וְיָדוֹ עַל הָעֶלְיוֹנָה; \u0010y7\u0011 שֶׁאִם הָיְתָה הַהוֹצָאָה יְתֵרָה עַל הַשֶּׁבַח, נוֹטֵל הַהוֹצָאָה; וְאִם הַשֶּׁבַח יְתֵרָה עַל הַהוֹצָאָה, נוֹטֵל הַשֶּׁבַח. \u0005וְאִם בַּעַל הַשָּׂדֶה הוּא עַצְמוֹ אָרִיס, חָזַר לִהְיוֹת דִּינוֹ כְּאֵינוֹ עָשׂוּי לִטַּע, רַק שֶׁשָּׁמִין כַּמָּה רוֹצֶה לִתֵּן שֶׁלֹּא יִצְטָרֵךְ לִטְרֹחַ בְּעַצְמוֹ (נִמּוּקֵי יוֹסֵף פֶּרֶק הָאִשָּׁה \u0010c4\u0011 שֶׁנָּפְלוּ)\u0006.\nבַּעַל בְּנִכְסֵי מְלוֹג \u0010y8\u0011 אִשְׁתּוֹ קְטַנָּה, \u0010y9\u0011 וְהַשֻּׁתָּף בַּשָּׂדֶה שֶׁיֵּשׁ לוֹ חֵלֶק בָּהּ, \u0010y10\u0011 כְּיוֹרֵד בִּרְשׁוּת הֵן וְשָׁמִין לָהֶם וְיָדָם עַל הָעֶלְיוֹנָה. \u0005(וְע\"ל ס\"ס קע\"ח וס\"ס ת\"ד)\u0006.\nהַיּוֹרֵד לְתוֹךְ חֻרְבָתוֹ שֶׁל חֲבֵרוֹ וּבְנָאָהּ שֶׁלֹּא בִּרְשׁוּת, שָׁמִין לוֹ וְיָדוֹ עַל הַתַּחְתּוֹנָה. וְאִם אָמַר בַּעַל הַבִּנְיָן: עֵצַי וַאֲבָנַי אֲנִי נוֹטֵל, \u0010y11\u0011 שׁוֹמְעִין לוֹ \u0005(שָׁם ד\"ה)\u0006. אָמַר לֵהּ בַּעַל הַקַּרְקַע: טֹל מַה שֶּׁבָּנִיתָ, שׁוֹמְעִין לוֹ. \u0005הַגָּה: \u0010y12\u0011 \u0010c5\u0011 וְדַוְקָא אִם הַחֻרְבָה אֵינָהּ עֲשׂוּיָה לִבְנוֹת; אֲבָל אִם עֲשׂוּיָה לִבְנוֹת, אוֹ בְמָקוֹם שֶׁסְּתַם חֻרְבָה עוֹמֶדֶת לִבְנוֹת, דִּינוֹ כְּמוֹ חֲצֵרוֹת, שֶׁיִּתְבָּאֵר בְּסָמוּךְ (בֵּית יוֹסֵף בְּשֵׁם תַּלְמִידֵי רַשְׁבָּ\"א (וְהָרַמְבַּ\"ם פ\"ו דִּגְזֵלָה)\u0006 וּמָרְדְּכַי פֶּרֶק הַשּׁוֹאֵל).\n\u0005(רַמְבַּ\"ם פ\"י דִּגְזֵלָה טוּר הֵבִיאוֹ ס\"ט)\u0006 הַחֲצֵרוֹת הֲרֵי הֵם רְאוּיִים לְבִנְיָן וּלְהוֹסִיף בָּהֶם בָּתִּים וַעֲלִיּוֹת. לְפִיכָךְ, הַבּוֹנֶה בַּחֲצַר חֲבֵרוֹ, הֲרֵי זֶה כְּנוֹטֵעַ שָׂדֶה הָעֲשׂוּיָה לִטַּע, וְשָׁמִין לוֹ כַּמָּה אָדָם רוֹצֶה לִתֵּן בְּבִנְיָן זֶה לִבְנוֹתוֹ; וְהוּא שֶׁיִּבְנֶה בִּנְיָן הַמּוֹעִיל הָרָאוּי לְאוֹתָהּ חָצֵר כְּמִנְהַג אוֹתוֹ מָקוֹם. \u0005הַגָּה: (הראב\"ד וּמָרְדְּכַי)\u0006 \u0010y13\u0011 וְלֹא יוּכַל הַבּוֹנֶה לוֹמַר: בִּנְיָנִי אֲנִי נוֹטֵל. הִשְׂכִּירָהּ הַבּוֹנֶה לַאֲחֵרִים וְקִבֵּל שָׂכָר, מְנַכִּין לוֹ מֵהוֹצָאוֹתָיו, אַף עַל גַּב דְּלָא עָבִיד לְמֵיגָר \u0005(רַשְׁבָּ\"א ונ\"י פֶרֶק הַשּׁוֹאֵל)\u0006. וְאִם דָּר בָּהּ הַבּוֹנֶה, אִם חִסַּר לְבַעַל הַקַּרְקַע דָּבָר מוּעָט, צָרִיךְ לִתֵּן לוֹ כָּל מַה שֶּׁנֶּהֱנָה, \u0010y14\u0011 כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שס\"ג \u0005(מֵישָׁרִים נל\"א ח\"ב)\u0006. רְאוּבֵן שֶׁהָיָה לוֹ בַּיִת רָעוּעַ וְיָצָא מִן הָעִיר, וּבָא שִׁמְעוֹן וְדָר בּוֹ וְהוֹצִיא הוֹצָאוֹת לְהַצִּיל הַבַּיִת מִן הַנְּפִילָה וְסִיְּדוֹ וְכִיְּדוֹ, כָּל מַה שֶּׁהָיָה לְצֹרֶךְ שֶׁלֹּא יִפֹּל צָרִיךְ רְאוּבֵן לְהַחֲזִיר לְשִׁמְעוֹן, \u0010y15\u0011 אֲבָל אֵין צָרִיךְ לִתֵּן לוֹ מַה שֶּׁסִּיְדוֹ וְכִיְּדוֹ, כִּי יוּכַל לוֹמַר: אֵינִי צָרִיךְ לָזֶה, וּכְשֶׁיִּתֵּן רְאוּבֵן מַה שֶּׁחַיָּב לִתֵּן לְשִׁמְעוֹן, יֵצֵא מִן הַבַּיִת \u0005(טוּר ס\"ח בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010c6\u0011\nכָּל מִי שֶׁשָּׁמִין לוֹ, \u0010y16\u0011 בֵּין שֶׁהָיְתָה יָדוֹ עַל הָעֶלְיוֹנָה בֵּין שֶׁהָיְתָה יָדוֹ עַל הַתַּחְתּוֹנָה, אֵינוֹ נוֹטֵל כְּלוּם עַד שֶׁיִּשָּׁבַע בִּנְקִיטַת חֵפֶץ כַּמָּה הוֹצִיא. \u0010y17\u0011 וְאִם אָמַר: יָבוֹאוּ הַדַּיָּנִים \u0005(ל' הַטוּר הַבַּנָּאִים)\u0006 וְיַּעֲשׂוּ שׁוּמַת הַהוֹצָאָה וַהֲרֵי הִיא גְּלוּיָה לְעֵינֵיהֶם וִישַׁעֲרוּ הָעֵצִים וְהָאֲבָנִים וְהַסִיד וּשְׂכַר הָאֻמָּנִים בְּפָחוֹת שֶׁבַּשִּׁעוּרִים, שׁוֹמְעִין לוֹ וְנוֹטֵל בְּלֹא שְׁבוּעָה. \u0010y18\u0011 וְכֵן זֶה שֶׁנּוֹטֵל הַשֶּׁבַח בִּלְבַד, וְהָיְתָה יָדוֹ עַל הָעֶלְיוֹנָה, אֵינוֹ צָרִיךְ שְׁבוּעָה.\nכָּל שֶׁשָּׁמִין לוֹ וְנוֹטֵל, שֶׁטָּעַן בַּעַל הַשָּׂדֶה וְאָמַר: נָתַתִּי, וְהַיּוֹרֵד אוֹמֵר: לֹא נָטַלְתִּי, הַיּוֹרֵד נֶאֱמָן, וְנִשְׁבַּע שֶׁלֹּא נָטַל כְּלוּם, וְנוֹטֵל, \u0010y19\u0011 שֶׁהֲרֵי אוֹמְרִים לְבַעַל הַשָּׂדֶה: עֲדַיִן לֹא שָׁמוּ לְךָ, וְלֹא יָדַעְתָּ כַּמָּה אַתָּה חַיָּב לִתֵּן, הֵיאַךְ נָתַתָּ. אֲבָל אִם שָׁמוּ לוֹ \u0010y20\u0011 וְאָמְרוּ לְבַעַל הַשָּׂדֶה: תֵּן לוֹ, וְאָמַר: נָתַתִּי, אַף עַל פִּי שֶׁעֲדַיִן לֹא נִשְׁבַּע הַיּוֹרֵד, הֲרֵי בַּעַל הַשָּׂדֶה נֶאֱמָן, וְיִשָּׁבַע הֶסֵת שֶׁנָּתַן, וְיִפָּטֵר, שֶׁהַקַּרְקַע בְּחֶזְקַת בְּעָלֶיהָ:",["\u0003אומדין כמה אדם רוצה ליתן בשדה זו לנוטעה \u0004 והיינו כשאר שתלי העיר כ\"כ רש\"י והרא\"ש והביאו הב\"י וכתב שתלמידי רש\"י לא ס\"ל הכי מאחר שירד שלא ברשות וגם עומד להסתלק ע\"ש ועפר\"ד:","\u0003וידו על התחתונה פי' שאם השבח יתר על ההוצאה נותן לו ההוצאה ואם הוצאה יתירה על השבח אינו נותן לו בהוצאתו אלא שיעור השבח:\u0004","\u0003סתם כרם עשוי ליטע \u0004 פי' לאפוקי שדה שעומד ג\"כ לזרוע וחצר עומד לבנות:","\u0003שומעין לו \u0004 הרא\"ש והרמ\"ה ס\"ל דאפי' עשויה ליטע שומעין לו כשאומר כן וכתב הנ\"י שכן דעת המחבר והרמב\"ם ודלא כמ\"ש המ\"מ דהרמב\"ם מיירי דוקא באין עשויה ליטע ועד\"ר:","\u0003מפני שמכחיש הארץ רש\"י \u0004 פי' שכבר הכחישו הנטיעות הארץ ביניקתן וכיון שהפסידו ממון לבעל הקרקע מ\"ה אפי' בח\"ל אין שומעין לו עכ\"ל ונראה שכן דעת הרמב\"ם והמחבר אע\"פ שכתבו ל' שמכחיש הארץ ולא כע\"ש שכתב ז\"ל מפני שמכחיש הקרקע בעקירת האילנות:","\u0003מיהו אם א\"ל תחלה עקור אילנך כו' \u0004 נראה דהג\"ה זו שייכא לסעיף זה שכ' כאן שאין שומעין לו לבעל האילן בבא ליקח נטיעותיו אזה כתב דבכה\"ג אם א\"ל בעל השדה מתחלה עקור כו' שומעין אח\"כ לבעל האילן:","\u0003שמין לו וידו על העליונה \u0004 דע דלדעת רש\"י ורא\"ש בכ\"מ שידו על העליונה אם השבח יותר על ההוצאה נוטל בשבח כשאר שתלי העיר ואם ההוצאה יתירה על השבח נוטל כל ההוצאה אע\"פ דלא נהנה כלום מ\"מ הואיל וגילה דעתו דניחא ליה אמרינן אילו לא נטעה היה הוא בעצמו נטעה והוציא עליה הוצאה כזו ובעיקר הדין ס\"ל להרא\"ש דדוקא בשדה העשויה ליטע הדין כן והרמ\"ה ורוב המפרשים ס\"ל דאפי' באינה עשויה ליטע הואיל וגילה דעתו דניחא ליה בהנטיעה ידו על העליונה ובב\"י כ' דהיינו דוקא כשאמר תחלה איני חפץ בהנטיעות ואח\"כ גילה דעתו דניחא ליה בהן הוא דידו על העליונה אפי' בשדה שאינו עשויה ליטע והמחבר סתם הדברים כאן ועפ\"ר שם כתבתי דמדברי הטור מוכח דלא ס\"ל האי סברא:","\u0003שאם היתה ההוצאה יתירה על השבח נוטל ההוצאה ואם השבח יתירה על ההוצאה נוטל השבח כו' \u0004 (ולאפוקי הנוסח בס\"י דכ' בהיפך שאם ההוצאה יתירה על השבח נוטל השבח ואם השבח יתר על ההוצאה) נוטל ההוצאה ור\"ל שנוטל בשבח כשאר שתלי העיר וכנ\"ל בפי' ידו על העליונה וכן הוא במיימוני פ\"י דגזיל' בדפוס כ\"מ וכן מצאתי במיימוני של קלף ישן נושן וכן הוגה ונדפס בש\"ע בדפוס חדש הנדפסי' בקראקא וא\"ת הא כתב מור\"ם לעיל בסוף סי' קע\"ח בהג\"ה בשותף דה\"ל כיורד ברשות ואפ\"ה אם ההוצאה יתירה על השבח אינו נוטל אלא ההוצאה שיעור שבח הא כתבתי שם דהנ\"י בשם רמב\"ם ורא\"ה כתב דשותף אף דה\"ל כיורד ברשות לענין אם השבח הוא יתר על ההוצא' דנוטל בהשבח כאריס או כשתל כמבואר שם מ\"מ אם הוצאה יתירה על השבח בזה אינו דומה ליורד ברשות דנוטל כל ההוצאה והשותף אינו נוטל הוצאה אלא שיעור שבח ומ\"ה קאמר כיורד ברשות ולא יורד ברשות לגמרי אבל הט\"ו שאיירי כאן ביורד ברשות דינו שנוטל כל ההוצאה כנ\"ל וכמ\"ש שם ודוק:","\u0003אשתו קטנה \u0004 דבקטנה עשו תקנה וכמבואר בא\"ע ס\"ס פ\"ח בטור ובדברי המחבר ע\"ש בפרישה:","\u0003והשותף בשדה כו' \u0004 ע\"ל סימן קע\"ח בדברי הטור והמחבר:","\u0003כיורד ברשות כו' \u0004 בסעיף שלפני זה כתבתי בשם נ\"י ורנב\"ר ורא\"ה דלא הוה דינם כיורד ברשות לגמרי לענין אם ההוצאה יתירה על השבח וכן הדין ג\"כ במוציא הוצאות על נכסי אשתו כמ\"ש בת\"ה בהדיא וכתבתי ל' לעיל בס\"ס קע\"ח אהג\"ה דברי מור\"ם ז\"ל ע\"ש. (הג\"ה כתב הר\"י בן הרא\"ש על ששאל על ראובן שהיה לו בית שנפרץ והלך למרחוק ואמרו הקהל לסופר בנה בית לעצמך שלא יארע לנו נזק מבית ראובן וכן עשה ואח\"כ בא אחר וקנה בית ראובן מבת אשתו ופסק דאע\"פ שלא נודע בבירור שהבית היא של בת אשתו של ראובן מ\"מ זה מיקרי יורד שלא ברשות ומוציאין מידו ונותנין למי שקנה מחורגתו של ראובן עכ\"ל ד\"מ ס\"ס ה' ו' עכ\"ה):","\u0003שומעין לו דבבנין ע\"ג קרקע לא שייך כחשא דארע' כמו דשייך באילנות כמבואר לפני זה בס\"ב:\u0004","\u0003ודוקא אם החורבה כו' אבל אם עשויה לבנות כו' \u0004 והטור בשם הרא\"ש כתב ז\"ל ומסתבר לומר כן (דאין שומעין לו) היכא דלא הי' משתמש בחורבתו ויש לו משלו שראוי לבנות בנין כזה בלי קפוח פרנסתו דאז ודאי תואנה הוא מבקש כדי להפסיד לבעל הבנין הא לאו הכי שומעין לו:","\u0003ולא יוכל הבונה לומר בניני אני נוטל \u0004 הטעם דאף דאין כאן טעם כחשא דארעא מ\"מ כיון דאין הב\"ה יכול לומר טול עציך ואבניך כיון דעשוי' לבנות כן הוא אינו יכול לומר שיטלם כיון שבנאו במקום הראוי לבנות ודאי אדעתא דהכי בנאו שיקום כאן:","\u0003כמו שנתבאר לעיל סי' שס\"ג ע\"ש ס\"ז דכתב דאם השחיר את כותלי בית חדש דמגלגלין עליו את הכל גם מ\"ש מור\"ם לפני זה דאם השכירה הבונה כו' מנכין לו כו' כעין זה כתב הטור בסי' שס\"ג ומור\"ם שם בס\"ה:\u0004","\u0003אבל א\"צ ליתן לו מה שסיידו כו' \u0004 בטור כתב אפי' הי' מסוייד ומכוייד ומבפנים לסיד היה הכותל מעופש ורעוע והוצרך שמעון להרוס הסיד כדי לתקן הקיר ותקנה כמו שהיה קודם לכן אפ\"ה א\"צ להחזיר לו כיון שיכול להיות קיים זולת הסיוד והכיוד וכיוצא בו ע\"ש:","\u0003בין שהיתה ידו על העליונה כו' \u0004 פי' גם כשיהיה ידו על העליונה צריך לישבע על ההוצאה ל\"מ כשהוצאה יתרה על השבח דאז נותנין ההוצאה וכנ\"ל דצריך שישבע ויטול אלא אפי' אם השבח יתר על ההוצאה דאז נוטל חלק גם בשבח היתר על ההוצאה מ\"מ כיון שגם כפי ההוצאה צריך ליתנו לו צריך לישבע כמה הוציא או שיאמדו אותו הבנאים וכדמסיק:","\u0003ואם אמר יבואו \"הדיינים כו' \u0004 כן הוא לשון הרמב\"ם שם \"הדיינים אבל הטור הביא ל' הרמב\"ם שכתוב בו יבואו \"הבנאים:","\u0003וכן זה שנוטל השבח בלבד \u0004 נראה דר\"ל דאם היתה ידו על העליונה וההוצאה יתירה על השבח דהדין ליתן לו ההוצאה כמ\"ש אם אומר איני רוצה ליקח היציא' יתירה על השבח בשבועה אלא אקח השבח המועט בלא שבועה ישומו לי שומעין לו ומיירי שהוא ניכר לעינים דעכ\"פ יציאה היתה יתירה על השבח אלא שאין ידוע כמה ואמר ישומו לי כו' וז\"ש נוטל השבח בלבד ר\"ל שהוא הפחות וקמ\"ל בכל זה דל\"מ למימר ליה השבע וטול כדינך או לא תטול כלום וק\"ל:","\u0003שהרי אמרי' לבעל שדה עדיין לא שמו כו' דין זה נלמד כאן מהא דאיתא בפ\"ק דב\"ב בבונה כותל בחצר המפסקת בין אדם לחבירו גבוה מד' אמות כו' וכתבו הט\"ו לעיל ס\"ס קנ\"ז ע\"ש ועפ\"ר:\u0004","\u0003ואמרו לבעל השדה תן לו \u0004 ע\"ל סי' כ\"ב וע\"ש חילוק בין א\"ל צא תן לו או חייב אתה ליתן לו:"],["\u0003 היורד לתוך שדה חבירו כו' \u0004 עיין בתשוב' מהרא\"ן ששון סימן רכ\"ד:","\u0003 א\"ל בעה\"ב עקור אילנך כו' \u0004 עיין בתשו' מהרי\"ט סי' ק\"ל דף קכ\"ט:","\u0003 וידו על העליונה כו' \u0004 והרא\"ש והטור חולקין ע\"ז:","\u0003 מיהו אם א\"ל תחלה עקור אילנך כו' \u0004 הג\"ה זו שייך אחר סעיף ב' וכן משמע בסמ\"ע:","\u0003 בעל בנכסי כו' \u0004 עיין בתשו' רמ\"א סימן פ\"ו דף קע\"ה:","\u0003 ודוקא אם החורבה כו' \u0004 עיין בתשו' רשד\"ם סימן רכ\"ז ורמ\"א וסי' ש\"ל:","\u0003 כל מי ששמין לו כו' \u0004 עיין בתשו' מהרא\"ן ששון סי' רל\"א:"]],["הַמַּסִיג גְּבוּל רֵעֵהוּ וְהִכְנִיס מִתְּחוּם חֲבֵרוֹ בְּתוֹךְ תְּחוּמוֹ אֲפִלּוּ מְלֹא אֶצְבַּע, אִם בְּחָזְקָה עָשָׂה, הֲרֵי זֶה גַזְלָן. וְאִם הִסִיג בַּסֵתֶר, הֲרֵי זֶה גַּנָּב. \u0010y0\u0011 וְאִם בְּאֶרֶץ יִשְׂרָאֵל הִסִיג הַגְּבוּל, \u0010y1\u0011 הֲרֵי זֶה עוֹבֵר בִּשְׁנֵי לָאוִין: בְּלָאו גְּנֵבָה אוֹ בְלָאו גְּזֵלָה, וּבְלָאו דְּלֹא תַסִיג. \u0005אִם מֻתָּר לָאָדָם לִקַּח מַעֲרוּפְיָא שֶׁל חֲבֵרוֹ, עַיֵּן לְעֵיל סִימָן קנ\"ו.\u0006",["\u0003ואם בארץ ישראל הסיג גבול כו' עד ובלאו דלא תסיג \u0004 סיפא דקרא בנחלתך אשר תנחל בארץ כו' הרי דלא הזהר הכתוב אלא אמסיג גבול קרקע דא\"י:","\u0003ה\"ז עובר בשני לאווין כו' \u0004 כן הוא ג\"כ ל' הרמב\"ם אבל בטור לא נזכר לאו דלא תגזול ולא תגנוב משום דקרקע אינה נגזלת כמ\"ש בסי' שע\"א אלא עבירה היא בידו וכמ\"ש בסימן שנ\"ט גם כאן לא כתב הטור שבשאר ארצות עובר בלאו דלא תגזול כמ\"ש בא\"י דעובר בלאו דלא תסיג גבול אלא ז\"ל אם בחזקה ה\"ז גזלן:"],[]],["\u0010c0\u0011 מִי שֶׁהָיְתָה \u0010y0\u0011 דֶּרֶךְ הָרַבִּים עוֹבֶרֶת בְּתוֹךְ שָׂדֵהוּ, נְטָלָהּ וְנָתַן לָהֶם מִן הַצַּד, מַה שֶּׁנָּתַן נָתַן וְזָכוּ בוֹ, וְזֶה שֶׁנָּטַל לֹא זָכָה בוֹ. \u0005מֶצֶר \u0010y1\u0011 שֶׁהֶחֱזִיקוּ בּוֹ רַבִּים בִּרְשׁוּת, אָסוּר לְקַלְקְלוֹ (מָרְדְּכַי דְּבָבָא מְצִיעָא)\u0006.",["\u0003דרך הרבים עוברת \u0004 נראה דהיינו דוקא בדרך שכל מי שרוצה ילך שם אפי' ממקומות דעלמא הוי דינא דזכו בשניהן דדרך הראשון אין כח בידו לבטל זכות הרבים דעלמא והדרך שנתן להן מדעתו מן הצד זכו בהן אלו בנתינתו זו שנתן להן מדעתו משא\"כ אם היה הדרך מיוחד דוקא לבני מבוי או עיר א' לחוד ולא לזולתם דאזי אותו בני העיר ואפי' ז' טובי עיר לחוד יכולין להחליף אותו הדרך בדרך אחר ומי ימחה בידם ותנאם ועסקם קיים וכ\"ש דלא זכו בזה ובזה וק\"ל:","\u0003שהחזיקו בו רבים ברשות כו' \u0004 קמ\"ל בזה דדוקא כשהחזיקו ברשות אסור לקלקלו משא\"כ כשהזיקו בו שלא ברשות מיהו כל שרבים מוחזקים בו עתה לפנינו טוענין להן ואמרי' דבודאי ברשות החזיקו בו:"],["\u0003 מי שהיתה דרך הרבים כו' \u0004 עיין בתשו' מהרא\"ן סי' כ\"ט דף קמ\"א ע\"א ובתשובות מהרשד\"ם סי' תס\"ג:"]],["\u0003הלכות נזיקין\u0004\nאָסוּר לְהַזִּיק מָמוֹן \u0010y0\u0011 חֲבֵרוֹ. וְאִם הִזִּיקוֹ, אַף עַל פִּי שֶׁאֵינוֹ נֶהֱנֶה, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם, בֵּין שֶׁהָיָה שׁוֹגֵג בֵּין שֶׁהָיָה אָנוּס. \u0010c0\u0011 \u0010c1\u0011 \u0005וְדַוְקָא שֶׁאֵינוֹ אָנוּס גָּמוּר, כְּמוֹ שֶׁיִּתְבָּאֵר.\u0006 כֵּיצַד, נָפַל מֵהַגַּג וְשָׁבַר אֶת הַכְּלִי, אוֹ שֶׁנִּתְקַל כְּשֶׁהוּא מְהַלֵּךְ וְנָפַל עַל הַכְּלִי וּשְׁבָרוֹ, חַיָּב נֶזֶק שָׁלֵם.\nנָפַל מִן הַגַּג וְהִזִּיק, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם, \u0010y1\u0011 בֵּין שֶׁנָּפַל בְּרוּחַ מְצוּיָה בֵּין שֶׁנָּפַל בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה. \u0005דְּלָא מִקְרֵי אֹנֶס גָּמוּר (טוּר)\u0006.\nהָיָה עוֹלֶה בְּסֻלָּם וְנִשְׁמְטָה שְׁלִיבָה מִתַּחְתָּיו וְנָפַל [ה] וְהִזִּיק [ה], אִם לֹא הָיְתָה מְהֻדֶּקֶת וַחֲזָקָה, חַיָּב. וְאִם הָיְתָה חֲזָקָה וּמְהֻדֶּקֶת וְנִשְׁמְטָה אוֹ שֶׁהִתְלִיעָה, הֲרֵי זֶה פָּטוּר, שֶׁזּוֹ מַכָּה בִּידֵי שָׁמַיִם הִיא. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nכָּל אֵלּוּ \u0010y2\u0011 הַדְּבָרִים בִּרְשׁוּת הַנִּזָּק, אֲבָל בִּרְשׁוּת הַמַּזִּיק פָּטוּר, עַד שֶׁיִּתְכַּוֵּן לְהַזִּיק כְּמוֹ שֶׁיִּתְבָּאֵר\nאֲפִלּוּ בִּרְאִיָּתוֹ, אִם יֵשׁ בּוֹ הֶזֵּק לַחֲבֵרוֹ אָסוּר לְהִסְתַּכֵּל בּוֹ. \u0010y3\u0011 לְפִיכָךְ, אָסוּר לָאָדָם לַעֲמֹד עַל שְׂדֵה חֲבֵרוֹ בְּשָׁעָה שֶׁעוֹמֶדֶת בְּקָמוֹתֶיהָ. \u0010y4\u0011\nכָּל מָקוֹם שֶׁמַּזִּיק, חַיָּב לְשַׁלֵּם, בֵּין בִּרְשׁוּת הָרַבִּים בֵּין בִּרְשׁוּת הַנִּזָּק. וַאֲפִלּוּ בִּרְשׁוּת הַמַּזִּיק, אִם הִכְנִיס בּוֹ הַנִּזָּק מָמוֹנוֹ שֶׁלֹּא בִּרְשׁוּת \u0010y5\u0011 וְהִזִּיקוֹ, לֹא שְׁנָא בְּגוּפוֹ לֹא שְׁנָא בְּמָמוֹנוֹ, חַיָּב לְשַׁלֵּם; דִּנְהִי שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ, אֵין לוֹ רְשׁוּת לְהַזִּיקוֹ. וְדַוְקָא בְּמַזִּיקוֹ בְּמֵזִיד, אֲבָל אִם הִזִּיקוֹ בְּשׁוֹגֵג, פָּטוּר בַּעַל הַבַּיִת. וְאִם בַּעַל הַבַּיִת הֻזַּק בַּנִּכְנַס, אֲפִלּוּ בְּשׁוֹגֵג, חַיָּב הַנִּכְנַס כֵּיוָן שֶׁנִּכְנַס שֶׁלֹּא בִּרְשׁוּת. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּדַוְקָא בְּשֶׁלֹּא יָדַע בַּעַל הַבַּיִת שֶׁנִּכְנַס, \u0010y6\u0011 אֲבָל אִם רָאָהוּ שֶׁנִּכְנַס, אִם הֻזַּק בּוֹ, פָּטוּר. \u0010y7\u0011\nהָיוּ שְׁנֵיהֶם בִּרְשׁוּת אוֹ שְׁנֵיהֶם שֶׁלֹּא בִּרְשׁוּת, וְהֻזְּקוּ זֶה בְּזֶה בֵּין בְּגוּפָם בֵּין בְּמָמוֹנָם, אִם לֹא יָדְעוּ זֶה בְּזֶה, פְּטוּרִים. אֲבָל אִם רָאוּ זֶה אֶת זֶה, \u0010y8\u0011 \u0010c2\u0011 אַף עַל פִּי שֶׁלֹּא \u0010y9\u0011 כִּוְּנוּ, חַיָּבִים. לְפִיכָךְ, שְׁנַיִם שֶׁהָיוּ רָצִים בִּרְשׁוּת הָרַבִּים, אוֹ שֶׁהָיוּ מְהַלְּכִים וְהֻזְּקוּ זֶה בְּזֶה, פְּטוּרִים; הִזִּיקוּ זֶה אֶת זֶה, חַיָּבִים.\nהָיָה אֶחָד רָץ וְאֶחָד מְהַלֵּךְ, וְהֻזַּק הַמְהַלֵּךְ בָּרָץ, חַיָּב, מִפְּנֵי שֶׁרָץ שֶׁלֹּא בִרְשׁוּת. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּחוֹל. אֲבָל בְּעֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת, פָּטוּר, \u0010y10\u0011 מִפְּנֵי שֶׁרָץ בִּרְשׁוּת. \u0005וְדַוְקָא בִּסְתָם, דְּתָלִינָן דְּרָץ לְצֹרֶךְ שַׁבָּת. אֲבָל אִם יָדוּעַ שֶׁאֵינוֹ רָץ אֶלָּא לִשְׁאָר חֲפָצָיו, וְלֹא שַׁיְיכֵי בֵּהּ צֹרֶךְ שַׁבָּת, חַיָּב כְּמוֹ בְּחוֹל (רַ\"ן פֶּרֶק הַמֵּנִיחַ)\u0006. \u0010y11\u0011\nאִם בָּא אֶחָד רוֹכֵב בְּסוּסוֹ מֵאַחֲרֵי חֲבֵרוֹ, וְפָגַע בַּסוּס שֶׁחֲבֵירוֹ רוֹכֵב בּוֹ וְהִכָּה אֶת הַסוּס, חַיָּב לְשַׁלֵּם כָּל מַה שֶּׁיָּשׁוּמוּ בֵּית דִּין שֶׁנִּפְחַת מֵחֲמַת הַכָּאָה זוֹ. וַאֲפִלּוּ הָיָה הַסוּס הַמֻּכֶּה שֶׁל גּוֹי, וְצָרִיךְ הַנִּזָּק לְשַׁלֵּם לַגּוֹי יוֹתֵר מִמַּה שֶׁנִּפְחֲתוּ דְּמֵי הַסוּס, אֵין הַמַּזִּיק חַיָּב לְשַׁלֵּם יוֹתֵר מִמַּה שֶׁיָּשׁוּמוּ בֵּית דִּין. \u0005בַּחוּרִים הָרוֹכְבִים לִקְרַאת חָתָן וְכַלָּה וְהִזִּיקוּ זֶה אֶת זֶה מָמוֹן חֲבֵרוֹ דֶרֶךְ שִׂמְחָה וּשְׂחוֹק, וְכֵן בִּשְׁאָר דְּבַר שִׂמְחָה, \u0010y12\u0011 הוֹאִיל וְנָהֲגוּ כֵן, פְּטוּרִין (מָרְדְּכַי סוֹף פֶּרֶק הַיָּשֵׁן וְתוֹסָפוֹת וְהָרֹא\"שׁ וַאֲגֻדָּה פֶּרֶק לוּלָב וַעֲרָבָה)\u0006, מִכָּל מָקוֹם, אִם נִרְאֶה לְבֵית דִּין לַעֲשׂוֹת סְיָג וְגָדֵר, הָרְשׁוּת בְּיָדָם \u0005(פִּסְקֵי מהרא\"י סִימָן ר\"י)\u0006.",["\u0003אסור להזיק ממון חבירו כו' \u0004 התחיל באיסור וסיים בחיוב תשלומין ללמדינו תרתי אית ביה חדא דאף אם ירצה להזיק ולשלם מ\"מ יש איסור בדבר דומיא דגניבה וגזילה וכמ\"ש הטור והמחבר לעיל ר\"ס שמ\"ח ושנ\"ט מ\"ה תלה הטור כאן איסור נזיקין באיסור גניבה וגזילה ע\"ש והשני שחייב בתשלומין ואפי' לא נהנה ואפי' שגג והטעם דאדם מועד לעול' אם לא באונס גדול עפ\"ר (הג\"ה וכ' נ\"י פרק המניח (דף י\"ב) הא דאמרי' האי מאן דבעי למהוי חסידא לקיים מילי דנזקין היינו כל דינים האמורים בתלתא בבות דהיינו נזיקין וגזל והשבת אבידה וריבית ואונאה וע\"ש ד\"מ ר\"ס זה):","\u0003בין שנפל ברוח מצוייה כו' \u0004 עד\"ר שם כתבתי אל' הטור שכתב שאם נפל ברוח שאינו מצויה פטור דקשה הא הטור בעצמו כתב לקמן בסי' תכ\"א סי\"ג דאם נפל ברוח שאינו מצוייה חייב בנזק וכן הוא בגמ' וחלקתי דבגמרא ושם בסימן תכ\"א איירי כשניזק האדם מנפילתו עליו מהגג ברוח שאינו מצויה ובהזיק באדם דאם נפל ברוח מצוייה נתבאר שם דחייב בד' דברים מ\"ה ברוח שאינו מצויה נחתי בה חד דרגא שלא לחייבו בד' דברים כ\"א בחיוב נזק בלבד וכאן דאיירי דנזק וכלים בנפילתו דגם בנפילתו ברוח מצויה אינו חייב על נזקם כ\"א נזק מ\"ה בנפילתו ברוח שאינו מצויה ס\"ל להטור דנחתינין ביה לחיובו ולא מחייבינן לי' אנזקו כלל כ\"א בנפילתו ברוח מצויה ע\"ש מה שכתב עוד שינוי וא\"כ יתיישב לשון המחבר דנראה בדבריו ככפל וסתומים דבס\"א סתם וכ' חייב לשלם היזק כלים בנפל מן הגג ולא פירש דמיירי גם ברוח שאינו מצויה ובסעיף שאחריו חזר וכתב דינא דנפילה מהגג ופירש דבריו דחייב אפי' ברוח שאינו מצויה ולפי מה שכתבתי לחלק א\"ש דבס\"א דאיירי בנזקי כלים מש\"ה לא כתב דחייב ברוח שאינו מצויה ובסעי' ב' דאיירי בהזיק בן אדם משום הכי כתב שם דחייב אפי' בנפל ברוח שאינו מצויה ואף שהב\"י לא ס\"ל האי שינוי דהא הב\"י הקשה אדברי הטור דפטרו ברוח שאינו מצויה מ\"מ י\"ל דחזר בו כאן בחיבור וס\"ל ג\"כ כמה שכתבתי ודוק:","\u0003אבל ברשות המזיק כו'. \u0004 דהמזיק יכול לומר לא ידעתי במה שהכניס שם ענינו להזהר להזיקן ודוקא שהזיקו בשוגג וכמ\"ש הטור והמחבר בסמוך ס\"ו וזהו שסיים וכתב וכמו שיתבאר ור\"ל בס\"ו:","\u0003לפיכך אסור לאדם לעמוד על שדה כו'. \u0004 הא דכתבו הטור והמחבר היזק ראייה זה בלשונם ולא נקטו בלשונם הני היזק ראייה דסי' קנ\"ד (ודוחק לו' דכוונת המחבר לתרוייהו דבמה שכ' ברישא אפי' בראייתו אסור להסתכל כוון להיזק ראיה דבסי' קנ\"ד ובסיפא כ' לפיכך כו' איירי אפי' היזק ראיה דקמה בשדה דאין הל' משמע כן גם בטור לא כ' אלא היזק ראיה דקאמר לגירסא דאמר רב יודא ע\"ש) משום דשם הראיה מצד עצמה אין עושה בהן היזק אלא שגורמת היזק כגון שחבירו לא יעשה עסקיו בחצר מכח שבושה ממנו או שירא שיבא לו היזק השגת גבול או שאר ענינים כיוצא באלו משא\"כ שדה בקמותיה דהראויה מצד עצמה שולטת בה וגורמת היזק אבל לענין איסור הנהו מכל שכן דאסור דבזה איכא למאן דאמר בגמ' דלית ביה אלא מדת חסידות ועפ\"ר:","\u0003כ\"מ שמזיק כו'. \u0004 כלשון זה הוא ברמב\"ם ובטור ונראה לי דצריך לו' בכ\"מ בבי\"ת:","\u0003והזיקו \u0004 כ\"מ שנזכר ל' היזק ר\"ל שהמזיק הזיק לניזק במעשה אפי' לא נתכוון וכ\"מ שכתב שהוזק ר\"ל שהניזק הוזק מעצמו בהמזיק והיינו שמזיק עומד במקומו והניזק הלך בצדו וניזק ממנו רש\"י ועפ\"ר:","\u0003אבל אם ראהו שנכנס כו' \u0004 פי' אפי' לא ראהו בשעה שהוזק ממנו אלא ראהו מתחלה נכנס הוה ליה לאסוקי אדעתו שיש בו אדם שראוי שיוזק ממנו ולשמור נפשו וכשלא שמר נפשו איהו דאפסיד אנפשיה ודוקא בהוזק ממנו הבע\"ה אבל אם הזיקו הנכנס אפי' בשוגג חייב הנכנס וכדין שניהם ברשות שיתבאר בסי' שאחר זה:","\u0003היו שניהן ברשות \u0004 ל' הטור כגון שנתן בעל החצר לשניהן רשות ליכנס כו' וכתבתי שם דה\"ה אם ב\"ה נתן לא' רשות לכנס לחצירו או שראוהו נכנס מקרי שניהן ברשות וכמ\"ש לפני זה אלא כשהבע\"ה נתן לו רשות דלא שייך לומר דלא ידעו זה מזה ע\"ש ודוקא בהוזקו זמ\"ז פטורין אבל הזיקו זה את זה חייבין דכל אחד ה\"ל לאסוקי אדעתיה כמו שאני נכנסתי לחצר חבירי ברשות או שלא ברשו' כן נכנס גם כן אחר משא\"כ באחד שנכנס לרשות חבירו שלא ברשות דלא ה\"ל לבע\"ה לאסוקי אדעתי' שיכנוס מי לרשותו שלא מדעתו ומ\"ה אפי' הוזק ממנו הבע\"ה חייב הנכנס כמ\"ש בסעיף שלפני זה ועפ\"ר:","\u0003אע\"פ שלא כיונו \u0004 דאדם מועד לעולם וכנ\"ל:","\u0003לפיכך ב' שהיו רצים בר\"ה כו' \u0004 והליכת שניהם בר\"ה מקרי ברשות וריצתם שמה מיקרי שלא ברשות דה\"ל למיסק אדעתי' שמא יפגע בו חבירו ולא יהיה בידו לעמוד מלהזיקו ומ\"ש הוזקו זה בזה פטורים היינו דוקא בלא רצו [ראו] זא\"ז ועמ\"ש לפני זה בסמוך ועפ\"ר:","\u0003מפני שרץ ברשות. \u0004 ז\"ל הרמב\"ם פ\"ב דחובל דרץ ברשות כדי שלא תכנס שבת והוא אינו פנוי עכ\"ל ול' זה משמע לכאורה אפי' רץ בעסקיו לגומרם קודם שבת מיקרי ברשות אבל ממ\"ש מור\"ם אחר זה מוכח דס\"ל דוקא דרץ בעסקי צרכי שבת מיקרי ברשות ועפ\"ר:","\u0003אם בא אחד רוכב בסוסו כו'. \u0004 ז\"ל הטור בשם תשובת הרא\"ש בזה מה שטעה ראובן שהוא פטור כיון שהיו רוכבין בר\"ה והיה לו לניזק לשמור עצמו לאו טענה היא שרץ לו לרוץ בר\"ה ואפי' ברגליו שיכול לעמוד כשירצה כ\"ש הרוכב סוס שאין לו לרוץ במקום שבני אדם רוכבין שמא לא יוכל להעמיד הסוס כשירצה ונמצא שפשע בו ומזיק בגופו הוא כיון שרוכב על הבהמה ומזיק בגוף הבהמה או באוכף שעליה חייב לשלם אבל כל כו' אם הסוס המוכה היה של עכו\"ם כו' עד אם העכו\"ם מעביר עליו הדרך בשביל זה אין לחייב לזה כיון שלא כוון עכ\"ל (וכיוצא בזה כתב המחבר לעיל סימן ע\"ב ס\"ח בסייף המומשכן ביד ראובן ושאל לשמעון ואבדו) ועפ\"ר מ\"ש ל' הטור לכאורה היה נראה להגיה מ\"ש אפי' הי' הסוס דצ\"ל אבל אם היה הסוס אבל מדסיים המחבר וכ' בל' ז\"ל אין המזיק חייב לשלם לו יותר ממה שישומו לו הב\"ד זה לא יתכן שפיר לגרסת אבל אם כו' ויתכן יותר לנוסחא שלפנינו ואפי' היה הסוס כו' וקאי אמ\"ש לפניו דישלם לו כפי השומא ואזה כתב דבשומא סגי אפי' העליל עליו העכו\"ם וק\"ל:","\u0003הואיל ונהגו כן פטורים. \u0004 עיין בד\"מ בטור א\"ח סי' תרצ\"ה מה שכתוב עוד מענינים אלו:"],["\u0003 ודוקא שאינו אנוס כו'. \u0004 הל' מגומגם וכך הל\"ל וי\"א דוקא שאינו אנוס גמור דמלשון הרמב\"ם והמחבר משמע דאין חילוק וכ\"כ הרב המגיד דלהרמב\"ם אין חילוק:","\u0003 שאינו אנוס גמור כו' \u0004 עיין מ\"ש לקמן ריש סי' שפ\"ו דנראה דוקא כשהזיק בלא מתכוין אבל מי שמזיק במתכוין אפי' אונס גמור חייב כמו נרדף ששבר את הכלים לקמן סי' ש\"פ סעיף ב' וע\"ש:","\u0003 אע\"פ שלא כוונו כו'. \u0004 ע\"ל סימן תכ\"א ס\"ה בהג\"ה:"]],["שְׁנַיִם שֶׁהָיוּ מְהַלְּכִים בִּרְשׁוּת הָרַבִּים, זֶה בָּא בְּחָבִיתוֹ וְזֶה בָּא בְּקוֹרָתוֹ, וּפָגְעוּ זֶה בְּזֶה וְנִשְׁבְּרָה חָבִית בְּקוֹרָה, פָּטוּר, שֶׁלָּזֶה רְשׁוּת לְהַלֵּךְ \u0010y0\u0011 וְלָזֶה רְשׁוּת לְהַלֵּךְ.\nהָיָה בַּעַל קוֹרָה רִאשׁוֹן וּבַעַל הֶחָבִית אַחֲרוֹן, וְנִשְׁבְּרָה הֶחָבִית בַּקּוֹרָה, פָּטוּר. וְאִם עָמַד בַּעַל הַקּוֹרָה \u0010y1\u0011 לָנוּחַ מִכֹּבֶד מַשָּׂאוֹ, חַיָּב. וְאִם הִזְהִיר לְבַעַל הֶחָבִית וְאָמַר לוֹ: עֲמֹד, פָּטוּר. \u0010c0\u0011 וְאִם עָמַד לְתַקֵּן מַשָּׂאוֹ, \u0010y2\u0011 אַף עַל פִּי שֶׁלֹּא הִזְהִירוֹ, פָּטוּר, שֶׁטָרוּד הָיָה וְלֹא הָיָה יָכוֹל לְהַזְהִירוֹ \u0005(וְע\"ל ר\"ס תי\"ג)\u0006.\nהָיָה בַּעַל הֶחָבִית רִאשׁוֹן וּבַעַל הַקּוֹרָה אַחֲרוֹן, וְנִשְׁבְּרָה חָבִית בְּקוֹרָה, חַיָּב. וְאִם עָמַד בַּעַל הֶחָבִית לָנוּחַ, פָּטוּר. וְאִם הִזְהִיר לְבַעַל הַקּוֹרָה שֶׁיַּעֲמֹד, חַיָּב. וְאִם עָמַד לְתַקֵּן מַשָּׂאוֹ, חַיָּב בַּעַל הַקּוֹרָה, אַף עַל פִּי שֶׁלֹּא הִזְהִירוֹ בַּעַל הֶחָבִית. וְכֵן זֶה בָּא בְּנֵרוֹ, וְזֶה בָּא בְּפִשְׁתָּנוֹ.\nהֲרֵי שֶׁמִּלֵּא חֲצַר חֲבֵרוֹ כַּדֵּי יַיִן וְשֶׁמֶן, אֲפִלּוּ הִכְנִיס בִּרְשׁוּת, הוֹאִיל וְלֹא קִבֵּל עָלָיו בַּעַל הֶחָצֵר לִשְׁמֹר, הֲרֵי זֶה נִכְנָס וְיוֹצֵא כְּדַרְכּוֹ, \u0010y3\u0011 וְכָל שֶׁיִּשְׁתַּבֵּר מֵהַכַּדִּים בִּכְנִיסָתוֹ וּבִיצִיאָתוֹ הֲרֵי הוּא פָּטוּר עֲלֵיהֶם. וְאִם שִׁבְּרָם בְּכַוָּנָה, אֲפִלּוּ הִכְנִיסָם בַּעַל הַכַּדִּים שֶׁלֹּא בִּרְשׁוּת, הֲרֵי זֶה חַיָּב:",["\u0003ולזה רשות להלך. \u0004 ל' הטור ודוקא שסייע בעל החבית בשבירת' שדרך הליכתו הטיח חביתו בקורה אבל אם עמד בעל החביות ובעל הקורה בא בקורתו ושוברה חייב:","\u0003לנוח מכובד משאו חייב. \u0004 ואפי' אין הקורה ממלא את כל הדרך טור. והטעם שלא היה לו לנוח בדרך שדרך בני אדם לבא אחריו ולהלוך בו ואם היה מוכרח לזה לפחות היה לו להזהיר להבא אחריו שיעמוד ולא יפגע בקורתו:","\u0003אע\"פ שלא הזהירו כו'. \u0004 עמ\"ש בר\"ס תי\"ג מזה:","\u0003וכל שישתבר בכניסתו כו'. \u0004 כן הוא דעת הרמב\"ם וכתב המ\"מ טעמו דכל שהוא ברשות המזיק ולא שברה כדי להזיקו אלא כדי לכנוס ולצאת הוא פטור אבל הראב\"ד והטור כתבו על דבריו שהן תמוהין כיון שהכניס ברשות איך יפטור על מה שמשבר בכניסתו ויציאתו אם לא שלא נתן לו רשות למלאות כל החצר עכ\"ל:"],["\u0003 ואם עמד לתקן משאו כו'. \u0004 וביש\"ש פ\"ג סימן כ\"ב פסק דפטור אא\"כ ידע דעמד לכתף ע\"ש ולא נהירא דמ\"ש ממ\"ש בסעיף ב' דאם בעל הקורה ראשון ועמד לכתף פטור דאף דגם שם לא ה\"ל למידע לבעל חביות שיעמוד הראשון ודו\"ק:"]],["הָאוֹמֵר \u0010c0\u0011 לַחֲבֵרוֹ: קְרַע אֶת כְּסוּתִי שַׁבֵּר אֶת כַּדִּי עַל מְנַת שֶׁאַתָּה פָטוּר, \u0010y0\u0011 הֲרֵי זֶה פָּטוּר. \u0005וְיֵשׁ אוֹמְרִים אֲפִלּוּ לֹא אָמַר לוֹ עַל מְנַת לִפְטֹר, בְּפֵרוּשׁ, אֶלָּא שֶׁאָמַר לוֹ דְבָרִים שֶׁמַּשְׁמָעָן כָּךְ, כְּגוֹן שֶׁאָמַר לוֹ: שְׁבֹר כַּדִּי, וְאָמַר לוֹ הַמַּזִּיק: עַל מְנַת לִפְטֹר, וְאָמַר לוֹ הַנִּזָּק: לֹא, \u0010y1\u0011 יֵשׁ לָנוּ לוֹמַר דְּבִתְמִיהָה קָאָמַר לֹא, וּפָטוּר (טוּר ס\"ג בְּשֵׁם הָרֹא\"שׁ)\u0006. וְאִם לֹא אָמַר לוֹ: עַל מְנַת שֶׁאַתָּה פָּטוּר, \u0010y2\u0011 הֲרֵי זֶה חַיָּב אַף עַל פִּי שֶׁהִרְשָׁהוּ לְהַשְׁחִית. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁבָּאוּ הַכֵּלִים לְיָדוֹ תְּחִלָּה בְּתוֹרַת שְׁמִירָה, כְּגוֹן שֶׁהָיוּ שְׁאוּלִים אוֹ מֻפְקָדִים אֶצְלוֹ. \u0010y3\u0011 אֲבָל אִם לֹא בָּאוּ לְיָדוֹ בְּתוֹרַת שְׁמִירָה, כֵּיוָן שֶׁאָמַר לוֹ: קַח כְּלִי זֶה וְשַׁבְּרוֹ, בֶּגֶד זֶה וְקָרְעוֹ, וְעָשָׂה כֵן, הֲרֵי זֶה פָטוּר, אַף עַל פִּי שֶׁלֹּא אָמַר לוֹ: עַל מְנַת שֶׁאַתָּה פָּטוּר. \u0005וְע\"ל עוֹד סִימָן שפ\"ב מִדִּינִין אֵלּוּ. הָאוֹמֵר לַחֲבֵרוֹ: זְרֹק מָנֶה לַיָּם וְאֶתְחַיֵּב אֲנִי לְךָ, יֵשׁ אוֹמְרִים דְּחַיָּב וְיֵשׁ אוֹמְרִים דְּפָטוּר (רַ\"ן פ\"ק דְּקִדּוּשִׁין ב' הַדֵּעוֹת)\u0006.\nהָאוֹמֵר לַחֲבֵרוֹ: שַׁבֵּר \u0010y4\u0011 כֵּלָיו שֶׁל פְּלוֹנִי עַל מְנַת שֶׁאַתָּה פָטוּר, וּשְׁבָרוֹ, הֲרֵי זֶה חַיָּב. וְאַף עַל פִּי שֶׁהָעוֹשֶׂה הוּא חַיָּב לְשַׁלֵּם, הֲרֵי זֶה הָאוֹמֵר לוֹ שֻׁתָּפוֹ בָּעָוֹן, וְרָשָׁע הוּא, \u0010y5\u0011 שֶׁהֲרֵי הִכְשִׁיל עִוֵּר, וְחִזֵּק יְדֵי עוֹבְרֵי עֲבֵרָה.\nרוֹדֵף שֶׁהָיָה רוֹדֵף אַחַר חֲבֵרוֹ לְהָרְגוֹ, \u0010y6\u0011 \u0010c1\u0011 אוֹ אַחַר אַחַת מֵהָעֲרָיוֹת לְאָנְסָהּ, וְשָׁבַר כֵּלִים, בֵּין שֶׁל נִרְדָּף בֵּין שֶׁל כָּל אָדָם, פָּטוּר, שֶׁהֲרֵי הוּא מִתְחַיֵּב בְּנַפְשׁוֹ, שֶׁכֵּיוָן שֶׁרָדַף הִתִּיר עַצְמוֹ לַמִּיתָה, וְלָכֵן פָּטוּר מֵהַתַּשְׁלוּמִין. וְאִם הַנִּרְדָּף שָׁבַר כֵּלִים שֶׁל רוֹדֵף, פָּטוּר, \u0010y7\u0011 שֶׁלֹּא יְהֵא מָמוֹנוֹ חָמוּר מִגּוּפוֹ. וְאִם הָיוּ שֶׁל אָדָם אַחֵר, חַיָּב, שֶׁהַמַּצִּיל עַצְמוֹ בְּמָמוֹן חֲבֵרוֹ, חַיָּב. \u0005וְע\"ל סִימָן שנ\"ט ס\"ד.\u0006 וְאֶחָד שֶׁרָדַף אַחַר הָרוֹדֵף לְהַצִּיל אֶת הַנִּרְדָּף, וְשָׁבַר כֵּלִים בֵּין שֶׁל רוֹדֵף בֵּין שֶׁל כָּל אָדָם, פָּטוּר, כְּדֵי שֶׁלֹּא יָבוֹאוּ מִלִּמָּנַע מִלְּהַצִּיל אֶת הַנִּרְדָּף.\nסְפִינָה שֶׁחָשְׁבָה לְהִשָּׁבֵר מִכֹּבֶד הַמַּשּׂוֹי, וְעָמַד אֶחָד מֵהֶם וְהֵקֵל מֵהַמַּשָּׂא וְהִשְׁלִיךְ בַּיָּם, פָּטוּר, שֶׁהַמַּשָּׂא שֶׁבָּהּ כְּמוֹ רוֹדֵף אַחֲרֵיהֶם \u0010c2\u0011 לְהָרְגָם, וּמִצְוָה רַבָּה עָשָׂה שֶׁהִשְׁלִיךְ וְהוֹשִׁיעָם. \u0005הַגָּה: \u0010y8\u0011 \u0010c3\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁטְּעוּנָה יוֹתֵר מִדַּאי, דְּהָוֵי הַמַּשּׂוֹי כְּרוֹדֵף. \u0010c4\u0011 אֲבָל אִם אֵינָהּ טְעוּנָה יוֹתֵר מִדַּאי, וּבָא נַחְשֹׁל לְטָבְעָן, חַיָּבִין לְשַׁלֵּם וּמְחַשְּׁבִין לְפִי הַמַּשּׂוֹי וְלֹא לְפִי הַמָּמוֹן (רַמְבַּ\"ם פי\"ב דִּגְזֵלָה והמ\"מ סוֹף הִלְכוֹת חוֹבֵל)\u0006, וְאַף עַל פִּי שֶׁלֹּא הֵטִיל רַק מַשּׂוֹי שֶׁל אֶחָד, כֻּלָּן מְשַׁלְּמִין \u0005(טוּר)\u0006. הִכְנִיס חֲמוֹר בִּסְפִינָה וְקוֹפֵץ בַּסְּפִינָה וּבִקֵּשׁ לְטָבְעוֹ, וּבָא אֶחָד וְהִשְׁלִיךְ הַחֲמוֹר לַנָּהָר, אִם דֶּרֶךְ \u0010c5\u0011 לְהַכְנִיס חֲמוֹרִים בִּסְפִינָה אָז הַמַּשְׁלִיכוֹ \u0010c6\u0011 חַיָּב לְשַׁלֵּם; וְאִם לָאו, פָּטוּר, \u0010c7\u0011 דְּאָז הַחֲמוֹר מִקְרֵי רוֹדֵף, וְכָל כַּיּוֹצֵא בָּזֶה, \u0010y9\u0011 וְכֵן נִרְאֶה לִי עִקָּר \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא וּתְשׁוּבַת מַיְמוֹנִי דְּסֵפֶר נְזִיקִין סִימָן כ')\u0006.",["\u0003הרי זה פטור \u0004 ולא אמרינן שדרך שחוק א\"ל כן ויחייב כמו מי שאומר לחבירו קטע את ידי סמא את עיני והפטר דחייב וכמ\"ש הטור והמחבר לקמן ס\"ס תכ\"א ע\"ש קמ\"ל דלא דשאני חבלה דגופו מחבלה דממונו:","\u0003יש לנו לו' דבתמי' קאמר לי' \u0004 דכיון דא\"ל מתחלה קרע כסותי מפרשינן הלא דא\"ל אח\"כ דבתמיה קאמר לי:","\u0003אע\"פ שהרשהו להשחית \u0004 דא\"ל דדעתו היה שיקרענו וישלמו:","\u0003אבל אם לא באו לידו בתורת שמירה כו' \u0004 דכי יתן איש אל רעהו כסף או כלים לשמור כתיב ודרשי' כשנותנו בידו לשמור הוא דמחייב בפשיעתו ולא כשנתנו בידו לאבדו ולקרעו וכ\"כ הטור לעיל בסי' ש\"א ע\"ש:","\u0003כליו של פלוני ע\"מ שאתה פטור כו' \u0004 חייב בזה כ\"ע מודים דאפי' אם א\"ל בפי' ע\"מ שאתה פטור אפ\"ה חייב כיון שיודע המשבר שהוא של חבירו ואע\"ג דלגבי הדדי נאמרו בגמ' צ\"ל דס\"ל להי\"א הנ\"ל דכל אחד איירי בכל ענין בריש' בא\"ל לשבר את שלו בכל ענין פטור אפי' א\"ל לא ובסיפא בא\"ל לשבר את חבירו בכל ענין חייב ועפ\"ר:","\u0003שהרי הכשיל עור \u0004 קראו עוד אע\"פ שידע שהוא של חבירו מ\"מ מדא\"ל ע\"מ לפטור וסבר שבאמת כן יהיה שיהיה פטור וק\"ל:","\u0003או אחר אחת מהעריות לאונסה. \u0004 ל' הטור בין חייבי כריתות בין חייבי מיתות ב\"ד או אחר זכר לרבעו כו' ור\"ל אע\"פ דבחיוב כריתות אין על הרודף חיוב מיתות ב\"ד מ\"מ פטור על שבירות הכלים כיון דקלב\"מ שמת חייב בנפשו בידי שמים ועפ\"ר:","\u0003שלא יהא ממונו חמור מגופו. \u0004 פי' שהנרדף שהרג לרודף פטור כמו שאמרו שאם קדם זמרי והרג לפנחס היה פטור:","\u0003וי\"א דוקא שטעונין יותר מדאי \u0004 עד\"ר שם כתבתי ל' המ\"מ והב\"י שפירשו כן לדברי הרמב\"ם כדי שלא יסתרו דבריו הללו מ\"ש כאן בספינה שחשבה להשבר כו' אמ\"ש בס\"פ י\"ב דגזילה שמחשבין בכזה לפי המשוי והיא ברייתא בפ' הגוזל בתרא וגם ליישב ולסלק השגת הראב\"ד מהרמב\"ם אמ\"ש כאן וכתבו דמ\"ש כאן מיירי כשאחד או שנים מבני הספינה שהטעינו בספינ' באחרונ' הן הן שהכביד בטעינתן להספינ' עד שחשבה להשבר ולטובעה בים ומ\"ה אם קידם א' מהראשונים מבני הספינה והשליך לים ממשא זה שהטעינו האחרונים פטור וההיא דפי\"ב דגזיל' מיירי באם אינ' טעונה יותר מדאי וחשב' להשבר ולטובע' בים מכח גלי ים ובא א' והקל הספינה כדי שילך בקלות ויתרחק מהגל אף שהשליך סחורה של זה שהטעין באחרונה לא אמרי' שלו לבדו יהי' ההיזק דהרי לא פשע האחרון בטעינה להספינה יותר מדאי ומזלא דכולם גרם לבא עליהם גל מ\"ה מחשבין אותו ההפסד על כל בני הספינה וכל א' כפי משאו וכמ\"ש ג\"כ הטור והמחבר לעיל בס\"ס רע\"ב ע\"ש וגם המשליך לתוך הים מצוה עשה להציל עי\"ז בני הספינה וכל אשר בתוכו ואינו חייב יותר מאחר ונראה דגם הראב\"ד שהשיג על הרמב\"ם מודה בזה אלא שהוא לא פיר' דברי הרמב\"ם כן ומ\"ה השיג עליו וכמ\"ש בפריש' ע\"ש ולפ\"ז לא ה\"ל למור\"ם לכתוב זה בשם י\"א כיון דליכא מאן דפליג בגוף הדין ובפריש' כתבתי עוד ישוב לדברי הרמב\"ם מהשגת הראב\"ד דההשג' מעיקרא ליתא והוא דהרמב\"ם כאן לא איירי כאן בפ' זה דסוף החובל אלא בדיני פטור וחיוב נזק מה שהזיק המזיק ובא לאשמועינן דאם בא א' והקל ממשוי הספינה אינו חייב הוא לשלם לבדו הנזק כדין המזיק וזהו פטור דקאמר ומטעם דהמשוי היא רודפת ומצוה עשה ולא איירי כאן למי יהיה ההיזק של המשא הנשלכת בים ויש בו חלוקים דאם ידוע שהבעל המשא זו שהושלך בים הוא שהטעין באחרונ' ההיזק שלו לבדו ואם אין ידוע מחשבין היזק המשא הנשלכת על כולן לכל א' כפי משאו והיינו ברייתא דהגוזל בתרא וכתבו הרמב\"ם בסוף הל' חובל וזהו שדייק וכתב שם והקילו ל' רבים ששם לא מיירי בדין יחיד שעשה כן מנפשו ובאם יהיה חייב לשלם אלא כתב הדין שמחשבין לפי המשוי ולא לפי הממון ודוק:","\u0003וכן נ\"ל עיקר. \u0004 כ\"כ לאפוקי מהב\"י שהשיג אדברי המרדכי הללו ועד\"ר שהבאתי לשונו:"],["\u0003 האומר לחבירו קרע כסותי כו' \u0004 עיין בתשובת מבי\"ט ח\"ב סי' ש\"ו ובתשו' רשד\"ם סי' נ' ושמ\"ה ותל\"ה ועיין בש\"ג פרק המפקיד דף ע\"ט סוף ע\"א:","\u0003 או אחר א' מהעריות כו'. \u0004 ל' הטור בין חייבי כריתות בין חייבי מיתות ב\"ד או אחר זכר לרבעו כו' ור\"ל ואע\"ג דבחיוב כריתות אין על הרודף חיוב מיתת ב\"ד מ\"מ פטור על שבירת כלים דקלב\"מ שמתחייב בנפשו בידי שמים עכ\"ל סמ\"ע וכל זה תמוה דסוגיי' דעלמא לאפוקי מדר' נחוני' בן הקנה ולא אמרי' קלב\"מ אלא בחייבי מיתות ב\"ד כדאית' בכתובות ד' ל' ובשבועות דף ל\"ג ובכמה דוכתי וכ\"פ כל הפוסקים בהרבה מקומות ועוד דאפי' ר' נחוניא מודה הכא דמעידנא דרדף חייב בתשלומין כדאיתא בכתובות שם מעידנא דאגבי' קני' כדלעיל סי' ש\"ן ולקמן סי' שפ\"ה אלא הדבר פשוט דהכ' ה\"ט דמתחייב הריג' שהרשות להנרדפים להרגו להציל עצמן בנפשו וכן מוכח להדיא בש\"ס פ' הגוזל בתרא (בבא קמא דף קי\"ז) ובסנהדרין דף ע\"ד ע\"א וכן פירש\"י שם להדיא וזה שכ' שכיון שרדף התיר עצמו למיתה ולדבריו קשה ל\"ל רודף וזה ברור וכ\"כ הגאון אמ\"ו בגליון סמ\"ע שלו:","\u0003 ומצוה רבה עשה כו' \u0004 עיין בתשו' רשד\"ם סי' שד\"מ ושפ\"ט:","\u0003 וי\"א דוקא שטוענין כו' \u0004 עיין בסמ\"ע ס\"ק ט' עד כשאחד או שנים מבני הספינה שהטעינו בספינה באחרונה הן הן שהכבידו בטעינתן כו' היינו כששכרו לספן באחרונה אבל אם שכרוהו בשוה ביחד לא הפסיד זה האחרון כן נ\"ל וכל הישובים שם בסמ\"ע דחוקים ויפה כוון הנ\"י שמהרמב\"ם משמע דבכל ענין פטור ולכך השיגו ראב\"ד וכ\"כ רש\"ל פ\"י דב\"ק סי' נ\"ב ע\"ש:","\u0003 אבל אם אינה טעונה כו'. \u0004 אין לשון זה מדוקדק דלדין זה כ\"ע מודים:","\u0003 להכניס חמורים כו' \u0004 דהיינו שאין דרכן לקפוץ:","\u0003 חייב. \u0004 וכ\"פ מהרש\"ל פ\"י דב\"ק סי' נ\"ב וע\"ש וכן עיקר ודלא כהעיר שושן שכתב וי\"ח:","\u0003 דאז החמור כו' \u0004 אין ל' זה מדוקדק אלא בעל החמור מקרי רודף:"]],["\u0010y0\u0011 חֲמִשָּׁה שֶׁיָּשְׁבוּ עַל הַכִּסֵא וְלֹא נִשְׁבַּר, וּבָא אַחֲרוֹן וְיָשַׁב עָלָיו \u0010y1\u0011 וְנִסְמַךְ עֲלֵיהֶם וְלֹא הִנִּיחָם לַעֲמוֹד וְנִשְׁבַּר, אַף עַל פִּי שֶׁהָיָה רָאוּי לִשָּׁבֵר בָּהֶם קֹדֶם \u0005(שֶׁיָּשַׁב)\u0006, הוֹאִיל וְקֵרַב שְׁבִירָתוֹ, הָאַחֲרוֹן חַיָּב, שֶׁהֲרֵי אוֹמְרִים לוֹ: אִלּוּ לֹא נִסְמַכְתָּ \u0005(עָלָיו)\u0006 [עָלֵינוּ] הָיִינוּ עוֹמְדִים קֹדֶם שֶׁיִּשָּׁבֵר. וְאִם יָשְׁבוּ כְּאֶחָד וְנִשְׁבַּר, כֻּלָּם חַיָּבִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דִּסְתַם סַפְסָל הִיא שְׁאוּלָה לִסְתָם בְּנֵי אָדָם וְאִם נִשְׁבְּרָה תַּחְתֵּיהֶן הָוֵי כְּמֵתָה מֵחֲמַת מְלָאכָה וּפְטוּרִים מִלְּשַׁלֵּם (טוּר ס\"ב בְּשֵׁם הָרֹא\"שׁ תוס' פ\"ק דְּב\"ק)\u0006, \u0010y2\u0011 אֶלָּא אִם כֵּן הַיּוֹשְׁבִים הֵם מְשֻׁנִּים וּשְׁמֵנִים וּכְבֵדִים מִשְּׁאָר בְּנֵי אָדָם, אָז אִם יָשְׁבוּ עָלֶיהָ בְּיַחַד וְנִשְׁבְּרָה תַּחְתֵּיהֶן כֻּלָּם חַיָּבִים לְשַׁלֵּם; וְאִם יָשְׁבוּ בְּזֶה אַחַר זֶה, אִם לֹא הָיְתָה נִשְׁבֶּרֶת בְּלֹא יְשִׁיבַת הָאַחֲרוֹן, הוּא לְבַד חַיָּב לְשַׁלֵּם. וְאִם הָיְתָה נִשְׁבֶּרֶת בְּלֹא הָאַחֲרוֹן, הוּא פָּטוּר. וְאִם לֹא הָיְתָה נִשְׁבֶּרֶת רַק תּוֹךְ ב' שָׁעוֹת, וְעִמּוֹ נִשְׁבְּרָה תּוֹךְ שָׁעָה, אָז רוֹאִין, \u0010y3\u0011 אִם סָמַךְ עֲלֵיהֶן וּמְנָעָן לַעֲמֹד, הוּא לְבַד חַיָּב לְשַׁלֵּם; \u0010y4\u0011 וְאִם לָאו, כֻּלָּן חַיָּבִין \u0005(הַכֹּל בַּטּוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.",["\u0003ה' שישבו על הכסא \u0004 כן הוא ל' הרמב\"ם בפ\"ו דחובל אבל ל' הגמ' והטור שישבו על הספסל:","\u0003ונסמך עליהן ולא הניחם לעמוד כו' \u0004 הטור הביא דברי הרמב\"ם ולא כ' הני ה' תיבות ונסמך עליהם ולא הניחם לעמוד וגם במיימוני ליתניהו לא בדפוס גדול ולא בדפוס קטן ובדריש' כתבתי והוכחתי שהטור לא פי' לדברי הרמב\"ם בעל דעה זו שכ' המחבר דמיירי בנשען זה שבא אחרונ' עליהן ומנעם מלעמוד ודוקא לרש\"י והרא\"ש פי' הכי ומ\"ש הרמב\"ם אח\"כ שא\"ל אילו לא נסמכת עליו היינו עומדין מ\"ש נסמכת עליו ר\"ל עליו דספסל ור\"ל אלו לא באת לסמוך ולקרב ולישב על הספסל היינו עומדין ודמ\"ה א\"י האחרון לו' לקמאי הי' לכם לעמוד כשישבתי דמיירי שנשבר עד שלא ידעו עדיין שרוצה לישב שם ומיד שבא אצלם והתחיל לסמוך על הספסל נשבר ובדפוס כ\"מ נדפס אילו לא נסמכת עלינו ונדפס כן ע\"פ פי' המ\"מ דפי' לדברי הרמב\"ם כרש\"י ואחריהן נמשך הע\"ש וכ' נסמכת עלינו ואינו נראה וכמ\"ש בדרישה ע\"ש:","\u0003אא\"כ היושבין הם משוני' כו'. \u0004 ובכה\"ג אפי' א' לבד שיושב עליו הוא חייב דב\"ה מסתמא מקפיד על ישיבתו עליו הואיל והוא משונה:","\u0003אם סמך עליהן ומנען מלעמוד כו'. \u0004 קמ\"ל בזה דלא אמרי' כחו לאו כגופו דמי וגרמא בעלמא הוא הואיל וגם זולתו הי' נשבר ועד\"ר:","\u0003ואם לאו כולן חייבים \u0004 די\"ל להו האחרון הי' לכם לעמוד כשבאתי לישב עליו והרי יש לי רשות לישב עליו כמותכם:"],[]],["\u0010c0\u0011 שׁוֹר שֶׁהָיָה עוֹמֵד לַהֲרִיגָה מִפְּנֵי שֶׁהוּא מַזִּיק אֶת הַבְּרִיּוֹת, וְאִילָן הָעוֹמֵד לִקְצִיצָה מִפְּנֵי שֶׁהוּא מַזִּיק אֶת הָרַבִּים, וְקָדַם אֶחָד וְשָׁחַט שׁוֹר זֶה וְקָצַץ אִילָן זֶה שֶׁלֹּא מִדַּעַת הַבְּעָלִים, חַיָּב לְשַׁלֵּם לַבְּעָלִים \u0010y0\u0011 כְּמוֹ שֶׁיִּרְאוּ הַדַּיָּנִים, שֶׁהֲרֵי הִפְקִיעָם מִלַּעֲשׂוֹת מִצְוָה. וְאִם טָעַן וְאָמַר: אַתָּה אָמַרְתָּ לִי לְהָרְגוֹ וּלְקָצְצוֹ, \u0010y1\u0011 הוֹאִיל וְהוּא עוֹמֵד לְכָךְ, הֲרֵי זֶה פָּטוּר. \u0005אֲבָל שְׁאָר מַזִּיק אֵינוֹ נֶאֱמָן לוֹמַר שֶׁהוּא נָתַן לוֹ רְשׁוּת (טוּר ס\"ג)\u0006, אֲפִלּוּ יֵשׁ לוֹ מִגּוֹ לוֹמַר: לֹא הִזַּקְתִּי, כְּגוֹן דְּלֵיכָּא עֵדִים שֶׁהִזִּיקוּ, דְּהָוֵי \u0010y2\u0011 כְּמִגּוֹ בְּמָקוֹם חֲזָקָה דְּלָא הָוֵי מִגּוֹ \u0005(מָרְדְּכַי וְנ\"י פֶּרֶק הַחוֹבֵל)\u0006. \u0010y3\u0011 \u0010c1\u0011 אֲבָל נֶאֱמָן לוֹמַר לֹא הִזַּקְתִּי: \u0005(נ\"א אַתָּה אָמַרְתָּ לִי וְכו')\u0006 בְּמִגּוֹ דְלָא הָיָה שֶׁלְּךָ מַה שֶּׁהִזַּקְתִּי אֶלָּא שֶׁלִּי הָיָה \u0005(מָרְדְּכַי שָׁם)\u0006. וְכֵן מִי שֶׁשָּׁחַט חַיָּה וָעוֹף, \u0010y4\u0011 וּבָא אַחֵר וְכִסָה הַדָּם שֶׁלֹּא מִדַּעַת הַשּׁוֹחֵט, חַיָּב לִתֵּן כְּמוֹ שֶׁיִּרְאוּ הַדַּיָּנִים. וְיֵשׁ מִי שֶׁהוֹרָה, שֶׁהוּא נוֹתֵן קְנָס קָצוּב, \u0010y5\u0011 \u0010c2\u0011 וְהוּא י' זְהוּבִים. וְכֵן הוֹרוּ, שֶׁכָּל הַמּוֹנֵעַ הַבְּעָלִים מִלַּעֲשׂוֹת מִצְוַת עֲשֵׂה שֶׁהֵם רְאוּיִים לַעֲשׂוֹתָהּ, וְקָדַם אַחֵר וַעֲשָׂאָהּ, מְשַׁלֵּם לַבְּעָלִים י' זְהוּבִים. \u0010c3\u0011 \u0010c4\u0011 \u0010c5\u0011 \u0010c6\u0011 \u0010c7\u0011 \u0010c8\u0011 \u0010c9\u0011 \u0010c10\u0011 \u0010c11\u0011 \u0005הָיָה לוֹ בֵּן לָמוּל, וּבָא אַחֵר וּמָלוֹ, חַיָּב לִתֵּן לוֹ י' זְהוּבִים. אֲבָל נְתָנוֹ לְאַחֵר \u0010y6\u0011 לָמוּל, וּבָא אַחֵר וּמָלוֹ, פָּטוּר (רַבֵּנוּ יְרוּחָם נל\"א ח\"ד)\u0006. וּבַזְּמַן הַזֶּה אֵין מַגְבִּין אוֹתוֹ, אֲבָל אִם תָּפַס לֹא מַפְקִינָן מִנֵּהּ:",["\u0003כמו שיראו הדיינים. \u0004 נראה דראיית עיני דיינים בזה ובביטל ממנו שאר מצות עשה דבסמוך הוא דיראו אם איש זה שביטל ממנו המצוה הוא איש שמדקדק בקיום שאר מצות אזי יקנסו המבטל ממנו הרבה ולפי מיעוטו בדקדוק מצות ימעט הקנס מהמבטל גם ישערו בטרח' קיום המצו' דפעמים מונע אדם עצמו מהמצוה מכח טירחא וניחא ליה שאחרים יעשה עד\"ר:","\u0003הואיל והוא עומד לכך כו'. \u0004 די\"ל דלמא ירא שיזיק אחרים והוא לא הי' לו פנאי לעסוק בהריגת השור ובקציצת האילן ונתן לו רשות להורגו ולקצצו ושכח הדבר שנתן רשו' לזה:","\u0003כמיגו במקום חזקה כו' \u0004 דחזק' הוא דאין אדם מצוה לאחר לעשות לו דבר שמזיק לו בממונו:","\u0003אבל נאמן לו' לא הזקתי \u0004 במיגו דלא הי' שלך קשה למה לי' מיגו לטענ' דלא הזקתי דמהיכי תיתי יהי' נאמן לטעון עליו שהיזק בלא עדים וגם לפני זה כ' מור\"ם ז\"ל ואפי' יש לו מיגו לומר לא הזקתי כגון דליכא עדים שהזיקו שמע מיני' דהי' נאמן לטעון לא הזקתי היכא דליכא עדים אפי' בלא מיגו שוב ראיתי במרדכי דפרק החובל במקום מקור דין זה שם נלמד דמ\"ש מור\"ם כאן דנאמן לומר לא הזקתי דר\"ל מה שעשיתי ברשותך עשיתי ונמצא דאינו מזיק בזה אינו נאמן אם לא במיגו דלא הי' שלך וכן מוכח בד\"מ ע\"ש:","\u0003ובא אחר וכיסה כו' \u0004 דוקא בכה\"ג דמצות כיסוי רמיא על השוחט שנא' ושחט וכסה מי ששחט הוא יכסה אבל אם נתנו לו בהמה לשחוט ובא אחר ושחטו פטור דשאני מצוה דנצטוינו לעשותו כגון כיסוי הדם דלאחר ששחט א\"א להפטר מהכיסוי דוקא קנסי' משא\"כ שחיט' דאי לא רצה לאכול בשר אינו מחויב לשחוט ועפ\"ר:","\u0003והוא י' זהובים כן הי' מעשה בגמ' שבא א' לפני ר' גמליאל וקנסוהו י' זהובים רק שדע' קמייתא ס\"ל שראות עיניו דר\"ג באותו איש כך הי' ושכל דיין יקנוס כפי ראות עיניו וכנ\"ל ועד\"ר:\u0004","\u0003ובא אחר ומלו פטור. \u0004 בי\"ד ס\"ס כ\"ח סיים בזה וכ' ז\"ל והכא אפי' תפס מפקינן מיניה כיון דענה אמן דהא אמרי' גדול העונה אמן יותר מן המברך ואם שמע ולא ענה איהו דאפסיד אנפשי' אבל אין לפוטרו מטעם שיתן לו תרנגול לשחוט דזו מצוה אחרת היא ומצוה ראשונה הלכה לה ומעוות אשר לא יוכל לתקן הוא עכ\"ל ושם כתבתי דנראה דלא פטרו מכח עניית אמן אלא במצו' מילה דנתקנ' ברכ' בצבור ובקול רם דכיון דצריך לברך בקול רם ודאי שמע הברכה משא\"כ בברכת השחיטה ומ\"ה כתבתי לעיל בסמוך וגם שם טעם אחר לנתנו לו תרנגול או בהמה לשחוט וקדמו אחר ושחטו דאין קונסין אותו דלא מחשב מצוה דרמיא עלי' דאינשי ☜ ונראה דמה\"ט אם קדם אחד ומל בנו של חבירו אף שהאב יכול לענות אמן אחר המברך מ\"מ כיון דהמצוה מיוחדת לאב בבנו יותר מלשאר כל אדם לא פטרינן להמקדים מכח עניית אמן דהאב ובע\"ש כתב טעמים אחרים לפטור זה שקדם ומל ע\"ש ולא שם לבו למ\"ש בי\"ד ס\"ס כ\"ח וכנ\"ל:"],["\u0003 שור כו' ואילן כו'. \u0004 חייב לשלם לבעלים כמו שיראו הדיינים כו' משמע מדברי הרמב\"ם והמחבר אלו שקנס הוא זה ולא דינא דאי ס\"ל דינא הוא פשיטא שחייב ליתן לו י' זהובים כמו שחייב ר' גמליאל גבי כיסוי וכדמשמע בפוסקים שהבאתי לקמן דחד דינא אית להו אלא ס\"ל דקנס הוא שקנס ר\"ג לפי ראות עיניו וא\"כ הכל הוא כפי מה שיראו הדיינים וכ\"כ הסמ\"ג ד' קמ\"ח סוף ע\"א חייב לשלם כמו שיראו הדיינים וכן משמע עוד ממ\"ש הרמב\"ם והמחבר אח\"כ גבי כיסוי ויש מי שהורה שהוא נותן קנס קצוב כו' וכן ממ\"ש וכן הורו שכל כו' ובשלטי גבורים פרק החובל דף ל\"ד ע\"א כ' דנראה מסוף דברי הרמב\"ם דדינא הוא מאחר שכ' שהורו כן בכל המצות אלמא גמרינן מיניה ולפע\"ד לא משמע כן מדברי הרמב\"ם ומה שהקש' הרי\"ף ס\"פ החובל על האיכא מ\"ד דקנסא הוא א\"כ היכי יליף רב מיניה לשור ואילן. חתני הנבון ה\"ר מאנש השיב ע\"ז דהא שפיר י\"ל רב לטעמיה דס\"ל בפ' הניזקין (ריש גיטין דף נ\"ב) גבי מטמא ומדמע ומנסך דמקנסא ילפי' (הג\"ה ולשמואל בש\"ס שם לא ילפי' וס\"ל לאיכא מ\"ד דקי\"ל כשמואל בדיני ולא ילפי' מקנסא וכמ\"ש הרמב\"ן בדיני גרמי שלו) ועיין מה שכתבתי בזה לקמן סימן שפ\"ה ס\"ק א'. והבאתי שם עוד ראיות דמקנסא ילפינן:","מיהו י\"ל דכוונת הרמב\"ם דלכ\"ע דינא הוא אלא דבברכה נהי דחייבו ר\"ג ליתן י' זהובים מ\"מ במצוה אפשר שאינו נותן י' זהובים רק כפי מה שיראה לדיינים ואח\"כ כתב יש מי שהורה כן בכל המצות ומ\"ש הרמב\"ם ויש מי שהורה שהוא נותן קנס קצוב כו' ר\"ל אע\"ג דדינא הוא מ\"מ קנס הוא כמו שאר קנסות הכתובים בתורה שקצובים הן והם דין תורה ולא קנסא דרבנן שאינן קצובים וכן נראה מהרב המגיד שזה היא דעת הרמב\"ם וע\"ש וכן משמע בר' ירוחם שכתב בספר אדם נתיב ט\"ו ח\"ד גבי כיסוי וז\"ל ומתוך דברי הרמב\"ן נראה שאינו שוה י' זהובים אלא הברכה אבל מצוה בלא ברכה לא וכן נראה דעת קצת זולתו ואחרים כתבו שכל מצוה שוה י' זהובים והביאו ראיה מפרק החובל גבי שור ואילן וכן פסק שם הרי\"ף כו' ע\"כ ונראה שמ\"ש הרמב\"ן ט\"ס הוא וצ\"ל הרמב\"ם ומ\"מ אין זה מוכרח וי\"ל שדעת הרמב\"ם כמו שכתבתי:","\u0003ועכ\"פ נראה ברור דמ\"ש הרמב\"ם והמחב' ויש מי שהורה כו'\u0004 וכן הורו שכל כו' קאי אכל מה שהזכירו מקודם דהיינו בשור ואילן ג\"כ וכן משמע בהרי\"ף והרא\"ש ס\"פ החובל דחד דינא אית להו ובכולהו משלם י' זהובים וכ\"פ מהרש\"ל פ' החובל סי' ס' ע\"ש וכ\"פ הרשב\"א בחדושיו ס\"פ כיסוי הדם וז\"ל ואסיקנא דשכר ברכה י' זהובים וה\"ה למצוה בלא ברכה כדאמ' בפרק החובל בשור העומד להריגה ואילן העומד לקציצה וכלן שכרן שוה עשרה זהובים שאין שמין את המצות להקל ולהחמי' אלא כך כולן שכרן עכ\"ל וכ\"כ הר\"ן שם וקשה לי על הטור שכ' חייב לשלם כפי מה שיראו הדיינים שהרי הרא\"ש פסק דדינא הוא ועוד שהרי הוא עצמו כ' אח\"כ גבי כיסוי חייב ליתן לו י' זהובים וכן הדין בכל מצות עשה שהוא עליו לעשות וקדם אחר ועשא' ומנע את זה מלעשות חייב ליתן לזה י' זהובים וא\"כ אמאי כ' כאן כפי מה שיראו הדיינים הלא גם זה מצות עשה הוא כדלקמן סי' תכ\"ז סעיף ח' וצל\"ע:","\u0003 אבל נאמן לו' לא הזקתי כו'. \u0004 כלו' לא עשיתי לך היזק בזה כגון שפטר החובות שלו ואומר שבלאו הכי נמי לא היו משלמים וכה\"ג ועיין מ\"ש לעיל סי' קע\"ו סי\"א בהג\"ה ומ\"ש שם:","\u0003 והוא י' זהובים \u0004 בש\"ס פרק כיסוי הדם (דף פ\"ז ע\"א) מסקינן דהוא שכר ברכת הכיסוי ובברכת המזון חייב מ' זהובים בעד ד' ברכות. ובספר לחם חמודות פרק כ\"ה ריש ד' קצ\"ב הביא דברי הר\"ן דבשכר מצוה נמי משלם והקשה עליו כיון דשכר מצוה בכיסוי איכא ישלם המצוה והברכה וצ\"ע עכ\"ל ולק\"מ דכדברי הר\"ן מוכח בש\"ס ס\"פ החובל ובתוס' שם ושאר הרבה פסקו שכולם כתבו להדיא דבשכר מצוה נמי משלם י' ובכיסוי לא משלם אלא י' ע\"ש בדבריהם וכ\"כ מהרש\"ל פ' החובל סי' ס' אלא ודאי ה\"ט דכיסוי דכיון דאי אפשר לברכה בלא מצוה אין משלם על המצוה:","וכתבו התוס' פרק כ\"ה וא\"ת דהל\"ל נ' זהו' דהא איכא ברכת פרי הגפן וי\"ל דסבר כמ\"ד דא\"צ לברך אכסא דברכתא אלא אכסא קמא ותו לא עכ\"ל וקשה לי דהא איתא התם א\"ל רבי כוס של ברכה אתה שותה או ארבעים זהובים אתה נוטל משמע שהיה מברך על הכוס מדקרי ליה כוס של ברכה ודוחק לו' דקרי ליה הכי משום דמברכין עליו ברכת המזון ועוד קשה דהא בפרק ערבי פסחים (פסחים דף ק\"ג) אמוראי הוא דפליגי התם בהכי ותיקשי מרבי לאותו אמורא דסבר צריך לברך ודוחק לו' דהתם תלמידי דרב סבאי צריך ורב תנא ופליג אלא נלפע\"ד לתרץ דכיון דהא דחייב י' זהו' אינו אלא במצוה דאורייתא ולא במצוה דרבנן וכמ\"ש מהרש\"ל בפ' החובל סי' ס' דנראה שבמצוה דרבנן פטור וא\"כ הטוב והמטיב ביבנה תקנוה ואינו אלא מדרבנן וא\"כ עם ברכת פרי הגפן ליכא אלא ד' וכן מוכרח לומר לדעת הרי\"ף והרא\"ש שהרי פסקו בפ' ערבי פסחי' דצריך לברך אכוס של בה\"מ ובס\"פ כיסוי הדם כתבו וחייבו ר\"ג ליתן לו י' זהובי' שכר ברכה ותו ההוא דסעד אצל רבי א\"ל כוס של ברכה אתה שותה או מ' זהו' אתה נוטל כו' משמע דאינו חייב אלא מ' זהובים וא\"כ א\"א לתרץ כמ\"ש התוס' אלא כמ\"ש כן נ\"ל:","שוב מצאתי בר' ירוחם בס' אדם נתיב ט\"ו ח\"ד גבי כיסוי כדברי ושמחתי וז\"ל שם כ' ה\"ר צמח ולדידי קשיא הא דאמרי' ששוה מ' זהובים כנגד ד' ברכות והא ה' הן ד' של ברכת המזון וא' של יין ויש לי לתרץ שלא מנו אלא הג' ברכות שבברכת המזון שהן מן התורה ולא מנו הרביעית מפני שהיא מדבריהם עכ\"ל. אבל בס' מישרים גבי דיני נזיקין נל\"א סוף ח\"ד כ' רבי' ירוחם וז\"ל כוס של ברכה מ' זהו' וברכת פרי הגפן אינה מן המנין כי היא ברכת הנהנין עכ\"ל ולפ\"ז ברכת הטוב היא מן המנין ואפשר גם דעת הרי\"ף והרא\"ש כן:","\u0003 היה לו בן למול כו' \u0004 פטור כ' הסמ\"ע וז\"ל עיין בי\"ד ס\"ס כ\"ח כ' וז\"ל והכא אפי' תפס מפקינן מיניה כיון דענה אמן דהוא גדול יותר מן המברך ואם שמע ולא ענה איהו דאפסיד אנפשיה כו' ע\"כ אבל באב לא מהני עניית אמן כו' ובע\"ש כ' טעמים אחרים לפטור זה שקדם ומל ולא שם לבו למ\"ש בי\"ד ס\"ס כ\"ח וכנ\"ל עכ\"ל ואין דבריו נכונים דלא מסתבר כלל לחלק בעניית אמן בין אב לאחר וכן מוכח להדיא בר' ירוחם שממנו מקור דין זה דכשיכול לענות אמן אפי' באב דרמיא מצוה עליה פטור שכ' שם בנתיב ל\"א סוף ח\"ד וז\"ל ומי שאמר למוהל למול וקדם אחר ומהל פטור אבל אם גזלה מאביו חייב וכן המונע בעלים מלעשית מצוה וקדם ועשאה משלם י' זהובים ואי תפס לא מפקינן מיניה זולתי בשיכול לענות אמן עכ\"ל וכן מוכח להדיא מדברי מהרש\"ל פ' החובל סי' ס' דאין חילוק בין אב לאחר בזה. ועוד מוכח כן מדברי המעד\"מ והפריש' עצמו שהבאתי לקמן שפירשו דבהך דר\"ג הי' מברך בנחת אלמא דאי היה מברך בקול רם היה פטור משום שה\"ל לענות אמן והא התם מצות כיסוי עליה רמיא כמו מצות מילת הבן על האב דכתי' וש\"ך וכיס' וילפינן מיניה מי ששפך יכס' אלא ודאי כדברי הע\"ש ושלא כדת השיג הסמ\"ע על הע\"ש כי דברי הע\"ש נכונים וז\"ל ודוקא שהי' האב בעצמו רוצה לימול שהוא חייב בה מן התורה אבל נתנו האב לאחר לימול ובא אחר ומלו פטור מן האב פטור שהרי לא מנע ממנו המצוה ומן המוהל פטור דבמה זכה במצוה זו דבמה הקנה אותה לו האב ואפי' הקנה לו בקנין אינו כלום שאינו אלא קנין דברים כו' עכ\"ל וכדבריו מבואר בהרא\"ש ס\"פ כיסוי הדם שכתב מתחלה שר\"ת פטר בא' שנתנו לו בן למולו וקדם אחר ומלו מטעם דאין גובין קנס בזמן הזה ועוד דה\"ל לענות אמן וכתב הרא\"ש אח\"כ וז\"ל ובלא הנך טעמי דר\"ת נ\"ל לפטור המוהל דאע\"פ שאמר האב למוהל אחר למול את בנו לא זכה באותה המצוה לחייב אחר אם קדם ועשאה ולא דמיא לכיסוי דאמרה תורה ושפך וכיסה מי ששפך יכסה וכן האב שחייב למול את בנו ורצה למולו וקדם אחר חייב אבל אם אין האב רוצה למולו כל ישראל חייב למולו ובדבור שאמר האב למוהל לא זכה במצוה לחייב לאחר אם קדמו עכ\"ל וזה מבואר כדברי הע\"ש וכן מוכח ודאי מדברי ר' ירוחם הנ\"ל ודבריו לקוחים מדברי הרא\"ש הנ\"ל וכ\"כ עוד הרא\"ש בתשו' כלל י\"ב סי' ג' דאפי' הקנה לו בקנין למול אינו כלום דקנין דברים הוא ונתבאר בי\"ד ריש סי' רס\"ד בהג\"ה ע\"ש ומ\"ש הסמ\"ע על הע\"ש שלא שם לבו למ\"ש בי\"ד ס\"ס כ\"ח כו' (ר\"ל שכ' שם דפטור מטעם שה\"ל לענות אמן משמע הא לאו הכי חייב) אין ראיה משם שכבר כ' הב\"י והפריש' עצמו שם שאינו מדברי הטור רק שאחד הוסיף כן בטור ע\"ש ופשוט הוא שהטור בע\"כ ס\"ל דבלא\"ה פטור משום דלא זכה בו האחר וכמ\"ש הרא\"ש ואין ספק דאשתמיטתי' להסמ\"ע דברי הרא\"ש הנ\"ל בהבאתי ואלו היה ראה לא כ' כן וכן פסק מהרש\"ל פ' החובל סי' ס' כדברי הרא\"ש אלו דפטור מטעם דלא זכה בו האחר וע\"ש:","והרב והע\"ש כאן מיירי בענין שלא היה יכול לענות אמן כגון שדחפו או שבירך בנחת וכה\"ג וק\"ל. ומדברי הרא\"ש שהבאתי מוכח דמי שהוא מוהל אינו רשאי ליתן את בנו לאחר למוהלו וחייב הוא בעצמו למוהלו דומיא דכיסוי דמי ששפך הוא יכסה וכן משמע מדברי הרמב\"ם ריש הל' מילה דמצות עשה זו מוטל על האב תחלה והכי משמע פשטא דש\"ס פ\"ק דקדושין (דף כט ע\"א) דאמרי' התם האב חייב בבנו למולו מנלן דכתיב וימל אברהם את יצחק בנו והיכא דלא מהליה אבוהא מחייבי בי דינא לממהלי' כו' וכתבתי זה לפי שראיתי כמה אנשים מכבדים לאחרים למול את בניהם אף שהם בעצמם יכולים למול ולדעתי הם מבטלים מצוה עשה ומצוה גדולה של מילה ויש לב\"ד לבטל הדבר הזה:","כתב מהרש\"ל פ' החובל סי' ס' וז\"ל ולפי הטעם שפטר ר\"ת אותו המוהל ואפי' תפס מפקינן מיני' כיון שזה ענה אמן וגדול העונה אמן יותר מן המברך ואם לא ענה אמן איהו דאפסיד אנפשי' ע\"כ מיירי אליבא הא דר\"ג כיסהו בלי דעת חברו ואמר הברכה בנחת כדי שלא ישמע חברו או שדחפו ממנו שלא היה יכול לשמוע ולא מיחוור בעיני כלל דסתמא איירי ש\"ס בלא פלוג ומסתמא הי' מברך כדרך המברכין ופשיטא דלא איירי ברשיעי שהי' מונע את חברו לענות אמן ע\"כ נראה דאפי' ענה אמן נמי חייב אע\"פ שהעונה גדול היינו בלא עשיית מצוה כגון לענין ברכת ס\"ת ותפלה שהוא מניעת ברכה לבד אבל לענין כיסוי הדם ומילה שהיא מצות עשה לבד והברכה אינה מעכבת א\"כ מנע אותו מן המצוה ומצוה לבד ג\"כ חשוב י' זהובים אע\"פ דלא אמרי' מצוה לחוד וברכה לחוד לענין י' זהובים מ\"מ על מצוה לבד ג\"כ דנין עליה י' זהובים כמו שור ואילן דלעיל הלכך נראה דאם תפס אפי' בזמן הזה י' זהובים לא מפקי' מיניה ואף שכך פסק אילן גדול ונתלו בו עמודי עולם התוס' והרא\"ש והמרדכי והר\"ן ומתיירא אני שלא ירוצו גולגלתי אבל תורה היא וללמוד אני צריך והנרא' בעיני כתבתי עכ\"ל ואין דבריו נכונים ודברי התוס' והרא\"ש ומרדכי (ס\"פ כיסוי הדם וכן הוא בטור י\"ד ס\"ס כ\"ח בשם פסקי מה\"ר חזקי') וסייעתם הם דברי אלהים חיים דהא מיבעיא בש\"ס ס\"פ כיסוי הדם אהך דר\"ג אי שכר מצוה או שכר ברכ' ופשיט דהוא שכר ברכה מברכת המזון בעובדא דרבי דהי' מ' זהובים אלמא דאע\"ג דבכיסוי ומילה איכא ברכה ומצוה מ\"מ עיקר החיוב הוא על הברכה ועוד דמה בכך ס\"ס כיון דהעונה אמן גדול מהמברך ונוטל שכר י' זהובים א\"כ ה\"ז שקדם ומל לא הפסידו כלום שהרי מ\"מ יש לו הי' זהובים ולמה יחייב אלא בע\"כ צ\"ל דבהך עובדא דר\"ג לא הי' חברו יכול לענות אמן ואין זה דוחק כלל דלא איירי ברשיעי כמ\"ש מהרש\"ל שאמר בכוון הברכה בנחת שלא ישמע חברו או שדחפו אלא מיירי שעשה הברכ' לפי תומו בנחת וכ\"כ בס' מעד\"מ ס\"פ כיסוי הדם דהא דפטר ר\"ת במוהל משום דבמילה מברך בקול רם וכדשדר רב צמח גאון דהיכא דאפשר עבדינן ליה בעשר' אבל בכיסוי הדם דרכן לברך בנחת וכ\"כ בפריש' בי\"ד ס\"ס כ\"ח.","בספר מעד\"מ ס\"פ כ\"ה הקשה אהא דפטר ר\"ת משום דה\"ל לענות אמן דהא אמרי' בס\"פ אלו דברים (וכן בסוף מסכת סוטה) דרב דא\"ל לחייא ברי' חטוף ובריך לית לי' הכי ודחק שם וכ' דרש\"י שפי' ס\"פ כ\"ה שכר ארבע ברכות שעונה אחריהם אמן לית לי' הא דר\"ת דגדול העונה כו' ואין דבריו נכונים דאדרבא אפי' לרב דא\"ל לחייא בריה מוכח הכי דהא אמרי' התם דרב ס\"ל כהאי תנא דאמר אחד המברך ואח' העונה במשמע אלא שממהרין למברך יותר מן העונה אלמא דאפי' לרב יש לעונ' שכר כמברך אלא דפליגי אי ממהרין למברך תחל' וא\"כ פשיטא דדינו של ר\"ת אמת ומוכרח לכ\"ע דפטור דהא יש לעונה שכר כמו המברך וא\"כ איך אפשר שיחלוק רש\"י אהא וגם פירושו בדברי רש\"י שם אינו נכון כלל ע\"ש אלא נ\"ל כוונת רש\"י משום דל' רבי שאמר לההוא מינא כוס של ברכה אתה שותה לא משמע שהמין יברך דא\"כ הל\"ל ברכת המזון אתה מברך וכן משמע להדיא בתוס' שם שכתבו בשתיה לחוד לא הי' לו שכר אלא רצה לדחות המין ע\"ש וכן מסתמא רבי לא הי' נותן למין לברך על סעודתו אלא ודאי הכי א\"ל כוס של ברכה אתה שותה עמנו וא\"כ כי א\"ל מ' זהובים היינו שכר ברכות שעונה המין אמן וא\"כ אדרבה רש\"י ס\"ל כר\"ת כן נ\"ל: מרגלא בפומא דאינשי מי שמכבד לחברו לברך ברכת המזון שמכבדו במ' זהובים וכן שמעתי בשם כמה גדולים וכ\"כ בשלטי גבורים פ' החובל דף ל\"ד ע\"א מי שהזמינוהו לברך ברכת המזון ובא אחר וחטף ובירך חייב ליתן לו מ' זהובים וכן מבואר בש\"ס פ' כיסוי הדם כו' ע\"כ וכ\"כ רבי' ירוחם במישרים ונל\"א סוף ח\"ד גזל מצוה מחבירו חייב ליתן לו י' זהובים וכן בכוס של ברכה מ' זהובים ע\"כ וכן משמע בש\"ס פ' כ\"ה (דף פ\"ז ע\"א) גבי הא דבעי התם אעובדא דר\"ג שכר מצוה או שכר ברכה מאי נ\"מ לברכת המזון (ודוחק לו' דקאמ' מאי נ\"מ למי שמברך ברכת המזון אם יש לו שכר מ' זהובים ולא קאי אחטיפה דל' מאי נפקא מיני' לא משמע הכי) וקשה דהא כבר נתבא' דגדול העונ' אמן יותר מן המברך ומה\"ט פטרו ר\"ת והרא\"ש ומרדכי ושאר פוסקים כשקדם ומל דה\"ל לענות אמן וכמ\"ש לעיל ובהך עובדא דר\"ג כבר כתבתי לעיל שצ\"ל שהי' מברך בנחת אבל בברכת המזון אם לא הי' זה מכבדו והי' עונה אמן הי' ג\"כ מ' זהובים וא\"כ היכא משכחת לה דכשחטף חברו יחייב במ' זהובים וגם ר' ירוחם גופי' כ' שם זולתי בשיכול לענות אמן אלמא דפטור כשיכול לענות אמן וא\"כ היאך חייב מ' זהובים בברכת המזון שמברכין בזמון בקול רם ואפי' תימא שזה שחטף עשה שלא כדין וברך בנחת ובכה\"ג מ\"מ הרי הנחטף חייב לברך ג\"כ בפני עצמו ברכת המזון כיון שאינו חברו מוציאו וא\"כ הרי יש לו המ' זהובים שלו ונראה דאין לאדם שכר ברכה י' זהובים אלא על ברכה שמברך בפני אחרים אבל בינו לבינו לא וא\"כ בש\"ס וש\"ג ור' ירוחם מיירי בענין שלא יוכל לענות אמן כגון שחטף מחברו כוס של ברכת המזון ודחפו חוץ לבית וסגר בפניו עד שברכו והלכו להם וכה\"ג וא\"כ נהי שזה יברך אח\"כ לעצמו מ\"מ כיון שיברך בינו לבינו לא יהי' לו שכר ר' זהובים על הברכה וא\"כ בהך עובדא דר\"ג צ\"ל שחייבו על הברכ' לפי שזה ששחט הי' רצונו לברך בקול רם בפני אחרים וזה קדם וברך בנחת וכה\"ג ולפ\"ז מה דמרגלא בפומא דאינשי ליתא שאין מכבדו בכלום כיון שבלאו הכי יכול לענות אמן ואפשר שר\"ל שמכבדין מה שממהרין לשלם למברך תחלה וכמ\"ש לעיל ועדיין צ\"ע:","ולענין ברכת ספר תורה עיין בהרא\"ש ומרדכי שם שכתבו בשם ר\"ת דפטו' ומהרש\"ל פ' החובל סי' ס' כ' דהאידנא שקונין המצות בדמים אם קנה א' שלישי או ששי או שביעי וקדמו אחר חייב ליתן לו י' זהובים אי תפס ואין דבריו מוכרחים. וע\"ש עוד במהרש\"ל כמה חילוקי דינים בענינים אלו:"]],["הִנִּיחַ גַּחֶלֶת עַל לֵב שׁוֹר \u0010y0\u0011 \u0010c0\u0011 חֲבֵרוֹ כְּשֶׁהוּא כָּפוּת, וְנִשְׂרַף; \u0010y1\u0011 אוֹ שֶׁדְּחָפוֹ לַיָּם, חַיָּב. וְאִם הִנִּיחַ גַּחֶלֶת עַל לֵב חֲבֵרוֹ וְנִשְׂרַף, יִתְבָּאֵר בְּסִימָן תי\"ח.\nשׁוֹר שֶׁעָלָה עַל גַּב שׁוֹר \u0010y2\u0011 לְהָרְגוֹ, בִּרְשׁוּת הַנִּזָּק שֶׁהוּא בַּעַל הַתַּחְתּוֹן, \u0010y3\u0011 בֵּין שֶׁהָיָה תָּם בֵּין שֶׁהָיָה מוּעָד, וּבָא בַּעַל הַתַּחְתּוֹן \u0010y4\u0011 וְשָׁמַט אֶת שׁוֹרוֹ לְהַצִּילוֹ, וְנָפַל עֶלְיוֹן וָמֵת, הֲרֵי זֶה פָטוּר. דְּחָפוֹ לָעֶלְיוֹן וָמֵת, \u0010y5\u0011 אִם הָיָה יָכוֹל לְשָׁמְטוֹ וְלֹא שְׁמָטוֹ, \u0010c1\u0011 הֲרֵי זֶה חַיָּב. וְאִם לֹא הָיָה יָכוֹל לְשָׁמְטוֹ, הֲרֵי זֶה פָּטוּר. \u0005הַגָּה: \u0010y6\u0011 וְכֵן רְאוּבֵן שֶׁלָּקַח כְּלִי שֶׁל שִׁמְעוֹן וְסָמַךְ בּוֹ חָבִיתוֹ שֶׁל יַיִן שֶׁלֹּא יִפֹּל, וּבָא שִׁמְעוֹן וְנָטַל כְּלִי שֶׁלּוֹ וְנִשְׁבַּר חָבִיתוֹ שֶׁל יַיִן, שִׁמְעוֹן \u0010y7\u0011 חַיָּב, דְּהָיָה לוֹ לְסָמְכוֹ בְּדָבָר אַחֵר (תְּשׁוּבַת הָרֹא\"שׁ כְּלָל ק\"א סִימָן ג')\u0006.\nשְׁנַיִם שֶׁהֵמִיתוּ אֶת הַבְּהֵמָה, אוֹ שָׁבְרוּ אֶת הַכְּלִי כְּאֶחָד, \u0010y8\u0011 מְשַׁלְּמִים בֵּינֵיהֶם.\nה' שֶׁהִנִּיחוּ ה' חֲבִילוֹת עַל הַבְּהֵמָה, וְלֹא מֵתָה, וּבָא זֶה הָאַחֲרוֹן וְהִנִּיחַ חֲבִילָתוֹ עָלֶיהָ וָמֵתָה, אִם הָיְתָה מְהַלֶּכֶת בְּאוֹתָם הַחֲבִילוֹת וּמִשֶּׁהוֹסִיף זֶה חֲבִילָתוֹ עָמְדָה וְלֹא הָלְכָה, \u0010y9\u0011 הָאַחֲרוֹן חַיָּב; וְאִם מִתְּחִלָּתָהּ לֹא הָיְתָה מְהַלֶּכֶת, הָאַחֲרוֹן פָּטוּר. וְאִם אֵין יָדוּעַ, כֻּלָּם מְשַׁלְּמִין בְּשָׁוֶה.\nהַכּוֹבֵשׁ בֶּהֱמַת חֲבֵרוֹ בְּמַיִם, אוֹ שֶׁהִנִּיחָהּ בַּחַמָּה, וְצִמְצֵם עָלֶיהָ הַמָּקוֹם כְּדֵי שֶׁלֹּא תִּמְצָא צֵל עַד שֶׁהָרַגְתָּהּ הַחַמָּה, חַיָּב. \u0005הַגָּה: וְדַוְקָא שֶׁאָחֲזָהּ בְּיָדוֹ; אֲבָל סָגַר עָלֶיהָ הַדֶּלֶת שֶׁלֹּא תֵּצֵא, יֵשׁ אוֹמְרִים דְּפָטוּר מִדִּינֵי אָדָם (טוּר ס\"ו)\u0006.",["\u0003כשהוא כפות. \u0004 דוקא כשהוא כפות אבל כשאינו כפות יכול להתנצל ולומר הייתי סבור שהשור ינענע מעליו כדרכו כשירגיש החמימות דהגחלת ומזלו דבעל השור גרם לו ובהניח גחלת על עבד של חבירו אפי' הוא כפות פטור המניח דיכול המניח להתנצל ולומר סברתי שרבו של העבד יסיר הגחלת ממנו ולא יניחנו לשרוף כיון דחייב במצות ול\"ד לשור די\"ל דסמך בעל השור על התשלומין דמה לי שור ומה לי דמיו משא\"כ נפש עבדו דחייב במצו' ודברי' אלו כתבן הטור כאן בקיצור ועיקר' לקמן בדין האש סי' תי\"ח סעי\"ח מ\"ה לא כתבן המחבר ג\"כ כאן רק שקיצר שם ולא הזכיר כפות לא בשור ולא בעבד וצ\"ל שסמך אמ\"ש כאן אבל א\"ל שכ' שם ע\"פ שיטת פירש\"י שפי' בלא כפות מאחר שכ' כאן דמיירי בכפות והוא כדעת התוס' והרא\"ש והטור בשם רשב\"ם ועמ\"ש עוד בדרישה ובסמ\"ע שם סי' תי\"ח:","\u0003או שדחפו לים. \u0004 זהו איירי אפי' בלא כפות:","\u0003להרגו ברשות הניזק \u0004 כן הוא ל' הרמב\"ם בפ\"ו דחובל ומשמע דברשות המזיק אם נכנס שור הניזק שם ועלה עליו שור המזיק אפי' שמט הניזק לשור שלו ונפל שור של המזיק חייב הניזק לשלמו ולשטתו אזל הרמב\"ם דס\"ל לפטור המזיק כשמזיק ברשותו אפי' הכניס הניזק כליו שם ברשות וכמ\"ש הטור לעיל בסי' שע\"ט בשמו ע\"ש וכיון שהמזיק פטור בהזיקו נמצא שהניזק הזיקו שלא כדין וחייב לשלם לו היזקו וכ\"כ הב\"י אבל הטור השמיט ולא כתב ברשות הניזק וגם לעיל ס\"ס שע\"ט פסק דלא כהרמב\"ם וע\"ש ועד\"ר:","\u0003בין שהי' תם כו'. \u0004 פי' ל\"מ כשהוא תם דאם לא יציל את שורו אזי לא יפרע אלא מגופו של תם ח\"נ דהרשות נתונה לו לדחפו להעליון אלא אפי' אם הוא מועד דאז ישתלם מבעל השור מעלייתו אפ\"ה בכה\"ג עביד אינש דינא לנפשי' להציל את שלו:","\u0003ה\"ג ושמט את שורו להצילו. \u0004 וכן הוא בברייתא וברמב\"ם:","\u0003אם הי' יכול לשומטו כו'. \u0004 פי' לשמט העליון מהתחתון בנחת ולא הי' לו לדוחפו בכח עד שמחמתו מת אבל ברישא דהשמיט השור שלו ניתן לו רשות להצילו וא\"צ לדקדק אף שהי' יכול להשמט העליון בנחת:","\u0003וכן ראובן שלקח כלי של שמעון כו' \u0004 תיבת וכן ד\"ל דכמו בשור הנ\"ל כיון דיש לו תקנה בשמיטת שור העליון כשלא שמטו חייב כן נמי בזה כיון שיש לו תקנה בסמיכת דבר אחר ול\"ד להרישא דיש בידו רשות להשמט התחתון וא\"צ לחוש שיפול העליון וימות ולא חילק באם יש לו תיקון בהשמטת העליון בנחת וכמ\"ש דשאני התם דבא להציל את שלו שלא ימיתנו העליון ואדם בהול על ממונו משא\"כ כאן דאין החביות מזיק להכלי וק\"ל:","\u0003חייב דה\"ל לסומכו בדבר אחר. \u0004 שם בתשוב' הרא\"ש סיים בזה ז\"ל אבל אם סמכו בדבר אחר פטור אע\"ג דאין האבן גדול כהראשון עכ\"ל והביאו בד\"מ וע\"ל סי' ת\"י סכ\"ט ובסמ\"ע מ\"ש דל\"ת מזה:","\u0003משלמין ביניהן. \u0004 קמ\"ל אף דיש בהכאה דכל א' כדי להמית לא אמרי' דישלמו כל א' מהן את כולה:","\u0003האחרון חייב. \u0004 ולא מצי למימר זה הי' לכם ליקח חבילתכם ממנו כשהנחתי את שלי כדאמרי' לעיל בה' שישבו על הספסל בסי' שפ\"א דשאני התם דמיירי דגם זולת האחרון הי' נשבר לאחר זמן דמ\"ה א\"ל כיון דהייתם צריכים לעמוד עכ\"פ לאחר זמן הי' לכם לעמוד מיד משא\"כ בחבילות הללו וכן בטעינות הספינות בס\"ס ש\"פ וכמ\"ש בדרישה בסי' שפ\"א ע\"ש:"],["\u0003 כשהוא כפות. \u0004 ע\"ל סימן תי\"ח:","\u0003 הרי זה חייב כו'. \u0004 ומתוך כך פסק המרדכי ב' אנשים שמכין זא\"ז ובא אחד ודחף אחד מן חבירו חייב לעשות לו דין דהיה לו לשומטו בנחת (הגה וכ\"פ בפסקי מהרא\"י סי' ר\"ח):"]],["אֶחָד הַמַּזִּיק בְּיָדוֹ \u0005אוֹ בִּשְׁאָר גּוּפוֹ (טוּר ס\"א)\u0006, אוֹ שֶׁזָּרַק אֶבֶן אוֹ יָרָה חֵץ וְהִזִּיק בּוֹ, אוֹ שֶׁפָּטַר \u0005(פֵּרוּשׁ, שֶׁפָּתַח)\u0006 מַיִם עַל חֲבֵרוֹ אוֹ עַל הַכֵּלִים וְהִזִּיק, אוֹ שֶׁרָק וְנָע וְהִזִּיק בְּכִיחוֹ \u0005(פֵּרוּשׁ, רֹק עָב הַיּוֹצֵא בְכֹחַ)\u0006 וְנִיעוֹ \u0005(פֵּרוּשׁ, רֹק דַּק שֶׁהוֹלֵךְ וּמִתְנוֹעֵעַ)\u0006 בְּעֵת שֶׁהָלְכוּ מִכֹּחוֹ, הֲרֵי זֶה כְּמַזִּיק בְּיָדוֹ, וְהֵם תּוֹלָדוֹת שֶׁל אָדָם. אֲבָל אִם רָק הָרֹק וְהִנִּיחַ עַל הָאָרֶץ, וְאַחַר כָּךְ נִתְקַל מֵהֶם אָדָם, \u0010y0\u0011 הֲרֵי זֶה חַיָּב מִשּׁוּם בּוֹרוֹ, שֶׁכָּל תַּקָּלָה תּוֹלְדוֹת בּוֹר הִיא.\nהָיָה מַכֶּה בְּפַטִּישׁ וְיָצָא גֵּץ \u0005(פֵּרוּשׁ, שְׁבִיב יוֹצֵא מִתַּחַת הַפַּטִּישׁ כְּשֶׁמַּכִּין בּוֹ עַל הַסַדָּן)\u0006 מִתַּחַת הַפַּטִּישׁ וְהִזִּיק, \u0010c0\u0011 הֲרֵי זֶה חַיָּב.\nהַבַּנַאי שֶׁקִּבֵּל עָלָיו אֶת הַכֹּתֶל לְסָתְרוֹ, וְשָׁבַר אֶת הָאֲבָנִים אוֹ הִזִּיק, חַיָּב. הָיָה סוֹתֵר מִצַּד זֶה וְנָפַל מִצַּד אַחֵר, פָּטוּר. וְאִם מֵחֲמַת הַמַּכָּה, \u0010y1\u0011 חַיָּב:\nהַחוֹצֵב \u0005(פֵּרוּשׁ, שֶׁחוֹצֵב אֲבָנִים מֵהָהָר)\u0006 שֶׁחָצַב אֶבֶן \u0010y2\u0011 וּנְתָנוֹ לַסַתָּת \u0005(פֵּרוּשׁ, הַפּוֹסֵל אַבְנֵי גָזִית וּמְרַבְּעָהּ וּמַחֲלִיקָהּ, רַשִׁ\"י)\u0006, וְהִזִּיק בּוֹ, הַסַתָּת חַיָּב. מְסָרָהּ הַסַתָּת לַחַמָּר, הַחַמָּר חַיָּב. מְסָרָהּ הַחַמָּר לַכַּתָּף, הַכַּתָּף חַיָּב. מְסָרָהּ הַכַּתָּף לַבַּנַּאי, הַבַּנַאי חַיָּב. מְסָרָהּ הַבַּנַאי לַמְסַדֵּר הַמְסַדְּרוֹ עַל שׁוּרַת הַבִּנְיָן, הַמְסַדֵּר חַיָּב. וְאִם אַחַר שֶׁסִדְּרוֹ עַל שׁוּרַת הַבִּנְיָן נָפַל וְהִזִּיק, אִם הֵם קַבְּלָנִים וְכֻלָּם שֻׁתָּפִים בַּמְּלָאכָה, כֻּלָּם חַיָּבִים. וְאִם הֵם שְׂכִירֵי יוֹם, הָאַחֲרוֹן חַיָּב וְכֻלָּם פְּטוּרִים:",["\u0003הר\"ז חייב משום בורו. \u0004 נ\"מ לפטור בו כלים שנשברו דשבירה זהו מיתתן ובבור כתיב ונפל שמה שור או חמור ודרשינן שור ולא אדם (פי' אם מת אדם שם פטור אבל אם הוזק בו האדם חייב) וחמור ולא כלים וכמ\"ש לקמן בסי' ת\"י:","\u0003החוצב. שחוצב אבן \u0004 פי' שחצבו מן ההר:","\u0003ה\"ג \"ונתנו לסתת \u0004 פי' לאומן לקצעו ולרבעו שיהי' ראוי לקבעו בכותל וכשגמר קצועו מן הדרך למסרו ליד החמר ולהוליכו למקום הבנין והחמר מוסרו לכתף ונושאו על החומה ואותו כתף כשנשאו על החומה מדרכו למסרו ליד האומן העומד על הבנין והאומן הבנאי מסרו לפועל הבונה ומסדרו בכותל וקאמר דאם נשבר האבן בעודו ביד א' מהן הוא לבדו חייב אע\"ג דכולן קבלנים הן במלאכה זו משא\"כ אם אחר שכבר סדרו והניחו על הבנין אירע סיב' שנפל והזיק דבזה אומרי' אם הם כולם קבלנים שכולן ביחד משלמין ההיזק וכדמסיק:"],["\u0003 הבנאי כו'. \u0004 עיין בתשו' רשד\"ם סי' רצ\"ב:"]],["\u0010c0\u0011 הַמַּזִּיק אֶת חֲבֵרוֹ הֶזֵּק שֶׁאֵינוֹ נִכָּר, כְּגוֹן שֶׁעֵרַב יֵין נֶסֶךְ בְּיֵינוֹ, מִן הַתּוֹרָה הוּא פָטוּר, אֲבָל חֲכָמִים קְנָסוּהוּ לְשַׁלֵּם נֶזֶק שָׁלֵם \u0010y0\u0011 \u0010c1\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו, כְּדִין כָּל הַמַּזִּיקִים. לְפִיכָךְ, אִם מֵת הַמַּזִּיק קֹדֶם שֶׁיְּשַׁלֵם, \u0010y1\u0011 \u0010c2\u0011 אֵין קוֹנְסִין בְּנוֹ אַחֲרָיו לְשַׁלֵּם. וְכֵן אִם הָיָה שׁוֹגֵג אוֹ אָנוּס, פָּטוּר, שֶׁלֹּא קָנְסוּ אֶלָּא מֵזִיד.\nהַמְנַסֵךְ יֵין חֲבֵרוֹ לַעכו\"ם, לֹא נֶאֱסָר, \u0010y2\u0011 שֶׁאֵין אָדָם מִיִּשְׂרָאֵל אוֹסֵר דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. \u0010y3\u0011 \u0010c3\u0011 וְאִם הָיָה לוֹ בּוֹ \u0010y4\u0011 שֻׁתָּפוּת, אוֹ שֶׁהָיָה מוּמָר שֶׁהֲרֵי הוּא כְּגוֹי, אוֹ שֶׁהִתְרוּ בוֹ וְקִבֵּל הַהַתְרָאָה שֶׁהֲרֵי הוּא מוּמָר, הֲרֵי זֶה אוֹסֵר הַיַּיִן, וְחַיָּב לְשַׁלֵּם אַף עַל פִּי שֶׁהוּא מִתְחַיֵּב בְּנַפְשׁוֹ; מִפְּנֵי שֶׁמִּשָּׁעָה שֶׁהִגְבִּיהוֹ נִתְחַיֵּב לְשַׁלֵּם, וְאֵינוֹ מִתְחַיֵּב בְּנַפְשׁוֹ עַד שֶׁיְּנַסֵךְ:",["\u0003מהיפה שבנכסיו. \u0004 כדין כל המזיק דבמזיק כתיב מיטב שדהו ישלם ולקמן בסי' תי\"ט יתבאר דהיינו דוקא כשבא לשלם לו בקרקעות אבל במטלטלין כל דבר מיקרי מיטב אפי' סובין משום דאם לא מכרם במקום זה יכול להוליכם למקום אחר למכרם שם משא\"כ בקרקעות ע\"ש:","\u0003אין קונסין בנו אחריו. \u0004 פי' אפי' עמד אביהן בדין וכ\"כ המחבר לעיל סי' ק\"ח ס\"ב משא\"כ במסור שמת וכמ\"ש בסי' שפ\"ח ס\"ב:","\u0003שאין אדם אוסר דבר כו'. \u0004 פי' אין מדרכו לאסור מ\"ה זה אף ששמעו מפיו שאמר שכוונתו לנסך אמרי' לצעורי' לחבירו קא מכוון ולא גמר בדעתו לנסכו וכן הוא מבואר בי\"ד סי' ד' ע\"ש:","\u0003ואם הי' לו בו שותפות כו'. \u0004 ע' בי\"ד סי' ד' שם מבואר דבשחט בהמת חבירו לעכו\"ם דג\"כ אמרי' לצעוריה כמכוון ובהי' לו שותפות עם חבירו בבהמה כתב שם הטור דלהרמב\"ם אסור וכמ\"ש כאן ביין ושדעת הרא\"ש הוא דאינו נאסר וכאן סתם הטור וכתב דנאסר ונראה לחלק דשאני כאן כיון דראוי ועומד לחלוק והי' לו ליטול ואח\"כ ה\"ל לצער חבירו באמרו שנסכו ולכן לא אמרי' דלצעוריה קמכוון משא\"כ בשחיטות בהמה לעכו\"ם דא\"א לחלקה בחייה ועמ\"ש בדרישה עוד ישוב בענין אחר:","\u0003או שהי' מומר כו' \u0004 דבהני מסתמא הי' דעתו לנסך כיון שהוא מומר או שהתרו בו:"],["\u0003 המזיק כו'. \u0004 ל' הרמב\"ם ר\"פ ז' מהלכות חובל המזיק ממון חברו היזק שאינו ניכר הרי זה חייב כיצד הרי שטמא אוכלין טהורים של חברו או שדמע לו פירות או ערב לו טפת יין נסך בתוך יינו שהרי אסר עליו הכל וכן כל כיוצא בזה שמין מה שהפסיד ומשלם נזק שלם כו' עכ\"ל ומדכתב כללא המזיק ממון חברו כו' וגם מדכתב וכן כל כיוצא בזה מוכח דפסק כרב דפרק הניזקין (ריש גיטין דף נ\"ב) דאי כשמואל הא משמע להדיא בש\"ס דדוקא הני תלתא ותו לא דמקנסא לא גמרינן וכ\"כ ה\"ה שם אמ\"ש הרמב\"ם שם אח\"כ המנסך חייב לשלם כרב דאמר הכי בהניזקין וממ\"ש כאן וכן כל כיוצא בזה כו' מוכח יותר דפסק כרב ודוק. אבל בדיני דגרמי להרמב\"ן ראיתי שכ' דקי\"ל הלכה כשמואל בדיני ומקנס' לא גמרינן ולפי דבריו אינו חייב אלא במטמא ומדמע ומנסך ולא בדברם אחרים. וכן ראיתי במשפטי שבועות לרב האי גאון דף י\"ט ע\"ב שסובר דמקנסא לא גמרינן וכן הוא דעת הרי\"ף ס\"פ החובל גבי מעשה באחד שקדם וכיסה וחייבו ר' גמליאל ליתן י' זהובים וכן דעת הרא\"ש שם. ונרא' טעם לדברי הרמב\"ם דפסק כרב משום דבש\"ס בחולין ס\"פ השוחט (חולין דף מ' ע\"א) מוכח דקיימא לן הכי דפריך התם מהמנסך והיינו ע\"כ כרב וכדאיתא בתוס' שם ומאי פריך דילמא ס\"ל כשמואל אלא ודאי קי\"ל כרב ע\"ש. ועוד נ\"ל טעם לדבריו משום דודאי נראה דהא דחייבו ר' גמליאל להאי ליתן י' זהו' קנסא הוא וכהאיכא מ\"ד שהביא הרי\"ף סוף פרק החובל וכ\"כ בש\"ג פ' החובל דף ל\"ד ע\"א בשם ריא\"ז שנרא' שקנס היא (וע\"ש) דלא מסתבר לי' כהרי\"ף דדינא הוא דא\"כ אמאי לא תני בשום מקום שהחוטף ברכה או מצוה מחבירו שחייב לשלם לו י' זהובים ועוד אי דינא הוא י' זהובים מנא לן אלא משמע דקנסא הוא ומה שהקשה הרי\"ף שם דא\"כ היכא יליף רב התם מניה שור ואילן הא מקנסא לא ילפינן לפע\"ד ל\"ק מידי דרב לטעמי' דס\"ל בפ' הניזקין מקנס' ילפינן וא\"כ האיכא מ\"ד התם ס\"ל דקנס' הוא וס\"ל דלענין הלכה קי\"ל כשמואל בדיני דמקנס' לא ילפי' כך נ\"ל לישב דעת האיכ' מ\"ד שהביא הרי\"ף. ולכאור' תמיה על הרי\"ף בזה ולדעת הרמב\"ם נר' לומר דבהא ס\"ל כהאיכא מ\"ד דר\"ג קנסא הוא דקניס לי' מטעם שכתבתי וא\"כ מוכח דקי\"ל דמקנסא ילפינן דהא בפרק כיסוי הדם (דף פ\"ז ע\"א) גרסי' בש\"ס אהא דחייבו ר\"ג ליתן לו י' זהובים אבעיא להו שכר מצוה או שכר ברכה למאי נפקא מיניה לברכת המזון כו' ומאי קמבעיא לי' הא אפי' הוי שכר ברכה מקנסא לא ילפי' אלא ודאי ס\"ל לסתמא דש\"ס דמקנסא ילפינן. עיין מ\"ש עוד בדעת הרמב\"ם והמחבר לעיל סי' שפ\"ב גבי מי שקדם וכיסה דס\"ל דהך דר\"ג קנסא הוא ומקנסא ילפינן וכמ\"ש שם. וכן מוכח דעת הפוסקים שהבאתי לקמן סי' שפ\"ו ס\"ק א' דסברו דדינא דגרמי קנסא הוא ומקנסא ילפינן וע\"ש:","\u0003 מהיפה שבנכסיו \u0004 כלומר מהעידית כדין מזיק לקמן סי' תי\"ט. ואע\"ג דאינו אלא מדרבנן דרבנן כעין דאורייתא תקון לשלם ממיטב כ\"כ הרא\"ש ריש ב\"ק:","\u0003 אין קונסים בנו אחריו. \u0004 כתב הסמ\"ע פי' אפי' עמד אביהן בדין וכ\"כ המחבר לעיל סי' ק\"ח ס\"ב משא\"כ במסור שמת וכמ\"ש בסי' שפ\"ח ס\"ב עכ\"ל ואין דבריו נכונים בעיני דהרמב\"ם והמחבר לקמן סי' שפ\"ח שפסקו דמסור שמת גובים מיורשיו אפי' לא עמד בדין היינו מטעם שכתבתי שם דסבירא להו דדינא דגרמי דינא הוא ולא קנסא והי\"א שם דס\"ל דדוקא שעמד בדין היינו משום דס\"ל דדינא דגרמי קנסא דרבנן ולא קנסו בנו אחריו ואינו חייב אא\"כ עמד בדין ואם כן הוא הדין הכא בעמד בדין חייב וכן מוכח להדיא במרדכי פרק החובל בשם מהר\"מ שהן הי\"א שהביא הרב לקמן סי' שפ\"ח ס\"ב שכ' וז\"ל ואין לדקדק כיון דתשלומי מסור קנסא הוא נימא דלדידיה קנסו רבנן לבריה לא קנסו כדאמר בפרק מי שהפך וכן שמעתי שפסק ריב\"א במסור ה\"מ מסור שמסר ולא הספיק הנמסר להעמידו בדין עד שמת המסור אבל אם קם המסור בדין ונתחייב נתחייבו הנכסים ותו לא ירתי להו הנכסים ושלום מאיר ב\"ב עכ\"ל וכן הוא בתשובת מהר\"ם ב\"ב ד\"פ סי' תקצ\"ט הרי שכ' דבריה לא קנסו כדאמר בפ' מי שהפך (והתם בפ' מי שהפך) במועד קטן (דף י\"ג ע\"א) במטמא ומדמע ומנסך מיירי ומ\"ש המחבר לעיל סי' ק\"ח ס\"ב אבל אם חייבוהו קנס לא קנסו בנו אחריו היינו כשחייבוהו יתר על מה שהפסיד ואדרב' הא כתב שם המחבר ברישא מי שנתחייב ממון בבית דין בעבור מלשינות ומת גובה מהיורשים אלא ודאי כמ\"ש. כן נ\"ל ועיין מ\"ש שם בסי' ק\"ח ס\"ב:","\u0003 ואם היה לו בו שותפות \u0004 ע' בסמ\"ע ס\"ק ד' ובבית חדש מה שהקשו מי\"ד סי' ד' לכאן ועיין מה שכתבתי בש\"ך בי\"ד סי' ד' ס\"ק ה' על זה:"]],["\u0010y0\u0011 \u0010c0\u0011 קַיְמָא לָן כְּרַבִּי מֵאִיר \u0010c1\u0011 דְּדָאִין \u0010c2\u0011 דִּינָא \u0010c3\u0011 דִגְרָמֵי. \u0005וְדַוְקָא בְּאָדָם חַיָּב דִּינָא דִגְרָמֵי, \u0010c4\u0011 אֲבָל בִּבְהֵמָה, לְכֻלֵּי עָלְמָא פָּטוּר (נִמּוּקֵי יוֹסֵף פֶּרֶק הַפָּרָה)\u0006. \u0010c5\u0011 לְפִיכָךְ, \u0010c6\u0011 הַדּוֹחֵף מַטְבֵּעַ שֶׁל חֲבֵרוֹ עַד שֶׁיָּרַד לַיָּם, \u0010y1\u0011 \u0010c7\u0011 חַיָּב, אַף עַל פִּי שֶׁלֹּא הִגְבִּיהוֹ. וְכֵן הַפּוֹחֵת מַטְבֵּעַ שֶׁל חֲבֵרוֹ וְהֶעֱבִיר צוּרָתוֹ, חַיָּב, אַף עַל פִּי שֶׁלֹּא חִסְרוֹ. וְהַמּוֹכֵר \u0010c8\u0011 שְׁטָר חוֹב לַחֲבֵרוֹ וְחָזַר וּמָחֲלוֹ, \u0010y2\u0011 דְּקַיְמָא לָן שֶׁהוּא מָחוּל, צָרִיךְ לְשַׁלֵּם לַלּוֹקֵחַ, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן ס\"ו. \u0010c9\u0011\nוְכֵן \u0010c10\u0011 הַשּׂוֹרֵף \u0010c11\u0011 שְׁטָר חוֹב שֶׁל \u0010c12\u0011 חֲבֵרוֹ, חַיָּב לְשַׁלֵּם \u0010c13\u0011 כָּל הַחוֹב שֶׁהָיָה בַשְּׁטָר, שֶׁאַף עַל פִּי שֶׁאֵין גּוּף הַשְּׁטָר מָמוֹן, הֲרֵי גָרַם לְאַבֵּד מָמוֹן. \u0010c14\u0011 וּבִלְבַד שֶׁיּוֹדֶה לוֹ הַמַּזִּיק שֶׁשְּׁטָר מְקֻיָּם הָיָה וְכָךְ וְכָךְ הָיָה כָּתוּב בּוֹ, וּמֵחֲמַת שֶׁשְּׂרָפוֹ הוּא אֵינוֹ יָכוֹל לִגְבּוֹת הַחוֹב; אֲבָל אִם לֹא הֶאֱמִינוֹ, אֵינוֹ מְשַׁלֵּם לוֹ אֶלָּא דְּמֵי הַנְּיָר בִּלְבַד. \u0005וּמַיְרֵי שֶׁאֵין עֵדִים שֶׁיּוֹדְעִים כַּמָּה הָיָה כָּתוּב בּוֹ, שֶׁאִם הָיוּ עֵדִים אֵינוֹ חַיָּב לוֹ כְּלוּם, \u0010y3\u0011 \u0010c15\u0011 שֶׁהֵם יַעֲשׂוּ לוֹ שְׁטָר אַחֵר, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן מ\"א (טוּר)\u0006. \u0010y4\u0011\nוְכֵן הַזּוֹרֵק כְּלִי שֶׁלּוֹ מֵרֹאשׁ הַגַּג, וְהָיוּ תַּחְתָּיו כָּרִים וּכְסָתוֹת שֶׁאִם יִפֹּל עֲלֵיהֶם לֹא יִשָּׁבֵר, וְקָדַם אַחֵר וְסִלְּקָם, וְנֶחְבַּט הַכְּלִי בָּאָרֶץ וְנִשְׁבַּר, חַיָּב הַמְסַלֵּק; \u0010c16\u0011 וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: \u0010y5\u0011 \u0010c17\u0011 וְיֵשׁ אוֹמְרִים דְּזֶה מִקְרֵי גְרָמָא בִּנְזָקִין וּפָטוּר. וְכֵן \u0010c18\u0011 בְּדוֹחֵף מַטְבֵּעַ שֶׁל חֲבֵרוֹ אוֹ פִּחֵת צוּרָתָהּ, פָּטוּר, דְּהָוֵי גְרָמָא \u0010y6\u0011 \u0010c19\u0011 בִּנְזָקִין. וְלָכֵן אֲפִלּוּ זָרַק כְּלִי מֵרֹאשׁ הַגַּג וְהָיוּ תַּחְתָּיו כָּרִים וּכְסָתוֹת, וְקָדַם בְּעַצְמוֹ (וְסִלְּקוֹ)\u0006, אֲפִלּוּ הָכִי פָּטוּר, דְּעַל הַזְּרִיקָה לֹא מִחַיֵּב דְּלָא הָיוּ רְאוּיִים לִשָּׁבֵר, וּמַה שֶּׁסִּלְּקָן הָוֵי גְרָמָא בְעָלְמָא \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ וְר\"י פֶּרֶק לֹא יַחְפֹּר)\u0006. סוֹפֵר שֶׁכָּתַב שְׁטָר וְכָתַב מָנֶה בִּמְקוֹם מָאתַיִם, אוֹ הַמַּזִּיק לַחֲבֵרוֹ בַּעֲצָתוֹ שֶׁיָּעַץ לוֹ, \u0010y7\u0011 \u0010c20\u0011 אוֹ \u0010c21\u0011 שָׁלִישׁ שֶׁהֶחֱזִיר שְׁטָר שֶׁלֹּא הָיָה לוֹ לְהַחֲזִיר, \u0010c22\u0011 כֻּלָּם פְּטוּרִים, דְּלָא הָיוּ אֶלָּא גְּרָמָא \u0010y8\u0011 בִּנְזָקִין. מִיהוּ, מְשַׁמְּתִינָן לֵהּ עַד דִּמְסַלֵּק הֶזֵּקָא. וְכֵן בְּכָל גְּרָמָא בְּנִזָּקִין \u0005(תְשׁוּבַת רַשְׁבָּ\"א סִימָן אֶלֶף נ\"ב וּתְשׁוּבַת רַמְבַּ\"ן סִימָן ר\"מ, וְר\"י וְנ\"י פֶּרֶק לֹא \u0010c23\u0011 יַחְפֹּר)\u0006. יֵשׁ אוֹמְרִים דִּבְכָל גְּרָמָא בִּנְזָקִין, אִם הוּא דָבָר שָׁכִיחַ וְרָגִיל, חַיָּב לְשַׁלֵּם מִשּׁוּם קְנָס \u0005(תוס' פֶּרֶק לֹא יַחְפֹּר בְּשֵׁם רִיצְבָ\"א)\u0006. \u0010c24\u0011 וְלָכֵן יֵשׁ מִי שֶׁכָּתַב דִּרְאוּבֵן שֶׁמָּכַר מֵקָּח לְגוֹי, וּבָא שִׁמְעוֹן וְאָמַר לֵהּ לַגּוֹי שֶׁאֵינוֹ שָׁוֶה כָּל כָּךְ, חַיָּב לְשַׁלֵּם לוֹ \u0005(מַהֲרַ\"ם מריזבורג)\u0006. וְאֶפְשָׁר דְּכִי הַאי גַוְנָא הָוֵי כְּמָסוֹר, דְּחַיָב, \u0005(כְּדִלְקַמָּן סִימָן שפ\"ח)\u0006. רְאוּבֵן שֶׁהִלְוָה מָעוֹת לְגוֹי עַל מַשְׁכּוֹנוֹת, וּבָא שִׁמְעוֹן וְאָמַר לַגּוֹי לְהַלְוֹת לוֹ בְּפָחוֹת, \u0010y9\u0011 וְהֶחֱזִיר לִרְאוּבֵן מָעוֹתָיו, פָּטוּר, דְּהָוֵי גְרָמָא בִּנְזָקִין, מִיהוּ, מִקְרֵי רָשָׁע \u0005(רַבֵּנוּ יְרוּחָם נל\"א ח\"ב)\u0006. וע\"ל סִימָן קנ\"ו ס\"ה. דִּין \u0010c25\u0011 \u0005(נ\"י הַמְבַטֵּל)\u0006 הַמַּגְבִּיהַּ כִּיסוֹ שֶׁל חֲבֵרוֹ, ע\"ל סִימָן רצ\"ב.\nהַזּוֹרֵק כֵּלִים מֵרֹאשׁ הַגַּג, וְאֵין תַּחְתֵּיהֶם כָּרִים וּכְסָתוֹת, וּבְעוֹדָם בָּאֲוִיר בָּא אֶחָד וּשְׁבָרָם בְּמַקֵּל, \u0010c26\u0011 הַזּוֹרֵק \u0010c27\u0011 \u0010c28\u0011 \u0010c29\u0011 \u0010c30\u0011 \u0010c31\u0011 \u0010c32\u0011 \u0010c33\u0011 \u0010c34\u0011 \u0010c35\u0011 \u0010c36\u0011 \u0010c37\u0011 \u0010c38\u0011 \u0010c39\u0011 \u0010c40\u0011 \u0010c41\u0011 \u0010c42\u0011 \u0010c43\u0011 \u0010c44\u0011 \u0010c45\u0011 \u0010c46\u0011 \u0010c47\u0011 \u0010c48\u0011 \u0010c49\u0011 \u0010c50\u0011 חַיָּב וְהַמְשַׁבֵּר פָּטוּר, דְּחָשְׁבִינָן לֵהּ כְּשָׁבוּר מִשָּׁעָה שֶׁזְּרָקוֹ:",["\u0003קי\"ל כר\"מ דדאין דינא דגרמי \u0004 לפיכך הדוחף מטבע של חבירו כו' עד וי\"א דזה מקרי גרמא בניזקין ופטור וכן בדוחף מטבע כו' בהיו' שהלכת' דגרמא ודגרמי טובא ורבוותא המה בתלמוד ופוסקים ודברי המחבר ודברי מור\"ם הכתובים עליו קצרים וסתומים המה ואין מספיקין למעיינים לעמוד על דבריהן וכדי לעמוד על תמצית דבריהן ולידע במאי פליגי ומחולקים המה המחבר והי\"א שהביא מור\"ם הוצרכתי להעתיק לפנינו בקיצור מקור הדברים הללו מהגמרא ומ\"ש הרמב\"ם והרא\"ש עליו. והוא דבפרק הגוזל עצים (בבא קמא דף צ\"ח) איתא שם ד' מימראות כולם בשם רבה. הא' דהזורק מטבע של חבירו לים הגדול פטור כו'. השניה דהשף (פי' פוחת צורת) מטבע של חבירו פטור כו'. השלישית דהצורם אוזן פרתו של חבירו פטור כו'. הרביעית השורף שטרות של חבירו פטור כו' ומסיק הגמרא שם ז\"ל אמר רב דימי הא דרבה (דאמר השורף שטרות של חבירו כו') מחלוקת ר\"ש ורבנן הוא ולר\"ש דאמר דבר הגורם לממון כממון הוא מחייב כו' מתקיף ליה רב הונא אימר דשמעית דבר הגורם לממון כממון דמי בדבר שעיקרו ממון כגון הגוזל חמץ לפני פסח ובא אחר ושרפו לאחר הפסח (דאלו הו' קיים היה אומר הגזלן להנגזל הרי שלך לפניך ועכשיו ששרפו זה צריך להחזיר להנגזל דמי החמץ) בדבר שאין עיקרו ממון (כגון זה השורף שטרו דמעולם לאו ממון היה) מי אמרי'. אמר אמימר מאן דדאין דינא דגרמי (ר\"מ בהגוזל בתרא) מגבי ביה דמי שטרא מעליא כו' ומאן דלא דאין דינא דגרמי מגבי ביה דמי ניירא בעלמא הוה עובדא וכפייה רפרם לרב אשי (ששרף שט\"ח בילדותו) ואגביה מיניה דמי השטר עכ\"ל הגמרא בקיצור והרמב\"ם בפ\"ז דחובל דין ז' כ' ז\"ל כל הגורם להזיק ממון חבירו חייב כו' כיצד הזורק כלי מראש הגג ע\"ג כרים ובא אחר וסלקן כו' וכן השורף שט\"ח כו' וכן המוכר שט\"ח וחזר ומחלו כו' וכן הדוחף מטבע לים כו' וכן הצורם אוזן הפרה כו' וכן המעביר צורת המטבע כו' וכתב ע\"ז המ\"מ ז\"ל דהני תלתא דוחף מטבע וצורם אוזן פרה וכן המעביר צורת המטבע כו' שלשתן פטור בהגוזל עצים משים דלית ליה דינא דגרמי אבל המפרשים כתבו דלדידן בכולהו חייב וכן דעת ר\"ח והלכות ויתר הפוסקים ז\"ל עכ\"ל המ\"מ. נשמע מכל זה דהרמב\"ם ושאר הפוסקים דכתב המ\"מ משמע דמחייבי בכל הני טעמייהו משום דמחשבי לכל הני לדינא דגרמי דמחייב בהו ר\"מ. ונרא' דס\"ל דאמימר דאמר אהשורף שטרות דמאן דדאין דינא דגרמי מגבי ביה דמי שטרא מעליא וכנ\"ל לרבותא אמריה השורף שטרו דאע\"פ דהשטר לאו ממונא הוא מתחיל' ועד סופו אפ\"ה מחייב ביה לר\"מ דדאין דינא דגרמי ק\"ו לאינך הנ\"ל ושאר גרמא דהמה ממון דמחייב בהו למאן דפסקי כר\"מ (משא\"כ לשטת ר\"י והרא\"ש שאכתוב בסמוך דאליבייהו אמימר דוק' אמר אמימרא דהשורף שטר ולא אאינך וכמבוא' בטור ובאשר\"י שאכתוב בסמוך) ולדידהו אין חילוק כלל בין דינא דגרמי לגרמא בניזקין. ואף שנזכר בגמ' בכמה מקומות דפטרי בגרמא ס\"ל דהנהו סוגיות אזלי אליבא דרבנן דפליגי עם ר\"מ ופטרי בדיני דגרמי כדאי' בפ' הגוזל בתרא אבל לר\"מ והפוסקים כוותיה בכלהו מחייבין ומ\"ה התחיל הרמב\"ם הנ\"ל וכתב ז\"ל כל הגורם להזיק ממון חבירו חייב ש\"מ דכייל להו ומחייב בכולהו וכ\"כ הנ\"י שם אהני מימראות דרבה הנ\"ל ז\"ל וטעמא דרבה בכל הני חדא הוא דאפי' דינא דגרמי לית ליה וכל הני דינא דגרמי נינהו ולית הלכתא כוותיה אלא כדכפיי' רפרם כדמוכח במסקנא עכ\"ל נ\"י ומה\"ט נמי התחיל המחבר וכתב ז\"ל קי\"ל כר\"מ דדאין דינא דגרמי לפיכך הדוחף מטבע כו' וכן הפוחת כו' ש\"מ דסבר ליה דכל הני שמחייב הרמב\"ם משום דקי\"ל כר\"מ ומינ' נלמד דס\"ל דהרמב\"ם מחייב נמי בשאר כל הגרמות אלא דנקט המחבר הני משום דאותן מימראות דרבה תכופים זה אל זה בהגוזל כנ\"ל וגם ההוא דזורק כלים מהגג כו' מימרא דרב' הוא בס\"פ כיצד הרגל ע\"ש ודלא כע\"ש שבריש דבריו שהן אליבא דהרמב\"ם כתב דהרמב\"ם מחייב בהני משום דדיני דגרמי נינהו ובגרמא בנזקין כ\"ע מודו דפטור וז\"א. ומור\"ם דכתב עליו די\"א זה מיקרי גרמא בנזקין ופטור כ\"כ אליבא שיטת ר\"י והרא\"ש והטור וז\"ל הטור (דכתב אדברי הרמב\"ם הנ\"ל) ור\"י פי' כיון דק\"ל דגרמ' בניזקין פטור. וגם קי\"ל כמ\"ד דדן דינא דגרמי צריכים לחלק ביניהן כו' (וכתב כמה פרטיים מהגרמות שהן לחיוב וכמה לפטור ע\"ש והמחבר ומור\"ם קצרו בהו ולבסוף כתב) וכ\"כ א\"א הרא\"ש ז\"ל עכ\"ל ודברי הרא\"ש בזה המה בפ' לא יחפור (בדף קצ\"א סע\"ג בדפוס גדול) וגם בפרק הגוזל קמא שכ\"כ אהני מימראות דרבה הנ\"ל וכתב שם ז\"ל ועתה יש ג' חילוקים במאבד ממון חבירו בגרמא. האחד בדבר הגורם לממון שנחלקו בו רבנן ור\"ש והלכה כרבנן דלאו כממון דמי. והשני הוא גרמא בניזקין ופטור לכ\"ע דפרק לא יחפור גבי מרחיקין הסולם מהשובך פריך והא גרמא בניזקין הוא כו'. והשלישי הוא גרמי בניזקין דפליגי בהו ר\"מ ורבנן כו' ומסיק וכתב הטעם דמחייבי בדיני דגרמי ופטרי בדיני דגרמא בניזקין וז\"ל היכא דהוא בעצמו עושה היזק לממון חבירו וברי היזקא הוא הנקרא דינא דגרמי כגון שורף שטר או מוחל הוא בעצמו מזיק ממון חבירו וכן מרא' דינר לשולחני דבמה שאומר לו שהוא טוב מזיקו וכן דאחוי אחווי שהראה לעכו\"ם ממון חבירו וברי הזיקא כאלו הוא נתנו לתוא מכמר ואין לך מעש' גדול מזה וכן (בכלאי') נתייאש ולא גדרה כיון דמעורב שלו בשל חבירו ונתייאש הוה כעוש' מעשה בשל חבירו וכן דן את הדין ומחייב ליתן את הזכאי ופוטר החייב ומצווה ליתן הנביל' והטריפה לכלבים הוה כעוש' מעשה אבל ההיא דשסה בו את הכלב והנחש לא ברי היזקא כגון מסור דשמא לא ישיך בו הכלב והנחש והמסלק כרים וכסתות אף ע\"ג דברי היזקא לא עשה מעש' בגוף הממון ולא דמי לאחויי אחוויי דמסור דכמאן דקלי' דמיא ועש' מעשה בגוף הממון והשולח את בעיר' ביד חש\"ו הוא אינו עוש' את המעש' אלא החרש ופורץ גדר בפני בהמת חבירו ממילא נפקא וכ\"ש טומן קמת חבירו דלא עביד מידי ומבעית חבירו איהו דאפסיד לנפשיה ולא עביד ביה מעש' ועוד יש לחלק היכא דבשעת מעש' נעשה ההיזק שנקרא דינא דגרמי כגון שורף שטר או מוחל וכן מרא' דינר לשולחני ואמר שהוא טוב מיד סומך עליו ונעש' לו ההיזק ופטר אותו שנתנו לו ומסור בעידנא דאחוי ליה כמאן דקליא דמי וכן נתייאש בשעת היאוש נעש' מיד כלאים אלא אינו אסור עד שיוסיף מאתים וכן דן את הדין מיד בא לו ההיזק אבל כל הני לא בא ההיזק מיד והמסלק הכרים לא נשבר הכלי עד שיגיע לארץ וכן שיסה עד אחר השיסוי לא ישיך וכן השולח את הבעיר' בשעה שנותן האש להחרש אינו מזיק וכן פורץ גדר ומבעית חבירו אחר שהבעיתו הוא מתפחד והולך כו' ע\"ש שהאריך גם המרדכי דפ' הגוזל עצים דפוס גדול סי' קי\"ט כ' בשם ר\"י דדיני דגרמי דחייבי בהו הוא משום דבעצמו עשה ההיזק בממון חבירו כו' עד ולי לא נתיישב לי ולא יכולתי לעמוד על החלוקים וגם ר\"י גמגם ברובם לכן קצרתי תוספות אכן הריב\"ש כ' מה שמחלק רבינו יצחק בין דינא דגרמי לגרמא בנזיקין נרא' שכולם שוים אלא דמילתא דשכיח קנסו ביה רבנן וחיובן אינו אלא מדרבנן ומטעם קנס ובמלתא דלא שכיח לא והכי איתא בירושלמי דבשבועות המקרע שטר של חבירו שלא מדעתו ר' חנינא ור' אבא חד אמר חייב וחד אמר פטור מאן דאמר חייב משום קנס כו' עכ\"ל ולדברי המרדכי הללו נתכוין מור\"ם מ\"ש בסמוך ז\"ל י\"א דבכל גרמא בניזקין אם הוא דבר שכיח ורגיל חייב לשלם משום קנסא כו' ומ\"ה נרא' דקיצר מור\"ם ולא כתב כל הני פרטי דכ' הרא\"ש והטור לפטור ולחיוב משום דס\"ל כהי\"מ והוא המרדכי דכלם פטורים א\"ל בהני דשכיחי דקנסו בהן ואפי' בגרמא בניזקין וממ\"ש נתבאר לך סתירות דברי הע\"ש שבא ליתן טעם למה קראו חז\"ל לאלו גורמת שחייב בהו דינא דגרמי ולאלו שפטרו בהו קראוהו גרמא בניזקין וכתב שהוא ע\"פ הדקדוק קל וכבד כמו שובר ומשבר ושהכבד מור' שהגרמא בא מהמזיק עצמו מה שאין כן הקל והאריך בדבריו ובנקודות גרמא וגרמי וז\"א לדעת י\"א דהוא המרדכי שכתב שכולם שוים הם לדינא אלא שבגרמות השכיחות קנסו וכנ\"ל. ולפי דבריו צ\"ל דדוקא לדעת ר\"י והרא\"ש שהתחיל בהן מור\"ם ס\"ל כן. ולע\"ד היה נרא' לומר דבהני גרמות דפטרי בהו רבנן מלשל' קראוהו גרמא בניזקין וכאלו אמר הגרמות באו מכח הניזקין וכאלו באו מעצמן ולא מכח האדם המזיק ובהני דמחייבי בהו רבנן מלשלם קראוהו דיני דגרמי ור\"ל הגרמות לא באו מעצמן אלם מאדם המזיק שגרם להו: וזה א\"ש גם לדברי המרדכי הנ\"ל שאף שס\"ל ששוין הן מ\"מ בדבר השכיח וקנסו עליו רבנן קראו הגרמות ע\"ש המזיק ובדבר שאינו שכיח לא קראו הגרמות ע\"ש המזיק ואפשר לומר שגם כוונת ע\"ש הי' ג\"כ לזה ומ\"ה הוצרך לשנות המלות והנקודות בשביל זה ודוק ובמ\"ש נתבאר לך כלל דברי המחבר ומור\"ם ומעתה אכתוב לך ביאור פרטי דבריהן:","\u0003אע\"פ שלא הגביהו. \u0004 ר\"ל דאלו הגביהו פשיטא דחייב דהרי כשהגביהו בא לרשותו וצריך להשבה מעלי' ועוד ה\"ל להמחבר לכתוב מה שאיתא בגמרא דמיירי באפי' המים צלולים ורואה המטבע לפניו אלא שצריך לשכור אדם היודע לשוט תחת המים ולהביאו:","\u0003דק\"ל שהוא מחול. \u0004 בטור והמחבר תמצאנו לעיל בסי' ס\"ו ע\"ש:","\u0003שהם יעשו לו שטר אחר \u0004 כל' זה כתב ג\"כ הטור בשם הרמב\"ם ועפ\"ר שם כתבתי דהאי ל' שהם ל\"ד קאמר דהרי העדים כבר עשו שליחותן ואין יכולין לכתוב לו תו שטר אחר אלא ר\"ל שהעדים יאמרו הדבר לפני הב\"ד והב\"ד יכתבו לו שטר אחר וכן יתבאר בסי' מ\"א ע\"ש:","\u0003וכן הזורק כלי שלו מראש הגג כו'. \u0004 פירוש בכלי שלו המסלק חייב כולו אבל אם זרק כלי של חבירו מראש הגג ס\"ל להרמב\"ם דהזורק והמסלק משלמין דמי הכלי יחד כל א' חצי הנזק והמחבר קיצר בדברי הרמב\"ם ועד\"ר שם כתבתי דבריו וטעמו וביאורו בארוכה:","\u0003וי\"א דזה מיקרי היזק גרמא כו'. \u0004 כבר כתבתי טעם די\"א לעיל בר\"ס זה בסמ\"ע:","\u0003ולכן אפילו זרק כלים כו'. \u0004 פי' לכן מסיק הטור וכתב דאפילו זרק כלים של חבירו מראש הגג וקדם הזורק בעצמו וסילק הכרים פטור על הזריקה ועל הסילוק:","\u0003או שליש שהחזיר שטר. \u0004 עמ\"ש מור\"ם בהג\"ה לעיל בס\"ס נ\"ד בשליש שהחזיר שטר שלא כדין ולא נודע לב\"ד עד שהוציאו מן הלוה כל השטר השליש פטור דהוה גרמא בניזקין עכ\"ל והוא מתשובת הרשב\"א הביאו הב\"י וד\"מ שם. ולפ\"ז צ\"ל דמה שמסיק כאן וכתב ז\"ל מיהו משמתינן ליה כו' היינו קודם שנעשה ההיזק או הגבה מהלוה. מיהו מה דמסיק מור\"ם וכ' עליו דבדבר השכיח ורגיל קנסינן ליה וחייב לשלם זהו מיירי אפילו בשכבר גבו ונעשה הנזק ודוק:","\u0003מיהו משמתינן ליה כו'. \u0004 ע\"ש בתשובת הרשב\"א סי' אלף נ\"ב דשם מבואר דהיינו דוקא לענין היזק שיארע לו אחר השמתא אבל ההיזק שמגיע לו קודם השמתא אינו חייב לשלם לו ומ\"ה כתב תחלה כולם פטורים והיינו כדעת הראב\"ד והביא' הב\"י ודעת הר\"ן שכ\"כ על המוכר שדהו לעכו\"ם בצד שדה ישראל דמשמתינן ליה עד דמסלק היזק חבירו והביאם הב\"י לעיל סי' קע\"ה ס\"ג ע\"ש ולא כהרא\"ש שהצריך לשלם הכל ועוד נראה מדבריהן שם שאפי' מת קודם שקיבל עליו לסלק היזקו שפטור:","\u0003והחזיר לראובן מעותיו שם בדברי ר' ירוחם משמע דאפילו א\"ל שמעון להעכו\"ם להחזיר לראובן מעותיו דאפ\"ה פטור מדינא מעשה אירע שבא עכו\"ם ועשה מקח עם ישראל ליקח ממנו כך וכך מדות יין שרוף כל מדה בכך וכך ונגמר המקח ביניהן כדין התגרים שמכים כף אל כף אח\"כ הלך העכו\"ם אל ישראל אחר הדר בשכונתו של ישראל הראשון ורוצה לעשות עמו ג\"כ מקח ולא גילה שכבר דיבר עם ישראל הראשון והיה כונתו שאם יוזיל לו ישראל השני המקח שיקח ממנו ויניח הראשון וישראל הראשון הרגיש בדבר שלכך הלך בבית ישראל השני ושלח אל ישראל זה ובקש ממנו שלא ימכור לו יין שרוף כי כבר עשה עמו מקח ולא השגיח ישראל השני על זה ועשה מקח עם העכו\"ם ולקח העכו\"ם מידו היין שרוף ומכח זה לא קנה העכו\"ם מישראל הראשון נראה פשוט דאם אין ערמה בדבר לפי ראות הדיינים דאין עונשין לישראל השני ע\"ז מאחר שהעכו\"ם מעצמו בא אליו ליקח ממנו יין שרוף דאף למ\"ד דאסו' ליקח מערופיא של חבירו היינו דוקא בעכו\"ם הרגיל להיות עסק עמו וישראל השני מהדר אחר העכו\"ם שישראל הראשון עסק עמו והשתדלהו לעסוק עמו. ואף ששלח אליו יהודי הראשון וביקש ממנו שלא יעשה עמו מקח לאו כל כמיניה לעשות לנפשו היזק עבורו וגם שם מסקינן דאם עבר ועשה דאין מוציאין מידו וכ\"ש וק\"ו בזה דאין כאן כל הצדדים הללו ויש עוד טענה לישראל השני לאמר מאחר שכבר עשה מקח עמך ובא ג\"כ אלי מי יאמר שלא יקח גם ממך כשיעור המקח שעשה עמך. וגדולה מזה כתב ר' ירוחם במשרים נל\"א ח\"ב (והביאו מור\"ם) תשובות מוהר\"ם ז\"ל ראובן שהלוה מעות לעכו\"ם בריבית \"ובא שמעון וא\"ל הילך בפחות ופרע לראובן אינו חייב לשלם לו כלום דלא ברי היזקא אלא ספק גרמא דשמא לא יוכל להלוות מעותיו בריבית כן כתב מהר\"ם ודמי למבטל כיסו של חבירו ומיהו יש לקרותו רשע טפי מעני המהפך בחררה עכ\"ל הרי דלא קראו רשע אלא דוקא התם דישראל השני הדר אחר העכו\"ם אחר שלוה מהראשון וא\"ל קח מעות ממני ופרע להראשון משא\"כ בנדון זה דעכו\"ם מעצמו בא אצל השני והשני לא אמר לו דלא יקח מהראשון ופשוט הוא בעיני. וכתבתיהו לאפוקי מהמורה דפסק והוציא כל הריוח משני ונתנוהו להראשון:\u0004"],["\u0003 קיימא לן כר' מאיר דדאין דינא דגרמי כו'. \u0004 הנה ראיתי הרמב\"ן האריך מאד בדיני דגרמי בסוף חדושי בבא בתרא שלו והתחלתי לעשות חיבור וביאור ופלפול על דבריו אך באשר כי ראיתי עיקר יסודו שסובר דדינא דגרמי דאורייתא הוא ומחמת זה הי' מוכרח לחלק בחילוקים איזו נקרא דינא דגרמי ואיזו נקרא גרמא כדי שלא יסתרו זא\"ז ועל כן הוכרח להאריך בזה אמנם לפי מה שנ\"ל עיקר דדינא דגרמי אינו אלא קנסא דרבנן אין צורך לחלק בשום חלוקים רק כמ\"ש שאר פוסקים שחכמים קנסו בדבר שהי' נראה להם שהוא שכיח ורגיל וכי האי גוונא ואין לדמות גזרות חכמים זו לזו על כן חזרתי לאחורי מלעשות החבור הנ\"ל ועם כל זה אמרתי להביא דברי הרמב\"ן בדינין השייכים לסי' זה:","\u0003והנה מתחלה אבאר שדינא דגרמי אינו אלא מדרבנן.\u0004 הנה באמת הטור והמחבר כתבו לעיל סי' ס\"ו סעיף ל\"ב כשמוחל שטרות ישלמו יורשיו והיינו משום דדינא דגרמי חייב מדינא ולא משום קנסא וכ\"כ הטור שם להדיא והוא מדברי בעל התרומות שער נ\"א חלק ו' וכתב שכן דעת הראב\"י והראב\"ד ע\"ש ומביאם ב\"י שם ולא הביאו בב\"י ובד\"מ שם שום חולק וע\"כ פסקו שם בפשיטות כהטור דישלמו יורשיו ובאמת התוס' פ' לא יחפור סוף (בבא בתרא דף כ\"ב) מסקי בשם הריצב\"א דדיני דגרמי הוי משום קנסא כדמוכח בירושלמי כו' (והוא הי\"א שהביא הרב לקמן ס\"ס זה בהג\"ה ס\"ק כ\"ד ובד\"מ שם ע\"ש) וכן הוא במרדכי פ' הגוזל קמא וכן דעת הסמ\"ג דף קמ\"ח ע\"א (וצל\"ע ששם בעמוד ב' כ' הסמ\"ג גבי מסור כהרמב\"ם דישלמו יורשיו ואין לו' דסבירא ל ה דמסור גרע טפי ודינא הוא דהא אמרי' בש\"ס ס\"פ הכונס אליבא דמאן דלא דאין דינא דגרמי לא תיבעי לך דמסורות נמי לא דיינינן ועמ\"ש לקמן ודוק) והאגוד' פ' לא יחפור ותשו' מיי' לספר נזיקין סי' ד' וכן הוא תשו' ה\"ר יקר בן ה\"ר שמואל הלוי ז\"ל בתשו' הרא\"ש ריש כלל ק\"א דמסו' קנסא הוא וכדמשמע בירושלמי דכלאי' ולא קנסו בנו אחריו ע\"ש וכן כ' בשלטי גבורים פ' הפרה סוף דף כ\"ג ופ' הכונס דף כ\"ו ע\"ב ופ' הגוזל קמא סוף דף ל\"ה בשם ריא\"ז וכן כתבו התוס' פ' הפרה דף כ\"ד ע\"א בשם ר\"י ובפרק מרובה סוף (בבא קמא דף ס\"ב) וכן בסוף דף ע\"א בשם ריצב\"א וכן בפרק אלו נערות (כתובות דף ל\"ד) סוף ע\"א דדיני דגרמי אינו אלא מדרבנן וכן הוא בפסקי תוס' פרק אלו נערו' דדיני דגרמי אפי' לר\"מ אינו אלא מדרבנן יע\"ש וכן כ' עוד במרדכי פ' הגוזל בתרא תשובות ה\"ר אביגדור באריכות ע\"ש שכ' בפשיטות דדינא דגרמי אף לר\"מ אינו אלא קנס מדרבנן ע\"ש וכן מוכח בנימוקי יוסף ריש ב\"ק שכ' וז\"ל ומסור ומפגל נמי מאבות נזיקין נינהו לשלם ממיטב ודוקא במזיד אבל בשוגג פטורין כדאי' בפ' הניזקין עכ\"ל. וגם בתרומת הדשן סי' ש\"ז ושט\"ז מספקא ליה בהא ע\"ש וגם בתשובות מהרי\"ן לב ספר א' סוף סי' קכ\"ג דף קנ\"ח ע\"ג מצאתי שכ' דאע\"ג דהרמב\"ן כ' דדיני דגרמי אמרו ולא קנסא מ\"מ יכול המוחזק לומר קים לי כהני דסבירא להו דדינא דגרמי הוי קנסא וע\"ש משמע מדבריו דהסוברים קנסא הם מיעוטא ונראה מדבריו שם שלא ראה כל הנך פוסקים שהבאתי דרבים נינהו ודבריהם נראה לי עיקר וכמו שאבאר (ע' בתשו' משאת בנימין סי' כ\"ח) וכן הוא דעת הי\"א שהביא הרב בהג\"ה לקמן סי' שפ\"ח סעיף ב' דדוקא שעמד בדין כו' והוא דעת מוהר\"מ שכ' ששמע שכן פסק ריצב\"א הנ\"ל וכדאי' במרדכי פ' החובל ובתשובת מהר\"מ מרוטנבור\"ק דפוס פראג סי' תקצ\"ט ע\"ש עוד אי' בתשו' מהר\"מ ד\"פ סי' ת\"ס שפסק מוהר\"ר הר\"ב דכל דיני דגרמי משום קנס ולא קנסו לבנו ע\"ש וגם מהרי\"ל בתשובה סי' צ' גבי מסירת רבי דוד ורבי ישי כ' בפשיטות אבל מסור מדינא דגרמי הוא ומשום קנסא כדמסיק ריצב\"א ע\"פ הירושלמי כו' וכן מהרי\"ו בתשובות סי' כ\"ח כתב בפשיטות וכיון דהא דמחייבינן מסור לשלם לא הוי אלא מטעם קנסא ולא מדינא כמ\"ש מהר\"מ בתשובה כו' וא\"כ קשה על הרב דלקמן סי' שפ\"ח ס\"ב הביא דעת הי\"א דוקא שעמד בדין ולעיל בסי' ס\"ו סעיף ל\"ב סתם כהטו' והמחב' וכן ק' על הע\"ש:","והנה הרמב\"ן בדיני דגרמי שלו כ' דדינא דגרמי חיוב מדינא ולא משום קנסא ובמוחל ושורף שטר וכן בכל דיני דגרמי ומת חייב בנו לשלם וכן אפי' בשוגג חייב וכתב דהירושלמי אפשר דלא דאין דינא דגרמי ע\"ש באריכות ואחריו נמשך מהרש\"ל פ' הגוזל קמא סי' כ\"ו. ונ\"ל לדחות כל ראיות הרמב\"ן ומהרש\"ל שם ממחיצת הכרם שנפרצ' שאין כוונתו להזיק כו' לפע\"ד אינה ראיה דכבר כ' הרמב\"ן שם דקשיא ממרא' דינר ואיכא מאן דדחי דהואיל וצריך למגמ' וקא חזי פושע ומזיק הוא כו' וא\"כ ה\"ה הכא כיון שלא גדרה פושע ומזיק הוא ונ\"ל כמ\"ש הרמב\"ן שם בדיני דגרמי שלו בדף קי\"ב ע\"א דהך מילתא מיתאמרא בש\"ס פ' הגוזל בתרא (בבא קמא דף קי\"ז) גבי א\"ל רב הונא בר חייא דינא או קנסא א\"ל מתני' היא אם מחמת הגזלן חייב להעמיד לו שדה אחר. ונרא' דלדעת הפוסקים דסברי דדינא דגרמי דינא הוא י\"ל דהא דא\"ל מתני' היא כו' פשיט ליה דדינא הוא וכן נראה מדברי הרמב\"ם ר\"פ ח' מה' חובל גבי מסור וכ\"כ הרב המגיד שם שבש\"ס פ' הגוזל בתרא משמע דדינא הוא מסור ולא קנסא וכ\"כ רבינו האי (וכן ראיתי בדברי רב האי בשערי שבועות דף י\"ט ע\"ב) והרמב\"ן והרשב\"א עכ\"ל וכ\"כ ר\"א בר נתן בפ' הגוזל דאיפשטא דדינא הוא ע\"ש ברמב\"ן ד' צ' ע\"א והפוסקים דסברי דקנסא הוא ס\"ל כמ\"ש הרמב\"ן בדיני דגרמי שלו דף ק\"ב ע\"א וז\"ל ואפש' דממתני' לא פשיט ליה כלום דאמר עובדין מתני' היא עכ\"ל וכן נראה דהיכא פשיט ליה ממתני' דלמא מתניתין גופא קנסא הוא ועוד דבירושלמי פרק הגוזל בתרא קאמר להדיא אהא מתני' א\"ר יוחנן והלא אמרו אין הקרקע נגזלת ולמה אמרו חייב להעמיד לו שדה קנס קנסוהו ע\"כ וכן משמע נמי מדאמרינן התם לבתר דנפיק א\"ל מאי נפקא לך מינה אי דינא או קנסא ואם איתא דפשיט ליה הל\"ל מאי נפקא לך מינה אי דינא ותו לא ודו\"ק ומ\"ש הרמב\"ן שם בדיני דגרמי שלו דאנן קי\"ל דמקנסא לא ילפינן הלכך ע\"כ דינא הוא כו' אינו מוכרח לפע\"ד ובפרט הראיה העיקרית שלו שכתב שם דקי\"ל כשמואל בדיני ושמואל ס\"ל בפ' הניזקין דמקנסא לא ילפינן גבי מנסך היינו מערב כו' ע\"ש ולפע\"ד לא מוכח מהתם מידי דהא משמע מדברי הרמב\"ם רפ\"ז מה' חובל דפסק כרב וכמ\"ש ה\"ה שם להדיא בפשיטות כרב וכבר כתבתי לעיל סי' שפ\"ה טעמים נכונים לזה ע\"ש. גם מ\"ש הרמב\"ן שם וסוגיין נמי בפרק הניזקין כוותיה דשמואל דמקשינן התם העושה מלאכה במי חטאת פטור ואי ס\"ד היזק שאינו ניכר שמיה היזק אמאי פטור ואי אמרת בשלמא לא שמיה היזק ניחא דאפי' במזיד פטור דמקנסא לא גמרינן וכ\"כ ר\"ח ז\"ל עכ\"ל לפע\"ד אין זו הוכחה מכמה טעמים חדא דהמקשה לא רצה להקשות כן משום דאיכא לדחויי הכי אבל אפשר דלקושטא ס\"ל דמקנסא גמרינן. ועוד דהא ר\"א הוא דפריך התם הכי ודלמא ר\"א כשמואל ס\"ל ואנן קי\"ל כרב מכח דמסתמא דש\"ס משמע דס\"ל כוותיה וכמ\"ש לעיל סי' שפ\"ה ועוד דה\"מ למימר ולטעמיך וכ\"כ ה\"ה להדיא ברפ\"ז מהלכות חובל בלאו הכי לדעת הרמב\"ם שם דס\"ל דהמ\"ל ולטעמיך אמאי לא קנסו ביה רבנן כי היכא דקנסו מטמא וחביריו אלא דלא אמר והרבה כמוהו בש\"ס עכ\"ל ועוד נראה דאפי' לדעת הראב\"ד בהשגות שם דס\"ל דדוקא למ\"ד שמיה היזק פריך ולא המ\"ל ולטעמיך ע\"כ לאו משום דמקנסא לא ילפינן כלל דא\"כ ל\"ל להראב\"ד התם למימר וז\"ל למ\"ד היזק שאינו ניכר לא שמיה היזק פטור אפי' במזיד וטעמא דמלתא משום דאין מתכוין להזיק אלא להנאתו הוא מתכוין ומש\"ה לא קנסו בו מזיד עכ\"ל ל\"ל האי טעמא הא אפי' הוי מתכוין להזיק פטור דומיא דמטמא ומדמע ומנסך דמתכוין דהא ממטמא וחביריו לא גמרינן דקנסא הוא אלא ודאי ס\"ל להראב\"ד דהך סוגיא אתיא אפילו כמ\"ד דמקנסא גמרינן אלא דהיכא דאין מתכוין להזיק לא גמרינן מקנסא (ואולי אי הוה ראה מהרש\"ל כל הנך פוסקים הנ\"ל שהבאתי לא הוה פסק כן) גם מ\"ש הרמב\"ן דהירושלמי לא דאין דינא דגרמי הוא דוחק דהא בירושלמי פ\"ז דכלאים קאמר ריש לקיש גופיה קנסא דר\"מ ומייתי לי' הרמב\"ן התם וריש לקיש בש\"ס דילן קאמר דקיימא לן כר\"מ דדאין דינא דגרמי:)","ועוד נ\"ל ראיה דדינא דגרמי אינו אלא מדרבנן מדגרסינן בס\"פ הכונס עשו תקנת נגזל באשו בעי אמימר עשו תקנת נגזל במסור או לא אליבא דמ\"ד דלא דיינינן דינא דגרמי לא תיבעי לך דמסורות נמי לא דיינינן כי תבעו לך אליבא דמ\"ד דיינינן דינא דגרמי כו' ואם איתא דגרמי דאורייתא מאי מבעי' ליה טפי מאשו ונ\"ל שלזה כיוונו התוס' פרק לא יחפור סוף (בבא בתרא דף כ\"ב) שכתבו במסקנת' וריצב\"א אומר דדינא דגרמי מדרבנן כדמוכח בפ' הכונס ור\"ל כמ\"ש וכ\"כ התוס' פרק הפרה דף נ\"ד ע\"א בהדיא בשם ר\"י דדיני דגרמי דרבנן כדמוכח בפרק הכונס דמדבעי ליה אי עשו תקנת נגזל במסור או לא ואי דינא דגרמי דאורייתא למה לא עשו תקנת נגזל במסור כמו בנגזל עכ\"ל וראיתי במהרש\"ל פרק הגוזל קמא סי' פ\"ו שכתב לדחות את זה דאפי' את\"ל דאורייתא מבעי' ליה דדילמא לא עבדי רבנן תקנתא רק במזיק גוף הממון ולא בדינא דגרמי עכ\"ל. ופשיטא דגם התוס' הרגישו בזה אבל אין נראה כן דאי אורייתא מה לי גוף הדבר מה לי גרמי:","ומ\"ש הרמב\"ן ובעה\"ת דדינא דגרמי מיקרי ולא קנסא דגרמי אין זה דקדוק ואדרבה מדאמרינן בכל דוכתי ר\"מ דאין דינא דגרמי או מאן דדאין דינא דגרמי ולא אמרי' ר\"מ סבר גורם להיזק חייב או כהאי לישנא דכותיה אלמא דלא מיחייב ממש אלא דדאין דינא דגרמי לחייבו מדרבנן גם מה שכתב הרמב\"ן שם דאי ס\"ד קנס' הוא מסר ומת או שרף שטרות ומת לא נקנוס בנו אחריו כדאמרינן במטמא ומדמע ומנסך כו' לא ירדתי לסוף דעתו אה\"נ אי קנסא הוא לא קנסו בנו אחריו וכמו שהבאתי לעיל בשם הרבה פוסקים:","ועוד נ\"ל ראיה ממאי דפטרינן למוסר כשהוא אנוס ואי דיני דגרמי דאורייתא הא בכל מילי דאורייתא מיחייב באונס כרצון ואף שנראה שהרמב\"ן הרגיש קצת בזה וכתב דאקילו רבנן בדבורא ולא עשו כרצון והבאתי דבריו לקמן ס\"ק ו' מ\"מ דוחק הוא דלמה עקרו רבנן דין תורה אלא ודאי דינא דגרמי אינו אלא מדרבנן ולכך במסור שהראה דאינו אלא גרמי מדרבנן פטור באונס וכשנשא ונתן ביד דעשה מעשה וחייב מדאורייתא חייב אף באונס. כן נ\"ל עיקר הדברים שוב מצאתי בהגהת מיימון רפ\"ח מהלכות חובל כתב שם אהא דמסור שאנסוהו להראות והראה פטור וז\"ל משום דדינא דגרמי לא הוי אלא מדרבנן הלכך כי אניס לא מחייב ר\"י מפסקי ה\"ר חזקיה ע\"כ וכ\"כ עוד בתשובת מיימון שם לספר נזיקין סי' כ' וכן הוא במרדכי ס\"פ הגוזל בתרא וז\"ל ונראה דישראל שאנסוהו והראה ממון חברו דפטור זהו משום דדינא דגרמי לא הוי אלא מדרבנן לכך כי אניס לא מיחייב כלל אלא כשנשא ונתן ביד ע\"כ (וע' במהרש\"ל פרק הגוזל בתרא סי' מ\"ז וסי' נ\"ב ואין דבריו מוכרחים ע\"ש ודוק) ואין להקשות א\"כ אמאי לא פשיט ליה רב נחמן לרב הונא בר חייא דקנסא הוא מדתניא ישראל שאנסוהו עכו\"ם להראות ממון חברו פטור י\"ל דאפשר ברייתא לא הוה שמיע ליה או אפשר משום דאיכא למידחי דאתיא כמ\"ד דלא דאין דינא דגרמי וה\"ה דאם הראה מעצמו בלא אונס פטור אלא דקתני אנסוה משום סיפא דבנשא ונתן ביד חייב אפי' אנסוהו תדע דקאמר בש\"ס אהך ברייתא) אמר רבא אם הראה מעצמו כנשא ונתן ביד דמי ומאי קמ\"ל רבא הא היינו ברייתא אלא ודאי כדאמרן:","ועוד נ\"ל ראיה נכונה מדאמרינן בפ' הגוזל קמא (בבא קמא דף צ\"ח ע\"ב) בתר הך שקל' וטריא דשורף שטר מחלוקת ר' שמעון ורבנן אמר אמימ' מאן דדאין דינא דגרמי מגבי ביה דמי שטרא מעלי' ואם איתא דדינא דגרמי מדאוריית' הא מעיקר' מפליג הש\"ס דאף ר\"ש דסבר דבר הגורם לממון כממון דמי מדאוריית' מודה בשט' שאין עיקרו ממון דפטור א\"כ מנא לי' לאמימ' דמאן דדאין דינא דגרמי מיחייב בשטר דלמא ס\"ל כר\"ש ודוחק לו' דאמימר פליג אשקל' וטרי' דלעיל ועוד דא\"כ לא הל\"ל אמר אמימר אלא הל\"ל אמימר אמר ועוד דא\"כ לל\"ל למאן דדאין דינא דגרמי הל\"ל בקצור אמר אמימר מאן דאמר דבר הגורם לממון כממון דמי מגבי ביה דמי שטרא מעלי' אלא ודאי דכל שקלא וטרי' דמעיקרא הוי מדינא דאורייתא וקאמר אמימר מילתא אחריתי דלמאן דדאין דינא דגרמי מקנסא דרבנן מגבי ביה דמי שטרא מעליא דפשיט' דיש לקנוס טפי בשורף שטר ממוסר ומחיצת הכרם שנפרצ':","ועוד נ\"ל ראיה מהא דאמרי' במרוב' (סוף דף ע\"א) ובפ' אלו נערות (כתובות דף ל\"ד סוף ע\"א) גבי הא דמחייב ר' מאיר ד' וה' בטבח שור הנסקל אמאי איסורי הנאה ניהו אמר רבא ר' מאיר סבר לה כר' שמעון דאמר דבר הגורם לממון כממון דמי כו' וכתבו התוס' שם תימה דילמא ר' מאיר לטעמיה דדאין דינא דגרמי דכ\"ש דמחייב בדבר הגורם לממון דהא אמר בהגוזל קמא דאפי' ר\"ש מודה בשטר שאין עיקרו ממון וי\"ל דאיכא נמי סברא איפכא דע\"כ לא מחייב ר\"מ אלא בשורף שטר וכה\"ג שראוי לכל העולם אבל שור הנסקל וקדשים אינו ראוי אלא לזה שיפטר בו ויש מפרשים דר\"מ לא מחייב אלא קרן אבל לא שמעינן ליה דמחייב כפל וריב\"א מפרש דבדינא דגרמי לא מחייב ר' מאיר אלא מדרבנן כדמוכח בסוף הכונס עכ\"ל וקשה לי על שני התירוצים הראשוני' דא\"כ היאך קאמר בפ' הגוזל קמא באנו למחלוקת ר' שמעון ורבנן הל\"ל נמי איפכא דע\"כ לא פליגי רבנן התם אלא בקדשים או לענין תשלומי כפל אבל בשטר שראוי לגבות לכל העולם מודו רבנן דחייב לשלם הקרן מיהת ודוחק לו' דרבא פליג אכל הך שקלא וטרי' דרב דימי בר חיננא ורב הונא בר' יושיע דבפ' הגוזל ועוד קשה לי על תירוץ הראשון דמה בכך שאינו ראוי אלא לזה סוף סוף גרם לו היזק ומה לו לזה שלא הי' ראוי לשאר העולם. ועוד קשה לי טובא על תירוץ השני דהא רבה קאמר בפרק הגוזל קמא השורף חמץ באנו למחלוקת ר\"ש ורבנן כו' אלמא דאין חילוק בין כפל לקרן והאיך נאמר דרבא פליג ארבה שהי' רבו ואם איתא דפליג עליה ה\"ל לאפלוגי עליה בדוכתא דאמר רבה למילתיה וה\"ל לאתקופי ולמימר ע\"כ לא פליגי רבנן התם אלא בכפל אבל לאפטורי מקרן מי שמעת להו אבל לפי תירוץ הריצב\"א דדינא דגרמי אינו אלא מדרבנן אתי הכל שפיר דכל שקלא וטרי' דעיקרא בפרק הגוזל קמא לא הוי אלא אי חייב מדאורייתא ובתר הכי מסיק אמימר דלר\"מ דדאין דינא דגרמי מדרבנן מגבי ביה דמי שטרא מעליא מדרבנן כן נ\"ל:","ובהכי ניחא מה שהקשו התו' בכמה מקומות דינא דגרמי אהדדי והוצרכו ליכנוס בכמה דחוקים ובחילוקים ודקדוקים שאינם נזכרים בש\"ס אבל למאי דמפרש ריצב\"א דדינא דגרמי דרבנן שקנסו במקום שהי' נראה להם לקנוס כגון בדבר דשכיח וכה\"ג אתי הכל שפיר וא\"צ ליכנס בחילוקים אחרים וכן הוא במרדכי פ' הגוזל שר\"י גמגם ברוב החילוקים וכ\"כ בסמ\"ג דף קמ\"ח ע\"א שלפי' ריצב\"א מתיישבו' כל ההלכו' וכ\"כ בתשו' מיימוני לס' נזיקין סי' ד' שר\"י גמגם ברוב החילוקים וגם כמה מקומות אינם מתיישבות לפי דבריו לכן נראה לריצב\"א דדינא דגרמי הוא משום קנס וכן מוכח בירושלמי לכן י\"ל שכל היזק המצוי ורגיל קנסו חכמים ובכך מתיישבו' כל ההלכות כו' עכ\"ל וע\"ש:","ונ\"ל עוד ראייה לזה מהא דקאמ' בפ' הגוזל קמא בתר כל הני שמעתתא דרבה ובתר מאי דקאמר התם דאמר רבה השורף חמץ באנו למחלוקת ר\"ש ורבנן כו' אמר אמימר מאן דדאין דינא דגרמי מגבי ביה דמי שטרא כו ואמאי שביק אמימר חמץ ונקט שטרא לחוד הל\"ל נמי מגבי ביה דמי חמץ מעלי' או הל\"ל מגבי ביה דמי מעליא ולמה נקט שטרא דוקא אלא נראה דוקא אשטר קאמר משום דשכיח אבל גזל חמץ ועבר עליה הפסח לא שכיחא וגם אין ראוי לקונסו שהרי אדרב' בשריפתו גרם תשלומין לנגזל והפסד לגזלן וניחא טפי להפוסקים דס\"ל דמדלא קאמר אמימר אלא בשורף שטר משמע דלא פליג ארבה בזרק מטבע ובשף מטבע ובצורם אוזן פרתו והסכים מהרש\"ל לדבריהם בזה כמ\"ש לקמן ס\"ק ז' רק שהוצרכו לדחוק מ\"ט לא פליג אמימר בהא ודבריהם מגומגמים בזה כאשר יראה המעיין ועוד קשה דה\"ל לאמימר לאפרושי החילוקים ההם אמאי לא דיינינן בהנך דלעיל דינא דגרמי אבל למה שכתבתי אתי שפיר דאמימר קאמר דמאן דדאין דינא דגרמי וקניס בדבר הרגיל מגבי ביה דמי שטר' מעלי' דשכיח הוא וא\"כ ממילא בהנך תלת' דלעיל דלא שכיח' דהא בזורק מטבע לים הגדול וצלולים דוקא ודוק' דאדיי אדויי ושף מטבע של חבירו דוקא בקורנס' וטרסיה ולא חסריה וצורם אוזן פרתו דכולהו שוורים לאו למזבח קיימי וכדאי' התם בסוגי' א\"כ כולהו מלתא דלא שכיח נינהו ולא שייך למקנסיה כל זה נ\"ל ברור ואפשר דלאמימר לא ברירא ליה דקנסא הוא אלא ספוקי מספק' ליה דדוחק לומר דבריר' ליה כיון דבפ' הגוזל בתרא בעי רב הונא בר חייא מרב נחמן לא איפשט' אלא נראה לומר דגם לאמימר מספקא ליה וקאמר בפ' הגוזל קמא דלמאן דדאין דינא דגרמי משום קנסא מגבי ביה בהאי שטרא דמי מעליא ובס\"פ הכונס קאמר דלמאן דדאין דינא דגרמי משום קנסא מבעי' אי עשו תקנ' נגזל במסור ודוק:","\u0003 דדאין דינא דגרמי. \u0004 ע' בתשו' מהר\"מ אלשיך סי' קל\"ד באריכו' ע' בתשו' מהרשד\"ם סי' קע\"ט ושל\"ב ות\"ס וע' בתשו' מהרי\"ט סי' צ\"ה וצ\"ח ובתשובות הר\"ב סי\"ז דף מ\"ו מ\"ז:","\u0003 דינא דגרמי \u0004 כ' בעה\"ת שער נ\"א ח\"ו גורם דגורם פטור וכדאמרי' בשבועות הכל מודים בעידי סוטה כו' הלכך השולח הבערה ביד חש\"ו (היינו כשמסר להם שלהבת דוקא כדלקמן סי' תי\"ח ס\"ז ע\"ש) ושרפו שטרות פטור עכ\"ל. והרמב\"ן בדיני דגרמי שלו דף קי\"ב ע\"ב ע\"ד חולק ע\"ז וכתב וז\"ל וכן אני אומר בגורם לשרוף שטרות חבירו חייב וליכא לדמוייה כלל לההיא דאמרי' בשבועות הכל מודים בעידי סוטה כו' דהתם לא חייבה התורה שבועה אלא על שבועת העדות המחייבת ממון או גורמת אבל גורם דגורם כפירת דברים הוא וממונא ליכא אפי' בכובש עדות גמור ומי שדמה שתי עניינים אלו וערבן חייב משום כלאים עכ\"ל ונראה דלפי מה שהעליתי לעיל דדינא דגרמי אינו אלא קנסא דרבנן יש לפטור גורם דגורם ודוק:","\u0003 דגרמי \u0004 עיין בסמ\"ע שהאריך בזה וכ' ודלא כמ\"ש שבריש דבריו שהן אליבא דהרמב\"ם כ' דהרמב\"ם מחייב בהנהו משום דדינ' דגרמי נינהו ובגרמ' בניזקין כ\"ע מודו דפטור וזה אינו כו' ושלא כדת השיג על הע\"ש כי הע\"ש לא הזכיר את הרמב\"ם רק כ' דגרמי חייב וגרמא בניזקין פטור וס\"ל דיש חילוק בין דינא דגרמי לגרמא וכ\"ע מודו דגרמא בנזיקין פטור וכן הוא להדיא כת' הרשב\"א שהביא ב\"י מחודש א' וכן כ' הרמב\"ן בדיני דגרמי שלו ומשמע שם להדיא שגם דעת הרי\"ף כן וכן מוכח באמת דעת הרי\"ף ס\"ס הכונס גבי ליבה ולבתה הרוח וכן בפ' לא יחפור גבי ההוא דהוה נפצי כיתנא וגם בחדושיו פ' לא יחפור השיג הרמב\"ן אפירש\"י דס\"ל דגרמי וגרמא הכל אחד ע\"ש וא\"כ דברי הע\"ש נכונים שהם אליבא דהרי\"ף והרמב\"ן והרשב\"א והמחבר דמחלקין בין דיני דגרמי לגרמא וכן משמע בתוס' מכמה דוכתי וכן הרא\"ש וטור ושאר פוסקים וס\"ל להע\"ש דכל הנך שהזכיר המחבר דחייב גרמי נינהו ובשאר גרמא בניזקין פטו' וכן הם דברי ר\"י נל\"א ח\"ב להדי' וגם מל' המחבר מה שרשם בתחלת הסי' ממה שמדבר הסי' נ' כן שכתב ורשם שפ\"ו חילוק שבין גרמא לניזקין לדינא דגרמי כו' וכן כ' מהרש\"ל פ\"ב דב\"ק סל\"ו ופרק ט' סי\"ט ע\"ש:","אך מה שרוצה מהרש\"ל שם לומר שגם רש\"י מחלק בין דינא דגרמי לגרמ' וכ' בפ' הגוזל קמא סי\"ט וז\"ל ואף שכתב הרמב\"ן בנימוקיו וז\"ל ואף רש\"י כך דעתו דרבא לית ליה דר\"מ בכול' עכ\"ל והנה הרמב\"ן לטעמו שסבר שלרש\"י אין חילוק בין דינא דגרמי לגרמא בניזקין ולא דק כפי מ\"ש בפ' כיצד סל\"ו עכ\"ל מהרש\"ל וכ\"כ עוד בפ' כיצד הרגל סל\"ו וז\"ל וכן נראה דעת רש\"י שכתב וזה שנטל פטור דגרמא בניזקין פטור ואף שכ' עליו הרמב\"ן בנימוקיו וז\"ל פירושו לדעתו דרבה אבל לדידן חייב דדיינינן דינא דגרמי ודינא דגרמי וגרמא בניזקין חדא מלתא היא לדעת רש\"י דוק ותשכח ותמצא זה רמוז בכמה מקומות בפירושיו עכ\"ל רמב\"ן ושרי ליה מריה שיאמר על פה קדוש שיטעה בצורה דשמעתא דהגוזל קמא דמוכח להדיא דגרמי חייב וכבר ידוע שגרמא בגרמא פטור לכ\"ע עכ\"ל מהרש\"ל.","ואני אומר במחילה מכבוד תורתו לא ירד לסוף דעת הרמב\"ן כי ודאי לא עלה על דעת הרמב\"ן שרש\"י טעה בשמעתא דהגוזל קמא רק שכונות הרמב\"ן לומר שרש\"י ס\"ל דדיני דגרמי וגרמא הכל אחד הוא ומ\"ש רש\"י על דברי רבה דזרק כלי כו' פטור דגרמא בניזקין פטור לא פי' כן אלא לדעתיה דרבה דהוא מרא דשמעתא דלקמן בהגוזל קמא דס\"ל השורף שטרו של חבירו פטור משום דגרמא בניזקין פטור ולא דאין דינא דגרמי אבל אנן קי\"ל כדמסיק בש\"ס התם דשורף חייב משום דדיינין דינא דגרמי וא\"כ לדידן בזרק כלי נמי חייב ורש\"י לא פי' כן אלא לדברי רבה (וזה ודאי אמת בדעת רש\"י ודלא כמהרש\"ל בדעתו) דליכא למימר דרש\"י מחלק בין גרמי נגרמא דהא משמע מדברי רש\"י דגרמי וגרמא כולהו חדא מילתא היא דהא רש\"י כ' על הנך מימרא דרבה פ' הגוזל קמא (בבא קמא דף צ\"ח ע\"א) טעמא דרבה בכולהו משום גרמא בניזקין הוא פטור עכ\"ל אלמא דס\"ל לרש\"י דשורף שטרו וזורק מטבע לים הגדול והשף מטבע כולהו חדא דינא אית להו דאל\"כ ה\"ל לרש\"י לחלק בין שורף לאינך אלא ודאי משמע דס\"ל לרש\"י דגרמי וגרמא חדא מלתא הוא לכ\"כ טעמא דרבה בכולהו משום גרמא בניזקין ופטור כלו' דלא דאין דינא דגרמי ולמאי דמסקינן דדיינין דינא דגרמי חייב בכולהו. ועוד מוכח כן להדיא מדברי רש\"י ס\"פ לא יחפור (סוף בבא בתרא דף כ\"ב) דגרסי' התם בש\"ס והא גרמא הוא אמר רב טובי בר מתנה זאת אומרת גרמא בנזקין אסור ופרש\"י גרמא בנזקין אסור אפי' למאן דלא דאין דינא דגרמי ופטור מלשלם אסור לגרום וכשבא להעמיד גרמא להזיק חבירו מעכב עכ\"ל הרי מבואר להדיא מדברי רש\"י דגרמי וגרמא הכל אחד הוא ועוד מוכח מדברי רש\"י ר\"פ הכונס דגרסינן התם תניא אמר ר' יושיע ד' דברים העוש' אותן פטור מדיני אדם כו' ופרש\"י פטור מדיני אדם קסבר גרמא בניזקין פטור עכ\"ל ואם איתא דרש\"י מחלק בין גרמי נגרמא וגרמא לכ\"ע פטור לא הל\"ל קסבר גרמא בנזקין פטור דלישנא דקסבר לא שייך אלא היכא דאיכא פלוגתא בדבר והכי הל\"ל פטור מדיני אדם דגרמ' בניזקין פטור אלא ודאי ס\"ל לרש\"י דגרמי וגרמא הכל אחד היא וכיון דאיכא פלוגתא בדיני דגרמי לכך כ' קסבר גרמא בניזקין פטור (ולקמן סי' תי\"ח ס\"ט הוכחתי דגם דעת הרמב\"ם וראב\"ן הוא כן דדיני דגרמי וגרמא הכל אחד הוא ע\"ש) ולדעתי פשוט שלזה כוון הרמב\"ן בנימוקיו שם שכ' וז\"ל ודיני דגרמי וגרמא בניזקין חדא מילתא הוא לדעת רש\"י דוק ותשכח ותמצא זה רמוז בכמה מקומות בפירושיו עכ\"ל ומביאו מהרש\"ל גופיה פ' כיצד הרגל שם וכונת הרמב\"ן כמ\"ש בכמה מקומות בפירושיו לפי' רש\"י ר\"פ הכונס ופ' הגוזל דף צ\"א ע\"א ופרק לא יחפור שהבאתי. שוב ראיתי בחדושי הרמב\"ן פרק לא יחפור הבין שם ג\"כ מדברי רש\"י כמ\"ש ע\"ש:","\u0003 אבל בבהמה לכ\"ע פטור \u0004 כ\"כ בנ\"י פרק הפרה שכתב הרא\"ה בשם רבו וצ\"ע דרבו של הרא\"ה הוא הרמב\"ן והרמב\"ן מפלפל בזה בדיני דגרמי שלו ומסיק דחייב וז\"ל שם בדף קי\"ד ריש ע\"ג ולפום הך סברא שורו שהדליק את האש ושרף שטרותיו של חבירו או אפי' קרען או מחקן פטור דגרמת שורו הוא ומסבר' דחייב ושאני גרמא דריחא דממילא אתיא מהך דהכא מעשה שורו הוא עכ\"ל ומ\"מ לפי מה שהעליתי לעיל ס\"ק א' דדיני דגרמי אינו אלא קנסא דרבנן ובדבר דלא שכיח לא קנסו א\"כ בבהמה פטור ועיין בשלטי גבורים פ' הפרה סוף דף כ\"ג ל' ריא\"ז:","\u0003 לפיכך כו'. \u0004 כ' מהרש\"ל פ' הגוזל בתרא ס\"ס מ\"ז דכל דיני דגרמי פטרינן באונס ומשמע התם דה\"ה שורף שטרות באונס פטור אבל הרמב\"ן בדיני דגרמי שלו לא כ' כן אלא כ' דמוסר ומוחל שטר וכה\"ג דדבורא בעלמא הוא ואקילו רבנן בדבורא ולא עשו בו אונס כרצון ומיהו ליתא להאי דינא אלא בהאי גרמא אבל השורף שטרות באונס חייב דהא לאו מחיל' היא עכ\"ל בריש דף קי\"ג. מיהו לפי מה שהעליתי לעיל ס\"ק א' דכל דיני דגרמי אינו אלא קנסא דרבנן פשיטא דפטו' באונס וכדאיתא בפ' הנזקין ונתבאר לעיל סי' שפ\"ה גבי מטמא ומדמע ומנסך דכיון דקנסא הוא פטור באונס וכן אם היה שוגג נמי פטור כמו מטמא ומדמע ומנסך והרמב\"ן שמחייב בדיני דגרמי שלו אף שוגג היינו משום דס\"ל דדינא דגרמי הוא דאורייתא:","\u0003 הדוחף כו'. \u0004 ודעת ר\"י והרא\"ש ושאר הרבה פוסקים דבדוחף מטבע לים ופוחת מטבע פטור והביא הר\"ב דעתם לקמן סעיף ג' וכ\"כ בהגהת אשרי פ' הגוזל שכ\"כ בא\"ז ובפסקי מהרי\"ח דבכולהו הלכה כרבה בר משורף שטרותיו של חבירו וכן פסק מהרש\"ל שם סי' ט\"ז וי\"ז ר\"ט וכן נר' עיקר וכמ\"ש לעיל סוף ס\"ק א' מיהו היינו דוקא שלא הגביהו ודחפה לים הגדול ודוקא במים צלולים דחזי ליה וכן בפוחת מטבע דוקא שלא חסרו וכן שלא הגביהו וע\"ש חלוקי דינים בזה. וכ' עוד מהרש\"ל שם בסי' י\"ז בשם ספר צפנת פענח דאפי' אם הכה על בתי נפש או שאר כלי כסף וזהב או על טבעת ופחת' נמי הוי כמטבע ממש ופטור ע\"כ והוא בראב\"ן סוף דף פ\"ט ואפשר לחלק דדוקא במטבע דליכא אלא צורתא אבל בכלי מעיקרא כלי הוי והשתא לאו כלי הוא והיינו שלא הוזכר דין זה בש\"ס ופוסקים רק גבי מטבע וצ\"ע:","\u0003 אע\"פ שלא הגביהו כו'. \u0004 דאלו הגביהו מיגזל גזליה השבה בעי מיעבד ש\"ס וכ' מהרש\"ל פ\"ט דב\"ק סי' ט\"ז וז\"ל ונ\"ל אף היכא דשקליה דצריך למעבד השבה מ\"מ יצא במה שמשלם לו שכר בר אמוראי ואינו צריך להטפל בה יותר וכן משמע מדברי התוס' לקמן גבי יש שבח סימנים ע\"ג צמר עכ\"ל ואין דבריו נראין לי דכיון דבעי למעבד השבה אינו יוצא עד שמחזירה למקום שנטלה ומ\"ש וכן משמע מדברי התוס' כו' ר\"ל בתוס' שם ריש דף ק\"א ולפע\"ד לא משמע משם מידי דהתוס' לא מיירי התם מזה אי קפיד בהכי משום דהתם מנח' הצמר קמיה אבל אי קפיד קפיד כן נ\"ל:","\u0003 וחזר ומחלו כו' \u0004 בסי' ס\"ו. ועיין מ\"ש שם בסעיף ל\"ב:","\u0003 וכן השורף שט\"ח של חבירו כו'. \u0004 כתב בעה\"ת שער כ\"ט אם בעל השטר אומר מנה היה בו והשורף אומר לא כי אלא נ' ישבע כדין מודה מקצת ואי אודי במקצת ועל השאר טען איני יודע מתוך שאינו יכול לישבע משלם עכ\"ל (וע' בספ' גידולי תרומה שם שהקשה שני קושיות על הבעל התרומות ושניהן אינם כלום ע\"ש ואין להאריך) ומביאו ב\"י ס\"ב וגם הד\"מ והב\"ח הביאוהו בסתם וכ\"כ העיר שושן. ודין זה צל\"ע דהא דקי\"ל סי' ס\"ו סעיף ל\"ט וריש סי' צ\"ה דאין נשבעין על השטרות לא שבועת השומרין ולא שביעת מודה מקצת והוא מן המשנה פ' שבועת הדיינים (שבועות דף מ\"ב ע\"ב) ובמשנה היה אפשר לדחוק דהיינו למאן דלא דאין דינא דגרמי או שאינו גורם היזק במה שאינו מחזיר השטרות רק שתובע גוף השטרות לאיזו טעם שיש לו אבל מסתימת כל הפוסקים שכתבו סתמא אין נשבעין שבועת מודה מקצת על השטרות משמע אף שמכח כפירתו לא יוכל התובע להוציא חובו אין נשבעין והכי מוכח להדיא בתוספות פ' שבועת הפקדון סוף (שבועות דף ל\"ז) שכתבו דהא דמיעט שטרות משבועה אתי שפיר טפי לר' מאיר דמחייב בשורף משום דינא דגרמי כו' וע\"ש: והנה היו לפני כמה דרכים ליישב דעת בעה\"ת ולא עלו כהוגן והעיקר נ\"ל דהבעה\"ת ס\"ל דדינא דגרמי ודבר הגורם לממון כממון דמי הכל אחד הוא וס\"ל הלכה כר' שמעון וא\"כ לדידן דלא קי\"ל כר' שמעון ליתנהו לדברי הבע\"ת וכמו שיתבאר וז\"ל הבעה\"ת שם בשע' כ\"ט חלק ב' ואי לא מודה כי' בעיקר השליחות ואמר חמשים צויתי לתתו ועל השאר איני יודע מתוך שאי\"ל משלם דקי\"ל כר' מאיר דדאין דינא דגרמי ודבר הגורם לממון בממון דמי וכי היכי דאי טעין בעל השטר מנה היה בשטר זה ששרפת והוא אודי ליה במקצת ועל השאר אמר איני יודע מתוך שאיל\"מ הכי נמי גבי חנוני כיון דחזקה שליח עושה שליחותו ודבר הגורם לממון היא הכי דיינינן דכמאן דטעין עליה בגוף הממון דמי עכ\"ל וכ\"כ עוד הבעה\"ת בשער נ\"א חלק ו' וז\"ל שהרי שורף שטרות חבירו פסקנו שאע\"פ שאין גוף השטר ממון כיון שהו' גרם לאבד ממון חברו חייב וכדאסיקנ' התם אמר אמימר מאן דדאין דינא דגרמי מגבי ביה דמי שטרא מעליא דקי\"ל כר' שמעון דאמר דבר הגורם לממון כממון דמי ואפי' בדבר שאין עיקרו ממון דכיון דשורף ועביד בידים או קורע שטרות של חבירו דינא דגרמי הוא כו' עכ\"ל וכתב עוד בבעה\"ת שם וז\"ל גם הראב\"ד כתב בתשובתו הריני מוסר לך מה שנראה לי לענין פסק דינן והלכ' למעשה פלוגתא דר' שמעון ורבנן הוי יודע שדעתי נוטה לקבוע מסמרות כר' שמעון דאמר דבר הגורם לממון כממון דמי ודינא דדבר הגורם שייך בדינא דגרמי כו' עכ\"ל ופלוגתא דר' שמעון ורבנן הוא במתני' פ' מרובה (בבא קמא דף ע\"ד ע\"ב) וגבי כפל וד' וה' ופ' הזהב (בבא מציעא דף נ\"ו ע\"ב) גבי אונאה ופ' שבועת הדיינים (שבועות דף מ\"ב ע\"ב) גבי שבועה דרבנן ס\"ל דהקדשות אין נשבעין עליהן ור' שמעון אומר קדשים שחייב באחריותן נשבעין עליהן ושאינו חייב באחריותן אין נשבעין עליהן ופירש\"י קדשים שחייב באחריותן נשבע דדבר הגורם לממון לר' שמעון כממון דמי והכי איתא בש\"ס פ' מרובה (בבא קמא דף ע\"א ע\"ב) ופ' הגוזל קמא (בבא קמא דף צ\"ח ע\"ב) דטעמי' דר' שמעון הוא דדבר הגורם לממון כממון דמי וא\"כ הרי משמע להדיא מדברי הבעה\"ת גופיה דאי הוי קי\"ל כרבנן לא היה נשבע זה השורף וא\"כ הרי רוב הפוסקים פסקו כרבנן הלא המה הרמב\"ם והברטנורה בפי' המשניות פ' מרובה ופ' הזהב ובפ' שבועת הדיינים וכן משמע דעת הרי\"ף והרא\"ש פ' שבועת הדיינים שהשמיטו שם מילתיה דר' שמעון מן המשנה וכ\"פ עוד הרמב\"ם והרב המגיד ריש פ\"ב מהלכות גניבה ופ' י\"ג מהלכות מכירה דין ח' ורפ\"ב מהלכות שכירות וכ\"כ עוד הרב המ' להדיא ריש פ\"ה מה' טוען שאפי' קדשים שחייב באחריותן אין נשבעין עליהן שאין הלכה כר' שמעון וכן מוכח עוד דעת הרבה פוסקים וכן עיקר וגם מה דס\"ל להבע\"ת דאמימר דדאין דינא דגרמי היינו משום דקי\"ל כרבי שמעון לא נהירא לי אלא משמע בפ' הגוזל קמא (בבא קמא דף צ\"ח ע\"ב) דאף אמימר סבר כרבנן וכמו שכתבתי לעיל ס\"ק הראשון בסופו ע\"ש:","ושוב ראיתי בדיני דגרמי להרמב\"ן שכתב להדיא כדברי וז\"ל שם בדף קי\"א סוף ע\"ב בשורף שטרות ודכותיה קי\"ל כר' מאיר דדאין דינא דגרמי ואע\"ג דלא קי\"ל כר' שמעון דאמר קדשים שחייב באחריותן חייב ואין משלמין עליהן תשלומי ד' וה' ואף אין נשבעין עליהן שהרי אין גופו ממון אע\"פ שגורמין לממון ואע\"פ שאם הזיק חייב לשלם אם פשע בשמירתה פטור שלא מצינו דינא דגרמי אלא במזיק ויש מי שאומר שהפושע מזיק הוא ומשלם אבל שבועת התורה לעולם אין נשבעין אלא על דבר שגופו ממון ולא על הגורם שהרי אין נשבעין על השטרות וכן נמי אין בהם אונאה דליתיה לדר' שמעון וכן הסכימו הגאונים ז\"ל דליתא לדר' שמעון עכ\"ל הרי להדיא דאין נשבעין שבועת התורה בשורף שטרות. ויותר מזה נראה מהרמב\"ן דבכל דיני דגרמי אין נשבעין שבועת התורה ויש לי לדקדק בזה על דבריו מדברי תשובות הרשב\"א ותשו' מיי' שהבאתי לקמן סי' שפ\"ח סעיף ז' ס\"ק ל\"ד וכן מדברי הרמב\"ם וכפי מה שפירשתי שם בס\"ק ל\"א מוכח שם מדבריהם דבמסור שייך ש\"ד אף דאינו חייב רק מדיני דגרמי ע\"ש ונראה לו' דאף מאן דס\"ל דבדיני דגרמי מחייבים ש\"ד מודים בשטרות וס\"ל דדוקא בהקדשו' ושטרות דממעטינן להו מקרא דאין נשבעין עליהם היכא דגלי גלי והיכא דלא גלי לא גלי:","ושוב ראיתי בדברי מהרש\"ל פ' הגוזל קמא סי' י\"ט כ' ג\"כ בפשיטות אי טעין השורף יודע אני שהי' כתוב בו חוב אבל איני יודע כמה ה\"ל משואיל\"מ ולא כ' לא טעם ולא ראי' וגם ק' עליו כל מ\"ש למעל' וצ\"ל דלשטתו אזיל דס\"ל שם כמ\"ש התוס' במרובה סוף ד' ע\"א דיש סברא איפכא דאפי' רבנן דפליגי אר\"ש מודו לר' מאיר דלא פטרי אלא בחמץ או בקדשים שאינו ראוי אלא לזה אבל שטר שראוי לכל העולם למכור ולגבות בו חייב וא\"כ חייב נמי שבועה אבל לפמ\"ש לעיל ס\"ק א' ולקמן ס\"ק י\"א (למ\"ד דינא דגרמי דאורייתא) דהעיקר כשינוייא בתרא שכתבו התוס' במרובה שם ובפרק אלו נערות (כתובות דף ל\"ד) סוף ע\"א בשם יש מפרשים דאין רבנן מודים לר\"מ אלא בקרן ולא בכפל א\"כ מוכח דה\"ה באונאה ושבועה פטרי רבנן ע\"ש ודוק לכן נ\"ל דברי הרמב\"ן בזה עיקר לדינא דכששורף שטרות אין נשבעין ש\"ד עליו דכיון דמעטינהו קרא משבועה משום שאין גופן ממון מסתמא מעטינהו אף שגורם לו היזק בזה ממה שאינו מחזיר לו השטרות כגון שאומר לא הפקדת אצלי אלא א' ומחמת זה לא יוכל המלוה להוציא חובו פטור משבועה דכיון שאין גופן ממון אין נשבעין עליהן וכדמוכח בשינוייא בתרא דתוס' והוא עיקר אם נאמר דדינא דגרמי דאוריית':","ונראה דאף לפי מה שהעליתי לעיל ס\"ס צ\"ה כהראב\"ד דהיכא דנפסדה הקרקע וא\"א למלאות החפירות והתביע' היא על הממון חייב ש\"ד היינו דוקא התם דקרקע אימעטיה מכח שישנה קרקע ואינה מטלטלים א\"כ מה שהיא בעינה גרע כחה וכיון דאשתני ואינה בעין אישתני דינה אבל הכא דשטרו' אימעטו כיון דמתחלתן אין עיקרן ממון ובזה לא אישתני ודו\"ק היטב. ומכ\"ש לפי מה שהעליתי לעיל ס\"ק א' דדינא דגרמי אינו אלא קנסא דרבנן דאין לחייב ש\"ד בהא (וכ\"כ מהרש\"ל פ' הכונס סי' ל' סעיף י\"א דלמאן דאמר דהוי דרבנן לא שייך שבוע' דאוריית' כלל) . ודלא כהבעה\"ת והנמשכים אחריו. כן נ\"ל:","\u0003 השורף כו'. \u0004 כתב הרמב\"ן בדינא דגרמי שלו דף קי\"א ע\"ב דה\"ה במי שגזל חמץ ועבר עליו הפסח שהיה יכול להחזירו להנגזל ולומר לו הרי שלך לפניך ובא אחר ושרפו חייב לשלם לגזלן מדינא דגרמי שהרי גרם להפסיד ממון מכיסו. ומהרש\"ל פ' הגוזל קמא סי' י\"ט כ' עליו ולא ידעתי על מי סמך שחולק על הסוגיא (פ' הגוזל קמא דף צ\"ח ע\"ב) שאמר השורף חמץ באנו למחלוקת ר\"ש ורבנן כו' ומאחר דהלכה כרבנן א\"כ משמע להדיא דפטור כו' עכ\"ל ולא קשה מידי דהרמב\"ן ס\"ל כתירוץ היש מפרשים שהביאו התוס' פ' מרובה (בבא קמא דף ע\"א) סוף ע\"ב ופ' אלו נערות (כתובות דף ל\"ד) סוף ע\"א ד\"ה סבר לה כר\"ש כו' דתרוצא קמא של התוס' ודאי לא מסתבר כלל וכמ\"ש לעיל ס\"ק א' דמה לי ששוה לכל העולם או ששוה לו ס\"ס גרם לו היזק וכן מצאתי בריטב\"א פ' אלו נערות שהכריע כתירוץ היש מפרשים הנ\"ל וכ' שהוא הנכון ע\"ש. וא\"כ הרמב\"ן פסק כסוגיא דמרובה ודפ' אלו נערות דהוא סוגיא דסתם ש\"ס ולא כדברי רבה שאמר השורף כו' באנו למחלוקת כו' ודוק בדברי הרמב\"ן בדינא דגרמי שלו דף קי\"א סוף ע\"ב ותמצא כדברי שהביא שם הש\"ס דפ' מרובה ודפ' אלו נערות הנ\"ל ולמד ממנה דלא מיתליא חדא בחברתה ע\"ש כי מהרש\"ל שם לא הביא דברי הרמב\"ן אלו רק קצר דבריו ונראה שלא דקדק בדבריו ע\"ש ודו\"ק:","ומ\"מ לפי מה שהעליתי לעיל ס\"ק א' דדינא דגרמי אינו אלא קנסא דרבנן הכא פטור דלא שכיח כמ\"ש בס\"ק א' ע\"ש:","\u0003 שטר חוב כו'. \u0004 וכן העושה עבדו אפותיקי וחזר ושחררו חייב המשחרר לבעל החוב שהרי הפקיע שיעבודו וגרם לאבד ממונו עכ\"ל רמב\"ם פ\"ז מחובל והראב\"ד השיג עליו וכ' הרב המגיד שם וז\"ל כ' עליו הר\"א אמר אברהם הרב אינו פוסק כן דרשב\"ג הוא דאית לי' הכי ורבנן פליגי עליה וקי\"ל כרבנן ולא דמי לשורף שטר חבירו דהתם בדחבריה קא עביד מעשה אבל הכא אמר בדנפשי קא עבידנא ואיני יודע אם נתכוין הר\"א ז\"ל באמרו הרב לרב אלפס ז\"ל כדרכו בשאר המקומות ואם לא לפי שלא נמצא דבר בהלכות הרב ז\"ל ובקצתן נמצא כרשב\"ג וכיון שכן הדרינן לכללין כ\"מ ששנה רשב\"ג במשנתינו הלכה כמותו וזו משנה פ' השולח וכ\"ש שהדבר הכרחי כאן לפסוק הלכה כמותו דהא טעמא דידיה משום דס\"ל דמזיק שעבודו של חבירו חייב ואנן דקי\"ל כדינ' דגרמי כ\"ש במזיק זה שהוא חייב דהוא אלים כדמוכח בהדי' בפ' המניח את הכד גבי שחטו בשרו מותר עכ\"ל. ואני אומר שאין דבריו מוכרחים וכוונת הראב\"ד הוא שהי' לפניו אותן נוסחאות הרי\"ף שלא הי' כתוב בהן הלכה כרשב\"ג וא\"כ ממילא הלכה כרבנן וכמ\"ש הרי\"ף התם להדיא לעיל מיניה במתני' דעבד שנשבה ופדאו כו' דפליגי רשב\"ג ורבנן וכ' הרי\"ף שם וחזינן לגאון דקא פסק הלכתא כרבנן דקי\"ל יחיד ורבים הלכה כרבים וא\"כ משמע דה\"ה הכא (ואע\"ג דכ' הרשב\"א והרא\"ש פ' השולח בשם הראב\"ד מדכתב הרי\"ף וחזינן לגאון כו' משמע דלא ס\"ל כהגאון מ\"מ הא מסיק הרשב\"א התם דס\"ל כהגאון וא\"כ דעת הראב\"ד בהשגות כאן כן ועוד דבשלמא לעיל י\"ל מדכתב וחזינן לגאון לא סבר הכי משא\"כ גבי מזיק שעבודו ודוק) ועוד דהא כ' הרי\"ף פ' גט פשוט דהך כללא דאמר רבה בר חנה משמיה דר' יוחנן כל מקום ששנה רשב\"ג במשנתינו הלכה כמותו ליתא עד דאיכא טעמא וכ\"כ הרשב\"א בחדושיו פ' מי שאחזו והר\"ן שם בשם הרי\"ף פ' ג\"פ ונראה שטעמו משום דאמרי' בס\"פ המדיר (כתובות דף ע\"ז) דאמוראי נינהו בהא אליבא דר' יוחנן. ומ\"ש הרב המגיד וכ\"ש שהדבר הכרחי כאן לפסוק הלכה כמותו כו' כדמוכח בהדיא פרק המניח כו' לפע\"ד לא מוכח מהתם מידי לפי מ\"ש הראב\"ד דלא דמי לשורף שטר חברו דהתם בדחבריה קעבד כו'. הרי נראה שהראב\"ד עצמו הרגיש בהך דהמניח את הכד וכתב דשורף שטר שאני והא דפריך התם הא נמי רבה אמרה דאמר רבה השורף שטר של חבירו פטור פריך מכח כל שכן כיון דאפי' בדחבריה פטור כל שכן בדידי' ומשני מהו דתימא התם ניירא בעלמא קלאי מיניה כו' א\"כ נהי דמזיק שעבודו אלים טפי לפי המסקנא היינו כמו דדיינין דינא דגרמי בשורף שטר של חבירו שחייב ה\"ה באחר שהזיק שעבודו של חברו אבל בלוה עצמו שהזיק שעבודו לא שמענו וא\"כ יש לו' דהלכה כרבנן דפליגי ארשב\"ג גבי לוה עצמו שהזיק דבדידיה קא עביד: ובהכי ניחא הא דקאמר רב הונא בר' יושיע סתמא זאת אומרת המזיק שעבודו של חברו פטור ופריך עליה הא רבה אמרה כו' ואם איתא אמאי פריך מרבה דהוא אמורא הל\"ל לימא כתנאי כרבנן ולא כר' מאיר דדאין דינא דגרמי אלא משמע דאף מאן דדאין דינא דגרמי פטר התם כיון דבדידיה קעביד כן נ\"ל:","מיהו דדעת הרא\"ש פ' המניח ופ' השולח כהרמב\"ם וכן דעת הרמב\"ן והר\"ן פ' השולח ושאר פוסקים וכ\"פ מהרש\"ל פ' המניח סי' כ\"ח וכ\"כ הט\"ו לעיל סימן קי\"ז ס\"ו וכ\"כ רי\"ו ומביאו ב\"י וד\"מ סי' זה וכתבו עוד בב\"י וד\"מ לשון ר\"י שכ' וז\"ל וכתב הר\"מ שאם היתה אפותיקי ומחל לו המלוה בעל הקרקע תובעו. ולשון זה מגומגם אבל כשתעיין בר' ירוחם עצמו תראה שלשונו נכון שמתחלה כתב בשם הר\"מ שבעל הקרקע תובעו ואח\"כ כ' בשם הרא\"ש ואפילו מחל לו המלוה בעל הקרקע תובעו ור\"ל אפילו מחל המלוה למזיק בעל הקרקע תובעו למזיק וע\"ש עוד כתבו ב\"י וד\"מ שם בשם ר' ירוחם ואם הי' אפותיקי מפורש אין הב\"ח גובה מהמזיק כמו שאינו גובה משאר נכסי הלוה עכ\"ל ותימא אך העתיקו דברים אלו בסתם והלא דברים אלו תמוהים אדרבא כשהוא אפותיקי מפורש הוא דגובה הב\"ח מהמזיק אבל באפותיקי סתם מצי המזיק לומר לב\"ח מה עשיתי לך הלא תגבה משאר נכסים ומאי דמיון הוא זה שכ' כמו שאינו גובה משאר נכסי הלוה אדרבה כיון שאינו גובה משאר נכסי הלוה הב\"ח גובה מהמזיק כיון שהזיק שעבודו וכדקי\"ל המזיק שעבודו של חבירו חייב וכן התוס' פ' השולח (גיטין דף מ\"א ע\"א) וכן הר\"ן שם והרמב\"ם פי\"ח מהל' מלוה והרב המגיד שם ופ\"ז מה' חובל והטור סי' קי\"ז ושאר פוסקים פירשו להדיא הך דרשב\"ג דמזיק שעבודו של חבירו חייב והיינו באפותיקי מפו' ואע\"ג דהתוס' והפוסקים מיירי כשהזיקם הלוה עצמו מ\"מ פשיטא דחד דינא אית להו לענין שיהא חייב משום מזיק וכן משמע להדיא בחדושי הרשב\"א פ' השולח ואדרבה כשהזיקם אחר גרע טפי וכמ\"ש לעיל לדעת הראב\"ד בהשגות וגם מדברי ר' ירוחם עצמו שם בנל\"א סוף ח\"ב נראה להדיא כמ\"ש דבאפותיקי מפורש חייב המזיק וז\"ל שם המזיק שעבודו של חברו כגון שחפר בשדה המשועבדת לחברו בורות חייב דקי\"ל כמאן דדאין דינא דגרמי וכ' רבינו מאיר דאם עשה שדהו אפותיקי מפורש ובא אחר וחפר בה בורות לא מצי למימר לבעל הקרקע לאו בעל דברים דידי את כי לא נתחייבתי אלא למלו' כי גם נתחייב לבעל הקרקע ומשתעי דינא בהדיה בעל הקרקע וכ' הרא\"ש ואפילו מחל לו המלוה בעל הקרקע תובעו כ' מורי הרב ר' אברהם שאם אמר ליה בפי' לא יהא לך פרעון אצא מזה ובא אחר וחפר בה בורות דאין בעל חוב גובה מן המזיק כי כמו שאינו גובה משאר נכסי דליה כך לא יגבה ממזיק עכ\"ל הרי שמתחלה כתב להדיא דבאפותיקי מפורש חייב לשלם למלוה לכך נ\"ל שסוף דבריו מ\"ש בשם מורו ה\"ר אברהם הם מוטעים קצת וצריך להגיה בזה\"ל כתב מורי ה\"ר אברהם שאם א\"ל בפירוש לא יהא לך פרעון אלא מזה ובא וחפר בשדה אחר בורות דאין ב\"ח גובה מן המזיק כו' וזה דין אמת ופשוט. אבל מדברי ב\"י וד\"מ נראה שלא השגיחו בזה ומשמע להדיא מדבריהם שהדברים הם כהווייתן והוא תמוה: ודע דאחר שהזיק שעבודו לאו משום מזיק שעבודו לחוד חייב אלא חייב נמי מדרב נתן וכ\"כ המרדכי פרק המניח שאמר רבינו מאיר למורו הר\"י מוינא דהתם מיירי שהבעלים בעצמם עשו לו ההיזק דאל\"כ בלא\"ה חייב מדרב נתן שהרי החופ' בקרקע בורות מן הדין חייב לפרוע לבעל הקרקע דהפסידו וכיון דחייב לו יתחייב לבעל חובו מדר' נתן וע\"ל סי' פ\"ו:","\u0003 חייב לשלם כו'. \u0004 משום דינא דגרמי ורבה דפטר בש\"ס פ' הגוזל קמא (בבא קמא דף צ\"ח) לא דאין דינא דגרמי וכ' מהרש\"ל פ' הגוזל קמא סימן י\"ט וז\"ל ונראה דאיירי דוקא דלא שקליה בידי' דלא הוי גזלן או שהיה בידו כבר בפקדון אבל שקליה בידיה ואגביה הוי גזלן לכ\"ע והשבה בעי למעבד וחייב לכ\"ע אפילו לרבה דלא גרע דיני דגרמי מגרמא בניזקינן דמסקינן לעיל דאי שקליה בידיה גזלן הוא וחייב כ\"ש הכא וא\"כ ישבע הנגזל כמה היה כתוב ביה דהא עשו תקנת נגזל בגזלן ודוקא בשטר ששוה הנייר פרוטה לצור ע\"פ הצלוחית דהוי בודאי גזלן אבל אי לא [לא] הוי ודאי גזלן ודלמא ליכא כאן דיני גזלה ואין כאן תקנה לנגזל עכ\"ל ואין דבריו נכונים בעיני דרבה סתמא קאמר ומשמע אפילו שקליה בידים ואגביה ושרפיה פטור ועוד דהא מעיקרא קאמר רבה זורק מטבע לים הגדול וה\"מ דאדיי אדויי אבל שקלי' בידים מגזל גזליה ובעינן השבה מעליא ובתר הכי קאמר בסתמא השורף שטר של חברו פטור מ\"ט דא\"ל ניירא בעלמא קלאי מינך משמע דבשורף שטרו של חברו אפילו שקליה בידי' פטור וגם נראה דאשתמיטתי' למהרש\"ל כולא סוגיא דפרק הגוזל בתרא (סוף בבא קמא דף קי\"ז) דממעטי' התם קרקעות ועבדים ושטרות מקרא דאין נגזלין וע\"כ בגזל קרקע ושטפה הנהר או נשרפה פטור ואיתא התם דאפילו ר' אליעזר דפליג בקרקעות מודה בשטרות והכי איתא נמי להדיא בש\"ס פרק שבועת הפיקדון (סוף דף ל\"ז) ומוכח התם להדיא דכיון דאימעטו מגזלה א\"כ אפילו שטפה נהר או נשרפה אחר שגזלן פטור מטעם דברשותא דמרא קמא קיימי ואף דאיתא התם לישנא דהרי שלך לפניך פירושו ברשותך הוא וכ\"כ הרא\"ש פ' הגוזל בתרא וז\"ל שטפה נהר אומר לו הרי שלך לפניך כלומר תקחנה במקום שהיא כאלו לא גזלה דקרקע אינה נגזלת וברשות בעליה נשטפה עכ\"ל וכ\"כ הרמב\"ם ריש פ\"ט מה' גזלה הגוזל קרקע ונשחתה מאליה כגון ששטפה נהר או נשרפה באש שירדה מן השמים אומר לו הרי שלך לפניך שהקרקע בחזקת בעליה קיימת ואין אחריות הפסד עליו כו' משא\"כ במטלטלים כמו שביארנו עכ\"ל וא\"כ ה\"ה שטרות דמחד קרא אמעטי ואדרבה כ\"ש שטרות דהא אפי' ר' אליעזר דדריש רבוי ומיעוטי ולא ממעט קרקע ממעט שטרות (וכן משמע להדיא מדברי הרמב\"ם ספ\"ח מהל' גזל' דקרקעות ועבדים ושטרות חד דינא אית להו מהא וכמ\"ש לקמן) והכי מוכח ודאי דקרא ממעט אפי' נשרפו דאי כשהן בעין לא צריך קרא למעוטי שטרות דהא אפי' מטלטלים כגון בחמץ ועבר עליו הפסח אומר לו הרי שלך לפניך וכדאיתא בהגוזל קמא (דף צ\"ח ע\"ב) אמר רבה דכ\"ע אמרי' באיסורי הנאה הרי שלך לפניך דאל\"כ נפלגו בחמץ בפסח כו' אלא ודאי הא דממעט קרקעות ועבדים ושטרות היינו דמתחלה אין נגזלין כלל והרי הן כאלו לא גזלן כלל וכל היכא דאיתנהו ברשותא דמרא קמא איתנהו והכי איתא להדיא בש\"ס פ' הגוזל קמא (בבא קמא ריש דף צ\"ו) דטעמא דבקרקעות ועבדים אומר לו הרי שלך לפניך משום דברשותי' דמאריה קאי דפריך התם אהא דאמר רב התוקף בעבדו של חברו ועשה בו מלאכה פטור ואי עבדא כמקרקעי דמי אמאי פטור ברשותיה דמרי' קאי ומשני הב\"ע שלא בשעת מלאכה כדאמר רב הונא הדר בחצר חבירו שלא מדעתו א\"צ להעלות לו שכר:","ואף הראב\"ד בהשגות רפ\"ט מה' גזלה דפליג בעבדים משמע להדיא מדבריו דמודה בשטרות דהא משמע מדבריו דלא פליג בעבדים אלא משום דמצינן בקרא דנקנין ביאוש דכתיב וישב ממני שבי אלמא לאו כקרקע דמי הלכך כשמת העבד או נשרף משלם את דמיו דכשמת לגזלן מת עכ\"ל משמע להדיא הא בשטרות דליכא קרא דנקנין ביאוש דמי לקרקע וגם בעבדים גופי' נ\"לעיקר דדינן כקרקע כמ\"ש לעיל סי' שס\"ג:","והכי מוכח נמי להדיא מדברי התוס' פ' שבועת הפקדון סוף (שבועות דף ל\"ז) שכתבו דלמאי דמסיק דלא פליגי לענין שבוע' רק לענין השבה כשנשתנו קשיא מה שייך למעוטי שטרות הא אפי' שרפן פטור לרבה דלא דאין דינא דגרמי וצ\"ל דסבר כר\"מ דדאין דיני דגרמי אי נמי כי פטרינן היינו כי קלנהו באתרייהו אבל נטלו ושרפו חייב עכ\"ל כוונתם לומר אבל נטלו ושרפו חייב אי לאו קרא להכי אתי קרא למעוטינהו מגזלה וא\"כ אפי' נטלו ושרפו פטור למאן דלא דאין דינא דגרמי. ובפסקי תוס' שם איתא נטל שטרות של חברו בידו ושרפן לכ\"ע חייב. ונ\"ל שטעה בפשט דברי התוס':","ועוד נ\"ל להוכיח כן מדברי הרמב\"ם ספ\"ח מה' גזלה שכ' וז\"ל העבדי' ושטרות וקרקעות אין בהם תוס' חומש שנא' וכחש בעמיתו בפקדון כל האמור בענין מטלטלין הוא וגופן ממון יצאו קרקעות ועבדים שהקשו לקרקעו' ויצאו שטרו' שאין גופן ממון וכן אם היו גזל גר שאין לו יורשים אין חוזרים לכהנים וכן הקרקע אינה נקנית לעולם לגזלן אלא ברשות בעליהם עומדת כו' ואל תדקדק מדבריו שכ' בסוף קרקע לבד דהא וכן קאמר אמ\"ש דעבדי' ושטרות דינן כקרקע ותדע שהרי כ' ר\"פ ט' מיד אח\"כ משא\"כ במטלטלי' כמו שאמרנו. ואפי' למאי דגריס הראב\"ד בדברי הרמב\"ם משא\"כ בעבדים מוכח מהראב\"ד שם דשטרות דינן כקרקע אף להרמב\"ם ועוד שכבר הוכיח הרב המגיד שם שעיקר הגירסא משא\"כ במטלטלין ועוד דמנין לו לחלק בין קרקע לשטרות וכן משמע עוד מדברי ה\"ה ס\"פ ח' שכ' וכן הקרקע אינה נקנית לעולם לגזלן כו' כרבנן דהגוזל עצים (ט\"ס הוא וצ\"ל הגוזל בתרא וכ\"כ הב\"ח בר\"ס שע\"א) והא התם בפלוגתא דרבנן אימעטו נמי שטרות לכ\"ע ועוד דאל\"כ תיקשי מנ\"ל להרמב\"ם הא שכתב וכן אם הי' גזל גר שאין לו יורשים אינן חוזרים לכהנים וגם הרב המגיד ציין שם וכן אם הי' גזל הגר כו' ושקיל וטרי בה ולא כ' מאין הוציא הרמב\"ם כן וכן הסמ\"ג דף קל\"ב ע\"א כתב כדברי הרמב\"ם וכן אם היו אלה שלשה גזל הגר שאין לו יורשים אין חוזרים לכהנים ולא כ' מקור לזה וליכא למימר דבגזל הגר נמי ממעטינן להו מכלל ופרט דהא האי קרא דוכחש בעמיתו בפקדון כתיב בסוף פ' ויקרא והתם איתא כלל ופרט וכלל וממעטינן להו וגזל הגר איתא בפ' נשא ושם ליכא כלל ופרט וכלל בקרא כלל דלימעטינהו א\"ו פשיטא להו להרמב\"ם והרב המגיד וסמ\"ג דכיון דאיתמעטי קרקעות ועבדים ושטרות בפרשת ויקרא דאינן נגזלין כלל וכי נשרפו ברשותיה דמרא קמא נשרפו א\"כ לא שייך כאן לומר שיהא בהן משום גזל הגר לכהנים דהא אין כאן גזלה כלל ובכ\"מ שהן ברשות הגר הן. כנ\"ל ברור וא\"כ מוכח להדיא דעת הרמב\"ם והרב המגיד והסמ\"ג דשטרות אין נגזלין כלל הארכתי בזה כי דין זה הוא חדוש גדול וברור הוא:","העולה מזה קרקעות ועבדים ושטרות אין נגזלין והרי כאלו הן ברשות הבעלים לפיכך אם אחר שגזלן נשרפו מעצמן בבית הגזלן פטור ואם שרפן הגזלן אינו חייב אלא משום דינא דגרמי משום קנס חכמים:","\u0003 כל החוב כו'. \u0004 היינו ששמין כמה היה שוה למכור כדלעיל סי' ס\"ו סעיף ל\"ב ואין סברא לחלק בין מוחל לשורף וגם בתשובת הרא\"ש כלל ס\"ט סי\"א משמע להדיא דגם בשורף דינא הכי ע\"ש וכ\"כ בתשו' מהרשד\"ם סי' ל\"ב וע\"ש ע' בתשו' מהרשד\"ם סי' ת\"ח ובתשו' מהר\"ם אלשיך סי' נ\"ד ובתשו' מ\"ע סי' נ\"ב ופ\"ט ובתשו' מהר\"א ן' ששון ס\"ס ק\"מ:","ועיין בתשובת מהר\"י ן' לב ספר א' ס\"ס קס\"ג דף קנ\"ח ע\"ג שא\"נ השורף לומר פרעתי לו ההיזק למ\"ד דינא דגרמי דאורייתא אלא דמצי למימר קים לי כמ\"ד דרבנן ולי נראה שנאמן לכ\"ע ודוק:","\u0003 ובלבד שיודה לו המזיק כו'. \u0004 ואם המזיק אינו יודע כתב מהרש\"ל פ' הגוזל קמא סי' י\"ט דלא אמרינן שכנגדו נשבע ונוטל דגבי שורף שטרות של חבירו גרע ממסור ולכ\"ע לא עשו תקנת נגזל בשורף כיון דניירא בעלמא קלא מיניה ומשמע שם מדבריו שהוציא כן מן הרא\"ש והנ\"י ובאמת משמע לכאורה כן בהרא\"ש פ' הגוזל קמא אבל לפע\"ד לא נהירא לחלק בדיני דגרמי בין זה לזה דנראה דכונה דינא דגרמי חד דינא אית להו וכי קמבעיא לן בס\"פ הכונס עשו תקנת נגזל במסור או לא בכולהו דינא דגרמי מבעי לן והכי משמע מלישנא דש\"ס שם דקאמר אליבא דמאן דלא דאין דגרמי לא תבעי לך דמסורות נמי לא דיינינן כי קמבעי לן אליבא מאן דדאין דינא דגרמי כו' והא דקאמר בש\"ס פרק הגוזל קמא אי דליכא עדים מנא ידעינן ולא קאמר דמשתבע ושקיל היינו משום דודאי רבה לא מיירי במלתא דמבעי' לש\"ס וגם מ\"ש מהרש\"ל שכ\"כ הר\"ן ור\"ל הנ\"י לפע\"ד לא מוכח מהנ\"י מידי דלא קאמר הנ\"י אלא דלא אמרי' בפשיטות דמשתבע ושקיל אלא כמו דמבעיא לש\"ס במסור ה\"נ מבעיא גבי שורף אבל מידי ספקא לא נפקא ע\"ש בנמוקי יוסף וגם בהרא\"ש יש לדחות דלא כ' כן אלא לס\"ד דש\"ס דלא דיינינן דינא דגרמי ע\"ש ואף אם ת\"ל דכוונת הרא\"ש כפשוטו וכדעת מהרש\"ל מ\"מ לענין דינא י\"ל כמו שכתבתי וכן מצאתי להדיא בתשו' מיימוני לספר נזיקין סי' ד' הביא תשובת רב האי גאון משמע שם להדיא דשורף שטרו של חברו ומסור חד דינא אית להו לענין תקנת נגזל וכמו דמבעיא לש\"ס גבי מסור ה\"נ בשורף וכבר נודע שאין לחלוק על הגאון אם לא בראיה ברורה ומכ\"ש כאן דפשטא דש\"ס משמע כהגאון וכמו שכתבתי:","שוב מצאתי במרדכי פ' הכונס וז\"ל תקנת נגזל במסור דסלקא בתיקו פי' ר\"י לקולא ורב האי גאון פסק בשער העשרים יחלוקו אבל בתשובתו פסק כיון דאשו ומסור סלקא בתיקו המע\"ה עכ\"ל ובספר גדולת מרדכי מחק תיבת דאשו וגם מהר\"מ מטיקטין בגליון המרדכי דחק מאד בזה משום דקשיא להו דהא באשו פשוט בש\"ס דעשו תקנת נגזל אבל לפע\"ד ר\"ל אשו בשורף שטר והיא כך תשובת של רב האי גאון שהובא בתשו' מיי' הנ\"ל וכ\"כ להדיא ג\"כ בתשו' מיי' הנ\"ל דבשער העשרים פסק רב הגאון דיחלוקו ובתשוב' הנ\"ל חזר בו ע\"ש. ויצא לי מזה דגם במרדכי רמוזה תשו' רב האי גאון הנזכרת:","\u0003 שהם יעשו כו'. \u0004 כתב הסמ\"ע ס\"ק ד' דל\"ד קאמר דהרי העדים כבר עשו שליחותן ואין יכולים לכתוב לו תו שטר אחר אלא ר\"ל שהעדים יאמרו הדבר לפני הב\"ד והב\"ד יכתבו לו שטר אחר כדלעיל ריש סי' מ\"א עכ\"ל וכן פי' הנ\"י פ' ג\"פ ל' הש\"ס וכ\"כ הבעה\"ת סוף שער נ\"ז בשם הראב\"ד ע\"ש:","\u0003 וכן כל כיוצא בזה. \u0004 עיין בתשו' מהרא\"א ן' ששון סי' קפ\"ט:","\u0003 וי\"א כו'. \u0004 וכן דעת הרבה פוסקים וכ\"פ מהרש\"ל פ\"ב דב\"ק סל\"ו ופ\"ט דב\"ק וכן נראה עיקר וכמ\"ש לעיל ס\"ק א':","\u0003 בדוחף כו' או פיחת כו' \u0004 עמש\"ל ס\"ק ז' בזה:","\u0003 ולכן אפילו זרק כלי כו'. \u0004 כלומר כלי של חבירו ונראה לי דזה מיירי שלא הגביה הכלי רק דחפו מן הגג לארץ אבל הגביהו מיגזל גזלי' השבה בעי מיעבד כדלעיל ס\"ק ח' וחייב ודוק:","\u0003 או שליש שהחזיר שטר וכו' \u0004 וכן אם החזיר שטר פרוע לעכו\"ם על א' והעכו\"ם הוציא ממנו פטור דהוי גרמא כ\"כ הב\"י מחו' א' והד\"מ בשם תשו' הרשב\"א. ובתשו' מהרש\"ך ס\"א סי' כ\"ז הקשה על הרשב\"א דמ\"ש משורף שטרות של חבירו ובתשו' מהר\"י לבית לוי סי' ל\"ד יישב דברי הרשב\"א ודבריו פשוטים וע\"ש גם בתשו' מהר\"מ אלשיך סי' קי\"ב וכן בתשו' מהר\"מ מלובלין סי' ס\"א מביאים דברי הרשב\"א לפסק הלכה וע\"ש וגם מדברי תשו' משאת בנימין סי' פ\"ה מתיישב קושית מהרש\"ך וק\"ל:","\u0003 שליש שהחזיר כו' \u0004 בתשו' משאת בנימין סי' פ\"ה פסק דדוקא החזיר למלוה הוי גרמא אבל שטר שאינו פרוע שהחזיר ללוה מיקרי גרמי וחייב והוכיח כן מתשו' הרא\"ש כלל ל\"ט סי' ב' (שהביא ב\"י לעיל סוף סי' ס\"ז מחו' מ\"ו) ופשוט הוא דהא הוי כשורף עיין בתשו' מבי\"ט ח\"א סי' כ\"ג וס\"ס נ\"ד:","\u0003 כולם פטורים דלא הוי אלא גרמא בניזקין. \u0004 וכן משסה כלב בחבירו סי' שצ\"ה ופורץ גדר לפני בהמתו סי' שצ\"ו ס\"ד והשולח את הבער' ביד חש\"ו סי' תי\"ח ס\"ז וליבה וליבתו הרוח שם סעיף ט' וכופף קומתו של חבירו לפני הדליקה שם סעיף י\"א ותקע באזנו סי' ת\"ך סכ\"ח וכה\"ג כולם גרמא נינהו ופטורין:","עוד איתא בטור ופוסקים הנותן סם המות לפני בהמת חבירו פטור מדיני אדם דלא הוי אלא גרמא וכ\"כ הרמב\"ם רפ\"ד מהל' נזקי ממון ותימה שלא כתבו המחבר בשום מקום. ובש\"ס פרק הפרה (דף מ\"ט ע\"ב) איתא דל\"מ אכלה סם המות אלא אפילו אכלה עשב מאכל בהמה שהיא סם המות לה פטור ונראה דה\"ה כשעירב סם המות במאכל הראוי לה פטור:","\u0003 י\"א דבכל גרמא בניזקין אם הוא שכיח כו'. \u0004 ל' הרב אינו נכון בעיני שלא מצאתי מי שאומר בכל גרמא בניזקין אם הוא שכיח שחייב לשלם משום קנס ומי מפיס איזו שכיח ואיזהו לא שכיח אבל בעל סברא זו הוא ריצב\"א בתו' ס\"פ לא יחפור ושאר פוסקים שכתבו לתרץ דהא דבכמה עניינים איתא בש\"ס דחייב משום דינא דגרמי ובכמה ענינים פטור ותירץ דדינא דגרמי אינו אלא משום קנס ואותן שהיו נראה להם לחכמי הש\"ס שהוא שכיח ורגיל לבוא קנסו וע\"ש. וגם בסמ\"ע ס\"ק ז' כתב דלפי מ\"ש הרב דבדבר השכיח ורגיל קנסו א\"כ גם בשליש שהחזיר השטר קנסו כו' ולא נהירא לי דדוק' מילת' דמצינן בש\"ס דקנסו אמרי' משום שהיה נראה להם דשכיח קנסו אבל בהא מאן לימא לן דשכיח הוא וכיון דדינא דגרמי אינו אלא קנסא דרבנן הבו דלא לוסיף עלה ואין לך אלא מה שאמרו הם כן נ\"ל:","\u0003 ולכן יש מי שכתב כו'. \u0004 הוא מהר\"מ מריזבורג שכתב כן בנימוקיו ואיתא שם ששמעון היה שם ואמר כן אחר שנגמר המקח וקבל העכו\"ם המקח והרב בד\"מ כתב עליו וז\"ל ואינו נראה לי דהא אין ההיזק בא מיד וגם הוא אינו עושה ההיזק גופי' ואפשר דהיה מילתא דשכיחא בימי מהר\"ם ולכן פסק כן וכדעת הריצב\"א דכתב דבמקום דשכיח קנסו כן נ\"ל ע\"כ ובאמת צ\"ע בדין זה ומ\"ש הר\"ב ואפשר דכה\"ג הוי כמסור איני נ\"ל דמסור מזיקו ומחסרו ממון אבל הכא אינו מחסרו ממון שהרי העכו\"ם מחזיר לו את שלו. וראיתי בנמוקי מהר\"מ מריזבורג ולא כ' בפירוש שחייב רק דאיתא שם שמעון היה לו עור ולקחו ראובן ממנו והביאו להגמון ואמר ליה ההגמון אמור בגימור דבר כמה סוף דמיו א\"ל לא פחות מליטרא כסף וקבלו מיד בכך והיה שם לוי ואמר עור זה רע הוא ודמיו יתרים ועתה טוען ראובן שהפסיד ה' דינרים ע\"י לוי אם יש עדים שכך הי' כיון שקבל ההגמון העור אע\"פ שלא פי' בכך אני נוטלו נתקיימה המכירה בקבול העור מיד ראובן עכ\"ל ונראה דמיירי שהעור לא הי' דמיו ידועים שאפשר שהי' שוה ליטרא כסף ואי לאו דנתקיימה המכירה מתחלה לא הפסידו לוי כלום שהרי מעולם לא קנהו ההגמון בליטרא כסף אבל עכשיו שנתקיימה המכירה א\"כ הרי העור נמכר בליטרא כסף ונמצא שראובן מוכרח לשלם לשמעון ליטרא כסף וע\"י דבורו של לוי פחת ההגמון ה' דינרים והחזיק בעור לעצמו ונמצא שהפסיד לוי לראובן ה' דינרים מכיסו שחייב לשלם לשמעון. אבל הר\"ב לא מיירי בהכי שהרי לא כתב בד\"מ ולא כאן בהג\"ה שראובן לקח דבר זה משמעון והביאו להגמון ומ\"מ נראה דאף הרב לא מיירי אלא כשהעכו\"ם מחזיק המקח לעצמו ומחסר לראובן בשביל דבורו של לוי שלא כדין בכח כי המקח שוה באמת כ\"כ כמו שמכרו ראובן אבל היכא שהעכו\"ם מחזיר לראובן את שלו אע\"פ שמתוך כך מוכרח למכרו לאחר בפחות אין שמעון חייב לשלם לו מה שהפסיד שהרי אינו מחסרו כלום כן נ\"ל ודו\"ק:","\u0003 המבטל כיסו כו'. \u0004 עיין בתשובת ן' לב ספר ב' סי' כ\"ו:","\u0003 הזורק חייב. \u0004 והנ\"י ר\"פ כיצד הרגל כתב בשם הריטב\"א בשם רבו שפסק כיון דמספקא ליה לרבא שניהם פטורים דהמע\"ה ומביאו הב\"ח ס\"ס זה וגם בשלטי גבורים פ' כ\"ה דף י\"ג וי\"ד מביאו ומפלפל בדבריו וכ\"כ בעל המאור פ' כ\"ה דאע\"ג דלרבה פשיטא לי' כיון דלרבא מספקא ליה חיישינן לה אלא דפסק שם דה\"ל ממון המוטל בספק וחולקין וא\"כ לדידן דקי\"ל בכל ספק המע\"ה ה\"ה הכא שניהם פטורים משום המע\"ה והרמב\"ן בספר המלחמות השיב שם על דברי בעל המאור ואין דבריו מוכרחים וע\"ש:","\u0003 והמשבר פטור. \u0004 אבל אם זרק חץ או אבן על הכלי וקדם אחר ושבר הכלי קודם שנפל החץ עליו פטור הזורק והמשבר חייב כ\"כ התוס' ר\"פ כ\"ה והנ\"י בשם הר\"א ומביאם הב\"ח ופסק כן וכ\"כ בהגהת מיימוני פ\"ז מהל' חובל וכ\"כ מהרש\"ל פ\"ב דב\"ק סי' ד' וסי' ל\"ו וע\"ש ועיין בתשו' מהר\"מ אלשיך סי' קל\"ד:"]],["\u0010y0\u0011 \u0010c0\u0011 שָׁמִין לַמַּזִּיק בְּיָדוֹ, כְּדֶרֶךְ שֶׁשָּׁמִין לוֹ אִם הִזִּיק מָמוֹנוֹ. כֵּיצַד, הֲרֵי שֶׁהָרַג בֶּהֱמַת חֲבֵרוֹ אוֹ שָׁבַר כֵּלָיו, שָׁמִין כַּמָּה הָיְתָה הַבְּהֵמָה שָׁוָה וְכַמָּה הַנְּבֵלָה שָׁוָה, וְכַמָּה הָיָה הַכְּלִי שָׁוֶה וְהוּא שָׁלֵם, וְכַמָּה שָׁוֶה עַתָּה, וּמְשַׁלֵּם הַפְּחָת לַנִּזָּק עִם הַנְּבֵלָה אוֹ הַכְּלִי הַשָּׁבוּר, כְּדֶרֶךְ שֶׁנִּתְבָּאֵר בְּשׁוֹרוֹ שֶׁהִזִּיק, בְּסִימָן ת\"ג.",["\u0003שמין למזיק בידו כו'. \u0004 פי' אע\"פ שהזיק והרג ראובן \"בידו לבהמת שמעון או שבר כליו לא אמרינן דראובן יקח לעצמו הנבילה או שברי הכלי וישלם לשמעון בהמה או כלי חדש כמ\"ש לעיל בדין גניב' וגזילה דשם דוקא גזירת הכתוב דכתיב בגזילה כאשר גזל ובגניבה כתיב חיים שנים ישלם וכנ\"ל אבל במזיק אין הדין כן אלא אפילו הזיקו בידו דינו כאלו הרג שור ראובן לשור שמעון דכתיב ביה והמת יהיה לו פי' לניזק ומשלם לו במועד המותר דמי שוויו דניזק:"],["\u0003 שמין למזיק כו' \u0004 כלומר אע\"ג דאין שמין לגנב וגזלן לעיל סי' שנ\"ה ס\"ה למזיק שמין וע\"ל ס\"ס צ\"ה כתבתי דנראה דהיינו כשאין אפשר לתקן הכלי אבל אם אפשר לתקנו מחויב המזיק לתקנו ע\"ש:"]],["\u0003הלכות מאבד ממון חבירו בידים ומוסר ומלשין\u0004\nהַמַּזִּיק \u0010y0\u0011 מָמוֹן \u0010c0\u0011 חֲבֵרוֹ וְאֵינוֹ יוֹדֵע מַה הִזִּיק, נִשְׁבָּע הַנִּזָּק וְנוֹטֵל. כֵּיצַד, לָקַח כִּיס \u0010c1\u0011 חֲבֵרוֹ וְהִשְׁלִיכוֹ לַמַּיִם אוֹ לָאֵשׁ אוֹ שֶׁמְּסָרוֹ לְיַד אַנָּס, וְאָבַד, בַּעַל הַכִּיס אוֹמֵר: זְהוּבִים הָיָה מָלֵא, וְהַמַּזִּיק אוֹמֵר: אֵינִי יוֹדֵעַ מֶה הָיָה בּוֹ, שֶׁמָּא עָפָר אוֹ תֶּבֶן הָיָה מָלֵא, הֲרֵי הַנִּזָּק נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל. וְהוּא שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶם \u0010c2\u0011 אוֹ אָמוּד לְהַפְקִידָם אֶצְלוֹ וְדַרְכָּן לְהַנִּיחָם בְּכִיס וְכַיּוֹצֵא בּוֹ. \u0010y1\u0011 \u0005אַרְנָקִי בְּשַׂק, אִם הוּא שַׁבָּת וְיו\"ט, מִקְרֵי דַּרְכּוֹ בְכָךְ, וְכָל כַּיּוֹצֵא בְזֶה (מָרְדְּכַי פֶּרֶק הַכּוֹנֵס)\u0006. \u0010y2\u0011 אֲבָל אִם אֵין דַּרְכָּם לְהַנִּיחָם בִּכְלִי זֶה, \u0010c3\u0011 הוּא פָּשַׁע בְּעַצְמוֹ \u0005וּפָטוּר הַמַּזִּיק.\u0006 כֵּיצַד, \u0010c4\u0011 הֲרֵי שֶׁחָטַף חֵמֶת אוֹ סַל מְלֵאִים וּמְחֻפִּים וְהִשְׁלִיכָם לַיָּם אוֹ שְׂרָפָם, וְטָעַן הַנִּזָּק שֶׁמַּרְגָּלִיּוֹת הָיוּ בְּתוֹכָהּ, \u0010c5\u0011 אֵינוֹ נֶאֱמָן. \u0005וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ הָיוּ עֵדִים שֶׁהָיוּ שָׁם, פָּטוּר, הוֹאִיל וּפָשַׁע, כְּמוֹ שֶׁנִּתְבָּאֵר (הַמַּגִּיד פ\"ז דְּחוֹבֵל בְּשֵׁם תוס' וע\"ל ס\"ק ו')\u0006. \u0010c6\u0011 וְאִם תָּפַס, אֵין מוֹצִיאִין מִיָּדוֹ. \u0010c7\u0011 \u0005וְיֵשׁ חוֹלְקִין (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְיִשָּׁבַע שֶׁמַּרְגָּלִיּוֹת הָיָה בְּתוֹכוֹ, וְנוֹטֵל מַה שֶּׁיֵּשׁ אֶצְלוֹ, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010c8\u0011 וְאִם יָדַע הַמַּזִּיק שֶׁהַכִּיס הָיָה בּוֹ זְהוּבִים, אֲבָל אֵינוֹ יוֹדֵעַ כַּמָּה הָיוּ, אִם הַנִּזָּק אוֹמֵר: אֶלֶף, נוֹטֵל אֶלֶף בְּלֹא שְׁבוּעָה, וְהוּא שֶׁיִּהְיֶה אָמוּד, שֶׁהֲרֵי הַמַּזִּיק מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל \u0010c9\u0011 לִשָּׁבַע. \u0005וְיֵשׁ אוֹמְרִים דְּנִשְׁבַּע הַנִּזָּק וְנוֹטֵל, וְכֵן עִקָּר (טוּר סִימָן צ' בְּשֵׁם הָרַאֲבַ\"ד וְהַמַּגִּיד פֶּרֶק הַנַּ\"ל וְהָרֹא\"שׁ)\u0006. \u0010c10\u0011\nהַמּוֹסֵר מָמוֹן בִּידֵי אַנָּס, בֵּין אַנָּס גּוֹי בֵּין אַנָּס יִשְׂרָאֵל, חַיָּב לְשַׁלֵּם \u0010y3\u0011 \u0010c11\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו כָּל מַה שֶּׁלָּקַח הָאַנָּס, אַף עַל פִּי שֶׁלֹּא נָשָׂא הַמּוֹסֵר, וְלֹא נָתַן בְּיָדוֹ \u0010y4\u0011 \u0010c12\u0011 אֶלָּא הִרְגִּיל בִּלְבַד. \u0010c13\u0011 וְאִם מֵת, גּוֹבִים מִיּוֹרְשָׁיו כִּשְׁאָר כָּל הַמַּזִּיקִים. \u0010c14\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּדַוְקָא שֶׁעָמַד בַּדִּין; אֲבָל אִם לֹא עָמַד בַּדִּין, אֵין הַיּוֹרְשִׁין חַיָּבִין לְשַׁלֵּם. וְאִשָּׁה שֶׁמָּסְרָה, מְשַׁמְּתִינָן לָהּ. וְאִם יֵשׁ לָהּ מָמוֹן שֶׁאֵין לַבַּעַל רְשׁוּת בּוֹ, מְשַׁלֶּמֶת. וְאִם יֵשׁ לָהּ נִכְסֵי מְלוֹג, \u0010y5\u0011 \u0010c15\u0011 הַבַּעַל אוֹכֵל פֵּרוֹת כָּל יְמֵי חַיֶּיהָ, וְאִם מֵתָה חַיָּב לְשַׁלֵּם לַנִּמְסָר, וְכֵן לִשְׁאָר \u0010c16\u0011 נִזָּק, וְאֵין הַבַּעַל \u0010y6\u0011 לְעִנְיַן זֶה רַק כְּיוֹרֵשׁ שֶׁחַיָּב לְשַׁלֵּם (מָרְדְּכַי פֶּרֶק הַחוֹבֵל)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהֶרְאָה הַמּוֹסֵר מֵעַצְמוֹ. אֲבָל אִם אֲנָסוּהוּ גּוֹיִים אוֹ יִשְׂרָאֵל אַנָּס לְהַרְאוֹת, וְהֶרְאָה, הֲרֵי זֶה פָּטוּר מִתַּשְׁלוּמִין. \u0005וְאִם אָנְסוֹ לְהַרְאוֹת שֶׁלּוֹ \u0010y7\u0011 \u0010c17\u0011 וְהֶרְאָה [שֶׁלּוֹ וְ] שֶׁל חֲבֵרוֹ, חַיָּב (טוּר ס\"א)\u0006. וְאִם נָשָׂא וְנָתַן בְּיָד, אַף עַל פִּי שֶׁהוּא אָנוּס, חַיָּב לְשַׁלֵּם, שֶׁהַמַּצִּיל עַצְמוֹ בְּמָמוֹן \u0010y8\u0011 \u0010c18\u0011 חֲבֵרוֹ חַיָּב. כֵּיצַד, \u0010c19\u0011 הֲרֵי שֶׁגָּזַר הַמֶּלֶךְ לְהָבִיא לוֹ יַיִן אוֹ תֶבֶן וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, וְעָמַד מוֹסֵר וְאָמַר: הֲרֵי יֵשׁ לִפְלוֹנִי אוֹצַר יַיִן אוֹ תֶבֶן בְּמָקוֹם פְּלוֹנִי, וְהָלְכוּ וּלְקָחוּהוּ, חַיָּב לְשַׁלֵּם. \u0005הַגָּה: \u0010c20\u0011 וַאֲפִלּוּ יִסְּרוּהוּ, וְלֹא אָמְרוּ לוֹ עַל מָה, וְהֶרְאָה מָמוֹן חֲבֵרוֹ, חַיָּב (טוּר שָׁם)\u0006 ; וְלֹא מִקְרֵי אוֹנֶס, אֶלָּא הַכָּאוֹת וְיִסּוּרִין, \u0010c21\u0011 אֲבָל לֹא אֹנֶס מָמוֹן \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא וּתְשׁוּבַת מַיְמוֹנִי דִנְזִיקִין סי\"ב וְנ\"י)\u0006. \u0010y9\u0011 הָיָה רוֹאֶה נֶזֶק בָּא עָלָיו, מֻתָּר לְהַצִּיל עַצְמוֹ אַף עַל פִּי שֶׁעַל יְדֵי זֶה בָּא הַנֶּזֶק לְאַחֵר \u0010y10\u0011 \u0010c22\u0011 \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַשֻּׁתָּפִין)\u0006.\nאֲנָסוֹ הַמֶּלֶךְ לְמוֹסֵר זֶה עַד שֶׁיַּרְאֶה לוֹ מָמוֹן חֲבֵרוֹ שֶׁהוּא בּוֹרֵחַ מִלְּפָנָיו, \u0010y11\u0011 וְהֶרְאָה לוֹ מִפְּנֵי הָאֹנֶס, הֲרֵי זֶה פָּטוּר, שֶׁאִם לֹא יַרְאֶה לוֹ יַכֵּהוּ אוֹ יְמִיתֵהוּ. \u0010c23\u0011\nנָשָׂא מָמוֹן חֲבֵרוֹ בְּיָדוֹ וּנְתָנוֹ לָאַנָּס, חַיָּב לְשַׁלֵּם \u0010y12\u0011 מִכָּל מָקוֹם, אַף עַל פִּי שֶׁהַמֶּלֶךְ אֲנָסוֹ לְהָבִיא. \u0005ב' שֻׁתָּפִים שֶׁהָיָה לָהֶן חוֹב בְּיַחַד, וְאָנַס שַׂר לְאֶחָד לִפְטֹר הַחוֹב, פָּטוּר, \u0010y13\u0011 \u0010c24\u0011 דְּזֶה לֹא מִקְרֵי נָתַן בְּיָד (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאִם אֲנָסוֹ לְהָבִיא וְהֵבִיא חַיָּב, כְּשֶׁלֹא הִגִּיעַ הַמָּמוֹן לִרְשׁוּת הָאַנָּס; אֲבָל אַנָּס שֶׁאָנַס אֶת יִשְׂרָאֵל עַד שֶׁהֶרְאָהוּ, וְעָמַד הָאֲנָס עַל הַמָּמוֹן וְנַעֲשָׂה בִּרְשׁוּתוֹ \u0005דְּהַיְנוּ שֶׁיּוּכַל לִשְׁלֹט עָלָיו וְלִטְּלוֹ (הַמַּגִּיד פ\"ח דְּחוֹבֵל)\u0006, וְאָנַס אֶת יִשְׂרָאֵל עַד שֶׁהוֹלִיכוּ לְמָקוֹם אַחֵר, וַאֲפִלּוּ הוֹלִיכוֹ זֶה הַמּוֹסֵר שֶׁהֶרְאָהוּ, הֲרֵי זֶה פָּטוּר, \u0010y14\u0011 שֶׁכֵּיוָן שֶׁעָמַד הָאַנָּס בְּצַד הָאוֹצָר כְּבָר אָבַד כָּל מַה שֶּׁיֵּשׁ בּוֹ, וּכְאִלּוּ נִשְׂרַף:\nבַּעֲלֵי דִין שֶׁהָיְתָה בֵינֵיהֶם מְרִיבָה עַל הַקַּרְקַע אוֹ עַל מִטַּלְטְלִין, זֶה אוֹמֵר: שֶׁלִּי, וְזֶה אוֹמֵר: שֶׁלִּי, עָמַד אֶחָד מֵהֶם \u0010y15\u0011 וּמְסָרָהּ בְּיַד גּוֹיִים, מְנַדִּין אוֹתוֹ עַד שֶׁיַּחֲזִיר הַדָּבָר לִכְמוֹת שֶׁהָיָה, וִיסַלֵּק יַד אַנָּס מִבֵּינֵיהֶם וְיַעֲשׂוּ דִּין בְּיִשְׂרָאֵל. \u0005הַגָּה: \u0010c25\u0011 מִכָּל מָקוֹם אֵין לוֹ דִּין מוֹסֵר, אַף עַל פִּי שֶׁהִפְסִיד חֲבֵרוֹ עַל יְדֵי זֶה הַרְבֵּה, דְּלָא מִקְרֵי מוֹסֵר אֶלָּא בְּמִתְכַּוֵּן לְהַזִּיק, אֲבָל לֹא בְּמִתְכַּוֵּן לְהוֹצִיא אֶת שֶׁלּוֹ (תְּשׁוּבַת מיי' דִּנְזִיקִין סִימָן כ\"א וּמָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא בְּשֵׁם ר\"א)\u0006. וְיֵשׁ חוֹלְקִין \u0010y16\u0011 וּסְבִירָא לְהוּ דְּמִקְּרֵי מוֹסֵר וְחַיָּב לְשַׁלֵּם לוֹ כָּל הֶזֵּקוֹ, אִם לֹא הָיָה חֲבֵרוֹ סַרְבָן; וְכָל שֶׁכֵּן אִם הִתְרוּ בּוֹ תְּחִלָּה שֶׁלֹּא יִדּוֹנוּ בִּפְנֵי גּוֹיִם, וְעָבַר, שֶׁיֵּשׁ לוֹ דִין מוֹסֵר \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל קַמָּא בְּשֵׁם מַהֲרַ\"ם וּפֶרֶק הַמַּנִיחַ וּתְשׁוּבַת הָרֹא\"שׁ כְּלָל י\"ז סִימָן ד' וּמַהֲרִי\"ק שֹׁרֶשׁ קנ\"ד וקס\"א)\u0006. \u0010c26\u0011\nמִי שֶׁנִּתְפַּס עַל חֲבֵרוֹ, וְלָקְחוּ גוֹיִים מָמוֹן מִמֶּנּוּ בִּגְלַל \u0010y17\u0011 חֲבֵרוֹ, אֵין חֲבֵרוֹ חַיָּב לְשַׁלֵּם. אֵין לְךָ מִי שֶׁנִּתְפַּס עַל חֲבֵרוֹ וְיִהְיֶה חֲבֵרוֹ חַיָּב לְשַׁלֵּם לוֹ, חוּץ מֵהַנִּתְפַּס \u0010y18\u0011 מִפְּנֵי הַמַּס הַקָּצוּב עַל כָּל אִישׁ וְאִישׁ בְּכָל שָׁנָה, אוֹ הַנִּתְפַּס עַל הַתְּשׁוּרָה שֶׁנּוֹתֵן כָּל אִישׁ לַמֶּלֶךְ בְּעָבְרוֹ עֲלֵיהֶם אוֹ חַיָּלוֹתָיו, הֲרֵי זֶה חַיָּב לְשַׁלֵּם לוֹ; וְהוּא שֶׁיִּקְּחוּ מִמֶּנּוּ בְּפֵרוּשׁ בִּגְלַל פְּלוֹנִי, בִּפְנֵי עֵדִים; וְנִתְבָּאֵר עוֹד בְּסִימָן קכ\"ח. \u0010y19\u0011 \u0010c27\u0011\nמִי שֶׁיֵּשׁ עָלָיו עֵדִים שֶׁמָּסַר מָמוֹן חֲבֵרוֹ, כְּגוֹן שֶׁהֶרְאָה מֵעַצְמוֹ \u0010c28\u0011 אוֹ שֶׁנֶּאֱנַס \u0010c29\u0011 וְנָשָׂא וְנָתַן, וְלֹא יָדְעוּ הָעֵדִים כַּמָּה הִפְסִידוֹ בִּמְסִירָתוֹ, וְהַנִּמְסָר אוֹמֵר: כָּךְ וְכָךְ הִפְסִידָנִי, \u0010c30\u0011 וְהַמּוֹסֵר כּוֹפֵר בַּמֶּה שֶׁטָּעֲנוֹ, \u0010y20\u0011 \u0010c31\u0011 אִם תָּפַס הַנִּמְסַר אֵין מוֹצִיאִין מִיָּדוֹ, אֶלָּא נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְזוֹכֶה בַּמֶּה שֶׁתָּפַס. \u0010c32\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּבִסְפֵיקָא דְדִינָא לָא מְהַנֵּי תְּפִיסָה (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006 \u0005(וע\"ל ס\"ק ל\"ב)\u0006. וְאִם לֹא תָּפַס, אֵין מוֹצִיאִין מִן הַמּוֹסֵר אֶלָּא \u0010c33\u0011 בִּרְאָיָה בְּרוּרָה. \u0005וְאִם [לֹא] יָדְעוּ בֵּרוּר הַדְּבָרִים, \u0010y21\u0011 \u0010c34\u0011 רַק שֶׁהֻצְרַךְ לְהִתְפַּשֵּׁר עִם הַשַּׂר בְּכָךְ וְכָךְ, הַנִּמְסַר נִשְׁבָּע וְנוֹטֵל. (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006 \u0010c35\u0011 וְיֵשׁ \u0010c36\u0011 מִי שֶׁאוֹמֵר, שֶׁאִם הַמּוֹסֵר אוֹמֵר: \u0010c37\u0011 אֵינִי יוֹדֵעַ כַּמָּה הִפְסַדְתָּ עַל יָדִי, יִשָּׁבַע הַנִּמְסַר וְיִטֹּל. \u0005הַגָּה: (וע\"ל ס\"ק \u0010c38\u0011 ל\"ז)\u0006 וְכָל זֶה בְּמוֹסֵר מָמוֹן; אֲבָל מָסַר גּוּפוֹ שֶׁל חֲבֵרוֹ \u0005(לַאֲנָסִים)\u0006, הַנִּמְסַר נִשְׁבָּע וְנוֹטֵל. וְכֵן אִם גָּרַם לוֹ תְּפִיסָה, \u0010y22\u0011 דְּהָוֵי כְּמַזִּיק בְּיָדַיִם וְצָרִיךְ לְשַׁלֵּם לוֹ כָּל הֶזֵּקוֹ \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010y23\u0011 \u0010c39\u0011 הָאוֹמֵר לַחֲבֵרוֹ: מְסַרְתַּנִי, וְהוּא כּוֹפֵר, יִשָּׁבַע לוֹ הֶסֵּת \u0005(הַגָּהוֹת אֲשֵׁירִי)\u0006. וְיֵשׁ אוֹמְרִים דְּצָרִיךְ לִשָּׁבַע לוֹ לִפְנֵי הַשַּׂר שֶׁלֹּא מְסָרוֹ לוֹ \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010c40\u0011 וְאֵין צָרִיךְ לַעֲשׂוֹת נְקִיּוּת זוֹ, אֶלָּא עַל פִּי אֶחָד הַמֵּעִיד שֶׁמְּסָרוֹ, אֲבָל אֵין הַגּוֹיִים נֶאֱמָנִים בְּכָךְ \u0005(מָרְדְּכַי פֶּרֶק הַחוֹבֵל וּפֶרֶק הַפָּרָה וּפִסְקֵי מהרא\"י סִימָן פ\"ג וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן אֶלֶף \u0010c41\u0011 צ\"ח)\u0006. שְׁנַיִם שֶׁמָּסְרוּ בְּיַחַד, כָּל אֶחָד מְשַׁלֵּם הַחֵצִי, וְאִם בְּזֶה אַחַר זֶה, הָאַחֲרוֹן פָּטוּר, \u0010c42\u0011 דְּכָל זְמַן שֶׁלֹּא נִפְטַר מִמְּסִירָה הָרִאשׁוֹנָה הַנֶּזֶק בָּא מִגְּרַם הָרִאשׁוֹן \u0005(מָרְדְּכַי פֶּרֶק הַפָּרָה)\u0006. \u0010y24\u0011 \u0010c43\u0011 וַאֲפִלּוּ לֹא מְסָרוֹ, רַק רָאָה אַנָּס אוֹ גוֹיִים שֶׁיַּגִּידוּ לַשַּׂר \u0010c44\u0011 \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. יֵשׁ אוֹמְרִים דְּאָדָם הַמֻּכֶּה מֵחֲבֵרוֹ יָכוֹל לֵילֵךְ לִקְבֹּל לִפְנֵי גוֹיִים, אַף עַל פִּי דְגוֹרֵם לַמַּכֶּה הֶזֵּק גָּדוֹל \u0005(מָרְדְּכַי הַנַּ\"ל ומהרי\"ו סִימָן כ\"ח וּתְשׁוּבַת מַיְמוֹנִי דִנְזִיקִין סִימָן ס\"ו וּמַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006.\nאֵין מַשְׁבִּיעִין אֶת הַמּוֹסֵר שֶׁהֶרְאָה מֵעַצְמוֹ, לֹא שְׁבוּעָה חֲמוּרָה וְלֹא שְׁבוּעַת הֶסֵת, מִפְּנֵי שֶׁהוּא רָשָׁע וְאֵין לְךָ פָּסוּל יוֹתֵר מִזֶּה. \u0010c45\u0011 \u0005וַאֲפִלּוּ לֹא מְסָרוֹ \u0010c46\u0011 עֲדַיִן, רַק שֶׁאוֹמֵר: אֵלֵךְ וְאֶמְסֹר, אִם אוֹמֵר כָּךְ בְּפַרְהֶסְיָא \u0010c47\u0011 נִפְסָל לְעֵדוּת, וְלֹא אַמְרִינָן בִּכְהַאי גַוְנָא עָבִיד אִינַשׁ דְּגָזִים וְלֹא עָבִיד (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. וְיֵשׁ חוֹלְקִין אֶלָּא אִם כֵּן מֻחְזָק בְּכָךְ \u0005(מָרְדְּכַי שָׁם בְּפ' הַנִּשְׁבָּעִין)\u0006. וַאֲפִלּוּ לֹא יוֹדְעִין \u0010c48\u0011 אִם רָגִיל בְּכָךְ אוֹ לֹא, מִכָּל מָקוֹם יוּכַל זֶה שֶׁכְּנֶגְדּוֹ לַעֲמֹד וּלְהַצִיל עַצְמוֹ עַל יְדֵי גוֹיִים, אַף עַל פִּי שֶׁיַּגִּיעַ נֶזֶק לָזֶה \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן קפ\"א וְהָרֹא\"שׁ כְּלָל ט\"ז)\u0006. אֲבָל הַמּוֹסֵר \u0010y25\u0011 \u0010c49\u0011 שֶׁאֲנָסוּהוּ לְהַרְאוֹת אוֹ לְהָבִיא, וְנָתַן וְנָשָׂא בְיַד, אַף עַל פִּי שֶׁהוּא חַיָּב לְשַׁלֵּם, אֵינוֹ רָשָׁע, וּבֶן תַּשְׁלוּמִין הוּא בִּלְבַד, \u0005(וּמַשְׁבִּיעִין אוֹתוֹ)\u0006 כִּשְׁאָר הַכְּשֵׁרִים. \u0005הַגָּה: וְכֵן אִם הוֹדָה שֶׁמָּסַר, וְאֵין עֵדִים בַּדָּבָר, אַף עַל פִּי שֶׁאֵינוֹ נִפְסָל בְּהוֹדָאַת עַצְמוֹ, \u0010c50\u0011 מִכָּל מָקוֹם חַיָּב לְשַׁלֵּם (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006.\nאָסוּר לִמְסֹר לְיִשְׂרָאֵל בְּיַד גּוֹיִים, בֵּין בְּגוּפוֹ בֵין בְּמָמוֹנוֹ; וַאֲפִלּוּ הָיָה רָשָׁע וּבַעַל \u0010y26\u0011 עֲבֵרוֹת; וַאֲפִלּוּ הָיָה מֵצֵר לוֹ וּמְצַעֲרוֹ. \u0005הַגָּה: וְדַוְקָא בִּדְבָרִים בְּעָלְמָא; אֲבָל אִם מְסָרוֹ, מֻתָּר לְמָסְרוֹ, דְּהֲרֵי יוּכַל לְהָרְגוֹ בַדִּין \u0010c51\u0011 בְּמָקוֹם שֶׁיֵּשׁ חֲשָׁשׁ שֶׁיַּחֲזֹר וְיִמְסְרֶנּוּ (הָרֹא\"שׁ כְּלָל י\"ו סִימָן א' וב' וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן קפ\"א)\u0006 ; אוֹ אִם אִי אֶפְשָׁר לְהַצִּיל עַצְמוֹ בְּדֶרֶךְ אַחֵר; אֲבָל אִם אֶפְשָׁר לְהַצִּיל עַצְמוֹ בְּדֶרֶךְ אַחֵר, הָוֵי כִּשְׁנַיִם שֶׁמָּסְרוּ זֶה אֶת זֶה וְכָל מִי שֶׁהִפְסִיד חֲבֵרוֹ יוֹתֵר חַיָּב לְשַׁלֵּם הַמּוֹתָר בְּנֶזֶק שָׁלֵם \u0005(מָרְדְּכַי פֶּרֶק הַנַּ\"ל וּתְשׁוּבַת מַיְמוֹנִי הנ\"ל)\u0006. \u0010c52\u0011 וְכָל הַמּוֹסֵר יִשְׂרָאֵל בְּיַד גּוֹיִים, בֵּין בְּגוּפוֹ בֵּין בְּמָמוֹנוֹ, אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. \u0010y27\u0011\nמֻתָּר לַהֲרֹג הַמּוֹסֵר אֲפִלּוּ בַּזְּמַן הַזֶּה. \u0010c53\u0011 וּמֻתָּר לְהָרְגוֹ קֹדֶם שֶׁיִּמְסֹר, אֶלָּא כְּשֶׁאָמַר: הֲרֵינִי מוֹסֵר פְּלוֹנִי \u0010y28\u0011 בְּגוּפוֹ אוֹ בְּמָמוֹנוֹ, אֲפִלּוּ מָמוֹן קַל, הִתִּיר עַצְמוֹ לַמִּיתָה, וּמַתְרִין בּוֹ וְאוֹמְרִים לוֹ: אַל תִּמְסֹר, אִם הֵעִיז פָּנָיו וְאָמַר: לֹא כִּי אֶלָּא אֶמְסְרֶנּוּ, מִצְוָה לְהָרְגוֹ, וְכָל הַקֹּדֶם לְהָרְגוֹ, זָכָה. \u0005הַגָּה: וְאִם אֵין פְּנַאי לְהַתְרוֹת בּוֹ, אֵין צָרִיךְ הַתְרָאָה (הַמַּגִּיד פ\"ח דְּחוֹבֵל)\u0006. וְיֵשׁ אוֹמְרִים דְּאֵין לַהֲרֹג הַמּוֹסֵר אֶלָּא אִם כֵּן אִי אֶפְשָׁר לְהִנָּצֵל מִמֶּנּוּ בְּאֶחָד מֵאֵבָרָיו, אֲבָל אִם אֶפְשָׁר לְהַצִּיל בְּאֶחָד מֵאֵבָרָיו, כְּגוֹן לַחְתֹּךְ לְשׁוֹנוֹ אוֹ לְסַמּוֹת עֵינָיו, אָסוּר לְהָרְגוֹ, דַּהֲרֵי לֹא גָּרַע מִשְּׁאָר רוֹדֵף \u0005(תְּשׁוּבַת מַיְמוֹנִי הַנַּ\"ל וּמָרְדְּכַי הַנַּ\"ל בְּשֵׁם מהר\"מ)\u0006. \u0010c54\u0011\nעָשָׂה הַמּוֹסֵר אֲשֶׁר זָמַם, וּמָסַר, אָסוּר \u0010c55\u0011 לְהָרְגוֹ, אֶלָּא \u0010c56\u0011 \u0010c57\u0011 אִם כֵּן הֻחְזַק לִמְסֹר, שֶׁהֲרֵי זֶה יֵהָרֵג שֶׁמָּא יִמְסֹר אֲחֵרִים. \u0010c58\u0011\nכָּל הַמּוֹסֵר הַצִּבּוּר וּמְצַעֲרָן, מֻתָּר לְמָסְרוֹ בְּיַד גּוֹיִים לְהַכּוֹתוֹ וּלְאָסְרוֹ וּלְקָנְסוֹ; אֲבָל \u0010y29\u0011 \u0010c59\u0011 מִפְּנֵי צַעַר יָחִיד אָסוּר לְמָסְרוֹ. \u0005הַגָּה: (וְע\"ל סִימָן תכ\"ה ס\"א)\u0006. מִי שֶׁעוֹסֵק בְּזִיּוּפִים וְכַדּוֹמֶה, וְיֵשׁ לָחוּשׁ שֶׁיַּזִּיק רַבִּים, מַתְרִין בּוֹ שֶׁלֹּא יַעֲשֶׂה, וְאִם אֵינוֹ מַשְׁגִּיחַ, יְכוֹלִין לְמָסְרוֹ וְלוֹמַר שֶׁאֵין אַחֵר מִתְעַסֵּק בּוֹ אֶלָּא זֶה לְבַד. מִי שֶׁרוֹצֶה לִבְרֹחַ וְלֹא לְשַׁלֵּם לַגּוֹי מַה שֶּׁחַיָּב, וְאַחֵר גִּלָּה הַדָּבָר, אֵין לוֹ דִּין מוֹסֵר, שֶׁהֲרֵי לֹא הִפְסִידוֹ רַק שֶׁהֻצְרַךְ לְשַׁלֵּם מַה שֶּׁחַיָּב, מִכָּל מָקוֹם בְּרָעָה עָשָׂה דְּהָוֵי כְּמֵשִׁיב \u0010y30\u0011 \u0010c60\u0011 אֲבֵדָה לְגוֹי; וְאִם גָּרַם לוֹ הֶזֵּק, חַיָּב לְשַׁלֵּם לוֹ מַה שֶּׁגָּרַם לוֹ \u0005(מַהֲרַ\"ם \u0010c61\u0011 מֵרִיזְבּוּרְק)\u0006.\nאָסוּר לְאַבֵּד מָמוֹנוֹ שֶׁל מוֹסֵר אַף עַל פִּי שֶׁמֻּתָּר לְאַבֵּד גּוּפוֹ, \u0010y31\u0011 שֶׁהֲרֵי מָמוֹנוֹ רָאוּי לְיוֹרְשָׁיו. \u0005(וע\"ל סי' ק\"ח ס\"ב)\u0006 \u0010y32\u0011 \u0010c62\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּמֻתָּר לִטֹּל מָמוֹנוֹ לְעַצְמוֹ, דְּאֵינוֹ אָסוּר אֶלָּא לְאַבְּדוֹ\u0006 \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006.\nמוֹסֵר, \u0010y33\u0011 מְקַבְּלִים עֵדוּת שֶׁלֹּא בְפָנָיו. \u0005הַגָּה: \u0010c63\u0011 וְאֵין צְרִיכִין לְכַוֵּן הָעֵדוּת כָּל כָּךְ (טוּר)\u0006.\nמִי שֶׁמֻחְזָק שֶׁשְּׁלֹשָׁה פְעָמִים מָסַר יִשְׂרָאֵל אוֹ מָמוֹנָם בְּיַד גּוֹיִים, הָיוּ מְבַקְּשִׁים עֵצָה וְתַחְבּוּלָה \u0010y34\u0011 לְבַעֲרוֹ מֵהָעוֹלָם, \u0005הַגָּה: \u0010c64\u0011 עַל יְדֵי גְרָמָא, \u0010c65\u0011 אַף עַל פִּי שֶׁאָסוּר לְהָרְגוֹ (בְּיָדַיִם)\u0006. מִי שֶׁמְּדַבֵּר בִּפְנֵי קָהָל וְעֵדָה דִבְרֵי מְסִירוּת, וְעַל יְדֵי זֶה נִשְׁמַע לַשַּׂר וְגָרַם הֶזֵּק, אַף עַל פִּי שֶׁאֵין לוֹ דִּין מָסוֹר מִכָּל מָקוֹם מַעֲנִישִׁין אוֹתוֹ לְפִי רְאוֹת עֵינֵי הַדַּיָּנִים \u0005(רִיבָ\"שׁ סִימָן רל\"ט וּתְשׁוּבַת רַמְבַּ\"ן סִימָן ר\"מ)\u0006. מִי שֶׁשָּׁלַח שָׁלִיחַ \u0010c66\u0011 לִמְסֹר, אִם הַשָּׁלִיחַ הֻחְזַק לַעֲשׂוֹת, חַיָּב הַמְשַׁלְּחוֹ, וְאֵין לוֹמַר אֵין שָׁלִיחַ לִדְבַר עֲבֵרָה, הוֹאִיל וְהֻחְזַק בְּכָךְ. \u0010y35\u0011 \u0010c67\u0011 \u0010c68\u0011 \u0010c69\u0011 \u0010c70\u0011 \u0010c71\u0011 \u0010c72\u0011 \u0010c73\u0011 \u0010c74\u0011 וְכֵן אִם מָסַר שְׁטָר פָּרוּעַ לְגוֹי, וְיוֹדֵעַ שֶׁיִּתְּנוֹ לַשַּׂר וְיָכֹף הַיִּשְׂרָאֵל לִפְרֹעַ שֵׁנִית, חַיָּב לְשַׁלֵּם \u0005(בֵּית יוֹסֵף בְּשֵׁם רשב\"ץ וּמַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006.\nהוֹצָאוֹת שֶׁעָשׂוּ לְבַעֵר מוֹסֵר, כָּל הַדָּרִים בָּעִיר חַיָּבִים לִפְרֹעַ בָּהֶם, אֲפִלּוּ אוֹתָם שֶׁפּוֹרְעִים מַס בְּמָקוֹם אַחֵר:",["\u0003ממון חבירו כו'. \u0004 לשון הטור כמו שהנגזל נשבע ונוטל כו' ועיין בסי' צ' סי\"ו ובדברי המחב' שם שכ' שם ג\"כ שהניזק נשבע ונוטל:","\u0003ארנקי בשק כו'. \u0004 נראה דצ\"ל הג\"ה זו מקומה כאן שכ' וכיוצא בזה כו' ודלא כמ\"ש בס\"י ודו\"ק:","\u0003אבל אם אין דרכם להניח בכלי זה כו'. \u0004 בגמ' הוא איבעי' דלא איפשט' ז\"ל מי מנחי מעות בכלי כזה או לא ופירשו הרמב\"ם והטור והמחבר דאפי' אי ודאי אין דרך אדם להניח שם מבעיא ליה אי אזלינן בתר דרך בני אדם ופטור וה\"ק מי מנחי בתמיה וכיון דאין דרך להניח שם והיה הסל מחופה פי' מכוסה דלא ראוהו פטור דלא עלתה על דעת המזיק שיש שם מעות או נימ' דנאמן הניזק בשבועה שהניח שם מעות וחייב המזיק משום דמאי הוה לזה להכלי להשליכו במים ופסק הרמב\"ם בזה דהמע\"ה ואם תפס אין מוציאין מידו וכמ\"ש המחב' והרא\"ש ס\"ל כיון דספיק' דדינא הוא לא מהני ביה תפיסה והו' דעת החולקים דכ' מוהר\"ם בסמוך דין מוסר:","\u0003מהיפה שבנכסיו. \u0004 בטור כתב כדין מזיק וכ\"כ בסימן שפ\"ה דהיינו דוקא כשמשלם מקרקעות אבל כשמשלם ממטלטלים אפי' בסובין הרשות בידו:","\u0003אלא הרגיל בלבד \u0004 פי' דיבר לאנס דממונו של זה במקום פלוני הוא:","\u0003הבעל אוכל פירות כל ימי חייה. \u0004 נ\"ע מ\"ש מחבלה באחרים דכ' הטור ומור\"ם לקמן בס\"ס תכ\"ד וכתבו ג\"כ המחב' בחבלה בבעלה דצריכ' למוכרן בטובת הנאה ולשלם ממנו דמי החבלה ואפשר דבמסירה דלא הזיקה בידים הקילו דשם קנס עליו גם מה\"ט במת קודם שעמד בדין אמרי' בסמוך דאין היורשים חייבים לשלם בעדו אבל במידי דאינו קנס כגון הלואה ושאלה וגניבה וחבלה ונשאת מוכח ל' סי' תכ\"ד דאם יש לה בכ\"מ או נצ\"ב או תוספת כתובה על כתובה דאורייתא דמחוייב' היא למכר' בטובת הנאה ולשלמם וכן כתבתי ל' בס\"ס שמ\"ו ע\"ש ובדרישה שם הארכתי ומ\"ש \"המרדכי דהא דאמרו דנשים ועבדים שחבלו באחרים פגיעתן רעה דעכ\"פ משמתינן ומלקינן אותן דאל\"כ כל אשה ועבד יחבלו ויסמכו על זה כו' ע\"ש אפשר דלא כ\"כ כ\"א כשלית לה נ\"מ:","\u0003לענין זה רק כיורש. \u0004 פי' אע\"ג דבעלמא הבעל מחשב כלוקח ראשון ה\"מ גבי לקוחות דאינהו אפסידו אנפשיהו דלא ה\"ל ללקח' מידה כיון דידעו שיש לה בעל משא\"כ בזה דאיהי גרמה להן היזק זה:","\u0003ה\"ג והראה לו שלו ושל חבירו חייב \u0004 כ\"כ בטור בסי' זה ובסי' שע\"ה ס\"ה ע\"ש:","\u0003כיצד הרי שגזר המלך להביא לו יין כו' \u0004 האי כיצד לאו אדסמיך לי' קאי אלא אמ\"ש לפניו וללמדינו דבכה\"ג אף שלא נשא ונתן ביד כיון שמסרו בלא אונס יסורין חייב לשלם לו הזיקו ושם ברמב\"ם כתב אחר זה ז\"ל אנסו המלך למוסר זה עד שיראה לו אוצרות יין או תבן או עד שיראה לו ממון חבירו שהוא בורח מלפניו כו' והמחבר תפס סוף דברי הרמב\"ם כמ\"ש בסעיף שאחר זה ז\"ל אנסו המלך כו' וממ\"ש ריש דברי הרמב\"ם נלמד דל\"ד קאמר דפטור כשאנסו להראות ממון חבירו \"שברח \"מלפניו אלא אורחא דמלתא נקט שאין דרך האנסין הוא לאנוס להראות לו ממון של אחרים סתם אם לא שיש לו טענה על א' מהן כגון \"שברח \"מלפניו שאז דרכו לפרטו בשמו ומאנס לו עד שיראה לו ממונו דאותו פלוני וק\"ל:","\u0003הי' רואה נזק בא עליו כו'. \u0004 שם בנ\"י סיים וכ' דאם כבר בא עליו אסור לסלקו ממנו בשגורם בזה היזק לחבירו:","\u0003אנסו המלך למוסר זה כו' \u0004 אבל אם אין לאותו איש ממון ואנס לזה שיראהו להאיש ורצונו לתופסו עד שיפדנו הקהל או קרוביו וזה הנאנס הי' יכול לפטור נפשו ג\"כ מהאנס מיסורים אם היה רוצה ליתן להאנס ממון כזה נראה דאסור לגרום היזק לקהל או יחידים קרוביו:","\u0003והראה לו מפני האונס ה\"ז פטור. \u0004 יש לדקדק מלשון הרמב\"ם והמחבר מדכתבו לשון \"פטור ולא כתבו \"דמותר להראותו כיון דנאנס ע\"ז די\"ל דלכתחל' לא יראהו אלא שאם הראהו פטור מהתשלומין:","\u0003אע\"ג שהמלך אנסו להביא ול\"ד למ\"ש בגמרא וכתבו הטור והמחבר בסי' רצ\"ב ס\"ח דהמפקיד אצל חבירו ממון אוכלים ואינו אמוד הנפקד ובאו עליו גנבים וקדם ונתן להם הפקדון להציל עצמו דכיון דאינו אמוד חזקה דלא באו אלא בשביל הפקדון ופטור וכ\"ש כאן דאנסוהו בהדיא ליתן לו ממון חבירו דשאני התם כיון דאינו אמוד מסתמא אונס' דמתיליד לי' לא הוי אלא בשביל הפקדון ואם לא הי' הפקדון אצלו לא הוו אתו עליה אבל כאן שמאנסין אותו שיביא ממון ראובן מבית ראובן ריע מזלו גרם לו זה דאל\"כ איך באים אצלו שיתן לו מעות ראובן שאינו בידו ולהכי נסתחפה שדהו וחייב אפי' אנסוהו גם על ההבאה כ\"כ ר\"ן אבל הראב\"ד השיג על הרמב\"ם גם בזה וכ' דאף שנשא ונתן ביד מ\"מ כיון שאנסוהו על ההבא' אין לך דבר שעומד בפני פקוח נפש והואיל ויחדו לו בפירוש אינו מחוייב שימות בשביל ממון חבירו וממילא ג\"כ נפטר מהתשלומין דאח\"כ ע\"ש שכ\"כ בשם גאון ועיין בנ\"י בהגוזל בתרא מ\"ש בדין זה וד\"מ הביאו ועד\"ר:\u0004","\u0003דזה לא מיקרי נתן ביד. \u0004 פי' אלא גרמא בעלמ' מ\"מ מסיק שם דאי עשה כן מדעתו בלא אונס חייב:","\u0003שכיון שעמד האנס כו'. \u0004 לשון הטור שעל מה שהראהו לו פטור כיון שהוא אנוס וגם לא עשה מעשה ועל מה שנטלו ונתנו לו אח\"כ פטור דכיון שראוהו האנס ויכול ליטלו חשיב כאלו נטלו ועד\"ר מ\"ש בד\"ה ואפי' בזה כתב א\"א הרא\"ש ז\"ל: הג\"ה וכתב מהר\"מ מריזיבורק ראובן לקח חפץ א' משמעון למוכרו לשר ואח\"כ החזירו לשמעון בפני עבד השר ואח\"כ לקח השר החפץ משמעון בחזקה בלא דמים ראובן חייב לשלם לשמעון דהיה לו לחזו' בינו לבין עצמו ולא מהני מה שאמר לא כוונתי להזיקך עכ\"ל ד\"מ ס\"ס זה:","\u0003ומסרה ביד אנס מנדין כו'. \u0004 ☜וכתב הריב\"ש סי' פ' באחד שביזה החכם ועמד החכם ונתן העונש שלו לשר העיר וכתב שם דהוי קרוב למסירה עכ\"ל ד\"מ ב':","\u0003דמיקרי מוסר וחייב לשלם כל הזיקו וכת' בתשוב' מיימוני ספר נזקין סי' י\"ד על אחד שרצה לתפוס את חבירו ולהכריחו למשפט ומתוך שלא רצה להניח לתפוס עצמו הכהו והרגו השופט ודן מהר\"ם על התובע דין רוצח וע\"ש סי' קי\"א בתשובת מהרי\"ו ד\"מ ד':\u0004","\u0003אין חבירו חייב לשלם \u0004 דריע מזלו גרם לו שיהא נתפס עבורו אף שנפטר חבירו ע\"י כך מחובו יכול לומר מפייסינא הוינא ליה עד דפטרני בלא דמים וכמ\"ש בריש סי' קכ\"ח:","\u0003מפני המס הקצוב \u0004 הטעם דחוק מלך ונימוסו הוא כן להיות נתפס אחד על חבירו כי אין עליו לטרוח לגבות מכל אחד בפני עצמו וכמ\"ש בסי' קכ\"ח ושס\"ט בטור ובדברי המחבר:","\u0003מי שיש עליו עדים כו'. \u0004 אבל אם אין עליו עדים ישבע לו היסת שלא מסרו כ\"כ הג\"א ד\"מ סי' צ' סי\"ד:","\u0003אם תפס הנמסר כו'. \u0004 דאיבעיא דלא איפשטא הוא בגמרא אי עשו תקנה בנמסר להיות נאמן בשבועתו ליטול כמו שתקנו בנגזל ולא איפשט' וס\"ל להרמב\"ם דמהני ביה תפיסה ור\"י והרא\"ש ס\"ל דלא מהני כיון דהוא ספיקא דדינא ועד\"ר ר\"ס זה מ\"ש:","\u0003רק שהוצרך להתפשר \u0004 פי' שיש לנמסר עדים ע\"ז שהוצרך לפשר עם השר בכך וכך אף שהמוסר כופר ואומר לא בשביל המסירה לחוד פשרת עם השר ליתן לו כך וכך הנמסר נאמן בשבועה כיון דיש לו עדים עכ\"פ שהוצרך לפשר עם השר בכך וכך וגם ידוע שמסרו:","\u0003הוי כמזיק בידים כו' \u0004 וסיים שם אף שטוען שלא תפסוהו משום שהכהו אלא משום שברח אפי' הכי חייב:","\u0003האומר לחבירו מסרתני. \u0004 וכ' הרשב\"א בתשוב' סי' תקע\"ו מוסר שהודה במקצת משלם מה שהודה ואינו משלם השאר ואפי' אומר נ' ידענא ונ' לא ידענא לא אמרי' מתוך שאיל\"מ מאחר שלא ה\"ל למידע כמה הזיקו עכ\"ל ד\"מ ג':","\u0003ואפי' מסרו רק כו'. \u0004 ר\"ל אם ראה השר מעצמו או עכו\"ם ראוהו דאז מסתמא יגידו להשר מה שראו שעשה ראובן כגון שהכה לשמעון אף שהלך לוי והגיד לשר על ראובן פטור לוי דבלא הגדתו ודאי יודע להשר ע\"י העכו\"ם:","\u0003שאנסוהו להראות כו'. \u0004 פי' אף שנשא ונתן אח\"כ ביד (וכדמסיק) דאז חייב לשלם אפ\"ה אינו נקרא רשע כו' א\"נ ה\"ק ל\"מ אם לא אנסוהו אלא להראות והראהו ולא נשא ונתן ביד דאינו נקרא רשע דהרי בכה\"ג אפי' בר תשלומין ליכא אלא אפי' אנסוהו להביא והוצרך לישא וליתן באונס אף דבר תשלומין הוא כנ\"ל אפ\"ה אינו נקרא רשע כו':","\u0003ואפי' הי' מצר לו ומצער \u0004 בגמרא יליף לה מדאמר דוד אמרתי אשמרה דרכי מחטא בלשוני אשמרה לפי מחסום בעוד רשע לנגדי דר\"ל אף שרשע לנגדי ומצערני ועוד אמר דום לה' והתחולל לו כו' דר\"ל שידום ויסבול והשם יפילם לפניו חללים חללים:","\u0003מותר להרוג כו' \u0004 וכ' הריב\"ש סי' רל\"ו מי שנתפס בעד גופו לדון אותו מפני שהוא מוסר או שאמר דברים שמתחייב בנפשו ורוצה ליתן ערבות מספיקין שלא יברח אין מקבלין ממנו דמה יעשה לערבים אם יברח הוא עכ\"ל ד\"מ י\"ג:","\u0003בגופו או בממונו. \u0004 דמוסר אף דאינו מזיק ממון חבירו בידים גרע ממזיק וילפי' לה בגמרא מדכתיב בניך עלפו שכבו בראש כל חוצות כתוא מכמר מה תוא זה כשנפל למכמר שוב אין מרחמין עליו כן ממונם של ישראל כיון שנפל ליד עכו\"ם אין מרחמין עליו ומעלילין עליו עלילות כל כך עד שהרבה פעמים יבא ע\"י לידי סכנת נפשות מ\"ה יש להמוסר דין רודף מיהו לא גרע מרודף דאחר שעבר עבירה אין הורגין אותו בלא התראה ובדין ב\"ד דוקא כן המוסר אחר שמסר אם לא שהוחזק למסור וכדמסיק המחבר בסי' י\"א:","\u0003מפני צער יחיד אסור למסרו. \u0004 והיינו דוקא מפני צער דעלמא אבל אם מסרו בממון וכ\"ש אם יסרו במכות ועונשי הגוף מותר כמ\"ש בס\"ט בהג\"ה ועד\"מ ס\"ט וע' בטור בסי' תכ\"ה ס\"ב:","\u0003ואם גרם לו היזק. \u0004 נראה דר\"ל היזק יותר ממה שחייב להעכו\"ם אם בא לו ע\"י שגילה לעכו\"ם מבריחותו אבל בכדי מה שחייב לו אינו נקרא היזק:","\u0003שהרי ממונו ראוי ליורשיו. \u0004 פי' וכתיב יכין רשע וצדיק ילבש:","\u0003דמותר ליטול ממונו כו'. \u0004 דלא עדיף ממונו מגופי דהוא הפקר והרי עדיין לא זכו בניו בחייו בממונו:","\u0003מקבלין עדות שלא בפניו. \u0004 ל' תשובת הרא\"ש הביאו הטור בס\"ס זה ואף שלא בשעת מעשה כשדנין עליו להורגו ביד עכו\"ם א\"צ לקבל העדות בפניו כי הדבר ידוע מי שהוא מוחזק למוסר העכו\"ם מקרבין אותו בשביל הנאתן ואילו רצה לקבל העדות בפניו ולדרוש ולחקור בדינו לעולם לא יעשו לו דין כי ינצל ע\"י עכו\"ם כי אפי' כשאינו בסכנה מוסר יחידים ורבים כ\"ש כשיראה עצמו בסכנת גופו כו':","\u0003לבערו מהעולם \u0004 ע\"י גרמא אע\"פ שאסור להורגו. כ\"כ בתשובת הרא\"ש הביאו הטור בס\"ס זה בשם ר\"ח דשלא בשעת מעשה אע\"פ שהוחזק למסור אינו מותר אלא ע\"י גרמא והיינו שמורידין אותו לבור ושם ימות מעצמו ואם הוא כבר ירד בסולם לבור מעצמו מסלקין הסולם משם וכיוצא באלו. וכן מותר להשתדל מיתתו ע\"י עכו\"ם דהוה כמו הורדה לבור כו' ע\"ש ועפ\"ר ושם כתבתי דלדעת הרמב\"ם והר\"ר אשר מלוניל מותר להורגו אפי' בידים לאחר שהוחזק להיות מוסר ג\"פ ואפילו שלא בשעת מעשה ושמדברי הבעל העיטור מוכח דס\"ל כר\"ח הנ\"ל:","\u0003וכן אם מסר שטר פרוע כו'. ואפי' מסרו בין שאר שטרות ואמר דלא ידע מזה מ\"מ חייב דה\"ל למידע רשב\"ץ שם:\u0004"],["\u0003 ואינו יודע מה הזיק כו' \u0004 משמע הא אם המזיק יודע מה היזק ומכחישו אין הניזק נשבע ונוטל ועיין מ\"ש לקמן סימן תי\"ח סי\"ג עיין בתשו' מהרש\"ך ס\"ג סי' פ\"א:","\u0003 והשליכו למים כו'. \u0004 ל' המרדכי פ' הכונס ההוא גברא דבטש בכספתא כו' כ' רבינו אבי העזרי וז\"ל ש\"מ דכל מי שמפסיד לחברו בפשיעתו ויש לו עדים שאבד על ידו ממונו או בידו או ע\"י פשיעתו שישבע כמה הפסידו ויטול כו' ומהרש\"ל כ' שם בפ' הכונס סי' ל\"ב וז\"ל וראבי\"ה כ' אפי' מי שמפסיד ממון לחברו בפשיעתו כו' ולא נ\"ל דלא עשו תקנת נגזל אלא כעין נגזל במזיק בידים אבל בפשיעה דאינו מזיק בידים לא ולא עוד אלא אפי' במזיק בידים נ\"ל דלא עשו תקנת נגזל אלא דומיא דנגזל במזיד ובכונה אבל המזיק בידים בשוגג לא עשו תקנה גביה וכן יראה לי מדברי הרמב\"ם שכ' המזיק ממון כו' כיצד לקח כיס חבירו והשליכו למים כו' עכ\"ל ולי נראה כדברי ראבי\"ה ומזיק בפשיעתו דקאמר היינו מזיק במזיד בפשיעתו דהיינו דלא תימא דוקא משליכו בידים למים אלא אפילו זרקו לארץ ומכח זריקתו נתגלגל ונפל למים או שהי' ביד חברו ודחפו מיד חברו וממילא נפל למים וכה\"ג חייב והיינו דאמרינן בש\"ס ההוא גברא דבטש בכספתא דחבריה שדייה בנהר' כו' ומדלא קאמרי' בקצור ההוא גברא דשדייה כספתא דחבריה בנהרא משמע שהמעש' הי' שלא השליכו בידים לנהר רק דבטש ביה ומכח דחיפתו שדייה בנהר' ומ\"ש הרמב\"ם והשליכו למים נמי יש לפרש דבריו כן גם בהג\"ה מיי' סוף פ\"ז מה' חובל הבי' דברי ראבי\"ה הנ\"ל על דברי הרמב\"ם וע\"ש מיהו בהזיק בשוגג נראה כדברי מהרש\"ל ונראה דאף ראבי\"ה מודה בזה:","\u0003 או אמוד להפקידם. \u0004 וצריך לברר טענתו מי הפקידו אצלו כ\"כ מהרש\"ל שם:","\u0003 הוא פשע בעצמו כו'. \u0004 משמע לכאורה מלשון זה דהטעם הוא משום דלא ה\"ל למזיק לאסוקי אדעתי' שיש שם דברים אלו וכ\"כ בעיר שושן להדיא א\"כ קשה מ\"ש אח\"כ אינו נאמן וגם בס' לחם משנה הניח בצ\"ע וצ\"ל דה\"ק אינו נאמן וגם אינו מועיל שבועתו וכן משמע ברמב\"ם שמסיים ואין משביעין אותו על כך שאין דרך בני אדם כו' דאל\"כ הוא כפל ל' ומ\"ש אח\"כ ואם תפס כו' היינו משום שגם זה בכלל הבעי' דדלמא לא מיקרי פשיעה ומהני שבועתו אך מדברי הרב המ' שם נרא' שהבין שהרמב\"ם מודה דכשיש עדים חייב וכ\"כ מהרש\"ל פ' הכונס סי' ל\"ב להדיא לדעת הרמב\"ם וכן נראה מדברי הרב ממ\"ש וי\"א כו' וקשה לדבריהם דהא כ' הוא פשע בעצמו וצ\"ל לדבריהם דה\"ק פשע בעצמו שהרי העולם לא יאמינו לו שעשה כן:","\u0003 הרי שחטף חמת כו'. \u0004 ומהרש\"ל שם כ' דבכה\"ג פשיטא דאינו נאמן ולא מבעיא אלא בארגז שמניחי' בו כספים וטען שהי' בו מרגליות כמו שפירש\"י ע\"ש:","\u0003 אינו נאמן \u0004 משמע לכאורה הא אם יש עדים מה הי' בתוכו חייב וע\"כ כ' הרב וי\"א דאפי' היו עדים פטור:","מיהו הרב המגיד מסיק וז\"ל ומ\"מ אם יש עדים שאותו דבר שהוא טוען שהי' שם אע\"פ שאין דרך להניחה גובין מן המזיק ונותני' לנזקין [לניזק] בלא שבועה כך העלה הרשב\"א בזה שלא כדברי בעלה הלכות עכ\"ל ומביאו ב\"י (וביש ספרים איתא בה' המגיד שלא כדברי התוס' ונוסח' זו עיקר כי כן הוא באמת דעת התוס' ס\"פ הכונס וכן הגה' אשר\"י שם) ונראה מהרב המ' שגם דעת הרמב\"ם כן וכ\"כ מהרש\"ל פ' הכונס סי' ל\"ב שדעת הרמב\"ם כהרשב\"א וכ\"נ דעת הרא\"ש ס\"פ הכונס וכ\"נ דעת הטור וכן דעת ראבי\"ה בהג\"ה מיי' פ\"ז מה' חובל ובמרדכי פ' הכונס וכן נראה בשלט\"ג ס\"פ המפקיד דף פ\"ו ע\"ב וכ\"פ מהרש\"ל פ' הכונס סי' ל\"ב וכן נר' עיקר (וכן מוכח בירושלמי שהבאתי לקמן):","אלא שלא מצאתי בדבריהם ישוב ברור למה שהקשו התו' דא\"כ מה הוא אומר לאו היינו מתני' כו' וגם מהרש\"ל שם כתב אבל ר\"י פי' אפי' יש עדים שהי' בו מרגניתא כו' ולכאורה נראה כפי' ר\"י כי לפי פירוש הרשב\"א והרמב\"ם פשיט ליה רב אחא מתקנת נגזל באשו וזה לא הוזכר במשנה כו' מ\"מ נ\"ל כפירוש' דלפי' התוס' ה\"ל לסדר בעי' זו אחר מלתא דרבא הנותן דינר זהב לאשה כו' ולא כ' ישוב ע\"ז דפשיט ממתני' ונלפע\"ד דס\"ל להפשטן כהירוש' שהביא הרא\"ש ס\"פ הכונס דביש עדים לא פליגי ר' יודא ורבנן במתני' אלא פליגי באין עדים אי עשו תקנת נגזל ע\"ש א\"כ ע\"כ ומודים חכמים דקתני היינו כשהוא דרך להניח שם מודים דעשו תקנת נגזל ואפשר שזהו דאי' בש\"ס התם לר' יודא דמחייב על נזקי טמון באש עשו תקנת נגזל באשו שכתבו התוס' דלאו דוקא לר' יודא דלרבנן נמי הוי מצי למימר כן בדבר שדרכו ע\"ש וזה דוחק ולפמ\"ש נראה דדוקא נקט לר' יודא לאשמועי' דלר' יודא אף בטמון עשו תקנת נגזל אבל במבעיר בשל חבירו בדבר שדרכו לא אצטריך לאשמועי' דהיינו מתני' דמודים חכמים לר' יודא דעשו תקנת נגזל ודוק כי כל זה נ\"ל ברור (אחר זמן מצאתי כדברי בס' המלחמות להרמב\"ם ס\"פ הכונס ונהניתי):","\u0003 ואם תפס \u0004 אפי' בעדים:","\u0003 ויש חולקין \u0004 דתפיסה בעדים ל\"מ בספיקא דדינא אבל בלא עדים פשיטא דנאמן ודוק וכבר הארכתי בזה בספרי תקפו כהן ע\"ש:","\u0003 ואם ידע המזיק כו'. \u0004 עיין בספר א\"א דף ק\"ד וע\"ל סי' צ' ס\"י מ\"ש בזה עיין בתשובת מהרשד\"ם סי' קמג:","\u0003 ויש אומרים דנשבע הניזק ונוטל כו' \u0004 דבדבר דלא ה\"ל לידע לא אמרינן דה\"ל מ\"ש ואי\"ל משלם וכבר הארכתי בזה לעיל סי' ע\"ב סי\"ב ס\"ק נ\"א והעליתי דבכל גווני הוי משואיל\"מ וא\"כ כאן העיקר כדברי הרמב\"ם והמחב' וגם ר' ירוחם נל\"א ח\"ב כ' כדברי הרמב\"ם כאן בסתם וכן הסמ\"ג עשין ע' דף קמ\"ח ע\"ב אף שכ' הסמ\"ג בעשין קצ\"ה דף קפ\"ה ע\"ד דלא אמרינן משואיל\"מ אלא בדבר דה\"ל לידע וע\"ש:","\u0003 המוסר ממון כו' \u0004 וה\"ה בקרקע שייך דין מוסר וכדלעיל ס\"ס שע\"א וע\"ש:","\u0003 מהיפה שבנכסיו \u0004 כלו' מן העידית כשאר מזיק ואף דדיני דגרמי רבנן כעין דאורייתא תקון והכי אמרי' לעיל סי' שפה ס\"ק ב' גבי מטמא ומדמע ומנסך מיהו היינו דוקא כשאין לו מטלטלין אבל כשמשלם לו מטלטלין יכול לסלקו אפי' בסובין דכל מילי מיטב נינהו כדלקמן סי' תי\"ט וכ\"כ הרב המגיד ופשוט הוא:","\u0003 אלא הרגיל בלבד \u0004 כלו' הראה או דיבר לאנס וגרם שנמסר ממונו של זה ביד האנס:","\u0003 ואם מת גובים מיורשיו \u0004 היינו משום דס\"ל דמוסר דינא הוא ולא קנס' דרבנן וכ\"כ ה\"ה והבאתיו לעיל ריש סי' שפ\"ו וא\"כ אפי' לא עמד בדין גובה מיורשיו והי\"א דס\"ל דדוקא כשעמד בדין ס\"ל דמוסר דמחייב משום דינא דגרמי דרבנן הוא וכמ\"ש בר\"ס שפ\"ו ולפ\"ז במוסר שנשא ונתן ביד גם להי\"א גובים מהיורשים אף שלא עמד בדין ופשוט הוא ועמ\"ש לעיל סי' שפ\"ה ס\"ק ג' עיין בתשו' מהר\"ם אלשיך סי' קל\"ד:","\u0003 וי\"א דדוקא כשעמד בדין כו'. \u0004 לשון הד\"מ וכתב הרמב\"ם ואם מת גובה מיורשיו וכתב המ\"מ שכן כתב רב האי והרמב\"ם והרשב\"א כו' וכן הוא תשובת מהר\"מ במרדכי פ' החובל דצריכי' היורשים לשלם אבל אם לא הספיק לעמוד בדין עד שמת אין היורשים צריכין לשלם כו' עכ\"ל ואין דבריו נכונים דודאי תשובת מהר\"מ חולק דלהמ\"מ מוסר הוא דינא ולא קנסא כדאיתא בדבריו להדיא וכן הוא בדינא דגרמי להרמב\"ן וגובה מיורשי' אף שלא עמד בדין ולתשובת מהר\"מ לדעת ריצב\"א הוא קנסא ע\"ש ודוק כי זה ברור:","\u0003 הבעל אוכל פירות כו'. \u0004 כ' הסמ\"ע צ\"ע מ\"ש מחבלה באחרים דכ' הטור והר\"ב לקמן ס\"ס תפ\"ד וכתבו ג\"כ המחבר בחבלה בבעלה דצריכה למוכרן בטובת הנאה ולשלם ממנו דמי החבלה ואפשר דבמסירה דלא הזיק' בידים הקילו דשם קנס עליו כו' עכ\"ל ולא ידענ' מה קשיא ליה דודאי הכא אם הוא רוצה שתמכור נ\"מ שלה בטובת הנא' מחויבת לעשו' כן וכמ\"ש הוא עצמו בסי' תכ\"ד סס\"ק ט\"ז דגם בהלואה ובהשאלה ובכל דבר הדין כן אע\"פ שלא הוזכר שם כן וא\"כ ה\"ה הכא ואדרבה הכא אשמועי' גדולה מזה דהנכסים מיד בחזק' הנמסר רק שהבעל אוכל פירות כל ימי חייה וחייב לשלם אחר מיתתה ואדרבה איפכא קשיא דהכא חייב לשלם לאחר מיתתה ובסי' תכ\"ד לא מחייבים לה אלא למכור נ\"מ בטובת הנאה פי' דאם תמות ירשנה הבעל כמ\"ש הטור שם הרי דאין הבעל חייב לשלם לאחר מיתתה ונ\"ל לתרץ משום דהתוס' ס\"ס י\"נ הקשו הא אפי' לאחר תקנת אושא אמרי' דבמקום פסידא לאחריני הוי בעל יורש וא\"כ תיזבין נ\"מ שלה ותיתב ליה ותרצו בשם רשב\"א דכיון שתקנו דלוקח הוא לא פלוג אפי' איכא פסידא כיון דלא שכיח שיהא פסידא לאחריני וכן תירץ הרמב\"ן שם בחדושיו וז\"ל א\"נ משום חבלות דמלתא דלא שכיחא הוא לא פלוג רבנן בתקנתא דבעל עכ\"ל י\"ל דבמסירה דשכיח דהא דיני דחבלות לא דיינינן בזמן הזה משום דלא שכיחי ודיני מסור' דיינינן וכמו שנתבאר בסי' א' מיהו ודאי אם היא רוצה למכור נ\"מ שלה בטובת הנאה לשלם להנמסר דסגי בהכי אלא דאדרב' אפי' אין כאן מי שרוצ' לקנות או שלא יעלה כ\"כ מחויב הבעל לשלם אפי' מתה ואם אינו רוצה לשלם אז גוף הקרקע וגם הפירות לנמסר וכדאי' במרדכי ודלא כסמ\"ע שכ' לתרץ דבמסורו' הקילו דאדרב' החמירו וכמ\"ש ועוד דהא כ' הר\"ב וכן לשאר ניזק מיהו צ\"ל דשאר ניזק דכ' הר\"ב היינו דומיא דמסורת דשכיח מיהו לתרוצ' קמא שכ' הרמב\"ן שם דאיכא למימר לפסיד' דידיה חשו רבנן ותקנו הכי לפסידא דלכל מאן דאתי בתר בעל לא חששו עכ\"ל משמע דאפי' בפסידא דשכיח הוי כלוקח וכן יש לכוין דברי התוס' שם ע\"ש ודוק וא\"כ במסור אין הבעל חייב לשלם כי יש לו דין לוקח רק תמכור נ\"מ שלה בטובת הנאה ותשלם ואפי' לתירוצא בתרא דהרמב\"ן י\"ל דמסירה כחבלות דיינינן לה לענין זה ומהר\"מ במרדכי שם דפסק דהבעל חייב לשלם י\"ל דס\"ל כשנויא קמא דהתוס' שם דהמ\"ל ולטעמיך ע\"ש ודוק:","שוב ראיתי במהרש\"ל פ' החובל סי' ל' פסק כהרשב\"א בתוס' די\"נ והעלה דבין חבלה ובין מסירה בעל לוקח הוי ולא יורש ואינו חייב לשלם לאחר מותה רק שכייפינן למכור כתובתה בטובת הנאה אם יש מי שיקנה ע\"ש:","\u0003 ואין הבעל לענין זה רק כיורש כו'. \u0004 כבר כתבתי דיש חולקין בזה וס\"ל דבעל לוקח הוי לענין זה ופטור לשלם וכ\"פ מהרש\"ל פ' החובל סי' ל' ע\"ש:","\u0003 והראה שלו ושל חבירו. \u0004 אע\"פ שהראה זה בכלל שלו חייב כדלעיל ס\"ס שע\"א:","\u0003 כיצד כו' \u0004 אלעיל קאי במוסר בלא אונס דחייב כיצד הרי שגזר המלך כו' ולא אנס כו' ועמד מוסר ואמר כו' עיין בתשובת מבי\"ט ח\"א בשאלות השניות סי' נ\"ז דקכ\"ו ועיין בתשובת ן' לב סי' ב' סי' נ\"ד ובתשובת מהר\"ם אלשיך סי' ס\"ו ובתשובות מהרשד\"ם סי' שד\"מ ושנ\"ח:","\u0003 הרי שגזר המלך להביא לו כו'. \u0004 היינו בענין שאין בו דינא דמלכותא כגון שגזר על איש ידוע וכה\"ג וכדלעיל סי' שס\"ט ס\"ח וע\"ש:","\u0003 ואפי' יסרוהו ולא א\"ל על מה והראה ממון חבירו חייב. \u0004 באמת כ\"כ הטור אבל לא ידעתי מנ\"ל הא ומן הסברא נראה דפטו' שיכול לו' הייתי סבור שמוסרין אותו להראות להם ממון ואולי האמת כך היה ולא יהא אלא ספק אמאי יתחייב מספק וכן בש\"ש איתא ישראל שאנסוהו עכו\"ם והראה ממון חברו פטור ולא הוזכר שאנסוהו להראות ממון ומ\"ש הב\"י שהטור הוציא כן מעובדא דכסא דכספא לא נהירא דהתם נטל ונתן ביד הוי וכן השיג עליו הב\"ח גם מ\"ש הב\"ח דהטור הוציא כן מהא דקאמר בש\"ס דאחויי אחויי אין ראיה משם דמאן לימא לן דהתם אנסוהו ונראה דהטור מיירי כשנכרין הדברים שלא יסרוהו מתחלה בשביל ממון ודוק:","\u0003 אבל לא אונס ממון \u0004 כ\"כ הב\"י בשם תשובת מיי' וכתב דפשוט הוא אמנם בתשובת רשב\"א סי' תתק\"פ לא משמע כן שכתב דהסוגיא מיירי באונס ממון ואף שכתבו לקמן ס\"ד ס\"ק כ\"ד דאין נ\"ל כתשובת רשב\"א בזה היינו במה שמפרש הסוגיא באונס ממון דוקא אלא הסוגיא מיירי אף באונס נפשות אבל מ\"מ במה דס\"ל להרשב\"א דבהראה פטור אף באונס ממון אין הכרח בש\"ס ופוסקים נגדו וגם מצאתי בס' החנוך להרא\"ה פרשת קדושים מצוה רמ\"ג וז\"ל וכדתניא ישראל שאנסוהו והראה ממון פטור דכל מראה ע\"י אונס פטור ופי' מורינו דלא סוף דבר אנסוהו בגופו אלא אפי' אנסוהו בממון שיקחו לו ממון אם לא יראה ממון חברו והראוהו פטור ואינו חייב אלא במראה מעצמו וכן כ' הרמב\"ם ז\"ל עכ\"ל ואף שמ\"ש וכן כ' הרמב\"ם ז\"ל צ\"ע דאף שהרמב\"ם כ' בתחלת דבריו בד\"א כשהראם המוסר מעצמו כו' מ\"מ ממ\"ש בסוף דבריו ה\"ז פטור שאם לא יראה יכהו או ימיתהו משמע דדוקא באונס הגוף פטור ואולי גירסא אחרת היה לו בדברי הרמב\"ם מ\"מ כיון דידוע דמורו של הרא\"ה היה הרמב\"ן וא\"כ הרמב\"ן והרשב\"א והרא\"ה סוברים דאף באונס ממון פטור כשהראה נראה לי דיכול לו' קיים לי כותייהו:","\u0003 אנסו המלך כו' \u0004 עיין בתשובת מהרשד\"ם סי' נ\"ה וסי' קל\"ה וסי' ר\"ז:","\u0003 נשא כו'. \u0004 חייב לשלם מ\"מ כו' והראב\"ד השיג על זה וז\"ל ע\"ד הרב הוא הולך ואין הגאון מודה לו וכן הדין שאין לך דבר שעומד בפני פקוח נפש ומאין מתחייב לו שימות בשביל ממון חברו הואיל ויחדו לו בפי' וכבר הרחבנו בדברים אלו בפי' ב\"ק עכ\"ל והרב המגיד כ' שראיות הרי\"ף נכונות ביותר ושכן העלה הרשב\"א ז\"ל ובאמת הרי\"ף האריך בראיות וגם הבעל המאור הודה לו וגם הרמב\"ן בס' המלחמות האריך עוד בראיות להרי\"ף וכן דעת הרא\"ה והרא\"ש והסמ\"ג והמרדכי והטור והמחבר ושאר פוסקים וכ\"כ מהרש\"ל פ' הגוזל בתרא סי' מ\"ז וכ\"כ הב\"ח אבל בספרי הארכתי בזה ודחיתי כל ראיות הרי\"ף ובעל המאור והרמב\"ן והעליתי דדוקא אם אנסוהו על ממון סתם אז אף שאנסוהו להביא חייב כשנשא ונתן ביד דזה מיקרי מציל עצמו בממון חברו ודמי לנרדף ששבר הכלים לעיל סי' ש\"פ ס\"ג משא\"כ הכא שאנסוהו להביא ממון פלוני א\"כ האונס הוא מתחלה על אותו הפלוני ואין זה נקרא מציל עצמו בממון חברו אלא שמוכרח לעשות כמו שאומר לו האנס ואם לא יעשה כן נמצא יציל הוא ממון חברו בנפשו ואין לך דבר שעומד בפני פקוח נפש ובההוא עובדא דאמטי ודרי בהדן לא אנסוהו אחר כך רק מתחלה אנסוהו להראות ואח\"כ אמרו לו כן ודוק ותשכח שבזה נדחין כל דברי הרי\"ף והרמב\"ן ועיין בבעל העיטור דף מ\"ח ע\"ב וב\"י ודוק והך דפקיע זה או עמיר זה מה שתי' הבעל לחם משנה בו אינו נכון כלל וגם נראה דאשתמיטתיה דברי בעל העיטו' והנ\"י ע\"ש וגם מה שתי' הבעל העיטור בזה דהתם ליכא אונס' כיון דקאי בתרי עברי דנהרי ומצי לאשתמוטי מיני' ואחריו נמשכו הב\"י והש\"ג והמעד\"מ בתירץ זה ואינו מחוור בעיני דא\"כ המקש' הי' סבור דאיכא אונסא ועיקר התירוץ דמשני דליכא אונסא הוא חסר מן הספ' וגם קמשני לישנא אריכא דלא צריך והל\"ל בקצור הב\"ע דליכא אונסא ועוד דאם איתא דהמקשן היה סבור דפקיע או עמיר מיירי בדאונסיה א\"כ אמאי פריך אטעמא דקלייה בלאו הכי ה\"ל לאקשויי לגופא דברייתא אמאי חייב הלא אנסוהו על ממון פלוני פטור דאין לך דבר שעומד בפני פקוח נפש אבל באמת נלפע\"ד שלחנם דחקו בעל העיטו' והנמשכים אחריו בזה אלא נרא' דבין להמקשן ובין להתרצן מיירי בשאין האנס מאנסו אלא שא\"ל האנס והיינו דקתני אמר לו אנס הושיט לי פקיע זה ולא קתני אנסו להושיט לו פקיע זה ופריך דלדידך דאמרת קלייה ולאו כלום עבד א\"כ ה\"נ באמר לו הושיט לי ואע\"ג דאינו מאנסו כלל נימא כיון דקלייה לאו כלום עבד ומשני דקאי בתרי עברא דנהרא רלא מצי אנס למשקליה וכמו שפירש\"י ומיירי כפשוטו דאף דקאי בתרי עברי דנהרי מצי למאנס ליה אלא דאינו מאנסו ואשמועי' ברייתא בין להמקשן בין להתרצן דאע\"ג דאנס הוא לא אמרינן דאמירת אנס אונס הוא אלא כל כמה דלא מאנס ליה בהדיא דהיינו שאומר לו אם לא תושיט לי אהרגך רק א\"ל הושיט לי חייב כן נ\"ל ברור:","מ\"מ אם אנסוהו בפי' להביא לו ממון פלו' והביא לו ביד פטור וכן דעת רב האי גאון ור\"ח גאון ופשיטא דאין לחלוק על דברי הגאונים אם לא בראייה ברורה מן הש\"ס וכ\"ש כאן שנראה כדבריהם וכן דעת ה\"ר אפרים ובע\"ה וגם הנ\"י כת' שדברי הראב\"ד נ\"ל נכון מאד וכ\"כ בתשו' הרשב\"א סי' תתק\"פ (ואף שבמ\"ש בתשו' רשב\"א שם שהסוגיא מיירי באונס ממון אין נ\"ל כן מ\"מ במה דס\"ל כהראב\"ד לדינא נראה כן וע\"ש) וגם הירושלמי ס\"פ החובל אע\"פ שדחקו הרמב\"ן בספר המלחמות והרא\"ש מפרשו בדרכים אחרים מ\"מ נ\"ל עיקר דירוש' מיירי כפשוטו דאם אנסוהו להביא ממון פלו' פטור וכר\"ח גאון וגם מצאתי בביאורי מהר\"א שטיין על הסמ\"ג דף קמ\"ח ע\"ב וז\"ל ובאבי\"ה סי' אלף ומ' הביא דברי האלפס עם כל ראיות שלו ושם מביא דברי רבי שב\"ט שסותר ראיות של הרב אלפס וגם מביא שם הירושלמי ופי' ר\"ח שהכל חולקין על האלפסי והאריך מאד וקצרתי עכ\"ל וכן ראיתי בפסקי מהר\"מ רקנטי סי' תע\"ג שכ\"כ בשם ראבי\"ה ובשם רשב\"ט וגם בתשובת מהרשד\"ם סנ\"ה כ' כיון דדבר זה פלוגתא דרבוותא היא קמאי ובתראי לא מפקינן ממונא ע\"ש וגם בש\"ג פ' הגוזל בתרא משמע דספיקא דרבוותא הוי ע\"ש ולדידי לאו ספיקא הוא אלא העיקר כהפוטרין וכמ\"ש בספרי (עיין בתשובת הר\"ב סי\"א דף כ\"ג ע\"ב):","\u0003 דזה לא מיקרי נשא ונתן ביד. \u0004 ונראה דאם הי' להם משכון בשותפות על החוב ונתנו להשר דזה מיקרי נשא ונתן ביד וכן מוכח בתשו' מהר\"מ שבמרדכי שם שכ' וז\"ל ואי עביד הכי מדעתיה בלא אונס חייב כמו שורף שטרותיו של חברו אבל באונס פטור ואע\"ג דאמרי' פ' א' דיני ממונות כיון דא\"ל פטור אתה כמי שנשא ונתן ביד דמי הא אתותב עכ\"ל בפ' א' דיני ממונות שם (בדף ל\"ג ע\"ג) בתר דאתותב קמתרץ רבי' דמיירי בשנשא ונתן ביד והא דזיכה את החייב מיירי כגון שהיה לו בידו משכון ונטלו ממנו דה\"ל נשא ונתן ביד ע\"ש:","\u0003 אין לו דין מוסר כו'. \u0004 בתשו' מהר\"מ מלובלין סכ\"ו כתב ואף שיש חולקים בזה נראה שכך הלכה עכ\"ל ולא נהירא להכריע נגד מהר\"מ ב\"ב דלא היה בדורו כמותו כדאיתא בפסקי מהרא\"י סי' קמ\"ב ועוד דהא הסברא ראשונה היא רק סברת יחיד רבי אליעזר מטול' במרדכי ס\"פ הגוזל בתרא ובתשו' מיימוני סוף ספר נזיקין והרי במרדכי פ' המניח משמע דרבוותא פליגי עלה דכתב שם ומעשה הי' בקולניא\"ה בא' שהפקיד אצל חבירו פקדון לימים כפר לו ולקח המפקיד את שלו בידי עכו\"ם ומתוך כך העלילו על הנפקד והפסיד הרבה ופסק הרב דאם אפשר למפקיד להציל את שלו בענין אחר חייב כמו הי' לו לשמטו ולא שמטו וכ\"פ רבינו יקר עכ\"ל וכ\"כ באגודה שם שכן פסקו הגדולים וכן בד\"מ מסיק כפוסקי' אלו וגם מהרש\"ל פרק הגוזל בתרא סי' מ\"ט כתב שאין נראה דברי ר\"א מטול' לענין פטור ממון וחלילה להורות כן שיבא כמה חילול השם מזה ע\"ש וקרוב אצלי דאף ר\"א מטול' לא קאמר אלא כשלא הי' אפשר לו להציל בענין אחר ואפ\"ה כתב שם דכשאין לו מגו לאו כל כמיניה והיינו מטעמא דכיון שהוא מחוייב להחזיר א\"כ שלא כדין עבד מה שתפס ולא יוכל לומר להציל שלי נתכוונתי והיינו דהמרדכי והאגודה אע\"פ שבפ' המניח כתבו כפסק הגדולים כתבו בס\"פ הגוזל בתרא בסתם דברי ר\"א מטול' ע\"ש ודו\"ק. וע' בתשובות מהר\"ם מלובלין ס\" ק\"ך ובתשו' הר\"ב סי' פ\"ו דף קע\"ב ובתשו' מהרי\"ט ס\"ס מ\"ה:","\u0003 מי שנתפס כו'. \u0004 זה נתבאר לעיל סי' קכ\"ב ס\"ב ועיין בתשובת מהרשד\"ם סי' רי\"ד:","\u0003 מי שיש עליו עדים כו'. \u0004 עיין בתשו' מהרש\"ך ספר ג' סי' פ\"ו ופ\"ח באריכות מדיני מוסר:","\u0003 או שנאנס ונש' ונתן ביד כו'. \u0004 באמת כ\"כ הרמב\"ם וכן הוא בע\"ש דמבעיא ולא איפשטא אבל קשה לי בנאנס ונשא ונתן ביד היכא נימא דהוא בעיא דלא איפשטא הא לא מבעיא בש\"ס אלא במוסר למאן דדאין דינא דגרמי אבל בנאנס ונשא ונתן ביד מזיק בידים ולאו גרמי הוא ופשיטא דלא שייך תקנת נגזל דהא אנוס הוא וא\"כ כיון שהוא מכחישו בברי נשבע זה שנאנס ופטור דהא אינו נפסל כיון שנאנס ויכול הוא לישבע כן נ\"ל ברור ודברי הרמב\"ם והמחבר והע\"ש צלע\"ג:","\u0003 ונשא ונתן כו'. \u0004 ואם נשא ונתן ביד בלא אונס פשיטא דעשו תקנת נגזל דהוי גזלן ממש וכ\"כ מהרש\"ל פ' הכונס סימן ל' בשם תשובת מהרי\"ל (והוא בתשו' מהרי\"ל שהבאתי לקמן ס\"ק ל\"ו) ושאר פוסקים והסכים כן ופשוט הוא:","\u0003 והמוסר כופר כו'. \u0004 כ' הרב המגיד ומביאו ב\"י שמדברי הרמב\"ם אלו משמע שסובר כר\"ת דאם אין המוסר כופר אלא שאינו יודע כמה הפסידו נשבע הנמסר ונוטל והוא היש מי שאומר שהביא המחבר לקמן) ואחריו נמשך מהרש\"ל פרק הבונה סי' צ' וכ' שכוונת הרמב\"ם כר\"ת ואין נ\"ל כן דדין זה של ר\"ת דין מחודש הוא וה\"ל להרמב\"ם לכתוב ההפוך דאם אינו כופר נשבע הנמסר ונוטל אלא נראה דהרמב\"ם לטעמיה אזיל דס\"ל דכל מודה מקצת ועל השאר אומר איני יודע ה\"ל משואיל\"מ אף בדבר דלא ה\"ל לידע וכמו שנתבאר לעיל סי' ע\"ב ס\"ק נ\"א באריכות לכך הוכרח לכתו' כאן שהמוסר כופר דאלו אומר איני יודע כמה הוה ליה משואיל\"מ וכשנגדו נוטל בלא שבועה לכך לא הוצרך לכתוב ההפוך דין זה פשוט בלאו הכי ואינו תלוי בכאן כלל. כן נ\"ל ברור לדעת הרמב\"ם ודו\"ק:","\u0003 אם תפס אפי' בעדים. \u0004 ל' מהרש\"ל פרק הכונס סי' ל' ואם העמיד העכו\"ם על ממון של חבירו דהוה כמוסר בידים וכל כה\"ג או שמוסר לאדם בגופו נשבע הנמס' ונוטל עכ\"ל ולא ירדתי לסוף דעתו אמאי בהעמיד לעכו\"ם על ממון חבירו הוי כמוסר בידים ס\"ס לא הוי אלא גרמי כיון שלא נשא ונתן ביד כדמוכח בסוף הגוזל בתרא ע\"ש:","\u0003 וי\"א דבספיקא כו'. \u0004 בב\"י כתב שכ\"כ התוס' והרא\"ש ס\"פ הכונס ולא דק אלא כוונת הטור למ\"ש הרא\"ש פרק כיצד הרגל דתפיס' לא מהני בספיקא דדינ' ועיין בספרי תקפו כהן:","\u0003 בראייה ברורה. \u0004 ולא באומדנא ועיין ב\"ח:","\u0003 רק שהוצרך להתפשר עם השר בכך וכך \u0004 ואולי הערים או היה אפשר להתפשר בפחות ועיין בתשו' מהר\"מ מינץ סי' מ\"ד:","\u0003 ויש מי שאומר \u0004 בטור ובתו' והרא\"ש ומרדכי וסמ\"ג ושאר פוסקים הביאו מחלוקת ר\"ת ור\"י בזה שר\"ת הוא היש מי שאומר ור\"י חולק והרא\"ש והטור הסכימו לר\"י ויש לי לדקדק דתיפוק להו בלאו הכי הא כיון שהמוסר מודה שהפסידו ואינו יודע כמה הוה ליה מודה מקצת ועל השאר אינו יודע דקי\"ל דה\"ל משואיל\"מ ושכנגדו אפי' שבועה לא בעי. ואמת שמצאתי בתשובת מיי' לספר משפטים סי' ס\"א כ' וז\"למנה לי בידך והלה אומר נ' ידענא ונ' לא ידענא דאמרי' משואיל\"מ שכנגדו צריך לכל הפחות לישבע אבל לא יטול בלא שבועה וכן משמע מתוך דברי ר\"ת בס\"פ הכונס דפי' דאם המוסר אומר איני יודע כמה הפסדת ע\"י שכנגדו נשבע ונוטל אלמא בכל כהאי גוונא שכנגדו נשבע ונוטל כו' עכ\"ל אבל אין נ\"ל כן דפשיטא דבנ' ידענא ונ' לא ידענא שכנגדו נוטל בלא שבועה והוא מוסכם מכל הפוסקים בדוכתי טובי וכן הפוסקים הנ\"ל שהביאו מחלוקת ר\"ת ור\"י במוסר כתבו בדוכתי טובי בנ' ידענא ונ' לא ידענא שכנגדו נוטל בלא שבועה ועוד דא\"כ מאי טעמיה דר\"י דחולק אר\"ת גם יתר דברי תשובות מיימוני ההיא שם גבי עד מסייע ע\"ש מגומגמים ואין כאן מקום להאריך בזה ונ\"ל לתרץ דאפשר דר\"ת ור\"י סוברים כמ\"ש לעיל סי' שפ\"ו ס\"ק י' בשם הרמב\"ן דבכל דיני דגרמי אין נשבעין שבועות התורה. א\"נ כמ\"ש לעיל סי' שפ\"ו ס\"ק א' דס\"ל לר\"י ישאר בעלי התוס' דדינא דגרמי דרבנן א\"כ לא שייך לומר משואיל\"מ וכמ\"ש מהרש\"ל פ' הכונס סי' ל' ול\"א דלמ\"ד דהוי דרבנן לא שייך ש\"ד כלל והבאתיו לעיל סי' שפ\"ו סס\"ק י' אך תירוץ זה א\"א לומר בהרא\"ש וסמ\"ג שהם פסקו דינא דגרמי דאורייתא עי\"ל דמיירי דאומר המוסר הילך על מה שהפסידו או שיש לו כנגדו ביד הנמסר אכן מתוך דברי הרשב\"א בתשו' והרא\"ש ס\"פ הכונס למדתי תירוץ אחר דכיון דלא ה\"ל למוסר לידע כמה הפסידו לא שייך לומר דהוי מחוייב שבועה דז\"ל הרשב\"א בתשובה סי' תתקע\"א ואפילו היא מודה בקצת הפסד ע\"י מסירתה על שאר טענות שאינה יודעת עליו להביא ראיה ואינו דומה לנ' לא ידענא ונ' לא ידענא דהתם הו\"ל למידע וכיון שאינו יודע ה\"ל משואיל\"מ ובא חברו ונוטל בלא שבועה כו' אבל כאן אינה מחויבת לדעת והו\"ל כאותו של שק צרור דירושלמי גם מה שראיתי למקצת רבנים שאמרו ישבע ויטול אינו נראה לי כלל כו' ועוד דבפ' הכונס איבעיא לן אי עשו תקנת נגזל במוסר ולא איפשיטא מספיקא לא מפקינן ממונא עכ\"ל ונ\"ל כוונתו דאע\"ג דבההיא דשק צרור של ירושל' שכנגדו נוטל בשבועה וכדאיתא בירושל' וכ\"כ ה\"ה להדיא בשם הרשב\"א בס\"פ ה' מה' שאלה וכבר נתבאר זה על נכון בסי' ע\"ב מ\"מ הכא אף בשבועה אינו נוטל משום דדוקא התם עשו תקנת נגזל אבל במוסר דדינא דגרמי הוא מבעיא ליה אי עשו תקנת נגזל מספיק' לא מפקינן ממוצא וכן מצאתי בהרא\"ש ס\"פ הכונס שמתחלה הביא דברי ר\"ת ור\"י והכריע כר\"י דבעיא דמוסר היינו אפילו המוסר אינו יודע ואח\"כ הביא הירושלמי הנ\"ל דשק צרור והקשה עליו אמאי לא הוי משואיל\"מ ויטול בלא שבועה ותירץ דכיון דלא הוה ליה לידע מה הפקיד אצלו לא הוה ליה מחיוב שבועה ואיל\"מ אלא שעשו תקנת נגזל בפקדון כיון שהנפקד אינו יודע שישבע המפקיד ואהא מייתי לה בירושלמי והא דסלקא בתיקו אם עשו תקנת נגזל במוסר ולא פשיט ליה מפקדון משום דמוסר דינא דגרמי הוא ובדבור' בעלמא הוא דאפסדיה עכ\"ל הרי משמע להדי' כמ\"ש עוד נ\"ל לתרץ אפי' למה שהעליתי לעיל סי' ע\"ב ס\"ק נ\"א כהרמב\"ם וסייעתו דאף בדבר שלא ה\"ל לידע אמרי' משואיל\"מ י\"ל דר\"ת ור\"י בתוס' ופוסקי' מיירי כאן שהנמסר מודה שהמוסר אינו יודע דבכה\"ג כתבתי שם דלכ\"ע לא אמרינן משוא\"י ל\"מ:","וראיתי בב\"ח סי' נ' סי\"ד שכתב וז\"ל ול\"נ דאע\"ג דר\"י והרא\"ש חלקו על ר\"ת דמדמה מוסר לנגזל דטפי מסתברא לדמותו למבעיר כמ\"ש הרא\"ש בס\"פ הכונס מ\"מ מטעם אחר נ\"ל דדברי ר\"ת עיקר דכיון דהמוסר מוד' שהפסיד על ידו אלא שאינו יודע כמה הפסיד ה\"ל כנ' ידענא ונ' לא ידענא דמתוך שאיל\"מ וכיון דלשם אין התובע צריך לישבע הכי נמי במוסר ודאי גם הנמסר מדינא א\"צ לישבע אלא דר\"ת הוא דכתב ונראה דמשביעין אותו מטעם חומרא ולא מדינא וכל זה דלא כתשובת רשב\"א בסי' תקע\"א עכ\"ל ונ\"ל שלא ירד לעומקו ולא ראה רק תחלת דברי הרא\"ש דס\"פ הכונס שהרי בסוף דברי הרא\"ש מוכח דלא הוי משואיל\"מ מטעם דלא הוי לו לידע וכמ\"ש הרשב\"א בתשו' סי' תקע\"א גם בד\"מ ובסמ\"ע ס\"ק כ\"ד הביאו דברי תשובת הרשב\"א סי' תקע\"א הנ\"ל בסתם וכבר מבואר מחלוקת הפוסקים בזה ומביאם הב\"ח עצמו לעיל סימן צ' סי\"ט וס\"ס רצ\"ח במסקנתו דבדבר דלא ה\"ל לידע לא הוי משואיל\"מ. וגם מ\"ש הב\"ח דר\"ת הוא דכ' דישבע מטעם חומרא כו' לא נהירא דאם איתא דהוי משואיל\"מ אפי' בלא מוסר א\"כ כ\"ש דבמוסר א\"צ לישבע. והיאך שייך כלל להחמירעל הנמסר במוסר יותר מבעלמא ולענין הלכה היה נראה לכאור' לפסוק כאן דה\"ל משואיל\"מ כיון דכבר העליתי לעיל סע\"ב ס\"ק נ\"א כהרמב\"ם וסייעתו דאף בדבר דלא ה\"ל לידע הוי משואיל\"מ אם לא שהתובע מודה שהנתבע אינו יודע אך שצ\"ע בכאן מטעם אחר דהרמב\"ם ס\"ל דאין נשבעין ש\"ד אכל דיני דגרמי והבאתיו לעיל סי' שפ\"ו ס\"ק י' וגם יש פוסקים דדינא דגרמי הוא דרבנן ולדידהו לא שייכא ש\"ד כלל וכמ\"ש שם:","\u0003 מי שאומר כו' \u0004 לכאורה קשה על המחבר מאחר שכבר העתיק ל' הרמב\"ם והמוסר כופר כו' דמשמע מיניה דאם אינו כופר נשבע הנמסר ונוטל וכמ\"ש הב\"י שכן דקדק הרב המגיד מדבריו שסובר כר\"ת א\"כ היאך חזר לכתוב כאן דין זה בשם יש מי שאומר. ונראה דמתחלה כתב והמוסר כופר ולפי שההפוך לא נזכר בפירוש ואפשר לדחוק ולומר דלאו דוקא כופר אלא ה\"ה אומר איני יודע לכך כתב כן כאן בפירוש דיש מי שאומר דבאומר איני יודע נשבע ונוטל. וכן יש לפרש דברי הסמ\"ג דף קמ\"ח ריש ע\"ג דבתחלה כתב כדברי הרמב\"ם ואח\"כ מחלוקת ר\"ת ור\"י ודלא כמהרש\"ל פרק הכונס סי' ל' שתמה על הסמ\"ג בזה: עוד י\"ל בדעת המחבר והסמ\"ג דמתחלה כתבו והמוסר כופר לאפוקי אם אומר איני יודע בענין שאפשר שידע דאז ה\"ל משואיל\"מ וכמ\"ש לעיל ס\"ק ל\"ג וכאן מיירי כשהנמסר בעצמו מודה שהמוסר אינו יודע דבהא לא שייך מחויב שבועה כלל וכמ\"ש בס\"ק שלפני זה ופשיטא דמחלוקת ר\"ת ור\"י מיירי אף בכה\"ג דהא מיירי דומי' דעשו תקנת נגזל באשו ובזה מיושב ג\"כ מה שהקשה מהרש\"ל על הסמ\"ג גם מה שפסק מהרש\"ל שם כר\"ת אין נ\"ל דפשט' דסוגיא משמע כר\"י וכמ\"ש הרא\"ש שם דמיירי דומי' דתקנת נגזל באשו וכן נראה מסקנת הסמ\"ג שם וכן מסיק הנ\"י וכן נראה מתשובת הרשב\"א סתקע\"א שהבאתי בס\"ק שלפני זה וכן נראה מתשובת מהר\"מ במרדכי בכמה תשובות וכדלקמן ס\"ק ל\"ט. ועוד דנראה ממהרש\"ל שם שפסק כן כיון שנראה דעת הרמב\"ם כן וכבר כתבתי לעיל ס\"ק ל\"ג דאין נ\"ל כן דעת הרמב\"ם הלכך נראין דברי ר\"י עיקר. ואף שבס\"ק שלפני זה כתבתי שצ\"ע לדינא היינו היכא שאפשר לר שהמוסר יודע אבל היכא שידוע בודאי שהמוסר אינו יודע או שהנמסר בעצמו מודה שאין המוסר יודע דבכה\"ג לא שייכא שבועה על המוסר כלל רק דשייכא פלוגתא דר\"ת ור\"י אי עשו תקנת נגזל בהא נראה עיקר כר\"י דגם בזה מבעי' לש\"ס אי עשו תקנת נגזל או לא ומספיקא לא מפקי' ממונא כן נ\"ל:","\u0003 איני יודע כמה הפסדת כו' \u0004 וכתב הרשב\"א בתשובה סי' תקע\"א גבי אחד שמסר את חברו ואינו יודע כמה הפסידו דאם תפס מטלטלים שלא בעדים אין לו עליו כי אם חרם סתם כל מה שנטל ממנו שלא כדין עכ\"ל ונראה דדין זה אמת אפי' למ\"ד בספיקא דדינא לא מהני תפיסה דאע\"ג דלמ\"ד דלא מהני תפיסה אפילו תפס שלא בעדים לא מהני וכמ\"ש בספרי תקפו כהן היינו בשאר ספיקא דדינא אבל הכא דמטעם נאמנות אתינן עלה דמספקינן אם יהא נאמן בשבוע' ליטול והלכך כיון דתפס שלא בעדים ודאי נאמן מכח מגו והא דאינו נשבע וכמ\"ש לעיל סי' ע\"ב סעיף י\"ז ס\"ק ס\"ז דאפי' בטוען שכנגדו שמא צריך לישבע כדי ליטול צ\"ל דהרשב\"א מיירי שהנמסר רוצה להחזיק במטלטלים ואינו חפץ שיפדם המוסר ושיגבה מהם חובו ובכה\"ג כתבתי שם בס\"ק ע\"א דא\"צ לישבע ולכך כ' הרשב\"א דאין עליו רק חרם סתם. כן נ\"ל:","\u0003 וכל זה במוכר ממון אבל מסר גופו של חבירו כו'. \u0004 דין זה אף שפסקו מהרי\"ל לא נהירא לי ולפי שראיתי גם מהרש\"ל פ' הכונס סי' ל' ומהר\"מ מלובלין בתשובה סי' ס\"א נמשכו אחרי תשו' מהרי\"ל ופסקו כדבריו לכן צריך אני להאריך קצת וז\"ל מהרי\"ל בתשו' סי' פ\"ו ובדפוס האנווא סי' צ' והשתא כיון דר' דוד מוסר גמור דנתיהו בתפיסה אחרונה ישבע ר' ישי ויטול מר' דוד כל מה שברור לו שהזיקתו תפיס' אחרונה אע\"ג דרוב רבותינו פסקו דתיקו לקולא ולא עשו תקנת נגזל במוכר ה\"מ במוכר דהוי דינא דגרמי כגון אחוי אחויי שהראה ממון חבירו אבל המזיק ממון חבירו בידים עשו תקנת נגזל כאשו וכאן מזיק בידים כמו שכתבו רבותינו בפי' במיימוני פ\"ז במי שמוסר בידי' דעשו תקנת נגזל בההוא מוסר וכן באור זרוע וכן נ\"ל שצריך ליישב שכ' המרדכי בשם מהר\"מ בפ' הכונס דפסק כרבינו תם כשאין המוסר מכחישו דנשבע ונוטל דבאינך פירקי מייתי כמה תשובו' שפסק בהדי' דתיקו לקול' ואפי' אין מכחישו אלא היכא דמסר בידים כי האי דמכר גופו דחשיב מזיק בידים כדפסק ר' אפרים שלהי הגוזל קמא דכשמוסר גופו הוי מזיק ממש דאפי' רבנן מודו דהוי כחובל ובההי' תשוב' דאלכסנרי נמי קרי ליה מזיק ופשיטא דמזיק עשו תקנת נגזל כדפי' ור' ישי ישבע בנק\"ח ויטול והני תשובות מן הגוזל בתרא מן הערב ומן בעל הסעודה כל הני הוה מסירת ממון ואין שם מסירת הגוף עכ\"ל ולפע\"ד דלא נהיר' כלל לחלק בין מוסר ממונו או גופו או כגון שגרם לו תפיסה דס\"ס לא עביד מעשה אלא דיבורא הוא ולא מיחייב אלא משום דינא דגרמי והוי בכלל מה דקאמר בש\"ס כי תבעי לך אליבא דמאן דדאין דינא דגרמי כו' ומ\"ש וכן נראה לי שצריך ליישב שכתב המרדכי בשם מהר\"מ פ' הכונס דפסק כרבינו תם כו' בדקתי בכל ספרי המרדכי ולית' שם דפסק מהר\"מ כר\"ת רק איתא שם דפסק מהר\"מ בתיקו לקולא ע\"ש ואם איתא בשום מרדכי בע\"כ ט\"ס הוא או צריך ליישב בענין אחר דמ\"ש מהרי\"ל דהך פ' הכונס מיירי במסירת הגוף הוא תמוה דהא ס\"ל דמסירת הגוף הוי כמזיק בידים דפשיטא דעשו תקנת נגזל כאשו א\"כ בהא פשיטא דלא פליגי ר\"ת ור\"י וקאי התם אמאי דמבעי' ליה לש\"ס דהיינו בדינא דגרמי אבל במזיק בידים לאו גרמי הוא ולא מבעי' ליה לש\"ס כלל וגם מ\"ש מהרי\"ל כדפסקי ר' אפרים שלהי הגוזל קמא דכשמוכר גופו הוי מזיק ממש דאפי' רבנן מודו דהוי כחובל כו' ר\"ל כמ\"ש המרדכי פרק הגוזל קמא וז\"ל ודוקא פטרי רבנן מראה ממון ישראל משום גרמא אבל אם היה מוכר גוף חבירו בידי עכו\"ם עד שיפדה עצמו מן העכו\"ם אפי' רבנן מודו ודמי לחובל בחבירו שמשלם ריפוי דחשיב ליה כאלו הפסיד ממונו ממש כשגרם לו ריפוי ה\"נ הואיל ומסר גופו בידי עכו\"ם כאלו מסר ממונו בידים ותדע שיש חילוק בין נזקי גופו לנזקי ממונו בכה\"ג ומשום ה\"ט דפריך שהרי שבת דאדם אם סגרו בחדר ובטלו ממלאכתו חייב שהרי ד' דברים שייכי באדם ושבת אחד מהם ואם סגר בהמה בבית ובטלה ממלאכת' פטור לד\"ה עכ\"ל וכן מהרש\"ל פ' הכונס סי' ל' הביא דברי מהרי\"ל הנ\"ל ודברי המרדכי אלו וכ' שכן יראה מדברי המרדכי אלו ולע\"ד אין נראה מהמרדכי כלום דבמרדכי מיירי כשמוסר גופו של חבירו בידים דהיינו שנוטל גופו בידו ומוליכו בחזקה לתפיסה לעכו\"ם ולאפוקי דלא תימא כיון דס\"ס אינו נוטל ממונו בידו ונותנו לעכו\"ם לא תהוי אלא גרמי אלא כיון דמוסר גופו בידים ומרמת זה נפסד לו ממון כל הזיק דממונו ה\"ל כאלו הזיקו בעצמו ובזה יש חילוק בין נזקי ממונו לנזקי גופו וקאי אמרדכי שם אמ\"ש שם בתחילה וז\"ל ויש לחלק בין נזקי גופו לנזקי ממונו שכשמזיק לגופו יש לו ליתן לרופא כו' אבל כשהזיק לממונו ומחמת אותו ממון נפסד ממון אחר כגון חובל בהמה ומחמת הבהמה נפסד ממון שיש לו ליתן לרופא זהו גרמא דלאו בגופו הוא אלא בממונו מ\"ה פטור והיינו טעמא דמודה ר' מאיר בזורק מטבע כו' דמחמת הממון נפסד ממון אחר בכה\"ג מודה ר' מאיר ודוקא פטרי רבנן מראה ממון ישראל משום גרמא אבל אם היה מוסר גוף חבירו כו' עכ\"ל המרדכי אלמא דכוונתו כדפי' והיינו שכ' שהרי שבת דאדם אם סגרו בחדר ובטלו ממלאכתו חייב כו' אלמא דמיירי במסרו בידו והוליכו לתפיס' לעכו\"ם דומי' דסגרו בחדר ובדברי מהרש\"ל פ' הכונס סי' ל' היה אפשר לדחוק ולו' דמיירי ג\"כ במוסר גופו בידים אבל בתשו' מהרי\"ל שם שממנו הוציא מהרש\"ל שם דבריו לא משמע כן וגם משמע שם להדיא דלא היה ר' דוד מוסרו רק בדבורו וכן משמע מדברי הר\"ב ועוד מבואר כן יותר מדבריו שכ' וכן אם גרם לו תפיסה כו' וכן משמע להדיא בתשו' מהר\"מ מלובלין סי' ס\"א דהתם בעובדא דיליה לא עביד מידי רק בדבוריה ופסק שם כיון דע\"פ דבורו היו תופסים אותו המושל והוא הציל עצמו מהתפיסה והוצרך להוציא הוצאות ע\"ז חייב לשלם לו כל הוצאתיו ע\"פ שבועתו דהנמסר והביא כל תשו' מהרש\"ל הנ\"ל ולמד ממנה כן. וכבר כתבתי דאין זה נראה לפע\"ד (ועוד מטעמים אחרים יש לי לדון על פסק מהר\"מ מלובלין שם וע\"ש ואין להאריך) גם מ\"ש מהרי\"ל ובההיא תשו' דאלכסנדרי נמי קרי ליה מזיק כו' ההיא תשו' דאלכסנדרי היא בתשו' מיי' לספר נזיקין סי' י\"ד תשו' מהר\"מ לענין שאלכסנדרי צריך כפרה במה שעל ידו נהרג ישראל שמסרו אלכסנדרי ורצו עכו\"ם לתפסו ולא הניח עצמו לתפוס מתוך כך נהרג וכ' מהר\"מ שם פושע הוא ומזיק הוא וגירי דיליה נינהו ובלא שום עדות כי אם על פיו נ\"ל דצריך כפרה כו' אבל לענין שיקרא מזיק בידים לענין היזק ממון שיגיע ע\"י זה ולא גרמי לא שמענו כלל הלכך נראה ברור כמ\"ש דבין מסר ממונו או גופו אם לא עשה מעשה בידיו כגון שהוליכו בעצמו לתפיס' ולא עביד אלא דבורו לא מיחייב אלא משום דינא דגרמי והוא בכלל מה דבעי' לש\"ס אי עשו תקנת נגזל במסור למאן דדאין דינא דגרמי כנ\"ל ברור ולא הוצרכתי להאריך רק מפני שגדול הדור מהרי\"ל לא פסק כן ונמשכו אחריו מהרש\"ל והר\"ב ומהר\"ם מלובלין ושאר אחרונים ולע\"ד הוא כשגגה היוצא מלפני השליטים האלו:","\u0003 שאומר לחבירו מסרתני כו' \u0004 וכ' הרשב\"א בתשו' סי' תקע\"א מוסר שהודה במקצת ישלם מה שהודה ואינו משלם השאר ואפי' או' נ' ידענא ונ' לא ידענא לא אמרינן מתוך שאיל\"מ מאחר שלא ה\"ל לידע כמה הזיקו עכ\"ל ד\"מ ג' עכ\"ל סמ\"ע ס\"ק כ\"ד ותשו' רשב\"א שם כ' ע\"ז והוה ליה כאותו של שק צרור דירושלמי עכ\"ל וסבירא ליה להרשב\"א בההיא דירושלמי כהרא\"ש וסייעתו שהביא הטור סי' רצ\"ח וכן כ' הרב המגיד ספ\"ה מהלכות שאלה בשם הרשב\"א ולפ\"ז למ\"ש הרמב\"ם והמחבר לעיל סי' צ' ס\"י וסי' רצ\"ח ס\"א באותו של שק צרור דירושלמי דה\"ל משואיל\"מ אע\"ג דלא ה\"ל לידע א\"כ ה\"ה הכא ודו\"ק וגם בב\"ח סי' צ' ס\"ס י\"ד כתב דלא כתשו' רשב\"א סי' תקע\"א ע\"ש וכן העליתי לעיל סי' ע\"ב סעיף י\"ב ס\"ק נ\"א דבכל ענין ה\"ל משאיל\"מ אם לא שהתובע מודה שהנתבע אינו יודע וע\"ש ודו\"ק:","\u0003 ואין צריך לעשות נקיות זו אלא ע\"פ עד א' כו'. \u0004 כ\"כ בד\"מ דכן משמע בתשו' מהר\"מ במרדכי פ' החובל ופ' שור שנגח הפרה וכן משמע בפסקי מהרא\"י סי' פ\"ג דא\"צ לעשות נקיות זו ע\"פ עכו\"ם עכ\"ל ובאמת המעיין שם יראה דלא משמע מידי ואני ראיתי בהג\"ה אשר\"י ס\"פ הכונס ומרדכי (ואגודה) פ' הגוזל בתרא כתבו וז\"ל והיכא ששני ישראלים דרים יחד בישוב ואין להם עדים ואתי חד וקצווח על חבריה דמסרו לעכו\"ם או לשלטון והלה אומר להד\"ם זה היה מעשה והורה ה\"ר אליעזר ממיץ בשם ר\"ת שיש לו לישבע לפני השלטון שלא דבר לשלטון על שכנגדו שום דבר רע המביאו לידי הפסד עכ\"ל ומביאו בד\"מ גופיה לעיל מיניה מיד הרי משמע להדיא דאף שלא היה עד אחד צריך לישבע לפני השלטון ונרא' דאף הר\"ב לא קאמר אלא לאפוקי שאין העכו\"ם נאמנים בכך לענין שיעשה נקיות זו בפניהם וזה באמת משמע לכאור' בתשו' מהר\"מ ופסקי מהרא\"י שם אבל אה\"נ אם הנמסר טוען ברי שמסרו צריך לעשות נקיות זו בפני השלטון אף שאין שם עד כלל והך עובדא דרבינו תם הי' הנמסר טוען ברי ומה שכתב הר\"ב ואין צריך לעשות נקיות זו אלא ע\"פ עד אחד כו' היינו כשאין הנמסר טוען ברי. שוב ראיתי בתשוב' מהרי\"ל סי' צ' משמע כדברי דאפי' בלא עד יש להשביעו בפני השר וכמ\"ש וע\"ש:","\u0003 שנים שמסרו ביחד כל א' משלם החצי \u0004 אפי' אין לחבירו לשלם א\"צ לשלם רק החצי כן הוא בהגהות מיימוני פי\"ב מהל' נזקי ממון ובמרדכי פרק הפרה בשם תשו' מהר\"ם ואזדא לטעמי' דלקמן ס\"ס ת\"י ועיין מ\"ש שם ובסוף ס' שארית יוסף כ' בכאן דברים שאינן מבוררין וע\"ש ומסיים בתשו' מהר\"מ במרדכי שם אמנם אם אתם רגילים לפטור המוסר לפי שהיה מוכה ואין אדם נתפס על צערו אז ירא' לי ששמעון המוסר השני חייב כל ההיזק אם יש עדים שמסרו שניהם ביחד כר' נתן דכל היכא דליכא לאשלומי מהאי משתלם מהאי ע\"כ:","\u0003 דכל זמן שלא נפטר ממסירה הראשונ' כו'. \u0004 ואם יש ספק בדבר אם נפטר ממסירה הראשונה מספיק' לא מפקינן ממונא והאחרון פטור כן הוא בתשובת מהר\"מ שם. ולפ\"ז לעולם אין חייב האחרון אלא כשידוע בבירור שכבר נפטר ממסירה הראשונה ואע\"ג דכתב בתשובת מהרי\"ל ר\"ס צ' וז\"ל כדפסיק מהר\"מ במרדכי אע\"ג דהתם כבר הי' פטור מן השופט וחזר עליו ע\"י מסירת שמעון כ\"ש הכא דלא נפטר ר' דוד כלל עדיין כו' עכ\"ל אין ר\"ל דהיה פטור לגמרי בבירור מן השופט רק שיצא מלפני השופט וכדאיתא בתשו' מהר\"מ שם ולפי הנראה היה פטור ממנו אבל אם נפטר ממנו בבירור האחרון חייב דמסירה חדשה היא וכמו שנראה מדברי הר\"ב:","\u0003 ואפי' לא מסרו כו' \u0004 כלו' אפי' לא מסר הראשון רק ראה השר או עכו\"ם שיגידו לשר פטור המוסר דהא בלא\"ה יודע לשר וכן כתב בדרכי משה בשם מהר\"מ מריזבורק וז\"ל ועוד כתב על שהכה חבירו ועכו\"ם ראוהו והלך אחד והגיד פטור דהא בלאו הכי ראוהו עכו\"ם ובודאי יגידו עד כאן:","\u0003 י\"א דאדם המוכה כו' \u0004 כתב בד\"מ וז\"ל וכ\"כ מהר\"מ מריזבורק וכתב דאם רגיל להכות הבריות מותר לקצץ ידו ע\"י עכו\"ם או להפסיד ממונו או להציל בא' מאבריו עכ\"ל וע\"ש שהאריך בדינים אלו ואין דבריו נראין דהא אפי' מוסר גמור אסור לאבד ממונו וכ\"ש זה כנ\"ל עכ\"ל ד\"מ ולא ירדתי לסוף דעת הר\"ב דז\"ל מהר\"מ מריזבורק מצוה לכל אדם להגיד לשופט פלוני הכה פלו'. ועוד הולכים בכעסם תעשה כך שלא יוסיף עוד ואם יעליל השופט עליו ויקח כל אשר לו פטור המגיד דאל\"כ אין לך אדם מציל את חברו מיד מכהו ודאי אם יכול להצילו בא' מאבריו יעשה כרב הונא דקץ ידא או שמא יותר טוב שיגיד לשופט ויפסיד ממון מלחסרו אחד מאיבריו והא רפיא עכ\"ל וא\"כ ל\"ק ממוסר דהכא להציל הוא בא וא\"א להצילו אם לא שיגיד לשופט וע\"י כך הוא מפסיד ממון ופשיטא דאם יכולים להציל הנמסר ע\"י שיפסיד המוסר ממון דשרי ומצוה הוא ועוד דממון מוסר דוקא לאבדו ביד אסור אבל להפסיד ע\"י גרמי מותר:","\u0003 ואפי' לא מסרו כו' \u0004 עיין בס' א\"א דף ע\"ז ע\"א:","\u0003 רק שאומר אלך כו' \u0004 ע\"ל סי' ל\"ד סעיף כ':","\u0003 נפסל לעדות כו' \u0004 עיין בתשובת הר\"ב סי' י\"ב דף כ\"ח ע\"ב ועיין בתשובת ן' לב ס' א' כלל י\"ז סי' כ\"ז וריש כלל כ' סי' ק\"ו ובתשוב' מבי\"ט ח\"א סי' ל\"ח:","\u0003 אם רגיל בכך כו'. \u0004 עיין בס' גדולת מרדכי פ' הגוזל בתרא:","\u0003 שאנסוהו להראות כו'. \u0004 פירוש אף שנשא ונתן אח\"כ ביד וכדמסיק וכן פירש בסמ\"ע ס\"ק כ\"ו מתחלה ועיקר:","\u0003 מ\"מ חייב לשלם. \u0004 ל' מהרש\"ל פ' הגוזל בתרא ס\"ס נ' ואם הודה המוסר מעצמו כ\"כ בהגוזל קמא גבי דינא דגרמי שאינו קנס וא\"כ ממילא חייב לשלם בהודאתו וכן נמצא בשם הר\"י מקורבי\"ל בעל הסמ\"ק להדיא עכ\"ל ולא נהירא דאף דהוי קנס מ\"מ לא אמרינן מודה בקנס פטור רק גבי קנס דאורייתא ולא בקנס דרבנן וכן משמע בפוסקים וכן בתשו' מהרי\"ל סי' צ' גבי מסירת ר' דוד ור' ישי כ' דהוי מדרבנן ואפ\"ה כתב בסוף התשובה דאם מודה ר' דוד ישלם וכן הוא להדיא במרדכי פרק הגוזל בתרא וז\"ל ואם הודו כמה גרמו להם להפסיד חייבים לפרוע כל מה שהודו דאף על גב דמודה בקנס פטור ודינא דגרמי הוי קנסא דרבנן ה\"מ בקנס דאורייתא משום דכתיב אשר ירשיעון אלקי' פרט למרשיע עצמו אבל קנסא דרבנן מחייב בהודאת עצמו ושלו' אביגדור ברבי אליה הכהן עכ\"ל והוא פשוט:","\u0003 במקום שיש חשש שיחזור וימסרנו אם א\"א להציל עצמו בדרך אחר כו'. \u0004 כן צ\"ל:","\u0003 לכל המוסר כו' אין לו חל\"ה. \u0004 ואמרינן נמי בפ\"ק דר\"ה (דף י\"ז ע\"א) דהמסורות יורדים לגיהנם ונידונין לדורי דורות וגופן כלה ונשמתן כלה כו' ע\"ש ועוד הבאתי לקמן ס\"ק ס' בשם התוס' והגהת אשרי שהוכיחו דגריע מהשומדים. ובי\"ד סי' ב' סעיף ט' בהג\"ה נתבאר דיש פוסלין שחיטת מוסר כמו שחיטת מומר ובי\"ד סי' רפ\"א ס\"ג נתבאר דס\"ת שכתבו מוסר או עכו\"ם או ישראל מומר פסולה:","\u0003 ומותר להורגו כו'. \u0004 כשאומר הריני מוסר כו' היינו כשניכר שיעשה כן וע' בתשו' רשב\"א סי' קפ\"א:","\u0003 עשה המוסר אשר זמם כו'. \u0004 ובמרדכי ס\"פ הגוזל בתרא הביא תשו' מהר\"מ בר ברוך שכ' וז\"ל שוב מצאתי שהוכיח רבינו שמחה שהרי\"ף חולק על הרמב\"ם שהרי\"ף הביא ראיה דממון מוסר אסור לאבדו ביד מדמבעי' בפ' הכונס אם עשו תקנת נגזל במוסר או לא וסלקא בתיקו ואי ס\"ל להרי\"ף סברת הרמב\"ם מאחר שעשה המוס' כאשר זמם דאסור להורגו וא\"כ ה\"ה לאבד ממונו דאסו' דהא מיניה יליף ומה מביא ראיה דלמא הא דבפרק הכונס איירי כגון שעשה המוסר אשר זמם ומ\"ה אסור לאבדו אלא ש\"מ דלית ליה האי סברא עכ\"ד ועיין במהרש\"ל פרק הגוזל בתרא סי' נ' שהשיב ע\"ז ובספרי השגתי עליו והוכחתי שהעיקר מהש\"ס דפ' הגוזל בתרא כר' שמח' שאפילו בפעם אח' נקרא מוסר ומותר להורגו וכן משמע מהתוס' ופסקי תוס' פרק הגוזל בתרא אך הרבה פוסקים נמשכו לדעת הרמב\"ם בזה:","\u0003 אא\"כ הוחזק למוסר \u0004 שהרי זה יהרג שמא ימסור אחרים ומעשים בכל יום בערי המערב להרוג המוסרי' שהוחזקו למסור ממון של ישראל ולמסור המוסרים ביד העכו\"ם להרגם ולהכותם כפי רשעיהם עכ\"ל רמב\"ם פ\"ח מה' חובל דין י\"א והביאו בתשו' מהר\"מ בר ברוך שהביא המרדכי ס\"פ הגוזל בתרא ע\"ש וכ\"כ הסמ\"ג דף קמ\"ח ע\"ג בשם הרמב\"ם בקצרה משמע דהורגים אותו בידים וכן משמע מל' פסקי תוס' פ\"ב דעכו\"ם סי' מ\"א שכתבו מוסר מותר להרגו אפי' מסר כבר עכ\"ל וכן מוכח להדיא מתשובות מהר\"מ ב\"ב שהשיב להרשב\"א שהביא הב\"י ס\"ס זה וכן פסק הרשב\"א להדיא בתשו' ששלח לחכמי צרפת ולמלך וכתב וז\"ל המינים והמסורות מורידין ולא מעלין ואפי' להורגן בידים וכן עושים מעשה במוסר מוחזק להורגן בידים ברוב מקומות ישראל וכן העיד הרמב\"ם ז\"ל בחבורו כו' עכ\"ל והא דמורידים ולא מעלין (ברייתא בפ\"ב דעכו\"ם דף כ\"ז ע\"ב) אין מפרשים הרמב\"ם וסייעתו כמ\"ש הרא\"ש בתשו' בטור בשם ר\"ח דדוקא מורידין ולא הורגים בידים אלא ה\"ה להורגו בידים אלא דקא' מורידי' היכא דא\"א להורגו ויש לסבב הריגתו ע\"י הורד' וכן נראה מדברי הרמב\"ם פ\"ד מה' רוצח ועיין בי\"ד סי' קנ\"ח ס\"ב וכן נ\"ל עיקר בש\"ס מדקאמ' סוף פרק הגוזל בתרא ממון מוסר חד אמר מותר לאבדו ביד לא יהא ממונו חמור עליו מגופו משמע דגופו מותר לאבדו ביד:","ושוב ראיתי במהרש\"ל פרק הגוזל בתרא סי' נ' כתב בזה דנוכל לפרש דה\"ק מאחר שמותר להרוג המוסר ע\"י הורדה א\"כ כ\"ש שהממון מותר לאבדו בידים ע\"כ ולא נהירא לי דמ\"מ מאי ק\"ו הוא זה ועוד דלישנא דש\"ס לא משמע הכי וגם מ\"ש מהרש\"ל שם דמהרי\"ף נראה קצת דאוסר להרוג המוסר בידים כיון דהשמיט עובדא דרב כהנא דשמטיה לקועי' כו' אלמא שסובר רב כהנא עשה שלא כדין שהרגו כו' לא נהירא לי שחלילה שהרי\"ף יחשוב על רב כהנא שעש' שלא כדין וגם פשט' דש\"ס לא משמע הכי אלא נראה דמאחר שהביא הרי\"ף בסוף הפרק לא יהא ממונו חמור מגופו לא הוצרך להאריך ולהביא עובדא דרב כהנא וגם יתר דברי מהרש\"ל שם אינם מוכרחים לפע\"ד והנלפע\"ד כתבתי ועיין מ\"ש לקמן סעיף ט\"ו ס\"ק ס\"ו:","\u0003 הוחזק למסו' כו' \u0004 כ' בתשובת רשב\"א שהביא ב\"י מחודש ח' שהשיב לחכמי צרפת ולמלך ואיזו מוחזק כל שנודע לרבים שהוא כן לא שהוחזק בב\"ד של כ\"ג ושקבלו עדיו בפניו שא\"כ אין לך מוחזק עכשיו שאין לנו מומחים והרי החכמים מחברי הספרים שהעידו וכתבו שהמוסר המוחזק הורגים אותו בכ\"ז וכל הנעשה ענוותן ומרחם על אלו נעשה אכזר על דורו ע\"כ ובתשו' מהר\"מ ב\"ב שהשיב להרשב\"א שהביא בב\"י ס\"ס זה כ' הוחזק היינו ג' פעמים דאתחזק בין לר' בין לרשב\"ג ולא הרגשנו בו צד תשובה כל הקודם להורגו זכה דגדולה חזקה דהא סוקלין ושורפים על החזקות ע\"כ וכן הוא בתשו' הרא\"ש בטור ס\"ס זה והמחבר לקמן סעיף ט\"ו מי שמוחזק ששלשה פעמים מסר כו' וע' בש\"ס פרק הבא על יבמתו (סוף יבמות דף ס\"ד) ובסנהדרין פרק הנשרפים (סנהדרין דף פ\"א ע\"ב) במי שלקה ושינה שלישית מכניסים אותו לכיפה כו' ובהרמב\"ם פי\"ח מהלכות סנהדרין דין ד':","\u0003 שהרי זה יהרג וכו'. \u0004 וכ' הריב\"ש סי' רצ\"ו דמי שנתפס מפני שחייב מיתה אין מקבלין ממנו ערבית דמה נעשה לערבים אם יברח והביאוהו האחרונים:","\u0003 כל המוסר כו'. \u0004 כן הוא בכל ספרי המחבר ובעיר שושן וטעות הוא וצ\"ל כל המיצר וכן הוא בטור ורמב\"ם:","\u0003 מפני צער יחיד כו' \u0004 דווקא צער יחיד (וע\"ל ס\"ק מ\"ג דמי שרגיל להכות מותר למוסרו להציל שלא יכה עוד) אבל במוסר ליחיד דינו כמוסר לצבור מיהו אפשר דלהרמב\"ם דס\"ל דאם כבר מסר אין הורגין אותו אא\"כ הוחזק במוסר ס\"ל דבמוסר לצבור אפי' לא הוחזק מותר למוסרו ביד עכו\"ם:","\u0003 ואם גרם לו היזק. \u0004 יותר ממה שחייב להעכו\"ם:","\u0003 אסור לאבד ממונו של מוסר ביד. \u0004 אבל ע\"י גרמא או גרמי מותר טור בשם בעל העיטור ומהרי\"ו סי' ק\"ס ולמסור ממונו לעכו\"ם אסור כ\"כ מהרש\"ל פ' הגוזל בתרא ס\"ס נ' וע\"ש שהביא ראי' מעובדא דמסירות ר' יואל ור' אפרים במרדכי ולפ\"ז משמע דאם חזר ומסר ממונו חייב לשלם לו מה שהפסידו כדאי' במרדכי שם בההיא עובדא וכדלעיל סעיף ט' בהג\"ה ע\"ש ודוק:","ונראה דמי שמוחזק למסור ונראה שאין דבריו נשמעין רק מחמת עשרו וכשיעני לא יהיו דבריו נשמעים מותר לאבד ממונו או למוסרו לעכו\"ם שהרי במה שמאבדין ממונו מצילים אחרים. בתוס' פ\"ב דעכו\"ם דף כ\"ו ע\"ב נסתפקו אי משיבין אבדתו וכתבו דמוסר גרע ממומר ובכ\"מ שונה מוסר אצל מין ולא אתרבי אצל אבדה ושמא מאן דאית ליה ממון מוסר אסור לאבדו ביד אית להו נמי דמשיבין אבדתו ומטעמא דיכין רשע וצדיק ילבש עכ\"ל ובהגהת אשר\"י ס\"פ אלו מציאות כתבו דמוסר הוי כמו מומר להכעיס דאסור להחזיר אבדתו וע\"ש:","\u0003 וי\"א דמותר כו'. \u0004 והרי\"ף וסייעתו בע\"כ לא ס\"ל הכי וכן משמע במרדכי שם שבעל סברא זו חולק על הרי\"ף ומהרש\"ל שם סי' ן' פסק דאסור ליטול ממונו לעצמו וכן עיקר וכן משמע להדיא מתשו' רש\"י שבמרדכי פ\"ק דקידושין והביא' ב\"י לעיל ר\"ס רפ\"ג מחודש ב' ע\"ש:","\u0003 ואין צריכין לכוין העדות כל כך. \u0004 כלומר דאע\"ג דדיני נפשות צריך דרישה וחקירה כדלעיל סי' ל' במוסר אין מדקדקים כל כך כן הוא בטור סי\"ג בשם תשו' הרא\"ש וז\"ל ואלו רצו לקבל העדות לפניו ולדרוש ולחקור בדינו לעולם לא יעשה לו דין כי יציל ע\"י עכו\"ם כו' ויסכן כל ישראל כו':","\u0003 ע\"י גרמא. \u0004 כגון ע\"י הורדה לבור או ע\"י עכו\"ם כן הוא בטור בתשו' הרא\"ש והובא בסמ\"ע ס\"ק ל\"ה ומהרש\"ל פ' הגוזל בתרא סי' ן' חולק ופסק דע\"י עכו\"ם הוי כאלו הורגו בעצמו דהעכו\"ם יש שליח לד\"ע לחומרא ודוקא הורדה לבור שרי אבל ע\"י עכו\"ם אסור ואין דבריו מוכרחים גם שאר דברים שכ' שם אינם מוכרחים וע' מ\"ש בס\"ק שאח\"ז:","\u0003 אע\"פ שאסור להורגו. \u0004 באמת כ\"כ הטור תשו' הרא\"ש בשם ר\"ח אבל תימה על הר\"ב שכתב כן בפשיטות שהרי מדברי המחבר לעיל סעיף י\"א מבואר שיש להורגו וכן הבאתי לעיל ס\"ק נ\"ו שהוא דעת הרמב\"ם והרשב\"א ושאר הרבה פוסקים והבאתי ראיות לדבריהם ע\"ש ובסמ\"ע ס\"ק ל\"ה כ' שמדברי בעל העיטור מוכח דס\"ל כר\"ח ולפעד\"נ דבע\"ה לא קאי רק אממון ע\"ש:","\u0003 אם השליח הוחזק לעשות חייב המשלח כו'. \u0004 דין זה שכתבו הר\"ב והר\"ש בן צמח לא נהירא לי וז\"ל הרשב\"ץ ולא תימא אין שליח לד\"ע דלא מיפטר בה\"ט אלא בישראל אבל אם הוחזק במוסר ובאנס לאו ישראל הוא וכמו שכתב הרמב\"ם הל' עדות המוסרים הם פחותים מן העכו\"ם וכיון שכן אין למשלח טענה לפטור משום דברי הרב וכו' שזה מפורסם שאינו שומע דברי הרב עכ\"ל הביאו ב\"י ס\"ס זה ואין דבריו נכונים בעיני ולא מבעי' למה שפסקו הרמ\"ה והרא\"ש והנימוקי יוסף ושאר הרבה פוסקים כרב סמא בפ\"ק דמציעא לעולם אין שליח לד\"ע אפי' השליח לאו בר חיובא הוא כיון דאי בעי עביד ואי לא בעי לא עביד א\"כ פשיטא הכא פטור המשלח דהא הכא נמי אי בעי המוסר עביד אי בעי לא עביד תדע דהא כתבו הפוסקים הנ\"ל דלעולם לא משכחת שליח לד\"ע אלא חצר ואם איתא הא משכחת נמי מוחזק בכך אלא ודאי כמ\"ש אלא אפי' לרבינא דס\"ל דהיכא דהשליח לאו בר חיובא הוא מיחייב שולחו פטור הכא דס\"ס זה ישראל הוא ובר חיובא הוא ולא כתב הרמב\"ם דהם פחותים מן העכו\"ם אלא לענין דפסולים לעדות אבל מ\"מ ישראל הוא ובר חיובא הוא ומה בכך שהוחזק במוסר ס\"ס בר חיובא הוא והכי מוכח מדברי כל הפוסקים בכמה דוכתי שכתבו וסתמו אין שליח לד\"ע ולא חלקו בין שהשליח מוחזק בכך או לא. ועוד נראה דהרב לטעמיה אזיל דס\"ל לעיל ר\"ס קפ\"ב דהכל תלוי כשהשליח בר חיובא אבל כבר חלקתי שם עליו ע\"ש ונראה דגם הרשב\"ץ לא פסק כן בתשובה אלא משום שצירף עוד טעמים שם לזה וז\"ל ועוד שזה דומה לשליחות יד דחייבה רחמנא ע\"י שליח ועוד יש לחייבו כאילו מסרו אל האנס עצמו ואין אנו צריכין לבא עליו מדין שליח שכיון שהוחזק הזקן מוסר המוסר בידו כמוסר ביד האנס כו' עכ\"ל לפי עניות דעתי גם זה אינו נכון דנהי דשליחות יד חייב אף ע\"י שליח היינו בשולח יד בממון אבל כאן מה שליחות יד שייך ועוד דשולח יד הוי גזלן וכבר כתבתי לעיל סי' שפ\"ו ס\"ק י\"ג דשטרות אימעטי מגזלה ועוד דכיון דכתבתי לקמן בס\"ק שאח\"ז דאפילו מסר הוא עצמו השטרות להעכו\"ם פטור דלאו מידי עבד א\"כ כ\"ש כשמסרם למסור שימסרם לעכו\"ם. כן נראה לי ברור:","\u0003 וכן אם מסר שטר פרוע כו'. \u0004 ג\"ז מהרשב\"ץ ולא נהירא לי כלל ואפילו מסרו לשר גופיה פטור דליכא כאן גרמ' גם מ\"ש הרשב\"ץ בסוף דבריו וגדולה מזאת שאפילו היה ראובן המלוה ושמעון מסר שטרו ביד מוסר והפסיד חובו מיחייב שמעון מדין מוסר כו' עכ\"ל לא נהירא לי דאדרבא איפכא מסתברא בהך דראובן הוא המלוה דוקא חייב ולא מטעם מוסר אלא מטעם דכיון שהוא הפקידו אצלו והוא מוסרו למוסר קלייה לשטריה והוי כשורף שטורותיו של חברו דחייב מדינא דגרמי וכדאיתא בתשובת הרא\"ש כלל ל\"ט סי' ב' ונתבא' לעיל סי' ס\"ו ס\"ק קכ\"ז וסי' שפ\"ו ס\"ק כ\"ב אבל כשמס' שטרות פרועי' שלו לעכו\"ם ליכא כאן גרמי וכמ\"ש הרשב\"א להדיא בתשובה והביאו הב\"י לעיל סי' שפ\"ו מחו' א' והרב בד\"מ שם וז\"ל רואה אני לפטו' את שמעון אם עבר והחזיר השטר לעכו\"ם וכל שאינו זוכה מיד אינו קרוי דינא דגרמי אלא גרמא בניזקין ופטו' עכ\"ל וכ\"כ בתשובות מהר\"י לבית לוי סי' ל\"ד ובתשובת מהר\"ם אלשיך סי' קי\"ב דברי תשו' רשב\"א זו לפסק הלכה וכן בתשו' מהר\"מ מלובלין סי' ס\"א וכן בתשובת משאת בנימן סי' פ\"ה. שוב ראיתי בד\"מ שכתב ע\"ז וז\"ל וע\"ל סימן שפ\"ו דיש חולקין בזו ונראה דר\"ל תשו' הרשב\"א דלעיל שהביא בד\"מ שם. וא\"כ כ\"ש שיש לתמוה על הר\"ב שכתב כאן בסתם כדברי הרשב\"ץ וגם לענין דינא נ\"ל דברי הרשב\"א עיקר וכמ\"ש:"]],["\u0003הלכות נזקי ממון\u0004\n\u0010y0\u0011 כָּל נֶפֶשׁ חַיָּה שֶׁהִיא בִּרְשׁוּתוֹ שֶׁל אָדָם שֶׁהִזִּיקָה, חַיָּבִים הַבְּעָלִים לְשַׁלֵּם, שֶׁנֶּאֱמַר: וְכִי יִגֹּף שׁוֹר אִישׁ אֶת שׁוֹר רֵעֵהוּ, \u0010y1\u0011 אֶחָד הַשּׁוֹר וְאֶחָד שְׁאָר בְּהֵמָה חַיָּה וָעוֹף, לֹא דִבֵּר הַכָּתוּב בְּשׁוֹר אֶלָּא בַּהֹוֶה.\nוְכַמָּה מְשַׁלֵּם, אִם הִזִּיקָה בַּדְּבָרִים שֶׁדַּרְכָּהּ לַעֲשׂוֹת תָּמִיד כְּמִנְהַג בְּרִיָּתָהּ, כְּגוֹן בְּהֵמָה שֶׁאָכְלָה תֶּבֶן אוֹ עָמִיר, אוֹ שֶׁהִזִּיקָה בְּרַגְלָהּ \u0005(אוֹ)\u0006 בְּדֶרֶךְ הִלּוּכָהּ, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם \u0010y2\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו, שֶׁנֶּאֱמַר: מֵיטַב שָׂדֵהוּ וּמֵיטַב כַּרְמוֹ יְשַׁלֵּם. וְאִם שִׁנְּתָה וְעָשְׂתָה מַעֲשִׂים שֶׁאֵין דַּרְכָּהּ לַעֲשׂוֹת תָּמִיד, וְהִזִּיקָה בָּהֶם, כְּגוֹן שׁוֹר שֶׁנָּגַח אוֹ נָשַׁךְ, חַיָּב לְשַׁלֵּם חֲצִי נֶזֶק מִגּוּף הַמַּזִּיק עַצְמוֹ, שֶׁנֶּאֱמַר: וּמָכְרוּ אֶת הַשּׁוֹר הַחַי \u0010y3\u0011 וְחָצוּ אֶת כַּסְפּוֹ וְגוֹ'.\nכֵּיצַד, שׁוֹר שְׁוֶה מָנֶה שֶׁנָּגַח לְשׁוֹר שְׁוֶה עֶשְׂרִים וְהֵמִיתוֹ, וַהֲרֵי הַנְּבֵלָה שָׁוָה אַרְבָּעָה, בַּעַל הַשּׁוֹר הַמַּזִּיק חַיָּב לְשַׁלֵּם שְׁמֹנָה. וְאֵינוֹ חַיָּב לְשַׁלֵּם אֶלָּא מִגּוּף הַשּׁוֹר שֶׁהִזִּיק, שֶׁנֶּאֱמַר: וּמָכְרוּ אֶת הַשּׁוֹר הַחַי. \u0010y4\u0011\nלְפִיכָךְ, אִם הֵמִית שׁוֹר שְׁוֶה עֶשְׂרִים לְשׁוֹר שְׁוֶה מָאתַיִם, וְהַנְּבֵלָה שָׁוָה מָנֶה, אֵין בַּעַל הַנְּבֵלָה יָכוֹל לוֹמַר לְבַעַל הַחַי: תֵּן לִי חֲמִשִּׁים, אֶלָּא אוֹמֵר לוֹ: הֲרֵי שּׁוֹר שֶׁהִזִּיק לְפָנֶיךָ, קָחֵהוּ וָלֵךְ, אֲפִלּוּ אֵינוֹ שָׁוֶה אֶלָּא דִּינָר; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nהָעוֹשֶׂה מַעֲשֶׂה שֶׁדַּרְכּוֹ לַעֲשׂוֹת תָּמִיד כְּמִנְהַג בְּרִיָּתוֹ, הוּא הַנִּקְרָא מוּעָד. וְהַמְשַׁנֶּה וְעָשָׂה מַעֲשֶׂה שֶׁאֵין דֶּרֶךְ כָּל מִינוֹ לַעֲשׂוֹתוֹ כֵּן תָּמִיד, כְּגוֹן שֶׁנָּגַח אוֹ נָשַׁךְ, הוּא נִקְרָא תָּם. וְזֶה הַמְשַׁנֶּה, אִם הִרְגִּיל בְּשִׁנּוּיוֹ פְּעָמִים רַבּוֹת, נַעֲשָׂה מוּעָד לְאוֹתוֹ דָּבָר שֶׁהִרְגִּיל בּוֹ, שֶׁנֶּאֱמַר: אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא.\nחֲמִשָּׁה מַעֲשִׂים תַּמִּים יֵשׁ בַּבְּהֵמָה, וְאִם הוּעֲדָה לְאֶחָד מֵהֶם, נַעֲשֵׂית מוּעֶדֶת לְאוֹתוֹ מַעֲשֶׂה. וְאֵלוּ הֵם: הַבְּהֵמָה אֵינָהּ מוּעֶדֶת מִתְּחִלָּתָהּ לֹא לִגַּח, וְלֹא לִגֹּף, וְלֹא לִנְשֹׁךְ, וְלֹא לִרְבֹּץ עַל הַכֵּלִים גְּדוֹלִים, וְלֹא \u0010y5\u0011 לִבְעֹט; וְאִם הוּעֲדָה לְאֶחָד מֵהֶם הֲרֵי זוֹ מוּעֶדֶת לוֹ. אֲבָל הַשֵּׁן מוּעֶדֶת מִתְּחִלָּתָהּ לֶאֱכֹל אֶת הָרָאוּי לָהּ, וְהָרֶגֶל מוּעֶדֶת מִתְּחִלָּתָהּ לְשַׁבֵּר בְּדֶרֶךְ הִלּוּכָהּ.\nהַבְּהֵמָה, יֵשׁ מִי שֶׁאוֹמֵר שֶׁהִיא מוּעֶדֶת מִתְּחִלָּתָהּ לִרְבֹּץ עַל פַּכִּים קְטַנִּים וּלְמַעֵךְ אוֹתָם, וְיֵשׁ חוֹלְקִין עָלָיו.\nחֲמִשָּׁה מִינֵי חַיָּה מוּעָדִים מִתְּחִלַת בְּרִיָּתָן לְהַזִּיק, אֲפִלּוּ אִם הֵם בְּנֵי תַרְבּוּת, לְפִיכָךְ, אִם הִזִּיקוּ אוֹ הֵמִיתוּ בִּנְגִיחָה אוֹ בִּנְשִׁיכָה וּדְרִיסָה וְכַיּוֹצֵא בָּהֶם, חַיָּב נֶזֶק שָׁלֵם. וְאֵלוּ הֵם: הַזְּאֵב, וְהָאֲרִי, וְהַדֹּב, וְהַנָּמֵר, וְהַבַּרְדְּלָס; וְכֵן הַנָּחָשׁ שֶׁנָּשַׁךְ, הֲרֵי זֶה מוּעָד וַאֲפִלּוּ הָיָה בֶּן תַּרְבּוּת. \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא נָחָשׁ מוּעָד לְכָל מִינֵי הֶזֵּק, אֲבָל הָאֲחֵרִים אֵינָן מוּעָדִין אֶלָּא מַה שֶּׁדַּרְכָּן בְּכָךְ, \u0010y6\u0011 כְּגוֹן אֲרִי לִדְרֹס וּזְאֵב לִטְרֹף, אֲבָל לֹא אִפְּכָא (טוּר ס\"ג בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.\nכָּל מוּעָד מְשַׁלֵּם נֶזֶק שָׁלֵם מֵהַיָּפֶה שֶׁבִּנְכָסָיו; וְכָל תָּם מְשַׁלֵּם חֲצִי נֶזֶק מִגּוּפוֹ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁנִּכְנְסָה הַבְּהֵמָה לִרְשׁוּת הַנִּזָּק וְהִזִּיקַתְהוּ. אֲבָל אִם נִכְנַס הַנִּזָּק לִרְשׁוּת הַמַּזִּיק וְהִזִּיקַתְהוּ בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת, הֲרֵי זֶה פָּטוּר עַל הַכֹּל, שֶׁהֲרֵי הוּא אוֹמֵר לוֹ: אִלּוּ לֹא נִכְנַסְתָּ לִרְשׁוּתִי לֹא הִגִּיעַ לְךָ \u0010y7\u0011 הֶזֵּק. וַהֲרֵי מְפֹרָשׁ בַּתּוֹרָה, וְשִׁלַּח אֶת בְּעִירוֹ וּבִעֵר בִּשְׂדֵה אַחֵר. \u0005הַגָּה: כָּל זֶה לְשׁוֹן הָרַמְבַּ\"ם וְצָרִיךְ עִיּוּן, דְּמִקְרָא זֶה בְּשֵׁן וְרֶגֶל הוּא דִכְתִיב \u0010y8\u0011 לְפָטְרָן בִּרְשׁוּת שְׁנֵיהֶם, אֲבָל בִּרְשׁוּת הַמַּזִּיק דְּפָטוּר אֲפִלּוּ בְקֶרֶן אֵין עִנְיָן מִקְרָא זֶה טַעַם אֵלָיו, אֶלָּא דְּפָטוּר מִכֹּחַ דְּאָמַר לֵהּ: אִלּוּ לֹא נִכְנַסְתָּ כו'; \u0010y9\u0011 וְהָא דְּפָטוּר בִּרְשׁוּת הַמַּזִּיק, דַּוְקָא שֶׁנִּכְנָס שֶׁלֹּא בִּרְשׁוּת, אֲבָל נִכְנַס בִּרְשׁוּת, כְּגוֹן פּוֹעֲלִים הַנִּכְנָסִין לִתְבֹּעַ שְׂכָרָן, וּנְגָחָן שׁוֹרוֹ שֶׁל בַּעַל הַבַּיִת, חַיָּב (טוּר ס\"ה בְשֵׁם הָרֹא\"שׁ)\u0006. \u0010y10\u0011\nהִזִּיקָה בִּרְשׁוּת הָרַבִּים אוֹ בְּחָצֵר שֶׁאֵינָה שֶׁל שְׁנֵיהֶם, לֹא לְמַזִּיק וְלֹא לַנִּזָּק, אוֹ בְּחָצֵר שֶׁהִיא שֶׁל שְׁנֵיהֶם וַהֲרֵי הִיא מְיֻחֶדֶת לְהַנִּיחַ בָּהּ פֵּרוֹת וּלְהַכְנִיס לָהּ בְּהֵמָה, כְּגוֹן הַבִּקְעָה וְכַיּוֹצֵא בָּהּ, אוֹ שֶׁהִיא שֶׁל שְׁנֵיהֶם לְהַכְנִיס בָּהּ בְּהֵמָה וְאֵין שׁוּם אֶחָד מֵהֶם רַשַּׁאי לְהַכְנִיס בָּהּ פֵּרוֹת, אִם בְּשֵׁן וְרֶגֶל הִזִּיקָה כְּדַרְכָּהּ, הֲרֵי זֶה פָּטוּר, מִפְּנֵי שֶׁיֵּשׁ לָהּ רְשׁוּת לְהַלֵּךְ בְּכָאן, וְדֶרֶךְ הַבְּהֵמָה לְהַלֵּךְ וְלֶאֱכֹל כְּדַרְכָּהּ וּלְשַׁבֵּר בְּדֶרֶךְ הִלּוּכָהּ. וְאִם נָגְחָה אוֹ נָגְפָה אוֹ רָבְצָה אוֹ בָּעֲטָה אוֹ נָשְׁכָה, אִם תַּמָּה הִיא מְשַׁלֵּם חֲצִי נֶזֶק; וְאִם מוּעֶדֶת, נֶזֶק שָׁלֵם.\nהָיָה הֶחָצֵר שֶׁל שְׁנֵיהֶם מְיֻחֶדֶת לְפֵרוֹת וְלֹא לְהַכְנִיס בָּהּ בְּהֵמָה, וְהִכְנִיס שָׁם אֶחָד מֵהַשֻּׁתָּפִים בְּהֵמָה, וְהִזִּיקָה, חַיָּב אֲפִלּוּ עַל הַשֵּׁן וְעַל הָרֶגֶל.\nוְכֵן אִם הָיְתָה מְיֻחֶדֶת לִבְהֵמָה לִשְׁנֵיהֶם, וְהָיָה רְשׁוּת לְאֶחָד מֵהֶם בִּלְבַד לְהַכְנִיס לָהּ \u0010y11\u0011 פֵּרוֹת, וְהִזִּיקָה פֵרוֹתָיו, חַיָּב אַף עַל הַשֵּׁן וְעַל הָרֶגֶל.\nאִם הוּא שֶׁל אֶחָד מֵהֶם לְפֵרוֹת וְלֹא לִשְׁוָרִים, וְלַשֵּׁנִי לִשְׁוָרִים וְלֹא לְפֵרוֹת, וְהִזִּיקָה בְּהֶמְתּוֹ שֶׁל אוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לִשְׁוָרִים וְלֹא \u0010y12\u0011 לְפֵרוֹת לְאוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לְפֵרוֹת; בְּשֵׁן וְרֶגֶל \u0010y13\u0011 חַיָּב, דִּלְגַבַּיְהוּ הֲוָה לֵהּ חָצֵר הַנִּזָּק; בְּקֶרֶן פָּטוּר, דִּלְגַבֵּי דִידֵהּ הֲוָה לֵהּ חֲצַר הַמַּזִּיק. וְאִם הִזִּיקָה בְּהֶמְתּוֹ שֶׁל אוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לְפֵרוֹת לְאוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לִשְׁוָרִים; בְּקֶרֶן חַיָּב, דִּלְגַבֵּי דִידֵהּ הֲוָה לֵהּ חֲצַר הַנִּזָּק; בְּשֵׁן וְרֶגֶל פָּטוּר, דִּלְגַבַּיְהוּ הָוֵי חֲצַר הַמַּזִּיק:\nשֵׁן וְרֶגֶל, אֵין חַיָּבִין אֶלָּא אִם כֵּן הִזִּיקוּ בִּרְשׁוּת הַנִּזָּק; אֲבָל בִּרְשׁוּת הָרַבִּים פְּטוּרִים. וְאֵין צָרִיךְ לוֹמַר בִּרְשׁוּת הַמַּזִּיק. וּמִיהוּ, אִם הִתִּיז אֲבָנִים בִּרְשׁוּת הָרַבִּים וְהָלְכוּ וְהִזִּיקוּ בִּרְשׁוּת \u0010y14\u0011 הַנִּזָּק, אוֹ עֵץ אָרֹךְ, מִקְצָתוֹ בִּרְשׁוּת הָרַבִּים וּמִקְצָתוֹ בִּרְשׁוּת הַנִּזָּק, וְדָרְסָה עָלָיו \u0010y15\u0011 בִּרְשׁוּת הָרַבִּים וְשִׁבְּרָה כֵּלִים בִּרְשׁוּת הַנִּזָּק, חַיָּב.\nרְאוּבֵן שֶׁהִכְנִיס פֵּרוֹתָיו לַחֲצַר שִׁמְעוֹן שֶׁלֹּא בִּרְשׁוּתוֹ, וְנִכְנַס שׁוֹרוֹ שֶׁל לֵוִי שָׁם וַאֲכַלְתָּם, פָּטוּר. \u0005הַגָּה: אֲבָל אִם הִכְנִיס רְאוּבֵן פֵּרוֹתָיו בִּרְשׁוּת, וְנִכְנַס שׁוֹרוֹ שֶׁל לֵוִי שֶׁלֹּא בִרְשׁוּת, \u0010y16\u0011 חַיָּב, דְּהָוֵי כְּחָצֵר שֶׁל שֻׁתָּפִים וְנִכְנַס שָׁם שׁוֹר שֶׁל אֲחֵרִים לְהַזִּיק, דְּחַיָּב (הַגָּהוֹת מַיְמוֹנִי שם)\u0006.\nחָצֵר שֶׁהִיא שֶׁל שְׁנֵיהֶם לִשְׁוָרִים, וְלָאֶחָד מֵהֶם לִשְׁאָר דְּבָרִים, וְהִכְנִיס בָּהּ טַלִּיתוֹ, וַחֲבֵירוֹ שֶׁמְּיֻחֶדֶת לוֹ לִשְׁוָרִים הִכְנִיס בָּהּ שׁוֹרוֹ, וְהִזִּיק הַשּׁוֹר לַטַּלִית וְגַם הַטַּלִּית לַשּׁוֹר, \u0010y17\u0011 אֵין אוֹמְרִים יֵצְאוּ זֶה בְּזֶה, אֶלָּא שָׁמִין הַנִּזָּקִין בְּבֵית דִּין, וְכָל מִי שֶׁהִזִּיק יוֹתֵר, יְשַׁלֵּם:\nג' אָבוֹת נְזִיקִין בְּשׁוֹר: הַקֶּרֶן וְהַשֵּׁן וְהָרֶגֶל. וְנִקְרְאוּ אָבוֹת מִפְּנֵי שֶׁהֵם כְּתוּבִים בַּפָּסוּק; וְלָהֶם תּוֹלָדוֹת, שֶׁכָּל דָּבָר הַדּוֹמֶה לְאֶחָד מִכָּל אֵלּוּ נִקְרָא תּוֹלָדָה וְדִינוֹ כָּמוֹהוּ, חוּץ מִנֶּזֶק צְרוֹרוֹת \u0010y18\u0011 כְּמוֹ שֶׁיִּתְבָּאֵר\nכֵּיצַד, שׁוֹר הָאָמוּר בַּתּוֹרָה הוּא שֶׁנָּגַח בְּקֶרֶן, וְאֵין דַּרְכּוֹ בְּכָךְ אֶלָּא דֶרֶךְ מִקְרֶה, וְאֵין לוֹ הֲנָאָה בְּהֶזֵּקוֹ; וְכָל הַדּוֹמֶה לוֹ דִּינוֹ כְּמוֹתוֹ, כְּגוֹן שֶׁנָּגְפָה בְּגוּפָהּ אוֹ נָשְׁכָה אוֹ בָעֲטָה אוֹ רָבְצָה עַל כֵּלִים וְשִׁבַּרְתָּם; \u0010y19\u0011 וְכֵן אִם אָכְלָה כְּסוּת אוֹ כֵּלִים, דִּינָהּ כְּקֶרֶן וְאֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֶזֶק, בֵּין בִּרְשׁוּת הַנִּזָּק בֵּין בִּרְשׁוּת הָרַבִּים. וְעוֹד יֵשׁ דְּבָרִים שֶׁמָזִּיקָה בְּרַגְלָהּ אוֹ בְפִיהָ וְדִינָם כְּקֶרֶן, וְיִתְבָּאֲרוּ בְּסִימָן ש\"צ.\nפָּרָה שֶׁרָבְצָה בִּרְשׁוּת הָרַבִּים, וְהָלְכָה פָרָה אַחֶרֶת דֶּרֶךְ עָלֶיהָ וּבָעֲטָה בָּהּ, \u0010y20\u0011 אַף עַל פִּי שֶׁזֹּאת שִׁנְּתָה וְרָבְצָה, אֵין לַמְּהַלֶּכֶת לִבְעֹט בָּהּ. אֲבָל אִם הִזִּיקָה דֶרֶךְ הִלּוּכָהּ, פְּטוּרָה:",["\u0003כל נפש חיה שהיא ברשותו של אדם. ודוקא כגון בהמ' שאינ' בר דעת אבל עבד שיש לו דעת אין רבו חייב על נזקיו שאם הי' חייב על נזקו אם יקניטנו רבו ילך ויזיק את רבו בכל יום ב\"כ הטור בסי' שמ\"ט וגם בסי' זה כתבו בקיצור.\u0004","\u0003אחד השור וא' בהמה. \u0004 דילפי' שור שור משבת ועד\"ר שכתבתי בשם ב\"י לימוד אחר אבל זה נ\"ל עיקר:","\u0003מהיפה שבנכסיו. \u0004 כבר נתבאר דאם משלם לו במטלטלין משלם לו המזיק במה שירצה שהרי כתיב ביה כסף ישיב ללמד שנפרע אפי' בסובין וכמ\"ש לקמן בסי' ת\"ג ובסי' תי\"ט בדברי הטור והמחבר אלא שבאם משלם לו קרקעות צריך לשלם בו מהיפה מנכסיו וגם בא לו' שבדברים כאלו שהוא בהן מועד אינו משתלם מגופו של שור המזיק לחוד ושבאם נגנב או נאבד לא יצטרך לשלם לו המזיק מביתו או לא ימלא לו דמי נזקו על דמי השור המזיק וכדין תם אלא צריך לשלם מכיסו וכמו שמבאר והולך ומ\"ה כ' הטור שמשלם מהעלייה וזהו ג\"כ דעת הרי\"ף שכ' שמשלם לו מהעידית ועפ\"ר:","\u0003וחצו את כספו: \u0004 וכתיב בתריה וגם את המת יחצון והתור' איירי בשווין שור שוה עשרים שהזיק שור שוה עשרים והמיתו והנבילה שוה עשרה שכשיחצו ויטלו כל א' חצי החי וחצי המת נמצא שנשתלם זה חצי נזקו דמעיקרא דאף שלא נחסר לו מעיקרא אלא עשרה והוא נוטל מהחי שוה עשרה מ\"מ הרי המזיק נוטל מהנבלה חמשה ואותן חמש' שהוא כדי חצי נזקו דמעיקרא הוא אשר יחסר לו והתשלומין דחצי נזקו יהא בענין זה דחמש' גובה מגוף המזיק וה' השניים המזיק ישלם לו אותו במה שירצה או משורו החי או מהנבילה שזיכה לו התורה מהניזק וזהו בשוים דאיירי בו התורה ומהשווי' נלמד לשאינו שוים וכמ\"ש ואזיל בסעיף שאחר זה (והוא ג\"כ מדברי הרמב\"ם) שכשנגח שור שוה מנה לשור שוה עשרים והנבילה שוה ארבע' כשיחצה הניזק הנבילה עם המזיק וקיבל ממנו שתים והמזיק צריך לחצות עמו שור השוה כ\"כ כמו שהי' שוה שור הניזק דהיינו עשרים ויתן ממנו עשרה לניזק ועל אותן עשר' משלם לו המזיק בדמי חצי נבילתו דהיינו שתי' שהרי על הניזק לטפל בנבילתו כדלקמן ונמצא דלא נשאר על המזיק ליתן לו אלא שמנה וק\"ל:","\u0003לפיכך אם המית כו'. \u0004 פי' לפיכך כיון דאינו משלם המזיק מביתו אלא מדמי שור המזיק לפיכך לפעמים אומר לו קחהו ולך:","\u0003ואם הועד' לאחד מהן \u0004 פי' שהותרו בבעליו לשומרו אחר שעשתה כן ג' פעמים:","\u0003כגון ארי לדרוס כו'. \u0004 לשון הטור בשם ר\"י כגון ארי לדרוס ולאכול או לטרוף ולהניח לפיכך באחד מאלו הוא מועד וחייב עליו ברשות הניזק נ\"ש ופטור בר\"ה כדין רגל אבל אם טרף ואכלו לאו אורחיה הוא וה\"ל כקרן תמה וחייב ח\"נ אפילו ברשות הניזק וזאב ושאר חיות דרכם בטריפה ולזה הן מועדין וכו'. אבל בדריסה לאו אורחייהו וה\"ל כקרן תמה ונחש נמי מועד מתחילתו ודרכו בכל מיני היזקות כו' עכ\"ל וכוונתו מפני שהארי הוא מלך בחיות ולא ישוב מפני כל אין ממתין להבהמה שדורס עד שתמות אלא דורס עליה ברגלו ואוכלה או טרפה ברוגזו לשני חתיכות ומניחה ואינה אוכלה אבל זאב ושאר חיות מפני מורך לבבם אינם אוכלים בעוד טורפם חי ומנענע וזהו זאב טורף ואוכל כ\"כ הרא\"ש ונחש שהמית אע\"פ שאינה נהנית כיון שדרכה בכך ולא בזה רוגזה ה\"ל מועד לכל דבר ועד\"ר:","\u0003והרי מפורש בתורה ושילח את בעירה וביער ובגמ' דרשו \"דושלח היינו היזק רגל ע\"י הליכתו וביער היינו היזק דשן דביערו על ידי אכילתו:\u0004","\u0003לפטרן ברשות שניהן \u0004 דבשדה אחר משמע שדה של אחר והיינו כשהיא מיוחדת להניזק ולא כשהיא של שניהן וכ\"ש כשהזיק בר\"ה שהוא מקום שכל הבהמות הולכין שם ברשות דפטור בעל המזיק מתשלומי שן ורגל דכיון דאורחתא דהבהמה היא לאכול בשן הראוי לאכול ולדרוס ברגל את כל המונח בדרך והניזק היה לו לשמור את הדבר שהיזק מלהניחו בדרך שהכל דשין בו משא\"כ כשהזיק בקרן והדומה לו דלאו אורחיה היא דלא ה\"ל לניזק לשמור מדבר דלאו אורח הבהמות להזיק בו מ\"מ חייב ח\"נ אפי' בר\"ה כמ\"ש המחבר בסעיף שאח\"ז. ונראה לישב תמיהת מור\"ם ז\"ל והוא דגם דעת הרמב\"ם והמחבר שכתבו והרי מפורש בתורה כו' לא אדסמיך ליה קאי אלא באו ליתן טעם אמ\"ש ברישא בד\"א כשנכנס' לרשות הניזק דממעט גם כשנכנס לרשות שניהן דהיינו מהאי קרא וכדי שלא תאמר מנ\"ל דהאי קרא אתא למעט גם כשנכנס לרשות שניהן דלמא לא אתא למעט אלא כשנכנס לרשות המזיק מ\"ה הקדים וכ' דלזה ודאי לא אתא דלרשות המזיק לא צריך קרא דסברא הוא דפטו' שהרי מצי א\"ל אילו לא נכנסת כו' וק\"ל:","\u0003והא דפטו' ברשות המזיק כו' \u0004 ענין בפני עצמו הוא וגם הטו' כתבו אמ\"ש לפני זה דאם הניזק נכנס לרשות המזיק והוזק דפטו' המזיק אם הפועלים נכנסים לרשותו ופעמים חייב ופעמים פטור ע\"ש ומסיק וכתב עליה בשם הרא\"ש דבזמן הזה דאין בעל הבית רגיל להמחות פועליו לחנוני אלא לפורעם במזומנים ואין רגיל לשלם להם בשוק כי אם בביתו ששם יש לו מעות מ\"ה לעולם נקראו נכנסים ברשות וחייב בניזקן ע\"ש:","\u0003הזיקה בר\"ה כו'. \u0004 סעיף זה וסעיף שלאחריו נתבא' ממ\"ש בסעיף שלפני זה ע\"ש:","\u0003והזיקה פירותיו חייב כו'. \u0004 דאף דיש להמזיק רשות להכניס שם שורו מכל מקום כיון שניתן להניזק רשות לבד להכניס שם פירותיו חצר הניזק קרינן ליה לענין היזק פירות ועפ\"ר מ\"ש עוד מזה ומדכתב חייב אף על השן והרגל ר\"ל וכל שכן אם הזיקה בקרן דהא אקרן חייב בכל מקום ועיין מ\"ש בסמוך:","\u0003לאותו שמיוחדת לו לפירות בשן ורגל כו' \u0004 בפריש' ודריש' הוכחתי דכל שהזיק הבהמה להפירות קרי לה שן ורגל על שם המקרא שנא' ושלח את בעירה וביער כו' דמיירי הבהמה הזיק' בשן ורגל וכל שהזיק' בהמה לבהמה קרי לה קרן ע\"ש המקרא שנא' כי יגח שור איש את שור רעהו והשתא אתי שפיר דסתם המחבר וכתב והזיקה בשן ורגל ר\"ל לפירות. בקרן פטור ר\"ל שהזיק בהמה דבעל השוורים לבהמה דבעל הפירות שהכניס' שלא ברשות ומ\"ש אח\"כ שאם הזיק' בהמתו דבעל הפירות לבעל השוורים בקרן ר\"ל לבהמתו דבעל השוורים גם מ\"ש בסוף בשן ורגל פטור ר\"ל ששניהן שינו דבעל הפירות הכניס הבהמה ובעל השוורים הכניס פירות והזיקה הבהמה להפירות פטור ואבהמתו הנזכר לפני זה קאי וקאמ' דאם אותה הבהמה הנזכרת הזיקה לבעל השוורים בשן ורגל פטור. אבל אין לפרש דמ\"ש ברישא בקרן פטור דר\"ל אם הזיק שורו של זה שניתן לו רשות לשוורים לפירותיו של השני בבעיט' או ברביצה דמקרי ג\"כ קרן דפטו' דאם כן קשה מ\"ש מהי' מיוחד לשניהן לשוורים ולא' מהן לשאר דברים והכניס בו טליתו והזיק השור להטלית בדריסתו עליו שכ' הטור והמחב' בסמוך בסי' ז' דחייב בעל השור על היזק הטלית וכתבתי שם דמוכח דל\"ד במיוחד לשניהם לשוורים איירי אלא ה\"ה במיוחד לזה לשוורים ולזה לטלית ע\"ש. וגם בסי\"ג כתב בסופו ז\"ל חייב אף על השן והרגל ור\"ל וכ\"ש על הקרן ש\"מ דאם הזיקה הבהמה לפירות בקרן דחייב מיהו לפי מ\"ש פי' דשן ורגל וקרן גם שם בס\"ס י\"ג יש לפרש דמ\"ש דחייב אף על השן והרגל דר\"ל וכ\"ש אם הזיק' בהמה דקה בקרן דחייב ומשלם דאקרן חייב בכל מקום אפי' ברה\"ר ודוק ועפ\"ר מ\"ש עוד בהוכחות פירוש זה שכתבתי ודו\"ק:","\u0003דלגבייהו ה\"ל חצר הניזק. \u0004 ר\"ל לגבי שן ורגל וטעמו כיון שיש לו רשות להכניס פירותיו ומ\"ש בסיפא דלגבייהו ה\"ל חצר המזיק כ\"כ ג\"כ הטו' ול\"ד קאמ' אלא ר\"ל דל\"ה חצר הניזק כיון שלא הי' מיוחד לו לפירות אלא להמזיק גם מ\"ש הטו' והמחב' לפני זה בחיובו דקרן משום דהוי לגבי דידי' חצר הניזק ל\"ד קאמ' דהא קרן חייב גם בר\"ה ובחצר של שניהן או שאינן של שום א' מהן אם לא בחצ' המזיק וכנ\"ל אלא משום דהאי חצר אינו מיוחד אלא לאחד מהן או למזיק או לניזק מ\"ה כתב האמת וק\"ל ועפ\"ר מ\"ש לכל זה עוד הוכחות וראיות:","\u0003או עץ ארוך כו'. \u0004 כל' זה כתב ג\"כ הטו' ובפרישה כתבתי דאין חיובן שוה דבדרכו על עץ ארוך כו' חייב עליו נזק שלם ובהתיז אבנים בר\"ה אינו חייב אלא ח\"נ דהיינו נזק צרורות וכמ\"ש הטו' והמחב' בסי' שאחר זה:","\u0003ושיברה כלים ברשות הניזק חייב. \u0004 ול\"ד לדרס' ע\"ג כלים ונתגלגל למקום אחר ושבר דקי\"ל דבתר מעיקרא אזלינן דשאני הכא דהנזק נעשה ברשות הניזק והניזק מעולם הי' שם:","\u0003דהוי כחצר של שותפין \u0004 פי' דבעל החצר וזה שנתן לו רשות להכניס הן שותפין בהחצ' ונקרא חצר הניזק לגבי זה שנכנס שם שלא ברשות:","\u0003אין אומרים יצאו זה בזה \u0004 פי' שלא תימא כיון דשניהם שוים בהכנסתם ה\"ל לכל אחד לשמור את שלו שלא יהא ניזק ולא יזקקו ב\"ד להן:","\u0003כמו שיתבאר. \u0004 בסימן שאחר זה:","\u0003וכן אם אכלה כסות כו' דאע\"ג דבשן הוה מועד מעיקרא ה\"מ בדבר שדרכו לאכול ולא כסות וכה\"ג:\u0004","\u0003אע\"פ דזאת שינתה \u0004 פי' וקי\"ל כל המשנה ובא אחר ושינה בו פטור וכמ\"ש בסי' שצ\"ה מ\"מ אין להאחרת רשות לבעוט בה:"],[]],["רֶגֶל הִיא אָב, שֶׁוְשִׁלַּח אֶת בְּעִירֹה הַכָּתוּב בַּתּוֹרָה, הוּא \u0010y0\u0011 שֶׁהַבְּהֵמָה הוֹלֶכֶת בְּרַגְלֶיהָ וּמַזֶּקֶת בְּדֶרֶךְ הִלּוּכָהּ, וְהוּא דָּבָר שֶׁדַּרְכָּהּ בְּכָךְ וְאֵין לָהּ בּוֹ הֲנָאָה. וְכָל הַדּוֹמֶה לִדְבָרִים אֵלּוּ הוּא תּוֹלְדוֹתָיו, וְדִינוֹ כְּמוֹתוֹ. כֵּיצַד, כְּגוֹן שֶׁהִזִּיקָה בְּגוּפָהּ דֶּרֶךְ \u0010y1\u0011 הִלּוּכָהּ, אוֹ בִּשְׂעָרָה, אוֹ \u0010y2\u0011 בְשָׁלִיף \u0005(פֵּרַשׁ הַבַּרְטְנוּרָא בָּרִאשׁוֹן מִקַמָּא שָׁלִיף, מַשּׂאוֹי בְּאַמְתָּחוֹת וּמַרְצוּפִין)\u0006 שֶׁעָלֶיהָ, אוֹ בִּפְרוֹמְבִּיָּא \u0005(פֵּרוּשׁ, רֶסֶן)\u0006 שֶׁבְּפִיהָ, אוֹ בַּזּוּג שֶׁבְּצַוָּארָהּ, אוֹ בְּמַשּׂוֹי שֶׁעָלֶיהָ; וְתַרְנְגוֹלִים שֶׁהָיוּ פּוֹרְחִים מִמָּקוֹם לְמָקוֹם וְשָׁבְרוּ כֵּלִים בְּכַנְפֵיהֶם, אוֹ שֶׁהָיוּ \u0010y3\u0011 מְהַדְּסִין \u0005(פֵּרוּשׁ מְהַדְּסִין, עִנְיָן דְּרִיסָה וּרְקִידָה)\u0006 עַל גַּבֵּי עִסָה אוֹ פֵרוֹת וְטִנְּפוּם \u0010y4\u0011 אוֹ נִקְּרוּ בָּהֶם, וְכֵן כָּל דָּבָר הַמְחֻבָּר בְּגוּפָהּ, כְּגוֹן עֶגְלָה הַמּוֹשֶׁכֶת בְּקָרוֹן וְהוֹלִיכָתָהּ עַל גַּבֵּי הַכֵּלִים וְשִׁבַּרְתָּם, כָּל אֵלּוּ תוֹלָדוֹת הָרֶגֶל וְדִינָם כָּמוֹהוּ. \u0010y5\u0011\nכִּשְׁכְּשָׁה בִּזְנָבָהּ כִּשְׁכּוּשׁ רַב שֶׁאֵין דַּרְכָּהּ לַעֲשׂוֹת תָּמִיד, וְהִזִּיקָה בִּרְשׁוּת הָרַבִּים; אוֹ שֶׁכִּשְׁכְּשָׁה בַּגִּיד שֶׁלָּהּ בִּרְשׁוּת הָרַבִּים וְהִזִּיקָה, פָּטוּר. וְאִם תָּפַס הַנִּזָּק, גּוֹבֶה חֲצִי נֶזֶק מִמַּה שֶׁתָּפַס, שֶׁזֶּה הַדָּבָר סָפֵק הוּא אִם אֵלּוּ תּוֹלְדוֹת הַקֶּרֶן שֶׁחַיָּב עָלֶיהָ בִּרְשׁוּת הָרַבִּים, אוֹ תוֹלְדוֹת הָרֶגֶל שֶׁפָּטוּר עָלֶיהָ בִּרְשׁוּת הָרַבִּים. \u0005הַגָּה: \u0010y6\u0011 \u0010c0\u0011 וְיֵשׁ אוֹמְרִים דִּבְכָל סְפֵקָא דְדִינָא לָא מְהַנֵּי תְּפִיסָה, וְלָכֵן אֲפִלּוּ אִם תָּפַס מַפְקִינָן מִנֵּהּ (טוּר ס\"א בְּשֵׁם ר\"י)\u0006 \u0005(וע\"ל סִימָן שכ\"א)\u0006. וּלְדַעַת הָרֹא\"שׁ דְּכִשְׁכְּשָׁה בִּזְנָבָהּ לָא הֲוֵי סָפֵק, וַדַּאי פָטוּר \u0005(טוּר שָׁם הֵבִיאוֹ)\u0006.\nכָּל תּוֹלָדָה כְּאָב שֶׁלָּהּ, חוּץ מִצְּרוֹרוֹת הַמִּנַּתְּזִין מִתַּחַת רַגְלֵי הַבְּהֵמָה בִּשְׁעַת הִלּוּכָהּ, שֶׁאַף עַל פִּי שֶׁתּוֹלְדוֹת רֶגֶל הֵם וּפָטוּר עֲלֵיהֶם בִּרְשׁוּת הָרַבִּים כְּרֶגֶל, וְאִם הִזִּיקוּ בִּרְשׁוּת הַנִּזָּק מְשַׁלֵּם מֵהַיָּפֶה שֶׁבִּנְכָסָיו כְּרֶגֶל שֶׁהוּא אָב, אַף עַל פִּי כֵּן אֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֶזֶק. כֵּיצַד, בְּהֵמָה שֶׁנִּכְנְסָה לַחֲצַר הַנִּזָּק וְהָיוּ צְרוֹרוֹת מִנַּתְּזִין מִתַּחַת רַגְלֶיהָ וְשָׁבְרוּ אֶת הַכֵּלִים, מְשַׁלֵּם חֲצִי נֵזֶק \u0010y7\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו; \u0010y8\u0011 וְדָבָר זֶה הֲלָכָה לְמֹשֶׁה מִסִינַי. \u0010y9\u0011\nוְכֵן אִם הָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וְנִתְּזוּ צְרוֹרוֹת מִתַּחַת רַגְלֶיהָ לִרְשׁוּת הַנִּזָּק וְשָׁבְרוּ אֶת הַכֵּלִים, מְשַׁלֵּם חֲצִי \u0010y10\u0011 נֶזֶק. וְהוּא הַדִּין לְתַרְנְגוֹלִים \u0010y11\u0011 שֶׁהִדְּסוּ וְהֶעֱלוּ עָפָר אוֹ צְרוֹרוֹת וְשָׁבְרוּ, וְכֵן חֲזִיר שֶׁהָיָה נוֹבֵר בְּאַשְׁפָּה וְהִתִּיז צְרוֹרוֹת וְהִזִּיק, מְשַׁלֵּם חֲצִי נֵזֶק.\nדָּרְסָה עַל הַכְּלִי בִּרְשׁוּת הַנִּזָּק וְשִׁבַּרְתּוֹ, וְנָפַל עַל כְּלִי אַחֵר וְשִׁבְּרוֹ, \u0010y12\u0011 עַל הָרִאשׁוֹן מְשַׁלֵּם נֶזֶק שָׁלֵם, וְעַל הָאַחֲרוֹן מְשַׁלֵּם חֲצִי נֶזֶק. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהוּא הַדִּין לְכֹחַ כֹּחוֹ. \u0005הַגָּה: דָּרְסָה עַל הַכְּלִי וְלֹא נִשְׁבַּר, וְנִתְגַּלְגֵּל לְמָקוֹם אַחֵר וְנִשְׁבַּר שָׁם, \u0010y13\u0011 מְשַׁלֵּם נֶזֶק שָׁלֵם (טוּר ס\"ב)\u0006. \u0010y14\u0011\nהָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים, וּבָעֲטָה וְהִתִּיזָה צְרוֹרוֹת, וְהִזִּיקוּ בִּרְשׁוּת הָרַבִּים, פָּטוּר. וְאִם תָּפַס הַנִּזָּק רְבִיעַ נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ; שֶׁהַדָּבָר סָפֵק הוּא שֶׁמָּא שִׁנּוּי הוּא וְאֵינוֹ תּוֹלָדַת רֶגֶל, שֶׁהֲרֵי בָּעֲטָה.\nבָּעֲטָה בָאָרֶץ בִּרְשׁוּת הַנִּזָּק וְהִתִּיזָה צְרוֹרוֹת מֵחֲמַת הַבְּעִיטָה וְהִזִּיקָה שָׁם, חַיָּב לְשַׁלֵּם רְבִיעַ נֶזֶק, שֶׁזֶּה שִׁנּוּי הוּא בְּהַתָּזַת צְרוֹרוֹת. וְאִם תָּפַס הַנִּזָּק חֲצִי נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ. וַאֲפִלּוּ הָיְתָה מְהַלֶּכֶת \u0010y15\u0011 בְּמָקוֹם שֶׁאִי אֶפְשָׁר לָהּ שֶׁלֹּא תַּתִּיז. וּבָעֲטָה וְהִתִּיזָה, מְשַׁלֵּם רְבִיעַ נֶזֶק. וְאִם תָּפַס הַנִּזָּק חֲצִי נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: (ר\"י וְהָרֹא\"שׁ)\u0006 וּכְבָר נִתְבָּאֵר דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא \u0010y16\u0011 מְהַנֵּי תְּפִיסָה בִּסְפֵק דִּינָא:\nבְּהֵמָה שֶׁהֵטִילָה גְלָלִים לְעִסָה, הַיְנוּ צְרוֹרוֹת. וּכְגוֹן דְּדָחִיק לָהּ עָלְמָא שֶׁאֵין לָהּ מָקוֹם לִנְטוֹת אָנֶה וָאָנָה, דְּאִי לָאו הָכִי \u0010y17\u0011 הָוֵי שִׁנּוּי וְתוֹלָדָה דְקֶרֶן הוּא.\nכְּשֵׁם שֶׁחַיָּב עַל כֹּחַ שֶׁיֵּשׁ בּוֹ מַמָּשׁ שֶׁהִתִּיז צְרוֹרוֹת, כָּךְ חַיָּב עַל כֹּחַ שֶׁאֵין בּוֹ מַמָּשׁ, כְּגוֹן סוּס שֶׁצָּנַף \u0005(פֵּרוּשׁ, צְנִיפָה בְּסוּס כְּמוֹ נְעִירָה בַּחֲמוֹר וּנְבִיחָה בְכֶלֶב וּשְׁאָגָה בְּאַרְיֵה)\u0006 וַחֲמוֹר שֶׁנּוֹעֵר וְשָׁבְרוּ כֵּלִים בְּכֹחַ קוֹלָם, וְתַרְנְגוֹל שֶׁשָּׁבַר כֵּלִים בְּרוּחַ כְּנָפָיו אוֹ שֶׁהוֹשִׁיט רֹאשׁוֹ לַאֲוִיר כְּלִי, וְתָקַע בּוֹ, וּשְׁבָרוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁיֵּשׁ בּוֹ זֵרְעוֹנִים, \u0010y18\u0011 דְּהַשְׁתָּא הָוֵי אוֹרְחֵהּ; אֲבָל אִם אֵין בּוֹ זֵרְעוֹנִים הָוֵי שִׁנּוּי, וְלֹא דַּיָּנִין לֵהּ הַשְׁתָּא. \u0010y19\u0011\nהַתַּרְנְגוֹלִים מוּעָדִים לְהַלֵּךְ כְּדַרְכָּן וּלְשַׁבֵּר. \u0005(אוֹ)\u0006 הָיָה חוּט אוֹ רְצוּעָה קָשׁוּר בְּרַגְלֵיהֶם, וְנִסְתַּבֵּךְ כְּלִי בְּאוֹתוֹ הַחוּט וְנִתְגַּלְגֵּל וְנִשְׁבַּר, מְשַׁלֵּם חֲצִי נֶזֶק. \u0005הַגָּה: זֶהוּ לָשׁוֹן הָרַמְבַּ\"ם, וְהוּא סָתוּם; אֲבָל אֲחֵרִים כָּתְבוּ: הָיָה חוּט אוֹ מְשִׁיחָה קְשׁוּרָה בְּרַגְלֶיהָ, אִם גָּרְרָה וְשִׁבְּרָה בּוֹ כְּלִי דֶרֶךְ הִלּוּכָהּ, \u0010y20\u0011 מְשַׁלֵּם נֶזֶק שָׁלֵם; \u0010y21\u0011 זְרָקוֹ וְשָׁבַר בּוֹ, מְשַׁלֵּם חֲצִי נֶזֶק. (וְאִם הִזִּיק אַחַר שֶׁנָּח, פָּטוּר)\u0006 בַּמֶּה דְּבָרִים אֲמוּרִים, בְּחוּט שֶׁל הֶפְקֵר אוֹ שֶׁיֵּשׁ לוֹ בְּעָלִים וְהִצְנִיעוֹ וְנִקְשַׁר מֵאֵלָיו; אֲבָל אִם הַחוּט שֶׁל בַּעַל הַתַּרְנְגוֹל וְלֹא הִצְנִיעוֹ, אֲפִלּוּ נִקְשַׁר מֵאֵלָיו וְשָׁבַר עַל יְדֵי זְרִיקָה, חַיָּב נֶזֶק שָׁלֵם \u0005(טוּר ס\"ג)\u0006, דַּחֲצִי נֵזֶק דִּצְרוֹרוֹת אֵינוֹ \u0010y22\u0011 אֶלָּא בְּהִתִּיזָה דְּבַר הֶפְקֵר, אֲבָל אִם הִתִּיזָה דָבָר \u0005(שֶׁיֵּשׁ לוֹ בְּעָלִים)\u0006 וְלֹא הִצְנִיעוֹ, חַיָּב נֶזֶק שָׁלֵם. וְאִם הַחוּט שֶׁל אֲחֵרִים, \u0010y23\u0011 בַּעַל הַחוּט חַיָּב, בֵּין הִזִּיק הַתַּרְנְגוֹל דֶּרֶךְ גְּרִירָה אוֹ דֶרֶךְ זְרִיקָה, הוֹאִיל וְלֹא הִצְנִיעַ חוּט שֶׁלּוֹ. וְאִם הִזִּיק הַחוּט לְאַחַר שֶׁנָּח, חַיָּב מִשּׁוּם \u0010y24\u0011 בּוֹר הַמִּתְגַּלְגֵּל. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּתַרְנְגוֹל שֶׁל הֶפְקֵר; אֲבָל אִם יֵשׁ לַתַּרְנְגוֹל בְּעָלִים, אִם הִזִּיק דֶּרֶךְ גְּרִירָה \u0010y25\u0011 שְׁנֵיהֶם מְשַׁלְּמִין בְּיַחַד. וְאִם הִזִּיק דֶּרֶךְ זְרִיקָה, \u0010y26\u0011 בַּעַל הַתַּרְנְגוֹל נוֹתֵן רְבִיעַ וּבַעַל הַחוּט שְׁלֹשָׁה חֲלָקִים. \u0010y27\u0011 וְאִם הִזִּיק לְאַחַר שֶׁנָּח, בַּעַל הַתַּרְנְגוֹל פָּטוּר וּבַעַל הַחוּט חַיָּב הַכֹּל. \u0005(וְעַיֵּן לְקַמָּן סִימָן תי\"א יִתְבָּאֵר בְּדִינֵי בוֹר)\u0006. וְכָל זֶה בְּנִקְשַׁר מֵאֵלָיו, אֲבָל אִם קְשָׁרוֹ אָדָם בְּרֶגֶל הַתַּרְנְגוֹל אָז הַקּוֹשֵׁר חַיָּב בְּכָל עִנְיָן, \u0010y28\u0011 אֲפִלּוּ יֵשׁ לַחוּט בְּעָלִים \u0005(טוּר)\u0006. וְהוּא הַדִּין אִם הָיָה הַחוּט מֻנָּח בְּמָקוֹם מֻצְנָע, וְהִנִּיחַ אָדָם בִּמְקוֹם תֻּרְפָּה וְעַל יְדֵי זֶה נִקְשַׁר בַּתַּרְנְגוֹל, הָוֵי כְּאִלּוּ קְשָׁרוֹ בְּיָדַיִם \u0005(בֵּית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת שָׁם וּבְשֵׁם הָרֹא\"שׁ)\u0006.\nתַּרְנְגוֹל שֶׁהָיָה מְחַטֵּט בְּחֶבֶל דְּלִי וְנִפְסַק הַחֶבֶל וְנִשְׁבַּר הַדְּלִי, אִם עִסָה דְבוּקָה בַּחֶבֶל דְּהַשְׁתָּא \u0010y29\u0011 אוֹרְחֵהּ הוּא, אוֹ אֲפִלּוּ אֵין בּוֹ עִסָה וְהוּא בָלוּי שֶׁדַּרְכּוֹ לִפָּסֵק עַל יְדֵי חַטִּיטַת הַתַּרְנְגוֹל, חַיָּב בֵּין עַל הַחֶבֶל בֵּין עַל הַדְּלִי נֶזֶק שָׁלֵם. וְאִם הַחֶבֶל חָדָשׁ וְאֵין עִסָה דְּבוּקָה בּוֹ, מְשֻׁנֶּה הוּא וְאֵינוֹ חַיָּב אֶלָּא חֲצִי נֶזֶק בֵּין עַל הַחֶבֶל בֵּין עַל הַדְּלִי, \u0010y30\u0011 וְאִם הוּא הוֹלֵךְ אַחַר הַדְּלִי וּמְגַלְגְּלוֹ עַד הַמָּקוֹם שֶׁנִּשְׁבַּר שָׁם, מְשַׁלֵּם נֶזֶק שָׁלֵם.\nהַכֶּלֶב וְהַגְּדִי שֶׁקָּפְצוּ מֵרֹאשׁ הַגַּג מִלְמַעְלָה לְמַטָּה וְשָׁבְרוּ אֶת הַכֵּלִים, מְשַׁלְּמִים נֶזֶק שָׁלֵם \u0010y31\u0011 מִפְּנֵי שֶׁמּוּעָדִים הֵם לְדָבָר זֶה. וְכֵן אִם נָפְלוּ וְהִזִּיקוּ, שֶׁעֲלִיָּתָן לְרֹאשׁ הַגַּג פְּשִׁיעָה; וְאַף עַל פִּי שֶׁנְּפִילָתָן \u0010y32\u0011 אֹנֶס, כָּל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ בְּאֹנֶס, חַיָּב. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם הָיוּ הַכֵּלִים סְמוּכִים לַכֹּתֶל, שֶׁאֵין רְאוּיִין לִשָּׁבֵר עַל יְדֵי קְפִיצָה, וְנָפְלוּ, פָּטוּר, דְּאֹנֶס הוּא. וְאִם הַכְּלִי אָרֹךְ וְרֹאשׁוֹ אֶחָד קָרוֹב לַכֹּתֶל וְרֹאשׁ הַשֵּׁנִי רָחוֹק בְּעִנְיָן שֶׁרָאוּי לִשָּׁבֵר עַל יְדֵי קְפִיצָה, וְנָפְלוּ קָרוֹב לַכֹּתֶל וְשָׁבְרוּ, חַיָּב, דִּתְחִלָּתוֹ בִּפְשִׁיעָה עַל יְדֵי קְפִיצָה. וְאִם הַכֹּתֶל צַר, אֲפִלּוּ קְרוֹבִים לַכֹּתֶל וְנָפְלוּ, \u0010y33\u0011 חַיָּב, וְהוּא שֶׁקָּפְצוּ כְּדַרְכָּם; אֲבָל אִם קָפַץ הַכֶּלֶב בִּרְקִידָה וְהַגְּדִי נִסְרַךְ, דְּהָוֵי \u0010y34\u0011 שִׁנּוּי גַבַּיְהוּ, אֵין מְשַׁלְּמִין אֶלָּא חֲצִי נֶזֶק (טוּר ס\"א)\u0006. קָפְצוּ מִלְּמַטָּה לְמַעְלָה, מְשַׁלְּמִים חֲצִי נֶזֶק. \u0010y35\u0011 \u0005וְהוּא\u0006 שֶׁנִּתְלָה הַגְּדִי וְנִסְרַךְ, וְקָפַץ הַכֶּלֶב. אֲבָל נִסְרַךְ הַכֶּלֶב, וְדִלֵּג הַגְּדִי, בֵּין מִלְמַעְלָה לְמַטָּה בֵּין מִלְּמַטָּה לְמַעְלָה, חַיָּבִים נֶזֶק שָׁלֵם. וְכֵן תַּרְנְגוֹל שֶׁדִּלֵג בֵּין מִלְמַעְלָה לְמַטָּה בֵּין מִלְּמַטָּה לְמַעְלָה, מְשַׁלֵּם נֶזֶק שָׁלֵם. וְהוּא הַדִּין מִי שֶׁמָּסַר בֵּיתוֹ \u0010y36\u0011 לְשָׁמְרוֹ וְהָיוּ בּוֹ חֵרֵשׁ שׁוֹטֶה וְקָטָן, צָרִיךְ לְשָׁמְרָם שֶׁלֹּא יְדַלְּגוּ מִלְמַעְלָה לְמַטָּה וְלֹא מִלְּמַטָּה לְמַעְלָה:",["\u0003ה\"ג שהבהמה הולכת ברגלי' ומזקת בדרך הילוכה \u0004 וכ\"כ הטור ר\"ס זה ע\"ש:","\u0003או בשער' \u0004 פי' שנסתבך כלים בשער' וגרר' ושברן:","\u0003בשליף שעלי' \u0004 הוא משאוי שנטען עליה המונח באמתחת במרצופין רש\"י. ומ\"ש המחבר אחר זה או במשוי שעלי' ר\"ל משוי שהוא בעין הנטען עליה:","\u0003מהדסין \u0004 פי' שמרקדין:","\u0003או נקרו בהן \u0004 ומאסוהו בנקירתן אף שלא אכלוהו דאל\"כ ה\"ל תולד' דשן דהא יש לו הנאה באכילתו:","\u0003כשכשה בזנבה כו' \u0004 ז\"ל הטור אם כשכשה בדרך כל הבהמות (פי' ושיבר' כלי דרך כשכושה) ודאי אורחיה הוא פי' והוי דינו ברגל שפטור על מה שהזיק בר\"ה ועל הזיקו ברשו' הניזק חייב נ\"ש אבל בכשכש רב (פי' אם הזיק מכח כשכש רב ואי לא הוי מכשכש אלא כדרך שאר הבהמות לא הוי משתבר הכלי) מיבעיא אי הוי כאורח' וכ' הרמב\"ם דלא איפשט' לי' אבל הרא\"ש כ' דאיפשט' דהוה אורח' והוי תולד' דרגל ואם כשכשה בגיד שלה (ועי\"ז שברה הכלי לכ\"ע) הוא איבעיא דלא אפשטא כו' ע\"ש ועל פי זה נתבאר לך דברי המחב' ומה שכ' מ\"ו ר' משה אסרלש ז\"ל עליו בהג\"ה דהמחב' כ' כדברי הרמב\"ם דס\"ל דכשכש רב דזנבו וסתם כשכש דגיד שלה שוין הן ושניהן הן איבעיות דלא איפשט' בגמ' אי תולדה דקרן הוא או תולד' דרגל והמע\"ה ומ\"ה אי לא תפסו הניזק והזיקה בר\"ה אין לו כלו' דיכול המזיק לומ' תולדה דרגל הוא ואם הזיקה ברשות הניזק אינו משלם אלא ח\"נ ממ\"נ אבל אם תפס ונעשה הנזק ברשות הניזק צריך לשלם נ\"ש דיד התופס על העליונ' ויאמר תולד' דרגל הוא ואם בר\"ה נעשה הנזק יאמר התופס תולדה דקרן הוא וצריך לשלם חצי נזק והיינו דוקא לדעת הרמב\"ם דס\"ל דמהני תפיסה אף במקום שהוא ספק לנו אי הוה קרן או רגל ועל זה כ' מור\"ם די\"א (והוא ר\"י והרא\"ש) דלא מהני תפיס' בספיק' דדינ' ועוד כ' דלדעת הרא\"ש אם כשכש בזנבו כשכש (שאינו) רב אפשט' האיבעיא דהוה אורחא ותולדה דרגל היא ואם הזיקה ברשות הרבים פטור לגמרי אפי' למ\"ד דמהני תפיסה לספיק' דדינא דכאן אין ספק אלא ודאי אורחא הוא ומינה דאם הזיקה ברשות הניזק דמשלם נזק שלם אפי' לדעת ר\"י והרא\"ש כיון דודאי אורחא הוא וה\"ל למור\"ם לכתוב ג\"כ צד חיובו דכשכש בזנבו כשכוש שאינו רב ברשות הניזק אלא דחדא באידך תליא וצד החיוב נלמד מצד הפטור כנ\"ל:","\u0003דבכל ספיקא דדינא לא מהני תפיסה כו'. \u0004 והיינו בדבר שהוא איבעיא וכנ\"ל אבל ג\"כ מודים דאם הזיקה ברשו' הניזק דאינו משלם אפי' חצי נזק בלא תפיסה דכיון דלא איפשטא יש לומ' דלא הוה אורחא ותולדה דקרן הוא וקרן אינו משלם חצי נזק אלא מגופו וכמ\"ש הטור והמחב' בסימן א' וגם בסימן זה כתבו הטור ע\"ש ומ\"ה בעינן שיתפוס גופו דהמזיק דוקא וישלם ממנו ח\"נ ועד\"ר והטור מסיק וכ' בזה ז\"ל ואפי' אם היזק לאדם אחד בר\"ה וברשות הניזק דינא הכי ואינו יכול לומ' ממ\"נ אם תאמר שהוא קרן תתחייב לי גם כן ברה\"ר וא\"ת שהוא רגל (ומ\"ה תפטר על הזיקו בר\"ה אם כן) תן לי נזק שלם הזיקו דרשות הניזק אלא בשניהן להקל עד כאן לשון הטור ואע\"ג דכתב הטור והמחב' בסי' א' בספיקא דדינא אי כליו של לוקח ברשות מוכר או איפכא קונים וקנה אחד מחבירו בשניהן דקנה בא' מהן ממ\"נ שאני הכא דהוא ענין דקנסא דהא גופו לא הזיק אלא שורו שהוא ממונו מ\"ה הולכין בשניהן להקל ועד\"ר:","\u0003מהיפה שבנכסיו. \u0004 כבר כתבתי פירושו דמשלם המזיק ג\"כ מכיסו ולאו דוקא מהשור כדין קרן:","\u0003ודבר זה הלכה למשה מסיני \u0004 פי' אע\"פ שהדברים נראין כסותרין זא\"ז שיש לו דין רגל לענין פטור בר\"ה ולענין חיוב תשלומין מנכסיו יש לו דין קרן שאינו משלם אלא חצי נזק אף ברשות הניזק מ\"ה כ' דהלכה למשה מסיני. כן הוא ואין להרהר אחריה:","\u0003וכן אם היתה מהלכת בר\"ה כו'. \u0004 קמ\"ל בזה דאע\"ג דצרורות דין רגל יש לו ופטור על הזיקו בר\"ה מ\"מ כיון דהצרורות נתזו משם ברשות הניזק בתר הניזק אזלינן וחייב:","\u0003וה\"ה לתרנגולים כו'. \u0004 שכל שאורחא הוא והיזק בא מכחו דין צרורות יש לו:","\u0003שהדסו והעלו עפר. \u0004 פי' ברשות הניזק או ברשות הרבים ונתזו לרשות הניזק והזיקו וכנ\"ל:","\u0003על הראשון משלם נ\"ש כו'. \u0004 דהראשון נשבר ברגלו והשני נשבר בצרורות:","\u0003משלם נ\"ש. \u0004 כיון דהשבירה בא מכח הדריסה על הכלי עצמו הולכין אחר התחלתו והוי מרגל עצמו ולא מצרורות. משא\"כ בהיתה מהלכת בר\"ה והתיזה צרורות לרשות הניזק דאזלינן בתר מקום שנשבר שם וכנ\"ל:","\u0003היתה מהלכת בר\"ה ובעט' כו'. \u0004 כ\"מ שנזכ' התזת צרורות היינו צרורות באורחי' דהוא תולדה דרגל ומשלם ח\"נ וברשות הניזק דוקא ובר\"ה פטו' לגמרי כדין רגל וכנ\"ל וכל היכא דנזכ' צרורו' בבעיט' ה\"ל צרורות בשינוי דדרך הבהמות לילך ולהתיזו להשליך צרורות דרך הילוכה אבל לא בבעיטה דהיינו שמכה ברגליה בכח דרך אחוריה ומכח זה נתזין הצרורות למקום אחר וכבר נתבא' בטו' ובדברי המחב' בס\"ס שפ\"ט דהבעיטה בבהמה שינוי הוא וקמבעיא בגמ' אם יש שינוי בצרורות כיון שבאין מכח הבעיטה או אין שינוי ופירשו הרמב\"ם דבכלל איבעיא זו אי יש שינוי לצרורות הוא קולא וחומרא קולא דאפי' ברשות הניזק רביע הוא דמשלם ותו לא והיינו שינוי דכמו שתם כיון שנשתנה ממועד אינו משלם אלא ח\"נ דמועד ה\"נ שינוי דצרורות אין משלמין אלא ח\"נ מצרורות דעלמא והיינו רביע וחומרא נמי דאפי' בר\"ה הוא משלם כדין קרן כיון דהוא משונה ואינו אורח' משא\"כ כשאמרי' דאין שינוי לצרורות דאז יש לו דין צרורות דהוי אורחי' ופטו' בר\"ה דומה לרגל וגם כן חייב עליהן ח\"נ ברשות הניזק כדין צרורות ואיבעיא זו עלתה בתיקו וסבירא ליה להרמב\"ם והמחב' דאזל בשיטתי' דמהני תפיסה לספיקא דדינא וכנ\"ל ועל פי זה יתבארו דברי המחב' מ\"ש דאם בעטה והזיק' ברשות הרבים פטו' היינו דאמרי' המע\"ה ושמא אין שנוי לצרורות דבעיטה ויש לו דין רגל דפטו' בר\"ה ואם תפס ידו על העליונה לו' יש שינוי לצרורות ויש לו דין קרן לחייב ברשות הרבים מיהו כיון דהתופס בא לתפוס ולילך לחומרא לו' יש שינוי א\"כ עליו ג\"כ לקבל צד הקולא דהיא ביש שינוי דהיינו דאינו משלם ברשות הרבים אלא רביע נזק חצי דין קרן ואפי' אותו רביע אינו משלם אלא כשתפס גוף השור המזיק דהא קרן דתם אינו משלם אלא מגופו וכנזכ' לעיל וזה שסיים המחב' בטעמו וכתב שהדב' ספק כו' שהוא טעם לכולן וכמו שכתבתי ומסיק וכתב דאם בעטה והזיקה ברשות הניזק חייב לשלם רביע על כל פנים דאף אם הוא קרן ויש שינוי לצרירות עכ\"פ חצי צרורות חייב לשלם והיינו רביעית מיהו גם רביע זה אינו משתלם אלא מגופו דהמזיק וכנ\"ל ואם תפס החצי ואפילו תפס דבר אחר אין מוציאין מידו דיכול לו' אין שינוי לצרורות והוה תולדה דרגל ומשתלם ברשות הניזק חציו אפילו מכיסו דהמזיק:","\u0003במקום שא\"א לה שלא תתיז. \u0004 ג\"ז איבעיא בגמ' ומשום דבזה יש סברא לו' דה\"ל דין רגל טפי אף שבא מחמת בעיטה כיון דאפילו בלא בעיטה ג\"כ היתה מתזת צרורות כיון שהוא מקום שא\"א לה שלא תתיזה ואפ\"ה כיון דאיבעיא דלא איפשטא הוא דינא כאיבעיא שלפני זה בבעטה והתיזה והיה אפש' לה שלא תתיז:","\u0003מהני תפיסה כו' \u0004 ולדעתם כתב הטור דאם היזק בר\"ה מפקינן מיניה וברשות הניזק אי תפס גוף המזיק גובין לו ממנו רביע הנזק עד כאן לשונו וטעמו הוא פשוט על פי מה שאמר דהמע\"ה וכיון דלא מהני ביה תפיסה לעולם הניזק ידו על התחתונה:","\u0003הוי שינוי \u0004 דאין דרך הבהמה להטיל גללים לעיסה:","\u0003דהשתא הוי אורחא. \u0004 פי' אורחא להושיט שם ראשו כדי לאכול וכל שאורחא להושיט שם ראשו רגיל גם כן לצעוק ולתקוע:","\u0003התרנגולים מועדים כו'. \u0004 עד ונתגלגל ונשבר משלם ח\"נ זהו ל' הרמב\"ם והוא סתום כו' ע\"ש ברמב\"ם דכת' עוד פרטי דינים בתרנגול וחוט קשר ברגליו ומחלת במי קשרו ובשל מי הי' החוט ועל רוב דבריו השיג שם הראב\"ד ואפש' דמשום הכי לא העתיקם המחב' אלא שקשה דא\"כ גם בבא זו דנתגלגל ונשב' משלם ח\"נ לא הי' לו להעתיק דגם עליה השיג הראב\"ד שם גם מור\"ם לא היה לו לכתוב עליה ל' והוא סתם שהרי הרמב\"ם ביאר דבריו שם וכ' עליה בד\"א כו' אלא שהפוסקים חולקים על דבריו ונראה דהמחב' העתיק מדברי הרמב\"ם ריש דבריו משום דנוכל לקיימן אליבא דהלכתא ולפרש' דמיירי בחוט של הפק' וכששוב' דרך זריקה דאז גם שאר הפוסקים ס\"ל דמשלם בעל התרנגול ח\"כ וכדמסיק מור\"ם ג\"כ ואף שהרמב\"ם כ' שם ע\"ז בד\"א וגילה דלא איירי בהכי מ\"מ ניחא לי' להמחב' להעתיק לשונו מאי דאפשר לקיימו ומור\"ם כ' עלו והוא סתום ור\"ל דהמחב' העתיק סתימת דבריו אבל פירושו זה הוא דחוק וצ\"ע:","\u0003משלם נזק שלם \u0004 דהוי רגל:","\u0003זרקו ושבר \u0004 דה\"ל צרורות:","\u0003אלא בהתיזה דבר הפקר \u0004 דומיא דצרורות דהם הפקר:","\u0003בעל החוט חייב \u0004 פירוש כל הנזק אם התרנגול הוא של הפקר וכדמסיק ומטעם דבעל החוט הוה ליה לשמור חוטו שלא יסתבך בו התרנגול של הפקר:","\u0003בור המתגלגל \u0004 פי' אף שלא הניחו בעל החוט במקום שהזיק מ\"מ יש לו דין בור שחוטו יש לו דין בור שנתגלגל ממקום שהניחו למקום שנח עתה ע\"י התרנגול והיזק שם וכ' שם הטו' דאם היזק אחר שנח פטור על הזיק כלי' שנזקו בו כמו שכ' הטו' בסי' ת\"י כדין בור דדרשינן חמור ולא כלים (אבל מה דדרשינן שור ולא אדם היינו דוקא אם ימית האדם בנפילתו לבור ומכח החוט לא ימות משא\"כ כלי הנשבר דשבירתו זו היא מיתתו) משא\"כ בהיזק דרך גרירא או זריקה דאז חיובו מכח רגל או אשו וחייב על הכל:","\u0003שניהם משלמין ביחד. \u0004 דגם בעל התרנגול פשע דהוה ליה לשמור התרנגול:","\u0003בעל התרנגול נותן רביע. \u0004 דזריקה דתרנגול ה\"ל כצרורות דשור דאינו משלם אלא ח\"נ והשתא דאיכא לבעל החוט לשלם בהדיה אין עליו אלא חצי חיובו דהיינו רביע הנזק וג' חלקים על בעל החוט דהא בעל החוט אי הוה הוא לבדו כגון שהתרנגול היה הפקר היה מחויב לשלם כולו:","\u0003ואם הזיק לאחר שנח \u0004 דדרשינן כי יכרה איש בור ולא שור בור מ\"ה אין צד חיוב בזה על בעל התרנגול אף אם החוט היה הפקר והזיק אחר שנח:","\u0003אפי' יש לחוט בעלים \u0004 כן הוא ג\"כ לשון הטו' והו\"מ למימר רבותא טפי אפילו אם יש גם לתרנגול בעלים וצ\"ל דס\"ל דאין בזה צד רבותא טפי דכל נזק שבא מצד התרנגול ודאי זה הקושר הוא חייב בו ולא בעל התרנגול כיון דהדר הוא ולקחו וקשרו בתרנגול נעשה בו בעל ולא אתא לאשמועינן אלא דחייב גם בחיובו דבעל חוט דהוא בעל התקלה דחוט אף שאינו תולה הזיקה בתרנגול וק\"ל:","\u0003או אפי' אין בו עיסה כו'. \u0004 פי' אף שאין בו עיסה דרך התרנגול לחטט בחבל דלי שהוא רטוב למצות מים לשתות וזהו שייך בין שהחבל הוא ישן או חדש אלא שאין דרך החדש להפסיק מכח מציצ' מים כזו אבל אם יש בו עיסה חוטט בו טובא ואף כשהוא חדש פוסק לפעמים.","\u0003ואם הוא הולך אחר הדלי כו'. \u0004 אבל אם אינו הולך אחר הדלי אינו משלם אלא ח\"נ ול\"ד לדורס הכלי ונתגלגל הכלי למקום אחר דנתבאר בסי' זה דאזלינן בתר התחלת הדריס' וה\"ל רגל וחייב נ\"ש דשאני דריס' דאורחיה הוא משא\"כ פסיקת חבל חדש בזה דשינוי הוא ועד\"ר:","\u0003מפני שמועדין הן כו'. \u0004 פי' וה\"ל לבעליהן לשומרן שלא יקפצו ויזיקו:","\u0003כל שתחלתו בפשיע' וכו'. \u0004 וזה אונס הבא מחמת הפשיעה דאילו שמרם מהפשיעה לא הוי בא לידי נפילה מהגג ומיהו אין דרכם לקפוץ אלא רחוק קצת מהכותל ומ\"ה אם היו כלים סמוכים לכותל דאז לא פשע מתחל' במה שלא שמרם כיון שאין דרכן ליפול ובקפיצתן אינן יכולין להשתבר ומ\"ה כתב הטור וכתבו מור\"ם בהג\"ה דאם נפלו והזיקו דבעליהן פטורין:","\u0003ומ\"ש והוא שקפצו כדרכן. \u0004 פי' שדרך הגדי לקפוץ בזקירה אחת מלמעלה למטה משא\"כ הכלב שרגיל לסרוך ולנעץ צפרנו בצידי הכותל ומאחז בה ויורד ולבסוף קופץ:","\u0003אין משלמין בזה אלא ח\"נ \u0004 ואין אומרים בזה כיון שפשע מתחלה לענין שאם יקפצו כדרכן שיחייב נ\"ש דהא מ\"מ התורה לא חייבה על היזק הבא ע\"י שינוי אלא ח\"נ דומיא דתם שהזיק בקרן ומשום דלאו אורחיה הוא ה\"ל שינוי לגבייהו:","\u0003והוא שנתלה הגדי כו'. \u0004 כן הוא דעת הרי\"ף והרמב\"ם דס\"ל דלמעלה למטה בכל ענין חייב נ\"ש ודוקא בקפצו מלמטה למעלה בו חילקו בגמרא בין קפצו כדרכן או דרך שינוי ועד\"ר שהארכתי בגרסתם בגמ' ושל הרא\"ש והטור הי' ולהן גירסא אחרת בדברי הרי\"ף והרמב\"ם ממה שהי' בפני הב\"י:","\u0003והי' בו חש\"ו. \u0004 דאלו עבדו כבר נתבאר בסי' שמ\"ט ושפ\"ט דאין אדם חייב על נזקי עבדו ואילו הזיקו הוא עצמו כבר נתבאר דאדם מועד לעולם בין ער בין ישן על כל מה שיזיק ודוק:"],["\u0003 וי\"א דבכל ספיקא דדינא כו'. \u0004 וכ\"פ מהרש\"ל פ' כיצד הרגל סי' ה' וז' ועמ\"ש לעיל סי' שפ\"ח סעיף א' ועיין בסמ\"ע ס\"ק ז' עד דהוא ענין דקנסא דהא גופו לא הזיק וכו' אין לזה טעם כלל וכבר השיג עליו הב\"ח גם מ\"ש הב\"ח דמיירי בב' בהמות שהזיקו לא נהירא אלא נראה אף בבהמה אחת כיון דמבעיא אי אורחא היא ואין כוונתה להזיק או כוונתה להזיק והוי קרן א\"כ יכול לו' דלמא טבע הבהמה לפעמי' הוא כך ולפעמים כך ודלמא בר\"ה הזיקה דרך הלוכה כי אורחא ולא הי' כוונתה להזיק וברשות הניזק היתה כוונת' להזיק וקרן הוא ודוק כן נ\"ל ברור:"]],["שֵׁן הִיא אָב, \u0010y0\u0011 דִּוְשִׁלַּח אֶת בְּעִירֹה \u0005(וּבִעֵר)\u0006 דִּכְתִיב בַּקְּרָא, מוֹקְמֵינָן לָהּ \u0010y1\u0011 נַמֵּי בִּבְהֵמָה שֶׁאוֹכֶלֶת פֵּרוֹת חֲבֵרוֹ דְּבָרִים הָרְאוּיִים לָהּ וְנֶהֱנֵית בַּאֲכִילָתָן חַיָּב נֶזֶק שָׁלֵם, בֵּין שֶׁאֲכָלָתָן בֵּין שֶׁלֹּא אֲכָלָתָן אֶלָּא שֶׁהִפְסִידָתָן \u0010y2\u0011 וְלֹא כִּלְּתָה אוֹתָם לְגַמְרֵי. לְפִיכָךְ, כָּל הַדּוֹמֶה לְזֶה, שֶׁמַּזִּיק בְּדָבָר שֶׁהִיא נֶהֱנֵית, הוּא תּוֹלָדָה דְשֵׁן; כְּגוֹן \u0010y3\u0011 נִתְחַכְּכָה בַכֹּתֶל לַהֲנָאָתָהּ וְהִזִּיקָה, אוֹ שֶׁטִּנְּפָה פֵרוֹת וְכֵלִים לַהֲנָאָתָהּ, כְּגוֹן שֶׁנִּתְגַּלְגְּלָה עֲלֵיהֶם:\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁאָכְלָה דָּבָר הָרָאוּי לָהּ. אֲבָל אָכְלָה דָּבָר שֶׁאֵין רָאוּי לָהּ, כְּגוֹן כְּסוּת וְכֵלִים, שִׁנּוּי הוּא וְאֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֶזֶק, \u0010y4\u0011 בֵּין שֶׁאָכְלָה אוֹתָם בַּחֲצַר הַנִּזָּק בֵּין שֶׁאָכְלָה אוֹתָם בִּרְשׁוּת הָרַבִּים.\nאָכְלָה דָּבָר שֶׁאֵין דַּרְכָּהּ לֶאֱכֹל אֶלָּא עַל יְדֵי הַדְּחַק, כְּגוֹן פָּרָה שֶׁאָכְלָה שְׂעוֹרִים, וַחֲמוֹר שֶׁאָכַל כַּרְשִׁינִין, וְכֶלֶב שֶׁלָּקַק אֶת הַשֶּׁמֶן, וַחֲזִיר שֶׁאָכַל חֲתִיכַת בָּשָׂר, וְחָתוּל שֶׁאָכַל תְּמָרִים, חָשִׁיב שַׁפִּיר אֲכִילָה. אֲבָל בְּהֵמָה שֶׁאָכְלָה בָּשָׂר אוֹ תַבְשִׁיל, לָאו אֹרְחָא הוּא, וּמְשַׁלֵּם חֲצִי נֶזֶק. אָכְלָה פַּת הָוֵי אֹרְחָא, אֲבָל חַיָּה לָאו אֹרְחָא לֹא בְּפַת וְלֹא בְּתַבְשִׁיל.\nבְּהֵמָה שֶׁרָאֲתָה לֶחֶם בְּסַל, וְשִׁבְּרָה הַסַל וְאָכְלָה הַלֶּחֶם, מְשַׁלֵּם נֶזֶק שָׁלֵם גַּם עַל הַסַל, שֶׁכָּךְ דַּרְכָּהּ לְשַׁבֵּר הַסַל כְּדֵי לֶאֱכֹל הַלֶּחֶם. אֲבָל אִם אָכְלָה הַלֶּחֶם תְּחִלָּה וְאַחַר כָּךְ שָׁבְרָה הַסַל, אֵינוֹ מְשַׁלֵּם עַל הַסַל אֶלָּא חֲצִי נֶזֶק, דְּהָוֵי קֶרֶן וְאֵינוֹ מִשְׁתַּלֵּם אֶלָּא מִגּוּפוֹ.\nרָאֲתָה אֳכָלִים עַל פִּי הֶחָבִית, וְנִסְתַּבְּכָה בֶּחָבִית לַעֲלוֹת כְּדֵי לֶאֱכֹל הָאֳכָלִים וְשִׁבַּרְתּוֹ, מְשַׁלֵּם גַּם עַל הֶחָבִית נֶזֶק שָׁלֵם, שֶׁכֵּן דַּרְכָּם לַעֲלוֹת עָלָיו כְּדֵי \u0010y5\u0011 לֶאֱכֹל הָאֳכָלִים.\nחַיָּה שֶׁטָּרְפָה בְּהֵמָה וַאֲכַלְתָהּ, אוֹ שֶׁאָכְלָה בָּשָׂר חַי, אֹרְחָא הִיא וּמְשַׁלֵּם נֶזֶק שָׁלֵם. אֲבָל כֶּלֶב שֶׁהֵמִית כֶּבֶשׂ, וְחָתוּל שֶׁהֵמִית תַּרְנְגוֹלִים גְּדוֹלִים וַאֲכָלָם, מְשֻׁנֶּה הוּא וְאֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֵזֶק. וְדַוְקָא בִּפְחָת שֶׁפִּחֲתָה מִיתָה, \u0010y6\u0011 אֲבָל דְּמֵי הַנְּבֵלָה מְשַׁלֵּם בִּרְשׁוּת הַנִּזָּק נֶזֶק שָׁלֵם, \u0010y7\u0011 וּבִרְשׁוּת הָרַבִּים מַה שֶּׁנֶּהֱנֵית, שֶׁאֲכִילָה אֵינוֹ שִׁנּוּי, שֶׁכֵּן דַּרְכָּן לֶאֱכֹל נְבֵלוֹת אֲפִלּוּ שֶׁל בְּהֵמוֹת גְּדוֹלוֹת.\nאֵין חַיָּב הַשֵּׁן לְשַׁלֵּם נֶזֶק שָׁלֵם אֶלָּא אִם כֵּן אוֹכֶלֶת \u0010y8\u0011 בִּרְשׁוּת הַנִּזָּק, אֲבָל אִם לָקְחָה בַּחֲצֵרוֹ וְהוֹצִיאָה מִשָּׁם וְאָכְלָה בִּרְשׁוּת הָרַבִּים אוֹ בֶחָצֵר שֶׁל אַחֵר, פָּטוּר מִלְּשַׁלֵּם יוֹתֵר מִמַּה שֶׁנֶּהֱנֵית. וְאִם לָקְחָה בִּרְשׁוּת הָרַבִּים וְהָלְכָה וְאָכְלָה בִּרְשׁוּת הַנִּזָּק, יֵשׁ מְחַיְּבִים לְשַׁלֵּם נֶזֶק שָׁלֵם, מִשּׁוּם \u0010y9\u0011 דְּפִי פָרָה כַּחֲצֵר הַנִּזָּק דָּמֵי; וְנָפְקָא מִנָּהּ אֲפִלּוּ בְּמָקוֹם שֶׁאֵין לְחַיֵּב עַל הַנְּטִילָה, כְּגוֹן שֶׁהָיוּ הַפֵּרוֹת מֻנָּחִים בְּמָקוֹם שֶׁאִי אֶפְשָׁר לִטְּלָם מִשָּׁם וּבָא רְאוּבֵן וְהוֹשִׁיט פֵּרוֹת שֶׁל שִׁמְעוֹן שֶׁבַּחֲצַר שִׁמְעוֹן לְפִי פָרַת לֵוִי, חַיָּב לֵוִי אִם הַמּוֹשִׁיט חֵרֶשׁ שׁוֹטֶה וְקָטָן אוֹ \u0010c0\u0011 שֶׁאֵין לוֹ לְשַׁלֵּם, שֶׁאִם הָיָה אֶפְשָׁר לְהִשְׁתַּלֵּם מִמֶּנּוּ הָיָה הוּא חַיָּב וּבַעַל הַפָּרָה פָטוּר:\nאָכְלָה \u0010y10\u0011 \u0010c1\u0011 בִּרְשׁוּת הָרַבִּים, מְשַׁלֵּם כָּל מַה שֶּׁנֶּהֱנֵית, דְּהַיְנוּ כָּל מַה שֶּׁאָכְלָה אֵינוֹ מְשַׁלֵּם אוֹתוֹ אֶלָּא \u0010y11\u0011 כְּאִלּוּ הָיָה תֶבֶן. \u0010y12\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּמֵי שְׂעוֹרִים בְּזוֹל (טוּר ס\"ג בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ וְהָרְאָ\"ה וְהָרִיטְבָ\"א וְנ\"י)\u0006. וְאִם אָכְלָה אֳכָלִים הָרָעִים לָהּ, כְּגוֹן שֶׁאָכְלָה חִטִּים, הוֹאִיל \u0010y13\u0011 וְלֹא נֶהֱנֵית, פָּטוּר.\nהָיוּ \u0010y14\u0011 הַפֵּרוֹת מֻנָּחִים בְּצִדֵּי רְחָבָה וְהִיא בְּתוֹךְ הָרְחָבָה, וְהֶחֱזִירָה רֹאשָׁהּ לְצִדֵּי רְחָבָה וְאָכְלָה מֵהֶן, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית; דְּכֵיוָן דְּגוּפָהּ בִּרְשׁוּת הָרַבִּים, הָוֵי לֵהּ שֵׁן בִּרְשׁוּת הָרַבִּים. אֲבָל אִם יָצְאָה מֵרְחָבָה לְצִדֵּי רְחָבָה וְאָכְלָה שָׁם, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה. \u0010y15\u0011 אָכְלָה מִפֶּתַח הַחֲנוּת, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית. מִתּוֹךְ הַחֲנוּת, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה.\nהִקְצָה מָקוֹם מֵרְשׁוּתוֹ לִרְשׁוּת הָרַבִּים וְהִנִּיחַ שָׁם פֵּרוֹתָיו וַאֲכָלָתָם שָׁם, חָשׁוּב כִּרְשׁוּת הָרַבִּים.\nהָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וּפָשְׁטָה צַוָּארָהּ וְאָכְלָה מֵעַל גַּבֵּי חֲבֶרְתָּהּ, וַאֲפִלּוּ עָמְדָה, \u0010y16\u0011 אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית, שֶׁכֵּן דֶּרֶךְ הַבְּהֵמוֹת לֶאֱכֹל זוֹ מֵעַל גַּבֵּי זוֹ. \u0010y17\u0011 וְאִם קָפְצָה וְאָכְלָה מֵעַל גַּבֵּי חֲבֶרְתָּהּ, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, שֶׁגַּבֵּי חֲבֶרְתָּהּ כַּחֲצַר הַנִּזָּק הוּא חָשׁוּב. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּדַוְקָא שֶׁהוּא בְּעִנְיָן שֶׁאִי אֶפְשָׁר לָהּ לֶאֱכֹל כִּי אִם בִּקְפִיצָה, \u0010y18\u0011 אֲבָל אִם תּוּכַל לְאָכְלָם בְּלֹא קְפִיצָה אָז חָשׁוּב כִּרְשׁוּת הָרַבִּים (טוּר שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010y19\u0011 וְהוּא הַדִּין לְהָיְתָה קֻפָּתוֹ מֻפְשֶׁלֶת לַאֲחוֹרָיו וְאָכְלָה פֵּרוֹת שֶׁבַּקֻפָּה.\nבְּהֵמָה שֶׁהָיְתָה עוֹמֶדֶת בִּרְשׁוּת הַנִּזָּק, וְתָלְשָׁה פֵּרוֹת מֵרְשׁוּת הָרַבִּים וַאֲכָלָתָן בִּרְשׁוּת \u0010y20\u0011 הַנִּזָּק, הֲרֵי הַדָּבָר סָפֵק, \u0005הַגָּה: \u0010y21\u0011 וְהוּא הַדִּין אִם הַבְּהֵמָה עוֹמֶדֶת בִּרְשׁוּת הָרַבִּים וְנָטְלָה הָאֹכֶל מֵרְשׁוּת הַנִּזָּק וְאָכְלָה בִּרְשׁוּת הָרַבִּים, דְּהָוֵי הַדָּבָר סָפֵק. וְדַוְקָא בְּכִי הַאי גַוְנָא שֶׁהַמַּאֲכָל בִּרְשׁוּת אֶחָד וְהַבְּהֵמָה גִּלְגְּלָה הַמַּאֲכָל לִרְשׁוּת שֵׁנִי, \u0010y22\u0011 אֲבָל אִם הַמַּאֲכָל דָּבָר אָרֹךְ, מִקְצָתוֹ מֻנָּח בִּפְנִים וּמִקְצָתוֹ מֻנָּח בַּחוּץ, וּכְשֶׁמּוֹשֶׁכֶת רֹאשׁ הָאֶחָד רֹאשׁ הַשֵּׁנִי נִגְרָר אַחֲרֶיהָ, בְּכָל מָקוֹם שֶׁהִיא מַתְחֶלֶת לְמוֹשְׁכוֹ חָשְׁבֵינָן לֵהּ כְּאִלּוּ אֲכָלָן שָׁם, בֵּין בִּרְשׁוּת הַיָּחִיד בֵּין בִּרְשׁוּת הָרַבִּים (טוּר)\u0006 ; לְפִיכָךְ, אֵינָהּ מְשַׁלֶּמֶת אֶלָּא מַה שֶּׁנֶּהֱנֵית. וְאִם תָּפַס הַנִּזָּק כַּמָּה שֶׁהִזִּיקָה, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: (ר\"י וְהָרֹא\"שׁ)\u0006 וּכְבָר נִתְבָּאֵר סִימָן ש\"צ \u0010y23\u0011 \u0010c2\u0011 דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא מְהַנֵּי תְפִיסָה בִּסְפֵיקָא דְדִינָא:",["\u0003דושלח את בעירה וביער. \u0004 כצ\"ל דמושלח ילפינן היזק הרגל ומוביער ילפינן היזק דשן:","\u0003ומ\"ש הטור והמחבר תיבת נמי בבהמה שאוכלת כו'. \u0004 היינו דל\"ת מ\"ש וביער אלקיחה משדה הניזק קאי ולא אאכילה קמ\"ל דפירושו של וביער הוא שאוכלת כו' מיהו לשון וביער לא קאי דווקא אאכילה אלא על כל דבר שמפסיד אם יש לו הנאה ממנו וכדמפרש ואזיל:","\u0003ולא כלתה אותן לגמרי. \u0004 זה ילפינן מדכתיב היזק דשן ורגל בחד קרא ובדריסה דרגל אינו מפסיד לגמרי:","\u0003נתחככה בכותל כו'. \u0004 אבל נתחככה בחבירת' והזיקה י\"ל דלהזיקה נתכוון וה\"ל תולד' דקרן לשלם ח\"נ אם לא שגם לאחר ששמטה ממנה הבהמה שנתחככה בה הולכת זו ונתחככה בכותל דאז אגלאי מילתא למפרע דגם כשנתחככ' בבהמה להנאת' נתכוון עמ\"ש בסי' א' בס\"ג [בטו' בס\"ד]:","\u0003בין שאכלה בחצר כו' \u0004 כדין קרן ובא לאשמועינן דל\"ת דזה בכלל מ\"ש כל המשנ' ובא אחר ושינה בו ה\"ז פטור דגם כאן זה שהניח בגדיו בר\"ה שינה קמ\"ל דאין זה מיקרי שינוי דלפעמים אדם מניח בגדים בר\"ה על שעה אחת למתפח:","\u0003חיה שטרפה בהמה ואכלתו כו' \u0004 ע\"ל בסי' שפ\"ט שכ' הטור ומור\"ם בהג\"ה בס\"ס ח' דדוקא זאב וכיוצא בו דרכו לאכול בטריפ' משא\"כ ארי שהטריפ' לאכילה הוא שינוי גביה לדעת ר\"י והרא\"ש כי דרכו לדרוס לאכול ועפ\"ר:","\u0003אבל דמי הנביל' \u0004 פי' שאכל הנבילה אחר שהמית':","\u0003מה שנהנית. \u0004 פי' דאינו כ\"כ כדמי שווי הנבילה כמ\"ש בס\"ד [בס\"ח]:","\u0003ברשות הניזק \u0004 דכתיב וביער בשד' אחר ור\"ל בשדה של אחר והוא ניזק ועמ\"ש בס\"ס שפ\"ט:","\u0003דפי פרה כחצר הניזק דמי \u0004 פי' אע\"ג דכתיב וביער בשד' אחר והבא הלקיח' שהוא תחל' הביעור לא הי' בשד' של ניזק גם הכיליון וההפסד הנעש' בפי של פרה אחר הלקיחה הרי היא כחצר המזיק דהרי השור של מזיק הוא קמ\"ל דלא אלא עשאה פי הפרה דהיינו השן והאכילה והכליון הנעשה בפיה כאלו נעשה בחצר הניזק מאחר דבשעת האכיל' היא עומדת בחצר הניזק וכ\"כ הטור בשם הרמ\"ה ובדריש' כתבתי דיש דיעות דלא ס\"ל הכי אלא בעינן דגם בשעת הלקיחה תהא עומדת בחצר הניזק ואז חייבת אף אם נתנה בפיה חש\"ו וכדמסיק המחבר אפ\"ה חייב בעל השור כיון דמ\"מ הבהמ' הית' בחצר הניזק וגם האכילה והכליון ואף שהי' בגופו של הבהמה שהוא של מזיק וקי\"ל דפי פרה דהיינו הכיליון ה\"ל כחצר הניזק כשעומדת ברשות הניזק מתחל' ועד סוף וע' בטור דלא כתב פי פרה כחצר הניזק דמי אלא אהאי דינא בתרא כשהבהמה ברשות הניזק והאוכלים היו במקום גבוה ולא היתה יכולה ליטלה משם ונתנ' בפיה חש\"ו כו' לחוד והמחבר כתבו לטעם גם אכשנטלה מר\"ה והלכה לחצר הניזק ואכלו ולפ\"ז לא ה\"ל לערבב הדברים ולכתוב נ\"מ אפילו כו' אלא הל\"ל ועוד נ\"מ ועד\"ר שם הארכתי:","\u0003משלם כלמה שנהנית \u0004 כלומר אף שפטרה התורה מלשלם נ\"ש מ\"מ מה שנהנית צריך לשלם:","\u0003כאילו היה תבן. \u0004 דיכול המזיק לומר לא הייתי מאכילה שעורים אלא תבן ומה שנהנית שאין צריך ליתן לה תבן כיון ששבעה מהבשר הוא דמשלם לניזק ולא יותר:","\u0003דמי שעורים בזול \u0004 דהיינו שליש פחות מכדי שיווי השעורים וכמ\"ש הטור והמחב' בסי' שפ\"ט [שמ\"א]:","\u0003ולא נהנית פטור. \u0004 דכיון דהיא בר\"ה ולא נהנית אין עליה שום חיוב:","\u0003בצידי הרחבה \u0004 פי' צדי הרחבה הוא לפני הבתי' דכ\"א והוא מיוחד לכ\"א להניח שם פירותיו מביתו ומ\"ה כשהלכ' הבהמ' מר\"ה לצדי הרחבה ואכלה שם חייב נ\"ש דמיקרי חצר הניזק משא\"כ כשעומדת בגופה בר\"ה:","\u0003אכל' מפתח החנו' כו'. \u0004 אף דפתח החנות ודאי לא גרע מצידי הרחב' שנתבא' לפני זה דאם עמדה שם ואכלה משלמת מה שהזיקה מ\"מ כיון דבצד פתח החניו' רבים באים שם לקנות והבהמה עומד' שם ה\"ל כעמד' בר\"ה ואכלה מתוך צידי הרחבה דנתבאר דאינו משלמת אלא מה שנהנית אבל באכל' מתוך החנות אף שהבהמה עומדת בצד פתח החנות (ודוחק לפ' דמיירי שנכנסה לתוך החנות) מ\"מ כיון שאין דרך הבהמה להושיט ראשה כלל לתוך החנות אפילו שמואל דפליג (בגמ' דכ\"א ע\"א) עם רב במחזר' ראשה מודה בזה דה\"ל כאלו עמד' בחנות ואכלה משם משא\"כ כשאכל' מפתח החנות דדרך הליכה דרכה להושיט ראשה שם:","\u0003אינו משלם אלא מה שנהנית. \u0004 נראה אפי' הי' ראשה בשעת אכילת' ע\"ג בהמה מ\"מ כיון שגופה ורגלי' עומדת בר\"ה בתר גופה אזלינן ויש לו דין שן בר\"ה דאינו משלם נ\"ש כ\"א מה שנהנית וכמ\"ש לעיל:","\u0003ואם קפצ' ואכל' כו'. \u0004 פי' ואכלה בשעה שהיא עדיין מגביה רגליה הראשונים ואפי' היתה יכולה לאכול מעל גבה בלי קפיצ' מ\"מ מדקפצה ואכלה על גבה של הבהמה דהניזק מיקרי חצר הניזק אבל הרא\"ש והטור חולקין וס\"ל דכל שיכולה לאכול בלי קפיצה אינו כר\"ה דדרך הבהמה לאכול בכל מקום שתוכל לאכול וזהו מ\"ש מור\"ם ז\"ל בשם י\"א:","\u0003אבל אם תוכל לאכול בלי קפיצה כו' \u0004 פי' ואף שקפצה ואכלה חשוב כר\"ה:","\u0003וה\"ה להית' קופתו כו' \u0004 פי' גם בזו יש חילוק בין אם קפצה ואכלה או אכלה בלי קפיצה ולדעת הרמב\"ם זו נראה דה\"ה אם היו מונחים הפירות בר\"ה במקום שאפשר ליטלם בלי קפיצה וקפצת ואכלה חשוב כחצר הניזק ועיין בטור שכתב בשם הרמ\"ה דעת שלישית שחולק דבאכלה מע\"ג חבירת' או מתוך קופתו חייב אפי' בלי קפיצה ובר\"ה אם קפצה משלם כל מה שהזיקה ובלא קפיצה כל מה שנהנית עד\"ר שהארכתי בזה:","\u0003הרי הדבר ספק כו' \u0004 ואע\"ג דפסק המחבר לפני זה בס\"ז דאם לקחה פירות בר\"ה והלכה ואכלה ברשות הניזק יש מחייבין לשלם נ\"ש י\"ל דזה שעומדת ברשות הניזק ועומדת ומושיטה ראשה לאכול ברשות אחר מחשב שינוי שאין דרך אכילתה בכך לכן ה\"ל ספק משא\"כ כשהלכה מרשות לרשות:","\u0003וה\"ה אם הבהמ' עומדת בר\"ה כו'. \u0004 זהו תימא דהא לכ\"ע אם נוטלת ברשות הניזק ואכלה בר\"ה אינו משלמת אלא כפי מה שנהני' וכ\"ש בזה שהיא שינוי ומסתבר בו טפי לפטור מתשלומי נ\"ש ולמה כ' מור\"ם דיש להסתפק בזה ואף שרש\"י כ' ג\"כ האי וה\"ה וכו' על האיבעיא דמתגלגל אי חשוב כחצר הניזק הא שם סתרי התו' מכח האי קושי' גופיה לפירש\"י ופי' האיבעיא דמתגלגל שהי' האוכל מתגלגל מרשות כו' וכמ\"ש הטור בשם ר\"י ע\"ש ואפש' דס\"ל לרש\"י לחלק בין גלגלה מרשות לרשות בעודו מונחת ע\"ג קרקע ובין עקרה והוציאתה בפיה מרשות וצ\"ע:","\u0003אבל אם המאכל דבר ארוך כו'. \u0004 עד בין ברה\"י כו' וקימתא זו היא בגמ' אליבא דכ\"ע ודוק:","\u0003דיש חולקין וס\"ל כו'. \u0004 עפ\"ר דכתבתי מדלא כ' הטור כאן דעת אביו הרא\"ש שחולק בזה משמע דס\"ל דל\"פ כאן דכיון דעכ\"פ תפיס ברשות נגד מה שנהנית מהני התפיסה גם לשאר:"],["\u0003 שאין לו לשלם כו'. \u0004 אין לפרש הטעם דכיון דאין לו לשלם חייב מטעם דראובן ה\"ל שלוחו של לוי דהא לוי לא צוה לראובן לעשות כן ועוד דאפי' אין לו לשלם אמרינן אין שליח לדבר עבירה וכמ\"ש לעיל ר\"ס קפ\"ב ורצ\"ב ובמע\"מ פ' כיצד הרגל כ' הטעם וז\"ל וטעמא אע\"ג דפקח בר תשלומין הוא מ\"מ כיון דליכא לאשתלומי מיניה חייב אידך לשלם כר' נתן דכל דין שותפים יש לשנים שהזיקו ביחד עכ\"ל וקשה דהרי הטו' לקמן ס\"ס ת\"י השיג על הרמ\"ה בעל סברא זו וכ' ואין נראה דלא מחייב ר' נתן היכא דליכ' לאשתלומי מאידך כו' והוא דעת הי\"ח שהביא המחב' שם א\"כ יהיו דברי הטו' סותרים זא\"ז גם סותרים לדברי הרא\"ש פ' כיצד הרגל שהוציאו הט\"ו דבריהם שבכאן ממנו אלא נ\"ל דשאני הכא כיון שהמושיט לא הזיק כלום רק שהושיט לפי פרה ואז היה עדיין בעין בשלימותו וא\"כ הפרה עשתה כל ההיזק והמושיט לא ה\"ל רק כגזלן דמעידנא דאגבי' ה\"ל שולח יד בדבר שאינו שלו דה\"ל גזלן א\"כ ה\"ל כגוזל ומאכיל דרצה מזה גובה רצה מזה גובה דלעיל סי' שס\"א ס\"ה אלא דאם יש לו לשלם כיון דעכ\"פ חייב המושיט מטעם מזיק ובעל הפרה לא הזיק בידים שהרי אלו לא הושיט לא אכל' לכך גוב' מהמושיט ודוק:","\u0003 משלם כל מה שנהנית. \u0004 בהרא\"ש פ' הגוזל קמא כתב גבי אוקימת' דרבינא בצבע הקוף צמר בסמנין וז\"ל דדוקא כשגופו נהנה ע\"י אחר או ממונו נהנה מחבירו ע\"י מעשה של ממונו כמו אכלה מצדי רחבה ונפלה לגנ' אז משלם מה שנהנית אבל כשממונו נהנה ע\"י אחר פטו' עכ\"ל והוא כתירוץ הראשון של התוס' שם ד\"ק ע\"א מוכח דאם תחב לה אחר אוכלין לתוך פיה פטו' לשלם מה שנהנית (ודל\"ד לעיל ס\"ז דהתם משלם מה שהזיקה דהוי פשיעה וכ\"כ בספר מע\"מ פ' הגוזל שם) וכ\"כ מהרש\"ל פ' הגוזל סי' כ\"ח דהתוחב אוכלין לתוך פיו של בהמתו אינו משלם כלום מה\"ט ומ\"מ נ\"ל דמיירי שתחב אוכלין של אחרים ופטור מן בעל האוכלין אבל אם תחב אוכלין שלו חייב לשלם לו דלא גרע מיורד שלא ברשות וטעמא ביורד שלא ברשות כיון שמתכוין להשביח חייב לשלם לו יציאותיו ודוק ומיהו כ\"ז לשנויא קמא דתוס' אבל תמיהני על הרא\"ש ומהרש\"ל דהא התוס' מסקי שם וז\"ל א\"נ הנאה דהכא לא חשיבה הנאה שאינו אלא נוי בעלמא יותר עכ\"ל כלו' משום דחזיתא לאו מילתא היא וכדקאמרינן בש\"ס התם ותירוץ זה נ\"ל לכאורה עיקר דמניין לנו לחלק בחלוקים שלא נזכרו בש\"ס (הג\"ה וגם הא דבעי בש\"ס התם למיפשט דחזיתא מילתא היא מערלה ושביעית לא יתיישב שפיר לתירוץ קמא דתוספות ודו\"ק ע\"ש) ועכ\"פ נ\"ל דדין זה כשממונו נהנה ממונו של אחר שלא ע\"י מעשה ממונו ה\"ל ספיקא דדינא אי פטור או לא ודו\"ק:","\u0003 דיש חולקין כו' \u0004 עיין בסמ\"ע ס\"ק כ\"ד עד דכיון דעכ\"פ תפס ברשות נגד מה שנהנית מהני תפיסה גם לשאר עכ\"ל וזהו דוחק ול\"נ דשאני הכא דהוי בעי' ולא איפשטא ולא סלקא בתיקו ובזה גם להרא\"ש וטור מהני תפיסה וכמש\"ל סי' שמ\"ו סי\"ד (הג\"ה וע\"ש שחזר בו אח\"כ וגם בספרו תקפו כהן וס\"ל דאין לחלק בין תיקו לבעיא דלא איפשטא):"]],["כֶּלֶב שֶׁנָּטַל אֶת הַחֲרָרָה וְהָלַךְ לוֹ לְגָדִישׁ \u0005שֶׁל בַּעַל הַחֲרָרָה, (טוּר ס\"ה)\u0006, אִם הִנִּיחָהּ בַּגָּדִישׁ \u0010y0\u0011 וְאָכַל אֶת הַחַלָּה וְהִדְלִיק אֶת הַגָּדִישׁ, עַל הַחַלָּה \u0010y1\u0011 וְעַל מְקוֹם הַחֲרָרָה מְשַׁלֵּם נֶזֶק שָׁלֵם, וְעַל הַגָּדִישׁ חֲצִי נֶזֶק; \u0010y2\u0011 וְאִם הָיָה מְגָרֵר אֶת הַחַלָּה עַל הַגָּדִישׁ וְהוֹלֵךְ וְשׂוֹרֵף, מְשַׁלֵּם עַל הַחֲרָרָה נֶזֶק שָׁלֵם, וְעַל מְקוֹם הַגַּחֶלֶת חֲצִי נֶזֶק, וְעַל שְׁאָר הַגָּדִישׁ פָּטוּר. \u0005וְיֵשׁ אוֹמְרִים דִּמְשַׁלֵּם עַל כָּל הַגָּדִישׁ חֲצִי נֶזֶק (טוּר שָׁם וּבֵית יוֹסֵף בְּשֵׁם הָרַשְׁבָּ\"א)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁשָּׁמַר בַּעַל הַגַּחֶלֶת אֶת אִשּׁוֹ, וְסָגַר הַדֶּלֶת, \u0010y3\u0011 וּבָא הַכֶּלֶב וְחָתַר, וְנָטַל אֶת הַחֲרָרָה מֵעַל הָאֵשׁ; אֲבָל אִם לֹא שָׁמַר אִשּׁוֹ, \u0010y4\u0011 בַּעַל הָאֵשׁ חַיָּב עַל שְׂרֵפַת הַגָּדִישׁ, וּבַעַל הַכֶּלֶב חַיָּב עַל אֲכִילַת הַחֲרָרָה וְעַל מְקוֹמָהּ \u0005(וְכ\"כ הַטוּר בְּשֵׁם הרמ\"ה)\u0006. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּעַל מְקוֹם הַחֲרָרָה מְשַׁלֵּם \u0010y5\u0011 כָּל אֶחָד הַחֵצִי, וְעַל שְׁאָר הַגָּדִישׁ \u0010y6\u0011 בַּעַל הַכֶּלֶב נוֹתֵן רְבִיעַ, וּבַעַל הַגַּחֶלֶת ג' חֲלָקִים. וְאִם זְרָקָהּ עַל הַגָּדִישׁ, אָז מְשַׁלֵּם בַּעַל הַכֶּלֶב רְבִיעַ אֲפִלּוּ עַל מְקוֹם הַחֲרָרָה, וּבַעַל הַגַּחֶלֶת שְׁלֹשָׁה חֲלָקִים\u0006 \u0005(טוּר שָׁם)\u0006.",["\u0003ואכל את החלה. \u0004 הוא חררה הנ\"ל אלא מתחלה לשון המשנה נקט דקתני חררה ואח\"כ ל' הרמב\"ם דכתב ל' חלה ואח\"כ תפס לשניהן יחד וכתב על החלה ועל מקום החררה:","\u0003ועל מקום החרר'. \u0004 דכיון דהניח' שם ה\"ל היזק בידים וכי אורחי' הוא חייב עליהן בעל הכלב נזק שלם ועל שאר הגדיש דלא בא ההיזק אלא מגרמת הנח' ה\"ל כצרורות ומ\"ה בתשלומי ח\"נ סגי:","\u0003ואם הי' מגרר כו'. \u0004 אז מקום הגחלת מחשב לשינוי או צרורות מ\"ה בח\"נ סגי ועל הגדיש ס\"ל דפטו' דזה גרע מכח כחו דנתבא' בטור ובדברי המחב' בסי' ש\"ץ דחייב עליו ג\"כ ח\"נ ע\"ש:","\u0003ובא הכלב וחתר כו'. \u0004 דבזה בעל הגחל' פטו' כיון דשמר אשו כדנטרי אינשי ובעל הכלב חייב כיון דסתם דלתות חתורות הן אצל כלבים ה\"ל לשמו' כלבו שלא יחתור ויזיק:","\u0003בעל האש חייב על שריפת הגדיש כו'. \u0004 ל\"ד קאמר חייב דהא מסתמא בעל החררה הוא בעל האש שאפה חררתו בתנורו והגחלת היא שלו וגם הוא בעל הגדיש ולמה ישלם אלא בא לו' שגם בעל הגחלת הוא הגורם ההיזק ומ\"ה בעל הכלב אינו משלם אלא החצי היזק:","\u0003כ\"א החצי \u0004 דשניהן שותפין בהנזק:","\u0003בעל הכלב נותן רביע. \u0004 דמחשב לגביה שינוי ואם הוא עשה ההיזק לבדו לא הי' חייב אלא ק\"נ השתא דאיכא בעל הגחלת דהוא שותפו בהיזק פטרו מחצי חיובו ולא נשאר עליו אלא רביע ההיזק ובעל הגחלת עליו לשלם שלשה רביעיו' כיון דאם לא הי' בעל הכלב שותפו ובעל הגחלת הי' עושה ההיזק הי' עליו לשלם הכל כי אין שייך אצלו לפטור מהחצי מ\"ה נשאר עליו חוב שלשה רביעית היזק:"],[]],["הִכְנִיס \u0010y0\u0011 פֵּרוֹתָיו לַחֲצַר בַּעַל הַבַּיִת \u0005(שֶׁלֹּא בִּרְשׁוּת)\u0006 וַאֲכָלָתָן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת, פָּטוּר. \u0005וַאֲפִלּוּ הָיָה בַּעַל הֶחָצֵר טוֹחֵן, וְהֵבִיא זֶה חִטִּים \u0010y1\u0011 לִטְחֹן שֶׁיִּשְׂתַּכֵּר בָּהֶן בַּעַל הֶחָצֵר, אֲפִלּוּ הָכִי מִקְרֵי שֶׁלֹּא בִרְשׁוּת (טוּר ס\"א)\u0006. וְאִם הֻחְלְקָה בָּהֶם וְהֻזְּקָה, בַּעַל \u0010y2\u0011 הַפֵּרוֹת חַיָּב. וְאִם הִכְנִיס בִּרְשׁוּת, פָּטוּר. \u0005וְיֵשׁ חוֹלְקִין (טוּר בְּסִימָן צ\"א וְסִימָן שצ\"ח בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006. כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סוֹף סִימָן שצ\"ח. וְאִם קִבֵּל עָלָיו \u0010c0\u0011 בַּעַל הַבַּיִת לִשְׁמֹר אֶת הַפֵּרוֹת, בַּעַל הַבַּיִת חַיָּב.\nהִכְנִיסָן שֶׁלֹּא בִּרְשׁוּת, וַאֲכָלָתָן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת וְהֻזְּקָה בַּאֲכִילָתָן, בַּעַל הַפֵּרוֹת פָּטוּר, מִפְּנֵי \u0010y3\u0011 שֶׁהָיָה לָהּ שֶׁלֹּא תֹּאכַל.\nהִכְנִיסָן בִּרְשׁוּת וְהִנִּיחוּ בַּעֲלֵי הֶחָצֵר אֶת זֶה שֶׁהִרְשׁוּהוּ בֶּחָצֵר לְשָׁמְרוֹ, וַאֲכַלְתָּן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת וְהֻזְּקָה בַּאֲכִילָתָן, בַּעַל הַפֵּרוֹת חַיָּב, שֶׁכֵּיוָן שֶׁרָאָה הַבְּהֵמָה אוֹכֶלֶת דְּבָרִים הַמַּזִּיקִים לָהּ וְהִנִּיחָהּ, חַיָּב, שֶׁהֲרֵי אֵין בַּעֲלֵי הֶחָצֵר מְצוּיִים שָׁם לְהַעֲבִיר הַבְּהֵמָה מֵהֶם. \u0010y4\u0011 וּמַעֲשֶׂה בְּאִשָּׁה אַחַת שֶׁנִּכְנְסָה בְּבֵית שְׁכֶנְתָּהּ לָלוּשׁ וְלֶאֱפוֹת, וְהִנִּיחוּהָ וְנִתְעַלְּמוּ \u0010y5\u0011 כְּדֵי שֶׁלֹּא יַבִּיטוּ בָּהּ בְּעֵת לִישָׁתָהּ וַאֲפִיָּתָהּ, וּבָא עֵז שֶׁל בַּעַל הַבַּיִת וְאָכַל הַבָּצֵק וָמֵת, וְחִיְּבוּהָ חֲכָמִים לְשַׁלֵּם דָּמָיו; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010y6\u0011\nהַמַּגְדִּישׁ בְּתוֹךְ שְׂדֵה חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וַאֲכָלָתָם בְּהֶמְתּוֹ שֶׁל בַּעַל הַשָּׂדֶה, פָּטוּר. וְאִם הֻחְלְקָה בָּהֶם וְהֻזְּקָה, בַּעַל הַפֵּרוֹת חַיָּב. אֲכַלְתָּן וְהֻזְּקָה בַּאֲכִילָתָן, פָּטוּר. וְאִם הִגְדִּישׁ בִּרְשׁוּת בַּעַל הַשָּׂדֶה, חַיָּב אַף עַל פִּי שֶׁלֹּא קִבֵּל עָלָיו לִשְׁמֹר, שֶׁהַשּׁוֹמֵר בַּגְּרָנוֹת כֵּיוָן שֶׁאָמַר לוֹ: הַגְדֵּשׁ בְּכָאן, כְּמִי שֶׁאָמַר לוֹ: הַגְדֵּשׁ וַאֲנִי אֶשְׁמֹר לְךָ, הוּא חָשׁוּב:",["\u0003הכניס פירותיו לחצר בעל הבית שלא ברשות ואכלתן כו'. \u0004 כצ\"ל וכן הוא במיימוני פ\"ג דניזקין וכלל דבריו הן דבעל החצר פטור בהיזק פירותיו כיון דשלא ברשות הכניסן ומה\"ט אם הוזקה בהן פרה של בעל הבית אז בעל הפירות חייב לשלם לו הזיקו מיהו ה\"מ שהוזק' בהן מוכח שהוחלק' בהפירו' אבל אם הוזקה מכח רוב האכילה פטור בעל הפירות מהיזקה דעל ב\"ה הוא מוטל לשומרה מאכילה יתירא כדמסיק המחבר בסעי' שאחר זה:","\u0003שישתכר בהן בעל החצר \u0004 שיתן לו שכירות מהטחינה:","\u0003ואם הכניס ברשות פטור. \u0004 ע\"ל סי' שצ\"ח שכ' הטור פלוגתת הגאונים בזה דר\"י והרא\"ש פסקו כרבנן דאמרו כל שנתן לחבירו רשות להכניס פירות קיבל עליו שמירת הפירות והרי\"ף והרמב\"ם פסקו כר' דאמ' אף אם נתן לו רשות להכניס לא הוה כאילו קיבל עליו נטירותא מיהו ה\"מ שלא נתחייב בעל החצר בתשלומי היזק בעל הפירות אם הזיקו שורו לפירות שהכניס אבל כ' שם דלכ\"ע אין בעל הפירות חייב בנזקי דבעל החצר אם הוזק שורו דבעל חצר בפירותיו ע\"ש וז\"ש המחבר כאן דאם הכניס ברשות פטור דאף דפסק המחבר כהרי\"ף והרמב\"ם דסתם נתינת רשות לא הוי כקיבל עליו שמירת הפירות מ\"מ בעל הפירות אינו חייב באשר הוזק בהן שורו דבעל החצר וא\"כ תימא על מור\"ם שמסיק וכתב כאן על דברי המחבר דיש חולקין כמ\"ש בסי' שצ\"ח דהא שם לא פליגי אלא אם נתחייב בעל החצר בהיזק דבעל הפירות ומזה לא איירי המחב' כאן אלא בפטו' דבעל הפירות בהיזק דבעל החצר (דהא ואם הכניס ברשות פטור דכתב האי פטור קאי אמ\"ש לפני זה דחייב בו בהכניסה שלא ברשות) ובזה כ\"ע מודו וצריכין לדחוק ולו' דס\"ל למור\"ם דמדסיים המחב' וכתב ז\"ל ואם קיבל עליו בעל הבית לשמו' את הפירו' ב\"ה חייב ולפני זה לא נזכר שום פטר בהב\"ה והוצרך לכתוב דבקבל עליו השמירה דחייב צ\"ל דמ\"ש המחב' אם הכניס ברשות פטו' שכל א' פטו' משילום הזיקו דחבירו ונשמע מיניה דס\"ל להמחב' דגם ב\"ה פטו' משילום הזיקו דהנכנס אם הזיק שורו לשורו דהנכנס ועל זה כ' מור\"ם דיש חולקין אבל פי' זה דוחק כיון דלא נזכר לפני זה מחיובו דב\"ה:","\u0003שהי' לה שלא תאכל \u0004 פי' הי' לו לשמור פרתו שלא תאכל יותר משיעור' וזה דוקא מסתמא כשבעל החצר בחצירו אבל אם נסתלק משם בעל החצר בידיעת בעל הפירות על בעל הפירות מוטל השמירה שלא תאכל יותר מדאי אפי' אם הכניס ברשות וכמ\"ש בסעיף שאחר זה:","\u0003ומעשה באשה א' כו'. \u0004 מתחל' כתב המחבר דברי הרמב\"ם בנסתלק בעל החצר בידיעת בעל הפירו' והניח עליו השמירה דבעל הפירות הי' לו לשומרו ובמעשה זה בא להוסיף דאף דנסתלק בעל החצר שלא בידיעת בעל הפירות אפ\"ה אם בעל הפירות עושה דבר צניעות דמסתמא יסתלק עבורו בעל החצר ויצא באותה שעה שעוש' דבר הצניעות ה\"ל כאילו הודיעו שיצא ובעל הפירות חייב בשמירת בהמה דבעל החצר אפילו לענין שלא תאכל יותר מדאי ותוזק:","\u0003כדי שלא יביטו בה כו' \u0004 פי' שלא יביטו זרועותי' המגולות בעת לישתה העיסה:","\u0003המגדיש בתוך שדה חבירו כו' כל' המחבר כן הוא ל' הרמב\"ם בספ\"ג דנ\"מ ויש לדקדק בדבריהן שסיים וכ' שהשומר בגרנו כיון שא\"ל הגדש כו' ולפני זה לא הזכירו בדבריהן דמיירי שיש בהשד' שומר לשמור השד' ושהוא נתן לבעל הפירות רשות ליכנס ואדרבא כ' אם הגדיש ברשות בעל השדה דמשמע דאיירי דבעל השדה נתן לו רשות להגדיש ולא השומר וליישב זה צ\"ל דהן איירי בבעל השדה שהוא עצמו שומר השדה ואפשר דדרכן הי' בכך מ\"ה סתמו ולא הוצרכו לכותבו וא\"ש כיון דבעל השדה הוא עצמו השומר והוא הנותן לו רשות להגדיש מ\"ה הרי\"ף והרמב\"ם מודים בזה דאף בעלמא לא אמרינן עול ואנטר לך קאמר בזה דבל\"ה משמר השדה ויושב בצדו דה\"ל סתמא כאילו קיבל עליו שמירתו ונראה שגם הרא\"ש שכ' בפסקיו דיש נ\"מ גם לרבנן בשומר דהעלוהו מעלה א' ויהי' שלא ברשות דידיה כסתמא דעלמא דלא כתב כך אלא כשהבעל השדה עצמו הוא השומר דאל\"כ הוא נגד הסברא דיכניס זה גדישו לשדה חבירו שלא ברשות כלל ויחייב לבעל השדה בשמירתו אבל הטור מפרש בדבריו דלא מוקי להגמרא כן אלא פי' דהגמרא איירי כשבעל השדה יש לו שומר בפני עצמו המשמר בשדה שהרי כתב ואם א\"ל שומר השדה כנוס ותגדיש אף ע\"פ שלא א\"ל בעל השדה כנוס ע\"ש ובזה נתיישב התמיה הגדולה שיש להקשות על דברי הטור במ\"ש נגד דברי אביו דהרא\"ש כתב דאפי' בלא רשות ה\"ל לרבנן כאלו נתן רשות והטור כתב דבעינן עכ\"פ שיתן השומר רשות להגדיש ובמ\"ש ניחא אלא שעדיין ק' למה השמיט הטור דינו דהרא\"ש אביו ולפי מה שישבתי בפרישה עוד בע\"א א\"ש וק\"ל:\u0004"],["\u0003 בעל הבית חייב כו'. \u0004 נ\"ל דכאן שייך הי\"ח וק\"ל:"]],["בְּהֵמָה שֶׁהֻחְלְקָה בְּאֶבֶן אוֹ בְּמֵימֵי רַגְלַיִם, וְנָפְלָה לְגִנָּה, וְנֶחְבְּטָה עַל גַּבֵּי פֵּרוֹת וִירָקוֹת, אוֹ \u0010y0\u0011 שֶׁאָכְלָה, מְשַׁלֵּם מַה שֶּׁנֶּהֱנֵית. \u0010y1\u0011 אֲפִלּוּ הָלְכָה מֵעֲרוּגָה לַעֲרוּגָה, וַאֲפִלּוּ נִשְׁאֲרָה שָׁם כָּל הַיּוֹם כֻּלּוֹ, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית. וּמַה הֲנָאָה יֵשׁ לָהּ בַּחֲבָטָה, שֶׁהֲרֵי מָצְאָה מָקוֹם רַךְ \u0010c0\u0011 וְלֹא נִתְרַסְקוּ אֵיבָרֶיהָ. אֲבָל אִם יָרְדָה כְּדַרְכָּהּ וְאָכְלָה, מְשַׁלֵּם מַה \u0010y2\u0011 שֶּׁהִזִּיקָה. וַאֲפִלּוּ טִנְּפָה פֵּרוֹת בְּמֵי לֵדָה, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה. וְכֵן אִם דְּחָפָהּ חֲבֶרְתָּהּ וְנָפְלָה, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי שֶׁהָיָה לוֹ לְהַעֲבִירָם אַחַת אַחַת כְּדֵי שֶׁלֹּא יִדְחֲפוּ זוֹ אֶת זוֹ \u0005(וְכֵן דַּעַת הָרִי\"ף)\u0006. \u0005הַגָּה: \u0010y3\u0011 וְיֵשׁ אוֹמְרִים דְּאִם דְּחָפָהּ חֲבֶרְתָּהּ לֹא מִקְרֵי פְשִׁיעָה, אֶלָּא הָוֵי אֹנֶס וּפָטוּר\u0006 \u0005(טוּר ס\"ג בְּשֵׁם ר\"י והרמ\"ה וְהָרֹא\"שׁ)\u0006. \u0010y4\u0011 \u0005אִם הֶעֱבִירָהּ אֵצֶל גִּנַּת חֲבֵרוֹ וְהָיָה אֶפְשָׁר לָהּ לֵירֵד וְלִכָּנֵס לַגִּנָּה, אֲפִלּוּ נָפְלָה בְּאֹנֶס חַיָּב, דְּהָוֵי תְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ בְּאֹנֶס\u0006 \u0005(טוּר ס\"א וְתוֹסָפוֹת וְהָרֹא\"שׁ)\u0006. \u0005וְיֵשׁ מִי שֶׁחוֹלֵק בְּזֶה\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַשְׁבָּ\"א בְּשֵׁם הָרַאֲבַ\"ד)\u0006.\nהֻחְלְקָה וְנָפְלָה וְיָצְאָה \u0005וְהוּא יָדַע (טוּר ס\"ב)\u0006, וְחָזְרָה לַגִּנָּה, אַף עַל פִּי שֶׁחָזְרָה שֶׁלֹּא לְדַעַת הַבְּעָלִים, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי \u0010y5\u0011 \u0010c1\u0011 שֶׁהָיָה לוֹ לְשָׁמְרָהּ שֶׁלֹּא תַּחֲזֹר, שֶׁהַדָּבָר יָדוּעַ שֶׁכֵּיוָן שֶׁיָּדְעָה דֶרֶךְ הַגִּנָּה הֲרֵי הִיא חוֹזֶרֶת מֵאֵלֶיהָ. \u0005הַגָּה: \u0010c2\u0011 מִיהוּ, אִם שְׁמָרָהּ בִּשְׁמִירָה מְעֻלָּה וְיָצְאָה וְהִזִּיקָה, פָּטוּר (טוּר)\u0006. \u0010y6\u0011\nהַמַּעֲמִיד בֶּהֱמַת חֲבֵרוֹ עַל גַּבֵּי קָמַת חֲבֵרוֹ, הַמַּעֲמִיד חַיָּב לְשַׁלֵּם מַה שֶּׁהִזִּיקָה. וְכֵן אִם הִכִּישָׁהּ \u0005(פֵּרוּשׁ, הִכָּה אוֹתָהּ)\u0006 עַד שֶׁהָלְכָה לְקָמַת חֲבֵרוֹ וְהִזִּיקָה, זֶה שֶׁהִכִּישָׁהּ חַיָּב. \u0005הַגָּה: \u0010y7\u0011 וַאֲפִלּוּ הַפֵּרוֹת בִּרְשׁוּת הָרַבִּים, דְּהָוֵי כְּמַזִּיק בְּיָדַיִם (המ\"מ פ\"ד מִנִּזְקֵי מָמוֹן וּבֵית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006. וְדַוְקָא הִכִּישָׁהּ וְכַיּוֹצֵא בָּזֶה, אֲבָל קָם לָהּ בְּאַפָּהּ עַד שֶׁהָלְכָה שָׁם, פָּטוּר, דְּהָוֵי גְרָמָא בִנְזָקִין \u0005(הַמַּגִּיד שָׁם, וּדְלָא כְּדַעַת הָרַאֲבַ\"ד)\u0006.\nכָּל \u0010y8\u0011 בְּהֵמָה שֶׁהִזִּיקָה פֵּרוֹת מְחֻבָּרִים, מְשַׁעֲרִים מַה שֶּׁהִזִּיקָה בְּשִׁשִּׁים וּמְשַׁלֵּם מִי שֶׁנִּתְחַיֵּב לְשַׁלֵּם. כֵּיצַד, הֲרֵי שֶׁאָכְלָה בֵּית סְאָה, שָׁמִין שִׁשִּׁים בֵּית סְאָה בְּאוֹתָהּ הַשָּׂדֶה כַּמָּה הָיָה שָׁוֶה, וְכַמָּה הוּא שָׁוֶה עַתָּה אַחַר שֶׁנִּפְסַד בּוֹ הַבֵּית סְאָה, וּמְשַׁלֵּם הַשְּׁאָר. \u0010y9\u0011 וְכֵן אִם אָכְלָה קַב אוֹ רֹבַע, אֲפִלּוּ קֶלַח אֶחָד, שָׁמִין אוֹתוֹ בְּשִׁשִּׁים.\nאָכְלָה פֵּרוֹת גְּמוּרִים שֶׁאֵינָם צְרִיכִים לַקַּרְקַע, מְשַׁלֵּם דְּמֵי פֵרוֹת גְּמוּרִים בְּשִׁוּוּיֵיהֶן, אִם סְאָה דְּמֵי סְאָה, וְאִם סְאָתַיִם דְּמֵי סְאָתַיִם.\nהֲרֵי שֶׁאָכְלָה פֵּרוֹת דֶּקֶל אֶחָד, \u0010y10\u0011 וְכֵן הַקּוֹצֵץ פֵּרוֹת דֶּקֶל חֲבֵרוֹ וְאָכַל, אִם הָיָה דֶקֶל רוֹמִי וְכַיּוֹצֵא בּוֹ שֶׁאֵין הַתְּמָרִים שֶׁלּוֹ יָפוֹת, מְשַׁעֲרִים אוֹתוֹ בְּשִׁשִּׁים עַל גַּבֵּי הַקַּרְקַע; וְאִם דֶּקֶל פַּרְסִי וְכַיּוֹצֵא בּוֹ הוּא, שֶׁהַתְּמָרִים שֶׁלּוֹ יָפוֹת בְּיוֹתֵר, מְשַׁעֲרִים הַדֶּקֶל בִּפְנֵי עַצְמוֹ, כַּמָּה הָיָה שָׁוֶה וְכַמָּה הוּא שָׁוֶה עַתָּה. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם לֹא נִגְמַר גִּדּוּלוֹ מְשַׁעֲרִין בְּשִׁשִּׁים, \u0010y11\u0011 וְאִם נִגְמַר גִּדּוּלוֹ מְשַׁעֲרִין כְּמוֹ שֶׁהוּא (טוּר ס\"ו)\u0006.",["\u0003משלם מה שנהנית כו'. \u0004 פי' ולא כל מה שהזיק' החילוק שבין דא לדא כ' הטור והמחבר בסי' שצ\"א ס\"ח ע\"ש:","\u0003ואפי' הלכה מערוג' לערוג' כו'. \u0004 פי' ואפי' בעל הבהמה ידע מזה דמזל רע דבעל השדה הוא דגרם ליה ההיזק:","\u0003ואפי' טנפה פירות כו'. \u0004 פי' אף שלא אכלם וזה שילדה וטנפ' הי' אונס דלא ה\"ל למיסק אדעתיה שתלד ותטנף אפי' הכי משלם אפי' כל ההוזק כיון דתחלתי' הוה בפשיעה דה\"ל לשומר' שלא תלך שם ותרד ותאכל הפירות וברישא מיירי שנפל' ממקו' שלא הי' לה לירד שם דרך הטבע אם לא שהוחלק' ונפלה שם באונס מ\"ה אינו משלם אלא מה שנהני' כ\"כ בטור ועמ\"ש מור\"ם בהג\"ה ובסמוך דיש חולק ע\"ז דתחלתו בפשיעה וסופו באונס:","\u0003וי\"א דאם דחפוה חבירת' כו'. \u0004 דאע\"ג דנתבאר בטור ובדברי המחבר לעיל בסי' ש\"ג סי\"א בש\"ש דבכה\"ג חייב לאו משום דהו' כפשיעה אלא דה\"ל כגניב' ואביד' דש\"ש חייב בו משא\"כ בשן ורגל דאין אדם מחויב לשמור בהמתו אלא שמירה פחות' כמ\"ש בר\"ס שצ\"ו ומחשב בהן זה לאונס ועד\"ר:","\u0003אם העביר' כו'. \u0004 והי' אפשר לה לירד כו' ומ\"ש המחבר בר\"ס זה יש לפרשו דלא הי' אפשר לה לירד וכמ\"ש לפני זה ובטו' כתב עוד ז\"ל או אפילו שאי אפשר שתרד ונפלה שם שלא באונס ג\"כ משלמת כל מה שהזיק' ור\"ל כגון שהיא הולכת במקו' גבוה והשדה בגיא ושינת' זו את טבע שאר הבהמות וקפצה לאכול הפירות שראת' שם","\u0003שהיה לו לשומר'. \u0004 פי' שמיר' מעול'. ופי' שמירה מעולה או פחות' תמצא בר\"ס שצ\"ו ובטור ובדברי המחבר:","\u0003המעמיד בהמת חבירו כו' \u0004 וכ\"ש בהמה שלו:","\u0003ואפי' הפירות בר\"ה ואע\"ג דבהיזק שן ורגל נתבאר בסימן שצ\"א דאם הזיק בהן בר\"ה אין בעל הבהמה משלם אלא (ח\"נ) מה שנהנית שאני הכא כיון דהעמידו שם ה\"ל כמזיק הפירות בידים וכדמסיק ומ\"ה משלם נ\"ש:\u0004","\u0003משמרין מה שהזיקה בס' כו' \u0004 ילפינן לה מדכתיב וביער בשד' אחר בבי\"ת דהול\"ל וביער שדה אחר ודרשינן דההיזק והביער ישער אגב שדה אחר והיינו דלא ישומו כמה היה שוה בית סאה זו הנאכל לחוד דהי' שוה טובא והי' מפסיד המזיק הרבה אלא משערינן אם אדם בא ליקח ס' כמו שיעור זה דהוזק כמה היה נותן בעדו דרך משל ס' זהו' וכמה הי' פוחת בשביל בית סאה זו שנאכל דדרך העולם הוא דלא הי' פוחת עבור זה כל שווי' בית סאה וגם אין שמין בית סאה זו הנאכל אגב שדה שלימה דלא הי' פוחת הקונה עבור זה כ\"א דבר מועט והיה נפסד הניזק טובא לכך נתנו שיעור ממוצע לשער בס' כשיעור הנאכל ואע\"ג דדרשינן זה מדכתיב וביער ובשדה אחר ילפינן נמי מינ' דדוקא כשהזיק' ברשות הניזק הוא דחייב לאפוקי הזיק' בר\"ה והיינו מדכתב' התורה גבי וביער ולא כתב' גבי דין תשלומין מיטב שדהו ישלם בשדה אחר ועד\"ר:","\u0003וכן אם אכלה קב כו'. \u0004 שמין אותו בששים כמו זה הנאכל ולאפוקי ממ\"ד דמשערינן לעולם אפי' קלח א' אגב סאה בס' סאין ועפ\"ר:","\u0003וכן הקוצץ כו'. \u0004 פי' בין שאכלה הבהמה בין שקוצץ האדם עצמו יש חילוק בין אם היו הפירות מדקל משובח או מדקל שאינו משובח כ\"כ:","\u0003ואם נגמר גדולו כו' \u0004 הטור כ\"כ אקוצץ אילן עצמו וחילק בין אם היה נגמר כ\"כ עד שהי' ראוי לשתלו במקום אחר או לא ומור\"ם ז\"ל אף שסדרו אמ\"ש המחבר לפני זה דמדבר בקוצץ פירות מ\"מ מוכרח דכוונתו אאילן הנזכר בכלל דברי המחבר שלפני זה מדכתב ב\"פ נגמרה גדולו ואי אפירות קאי הל\"ל אי נגמר גידולן וק\"ל:"],["\u0003 ולא נתרסק וכו'. \u0004 מלשון זה משמע דאם לא נתרסקו אבריה אלא הי' לה צער בעלמא לא הי' צריך לשלם כלל אבל אי יש לספק בזה צריך לשלם לו מה שהי' נותן שיצילו בהמתו מספק אמנם משמעות לשון התוספות והרא\"ש אינם מורין כן ע' ביש\"ש פ\"ו דב\"ק סי' י\"ג:","\u0003 שהי' לו לשומר'. \u0004 פי' שמירה מעולה ופי' שמירה מעולה או פחותה תמצא בר\"ס שצ\"ו וכו' עכ\"ל סמ\"ע ודלא כהבנת מהרש\"ל דלהרמב\"ם סגי בשמיר' פחותה ואינו כן אלא עכ\"פ צריך שמירה מעולה ולאפוקי הרא\"ש דס\"ל דלא סגי בשמירה מעולה ג\"כ ודוק:","\u0003 מיהו אם שמרה כו'. \u0004 וכ\"פ מהרש\"ל סי' י\"ז:"]],["הַמְשַׁסֶה \u0005(פֵּרוּשׁ, מְשַׁלֵּחַ וּמַקְנִיט)\u0006 כַּלְבּוֹ שֶׁל \u0010y0\u0011 חֲבֵרוֹ בַּחֲבֵרוֹ, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם; וּבַעַל הַכֶּלֶב \u0010y1\u0011 חַיָּב חֲצִי נֶזֶק, שֶׁכֵּיוָן שֶׁהוּא יוֹדֵעַ שֶׁאִם שִׁסָה אֶת כַּלְבּוֹ לְהַזִּיק נוֹשֵׁךְ, לֹא הָיָה לוֹ לְהַנִּיחוֹ. \u0010y2\u0011 וְאִם שִׁסָהוּ בְּעַצְמוֹ, בַּעַל הַכֶּלֶב פָּטוּר, שֶׁכָּל הַמְשַׁנֶּה וּבָא אַחֵר וְשִׁנָּה בּוֹ, פָּטוּר:",["\u0003פטור מדיני אדם \u0004 הטעם דלא הוה אלא גרמא בניזקין:","\u0003חייב ח\"נ \u0004 במ\"מ מבואר דאפילו היה מועד אינו משלם אלא ח\"נ כיון דלא נשך מעצמו אלא ע\"י שיסוי ה\"ל שינוי:","\u0003ואם שיסהו בעצמו. \u0004 פי' ששיסה ראובן כלב של שמעון עד שהלך ונשך לראובן המשסה פטור שמעון דראובן שינה מתחלה בהשסתו וכל המשנה ובא אחר ושינה בו כגון זה שבא שמעון עם כלבו ושינה בו פטור שמעון:"],[]],["שׁוֹר הַמּוּעָד, וְכֵן שֵׁן וָרֶגֶל \u0010y0\u0011 שֶׁהֵן מוּעָדִים \u0010y1\u0011 מִתְּחִלָּתָן, דַּי לָהֶם בִּשְׁמִירָה פְחוּתָה; לְפִיכָךְ, אִם קְשָׁרָם בְּעָלָיו בְּמוֹסֵרָה אוֹ שְׁמָרָם שְׁמִירָה פְּחוּתָה, וְיָצְאוּ וְהִזִּיקוּ, פָּטוּר. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמוּעָד; אֲבָל תָּם לֹא סָגֵי לֵהּ לֹא בְּמוֹסֵרָה וְלֹא בִּשְׁמִירָה פְּחוּתָה, עַד שֶׁיִּשְׁמְרֶנּוּ שְׁמִירָה מְעֻלָּה. אֵי זוֹ הִיא שְׁמִירָה מְעֻלָּה, דֶּלֶת שֶׁיְּכוֹלָה לַעֲמֹד אֲפִלּוּ בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה; וּשְׁמִירָה פְּחוּתָה, שֶׁיְּכוֹלָה לַעֲמֹד בְּרוּחַ מְצוּיָה וְלֹא בְּשֶׁאֵינָה מְצוּיָה. אֲבָל אִם אֵינָהּ יְכוֹלָה לַעֲמֹד אֲפִלּוּ בְּרוּחַ מְצוּיָה, כְּאִלּוּ לֹא שְׁמָרוֹ כְּלָל, וְחַיָּב, אֲפִלּוּ לֹא נָפְלָה הַדֶּלֶת עַל יְדֵי הָרוּחַ אֶלָּא לִסְטִים הוֹצִיאוּהָ, אוֹ חָפְרָה אוֹ חָתְרָה הַדֶּלֶת וְהִפִּילָתוֹ, דִּתְחִלָּתוֹ בִּפְשִׁיעָה לְגַבֵּי נְפִילַת הַדֶּלֶת, וְסוֹפוֹ בְּאֹנֶס לְגַבֵּי חֲתִירָה, וְקַיְמָא לָן כָּל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ \u0010y2\u0011 בְּאֹנֶס הַבָּא מֵחֲמַת הַפְּשִׁיעָה, חַיָּב. אֲבָל אִם חָתְרָה פִּרְצָה וְיָצְאָה מִשָּׁם, פָּטוּר, שֶׁאֵין הָאֹנֶס בָּא מֵחֲמַת הַפְּשִׁיעָה.\nשְׁמָרָהּ כָּרָאוּי \u0010y3\u0011 וְנִפְרְצָה בַלַּיְלָה, אוֹ שֶׁחָתְרָה הַדֶּלֶת וְיָצְאָה וְהִזִּיקָה, פָּטוּר, אֲפִלּוּ יָדַע שֶׁנִּפְרְצָה, שֶׁאֵינוֹ חַיָּב לָצֵאת לִטְרֹחַ אַחֲרֶיהָ. וְדַוְקָא נִפְרְצָה בַּלַּיְלָה, אֲבָל נִפְרְצָה בַּיּוֹם, חַיָּב, דְּקָלָא אִית לְמִלְּתָא וּמִסְתָמָא יָדַע.\nהוֹצִיאוּהָ לִסְטִים, \u0010y4\u0011 הֵם חַיָּבִים מִשְּׁעַת מְשִׁיכָה אוֹ שֶׁהִכִּישׁוּהָ בְּמַקֵּל לְהוֹצִיאָהּ. וְדַוְקָא שֶׁהוֹצִיאוּהָ כְּדֵי לְגָזְלָהּ, אֲבָל הוֹצִיאוּהָ \u0010y5\u0011 \u0010c0\u0011 כְּדֵי לְאַבְּדָהּ, פְּטוּרִים. \u0010c1\u0011\nהַפּוֹרֵץ גָּדֵר לִפְנֵי בֶּהֱמַת \u0010y6\u0011 חֲבֵרוֹ וְיָצְאָה וְהִזִּיקָה, אִם הָיָה גָּדֵר בָּרִיא וְחָזָק, חַיָּב. \u0005וְיֵשׁ אוֹמְרִים דְּאֵינוֹ חַיָּב בְּנִזְקֵי הַבְּהֵמָה אֶלָּא אִם הִכִּישָׁהּ וְהִזְמִינָהּ לְנֶזֶק, וְכֵן עִקָּר (טוּר בְּשֵׁם הָרַאֲבַ\"ד וְהַמַּגִּיד פ\"ד דְנ\"מ)\u0006. \u0010y7\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ עַל הַבְּהֵמָה עַצְמָהּ אֵינוֹ חַיָּב, אִם נֶאֶבְדָה \u0005(טוּר)\u0006. וְאִם הָיָה כֹּתֶל רָעוּעַ, פָּטוּר מִדִּינֵי אָדָם \u0010y8\u0011 וְחַיָּב בְּדִינֵי שָׁמַיִם:\nהִנִּיחָהּ בַּחַמָּה, אֲפִלּוּ חָתְרָה וְיָצְאָה וְהִזִּיקָה, חַיָּב זֶה שֶׁהִנִּיחָהּ שָׁם, שֶׁכֵּיוָן שֶׁהִנִּיחָהּ בַּחַמָּה הֲרֵי הִיא מִצְטַעֶרֶת וְעוֹשָׂה כָּל שְׁאֶפְשָׁר לָהּ לַעֲשׂוֹת לִבְרֹחַ. \u0005הַגָּה: וְלָכֵן אֲפִלּוּ הָיְתָה קְשׁוּרָה בְּקֶשֶׁר חָזָק, חַיָּב (טוּר)\u0006.\nמָסַר הַשּׁוֹר לְחֵרֵשׁ, שׁוֹטֶה וְקָטָן, אַף עַל פִּי שֶׁהָיָה הַשּׁוֹר קָשׁוּר, הַבְּעָלִים \u0010y9\u0011 חַיָּבִין, שֶׁדֶּרֶךְ הַשּׁוֹר לְהַתִּיר הַקֶּשֶׁר וְלָצֵאת וּלְהַזִּיק. \u0010y10\u0011 אֲפִלּוּ שְׁמָרוּהוּ שְׁמִירָה מְעֻלָּה, וְחָתְרָה וְיָצְאָה וְהִזִּיקָה, הַבְּעָלִים חַיָּבִים.\nמָסַר שׁוֹרוֹ לַחֲמִשָּׁה בְּנֵי אָדָם, וּפָשַׁע בּוֹ אֶחָד מֵהֶם וְיָצָא וְהִזִּיק, אִם אֵינוֹ מִשְׁתַּמֵּר אֶלָּא בַּחֲמֶשְׁתָּן, זֶה שֶׁפָּשַׁע בִּשְׁמִירָתוֹ חַיָּב; וְאִם מִשְׁתַּמֵּר בַּשְּׁאָר, \u0010y11\u0011 אַף אֵלּוּ הַנִּשְׁאָרִים חַיָּבִים. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהָנֵי מִלֵּי, כְּשֶׁאָמְרוּ לוֹ: כֵּיוָן שֶׁאֵינְךָ רוֹצֶה לְשָׁמְרוֹ גַם אָנוּ מְסֻלָּקִים מִשְּׁמִירָתוֹ, אֲבָל אִם לֹא נִסְתַּלְּקוּ מִשְּׁמִירָתוֹ, \u0010y12\u0011 הוּא פָּטוּר וְהֵם חַיָּבִים.\nמְסָרוֹ לְאֶחָד מֵאַרְבָּעָה שׁוֹמְרִים, \u0010y13\u0011 מִסְתָמָא קִבֵּל עָלָיו שֶׁלֹּא יַזִּיק, וְשֶׁלֹּא יֻזָּק. וְהָנֵי מִלֵּי בְּשׁוֹר סְתָם, אֲבָל אִם מַכִּיר בּוֹ שֶׁהוּא נַגְחָן, אֵינוֹ מְקַבֵּל עָלָיו אֶלָּא שֶׁלֹּא יַזִּיק, \u0010y14\u0011 אֲבָל לֹא שֶׁלֹּא יֻזָּק. וְאִם לֹא שְׁמָרוּהוּ כְּלָל, וְיָצָא וְהִזִּיק, נִכְנְסוּ תַּחַת הַבְּעָלִים וְחַיָּבִים לְשַׁלֵּם תָּם חֲצִי נֶזֶק וּמוּעָד נֶזֶק שָׁלֵם, \u0010y15\u0011 וְהַבְּעָלִים פְּטוּרִים. \u0010y16\u0011 וְאִם אַחַר שֶׁהִזִּיק הַתָּם בִּרְשׁוּתוֹ אוֹמְרִים לַבְּעָלִים: הֲרֵי שֶׁלְּךָ לְפָנֶיךָ, לֹא אָמַר כְּלוּם, שֶׁהֲרֵי בֵּית דִּין לוֹקְחִים אוֹתוֹ לְהִשְׁתַּלֵּם מִגּוּפוֹ. \u0010y17\u0011 וְאִם שְׁמָרוּהוּ כָּרָאוּי \u0010y18\u0011 שְׁמִירָה מְעֻלָּה, הַשּׁוֹמְרִים פְּטוּרִים, וְהַבְּעָלִים חַיָּבִים בְּנֶזֶק קֶרֶן בִּלְבַד שֶׁהִיא תַמָּה, אֲבָל בְּנֶזֶק שֵׁן וָרֶגֶל גַּם הַבְּעָלִים פְּטוּרִים. וְאִם שְׁמָרוּהוּ שְׁמִירָה פְּחוּתָה, אִם שׁוֹמֵר חִנָּם הוּא פָטוּר, וְאִם שׁוֹמֵר שָׂכָר אוֹ שׂוֹכֵר אוֹ שׁוֹאֵל הוּא, חַיָּבִים:\nמְסָרוֹ הַשּׁוֹמֵר לְשׁוֹמֵר אַחֵר וְהֻזָּק, חַיָּב, שֶׁשּׁוֹמֵר שֶׁמָּסַר לְשׁוֹמֵר \u0010y19\u0011 חַיָּב, אֲפִלּוּ שׁוֹמֵר חִנָּם שֶׁמָּסַר לְשׁוֹמֵר שָׂכָר. וְאִם הִזִּיק, \u0010y20\u0011 חַיָּב הַשּׁוֹמֵר הָרִאשׁוֹן לְשַׁלֵּם לַנִּזָּק, וְיֵלֶךְ לַעֲשׂוֹת דִּין עִם הַשּׁוֹמֵר הַשֵּׁנִי. וְאִם מְסָרָהּ שׁוֹמֵר רִאשׁוֹן לִבְנוֹ אוֹ לְבֶן בֵּיתוֹ אוֹ לַמְסַעֲדוֹ, נִכְנְסוּ תַּחַת הַשּׁוֹמֵר, וְחַיָּבִים.\nאִם הִזִּיק שׁוֹרוֹ שֶׁל שׁוֹאֵל לְשׁוֹרוֹ שֶׁל מַשְׁאִיל אוֹ אִפְּכָא, נִתְבָּאֵר בְּסִימָן שמ\"ז.",["\u0003שהן מועדין מתחלתן. \u0004 נתבאר לעיל בסי' שפ\"ט בדברי הטור והמחבר ע\"ש:","\u0003די להן בשמירה פחותה כו'. עד שמרה שמיר' פחות' פטור \u0004 עפ\"ר שם כתבתי דלהרמב\"ם הן פטורין לגמרי אפי' מח\"נ ולתו' והרא\"ש אינן פטורין אלא מנ\"ש כדין שור המועד אבל ח\"נ חייב דלא עדיף לענין ח\"נ לאחר שנעשה מועד מבעוד היותו תם והטעם דבמועד סגי בשמירה פחות' משא\"כ בתם כן הוא בגמ' וכתבתיו ג\"כ בפרישה והוא דסתם שוורים בחזקת שימור קיים דאין לך אדם שאין משמר את שורו לפחות שמירה פחותה ואפ\"ה חייבו התורה אשור תם אלמא שמירה מעול' בעי והדר כתב רחמנא ולא ישמרנו גבי מועד דנעביד ליה שמירה וה\"ל ריבוי אחר ריבוי ואינו אלא למעט ומיעט דאין צריך בו שמירה מעולה וגבי שן ורגל (שהן מועדין מתחלתן) ובער ושלח כתיב דמשמע דאינו חייב עליהן עד דה\"ל דומה כאלו ביער ושלח בידים דהיינו שלא שמרו כלל הא עבד שמירה כל דהו אינו חייב בהו:","\u0003הבא מחמת פשיעה כו'. \u0004 וה\"נ מיקרי מחמת פשיעה דאלו העמיד לפני' דלת חזקה לא היתה נופלת הדלת מחמת שחתר' בקרקע או נגחה בהדלת עצמה:","\u0003ונפרצה בלילה או שחתרה. \u0004 האי שחתרה ג\"כ אבלילה שלפניו קאי ומ\"ש אח\"כ ודוקא שנפרצה בלילה כו' חדא מנייהו נקט וק\"ל:","\u0003הם חייבים משעת משיכה. \u0004 פי' הגזלן חייב על מה שהזיקה הבהמה אע\"ג דהגזלן לא קני ליה במשיכה דמאן א\"ל למשוך מ\"מ כיון דעשה בה דבר הקונה במקח ובממכר והיא עתה ברשותו חייב בשמירתו כ\"כ התוס' והרא\"ש ועפ\"ר ולא כע\"ש שכתב שחייבים משום דקנאה במשיכה:","\u0003כדי לאבדה פטורי'. \u0004 כ\"כ הרא\"ש והטור הטעם כיון דלא עשה מעשה בהבהמה שיקנה בה וגם לא עלתה על דעתו לקחנה לנפשו מעולם לא באתה לרשותו לחייב על נזקי' אבל אם נאבדה הבהמה חייב לשלמה לבעלים אם הוציאו' בידים ודוקא בפרץ גדר לפני בהמת חבירו ונאבדה כתב הטור והמחב' בסמוך די\"א דפטור אם נאבדה משום דלא עשה בה מעשה בידים בהוצאתה כלל:","\u0003ויצאה והזיקה כו'. \u0004 עד\"ר שם כתבתי מה שהקשו חכמי לוני\"ל להרמב\"ם בזה ומה שהשיב להן:","\u0003דאפי' על הבהמה עצמה אינו חייב. \u0004 הטעם דה\"ל גרמא בניזקין דהא לא עביד מעשה בגוף הבהמה וע\"ל בסי' קנ\"ז בטור ס\"ו ובדברי המחבר ונראה דאינו פטור מבהמה אלא בדיני אדם אבל בדיני שמים ודאי חייב ק\"ו מכותל רעוע:","\u0003וחייב בדיני שמים. \u0004 ועפ\"ר שם כתבתי דהתוס' כתבו דדוקא אבהמה שהזיקה חייב ולא אהכותל כיון שהיתה רעוע ושהרא\"ש כ' שאפשר דגם על הכותל חייב דהא ראוי' לעמוד יום או יומים עד שימצאו פועלים ויתקננה כו' וכן נראה שהוא דעת הטור והמחבר שסתמו וכתב חייב ולהרמב\"ם חייב אפי' אכותל רעוע בדיני אדם עד\"ר:","\u0003שדרך השור להתיר הקשר. \u0004 כל' זה כתב ג\"כ הרמב\"ם ובפרישה כתבתי דאין נראה לפרשו כמשמעו דהשור מתיר הקשר מעצמו וכדפירש\"י שם בפ\"ק דב\"ק דא\"כ לא ה\"ל לכתבו בפשיעת הבעלים במה שמסרו ליד חש\"ו דהא אף בלי חש\"ו היה מתיר הקשר ויוצא ועוד דל' להתיר דקאמר לא שייך בבהמה ולכאור' היה נראה לומר דטעות נפלה בדפוס בספרי הרמב\"ם וש\"ע דמ\"ש דדרך השור להתיר צ\"ל דררך חש\"ו והוא ?ר\"ח חרש שוטה וקטן אלא שקשה להגי' הספרים ועוד דא\"כ לא ה\"ל להרמב\"ם לכתוב שדרך השור וכיוצא בו אלא כיוצא בהן לכן היותר נראה דל' הגמ' דפ\"ק דב\"ק נקט ובגמ' שם אמרינן שור דרכו לנתק ופי' התו' שם דר\"ל דרכו ע\"י החש\"ו וכן משמע מל' המ\"מ שכ' אדברי הרמב\"ם הנ\"ל ז\"ל פי' רבי' דהשור קשור כראוי ואפ\"ה הוא חייב שדרכן של אלו לשחק בהן ולהתירן וכיון שכן ה\"ל תחלתו בפשיעה ואפי' סופו באונס כגון שחתרה חייב עכ\"ל:","\u0003ומ\"ש אפי' שמרוהו שמירה מעולה וחתרה כו'. \u0004 נ\"ל דה\"פ בשעה שמסר' הבהמ' ליד חש\"ו קשרו הבעלים לבהמה בקשר חזק והניחוה בידם בלי סגירת הדלת בפני הבהמ' כי סמכו הבעלים על החש\"ו ועל קשירת הבהמ' ולאחר זמן מצאו הבהמ' ניתקה והזיק' וקאמר דחייבי' הבעלי' אפי' עשו החש\"ו עוד שמירה מעולה להבהמ' והיינו שנעלו בפניה הדלת שיכול' לעמוד דהוא הנקרא שמיר' מעול' כנ\"ל אלא שהבהמ' יצא' בחתירה והזיק' אע\"פ שזהו אונס כנ\"ל אפ\"ה כיון שפשעו הבעלי' מתחל' במה שסמכו על הקשר כיון שדרך החש\"ו לנתק הקשר אמרי' דודאי גם קשר זה התירוהו וה\"ל כאלו לא עשו להבהמ' שום שמירה ויצא' מתחת ידה והזיק' ואע\"ג דבעלמ' בעינן שיבא האונס מחמת הפשיעה וכמ\"ש לעיל בסימן רצ\"א שאני הכא דאותו הפשיע' הראוי לבא בשעה שמסרו הבהמ' ליד החש\"ו דהיינו שתצא ותזיק היא הנעשית לבסוף מ\"ה אע\"פ שנעשה באונס מחויבים הבעלי' עליה ועמ\"ש לקמן בסי' ת\"י ס\"ט [סכ\"ד] במכסה הבור בכיסוי שאינו ראוי לעמוד בפני גמלים כו':","\u0003אף אלו הנשארים חייבים. \u0004 דהשמיר' מוטלת על כל א' ולא הי' לזה להסתלק בלי רשותם:","\u0003הוא פטור כו' \u0004 דיכול לומר סמכתי עליכם דהא לכלנו מסרו לכל מי שיכול לשמרו:","\u0003מסתמא קבל עליו כו' \u0004 פי' כיון דקיבל לשומרו כל שמיר' סתם היא שלא יזיק ושלא יוזק:","\u0003אבל לא שלא יוזק. \u0004 דסתמא לא קיבל עליו נטירותא אלא למה שהי' מוחזק ולא סלקא אדעתיה לשומרו שלא יוזק דהא עד היום לא הי' השור מתיצב לנגדו:","\u0003והבעלים פטורים. \u0004 דמאי הוה ליה למעבד דהא העמיד השומר במקומו לשומרו:","\u0003ואם אחר שהזיק התם.\u0004 כצ\"ל ודוקא תם דאינו משלם אלא מגופו דינא הכי משא\"כ במועד אחר שהזיק יכול השומר לומר לבעלי' הרי שלך לפניך ואני אשוה את נפשי עם הניזק דהרי אינו משתלם מגופו:","\u0003ואם שמרוהו כראוי כו'. עד והבעלים חייבים כו' \u0004 כלשון זה תמצא ברמב\"ם בפ\"ז דנ\"מ ובהמ\"מ דכ? עליו דהיינו בנזק קרן כו' ע\"ש והטור כ' על דברי הרמב\"ם ז\"ל ואיני מבין דבריו כיון ששמרוהו כראוי למה יהיו הבעלי' חייבים וכן השיג עליו הראב\"ד עכ\"ל ומ\"ש המ\"מ והמחבר דמיירי בנזקי קרן כ' הב\"י דבזה מיושב התמיה וז\"א דגם בהיזק קרן אינם חייבי' הבעלי' אלא בשמירה פחות' ולא בשמירה מעולה וכמש\"ר בר\"ס זה גם הרמב\"ם כ\"כ בפ\"ז דנ\"מ ועפ\"ר שם כתבתי בשם הכ\"מ שחכמי לוני\"ל הקשו ג\"כ קושי' זו להרמב\"ם והשיב בעצמו שט\"ס היא בספרים וכצ\"ל אבל אם שמרו בו שמיר' מעולה ויצתה והזיקה השומרים פטורים שמרוהו שמירה פחותה אם ש\"ח הוא פטור והבעלי' חייבים ואם ש\"ש או שוכר או שואל חייבים עכ\"ל. ובפרישה הוכחתי שטעות זה נראה וניכר מתוך נוסח ספרי הרמב\"ם שבידינו שכ' שם ז\"ל. אבל אם שמרו שמירה מעולה השומרי' פטורים והבעלים חייבים אפי' המיתה את האדם שמרוהו שמירה פחות' ש\"ח פטור ואם ש\"ש כו' וקשה חדא דהאי אפי' המיתה ע\"כ אשומרי' פטורים קאי וקשה למה הפסיק בתיבת בעלים חייבי' ועוד בסיפא כשאמר ש\"ח פטור הל\"ל והבעלי' חייבים א\"ו ט\"ס הוא הני שני תיבות והבעלים חייבי' שכתבם ברישא וצריכים להעמיד' בסיפא אצל שמירה פחותה וכנ\"ל וכתבתי עוד בדרישה שנראה פשוט שכן הי' נוסחת הרמב\"ם ג\"כ לפני המ\"מ ושבדברי המ\"מ נפל הטעות (מהמדפיס שסבר שנוסחא המוטעת שבידינו עיקר והגיה כן בדברי המ\"מ) וכצ\"ל שם ומ\"ש והבעלי' חייבים כששמרוה שמירה פחותה הוא כגון קרן וע\"ז שפיר מסיק וכ' ז\"ל כמ\"ש בפ\"ז דשם בפ\"ז אשמיר' פחותה קאי ע\"ש אבל על דברי המחבר כאן יש לתמוה שתפס ל' המ\"מ כאשר הוא נדפס בטעות והוא סותר למ\"ש בר\"ס זה ודוק.","\u0003ומ\"ש השומרים פטורי'. \u0004 ר\"ל אפי' השואל דאע\"ג דהשואל חייב באונסין היינו דוקא אם הוזקה הבהמ' שהוא שומר עלי' ולא לענין אם יצאת' והזיקה ועפ\"ר:","\u0003ואפי' ש\"ח שמסר לש\"ש. \u0004 פי' אע\"ג דש\"ש צריך לשומרו טפי מש\"ח מגניבה ואביד' וכבר נתבאר זה בסי' רצ\"א ע\"ש:","\u0003חייב השומר הראשון כו'. \u0004 מ\"מ אם ירצה הניזק יעשה דין עם השני אלא שקאמר שגם דינו עם הראשון דהוי ליה פשיעה גביה שמסרו לשני דיכולין הבעלי' לומר אתה נאמן עלי בשבועה ולא האחר ול\"ד לבעל השור שמוסר בהמתו להשומר דהשומר חייב כמ\"ש בסעיף שלפני זה דשם ברשות נתנו להשומר וכן אם נתנו השומר לבנו כו' דכ' המחבר אחר זה דהוא ברשות דכל המפקיד לאדם על דעת אשתו ובניו הוא מפקיד וכמ\"ש הטור והמחבר ג\"כ בסי' רצ\"א ע\"ש:"],["\u0003 כדי לאבדה. \u0004 פטורים על הנזק אבל [לא] על הבהמה עצמה אע\"פ שלא הי' דעתם אלא לאבדה וכדלעיל סי' שפ\"ו גבי זורק מטבע לים הגדול ואפשר דבהכיש' אפילו לאבדה ונאבד' פטור וצ\"ע:","\u0003 הפורץ גדר לפני בהמתו כו' \u0004 ע' בתשובת רשד\"ם סי' שס\"ה:"]],["מִי שֶׁבְּהֶמְתּוֹ רְגִילָה לִכָּנֵס לִשְׂדֵה חֲבֵרוֹ וּמַזִּיקָתוֹ, \u0010y0\u0011 יָכוֹל בַּעַל הַשָּׂדֶה לְהַתְרוֹת בְּבַעַל הַבְּהֵמָה שֶׁיִּשְׁמֹר בְּהֶמְתּוֹ, וְצָרִיךְ לְשָׁמְרָהּ. \u0005וְאִם לֹא שְׁמָרָהּ וְהִזִּיקָה, \u0010c0\u0011 חַיָּב לְשַׁלֵּם הֶזֵּקוֹ (כֵּן מוּכָח מִדִּבְרֵי הַתוס' וְהָרֹא\"שׁ)\u0006. \u0010y1\u0011 וְאֵינוֹ יָכוֹל לוֹמַר לוֹ: גְּדֹר שָׂדְךָ כְּדֵי שֶׁלֹּא תִּכָּנֵס בּוֹ:\nהַקַּצָּבִים שֶׁיֵּשׁ לָהֶם בְּהֵמוֹת לִשְׁחֹט בְּיוֹם הַשּׁוּק, אִם הֵם מַזִּיקוֹת \u0010y2\u0011 \u0010y3\u0011 אֲפִלּוּ בִרְשׁוּת הָרַבִּים, מַתְרִים בַּבְּעָלִים שָׁלֹשׁ פְּעָמִים שֶׁיִּשְׁמְרוּם, וְאִם לֹא שְׁמָרוּם, רַשַּׁאי הַנִּזָּק לְשָׁחֲטָם שְׁחִיטָה כְּשֵׁרָה, וְאוֹמְרִים לַבְּעָלִים: בּוֹאוֹ וּמִכְרוּ הַבָּשָׂר שֶׁלָּכֶם:",["\u0003יכול הבעל השדה להתרו' כו'. \u0004 אבל לא לשחטם כמ\"ש בסעיף שאחר זה ששם מיירי מבהמות של קצבים שעומדי' לשחיטה אלא שהקצבים רוצים להשהות עד יום השוק שיכולין למכור אז הבשר ביוקר וקאמר דמשום הזיקתן מקדימין שחיטתן אם לא ישגיחו הקצבים בההתרא' משא\"כ כאן דאיירי בסתם בהמות דאינן עומדין לשחיטה:","\u0003ואינו יכול לומר לו גדור כו'. \u0004 דעל הבעלי' לשמור בהמת' שלא יזיקו ודומה זה לבהמה האוכלת מתוך החנות דחייבי' בעלי' לשלם לבעל החנות היזקתו כמ\"ש הטור והמחבר בסי' שצ\"א ואינו יכול לומר לו ה\"ל לסגור חנותך ע' בטור שם כ' שר\"ת והרא\"ש חולקין ע\"ז וס\"ל דאינו דומה לאכל' מתוך החנות ע\"ש ובפרישה:","\u0003אפי' בר\"ה. \u0004 ר\"ל אף דשם רשות המזיק והניזק שוה וה\"ל להניזק לשמור עניינו משור המזיק:","\u0003מתרין בבעלי' ג\"פ. \u0004 לא קאמר שצריכין שיזיקו ג\"פ אלא אף שלא הזיקו אלא פעם א' ואחר ההיזק התרו בבעלי' ג\"פ הרשות ביד הניזק לשחטם אם לא שמרם ואף אם ישיב בעל הבהמ' אם יהי' למי היזק מבהמתי אשלמנה לא משגיחין ביה דאין אדם רוצה להיות ניזק ולהטפל נפשו בתשלומין וגם ניחא לאדם בשלו והיינו דוקא בבהמת הקצבים דבלה\"נ עומדי' לשחיטה ביום השוק וכנ\"ל:"],["\u0003 חייב לשלם הזיקו ואינו יכול כו'. \u0004 ב\"י כתב שכך הם דברי הרמב\"ם פ\"ה מהל' נזקי ממון ועיינתי שם בכל דברי הרמב\"ם בהלכות נזקי ממון חפשתי ולא מצאתי דבר מזה ואי משום שכ' הרמב\"ם שם שחייב לשלם כשהזיקה הבהמה בשדות אחרות אין ראיה דהא בקרא נמי כתיב ובער בשדה אחר ומוקמינן לה בש\"ס כשגדר וחתרה או נפל בלילה וגם מ\"ש ב\"י שאין בדברי הרא\"ש הכרע דבריו תמוהין שהרי הרא\"ש מביא במסקנתו דברי רבינו חננאל ודוחה דברי התוס' ע\"ש ושפיר כ' הטור שמסקנת הרא\"ש כר\"ח: ומהרש\"ל כתב בפ\"ק דב\"ק סי' כ\"ה דלא נהירא כלל דברי ר\"ח דא\"כ למה סתם רועים גזלנים ופסולי' לעדות לפי שאינם נזהרים משדות אחרות ואי היה צריך לגדור כל אדם שדהו מסתמא כל השדות גדורים הם וא\"כ איך נכנס' בשדות אחרים כי מה שהבהמה חתר' הגדר לא שכיח כו' לכן נ\"ל כרב יוסף דהוא רבו של אביי ואין הלכה כתלמיד במקום הרב כו' עכ\"ל ודבריו לא נהירין לי דנהי דפטו' כשהזיק מ\"מ מסתמא כל השדות אינם גדורים ופוק חזי דאין דרך בני אדם לגדור שדותיהם דא\"כ צריך לגדור כל העולם אלא אין חוששין להיזק בהמות דלא שכיח שיזיקו בהמות בשדות אחרות והגע עצמך אף לדברי מהרש\"ל דחייב וכי בכל פעם יהיו לו עדות שהזיק' או פעמים שהוא עצמו לא ידע מהיזק הבהמות אלא ודאי אין חוששין לכך וכמ\"ש וסתם רועה פסול לעדות משום שרועה במזיד בשדות אחרות. גם בלאו הכי תימה על מהרש\"ל איך רוצה להכריע נגד אביי והלא אין בידינו להכריע מה שנחלקו בו חכמי הש\"ס והלא בע\"כ גם אביי מודה להא דסתם רועים פסולי' אלא ודאי כמ\"ש וגם על התוס' קשה כן שכתבו דאין הלכה כאביי משום דתניא אכלה מתוך החנות כו' ומ\"ש התוס' דאביי אשתמוטי קמשתמיט דוחק גדול הוא. גם מ\"ש מהרש\"ל דאין הלכ' כתלמיד במקו' הרב לא נ\"ל ואדרבא הא קי\"ל דהלכ' כבתראי מאביי ורבא ואילך ואולי כוון למ\"ש הנ\"י דאביי נגד רב יוסף תלמיד היושב לפני רבו היה באותו מעש' אבל גם זה לא נ\"ל ואדרבא משמע מדשתיק ליה רב יוסף אודי ליה ועוד דמשמע דהא דגרסי' בש\"ס ואי גדר שן דחייב רחמנא היכא משכחת לה כו' משמע דסתמא דש\"ס הוא דקפריך הכי דאי רב יוסף קא' לה הל\"ל אמ\"ר לי\"ה ואי שן כו' וא\"כ כיון דסתמא דש\"ס קאמר משמע דסתמא דש\"ס ס\"ל כאביי מדמשני אליבא דאביי כשחתר' או דנפל בלילה ואפי' תימא דרב יוסף קאמר לה מ\"מ משמע דקבל שינוי דאביי שחתר' כו' וכן מצאתי בהלכות גדולות דף פ\"ז סוף ע\"ג שכ' כדברי אביי וכ\"כ ראב\"ן בב\"ק דף פ\"ו ריש ע\"ב וז\"ל מהכא שמעינן דשן דחייב רחמנא בשד' אחר לא מיחייב אלא כשחתר' או דנפל גודא בלילה אבל אי לא גדר ארעי' ונכנסה בהמה ואכל' פטור עכ\"ל כיון דהלכות גדולות ורבינו חננאל וראב\"ן והרא\"ש וטור סוברים דפטור הכי נקטינן דכבר נודע שדברי ה\"ג ור\"ח דברי קבלה הם מהש\"ס ובפרט שהוכחתי שדבריהם עיקר:"]],["הִכְנִיס שׁוֹרוֹ לַחֲצַר חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וּנְגָחוֹ שׁוֹרוֹ שֶׁל בַּעַל הֶחָצֵר, פָּטוּר. וְכֵן אִם הִזִּיקוֹ בַּעַל הֶחָצֵר, פָּטוּר, שֶׁיָּכוֹל לוֹמַר: כֵּיוָן שֶׁהִכְנִיסוֹ שֶׁלֹּא לְדַעַת לֹא יָדַעְתִּי בּוֹ עַד שֶׁשָּׁגִיתִי בּוֹ. וּמִיהוּ, אִם הִזִּיקוֹ לְדַעַת, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם, שֶׁאַף עַל פִּי שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ מֵרְשׁוּתוֹ, אֵין לוֹ רְשׁוּת לְהַזִיקוֹ.\nהִזִּיק שׁוֹר הַנִּכְנָס לְבַעַל הֶחָצֵר אוֹ לְשׁוֹרוֹ, \u0010y0\u0011 דִּינוֹ כְּאִלּוּ הִזִּיקוֹ בִּרְשׁוּת הָרַבִּים, וּמְשַׁלֵּם תָּם חֲצִי נֶזֶק וּמוּעָד נֶזֶק שָׁלֵם.\nקִלְקֵל אֶת הֶחָצֵר, כְּגוֹן שֶׁחָפַר בּוֹ בּוֹרוֹת שִׁיחִין וּמְעָרוֹת, בַּעַל הַשּׁוֹר חַיָּב בְּנִזְקֵי הֶחָצֵר, \u0010y1\u0011 וּבַעַל הֶחָצֵר חַיָּב בְּנִזְקֵי הַבּוֹר, מִפְּנֵי שֶׁהָיָה לוֹ לְסָתְמוֹ.\nנָפַל לְבוֹר שֶׁבֶּחָצֵר וְהִבְאִישׁ אֶת מֵימָיו; אִם הִבְאִישָׁם \u0010y2\u0011 בִּשְׁעַת נְפִילָה, חַיָּב בְּנִזְקֵי הַמַּיִם; וְאִם הִבְאִישָׁם אַחַר נְפִילָה, פָּטוּר, \u0010y3\u0011 שֶׁהֲרֵי נַעֲשָׂה כִּשְׁאָר תַּקָּלָה שֶׁחָשׁוּב כְּבוֹר, וְהַמַּיִם חֲשׁוּבִים כְּכֵלִים, \u0010y4\u0011 וּבוֹר פָּטוּר בְּנִזְקֵי כֵלִים. \u0010c0\u0011\nאִם הִכְנִיסוֹ \u0010y5\u0011 בִּרְשׁוּת בַּעַל הֶחָצֵר, פָּטוּר בַּעַל הַשּׁוֹר. \u0010y6\u0011 \u0010c1\u0011 וְאִם הִזִּיק שׁוֹר בַּעַל \u0005הֶחָצֵר\u0006 לַשּׁוֹר הַנִּכְנָס בִּרְשׁוּת, פָּטוּר, אֶלָּא אִם כֵּן קִבֵּל עָלָיו בַּעַל הֶחָצֵר שְׁמִירָתוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּכֵיוָן דְּנָתַן לוֹ רְשׁוּת לִכָּנֵס הָוֵי כְּאִלּוּ קִבֵּל עָלָיו שְׁמִירָתוֹ. וְדַוְקָא בִּנְזִיקִין דְּאָתוּ לֵהּ מִבַּעַל הֶחָצֵר, אֲבָל \u0010c2\u0011 בִּנְזִיקִין דְּאָתוּ לֵהּ מֵעָלְמָא, אֵינוֹ חַיָּב עַד שֶׁיְּקַבֵּל עָלָיו שְׁמִירָתוֹ (טוּר בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.",["\u0003דינו כאלו הזיקו בר\"ה כו' ול\"ת דאפי' תם ישלם נ\"ש בהיזק דקרן מק\"ו דשן ורגל שאין משלמין עליהן בר\"ה אפ\"ה משלמין עליהן ברשו' הניזק נ\"ש קמ\"ל דלא אלא אמרינן דיו הואיל דבר\"ה אינו משלם אקרן כ\"א ח\"נ גם ברשות הניזק ישלם כן ועמ\"ש בסימן שפ\"ט:\u0004","\u0003ובעל החצר חייב בנזקי הבור. \u0004 והיינו דוקא בדהפקיר אח\"כ רשותו שסביב הבור ולא הפקיר הבור דאל\"כ ה\"ל בור בחצר המזיק ויכול לומר לניזק אנת ברשותי מאי בעית וכדמוכח בדברי הטור והמחבר בסי' ת\"י ס\"ב [ס\"ו] או שהבור הוא ברשותו סמוך לר\"ה וכמ\"ש הטור והמחבר שם:","\u0003בשעת נפילה חייב. \u0004 פי' שור תם ח\"נ ומועד נ\"ש כדין קרן:","\u0003שהרי נעשה כשאר תקלה שחשוב כבור. \u0004 פי' כבור דבעל השור:","\u0003ובור פטור בנזקי כלים. \u0004 לקמן סימן ת\"י ילפינן מדכתיב שור ולא אדם חמור ולא כלים ולא אמרינן דבל\"ה פטור כיון דלא סלקן בעל החצר וכמ\"ש הטור והמחבר שם בסימן ת\"ג ובסימן ת\"י דעל הניזק לסלק דבר המזיק והמזיק ישלם לו הוצאתו וטירחתו דשאני בסימן ת\"י דמאחר שמשלם לו בעל השור היזקו דחצירו שוב נקרא הוא בעל הבור כיון דהחצר הוא שלו גם בסי' ת\"ג ס\"ג דשם הדין נותן שמשלם המזיק להניזק נזקו בהנביל' אלא שצריך המזיק למסור הנביל' ליד הניזק וכמ\"ש שם בזה אמרו דלאחר שנודע להניזק מההיזק עליו להשתדל למכור הנביל' כדי שלא יפחו' דמיה והמזיק משלם לו טירחתו משא\"כ כאן דאין לבעל המים חלק בהשור שנפל למימיו ועפ\"ר:","\u0003ברשות בעל החצר \u0004 פי' שבעל החצר נתן רשות לראובן להכניס שורו לחצרו והזיק שור ראובן לשור בעל החצר בזה כ\"ע מודים דפטו' ראובן מההיזק ואם הוא איפכא דשור בעל החצר הזיק לשור ראובן הנכנס בזה פליגי דהמחב' פסק כר' דס\"ל דאף שנתן לו רשות לראובן להכניס שורו מ\"מ לא קיבל עליו שמירת שורו ומור\"ם הביא דעת הפוסקים כרבנן דס\"ל דמסתמא קיבל עליו שמירת שורו כיון דבעל החצר הוא מסתמא הוא ובני ביתו הן בחצירו משא\"כ זה שהכניס שורו דלא נשאר עומד שם לשמור שורו שלא יזיק לבעל החצר ועפ\"ר וע\"ל בסי' רצ\"א דשם נתבאר פלוגתייהו ועיין ג\"כ בסימן שצ\"ג מ\"ש שיש לתמוה על מור\"ם על מ\"ש שם בהג\"ה ס\"א ע\"ש:","\u0003ואם הזיק שור של בעל החצר כו' פטור. \u0004 דקדק וכ' שור כו' דאילו הזיקו בעל החצר בעצמו לשור הנכנס הי' חייב וכמ\"ש המחבר בס\"א דאם הזיקו לדעת חייב ור\"ל לדעת שידע בו שנכנס אף שנכנס שלא ברשות אפי' בשוגג ומשום דאדם מועד לעולם וכמ\"ש בסימן שע\"ח וכ\"ש כאן שנכנס ברשות:"],["\u0003 אם הכניסו כו'. \u0004 ע' בתשובת ר\"ש כהן ס\"ג סי' ו':","\u0003 ואם הזיק שור כו' \u0004 צ\"ל שיש ט\"ס בדברי הראב\"ד וכמ\"ש הרב המגיד ודלא כדאיתא בטור וב\"ח וכדמוכח בהשגות הראב\"ד ספ\"ג מה' נזקי ממון וע' בש\"ס ובתו' ובלח\"מ פ' ז' מהל' נזקי ממון ודו\"ק וצ\"ע:","\u0003 דאתי ליה מעלמא אינו חייב כו'. \u0004 פי' מהרש\"ל כגון שנכנסו שוורים לחצרו והזיקו לזה אבל אם יצא לחוץ והוזק חייב בעל החצר וה\"ה אם חנק עצמו בחצר דחייב ואף אם יצא והזיק לאחרים חייב בעל החצר ע\"ש באריכות ואין משמעו' לשון מוהר\"ם כן ומכ\"מ דברי מהרש\"ל עיקר ודוק בהרא\"ש:"]],["פָּרָה מְעֻבֶּרֶת שֶׁהִזִּיקָה, גוֹבֶה חֲצִי נֶזֶק \u0010y0\u0011 מִמֶּנָּה וּמִוְּלָדָהּ, מִפְּנֵי שֶׁהוּא כְּגוּפָהּ. \u0010y1\u0011 אֲפִלּוּ לֵיתָא לַפָּרָה, מִשְׁתַּלֵּם כָּל חֲצִי נֶזֶק מֵהַוָּלָד, מִפְּנֵי שֶׁהוּא כְּגוּפָהּ. אֲבָל תַּרְנְגוֹלֶת שֶׁהִזִּיקָה אֵינוֹ גוֹבֶה מִבֵּיצָתָהּ, מִפְּנֵי שֶׁהַבֵּיצָה אֵינָהּ מִגּוּפָהּ, אֶלָּא מֻבְדֶּלֶת וּמֻפְרֶשֶׁת. \u0005הַגָּה: מִיהוּ, אִם הַבֵּיצָה אֲגֻדָּה עֲדַיִן בְּגוּפָהּ, יֵשׁ אוֹמְרִים דְּגוֹבִין מִמֶּנָּה (הַמַּגִּיד פ\"ט דְנ\"מ)\u0006.\nפָּרָה מְעֻבֶּרֶת שֶׁנָּגְחָה, וְנִמְצָא עֻבָּרָה בְּצִדָּהּ, וְאֵין יָדוּעַ אִם קֹדֶם נְגִיחָה יָלְדָה, וְאָז אֵין לְהִשְׁתַּלֵּם מֵהַוָּלָד, אוֹ לְאַחַר נְגִיחָה יָלְדָה וְיֵשׁ לְהִשְׁתַּלֵּם מֵהַוָּלָד, \u0010y2\u0011 וְאֵין הַפָּרָה לְפָנֵינוּ, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה וְלֹא יִטֹּל מֵהַוָּלָד.\nוְכֵן שׁוֹר שֶׁנָּגַח אֶת הַפָּרָה וְנִמְצָא עֻבָּרָה מֵת בְּצִדָּהּ, וְאֵין יָדוּעַ אִם מֵחֲמַת נְגִיחָה הִפִּילָה אוֹ אִם הִפִּילָה קֹדֶם, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וַאֲפִלּוּ שֶׁהַנִּזָּק טוֹעֵן בָּרִי, וְהַמַּזִּיק טוֹעֵן שֶׁמָּא, וַאֲפִלּוּ שֶׁאֵין הַמַּזִּיק \u0010y3\u0011 מֻחְזָק, כְּגוֹן שֶׁעוֹמֶדֶת בָּאֲגַם, \u0010c0\u0011 פָּטוּר \u0010y4\u0011 \u0010c1\u0011 וַאֲפִלּוּ מִשְּׁבוּעָה. \u0005הַגָּה: \u0010y5\u0011 \u0010c2\u0011 מִיהוּ, אִם תָּפַס הַנִּזָּק, נֶאֱמָן, אִם יֵשׁ לוֹ מִגּוֹ דְּלָא הָיוּ דְּבָרִים מֵעוֹלָם (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nנָגַח פָּרָה מְעֻבֶּרֶת וְהִפִּילָה, אֵין שָׁמִין פְּחַת פָּרָה בִּפְנֵי עַצְמָהּ וּפְחַת הַוָּלָד בִּפְנֵי עַצְמוֹ, אֶלָּא שָׁמִין כַּמָּה הָיְתָה הַפָּרָה שָׁוָה כְּשֶׁהָיְתָה מְעֻבֶּרֶת וּבְרִיאָה, וְכַמָּה הִיא שָׁוָה עַכְשָׁיו הִיא וְהַנֶּפֶל שֶׁלָּהּ, וּמְשַׁלֵּם הַפְּחָת, אוֹ חֶצְיוֹ אִם הָיָה תָּם.\nהָיְתָה הַפָּרָה לְאֶחָד וְהַוָּלָד לְאַחֵר, הֲרֵי פְּחַת הַשּׁוּמָן שֶׁפָּחַת גּוּף הַפָּרָה לְבַעַל הַפָּרָה, וּפְחַת הַנֶּפַח \u0010y6\u0011 \u0005דְּהַיְנוּ מַה שֶּׁהָיְתָה נִרְאֵית תְּחִלָּה יוֹתֵר גְּדוֹלָה (טוּר)\u0006 חוֹלְקִין אוֹתוֹ בַּעַל הַפָּרָה עִם בַּעַל הַוָּלָד, וְהַנֶּפֶל שֶׁל בַּעַל הַוָּלָד:",["\u0003ממנה ומולד'. \u0004 פי' אע\"פ שהי' תם ותם אינו משלם אלא מגופו טור:","\u0003אפי' ליתא לפרה \u0004 פי' וה\"א דאין כאן צד חיוב אולד' אבל אי איתא לפרה מה לו למזיק לשלם מהפרה לחוד או גם מהולד דהא א\"צ לשלם אלא חצי נזק דהניזק גם קמ\"ל דמשתלם כל ח\"נ מהולד אפי' ליתא לפרה ול\"ת דלא משתלם מהולד אלא רביע מיהו גם בדאיתא לפרה איכא חידוש בדין זה כגון אם הפרה אינה שוה כשיעור ח\"נ דהניזק:","\u0003ואין הפרה לפנינו. \u0004 וה\"ה אם והיא לפנינו ואינה שוה דמי חצי נזק דהניזק וכמ\"ש אלא משום דמסתמ' שויא כדי דמי חצי נזק מש\"ה כ\"כ וכ\"כ הטור:","\u0003כגון שעומדת באגם כו' שמ\"ה אוקמי' ממונא אחזקת מרא קמא והמע\"ה:\u0004","\u0003ואפי' משבועה. \u0004 פי' היכא דהמזיק טוען ג\"כ ברי או שהניזק אומר ברי לי שאתה יודע השבע לי שאין אתה יודע דבכהאי גוונא בשור המועד צריך לישבע וכמ\"ש הטור והמחבר בסמוך בר\"ס ת' כאן דמיירי בשור תם אינו צריך לישבע והטעם מבואר בטור שכ' ז\"ל דלא רמינן שבועה אנתבע אלא כי היכי דלודי אבל הכא דקנסא הוא ואי מודה מפטר אכפירה נמי לא מחייב שבועה עכ\"ל וכן מבואר לעיל בטור ובדברי המחבר בסי' פ\"ז סכ\"ה ע\"ש גם המחבר רמזו בסמוך ר\"ס ת' ע\"ש:","\u0003מיהו אם תפס כו'. \u0004 כ\"כ הטור בשם הרא\"ש ולא כדעת הרמ\"ה דכתב דלא מהני תפיסה אפי' בלא עדים דכיון דקנסא הוא לא שייך ביה חיוב אלא בעדים:","\u0003דהיינו מה שהיתה נראה כו'. \u0004 כ\"כ בטור ע\"ש:"],["\u0003 פטור כו'. \u0004 כיון דהוי קנס כ\"כ הטור והיינו כשאומר לו הניזק אתה יודע דאל\"כ אפי' במועד פטור מטעם דלא ה\"ל לידע וכדלקמן רס\"ח וכ\"כ הסמ\"ע ס\"ק ה':","\u0003 ואפי' משבוע'. \u0004 ואף שידוע ונתחייב במקצת ע\"פ עדים שראו הנגיח' לא הוי על השאר מחויב שבועה ואינו יכול לישבע משלם בקנס כ\"כ התוס' ר\"פ שור שנגח הפרה ועוד כתבו שם ובנ\"י ובהגה' אשר\"י תירוץ אחר דלא ה\"ל לידע ע\"ש ומטעם הילך לא מיפטר דאף ע\"ג דכתבתי לעיל סי' פ\"ז ס\"א וסי' פ\"ח סעיף כ\"ד דהילך הוי בדבר שהוא בעין אפי' הוא בביתו של נפקד וכ\"כ הנ\"י גופי' בפ\"ק דמציעא היינו דוקא בדבר שהוא של התובע מיד לגמרי והלכך כל היכא דאיתי' ברשותא דמארי' איתי' משא\"כ בשור תם דצריך שומא א\"כ לאו הילך הוא וע' מ\"ש לקמן סי' ת' ס\"ג:","\u0003 מיהו אם תפס כו'. \u0004 כ\"כ הטור בשם הרא\"ש ולא כדעת הרמ\"ה דכתב דלא מהני תפיס' אפי' בלא עדים בקנס וכ\"כ הנ\"י ס\"פ המניח כהרמ\"ה ומשמע שם שהם דברי הרמ\"ה. והב\"ח הקשה דמדברי הרמ\"ה שהביא הרא\"ש ספ\"ק דב\"ק והטור לעיל ס\"ס שמ\"ט מבואר דבפלגא נזקא קנסא מהני תפיסה וצ\"ע עכ\"ל ולא דק דהתם מיירי כשיש לו עדים על הנזק דלא הי' פטור משום מודה בקנס וק\"ל: לשון הטור ולא נהירא לא\"א הרא\"ש ז\"ל כו' ולא מצאתי בהרא\"ש מבואר שחולק על הרמ\"ה בזה. מיהו בס\"פ המניח משמע שם מדבריו דלא כהרמ\"ה שכתב שם גבי שני תמין אם תפס משתלם כדקאמר מזיק אבל כדקאמר ניזק לא כיון שתפס בפני עדים עכ\"ל משמע אי תפס שלא בעדים משתלם כדקאמר ניזק משום מגו והרי הרא\"ש ס\"ל התם להדיא דסוגיא אזלא למ\"ד פלגא נזקא קנסא ע\"ש ואע\"ג דמודה בקנס פטור נרא' דכיון דהיכא דאית ליה מגו נאמן בכל דוכתי אלמ' דתפיסתו בלא עדים חשיב ליה כאלו הביא עדים שכדבריו כן הוא דאל\"כ איך יהא נאמן וא\"כ זה שמוד' ה\"ל כמוד' אחר שבאו עדים ולפ\"ז גם להרא\"ש וטור לא מהני כשתפס ויש לו מגו אלא כשתפס קודם שהוד' וה\"ה בזמן הזה דליכא מומחין ולא חשוב' הודאה וכמ\"ש הרמב\"ן והרא\"ש ספ\"ק דב\"ק והטור לעיל ס\"ס א' א\"כ בכל ענין מהני תפיסה בקנס אם יש מגו כן נ\"ל ודו\"ק:"]],["שׁוֹר שֶׁהָיָה רוֹדֵף אַחַר שׁוֹר אַחֵר, וְהֻזַּק, זֶה אוֹמֵר: שׁוֹרְךָ הִזִּיק, וְזֶה אוֹמֵר: לֹא כִּי \u0010y0\u0011 אֶלָּא בַּסֶלַע לָקָה, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו \u0010c0\u0011 הָרְאָיָה, אֲפִלּוּ נִזָּק טוֹעֵן בָּרִי וּמַזִּיק טוֹעֵן שֶׁמָּא. \u0010c1\u0011 וְאִם טָעַן הַנִּזָּק: אַתָּה יוֹדֵעַ שֶׁשּׁוֹרְךָ הִזִּיק, \u0010c2\u0011 נִשְׁבָּע הֶסֵת שֶׁאֵינוֹ יוֹדֵעַ. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמוּעָד; אֲבָל בְּתָם, פָּטוּר אַף מֵהֶסֵת, שֶׁהֲרֵי אִם הוֹדָה הָיָה פָטוּר, \u0010y1\u0011 הוֹאִיל וְהוּא קְנָס.\nהָיוּ שְׁנַיִם רוֹדְפִים אַחַר אֶחָד, \u0010y2\u0011 וַהֲרֵי עֵדִים שֶׁאֶחָד מֵהֶם הִזִּיק, וְאֵינָם יוֹדְעִים אֵיזֶה מִשְּׁנֵיהֶם, זֶה אָמַר: שׁוֹרְךָ הִזִּיק, וְזֶה אָמַר: שׁוֹרְךָ הִזִּיק, שְׁנֵיהֶם פְּטוּרִים. וְאִם הָיוּ שֶׁל אִישׁ אֶחָד, חַיָּב לְשַׁלֵּם \u0010y3\u0011 מִגּוּף הַפָּחוּת שֶׁבִּשְׁנֵיהֶם. וְאִם הָיוּ מוּעָדִים, מְשַׁלֵּם נֶזֶק שָׁלֵם מִנְּכָסָיו. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁשְּׁנֵי הַשְּׁוָרִים עוֹמְדִים. אֲבָל אִם מֵת אֶחָד מֵהֶם אוֹ אָבַד, וְהָיָה אֶחָד מֵהֶם תָּם, אַף עַל פִּי שֶׁהֵם שֶׁל אִישׁ אֶחָד, פָּטוּר, שֶׁהֲרֵי אוֹמֵר לוֹ: \u0010y4\u0011 הָבֵא רְאָיָה שֶׁזֶּה הָעוֹמֵד הוּא שֶׁהִזִּיק וַאֲשַׁלֵּם לְךָ.\nהָיוּ שְׁנֵי הַשְּׁוָרִים הָרוֹדְפִים אֶחָד גָּדוֹל וְאֶחָד קָטָן, הַנִּזָּק אוֹמֵר: הַגָּדוֹל הִזִּיק, וְהַמַּזִּיק אוֹמֵר: קָטָן הִזִּיק; הָיָה אֶחָד תָּם וְאֶחָד מוּעָד, הַנִּזָּק אוֹמֵר: מוּעָד הִזִּיק, וְהַמַּזִּיק אוֹמֵר: תָּם הִזִּיק; \u0010y5\u0011 הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. \u0005(לֹא הָיָה שָׁם רְאָיָה בְּרוּרָה שֶׁזֶּה הִזִּיק, אֶלָּא עֵדִים מְעִידִים שֶׁאֶחָד מִשְּׁנֵי אֵלּוּ הִזִּיק, מְשַׁלֵּם הַמַּזִּיק כְּמוֹ שֶׁאוֹמֵר)\u0006. \u0010c3\u0011 וְאִם טָעַן הַנִּזָּק: אַתָּה יוֹדֵעַ וַדַּאי שֶׁזֶּה הִזִּיק בְּפָנֶיךָ, הֲרֵי הַמַּזִּיק \u0010c4\u0011 מְשַׁלֵּם מַה שֶּׁהוֹדָה, \u0010y6\u0011 \u0010c5\u0011 וְנִשְׁבַּע \u0010c6\u0011 שְׁבוּעַת הַתּוֹרָה עַל הַשְּׁאָר. \u0005הַגָּה: \u0010c7\u0011 \u0010c8\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין כָּאן שְׁבוּעָה כְלָל, דְּהָוֵי לֵהּ כִּטְעָנוֹ חִטִּין וְהוֹדָה לוֹ בִּשְׂעוֹרִים דְּפָטוּר אַף בַּמֶּה שֶׁהוֹדָה, וַאֲפִלּוּ תָפַס מַפְקִינָן מִנֵּהּ (טוּר ס\"ב בְּשֵׁם הָרֹא\"שׁ)\u0006. וְדַוְקָא טָעַן הַנִּזָּק בָּרִי, אֲבָל אִם טוֹעֵן שֶׁמָּא, מְשַׁלֵּם הַמַּזִּיק כְּמוֹ שֶׁהוּא טוֹעֵן \u0005(שָׁם)\u0006.\nהָיוּ הַנִּזָּקִים שְׁנַיִם, אֶחָד גָּדוֹל וְאֶחָד קָטָן, וְהַמַּזִיקִים \u0005(ב')\u0006 אֶחָד גָּדוֹל וְאֶחָד קָטָן, הַנִּזָּק אוֹמֵר: גָּדוֹל הִזִּיק אֶת הַגָּדוֹל וְקָטָן אֶת הַקָּטָן, וְהַמַּזִּיק אוֹמֵר: לֹא כִּי אֶלָּא הַקָּטָן הִזִּיק אֶת הַגָּדוֹל וְגָדוֹל הִזִּיק אֶת הַקָּטָן, אוֹ שֶׁהָיָה אֶחָד תָּם וְאֶחָד מוּעָד, הַנִּזָּק אוֹמֵר: מוּעָד הִזִּיק אֶת הַגָּדוֹל וְתָם אֶת הַקָּטָן, וְהַמַּזִּיק אוֹמֵר: תָּם הִזִּיק אֶת הַגָּדוֹל וּמוּעָד אֶת הַקָּטָן, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה, וְאִם לֹא הֵבִיא רְאָיָה \u0010c9\u0011 בְּרוּרָה פָּטוּר הַמַּזִּיק, \u0010c10\u0011 שֶׁהֲרֵי \u0005(זֶה)\u0006 כִּטְעָנוֹ לוֹ חִטִּים וְהוֹדָה לוֹ בִּשְׂעוֹרִים, שֶׁהוּא נִשְׁבָּע הֶסֵת וּפָטוּר אַף מִדְּמֵי שְׂעוֹרִים. \u0010c11\u0011 \u0005זוֹ הִיא סְבָרַת יֵשׁ אוֹמְרִים שֶׁכָּתַבְתִּי בְּסָמוּךְ. אֲבָל יֵשׁ מְחַלְּקִים דְּאִם הָיוּ כָּאן עֵדִים שֶׁאוֹמְרִים אֶחָד מֵהֶן הִזִּיק אֶלָּא שֶׁאֵינָם יוֹדְעִין אֵיזֶה הוּא, מְשַׁלֵּם כְּמוֹ שֶׁאָמַר מַזִּיק, וְלֹא מִקְרֵי כְּהַאי גַּוְנָא טְעָנוֹ חִטִּין וְהוֹדָה לוֹ בִּשְׂעוֹרִים (הַמַּגִּיד פ\"ט דב\"מ)\u0006. וְכִסְבָרָא הָרִאשׁוֹנָה שֶׁכָּתַב הַמְחַבֵּר שֶׁמִּקְּרֵי הוֹדָאָה וּכְמוֹ שֶׁנִּתְבָּאֵר. \u0010y7\u0011 \u0010c12\u0011 וְאִם תָּפַס \u0010y8\u0011 הַנִּזָּק, הֲרֵי זֶה מְשַׁלֵּם לַקָּטָן מֵהַגָּדוֹל וְלַגָּדוֹל מֵהַקָּטָן כְּמוֹ שֶׁהוֹדָה הַמַּזִּיק. וַאֲפִלּוּ תָּפַס בְּעֵדִים, נוֹטֵל כְּמוֹ שֶׁאָמַר הַמַּזִּיק \u0010c13\u0011 \u0010c14\u0011 \u0010c15\u0011 \u0010c16\u0011 \u0010c17\u0011 אֲבָל אֵינוֹ נוֹטֵל כְּפִי דְבָרָיו. וְדַוְקָא תָּפַס קֹדֶם שֶׁבָּא לְבֵית דִּין, אֲבָל לְאַחַר שֶׁבָּא לְבֵית דִּין לֹא מְהַנְּיָא לֵהּ תְּפִיסָה, אֲפִלּוּ לִטֹּל כְּדִבְרֵי הַמַּזִּיק:",["\u0003אלא בסלע לקה. \u0004 ואע\"פ שנלקה ע\"י רדיפת שורו אחריו לא הוי אלא גרמא בניזקין:","\u0003הואיל והוא קנס. \u0004 כבר נתבאר טעמו בס\"ס שצ\"ט ס\"ג:","\u0003והרי עדים שא' מהן הזיק. \u0004 רצה לומר ואינן יכולין לטעון שבסלע נלקה מ\"ה אם היו שניהן של אחד מהן חייב וכדמסיק ובאם היו של שנים פטורים שניהן אף שיש עדים שא' מהן ודאי נגחו וק\"ל:","\u0003מגוף הפחות שבשניהן. \u0004 אם אינו שוה כדי דמי ח\"נ מפסיד הניזק:","\u0003הבא ראי' שזה העומד כו' \u0004 נראה דאם זה העומד הוא תם והמועד מת או נאבד דגובה ח\"נ מזה התם העומד ממ\"נ דאם הוא נגחו הרי בדין גובה מגוף המזיק ח\"נ ואם זה שמת נגחו הרי הי' מועד וחייבים בעליו לשלם מנכסיו. וזה שור תם העומד בכלל נכסיו דבעל השור המועד שמת הוא אלא איירי המחבר שזה העומד הוא מועד א\"נ אינם ניכרים איזה מועד ואיזה תם וק\"ל:","\u0003המע\"ה. \u0004 הרמב\"ם סיים שם וכתב ז\"ל לא הי' שם ראי' ברור' שזה הזיק אלא עדים מעידים שא' משנים אלו היזק משלם המזיק כמו שאומר וכ\"כ הטור בשמו (וכן צריכים להגיה בדברי המחבר) וכתב הטור עליו וז\"ל ובודאי הוא כדבריו אם אין הניזק מברר דבריו לומר ודאי זה שהזיקני אבל אם טוען ברי לי שזה הזיקני אז הוא מודה שהאחר לא הזיקו לפיכך אם אין לו עדים אינו נוטל כלום דמזה שאומר שהזיקו אינו נוטל שהרי המזיק מכחישו גם מהשני נמי אינו נוטל שהרי הודה לו שאינו הזיקו ודומה לטועני חטין והודה לו בשעורים שפטור אף מדמי שעורים אבל יראה לי מדברי הרמב\"ם שס\"ל שנוטל כדברי המזיק אף שבירר הניזק דבריו וזהו תימה דה\"ל כטוענו חטים והודה לו בשעורים ואפילו תפס כתב א\"א הרא\"ש ז\"ל דל\"מ תפיסה עכ\"ל ובזה מבוארין דברי המחבר ודברי מור\"ם ז\"ל שהמחבר כ' כדעת הרמב\"ם ומור\"ם כ' לדברי הרא\"ש והטור לי\"א. ומ\"ש ודוקא טען הניזק ברי כו' הוא מ\"ש הטור ובודאי הוא כדבריו אם לא בירר הניזק דבריו כו' כנ\"ל. אלא שצ\"ע למה כתב מור\"ם די\"א דאין כאן שבוע' כלל כו' דהל\"ל דאין כאן תשלומין כלל כל' הטור הנ\"ל. גם קשה דלא הל\"ל דאין כאן שבוע' כלל דהא אפילו בטוענו בחטין והודה לו בשעורים נהי דאין עליו חיוב תשלומין ולא ש\"ד דמודה מקצת מ\"מ שבועת היסת צריך לישבע וכמ\"ש סי' פ\"ח ומטעם דהרי טענו חוטין והודה לו שעורים ה\"ל כאלו אמר איני חייב לך חיטים ובטענה וכפירה לא נפטר משבועת היסת כמ\"ש הרמב\"ם והמחב' עצמו כאן בסס\"ד וצ\"ל בכלל דכתב מור\"ם ר\"ל לא חיוב תשלומין ולא ש\"ד דמחייב הרמב\"ם להנתבע בתרווייהו ע\"ז כ' די\"א דאפי' ש\"ד אין עליו וכ\"ש תשלומין מה שהודה אלא פטור מתרווייהו כלל ומשבועת היסת לא איירי כאן ועפ\"ר שם כתבתי ל' המ\"מ שמיישב לדברי הרמב\"ם מהשגת הטור וכתב דס\"ל להרמב\"ם דלא הוה כטוענו חיטים והודה לו בשעורין כיון שיש עכ\"פ עדים שאחד משוריו נגחו ויש לניזק ממ\"נ ממון אצל בעל השורים המזיק משא\"כ בטוענו חטים כו' דמיירי דאין שם עדים כלל ומה\"נ כתב דנשבע שבועה דאורייתא על השאר דהא ה\"ל מודה מקצת על הממון שח\"ל ע\"פ העדים עכ\"פ (ואפשר דהרא\"ש והטור לא סבירא להו האי חילוק דעדים בענין זה כיון דהעדים אינן מבררים דבריהם איזה נגח לזה ואיזה לזה) ושם הוכיח המ\"מ חילוק זה דאיירי הרמב\"ם כאן דוקא ביש בה עדים שא' מהן הזיק דאל\"כ קשיין דברי הרמב\"ם אהדדי דכאן כתב דצריך לשלם מה שהוד' ובבבא שאחריו כתב שם הרמב\"ם בעצמו בדין ט' י' באם לא הי' שם ראיה דפטור לגמרי מטעם דה\"ל כטוענו חטים כו' וכמ\"ש המחבר אותן דברים עצמן אחר זה מיד בס\"ד אלא ודאי מ\"ש הרמב\"ם ברישא דמשלם מה שהודה מיירי ביש עדים ובסיפא מיירי דאין כאן עדים כלל ואף שכתב הרמב\"ם בסיפא ז\"ל ואם לא הביא ראיה ברורה כו' ומשמע דאיירי דליכא ראי' ברורה שהגדול הזיק אבל יש ראיה שא' מהן הזיק ואפ\"ה פטור הא כתב המ\"מ שם שצ\"ל שאין כוונת הרמב\"ם לזה במ\"ש ראיה ברורה דא\"כ יסתרו סוף דבריו לראשיתן וכמ\"ש ע\"ש. וכ' עוד שם המ\"מ דהא דמיירי הרמב\"ם בסיפא בלא עדים וברישא בעדים ה\"ט דבכל א' כ' רבותא דברישא קמ\"ל דאע\"ג דלא ניזק אלא שור א' וטענתו רק על שור אחד אפ\"ה חייב לשלם כשיש עדים ובסיפא קמ\"ל דאע\"פ שטענתו על שניהן ששניהן נגחו לשני שוורים אפ\"ה פטור כשאין עדים וכ\"ש ברישא שאין תביעה אלא על א' מהן עכ\"ל המ\"מ בשינוי ל' קצת לתוס' ביאור. וזהו כוונת המחבר שהעתיק רישא וסיפא דדברי הרמב\"ם כצורתן זא\"ז בס\"ג ובס\"ד ומהתימא על מור\"ם שכ' על מ\"ש המחבר בס\"ד ז\"ל זהו סברת י\"א כו' וז\"א דהא מ\"ש המחבר שם בס\"ד הן דברי הרמב\"ם עצמן בעל הסברא החולק עם הי\"א וכנ\"ל בס\"ג וצריכין לדחוק וליישב דהי' קשה למור\"ם על דברי המחבר שהעתיק דברי הרמב\"ם ג\"כ מ\"ש ואם לא הביא ראיה ברורה כו' דמשמע דמיירי דאף אם יש קצת ראי' והיינו דיש עדים שהזיק א' מהן אלא שאינן יודעין איזהו. ע\"ז מתמה וכ' הלא זו היא דעת י\"א הנ\"ל ולא ה\"ל להמחב' לסתום דבריו ומסיק אבל יש מחלקים ור\"ל דס\"ל לאותן י\"א דהו' המ\"מ הנ\"ל דאין שום דקדוק במ\"ש ראי' ברורה אלא מיירי באין עדים כלל דאם היו כאן עדים כו' ושכן הוא דעת המחב' מ\"ה העתיקו סתם ודוק:","\u0003ונשבע שבוע' התורה על השאר. \u0004 גם הטור כתב זה בשם הרמב\"ם אחר דבריו ודברי הרא\"ש הנ\"ל וכתב עליו בשם הראב\"ד דלא כ\"כ הרמב\"ם אלא כשאחד מהן תם ואחד מהן מועד דכיון דאחד מהן מועד תביעת הניזק הוא על נכסי המזיק נמצא דגם שור תם בכלל תביעת נכסיו הן מ\"ה מחשב כמודה מקצת אבל בא' גדול ואחד קטן ושניהן תמין שהחיוב היא על גוף השוורים כל אחד מחשב תביעה בפני עצמו ואין כאן מודה מקצת ולדעת א\"א הרא\"ש ז\"לאין כאן שבועה כלל (פי' אפי' כשאחד הוא תם ואחד מועד) דה\"ל כטוענו חטין כו' עכ\"ל הטור ע\"ש:","\u0003ואם תפס הניזק כו'. \u0004 דכיון דטען על שניהן ששניהן נגחוהו וגם המזיק מודה בזה אף שאין לו עדים בזה איזהו נגח לזה ואיזהו לזה מהני תפיסתו לכ\"ע וכן הוא בגמ' ועד\"ר:","\u0003הרי זה משלם לקטן מהגדול כו'. \u0004 והיינו דוקא כשתפס בעדים וכדמסיק דאין מיגו להניזק אבל אם תפס בלא עדים גובה להגדול מהגדול כמו שאומר הניזק וכמ\"ש מור\"ם בסי' שצ\"ט בס\"ג והוא כדעת הרא\"ש והטור שכ\"כ הטור שם בשמו וגם כאן כתבו ז\"ל אבל אינו נוטל כדי דבריו כיון שתפס בעדים עכ\"ל דמוכח מזה הא תפס בלא עדים נוטל כדבריו והכי הוא הצעת דברי הטור ודברי המחבר ואם תפס הניזק כו' מהני תפיסתו לשלם כו' ואין בו דין טענו בחיטין כו' ול\"ת דזהו דוקא בתפס בלא עדים אלא אף אם תפס בעדים הדין כן ואח\"כ מסיק וכתב מיהו בהא דתפס בעדים אינו נוטל כפי דבריו וק\"ל:"],["\u0003 אפי' ניזק טוען ברי ומזיק שמא \u0004 משמע מדברי הרמב\"ם והט\"ו דאפי' במועד דינ' הכי ומהרש\"ל פרק המניח סי' ל\"ג כתב דבמועד שרדף חייב כשניזק טוען ברי ומזיק שמא מאחר דרב הונא ורב יודא מחייבים בברי ושמא ואין דבריו נכונים אלא כיון דקי\"ל דלא כרב הונא ורב יודא אלא מוקמינן ממונא בחזקת מאריה א\"כ בכל ענין המע\"ה:","\u0003 ואם טען הניזק אתה יודע כו'. \u0004 אבל כשאינו טוען כן א\"צ לישבע היסת שהרי הניזק עצמו מודה שלא היה שם וא\"כ ודאי אין הניזק [המזיק] יודע ועיין מ\"ש לעיל סי' ע\"ב סי\"ב ס\"ק נ\"א יסי' צ\"ג סעיף י\"ג:","\u0003 נשבע היסת שאינו כו'. \u0004 כתב מהרש\"ל שם והא דאינו פטור מהיסת במגו דיכול לטעון להד\"ם דמאחר שטען זה ברי כנגדו הוי כמגו במקו' עדים דהא רב הונא ורב יהודא מחייבי' בברי ושמא כמו בעדים אף דלית הלכתא כותייהו מ\"מ לענין מגו הוי כעדים עכ\"ל ודבריו תמוהים ולחנם דחק דמאי מגו איכא הא אי טען להד\"מ נמי היה צריך לישבע היסת:","\u0003 ואם טען הניזק אתה יודע ודאי כו'. \u0004 ואע\"ג דבעלמא ס\"ל להרמב\"ם והמחבר דאע\"ג שאינו טוען אתה יודע הוי מחויב שבוע' וכמ\"ש לעיל סי' ע\"ב סעיף י\"ב ס\"ק נ\"א שאני התם דיכול להיות שיודע אבל הכא אם אינו טוען אתה יודע ודאי אינו יודע שהרי המזיק לא היה שם וכיון שהניזק בעצמו מודה שהמזיק לא היה שם לא שייך שבוע' כלל וכמ\"ש בסי' ע\"ב ס\"ק נ\"א שם ע\"ש ודו\"ק:","\u0003 משלם מהשהודה ונשבע שבועת התורה על השאר \u0004 כ\"כ הרמב\"ם וצ\"ע דהא טוענו מועד ונתחייב בתם ומין אחר הוא ובמ\"ש ה\"ה והטור דכשתובעו על המועד גם שור תם בכלל נכסיו עדיין לא נתקררה דעתי דאטו מי שיתבע את אחד שהלוה לו מנה ויודה לו בכלי שוה נ' או יתחייב לו כלי שוה נ' ע\"פ עדים יתחייב ש\"ד על השאר הא ודאי פטור כיון דמין אחר הוא וכן מוכח להדיא מדברי הנ\"י ס\"פ המניח והמחבר גופיה לעיל סי' פ\"ח סעיף י\"ג וא\"כ הוא הדין הכא וכן מוכח בש\"ס ס\"פ המניח מדפריך מיניה לרבה בר נתן אלמא דמין אחר הוא כמו חטים ושעורים ונראה דאין ה\"נ בתובעו ממון ק' ומודה לו בכלי שוה נ' דהוי מודה מקצת דומי' דתובעו דינר זהו' דשוה קאמר ובכל מה שיודה לו חשיב ממין הטענ' וכדלעיל סי' פ\"ח סעיף ט' והא דפריך בש\"ס לרבה בר נתן היינו כיון דלא הודה לו ממש מה שתבעו מצי למימר משטה ודחויי הוי קמדחינא לך תדע דהא בהיו הנזקין שנים והמזיקין שנים תמין דודאי חשיב הודאה ממין הטענ' דהא תובע שניהם ואפ\"ה פריך מיניה לרבה בר נתן אלא ודאי כמ\"ש. ולפי זה מה שכ' הנ\"י ס\"פ המניח והמחבר לעיל סי' פ\"ח סי\"ג מיירי כשטוען משטה הייתי דאלו עומד בהודאתו הוי מודה מקצת ממש וחייב שבועה דאורייתא. ומ\"מ מה דאיתא בש\"ס ופוסקים והט\"ו לעיל סי' פ\"ח סעיף ט' בתובעו בדינר זהו' בכל מה שיודה לו חשיב ממין הטענ' ומשמע דהוי הודא' גמור' ואינו יכול לחזור בו לא דמי לכאן דהתם כיון שזה שוה קאמר וזה כל מה שיודה לו בכלל הוא ובכל ענין חייב לשלם לו כל מה שיודה אפי' נאבד זה שמוד' א\"כ הוי ממש ממין הטענ' ולאו דחויי הוא ואינו יכול לחזור אבל כאן שמוד' לו בתם נהי דהתם הוא בכלל נכסיו מ\"מ כיון שמוד' לו דבר שאינו משתלם אלא מגופו ואילו נאבד אינו חייב לו ש\"מ דמשטה הוא בו ויכול לחזור בו והיינו הך שכתב הנ\"י והמחבר לעיל סי' פ\"ח סי\"ג דהיכא דהוד' לו כלי שאינו משתלם אלא מגופו פטור אלא דהיכא דהוא עומד בהודאתו או איכא עדים חייב ש\"ד וכדכתבו הרמב\"ם והראב\"ד וה\"ה והט\"ו כאן כן נ\"ל ודוק: שוב ראיתי בספר לחם משנה ספ\"ט מה' נזקי ממון כ' וז\"ל ואיכא לאתמוהי על הראב\"ד אם כן כיון דחשיב ממין הטענ' מה שמודה בתם א\"כ מה הקשו בסוף המניח תנן היה אחד תם ואחד מועד הניזק אומ' מועד הזיק את הגדול כו' הא לא מייתי ראיה שקיל כדקאמר מזיק הא חטים ושעורים נינהו והא לא דמי לחטים ושעורים דהודא' בתם הוי ממין הטענ' לדעת הראב\"ד ז\"ל ובשלמא לדברי רבינו ז\"ל איכא למימר דלא קאמר רבינו ז\"ל דהוי מחויב שבועת התורה אלא משום דאיכא עדים שנגח א' מהם ומתניתין איירי דליכא עדים ומשום הכי דמי לחטין ושעורים ואע\"ג דגם עליו קשה אמאי לא מוקי הש\"ס מתניתין בדאיכא עדים דומיא דרישא כדכתיבנא לעיל מ\"מ להראב\"ד ז\"ל קשה יותר שהוא מפרש דבמתני' אע\"ג דליכא עדים חשיב תם ממין הטענ' דמועד ואלו היה טוען מזיק ברי היה נשבע א\"כ לדידי' לא פריך הש\"ס כלל כדכתיבנא וצ\"ע עכ\"ל ואין דבריו נכונים בעיני דאם איתא דמוכח בש\"ס דתם לא חשיב ממין הטענה דמועד אם כן גם על הרמב\"ם תקשי אמאי חייב שבועת התורה אטו מי שיתבע את חברו במאה חביות חטין וחברו כופר ומביא התובע עדים שחייב לו נ' חביות שעורים היתחייב שבועת התורה על השאר הא פשיטא כיון דאין החיוב ממין הטענה מה לי שנתחייב במקצת על פי הודאתו או על פי עדים (וגם על דברי הרב המגיד הקשתי לקמן בזה ע\"ש) ועוד דאף אם תאמר דתם לא חשיב ממין הטענה דמועד מ\"מ תיקשי מאי פריך בתר הכי מהיו הניקין שנים והמזיקין ב' לרבה בר נתן דהא התם ודאי מין הטענה ממש הוא שהתובע רוצה כל השני תמים שהזיקו והנתבע מודה לו הקטן שהזיק ובמקצת גדול שהזיק אלא ודאי כמ\"ש דאף דהוי הודאה ממין הטענה פריך שפיר כיון דטעמא דרבה בר נתן הוא משום דכיון דלא הודה לו ממש כמו שתבעו יכול לטעון משטה הייתי בך א\"כ ה\"ה במתניתין כיון דלא הודה לו ממש אמאי שקיל כדקאמ' מזיק הא יכול לומר משטה הייתי בך ויש ראיה לזה ממ\"ש התוס' ס\"פ המניח ד\"ה לימא תיהוי תיובתא כו' והגהת מיי' פ\"ג מה' טוען דרבה בר נתן קאמ' מילתיה אפי' לרבן גמליאל דחייב שבועה בטענו חטים והודה לו בשעורים מ\"מ פטור לשלם השעורים ע\"ש. ודוק ותראה שכל זה ברור וע' מ\"ש לעיל סי' פ\"ח סי\"ב עוד מזה באריכות:","\u0003 ונשבע שבועת התורה כו' \u0004 כ' הטו' בשם הראב\"ד דלא כ' הרמב\"ם כן אלא כשא' מהן תם וא' מהן מועד דכיון דא' מהן מועד תביעת הניזק הוא על נכסי המזיק נמצא דגם שור תם בכלל נכסיו הן מ\"ה מחשב כמודה מקצת אבל בא' גדול וא' קטן ושניהן תמין שהחיוב הוא על גוף השוורים כל א' מחשב תביעה בפ\"ע ואין כאן מודה מקצת עכ\"ל סמ\"ע ס\"ק ז' ובאמת כן פי' הטור דברי הראב\"ד וכ\"כ ה\"ה בדעת הראב\"ד (וכ\"כ מהרש\"ל ס\"פ המניח בפי' דברי הראב\"ד דר\"ל דאי בשניהם תמים כיון דשני מינים הם ה\"ל כטענו חטים והודה לו בשעורים וא\"צ לישבע רק היסת וכ\"כ הב\"ח) אבל לפע\"ד דברי הטור והרב המגיד והנמשכים אחריהם תמוהים דנ\"ל שלא נתכוין הראב\"ד לזה אלא מ\"ש הראב\"ד אתם ומועד קאי ר\"ל דאי בשני תמין לא שייכא שבועה כלל משום מודה בקנס פטור ויותר תמיה לי על מה שמסיים הרב המגיד וז\"ל ויש לחלק שאפי' כששניהם תמים כיון שיש שם עדים חייב שבועת התורה וצ\"ע עכ\"ל ומביאו ב\"י דהאיך אפשר לחייב שום שבועה כלל דהא קנס הוא וכמ\"ש הרמב\"ם והט\"ו לעיל ר\"ס זה וליכא למימר דשאני הכא כיון דאיכא עדים דהא העדים אין מעידים רק על א' מהן והשאר אינם יודעים והכי מוכח נמי להדיא בתוס' ר\"פ שור שנגח הפרה דאפי' איכא עדים כיון שאין יודעים מהשאר ליכא שבועה כיון דאם היה מודה בקנס הי' פטור והוא פשוט וא\"כ דברי הרב המגיד וכן דברי הטור והנמשכים אחריו צ\"ע:","ועוד קשה לי על הרב המגיד כיון דבשני תמין לא חשיב ממין הטענה א\"כ מה בכך שיש עדים לענין שבועה דאוריית' וכי מי שתובע את חברו בק' חביות חטים וחבירו כופר והתובע מביא עדים שחייב לו נ' שעורים וכי יוכלו עדים לחייב ש\"ד בזה על השאר אלא ודאי מ\"ש הרמב\"ם עדים היינו משום דאל\"כ הי' יכול לחזור מהודאתו כמו בטענו חטים והודה לו בשעורים דפטור אף משעורים דהודאתו לאו הודאה היא וכמ\"ש לעיל ואפשר שלכך כתב הרב המגיד בסוף דבריו וצ\"ע כלומר דצ\"ע אם יש לחלק בין הודה לעדים בזה אבל לפע\"ד אין כאן צ\"ע והדבר ברור כמ\"ש ודוק:","\u0003 שבועת התורה על השאר. \u0004 ואע\"ג דהתם הוא בעין והעליתי לעיל סי' פ\"ז ס\"א וסי' פ\"ח סכ\"ד דדבר שהוא בעין ה\"ל הילך אפי' הוא בביתו של הנתבע היינו היכא שהוא של התובע מיד כגון בפקדון וכה\"ג דכל היכא דאיתא ברשותי' דמארי איתי' משא\"כ הכא כיון דצריך שומא לא ה\"ל הילך והכי מוכח בתוס' ונ\"י ר\"פ שור שנגח הפרה וכמ\"ש לעיל סימן שצ\"ט ס\"ג וע\"ש:","\u0003 וי\"א כו'. \u0004 ולעיל סי' פ\"ח סעיף י\"ב הוכחתי דלא כהי\"א בזה אלא דהיכא דאיכא עדים משלם הפחות שבשניהם וכן תפיסה מהני ליטול כדקאמר מזיק אפי' ליכא עדים וע\"ש:","\u0003 דאין כאן שבועה כלל כו'. \u0004 כלומר אין כאן תשלומין ושבועה כלל דהוה ליה כו' וכ' הסמ\"ע ס\"ק ז' דלדעת הרא\"ש אין כאן שבועה כלל אפי' כשא' הוא תם ואחד הוא מועד והב\"ח השיג עליו וכתב דדוקא בשני תמין ס\"ל להרא\"ש דאפי' היסת א\"צ אבל בתם ומועד מודה דנשבע ש\"ד עד כאן ולא דק דהא כיון דס\"ל להרא\"ש דאפי' יש לו עדים על הנגיחה פטור כיון דהוי כהודה והודאת בע\"ד כק' עדים א\"כ אפי' בתם ומועד פטור מש\"ד ומתשלומין וגם מה שכ' הב\"ח דלהרא\"ש אפי' היסת אין צריך הוא תמוה דלמה לא ישבע היסת לפטור עצמו מתביעת הניזק שאומר גדול הזיק לסברתם שלא הרגישו במודה בקנס פטור ודו\"ק:","\u0003 פטור המזיק שהרי כו' \u0004 ומשמע מדברי הרמב\"ם והמחבר דאפי' בבבא דמועד הזיק את הקטן אם אין עדים על הנגיח' פטור לגמרי (וכן משמע בטור) אבל הנ\"י ס\"פ המניח כ' וז\"ל ובבא דאמר מועד היזק את הקטן אפי' בדליכא סהדי משלם דמועד משלם נזק שלם מן העליה וממונא הוא הילכך משלם ע\"פ עצמו ואי תימא ואפי' כי מודה הודאה גמור' אמאי חייב והלא טענו חטים והוד' לו בשעורים היא שהניזק טוען נזקי גדול ומזיק מודה לו בנזקי קטן וי\"ל דליתא דכיון דניזק טוענו נזקי גדול מן העלי' ומזיק מודה לו בנזקי קטן מן העלי' ה\"ל כטוענו כסות (נ\"ל שצ\"ל דמי) דעבד גדול והלה מודה לו בכסות (בדמי) עבד קטן כדאיתא פרק השואל וכ\"כ הרמ\"ה עכ\"ל ובאמת משמע כן בש\"ס פ' השואל (דף ק' ע\"א) ועמ\"ש לעיל סימן ה' [צ\"ה] סעיף ג' ודוחק לומר דהתם מיירי כשאינו טוען משטה רק עומד בהודאתו דהא כי היכא דפריך הש\"ס בסוף פרק המניח ממתני' אמאי שקיל כדקאמר מזיק הא יכול לחזור בו ה\"ל לאקשויי התם אמאי חייב הא יכול לחזור בו ועוד דהא מוכח התם בפרק השואל דבכה\"ג הוי הודא' ממין הטענ' אבל נראה לי דגם הרמב\"ם והמחבר מודים בטוענו דמי עבד גדול ומודה לו בדמי עבד קטן דחייב ואינו יכול לטעון משטה אלא דס\"ל להרמב\"ם והמחבר דפריך דכיון דטעמא דרבה בר נתן משום דדחויי קמדחי ליה א\"כ הכא במועד נמי כיון דמסתמא לא הי' המזיק שם ואינו יודע מההיזק כלל והי' לו לטעון איני יודע כלל משום הזיק א\"כ נימא דמאי דקאמר מועד היזק את הקטן דחוי קמדחי לי' ויטעון משטה הייתי בך כי היכא דלרבה בר נתן כל מה דלא הי' מחויב לטעון כגון בשעורים שלא תבעו בשעורים כי מודי ליה בשעורים יכול לטעון משטה הייתי בך א\"כ הכא נמי נימא כיון שלא הי' מחויב להודות כלל שהזיק את הקטן ושפיר הי' יכול לו' איני יודע כלל משום היזק א\"כ נימא דדחוי קמדחי ליה ויוכל לטעון אח\"כ משטה הייתי בך והכי משמע פשטא דש\"ס דממועד הזיק את הקטן נמי פריך אלא ודאי כמ\"ש. כן נ\"ל):","\u0003 שהרי זה כטוענו לו חטים כו' \u0004 הוצרך לזה במועד אבל בתמין בלאו הכי פטור משום מודה בקנס וכ\"כ הרב המגיד שם:","\u0003 זו היא סברת יש אומרים כו' \u0004 באמת זה אינו אלא כל סעיף זה וכל סעיף ג' דלעיל הכל הוא לשון הרמב\"ם ומיירי כאן כשאין עדים כלל על הנגיחה וכן פי' ה' המגיד ומביאו ב\"י: וראיתי בספר גידולי תרומה שער ז' חלק ב' דף כ\"ו ע\"ד האריך להקשות דהאיך אפשר דהרמב\"ם מחייב בעדים דאם כן תיקשי קושיית הבעה\"ת שם והרא\"ש ס\"פ המניח הא מתני' בעדים מיירי דאל\"כ פטור משום מודה בקנס ועוד דהא מדברי הרמב\"ם פ\"ג מה' טוען משמע דס\"ל דטעמא דרבה בר נתן הוא משום דהוה כאלו הודה התובע שאין בידו שעורים וכיון דמדין הודא' אתינן עלה פשיטא דאפי' יביא מאה עדים לסתור הודאתו לא משגיחינן בהו אלא ודאי מ\"ש הרמב\"ם לעיל בס\"ג משלם המזיק כמו שאומר היינו כשהניזק טוען שמא דאם הניזק טוען ברי פטור לגמרי אפי' יש עדים דה\"ל כטוענו בחטים והודה לו בשעורים ע\"כ דבריו ואין דבריו נכונים כלל מכמה טעמים חדא דפשט דברי הרמב\"ם דלעיל משמע דהניזק טוען ברי ועוד דהא כ' שם מיד אח\"כ ואם טען הניזק אתה יודע שזה היזק בפניך הרי המזיק משלם מה שהוד' ונשבע שבועת התורה על השאר. והרי כשטען הניזק אתה יודע ודאי כו' אין לך ברי גדול מזה דהאיך יודע הניזק שהוא יודע ודאי שזה היזק בפניך אלא ודאי אומר אני ואתה היינו שם באותו מעמד ואני ואתה ראינו שזה היזק הרי שטוען ברי ואפ\"ה קאמר משלם מה שהודה ונשבע כו' ועוד דאי הוי טעין הניזק שמא לא הוה שייך לומר ונשבע שבועת התורה דהא אין נשבעין על טענת שמא אלא ודאי ברי קטעין שאומר ברי לי שאתה יודע שזה הזיק בפניך ואפ\"ה משלם מה שהודה ונשבע כו'. ול\"ד לחטים ושעורים כיון שיש כאן עדים וכמו שכתב הרב המגיד וכמו שהבין הטור בדעת הרמב\"ם וכ\"כ הסמ\"ע והב\"ח לדעת הרמב\"ם והוא ברור ודלא כבעל ספר גי' תרומה:","\u0003ולענין מה שהקשה הסי' גי' תרומה דתקש' קושיית הבעה\"ת והרא\"ש סוף פ' המניח כו'\u0004 נראה דאישתמיטתי' או לא עיין שפיר בהרב המ' שהרי הרב המ' כ' דמתני' מיירי בלא עדים וסוגין כמ\"ד פלגא נזקא ממונא כו' וכבר הארכתי לעיל סי' פ\"ח סעיף י\"ב הוכיח כן ע\"ש:","\u0003גם מה שהקשה דהא מדברי הרמב\"ם פ\"ג מהל' טוען משמע דמדין הודאה אתינן עלה כו'\u0004 לק\"מ דאפי' תימא דטעמא הוא משום הודא' מ\"מ כשיש לו עדים לא חשבינן ליה כאלו הודה די\"ל הא דלא תבעתי השעורים משום שיש לי עדים כי על מה שיש לי עדים ואינו יכול לכפור למה לי לתובעו רק רציתי לתובעו במה שאין לי עדים וכמ\"ש לעיל סי' פ\"ח סי\"ב ועוד די\"ל דטעמא דהרמב\"ם פ\"ג מה' טוען נמי דמשום דכיון שזה לא תבע ממנו מה שהודה הרי הודה שאינו תובע זה ויכול הנתבע לטעון משטה הייתי בך ואין הב\"ד מחייבין את הנתבע ליתן מפני הודאתו הראשונה וכמ\"ש לעיל סי' פ\"ח סי\"ב ועכ\"פ דעת הרמב\"ם ברור דהיכא דאיכא עדים חייב ול\"ד לטענו חטים והודה לו בשעורים דהתם מיירי בלא עדים וכן עיקר וכמו שהארכתי לעיל ספ\"ח סי\"ב והוכחתי כן בראיות מן הש\"ס והרבה פוסקים ע\"ש:","\u0003 ואם תפס הניזק ה\"ז משלם לקטן כו'. \u0004 ואע\"פ שהמוד' בקנס פטור כבר תירץ הר\"א ז\"ל בפירושיו דפלגא נזקא שאני משאר קנסות שאם תפס אין מוציאין מידו והוא דעת רבינו ז\"ל עכ\"ל הר' המ' ס\"פ ט' מהל' נזקי ממון אבל הנ\"י ס\"פ המניח כתב דלמ\"ד פלגא נזקא קנסא דקי\"ל כותי' לא מהני עד דאיכא סהדי אבל אי ליכא סהדי אפי' כדקאמר ניזק [מזיק] לא שקיל דלא מהניא תפיס' אלא בממונא דאי הוה מוד' ביה נתבע הוי מחוייב אבל בקנסא דרחמנא פטריה אפי' תפסי' בלא עדים ליכא מגו עכ\"ל (ומשמע שם שהן דברי הרמ\"ה ועמ\"ש לעיל סי' שצ\"ט ס\"ג דבתפס בלא עדים נ\"ל עיקר דמהני) ובאמת כיון דמוכח בש\"ס בכמה דוכתי וכן בפ' מרובה (ריש בבא קמא דף ע\"ה) גבי ר\"ג שסימא את עין טבי עבדו דתפיס' לא מהני במודה בקנס דאין לך תפיסה גדולה מעבד וכדאיתא בהראב\"ד עצמו ובהרא\"ש ספ\"ק דבב\"ק ובכסף משנה ס\"פ ה' מהל' עבדים ושאר פוסקים וכן מוכח מדברי הרב המגיד גופיה דתפיסה לא מהני במודה בקנס א\"כ מנלן לחלק בין פלגא נזקא לשאר קנסות וכ\"כ מהרש\"ל פ' המניח סי' ל\"ה דלא מסתבר לחלק בכך ע\"ש:","שוב ראיתי בתוס' י\"ט ס\"פ המניח שכ' על דברי הברטנורא דברי הר\"ב המגיד בשם הר\"מ דלעיל ועל הראשונים אני מצטער והוא בא להוסיף וכל המוסיף גורע ובחנם דחק די\"ל דהברטנורא מיירי כשיש עדים על הנגיחה וק\"ל:","\u0003 אבל אינו נוטל כפי דבריו. \u0004 כיון שתפס בעדים ואם תפס שלא בעדים נוטל כפי דבריו כ\"כ הטור ומשמע דהיינו משום דמהימן במגו אף בקנס וכן משמע בהרא\"ש ס\"פ המניח וכמ\"ש לעיל סי' שצ\"ט ס\"ג ועמ\"ש שם:"]],["שׁוֹר שֶׁנָּגַח וְחָזַר וְנָגַח שׁוֹר אַחֵר, \u0010c0\u0011 הֲרֵי הַנִּזָּק הָרִאשׁוֹן וְהַבְּעָלִים \u0010c1\u0011 כְּשֻׁתָּפִים בּוֹ. כֵּיצַד, שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח שׁוֹר שְׁוֵה מָאתַיִם, וְאֵין הַנְּבֵלָה יָפָה כְּלוּם, הַנִּזָּק נוֹטֵל ק' וּבַעַל הַשּׁוֹר ק'. חָזַר וְנָגַח שׁוֹר אַחֵר שְׁוֵה מָאתַיִם, וְאֵין הַנְּבֵלָה יָפֶה כְּלוּם, הָאַחֲרוֹן נוֹטֵל מֵאָה וְהַנִּזָּק שֶׁלְּפָנָיו עִם הַבְּעָלִים נוֹטְלִים חֲמִשִּׁים, חֲמִשִּׁים זוּז. חָזַר וְנָגַח שׁוֹר שְׁוֵה מָאתַיִם וְאֵין הַנְּבֵלָה יָפָה כְּלוּם, הָאַחֲרוֹן נוֹטֵל מֵאָה, וְהַנִּזָּק שֶׁלְּפָנָיו חֲמִשִּׁים, וְהַנִּזָּק הָרִאשׁוֹן עִם הַבְּעָלִים כ\"ה כ\"ה; \u0010y0\u0011 וְכֵן עַל דֶּרֶךְ זֶה חוֹלְקִים וְהוֹלְכִים.\nנִזָּק שֶׁתָּפַס בְּהֵמָה שֶׁהִזִּיקָה, לִגְבּוֹת חֲצִי נִזְקוֹ מִגּוּפָהּ, נַעֲשָׂה עָלֶיהָ שׁוֹמֵר שָׂכָר לִנְזָקִים, וְאִם יָצָאת וְהִזִּיקָה, \u0010c2\u0011 הַנִּזָּק הָרִאשׁוֹן חַיָּב בִּנְזָקֶיהָ וְהַבְּעָלִים פְּטוּרִים. כֵּיצַד, שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח וְהִפְסִיד מָאתַיִם, וּתְפָסוֹ הַנִּזָּק לִגְבּוֹת מִמֶּנּוּ ק', \u0010y1\u0011 וְחָזַר וְנָגַח וְהִפְסִיד ק\"מ, הֲרֵי הַנִּזָּק הָאַחֲרוֹן מִשְׁתַּלֵּם ע', וְהַנִּזָּק הָרִאשׁוֹן שֶׁתָּפְסוֹ מִשְׁתַּלֵּם מוֹתַר נִזְקוֹ וְהוּא ל', וְהַבְּעָלִים ק'; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: \u0010y2\u0011 \u0010c3\u0011 \u0010c4\u0011 \u0010c5\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין חִלּוּק בֵּין אִם תְּפָסוֹ אוֹ לֹא תְפָסוֹ, בְּכָל עִנְיָן הַנִּזָּק אֵינוֹ מַפְסִיד אֶלָּא חֲצִי וְהַבְּעָלִים חֲצִי (טוּר בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.",["\u0003וכן על דרך זה הולכים וחולקים. \u0004 לפי מה שהקדים המחבר וכתב כיצד כו' לפרש בו שחזר ונגח וחזר ונגח הרי מיירי שנגח ג' פעמים ובג\"פ נעשה שור המועד וגבהו הניזק האחרון כולו ולא הל\"ל שכן עד\"ז חולקים והולכים ואפשר של\"ד קאמר או מיירי כשלא התרה בו דלא נעשה מועד:","\u0003וחזר ונגח והפסיד ק\"מ כו'. \u0004 כן הוא גם כן לשון הרמב\"ם וק\"ק למה שינה בלשונו ונקט הפסיד ק\"מ ולא כתב כמו לעיל שהפסיד שור שוה ק\"ק שמפסיד התופס כל חלקו כי הניזק האחרון יטול משור המזיק ק' והבעלים ק' וכ\"כ הטור בקיצור ע\"ש:","\u0003וי\"א דאין חילוק בין אם תפסו כו'. \u0004 הטעם כיון דקי\"ל דניזק ובעלים נעשים שותפים בו ואם כיחש או נשבח הוא ברשות שניהן לא נעשה שומר אלא מחלקו דעל כל א' מוטל לשמור חלקו ועד\"ר וע\"ל סי' קע\"ו שכתב הטור בסי\"א ז\"ל השותפין שומרי שכר הן שאם נגנב או נאבד מהשותפין ברשות א' מהן חייב באחריות בד\"א בזמן שכל אחד ואחד מתעסק בהשותפות זמן ידוע ונגנב לו בזמן שמתעסק בו אבל כו' ויש לחלק ביניהן ולומר דלא נעשה שומר עליו אלא שלא יתאבד חלק הבעלים שהן שותפין ולא לענין שמיר' דניזקין דעלמא ועד\"ר:"],["\u0003 הרי הניזק הראשון. \u0004 כתבו התוס' ר\"פ שור שנגח ארבעה וחמשה דהיינו כשיש בידו להביא עדים לאלתר ולזכות בו אבל כשאין בידו להביא עדים לאלתר לא הוי שותף וראשון ראשון נשכר ע\"ש. ע' בתשו' הר\"ב סי' כ\"ז ומ\"ש לעיל ר\"ס ע\"ז:","\u0003 כשותפין כו'. \u0004 ולפ\"ז אם הקדישו ניזק עד שלא עמד בדין מוקדש הכי אמרי' בש\"ס פ' המניח (בבא קמא דף ל\"ג ע\"א) וכ\"כ הנ\"י ר\"פ שור שנגח ד' וה' בשם הרמ\"ה וכן אם מכרו הניזק וכדלקמן ריש סי' ת\"ז ועמ\"ש שם. וכן אין המזיק יכול לסלק את הניזק במעות אלא נוטל את השור עצמו כדאיתא בש\"ס שם בפ' המניח ובתוס' שם ד\"ה והקדישו ניזק כו' ע\"ש עוד בתוס' [דבור בפ\"ע] וכן על דרך זה הולכים וחולקים לפי מה שהקדים המחבר וכתב כיצד כו' לפרש בו שחזר ונגח וחזר ונגח הרי מיירי שנגח ג' פעמים ובג\"פ נעשה שור המועד וגבהו הניזק האחרון כו' ולא הל\"ל וכן עד\"ז חולקים והולכים ואפשר של\"ד קאמר או מיירי כשלא התרה בו דלא נעשה מועד עכ\"ל סמ\"ע ס\"ק א' ומה שכ' ולא הל\"ל וכן עד\"ז חולקין כו' לא קשה מידי דהרמב\"ם והמחבר כתבו כל' המשנה שור שנגח ארבע וחמשה ומ\"ש או מיירי כשלא התר' בו דלא נעשה מועד כ\"כ ג\"כ ר' ירוחם נ\"א ח\"ג. ועי\"ל כמו שפירש\"י ר\"פ שור שנגח ד' וה' ז\"ל ובכלן הי' תם דמשתלם מגופו והיכי דמי כגון ראה שור ונגח שור ולא נגח וראה שור ונגח ואחר נגיחה הב' ראה ב' פעמים ולא נגח דאפילו מועד לסירוגין ליכא דשור אינו נעשה מועד אלא א\"כ נגח השלשה נגיחות בשלשה שראה כסדרן או שלא כסדרן ונעשה מועד לסירוגין עכ\"ל וכ\"כ הנימוקי יוסף שם:","\u0003 הניזק הראשון חייב כו'. \u0004 וכן אם תפסו ניזק שני נעשה ש\"ש לראשון ולבעלים וכן ג' וד' כדמוכח בש\"ס וכתבו התוס' דפעמים שהרביעי אין לו כלום ושלישי יש לו כגון שנזקי ד' וה' שוים ונזקי ג' יתרים ואפי' חמישי נמי פעמים שאין לו כל נזקו אם נזקיו יתרים על של ד' שאינו נוטל אלא חלקו של ד'. ומהר\"ש אידלש תמה על דבריהם דלמה לא יטול החמישי מגוף המזיק מהבעלים ומהג' ומהב' וכדפריך לקמן ולימא ליה אי תם הוה משתלם מגופו משום דא\"ל ס\"ס תורי בעי שלומי וגם בשלטי גבורים הניח דבריהם בצ\"ע עכ\"ד מהרש\"א ול\"ק מידי דהתם נתנו לשומר משא\"כ הכא שתפסו בע\"כ יכול המזיק לומר אנוס הייתי ולא הייתי יכול לשומרו וה\"ל כהוציאו' לסטים דהבעלים פטורים וגם מה שהקש' הש\"ג דלמה לא ישלם הב' והג' מה שהזיק יותר מחלקו פשיטא נמי דל\"ק מידי דכיון דתם אינו משלם רק מגופו היאך יעלה על הדעת שישלם יותר ממה שיש לו בו ואפילו הי' החלק שיש לו בו שלו לגמרי לא הי' משלם יותר. ונראה דאף למ\"ש לקמן דהעיקר כהי\"א דאף בתופסו לא הוי רק ש\"ש על חלקו מ\"מ נ\"מ לענין מועד שהזיק דבכה\"ג לכ\"ע נעשה שומר שכר לנזקיו כשתפסו וכמ\"ש לקמן וא\"כ לפי מה שכתבתי אינו נוטל יותר ממה שמגיע למי שלפניו ודוק:","\u0003 וי\"א כו' \u0004 טור בשם ר\"י והרא\"ש. וכן דעת ה\"ר אפרים תלמיד הרי\"ף ובעל המאור והרמ\"ה והתוס' ר\"פ ד' וה' וכן נראה דעת הברטנורא שם וכ\"כ האגוד' בשם ר\"י וכן נראה עיקר בש\"ס שם וכ\"פ מהרש\"ל שם ודלא כעיר שושן שהשמיט דעת הי\"א ועשה מן הטפל עיקר (גם תמיהא לי על ר' ירוחם שכתב בנל\"א ח\"א בסתם כדברי הרמב\"ם ולא הזכיר דעת הרא\"ש רבו וכל הני רבוותא כלל) מיהו במועד לכ\"ע נעשה שומר דהא מוכח בש\"ס דע\"כ לא פליג ר\"ע עליה דר' ישמעאל אלא משום דס\"ל כיון דמשתלם מגופו שותפי נינהו וכן כתב הבעל המאור והנ\"י ומהרש\"ל שם וגדולה מזו נ\"ל דבמועד שתפסו חייב אפי' באונסין וכמ\"ש לעיל סי' ע\"ב ס\"ב ס\"ק ט' ואע\"ג דבש\"ס אמרי' נעשה כש\"ש לנזקיו היינו בתם דמשתלם מגופו ואע\"ג דלר' ישמעאל אין לו בו חלק מבורר מ\"מ דכיון דמשתלם מגופו לא הוי רק ש\"ש אבל במועד שמשלם מן העלי' א\"כ ה\"ל התפיס' ממש כתופס משכון שלא ברשות ב\"ד דכתבתי לעיל סי' ע\"ב ס\"ב ס\"ק ט' דחייב לכ\"ע אף באונסים וע\"כ קשה לי על בעל המאור והנמ\"י שכתבו דבמועד נעשה שומר שכר ומהא שמעינן דמאן דתפיס מחבריה מידי למגבי מיני' חובו נעשה עליו שומר שכר כו' דעדיפא מיניה ה\"ל לאשמועינן דחייב עלי' באונסים ומכ\"ש לפי מש\"ל סי' ע\"ב ס\"ב ס\"ק ט' דדעת בעל המאור דר' יצחק דאמר ב\"ח קונה משכון במשכנו שלא בשעת הלואתו היינו אפי' לאונסים וגם קשה דמאי אצטריך בעל המאור לאתויי ראי' מהכא הא היינו מימרא דרבי יצחק ודוחק לומר דס\"ל לבעל המאור דמשכנו שלא ברשות ב\"ד עדיף טפי דאדרבא איפכא מסתברא וכמש\"ל סי' ע\"ב ס\"ק ט' וגם בש\"ס ורמב\"ם והרב המגיד מוכח דברשות בית דין עדיף טפי כמ\"ש שם וצ\"ע:","שוב נרא' דלפי מה שהעליתי לעיל סי' ע\"ב ס\"ב ס\"ק ט' באריכות דטעמא דשלא בשעת הלואתו קני ליה אף לאונסים דכיון דאין לו לשלם אם כן שעבודי' רמיא עליה דההוא משכון ונקנ' לו גוף המשכון א\"כ לא קשה מידי דשאני הכא דמיירי דיש לו לשלם ממקום אחר א\"כ שעבודי' לא רמי' על שור זה ולא דמי לדר' יצחק ומשום תופס שלא ברשות נמי ליכא דכיון דשור זה הזיקו יש לו רשות לתפסו דמי שתופס דבר המזיק לא חשיב גזלן בהכי (ועיין בספרי תקפו בהן סי' ק\"ח וק\"י) ובעל המאור ונ\"י שלמדו מכאן דמאן דתפיס מחברי' מידי למגבי מיני' חובו נעשה עליו ש\"ש כו' כוונתם אפילו תפס ברשות דומיא דשור המועד כגון שנתן לו חבירו רשות שאם לא ישלם לו לזמן פלוני יהא לו רשות לתפוס ממנו מטלטלים בעצמו שלא ע\"פ ב\"ד וכה\"ג הוי ש\"ש ומיהו לאונסים לא קני כיון יש לו לשלם ממקום אחר ועוד נ\"ל די\"ל דאה\"נ דס\"ל לבעל המאור ונ\"י דחייב באונסים מטעם דר' יצחק אלא מדר' יצחק לא נשמע אלא בב\"ח קונ' משכון כלומר מה שכנגד הלואתו הוי כאלו מכור לו אבל לא שמעינן מיני' דהוי עליה ש\"ש כלל להמותר שעל חובו והלכך למדו מהך דשור דאפילו ש\"ש הוי להמותר בההיא הנאה דתפיס ליה אחובי' מיהו לענין דינא האמת דלא קנה לאונסים אלא כשאין לו לשלם ממקום אחר וכמו שהארכתי בזה לעיל סי' ע\"ב ס\"ב ס\"ק ט' ע\"ש:","\u0003 דאין חילוק כו' \u0004 וע\"ל סי' קע\"ו שכתב הטור בסי\"א ז\"ל השותפין שומרי שכר הן שאם נגנב או נאבד מהשותפין ברשות א' מהן חייב באחריות בד\"א בזמן שכל א' וא' מתעסק בשותפות בזמן ידוע ונגנב לו בזמן שמתעסק בו אבל כו' ויש לחלק ביניהן ולומר דלא נעש' שומר עליו אלא שלא יתאבד חלק הבעלים שהן שותפין ולא לענין שמיר' דניזקין דעלמא עכ\"ל סמ\"ע ס\"ק ג' ודבריו אינם נכונים ונ\"מ טובי לדינא דלדבריו כי היכי בשור של שותפים שהי' ברשות א' מהן והזיק אין השותף חייב על חלק חבירו וגם בזה שתפסו אם נאבד אצלו חייב לשלם חלק הבעלים לפי סברתו דמחלק בין ניזקין לאביד' ואין טעם כלל לחלק בכך וגם בש\"ס ופוסקים לא משמע כן גם מל' הרא\"ש שכתב דהוי כמו חפץ ששו' ר' שלפעמים זה שומרו ולפעמים זה שומרו ולעולם הוי אחריותו על שניהם עכ\"ל לא משמע כן אבל האמת יורה דרכו דשאני הכא כיון שאינו מחויב לשמור א\"כ אינו נעש' שומר רק על חלקו אבל על חלק חבירו אפי' ש\"ח לא הוי וכ\"כ בעל המאור ר\"פ שור שנגח ד' וה' להדיא לחלק בכך וכ\"כ המרדכי פ' ח\"ה ובלי ספק דאשתמיטתי' להסמ\"ע דברי בעל המאור והמרדכי. ולפ\"ז ה\"ה אם נאבד אצלו פטור על חלק חבירו אבל בשור של ב' שותפין שחל א' מחויב לשמור אפי' הזיק חייב גם על חלק חבירו. ועיין מ\"ש לעיל סי' קע\"ז ס\"ח:"]],["שְׁנֵי שְׁוָרִים תַּמִּים שֶׁחָבְלוּ זֶה בָזֶה, מְשַׁלְּמִים בַּמּוֹתָר חֲצִי נֶזֶק. כְּגוֹן אִם אֶחָד הִזִּיק בַּחֲבֵרוֹ שָׁוֶה ק', וְהַשֵּׁנִי הִזִּיק שָׁוֶה נ', \u0010y0\u0011 יָצְאוּ חֲמִשִּׁים בַּחֲמִשִּׁים, וְהַנ' הַנּוֹתָרִים יְשַׁלֵּם לוֹ חֶצְיָם. \u0005וַאֲפִלּוּ נֶאֱבַד הָאֶחָד. \u0010y1\u0011 וְדַוְקָא שֶׁשָּׁוֶה כָּל אֶחָד דְּמֵי נִזְקוֹ; אֲבָל אִם אֵינוֹ שָׁוֶה כָּל כָּךְ, אֵינוֹ מְנַכֶּה לוֹ רַק מַה שֶּׁיּוּכַל לִגְבּוֹת מִגּוּפוֹ (נִמּוּקֵי יוֹסֵף שם)\u0006. וְאִם שְׁנֵיהֶם מוּעָדִים, מְשַׁלְּמִים בַּמּוֹתָר נֶזֶק שָׁלֵם. וְאִם הָיָה אֶחָד תָּם וְאֶחָד מוּעָד, מוּעָד בְּתָם, שֶׁהִזִּיק הַמּוּעָד לַתָּם יוֹתֵר מִמַּה שֶׁהִזִּיקוֹ, יְשַׁלֵּם בַּמּוֹתָר נֶזֶק שָׁלֵם. \u0010y2\u0011 כְּגוֹן אִם הִזִּיק מוּעָד בְּתָם מֵאָה, וְהַתָּם לֹא הִזִּיקוֹ אֶלָּא נ', מְשַׁלֵּם לוֹ ע\"ה. תָּם בְּמוּעָד יְשַׁלֵּם לוֹ חֲצִי נֶזֶק, כְּגוֹן שֶׁהִזִּיק תָּם בְּמוּעָד ק', וְהַמּוּעָד לֹא הִזִּיקוּ אֶלָּא כ\"ה, מְשַׁלֵּם לוֹ כ\"ה. \u0005הַגָּה: \u0010y3\u0011 יֵשׁ אוֹמְרִים דְּכָל זֶה מַיְרֵי דַּוְקָא שֶׁהִתְחִילוּ בְּבַת אַחַת, \u0010y4\u0011 אוֹ לְאַחַר שֶׁנִּפְרְדוּ זֶה מִזֶּה חָזַר הַשֵּׁנִי וְחָבַל בָּרִאשׁוֹן; אֲבָל אִם אֶחָד הִתְחִיל, הַמַּתְחִיל מְשַׁלֵּם וְהַשֵּׁנִי פָּטוּר, דְּכָל הַמְשַׁנֶּה וּבָא אַחֵר וְשִׁנָּה (בּוֹ)\u0006 פָּטוּר \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְכֵן הוּא לְקַמָּן סִימָן תכ\"א סָעִיף י\"ג לְעִנְיַן שְׁנֵי אֲנָשִׁים שֶׁחָבְלוּ זֶה בָזֶה. \u0010c0\u0011 וְהַמְחַבֵּר שֶׁפָּסַק כָּאן כְּמִי שֶׁחוֹלֵק, וּסְבִירָא לֵהּ שֶׁאֵין לְחַלֵּק, וּלְקַמָּן פָּסַק כְּמוֹ שֶׁכָּתַבְתִּי, לֹא כִּוֵּן יָפֶה:",["\u0003יצאו חמשים בחמשים כו'. \u0004 ונ\"מ אם נאבד האח' וכמ\"ש מור\"ם על זה דה\"א כיון דהשור תם אינו משלם אלא מגופו נמצא שור של ראובן שנגח שור של שמעון והפסידו מנה ואח\"כ חזר שור של שמעון ונגח לשור של ראובן שוה מנה והפסידו חמשים ונאבד שור של שמעון אח\"כ ה\"א דראובן יפסיד הזיקו שאין לו מקום לגבות ושמעון יגבה חמשים זוז משורו של ראובן קמ\"ל דלא אלא מיד שהזיקו זא\"ז מנכין זא\"ז בכדי שווים דמי ההזיק והמותר משלם ח\"נ א\"נ קמ\"ל אע\"ג דשור אח' יפה למכור מהשני וה\"א כיון דקי\"ל דגובין וחוזרין וגובין לשני בעלי חובות שחייבין זה לזה היכא שיש להן נ\"מ כגון שיש לאח' עידית ובינונית ולהשני זיבורית וכמ\"ש הטור והמחבר לעיל סימן פ\"ה ס\"ג ה\"נ יגבה כ\"א דמי נזקו מהמזיק קמ\"ל כיון דהניזק משלם ממיטב זהו מיטב שלו שיעמוד כל אחד בשלו כ\"כ הנ\"י ועפ\"ר והאי טעמא בתרא שייך בשני מועדים דהן גובין מעידית שיש למזיק ולא בתמין וטעם הראשון שייך דוקא בשני תמין דהן משלמין דוקא מגופן וכן בשני' שחבלו זה בזה דנשנה שם במשנ' עמהן דמשלמין במותר נ\"ש וכתבו הטור והמחבר לקמן בסי' תכ\"א ס\"ג שייך בו ג\"כ טעם בתרא וק\"ל ולא כע\"ש שכ' דה\"ט דמנכין זה כנגד זה משום דאפוכי מטרת' ל\"ל דז\"א אלא אף אם יש בו נ\"מ לא' בגביות כל אחד מחבירו לא שמעינן ליה ומטעם שכתבתי:","\u0003ודוקא ששוה כל א' כו'. \u0004 כ\"כ הנ\"י פ' המניח (בדפוס גדול דף י\"ז ע\"א) ז\"ל וראוי שתדע דכי אמרינן דמשלמין במותר ח\"נ דוקא במאי דיכלו לאשתלומי מיניה אהדדי אבל שור שוה ר' שנגח לשור שוה מנה והכחישו פ' זוז וחזר האחרון ונגח להראשון והכחישו מנה אם נאמר נוציא מ' שהוא ח\"נ שחייב הראשון כנגד מ' מחמשים שחייב האחרון וגובה הראשון מהאחרון י' דינרים במותר ח\"נ לקתה מדין שהרי האחרון שהכחיש להראשון מנה אינו שוה אלא ך' ואין להראשון להשתלם אלא מגופו והראשון שחייב להאחרון נ' זוז עדיין שוה מנה ויכול להשתלם ממנו לפיכך דין הוא בזה שנוציא ך' כנגד ך' שהוא שיעור מה דאית להו לאשתלומי מהדדי ויגבה האחרון מהראשון ך' זוז שהוא מותר מ' מחצי נזק שלו ונמצא דפעמים הניזק מועד גובה יותר מחביריו שנזקו מרוב' עכ\"ל:","\u0003כגון אם הזיק מועד בתם ק' כו' \u0004 כ\"כ ג\"כ בטור ושם בפריש' כתבתי דהי' יכול לומר כגון דגם המועד לא הזיקו אלא נ' אפ\"ה משלם המועד במותר כ\"ה אח' שניכה כ\"ה דח\"נ דתם נגד כ\"ה מנ' דמועד ולא נקט שהזיק ק' אלא אגב שהוצרך לכתוב כן לשטת פירש\"י דכתב הרא\"ש והטור משמו דהיכי דהתחילו התם והמועד יחד דגם התם משלם נ\"ש ע\"ש ועפ\"ר:","\u0003י\"א דכל זה כו' עד והמחבר שפסק כאן כמי שחולק כו' \u0004 עד\"ר שם כתבתי דלעד\"נ דלית פלוגתא בזה דכ\"ע ס\"ל דאם לא התחילו יחד אלא שחזר ונגח קודם שנח רוגזו דהשני פטור וכמ\"ש הטור בשם הרא\"ש כן בלי חולק עליו בב' מקומות בשור ובאדם ול\"פ ר\"י אפירש\"י אלא במ\"ש רש\"י דאם התחילו כא' והי' א' תם וא' מועד דמשלם תם כמועד נ\"ש דבזה ס\"ל לר\"י דאפילו התחילו יחד אינו משלם התם אלא ח\"נ והמחבר לא הזכיר דעת רש\"י כלל לא כאן בשוורים ולא בסימן תכ\"א באדם אלא ס\"ל פשוט כר\"י והחילוק שכתב הרא\"ש בין החחילו יחד או לא כתבו המחבר בסימן תכ\"א וה\"ה כאן בשוורים דמ\"ש זה או זה ומ\"ש מור\"ם כאן החילוק דבין התחילו יחד בשם י\"א לא דק גם בזה כי אין פלוגתא בזה וכמ\"ש וחדא באידך תליא דמשום דעלה בדעת מור\"ם דפליגי וכתבו בשם י\"א הוא הגורם לכתוב אהמחבר דלא כוון יפה ודו\"ק:","\u0003או לאחר שנפרדו כו'. \u0004 יחזר השני וחבל כו' דאז הוי השני ג\"כ כהתחל' חדשה משא\"כ אם חבל השני בראשון קודם שנפרדו וז\"ש מור\"ם אבל אם א' התחיל כו':"],["\u0003 והמחבר שפסק כאן כמי שחולק כו'. \u0004 ונוסחת הטור שלפנינו גרם למור\"ם לכתוב כן והנוסחא הנכונה עיין ביש\"ש פ\"ג סי' כ\"ו והב\"ח לא הרגיש בזה ולכן הגיה נוסחא המוטעת וגם הסמ\"ע לא הזכירה ומ\"מ כוון כהלכה בדעת הרא\"ש וכן הוא ברמזים והוא ע\"פ נוסחת מהרש\"ל וק\"ל:"]],["שָׁמִין הַשְּׁבָרִים בִּנְזִיקִים. אִם שָׁבַר כְּלִי הוּא אוֹ בְּהֶמְתּוֹ אֵין אוֹמְרִים: יִתֵּן לוֹ כְּלִי שָׁלֵם וְיִקַּח הַשְּׁבָרִים, \u0010y0\u0011 אֶלָּא שָׁמִין כַּמָּה נִפְחֲתוּ דָּמָיו בִּשְׁבִיל הַשְּׁבִירָה, וְיִקַּח הַנִּזָּק הַשְּׁבָרִים, וְהַמַּזִּיק יַשְׁלִים עֲלֵיהֶם.\nפְּחַת הַנְּבֵלָה לַנִּזָּק, וּשְׁבַח הַנְּבֵלָה חוֹלְקִים אוֹתוֹ הַמַּזִּיק וְהַנִּזָּק. כֵּיצַד, שׁוֹר שָׁוֶה מָאתַיִם שֶׁנְּגָחוּהוּ וּמֵת, וַהֲרֵי הַנְּבֵלָה שָׁוָה בִּשְׁעַת מִיתָה מֵאָה, וּבִשְׁעַת הַעֲמָדָה בַּדִּין פָּחֲתָה וַהֲרֵי שָׁוָה פ', אֵין הַמַּזִּיק מְשַׁלֵּם אֶלָּא ק'. וְאִם הָיָה תָּם, מְשַׁלֵּם לוֹ נ' מִגּוּפוֹ. \u0010y1\u0011 \u0005(נ\"י)\u0006 \u0005וְדַוְקָא שֶׁנּוֹדַע לַנִּזָּק בִּשְׁעַת מִיתָה, אֲבָל אִם לֹא נוֹדַע לוֹ, הַפְּחָת עַל הַמַּזִּיק עַד \u0010y2\u0011 שֶׁיִּוָּדַע לַנִּזָּק. וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין אִם הוּזְלָה\u0006 \u0005(טוּר ס\"ח)\u0006. \u0005וְיֵשׁ חוֹלְקִין דִּבְזוֹלָא \u0010y3\u0011 אַף עַל גַּב דְּלָא נוֹדַע לֵהּ הָוֵי שֶׁל נִזָּק\u0006 \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הנ\"ל)\u0006. הִשְׁבִּיחָה הַנְּבֵלָה וַהֲרֵי הִיא שָׁוָה בִּשְׁעַת הַעֲמָדָה בַדִּין ק\"כ, הֲרֵי הַמַּזִּיק מְשַׁלֵּם תִּשְׁעִים. \u0010y4\u0011 וְאִם הָיָה תָּם, מְשַׁלֵּם מ\"ה מִגּוּפוֹ, \u0010y5\u0011 וְזֶהוּ וְגַם אֶת הַמֵּת יֶחֱצוּן. \u0005הַגָּה: מִיהוּ, אִם הִשְׁבִּיחָה כָּל כָּךְ עַד שֶׁחֲצִי שֶׁבַח הוּא יוֹתֵר מִדְּמֵי \u0010y6\u0011 הַהֶזֵּק, לָא אָמְרִינָן דְּהַמַּזִּיק יִטּוֹל חֲצִי הַשֶּׁבַח וְיַרְוִיחַ (טוּר)\u0006. \u0010y7\u0011\nעַל הַמַּזִּיק לִטְרֹחַ בַּנְּבֵלָה עַד שֶׁמַּמְצִיא אוֹתוֹ לַנִּזָּק. כֵּיצַד, כְּגוֹן שֶׁנָּפַל הַשּׁוֹר לְבוֹר וָמֵת, מַעֲלֶה הַנְּבֵלָה מֵהַבּוֹר וְנוֹתְנָהּ לַנִּזָּק, וְאַחַר כָּךְ שָׁמִין לוֹ פְּחַת נְבֵלָה. שֶׁנֶּאֱמַר: כֶּסֶף יָשִׁיב לִבְעָלָיו וְהַמֵּת יִהְיֶה לוֹ, מְלַמֵּד, שֶׁהוּא חַיָּב לְהָשִׁיב אֶת הַנְּבֵלָה וְאֶת הַפְּחָת שֶׁפָּחֲתָה מִן הַחַי לַנִּזָּק; וְאִם הָיָה תָם, חֲצִי הַפְּחָת:",["\u0003אלא שמין כמה נפחתו כו'. \u0004 וכ\"כ הטור והמחבר הדין בשואל בסי' שמ\"ד וסי' שפ\"ז כתבו הטור בדין ניזק משא\"כ בגנב וגזלן וכמ\"ש בטור והמחבר בסי' שנ\"ד ושס\"ב והטעה כתבתי שה דכתיב והשיב את הגזלה אשר גזל ודרשינן כאשר גזל וגם בגניבה דרשינן אחיי' לגניבתו אבל בניזק כתבה התורה ישיב ודרשינן מיניה דכשבא לשלם במטלטלין דיכול לשלם בכל מה דיכול להשיב אפילו סובין וכמ\"ש בסי' תי\"ט ע\"ש:","\u0003ודוקא שנודע לניזק כו'. \u0004 פי' דאז ה\"ל לניזק לטפל במכירת הנבילה קודם שנסרח' ונפחתה מדמי' ואפילו נפלה לבור דעל המזיק מוטל להעלותה ולמסרה להניזק בדמי שווי' וכמ\"ש הטור והמחבר בסמוך בס\"ג היינו שהמזיק מחויב ליתן הוצאת שצריכין ליתן להמעלין מהבור אבל הטפול להשתדל להעלותה מוטל על הניזק וחוזר ולוקח ההוצאה מהמזיק וכ\"כ בטור ובב\"י שהוא הסכמת הפוסקים:","\u0003אם הוזלה \u0004 פי' שלא נפחתה הנבילה מצד עצמה ממה שהיתה בשעת מיתה אלא שהוזל הבשר:","\u0003אע\"ג דלא נודע לו. \u0004 דבזול אין נ\"מ בידיעתו דדוקא בנפחתה מחמת סרחון דרגיל להיות מחמת שהיי' אמרינן אלו ידע ודאי היה מטפל בה למכרה משא\"כ בזולא דלא עלתה על דעתו שיזול:","\u0003ואם הי' תם משלם מ\"ה. \u0004 דלעולם שמין הריוח לפי השומא שהיה שוה מתחלה ומתחלה היה שוה ר' ובאותן ר' משותף המזיק בשור הניזק ברביעית דהיינו נ' כיון שהוא תם לכך אינו נוטל אלא הרביעית בהריוח:","\u0003וזהו וגם את המת יחצון. \u0004 ר\"ל שבח המת יחצון (וכ\"ה בהדיא שם ברמב\"ם) וילפינן מיתורא דוגם דהמ\"ל ואת המת יחצון ואף על גב דאין להמזיק אלא בפחת כנ\"ל יש לו חלק בהריוח דהתורה חס על המזיק כיון שהוא עצמו לא הזיק אלא שורו:","\u0003לא אמרינן דהמזיק יטול חצי השבח וירויח. \u0004 עפ\"ר ודרישה שם כתבתי והוכחתי דאף דאז אין נוטל חלק בהשבח מ\"מ פטור הוא ג\"כ מלשלם להניזק מה שהזיק שורו דהיינו שור ששוה ה' סלעים שנגח לשור ששוה חמשה סלעים ובשעה שנודע לו לא היתה שוה אלא ג' סלעים ואח\"כ השביחה עד ששוה ל' זוז דהיינו ו' סלעים כיון דהשתא אחר שהשביח אין לו הפסד ול\"ד למ\"ש הטור והמחבר בר\"ס שאחר זה דאם נגח השור והפחיתו ועדיין הוא חי והשביח עד ששוה כפל ממה שהי' מתחל' דאפ\"ה משלם לו היזק כמו שהי' בשעת הנגיחה דשאני התם דמצי הניזק למימר לולי שנגחוהו שורך היה ריוח זה דנעשית שומן גדולה כפל ממה שהוא עתה שכן דרך הטבע שבהמה חיה נשבחת בשומן וגידול וכשהיא אינה נגוח' נשבחת יותר מנגוח' וחולה משא\"כ כאן בנבילה דאף דנתיקר הבשר הוא דבר שאינו מצוי ותלוי במזל ואין לו' אלו לא המיתו היה נתיקר בכפלים דיכול להיות דבמזלו נתיקר:","\u0003על המזיק לטרוח כו'. \u0004 כבר כתבתי דעל הניזק להעלותו מהבור עד שנודע לו שנפלה שם ונוטל דמי הוצאותיו של העלי' מהמזיק ואם לא עשה כן ונפסד השור בהבור דהוא פסידא דהניזק. וכ\"כ הטור בהדיא וכתב הב\"י שהוא הסכמת הפוסקי' וכאן למדונו דאם לא ירצה המזיק להעלותו ולא ליתן לו הוצאה להעלותו דצריך ליתן דמים שכל חציו דהפחת אם הוא תם ואם הוא מועד צריך לשלם דמי כל הפחת מאשר היה שוה כשהי' חי וכן משמעות הקרא כסף ישיב לבעליו והמת שגם המת ישיב המזיק ויתנהו לידו דניזק ואז יהי' לו המת בתשלומי דמי נזקו והמותר עד כדי נזקו ישלם לו בכסף אם נפל לבורו דפסוק זה בנפל לבורו כתיב וה\"ה לשור מועד שנגח וק\"ל:"],[]],["שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח שׁוֹר שְׁוֵה מָאתַיִם \u0010y0\u0011 וְהִפְחִיתוֹ חֲמִשִּׁים, וּבִשְׁעַת הַעֲמָדָה בַדִּין הִשְׁבִּיחַ הַנִּזָּק וַהֲרֵי הוּא שָׁוֶה ת', \u0010y1\u0011 וְאִלְמָלֵא הַנְּגִיחָה שֶׁהִפְחִיתוֹ הָיָה שָׁוֶה ת\"ת, בֵּין שֶׁפִּטְּמוֹ בֵּין שֶׁשָּׁבַח מֵאֵלָיו, אֵינוֹ נוֹתֵן אֶלָּא כִּשְׁעַת הַנֶּזֶק.\nכָּחַשׁ מֵחֲמַת הַמַּכָּה בִּשְׁעַת הַעֲמָדָה בַּדִּין, וַהֲרֵי הַפְּחָת שָׁוֶה מֵאָה, \u0010y2\u0011 נוֹתֵן לוֹ כִּשְׁעַת הַעֲמָדָה בַּדִּין. \u0010y3\u0011 הִשְׁבִּיחַ הַמַּזִּיק בִּשְׁעַת הַעֲמָדָה בַּדִּין, אִם מֵחֲמַת שֶׁפִּטְּמוֹ שָׁבַח, אֵינוֹ מִשְׁתַּלֵּם מִמֶּנּוּ אֶלָּא מַה שֶּׁהָיָה שָׁוֶה בְּשָׁעָה שֶׁהִזִּיק. \u0010y4\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם הַשֶּׁבַח יֶתֶר עַל הַהוֹצָאָה נוֹטֵל הַמַּזִּיק דְּמֵי הַהוֹצָאָה וּשְׂכַר טָרְחוֹ וַעֲמָלוֹ, וּבִשְׁאָר הַשֶּׁבַח נוֹטֵל הַנִּזָּק חֶלְקוֹ (טוּר ס\"ג)\u0006. \u0010y5\u0011 וְאִם מֵחֲמַת עַצְמוֹ הִשְׁבִּיחַ, מִשְׁתַּלֵּם מִמֶּנּוּ כִּשְׁעַת הַעֲמָדָה בַדִּין:",["\u0003והפחיתו חמשים כו' \u0004 פי' ועדיין הוא חי והשביח בין הנגיח' להעמדה בדין במה שנתגדל' או השמינ':","\u0003ואלמלא הנגיחה שהפחית' כו'. \u0004 פי' ולא יכול הניזק לתובעו בעד אותו נזק כיון שאינו אלא גרמא ולא פסידא בידים מיהו צריך לשלם כשעת הנזק אע\"ג דנשבח הרבה יותר ממה שהיה שוה בשעת הנגיח' משא\"כ במת מחמת הנגיחה ונתייקר הבשר וכמ\"ש בסי' שלפני זה מילתא בטעמא ע\"ש:","\u0003נותן לו כשעת העמדה בדין. \u0004 לשון הגמ' דאמר לי' מקרנ' דתורך דקבירא בשורי המנוגח כיחש כ\"כ פי' כיון שהוא עדיין חי כאב הנגיחה הוא בו עדיין ומכח זה מכחיש ואזיל משא\"כ בסי' שלפני זה דשם מיירי דמת מיד מהנגיחה והפסידה דאח\"כ אינו מחמת כאב הנגיח':","\u0003השביח המזיק. \u0004 פי' שור המזיק:","\u0003וי\"א דאם השבח יתר על ההוצאה כו'. \u0004 בטור כתב עוד ז\"ל דאם ההוצא' יתירה על השבח אין לו לניזק בשבח כלום אלא נוטל כפי מה שמגיעו בשעת הנזק ע\"כ וכתבתי בפריש' דדוקא קאמר דאין לו בשבח כלום אבל ג\"כ א\"צ ליתן הוצאה כלום ומפסיד המזיק מה שהיתה ההוצא' יתירה על השבח וה\"ט דאף דהם שותפין בשור המזיק והשותף היורד ברשות צריך לשלם לו חצי ההוצא' מכיסו היתירה על השבח וכמ\"ש בסי' שע\"ה היינו דוקא בשותף היורד ברשות אבל זה אף דהוא כשותף מ\"מ ה\"ל כשותף היורד שלא ברשות וכמ\"ש בסי' קע\"ה ושע\"ה ע\"ש ודו\"ק:","\u0003ואם מחמת עצמו כו'. \u0004 הטעם דמיד בשעת נגיחה נעשו המזיק והניזק שותפין בהשור והוא ברשות שניהן לענין אם נפחת או נשבח ממילא משעת הנגיחה והלאה וכ\"כ בטור:"],[]],["שׁוֹר שֶׁחָבַל בָּאָדָם, \u0010y0\u0011 אֲפִלּוּ נִתְכַּוֵּן לַבְּהֵמָה וְחָבַל בָּאָדָם, דִּינוֹ כְּדִין שׁוֹר שֶׁהִזִּיק לְשׁוֹר; תָּם מְשַׁלֵּם חֲצִי נֵזֶק, וּמוּעָד נֶזֶק שָׁלֵם, \u0010y1\u0011 וּפָטוּר מִצַּעַר וְרִפּוּי וְשֶׁבֶת וּבֹשֶׁת, שֶׁלֹּא חִיְּבָה תּוֹרָה בְּאַרְבָּעָה דְּבָרִים אֵלּוּ, אֶלָּא בְּאָדָם. \u0010y2\u0011\nשׁוֹרוֹ שֶׁחָבַל בְּאָבִיו וְאִמּוֹ, אוֹ שֶׁהִדְלִיק גָּדִישׁ בְּשַׁבָּת, חַיָּב בִּנְזָקָיו; אַף עַל פִּי שֶׁאִם עָשָׂה הוּא כֵּן \u0010y3\u0011 הָיָה פָטוּר:\nנָגַח אִשָּׁה וְיָצְאוּ יְלָדֶיהָ, \u0010y4\u0011 פָּטוּר מִדְּמֵי וְלָדוֹת, אַף עַל פִּי שֶׁהוּא מוּעָד לִנְגֹחַ. אֲבָל אִם נָגַח שִׁפְחָה מְעֻבֶּרֶת וְיָצְאוּ יְלָדֶיהָ, חַיָּב כְּאִילוּ נָגַח בְּהֵמָה מְעֻבֶּרֶת, וְשָׁמִין אוֹתָהּ כַּמָּה הָיְתָה שָׁוָה תְּחִלָּה, וְכַמָּה נִפְחֲתוּ דָּמֶיהָ, וּמְשַׁלֵּם תָּם חֲצִי נֶזֶק, וּמוּעָד נֶזֶק שָׁלֵם:",["\u0003אפילו נתכוון לבהמה וחבל באדם \u0004 עפ\"ר דכתבתי דיש צד רבותא בזה יותר משור שכוון לנגח בהמה זו ונגח בהמ' אחרת דהתם מין בהמה אחת היא משא\"כ אדם שיש לו מזל (וכמ\"ש בסי' א') ואין דרכו של שור לכוין אליו לנגחו וה\"א דמחשב אונס טפי:","\u0003ופטור מצער כו'. \u0004 דכי יתן איש בעמיתו כתיב ולא שור בעמיתו:","\u0003שור שחבל באביו כו'. \u0004 פי' שור שחבל באביו ואמו של בעל השור חייב בעל השור בנזקי אביו:","\u0003היה פטור. \u0004 וה\"ט דמה שהוא הי' פטור היינו משום דקים לי' בדרבא מיני' דהי' חייב מית' משא\"כ בשורו שחבלו שבעליו אינו חייב מיתה אזה:","\u0003פטור מדמי ולדות דכתיב כי ינצו אנשים ולא שורים:\u0004"],[]],["שׁוֹר שֶׁל יִשְׂרָאֵל \u0010y0\u0011 שֶׁנָּגַח שׁוֹר שֶׁל גּוֹי, פָּטוּר. וְשֶׁל גּוֹי שֶׁנָּגַח לְשֶׁל יִשְׂרָאֵל, בֵּין תָּם בֵּין מוּעָד, מְשַׁלֵּם נֶזֶק שָׁלֵם.\nשׁוֹר שֶׁל הֶפְקֵר שֶׁנָּגַח, וְקֹדֶם שֶׁיִּתְפֹּס אוֹתוֹ הַנִּזָּק קָדַם אַחֵר \u0010y1\u0011 וְזָכָה בּוֹ, פָּטוּר.\nנָגַח שׁוֹרוֹ וְהִפְקִירוֹ קֹדֶם שֶׁעָמַד בַּדִּין, וְזָכָה בּוֹ אַחֵר, פָּטוּר. אֲבָל אִם זָכָה בּוֹ הוּא עַצְמוֹ, חַיָּב.\nנָגַח \u0010y2\u0011 וְאַחַר כָּךְ מָכַר אוֹ הוֹרִישׁ, חַיָּב.\nשׁוֹר שֶׁל פִּקֵּחַ שֶׁנָּגַח לְשׁוֹר חֵרֵשׁ שׁוֹטֶה וְקָטָן, חַיָּב. וְשֶׁל חֵרֵשׁ שׁוֹטֶה וְקָטָן שֶׁנָּגַח לְשֶׁל פִּקֵּחַ, וְכֵן שׁוֹר שֶׁהָלְכוּ בְּעָלָיו לִמְדִינַת הַיָּם \u0010y3\u0011 וְנָגַח, פְּטוּרִים:",["\u0003שנגח שור של עכו\"ם פטור. \u0004 דשור רעהו כתיב ולא שור של עכו\"ם ומה\"ט היה מן הראוי לפטור ג\"כ איפכא בשל עכו\"ם שנגח לשל ישראל אלא דלמדו מקר' לחייב מדכתי' (בחבקוק) אלוה מתימן יבא וקדוש מהר פארן כו' עד עמד וימודד ארץ ראה ויתר גוים ודרשו רז\"ל בפרק שור שנגח ד' וה' (ריש בבא קמא דף ל\"ח) ראה ז' מצות בני נח שקבלו עליהן ולא קיימו עמד והתיר וכו' ור' יוחנן דרשו מדכתיב בפ' וזאת הברכה הופיע מהר פארן. מפארן שרצה ליתן להן התורה ולא רצו לקבל' הופיע וכו' כן הוא בגמ' שם ומהתימ' על המחבר \"עיר שושן שערבב וכתב ראה והופיע יחד וגם כתב אחריו ז\"ל כיון שראה שלא קיימו אפילו ז' מצות בני נח הופיע וכו' ומשמע מל' שם דס\"ל דחד לימוד ומקרא א' הוא וז\"א:","\u0003וזכה בו פטור. \u0004 פי' זה הזוכה פטור מהניזק ובגמ' ילפינן מקראי דבעינן שיהא לו בעלים בשעת נגיחה ובשעת גמר דין ועפ\"ר:","\u0003ואח\"כ מכר כו'. \u0004 קמשמע לן כיון דיש לו בעלים גם בשעת גמר דין אף ע\"ג דאינן בעלים הראשונים חייב.","\u0003ונגח פטורים. \u0004 עד\"ר שכתבתי לשון התוס' שדרז\"ל שלא לחייב באלו דכאלו אין להם בעלים דמי וגם לא תקנו להעמיד אפוטרופוס על השמירה ולגבות מהן לאחר שיגחו אם לא שכבר נגחו ג\"פ אז תקנו חכמי משנ' שיעמדו להן אפטרופוס ואח\"כ כשיחזרו ויגחו ג\"פ לפני אפוטרופוס לאחר התראה מגבינן נזקיהו מעליית היתומים וכתבו הטור ע\"ש והמחבר השמיטו ולא כתבו ג\"כ מור\"ם ז\"ל נראה דהיינו טעמא משום דאינו נוהג בזמן הזה דהא אין מועד בבבל (כמ\"ש בסי\"א) והטור לא כתבו אלא ללמדינו פי' הגמ' וגם משום דאם הועד בא\"י בכה\"ג ובא לח\"ל והזיק וקדם ותפסו הניזק שאין מוציאין מידו והוא דבר שאינו שכיח לכך לא כתבוהו ולא הזכיר אפטרופוס כלל ובעיר שושן נתן מכשול לפני המעייני' בספרו במ\"ש בזה ז\"ל חשו לממונא שלא לכלייא קרנא אמרו שלא להעמיד להן אפטרופוס לחובתן לשלם לניזק כו' וז\"א דהא אחר שנגחו ג\"פ מעמידין אפטרופוס וכנ\"ל ואי משום דכ' לכליא קרנא דהיינו כ\"ז שהן תמים שאז גובה מגופו ושייך כילוי קרן משא\"כ כשהועד הא זה הטעם דחו התו' ועד\"ר:"],[]],["שׁוֹר תָּם שֶׁהִזִּיק, אִם מְכָרוֹ הַמַּזִּיק עַד שֶׁלֹּא עָמַד בַּדִּין, \u0010y0\u0011 \u0010c0\u0011 אַף עַל פִּי שֶׁהוּא מָכוּר, הֲרֵי הַנִּזָּק גּוֹבֶה הֵימֶנּוּ, וְחוֹזֵר הַלּוֹקֵחַ וְגוֹבֶה מֵהַמַּזִּיק שֶׁמָּכַר לוֹ; שֶׁכֵּיוָן שֶׁנָּגַח, קוֹל יֵשׁ לוֹ וְלֹא הָיָה לוֹ לַלּוֹקֵחַ לִקַּח אוֹתוֹ עַד שֶׁיִּגְבֶּה הַנִּזָּק. \u0005הַגָּה: מְכָרוֹ נִזָּק, מָכוּר; \u0010y1\u0011 וּכְשֶׁיִּתְפְּסֶנּוּ, יִקָּחֶנּוּ הַלּוֹקֵחַ (טוּר ס\"א)\u0006.\nשְׁחָטוֹ מַזִּיק, גּוֹבֶה מִבְּשָׂרוֹ. \u0010c1\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּצָרִיךְ לְשַׁלֵּם פְּחַת הַשְּׁחִיטָה (טוּר שָׁם מהג\"מ פֶּרֶק הַמֵּנִיחַ)\u0006. \u0010c2\u0011 וְכֵן אִם \u0010c3\u0011 נִשְׁתַּמֵּשׁ בּוֹ חַיָּב לִתֵּן לַנִּזָּק שְׂכִירוּת. \u0005(טוּר וּבֵית יוֹסֵף בְּשֵׁם רַשִׁ\"י וְהָרַאֲבַ\"ד)\u0006. נְתָנָהּ בְּמַתָּנָה, מַה שֶּׁעָשָׂה עָשׂוּי, וְיִגְבֶּה הַנִּזָּק מִמֶּנּוּ:\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁמָּכַר אוֹ נָתַן קֹדֶם שֶׁעָמַד בַּדִּין. אֲבָל אִם עָמַד בַּדִּין וְאַחַר כָּךְ מְכָרוֹ אוֹ נְתָנוֹ בְמַתָּנָה, לֹא עָשָׂה כְּלוּם.\nקָדְמוּ בַּעַל חוֹב שֶׁל מַזִּיק וּתְפָסוּהוּ, בֵּין שֶׁחָב עַד שֶׁלֹּא הִזִּיק, בֵּין הִזִּיק עַד שֶׁלֹּא חָב, לָא זָכָה, אֶלָּא הַנִּזָּק גּוֹבֶה מִמֶּנּוּ, \u0010y2\u0011 שֶׁאֲפִלּוּ הָיָה אֵצֶל בַּעַל חוֹב מִתְּחִלָּה וְהִזִּיק, הָיָה גוֹבֶה מִגּוּפוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דַּוְקָא דְּיוּכַל הַבַּעַל חוֹב לִגְבּוֹת חוֹבוֹ מִמָּקוֹם אַחֵר, אֲבָל אִם הָיָה הַשּׁוֹר \u0010y3\u0011 אִפּוֹתִיקִי מְפֹרָשׁ לְבַעַל חוֹב, וְקָדַם בַּעַל חוֹב לַנְּזִיקִין, \u0010y4\u0011 בַּעַל חוֹב קוֹדֵם (טוּר ל' הָרַמְבַּ\"ם שָׁם וְהָרֹא\"שׁ)\u0006.",["\u0003אע\"פ שהוא מכור. \u0004 פי' לענין זה דיכול הלוקח לחרוש ולעבוד בו וגם אין שום א' מהן יכול לחזור בו כ\"ז שלא גבה ממנו הניזק וכן לענין זה קאמר בסמוך בס\"ב דמתנתו מתנה:","\u0003וכשיתפסנו יקחנו כו'. \u0004 כ' שיתפסנו משום זמן הזה דאין מגבין דיני קנסות בב\"ד ולרבותא כ\"כ דאע\"ג דאין לו בו דבר עד שיתפסנו אפ\"ה מכירתו מכיר' ועפ\"ר:","\u0003שאפי' היה אצל ב\"ח כו'. \u0004 היה גובה מגופו ר\"ל כיון שאפי' היה של עצמו גובה מידו אם הזיק כ\"ש זה שאין עליו אלא שיעבוד ועד\"ר שם כתבתי דכן הוא בגמר' ושהתו' כתבו ע\"ז דאין זה כ\"ש דבשלמא אם היה שלו מעולם או שכבר גבהו בחובו ויצא והזיק מ\"ה חייב דהוא פשע בשמירתו משא\"כ זה שנגח בעוד שלא היה ברשותו ולא בא הגמרא אלא לומר קצת טעם דמ\"ה גובה מיד ב\"ח כיון דאין גוף השור משועבד לב\"ח כמו שהוא משועבד לניזק:","\u0003אפותיקי מפורש לב\"ח. \u0004 פי' שכתב לו לא יהא לך פרעון אלא מזה דאז אינו גובה ממקום אחר אף אם נגנב או נשתדף זה האפותיקי א\"ל ברצון שניהן או שמשלם לו במזומנים וכמ\"ש הטור והמחבר בסי' קי\"ז ע\"ש:","\u0003ב\"ח קודם. \u0004 פי' כשתפסו עפ\"ר ודריש' שם כתבתי דנרא' דאפ\"ה אם קדם הניזק ותפס השור דאין מוציאין מידו דלא עדיף לגבי ב\"ח משאר מטלטלים שעשאו אפותיקי מפורש דאם קדם ומכרו או שקידם ב\"ח מאוחר וגבהו גבייתו גביי' ומכירתו מכיר' וכמ\"ש הטור בסי' קי\"ז ס\"ד ואפי' אם לא קדם הניזק ותפס ובאו הניזק וב\"ח יחד לגבות משור זה שעשאו אפותיקי לב\"ח הב\"ד מגבין אותו לשניהן בשוה כמ\"ש הטור והמחבר בסימן ק\"ד דאין קדימ' למטלטלין מיהו אם הוא איפכא דניזק קודם שלוה מזה הב\"ח אפי' קדם הב\"ח ותפס זה השור הניזק שעשאו אפותיקי מפורש ל\"מ תפיסתו דשור זה שנגח שם תורא דנגחנא לפלוני יש עליו ויש לו קול ודינו כקרקע לענין הניזק ובקרקע קיימא לן דבעל חוב מאוחר שקדם וגבה גבייתו לאו גביי' הוא וכמ\"ש בסי' ק\"ד ועפ\"ר מ\"ש עוד מזה:"],["\u0003 אע\"פ שהוא מכור לרדיא \u0004 ומהרש\"ל פ\"ג דב\"ק סימן כ\"ח תמה ע\"ז וכתב דלרבי עקיבא אפילו לרדיא אינו מכור וע\"ש וכן דעת הטור וכ\"כ התוספות דף ל\"ג ע\"א ד\"ה והקדישו וכן נרא' עיקר בש\"ס למאי דקי\"ל כר' עקיבא דשותפין נינהו ודו\"ק היינו שכתב הרב שס\"ב וכן אם נשתמש בו חייב ליתן לו שכירות ועיין מ\"ש שם:","\u0003 וי\"א כו' \u0004 וכן עיקר לפי מאי דקי\"ל כרשב\"ג דמזיק שעבודו של חבירו חייב וכמו שכ' הרמב\"ם פ\"ז מה' חובל ופ\"ח מה' מלוה וכ\"כ המחבר לעיל סימן קי\"ז (סעיף ו') וכ\"פ בהגהות אשרי פ' המניח וכ\"פ מהרש\"ל שם סי' כ\"ח ומ\"ש הרמב\"ם והמחבר אח\"כ נתנו במתנה מה שעש' עשוי אין לדקדק מזה דפטור מפח' שחיט' וכדדייקינן בש\"ס מהאי לישנא דבש\"ס מדייק שפיר דקתני שחטו ונותנו במתנה מה שעש' עשוי אבל הרמב\"ם והמחבר שכתבו מתחלה שחטו גובה מבשרו אם כן מה שכתב אחר כך נתנו במתנ' מה שעשה עשוי ומתנתו מתנה לרדיא ודו\"ק וכ\"כ בע\"ש נתנו במתנה מה שעש' עשוי לענין לחרוש בו ועיין מ\"ש לעיל סי' שפ\"ו:","\u0003 וכן אם כו' \u0004 סדר הר\"ב אינו נכון בעיני דהא זה חולק אדברי הרמב\"ם והמחבר לעיל סעיף א' שכתבו אע\"פ שמכר והל\"ל זה בלשון י\"א בסעיף א' ודו\"ק:","\u0003 נשתמש בו כו'. \u0004 כתב ב\"י שהרשב\"א חולק על זה ומפרש לרדיא היינו לענין לחרוש בו לכתחל' אבל אם כבר נשתמש בו פטור ליתן שכירות דהא כשמכרו גזלן הוא וגזלן אינו מעלה שכר לבעלים ע\"כ ויש לו ראיה מש\"ס פרק הגוזל קמא גבי תוקף עבדו וספינתו של חברו ועש' בהם מלאכה ונתבאר לעיל סי' שי\"ג [שס\"ג] ס\"ד וה' ועמ\"ש שם ס\"ד:"]],["אֵין הַנְּזִיקִים מִשְׁתַּלְּמִים \u0010y0\u0011 אֶלָּא בִּרְאָיָה בְּרוּרָה וּבְעֵדִים כְּשֵׁרִים. \u0005וְאֵין מְקַבְּלִין הָעֵדוּת אֶלָּא בִּפְנֵי בַּעַל דִּין, אֲפִלּוּ הָיָה הוּא וְעֵדָיו חוֹלִים (נִמּוּקֵי יוֹסֵף פֶּרֶק כֵּיצַד)\u0006.\nשׁוֹר שֶׁהָיָה רוֹעֶה, וְנִמְצָא שׁוֹר הָרוּג בְּצִדּוֹ, אַף עַל פִּי שֶׁזֶּה מְנֻגָּח וְזֶה מוּעָד לִגַּח, זֶה מְנֻשָּׁךְ וְזֶה מוּעָד לִנְשֹׁךְ, אֵין אוֹמְרִים בְּיָדוּעַ שֶׁזֶּה נְגָחוֹ אוֹ נְשָׁכוֹ. וַאֲפִלּוּ גָמָל הָאוֹחֵר בֵּין הַגְּמַלִּים וְנִמְצָא הָרוּג בְּצִדּוֹ, אֵין אוֹמְרִים בְּיָדוּעַ שֶׁזֶּה הֲרָגוֹ, עַד שֶׁיִּרְאוּהוּ עֵדִים כְּשֵׁרִים:",["\u0003אלא בראי' ברורה. \u0004 כן הוא במשנ' והרמב\"ם בפ\"ח מהל' נ\"מ מסיק וכתב בזה והביאו הטור כאן ז\"ל של\"ת הואיל ואין מצוי בארוות הסוסים ובגדרות הצאן אלא הרועים והעבדים וכיוצא בהם אם העידו ששור זה נגח או היזק לאדם שומעין להן קמ\"ל דאין הדבר כן אלא לעולם אין מחייבין ממון אלא ע\"פ עדים כשרים ויעידו בב\"ד ויחייבו ב\"ד המזיק לשלם ועד\"ר מ\"ש בשם ת\"ה ע\"ז וכתבו מור\"ם ז\"ל לעיל בהג\"ה ש\"ע בס\"ס ל\"ה דמכח תקנה יכולין להעיד ועוד כתב הטור כאן בשם ר\"י דקמ\"ל המשנ' הנ\"ל בזה דאפי' שור עכו\"ם שנגח לשור של ישראל אין דנין אותו אלא בעדים כשרים עכ\"ל:"],[]],["\u0010y0\u0011 אֵין מְגַדְּלִים בְּהֵמָה דַקָּה \u0010y1\u0011 בְּאֶרֶץ יִשְׂרָאֵל, מִפְּנֵי שֶׁדַּרְכָּם לִרְעוֹת בְּשָׂדוֹת שֶׁל אֲחֵרִים וְהֶזֵּקָם מָצוּי; אֲבָל מְגַדְּלִים בְּסוּרְיָא וּבַמִּדְבָּרוֹת שֶׁבְּאֶרֶץ יִשְׂרָאֵל. וְהָאִדָּנָא, שֶׁאֵין מָצוּי שֶׁיִּהְיוּ לְיִשְׂרָאֵל בְּאֶרֶץ יִשְׂרָאֵל שָׂדוֹת, נִרְאֶה דְּשָׁרִי. \u0010y2\u0011\nלֹא יְגַדֵּל יִשְׂרָאֵל חֲזִירִים בְּכָל מָקוֹם, אֲפִלּוּ לִמְשֹׁחַ בָּהֶם עוֹרוֹת; \u0010y3\u0011 וְאֵין צָרִיךְ לוֹמַר לִסְחוֹרָה.\nאָסוּר לְגַדֵּל כֶּלֶב רָע, \u0010y4\u0011 אֶלָּא אִם כֵּן הוּא אָסוּר בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל וְקָשׁוּר בָּהֶם. וּבְעִיר הַסְמוּכָה לַסְפָר, מֻתָּר לְגַדְּלוֹ; וְקוֹשְׁרוֹ בַּיּוֹם וּמַתִּירוֹ בַּלַּיְלָה. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהַשְׁתָּא שֶׁאָנוּ שְׁרוּיִן בֵּין הַגּוֹיִים וְאוּמוֹת בְּכָל עִנְיָן שָׁרִי, וּפוּק חַזֵּי מַאי עַמָּא דָּבַר (הַגָּהַת אַלְפָסִי הַחֲדָשִׁים)\u0006. מִיהוּ, נִרְאֶה, אִם הוּא כֶּלֶב רָע, שֶׁיֵּשׁ לָחוּשׁ שֶׁיַּזִּיק בְּנֵי אָדָם, דְּאָסוּר לְגַדְּלוֹ אֶלָּא אִם כֵּן קָשׁוּר בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל:\nמִי שֶׁנָּפְלוּ לוֹ כְּלָבִים וַחֲזִירִים בִּירֻשָּׁה, אֵין מְחַיְּבִים אוֹתוֹ לְמָכְרָם בְּיַחַד, אֶלָּא מוֹכֵר מְעַט מְעַט:",["\u0003אין מגדלין בהמה דקה כו' \u0004 בטור כתב דאפי' בבית אסור ואפי' אין הבהמה שלו דאין אדם חוטא ולא לו מ\"מ כיון שדרך בהמה דקה לצאת ולהזיק גזרו מחששא שתצא בלי ידיעת הרוע' ותזיק:","\u0003בא\"י \u0004 בגמ' והטור כ' דגם בבבל היו אוסרין כשהיו שכיחין רוב ישראל והי' להן שדות וכרמים וה\"ה לשאר ארצות אם היו בהן כן אלא שאין זה בזמנינו עיין בטור שכת' כן:","\u0003לא יגדל ישראל חזירים כו'. \u0004 משום מעשה שהי' בימי הורקנוס ואריסתובלוס גזרו כן וכתבתיהו בפריש' ע\"ש:","\u0003ואצ\"ל לסחור'. \u0004 דלסחור' אסר מדאורייתא כמ\"ש בי\"ד סי' קי\"ג דאסור לסחור בכל הדברים האסורים מן התור' לאכול אע\"פ שמותרין בהנא':","\u0003אא\"כ קשור בשלשלאות של ברזל. \u0004 דאז טעם שישוך וגם טעם שמנבח ומפילות הנשים מיראתו אין כאן כיון דיודעין שהוא קשור לא מתיראין ממנו ואינן מפילות:"],[]],["בּוֹר הוּא מֵאֲבוֹת נְזִיקִין, דִּכְתִיב: כִּי יִכְרֶה אִישׁ בֹּר; שֶׁמֵּאַחַר שֶׁחָפְרוּ נִתְחַיֵּב בִּנְזָקָיו, כֵּיוָן שֶׁעָשָׂה דָּבָר הַמַּזִּיק. וְזֶהוּ מָמוֹנוֹ שֶׁמַּזִּיק בְּמָקוֹם שֶׁעֲשָׂאוֹ, שֶׁאֵינוֹ זָז מִמְּקוֹמוֹ אֶלָּא עוֹמֵד בִּמְקוֹמוֹ וְהָעוֹבֵר עָלָיו נִזָּק. לְפִיכָךְ, כָּל הַדּוֹמֶה לוֹ, שֶׁהוּא מָמוֹנוֹ \u0010y0\u0011 וּמֻנָּח בִּמְקוֹמוֹ וּמַזִּיק, אֲפִלּוּ שָׁפַךְ מַיִם בִּרְשׁוּת הָרַבִּים וְהֻחְלַק בָּהֶם אַחֵר, חַיָּב:\nאֶחָד הַכּוֹרֶה בּוֹר, \u0010y1\u0011 וְאֶחָד הַפּוֹתֵחַ בּוֹר שֶׁכָּרָהוּ אַחֵר וְכִסָהוּ כָרָאוּי וּבָא זֶה וְגִלָּהוּ, חַיָּב.\nהַמּוֹצֵא בּוֹר וְכִסָהוּ וְחָזַר \u0010y2\u0011 וְגִלָּהוּ, בַּעַל הַבּוֹר חַיָּב, וְזֶה הָאַחֲרוֹן פָּטוּר. סְתָמוֹ בֶּעָפָר וְחָזַר וְהוֹצִיא אֶת כָּל הֶעָפָר, זֶה הָאַחֲרוֹן חַיָּב, שֶׁכֵּיוָן שֶׁסְתָמוֹ בֶּעָפָר \u0010y3\u0011 נִסְתַּלֵּק מַעֲשֵׂה רִאשׁוֹן.\nאֶחָד הַחוֹפֵר אוֹ הַלּוֹקֵחַ אוֹ שֶׁנִּתַּן לוֹ בְּמַתָּנָה, שֶׁנֶּאֱמַר: בַּעַל הַבּוֹר יְשַׁלֵּם, מִי שֶׁיֵּשׁ לוֹ בְּעָלִים מִכָּל מָקוֹם. וְכֵן אִם נֶחְפַּר \u0010y4\u0011 מֵאֵלָיו, אוֹ שֶׁחָפְרוּ בְּהֵמָה וְחַיָּה בִּרְשׁוּתוֹ, הוֹאִיל וְהוּא חַיָּב לְמַלּאוֹתוֹ אוֹ לְכַסוֹתוֹ וְלֹא עָשָׂה, \u0010y5\u0011 הֲרֵי זֶה חַיָּב בִּנְזִיקִין. \u0005הַגָּה: וְכֵן אִם כָּרָה אַחֵר בִּרְשׁוּתוֹ וְנוֹדַע לְבַעַל הֶחָצֵר, חַיָּב בַּעַל הֶחָצֵר לְכַסּוֹתוֹ, וְאִם לֹא כִּסָּה הָוֵי כְּאִלּוּ חֲפָרָה בְּעַצְמוֹ; וְהַכּוֹרֶה חַיָּב לְשַׁלֵּם לוֹ נִזְקֵי חֲצֵרוֹ (טוּר)\u0006.\nשׁוֹרוֹ שֶׁחָפַר בִּרְשׁוּת הָרַבִּים אוֹ בִּרְשׁוּת אַחֵר, פָּטוּר בַּעַל הַשּׁוֹר, שֶׁנֶּאֱמַר: כִּי יִכְרֶה אִישׁ בֹּר, וְלֹא שׁוֹר בּוֹר.\nאֶחָד הַחוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים, אוֹ הַחוֹפֵר בּוֹר בִּרְשׁוּתוֹ \u0010y6\u0011 וּפְתָחוֹ \u0010y7\u0011 לִרְשׁוּת הָרַבִּים אוֹ פָּתַח לִרְשׁוּת חֲבֵרוֹ, אוֹ שֶׁחָפַר וּפָתַח לִרְשׁוּתוֹ וְהִפְקִיר רְשׁוּתוֹ וְלֹא הִפְקִיר בּוֹרוֹ, הֲרֵי זֶה חַיָּב בִּנְזָקָיו. אֲבָל אִם הִפְקִיר רְשׁוּתוֹ וּבוֹרוֹ, \u0010y8\u0011 אוֹ שֶׁהִפְקִיר בּוֹרוֹ שֶׁבִּרְשׁוּתוֹ, הֲרֵי זֶה פָטוּר. שֶׁנֶּאֱמַר: בַּעַל הַבּוֹר יְשַׁלֵּם, מִי שֶׁיֵּשׁ לוֹ בְּעָלִים, וְזֶה הֶפְקֵר, וּבַתְּחִלָּה בִּרְשׁוּת חָפַר, מִפְּנֵי שֶׁחָפַר בִּרְשׁוּתוֹ.\nהַחוֹפֵר בּוֹר \u0010y9\u0011 בִּרְשׁוּת הָרַבִּים לְצֹרֶךְ רַבִּים, וּמָסַר לָהֶם כִּסוּיוֹ, אוֹ הוֹדִיעַ לְבֵית דִּין שֶׁרוֹצֶה לְהִסְתַּלֵּק מִמֶּנּוּ, שֶׁהֵם יִתְעַסְקוּ בּוֹ לְכַסוֹתוֹ, פָּטוּר. \u0010y10\u0011 וְהוּא שֶׁחָפַר בְּמָקוֹם שֶׁיֵּשׁ רְשׁוּת לַחְפֹּר.\nהָאוֹמֵר לַחֲבֵרוֹ לַחְפֹּר בּוֹר בִּרְשׁוּת הָרַבִּים, וַחֲפָרוֹ; הַחוֹפֵר \u0010y11\u0011 חַיָּב וְהַמְשַׁלֵּחַ פָּטוּר.\nהַבּוֹנֶה סָמוּךְ לִרְשׁוּת הָרַבִּים, רַשַּׁאי לַחְפֹּר לְצֹרֶךְ הַיְסוֹד, \u0010y12\u0011 אֲפִלּוּ לְהַרְחִיבוֹ, לְצַד \u0010y13\u0011 \u0010c0\u0011 רְשׁוּת הָרַבִּים; וְאִם הֻזְּקוּ בּוֹ פָטוּר, כֵּיוָן שֶׁעָשָׂה בִּרְשׁוּת.\nאֶחָד הַחוֹפֵר \u0010y14\u0011 בּוֹר אוֹ שִׁיחַ אוֹ מְעָרָה אוֹ חָרִיץ. \u0010y15\u0011 וְלָמָּה נֶאֱמַר: בּוֹר, שֶׁיְּהֵא בּוֹ כְּדֵי לְהָמִית, דְּהַיְנוּ עֹמֶק י' טְפָחִים; אֲבָל אִם הָיָה פָּחוֹת מִי' טְפָחִים, וְנָפַל לְתוֹכוֹ שׁוֹר אוֹ שְׁאָר בְּהֵמָה חַיָּה וָעוֹף, וּמֵת, פָּטוּר. וְאִם הִזִּיק, בַּעַל הַתַּקָּלָה חַיָּב נֶזֶק שָׁלֵם.\nהָיָה עֹמֶק הַבּוֹר ט' טְפָחִים, וּמֵהֶם טֶפַח אֶחָד מַיִם, \u0010y16\u0011 חַיָּב, שֶׁהַטֶּפַח שֶׁל מַיִם חָשׁוּב כְּעֹמֶק ב' טְפָחִים בַּיַּבָּשָׁה.\nהָיָה עָמֹק שְׁמֹנָה, \u0010y17\u0011 וּמֵהֶם שְׁנֵי טְפָחִים מַיִם, אוֹ שֶׁהָיָה עָמְקוֹ ז' טְפָחִים וּמֵהֶם ג' טְפָחִים מַיִם, וְנָפַל לְתוֹכוֹ שׁוֹר וְכַיּוֹצֵא בּוֹ וָמֵת, אֵין מְחַיְּבִין אוֹתוֹ לְשַׁלֵּם, וְאִם תָּפַס אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: וְעַיֵּן לְעֵיל סִימָן שפ\"ח סָעִיף א' וְז' \u0010y18\u0011 דְּיֵשׁ חוֹלְקִין:\u0006\nחָפַר אֶחָד שְׁמֹנָה, וּבָא חֲבֵרוֹ וְחָפַר עוֹד טֶפַח, \u0010y19\u0011 שְׁנֵיהֶם חַיָּבִים בִּנְזָקִין, כָּל אֶחָד לְפִי מַה שֶּׁחָפַר.\nהַחוֹפֵר בּוֹר עֲשָׂרָה, וּבָא אַחֵר וְהִשְׁלִימוֹ לְכ', וּבָא אַחֵר וְהִשְׁלִימוֹ לְל', \u0010y20\u0011 כֻּלָּם חַיָּבִים.\nחָפַר הָרִאשׁוֹן פָּחוֹת מִי', אֲפִלּוּ טֶפַח, וּבָא אַחֲרוֹן וְהִשְׁלִימוֹ לַעֲשָׂרָה, בֵּין שֶׁחָפַר בּוֹ טֶפַח אוֹ שֶׁהִגְבִּיהַּ בִּנְיָן עַל שְׂפָתוֹ, זֶה \u0010y21\u0011 הָאַחֲרוֹן חַיָּב \u0005אֲפִלּוּ בִּנְזִיקִין (טוּר ס\"ח)\u0006. סָתַם טֶפַח שֶׁהוֹסִיף, אוֹ שֶׁסָתַר טֶפַח שֶׁבָּנָה, \u0010y22\u0011 הֲרֵי זֶה סָפֵק אִם כְּבָר נִסְתַּלֵּק מַעֲשֵׂה רִאשׁוֹן אוֹ אִם עֲדַיִן לֹא נִסְתַּלֵּק.\nחָפַר הָרִאשׁוֹן בּוֹר עָמֹק, וּבָא הָאַחֲרוֹן וְהִרְחִיבוֹ, וְנָפַל לְתוֹכוֹ שׁוֹר וָמֵת, \u0010y23\u0011 אִם מֵחֲמַת הַבְלוֹ מֵת, הָאַחֲרוֹן פָּטוּר, שֶׁהֲרֵי מִעֵט הַבְלוֹ; וְאִם מֵחֲמַת חֲבָטוֹ מֵת, הָאַחֲרוֹן חַיָּב, שֶׁהֲרֵי הִקְרִיב הֶזֵּק בּוֹר זֶה. \u0010y24\u0011 וְכֵן אִם נָפַל הַשּׁוֹר מֵאוֹתוֹ הַצַּד שֶׁהִרְחִיב הָאַחֲרוֹן, חַיָּב, שֶׁהֲרֵי הִקְרִיב הֶזֵּק בּוֹר זֶה אַף עַל פִּי שֶׁמֵּת מִן הַהֶבֶל. \u0010y25\u0011 וְאִם מֵהַצַּד שֶׁחָפַר הָרִאשׁוֹן נָפַל, הָרִאשׁוֹן חַיָּב, שֶׁזֶּה הָאַחֲרוֹן מִעֵט הַבְלוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין חִלּוּק בֵּין מֵת בְּהַבְלָא אוֹ בַחֲבָטָהּ, רַק, אִם נָפַל מִצַּד שֶׁהִרְחִיב חַיָּב בְּכָל עִנְיָן, וְאִם נָפַל מִצַּד הַשֵּׁנִי, הָאַחֲרוֹן פָּטוּר בְּכָל עִנְיָן (טוּר ס\"ח בְּשֵׁם הָרֹא\"שׁ)\u0006.\nבּוֹר שֶׁחִיְּבָה עָלָיו תּוֹרָה, \u0010y26\u0011 אֲפִלּוּ לֹא מֵתָה הַבְּהֵמָה אֶלָּא מֵהַבְלוֹ, וְאֵין צָרִיךְ לוֹמַר אִם מֵתָה מֵחֲבָטוֹ. \u0010y27\u0011 לְפִיכָךְ, אִם הָיָה עֹמֶק הַבּוֹר כְּרָחְבּוֹ, אֵין לוֹ הֶבֶל; \u0010y28\u0011 וְאִם לֹא נֶחְבְּטָה בּוֹ הַבְּהֵמָה וָמֵתָה, פָּטוּר. הָיָה עָמְקוֹ יוֹתֵר עַל רָחְבּוֹ, יֵשׁ לוֹ הֶבֶל, וְאִם מֵתָה בּוֹ הַבְּהֵמָה חַיָּב, אַף עַל פִּי שֶׁלֹּא נֶחְבְּטָה בְּקַרְקָעִיתָהּ. \u0010y29\u0011\nעָשָׂה תֵּל גָּבוֹהַּ בִּרְשׁוּת הָרַבִּים, וְנֶחְבְּטָה בּוֹ הַבְּהֵמָה וָמֵתָה, אִם הָיָה גָבוֹהַּ י' טְפָחִים חַיָּב לְשַׁלֵּם. וְאִם הָיָה פָּחוֹת מִי', פָּטוּר עַל מִיתַת הַבְּהֵמָה, אֲבָל אִם הֻזְּקָה בִּלְבַד חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם. \u0010c1\u0011 וַאֲפִלּוּ בְתֵל גָּבוֹהַּ כָּל שֶׁהוּא אוֹ בַּחֲפִירָה כָּל שֶׁהִיא, שֶׁהַנֶּזֶק בְּכָל שֶׁהוּא דָּבָר מָצוּי וְיָדוּעַ, וְאֵין הַמִּיתָה בְּכָל שֶׁהוּא מְצוּיָה, וַהֲרֵי הוּא כְּמוֹ \u0010y30\u0011 אֹנֶס.\nוְכֵן אֵינוֹ חַיָּב עַל מִיתַת הַבְּהֵמָה בַּבּוֹר אוֹ עַל חֲבָטָתָהּ בַּתֵּל, אֶלָּא אִם הָיְתָה הַבְּהֵמָה קְטַנָּה אוֹ חֵרֶשֶׁת, אוֹ שׁוֹטָה אוֹ סוּמָא, אוֹ שֶׁנָּפְלָה בַּלַּיְלָה, אֲבָל אִם הָיְתָה פִּקַּחַת וְנָפְלָה בַּיּוֹם וָמֵתָה, פָּטוּר, שֶׁזֶּה כְּמוֹ אֹנֶס, מִפְּנֵי שֶׁדֶּרֶךְ הַבְּהֵמָה לִרְאוֹת וְלָסוּר מֵהַמִּכְשׁוֹלוֹת. \u0010y31\u0011\nוְכֵן אִם נָפַל לְתוֹכוֹ אָדָם וָמֵת, אֲפִלּוּ הָיָה סוּמָא אוֹ שֶׁנָּפַל בַּלַּיְלָה, בֵּין שֶׁהָיָה בֶּן חוֹרִין אוֹ עֶבֶד, הֲרֵי זֶה פָּטוּר; וְאִם הֻזָּק בּוֹ הָאָדָם אוֹ הַבְּהֵמָה הַפִּקַּחַת, חַיָּב נֶזֶק שָׁלֵם. \u0005הַגָּה: \u0010y32\u0011 וְיֵשׁ אוֹמְרִים דְּבִּבְהֵמָה פִקַּחַת פָּטוּר אֲפִלּוּ מִנִּזָּקִין אִם נָפַל שָׁם בַּיּוֹם (טוּר סכ\"ב וְהַמַּגִּיד פֶּרֶק י\"ב דְּנִזְקֵי מָמוֹן)\u0006. \u0010y33\u0011\nנָפְלוּ כֵּלִים בַּבּוֹר וְהֻזְּקוּ אוֹ נִשְׁתַּבְּרוּ, פָּטוּר, שֶׁנֶּאֱמַר: וְנָפַל שָׁמָּה שׁוֹר אוֹ חֲמוֹר \u0005(שְׁמוֹת כא, לג)\u0006, שׁוֹר וְלֹא אָדָם, חֲמוֹר וְלֹא כֵּלִים; וְלֹא נִתְמַעֵט אָדָם אֶלָּא מִמִּיתָה, אֲבָל אִם הֻזָּק בּוֹ חַיָּב; אֲבָל עַל הַכֵּלִים פָּטוּר, בֵּין אִם נִשְׁבְּרוּ לְגַמְרֵי בֵּין אִם הֻזְּקוּ.\nכִּסָהוּ כָּרָאוּי, אַף עַל פִּי שֶׁהִתְלִיעַ מִתּוֹכוֹ, וְנָפַל לְתוֹכוֹ שׁוֹר וָמֵת, פָּטוּר, שֶׁנֶּאֱמַר: וְלֹא יְכַסֶנּוּ \u0010y34\u0011 \u0005(שְׁמוֹת כא, לג)\u0006, הָא אִם כִּסָהוּ, פָּטוּר.\nכִּסָהוּ בְּדָבָר שֶׁיָּכוֹל לַעֲמֹד בִּפְנֵי שְׁוָרִים, וְאֵינוֹ יָכוֹל לַעֲמֹד בִּפְנֵי גְּמַלִּים, וְהָלְכוּ עָלָיו גְּמַלִּים וְנִתְרוֹעֵעַ, וְהָלְכוּ עָלָיו שְׁוָרִים וְנָפְלוּ בּוֹ, אִם אֵין הַגְּמַלִּים מְצוּיִים בְּאוֹתוֹ מָקוֹם הֲרֵי זֶה פָּטוּר, מִפְּנֵי שֶׁזֶּה \u0010y35\u0011 אֹנֶס. \u0005מִיהוּ, אִם נָפַל בְּתוֹכוֹ גָמָל, אֲפִלּוּ פִּקֵּחַ, חַיָּב, דְּהוֹאִיל וְרָאָהוּ מְכֻסֶּה עָבַר עָלָיו (טוּר ס\"ט)\u0006. וְאִם יָבֹאוּ שָׁם גְּמַלִּים אֲפִלּוּ לִפְרָקִים, חַיָּב.\nהִתְלִיעַ מִתּוֹכוֹ וְנָפְלוּ בּוֹ שְׁוָרִים, אַף עַל פִּי שֶׁהַגְּמַלִּים מְצוּיִים שָׁם תָּמִיד \u0010y36\u0011 וַהֲרֵי הוּא פּוֹשֵׁעַ לַגְּמַלִּים, הוֹאִיל וּמֵחֲמַת שֶׁהִתְלִיעַ נָפְלוּ בּוֹ הַשְּׁוָרִים, פָּטוּר, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: וְיֵשׁ מְחַלְּקִין: דְפָטוּר בִּכְהַאי גַוְנָא, דַּוְקָא שֶׁאִם הָיוּ עוֹבְרִים הַגְּמַלִּים הָיוּ נוֹפְלִים עִם הַכִּסּוּי, דְּאָז לֹא פָשַׁע כְּלָל לְגַבֵּי שְׁוָרִים, דְּאִם יַעַבְרוּ גְמַלִּים יִפֹּל הַכִּיסוּי, וְלֹא יַעַבְרוּ שְׁוָרִים פִּקְחִין כִּי יִרְאוּ שֶׁאֵינוֹ מְכֻסֶּה; אֲבָל אִם הוּא שֶׁאִם יַעַבְרוּ הַגְּמַלִּים לֹא יִפֹּל הַכִּסּוּי רַק יִתְרוֹעֵעַ, וְאִם יַעַבְרוּ אַחַר כָּךְ שְׁוָרִים יִפְּלוּ, \u0010y37\u0011 חַיָּב אַף בְּהִתְלִיעַ מִתּוֹכוֹ, דְּהוֹאִיל וּפָשַׁע לְגַבֵּי שְׁוָרִים חַיָּב אַף בְּהַתְלָעָה (טוּר ס\"ט)\u0006.\nבּוֹר שֶׁל שְׁנֵי שֻׁתָּפִין, וְעָבַר עָלָיו הָרִאשׁוֹן וְלֹא כִּסָהוּ, הַשֵּׁנִי וְלֹא כִּסָהוּ. הָרִאשׁוֹן חַיָּב, עַד שֶׁיִּמְסֹר דָּלְיוֹ לַשֵׁנִי. \u0010y38\u0011 \u0005וְיֵשׁ אוֹמְרִים דִּשְׁנֵיהֶן חַיָּבִין, עַד שֶׁיִּמְסֹר דָּלְיוֹ לַשֵּׁנִי (טוּר ס\"י)\u0006. \u0010y39\u0011 וּמִשֶּׁמָּסַר דָּלְיוֹ לַשֵּׁנִי לִדְלוֹת מִמֶּנּוּ, נִפְטָר הָרִאשׁוֹן, וְנִתְחַיֵּב הַשֵּׁנִי לְכַסוֹתוֹ:\nכִּסָהוּ הָרִאשׁוֹן, וּבָא הַשֵּׁנִי וּמְצָאוֹ מְגֻלֶּה וְלֹא כִּסָהוּ, הַשֵּׁנִי חַיָּב. וְעַד אֵימָתַי יִהְיֶה הַשֵּׁנִי חַיָּב לְבַדּוֹ, \u0010y40\u0011 עַד שֶׁיֵּדַע הָרִאשׁוֹן שֶׁהַבּוֹר מְגֻלֶּה, וּכְדֵי שֶׁיִּשְׂכֹּר פּוֹעֲלִים וְיִכְרֹת אֲרָזִים וִיכַסֶנּוּ; וְכָל שֶׁיָּמוּת בּוֹ תּוֹךְ זְמַן זֶה, הֲרֵי הַשֵּׁנִי לְבַדּוֹ חַיָּב בּוֹ, וְכָל שֶׁיָּמוּת בּוֹ אַחַר זְמַן כַּזֶּה, שְׁנֵיהֶם חַיָּבִים לְשַׁלֵּם, שֶׁהֲרֵי שְׁנֵיהֶם פָּשְׁעוּ בוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּגַם לַשֵּׁנִי נוֹתְנִין זְמַן עַד שֶׁיִּשְׂכֹּר פּוֹעֲלִים וְיִכְרֹת אֲרָזִים, \u0010y41\u0011 אֶלָּא שֶׁאֵינוֹ צָרִיךְ הוֹדָעָה (טוּר סי\"ב בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אֵינוֹ מוֹצֵא לִקְנוֹת אֲרָזִים אֶלָּא \u0010y42\u0011 בְּיֹקֶר, צָרִיךְ לְהַמְתִּין לוֹ עַד שֶׁיִּמְצָא לִקְנוֹת בְּשָׁוְיָם.\nכָּל הַנְּזָקִים, אִם הוּא דָּבָר שֶׁאֵין דַּרְכּוֹ בְּעַצְמוֹ לְסַלְּקוֹ, אֵין מְחַיְּבִין אוֹתוֹ לְסַלְּקוֹ עַד שֶׁיִּשְׂכֹּר פּוֹעֲלִים. וְהָנֵי מִלֵּי דְאָנוּס, כְּגוֹן בּוֹר שֶׁכִּסָהוּ כָּרָאוּי וְהִתְלִיעַ, אֲבָל בּוֹר שֶׁהִנִּיחוֹ מְגֻלֶּה, פּוֹשֵׁעַ הוּא וּלְאַלְתַּר חַיָּב בִּנְזָקָיו.\nהַמְכַסֶה בּוֹרוֹ בְּדָלְיוֹ שֶׁל חֲבֵרוֹ, וּבָא בַּעַל הַדְּלִי וְנָטַל דָּלְיוֹ, \u0010y43\u0011 בַּעַל הַבּוֹר חַיָּב.\nהַמּוֹסֵר בּוֹרוֹ לְשׁוֹמֵר, חַיָּב בִּנְזָקָיו. וְאִם מְסָרוֹ לְחֵרֵשׁ שׁוֹטֶה וְקָטָן, אַף עַל פִּי שֶׁהָיָה מְכֻסֶה, הֲרֵי הַבְּעָלִים \u0010y44\u0011 חַיָּבִים, שֶׁהַבּוֹר עָשׂוּי לְהִתְגַּלּוֹת וְאֵלּוּ אֵין בָּהֶם דַּעַת:\nבּוֹר שֶׁכָּרוּי וְעוֹמֵד, וְנִכְנַס בּוֹ אָדָם לְהַרְחִיבוֹ אוֹ לְהַעֲמִיקוֹ, וְעָמַד שׁוֹר עַל שְׂפָתוֹ וְנִבְעַת מִקּוֹל הַכּוֹרֶה, וְנָפַל לְתוֹכוֹ, \u0010y45\u0011 בֵּין לְפָנָיו בֵּין לְאַחֲרָיו, חַיָּב בַּעַל הַבּוֹר, אֲפִלּוּ הַשּׁוֹר פִּקֵחַ וּבַיּוֹם; שֶׁהַכּוֹרֶה פָּטוּר שֶׁאֵינוֹ אֶלָּא גְרָמָא, וְכֵיוָן שֶׁאִי אֶפְשָׁר לְהִשְׁתַּלֵּם מִמֶּנּוּ, יִשְׁתַּלֵּם מִבַּעַל הַבּוֹר. \u0010y46\u0011 אֲבָל אִם נִבְעַת הַשּׁוֹר מִקּוֹל הַכּוֹרֶה וְנָפַל לַאֲחוֹרֵי הַבּוֹר, פָּטוּר.\nשׁוֹר שֶׁדָּחַף בְּהֵמָה לְתוֹךְ הַבּוֹר וָמֵת, אִם מוּעָד הוּא, בַּעַל הַבּוֹר מְשַׁלֵּם מֶחֱצָה וּבַעַל הַשּׁוֹר מֶחֱצָה; וְאִם תָּם הוּא, בַּעַל הַשּׁוֹר מְשַׁלֵּם רְבִיעַ מִגּוּפוֹ וּבַעַל הַבּוֹר מְשַׁלֵּם ג' חֲלָקִים מֵהַיָּפֶה שֶׁבִּנְכָסָיו; שֶׁבַּעַל הַנְּבֵלָה אוֹמֵר לְבַעַל הַבּוֹר: \u0010y47\u0011 פְּחַת נְבֵלָה זוֹ יֵשׁ לִי אֶצְלְךָ, \u0010y48\u0011 אַף עַל פִּי שֶׁהִיא גְּדוֹלָה וּפִקַּחַת, \u0010y49\u0011 כֵּיוָן שֶׁנִּדְחֲפָה, הֲרֵי זוֹ כְּמִי שֶׁנָּפְלָה בַלַּיְלָה, כָּל שֶׁאֲנִי יָכוֹל לְהוֹצִיא מִבַּעַל הַשּׁוֹר אֲנִי מוֹצִיא \u0010y50\u0011 וְהַשְּׁאָר אַתָּה חַיָּב לְשַׁלְּמוֹ.\nוְכֵן הַמַּנִּיחַ אֶבֶן עַל פִּי הַבּוֹר וּבָא הַשּׁוֹר וְנִתְקַל בָּהּ וְנָפַל לַבּוֹר וָמֵת, הַמַּנִּיחַ אֶת הָאֶבֶן מְשַׁלֵּם מֶחֱצָה, וּבַעַל הַבּוֹר מֶחֱצָה.\nאִם אָדָם וְשׁוֹר דָּחֲפוּ שׁוֹר אַחֵר לְבוֹר; וְהָיָה אָדָם שֶׁלֹּא \u0010y51\u0011 בְּכַוָּנָה, שֶׁאִם הָיָה בְּכַוָּנָה הָיָה בַּעַל הַבּוֹר פָּטוּר; שְׁלָשְׁתָּן חַיָּבִים; אִם הַשּׁוֹר מוּעָד, מְשַׁלְּשִׁים בֵּינֵיהֶם. וְאִם הוּא תָּם, \u0010y52\u0011 מְשַׁלֵּם הַשְּׁתוּת, וְהַמּוֹתָר יְשַׁלְּמוּ בֵּינֵיהֶם הָאָדָם וּבַעַל הַבּוֹר.\nאִם דָּחֲפוּ אִשָּׁה וְיָצְאוּ יְלָדֶיהָ, הָאָדָם לְבַדּוֹ חַיָּב הַכֹּל, \u0010y53\u0011 וְשׁוֹר וּבוֹר פְּטוּרִים.\nאִם דָּחֲפוּ בּוֹ אָדָם וְהֻזָּק, שְׁלָשְׁתָּם חַיָּבִים בְּנֶזֶק. וְאָדָם לְבַדּוֹ \u0010y54\u0011 \u0010c2\u0011 חַיָּב בִּשְׁאָר \u0005(ד')\u0006 דְּבָרִים. וְאִם דָּחֲפוּ בּוֹ כֵּלִים וְנִשְׁבְּרוּ, אָדָם וּבַעַל הַשּׁוֹר \u0010y55\u0011 חַיָּבִים, וּבַעַל הַבּוֹר פָּטוּר.\nיֵשׁ מִי שֶׁאוֹמֵר, הוּא הַדִּין לִשְׁנַיִם שֶׁהִזִּיקוּ וּשְׁנֵיהֶם בְּנֵי חִיּוּבָא, אֶלָּא שֶׁהָאֶחָד בָּרַח אוֹ שֶׁאֵין לוֹ בַּמֶּה לְשַׁלֵּם, מִשְׁתַּלֵּם \u0010y56\u0011 מֵהָאַחֵר עַד שִׁעוּר מַה שֶּׁהָיָה הוּא חַיָּב עַל נֶזֶק זֶה אִלּוּ עֲשָׂאוֹ לְבַדּוֹ. \u0010c3\u0011 וְיֵשׁ חוֹלְקִין דְּכֵיוָן דַּחֲבֵירוֹ מִדִּינָא בַּר תַּשְׁלוּמִין אֶלָּא שֶׁאֵין לוֹ מַה לְּשַׁלֵּם, לָמָּה יִפְרַע זֶה בִּשְׁבִילוֹ. וּלְפִי זֶה, שׁוֹר שֶׁדָּחַף בְּהֵמָה לְבוֹר, הָאִדָּנָא אֵינוֹ מְשַׁלֵּם אֶלָּא ג' חֲלָקִים; אַף עַל פִּי שֶׁהַשּׁוֹר פָּטוּר אַף מֵהָרְבִיעַ, שֶׁהֲרֵי אֵין דָּנִין דִּינֵי קְנָסוֹת, אֵין בַּעַל הַבּוֹר מְשַׁלֵּם אוֹתוֹ בִּשְׁבִילוֹ.\nהַחוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים וְנָפַל עָלָיו שׁוֹר וַהֲרָגוֹ, \u0010y57\u0011 בַּעַל הַשּׁוֹר פָּטוּר. וְאִם מֵת הַשּׁוֹר, נוֹטֵל בַּעַל הַשּׁוֹר דְּמֵי שׁוֹרוֹ \u0010y58\u0011 מִיּוֹרְשֵׁי בַּעַל הַבּוֹר:",["\u0003ומונח במקומו ומזיק כו'. \u0004 ל' הטור אם הוא בעומק או בגובה או אפילו לא זה ולא זה אלא שפך מים כו' ועפ\"ר:","\u0003ואחד הפותח בור \u0004 דכתיב בפרשת משפטים גבי אהדדי כי יפתח איש בור או כי יכרה איש בור ולא יכסנו ונפל שמה שור או חמור בעל הבור ישלם כו' ומדכתיב ולא יכסנו ש\"מ דבהכיסוי הוא פטור ומינה נלמד דמ\"ש כי יפתח איש בור בעל הבור ישלם דהפותח הכיסוי נקרא בעל הבור ומחייב בתשלומי הניזקין שיפלו בה:","\u0003בעל הבור חייב. \u0004 עפ\"ר שכתבתי בשם המ\"מ דאפי' ראה הראשון דכיסהו שני ולא ראה שחזר וגילהו אפ\"ה הראשון חייב דלא ה\"ל לסמוך אהכיסוי של זה שאין לו חלק בבור משא\"כ בבור של שני שותפין כדלקמן בסימן זה:","\u0003נסתלק מעשה הראשון. \u0004 פי' כאלו לא חפרו מעולם והשני חפרו מחדש:","\u0003או שחפרו בהמה וחיה כו'. \u0004 פי' אע\"ג דכתיב כי יכרה איש בור וכמ\"ש המחבר בסעיף שאחר זה ה\"מ בחופר בר\"ה דהקרקע אינו שלו וכיון דהוא לא חפר אין עליו למלאות קרקע שאינו שלו משא\"כ בחפר' בהמתו בחצירו דלא גרע מנחפר בור שם מאליו דמוזהר עכ\"פ שלא יוזק אדם ממונו דהיינו חצירו שהוא קרקע שלו שיש בו בור והיינו דוקא אם הפקיר חצירו שסביב הבור ולא הפקיר באותו פעם גם מקום הבור דאל\"כ אלא דלא הפקיר כלל יכול לומר מה לאחרים לילך בחצרי דאתחייב בשמירתן וה\"ל דומיא דהיזק רגל בחצר הניזק דפטור כמ\"ש בסי' ש\"ץ ושצ\"א ואם הפקיר אח\"כ הבור וחצירו שסביבו בפעם אחת ג\"כ לא נתחייב על היזק הבור כיון דבשעת הכריה הי' הכל שלו ושוב לא עשה מעשה בחפיר' דיתחייב עליו משא\"כ כשחפר תחילה בחצירו ואחר כך הפקיר מקום שסביב לבור ונותן רשות לכל לקרב נפשם סמוך לבור דהוה ליה כפותח בור לר\"ה דמחויב לשמור בורו מהזיקתן וכמ\"ש הטור והמחבר בסמוך בסעיף ו' ומשם נלמד ג\"כ זה שכתבתי דמיירי שהפקיר רשותו לחוד ולא שניהן יחד ואחר שהפקיר רשותו לחוד אף שאח\"כ ג\"כ הפקיר בורו חייב על נזקי' דלאו כל כמיניה להפקיר נזקיו שכבר עליו החיוב לסלק התקל' וע\"ל בטור ובדברי המחבר ר\"ס שצ\"ח ובפרישה מ\"ש עוד מזה:","\u0003ה\"ז חייב בניזקין \u0004 מדלא כתבו בדין זה ג\"כ השיעור בכדי שידע וישכור פועלים ויכרתו ארזים כמ\"ש לקמן בסכ\"ו נראה דזה דומה לחופר בור והניחו מגולה דכתב הטור והמחבר לקמן בסכ\"ח דמחשב פשיעה ולאלתר חייב בניזקין והוא הדין בור שחפרו השור בחצירו כיון דעליו מוטל לטרוח ולכסותו:","\u0003ופתחו לר\"ה. ל' הטור שפתחו ברשותו בתוך ד\"ט סמוך לר\"ה עכ\"ל וה\"ט דכל ד\"ט סמוך לר\"ה דחקי ביה רבים אבל בפתחו לרשות חבירו בעינן שיסמכו לרשות חבירו ומ\"ה לא כתב הטור ד\"ט כ\"א בסמוך לר\"ה ועפ\"ר:\u0004","\u0003או פתחו לרשות חבירו כו'. \u0004 ז\"ל הטור ומיהו דוקא קודם שנודע לבעל החצר אבל אחר שנודע לו פטור הכורה כיון דהוא חייב בניזקי הבעל החצר הי' לו לבעל החצר למלאותו מיד וזה יפרע לו וכיון דלא מלאוהו כמאן דכרייה איהו דמי עכ\"ל ואף ע\"פ שהבור אינו ברשות בעל החצר הניזק אלא ברשות החצר המזיק רק שפתוח לרשות הניזק מ\"מ כיון שעומדת סמוך לחצר הניזק ממש וכמ\"ש ה\"ל כאלו עומדת בחצר הניזק ועליו לסתמו להרחיק ממנו נזקו ויקבל שכר טרחתו מהכורה:","\u0003או שהפקיר בורו שברשותו כו'. \u0004 הוא מטעם שכתבתי כיון דלא הי' להניזק רשות ליכנס ולהקריב להבור אין בעל הבור חייב בשמירתו:","\u0003לצורך רבים כו'. \u0004 בטור בשם הרמ\"ה כתב דאי חפר מעיקרא לצורך עצמו והדר מימלך למימסרי' לרבים דלא נפטר החופר עד דטמים ליה וכתב עליו הטור ז\"ל ואינו נראה כיון דמסרו עתה לרבים והן צריכים לו מאי נ\"מ שחפרו מתחלה לצרכו עכ\"ל:","\u0003והוא שחפר במקום שיש לו רשות לחפור \u0004 כן כתב ג\"כ הטור בשם הרמ\"ה ז\"ל והני מילי שחפר לצורך רבים במקום שיש לו רשות לחפור כו' ור\"ל דאפילו בר\"ה אינו מותר לחפור לצורך רבים אלא כשכורה במקום שאינו מעבר לרבים וכדומה לו שמזיק לרבים וק\"ל:","\u0003והמשלח פטור. \u0004 משום דאין שליח לדבר עבירה וע\"ל בר\"ס קפ\"ב:","\u0003אפי' להרחיבו לצד ר\"ה \u0004 נראה דר\"ל ל\"מ דמותר לעשות ברשותו בתוך ד\"ט סמוך לר\"ה אף דבלא לצורך בנין הוה אסור וכמ\"ש בסמוך בס\"ו אלא אפי' לחפור עד סוף גבול והיינו שהרחיב קצה הבור עד שהיה עומדת פתוח' בצד ר\"ה ממש מותר:","\u0003ואם הוזקו בו פטור כו'. \u0004 ול\"ד למש\"ר לקמן בסי' תי\"ד בהוצאת זבלים בר\"ה או בהנחת קוריו ועציו לצורך בנין בס\"ס תי\"ז דג\"כ עשאו ברשות ואפ\"ה אם מקלקלין ומזיקין שם דחייב דשאני התם דעושה בר\"ה עצמו משא\"כ כאן דהבור עומד ברשותו וגם הוא לשעה ומיד אחר החפירה יחזור לסותמו באבני הבנין שיניח ביסוד חומתו ומה\"ט אינו דומה לעושה תנור בביתו והרחיקו כשיעור מהעלי' ואפ\"ה אם הודלק העליה דחייב על העלייה כמ\"ש הטור והמחבר בר\"ס קנ\"ה דשם הוא עושה כן תדיר משא\"כ זה שעושה לפי שעה וכ\"כ הרי\"ף כתבתיהו בדרישה ע\"ש מ\"ש עוד מזה:","\u0003בור או שיח כו'. \u0004 במתני' קתני ג\"כ ונעיצין ול\"מ בכולן קאמר ל\"מ בור דהוא קטן ועגול ובהפשיטא דחייב דיש בה הבל אלא אפילו שיח שהוא ארוך ואפי' מערה שהיא מרובעת ואפילו חריצין שאין מקורין ואפי' נעיצין שהן רויחי מעילאי טפי מתתאי דלית בה הבל אלא דבר מועט קמ\"ל דאפ\"ה חייב ושם במשנה סיים וקתני ז\"ל אף כל הדומה לבור ומפרשו שמואל דבא לרבות בהאי כל כגון שעשה תל גבוה י' טפחים וכתבתי בפרי' דאליבי' (דאלו לרב מיושב בע\"א וכתבתי בדרישה ע\"ש) ה\"ק המשנה ל\"מ הני דאית בהו הבלא וחבטה אלא אפי' דבר דלית בהו הבל כלל כגון עשה תל ונכשל בה או נפל מעליו ג\"כ חייב:","\u0003ולמה נאמר בור. \u0004 פי' למה כתבה התורה כי יכרה איש בור לחייב עליו כיון דאפי' אהני ג\"כ חייב ומשני דנקט בור דהוא ידוע בשיעור עמיקתו וכאלו אמר דנקט בור לרבותא לענין פטור דאפי' בור אם אינו עמוק י\"ט ונפל שמה שור או חמור ומת פטור דה\"ל מיתה אונס דאין דרך הבהמה למות בנפיל' בפחות מי\"ט ק\"ו לשיח ומערה כשאינן גבוהין י\"ט:","\u0003שהטפח של מים חשוב כו'. \u0004 פי' נחשב לענין הבל שיש הבל במים יותר מבאויר:","\u0003ומהם שני טפחים מים כו'. \u0004 איבעיא הוא בגמרא דלא איפשטא אי גם בכה\"ג יחשב כל טפח מים לשני טפחים אויר ומ\"ה אם אינן אלא ז' עם המים דהיינו ג' טפחים עמקות המים וע\"ג המים עוד ד' טפחים אויר אי ג\"כ הוה לענין הבל כעומק עשרה טפחים דג\"ט של מים יחשבו כששה של אויר והרי עשרה טפחים ביחד או לא ובכזה אמרי' המע\"ה ועפ\"ר שם כתבתי שיש גירסאות בזה ושהטור כתב הגירסא שבעומק ח' ומהן ב\"ט של מים פשיטא להגמ' דנחשב כשתים שהן ארבע וחייב והאיבעיא היא דוקא בבור של ז' ומהן ג\"ט של מים או בשל ט' ומהן טפח א' של מים (דקמבעיא ליה אי נחשב טפח א' של מים להבל) ע\"ש:","\u0003די\"ח. \u0004 פי' חולקין וס\"ל דלא מהני תפיסה בספיקא דדינא:","\u0003שניהן חייבין בניזקין. \u0004 דקדק וכתב בניזקין לאפוקי נפלה שם בהמה ומתה דפטור כל שאינו עמוק עשרה וכנ\"ל:","\u0003כולם חייבים \u0004 פי' אפילו לענין אם נפלה שם בהמה ומתה כיון דיש במעשה דכל אחד כדי להמית וכח דכולם מעורבים בו.","\u0003האחרון חייב אפילו בניזקין \u0004 דכיון דבור זה נקרא ע\"ש האחרון לחוד לענין תשלומין כשנפל שם ומת נקרא ג\"כבורולחוד לענין ניזקין:","\u0003הרי זה טפח כו' איבעיא דלא איפשיטא הוא שם בגמרא אם מחויב תו האחרון בתשלומי ניזקין שיזיק בהבור שאינו עמוק עשרה מי אמרינן כיון דבשע' שהוסיף טפח היה הוא בעל הבור לחוד לחייב עליה וכמ\"ש מאותה שעה נסתלק מעשה הראשון גם לענין זה דאף שלאחר שחזר והסיר התוספות נקרא הבור על שמו או נימא דחזר הדבר לקדמותו מיד שהסיר מה שהוסיף וחייב הראשון ולא השני וכיון דלא איפשטא דינא הוי דהמע\"ה להמחבר ולהחולקין לא מהני ת\"ה וכמ\"ש בס\"ב.\u0004","\u0003אם מחמת הבלו מת האחרון פטור. \u0004 נראה דר\"ל שנפל לבור דרך פיה למטה ומתה וניכר הדבר להרואים שמתה מחמת הבל ולא מחמת חבטה ואם מחמת חבטה היינו שנפלה לבור על גבה וניכר להרואים שלא מתה אלא מחמת החבט' ומיירי בבבא זו כשנפל מצד שלא הרחיב וכדמסיק ואפ\"ה מסיק דחייב כשמת בחבטה שהרי הקריב היזק בור זה כו' ור\"ל דכיון דהיא גרם היזק לענין חבט' אם נפל מצד שהרחיב מקרי בעל הבור לענין חבט' אף כשיפול מיד השניי' ועפ\"ר:","\u0003וכן אם נפל השור כו'. \u0004 אפילו מתה מחמת הבלו חייב וה\"ט דכיון שהוא פושע לענין שור זה עצמו דהי' ראוי למות מחמת חבטה שקירב מיתתו לענין חבטה תלינן נמי בו מיתה מהבל אף ע\"פ שמיעט הוא מהבל וכמ\"ש הרא\"ש והטור והמחבר דומה לזה סמוך לענין אם פשע בשור לענין גמלים אלא שאינו דומה ממש כיון דכאן נראה לעינים דמיעט ההבל ומ\"ה השיג הטור אדברי הרמב\"ם בזה:","\u0003ואם מהצד שחפר הא' כו'. \u0004 פי' אף כשמת מההבל וכבר כתב המחבר בריש סעיף זה דבכה\"ג האחרון פטור וכאן קמ\"ל דהראשון חייב ולא אמרי' דנסתלק מעשה הראשון כשהרחיב זה הבור:","\u0003אפילו לא מתה הבהמה אלא מהבלו \u0004 ואצ\"ל אם מתה מחבטה כ\"כ ג\"כ הרמב\"ם והל' אינו מדוקדק ע\"פ פלוגתת רב ושמואל דרב ס\"ל דלא מחייב משום בור אא\"כ מתה מהבל הבור ולא מהחבט' כיון דהוא קרקע עולם (אם לא שהבור ברשותו וסמך לר\"ה דאז קרקעית הבור דידי' הוא) ולשמואל חייב נמי אם מתה בחבט' וקי\"ל כוותי' והנה לרב לא א\"ש דהא ס\"ל דפטור אם מתה בחבט' ולשמואל הל\"ל איפכא אפי' מתה בחבט' ואצ\"ל בהבלא וצ\"ל דלסברת שמואל מאחר דחייבי התור' אחבט' אף שהיא קרקע עולם תו יש סברא לחייבו יותר ע\"י חבט' דיש בו מעש' טפי ממת' ע\"י הבל הבור דאין בו אלא כעין גרמא:","\u0003לפיכך אם היה עומק הבור כרחבו כו'. \u0004 פטור הטעם דמתה באונס שלא כדרך מיתת הבהמות והרי לא היה כאן לא חבט' ולא הבל והאי לפיכך דכתב נמשך למ\"ש בבבא שניי' וה\"ק כיון דחייב על הבלא בלא חבט' לפיכך אם היה עומקו יותר כו' חייב.","\u0003ואם לא נחבט' בו הבהמה כו'. \u0004 בטור מפורש כגון שהי' בתוכו ספוגין שהן רכים ואינ' ניזקה מחבטת' עליהן:","\u0003עשה תל גבוה בר\"ה ונחבטה בו הבהמה כו' \u0004 קמ\"ל בזה דאע\"ג דאין כאן הבל אפ\"ה חייב כיון דמתה מחמת חבט' וק\"ק דלענין אם נחבט' בתל עצמו א\"צ גבוהי' דהא אפי' נתקל הבהמ' בקרקע עולם והוזק' באבן ומת' חייב כמ\"ש הטור והמחבר בסי' שאחר זה גם ה\"ל לכתוב רבותא כאן דאפי' לא נחבט בתל אלא בקרקע עולם וכן בסעיף שאחר זה דכתב ז\"ל וכן אינו חייב כו' עד או על חבטת' בתל ובטור כתב ז\"ל דאם עשה תל בר\"ה גבוה י' ועלה עליו שור ונפלה לארץ ומתה חייב וזה א\"ש דתל דומה לבור דאם נפל מלמעל' למט' בעינן גבוה י' כיון דהוזק' לבסוף בקרקע עולם:","\u0003וכן אינו חייב על מיתת הבהמה בבור או כו'. \u0004 כצ\"ל וכתב בבור ל' מיתה ור\"ל בין שמת' בחבט' בין בהבל משא\"כ בתל שאין שם הבל כ' בו ל' חבט':","\u0003וכן אם נפל לתוכה אדם ומת כו'. \u0004 דכתיב ונפל שמה שור או חמור. ושור וחמור ל\"ד הוא דהא ילפי' שור שור משבת דעל כל בהמה חייב וא\"כ למה נכתב שור וחמור ודרשינן שור ולא אדם חמור ולא כלים ומיעוט דשור ולא אדם היינו דוקא אם נפל שם האדם ומת דקרא זה במית' איירי כדכתיב בו והמת יהי' לו אבל אם נפל שם אדם והוזק לא נתמעט מתשלומי הזיקו אבל כלים דאיתמעטו אתמעטו ואפי' בשבירתן דהא שבירתן זהו מיתתן וכ\"כ המחבר בסעיף שאחר זה:","\u0003וי\"א דבבהמה פקחת פטור כו' \u0004 דבהמ' עיני' למט' ודרכ' להתבונן בדרכי' ולהשמר מנזקי' משא\"כ אדם שהולך ועינו משוטטו' למעל' ולהלן מדרך הלוכו וכמ\"ש בסימן תי\"ב ס\"ג בדברי המחבר גם בטו' ע\"ש:","\u0003נפלו כלים לבור כו'. \u0004 ל' הטור ואפי' נפל שם השור עם הכלים ומת השור ונשתברו הכלים חייב על השור ופטור על הכלים:","\u0003הא אם כסהו פטור. \u0004 קמ\"ל דל\"ת דעליו לסתמו בעפר באופן שלא יוכל להגיע ממנ' היזק:","\u0003מיהו אם נפל בתוכו גמל כו'. \u0004 פי' אע\"ג דגמלים אינם שכיחי' כלל מ\"מ ה\"ל לאסוקי אדעתי' שמא יבא אבל אם נפל שמה שור כולי האי לא ה\"ל לאסוקי אדעתי' כשאין גמלים שכיחים שיבא גמל ויארעוהו ואח\"כ יבא שור ויפול בו:","\u0003והרי הוא פושע לגמלי'. \u0004 פי' דאם עברו שם גמלים היו נופלים שם השוורי' והגמלי' שכיחי' וה\"ל פושע מתחלתו שמא יעברו שם גמלים מ\"מ הואיל ולא עברו גמלים ולא נפלו לבור אלא מכח שהתליע הכיסוי ה\"ל אונס שלא בא מחמת הפשיע' ופטו' וע\"ז כ' מור\"ם דיש מחלקין וס\"ל דחיי' בזה:","\u0003חייב אף בהתליע מתוכו הטור כתב מילתא בטעמא יותר והוא כיון דפשע לענין השור זה עצמו דהרי זה השור שנפל כאן מחמת התלעה ג\"כ הי' נופל שם אם הי' שעברו שם גמלים וקלקלו הכיסוי (משא\"כ כשנפל בבור שור פקח דאף שפשע לענין נפיל' שור חרש או סומא מ\"מ לענין שור פקח שנפל שם לא הי' בו צד פשיע') כיון דפשע מתחל' בשור זה עצמו אף שבסופו הי' האונס מחמת התלעה ונראה דאינו מחמת הפשיע' מ\"מ כל שפשע מתחלה באותו דבר עצמו כל מאי דאפשר לתלות בו תלינן אף בחשש רחוק (ובפרט התלעה שהוא ג\"כ דבר שאינו שכיח וכ\"ד שא\"ש הוא על המיעוט) ותלינן לומר שאם הי' מכסהו בכיסוי חזק שראוי לעמוד לפני הגמלים לא הי' נתלע ועפ\"ר מ\"ש עוד מזה יותר כאן וגם לעיל ר\"ס שצ\"ו:\u0004","\u0003וי\"א דשניהן חייבין הא דכתב מור\"ם בל' י\"א משום שנ\"ל מוכח דהראשון חייב דכ' הרמב\"ם והמחבר ר\"ל דחייב הראשון לבדו דאם לא כן אלא תאמר מ\"ש חייב הראשון ר\"ל אף הראשון וכמו שפי' הרא\"ש לדברי הרי\"ף א\"כ מ\"ש אחר זה עד שימסר דליו לשני ע\"כ ר\"ל דכוונתו דאז נתחייב השני לבדו ותו לא הוה צ\"ל ז\"ל ומי שמסר דליו להשני כו' נתחייב השני לכסותו וק\"ל ומה\"ט כתב הטור ג\"כ אל' הרמב\"ם שהוא כל' המחבר ול\"נ כו' ע\"ש וכמ\"ש בדרישה ולא כב\"י שתמה על הטור עבור זה:\u0004","\u0003ומשמסר דליו להשני לדלות. משמע דמפרש דליו מלשון דלי וכן פי' ר\"ח אבל רש\"י והטור פירשו דליו כיסוי הבור ע\"ש:\u0004","\u0003עד שידע הראשון דקדק וכ' עד שידע דהיינו שהודיעו ממש ולא די בכדי זמן שיכול להוודע דדילמא לא נודע לו ואח\"כ כ' וכדי שישכור פועלים כו' דאחר שנודע לו והי' לו שהות זמן לשכור פועלים ולא שכרם מאז גם הוא יש לו חלק בתשלומי נזקין ועפ\"ר:\u0004","\u0003אלא שאינו צריך הודעה דהא מיירי שכבר ידע דהא מתחל' כ' ובא השני ומצאוהו מגול':\u0004","\u0003צריך להמתין לו כו'. ע\"ש בטור ובפריש' שם כתבתי הוכחתם:\u0004","\u0003בעל הבור חייב. בטור מסיים בזה וכתב ז\"ל ואין בעל הכיסוי צריך להודיעו שנטלו ע' ד\"מ שכתבתי ליישב דל\"ת מזה למ\"ש הרא\"ש דחייב הנוטל (והביאו מור\"ם בהג\"ה לעיל סימן שפ\"ג ס\"ד) דשאני התם בתשובה דהסומך חביתו בר\"ה באבן של חבירו ובא חבירו ונטל אבנו דנשבר החביו' מיד וה\"ל כהזיקו בידים משא\"כ כאן בגיל' הבור דאין ההיזק בא מיד אלא לאחר זמן כשיפול שם בהמת חבירו וגם לא ברי כ\"כ היזקו:\u0004","\u0003שהבור עשוי להתגלות. ע\"ל בסי' שצ\"ו ס\"ו בדין המוסר שורו ביד חש\"ו דכתב דאפי' היה קשור בהחבל מחשב פשיעת בעלים משום שדרך השור להתיר הקשר ופירש התו' דר\"ל דחש\"ו בעצמן יתירוהו נראה דה\"ה כאן י\"ל כיון דלאו בני דעה נינהו חיישינן שיגלו להבור העשויה להתגלות בקל כי בגמ' אתאמרו הני שני דינים יחד ע\"ש שכתבתי שם לשון הגמרא:\u0004","\u0003בין לפניו בין לאחריו. \u0004 פירוש דאם נפל השור דרך פניו מסתמא מת בהבל ואם מת בבור דרך אחוריו אז מסתמא לא מת מכח הבל אלא מחמת חבטה וכנ\"ל וכבר נתבאר דקי\"ל דחייב בעל הבור בין מת בחבט' בין בהבל ועיין ברמב\"ם שכתב דאם נפלה מאחריה לבור פטור אבל הראב\"ד וגם המ\"מ תמהו שם על דבריו ע\"ש:","\u0003אבל אם נבעת השור מקול הכורה ונפל לאחורי הבור. \u0004 כן הוא ג\"כ ל' הרמב\"ם ובטור כתב אבל נבעת מקול הכור' ונתקל בבור ונפל כו' והטעם דפטור כיון דקרקע עולם הזיקתו והוא דומה לנתקל באבן וניזק בקרקע דפטור כמ\"ש הטור והמחבר בסי' תי\"א ס\"א:","\u0003פחת נביל' זו יש לי אצלך. שהרי בבורך מצאתי הזיקי:\u0004","\u0003אע\"פ שהיא גדולה ופקחת כו' \u0004 בטור כתב האי אע\"פ ברישא וז\"ל שור שדחף בהמה לבור אע\"פ שהוא ביום ופקחת כו' וא\"ש טפי ונוסחת המחבר והרמב\"ם צ\"ל דהניזק מדבר כן עם בעל השור דפחת נבילתו היא אצלו לחוד אע\"פ כו' ומ\"ה כל שאני יכול להוציא כו':","\u0003כיון שנדחפה כו'. \u0004 דהיה לבעל הבור לאסוקי אדעתי' שמא ידחפנו אותו שור שם ויגרם בורו היזק לבעל השור:","\u0003והשאר אתה חייב לשלמו. \u0004 היינו דין דאמר רבי נתן בגמ' כל היכא דליכא לאשתלומי מהאי משתלם מהאי:","\u0003שאם היה בכונה כו' \u0004 הוא מטע' שכתבו התו' ז\"ל דאטו אם ישים אדם טליתו של חבירו באש מי מחייב בעל האש:","\u0003משלם השתות. \u0004 דכיון שיש שנים עמו אין מגיע אלא שליש לנזק שלם והשתא דהוא תם אם עשה היזק לחוד לא היה משלם אלא חצי נזק חצי' מחלק שלו הוא שתות:","\u0003ושור ובור פטורים. \u0004 פי' בעל השור ובעל הבור פטורים השור מדכתיב וכי ינצו אנשים ולא שוורים ובור דרשינן שור ולא אדם וכנ\"ל וכיון דליכא לאשתלומי מהני משתלם מאדם כולה:","\u0003חייב בשאר ד' דברי'. \u0004 דאיש בעמיתו כתיב:","\u0003ובעל הבור פטור \u0004 דחמור כתיב ולא כלים וכנ\"ל","\u0003עד שיעור מה שהי' הוא חייב כו'. \u0004 בטור מבואר זה יותר ז\"ל ודוקא עד שיעור מה שהי' חייב ביה אהאי נזקא היכא דהו' עביד ליה איהו לבדו אבל טפי לא עכ\"ל ולכאורה הי' נראה לפרש דר\"ל משום דלפעמים נחבל וניזק יותר מדחיפת שנים מבדחיפת א' ובא לומר דבכה\"ג אין האחד צריך לשלם כל הנזק הנעשה ע\"י שניהן כיון דאין הא' יכול להזיקו כ\"כ אבל ק' דה\"ט שייך גם בדחפו כלים לבור ונשברו דאי לאו בור לא היו נשברים הכלים מדחיפת האדם ואפ\"ה קאמר לפני זה דצריך האדם לשלם כל נזק. הכלים ☜לכן נר' דלא אתי לאפוקי אלא כגון אדם ושור שדחפו אדם והזיקוהו שנתבא' לפני זה שבדמי היזקו המה משותפי' ובשאר ד' דברי' האדם צריך לשלמן לבדו ולמדונו כאן דאם ברח האדם אזי על בעל השור חיוב לשלם כל דמי נזקו כאלו הזיקו לבדו אבל שאר ד' דברים א\"צ לשלם עבור האדם שברח ואע\"ג דבעל השור עומד בחיוב התשלומין בעד האדם לא אמרינן דעומד במקומו בכולו משום דאף אם הי' מזיקו השור לבדו לא הי' חייב לשלם ודוק:","\u0003בעל השור פטור. \u0004 דאיהו גרם ההפסד לנפשו בחפירתו:","\u0003מיורשי בעל הבור. \u0004 רצה לומר ל\"מ דאם הוא חי דצריך לשלם השור אלא אפילו מת הכורה צריכי' בניו היורשים לשלם לבעל השור הזיקו ואע\"פ דמלוה על פה של ראובן אינן נפרעין מיורשיו אחרי מותו שאני הכא כיון דאביהן עכשיו מת בשעה שנפל שם השור בודאי לא פרע להן עדיין דמי השור ועפ\"ר:"],["\u0003 ואם הוזקו בו פטור. \u0004 וביש\"ש כתב שהוא טעות וחייב לשלם והש\"ס איירי כשכנס החומה לתוך שלו והחפירה הוא בחלק הכניסה ע\"ש שהוכיח כן ודלא כמ\"ש בסמ\"ע ס\"ק י\"ד וכ\"כ הב\"ח:","\u0003 ואפילו בתל גבוה \u0004 מלשון זה נראה אפילו התל והחפירה הוא פחות מג' טפחים ומהרש\"ל סימן כ\"ד כתב דכל פחות מג' טפחים הוא כארעא סמיכתא ופטור דלא מיקרי בור ולדבריו צ\"ל דל\"ד קאמר המחבר והרמב\"ם כל שהוא וכה\"ג אשכחן פ' ראשית הגז ומסכת נדה ופרק העור והרוטב וכמה כל שהוא כו' אמנם מדברי המרדכי סוף הבית והעלי' ומדברי הרב לקמן סימן תי\"ד ס\"ב בהג\"ה מוכח לכאורה דאף פחות מג\"ט אף דאינם יכולים לעכב מ\"מ אם הזיק חייב לשלם ודמי למוציא זבלים שלא בשע' הוצאת זבלים כדי לפנותו לאלתר ודו\"ק במרדכי ואם כן צ\"ע לדינא:","\u0003 חייב בשאר ד' דברים \u0004 והא דחייב בבושת אף דע\"כ איירי שדחפו שלא בכוונה כמ\"ש סל\"ד צ\"ל כמ\"ש התוספת כגון שידע אדם בשעת נפילת חבירו והשיב בכונה ומהרש\"ל סימן מ\"ב פסק דפטור מבשת אא\"כ שבתחלה דחפו השור ואח\"כ בא האדם להוסיף עליו וע\"ש שהאריך ודבריו דחוקים ע\"ש:","\u0003 וי\"ח \u0004 וכ\"כ הג\"ה מיי' ומרדכי בשם מהר\"ם וכ\"פ מהרש\"ל פ\"ה דב\"ק סי' מ' ע\"ש במהרש\"ל ובתוספת פ' כיצד הרגל ועיין בהגהות מיי' דיש ליישב דגם דברי מהר\"ם הראשונים אינם סותרים זה (והב\"י וב\"ח ומהרש\"ל לא הבינו כן) ועיין בסוף ספר שארית יוסף שכתב בכאן דברים שאינם מוכרחים:"]],["תּוֹלְדוֹת הַבּוֹר, אַבְנוֹ, סַכִּינוֹ וּמַשָּׂאוֹ וְכַיּוֹצֵא בָּהֶן, \u0010y0\u0011 שֶׁהִנִּיחָם בִּרְשׁוּת הָרַבִּים וְהִזִּיקוּ בִּמְקוֹמָם, בֵּין הִפְקִירָן אוֹ לֹא הִפְקִירָן, אוֹ שֶׁהִנִּיחָם בְּרֹאשׁ גַּגּוֹ וְנָפְלוּ בְּרוּחַ מְצוּיָה וְהִזִּיקוּ בִּמְקוֹמָם אַחַר שֶׁנָּחוּ, שֶׁדּוֹמֶה לְבוֹר מָמוֹנוֹ שֶׁמַּזִּיק בְּמָקוֹם שֶׁמֻּנָּח שָׁם, לְפִיכָךְ, יֵשׁ לוֹ כָּל דִּינֵי בּוֹר \u0010y1\u0011 לְחַיֵּב נֶזֶק שָׁלֵם מִתְּחִלָּתוֹ עַל מִיתַת בְּהֵמָה אוֹ הֶזֵּקָהּ וְעַל נִזְקֵי אָדָם, בֵּין נִתְקַל בְּאֶבֶן וְהֻזַּק בְּאֶבֶן בֵּין נִתְקַל בְּקַרְקַע וְהֻזַּק בְּאֶבֶן. אֲבָל אִם נִתְקַל בְּאֶבֶן \u0010y2\u0011 וְהֻזַּק בַּקַּרְקַע, פָּטוּר. \u0010y3\u0011 \u0005וּפָטוּר\u0006 בּוֹ מִמִּיתַת אָדָם וְנִזְקֵי כֵּלִים. וְכֵן אִם הִנִּיחָם בִּרְשׁוּתוֹ וְהִפְקִיר רְשׁוּתוֹ וְלֹא הִפְקִירָם, וְנִתְקַל בְּקַרְקַע וְנִזַּק בְּתַקָּלָה זוֹ וְהֻזַּק, חַיָּב בַּעַל הַתַּקָּלָה.\nוְאִם נָפְלוּ בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה וְהִזִּיקוּ בִּשְׁעַת נְפִילָה, אוֹ אֲפִלּוּ אַחַר נְפִילָה כָּל זְמַן שֶׁלֹּא הָיָה לוֹ פְּנַאי לְסַלְּקָם, פָּטוּר; אֲבָל לְאַחַר מִכָּאן \u0010y4\u0011 חַיָּב. וְאִי אַפְקְרִינְהוּ, פָּטוּר אֲפִלּוּ לְאַחַר מִכָּאן.\nאִם הִנִּיחָם בִּרְשׁוּת הָרַבִּים, וְלֹא הִזִּיקוּ בִּמְקוֹמָם, אֶלָּא נִתְגַלְגְּלוּ לְמָקוֹם אַחֵר \u0010y5\u0011 עַל יְדֵי רַגְלֵי אָדָם אוֹ רַגְלֵי בְּהֵמָה, אִם הִזִּיקוּ דֶרֶךְ הִלּוּכָן עַל יְדֵי רַגְלֵי אָדָם חַיָּב הַמְגַּלְגֵּל הַכֹּל, שֶׁהוּא פּוֹשֵׁעַ בְּהֶזֵּק זֶה, וּבַעַל הַתְּקָלָה פָטוּר. \u0010c0\u0011\nאִם גִּלְגְּלָם רַגְלֵי בְהֵמָה וְהִזִּיקוּ בְּהִלּוּכָם, חַיָּב בַּעַל הַבְּהֵמָה הַחֵצִי, וּבַעַל הַתַּקָּלָה הַחֵצִי.\nאִם הִתִּיזָה הַבְּהֵמָה וְהִזִּיקָה דֶרֶךְ הִלּוּכָהּ, \u0010y6\u0011 מְשַׁלֵּם בַּעַל הַבְּהֵמָה רְבִיעַ, וּבַעַל הַתַּקָּלָה שְׁלֹשָׁה חֲלָקִים.\nאִם לְאַחַר שֶׁנָּחוּ מֵגִּלְגוּלָם הִזִיקוּ, הָוָה לֵהּ בּוֹר וְחַיָּב בַּעַל הַתַּקָּלָה הַכֹּל.\nהִכְנִיס שׁוֹרוֹ לַחֲצַר חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת \u0010y7\u0011 וְהֵטִיל בּוֹ גְּלָלִים וְטִנְּפוּ כֵּלָיו שֶׁל בַּעַל הֶחָצֵר, פָּטוּר בַּעַל הַשּׁוֹר, דְּהָוָה לֵהּ הָנַךְ גְּלָלִים בּוֹר, \u0010y8\u0011 וּבוֹר פָּטוּר בְּכֵלִים, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן שֶׁקֹּדֶם זֶה:",["\u0003והזיקו במקומם. \u0004 דאז הוה דומיא דבור דהוא מונח במקומו והניזק עובר עליו משא\"כ אם הזיקו דרך הליכתן או נפילתן מן הגג דהוי תולד' דאש דמזיק דרך הלוכו לניזק העומד במקומו וכמ\"ש הטור והמחבר בסי' תי\"ח:","\u0003נזק שלם מתחלתו. \u0004 לאפוקי שור דאינו משלם נ\"ש מתחלתו עד שיגח ג\"פ:","\u0003והוזק בקרקע פטור. \u0004 דקרקע עולם הזיקתו דומה למ\"ש הטור בסי' ת\"י סכ\"ה בנתקל בבור ונפל אחורי הבור והוזק:","\u0003ופטור בו ממיתת אדם כו'. \u0004 כדין בור וכנ\"ל בסי' ת\"י ולא הפקירם דאלו הפקירם גם כן היה פטור כמ\"ש בסי' תי\"ו ס\"ו בחופר בור ברשותו ואח\"כ הפקיר בור ורשותו דסביבו ומטעם שכתבתי שם:","\u0003ואי אפקרינהו פטור. דה\"ל מפקיר נזקיו קודם שמזיקין אחר נפילת אונס דפטור:\u0004","\u0003ע\"י רגלי אדם חייב המגלגל כו' דאע\"ג דאין דרך בני אדם להתבונן בדרכים כמ\"ש בסימן ת\"י היינו לענין זה שאם שבר כלי שהוא מונח לפניו דפטור אבל כולי האי אין לו להשתגע בהליכתו שיתיז כלי ממקומו ויזיק דרך הליכתו ופושע הוא ומחייב בכולו ואם גלגל' רגלי בהמה והזיקה משלם כל אחד מחצה (כמ\"ש בסעיף שאחר זה) דומה לדליל הנקשר בתרנגול וכלב שנטל חררה ובה גחלת דחייב בעל הדליל ובעל הגחלת כל אחד מחצה וכמ\"ש בסי' ש\"ץ וטעם א' להן דהכלב והתרנגול דלשם ובהמה שבכאן לאו בני דעת נינהו אבל האדם בן דעת הוא מ\"ה הוא לבדו חייב בכולו:\u0004","\u0003משלם בעל הבהמה רביעית. דהתיז צרורות לבדו אינו משלם אלא חצי נזק וכאן דיש שותף עמו בחיוב היזקו אין עליו חוב אלא חצי דמי חיובו דהיינו רביעית והמותר על בעל התקלה מדרבי נתן:\u0004","\u0003והטיל בו גללי'. \u0004 ע\"ל סי' ש\"ץ ס\"ח דכתב אם הטילה גללים לעיסה חייב ח\"נ דה\"ל צרורות ונראה דה\"ה אם טנפה כלים דרך נפילתה (אלא שבהטילה לעיסה בעינן דדחיק' לה עלמא וכמבואר שם) משא\"כ כאן דאיירי בהזיקו אחר נפילתו:","\u0003ובור פטור בכלים. \u0004 אבל אם הוזק בו בעל החצר חייב בעל הבהמ' דה\"נ בורו ואע\"ג דכתיב כי יכרה איש בור ולא שור בור מ\"מ כיון דדידיה הוה בשעת נפילה ועליה דידיה רמיא לסלוקי ה\"ל כאלו איהו כרייה ואע\"ג דבסי' שי\"ג נתבאר בטור ובדברי המחבר דאם בהמת ראובן הטיל' גללים בחצר שמעון דזכה שמעון בהגללים שאני הכא דלא ניחא לי' לבעל החצר שיזכה חצירו דבר שיוזק על ידו אבל אם נראה דכבר ידע בעל החצר בהגללים וניחא לו בהו זוכ' לו חצירו ואח\"כ הוזק בו בעל החצר פטור בעל הבהמ' מניזקיו:"],["\u0003 אם גלגלם רגלי בהמה כו'. \u0004 וצ\"ל דגילגלו ברשות הניזק דאי בר\"ה פטורה דהא הוי תולד' דרגל וכן מצאתי ביש\"ש פ\"ק סי' ח' ודוק וא\"ל דהוי משונה והוי תולדה דקרן א\"כ לא ישלם אלא רביע כמו בהתיז' בסעיף ה' ודוחק לומר דבמועד איירי כאן וק\"ל:"]],["הַמַּנִיחַ אֶת הַכַּד בִּרְשׁוּת הָרַבִּים, וּבָא אַחֵר וְנִתְקַל בּוֹ וּשְׁבָרוֹ, פָּטוּר, שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהִתְבּוֹנֵן בַּדְּרָכִים. וְאִם הֻזַּק בּוֹ, בַּעַל הַכַּד חַיָּב וַאֲפִלּוּ הִפְקִיר הַכַּד, שֶׁכָּל הַמַּפְקִיר נְזָקָיו בְּדָבָר שֶׁאֵין לוֹ רְשׁוּת לַעֲשׂוֹת מִתְּחִלָּה, חַיָּב.\nהִנִּיחַ הַכַּד בְּמָקוֹם שֶׁיֵּשׁ לוֹ רְשׁוּת לְהַנִּיחוֹ, כְּמוֹ \u0010y0\u0011 בְּמָקוֹם פָּנוּי שֶׁלִּפְנֵי בֵּית הַבַּד, וּבָא אַחֵר וְנִתְקַל בּוֹ \u0010y1\u0011 וְשָׁבְרוֹ, חַיָּב. וְאִם הֻזַּק בּוֹ הַמְהַלֵּךְ, בַּעַל הַכַּד פָּטוּר, מִפְּנֵי שֶׁהָיָה לוֹ לְהִסְתַּכֵּל. \u0010y2\u0011 וְאִם הָיְתָה אֲפֵלָה, אוֹ שֶׁמִּלֵּא כָּל הַדֶּרֶךְ כַּדִּים, פָּטוּר עַל שְׁבִירָתָן. וְאִם נִתְקַל בָּהּ וְהֻזַּק, בַּעַל הַכַּד חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם מִלֵּא כָּל הַדֶּרֶךְ כַּדִּים שֶׁאִי אֶפְשָׁר לַעֲבֹר, אֲפִלּוּ שְׁבָרוֹ בְּיָדַיִם פָּטוּר. וּמִיהוּ, אִם בְּשָׁעָה שֶׁשִּׁבְּרָם הֻזַּק בַּחֲרָסֶיהָ, פָּטוּר, אַף עַל פִּי שֶׁזֶּה מִלֵּא כָּל הַדֶּרֶךְ, דְּאִיהוּ דְאַזִּיק אַנַּפְשֵׁהּ.\nוְדַוְקָא אָדָם אֵין דַּרְכּוֹ לְהִסְתַּכֵּל בַּדְּרָכִים; אֲבָל בְּהֵמָה שֶׁעֵינֶיהָ לְמַטָּה, דַּרְכָּהּ לְעַיֵּן אָנָה תֵּלֵךְ. לְפִיכָךְ אִם נִתְקְלָה וְהֻזְּקָה בַּכַּד הַמֻּנָּח בִּרְשׁוּת הָרַבִּים, פָּטוּר בַּעַל הַכַּד. וְאִם שִׁבַּרְתּוֹ דֶּרֶךְ \u0010y3\u0011 הִלּוּכָהּ, הָוָה לֵהּ רֶגֶל וּפָטוּר. דֶּרֶךְ \u0010y4\u0011 בִּעוּט, הָוָה לֵהּ קֶרֶן וְחַיָּב.\nמִי שֶׁהָיָה טָעוּן כַּד, וְנִתְקַל וְנִשְׁבַּר הַכַּד וְהִזִּיק לַאֲחֵרִים בִּשְׁעַת נְפִילָה, פָּטוּר, \u0010y5\u0011 דְּנִתְקָל לָאו פּוֹשֵׁעַ הוּא. \u0005(ע\"ל טוּר סִימָן ש\"ד)\u0006. לְפִיכָךְ, אִם לְאַחַר שֶׁנָּחוּ שִׁבְרֵי הַכַּד בָּאָרֶץ הֻזָּק בָּהֶם אָדָם, אוֹ שֶׁהֻחְלַק בְּמַיִם שֶׁנִּשְׁפְּכוּ מֵהַכַּד, פָּטוּר מִדִּינֵי אָדָם, \u0010y6\u0011 דְּהָוֵי לֵהּ מַפְקִיר נְזָקָיו לְאַחַר נְפִילַת אֹנֶס, וְחַיָּב בְּדִינֵי שָׁמַיִם אִם הָיָה לוֹ פְּנַאי לְסַלְּקָם. וְאִם נִתְכַּוֵּן לִזְכּוֹת בְּשִׁבְרֵי הַחֶרֶס, חַיָּב בְּנִזָּקִין שֶׁיַּזִּיקוּ אַחַר כָּךְ, דְּהַשְׁתָּא הָוָה לֵהּ בּוֹר וּפָטוּר בָּהֶם עַל הַכֵּלִים. וְאִם פָּשַׁע בִּנְפִילָתָן וְנִשְׁבַּר הַכַּד, חַיָּב עַל מַה שֶּׁיַּזִּיק, בֵּין בִּשְׁעַת נְפִילָה בֵּין עַל אַחַר שֶׁנָּחוּ הַשְּׁבָרִים, \u0010y7\u0011 אֲפִלּוּ דְאַפְקְרִינְהוּ.\nהַשּׁוֹפֵךְ מַיִם בִּרְשׁוּת הָרַבִּים וְנִטַּנְפוּ בָּהֶם כֵּלָיו שֶׁל חֲבֵרוֹ, פָּטוּר, דְּהָוָה לֵהּ בּוֹר וּפָטַר בּוֹ אֶת הַכֵּלִים, בֵּין הִפְקִירָם בֵּין לֹא הִפְקִירָם. אֲבָל אִם הֻחְלַק בָּהֶם אָדָם \u0010y8\u0011 וְנָפַל לָאָרֶץ וְהֻזַּק, חַיָּב. וְכָל שֶׁכֵּן אִם \u0010y9\u0011 נִבְלְעוּ הַמַּיִם בָּאָרֶץ וְנַעֲשׂוּ רֶפֶשׁ וְטִיט \u0010y10\u0011 וְהִזִּיקוּ, דְּהַשְׁתָּא הָוֵי לֵהּ בּוֹר מַמָּשׁ, אֲפִלּוּ אִם הוּא בִּימוֹת הַגְּשָׁמִים שֶׁיֵּשׁ רְשׁוּת לְכָל אָדָם לִפְתֹּחַ בִּיב שֶׁלּוֹ לִהְיוֹת מְקַלֵּחַ בִּרְשׁוּת הָרַבִּים, אֲפִלּוּ הָכִי אִם הִזִּיק חַיָּב לְשַׁלֵּם. וְכָל שֶׁכֵּן בִּימוֹת הַחַמָּה, דְּחַיָּב, כֵּיוָן שֶׁהוּא שֶׁלֹּא בִּרְשׁוּת, שֶׁאֵין לָאָדָם רְשׁוּת לִפְתֹּחַ לִרְשׁוּת הָרַבִּים בִּימוֹת הַחַמָּה:",["\u0003במקום הפנוי שלפני בית הבד שפעמים מניחין שם כדין כשבית הבד מלא או כיוצא בו. טור:\u0004","\u0003ושברו חייב \u0004 דאף דאין דרך בני אדם להתבונן בדרכים שאני הכא דיודע דלפעמים מניחים שם כלים וה\"ל להתבונן ולראות אם יש שם ואם היתה אפילה שלא היה יכול להתבונן ה\"ל כנתקל בכלי דשאר מקומות ופטור:","\u0003ואם היתה אפילה או שמילא כל הדרך כדים פטור כו' \u0004 כן הוא ל' הרמב\"ם בפי\"ג דנ\"מ ד\"ו. ונרא' דאף דקאמר דממלא כל הדרך כדים מ\"מ מיירי דהי' אפשר לו לסבב ולילך מן הצד או להגבי' רגליו לעבור דרך עליהן מ\"ה דוקא בנתקל בה ושברו קאמר דפטור אבל כשמילא כ\"כ עד שא\"א לעבור בזה כ' המחבר אחר זה מיד דאפי' שברה בידים וברשות פטור וכן הוא משמעות הגמרא דר\"פ המניח ורש\"י והתוס' שם ע\"ש וגם ע\"ל ס\"ס שע\"ט:","\u0003ה\"ל רגל ופטור דרגל אינו חייב אלא בחצר הניזק \u0004 כמ\"ש בסימן ש\"ץ ושצ\"א:","\u0003ה\"ל קרן וחייב. \u0004 פי' חייב ח\"נ כדין קרן:","\u0003דנתקל לאו פושע היא. כ\"כ הרי\"ף והרמב\"ם וגם הטור סתם וכתב בסי' זה כן בס\"ו ולא חילק בין נתקל במקום מדרון לבמקום שאינו מדרון אכן בר\"ס ש\"ד חילק בינייהו וכ' דנתקל במקום שאינו מדרון פושע הוא מדינא וכ\"כ בקיצור פסקי הרא\"ש בס\"פ האומנין אבל הרא\"ש ג\"כ לא הזכיר שם חילוק בין מקום מדרון לאינו מקום מדרון ועד\"ר בר\"ס ש\"ד שם הארכתי:\u0004","\u0003דה\"ל מפקיר נזקיו כו'. \u0004 דמסתמא אדם מפקיר החרסים מן הכלי שנשבר לו בדרך והמים שנשפכו ממנו להארץ:","\u0003אפילו דאפקרינהו. \u0004 דה\"ל מפקיר נזקיו אחר שהונחו במקום שלא היה להן רשות להניח כגון זה שפשע בנפילתו:","\u0003ונפל לארץ והוזק בפר שם כתבתי ל' התוס' דמוקי לה בנפל לארץ שבו המים נשפכו דה\"ל כקרקעית הבור דא\"כ קשה מ\"ש מנתקל בבור ונפל אחורי הבור דפטור כמ\"ש בסי' ת\"י ע\"ש:\u0004","\u0003נבלעו המים בארץ. \u0004 ונמחה מהן הארץ עד שנעשה רפש וטיט:","\u0003והזיקו דהשתא כו' \u0004 דוקא הזיקו הא אם מת מזה השור פטור כיון דאין כאן הבל וגם ליתא כאן חבטה דעומק עשרה טפחים וכמ\"ש בסי' ת\"י בטור ובדברי המחבר דחבטה גובה י' טפחים דוקא בעינן לתשלומי מית' ע\"ש:"],[]],["שְׁנֵי קַדָּרִים שֶׁהָיוּ מְהַלְּכִים בַּדֶּרֶךְ, זֶה אַחַר זֶה, וְנִתְקַל הָרִאשׁוֹן וְנָפַל, וְנִתְקַל הַשֵּׁנִי בָּרִאשׁוֹן, אִם הָיָה לָרִאשׁוֹן לַעֲמֹד וְלֹא עָמַד, חַיָּב הָרִאשׁוֹן בְּנִזְקֵי שֵׁנִי, שֶׁאַף עַל פִּי שֶׁהוּא אָנוּס בִּשְׁעַת נְפִילָה, אֵינוֹ אָנוּס בִּהְיוֹתוֹ מֻטָּל לַדֶּרֶךְ, וַהֲרֵי הוּא יָכוֹל לַעֲמֹד; וְאִם לֹא הָיָה לוֹ לַעֲמֹד, פָּטוּר, וְאַף עַל פִּי שֶׁלֹּא הִזְהִיר לְזֶה שֶׁנִּתְקַל בּוֹ, מִפְּנֵי שֶׁהוּא טָרוּד בְּנַפְשׁוֹ. \u0010y0\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּחַיָב אִם הָיָה לוֹ פְּנַאי לְהַזְהִירוֹ וְלֹא הִזְהִיר (טוּר ס\"א בְשֵׁם הָרֹא\"שׁ)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהוּא חַיָּב בִּנְזָקָיו שֶׁל שֵׁנִי, כְּשֶׁהֻזַּק גּוּפוֹ שֶׁל שֵׁנִי. אֲבָל אִם הֻזְּקוּ כֵלָיו, פָּטוּר, שֶׁאֵינוֹ חַיָּב עַל הַכֵּלִים בַּבּוֹר, וְכָל תַּקָּלָה תּוֹלְדוֹת בּוֹר הוּא, \u0010y1\u0011 כְּמוֹ שֶׁנִּתְבָּאֵר.\nהַקַּדָּרִים וְהַזַּגָּגִים \u0005(פֵּרוּשׁ, מוֹכְרִים כְּלֵי זְכוּכִית)\u0006 וְכַיּוֹצֵא בָּהֶם שֶׁהָיוּ מְהַלְּכִים זֶה אַחַר זֶה, וְנִתְקַל הָרִאשׁוֹן וְנָפַל, וְנִתְקַל הַשֵּׁנִי בָּרִאשׁוֹן, וְהַשְּׁלִישִׁי בַּשֵּׁנִי, וְכָל אֶחָד מֵהֶם \u0010y2\u0011 יֵשׁ לוֹ לַעֲמֹד וְלֹא עָמַד, הָרִאשׁוֹן חַיָּב בְּנִזְקֵי גוּפוֹ שֶׁל שֵׁנִי, בֵּין שֶׁהֻזַּק בְּגוּפוֹ שֶׁל רִאשׁוֹן הַמֻּטָּל לָאָרֶץ \u0010y3\u0011 בֵּין שֶׁהֻזַּק בְּמַשָּׂאוֹ. \u0010y4\u0011 \u0005וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּאִם הֻזַּק בְּמַשָּׂאוֹ אֲפִלּוּ גוּפוֹ שֶׁל שֵׁנִי, פָּטוּר (טוּר שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006. וְהַשֵּׁנִי חַיָּב בְּנִזְקֵי גוּפוֹ שֶׁל שְׁלִישִׁי, אִם הֻזַּק בְּגוּפוֹ שֶׁל שֵׁנִי; אֲבָל אִם הֻזַּק בְּמַשָּׂאוֹ שֶׁל שֵׁנִי שֶׁנָּפַל, פָּטוּר, שֶׁהֲרֵי אוֹמֵר לוֹ הַשֵּׁנִי: בּוֹר זֶה שֶׁהוּא מַשָּׂאִוֹ \u0010y5\u0011 אֵין אֲנִי הַכּוֹרֶה אוֹתוֹ, שֶׁהֲרֵי הָרִאשׁוֹן הִפִּיל הַשֵּׁנִי עִם מַשָּׂאוֹ. וְאִם הִזְהִירוּ זֶה אֶת זֶה, כֻּלָּם פְּטוּרִין.\nנָפַל הָרִאשׁוֹן וְהָיָה מֻטָּל לְרֹחַב הַדֶּרֶךְ, וְנִתְקַל אֶחָד בְּרֹאשׁוֹ וְאֶחָד בְּרַגְלָיו וְאֶחָד בְּבִטְנוֹ, הֲרֵי הוּא חַיָּב בְּנִזְקֵי כֻלָּם הוֹאִיל וְהָיָה לוֹ לַעֲמֹד וְלֹא עָמַד. \u0005הַגָּה: \u0010y6\u0011 וְיֵשׁ אוֹמְרִים דְּדַוְקָא אִם מֻנָּח הָרִאשׁוֹן בַּאֲלַכְסוֹן (טוּר שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006.",["\u0003וי\"א דחייב אם היה לו פנאי להזהירו ולא הזהיר. \u0004 הוא דעת הטור שכ\"כ בשם הרא\"ש בר\"ס זה ובדריש' כתבתי כאן בסי' שע\"ט דהרא\"ש משו' דין זה לדין אחד הולך בקורה ורשני בא אחריו בחביתו ונשבר החביות בהקור' דתנן בפ' המניח דאם עמד בעל הקור' בדרך עם קורתו דחייב בעל הקורה בשבירת חביתו ומפרש' דמיירי אפילו בעומד לתקן משאו ולא אמרי' דה\"ה טרוד במשאו מלהזהירו לבעל החביות ע\"ש ולא כהרי\"ף דמפרש להמשנה דמיירי דוקא בעומד לנוח וא\"כ ק' על הטור וגם על מור\"ם שבסימן שע\"ט סתמו כדברי הרי\"ף דבעמד כדי לתקן משאו פטור על שבירת החביות וכאן כתב הדברים בפלוגתא וכתבתי דצ\"ל הטור וגם מור\"ם ס\"ל דטרדת דבעל הקורה לתקן משאו היא גדולה יותר מאשר הוא טרוד הקדר והדומה לו שנפלו ושס\"ל שגם הרא\"ש אפשר דמודה לפי המסקנא לחלק בינייהו ושהמשנ' מיירי דוקא בעומד לנוח ועד\"ר בסי' שע\"ט שכתבתי מילתא בטעמא:","\u0003כמו שנתבאר \u0004 ר\"ל בסי' תי\"א ותי\"ב וזהו דעת הרמב\"ם והרא\"ש אבל הטו' כתב שדעת הרי\"ף הוא דגופו של ראשון שהיה יכול לעמוד ולא עמד מחשב כאדם המזיק בפשיעה ופושע חייב אפילו על כלים ויש בו נ\"מ לדינא גם למ\"ש בסעיף שאחד זה ועד\"ר שם הארכתי בפירושים ע\"פ סוגית הגמרא וע\"ש:","\u0003יש לו לעמוד ולא עמד \u0004 ולהי\"א הנ\"ל אף אם לא היה יכול לעמוד רק שהיה יכול להזהיר להבא אחריו ולא הזהיר וכ\"כ בטור ע\"ש:","\u0003בין שהוזק במשאו. \u0004 היינו הקדרי' והזגגים שנשאו ונפלו בדרך:","\u0003ויש חולקין כו' \u0004 לפי מה שנדפס ההג\"ה זו ומסודרת לפנינו היה נ\"ל להגיה וצ\"ל ויש חולקין וס\"ל דאפילו אם הוזק במשאו של ראשון גופו כו' וקאי האפילו אמ\"ש אם הוזק במשאו של שני פטור והי\"א ס\"ל דאף בשל ראשון פטור אבל שוב מצאתי בהגהות דמור\"ם הנכתבי' בכתיבת ידו שמסודרת החי הג\"ה לפני זה אמ\"ש דהראשון חייב בנזקי גופו של שני בין שהוזק בגופו של ראשון בין שהוזק במשאו אזה קאי הג\"ה דיש חולקין וס\"ל דדוקא אם הוזק גופו של שני בגופו של ראשון הוא דחייב הראשון ולא כשהזיק במשאו והוא דעת הרא\"ש וטעמו כיון דקי\"ל דנתקל לאו פושע הוא דיינו אם ניתן על גופו תורת בור ולא על משאו:","\u0003אין אני הכורה כו'. \u0004 אבל מה שהוזק מגופו חייב כיון דמ\"מ היה יכול לעמוד עם משאו ועד\"ר:","\u0003וי\"א דדוקא אם מונח הראשון באלכסון \u0004 הטעם דהיה לו להראשון ליזהר כשבא וראה שהשני נתקל בהראשון אבל כשמונח באלכסון כשנתקל השני בראשו של הראשון אותו שבא אח\"כ ונתקל ברגל דהראשון י\"ל דלא ראה השני מוטל לפניו ועד\"ז נמי כשנתקל עוד א' בהראשון בבואו לבטנו י\"ל דלא ראה לפניו לא זה שנתקל בראש דהראשון ולא זה שנתקל ברגלי דהראשון וק\"ל:"],[]],["לֹא יוֹצִיא אָדָם תִּבְנוּ וְקַשּׁוֹ לִרְשׁוּת הָרַבִּים כְּדֵי שֶׁיִּדֹּשׁוּ וְיַעֲשׂוּ זֶבֶל; וְאִם הוֹצִיאָם, קְנָסוּהוּ חֲכָמִים שֶׁיִּהְיוּ כְּהֶפְקֵר וְכָל הַקּוֹדֵם בָּהֶם זָכָה \u0010y0\u0011 מֵעֵת שֶׁנִּדּוֹשׁוּ וְהִשְׁבִּיחוּ. \u0005מִיהוּ יֵשׁ אוֹמְרִים, דְּאֵין מוֹרִין לוֹ לְכַתְּחִלָּה לְהַחֲזִיק רַק בַּשֶּׁבַח, אֲבָל לֹא בְּגוּפוֹ; וְאִם הִתְרוּ בַּבְּעָלִים וְלֹא סִלְּקוּ, מַפְקִירִין אוֹתוֹ לַכֹּל (טוּר ס\"ד)\u0006. וְאִם קָדַם אָדָם וְזָכָה בָּהֶם מִשְּׁעַת הוֹצָאָה לִרְשׁוּת הָרַבִּים, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005וְיֵשׁ אוֹמְרִים דְּלָא מְהַנֵּי תְּפִיסָה (ר\"י וְרֹא\"שׁ וְטוּר שָׁם)\u0006 וְע\"ל סִימָן שפ\"ח. וְאַף עַל פִּי שֶׁהֵם כְּהֶפְקֵר, אִם הֻזַּק בָּהֶם אָדָם אוֹ בְּהֵמָה, \u0010y1\u0011 הֲרֵי זֶה הַמּוֹצִיא חַיָּב לְשַׁלֵּם. \u0010y2\u0011\nיֵשׁ לְכָל אָדָם לְהוֹצִיא אֶת הַזֶּבֶל וְהַגְּלָלִים לִרְשׁוּת הָרַבִּים בִּשְׁעַת הוֹצָאַת זְבָלִים, \u0005אֲבָל שֶׁלֹּא בִּשְׁעַת הוֹצָאַת זְבָלִים אָסוּר לְהוֹצִיאוֹ כְּדֵי לְהַנִּיחוֹ שָׁם, אֲבָל מוֹצִיאוֹ כְּדֵי לְפַנּוֹתוֹ לְאַלְתַּר (טוּר ס\"א)\u0006, וְכָל שֶׁכֵּן מַיִם נְקִיִּים וְשׁוֹפְכִין שֶׁלּוֹ \u0010y3\u0011 שֶׁאֵין שׁוֹהִין וּמִתְעַכְּבִים בִּרְשׁוּת הָרַבִּים, שֶׁמֻּתָּר לְשָׁפְכָן אֲפִלּוּ בִּימוֹת הַחַמָּה; וַאֲפִלּוּ מַיִם סְרוּחִין, כָּל שֶׁדַּעְתּוֹ לְפַנּוֹתוֹ לְאַלְתַּר. וַאֲפִלּוּ מְתַקֵּן בּוֹר פָּחוֹת מִשְּׁלֹשָׁה טְפָחִים אֵין בְּנֵי רְשׁוּת הָרַבִּים יְכוֹלִים לְעַכֵּב \u0005(מָרְדְּכַי סוֹף ב\"מ בְּשֵׁם מַהֲרַ\"מ)\u0006, וְלִצְבֹּר אוֹתָם שָׁם שְׁלֹשִׁים יוֹם, \u0010y4\u0011 כְּדֵי שֶׁיִּהְיֶה נִשֹּׁף בְּרַגְלֵי אָדָם; \u0010y5\u0011 וְאַף עַל פִּי כֵן אִם הִזִּיק חַיָּב לְשַׁלֵּם. וְחַיָּבִים עַל זֶה הַגָּלָל מִשּׁוּם גָּזֵל, כֵּיוָן שֶׁאֵין בּוֹ שֶׁבַח אִם נִדֹּשׁ, לֹא קָנְסוּ בּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דִּלְאַחַר שֶׁהֻזַּק, כָּל הַקּוֹדֵם בָּהֶם זָכָה (טוּר ס\"ב)\u0006.",["\u0003מעת שנידושו והשביחו. \u0004 בגמרא קאמר דקנסו גופו של תבן לעשותו כהפקר משום שבחו כדי שלא יעברו ויוציאו לר\"ה להשביחו לעשות ממנו זבל וקמבעיא בגמרא אם לא גזרו על גופו להפקירו עד שעה שכבר השביח דאז שייך טפי לומר שגזרו גופו משום שבחו או דילמא גם קודם שהשביח ונעשה זבל קנסו להיות גופו של הזוכה כדי שלא יוציאו ולא איפשיטא והמחבר סתם וכתב כדעת הרמב\"ם שנתבאר לעיל כמה פעמים בטור וגם בסי' זה בשמו דס\"ל דמהני תפיס' לספיקא דדינא ומש\"ה כ' אחר זה ז\"ל ואם קדם אדם כו' אין מוציאין מידו ומור\"ם כ' עליו די\"א (והוא דעת ר\"י והרא\"ש) דלא מהני כו':","\u0003הרי זה המוציא חייב לשלם \u0004 דכיון דממונו היא ס\"ל כמפקיר נזקיו אחר הנחתו במקום שלא היה לו רשות להניחו דחייב כמ\"ש בסימנים שלפני זה:","\u0003יש לכל אדם להוציא את הזבל כו'. \u0004 דזבל אינו מזיק כ\"כ כמו קש שהוא מחליק וגם הוא ארוך ונופלים ע\"י בקל:","\u0003שאין שוהין ומתעכבין \u0004 פי' אלא נוזלין ויוצאין מעצמם מיד לאחר שפיכתן מאותו מקום ויתפזרו ואין מזיקין:","\u0003כדי שיהא נישוף. \u0004 בגמרא קאמר הטעם דע\"מ כן הנחיל יהושע את הארץ לישראל שלא יקפדו בזה זה על זה וע\"ל סי' רע\"ד דשם כ' הטור שהרי\"ף חולק ע\"ז:","\u0003ואעפ\"כ אם הזיק חייב. \u0004 דיהושע לא התנ' שיהא פטור מתשלומי היזיקו ואעפ\"כ צריכין לתנאי דיהושע דאל\"כ היו מוחין דלא ניחא ליה לאדם שיהא ניזק בשלו ואח\"כ ישתלם הזיקו וגם יצטרך לירד עמו בדינא ודיינא ולא כע\"ש שכ' שיהושע לא התנה אלא ע\"מ שיהא כ\"א משמר את זבלו ע\"ש וזה ודאי אינו אלא אף אם אינו משמרו כו' רק שיהא צריך לשלם הזיקו:"],[]],["הַמַּצְנִיעַ אֶת הַקּוֹץ וְאֶת הַזְּכוּכִית, וְהַגּוֹדֵר גִּדְרוֹ בְּקוֹצִים \u0010y0\u0011 וְהִפְרִיחוּ לִרְשׁוּת הָרַבִּים וְהֻזַּק בָּהֶם אַחֵר, חַיָּב נֶזֶק שָׁלֵם. וְאִם גָּדַר בְּקוֹצִים \u0010y1\u0011 בְּצִמְצוּם בְּתוֹךְ רְשׁוּתוֹ, פָּטוּר, לְפִי \u0010y2\u0011 שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהִתְחַכֵּךְ בַּכְּתָלִים.\nהַמַּצְנִיעַ קוֹצָיו וּזְכוּכִיּוֹתָיו בְּתוֹךְ כָּתְלוֹ שֶׁל חֲבֵרוֹ, וּבָא בַּעַל הַכֹּתֶל וְסָתַר כָּתְלוֹ וְנָפַל לִרְשׁוּת הָרַבִּים וְהִזִּיק, אִם כֹּתֶל רָעוּעַ הוּא, הַמַּצְנִיעַ חַיָּב; וְאִם כֹּתֶל בָּרִיא הוּא, בַּעַל הַכֹּתֶל חַיָּב. \u0005הַגָּה: וְאִם הִזִּיקוּ בִּשְׁעַת נְפִילָה, \u0010y3\u0011 יֵשׁ אוֹמְרִים דְּבַעַל כֹּתֶל חַיָּב בְּכָל עִנְיָן (טוּר ס\"ב)\u0006. וְאִם נָפַל הַכֹּתֶל מֵאֵלָיו, אִם הָיָה בָרִיא פְּטוּרִים; וְאִם הָיָה רָעוּעַ, הַמַּצְנִיעַ חַיָּב. וְאִם סְתָרוֹ אִינַשׁ דְּעָלְמָא, הַסּוֹתֵר חַיָּב וְהַמַּצְנִיעַ פָּטוּר \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַמַּנִּיחַ)\u0006. וְעַיֵּן לְעֵיל סִימָן שצ\"ו. \u0010y4\u0011\nמִדַּת חֲסִידוּת הוּא שֶׁיַּצְנִיעַ אָדָם קוֹצָיו וּשְׁאָר כָּל דָּבָר הַמַּזִּיק בְּמָקוֹם שֶׁלֹּא יָבֹא מֵהֶם תַּקָּלָה, כְּגוֹן שֶׁיַּשְׁלִיכֵם לַנָּהָר אוֹ יִשְׂרְפֵם:",["\u0003והפריחו לר\"ה. \u0004 ל' הטור והוציאן לר\"ה אפי' מעט:","\u0003בצמצום בתוך רשותו \u0004 פי' שלא הוציאם כלל לר\"ה אפי' יצאו ובולטין מן הכותל כל שהן ברשותו:","\u0003שאין דרך בני אדם. \u0004 פי' ההולכים לר\"ה:","\u0003דבעל הכותל חייב בכל ענין. \u0004 פי' אפי' הכותל רעוע דכיון דסתרו \"בידים ה\"ל כאדם הנוטל זכוכיתו של חבירו ומזיק בו לאחר דמזיק חייב (מה\"ט נמי מסיק וכ' דאם סתרה אינש דעלמא הסותר חייב) ומה\"ט דוקא אם סתר הכותל בידים הא נפלה מאליו והיית' רעוע המצניע חייב וכדמסיק:","\u0003מדת חסידות כו'. \u0004 ועל כיוצא בזה אמרו בפרק המניח האי מאן דבעי למהוי חסידא לקיים מילי דניזקין וע\"ל ר\"ס שע\"ח כתבתי ל' הנ\"י בזה ועפ\"ר:"],[]],["הַכֹּתֶל וְהָאִילָן שֶׁנָּפְלוּ לִרְשׁוּת הָרַבִּים וְהִזִּיקוּ, פָּטוּר מִלְּשַׁלֵּם, \u0010y0\u0011 וְאַף עַל פִּי שֶׁהִפְקִירָם; לְפִי שֶׁאֵינָם דּוֹמִים לְבוֹר, שֶׁהֲרֵי אֵין תְּחִלָּתָן לְהַזִּיק. \u0005וְיֵשׁ אוֹמְרִים דְּאִם הָיָה לוֹ פְּנַאי לְסַלְּקָן וְלֹא הִפְקִירָן, חַיָּב (טוּר ס\"א)\u0006. וְאִם הָיוּ רְעוּעִין, בֵּית דִּין קוֹבְעִים לוֹ זְמַן \u0005וְדַוְקָא שֶׁהִתְרוּ בוֹ בֵּית דִּין, אֲבָל בְּלֹא בֵּית דִּין אַף עַל פִּי שֶׁהִתְרוּ בּוֹ חֲבֵרָיו אֵינוֹ כְּלוּם; מִיהוּ, אִם חָפַר בַּכֹּתֶל וְגָרַם לְהַפִּילוֹ, חַיָּב בְּנִזָּקִין דְּהָוָה לֵהּ חִצָּיו מַמָּשׁ (בֵּית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006, לָקֹץ אֶת הָאִילָן וְלִסְתֹּר אֶת הַכֹּתֶל. וְכַמָּה הַזְּמָן, ל' יוֹם. \u0005וְאִם הַדָּבָר נָחוּץ וְיֵשׁ לָחוּשׁ שֶׁיַּזִּיק לַאֲחֵרִים, אֵין נוֹתְנִין לוֹ זְמַן רַק כּוֹפִין אוֹתוֹ לְסַלֵּק הֶזֵּיקוֹ מִיָּד (בֵּית יוֹסֵף בְּשֵׁם רִיטְבָ\"א)\u0006. נָפְלוּ בְּתוֹךְ הַזְּמַן, פָּטוּר; \u0010y1\u0011 לְאַחַר הַזְּמַן חַיָּב, מִפְּנֵי שֶׁהִשְׁהָה אוֹתָם. \u0005הַגָּה: וְכָל זֶה כְּשֶׁבְּנָאָהּ מִתְּחִלָּתוֹ כָּרָאוּי, אֲבָל אִם לֹא בְנָאָהּ כָּרָאוּי וּמֵחֲמַת זֶה נָפַל הַכֹּתֶל, חַיָּב בְּנִזְקָה (תוס' הַמַּגִּיד פי\"ג דְּנִזְקֵי מָמוֹן וּבֵית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם נל\"א ח\"א)\u0006.",["\u0003ואע\"פ שהפקירם. \u0004 לכאורה היה נראה להגיה שלא הפקירם דכיון שאין מונחין בר\"ה והן שלו עדיין שלא הפקירן והזיקו יש סברא להשתלם ממנו טפימשהפקירן והזיקו וכמ\"ש מור\"ם ג\"כ בהג\"ה ע\"ז ז\"ל ולא הפקירן חייב ולפי הגירסא שלפנינו צריך לומר דה\"ק אע\"פ שהפקירן ויש רשות לכל אדם לעבור דרך עליו ויזוקו בו אפ\"ה פטור מטעם שהרי כו':","\u0003לאחר הזמן חייב. \u0004 לשון הטור לאחר הזמן והזיקו בין בשעת נפילה בין לאחר נפילה יש להן דין בור כו' וכ\"כ הרא\"ש וכתב עוד הרא\"ש ז\"ל ול\"ד לאבנו סכינו ומשאו שהניחו בראש גגו ונפלו ברוח מצויה והזיקו בשעת נפילה דיש להן דין אש דהנך נעשו אש ע\"י כח אחרים (דהיינו ברוח שהפילם) אבל כותל ואילן מחמת עצמן מריעותא נפלו כי ראו שלא היו יכולין לעמוד יותר והזהירו ב\"ד עליהן להפילן ואי משום דהולכים ומזיקין ואינו דומה לבור לא גריע מחמת זה וכ\"ש דיש לחייבו יותר מידי דהוי אקושר אבן ברגל בהמתו והלכה לר\"ה והזיקו ואי משום דאין תחלת עשייתן להזיק שור יוכיח עכ\"ל הרא\"ש שם:"],[]],["לֹא יְסַקֵּל אָדָם מֵרְשׁוּתוֹ לִרְשׁוּת הָרַבִּים. וְאֵין עוֹשִׂין חָלָל \u0010y0\u0011 תַּחַת רְשׁוּת הָרַבִּים, וְלֹא בּוֹרוֹת וְלֹא שִׁיחִין וְלֹא מְעָרוֹת, וְאַף עַל פִּי שֶׁהָעֲגָלָה יְכוֹלָה לְהַלֵּךְ עַל גַּבֵּיהֶן וְהִיא טְעוּנָה אֲבָנִים, \u0010y1\u0011 שֶׁמָּא תִפָּתַח מִלְּמַטָּה שֶׁלֹּא מִדַּעְתּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאַף עַל גַּב דְּהָכִי דִינָא הוּא, מִכָּל מָקוֹם כְּבָר נָהֲגוּ לַעֲשׂוֹת בִּיבִין וּמַרְתְּפוֹת תַּחַת חֲלַל רְשׁוּת הָרַבִּים, וְכֵן זִיזִין, \u0010y2\u0011 וְכֻלָּן מוֹחֲלִין עַל כָּךְ מֵאַחַר שֶׁכֵּן נָהֲגוּ. וְעוֹד, שֶׁרְשׁוּיוֹת הָרַבִּים הֵם \u0010y3\u0011 שֶׁל מוֹשְׁלֵי הָעִיר, וּלְכָל מַה שֶּׁנּוֹתְנִין רְשׁוּת אָזְלֵינָן בַּתְרֵהּ וּלְפִי עִנְיָן הַמִּנְהָג (בֵּית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006. וְהַחוֹפֵר בּוֹר לְצָרְכֵי רַבִּים, \u0010y4\u0011 \u0010c0\u0011 מֻתָּר:\nאֵין מוֹצִיאִין זִיזִין וּגְזֻזְטְרָאוֹת לִרְשׁוּת הָרַבִּים, אֶלָּא אִם כֵּן הָיוּ לְמַעְלָה מִגָּמָל וְרוֹכְבוֹ, וְהוּא שֶׁלֹּא יַאֲפִיל הַדֶּרֶךְ עַל גַּבֵּי רְשׁוּת הָרַבִּים. וְאִם רָצָה, כּוֹנֵס לְתוֹךְ שֶׁלּוֹ וּמוֹצִיאוֹ. כָּנַס וְלֹא הוֹצִיא, הֲרֵי זֶה מוֹצִיא כָּל זְמַן שֶׁיִּרְצֶה, אֲבָל אֵינוֹ יָכוֹל לְהַחֲזִיר הַכְּתָלִים לִמְקוֹמָם לְעוֹלָם, שֶׁכָּל מֶצֶר שֶׁהֶחֱזִיקוּ בּוֹ רַבִּים אָסוּר לְקַלְקְלוֹ. \u0005הַגָּה: וְדַוְקָא בְּמָקוֹם שֶׁרַבִּים דּוֹרְסִים בּוֹ, אֲבָל אִם אֵין דּוֹרְסִים שָׁם, כְּגוֹן שֶׁבָּנָה שָׁם אִצְטַבָּא, אַף עַל גַּב דְּרַבִּים מַעֲבִירִים שָׁם מַשָּׂאָם, יָכוֹל לְהַחֲזִיר הַכֹּתֶל לִמְקוֹמוֹ (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006.\nלָקַח חָצֵר וּבָהּ זִיזִין וּגְזֻזְטְרָאוֹת יוֹצְאוֹת \u0010y5\u0011 לִרְשׁוּת הָרַבִּים, הֲרֵי זוֹ בְּחֶזְקָתָהּ, וְאִם נָפְלָה, חוֹזֵר וּבוֹנֶה אוֹתָהּ כְּשֶׁהָיְתָה.\nאִילָן שֶׁהוּא נוֹטֶה לִרְשׁוּת הָרַבִּים, קוֹצֵץ, כְּדֵי שֶׁיְּהֵא הַגָּמָל עוֹבֵר בְּרוֹכְבוֹ. וּמַנִּיחִים מָקוֹם פָּנוּי מִשְׁתֵּי שִׂפְתוֹת הַנָּהָר כְּרֹחַב כִּתְפֵי הַמַּלָחִים שֶׁיּוֹרְדִים שָׁם וּמוֹשְׁכִים הַסְפִינָה, וְכָל אִילָן הַנִּמְצָא בְּרֹחַב זֶה קוֹצְצִין אוֹתוֹ מִיָּד וְאֵין מַתְרִין בַּבְּעָלִים, שֶׁהֲרֵי מְעַכֵּב מוֹשְׁכֵי הַסְפִינָה.\nאֵין שׁוֹרִין טִיט בִּרְשׁוּת הָרַבִּים לְהַשְׁהוֹתוֹ זְמַן רַב, וְאֵין לוֹבְנִים בּוֹ לְבֵנִים; אֲבָל גּוֹבְלִים שָׁם טִיט לְצֹרֶךְ בִּנְיָן, אֲבָל לֹא לַעֲשׂוֹת לְבֵנִים.\nהַבּוֹנֶה בִּרְשׁוּת הָרַבִּים, כְּשֶׁמֵּכִין הָאֲבָנִים צָרִיךְ שֶׁלֹּא יַשְׁהֵם שָׁם, אֶלָּא מֵבִיא וּבוֹנֶה מִיָּד.\nוְכֻלָּם שֶׁהִזִּיקוּ, חַיָּבִים לְשַׁלֵּם נֶזֶק שָׁלֵם.",["\u0003תחת רשות הרבים ולא בורות שיחין כו' \u0004 וכן הוא ל' הרמב\"ם והטור דכתבו \"ולא בורות כו' בוי\"ו ומשמע דתרתי דברים נינהו חלל ובורות ואפשר משום דבורות מיירי שהן מגולין ועומדין וכן אינך שיכולין בני ר\"ה ליזהר מהן ואפ\"ה אסור אבל במשנה קתני לא בורות בלא וי\"ו ופי' רשב\"ם שם דחדא הוא דקתני חלל והדר מפרש דהיינו בורות שיחין כו' וכן משמע מדמסיק ותני עלייהו אף ע\"פ שהעגלה יכולה לילך ע\"ג כו' מוכח דמבוסות הן ועפ\"ר:","\u0003שמא תפחת מלמט' שלא מדעתו \u0004 ולא סגי במה שמקבל עליו אחריות היזקן דהעוברים עליו דניחא לבני אדם בשלהן ולא שיזיקו בשלהן ולקבל עליו תשלומין וחילופיהן וגם לא ניחא להו לירד בדינא ודיינא וכמ\"ש לעיל:","\u0003וכולן מוחלין על כך \u0004 שהיום או מחר יצטרך גם הוא או בניו לעשות כן:","\u0003של מושלי העיר \u0004 פי' של שר העיר ז\"ל הרשב\"א שהדבר ידוע שהדרכים עם היותם מסורים לרבים של אדוני הארץ הם והם רשאים לסתום דרכים ולפתחן במקום אחר לפי שהדרכי' שלהם הן והרי זה ככונס לתוך שלו על דעת שיוציא זיזין ומחילות לכשירצה עכ\"ל ועד\"מ:","\u0003אין מוציאין זיזין כו' לר\"ה \u0004 ל' הטור אבל במבוי יכול להוציאן מדע' בני המבוי משא\"כ בר\"ה שאין לו בעלים וכתב ר\"י דהאי מבוי ר\"ל שאיני מפולש דאם הוא מפולש שרבים עוברים שם דינו כר\"ה הביאו הב\"י ומהתימה למה השמיטו המחבר:","\u0003ה\"ז בחזקתו דטוענין ללוקח ואמרינן דשמא המוכר לו או אבותיו כונס לתוך שלו היה וכנ\"ל:\u0004"],["\u0003 אין מוציאין זיזין כו'. \u0004 עיין בתשובות מהרי\"ט סימן ק\"ח:"]],["אֵשׁ הוּא אָב, \u0010y0\u0011 דִּכְתִיב: כִּי תֵצֵא אֵשׁ וּמָצְאָה קוֹצִים \u0005(שְׁמוֹת כב, ה)\u0006 ; וְהוּא מָמוֹנוֹ שֶׁהוֹלֵךְ לְמֵרָחוֹק וּמַזִּיק עַל יְדֵי הָרוּחַ שֶׁמּוֹלִיכוֹ. לְפִיכָךְ, כָּל הַדּוֹמֶה לוֹ, שֶׁהוּא מָמוֹנוֹ וְהוֹלֵךְ וּמַזִּיק, הוּא תוֹלַדְתּוֹ וְיֵשׁ לוֹ דִּין לִפְטֹר בּוֹ טָמוּן.\nכְּתִיב: כִּי תֵצֵא אֵשׁ \u0005(שְׁמוֹת כב, ה)\u0006 ; אֲפִלּוּ מֵעַצְמָהּ, שֶׁהִדְלִיק בְּתוֹךְ שֶׁלּוֹ וְהָלַךְ וְדָלַק בְּתוֹךְ שֶׁל \u0010y1\u0011 חֲבֵרוֹ. אֲפִלּוּ לֹא שָׂרְפָה אֶלָּא עֵצָיו וַאֲבָנָיו, אוֹ שֶׁלִּחֲכָה נִירוֹ, חַיָּב לְשַׁלֵּם הַכֹּל, אֶלָּא אִם כֵּן הִרְחִיק כְּשִׁעוּר; אֲבָל אִם הִרְחִיק \u0010c0\u0011 כְּשִׁעוּר וְיָצָא וְהִזִּיק, פָּטוּר. \u0005הַגָּה: וְכָל זֶה בְּמַדְלִיק בְּתוֹךְ שֶׁלּוֹ; \u0010y2\u0011 אֲבָל בְּמַדְלִיק בְּתוֹךְ חֲבֵרוֹ, אֲפִלּוּ עָבְרָה כַּמָּה מִילִין, חַיָּב (טוּר ס\"א)\u0006.\nוְכַמָּה שִׁעוּר הַהַרְחָקָה, הַכֹּל לְפִי \u0010c1\u0011 גֹבַהּ הַדְּלֵקָה. וְאִם לֹא הִרְחִיק כָּרָאוּי, וְעָבְרָה הָאֵשׁ וְהִזִּיקָה, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם:\nהִרְחִיק כָּרָאוּי, וְעָבְרָה וְהִזִּיקָה, פָּטוּר, \u0010y3\u0011 שֶׁזּוֹ מַכָּה בִּידֵי שָׁמַיִם הִיא. וְכֵן אִם עָבְרָה נָהָר אוֹ שְׁלוּלִית שֶׁיֵּשׁ בָּהֶם מַיִם, \u0010y4\u0011 וְרָחְבָּם שְׁמֹנֶה אַמּוֹת, פָּטוּר. \u0005וְיֵשׁ אוֹמְרִים דְּאִם הַנָּהָר \u0010c2\u0011 רָחָב שְׁמֹנֶה אַמּוֹת, אֲפִלּוּ אֵין בּוֹ מַיִם; וְהַיְאוֹר, אֲפִלּוּ כָּל שֶׁהוּא וְיֵשׁ בּוֹ מַיִם פָּטוּר (טוּר ס\"א)\u0006. עָבְרָה גָדֵר, אוֹמְדִים גֹּבַהּ הַגָּדֵר וְגֹבַהּ הַדְּלֵקָה וְהָעֵצִים וְהַקּוֹצִים הַמְּצוּיִים שָׁם, אִם אֵינָהּ רְאוּיָה לַעֲבֹר, פָּטוּר; וְאִם רְאוּיָה \u0010y5\u0011 לַעֲבֹר, חַיָּב.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בָּאֵשׁ הַקּוֹדַחַת. אֲבָל אִם הָיָה לַהַב גָּדוֹל הָעוֹלֶה וְנִכְפָּף מִגֹּבַהּ עֲלִיַּת הַלַּהַב, וְהָיוּ עֵצִים מְצוּיִים שָׁם, אֵין לָהּ אֹמֶד, אֶלָּא אֲפִלּוּ עָבְרָה אֶלֶף אַמָּה, חַיָּב.\nנָפְלָה דְלֵקָה בַּחֲצֵרוֹ, וְנָפַל גָּדֵר שֶׁלֹּא מֵחֲמַת הַדְּלֵקָה, וְעָבְרָה הַדְּלֵקָה בְּחָצֵר אַחֶרֶת, אִם הָיָה יָכוֹל לִגְדֹּר הַגָּדֵר שֶׁנָּפַל וְלֹא גְּדָרוֹ, חַיָּב; לְמָה הַדָּבָר דּוֹמֶה, לְשׁוֹרוֹ שֶׁיָּצָא וְהִזִּיק, שֶׁהָיָה לוֹ לְשָׁמְרוֹ וְלֹא שְׁמָרוֹ.\nהַשּׁוֹלֵחַ אֶת הַבְּעֵרָה בְּיַד חֵרֵשׁ שׁוֹטֶה וְקָטָן, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁמָּסַר לָהֶם גַּחֶלֶת וְלִבּוּהָ \u0005(פֵּרוּשׁ, מֵעִנְּיַן לַבַּת אֵשׁ)\u0006 \u0005(שְׁמוֹת ג, ב)\u0006, שֶׁדֶּרֶךְ הַגַּחֶלֶת לְהִכָּבוֹת מֵאֵלֶיהָ קֹדֶם שֶׁתַּעֲבֹר וְתַדְלִיק, אֲבָל אִם מָסַר לָהֶם שַׁלְהֶבֶת, חַיָּב, שֶׁהֲרֵי מַעֲשָׂיו גָּרְמוּ.\nשָׁלַח הַבְּעֵרָה בְּיַד הַפִּקֵּחַ, זֶה שֶׁהִבְעִיר חַיָּב לְשַׁלֵּם; וְהַשּׁוֹלֵחַ פָּטוּר. \u0010y6\u0011 וְכֵן אִם הִנִּיחַ שׁוֹמֵר לִשְׁמֹר הַבְּעֵרָה, הַשּׁוֹמֵר חַיָּב:\nאֶחָד הֵבִיא אֶת הָאוּר, וְאֶחָד הֵבִיא אֶת \u0010y7\u0011 הָעֵצִים, הַמֵּבִיא אֶת הָעֵצִים חַיָּב. אֶחָד הֵבִיא אֶת הָעֵצִים וְאֶחָד הֵבִיא אֶת הָאוּר, הַמֵּבִיא אֶת הָאוּר חַיָּב. בָּא אַחֵר וְלִבָּה, הַמְלַבֶּה \u0010y8\u0011 חַיָּב. לִבָּתוֹ רוּחַ שֶׁאֵינָהּ מְצוּיָה תָמִיד, הֲרֵי כֻּלָּם פְּטוּרִים. \u0005וְאִם הָרוּחַ מְצוּיָה, הָאַחֲרוֹן חַיָּב (טוּר ס\"ד)\u0006. וְכֵן אִם הָיָה הָרוּחַ שֶׁאֵינָהּ מְצוּיָה, מְנַשֵּׁב בְּשָׁעָה שֶׁבָּא הָאַחֲרוֹן לְשָׁם, הָאַחֲרוֹן חַיָּב \u0005(הַמַּגִּיד פי\"ד \u0010c3\u0011 דְנ\"מ)\u0006. לִבָּה וְלִבָּתוֹ הָרוּחַ, חַיָּב. \u0005הַגָּה: \u0010y9\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין הַמְלַבֶּה חַיָּב אֶלָּא כְּשֶׁיֵּשׁ בַּלִּבּוּי שֶׁלּוֹ כְּדֵי לְלַבּוֹת, וְאֵין בָּרוּחַ לְבַד כְּדֵי לְלַבּוֹת. אֲבָל אֵין בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, אוֹ שֶׁיֵּשׁ בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, פָּטוּר (טוּר שָׁם ובֵית יוֹסֵף בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006. וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין אִם שְׁנַיִם לִבּוּ וְאֵין בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, פְּטוּרִין \u0005(מָרְדְּכַי פֶּרֶק הַכּוֹנֵס)\u0006.\nעָשָׂה הָאֶחָד הָאֵשׁ, וּבָא אַחֵר וְהוֹסִיף, אִם יֵשׁ בַּמֶּה שֶׁעָשָׂה הָרִאשׁוֹן כְּדֵי שֶׁתַּגִּיעַ לַמָּקוֹם שֶׁהָלְכָה, הָרִאשׁוֹן חַיָּב; וְאִם לָאו, הָרִאשׁוֹן פָּטוּר וְהָאַחֲרוֹן חַיָּב.\nהַכּוֹפֵף קָמָתוֹ שֶׁל חֲבֵרוֹ לִפְנֵי הַדְּלֵקָה, כְּדֵי שֶׁתַּגִּיעַ בָּהּ הַדְּלֵקָה, אִם כְּפָפָהּ בְּמָקוֹם שֶׁתּוּכַל הַדְּלֵקָה לְהַגִּיעַ בְּרוּחַ מְצוּיָה, חַיָּב לְשַׁלֵּם; וְאִם אֵינָהּ יְכוֹלָה לְהַגִּיעַ בְּרוּחַ מְצוּיָה, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0005וְאִם הָרוּחַ שֶׁאֵינָהּ מְצוּיָה כְּבָר מְנַשֵּׁב, וְאַחַר כָּךְ כְּפָפָהּ, חַיָּב בְּכָל עִנְיָן (הַמַּגִּיד הַנַּ\"ל)\u0006.\nגָּמָל שֶׁהוּא טָעוּן פִּשְׁתָּן, וְעָבַר בִּרְשׁוּת הָרַבִּים וְנִכְנַס פִּשְׁתָּנוֹ לְתוֹךְ הַחֲנוּת וְדָלְקָה בְּנֵרוֹ שֶׁל חֶנְוָנִי וְהִדְלִיק אֶת כָּל הַבִּירָה, בַּעַל הַגָּמָל חַיָּב, מִפְּנֵי שֶׁהִרְבָּה בַּמַּשּׂאוֹי, בֵּין שֶׁעָמְדָה הַבְּהֵמָה בֵּין שֶׁלֹּא עָמְדָה. וְאִם הִנִּיחַ הַחֶנְוָנִי נֵרוֹ מִבַּחוּץ, הוּא חַיָּב לְשַׁלֵּם אַף דְּמֵי הַפִּשְׁתָּן לְבַעַל הַגָּמָל, \u0010y10\u0011 \u0010c4\u0011 וַאֲפִלּוּ הוּא נֵר חֲנֻכָּה, שֶׁהָיָה לוֹ לֵישֵׁב וְלִשְׁמֹר שֶׁלֹּא יַזִּיק. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם הַדְּלֵקָה בְּמָקוֹם אֶחָד וְנִתְפַּשֵּׁט הָאֵשׁ לְמָקוֹם אַחֵר, חַיָּב עַל מְקוֹם הָאֵשׁ נֶזֶק שָׁלֵם וְעַל הַשְּׁאָר חֲצִי נֶזֶק. וְאִם הַגָּמָל סִכְסֵךְ הָאֵשׁ בְּכָל הַבִּירָה, חַיָּב עַל כֻּלּוֹ נֶזֶק שָׁלֵם (טוּר ס\"ז)\u0006, וְעַיֵּן לְעֵיל סִימָן שצ\"ב חִלּוּקִין אֵלּוּ: \u0010y11\u0011\nטָמוּן בְּאֵשׁ, פָּטוּר. שֶׁאִם הִדְלִיק גְּדִישׁ חֲבֵרוֹ וְהָיוּ טְמוּנִים בּוֹ אֲפִלּוּ מוֹרִגִּים \u0005(פֵּרוּשׁ, קְרָשִׁים נְקוּבִים וּבָהֶם יְתֵדוֹת שֶׁל עֵץ אוֹ שֶׁל בַּרְזֶל שֶׁדָּשִׁין בָּהֶם הַתְּבוּאָה)\u0006 וּכְלֵי בָּקָר \u0010y12\u0011 שֶׁדֶּרֶךְ לְהַטְמִינָם בַּגָּדִישׁ, פָּטוּר, וְרוֹאִים מְקוֹם הַכֵּלִים הַטְּמוּנִים \u0010y13\u0011 כְּאִלּוּ הָיוּ שָׁם שְׂעוֹרִים אוֹ חִטִּים כְּפִי מַה שֶּׁהוּא הַגָּדִישׁ, וְכָךְ יְשַׁלֵּם לוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמַדְלִיק בְּתוֹךְ שֶׁלּוֹ וְהָלְכָה וְדָלְקָה בְּשֶּׁל חֲבֵרוֹ וְכָלוּ חִצָּיו, כְּגוֹן שֶׁנָּפַל הַגָּדֵר שֶׁבֵּינֵיהֶם שֶׁלֹּא מֵחֲמַת \u0010y14\u0011 הַדְּלֵקָה, וְהָיָה אֶפְשָׁר לוֹ לִגְדֹּר וְלֹא גָדַר. אֲבָל אִם הִדְלִיק בְּתוֹךְ שֶׁל חֲבֵרוֹ, אוֹ אֲפִלּוּ בְּתוֹךְ שֶׁלּוֹ וְלֹא כָּלוּ חִצָּיו, כְּגוֹן שֶׁנָּפַל הַגָּדֵר מֵחֲמַת הַדְּלֵקָה, חַיָּב בְּדָבָר שֶׁדַּרְכּוֹ לְהַטְמִין בַּגָּדִישׁ כְּגוֹן מוֹרִגִּים וּכְלֵי בָּקָר, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן צ'. וּבְבַיִת \u0010c5\u0011 חַיָּב עַל כָּל דָּבָר, שֶׁדֶּרֶךְ בְּנֵי אָדָם לְהַנִּיחַ בַּבַּיִת כָּל כְּלֵיהֶם וְכָל חֲפָצֵיהֶם, וְכָל מַה שֶּׁיִּטְעֹן בַּעַל הַבַּיִת שֶׁהָיָה בַבַּיִת, \u0010y15\u0011 \u0010c6\u0011 הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל, וּבִלְבַד שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶם שֶׁהֵם שֶׁלּוֹ \u0010c7\u0011 אוֹ שֶׁרְגִילִים לְהַפְקִיד בְּיָדוֹ. \u0005וְע\"ל סִימָן צ'.\u0006\nהַמַּשְׁאִיל מָקוֹם לַחֲבֵרוֹ לְהַגְדִּישׁ בּוֹ, וְהִגְדִּישׁ וְהִטְמִין בּוֹ כֵּלִים, וְהִדְלִיק הַמַּשְׁאִיל \u0010y16\u0011 \u0005דְּהַיְנוּ שֶׁעָשָׂה הַמַּשְׁאִיל אֵשׁ וְיָצְאָה וְהִדְלִיקָה (טוּר)\u0006 וְשָׂרַף הַגָּדִישׁ וְהַכֵּלִים שֶׁבְּתוֹכָהּ, אֵינוֹ מְשַׁלֵּם אֶלָּא דְּמֵי גָדִישׁ בִּלְבַד.\nהִשְׁאִילוֹ מָקוֹם \u0010y17\u0011 לְהַגְדִּישׁ חִטִּים, וְהִגְדִּישׁ שְׂעוֹרִים, אוֹ לְהַגְדִּישׁ שְׂעוֹרִים \u0010y18\u0011 וְהִגְדִּישׁ חִטִּים, אוֹ שֶׁהִגְדִּישׁ חִטִּים \u0010y19\u0011 וְחִפָּם בִּשְׂעוֹרִים, \u0010y20\u0011 אוֹ שֶׁהִגְדִּישׁ שְׂעוֹרִים וְחִפָּם בְּחִטִּים, אֵינוֹ מְשַׁלֵּם לוֹ אֶלָּא דְּמֵי שְׂעוֹרִים בִּלְבַד.\nמִי שֶׁרָאָה דְּלֵקָה שֶׁמִּתְקָרֶבֶת לְקָמַת חֲבֵרוֹ, וְהָלַךְ וְכִסָה הַקָּמָה, אַף עַל פִּי שֶׁגָּרַם לוֹ הֶפְסֵד שֶׁהֲרֵי עֲשָׂאוֹ טָמוּן, הֲרֵי זֶה פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם.\nאֵשׁ שֶׁעָבְרָה וְהִזִּיקָה אֶת הָאָדָם \u0010y21\u0011 וְחָבְלָה בּוֹ, הֲרֵי הַמַּבְעִיר חַיָּב בְּנִזְקוֹ וּבְשִׁבְתּוֹ \u0010y22\u0011 וּבְרִפּוּיוֹ וּבְצַעֲרוֹ וּבְבָשְׁתּוֹ \u0010y23\u0011 כְּאִלּוּ הִזִּיקוֹ בְּיָדוֹ, \u0005(שֶׁאַף עַל פִּי)\u0006 שֶׁאִשּׁוֹ מָמוֹנוֹ הוּא, \u0010y24\u0011 הֲרֵי הוּא כְּמוֹ שֶׁהִזִּיק בְּחִצָּיו; וְהוּא שֶׁהָיָה הָאֵשׁ רָאוּי לְהַגִּיעַ שָׁם לַמָּקוֹם שֶׁהִזִּיק בְּשָׁעָה שֶׁהִדְלִיק, אֲבָל אִם לֹא הָיָה רָאוּי לְהַגִּיעַ שָׁם, כְּגוֹן שֶׁהָיָה גָּדֵר בֵּינֵיהֶם וְנָפַל שֶׁלֹּא מֵחֲמַת הָאֵשׁ, אֲפִלּוּ אִם הָיָה אֶפְשָׁר לוֹ לְגָדְרָהּ, כְּבַר כָּלוּ חִצָּיו וְיֵשׁ לוֹ דִּין מָמוֹנוֹ שֶׁהִזִּיק אָדָם שֶׁאֵינוֹ חַיָּב אֶלָּא בְּנֶזֶק בִּלְבַד, \u0010y25\u0011 וּפָטוּר מֵאַרְבָּעָה דְבָרִים.\nהִנִּיחַ לַחֲבֵרוֹ גַּחֶלֶת עַל לִבּוֹ, וְנִשְׂרַף, פָּטוּר, אֲפִלּוּ הִתְרוּ בּוֹ; שֶׁלֹּא הָיָה סָבוּר שֶׁלֹּא יְסַלְּקֶנָּה, שֶׁאֵין דֶּרֶךְ שֶׁיַּנִּיחַ אָדָם עַצְמוֹ לִשְׂרֹף כְּדֵי שֶׁיֵּהָרֵג חֲבֵרוֹ. אֲבָל אִם הִנִּיחַ גַּחֶלֶת עַל בִּגְדוֹ שֶׁל חֲבֵרוֹ וְנִשְׂרָף, \u0010y26\u0011 \u0010c8\u0011 חַיָּב, שֶׁאֵינוֹ חוֹשֵׁשׁ לְסַלְּקוֹ כֵּיוָן שֶׁזֶּה חַיָּב לְשַׁלֵּם לוֹ. וְעַבְדּוֹ כְּגוּפוֹ, וְשׁוֹרוֹ כְּבִגְדוֹ. \u0005הַגָּה: \u0010y27\u0011 וְיֵשׁ אוֹמְרִים דְּעֶבֶד קָטָן דִּינוֹ כְּשׁוֹר (נִמּוּקֵי יוֹסֵף ס\"פ כֵּיצַד)\u0006. וְיֵשׁ אוֹמְרִים דַּוְקָא בְּשׁוֹר כָּפוּת, אֲבָל בְּשׁוֹר שֶׁאֵינוֹ כָפוּת, פָּטוּר \u0005(טוּר סי\"ד בְּשֵׁם רַשְׁבָּ\"א וְהָרֹא\"שׁ)\u0006.",["\u0003דכתיב כי תצא וגו' \u0004 בפרשת משפטים כי תצא אש ומצאה קוצים ונאכל גדיש או הקמה או השדה שלם ישלם המבעיר את הבעירה ודרשינן שהדבר הנשרף בעינן שיהא דומיא דקמה וגדיש שהן דברים שבגלוי לאפוקי אם נטמן בהן דבר וכמ\"ש הטור והמחבר בסמוך בסי\"ג ע\"ש:","\u0003אפי' לא שרפו אלא עציו ואבניו כו' \u0004 ל' הטור או שליחכ' נירו שהוא דבר \"שאינו \"ראוי לו ובפרישה כתבתי שהאי \"שאינו \"ראוי לו קאי גם אאבניו וגם אעציו אם הם בענין שאינם ראויים לו וקמ\"ל דאף דכתיב ביה כי תאכל לשון אכילה ובהיזק שן נתבאר בסי' ש\"ץ דאם אכל דבר הראוי לו ודרכן בכך נתחייב עליו בעליו נ\"ש ואי לא (ח\"נ) אבל בכאן אפי' אינו ראוי לשרוף מתחייב עליו נ\"ש וילפינן מיתורא דאו השדה דאפי' ליחכה נירו וה\"ה נשרפו אבניו:","\u0003אבל במדליק בתוך חבירו כו' \u0004 דכיון דהדליק מתחלה שלא ברשות חייבוהו על הכל:","\u0003שזו מכה בידי שמים הוא. \u0004 כצ\"ל וכן הוא לשון הרמב\"ם ורצה לו' ומה\"ט פטור אע\"ג דבעלמא אמרינן דכל המקלקלין אע\"פ שהניח ברשות אפי' הכי הוא חייב וכמו שכתבו הטור והמחבר בסוף סי' שלפני זה ועמ\"ש בשם הרי\"ף בסי' ת\"י ס\"ה בדרישה בטעם חילוקי חיוב פטור הללו:","\u0003ה\"ג ורחבם שמנ' \u0004 וכן הוא ברמב\"ם דפוס גדול וקטן:","\u0003בד\"א באש הקודחת כו' \u0004 לשון הטור וכל זה לא איירי אלא כשמתמרה ועולה למעלה אבל אם נסרכ' לצידה ועצים מצויי' לה אין לה שיעורכו':","\u0003וכן אם הניח שומר לשמור כו'. \u0004 וכן הדין במי שמסר שור ביד שומר ויצא והזיק כמ\"ש הטור והמחבר בסי' שצ\"ו ושם נתבאר חילוק דאם הוא ש\"ח או ש\"ש או שואל ודין שומר שמסר לשומר ע\"ש:","\u0003המביא עצים חייב כו'. \u0004 ל' הטור לעולם האחרון חייב:","\u0003רוח שאינו מצויה תמיד \u0004 ז\"ל מ\"מ בפ\"ד מנ\"מ רוח שאינו מצויה ר\"ל שאין העולם מתנהג בה תמיד אלא לפעמים אף ע\"פ שהוא בא בעתים הרבה ואצ\"ל רוח סערה שאינו נשבה אלא לעתים רחוקות:","\u0003דאין המלבה חייב אלא כו'. \u0004 ואע\"ג דלענין הזורה בשבת והרוח מסייעו חייב שאני התם דמלאכת מחשבת אסרה התורה והרי מלאכת הזרייה דרכה בכך ע\"י הרוח שסייעו משא\"כ כאן דה\"ל הוא רק גורם להיזק ופטור והרמב\"ם סבר דחייב כיון דהוא עצמו ליבה ויש לו חלק בנזק זה ואינו דומה לגרמא בנזקין דפטור עד\"ר:","\u0003ואפי' הוא נר חנוכה \u0004 פירוש אע\"פ שהניחו שם ברשות כי המצוה הוא בכך:","\u0003טמון באש פטור. \u0004 בר\"ס זה כתבתי דילפינן ליה מיתור' דאו הקמה דבעינן דיהא דומה לקמה דהוא דבר שבגלוי והאי או קמה גבי תצא אש כתיב דמיירי שיצאה מרשותו בזה דוקא מצינו בו דפטור בו טמון משא\"כ בהדליק בשל חבירו וכדמסיק:","\u0003שדרך להטמינ' בגדיש. \u0004 פי' וה\"ל לאסוקי אדעתיה שישנו שם ולהיות חייב בשריפתן:","\u0003כאלו היה שם חטים או שעורים כו'. \u0004 בפרישה כתבתי שאם הגדיש הוא חיטין או שעורין עם תבן שלהן וכדרך הגדיש דשמין גם המוריגי' בחיטין ושעורין בתבן שלהן וגם זהו בכלל מ\"ש הטור והמחבר כפי מה שהוא הגדיש:","\u0003והיה אפשר לו לגדור \u0004 דאל\"כ לא היה חייב על היזק השריפה כיון שכלו חציו וכמ\"ש לפני זה בס\"ו:","\u0003נשבע בנק\"ח ונוטל. \u0004 פי' אע\"פ שאין עדים בדבר שכך וכך הי' לו בבית ע' בד\"מ שכ' בשם המ\"מ אם היו מחולקין בדבר הנשרף לו בגלוי שהניזק אמר כך וכך הי' והמזיק אמר ברי לי שלא הי' אלא כך אפ\"ה הניזק נשבע ונוטל דעשו תקנ' נגזל ג\"כ בנשרף ע\"ש וע\"ל בסי' צ' מקור דין נשבע ונוטל בענייני' אלו:","\u0003דהיינו שעשה המשאיל אש כו' \u0004 פי' עשה האש בשלו וכלו חציו וכנ\"ל קמל\"ן דל\"ת כיון דנתן ראובן רשות לשמעון להגדיש בחצירו וה\"ל כאלו קיבל ראובן שמירתו דגדיש עליוואפי' להרי\"ף והרמב\"ם החולקים בסימן שצ\"ח עם ר\"י והרא\"ש ופטרי לב\"ה שהזיק שורו לשור הנכנס ברשות ה\"א דמודו בהא כיון דמ\"מ הדליק האש בידים קמל\"ן:","\u0003להגדיש חטין והגדיש שעורים \u0004 וא\"ת פשיטא איך ישלם טפי ממה שהזיק י\"ל דקמ\"ל דל\"ת דליחייב אמוריגין שהטמין בתוכו כאלו הי' חטים וכדין מוריגין שטמון בגדיש של חטין והרי נתן לו רשות לחיטין ועפ\"ר:","\u0003והגדיש חטים וכו' \u0004 דיכול לומר לא קבלתי עלי אלא שמירת שעורים:","\u0003וחיפן בשעורים. \u0004 אף ע\"ג דנתן רשות לחיטין יכול לומר לא ראיתי לפני אלא שעורין:","\u0003ומ\"ש הטור והמחבר או שהגדיש שעורים וחיפן בחיטין. \u0004 בפריש' כתבתי ל' רש\"י שפי' דמיירי בנתן לו רשות להגדיש שעורים וכתבתי דלפ\"ז ל\"ל דקמ\"ל בזה דל\"ת דוקא ברישא ששינ' מדעת המשאילו לגמרי שנתן לו רשות לשעורים והוא הגדיש חטים הוא דפטור מחטים מה שא\"כ זה שהגדיש שעורים לחייב לפחות גם אחיפוי חטין קמ\"ל:","\u0003וחבלה בו. \u0004 ואם מת מכח הבערה חייב בעליו מיתה כאלו ירה בו חץ וכ\"כ הטור:","\u0003ובצערו ובבשתו. \u0004 ואע\"ג דיתבאר בסי' תכ\"א דאין חייב על הבשת עד שיכוון לבייש ה\"נ כיון דעבר הדליק' ברוח מצויה ה\"ל כאלו ידע וכוון לכך וצריכין לומר דחילקו הרמב\"ם והמחבר בין זה לנפל מן הגג ברוח מצוי' והזיק שכתב הרמב\"ם בפ\"א דחובל והמחבר לקמן בסי' תכ\"א סי\"א דאינו משלם בבשת משום דלא כוון דשאני התם דנפילתו מהגג ויזיק מחשב לאונס טפי אף שהי' ברוח מצוי' מהדליק אש ויצא והזיק לאדם אבל רש\"י ור\"ן כתבו בפ' כיצד הרגל בהדיא גם בזה דפטור מבושת והביאו ראיה מההיא דנפל מהגג והרא\"ש והטור סתמו וכתבו בדין זה דחייב בד' דברים ועפ\"ר שכתבתי שנ\"ל דס\"ל ג\"כ כהרמב\"ם דחייב גם בבשת וד' דברים חוץ מנזק קאמרי דנזק חייב בפשיע' לכ\"ע אף אם לא היה בו משום חציו אלא משום ממונא ע\"ש ודו\"ק:","\u0003כאלו הזיק בידים \u0004 שאע\"פ שאשו כו' כצ\"ל וילפינן לה מדכתי' כי תצא אש ומצאה קוצים דמשמע דיצאה מעצמו וסיים וכתב ישלם המבעיר משמע דנחשב כאילו הבעירו בידים:","\u0003הרי הוא כמי שהזיק בחציו. \u0004 פי' לענין להתחייב עליו בה' דברים וגם מיתה אם מת מחמת האש וכנ\"ל אבל ג\"כ לא גרע משור ובור שהן ממונו וחייב עליהן לפחות נזק ונ\"מ דאפי' היכא דלא חייב על האש משום חציו כגון שלא היה לו לעבור עדיין חייב משום ממונו וכדמסיק המחבר:","\u0003ופטור מד' דברים. \u0004 דכי יתן איש בעמיתו כתיב וכנ\"ל:","\u0003שאינו חושש לסלק כו' \u0004 ונראה דה\"ה אם ראובן אמר לשליח שאינו בר חיובא כגון חש\"ו קרע בגד שמעון והחש\"ו קרעו לפני שמעון ושותק דחייב ראובן המשלח מה\"ט שלא חשש שמעון למחות בידו:","\u0003דעבד קטן דינו כשור. \u0004 עד\"ר שם כתבתי דלא כתב הנ\"י כן אלא לשטת פירש\"י דס\"ל דבהניח על השור אף שאינו כפות חייב דלא אמרינן גבי בהמה דאין לה דעת דה\"ל לברוח ע\"ז כתב הנ\"י בס\"פ כיצד הרגל דה\"ה עבד קטן דאין בו דעת אבל לדעת התוס' והרא\"ש דכתבו דדוקא בשור כפות הוא דחייב אבל באינו כפות פטור משום דדרכו לברוח מהאש אף שאינו בר דעת ובהניח על לב עבד פטור אם רבו הוא שם אפי' בכפות משום דסבר המניח שרבו יסירנ' מעליו כיון שעבד הוא בן חורין (חיוב) וחייב במצות מה\"ט גם בעבד קטן שאינו כפות פטור דהוי לו לברוח דומיא דשור. ובכפות ורבו עומד בצדו (אינו) דומה לעבד גדול ואין יכול המניח גחלת על לבו להתנצל ולומר סברתי שרבו יסירנה מלבו כדין עבד: וע\"פ מ\"ש יתבאר לך דמור\"ם דסתם וכ' די\"א עבד קטן הוא כשור הוא ע\"פ מה שסתם המחבר וכ' דין שור ועבד ולא הזכיר בדבריו כפות כ\"כ אבל לפי מה שמסיק מור\"ם וכ' די\"א דוקא שור כפות ע\"פ אותו דעה אין דין עבד קטן כשור וכמ\"ש וזה ברור אלא שק' הא צ\"ל דהמחבר אף שלא הזכיר כפות ע\"כ צריכין לפ' דמיירי בכפות שהרי כ' בר\"ס שפ\"ג אעבד ושור דין זה כשהיו כפותין וצ\"ל שקיצר כאן יסמך אמ\"ש שם וכמ\"ש בסמ\"ע שם בסי' שפ\"ג וצריכין לדחוק ולומר דאעפ\"כ מ\"מ כיון דלא הזכיר המחבר כאן כפות כ' מור\"ם עליו כן:"],["\u0003 ויצא והזיק כו'. \u0004 ע\"ל סימן קנ\"א [קנ\"ה] ס\"א:","\u0003 ואם לא הרחיק כו'. \u0004 עיין ביש\"ש סי' צ\"ח [כ\"ח] מה שהקשה ע\"ז מ\"ש בס\"ד ויש ליישבו ודוק וע\"ש:","\u0003 רחב ח' אמות כו' \u0004 וכ\"פ מהרש\"ל סי' כ\"ח ועיין שם טעמו ואין כדאי בטעמו לדחות דברי הרא\"ש וטור:","\u0003 ליבה וליבתו הרוח חייב. \u0004 הוא לשון הרמב\"ם והראב\"ד השיג עליו וז\"ל איך לא חלק כמו שחלק בברייתא אם יש בלבויו כדי ללבות חייב ואם לאו פטור והרב המגיד כתב שאפשר לתרץ שפסק דלא כרב אשי אלא כאידך שנויי דאמוראי אלא שקשה שבפי\"א מה' שכנים פסק כרב אשי (כדלעיל סימן קנ\"ה סל\"ד ע\"ש) והב\"י כתב שדברי הרב המגיד נכונים ול\"ק מפי\"א מה' שכני' דשאני התם שאין נזק זה בא מכח מזיק עצמו משא\"כ הכא שבא מכח מזיק עצמו נקטינן כאינך אמוראי דחייב עכ\"ל ואחריו נמשך הסמ\"ע ושאר אחרונים וכה\"ג כתב מהרש\"ל פ' הכונס סימן כ\"ד. ואני אומר אם כדבריהם ודאי פה השיגו הראב\"ד דהאיך יתכן שיפסוק כאינך אמוראי והא קיימא לן בכל דוכתא הלכתא כרב אשי נגד הנך אמוראי ועוד דמ\"מ תיקשי דהל\"ל כדברי הברייתא ואם לאו פטור ולפרושי בהנך גווני דמפרשי לה אינך אמוראי לאביי כגון שלבתו הרוח מצד אחר ולרבא ברוח שאינו מצויה ולר' זירא כגון דצמרא צמורי אכן לפע\"ד נ' שלא ירדו כולם לסוף דעת הרמב\"ם וטעמו ונמוקו עמו מה שלא חלק כמו שחילק בבריית' והוא בשום לב עוד שהרמב\"ם כתב וז\"ל לבה ולבתו הרוח חייב שהרי הוא גרם וכל הגורם להזיק משלם נזק שלם מן היפה שבנכסיו כשאר כל המזיקין עכ\"ל דלאיזה צורך האריך הרמב\"ם בטעם זה וגם היאך כתב טעם שלא נזכר בש\"ס כלל אלא ודאי כוונת הרמב\"ם לפסוק כרב אשי דבתראי הוא וס\"ל דפירושא דברייתא ודאי כרב אשי הוא ולא כאידך אמוראי ואין חילוק בין לבתו מצד אחר או בין רוח שאינה מצויה או בין צמרה צמורי אלא ברייתא כפשטא היא כדאוקמה רב אשי דטעמא הוא משום גרמא בנזקין פטור אלא דס\"ל להרמב\"ם דנהי דאוקימתא דברייתא הכי היא מ\"מ לא קי\"ל כוותה משום דאתיא כמ\"ד דלא דיינינן דינא דגרמי ואנן דיינינן דינא דגרמי וכדאיתא להדיא בש\"ס פרק הגוזל קמא (בבא קמא דף צ\"ח ע\"ב) ונתבאר לעיל סי' שפ\"ו (וס\"ל להרמב\"ם דגרמי וגרמא הכל א' הוא וכדעת רש\"י שהביא הרמב\"ן בדיני דגרמי שלו וכן הוכחתי מדברי רש\"י ר\"פ הכונס ופ' הגוזל שם ע\"א ופרק לא יחפור סוף (בבא בתרא דף כ\"ב) ודלא כמהרש\"ל פרק כיצד הרגל סי' ל\"ו ופרק הגוזל קמא סי' י\"ט לדעתו עיין שם) וזה לשון הש\"ס פרק הגוזל גבי שורף שטר של חברו אמר אמימר מאן דדאין דינא דגרמי מגבי דמי שטרא מעליא ומאן דלא דאין דינא דגרמי מגבי דמי ניירא בעלמא הוה עובד' וכפייה רפרם לרב אשי ואגביה כי כשורא לצלמא עכ\"ל ופירש רש\"י כי כשורא לצלמא פרעון גמור מן העידית וכן כ' הרמב\"ם פ\"ז מה' חובל וז\"ל כל הגורם להזיק ממון חברו חייב לשלם נ\"ש מן היפה שבנכסיו כו' וכן השורף שטר של חברו וכן אם מחלה משלם המוחל מן היפה שבנכסיו עכ\"ל הרי שזה ה\"ל [הל'] ממש שכתב הרמב\"ם בפי\"ד מה' נזקי ממון הוא שאול מדבריו פ\"ז מהלכו' חובל והוא ע\"פ מאי דקי\"ל דדיינינן דינא דגרמי. כן נראה לי ברור בדעת הרמב\"ם ז\"ל אך יש לדקדק אמאי פסק בפי\"א מהלכות שכנים דפטור ומה שתירץ הב\"י בזה שאין הנזק בא מכחו הוא דוחק דהא כיון שבהכאתו הולך העפר דומה לליבה שבלבתו הולך האש ויש לתרץ בזה כמו שחילקו הרמב\"ם בדיני דגרמי שלו ומהרש\"ל שם דל\"ד לעפר שבפי\"א שהולך הפך מכחו שכונתו להפיל העפר לארץ ולא שילך למרחוק משא\"כ אש שהרוח מסייע למה שכוונתו שילך האש ע\"ש ואולי גם הב\"י כוון לזה ואין להקשות מנ\"ל להרמב\"ם לחלק בכך י\"ל דמשמע לי' דמסתמא לא פליגי [מר בר] רב אשי ואמימר בס\"פ לא יחפור ארבינ' פלוגתא רחוק' דרבינא שרי אפי' לכתחלה כדמוכח התם אלא ודאי אינהו לא קאמרו אלא לכתחל' אבל בדיעבד אם הזיק פטור לכ\"ע והיינו משום דהתם ליכא גרמא כלל משום דלא ניחא ליה במה שהעפר הולך למרחוק והיינו בכלל מה דמשני התם בגמרא הכא לא ניחא ליה דליזל אבל בליבה ולבתו הרוח ניחא ליה דליזל. כל זה נ\"ל לדעת הרמב\"ם והיה לבי נוקפי קצת על מה שפרשתי בדעת הרמב\"ם שטה אחרת בש\"ס ס\"פ הכונס עד שמצאתי ת\"ל ראיה ברור' לדברי בראב\"ן פרק הגוזל קמא בספרו ד' צ' ע\"א וז\"ל הוה עובדא דאדם אחד שרף שטר של חבירו ובאו לדין לפני רב אשי והי' פוטרו כדברי רבה ולפי שמועתו שאמר בפרק הכונס גבי לבה וליבתו הרוח דאמר רב אשי גרמא בעלמא הוא וגרמא בנזיקין פטור ואכפייה רפרם לרב אשי בדברים ובדין ואגביה ביה כשורא מן המובחר וכיון דרב אשי ורפרם עבדו עובדא ודנו דיני דגרמי כותייהו קי\"ל דאינון בתראי עכ\"ל הרי להדיא כדברי. ובריש הספר הסוגיא דס\"פ לא יחפור כתב ראב\"ן וז\"ל ולרבינא מאי שנא מגץ היוצא כו' כלומר מאי שנא מזור' וגץ דבתרוייהו הרוח מסייעו ומשני התם ניחא ליה דליזל כלומר בין זורה בין גץ ניחא ליה דליזלו מרחוק ולא יפלו תחתם אבל רקתא לא ניחא ליה דליזל אלא שיפול תחתיו וכי אזיל לאו גירי' הוא דמדעתו ורצונו לא אזיל עכ\"ל והלכך הרמב\"ם אע\"ג דפסק כמר בר רב אשי ואמימר דפליגי אדרבינא היינו לענין להרחיק לכתחלה אבל אם הזיק משמע ליה דל\"ד לזורה ורוח מסייעתו מהאי טעמא וכמ\"ש ודו\"ק:","\u0003 ואפי' הוא נר חנוכה \u0004 (הגה\"ה ועיין ברי\"ף פרק במה מדליקין דאיתא שם שפטור ועיין בש\"ג שם שכתב שהוא הג\"ה ואינו מלשון הרי\"ף ע\"ש טעמו וק\"ל וכן משמעות הלשון שם שהוא אינו מדברי הרי\"ף):","\u0003 על כל דבר שדרך בני אדם להניח כו' \u0004 משמע אם אין דרך להניחו אפי' ידוע שהי' שם פטור ויש להקשות דהא לעיל ר\"ס שפ\"ח משמע להדיא מדברי הרמב\"ם והמחבר דבידוע שהי' שם אפי' אין דרכו להניח שם חייב וצ\"ל דהתם מיירי המזיק בידים אבל הכא אע\"פ דמיירי שהדליק בתוך של חבירו היינו בפשיעה ולא בידים וכן נ\"ל מתוך דברי מהרש\"ל פרק הכונס סי' ל\"ב שכתב שם וז\"ל אבל אי הוי עדים פשיטא דמשלם מאחר דמזיק בידים הוא אבל מזיק בפשיעה לא משלם אפי' בעדים דבר שאין דרך להניח בו ומדליק בתוך של חבירו נמי דפטרי רבנן כל מה שאין דרכו להניח היינו דמדליק בידים פשיטא שחייב על הכל עכ\"ל ונ\"ל שיש חסרון בדבריו וכך צ\"ל היינו מדליק בפשיע' דאלו מדליק בידים פשיטא שחייב על הכל ודו\"ק:","\u0003 הרי זה נשבע בנקיטת חפץ. \u0004 ועיין בד\"מ ובב\"י שכתבו בשם המ\"מ אם היה מחולקין בדבר הנשרף לו בגלוי שהניזק אומר כך וכך היה והמזיק אומר ברי לי שלא היה אלא כך אפ\"ה הניזק נשבע ונוטל דעשו תקנת נגזל ג\"כ בנשרף ע\"ש ומביאו ג\"כ בסמ\"ע ומיירי שיש עדים על הדליק' וכן הוא במ\"מ להדיא ובזה ניחא דלא תקשי ממ\"ש הרמב\"ם והמחבר לעיל ר\"ס שפ\"ח המזיק ממון חבירו ואינו יודע מה הזיק כו' או לאש כו' והמזיק אומר אינו יודע כו' הניזק נשבע בנק\"ח ונוטל כו' דמשמע הא אם טוען המזיק ברי אין הניזק נשבע ונוטל דהתם מיירי שאין עדים שהזיקו אם כן נאמן במגו ודו\"ק כל זה צ\"ל לדעת הרב והמגיד והסמ\"ע אבל באמת נ\"ל עיקר דהרמב\"ם והמחבר ס\"ל כהי\"א שהביא הרב המגיד דבאש אם טוען המבעיר ברי נשבע ונפטר והדעת נותנת כן וכן משמע להדיא מדברי מהרש\"ל פרקי הכונס ס\"ס ל\"ג שכתב שם וז\"ל דוקא שטען המזיק שמא אבל אי טען ברי לא א\"ל גבי גזלן כו' וכ\"כ עוד מהרש\"ל להדיא שם סי' ל' דמסור מיירי כשטוען המוסר ברי ואף דהא דאמרי' עשו תקנת נגזל באשו לא איירי בכופר המבעיר מכל מקום לא הוי רשע כגזלן ודוק' מוסר ראוי לדמותו לגזלן אבל לא מזיק אפי' להכעיס כו' עכ\"ל וכן מוכח להדיא בהרא\"ש פרק הכונס וז\"ל ואין נראה לר\"י דמשמע בבעיא דומיא דטמון באש שאין המבעיר יודע כמה הפסיד הניזק והכי מסתבר טפי לדמות בעיא זו לטמון באש מלדמותו לנגזל דהא טמון לא מדמינן לנגזל אף ע\"ג דקאמר עשו תקנת נגזל באשו עכ\"ל ובספר מע\"מ שם כתב על דברי הרא\"ש אלו וז\"ל דהא טמון לא מדמינן לנגזל כו' לא ידענא מאי קאמר לענין מה דלא מדמינן שלא מצינו בתלמוד שום דבר עכ\"ל ולא דק דה\"ק דהא טמון לא אשכחן דמדמינן לנגזל היכא דהמבעיר טוען ברי וק\"ל וכן כתב עוד הרא\"ש בס\"פ הכונס וז\"ל ותימא למה יעשו תקנת נגזל במפקיד בשלמא בנגזל עשו תקנה שלא ישבע הגזלן וכן באש שפשע בשמירת אשו וגם אין המבעיר יכול לידע מה היה לניזק בבית וכן במוסר שבועה על הנמסר שישבע ויטול שעשה המוסר עבירה אבל במפקיד למה הטילו כו' עכ\"ל וכן עיקר:","\u0003 או שרגילים כו' \u0004 עמ\"ש לעיל סימן צ' סעיף ז':","\u0003 שאינו חושש לסלקו כו'. \u0004 עיין בסמ\"ע ס\"ק כ\"ז וה\"ה דאמר לשליח שאינו בר חיובא כגון חש\"ו כו' דבריו תמוהין דהא תנן השולח את הבערה ביד חש\"ו פטור ועיין בפ\"ק דמציעא (דף י') ובתוס' שם (הג\"ה ר\"ל שהרגישו בקושיא זו דהא לאו בר חיובא הוא ותירצו ע\"ש) ובנ\"י שם ועמש\"ל ר\"ס קפ\"ב ורצ\"ב (הג\"ה ושמ\"ח):"]],["\u0010c0\u0011 כְּשֶׁבֵּית דִּין נִזְקָקִין לִגְבּוֹת לַנִּזָּק מִנִּכְסֵי הַמַּזִּיק, \u0010y0\u0011 \u0010c1\u0011 גּוֹבִין מֵהַמִּטַּלְטְלִין תְּחִלָּה, וְאִם לֹא הָיוּ מִטַּלְטְלִין כְּלָל, אוֹ שֶׁלֹּא הָיוּ לוֹ מִטַּלְטְלִין כְּנֶגֶד כָּל הַנֶּזֶק, גּוֹבִין הַשְּׁאָר מֵהַקַּרְקַע הַמְעֻלֶּה שֶׁבְּנִכְסֵי הַמַּזִּיק; וְכָל זְמַן שֶׁיִּמְצָא מִטַּלְטְלִין, וַאֲפִלּוּ סֻבִּין, אֵין נִזְקָקִין לַקַּרְקַע. \u0010c2\u0011 וַאֲפִלּוּ שֶׁיֵּשׁ לוֹ כֶּסֶף, יָכוֹל לְפוֹרְעוֹ בְּסֻבִּין, דְּכָל מִטַּלְטְלִים מֵיטַב נִינְהוּ. וְשָׁמִין אוֹתָהּ \u0010y1\u0011 כְּמוֹ שֶׁיָּכוֹל לְמוֹכְרָהּ מִיָּד וּבִמְקוֹמוֹ. וּכְשֶׁמְּשַׁלֵּם מֵהַקַּרְקַע, אֲפִלּוּ הָיְתָה זִבּוּרִית שֶׁל מַזִּיק טוֹבָה מֵעִדִּית שֶׁל נִזָּק, אֵינוֹ מְקַבֵּל מִמֶּנּוּ, אֶלָּא מַגְבִּין לוֹ \u0010y2\u0011 מֵעִדִּית שֶׁבְּנִכְסֵי הַמַּזִּיק.\nאִם יֵשׁ לַמַּזִּיק שְׁנֵי עִדִּית, אֵין הַנִּזָּק יָכוֹל לוֹמַר לוֹ: תֵּן לִי מֵעִדִּית פְּלוֹנִי, אֶלָּא תָּלוּי בִּרְצוֹן הַמַּזִּיק לָתֵת לוֹ אֵיזֶה שֶׁיִּרְצֶה. אֲבָל אִם הַמַּזִּיק חָפֵץ לָתֵת לוֹ הָעִדִּית שֶׁבִּקֵּשׁ, אֶלָּא שֶׁהִיא עַתָּה בְּזוֹל וּמַמְתִּין עַד שֶׁתִּתְיַקֵּר, וְאוֹמֵר: אִם תִּרְצֶה אוֹתָהּ קַח אוֹתָהּ כְּפִי מַה שֶּׁהִיא עֲתִידָה לְהִתְיַקֵּר, אֵין שׁוֹמְעִין לוֹ, אֶלָּא \u0010c3\u0011 צָרִיךְ לִתְּנָהּ לוֹ \u0010y3\u0011 כְּפִי מַה שֶּׁשָּׁוָה עַתָּה.\nמֵת הַמַּזִּיק קֹדֶם שֶׁיִּפְרַע, \u0010c4\u0011 מַגְבִּין \u0010y4\u0011 \u0010c5\u0011 לַנִּזָּק מֵהַמִּטַּלְטְלִין שֶׁל יְתוֹמִים; וְאִם לֹא הִנִּיחַ מִטַּלְטְלִין, מַגְבִּין לוֹ מִזִּבּוּרִית שֶׁבְּקַרְקְעוֹתָיו, \u0010c6\u0011 \u0010c7\u0011 \u0010c8\u0011 \u0010c9\u0011 שֶׁכָּל הַבָּא לִפָּרַע מִנִּכְסֵי יְתוֹמִים, לֹא יִפָּרַע אֶלָּא מֵהַזִּבּוּרִית:",["\u0003גובין מהמטלטלין תחלה. \u0004 עד\"ר שם כתבתי ל' הגמרא והוכחתי ממנה דאף בהלוא' [דבהלוא'] יד המלוה על העליונה דאם יש ללוה כסף או מטלטלין צריך לשלם ממנו ולאו כל כמיניה לשלם לו מקרקע אפי' מעידית ה\"ט דהמלוה הלוה לו מעות מ\"ה דינו ג\"כ במעות או במטלטלין שקרובים למעות שיכולין לטלטלן ולמכרם אפי' במקום אחר אי לא מזדבני בהאי מתא אבל בניזק יד המזיק על העליונה שאף אם יש לו כסף או מטלטלי אם ירצה לשלם בקרקע צריך הניזק לקבלן אך שיתן לו מעידית שבנכסיו וזהו כוונת רב פפא שאמר בגמ' בישוב הקושיא שהקשו שם בפי' מיטב שדהו ומיטב כרמו ישלם מיטב אין מידי אחריני לא והתניא ישיב לרבות שוה כסף ואפי' סובין ומשני רב פפא דביש לו מטלטלין ובא לפרוע מהם אינהו מקרי מיטב דאי לא מזדבני בהאי מתא מזדבני במתא אחריתי ואם בא לשלם מקרקעותיו צריך לשלם ממיטב שדותיו ועד\"ז פירשתי ג\"כ דעת הטור וכן יש לפרש ג\"כ דעת המחבר ומ\"ש גובין מהמטלטלין תחל' היינו משום דמסתמא ניחא למזיק לשלם במטלטלין מבקרקעות שהוא בר קיימא ומ\"ה קאמר כשב\"ד נזקקין משלמין מהמטלטלין ולמדונו דאף אם אין המזיק לפנינו לגלות דעתו לשלם במטלטלים אמרינן דמסתמא ניחא למזיק לשלם ממטלטלים ואף אם הניזק צועק לשלם לו מקרקעות כמשמעות הקרא ממיטב שדהו אין ב\"ד שומעין לו אבל ודאי אם המזיק גיל' דעתו דניחא ליה טפי במטלטלים ורוצה לשלם לו בקרקעות והניזק רוצה דוקא במטלטלין יד המזיק על העליונה ול\"ד למלוה ולוה ומטעם שכתבתי וק\"ל ולא כב\"י והע\"ש נמשך אחריו שכ' ז\"ל דאי בעי הניזק מטלטלים צריך המזיק ליתן לו כו' ע\"ש אבל אני הוכחתי דלע\"ד לא עלתה על דעתו דהטור כן עיין שם בדרישה:","\u0003כמו שיכול למוכרם מיד כו' \u0004 ע\"ל סי' ק\"א וק\"ג מ\"ש בביאור זה:","\u0003מעידית שבנכסי המזיק. \u0004 דכתי' מיטב שדהו ישלם ודרשינן דהיאך דמשלם דהיינו המזיק","\u0003כפי ששוה עתה \u0004 וכ\"כ הטור ועפ\"ר שם כתבתי דל\"ד למלוה שדינו להשתלם מהלוה בבינונית וכשהוא אומר להלוה פרע לי מעידי' שלך בציר פורתא וגם הלוה נתרצה לשלם לו מהעידית רק שא\"ל קח אות' כיוקרא דלקמי' דפסק הטור כהרא\"ש בסי' ק\"כ [ק\"ב] דהדין עם הלוה דצריך לקבל כיוקרא דלקמיה ולא כמו שהוא שוה עתה שאני התם דאין דין המלוה להשתל' מהעידי' כלל אבל ניזק דדינו להשתלם מהעידית אלא שיפו חז\"ל כח המזיק ליתן לו מאיזה עידית שהוא רוצה ולשייר החביב לפניו וכיון שהוא גילה דעתו שאינו מבקש לקיים זו לפניו אלא שרוצה להעלות להניזק בדמים כיוקרא דלקמיה העמידהו על דינו לשלם ממיטב ממש וכזולא דהשתא ולא כע\"ש דכ' דברי המחבר וכ' עליהן ז\"ל ונ\"ל דלא נאמרו דברים הללו אלא כשיש למזיק עידית ובינונית ואומר הניזק תן לי בינונית טפי פורת' כו' עד אבל בשניהן עידי' אפי' אם המזיק גילה דעתו שאינו רוצה להעמיד בידו אותו עידית שמבקש הניזק א\"צ ליתן לו כזולא דהשתא דמ\"ש זה מכשיש בידו כסף וסובין דאמרי' בסעיף א' דיכול ליתן לו סובין משום דמטלטלי כל מילי מיטב הוא ויכול ליתן איזה שירצ' ה\"נ הא שניהם מיטב הוא ויכול ליתן לו איזה שירצה ומהתימא שהטור גם מהרי\"ק ז\"ל בש\"ע לא דקדקו בזה וצ\"ע עכ\"ל עיר שושן ומהתימא דלפי סברתו הו\"ל להקשות דברי הטור והמחבר אהדדי מכאן למ\"ש בסי' ק\"ב הנ\"ל. ועוד מאי מייתי ראי' מכסף וסובין הלא י\"ל דכמו שהן מחולקין ביש לו שני מיני עדות כתבו דהרשות בידו ליתן איזה שירצה ואפ\"ה כתבו דכשגיל' דעתו שאינו מבקש להעמיד הטוב' יות' לפניו צריך ליתנו לו כזולא דהשתא. א\"כ גם בכסף וסובין נאמר כן. גם י\"ל דמ\"ה לא אמרו בהדיא בכסף וסובין דאם גיל' דעתו כו' דנותן לו מהכסף כזול' דהשתא משום דלא שייך בכסף כיוקרא דלקמיה וזולא דהשתא דכל הזמנים שוים בדמי שוויה דהכסף משא\"כ בקרקע שבימי הקיץ שהן עומדין לזרוע ולאכול מהן פירות הן יקרים טפי מכשהן בימי הגשמים וכמבואר בי\"ד סי' רנ\"ג ע\"ש:","\u0003מהמטלטלים של יתומים. \u0004 בטור מפורש דמיירי לאחר תקנת הגאונים דתקנו דמלוה גובה ממטלטלים דיתמי וה\"ה מזיק וגם לענין זה מזיק שוה למלוה דבא לגבות מנכסי יתמי לוה דאינו גובה אלא מהזיבורית אף דהלוה הי' צריך לשלם מבינונית ה\"נ בניזק שבא לגבות מיתמי המזיק. וצ\"ע דכאן סתם המחבר ומשמע דס\"ל דאפי' אם בא לגבות מיתומים גדולים אינו גובה אלא מהזיבורית והמ\"מ בפ\"ה דנ\"מ כתב שכן הוא דעת הרמב\"ם ושהרשב\"א חילק בין קטנים לגדולים ולעיל ס\"ס ק\"ח פסק המחבר גופו כן לחלק בין קטנים לגדולים ומטעם שכתבתי שם בסמ\"ע והוא כדעת הרא\"ש וה\"ר יונה וכמו שכתב הטור שם והא דבסי' זה סתם הטור ג\"כ וכתב דאין מגבין לניזק ממטלטלי דיתמי דאינן משועבדין לב\"ח אלא מקרקעותיו ומהזיבורית שבהן י\"ל שאגב שכ' החילוק שבין אם בא לגבות מהמזיק עצמו לבא לגבות מיתומים לענין מטלטלין כ' ג\"כ החילוק שביניהן לענין זיבורית ומיירי דוקא בקטנים ולולי דעת המ\"מ הנ\"ל הייתי אומר שגם דעת הרמב\"ם כן ששם בפ\"ח דנ\"מ כתב כל' הטור שבכאן אבל ל' המחבר שבכאן דגובין ממטלטלין א\"א לפרש כן וצ\"ע:"],["\u0003 כשב\"ד נזקקין כו'. \u0004 עיין ביש\"ש פ\"ק דב\"ק סימן ט\"ז פסק דניזקין גובין ממשועבדים אף שלא עמד בדין דיש קול לניזקין וכן משמע בתוס' פ\"ק דב\"ק דף י\"ד ע\"ב לפי' ר\"ת כפי מאי דס\"ל שעבודא דאורייתא וכ\"כ ר' ירוחם נתיב ל\"א ח\"א בסופו וכ\"כ הרב המגיד פי\"ט מה' מלוה בשם יש מפרשים וכ\"כ הסמ\"ע לעיל סי' קי\"ט ס\"ק י\"ד מיהו יש חולקין ועיין מה שכתבתי לעיל סי' ס\"ו סעיף ל\"ה [ע\"ד הסמ\"ע] ס\"ק פ\"ג:","\u0003 גובין מהמטלטלים תחלה כו'. \u0004 כ' הסמ\"ע דהיינו משום דמסתמא ניחא למזיק לשלם במטלטלין מבקרקעות ולמדונו דאף אם אין המזיק לפנינו גובין לו ממטלטלין אבל ודאי אם המזיק גילה דעתו דניחא ליה טפי במטלטלין ורוצה לשלם לו בקרקעות והניזק רוצה דוקא מטלטלין יד המזיק על העליונה ולא דמי למלוה ולוה ולא כב\"י והעיר שושן נמשך אחריו שכתב ז\"ל דאי בעי הניזק מטלטלין צריך המזיק ליתן לו כו' ע\"ש עכ\"ל ואין דבריו נכונים דפשיטא דדעת הרמב\"ם והמחבר כהעיר שושן וכן דעת הטור ושאר הרבה פוסקים וכן עיקר וכמו שאבאר וכן מצאתי בנ\"י ריש פרק המוכר פירות שכ' להדיא שמדברי הרמב\"ם נראה בניזקין אי אית לי' קרקע ומטלטלים כפינן ליה ליתן לו מטלטלים וע\"ש והכי משמע ודאי פשט דברי הרמב\"ם שכתב כשב\"ד נזקקין כו' גובין מהמטלטלים תחלה כו' משמע דעליה דבי דינא רמיא לגבות תחלה מהמטלטלים והדין כך הוא ואינו תלוי ברצון המזיק או הניזק ועוד שכתב שם הרמב\"ם מיד אח\"כ דמדין הש\"ס אם מת והניח מטלטלים וקרקעות גובין מהיתומים מקרקעות וכן הוא בטור ואם איתא דמסתמא ניחא ליה למזיק טפי ליתן מטלטלים נטעון להו ליתמי לטעון מטלטלים והיאך יגרע כח היתומים מן המזיק עצמו ואמת שבהרא\"ש פ\"ק דב\"ק ומרדכי ושאר פוסקים משמע שדעת ר\"ת דאין צריך ליתן לו מטלטלים אלא נותן לו מה שירצה או מקרקעי או מטלטלי וכ\"כ הנ\"י ריש פרק המוכר פירות בשם המפרשים וכן כתבו התוספות ר\"פ המוכר פירות וריש ב\"ק ופ' הפר' דף מ\"ו ריש ע\"ב בשם ר\"ת ומשמע שם שר\"ת מפרש דהא דקאמרינן בש\"ס בב\"ק (דף ט' ע\"א) רב הונא אמר או כסף או מיטב דהיינו שהרשות בידו ליתן לו איזו שירצה אבל לדעת הרמב\"ם נ\"ל לפרש או כסף או מיטב או דינו על כסף היכא דאית לי' מטלטלים או דינו במיטב גבי קרקע היכא דלית לי' מטלטלי ובהא דכסף לא קי\"ל כרב הונא אלא אפי' סובין מיטב נינהו וכן מוכח להדיא מדברי בעל התרומות ריש שער ד' ומבואר שם להדיא ג\"כ דעת רבינו חננאל שהביא שם הך דרב הונא ומאי דשקיל וטרי התם בש\"ס עלי' וכתב ע\"ז וז\"ל וכ' על זה ר\"ח ז\"ל מהכא שמעינן דלא מסלקינן לב\"ח בארעא אלא היכא דקים לן דלית ליה זוזי למפרע מיניה כו' עכ\"ל ודלא כס' גידולי תרומה שם דף כ\"ז ע\"א שתמה הרבה על דברי ר\"ח והניחם בצ\"ע והדבר ברור דר\"ח מפרש כדפי' וכן נראה להדיא מדברי ראב\"ן ריש ב\"ק ע\"ש בדף פ\"ה ע\"א וכן מוכח מדברי הרמ\"ה שהביא הנ\"י ריש ב\"ק גבי מ\"ש שכל הפוסקים פסקו הלכה כרב פפא ורב הונא ברי' דרב יושיע וכ' הרמ\"ה כו' ע\"ש דמוכח דס\"ל לרמ\"ה גם כן דהיכא דאית ליה למזיק מטלטלים וקרקעות כפינן ליה למיתב מטלטלים כמו גבי ב\"ח:","וכן משמע פשט דברי הטור דדין הוא לגבות מהמטלטלים אפי' בע\"כ של מזיק ובמ\"ש ב\"י והיינו שכתב גם כן מיד אח\"כ דאם מת המזיק מגבינן מן הקרקעות של היתומים ולא מן המטלטלים מדינא דש\"ס ואי הברירה ביד המזיק אמאי כשמת יגרע כח היתומים וכמ\"ש לעיל. והב\"ח כ' דע\"כ לא קאמר הרא\"ש הכי אלא בבעל חוב אבל בניזקין אין הניזק יכול לכופו לגבות מהמטלטלים אם רוצה ליתן לו קרקע וכן דעת הטור ודלא כב\"י אלא יד המזיק על העליונה וכן מפורש בדברי הרב המגיד רפ\"א דחובל ובפ\"ח דהלכות נזקי ממון עכ\"ל ולפעד\"נ כמ\"ש הב\"י ואף שלכאורה משמע בהרא\"ש דכתב כן דוקא בב\"ח מ\"מ נראה דהא דכתב כן בב\"ח היינו אפי' לר\"ת אבל למה שכתב הרא\"ש שם דדברי רב אלפס עיקר הרי אלפס לא כתב שהבריר' ביד המזיק וגם נראה כיון דלרב אלפס אפי' יש לו מעות יכול לסלקו בסובין א\"כ הא דכתב קרא ישיב לרבות שוה כסף היינו דגלי לן קרא דעיקר גביה על המטלטלים הוא א\"כ לא מסתברא שיהא הברירה ביד המזיק כיון דגלי לן קרא דעיקר גביה במטלטלים היא אפי' אית ליה כסף גם מ\"ש הב\"ח בדעת הרב המגיד ליתא וכמ\"ש לקמן:","ועוד נ\"ל כן עיקר ממאי דגרסינן בש\"ס פ\"ב דב\"ק (דף י\"ד ע\"ב) על פסקא דשוה כסף רמי ליה רב יודא בר חנניא לרב הונא בריה דרב יושיע תנא שוה כסף ככסף מלמד שאין ב\"ד נזקקין אלא לנכסי' שיש להן אחריות והתניא ישיב לרבות שוה כסף ואפי' סובין הכא במאי עסקינן ביתמי ע\"כ ומייתי לה הרי\"ף אלמא דמעיקרא ס\"ד דב\"ד נזקקין לקרקע ומסיק דנזקקין לגבות ממטלטלי ואין ספק שמכאן הוציא הרמב\"ם את דבריו והיינו שכ' כשב\"ד נזקקין כו' כ' לשון נזקקין כל' הש\"ס שהוציא משם דבריו וכן כ' הרב המגיד להדיא בפ\"ח מה' נזקי ממון וז\"ל כשב\"ד נזקקין כו' מבואר פ\"ק בסוגיא על פיסקא דשוה כסף וכן למעל' באותו פרק מחלוקת אמוראין ופסק רבינו כר\"פ ורב הונא בריה דרב יושיע וכ\"ד ההלכות עכ\"ל ודבריו ברורים וליכא למימר דמעיקרא ס\"ד דנזקקין לקרקע ואין נזקקין למטלטלין כלל אפי' אין לו קרקע וכ\"מ לכאורה מפרש\"י שכ' אין ב\"ד נזקקין ליפרע מן המזיק אא\"כ יש לו קרקע כו' וא\"כ כי משני הכא ביתמי י\"ל דבדידי' כשיש לו מטלטלי לבד חייב ליתן לו אבל אה\"נ אם יש לו מטלטלי וקרקע הבריר' ביד המזיק דהיאך נא' דקס\"ד מעיקרא אפי' יהיה לו מטלטלים לא יצטרך לשלם לו כלום אם אין לו קרקע וכי בשביל שלא יהיה לו קרקע יפטר מלשלם ועוד דא\"כ לא שבקת חיי לכל בריה דכל מי שלא יהיה לו קרקע יזיק לבריות מה שירצה ויפטר מלשלם ועוד דהא לעיל (בדף ט' ע\"א) אהא דקאמר רב הונא ישיב אפי' סובין מיירי בדלית ליה אלא סובין פריך אי דלית ליה פשיטא ומשני מהו דתימא אמרינן ליה זיל טרח וזבן קמ\"ל אלמא דאינו עולה על הדעת כלל דכשאין לו רק סובין שלא יצטרך לשלם לו סובין אלא ודאי דמעיקרא סבר דב\"ד נזקקין לגבות מן הקרקע בע\"כ של מזיק דשוה כסף היינו קרקע ומסיק דב\"ד נזקקין לגבות מהמטלטלים בע\"כ של מזיק דשוה כסף היינו מטלטלים. ודקדקתי היטב בסוגיא זו לפרשה בדרכים אחרים והתבוננתי שא\"א לפרשה כי אם כמו שכתבתי אם לא ע\"פ דוחק גדול לכן העיקר כמ\"ש ודוק היטב. ומעתה גם מ\"ש הב\"ח שכך מפורש בדברי הרב המגיד רפ\"א מה' חובל ופ\"ח מה' נזקי ממון שיד המזיק על העליונה ליתא דהמעיין שם בדברי הרב המגיד יראה דאדרבא יותר נראה מדברי הרב המגיד כמ\"ש וגם בר\"פ א' מהל' מלוה נראה מהרב המגיד כמ\"ש ע\"ש: ועוד נראה כיון דבבעל חוב קי\"ל לעיל סי' ק\"א דמחויב ליתן לו מטלטלים כשיש לו ואין צריך המלוה ליקח קרקע א\"כ למה נימא דניזקין שאני דהא אדרבא ניזקין עדיפי דגובה מהעידית ואף שיש לחלק כמו היכי דיש לו מעות דאין צריך המזיק ליתן לו מעות ונמצא המזיק עדיף בזה מלוה היינו משום דגלי לן קרא גבי מזיק ישיב אפי' סובין ולא גלי לן הכי גבי ב\"ח א\"כ מסתבר דב\"ח דיהיב ליה זוזי צריך למפרע ליה בזוזי אבל בהא שיגבה תחלה מן מטלטלים בע\"כ של החייב אין סברא לחלק בין ב\"ח למזיק ודוק:","\u0003 ואפי' שיש לו כסף יכול לסלקו בסובין. \u0004 כלומר אפי' יש לו מעות א\"צ ליתן לו מעות ונותן לו מהפחות שבמטלטלים משא\"כ בב\"ח לעיל סימן ק\"א והיינו כהרי\"ף והרא\"ש והרמב\"ם שפסקו כרב פפא ורב הונא בריה דר' יושיע ולא כר\"ת (וכ\"כ בעל הטור ברמזי הרא\"ש שם דלית הלכתא כר\"ת וקאי אניזקין ודלא כב\"י לעיל ר\"ס ק\"א שכ' שמ\"ש ברמזי הרא\"ש הוא כשגגה דליתא דהמעיין שם יראה להדיא דקאי אניזקין רק שיש שם קצת ט\"ס ברמזים שלפנינו כנראה לכל מעיין בנקל והדבר ברור כמו שהוא בנוסחות הרמזים הישנים וכמו שהביא בספר מעד\"מ ברמזים שם ע\"ש): אך מ\"ש הרא\"ש שם ונראה דברי רב אלפס עקר דרב כהנא תלמידו דרבא דבתרא' הוא סבר כרב פפא ור' הונא בריה דרב יהושע דאמר לקמן א\"ל רב כהנא לרבא טעמא דכתב רחמנא והמת יהיה לו הא לאו הכי ה\"א נבלה דמזיק הוי השתא אי אית ליה לדידיה יהיב לי' דאמר מר ישיב לרבות שוה כסף אפי' סובין נבלה דידיה מבעיא ואם איתא לדרב הונא לימא ליה דאצטריך קרא היכא דאית ליה כסף או מיטב עכ\"ל לא ירדתי לסוף דעתו דלא מצינו בשום מקום דרב כהנא היה תלמידו דרבא אלא משמע בכמה דוכתי דרב כהנא היה תלמידו דרב וכדאיתא נמי בפרק אחד דיני ממונות (סנהדרין דף ל\"ו ריש ע\"ב) כי קאמר רב כגון [רב] כהנא ורב אסי דלגמריה דרב הוי צריכי כו' וכן בכמה דוכתי וכן הוא לקמן בכל ספרי הש\"ס (סוף ד\"י) א\"ל רב כהנא לרב טעמא דכתב רחמנא והמת יהיה לו כו' ואין ספק שנוסחא מוטעת מזדמנא להרא\"ש בכאן בש\"ס ועוד קשה לי על הרא\"ש הא רב פפא ורב הונא בריה דרב יהושע הוו בתראי טפי מרבא. וזהו עיקר הטעם שפסק הרי\"ף כרב פפא ורב הונא ברי' דרב יושיע דבתראי נינהו ואין צריך טעם יותר דמ\"ש הרא\"ש מתחל' בדעת ר\"ת דרב פפא ורב הונא בריה דרב יהושע לא פליגי ארב הונא ודאי נדח' מהא דקאמר רב כהנא לרב טעמא דכתב רחמנא והמת יהיה לו כו' דא\"כ לא הוי פריך מידי דקרא מיירי היכ' דאית ליה כסף וגם בתוספות פרק הפרה דף מ\"ו ריש ע\"ב ושאר פוסקים מבואר דאף ר\"ת ס\"ל דפליגי. וגם מ\"ש הרא\"ש דהטעם ר\"ת היא כיון דהש\"ס קאי לדרב הונא באחרונה חשיב ליה עיקר אף שיכול להיות שדעת ר\"ת כן מ\"מ אין ראיה כ\"כ מזה וק\"ל וכבר האריך מהרש\"ל פ\"ק דב\"ק סי' כ\"א בזה להוכיח דקי\"ל כרב פפא ורב הונא בריה דרב יושיע וכ\"כ בנ\"י שכ\"פ כל המפרשים ז\"ל וכן עיקר. אך כתב הנ\"י שם שכתב הרמ\"ה ז\"ל דהא דמצי יהיב ליה אפי' סובין ה\"מ היכא דלית ליה למזיק זוזי כו' וע\"ש בגליון האלפסי של מהר\"ם מטיקאטין שתמה על זה דהא לרב פפא ורב הונא בריה דר\"י אפי' אית ליה כסף יכול לסלקו בסובין ול\"נ שדעת הרמ\"ה דכסף שאני וכן מדוקדק בלשונו שם ע\"ש אך דעת כל הפוסקי' מבואר דכסף היינו זוזי ואפי' אית ליה זוזי יכול לסלקו בסובין והכי מוכח נמי מהך דא\"ל רב כהנא לרב טעמא דכתב רחמנא והמת יהיה לו כו' ואי איתא דהיכא דאית ליה זוזי צריך לסלקו בזוזי לא הוה פריך מידי דדלמא קרא איירי בדאית לי' זוזי א\"ו כסף היינו זוזי כמו אם כסף תלוה וכן עיקר:","מיהו היכא דהמזיק רוצה לסלקו במעות ודאי אין צריך ליתן לו מטלטלי או קרקעות שלו ופשוט הוא:","\u0003 צריך ליתנה לו כפי מה כו'. \u0004 והעיר שושן חולק על זה ועיין בספר מגדל דוד ובסמ\"ע ס\"ק ד' מה שהשיגו עליו ואין דבריהם מוכרחים ודברי הע\"ש יותר נכונים. ומהרש\"ל פ\"ק דב\"ק סי' י\"א חולק בכל הסעיף וכתב דהניזק לעולם גובה מעידית המזיק אפי' עידי עידית שהוא רוצה מאחר שדינו ממיטב ומ\"מ לפי ראות עיני הדייני' שאם יראו שזאת טובה לניזק וזאת טובה למזיק זהו בכלל ועשית הישר והטוב כו' וע\"ש:","\u0003 מגבין לניזק מהמטלטלים של יתומים \u0004 רבינו אפרים השיב על הרי\"ף בזה דניזקין מלתא דלא שכיחא היא וכי תקנו הגאונים לב\"ח משום נעילת דלת בפני לווין אי נמי לאשה משום פריה ורביה אבל לניזקין לא תקון והרא\"ש כ' וז\"ל ונ\"ל דבדורות הללו מטלטלי כמקרקעי לכל מילי שעבוד מדינ' דש\"ס אף בלא תקנה דהוי כגמלי דערביא ואשלי דקמחוניא דקאמר בכתובות אשה גובה פורנא מהם עכ\"ל וכן מסקנת הטור ולפי עניות דעתי אין דברי הרא\"ש מוכרחים בזה דהא דאמרי' בכתובות בפרק מציאת אשה (כתובות דף ס\"ז ע\"א) אשה גובה פורנא מהם היינו דוקא בכתובה דאש' סמכ' דעתה עלייהו ומתחלה כשנשאת לזה אדעתא דהכי נשאת שתגבה ממטלטלי כיון שעיקר משא ומתן שלהם היה במטלטלים וזה לא שייך בניזקין. ומ\"מ דעת רוב הפוסקים כהרי\"ף והרמב\"ם והמחב' דהאידנא אף נזקין גובין ממטלטלי' דיתמי וכ\"כ מהרש\"ל פ\"ק דב\"ק סי' ל\"ט וע\"ש:","\u0003 מהמטלטלי' של יתומים. \u0004 משמע דהיינו אפילו יש להן קרקע מיהו היינו מן הסת' אבל אם היתומי' רוצים לסלקו בקרקע הרשות בידם דבכה\"ג לא תקנו הגאונים וכדלעיל סי' ק\"ז סעיף א' גבי ב\"ח וכ\"ש הכא ועמ\"ש שם וכן כ' בשלטי גבורים פ' חזקת הבתים דף קפ\"ד ע\"א ע\"ש:","\u0003 שכל הבא ליפרע מיתומים כו'. \u0004 משמע אפילו גדולים וכן נראה דעת הרמב\"ם ודלא כהסמ\"ע לדעתו ועמש\"ל סוף סי' ק\"ח מזה:"]],["\u0003הלכות חובל בחבירו\u0004\nאָסוּר לְאָדָם לְהַכּוֹת חֲבֵרוֹ; וְאִם הִכָּהוּ עוֹבֵר בְּלָאו, \u0010y0\u0011 שֶׁנֶּאֱמַר: פֶּן יֹסִיף \u0005(דְּבָרִים כה, ג)\u0006. וְאִם הִקְפִּידָה תּוֹרָה \u0010y1\u0011 בְּהַכָּאַת רָשָׁע שֶׁלֹּא לְהַכּוֹתוֹ יוֹתֵר עַל רִשְׁעוֹ, קַל וָחֹמֶר בְּהַכָּאַת צַדִּיק. וְהַמֵּרִים יַד עַל חֲבֵרוֹ לְהַכּוֹתוֹ, \u0010y2\u0011 אַף עַל פִּי שֶׁלֹּא הִכָּהוּ, נִקְרָא רָשָׁע. \u0005הַגָּה: וְעַיֵּן לְקַמָּן סִימָן תכ\"א סָעִיף י\"ג. וְדִין הַכָּאַת אִישׁ לְאִשְׁתּוֹ, עַיֵּן בְּאֶבֶן הָעֵזֶר סִימָן קנ\"ד. \u0010y3\u0011 דְּיֵשׁ אוֹמְרִים דְּיֵשׁ חֵרֶם קַדְמוֹנִים בְּאָדָם הַמַּכֶּה לַחֲבֵרוֹ, וּצְרִיכִין לְהַתִּיר לוֹ כְּדֵי לְצָרְפוֹ לְמִנְיָן עֲשָׂרָה, וּמִיָּד שֶׁמְּקַבֵּל עָלָיו לַעֲשׂוֹת דִּין, מַתִּירִין לוֹ אַף עַל פִּי שֶׁאֵין (הַמֻּכֶּה)\u0006 מִתְרַצֶּה \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק והג\"מ פֶּרֶק הַחוֹבֵל)\u0006.\nהִכָּהוּ מַכָּה שֶׁאֵין בָּהּ שְׁוֵה פְרוּטָה, לוֹקֶה, \u0010y4\u0011 כֵּיוָן שֶׁאֵין בָּהּ חִיּוּב מָמוֹן. וַאֲפִלּוּ הִכָּה \u0010y5\u0011 \u0010c0\u0011 עֶבֶד כְּנַעֲנִי, לוֹקֶה הוּא, שֶׁהֲרֵי חַיָּב בְּמִצְוֹת.\nהַחוֹבֵל \u0010y6\u0011 \u0010c1\u0011 בַּחֲבֵרוֹ, חַיָּב בַּחֲמִשָּׁה דְבָרִים: נֶזֶק, צַעַר, רִפּוּי, שֶׁבֶת, בֹּשֶׁת; אִם הַחַבָּלָה בְּעִנְיָן שֶׁיֵּשׁ בָּהּ כָּל הֶחָמֵשׁ. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּצָרִיךְ לִתֵּן גַּם כֵּן תּוֹסָפוֹת מְזוֹנוֹת הַצְּרִיכִין בְּחָלְיוֹ מִמַּה שֶׁהָיָה אוֹכֵל כְּשֶׁהָיָה בָּרִיא (נִמּוּקֵי יוֹסֵף פֶּרֶק הַחוֹבֵל)\u0006, וְנִרְאֶה לִי, דְבִכְלָל רִפּוּי יֵחָשֵׁב. וְאִם אֵין בָּהּ אֶלָּא ד', מְשַׁלֵּם ד'; וְאִם ג', ג'; וְאִם ב', ב'; וְאִם א', א'.\nכֵּיצַד, קָטַע יָדוֹ אוֹ רַגְלוֹ אוֹ אֶצְבַּע אַחַת, אוֹ שֶׁחִסְרוֹ אֶחָד מִכָּל אֵבָרָיו, נוֹתֵן לוֹ כָּל ה' הַדְּבָרִים.\nהִכָּהוּ \u0010y7\u0011 עַל יָדוֹ וְצָבְתָה וְסוֹפָהּ לַחֲזֹר, אוֹ הִכָּהוּ עַל עֵינוֹ וּמָרְדָה וְסוֹפָהּ לַחֲזֹר, אֵין כָּאן נֶזֶק, וְנוֹתֵן לוֹ שְׁאָר אַרְבַּע דְּבָרִים.\nהִכָּהוּ עַל רֹאשׁוֹ וְצָבְתָה, אֵין כָּאן נֶזֶק וְשֶׁבֶת, וְנוֹתֵן לוֹ שְׁאָר הַשְּׁלֹשָׁה דְבָרִים. \u0010y8\u0011\nהִכָּהוּ בְּמָקוֹם שֶׁאֵינוֹ נִרְאָה, וְלֹא רָאָהוּ שׁוּם אָדָם, אֵינוֹ נוֹתֵן לוֹ אֶלָּא צַעַר וְרִיפּוּי.\nהִכָּהוּ בְּמִטְפַּחַת שֶׁבְּיָדוֹ אוֹ בִּשְׁטָר וְכַיּוֹצֵא בְּזֶה, אֵין כָּאן אֶלָּא בֹּשֶׁת. \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁהוּא בִּמְקוֹם רוֹאִין (הָרַאֲבַ\"ד)\u0006.\nכְּוָאוֹ בְּשַׁפּוּד עַל צִפָּרְנוֹ, בְּמָקוֹם שֶׁאֵינוֹ עוֹשֶׂה חַבּוּרָה וְאֵינוֹ מְעַכְּבוֹ מִמְּלָאכָה, אֵינוֹ נוֹתֵן אֶלָּא צַעַר. \u0005וְאִם הָיָה בִּמְקוֹם רוֹאִין, חַיָּב בְּבֹשֶׁת (המ\"מ שם)\u0006.\nהִשְׁקָהוּ סַם, אוֹ שֶׁסָכוֹ סַם, וְשִׁנָּהוּ מִמַּרְאֵה עוֹרוֹ, אֵינוֹ מְשַׁלֵּם לוֹ \u0010y9\u0011 אֶלָּא רִפּוּי בִּלְבַד.\nהִכְנִיסוֹ בְּחֶדֶר וְסָגַר הַדֶּלֶת עָלָיו וּבִטְּלוֹ מִמְּלַאכְתּוֹ, אֵינוֹ נוֹתֵן לוֹ אֶלָּא שֶׁבֶת בִּלְבַד. אֲבָל אִם הָיָה כְּבָר בְּחֶדֶר וְסָגַר עָלָיו מִלָּצֵאת, \u0010y10\u0011 הָוֵי גְרָמָא בְּנִזָּקִין וּפָטוּר מִדִּינֵי אָדָם.\nגִּלַּח שְׂעַר רֹאשׁוֹ, אֵינוֹ נוֹתֵן לוֹ \u0010y11\u0011 אֶלָּא בֹּשֶׁת. סָכוֹ בְּסַם עַד שֶׁאֵין סוֹף הַשֵּׂעָר לַחֲזֹר, חַיָּב בְּה' דְּבָרִים, \u0010y12\u0011 שֶׁהֲרֵי מִצְטַעֵר מִן הַסַם, וְשֶׁבֶת שֶׁהֲרֵי הוּא רָאוּי לְרַקֵּד \u0010y13\u0011 וּלְנַדְנֵד \u0005(שְׂעַר)\u0006 רֹאשׁוֹ בִּשְׁעַת רִקּוּד, וְנִמְצָא בָּטֵל מִמְּלָאכָה זוֹ.\nהַמְחַסֵר אֶת חֲבֵרוֹ אֵבֶר שֶׁאֵינוֹ חוֹזֵר, חַיָּב בְּכָל הַה' דְּבָרִים. אֲפִלּוּ הִפִּיל שִׁנּוֹ, חַיָּב בַּכֹּל, שֶׁאִי אֶפְשָׁר שֶׁלֹּא יֶחֱלֶה פִיו שָׁעָה אַחַת; אַף עַל פִּי שֶׁהַשֵּׁן אֵין לוֹ רְפוּאָה, בְּשַׂר הַשִּׁנַּיִם צָרִיךְ רְפוּאָה.\nאֲפִלּוּ חִסְרוֹ כִּשְׂעוֹרָה מֵעוֹר בְּשָׂרוֹ, חַיָּב בְּה' דְּבָרִים, שֶׁהָעוֹר אֵינוֹ חוֹזֵר \u0010y14\u0011 אֶלָּא צַלֶּקֶת \u0005(פֵּרוּשׁ, רֹשֶׁם מַכָּה שֶׁנִּתְרַפְּאָה)\u0006. לְפִיכָךְ, הַחוֹבֵל בַּחֲבֵרוֹ וְקָרַע הָעוֹר וְיָצָא מִמֶּנּוּ דָם, חַיָּב בְּה' דְּבָרִים.\nכֵּיצַד מְשַׁעֲרִים הַה' דְּבָרִים, נֵזֶק אִם חִסְרוֹ אֵבֶר אוֹ חָבַל חַבּוּרָה שֶׁאֵין סוֹפָהּ לַחֲזֹר שָׁמִין אוֹתוֹ \u0010y15\u0011 כְּאִלּוּ הוּא עֶבֶד נִמְכָּר בַּשּׁוּק, כַּמָּה הָיָה שָׁוֶה קֹדֶם שֶׁחָבַל בּוֹ וְכַמָּה נִפְחֲתוּ דָמָיו אַחַר הַחַבָּלָה, וְכָךְ יִתֵּן לוֹ. \u0005הַגָּה: \u0010c2\u0011 וְאִם הָיָה בַּעַל אֻמָּנוּת, כְּגוֹן נוֹקֵב מַרְגָלִיּוֹת, וְקָטַע לוֹ יָדוֹ, מְשַׁעֲרִינָן הֶזֵּיקוֹ כְּפִי מַה שֶּׁהוּא. אֲבָל אִם קָטַע רַגְלוֹ, \u0010y16\u0011 שֶׁאֵין מַזִּיק לוֹ כָּל כָּךְ, מְשַׁעֲרִינָן הֶזֵּקוֹ כְּאִלּוּ לֹא הָיָה בַּעַל אֻמָּנוּת (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nצַעַר כֵּיצַד, הֲרֵי שֶׁקָּטַע אֶצְבָּעוֹ, אוֹמְדִים כַּמָּה אָדָם רוֹצֶה לִתֵּן בֵּין לִקְטֹע לוֹ אֵבֶר זֶה בְּסַיִף אוֹ לִקְטֹעַ אוֹתוֹ בְּסַם, \u0010y17\u0011 אִם גָּזַר הַמֶּלֶךְ לִקְטֹעַ אֵבֶר \u0005בְּסַיִף,\u0006 וּמַה שֶּׁיֵּשׁ בֵּין זֶה לְזֶה מְשַׁלֵּם לוֹ. \u0005הַגָּה: וּבְמָקוֹם דְּאִכָּא צַעַר לְחוּד, מְשַׁעֲרִין \u0010y18\u0011 אִם הָיָה גּוֹזֵר הַמֶּלֶךְ לִכְווֹת אוֹתוֹ בְּשַׁפּוּד עַל צִפָּרְנוֹ וְכַדּוֹמֶה, כַּמָּה הָיָה נוֹתֵן לְהִנָּצֵל מִצַּעַר זֶה (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nכֵּיצַד מְשַׁעֲרִין הַשֶּׁבֶת, אִם לֹא חִסְרוֹ אֵבֶר אֶלָּא חָלָה וְנָפַל לְמִשְׁכָּב, אוֹ צָבְתָה יָדוֹ וְסוֹפָהּ לַחֲזֹר, נוֹתֵן לוֹ שִׁבְתּוֹ שֶׁל כָּל יוֹם וָיוֹם \u0010y19\u0011 כְּפוֹעֵל בָּטֵל שֶׁל אוֹתָהּ מְלָאכָה שֶׁבָּטַל מִמֶּנָּה. וְאִם חִסְרוֹ אֵבֶר, כְּגוֹן שֶׁקָּטַע יָדוֹ, נוֹתֵן לוֹ דְּמֵי יָדוֹ שֶׁהוּא הַנֶּזֶק, וְשֶׁבֶת רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא שׁוֹמֵר קִשּׁוּאִין, וְרוֹאִין כַּמָּה הוּא שְׂכַר שׁוֹמֵר קִשּׁוּאִים בְּכָל יוֹם, וְעוֹשִׂין חֶשְׁבּוֹן כָּל יְמֵי חָלְיוֹ שֶׁל זֶה וְנוֹתֵן לוֹ. וְכֵן אִם קָטַע רַגְלוֹ, רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא שׁוֹמֵר עַל הַפֶּתַח. סִמָּא אֶת עֵינוֹ, רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא טוֹחֵן בְּרֵחַיִם; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: וְדַוְקָא בִּסְתָם בְּנֵי אָדָם שֶׁאֵינָן בְּנֵי אֻמָּנוּת, אֲבָל אִם הוּא בֶּן אֻמָּנוּת וְיָכוֹל לַעֲסֹק בִּמְלַאכְתּוֹ אַחַר חָלְיוֹ, מְשַׁעֲרִין הַשֶּׁבֶת כְּפִי הַמְּלָאכָה דְבָטֵל מִנֵּהּ (טוּר סי\"ט בְּשֵׁם הָרֹא\"שׁ)\u0006.\nכֵּיצַד מְשַׁעֲרִין הָרִיפּוּי, אוֹמְדִים בְּכַמָּה יָמִים יִחְיֶה מֵחֹלִי זֶה, וְכַמָּה הוּא צָרִיךְ, וְנוֹתֵן לוֹ מִיָּד; וְאֵין מְחַיְּבִים אוֹתוֹ לָתֵת דְּבַר יוֹם בְּיוֹמוֹ, \u0010y20\u0011 וְדָבָר זֶה תַּקָּנָה הִיא לַמַּזִּיק. וְכֵן הַשֶּׁבֶת אוֹמְדִין אוֹתוֹ וְנוֹתֵן הַכֹּל מִיָּד; אִם הָיָה מִתְגַּלְגֵּל בְּחָלְיוֹ וְהוֹלֵךְ, וְאָרַךְ הַחֹלִי יוֹתֵר עַל מַה שֶּׁאֲמָדוּהוּ, אֵינוֹ מוֹסִיף לוֹ כְּלוּם; וְכֵן אִם הִבְרִיא מִיָּד, אֵין פּוֹחֲתִין מִמַּה שֶׁאֲמָדוּהוּ:\nאָמַר הַמַּזִּיק: אֵין רְצוֹנִי בְּתַקָּנָה זוֹ אֶלָּא אֶרְפָּאֶנּוּ דְּבַר יוֹם בְּיוֹמוֹ, שׁוֹמְעִין לוֹ. \u0010y21\u0011 הֲרֵי שֶׁלֹּא פָּסַק עִמּוֹ אֶלָּא הָיָה מְרַפֵּא יוֹם יוֹם, וְעָלוּ בּוֹ צְמָחִים מֵחֲמַת הַמַּכָּה, אוֹ נִסְתְּרָה הַמַּכָּה אַחֲרֵי שֶׁחָיְתָה, חַיָּב לְרַפּאוֹתוֹ וְלָתֵת לוֹ דְּמֵי שִׁבְתּוֹ; עָלוּ בּוֹ צְמָחִים \u0010y22\u0011 שֶׁלֹּא מַחֲמַת הַמַּכָּה, אֵינוֹ חַיָּב לְרַפּאוֹתוֹ וְלֹא לָתֵת לוֹ דְּמֵי שִׁבְתּוֹ.\nעָבַר עַל דִּבְרֵי הָרוֹפֵא וְהִכְבִּיד עָלָיו הַחֹלִי, אֵינוֹ חַיָּב לְרַפּאוֹתוֹ.\nאָמַר לוֹ הַמַּזִּיק: אֲנִי אֲרַפֵּא אוֹתְךָ, אוֹ: יֵשׁ לִי רוֹפֵא שֶׁמְּרַפֵּא בְּחִנָּם, \u0010y23\u0011 אֵין שׁוֹמְעִין לוֹ, אֶלָּא מֵבִיא רוֹפֵא אֻמָּן וּמְרַפְּאוֹ בְּשָׂכָר:\nאִם יֹאמַר הַמַּזִּיק: אָבִיא לְךָ רוֹפֵא מִמָּקוֹם רָחוֹק שֶׁיִּקַּח שָׂכָר מוּעָט, יָכוֹל הַנֶחְבָּל לוֹמַר לוֹ: הָרוֹפֵא שֶׁהוּא בִּמְקוֹמוֹ מְדַקְדֵּק יוֹתֵר, שֶׁלֹּא יַפְסִיד הַמְחָאָתוֹ.\nאָמַר הַנֶחְבָּל: תֵּן לִי שְׂכַר הָרוֹפֵא וַאֲנִי אֲרַפֵּא אֶת עַצְמִי, יָכוֹל הַחוֹבֵל לוֹמַר לוֹ: שֶׁמָּא לֹא תְּרַפֵּא עַצְמְךָ יָפֶה וְיִקְרְאוּ אוֹתִי מַזִּיק לְעוֹלָם.\nכֵּיצַד מְשַׁעֲרִין הַבֹּשֶׁת, הַכֹּל לְפִי הַמְבַיֵּשׁ וְהַמִּתְבַּיֵּשׁ; אֵינוֹ דוֹמֶה מִתְבַּיֵּשׁ מֵהַקָּטָן לַמִּתְבַּיֵּשׁ מֵאָדָם גָּדוֹל \u0010y24\u0011 וּמְכֻבָּד, שֶׁזֶּה שֶׁבִּיְּשׁוֹ הַקַּל בָּשְׁתּוֹ מְרֻבָּה. \u0005הַגָּה: וְכֵן הַמִּתְבַּיֵּשׁ, כְּפִי מַה שֶּׁכְּבוֹדוֹ גָדוֹל בָּשְׁתּוֹ מְרֻבָּה (טוּר)\u0006. וְהַמְבַזֶּה כֹּהֵן, בָּשְׁתּוֹ יוֹתֵר גְּדוֹלָה מִבְּאִישׁ אַחֵר \u0005(רִיבָ\"שׁ סִימָן נ\"ד)\u0006.\nצָעַק בְּאָזְנוֹ וְחֵרְשׁוֹ, \u0010y25\u0011 פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. אָחֲזוֹ \u0010y26\u0011 וְתָקַע בְּאָזְנוֹ וְחֵרְשׁוֹ, אוֹ שֶׁהִכָּהוּ בְּאָזְנוֹ וְחֵרְשׁוֹ, נוֹתֵן לוֹ דְּמֵי כֻּלּוֹ אִם אֵינוֹ בַּעַל אֻמָּנוּת. וְאִם הוּא בַּעַל אֻמָּנוּת וְרָאוּי עֲדַיִן לְאוֹתוֹ אֻמָּנוּת, רוֹאִים כַּמָּה נִפְחֲתוּ דָמָיו וְנוֹתֵן לוֹ.\nסִמָּא עֵינוֹ וְלֹא אֲמָדוּהוּ, \u0005(קָטַע יָדוֹ וְלֹא אֲמָדוּהוּ)\u0006, וְקָטַע רַגְלוֹ וְלֹא אֲמָדוּהוּ, וְאַחַר כָּךְ חֵרְשׁוֹ, הוֹאִיל וְלֹא אֲמָדוּהוּ מִכָּל נֶזֶק וָנֶזֶק, \u0010y27\u0011 נוֹתֵן לוֹ דְּמֵי כֻּלּוֹ. \u0005הַגָּה: וּמְחֻיָּב לִתֵּן צַעַר וְרִפּוּי וּבֹשֶׁת שֶׁל כָּל מַכָּה וּמַכָּה, רַק שֶׁאוֹמְדִים הַכֹּל בְּיַחַד (טוּר סי\"ז בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010y28\u0011 אֲמָדוּהוּ לְכָל נֶזֶק וָנֶזֶק, וְאַחַר כָּךְ אֲמָדוּהוּ לְכֻלּוֹ, אֵין גּוֹבִין מִמֶּנּוּ אֶלָּא דְּמֵי כֻּלּוֹ בִּלְבַד. \u0010y29\u0011 וְאִם תָּפַס הַנִּזָּק נֶזֶק כָּל אֵבֶר וְאֵבֶר וּדְמֵי כֻלּוֹ, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: וּכְבָר נִתְבָּאֵר סִימָן שפ\"ח דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא מְהַנֵּי תְפִיסָה (הָרֹא\"שׁ וְהַטּוּר)\u0006.\nכְּשֶׁבֵּית דִּין מַגְבִּין לַנֶּחְבָּל אַרְבָּעָה דְבָרִים, \u0010c3\u0011 אֵין נוֹתְנִים לַחוֹבֵל בָּהֶם שׁוּם זְמַן. אֲבָל אִם לֹא עָשָׂה בּוֹ דָּבָר \u0010y30\u0011 אֶלָּא שֶׁבִּיְּשׁוֹ, נוֹתְנִים לוֹ זְמַן כֵּיוָן שֶׁלֹּא חִסְרוֹ מָמוֹן. \u0010y31\u0011\nכְּשֵׁם שֶׁאוֹמְדִים לְמִיתָה, כָּךְ אוֹמְדִים לִנְזִיקִין. כֵּיצַד, הֲרֵי שֶׁהִכָּה \u0010y32\u0011 חֲבֵרוֹ בִּצְרוֹר קָטָן שֶׁאֵין בּוֹ כְּדֵי לְהַזִּיק, אוֹ בְּקֵיסָם שֶׁל עֵץ קָטָן, וְחָבַל בּוֹ חַבָּלָה שֶׁאֵין חֵפֶץ זֶה רָאוּי לַעֲשׂוֹתוֹ, \u0010y33\u0011 הֲרֵי זֶה פָטוּר, שֶׁנֶּאֱמַר: בְּאֶבֶן אוֹ בְאֶגְרֹף \u0005(שְׁמוֹת כא, יח)\u0006, דָּבָר הָרָאוּי לְהַזִּיק; \u0010y34\u0011 אֲבָל חַיָּב הוּא בְּבֹשֶׁת בִּלְבַד, שֶׁאֲפִלּוּ רָקַק בְּגוּפוֹ שֶׁל חֲבֵרוֹ חַיָּב בְּבֹשֶׁת; לְפִיכָךְ צְרִיכִים הָעֵדִים לֵידַע בַּמֶּה הִזִּיק, וּמְבִיאִים הַחֵפֶץ שֶׁהִזִּיק בּוֹ לְבֵית דִּין, עַד שֶׁאוֹמְדִין אוֹתוֹ וְדָנִין עָלָיו. וְאִם אָבַד הַחֵפֶץ, וְאָמַר הַחוֹבֵל: לֹא הָיָה בּוֹ כְּדֵי לְהַזִּיק, וְנֶחְבָּל אוֹמֵר: הָיָה בּוֹ כְּדֵי לְהַזִּיק, \u0010y35\u0011 יִשָּׁבַע הַנֶּחְבָּל \u0010y36\u0011 וְיִטֹּל.\nהַבַּרְזֶל, אֵין לוֹ אֹמֶד; אֲפִלּוּ מַחַט קְטַנָּה רְאוּיָה הִיא לְהָמִית, וְאֵין צָרִיךְ לוֹמַר לְהַזִּיק. וְדַוְקָא כְּעֵין מַחַט, שֶׁהִיא חַדָּה, אֲבָל אִם לֹא הִזִּיק אֶלָּא מֵחֲמַת מִשְׁקָלוֹ, \u0010y37\u0011 שֶׁאֵינוֹ מְחֻדָּד כְּלָל, אוֹמְדִים אוֹתוֹ כִּשְׁאָר דְּבָרִים.\nהַזּוֹרֵק אֶבֶן, וּלְאַחַר שֶׁיָּצְאָה מִתַּחַת יָדוֹ הוֹצִיא הֲלָה רֹאשׁוֹ מֵהַחַלּוֹן וְקִבְּלָהּ, פָּטוּר מִכֻּלָּם, שֶׁנֶּאֱמַר: וּמָצָא אֶת רֵעֵהוּ \u0005(דְּבָרִים יט, ה)\u0006, פְּרָט לְמַמְצִיא אֶת עַצְמוֹ.\nהַחוֹבֵל בְּעַצְמוֹ, אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי, \u0005(פָּטוּר)\u0006 \u0010y38\u0011 ; אֲחֵרִים שֶׁחָבְלוּ בּוֹ, חַיָּבִים.\nהַמַּבְעִית אֶת חֲבֵרוֹ, אַף עַל פִּי שֶׁחָלָה מֵהַפַּחַד, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם; וְהוּא שֶׁלֹּא נָגַע בּוֹ, כְּגוֹן שֶׁצָּעַק לוֹ מֵאֲחוֹרָיו, אוֹ שֶׁנִּרְאָה לוֹ בַּאֲפֵלָה וְכַיּוֹצֵא בּוֹ. וְכֵן אִם זָעַק לוֹ בְּאָזְנוֹ וְחֵרְשׁוֹ, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0010y39\u0011 אָחֲזוֹ וְתָקַע לוֹ בְּאָזְנוֹ וְחֵרְשׁוֹ, אוֹ שֶׁנָּגַע בּוֹ וַהֲדָפוֹ בְּשָׁעָה שֶׁהִבְעִיתוֹ, אוֹ שֶׁאָחֲזוֹ בִּבְגָדָיו, חַיָּב בְּתַשְׁלוּמִין.\nאִם הַנֶחְבָּל אוֹמֵר: נֶחֱרַשְׁתִּי, נִסְמֵית עֵינִי, וְאֵינִי רוֹאֶה, אוֹ: אֵינִי שׁוֹמֵעַ, אֵינוֹ נֶאֱמָן, שֶׁאֵין אָנוּ מַכִּירִים הַדָּבָר וְשֶׁמָּא יַעֲרִים, וְאֵינוֹ נוֹטֵל הַנֶּזֶק עַד שֶׁיִּבָּדֵק זְמַן מְרֻבֶּה וְיִהְיֶה מֻחְזָק שֶׁאָבַד מְאוֹר עֵינָיו אוֹ נִתְחָרֵשׁ, וְאַחַר כָּךְ יְשַׁלֵּם זֶה. \u0010y40\u0011\nהַמְבַיֵּשׁ אֶת הֶעָרֹם אוֹ מִי שֶׁהוּא בְּבֵית הַמֶּרְחָץ, פָּטוּר. נָשְׁבָה בּוֹ הָרוּחַ וְהִגְבִּיהַּ בְּגָדָיו וְנִרְאָה כְּעָרֹם, וּבָא אַחֵר וְהוֹסִיף בְּהַפְשָׁטָתוֹ, חַיָּב בְּבֹשֶׁת; וּמִכָּל מָקוֹם, אֵין בָּשְׁתּוֹ שֶׁל זֶה מְרֻבָּה כְּמוֹ הַמְבַיֵּשׁ אֶת שֶׁאֵינוֹ עָרֹם כְּלָל. וְכֵן אִם הִגְבִּיהַ בְּגָדָיו לֵירֵד לַנָּהָר, אוֹ שֶׁעָלָה מִנָּהָר, וּבִיְּשׁוֹ, חַיָּב; וּמִכָּל מָקוֹם, אֵינוֹ כָּל כָּךְ בֹּשֶׁת כְּמוֹ שֶׁמְּבַיֵּישׁ הַמְלֻבָּשׁ.\nבִּיְּשׁוֹ כְּשֶׁהוּא יָשֵׁן, וּמֵת \u0005(בְּתוֹךְ שְׁנָתוֹ)\u0006, שֶׁלֹּא הִרְגִּישׁ בְּבֹשֶׁת, אֵין גּוֹבִין אוֹתוֹ \u0010y41\u0011 בֹּשֶׁת; וְאִם תָּפְסוּ יוֹרְשָׁיו, אֵין מוֹצִיאִין מִיָּדָם. \u0010y42\u0011 \u0005וְיֵשׁ אוֹמְרִים שֶׁהוּא פָּטוּר (טוּר סכ\"ו בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010y43\u0011\nיָשֵׁן שֶׁבִּיֵּשׁ, פָּטוּר.\nהַמְבַיֵּשׁ אֶת \u0010y44\u0011 הַשּׁוֹטֶה, פָּטוּר. אֶת הַחֵרֵשׁ, אוֹ אֶת הַגֵּר, אוֹ אֶת הָעֶבֶד, אוֹ \u0010y45\u0011 אֶת הַקָּטָן שֶׁכְּשֶׁמַּכְלִימִים אוֹתוֹ נִכְלָם, חַיָּב. וּמִכָּל מָקוֹם, אֵינוֹ דוֹמֶה הַמְבַיֵּשׁ אֶת הַקָּטָן לַמְּבַיֵּשׁ אֶת הַגָּדוֹל, וְלֹא הַמְבַיֵּשׁ אֶת הָעֶבֶד לַמְּבַיֵּשׁ בֶּן חוֹרִין, וְלֹא הַמְבַיֵּשׁ חֵרֵשׁ לַמְּבַיֵּשׁ פִּקֵּחַ. \u0010y46\u0011 \u0010c4\u0011\nרָקַק בַּחֲבֵרוֹ, חַיָּב. אֲבָל רָקַק בִּבְגָדָיו, אוֹ שֶׁבִּיְּשׁוֹ בִּדְבָרִים, פָּטוּר; וְיֵשׁ לְבֵית דִּין בְּכָל מָקוֹם וּבְכָל זְמַן לִגְדֹּר כְּפִי מַה שֶּׁיִּרְאוּ. וְיֵשׁ \u0010y47\u0011 אוֹמְרִים שֶׁמְּנַדִּין אוֹתוֹ עַד שֶׁיְּפַיֵּס הַמְבֻיָּשׁ. \u0005הַגָּה: \u0010y48\u0011 וְיֵשׁ אוֹמְרִים דְּמַכִּין אוֹתוֹ מַכַּת מַרְדוּת (בֵּית יוֹסֵף ס\"ס א' בְּשֵׁם מָרְדְּכַי פֶּרֶק הַזָּהָב)\u0006. וְהַמּוֹצִיא שֵׁם רָע עַל חֲבֵרוֹ, הָוֵי בִּכְלַל הַמְבַיֵּשׁ בִּדְבָרִים \u0005(פִּסְקֵי מהרא\"י סִימָן רי\"ב ות\"ה סִימָן ש\"ז)\u0006. הַמְקַנְטֵר חֲבֵרוֹ וְאָמַר \u0010y49\u0011 לֵהּ: אֵינִי מוּמָר וְאֵינִי עֲבַרְיָן, אַף עַל פִּי שֶׁלֹּא אָמַר: כָּמוֹךָ, הָוֵי כְּאִלּוּ פֵּרַשׁ כָּמוֹךָ \u0005(בֵּית יוֹסֵף מָצָא כָתוּב מהרי\"ו סִימָן קנ\"ז)\u0006. הָאוֹמֵר לַחֲבֵרוֹ: הֲרֵי אַתָּה עוֹשֶׂה כְּמוֹ מַמְזֵר, אוֹ: אַתָּה כְּמַמְזֵר, אֵינוֹ כְלוּם \u0005(מהרי\"ו סִימָן נ\"ט)\u0006. וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ שֶׁאִם אוֹמֵר: אַתָּה כְּמַמְזֵר, כְּאִלּוּ קְרָאוֹ מַמְזֵר \u0005(פִּסְקֵי מהרא\"י סִימָן רנ\"ז וְסִימָן קל\"ה וּמַהֲרִי\"ט סִימָן קכ\"ז וַאֲגֻדָּה פ\"ב דְּיוֹמָא)\u0006 ; אֲבָל אִם אוֹמֵר: אַתָּה מְכַזֵּב כְּמוֹ מַמְזֵר עַד שֶׁתִּתְבָּרֵר דָּבָר זֶה, אוֹ כַיּוֹצֵא בָּזֶה שֶׁהֵטִיל בַּדָּבָר תְּנַאי, אֵינוֹ כְלוּם \u0005(פִּסְקֵי מהרא\"י סִימָן קל\"ה)\u0006. הָאוֹמֵר לַחֲבֵרוֹ: פָּסוּל אַתָּה, \u0010y50\u0011 יֵשׁ אוֹמְרִים דְּיָכוֹל לְתָרֵץ דְּפָסוּל מִשּׁוּם קוּרְבָה קָאָמַר וְאֵין זֶה בִּיּוּשׁ \u0005(מהרי\"ו סִימָן נ\"ט)\u0006. \u0010y51\u0011 וְיֵשׁ חוֹלְקִין \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. \u0010c5\u0011 הַמְדַבֵּר רָע עַל שׁוֹכְנֵי עָפָר, צָרִיךְ לְקַבֵּל עָלָיו תַּעֲנִיּוֹת וּתְשׁוּבָה וְעֹנֶשׁ מָמוֹן כְּפִי רְאוֹת בֵּית דִּין \u0005(מָרְדְּכַי פֶּרֶק הַחוֹבֵל)\u0006 ; וְאִם קְבוּרִים בְּסָמוּךְ לוֹ, יֵלֵךְ עַל קִבְרֵיהֶם וִיבַקֵּשׁ מֵהֶם מְחִילָה, וְאִם הֵם רְחוֹקִים \u0010y52\u0011 יִשְׁלַח שָׁם שְׁלוּחוֹ \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. וְאִם כּוֹפֵר הַמְבַיֵּשׁ, אִם הוּא בִּיּוּשׁ שֶׁל שׁוֹכְנֵי עָפָר, יִתְּנוּ חֵרֶם בְּעֵדוּת, \u0010y53\u0011 \u0010c6\u0011 אֲבָל לֹא עַל בִּיּוּשִׁים אֲחֵרִים \u0005(מָרְדְּכַי הַנַּ\"ל מהרי\"ו סִימָן כ\"ח)\u0006. וְנִרְאֶה, דְהַכֹּל לְפִי רְאוֹת בֵּית דִּין. וְעַיִּןִ לְעֵיל סִימָן פ\"ז סָעִיף כ\"ה. הַקּוֹרֵא \u0010y54\u0011 לַחֲבֵרוֹ מַלְשִׁין בֶּן מַלְשִׁין, אִם הוּא לְבַד מַלְשִׁין, פָּטוּר. וְכֵן אִם קוֹרֵא לְרָשָׁע בֶּן צַדִּיק: רָשָׁע בֶּן רָשָׁע \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006. \u0010y55\u0011 \u0010c7\u0011 הַקּוֹרֵא לַחֲבֵרוֹ עֶבֶד אוֹ מַמְזֵר, וְהוּא אֱמֶת, פָּטוּר; אֲבָל אִם לֹא יוּכַל לְבָרֵר, אַף עַל גַּב דְּשָׁמַע כֵּן שֶׁאֲחֵרִים דִּבְּרוּ כָךְ, לֹא נִפְטָר בְּכָךְ \u0005(נִמּוּקֵי מַהֲרַ\"ם)\u0006 \u0005(וע\"ל סי' תכ\"א ס\"ג)\u0006.\nאַף עַל פִּי שֶׁהַמְבַיֵּשׁ בִּדְבָרִים אֵינוֹ בַּר תַּשְׁלוּמִין, עָוֹן גָּדוֹל הוּא; וְאֵין הַמְחָרֵף וּמְגַדֵּף לָעָם וּמְבַיְּשָׁן אֶלָּא שׁוֹטֶה רָשָׁע וְגַס רוּחַ. וְכָל הַמַּלְבִּין פְּנֵי אָדָם כָּשֵׁר מִיִּשְׂרָאֵל בִּדְבָרִים, אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. \u0010c8\u0011\nדִּין הַמְבַיֵּשׁ תַּלְמִיד חָכָם בִּדְבָרִים, נִתְבָּאֵר בְּטוּר י\"ד \u0005סִימָן רמ\"ג סָעִיף ז'.\u0006\nיֵשׁ הַכָּאוֹת רַבּוֹת שֶׁיֵּשׁ בָּהֶם בִּזּוּי וְצַעַר מְעַט, וְאֵין בָּהֶם נֶזֶק; וּכְבָר פָּסְקוּ לָהֶם חֲכָמִים דָּמִים קְצוּבִים, וְכָל הַמַּכֶּה אֶת חֲבֵרוֹ הַכָּאָה מֵהֶן, מְשַׁלֵּם אוֹתוֹ הַמָּמוֹן הַקָּצוּב; וְכֻלָּם קְנָסוֹת הֵן. וְאוֹתוֹ הַמָּמוֹן הַקָּצוּב \u0010y56\u0011 הוּא דְּמֵי הַצַּעַר וְהַבֹּשֶׁת וְהָרִפּוּי וְהַשֶּׁבֶת, \u0010y57\u0011 בֵּין צָרִיךְ לִרְפוּאָה בֵּין לֹא צָרִיךְ, זֶהוּ מְשַׁלֵּם. וְכַמָּה הוּא מְשַׁלֵּם, הַבּוֹעֵט בַּחֲבֵרוֹ בְּרַגְלוֹ, מְשַׁלֵּם ה' סְלָעִים; הִכָּהוּ בְּאַרְכּוּבָתוֹ, מְשַׁלֵּם ג' סְלָעִים; קִבֵּץ אֶצְבְּעוֹתָיו כְּמוֹ אוֹגֵד אֲגֻדָּה וְהִכָּהוּ בְּיָדוֹ כְּשֶׁהִיא אֲגֻדָּה, מְשַׁלֵּם י\"ג סְלָעִים; תָּקַע אֶת חֲבֵרוֹ בְכַפּוֹ, מְשַׁלֵּם סֶלַע; סְטָרוֹ עַל פָּנָיו, מְשַׁלֵּם חֲמִשִּׁים סְלָעִים; סְטָרוֹ בַּאֲחוֹרֵי יָדוֹ, מְשַׁלֵּם ק' סְלָעִים; וְכֵן אִם צָרַם בְּאָזְנוֹ אוֹ תָלַשׁ בִּשְׂעָרוֹ אוֹ רָקַק וְהִגִּיעַ בּוֹ \u0010y58\u0011 הָרֹק, מְשַׁלֵּם מֵאָה סְלָעִים. וְכָזֶה הוּא מְשַׁלֵּם עַל כָּל מַעֲשֶׂה וּמַעֲשֶׂה; כֵּיצַד, כְּגוֹן שֶׁבָּעַט בַּחֲבֵרוֹ אַרְבַּע בְּעִיטוֹת, אֲפִלּוּ זוֹ אַחַר זוֹ, מְשַׁלֵּם עֶשְׂרִים סְלָעִים. סְטָרוֹ עַל פָּנָיו שְׁתֵּי סְטִירוֹת, מְשַׁלֵּם מֵאָה סֶלַע, וְכֵן בַּשְּׁאָר. \u0005הַגָּה: יֵשׁ אוֹמְרִים אַף עַל גַּב דְּאִיתָא בַגְּמָרָא הַקּוֹרֵא לַחֲבֵרוֹ מַמְזֵר סוֹפֵג אַרְבָּעִים, מִכָּל מָקוֹם יֵשׁ מְקוֹמוֹת שֶׁאֵין נוֹהֲגִין כֵּן, וְהוֹלְכִין אַחַר הַמִּנְהָג (הָרֹא\"שׁ כְּלָל ק\"א סִימָן א')\u0006. וְנִרְאֶה לִי, דְּהוּא הַדִּין בְּאֵלּוּ הַדְּבָרִים הַנִּזְכָּרִים:\nכָּל אֵלּוּ הַסְלָעִים, הֵם מִכֶּסֶף מְדִינָה שֶׁאֵין בּוֹ כֶּסֶף \u0010y59\u0011 אֶלָּא שְׁמִינִית, שֶׁהֵם שָׁלֹשׁ מָעִין, שֶׁכָּל מָעָה מִשְׁקָל ט\"ז שְׂעוֹרוֹת כֶּסֶף צָרוּף, שֶׁהוּא עוֹטָמָנִי אֶחָד.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּמְכֻבָּד. אֲבָל אָדָם שֶׁהוּא מְבֻזֶּה וְאֵינוֹ מַקְפִּיד בְּכָל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶם, אֵינוֹ אֶלָּא כְּפִי מַה שֶּׁיִּרְאוּ הַדַּיָּנִים שֶׁרָאוּי לִטֹּל. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁאֵלּוּ הַדְּבָרִים אֵינָן רַק מִשּׁוּם בֹּשֶׁת וְצַעַר, אֲבָל רִפּוּי וָשֶׁבֶת הַכֹּל לְפִי הָעִנְיָן (טוּר סל\"ד בְּשֵׁם הָרִי\"ף וְכ\"כ הָרֹא\"שׁ בִּשְׁמוֹ)\u0006.\nכֵּיצַד מַגְבִּין הָאִדָּנָא חַבָּלוֹת וּקְנָסוֹת אֵלּוּ, נִתְבָּאֵר בְּסִימָן א'.",["\u0003שנאמר פן יוסיף כו' \u0004 בסוף פ' כי תצא כתיב והי' אם בן הכות הרשע וגו' ארבעים יכנו ולא יוסיף פן יוסיף להכותו כו' והנה הטור והמחבר למדו הלאו מדכתיב פן יוסיף לרמוז למ\"ש כל מקום שנ' השמר פן ואל אינו אלא ל\"ת אבל ברמב\"ם פ\"ה דחובל למדו מדכתיב בהדיא בקרא לא יוסיף וכן פירש\"י שם בפי' החומש ז\"ל לא יוסיף מכאן אזהר' למכה את חבירו וניחא ליה להרמב\"ם ללמדו מלא יוסיף שהוא לאו מפורש והטור והמחבר לא ניחא להו ללמדו מלא יוסיף משום דקאי אהכאת הרשע וי\"ל דדוקא נקיט שם דנלקה כבר ל\"ט מכות ויש סכנה בהוספ' לו עוד מכה א' משא\"כ בהכאה לחבירו מכה א' מ\"ה למדוה מיתורא דפן יוסיף ועמ\"ש בפרישה עוד מזה:","\u0003בהכאת הרשע. \u0004 דשם בקרא ארשע קאי כנ\"ל:","\u0003אף ע\"פ שלא הכהו. \u0004 דכתיב רשע למה תכה רעך הכית לא נאמר אלא תכה:","\u0003דיש חרם קדמונים אדם המכה לחבירו וצריכין להתיר לו כו'. \u0004 הל' משמע דא\"צ לנדותו עתה מחדש אלא מנודה ועומד זה המכה מהחרם שהחרימו ע\"ז הקדמונים וקאמר דצריך להתיר עתה אותו חרם למי שעברו ונ\"ל דה\"ה ☜ היכן שנזכרו בדברי האחרונים שהקהלות החרימו ע\"ז או שיש בו חרם ר\"ג נמי פי' הכי שא\"צ לנדותו עתה מחדש אלא שהוא מוחרם ועומד העובר על דברי תקנות ומדסתם מור\"ם וכ' ז\"ל וצריכין להתיר לו כו' משמע דר\"ל כסתם התרת נדרים שהוא בג' וכמ\"ש הטור והמחבר בי\"ד סי' של\"ד ולא כמו שעלה על דעת חכם א' לו' שכל מקום שנזכר בדברי האחרונים ז\"ל שהקהלות החרימו ע\"ז דאין לו התרה כ\"א בק' אנשים מג' קהילות מג' מדינות שלא מצינו שהחמירו בזה כ\"א בהרוצה לישא אשה על אשתו הראשונה משום צורך שהתירוהו עליו להנשא ודוקא אחר היתר גדול כזה אבל בשאר חרמות הקהלות או דר\"ג לא מצינו זה ודו\"ק:","\u0003כיון שאין בו חיוב ממון. \u0004 אבל אם יש בו חיוב ממון נותן ממון ואין לוקין אותו אע\"ג דאתרו ביה ולמדינן לה בגמ' מדכתיב כאשר עשה כן יעשה לו כן ינתן בו תו ל\"ל אלא דבר שיש בו נתינה ומאי נינהו ממון. וממון ומלקות כחדא פשיטא דלא מענשין אותו דכתיב כדי רשעתו כדי רשעה א' ולא ב' רשעות וע\"ל ר\"ס תכ\"ד מ\"ש עוד מזה:","\u0003עבד כנעני של חבירו. \u0004 והב\"י תמה שם עליהן וכ' דאפי' עבד כנעני שלו נמי דינא הכי כיון דחייב במצות ומ\"ה השמיטו ג\"כ כאן בש\"ע תיבת של חבירו ובדריש' כתבתי ליישב זה והוא דכיון דנתבאר דבמכ' שיש בה ש\"פ משלמין ואין לוקין וחיוב תשלומין לא שייך במכה עבד שלו דמה שקנה עבד קנה רבו ומ\"ה גם בהכא' דפחות מש\"פ לא מצינו גבי אדונו שום חיוב דאם באנו לחייבו עליה מלקות יבא להכותו מתחל' מכה רבה שיהיה בו ש\"פ כדי שיפטר בו מכל וכל ומ\"ה סתם הטור והמחבר לקמן בסי' תכ\"ד ס\"ג וכ' דהחובל בעבדו הכנעני פטור וכ\"כ הרמב\"ם בפ\"ב דהחובל דין י' ע\"ש ודוחק לומר דאיירי דוקא בחבל' שיש בו ש\"פ ומעלה ולא בפחות ממנו ועיין מ\"ש בדריש' שם וכאן:","\u0003חייב בחמש' דברים. \u0004 בגמרא ילפינן מקרא ועפ\"ר:","\u0003על ידו וצבתה. \u0004 מל' וצבתה בטנה דהיינו נפחה:","\u0003הכהו במקום שאינו נראה ולא ראוהו שום אדם \u0004 פי' תרתי בעינן שלא ראוהו בשעת הכאה וגם שתהא המכה עומדת במקום שלא תהיה נרא' לאחר זמן:","\u0003אלא ריפוי לבד. \u0004 כדי להחזירו למרא' עורו:","\u0003הוה גרמא בניזקין דומה לזה כ' הטור והמחבר [והרב] לעיל בסי' שס\"ג בסגירת בית חבירו ומעכבו מלדור בו ע\"ש:\u0004","\u0003אלא בשת. \u0004 דסופו לחזור השערות:","\u0003שהרי מצטער מן הסם. \u0004 שעושה בקעים בראשו מחמת חריפותו וצריך ריפוי לרפאותו ונזק אין לך נזק גדול מזה שלא יהיה לו שערות לעולם לחמם בהן ראשו גם בשת יש לו מזה הן בשעה שסכו כשאר מכה שיש לו בשת מה שרואין שהכהו וגם אח\"כ במה שרואין שאין לו שערות ונעשה קרח:","\u0003ולנדנד ראשו. \u0004 בטור כתב שער ראשו ועפ\"ר דהוכחתי דל\"ד קאמר שער ראשו דהנדנוד בראשו בשעת ריקודו נעשה גם בלא שערות (דאל\"כ גם בגילח לו שערות היה לו לחייבו ועוד דא\"כ בכלל נזק יחשב וכיון דכבר שילם לו נזקי דמי שערות שלו בכללו הוא השבת דשערות) אלא שכל זמן שראשו עליו יכאב אינו יכול להתעסק במלאכת ריקוד ונדנוד ראשו והוא שבתו והאי שבת לאו בכל ענין מתחייב בו אא\"כ מלאכתו הוא בכך וכן הוא לשון הטור ז\"ל ושבת אם הוא יודע לרקד בו ע\"ש:","\u0003אלא צלקת. \u0004 פי' שחיתה המכה ובעור נשאר רושם המכה לעולם. והמ\"מ כ' והב\"י הביאו דצ\"ע בחובל בבתו משמע דאינו חייב בזה כ\"א בחבל בפניה דשם יש הקפדה ברושם וכאן סתם המחב' ובפריש' כתבתי שי\"ל דדוקא בתו אינה מקפדת עם אביה בשאר מקומות משא\"כ איש זה עם איש אחר ע\"ש:","\u0003כאלו הוא עבד נמכר בשוק. \u0004 רש\"י ונ\"י ר\"פ החובל פירשו כאלו נמכר להיות עבד עברי אבל הרא\"ש כתב שם דשמינן ליה כמו עבד כנעני דנמכר לעבד לעולם כי גם חסרון אברו הוא לעולם משא\"כ עבד עברי שאינו נמכר אלא לו' שנים ואם באנו לשומו בכל ו' שנים פעם אחר פעם יעלה לערך יותר ממה שיעלה הערך כששמין אותו פעם אחת וגם כבר כתבתי מזה בסי' א' ואפי' הוא אדם חשוב שיימינן נזקו כעבד ואשר נגע בכבוד חשיבתו זה משלם לו בכלל בושת שהיא משתלמת לפי המתבייש כדלקמן אבל לענין נזק הכל שווין:","\u0003שאינו מזיק לו כ\"כ. \u0004 לשון הטור בשם הרא\"ש ויראה דשומא זו ששמין לאדם כפי מלאכתו היינו דוקא להוסיף בשומא כגון אם קיטע ידו של עבד נוקב מרגליות אבל אם קיטע רגלו והיתה שומתו פחותה משומת עבד העומד לשימוש לפי שהעבד הנוקב מרגליות אין רבו מקפיד כל כך על חסרון רגלו שעדיין הוא ראוי למלאכתו ראשונה ויותר יהיה עתה קבוע במלאכתו לא ישומו אותו כנוקב מרגליות דמסתברא (יעמוד) שלא יפסיד באומנתו לפי שאם ירצה לא יעשה דבר זה ויהי' כשאר כל אדם הנמסר לכל מיני תשמיש עכ\"ל ולזה כוון מור\"ם ז\"ל בקיצור לשונו:","\u0003אם גזר המלך לקטוע בסייף \u0004 שהרי גם כאן גזר המלך הש\"י שכאשר עשה וחתכו לחבירו בסייף כן יעשה לו אלא שלמדנו שעשייה זו היא נתינת ממון ומ\"ה אף שישלם לו דמי נזק ידו עדיין עליו לשלם מה שציערו בקטיעת היד ומן הדין עליו לשלם לו דמי צער קטיעת סייף כמו שעשה אלא שמשום דמה שקיטע ידו דחבירו כבר נעשה ולקטוע ידו לכתחלה אין אדם לוקח דמים הרבה מ\"ה אמרו חכמים לשער כמה היה כשהיה נותן לחתוך בסם למי שנגזר עליו חתיכת סייף דמדכתיב וביער בשדה אחר ואחז\"ל שלא ישום הערוגה שהזיקה לבד אלא ישומו אגב כל השדה וכמ\"ש לעיל סי' שצ\"ד למדונו שהתורה חסה על המזיק להקל לו בשומא אשר\"י:","\u0003אם היה גוזר המלך לכוות כו'. \u0004 אבל אין שמין כמה אדם רוצה ליקח להכוות אותו בשפוד דאין אדם לוקח הרבה כדי להצטער בתחלה בכזה וכנ\"ל","\u0003כפעל בטל כו' \u0004 לשון הטור הוא מבוא' בדין זה יותר והנה אעתיקו נותן לו כפועל בטל של אותה מלאכה דבטל ממנו ורואין כמה היה רוצה ליקח ויהיה בטל וזה תלוי כפי מה שהוא מלאכתו שיש מלאכה כבידה ושכרה מועט שהיה לוקח מעט שישב בטל ויש מלאכה קלה ששכרה הרבה וצריכין ליתן לו הרבה שישב בטל ממנה (ודומה לזה כתב הטו' בפועל בטל בי\"ד סי' שי\"ב בדין ראית בכור במומו ע\"ש והרמב\"ם הוסיף בזה וכתב דאם הוא אדם שהבטלה קשה לו כאוכלסי דמחוזאי צריך ליתן לו כל שכרו ודומה לזה כתב הטור לעיל ס\"ס של\"ד ושל\"ה ע\"ש) ואם חסרו אבר כבר נתן לו נזק שהוא דמי האבר כגון אם קטע ידו כבר נתן לו מה ששוה פחות לפי שאינו יכול לעשות מלאכה בידו אבל עדיין הוא ראוי לשמור קישואין לכשיתרפא לפיכך נותן לו כל ימי משך חליו בכל יום ויום כמו שנותנין לשומר קישואין (ובסעיף שאחר זה יתבאר דנותנין לו מיד הריפוי והשבת דכל ימי חליו והוא לטובת המכה וכמו שיתבא' שם ומה\"נ דקדק הרמב\"ם וכ' כאן ז\"ל ועושין חשבון כל ימי חליו של זה ונותן לו ר\"ל נותן לו מיד בפעם א') וכן אם שיבר רגל א' עדיין הוא ראוי לשמר קישואין (וכן אם נחתך ידו ורגלו א') שבר שני רגליו אינו ראוי לשמו' קישואין (דשומר קישואים צריך לסבב הגנים ולילך בכל צד לשומרם) אבל ראוי לישב במקום א' לשמור הפתח וכן יתן לו כל ימי משך חליו (והמותר עולה לו בדמי נזקו שהוא בזה יותר גדול מאילו לא חיסר אלא רגל א' וכן בסימא עינו בסמוך והכלל כל שהשבת יותר מעט נזקו יותר גדול) סימא לו עינו א' עדיין הוא ראוי לו למלאכה ראשונה (פי' ונותן לו השבת כל ימי חליו מכאיבת עינו הא' כפועל בטל ממלאכתו הראשונה וכנ\"ל) סימא ב' עיניו אז אינו ראוי אחר שיתרפא אלא לטחון ברחיים וכן יתן לו כל ימי חליו וכתב א\"א הרא\"ש ז\"ל דכל זה הוא בסתם בני אדם שאינם בני אומנות אבל אם הוא בעל מלאכה שמין השבת לאותה מלאכה שיכול לעשות אחר שיתרפא (וז\"ש מור\"ם ודוקא בסתם כו') כגון אם הוא מלמד תינוקות וקיטע את ידו או שיבר את רגלו לאחר שיתרפאו הוא ראוי למלאכתו וגם אם היה ניקב מרגליות ושיבר את רגלו לכשיתרפא ראוי הוא למלאכתו ולמה ישומו אותו בימי חליו כשומר קשואין עכ\"ל הטור ובזה דברי המחב' מבוארין דמ\"ש קיטע רגלו ר\"ל שני רגליו ומ\"ש סימא את עינו ר\"ל ב' עיניו ודוק:","\u0003ודבר זה תקנה הוא למזיק. \u0004 דאם היה צריך לתת לו שכר רפוי דבר יום ביומו שמא יתרשל המוכה ברפואתו באמרו דמי הרפואה הן על המכה אצערנו בזה כדי שיוציא הרבה דמים וזה שמסיק וכ' דאם היה מתגלגל וארך החולה אינו מוסיף לו כלום ואף דלפעמים יהיה להמכה בזה הפסד דאם הבריא מיד דאין פוחתין לו מהאומד כדמסיק זהו דבר שאינו שכיח שיבריא קודם זמן שאמדוהו לכך משא\"כ בהמשך חליותו דאיכא למיחש כנ\"ל ועוד כמה סבות וגרמות הן דימשך חליותו:","\u0003הרי שלא פסק עמו וכו' \u0004 משמע דאפי' סתמא נמי כל שלא פסק ונתן דבר יום ביומו ועלתה בו צמחים חייב בריפוי ושבת הצמחים מ\"ה דרך המכה לדרוש טובתו ולפסוק וכנ\"ל ולא כע\"ש דכ' ז\"ל אמר המזיק ליתן דבר יום ביומו ועלה בו צמחים כו' דבלא אמירה כן נמי דינא הכי וק\"ל.","\u0003שלא מחמת מכה. \u0004 בגמ' דף פ\"ה ע\"א פריך פשיטא ומשני קמ\"ל דאפי' א\"ל אל תאכל מיני מתיקה והוא אכלם ועלה בו צמחים כיון דעבר על דברי הרופא שלא מחמת מכה מיקרי והטו' והמחב' כתבו מתחלה שלא מחמת מכה ובכללא הוא זה דאכל מיני מתיקה ואח\"כ כ' ג\"כ עבר על דברי הרופא לרבות שאר כל דבר:","\u0003אין שומעין לו \u0004 בגמ' מפרש טעמא דאם אמר אני ארפאך יאמר לו דמית עלי כאריא ארבא ועל רופא אחר חנם יאמר רופא שאינו מקבל תשלומין אין מדקדק ברפואתו ובטו' כ' ה\"ט בתרא גם אאם א\"ל ואני ארפאך ע\"ש:","\u0003שזה שביישו הקל בשתו מרובה. \u0004 בפרישה כתבתי בשם רש\"י והר\"ן דבושת אדם בינוני מרובה משל אדם נכבד ומזולזל חוץ באונס ומפתה שבושת הקל מהמזולזל בושתו יותר:","\u0003פטור מדיני אדם כו'. \u0004 דכל שלא אחזו לעשות מעשה בגופו גרמא בעלמא מיקרי ומ\"מ חייב בדיני שמים כיון שנחרש בסיבתו:","\u0003ותקע באזנו כו' \u0004 וכתב המרדכי פ' החובל דאף דלא תקע באזנו אלא הכה על הכותל כנגד אזנו ונתחרש חייב אם אחזו עכ\"ל ד\"מ כ\"ד:","\u0003נותן לו דמי כלו \u0004 ל' הטור וכ' א\"א הרא\"ש ז\"ל לענין נזק ושבת אין חילוק בין חד אומדנא ובין כל אבר ואבר לבד דבכל שומא שמין כמה נחסרו דמיו בשביל אותו אבר עד שיצטרפו כל איבריו יחד וגם שבת שבין הכאה להכאה פשיטא שנותן לו כי עדיין הוא ראוי למלאכה כשיתרפא כל זמן שלא חרשו ואין חילוק אלא לענין צער וריפוי ובושת ודבר פשוט דצריך ליתן לו צער ריפוי ובושת של כל מכה ומכה בפני עצמה אלא יותר יעלו כשישומו כל מכה ומכה בפני עצמה ממה שיעלו כשישומו כאילו עשאן כולם כאחד ואין ביניהן אלא דבר מועט אבל בנזק ושבת אפי' מועט כזה אין ביניהן כי גם לבסוף שמין כמה נפחת דמיו בשביל כל אבר ואבר בפני עצמו עכ\"ל בקצת שינוי ל' לתוס' ביאור וז\"ש מור\"ם בהג\"ה דנותן לו צער ריפוי ובשת באומדן הכל יחד שבהן יש נ\"מ בין אומדנא יחד או כל א' וא' בפני עצמו משא\"כ בנזק ושבת דאין ביניהן חילוק כלל.","\u0003אמדוהו לכל נזק ונזק כו'. \u0004 איבעיא דלא איפשטא הוא בגמרא ופסק הרמב\"ם כפי שטתו בכל תיקו דממונא דאם לא תפס דהוה קולא לנתבע וחומרא לתובע ואינו משלם לו אלא דמי כולו ואם תפס דמי אומדן לכל אבר בפני עצמו מהני תפיסתו ע\"ז כ' מור\"ם דבסי' שפ\"ח נתבאר די\"ח וס\"ל דלא מהני תפיסה בספיקא דדינא ודע דהרא\"ש והטור הן בעלי סברא זו שם בסי' שפ\"ח ובשאר דינים המבוארים בטור סי' זה ואפ\"ה סברי בדין זה דנותן לו דמי אומדן של כל מכה בפני עצמה ומטעם כיון דאין נ\"מ כ\"א דבר מועט בריפוי ובשת ובנזק ושבת אין נ\"מ כלל לכן פסק דגובין נזק של כל אבר בפני עצמו כיון שכבר אמדוהו לכך:","\u0003ואם תפס הניזק נזק כל אבר ואבר ודמי כולו אין מוציאין כו' \u0004 כן הוא גם לשון הרמב\"ם בפ\"ב דחובל וכ' עליו המ\"מ שם ז\"ל אם דעת הרב במ\"ש דמי כל אבר ואבר כל נזק אין דמי כולו האמור ראשון (ר\"ל שכ' ברישא נותן לו דמי כולו) כדמי כולו השני שאלו הראשון דמי כולו כמו שהיה בריא טרם שחבל בו כלל והאחרון דמי כולו אחר שנגרעו דמיו מחסרון עינו וידו ורגלו דודאי אם תפס דמי האברים ודמי כולו כמו שהיה בריא מפקינן מיניה עכ\"ל ועד\"ר מ\"ש ביאור דבריו הללו והנלוה לו:","\u0003אלא שביישו נותנין כו'. \u0004 עפ\"ר שם הוכחתי דלבשת של חבלה אין נותנין זמן כיון שלשאר דברים שגובין בחבלה אין נותנין זמן כיון דיש בהן חסרון ממון אגבן גובין ג\"כ צער ובשת אע\"ג דלית בהו חסרון ממון ודוקא בדבר שאין גובין עליה אלא דמי בשת לחוד הוא דנותנין זמן ונראה דה\"ה צער כשהוא לחוד כגון בשפוד במקום שאין רואין כיון דלית ביה חסרון ממון נותנין לו זמן והא דכ' הטור והמחבר והרמב\"ם דין זה בבשת לחוד ולא בצער משום דבמשנה וגמרא מעשה כך היה לפני רבי עקיבא באשה שפרע ראשה ונתביישה ועיין שם ובפרישה:","\u0003כשם שאומדים למיתה כו' \u0004 דבמיתה כתי' בפרשת מסעי בהדיא אם באבן או באגרוף אשר ימות בו הכהו ופירשהו רז\"ל שיעור שימות בו:","\u0003בצרור קטן כו'. \u0004 בטור כ' עוד דאומדין ג\"כ המקום אשר הכהו עליו מ\"ש:","\u0003ה\"ז פטור \u0004 דאמרי' מזלו גרם:","\u0003אבל חייב בבשת. \u0004 עפ\"ר שם הוכחתי דאפילו אם האבן קטן עשה חבלה גדולה ונתבייש בה אף דאינו חייב בשאר הדברים מכל מקום אבשת שנתבייש בה חייב וראיה לזה שהרי אפילו רקק בחבירו שהוא ענין קל חייבוהו עליו בשת ה\"ה בבושת הבא לו מאבן קטן:","\u0003ישבע הנחבל ויטול. \u0004 כיון דאין דרך לעשות מכה כזה אא\"כ היהבה כדי להזיק אוקמינן אחזקתו וק\"ו הוא ממה שאמרו נחבל נשבע ונוטל אף אם אומר הנתבע לא אני חבלתי אלא חבל בעצמו כיון דאין דרך אדם לחבול בעצמו וכמ\"ש הטור והמחבר לעיל ס\"ס צ':","\u0003הברזל אין לו אומד דבברזל לא כתיב אשר ימות בו:\u0004","\u0003שאינו מחודד. \u0004 נראה דאפילו אם הוא מחודד אלא שלא המית בחידודו אלא במשקלו פטור דזיל בתר טעמו:","\u0003אחרים שחבלו בו חייבים. \u0004 פי' ול\"ת כיון דזה עובר על דעת המקום במה שחבל בעצמו אף שאינו רשאי וגם אנו רואים שאינו מקפיד בצערו וחבלתו שהרי חובל בעצמו גם אחרים שחבלו בו יהיו פטורים קמ\"ל ועפ\"ר וע\"ל סי' שפ\"ב שכתב הטור דומה לזה בקוצץ נטיעתו של חבירו:","\u0003אחזו ותקע לו באזנו חייב בתשלומין \u0004 בכאן לא כתב כמה חייב כי סמך אמה שכתוב לפני זה בסכ\"ח [בסכ\"ה] וחזר וכתבו כאן כדי לכללו בין שאר דינים שחילק בכולן בין אחז בו ועשה מעשה בגופו דחייב ובין לא אחז בו דפטור בדיני אדם:","\u0003המבייש את הערום \u0004 כן הוא ל' הרמב\"ם ובפרישה הוכחתי דמדכתב המבייש את הערום מוכח דס\"ל כרש\"י דאפי' ביישו בכל מיני ביוש שרקק בו או הכהו אפ\"ה פטור מהבשת כיון דלאו בר בשת הוא במרחץ כיון שהולך ערום וכ\"ש כשהולך ערום בלא מרחץ מה שא\"כ כשאינו הולך ערום כל כך דאז בר בושת מיקרי וחייב עליו אפי' כשבא אחר והגביה בגדיו קצת יותר וכ\"ש אם ביישו בענין אחר אבל ר\"י כתב דגם כשהוא ערום או בבית המרחץ דאינו פטור כשמביישו בשאר ענינים אלא דכשהוא רוחץ במרחץ דאז הוא כבר ערום לגמרי לא שייך בו בשת דהפשטת בגדים אבל כשהוא הולך לרחוץ בנהר והגביה בגדיו ובא אחר והגביהן יותר או שנשבה בו רוח והגביהן ובא אחר והגביהן יותר בזה קאמר הברייתא דביישו ערום בבית המרחץ או כשהוא ערום דחייב ומהתימא על מור\"ם שלא הביא דעת ר\"י זו שסתר פירש\"י שהוא כדברי הרמב\"ם שכ' המחבר:","\u0003ואם תפסו יורשיו כו' \u0004 איבעיא הוא בגמרא אם טעם דחייבתו התורה בשת הוא משום כיסופא דידיה והכא לא שייך כיון שמת ופטור או משום בשת דבני משפחתו חייבו התורה והרי הן בחיים וחייב ולא איפשטא וס\"ל להרמב\"ם דמהני תפיסה בספיקא דדינא:","\u0003וי\"א שהוא פטור. \u0004 עפ\"ר שכתבתי דאפילו הסוברים דמהני תפיסה לספיקא דדינא יש מהן דס\"ל כאן פטור משום דס\"ל דהא איבעיא נפשט' בגמ' דמשום כיסופ' דידיה הוא ע\"ש מ\"ש עוד בזה:","\u0003ישן שבייש פטור. \u0004 דמוהחזיקה במבושיו ילפינן דבבשת בעינן דוקא שיבייש בכונה:","\u0003השוטה פטור \u0004 דלאו בר בשת הוא משא\"כ בחרש ובגר ועבד דחייבים משום דבני מצות נינהו:","\u0003את הקטן שכשמכלימין אותו נכלם לשון הטור הוא זה וכאילו אמר אם כשמכלימין אותו הוא נכלם חייב ואם לאו הוא פטור וכ\"כ בהדיא בטור ע\"ש בסכ\"ט:\u0004","\u0003רקק בחבירו חייב \u0004 משום בשת ובבגדיו ובביישו בדברים פטור דבעינן דיעשה מעש' בגופו דומיא דוהחזיקה במבושיו:","\u0003שמנדין אותו שיש בוטה כמדקרות חרב ואין לך בשת גדולה יותר מהוצאת שם רע ודבה אשר\"י וע\"ל ס\"ס א' וגם המחבר סתם וכתב שם כן בס\"ו וכאן כתבו בשם י\"א וכבר כתבתי כמה פעמים דאין הוכחה מלשון י\"א דפלוגתא הוא אלא דבמקום שמצא שיחיד כ\"כ ואינו מפורסם בשאר פוסקים רגיל לכתבו המחבר ומור\"ם בלשון י\"א:\u0004","\u0003דמכין אותו מכת מרדות \u0004 דעבר על לאו דלא תונו אבל כיון דהוא לאו שאין בו מעשה אין לוקין עליו מלקות דאורייתא:","\u0003איני מומר כו'. \u0004 וכתב בהגמ\"ר (דף נ\"ג) אם קראו מומר אחר שעשה תשובה הרי עובר חרם ר\"ג ואי לא ידע מן החרם אינו מקרי עבריין עכ\"ל ודין איש שחרף אשה כ' בהגמ\"ר דקידושין דיתענה בה\"ב וישב יחף לפני ב\"ה ויבקש מחילה על המגדל וע\"ל סי' תכ\"א סי\"ג מדין אשה שביזה לאחר:","\u0003י\"א דיכול לתרץ כו' וכ' מהרי\"ו שם עוד וכן אם קראו מבייש הנשים יכול לתרץ דיבוריה דר\"ל דמביישן בדברים וכן אם קראו בן הזונה יכול לתרץ דיבוריה ור\"ל בן פונדקת עכ\"ל ד\"מ שם. הג\"ה וכ' עוד בשם נימוקי מהר\"ם דכ' באם עד ח' מעיד שקראו ממזר ועד א' מעיד שקראו בן הזונה דמצטרפין לענין בן הזונה דבכלל מאתים מנה מ\"מ אין לו דין ממזר דלמא קראו בן הזונה כשהיתה פנויה עכ\"ה.\u0004","\u0003ויש חולקין. \u0004 ר\"ל דלא יוכל לתרץ דיבוריה ושם כ' כן על א' שקראו כנען אבל כ' שם מהר\"ם על אשה אחת שיצא עליה קול שזינתה בטבריה וצוח לה אחד טברי' טבריה לא מיקרי ביוש בפרהסי' כו'. ע\"ש ד\"מ:","\u0003ישלח שם שלוחו \u0004 ומסיק שם דשלוחו יקח ב' מהעיר שנקבר שם וילך על קברו ויבקש מחילה בשם המחרף:","\u0003אבל לא על ביושים אחרים \u0004 ר\"ל דשם נותנין חרם אחר עדות אבל גם בביוש של שוכני עפר א\"צ לישבע ע\"ז כן הוא שם ע\"ש דמ\"ש.","\u0003מלשין בן מלשין פטור. \u0004 דאמרינן בפרק ד' מיתות כמאן קרינן לרשיע בר צדיקא רשיעא בר רשיעא שנא' ובת כהן כי תחל לזנות את אביה היא מחללת ע\"ש:","\u0003הקורא לחבירו עבד כו' \u0004 וכ' מוהר\"ם מריזבורק וז\"ל האומר לחבירו ממזר או עבד או רשע או נואף או פסול או נבל לוקה (ועמ\"ש בהג\"ה בסמ\"ע בשם הרא\"ש ואם קראו עובר על חרם מלשין או גנב הוי כקוראו רשע ויורד עמו לחייו ופי' ר\"י דמותר להכותו דעובר על לאו דלא תונו אבל אם קראו טמא או כלב או שאר חירופין און בהן דין אלא צריך לפייס חבירו עכ\"ל ד\"מ שם וע\"ל ר\"ס תכ\"א באחד הקובל על חבירו שהלשינו או גנב לו. (הג\"ה וכ' בד\"מ סל\"ד ומהרי\"ו סי' כ\"ח פסק בא' שחבל בחבירו להלקותו בב\"ה בין מנחה למעריב דהמגביה ידו על חבירו נקרא רשע וחייב מלקות וגם הוצרך לעשות מחילה וגם פסק ליתן לו זקוק כסף אם הוא עני ואם הוא עשיר יתנו לעומלי תורה כן פסק גדול א' על א' שתלש שערו של חבירו ופסק ליתן לו זקוק כסף אמנם אם יש מנהג בזו הכל לפי המנהג ונ\"ל דכל זה אינו אלא הוראת שעה לפי ראות עיני הב\"ד שחטא המחבל אבל מדינא אינו חייב מלקות וממון כמו שנתבאר כו' עכ\"ל ד\"מ עכ\"ה):","\u0003הוא דמי כו'. \u0004 ר\"ל הריפוי והשבת הוא בכללו שאף אם יש מחמת אותו הכא' הוצא' ממון דריפוי או שבת א\"צ לשלם לו יות' ובע\"ש כ' שינוי לשון ז\"ל ואמרו שיתן הצער והבושת והריפוי והשבת כו' דמשמע דתחלת תיקונו היה כ\"כ בשביל הריפוי והשבת כו' וללא צורך כ\"כ וגם אמירה זו לא מצינו שאמרו כן:","\u0003בין צריך לרפואה בס\"ס זה כ' מור\"ם דעת החולקים ע\"ז ואומרים דדמים הללו אינן בשביל רפוי ושבת כי לא קצבו דמים קצובים כ\"א הצער ובושת שהן בכל מכות שמכה אדם לחבירו ואם יש ריפוי ושבת משלם עוד נוסף על קצבה זו ולפי הענין ובהן לא יוכלו חז\"ל ליתן בהן קצבה:\u0004","\u0003משלם ק' סלעים כו'. \u0004 ובטור סל\"ד מסיים כאן ז\"ל או שפרע ראש האשה משלם ק' סלעים כו' וכתב בד\"מ סל\"ד בשם נימוקי מוהר\"ם וז\"ל המלעיג על דברי חכמים לוקה והקורא לאשת חבירו זונה או פרוצה לוקה ד' מלקיות דתנן פרע ראש האשה נותן ארבע מאות זוז ומדלא מגבינן קנסא בבבל לוקה ד' מלקיות וע\"ל סי' ב' מ\"ש בשם מהרי\"ו (ור\"ל דשם כתב דכל מלקיות הוא ארבעים זוז) עכ\"ל ד\"מ ח':","\u0003אלא שמינית כו' \u0004 ז\"ל הטור והרמב\"ם סלע מדינה יש בו חצי דינר כסף (שהוא שמינית שבסלע צורי שיש בו ד' דינרי כסף) וג' דינרים ומחצה נחושת לפיכך מי שנתחייב ק' סלעי' משלם י\"ב סלעי' ומחצה כסף נקי עכ\"ל ובפרישה כתבתי דאינו ר\"ל דיצא בשילום י\"ב סלעי' והחצי כסף נקי לחוד שהרי כיון דחייבוהו לשלם בסלעים שבכל סלע יש בו ז' חלקים נחשת והחלק השמיני של כסף נהי דנסתלק ממנו בזה ידי שלום הכסף שבו עדיין לא נסתלק ממנו תשלומין הנחשת שבו וצ\"ל דמ\"ש דמשלם י\"ב סלעי' ומחצה כו' צ\"ל כשיבא לשלם לו בסלעי' דמדינה ירא' שלא יהא בהן פחות מי\"ב סלעים ומחצה כסף והמותר יהיה נחשת ומשום דהמקומות והזמנים משתנים שפוחתין בסלע מדינה הכסף ומוסיפין במקומו נחשת מ\"ה כתב שיעור הכסף שלא יפחות מזה ומה\"נ נראה דסתם המחבר ולא כתב שיתן י\"ב סלעים ומחצה כסף כי לא בא אלא ללמדינו כמה כסף יהיה בו והרמב\"ם שכתבו בספ\"ג דחובל מ\"מ רמזו במה שהתחיל שם וכתב ז\"ל כל אלו הסלעים הן מכסף א\"י באותו זמן שהיה בכל סלע כו' חצי דינר כסף כו' הרי לשונו משמע שבא ללמדינו כמה היה הסלע באותו זמן דחכמי המשנ' שקבעו שיעורים הללו ומאותו שיעור נלמד לכל זמן וזמן ומקום ומקום לפי מה שהוא המטבע שם שלא יפחות הכסף ממנו וכנ\"ל ועמ\"ש בפריש' עוד מזה:"],["\u0003 עבד כנעני של חברו כו'. \u0004 עיין בסמ\"ע ס\"ק ו' עד ומ\"ה גם בהכא' כו' והב\"ח השיג ע\"ז ואין דבריו מוכרחים:","\u0003 חייב בחמש' דברים \u0004 וה' דברים אלו משתלמין מן היפה שבנכסיו כדין כל המזיקין עכ\"ל רמב\"ם ריש הל' חובל וכן כ' הסמ\"ג דף קמ\"ה ע\"ג וכ' הרב המגיד שם שהדין מבואר ריש ב\"ק דאמר כלם כאבות הן לשלם ממיטב ע\"כ וכן פסקו הרי\"ף והרא\"ש והנ\"י ריש ב\"ק וכ\"פ רש\"ל שם סי' ו' וכן הוא הדין לעיל סי' שפ\"ה ושפ\"ח ס\"ב:","\u0003 ואם הי' בעל אומנות כו'. \u0004 ומהרש\"ל פסק דלענין נזק אין חילוק בשום בני אדם בעולה אלא שמין אותו כעבד שא\"י שום מלאכה וע\"ש סי' י\"א ומכל מקום אין טעם לדבריו דהא מכל מקום היזקו הוא רב יותר מעבד שאינו יודע שום מלאכה ודו\"ק נ\"ל:","\u0003 אין נותנין לחובל שום זמן כו' \u0004 משמע אפילו זיל נכסי דנתבע ודוקא כשנתחייב בדין אבל אם מבקש זמן להביא עדים לפטור נותנים זמן אף לחבלות אם זיל נכסיה כדמוכח בתוספות והרא\"ש פרק הפרה וכ\"כ נ\"י שם ודלא כב\"ח סי' כ\"ד וכבר השגתי עליו שם ע\"ש:","\u0003 רקק בחבירו \u0004 עיין בתשו' ר\"י לבית לוי סי' כ\"ט מדינים אלו:","\u0003 המדבר רע על שוכני עפר כו' \u0004 עיין בתשו' ר\"א ן' חיים סי' נ' וסי' צ\"ג וסי' קי\"א:","\u0003 אבל לא על ביושים אחרים כו' \u0004 ע\"ל סי' פ\"ז (בסמ\"ע) ס\"ק ע\"ה וע\"ו כ' הסמ\"ע ר\"ל דשם נותנין חרם אחר עדות אבל גם בביוש של שוכני עפר א\"צ לישבע ע\"ז כן הוא שם עכ\"ל ובאגוד' פ' הזהב ז\"ל אם אדם טוען ביישתני בדברים או בשוכני עפר והלה כופר נרא' דא\"נ לישבע דלא נתקנ' שבועת היסת ע\"ז מיהו בס' מיימוני ובס' המצות לא משמע הכי עכ\"ל ולא ידעתי למה לא משמע הכי בס' מיימוני ובס' המצות ואי משום שכ' בריש הלכות טוען ונטען שהטוען לחבירו אתה ביישתני וזה אומר להד\"ם אם הוא במקום שגובין קנס נשבע היסת כו' וה\"נ אלו הוה אמת היו קונסין אותו י\"ל דשאני התם דאלו היה האמת קונסין אותו ממון הקצוב בתורה משא\"כ הכא תדע שהרי גם הטור ס\"ס פ\"ז כתב כהרמב\"ם וסמ\"ג ואפ\"ה כתב שם לעיל מיניה דאם טוען אתה קללת אותי או הוצאת עלי ש\"ר אין משביעים אותו רק מחרימים ע\"ז שהרי אם יתברר שהוא אמת קונסין אותו כו' (הג\"ה עיין במהרש\"ל פ' החובל באריכות מדינים אלו ועיין בתשובת ר\"י מטראני מי\"ד סי' ט\"ז שכ' שכל מה שמדבר לחבירו בלשון צחות כגון שקורא לרבים בני יונים או אמר על אחד שבא לדור ממקום אחר ונעשה דיין הגר אשר בקרבך יעלה עליך וגו' אע\"ג דקרא קאי אעכו\"ם לא מיקרי בושת וההיא איתתא דאמרה ורב כריסא וכו' אשה זו. פושעת היתה דה\"ל ליתן בו סי' אחר וע\"ש ראיה שלו:","\u0003 הקור' לחבירו עבד \u0004 עיין בתשו' ר\"מ אלשיך סי' ע\"ג ובתשובת מבי\"ט ח\"ח בשאלות השניות סי' ע\"ז דף ק\"ח אם קראו בן השפח' ונידהו ועיין עוד שם סי' קכ\"ה דף קע\"ד:","\u0003 דין המבייש ת\"ח כו'. \u0004 וראשים וממונים הקהל כת\"ח כ\"כ בתשובת מהר\"י לבית לוי סי' כ\"ט ועיין שם באריכות:"]],["אֵינוֹ חַיָּב עַל הַבֹּשֶׁת עַד שֶׁיִּתְכַּוֵּן לְבַיְּשׁוֹ; וְהַמְבַיֵּשׁ אֶת חֲבֵרוֹ שֶׁלֹּא \u0010y0\u0011 בְּכַוָּנָה, פָּטוּר. \u0010y1\u0011 לְפִיכָךְ, יָשֵׁן שֶׁבִּיֵּשׁ, פָּטוּר. \u0005הַגָּה: וְכֵן מִי שֶׁקּוֹבֵל עַל חֲבֵרוֹ שֶׁמְּסָרוֹ אוֹ גָּנַב לוֹ וְכַיּוֹצֵא בָּזֶה, אַף עַל פִּי שֶׁלֹּא יָכוֹל לְבָרֵר עָלָיו, מִכָּל מָקוֹם פָּטוּר, \u0010y2\u0011 דַּהֲרֵי לֹא כִּוֵּן לְבַיְּשׁוֹ (מהרי\"ו סִימָן קס\"ח)\u0006.\nהַמִּתְכַּוֵּן לְבַיֵּשׁ אֶת הַקָּטָן וּבִיֵּשׁ אֶת הַגָּדוֹל, \u0010y3\u0011 נוֹתֵן לַגָּדוֹל דְּמֵי בָּשְׁתּוֹ שֶׁל קָטָן. נִתְכַּוֵּן לְבַיֵּשׁ אֶת הָעֶבֶד וּבִיֵּשׁ בֶּן חוֹרִין, נוֹתֵן לַבֶּן חוֹרִין דְּמֵי בָּשְׁתּוֹ שֶׁל עֶבֶד: \u0010y4\u0011\nיֵשׁ אוֹמְרִים דְּצַעַר רִפּוּי וְשֶׁבֶת \u0010y5\u0011 חַיָּב אֲפִלּוּ שֶׁלֹּא בְכַוָּנָה, וּבִלְבַד שֶׁלֹּא יְהֵא אָנוּס, אֶלָּא שׁוֹגֵג קָרוֹב לְמֵזִיד; אֲבָל בְּנֶזֶק \u0010y6\u0011 חַיָּב אֲפִלּוּ אָנוּס, \u0010y7\u0011 דְּאָדָם מוּעָד לְעוֹלָם, בֵּין שׁוֹגֵג בֵּין מֵזִיד, בֵּין עֵר בֵּין יָשֵׁן.\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁיָּשֵׁן חַיָּב, בְּשֶׁיָּשְׁנוּ שְׁנֵיהֶם כְּאֶחָד וְנִתְהַפֵּךְ אֶחָד מֵהֶם עַל חֲבֵרוֹ וְהִזִּיקוֹ אוֹ קָרַע בְּגָדָיו. אֲבָל אִם הָיָה אֶחָד יָשֵׁן, וּבָא חֲבֵרוֹ וְשָׁכַב בְּצִדּוֹ, זֶה שֶׁבָּא בָּאַחֲרוֹנָה חַיָּב אִם הִזִּיק לָרִאשׁוֹן. וְאִם הָרִאשׁוֹן הִזִּיקוֹ, פָּטוּר. \u0005וְהוּא הַדִּין בְּכָל אֹנֶס גָּדוֹל כְּזֶה, פָּטוּר הַמַּזִּיק (ר\"י נל\"א ח\"ב)\u0006. וְכֵן אִם הִנִּיחַ כֵּלָיו בְּצַד הַיָּשֵׁן, וְנִתְהַפֵּךְ עֲלֵיהֶם וּשְׁבָרָם, פָּטוּר, שֶׁזֶּה שֶׁהִנִּיחָם בְּצִדּוֹ \u0010y8\u0011 פּוֹשֵׁעַ הוּא בַּמֶּה שֶׁהִנִּיחָם בְּצִדּוֹ.\nשְׁנַיִם שֶׁנִּתְאַבְּקוּ יַחַד, וְאֶחָד הִפִּיל חֲבֵרוֹ לָאָרֶץ, וְנָפַל \u0010y9\u0011 עָלָיו וְסִמָּא אֶת עֵינוֹ, פָּטוּר.\nבְּכָל מָקוֹם שֶׁחוֹבֵל בַּחֲבֵרוֹ בְּכַוָּנָה חַיָּב בְּה' דְּבָרִים, אֲפִלּוּ נִכְנַס חֲבֵרוֹ לִרְשׁוּתוֹ שֶׁלֹּא בִּרְשׁוּת, וְחִבֵּל בּוֹ וְהוֹצִיאוֹ, חַיָּב; דִּנְהִי שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ, אֵין לוֹ רְשׁוּת לַחְבֹּל בּוֹ. אֲבָל אִם הוּא מְסָרֵב בּוֹ וְאֵינוֹ רוֹצֶה לָצֵאת, יֵשׁ אוֹמְרִים שֶׁיֵּשׁ לוֹ רְשׁוּת אֲפִלּוּ לַחְבֹּל בּוֹ כְּדֵי לְהוֹצִיאוֹ. \u0005הַגָּה: וְכֵן מִי שֶׁיֵּשׁ לוֹ מְשָׁרֵת, וְחוֹשֵׁשׁ שֶׁיִּגְנֹב לוֹ, יוּכַל לְהוֹצִיאוֹ קֹדֶם זְמַן הַשְּׂכִירוּת; \u0010y10\u0011 וְאִם מְסָרֵב, יוּכַל לְהַכּוֹתוֹ עַד שֶׁיֵּצֵא (מָרְדְּכַי פֶּרֶק הַמַּנִיחַ)\u0006.\nנִכְנַס לַחֲצַר חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וְלֹא יָדַע בַּעַל הַבַּיִת שֶׁנִּכְנַס, \u0010y11\u0011 וְהִזִּיקוֹ בַּעַל הַבַּיִת שֶׁלֹּא בְּכַוָּנָה, פָּטוּר. וְאִם הֻזַּק בּוֹ בַּעַל הַבַּיִת, חַיָּב, כֵּיוָן שֶׁנִּכְנַס שֶׁלֹּא בִּרְשׁוּת. וְדַוְקָא בְּשֶׁלֹא יָדַע בּוֹ וְלֹא רָאָהוּ שֶׁנִּכְנָס, אֲבָל רָאָהוּ, פָּטוּר, דְּאִיהוּ דְּאַזִּיק \u0010y12\u0011 אַנַּפְשֵׁהּ.\nהָיוּ שְׁנֵיהֶם בִּרְשׁוּת אוֹ שְׁנֵיהֶם שֶׁלֹּא בִּרְשׁוּת, וְהֻזְּקוּ זֶה בְּזֶה, שְׁנֵיהֶם פְּטוּרִים. \u0005הִזִּיקוּ זֶה אֶת זֶה בְכַוָּנָה, שְׁנֵיהֶם חַיָּבִים (טוּר ס\"ט)\u0006. וְעַיֵּן לְעֵיל סִימָן שע\"ח \u0010y13\u0011\nהַמְבַקֵּעַ עֵצִים בִּרְשׁוּת הָרַבִּים, וּפָרַח עֵץ מֵהֶם וְהִזִּיק בִּרְשׁוּת הַיָּחִיד, אוֹ שֶׁבָּקַע בִּרְשׁוּת הַיָּחִיד וְהִזִּיק בִּרְשׁוּת הַיָּחִיד אַחֵר, \u0010y14\u0011 אוֹ שֶׁנִּכְנָס לַחֲנוּתוֹ שֶׁל נַגָּר, בֵּין בִּרְשׁוּת בֵּין שֶׁלֹּא בִּרְשׁוּת, וְנִתְּזָה בְּקַעַת וְטָפְחָה לוֹ עַל פָּנָיו, חַיָּב בְּד' דְּבָרִים וּפָטוּר מֵהַבֹּשֶׁת.\nהָיְתָה לוֹ אֶבֶן מֻנַּחַת בְּחֵיקוֹ, בֵּין שֶׁלֹּא הִכִּיר בָּהּ מֵעוֹלָם בֵּין \u0010y15\u0011 שֶׁהִכִּיר בָּהּ וּשְׁכָחָהּ, וְעָמַד וְנָפְלָה וְהִזִּיקָה, וְכֵן אִם נִתְכַּוֵּן לִזְרֹק שְׁנַיִם \u0010y16\u0011 וְזָרַק אַרְבָּעָה וְהִזִּיק, אוֹ שֶׁהִזִּיק כְּשֶׁהוּא יָשֵׁן, חַיָּב בְּנֶזֶק וּפָטוּר מִד' דְּבָרִים.\nמִי שֶׁנָּפַל מִן הַגַּג בְּרוּחַ מְצוּיָה וְהִזִּיק, \u0010y17\u0011 חַיָּב בְּד' דְּבָרִים וּפָטוּר מֵהַבֹּשֶׁת. נָפַל בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה, חַיָּב בְּנֶזֶק בִּלְבַד וּפָטוּר מִד' דְּבָרִים \u0005(וְע\"ל סִימָן תי\"ח סי\"ג)\u0006. \u0010y18\u0011 וְאִם נִתְהַפֵּךְ, חַיָּב בַּכֹּל, אַף בְּבֹשֶׁת; שֶׁכָּל הַמִּתְכַּוֵּן לְהַזִּיק, אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן לְבַיֵּשׁ, חַיָּב בְּבֹשֶׁת.\nהַמַּזִּיק לְאִשְׁתּוֹ בְתַשְׁמִישׁ הַמִּטָּה, \u0010y19\u0011 חַיָּב בִּנְזָקֶיהָ. הָאוֹמֵר \u0010y20\u0011 לַחֲבֵרוֹ: קְטַע אֶת יָדִי, אוֹ: סַמֵּא אֶת עֵינִי עַל מְנַת שֶׁאַתָּה פָטוּר, הֲרֵי זֶה חַיָּב בַּחֲמִשָּׁה דְבָרִים, שֶׁהַדָּבָר יָדוּעַ שֶׁאֵין אָדָם רוֹצֶה בְכָךְ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם אָמַר לוֹ בְּפֵרוּשׁ: עַל מְנַת לִפְטֹר, פָּטוּר; אֶלָּא שֶׁאִם לֹא אָמַר לוֹ בְּפֵרוּשׁ, רַק דְּבָרִים שֶׁמַּשְׁמָעָן כָּךְ, אָנוּ דָנִין דְּבָרָיו שֶׁלֹּא פְטָרוֹ, \u0010y21\u0011 כְּגוֹן שֶׁאָמַר לוֹ: קְטַע יָדִי, אוֹ: סַמֵּא עֵינִי, וְאָמַר לוֹ הַמַּזִּיק: עַל מְנַת לִפְטֹר, וְאָמַר לוֹ הַנִּזָּק: הֵן, אָנוּ דָנִין שֶׁבִּתְמִיהָה קָאָמַר הֵן, וְחַיָּב הַמַּזִּיק (טוּר סי\"א בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010c0\u0011\nשְׁנַיִם שֶׁחָבְלוּ זֶה בְּזֶה, אִם חָבַל הָאֶחָד בַּחֲבֵרוֹ יוֹתֵר מִמַּה שֶׁחָבַל בּוֹ הוּא, \u0010y22\u0011 מְשַׁלֵּם לוֹ בַּמּוֹתָר נֶזֶק שָׁלֵם. וְדַוְקָא שֶׁהִתְחִילוּ שְׁנֵיהֶם כְּאֶחָד, אוֹ לְאַחַר שֶׁחָבַל \u0010y23\u0011 בַּחֲבֵרוֹ חָזַר גַּם הוּא מִיָּד וְחָבַל בּוֹ; אֲבָל אִם הִתְחִיל הָאֶחָד, הַשֵּׁנִי פָטוּר, שֶׁיֵּשׁ לוֹ רְשׁוּת לַשֵּׁנִי לַחְבֹּל בּוֹ \u0010y24\u0011 כְּדֵי לְהַצִּיל עַצְמוֹ. \u0010y25\u0011 \u0010c1\u0011 \u0005וְכֵן הוּא לְעִנְיַן גִּדּוּפִים וּבִיּוּשִׁים, הַמַּתְחִיל פּוֹרֵעַ הַקְּנָס (הַגָּהוֹת מָרְדְּכַי דְקִדּוּשִׁין)\u0006. רְאוּבֵן שֶׁהִכָּה לְשִׁמְעוֹן, וְחָזַר שִׁמְעוֹן וּבָא לְהַכּוֹתוֹ לִרְאוּבֵן, \u0010y26\u0011 וּבָאתָה אִשְׁתּוֹ שֶׁל רְאוּבֵן וְהֶחֱזִיקָה בְּשִׁמְעוֹן, וְהוּא נִתֵּק יָדָיו וְהִכָּה אוֹתָהּ, פָּטוּר \u0005(מהרי\"ו סִימָן כ\"ח)\u0006. וְע\"ל סוֹף סִימָן תכ\"ד אִישׁ וְאִשָּׁה שֶׁחָבְלוּ זֶה בְּזֶה. וּמִיהוּ צָרִיךְ אֹמֶד, אִם הָיָה יָכוֹל לְהַצִּיל עַצְמוֹ בְּחַבָּלָה מוּעֶטֶת וְחָבַל בּוֹ הַרְבֵּה, חַיָּב. \u0005וְדַוְקָא לְעִנְיַן חַבָּלָה שֶׁמְּשַׁלֵם לוֹ ד' דְּבָרִים, דְּהָוֵי כְּאָדָם הַמַּזִּיק בְּשׁוֹגֵג; אֲבָל פָּטוּר עַל הַבֹּשֶׁת, דְּהָא לֹא כִּוֵּן לְבַיֵּשׁ. וְלָכֵן הַמַּכֶּה חֲבֵרוֹ, וַחֲבֵירוֹ קְרָאוֹ מַמְזֵר, פָּטוּר, שֶׁנֶּאֱמַר: וְהָיָה כִּי יֵחַם לְבָבוֹ וְגוֹ' (דְּבָרִים יט, ו)\u0006. וְכֵן אִם אֶחָד קָרָא לַחֲבֵרוֹ גַּנָּב, וְהוּא אוֹמֵר לוֹ: \u0010c2\u0011 אַתָּה מְכַזֵּב כְּמַמְזֵר, אוֹ קְרָאוֹ מַמְזֵר, פָּטוּר מֵהַאי טַעֲמָא \u0005(מהרי\"ו סִימָן כ\"ח וְסִימָן ס')\u0006. וְכֵן הַדִּין בְּאָדָם הָרוֹאֶה אֶחָד מִיִּשְׂרָאֵל מַכֶּה חֲבֵרוֹ, וְאֵינוֹ יָכוֹל לְהַצִּילוֹ אִם לֹא שֶׁיַּכֶּה הַמַּכֶּה, יָכוֹל לְהַכּוֹתוֹ, \u0010y27\u0011 כְּדֵי לְאַפְרוּשֵׁי מֵאִסוּרָא. \u0005הַגָּה: וְכֵן מִי שֶׁהוּא תַּחַת רְשׁוּתוֹ, וְרוֹאֶה בּוֹ שֶׁהוּא עוֹשֶׂה דְּבַר עֲבֵרָה, רַשַּׁאי לְהַכּוֹתוֹ וּלְיַסְּרוֹ כְּדֵי לְהַפְרִישׁוֹ מֵאִסּוּר, וְאֵין צָרִיךְ לַהֲבִיאוֹ לְבֵית דִּין (ת\"ה סִימָן רי\"ח)\u0006.\nשְׁנַיִם שֶׁחָבְלוּ בְּאֶחָד כְּאֶחָד, שְׁנֵיהֶם חַיָּבִים, וּמְשַׁלְּשִׁים בֵּינֵיהֶם. הָיָה אֶחָד מִתְכַּוֵּן וְהַשֵּׁנִי לֹא כִּוֵּן, הַשֵּׁנִי פָּטוּר מִבֹּשֶׁת:",["\u0003עד שיכוון לביישו כו'. \u0004 כבר נתבאר זה בסי' ת\"ך סל\"ו דין ישן שבייש פטור ודהוא מדכתיב והחזיקה במבושיו דמיניה למדין דין בשת ובעינן דומה לו שמתכוין לכך:","\u0003לפיכך ישן שבייש פטור \u0004 כ\"כ ג\"כ בטור והוא פשיטא ממ\"ש כבר דבעינן כוונה ובפרישה כתבתי דה\"ק ומה\"ט תנינא ישן שבייש פטור:","\u0003דהרי לא כוון לביישו. \u0004 אלא לגבות ממנו הזיקו:","\u0003נותן לגדול דמי בשתו של קטן. \u0004 בסי' ת\"ך סל\"ז נתבאר דבקטן אין חייבין על בושתו אלא בתנאי שכשמכלימין אותו הוא נכלם ושם ג\"כ כתב המחבר דמ\"מ אין דומה המבייש הקטן להמבייש הגדול וזה שכ' כאן שאינו נותן לו אלא דמי בשת של קטן שהרי לא נתכוון אלא לבשת כזה ולבושת היתרה לא כוון ובשת שלא בכוונה אין מחייבין עליו:","\u0003יש אומרי' דצער כו'. \u0004 דין זה כתבו הטור וגם שאר פוסקים בפשיטות בלי פלוגתא ומה שסיים וכתב ז\"ל אבל בנזק חייב אפי' אונס כו' בסמוך כ' הטור והמחבר בסעיף י\"א דאפי' נפל מהגג ברוח שאינה מצויה חייב בנזק וע\"ל ר\"ס שע\"ח מ\"ש המחבר בשני סעיפים תכופים זה לזה סא\"ב ושם כתבתי בספר מאירת עינים מוכח מדברי הטור והמחבר שמחלקים בין נפל על גבי אדם והזיקו דחייב בנזקו אפילו בנפל ברוח שאינו מצויה. ובין נפל על הכלים דאינו חייב בנזק כ\"א ברוח מצויה ובסי' זה מנפל ע\"ג אדם איירי מ\"ה סתמו הטור והמחבר בסעיף י\"א וכתבו דאפי' ברוח שאינו מצוי' חייב ע\"ש ודו\"ק:","\u0003חייב אפי' שלא בכוונה \u0004 נלמד מדכתיב כי יריבון כו' ושם קרוב למזיד הוא וריפוי ושבת כתובין שם וה\"ה לצער:","\u0003אפי' אנוס \u0004 ילפינן לה מיתורא דקרא דכתיב פצע תחת פצע והל\"ל פצע בפצע וכל מה דמצינן לפטור שוגג פטרינן לכן לא אוקמינן האי יתורא דקרא כ\"א אנזק:","\u0003דאדם מועד לעולם \u0004 מ\"מ לכ\"ע אאונס גדול אינו חייב וכמ\"ש הטו' והמחב' ומור\"ם בסמוך בס\"ד וגם זה מבוא' בסי' שע\"ח ובשאר מקומות.","\u0003פושע הוא. \u0004 בכלל פושע הוא דקאמ' הוא נמי דאם הישן הוזק בהכלים שהונחו בצדו שחייב בעל הכלים בנזקי דהישן וק\"ל:","\u0003וסימא את עינו פטור טעם הדבר כיון דהתאבקו שניהם ברצון וכל אחד דעתו היה להפיל חבירו וכל אחד ידע שא\"א לצמצם שיפילו דוקא באופן שלא יהיה בו היזק ה\"ל כאלו נתייאשו ומחלו אהדדי שאף אם יארע לא' היזק יהיה מה שיהיה כיון שלא נתכוון חבירו להזיקו אלא שקרה לו דרך נפילתו שיהיה פטור דומה למ\"ש בשנים שרצין בר\"ה והזיקו זא\"ז דרך ריצתן דפטו' המזיק משום דכל הרץ בר\"ה יודע שגם לאחרים יש רשות לרוץ בר\"ה וכאשר יפגשו שניהם הרצין זה נגד זה דרכן להזיק זא\"ז. ואע\"ג דאמרינן אדם מועד לעולם ע\"כ לאו בכל ענין אמרוהו דהרי בהזיקת אונס גמור פטור וכאשר כתבתי טעם זה כן הוא דברי הרא\"ש בתשובותיו הביאו הטו' בסי' זה וכמ\"ש בפרישה ועפ\"ר בסי' שע\"ח ס\"ח שם כתבתי דבשניהן רצין לאו משום מחילה לחוד הוא אלא משום דשניהן עבדו מעשה בהזיקתן ומה\"ט בלא ר\"ה נמי אלא כל שרצין שנים זה כנגד זה וכ\"כ הטור בשם הרמ\"ה שם בהדיא וע\"ש בדרישה דכתבתי שנראה דהטו' בשם רש\"י חולק על הרמ\"ה הנ\"ל ושי\"ל דאין חולקין ועמ\"ש כאן בפרישה מיד מזה:\u0004","\u0003ואם מסרב יכול להכותו \u0004 בגמרא אמרו כן בעבד עברי ולמדו כן מדכתיב לא תקחו כופר לשוב וגו' ודרשינן לא תקחו שופר לשב פי' מי שדינו להיות שב אל משפחתו:","\u0003והזיקו בעל הבית כו' \u0004 דלא מסיק בעל הבית אדעתיה שיכנס אדם לרשותו שלא מדעתו ועיין בטור שכתב שם עוד בבא א' ז\"ל ואם זה שנכנס ניזק מאליו בע\"ה פטור והב\"י כתב דט\"ס הוא וגם כאן השמיטו המחבר ובפרישה כתבתי דטעמא דב\"י הוא דס\"ל דנלמד במכ\"ש מהבבא הראשונה דאפי' הזיקו הב\"ה פטור וכ\"ש אם הוזק מאיליו בב\"ה מיירי ושם כתבתי דנ\"ל דא\"צ למוחקו דאלו ברישא אינו פטור הב\"ה אלא כשלא ידע מזה שנכנס ומציעתא זו דהוזק בו מאיליו מיירי אפי' ידע ממנו שנכנס אפ\"ה פטור כיון דהוזק מאיליו וק\"ל:","\u0003היו שניהם ברשות כו'. \u0004 כבר נתבא' טעמו דכל ששניהן שווין הן היה לזה לשמו' כמו זה וכיון שהזיקו שלא בכוונה זא\"ז היזק כזה מחלו מתחל' אהדדי:","\u0003המבקע עצים בר\"ה כו'. \u0004 לא זו אף זו קאמר ל\"מ אם הבקיעה היתה במקום דשכיחי רבים דהיה לו ליזהר טפי דחייב אלא אפי' הבקיעה היתה ברה\"י וגם ההיזק נעשה במקום דלא שכיחי בה רבים אפי' הכי חייב (ובטו' כ' עוד בבא דאם הבקיעה ברה\"י והזיק בר\"ה חייב והמחב' קיצר דנלמד במכ\"ש מהסיפא) ל\"מ בנזק אלא אפי' בשאר ג' דברים משום דקרוב לפשיעה הוא זה זולת הבושת דפטר כיון דלא כוון לזה:","\u0003או שנכנס בחנותו של נגר. \u0004 לשון הטור וריב\"א פי' אפי' לא ראוהו נכנס חייב דכל אומן שדרך בני אדם לכנס לביתו בשביל אומנתו יש ליזהר יותר עכ\"ל ור\"ל אף שזה לא נכנס כדי לקנות ממנו מ\"מ מוזהר ועומד הוא על כל הנכנסים כיון שדרך לכנוס וליקח ממנו:","\u0003שהכיר בה ושכחה \u0004 ג\"ז דומה לאונס הוא:","\u0003וזרק ארבע כו'. \u0004 בטור כ' עוד ז\"ל או שנתכוון לזרוק ד' וזרק שמונה כו' ועפ\"ר שכתבתי טעם למה כ' זה עיין בטור שכ' כאן עוד דין הזורק אבן ואח\"כ הוציא ראשו וקבלה פטור מד' דברים וחייב בנזק כו' והמחב' כתבו בסי' ת\"ך ס\"ל וכ' שם דפטור מכולם ולאפוקי מהטור שכ' שחייב בנזק ע\"ש:","\u0003חייב בד' דברים \u0004 ז\"ל הטור דשוגג קרוב למזיד הוא דלא היה לו לעלות לגג שאין לו מעקה כיון שיכול ליפול ברוח מצויה:","\u0003ואם נתהפך \u0004 ל' הטור ואם נתהפך דרך נפילתו כדי שיפול על האדם להנאתו כדי שלא יחבט בהקרקע:","\u0003חייב בנזקיה \u0004 ל' הטור חייב בד' דברים וגם המחב' דכ' בנזקיה ר\"ל כל נזקי' זולת הבושת דלאו בכלל נזקיה הוא דהא לא כוון לביישה אבל בשאר דברים אע\"ג דיש לו רשות לשמש עמה מ\"מ ה\"ל לעיוני דלא יזיק ודין המעות דנותן בהד' דברים יתבאר בסי' תכ\"ג מה עושה בהן ואיך דינן גם בא\"ע סימן פ\"ג:","\u0003קטע את ידי כו'. \u0004 עד\"ר שם כתבתי דלסברא זו דס\"ל דאפי' א\"ל מתחלה בפי' מ\"מ לפטור אפ\"ה חייב בהני דוקא קאמר דחייב כיון דהן ראשי איברים ידועים ואין אדם רוצה בחסרון איברים הללו וסבור שחבירו לא יקטעו ויסמאוהו אע\"ג דא\"ל ע\"מ לפטו' אבל אם א\"ל הכני פצעני ע\"מ לפטור והוא פצע בו בלא חסרון ראשי איברים הוא פטו' כמו בא\"ל שבור את כדי ושאר כלים לעיל וכמ\"ש הטור והמחב' ר\"ס ש\"פ ע\"ש:","\u0003כגון שא\"ל קטע את ידי כו' \u0004 עד שבתמיה קאמר ובהאי דלא א\"ל בפי' ע\"מ לפטור אלא נוכל לומר דבתמיה קאמר אפי' בלא ראשי איברים נמי אמרי' דבתמיה קאמר וחייב ולא נקט קטע ידי כו' אלא ללמדינו דאם אמר בפי' ע\"מ לפטור דפטור אפי' בהני ודוקא בהיזק ממון הוא דפטרינן ליה אף בל' המתפרש דבתמיה קאמר וכמ\"ש הטור והמחבר לעיל ר\"ס ש\"פ ע\"ש ולא בצער דגופו ודלא כע\"ש דכ' דגם י\"א הללו לא חייבוהו בסתם אלא בראשי איברים דז\"א ועיין בפרישה ודרישה כאן ולעיל בסי' ש\"פ:","\u0003משלם במות' נזק שלם \u0004 ע\"ל בסי' ת\"ב מ\"ש בהיזק שור בשור בתשלומי במותר נזק שלם ומינה יש ללמד לאדם באדם:","\u0003חזר גם הוא מיד גם בטור כ' כאן כהאי לישנא ז\"ל או לאחר שחבל זה בחבירו חזר גם הוא מיד וחבל בו אבל כו' ובפרישה כתבתי דלכאורה נראה דהאי מיד ט\"ס הוא דאם השני חזר וחבלו מיד בעודו בחימום הוא פטור וגם לעיל בס\"ס ת\"ב בשני שוורים לא כ' הטור ומור\"ם לתיבת מיד אלא ז\"ל או לאחר שנפרדו זה מזה חזר השני כו' ושניהן נשנו בפ' המניח (בבא קמא דף ל\"ג) במשנה אחת גם באשר\"י שם (דף קל\"ב פ\"א) ולא כ' תיבת מיד אלא ז\"ל או לאחר זמן זה שחבל זה כו' ור\"ל לאחר זמן שכבר נפרדו זה מזה ועבר חימומן ודוחק לו' שגרס' הטור היה באשר\"י כאשר כ' כאן ומחלק בין שוורים לאדם שאדם הוא מועד לעולם וס\"ל דבשני בני אדם אף דהתחיל הא' מ\"מ אם פסק אותו א' אף שעדיין השני המוכה בחמימותו אם חזר וחבלו גם הוא להראשון דחייב דה\"ל להעמידו בדין על הכאתו משא\"כ בשני שוורי' דאין שייך זה מ\"ה כתבו שם דתלה באחר שנפרדו וכאן בשני בני אדם כתבו או לאחר שחבל זה בחבירו פי' ופסק מלהכותו אם חזר גם הוא מיד פי' אפי' בעודו בחמימתו וחבל בו חייב גם הוא ומ\"ש אם התחיל הא' השני פטור ר\"ל הראשון התחיל במריבה וירא השני שיחבל בו וכדי להציל נפשו מההכא' חבל בהראשון או שכבר חבל בו הראשון וירא שיחבול בו עוד וקידם וחבל בהראשון כדי שלא יחבלוהו עוד פטור דאין הל' סובל פי' זה וגם ק' מנ\"ל להרא\"ש והטור לחלק בזה מאחר דהמשנה השוויהן יחד גם בקיצור פסקי הרא\"ש כ' שניהם בל' אחד לכן נראה דט\"ס הוא וה\"ג בדברי הטור והמחבר או לאחר זמן שחבל זה בחבירו חזר גם הוא וחבל בו אז החיוב על שניהן ומשלם במותר נזק שלם אבל אם התחיל הא' וחזר השני וחבל בו מיד השני פטור והיינו כלישנא דהרא\"ש דפ' המניח הנ\"ל ודו\"ק והשתא א\"ש הא דמסיק מור\"ם וכ' אדברי המחבר ז\"ל וכן הוא לענין גדופים כו' עד וכן אם קרא לחבירו גנב והשני קראו ממזר דפטור ולא מחייבינן להשני משום דהיה לו לתובעו בדין ודוק ועמ\"ש מור\"ם שם בסי' ת\"ב תמיה על המחבר ששם סתם ולא חילק כלל וכאן חילק וכתב דאם האחד התחיל השני פטור כתבתי שם ישוב נכון ולק\"מ ע\"ש:\u0004","\u0003כדי להציל עצמו \u0004 דאפי' אחרים חייבים לחבול בהחובל כדי להציל חביריהן כמ\"ש הטור והמחבר בסי' תכ\"ה כ\"ש הוא עצמו:","\u0003וכן הוא לענין גידופין כו'. \u0004 וכתב מהר\"מ מריזבור\"ק ראובן טען על שמעון שקראו ממזר ושמעון אומר שמתחלה לחש לו באזנו שהוא ממזר לכן נתרגז וא\"ל כן אומדנא דמוכח הוא כיון שקראו פתאום ממזר ודאי האמת אתו עכ\"ל וא\"צ לישבע ע\"ז כמ\"ש לעיל סי' ת\"ך סל\"ה עכ\"ל ד\"מ י\"ט:","\u0003ובאתה אשתו כו'. \u0004 וכתב בנימוקי מהר\"מ דדין אשה לענין בזיון כדין איש ואם אין האיש רוצה שתתבזה אשתו צריך לפדותה בממון כפי אשר ישיתו עליו הב\"ד וע\"ל סי' תכ\"ד ס\"י מזה:","\u0003כדי לאפרושי מאיסורא. \u0004 בטור כתב עוד בבא א' לפני בבא זו וכן הדין באדם הרואה את חבירו שמכה לאביו או בנו או אחיו והרואה הכה המכה כדי להציל את קרובו שפטור עכ\"ל ודקדקתי בפרישה מדלא כייל אחיו ובנו עם סיפא דרואה מכה לא' מישראל גם כתב בכל א' טעם בפני עצמו דבמציעתא כתב כדי להציל את קרובו ובסיפא כ' כדי לאפרושי מאיסורא וכתבתי דאיכא בינייהו נ\"מ לדינא והוא דאם זה הבא להציל ולהכות המכה אינו בר הכי דרגיל לאפרושי מאיסורא דכמה פעמים רואה שמכה א' לחבירו ואינו חושש לאפרושי המכה מאיסורא אז אמרינן דאסור להכות לזה המכה דודאי מכח שנאה בא להכותו ולא בא להפרישו מהאיסור מה שא\"כ ברואה מכה אביו ובנו ואחיו דמותר להציל קרובו בהכאה אף שאין מדרכו להפריש אחרים והמחבר דלא חילק בינייהו אפשר משום דלא הרגיש בזה דבאמת טעם הגון הוא לחלק בינייהו ודוק"],["\u0003 שנים שחבלו זה בזה כו'. \u0004 עיין בתשו' מבי\"ט ח\"ב סימן שי\"א:","\u0003 וכן הוא הדין לענין גדופים וביושים כו'. \u0004 עיין בתשובת ר\"א ן' חיים סי' נ' וסי' צ\"ג וסי' קי\"א:","\u0003 אתה מכזב כממזר כו'. \u0004 עיין בנימוקי מהר\"מ מריזבורק וביש\"ש פ\"ח דב\"ק סימן מ\"ב:"]],["הַחוֹבֵל בַּחֲבֵרוֹ, אַף עַל פִּי שֶׁנָּתַן לוֹ ה' דְּבָרִים, \u0010y0\u0011 אֵינוֹ מִתְכַּפֵּר לוֹ עַד שֶׁיְּבַקֵּשׁ מִמֶּנּוּ \u0010y1\u0011 וְיִמְחֹל לוֹ. \u0010y2\u0011 וְאָסוּר לַנֶּחְבָּל לִהְיוֹת אַכְזָרִי מִלִּמְחֹל, כִּי \u0010y3\u0011 אֵין זֶה דֶרֶךְ זֶרַע יִשְׂרָאֵל, אֶלָּא כֵּיוָן שֶׁבִּקֵשׁ מִמֶּנּוּ הַחוֹבֵל וְנִתְחַנֵּן לוֹ \u0010y4\u0011 פַעַם רִאשׁוֹנָה וּשְׁנִיָּה, וְיָדוּעַ שֶׁהוּא שָׁב מֵחֶטְאוֹ וְנִחַם מֵרָעָתוֹ, יִמְחֹל לוֹ. וְכָל הַמְמַהֵר לִמְחֹל הֲרֵי זֶה מְשֻׁבָּח, וְרוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ. \u0005הַגָּה: \u0010y5\u0011 וְעַיֵּן בְּאֹרַח חַיִּים סִימָן תר\"ו. אָסוּר לְבַקֵּשׁ דִּין מִן הַשָּׁמַיִם עַל חֲבֵרוֹ שֶׁעָשָׂה לוֹ רָעָה. וְדַוְקָא דְּאִית לֵהּ דַּיָּנָא בְאַרְעָא. וְכָל הַצּוֹעֵק עַל חֲבֵרוֹ, הוּא נֶעֱנָשׁ תְּחִלָּה (גְּמָרָא פֶּרֶק הַחוֹבֵל)\u0006. וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ לֵית לֵהּ דַּיָּנָא בְּאַרְעָא אָסוּר לִצְעֹק עָלָיו, אֶלָּא אִם כֵּן הוֹדִיעוֹ תְּחִלָּה \u0005(הָרַ\"ן פ\"ק דְּר\"ה)\u0006.\nדִּין נֶחְבָּל נִשְׁבָּע וְנוֹטֵל, נִתְבָּאֵר בְּסִימָן צ'.",["\u0003אינו מתכפר לו עד כו'. \u0004 כן הוא ל' המשנה והברייתא בפרק החובל (בבא קמא דף צ\"ב ע\"א) גם ברמב\"ם כ\"כ אבל רש\"י פי' שם דקאי אצער דבושת וכ\"כ בקיצור פסקי הרא\"ש גם בטורים המדויקים כ\"כ בהדיא אבל בדפוס ב\"י כתב צער והבושת:","\u0003וימחול לו. בגמרא למדו זה מדכתי' באבימלך ועתה השב את אשת האיש כו' ויתפל בעדך. ונראה דהלימוד משם הוא דאם רצה הש\"י למחול לו היה מוחל לו בלא תפילת אברהם אלא למדונו שצריך לפייסו עד שימחול לו במחילה גמורה ואז יתפלל בעדו:\u0004","\u0003ואסור לנחבל כו'. \u0004 גם זה נלמד מאותו מעשה דהרי אברהם נתפייס מאבימלך והתפלל בעדו כמ\"ש בכתוב:","\u0003ה\"ג אין זה דרך זרע ישראל כו'. \u0004 ור\"ל שג' סימנים יש לזרע אברהם ביישנים רחמנים גומלי חסדים ורחמנים הוא היפך אכזריות:","\u0003פעם הראשונה ושנייה. \u0004 ובא\"ח סי' תר\"ו כתב הטור והמחבר ראשונה ושנייה ושלישית שם קאי אהמפייס וקאמר שאם לא נתפייס בשני פעמים ילך אצלו גם פעם שלישית וכאן למדונו שזה שמפייסין אותו יהיה רחמן ולא ימתין עד שילך ויבא אצלו שלישית אלא ימחול לו בראשונה או בשנייה וק\"ל:","\u0003ועיין בא\"ח סי' תר\"ו \u0004 שם כתב מור\"ם בהג\"ה דאם הוציא עליו שם רע א\"צ למחול לו עכ\"ל והוא מדברי הג\"מ פ\"ב דהל' תשובה ומהרי\"ל והטעם דשם רע פגע בכבוד אבותיו או בניו לדורות ושמא היו אנשים דשמעו הש\"ר ולא ישמעו החרטה והמחילה ויסברו שהוא אמת:"],[]],["הַנּוֹגֵף אֶת הָאִשָּׁה וְיָצְאוּ יְלָדֶיהָ, \u0010y0\u0011 אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן, חַיָּב לְשַׁלֵּם דְּמֵי וְלָדוֹת לְבַעְלָהּ, \u0010y1\u0011 וְנֵזֶק וְצַעַר לָאִשָּׁה. וְכֵיצַד מְשַׁעֲרִין דְּמֵי וְלָדוֹת, שָׁמִין אֶת הָאִשָּׁה כַּמָּה הָיְתָה יָפָה עַד שֶׁלֹּא יָלְדָה, \u0010y2\u0011 וְכַמָּה הִיא יָפָה מִשֶּׁיָּלְדָה, וְנוֹתְנִים לַבַּעַל. \u0005וְצַעַר וְנֶזֶק מְשַׁעֲרִין כַּמָּה תִּפְחַת הָאִשָּׁה וְנִכְחֶשֶׁת יוֹתֵר כְּשֶׁהִיא מַפֶּלֶת עַל יְדֵי הַכָּאָה מִשֶּׁיָּלְדָה כְּדַרְכָּהּ. \u0010y3\u0011 וְכֵן בְּשֶׁבֶת וְרִפּוּי, אִם צְרִיכָה לְכָךְ (טוּר ס\"א)\u0006. וְעַיֵּן בְּאֶבֶן הָעֵזֶר סִימָן פ\"ג. וְאִם מֵת הַבַּעַל, נוֹתְנִים לְיוֹרְשָׁיו. \u0005(שָׁם בְּשֵׁם הרמב\"ם ד\"ב)\u0006. וְאִם נְגָפָהּ אַחַר מִיתַת הַבַּעַל, נוֹתְנִים אַף \u0010y4\u0011 דְּמֵי וְלָדוֹת לָאִשָּׁה. \u0010y5\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּהוּא שֶׁל יוֹרְשָׁיו (טוּר בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006.\nהָיְתָה נְשׂוּאָה לְגֵר, וְחִבֵּל בָּהּ בְּחַיֵּי הַגֵּר, נוֹתֵן דְּמֵי וְלָדוֹת לַבַּעַל. \u0010y6\u0011 מֵת הַגֵּר, פָּטוּר. וְאִם חָבַל בָּהּ אַחַר מִיתַת הַגֵּר, \u0010y7\u0011 זָכְתָה הִיא בִּדְמֵי וְלָדוֹת. \u0010y8\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּהוּא פָטוּר (טוּר ס\"ג בְּשֵׁם הָרֹא\"שׁ)\u0006.\nהָיְתָה שִׁפְחָה אוֹ גוֹיָה בִּשְׁעַת הֵרָיוֹן, וּבִשְׁעַת נְגִיפָה נִשְׁתַּחְרְרָה אוֹ \u0010y9\u0011 נִתְגַיְּרָה, הֲרֵי דְּמֵי וְלָדוֹת שֶׁלָּהּ. \u0010y10\u0011 \u0010c0\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם בַּעְלָהּ קַיָּם הֲרֵי הֵן שֶׁל בַּעַל; \u0010y11\u0011 וְאִם לָאו, הוּא פָטוּר (טוּר ס\"ד בְּשֵׁם הָרֹא\"שׁ)\u0006.\nהַנּוֹגֵף אֶת הָאִשָּׁה וְיָצְאוּ יְלָדֶיהָ וָמֵתָה, אַף עַל פִּי שֶׁהָיָה שׁוֹגֵג, הֲרֵי זֶה פָטוּר מֵהַתַּשְׁלוּמִין וְאֵינוֹ מְשַׁלֵּם כְּלוּם, \u0010y12\u0011 שֶׁנֶּאֱמַר: וְלֹא יִהְיֶה אָסוֹן עָנֹשׁ יֵעָנֵשׁ \u0005(שְׁמוֹת כא, כב)\u0006 ; \u0005(לֹא חִלֵּק הַכָּתוּב בֵּין שׁוֹגֵג לְמֵזִיד בְּדָבָר שֶׁיֵּשׁ בּוֹ מִיתַת בֵּית דִּין לְפָטְרוֹ מִן הַתַּשְׁלוּמִין\u0006 \u0010y13\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁנִּתְכַּוֵּן לָאִשָּׁה. אֲבָל אִם נִתְכַּוֵּן לַחֲבֵרוֹ, וְנָגַף אֶת הָאִשָּׁה, אַף עַל פִּי שֶׁמֵּתָה, הוֹאִיל וְהֵמִיתָהּ בְּלֹא \u0010y14\u0011 כַּוָּנָה הֲרֵי זֶה כְּדָבָר שֶׁאֵין בּוֹ מִיתַת בֵּית דִּין, וּמְשַׁלֵּם דְּמֵי וְלָדוֹת. \u0005וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ לֹא נִתְכַּוֵּן לָאִשָּׁה פָּטוּר מִתַּשְׁלוּמִין (טוּר ס\"ה בְשֵׁם הָרַאֲבַ\"ד)\u0006.",["\u0003אע\"פ שלא נתכוין כו'. \u0004 דכתיב בפרשת משפטים וכי ינצו אנשים ונגפו אשה הרה ויצאו ילדיה ולא יהיה אסון ענוש יענש כאשר ישית עליו בעל האשה דמדכתיב וכי ינצו אנשים למדונו דלא נתכוין להאשה ומדכתיב ולא יהיה אסון פי' בהאשה הנוגפת למדונו דבזה דוקא יהיה עליו חיוב תשלומין הוולדות הא אם יהיה בה אסון מיתה פטור מדמי וולדות דקם להו בדרבה מיניה וכמ\"ש הטור והמחבר בס\"ס זה ע\"ש ומדכתיב בעל האשה למדונו שזכתה התורה דמי הולדות לבעלה:","\u0003ונזק וצער של האשה. \u0004 עיין בא\"ה סי' פ\"ג שם כ' הטור והמחבר דהנזק והפגם הוא שלו ושלה ולק\"מ דשם קאי אנזק דקטיעת ידה או אבר שמחסרה ממלאכתה מ\"ה יש לו חלק בו דהא מכח זה נתבטלה ממלאכתו משא\"כ כאן דמיירי מכחישת גופה דאין לו חסרון ממלאכתו כ\"א שבת בעודה בחליות' ואותה משלם להבעל ועפ\"ר:","\u0003וכמה היא יפה משילדה. \u0004 פי' אם היא ילדה בלא הכאה אלא שהיא ריקנית בלא ולד ומשום דלפעמים אשה מפלת ג\"כ מעצמה בלי נגיפה והכאה מ\"ה אין עליו לשלם כל דמי הולד אלא בכמה אדם קונה אשה הרה ביוקר כדי שאם תלד יהיה הולד שלו דאין נותן בה כ\"כ דמים דשמא תפיל ולא תשארה בידו אלא ריקנית וק\"ל והיינו פחת דמי הולדות דזכתה לו התורה אבל מה שנכחש גופה מחמת כאב הכאתה זהו מקרי נזק ועליו כ' הטור והמחבר דהוא של האשה:","\u0003וכן בשבת וריפוי. \u0004 והריפוי נותן לרופא והשבת לבעל משום דמעשה ידיה הוא שלו וכ\"כ בטור עוד כ' שם דהבושת אם הוא בסתר לו חלק א' ולה שני חלקים ואם הוא בגלוי לה חלק א' ולו שני חלקים ולא ידעתי למה השמיטו המחבר. ופי' סתר ובגלוי בדבר זה נראה דר\"ל דההכאה היה בסתר שלא היו רואין בדבר או בגלוי במקום רואין ועפ\"ר מ\"ש עוד בזה וגם עיין בטור א\"ע סי' פ\"ג דכ' שם בדין ריפוי אם אמדוהו לרפאותו בה' ימים ועבדה לה סמא חריפא ונתרפאת בג' ימים דהוא בכלל צער והוא שלה:","\u0003דמי יולדות לאשה. \u0004 פי' ולא ליורשיו משום דאין אדם מוריש ליורשיו דבר שלא בא לעולם דבחייו עדיין לא נגפה והן שלה כיון דכתיב בתורה ויצאה ילדיה ולא כתיב הילדים ללמדינו ששמה נקרא על ילדיה היכא דאין לאב זכייה בהן:","\u0003דהוא של יורשיו \u0004 דכיון דזיכתה התורה להיות דמי הולדות שלו נחשבו הולדות כשהן במעי אמן של הבעל וכשמת שם יורשיו נקראין עליהן ועומדים במקומו גם בזה:","\u0003מת הגר פטור \u0004 פי' ואינם נותנים ליורשיו דאין יורשי הגר יורשים אותו וכמ\"ש הטור והמחבר לעיל בסי' רע\"ה:","\u0003זכתה היא בדמי כו'. \u0004 דומיא דאשה ישראלית שנגפה אחר מיתת הבעל דפסק המחבר לעיל דנותנין לאשה דמי הוולדות ולא ליורשיו:","\u0003דהוא פטור. \u0004 ג\"כ הוא מטעם דס\"ל לי\"א הנ\"ל באשה דעלמא דאין האשה זכה בהן כ\"א יורשיו ובגר דאין יורשיו יורשין אותו ממילא פטור הנוגף:","\u0003הרי דמי הולדות שלה \u0004 דכיון דאין הקדושין תופסין בשפחה ועכו\"ם משום ישראל לא קרינן ביה בעל האשה ואין לישראל זה שנתעברה ממנו זכייה בהולדות ואף שהוא חי בשעת נגיפה (ול\"ד לישראל שנתעברה מישראל בזנות דקי\"ל דדמי הולדות הוא של הבועל דשם בני קידושין נינהו וכ\"כ המ\"מ שם) ומ\"ה הדמים הן שלה משום דס\"ל דזכתה התורה לה היכא דאין להבעל בהן זכייה כנ\"ל:","\u0003וי\"א דאם בעלה קיים הרי הן של בעל. \u0004 פי' כשנתעברה מישראל וכנ\"ל וטעמם דמדמי זה לישראל המזנה עם ישראלית:","\u0003ואם לאו הוא פטור. \u0004 י\"א הללו ג\"כ לטעמם הנ\"ל אזלי דאין לאשה שום זכייה בדמי וולדותי':","\u0003שנאמר ולא יהיה אסון כו'. ה\"ג יענש לח חילק הכתוב בין שוגג למזיד בדבר שיש בו מיתת ב\"ד לפוטרו מהתשלומין בד\"א כו' וכן ברמב\"ם שם:\u0004","\u0003כשנתכוין לאשה כו' \u0004 אף ע\"ג דקרא איירי בשנים שמריבין ומכוין להכות לחברו ונגף האשה שלא בכוונה וכמ\"ש בר\"ס זה מ\"מ הדיוק דלמדנו מולא יהיה אסון הא אם יהיה אסון פטור מדמי ולדות משום דקם ליה בדרבה מיניה זה (לא) שייך כשלא נתכוין להאשה דס\"ל דאין צד מיתה בכה\"ג אבל כשנתכוין להאשה אע\"פ שהיה שוגג במיתתה למדנו מקרא כל שאם מזיד היה חייב מיתה אפילו אם היה שוגג באותה מיתה ג\"כ פטור מממון וכמו שכ' הטור והמחבר בריש סי' שאחר זה:","\u0003כדבר שאין בו מיתת בית דין. \u0004 כן הוא ג\"כ ל' הרמב\"ם שם בפ\"ד דהל' חובל ואע\"ג דסבירא ליה להרמב\"ם דאין מיתת בית דין בנתכוין להרוג את זה והרג את זה וכמו שכתוב שם מכל מקום כ' כדבר בכ\"ף הדמיון משום דבהרג שוגג ג\"כ אין מיתת בין דין ואפי' הכי אמרי' דפטור מדמי וולדות כיון דאיכא צד מיתת בית דין אם היה מזיד וה\"נ ג\"כ בלא נתכוון להקמ\"ל דבכזה אמרינן כאלו אין כאן צד מיתת בית דין כלל:"],["\u0003 דאם בעל הקיים כו' \u0004 ומהרש\"ל פ\"ה דב\"ק סי' י\"ז כתב דלהרא\"ש לעולם אין לו לבעל דהא לא מיקרי בעל כיון דלא תפס בה קידושין ע\"ש דהטור ומור\"ם לא דקדקו בהרא\"ש:"]],["הַחוֹבֵל בְּאָבִיו וְאִמּוֹ \u0010y0\u0011 וְלֹא הוֹצִיא מֵהֶם דָּם, חַיָּב בַּחֲמִשָּׁה דְבָרִים. הוֹצִיא מֵהֶם דָּם, חַיָּב מִיתָה, לְפִיכָךְ פָּטוּר מִתַּשְׁלוּמִין אֲפִלּוּ הוּא שׁוֹגֵג. לְפִיכָךְ, לֹא יַקִּיז הַבֵּן לְאָבִיו, וְלֹא יוֹצִיא קוֹץ מִבְּשָׂרוֹ וְלֹא יִפְתַּח לוֹ מוּרְסָא, שֶׁמָּא יָבֹא לְהוֹצִיא מִמֶּנּוּ דָם. וְנִתְבָּאֵר זֶה בְּטּוּר יוֹרֶה דֵעָה סִימָן רמ\"א.\nהַחוֹבֵל בַּחֲבֵרוֹ בְּשַׁבָּת, פָּטוּר מִתַּשְׁלוּמִין אֲפִלּוּ הוּא שׁוֹגֵג, \u0010y1\u0011 כֵּיוָן שֶׁיֵּשׁ בּוֹ מִיתַת בֵּית דִּין. אֲבָל הַחוֹבֵל \u0010y2\u0011 בַּחֲבֵרוֹ בְּיוֹם הַכִּפּוּרִים, \u0005(אֲפִלּוּ)\u0006 בְּמֵזִיד, חַיָּב לְשַׁלֵּם לוֹ.\nהַחוֹבֵל \u0010y3\u0011 בְּעֶבֶד כְּנַעֲנִי שֶׁלּוֹ, פָּטוּר. חָבְלוּ בּוֹ אֲחֵרִים, רַבּוֹ נוֹטֵל \u0010y4\u0011 ה' דְּבָרִים. וַאֲפִלּוּ צִעֲרוֹ בְּסַם וְנִתְרַפֵּא מְהֵרָה, הֲרֵי כָּל רְפוּאָתוֹ לְרַבּוֹ.\nמִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין, שֶׁהִכָּהוּ אָדָם אוֹ נְגָחוֹ שׁוֹר, נִתְבָּאֵר מִשְׁפָּטוֹ בְּטוּר יו\"ד סִימָן רס\"ז \u0005(סָעִיף ס\"ב)\u0006.\nמִי שֶׁיָּצָא לְחֵרוּת וַעֲדַיִן לֹא הִגִּיעַ גֵּט שִׁחְרוּר לְיָדוֹ, \u0010y5\u0011 וְחָבְלוּ בּוֹ אֲחֵרִים, פְּטוּרִים. \u0010y6\u0011\nהַחוֹבֵל בְּבַת קְטַנָּה שֶׁל אֲחֵרִים, אִם נֶזֶק \u0010y7\u0011 הַפּוֹחֵת אוֹתָהּ מִכַּסְפָּה הוּא, \u0010y8\u0011 הֲרֵי הוּא שֶׁל הָאָב. וְכֵן שִׁבְתָּהּ שֶׁל אָב, שֶׁהֲרֵי מַעֲשֵׂה יָדֶיהָ וְכֶסֶף מְכִירָתָהּ שֶׁל אָבִיהָ \u0010y9\u0011 הוּא. \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא בִּסְמוּכָה עַל \u0010y10\u0011 שֻׁלְּחָנוֹ, אֲבָל אֵינָהּ סְמוּכָה עַל שֻׁלְּחָנוֹ, הוּא שֶׁלָּהּ (טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006. וְיֵשׁ אוֹמְרִים אֲפִלּוּ בִּסְמוּכָה עַל שֻׁלְּחָנוֹ הוּא שֶׁלָּהּ, \u0010y11\u0011 אִם אֲחֵרִים חָבְלוּ בָהּ \u0005(שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006. אֲבָל צַעַר וְרִפּוּי וּבֹשֶׁת, שֶׁלָּהּ. וְכֵן נֶזֶק שֶׁאֵינוֹ פּוֹחֲתָהּ מִכַּסְפָּה הֲרֵי הוּא שֶׁלָּהּ. וְכֵן הַחוֹבֵל בְּבִתּוֹ, מְשַׁלֵּם צַעַר וְרִפּוּי וּבֹשֶׁת. \u0005הַגָּה: וְנִרְאֶה לִי, דַּוְקָא בְּאֵינָהּ סְמוּכָה עַל שֻׁלְּחָנוֹ (ע' בד\"מ)\u0006, אֲבָל סְמוּכָה עַל שֻׁלְּחָנוֹ \u0010y12\u0011 יֵשׁ אוֹמְרִים דְּפָטוּר \u0005(הַמ\"מ לְדַעַת הָרַמְבַּ\"ם)\u0006, כְּמוֹ שֶׁיִּתְבָּאֵר בְּסָמוּךְ:\nהַחוֹבֵל בְּבָנָיו הַגְּדוֹלִים, אִם אֵינָם סְמוּכִים עַל שֻׁלְחָנוֹ, נוֹתֵן לָהֶם מִיָּד; \u0010y13\u0011 וְהַקְּטַנִּים, יִלָּקַח קַרְקַע בְּנִזְקָן, \u0010y14\u0011 \u0005וְיֵשׁ אוֹמְרִים סֵפֶר תּוֹרָה (טוּר סי\"א בְּשֵׁם הָרֹא\"שׁ)\u0006 וְהֵם אוֹכְלִים פֵּרוֹתָיו. וְכֵן בַּאֲחֵרִים שֶׁחָבְלוּ בָּהֶם. וְאִם הָיוּ סְמוּכִים עַל שֻׁלְחָנוֹ, וְחָבַל בָּהֶם \u0005(הוּא)\u0006, פָּטוּר בֵּין שֶׁהָיוּ גְּדוֹלִים בֵּין שֶׁהָיוּ קְטַנִּים; וְאִם אֲחֵרִים חָבְלוּ בָהֶם, בִּגְדוֹלִים יִתֵּן לָהֶם מִיָּד; בִּקְטַנִים, יִלָּקַח בָּהֶם קַרְקַע וְהוּא אוֹכֵל פֵּרוֹתָיו עַד שֶׁיִּגְדְּלוּ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵינוֹ פָטוּר בִּסְמוּכִים עַל שֻׁלְּחָנוֹ אֶלָּא מִשֶּׁבֶת, אֲבָל חַיָּב בִּשְׁאָר ד' דְּבָרִים, וְדִינוֹ בָּהֶם כְּאִלּוּ חָבְלוּ בָהֶן אֲחֵרִים (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nהַחוֹבֵל בְּחֵרֵשׁ שׁוֹטֶה וְקָטָן, חַיָּב; וְהֵם שֶׁחָבְלוּ בַּאֲחֵרִים, פְּטוּרִים; אַף עַל פִּי שֶׁנִּתְפַּקַּח הַחֵרֵשׁ וְנִשְׁתַּפֶּה הַשּׁוֹטֶה וְהִגְדִּיל הַקָּטָן, אֵינָם חַיָּבִים לְשַׁלֵּם, שֶׁבַּשָׁעָה שֶׁחָבְלוּ בָּהֶם לֹא הָיוּ בְּנֵי דַעַת:\nהָעֶבֶד וְהָאִשָּׁה, הַחוֹבֵל בָּהֶם חַיָּב; וְהֵם שֶׁחָבְלוּ בַּאֲחֵרִים, פְּטוּרִים, \u0010y15\u0011 אֲבָל מְשַׁלְּמִים לְאַחַר זְמַן, \u0010c0\u0011 אִם נִתְגָרְשָׁה הָאִשָּׁה אוֹ נִתְאַלְמְנָה אוֹ נִשְׁתַּחְרֵר הָעֶבֶד. \u0005הַגָּה: יֵשׁ לָהּ נִכְסֵי מְלוֹג אוֹ נִכְסֵי צֹאן בַּרְזֶל, מוֹכֶרֶת אוֹתָן לַאֲחֵרִים \u0010y16\u0011 בְּטוֹבַת הֲנָאָה, וּמְשַׁלֶּמֶת לַנֶּחְבָּל (טוּר סי\"ג)\u0006.\nהָאִשָּׁה שֶׁחָבְלָה בְּבַעְלָהּ, \u0010y17\u0011 אִם הָיָה תּוֹסֶפֶת בִּכְתֻבָּתָהּ אוֹ נִכְסֵי מְלוֹג אוֹ נִכְסֵי צֹאן בַּרְזֶל, מְחַיְּבִים אוֹתָהּ לְמָכְרָם לְבַעְלָהּ בְּטוֹבַת הֲנָאָה, וְגוֹבֶה מִמֶּנָּה אִם רָצָה הַבַּעַל. וְאִם רָצָה לְגָרְשָׁהּ וְלִגְבּוֹת מִמֶּנָּה הַכֹּל, גּוֹבֶה; וְאִם לֹא הָיָה לָהּ, אֵינָהּ יְכוֹלָה לִמְכֹּר לוֹ עִקַּר כְּתֻבָּתָהּ, שֶׁאָסוּר לָאָדָם לַשְׁהוֹת אֶת אִשְׁתּוֹ שָׁעָה אַחַת בְּלֹא כְּתֻבָּה, אֶלָּא אִם רָצָה הַבַּעַל כּוֹתֵב עָלֶיהָ שְׁטָר בִּדְמֵי הַחַבָּלָה, אוֹ מְגָרְשָׁהּ וְנוֹטֵל מִכְּתֻבָּתָהּ הָרָאוּי לוֹ. \u0005הַגָּה: וְכֵן אִם הַחַבָּלָה כְּפִי כְּתֻבָּתָהּ, מוֹכֶרֶת כְּתֻבָּתָהּ לְבַעְלָהּ וּמְשַׁלֶּמֶת לְבַעְלָהּ, וְלָא חַיְשִׁינָן שֶׁמָּא תְהֵא קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ, \u0010y18\u0011 שֶׁהֲרֵי אִם יִרְצֶה יוּכַל לְגָרְשָׁהּ וְלִגְבּוֹת בַּחַבָּלָתוֹ (טוּר סי\"ג)\u0006.\nדִּין אֵשֶׁת אִישׁ שֶׁחָבְלוּ בָּהּ אֲחֵרִים אוֹ בַּעְלָהּ, נִתְבָּאֵר בַּטּוּר א\"ה סִימָן פ\"ג. \u0005הַגָּה: אִישׁ, וְאִשָּׁה שֶׁיֵּשׁ לָהּ בַּעַל, שֶׁחָבְלוּ זֶה בָזֶה, \u0010y19\u0011 לָא אַמְרִינָן שֶׁיְּשַׁלְּמוּ בַּמּוֹתָר נֶזֶק שָׁלֵם, דְּהָא קְצָת מֵחַבָּלָה שֶׁחָבַל בָּאִשָּׁה הוּא לְבַעְלָהּ, עַל כֵּן יְשַׁלֵּם הַחוֹבֵל בָּהּ הַשַּׁיָּךְ לְבַעְלָהּ, וּמַה שֶּׁשַׁיָּךְ לָאִשָּׁה מְנַכִּין לוֹ נֶגֶד חַבָּלָתוֹ (תְּשׁוּבַת רַשְׁבָּ\"א סִימָן תתקמ\"ח)\u0006.",["\u0003ולא הוציא מהם דם. \u0004 פי' דאז לא חייב מיתה על הכאתו דכתי' בסוף פ' אמור מכה בהמה ישלמנה ומכה אדם יומת והאי אדם ר\"ל לאביו ולאמו דזולתם לא היה חייב מיתה על הכאתם והוקש אהדדי הכאת אביו לענין מיתה להכאת בהמה לתשלומין מה מכה בהמה אינו חייב עליה בתשלומין אא\"כ עשה בה חבלה שמוציא ממנה דם דכתי' לפני זה מכה נפש בהמה ודם הוא הנפש אף מכה אביו כן ומה מכה בהמה בין שוגג בין מזיד דאדם מועד לעולם לחייב על נזקיו כן נמי מ\"ש מכה אדם יומת איירי אפי' במכה בשוגג לענין זה דשם מיתה עליו ואינו חייב אפי' בתשלומין על חבלתו דקם ליה בדרב' מיני' אם היה מזיד וה\"ה בשוגג לענין זה:","\u0003כיון שיש בו מיתת ב\"ד \u0004 פי' אם חבלו במזיד ומשום הכי אפי' בשוגג אינו חייב בתשלומין וכמ\"ש בסעיף שלפני זה וכ' הרמב\"ם אע\"ג דמקלקל הוא מ\"מ הואיל ועשה נחת רוח ליצרו בשעה שחבל בחבירו מ\"ה חייב מיתה אחבלה זו אם חבלו במזיד ומה\"ט חייב אע\"פ שאין עושה להנאתו ועפ\"ר:","\u0003ביום הכיפורים אפי' במזיד כו' \u0004 כצ\"ל וכ\"כ בטור ור\"ל בי\"כ דליכא מיתה אפי' בחובל או עשה מלאכה בו אפי' במזיד כי אם כרת ואף על גב דיש לאו עם הכרת שעושה מלאכה ביום הכפורים ולוקה עליה דלאו אם התרו בו וקי\"ל כל היכא דאיכא חיובי מלקות וחיוב ממון (על מעשה אחד ואין עושין שתיהן באדם אחד דרשעה אחת אנו מחייבין אותו) לוקין אותו ולא משלם שאני גבי חבלה דגלי לן קרא דיתן ממון ולא יהא לוקה דנתינה כתיב ביה וכמ\"ש לעיל בר\"ס ת\"ך ע\"ש:","\u0003בעבד כנעני שלו פטור \u0004 סתם וכ' דפטור ומשמע דאפי' הכהו מכה דאין בה שוה פרוטה ואין אומרים דחייב עליה מלקות ומטעם שכתבתי בפרישה ריש סימן ת\"ך ע\"ש ולא כמ\"ש ב\"י שם דבכה\"ג אפי' בשלו חייב מלקות ע\"ש. ולהב\"י צ\"ל דהכא דוקא במכה שיש בה ש\"פ ולמעלה איירי דאז משלם ומה שקנה עבד קנה רבו ועפ\"ר:","\u0003חמשה דברים \u0004 ואע\"פ דהריפוי צריך ליתן להרופא שירפאהו מ\"מ נ\"מ בזה אם אמדוהו שירפאהו בה' ימים ונתן לו החובל דמי הרפואה על ה' ימים ורפאו רבו בסם חריף בג' ימים המותר מדמי הרפוא' נשאר ביד רבו וזהו שסיים המחבר וכ' ואפי' צערו הרבה לעבד זה הנחבל בסם חריף ונתרפא כו' ונכון להגיה דלי\"ת דאפי' צערו במקום וי\"ו ואפי' ועד\"ז כ' בטור ע\"ש וק\"ל:","\u0003וחבלו בו אחרי' פטורי'. \u0004 ז\"ל הטו' אינו יכול להוצי' מהם לעצמו כיון שעדיין לא נגמר שחרורו ולא האדון יכול להוצי' מהן כו'. והראב\"ד השיג עליו וכ' ויש אומרים דכותבין הרשאה זה לזה וגובין אותו עכ\"ל הטור וכ' הב\"י שם בפנים דנ\"ל דהכל מודים בזה שאם כתבו הרשאות אדון להעבד או איפכא יכולין להוצי' מידו. ודומ' לזה כ' הטו' והמחב' בס\"ס מ\"ג ובסי' ר' בטו' ס\"ח ע\"ש ומהתימא על שהשמיטו המחבר כאן האי דין דהרשאה:","\u0003החובל בבת קטנה כו'. \u0004 המחבר השמיט כאן דין חובל בע\"ע וכתבו הרמב\"ם פ\"ד דחובל והטור בסי' זה ס\"ח דבעבדו העברי חייב בכולן ליתן להעבד חוץ משבת דישאר בידו אם העבד הוא שלו דבשבתו הוא מבטל ממלאכת רבו שחבלו. ובחבלו בו אחרים כתב הרמב\"ם ילקח בהן קרקע והרב אוכל מפירותיו כ\"ז שהוא אצלו וכשיצא לחירות יקח הקרקע לעצמו וכן דעת הרי\"ף וכן פסק ב\"י להלכה. ור\"ח פי' דשבת גדולה דהיינו דמי ידו ילקח בהן קרקע והרב יאכל פירות שהרי הוא מפסיד בקטיעת ידו מה שיש בין שאר מלאכות לשמירת קישואין לאחר שיתרפא (ר\"ל כשמשלם נזק דמי היד שקטע ממנו אינו משלם לו בעדו אלא מה שהיה עושה מלאכה בידו אבל עדיין הוא ראוי לשמור קישואין מיד שיתרפא מכאב קטיעת ידו וכמ\"ש לעיל סי' ת\"ך) ולכך יאכל פירות בעודו אצלו (כמו שהיה אוכל ממלאכת ידו שנקטעה) ולכשיצא לחרות יטלנה ושבת קטנה דהיינו שכר שומר קישואין כל ימי משך החולי כולו לרבו ולזה הסכים א\"א הרא\"ש ז\"ל ואם חבלו בדבר שאין בו הפסד לרבו כגון שקטע ראש אזנו או ראש חוטמו חבלתו לעבד ואין לרבו בו כלום עד כאן ל' הטור ועפ\"ר:","\u0003הפוחת אותה מכספה \u0004 פי' אם בא למכרה או להשיאה לאיש אין נותנין בעדה כל כך כמו שנותנין בעדה קודם חבלתו ובטור קאמר כגון שפצע' בפניה וכו' ור\"ל דאף אחר שנתרפאת מ\"מ עומד רושם המכה בפניה ונמאסת בה וכ\"ש אם קטע ממנה אבר אחד דמחוסרת אבר אחד שהוא נזק מבורר וידוע יותר ועפ\"ר:","\u0003הרי הוא של אב \u0004 דכתיב את בתי נתתי לאיש הרי שנתנה התורה ברשותו ליתן לאיזה איש שירצה והוא מקבל דמי קדושיה וגם כי ימכור איש את בתו כתיב וכיון דכסף קדושין ומכירתו שלו וזה פחתה מכספה לוקח האב דמי פחתה. ולא כע\"ש דכתב דמדכתיב בנעוריה בית אביה למדינן מיניה דכל שבנעוריה בית אביה היא דז\"א דבהדיא כתבו התוספות דההיא דוקא בהפרת נדרי' איירי וכתבו דאף דבגמ' נזכר לפעמי' האי קרא דבנעוריה בית אביה לא נקטו אלא לסימנא בעלמא ועפ\"ר:","\u0003וי\"א דווקא בסמוכה כו'. \u0004 נראה דאם אינה סמוכה על שלחנו אפי' אביה רוצה ליתן לה מזונות בימי חליה כדי ליקח לעצמו משבתה כדי להיות לו ממנו מותר דמי מזונותיה לאו כל כמיניה משא\"כ בחבל בה האב דכ' המ\"מ שם בדין י\"ט דבכה\"ג שבתה לאביה ע\"ש ודוק:","\u0003אבל אינה סמוכה היא שלה. \u0004 פי' אשבתה קאי דאז ניזונית בדמי שבתה אבל בדמי נזקה דמכירה וכסף קדושיה הנ\"ל אין חילוק:","\u0003אם אחרים חבלו בה \u0004 ל' הרא\"ש דבמידי דאתי לה מעלמא וע\"י צער לא קפיד:","\u0003יש אומרים דפטור \u0004 כמ\"ש בסמוך ר\"ל מיד בסעיף שאחר זה בדין אם חובל בבניו הגדולים וכמ\"ש המחבר שם והוא דעת הרמב\"ם ודין בן ובת שוה גם המ\"מ כתב אדברי הרמב\"ם כמ\"ש מור\"ם דמיירי דוק' באינה סמוכה ע\"ש סוף פ\"ד דחובל:","\u0003והקטני' ילקח בהן קרקע כו'. \u0004 בגמרא פליגי שני מ\"ד חד אמר דיקלא וחד אמר ס\"ת והרמב\"ם והמחבר כתבו קרקע במקום דיקלא דסביר' ליה דלא קאמר דיקל' אלא משום דדמים הללו השייכים לקטן בחבלתו אין בהן כדי לקנות בהן קרקע והיכא דאפשר לקנות בהן קרקע קרקע עדיפ' שקרנו קיים יותר וכן מצינו בגמ' בכמה מקומות שקונין קרקע והבעל אוכל פירותיו:","\u0003ויש אומרים ספר תורה. \u0004 פי' והקטנים ילמדו מתוכה והוא פירות דספר תורה והקרן קיימת להן עד שיגדלו ועיי' מה שכתבתי בדרישה ע\"ז מ\"ש זה מהא דאית' בגמרא פ\"ז דהמקבל פקדון מיד קטנים דהדין הוא דאין מחזירין הפקדון ליד הקטן ופליגי נמי בו הני שני מ\"ד חד אמר לא יחזירהו לקטן אלא יקנ' בו דיקל' וחד אמר ס\"ת ופסק שם בטור דיקנ' דקל וי\"ל דשאני הכא דהמעות הן ודאי שלקטן אלא שאין נותנין בידו מפני שיפסידו וס\"ל שטובתו הוא שיקנ' בהן ס\"ת וילמד מתוכה ואף אם יקלקלנ' לא איכפת לן בהך כיון שהוא שלו והוא טובתו משא\"כ התם דיש לחוש שיתברר של מי היה הממון לכך יקנה דקל דלא כליא קרנא אלא שצ\"ע מ\"ט דהרמב\"ם דפסק כאן כרבה דיקנה בהן דקל ובפ\"ו דפקדון פסק דיקנה בהן ס\"ת או דקל ויאכל פירותיו ואפש' דה\"ט דהכא שעדיין לא בא הממון ליד הקטן ס\"ל דאין קונים בעד הדמים ס\"ת ונותנין לו לפי שיכלה קרנם ואין לב\"ד לגרום שיצ' תקלה מתחת ידם אבל בפקדון דכבר היה מוחזק הממון ביד הקטן ומידו הפקיעו לזה הנפקד אלא שמחשש השבת אבידה נגעו בה דלמא יבואו הבעלים ויכירו את שלהם ס\"ל דאין לחוש כולי האי וקונים בעד הדמים אפי' ס\"ת ללמוד מתוכו וק\"ל:","\u0003אבל משלמין לאחר זמן. \u0004 ול\"ד לחש\"ו שחבלו מפני דהאשה והעבד הן בני דעת בשעה שחבלו דחייבין לשלם אלא שאין להם במה לשלם והטור כתב ע\"ז ז\"ל לפיכך שמין ב\"ד הה' דברים בשעה שחבלו באחרים וכותבין ונותנין אותו ביד הנחבל ולכשיהיה להן נכסים משלמין:","\u0003בטובת הנאה לשון הטור \u0004 פי' שאם תתאלמן או תתגרש יקחם הלוקח ואם תמות ישארו לבעל ואותה טובת הנאה שקבלו בהן תתנה לנחבל אבל אינה חייבת למכור כתובתה לשלם לנחבל עכ\"ל והטעם משום דקיימא לן המוכר שטר חוב לחברו וחזר ומחלו מחול וכמ\"ש הטור והמחבר לעיל סי' ס\"ו ואם תמכר שטר כתובתה שיש לה על בעלה לאחר והיא תמחול החוב שבשטר כתובתה לבעלה יפסידו הב\"ד להלוקח בידים וכי תימא תמכרה הכתובה לההוא דחבלה בו בטובת הנאה דאז אף אם תמחלה לבעלה לא קמפסיד דמה לי שיש לו עליה חוב של חבלתו או דמי הכתובה לאחר שתמחלה לבעלה מ\"מ כיון דודאי מחלה לגבי בעלה אטריחי רבנן בכדי למה לן כן הוא בגמ' דפרק החובל (דס\"ט) ושם ג\"כ הדין אם חבלה בבעלה דכתב המחבר אחר זה ושם ג\"כ הדין דאם יש לה נכסי מלוג ונצ\"ב שהן בעין ולא שייך בהו ה\"ט דמחלה לבעלה וע\"ל סי' שפ\"ח ס\"ב דכ' שם דאם אשה מסרה לאח' דמשמתינן לה וכ\"כ המרדכי בפ' החובל אהא שאמרו נשים ועבדים שפגיעתן רעה דמ\"מ משמתינן אותן ומלקין אותן שלא ירגילו לעשות כן ואפשר דדוקא במסירה וחבלה או בשאר בזיון דמבזין ס\"ל הכי ולא בחוב שעליה דאין עליה אלא חיוב ממון (וע\"ל סי' תכ\"א סי\"ג מ\"ש מדין בזיון אשה) וכתב בעל התרומות בשער ל\"ו דאם אין מי שירצה ליקח הנכסי מלוג או נכסי צאן ברזל בטובת הנאה יקחם הנחבל עצמו בטובת הנאה ואם יש מותר בטובת הנאה מדמי החבלה אין צריך ליתן הנחבל להאשה המותר עד שעה דקניא לנפשה ועיין לעיל בסי' שפ\"ח סעיף ב' דכתבתי דגם בהלואה דס\"ס צ\"ו ובשאלה (ונשאת) ונאנסה הבהמה דס\"ס שמ\"ו ובגניבה בסימן שמ\"ט דאם יש להנ\"מ ונצ\"ב ותוס' כתובה דג\"כ מחוייבת למכרה בטובת הנאה ולשלמ' וע\"ל ס\"ס שמ\"ו מ\"ש מזה ועפ\"ר מ\"ש עוד מזה:","\u0003אם היה תוספות בכתובתה או נ\"מ כו' \u0004 האי תוספות לא קאי אנכסי מלוג ואנצ\"ב דקאמר וגם בטור וברמב\"ם לא נזכר בדין זה נ\"מ וצ\"ב רק שהמחבר כללן יחד וכתב אשלשתן דהב\"ד כופין אותה למוכרו בטובת הנאה כל אחד כפי דינו דהיינו נצ\"ב ונ\"מ צריכה למכור לבעלה או לאחר כולן והמעות שתקבל צריכה ליתן לבעלה בדמי חבלתו ואם הבעל קנאה כבטובת הנאה אזי הבעל מנכה לה אותן דמים דדמי חבלתו ובתוס' כתובתה שאינה יכולה למכור לאחר מטעם הנ\"ל שתמחלה לבעלה כו' אזי אין לה קונה כ\"א הבעל עצמו והאי תוס' כתובתה ר\"ל שהוסיף לה בעלה זה כתובתה על דין כתובה דאורייתא דהיינו לבתולה מאתים דינרין צורי ולאלמנה מנה ומשום שהוצרך לכתוב אדין אם יש תוספות בכתובתה שימכרנה לבעלה בטובת הנאה ולא לאחר כתבו נמי כן אנצ\"ב ונ\"מ וסמך אהמחבר אפשיטיתו דבנצ\"ב ונ\"מ שהם בעין אין חילוק בין אם ימכרם לבעלה שחבל' בו או לאחרים וליכא למטעי בו. ומסיק וכ' ז\"ל ואם לא הי' לה ר\"ל דאין לה שום אחד משלשתן ואין לה אלא כתובה דאורייתא על בעלה אינה יכולה למכור כו' ור\"ל שאין יכולה למכור ממנה כלום בין בטובת הנאה בין שלא בטובת הנאה דהא חכמים שיערו הכתובה במנה ומאתים ושבפחות מזה אפי' פרוטה יש לחוש שתהא קלה בעיניו להוציאה מ\"ה אין תקנה לבעלה הנחבל לגבות ממנה דמי חבלתו אם לא שיגרשנה ויגבה מכתובתה דמי חבלתו או שיכתוב עליה שט\"ח וכדמסיק וק\"ל:","\u0003שהרי אם ירצה כו' \u0004 ל' הטור שאף אם לא תמכרנה לו בשביל חיוב כתובה לא ימנע מלהוציאה אם ירצה שהרי אינו צריך ליתן לה כתובה כיון שחייבת לו נגד החבל' אבל אם כתובתה מרובה מחבל' אין אומרים למכור לו (פי' בטובת הנאה דאז אף שהוא מרובה מדמי החבלה אין נותנין בהנאה דמי החבלה) כדי שלא תהא קלה בעיניו להוציא' ואלמלא המכר לא הי' מוציא' כיון שכתובת' מרובה מהחבלה עכ\"ל וכן הוא בטור והוא מגמרא שם בפ' החובל ע\"ש:","\u0003לא אמרינן שישלם במותר נזק שלם. \u0004 פי' שינכו דמי החבלים זה כנגד זה ודמי החבלה העולה יותר בא' מהשני ישלם לו השני החובלו נ\"ש וכמ\"ש הטור בס\"ס תכ\"א סי\"ט וגם המחבר כתבו שם סי\"ג ע\"ש קמ\"ל דבאיש שחבל באשה של איש אחר אין הדין כן והטעם שהאשה אין לה במה לשלם מה שחבלה באיש האחר ומה שחבל האיש האחר בה מגיע ממנו חלק לבעלה כמ\"ש הט\"ו מ\"ה קאמר דצריך האיש החובל באשה ליתן לבעלה כל חלקו מה שיגיע לו מדמי חבלתה והחלק השייך לה א\"צ ליתן לה פי' דה\"א דגם זה יתן וילקח בעלה באותן דמים שדה ויאכל פירות כל ימי חייה והאיש הנחבל לא יגבה דמי חבלתו עד שימות הבעל בחייה דאז יגבה האיש הנחבל לטרוף אותו שדה והמותר יגבה מדמי כתובתה קמ\"ל דלא ומשום דעשאוהו חז\"ל חלקה כנכסים שאין ידועים לבעלה שאין הבעל אוכל מהן פירות כל זה כתב שם בתשובת הרשב\"א ומ\"ה אותן דמים שמגיע בחלקה על שחבל בה הוא ינכה במה שהיא חייבת לו במה שחבלה בו ובהמותר יכתוב שטר עליהן וימתין עד שתתגרש או ימות בעלה:"],["\u0003 אם נתגרשה האשה כו' \u0004 ע' בתשו' רשד\"ם ס\"ס רי\"ז:"]],["\u0005הַגָּה: \u0010y0\u0011 כָּל חַיְבֵי מִיתוֹת בֵּית דִּין בַּזְּמַן הַזֶּה, אֵין בְּיָדֵנוּ לְהַלְקוֹתָן אוֹ לְהַגְלוֹתָן אוֹ לְהָרְגָן אוֹ לְחָבְטָן, אֶלָּא מְנַדִּין אוֹתָן וּמַבְדִּילִים אוֹתָן מִן הַקָּהָל (טוּר ס\"א בְּשֵׁם רַב נַטְרוֹנַאי גָאוֹן)\u0006. כָל זֶה מִצַּד הַדִּין, אֲבָל אִם רוֹאִין בֵּית דִּין שֶׁהוּא צֹרֶךְ שָׁעָה \u0010y1\u0011 וּמִגְדַּר מִלְּתָא, יְכוֹלִין לַעֲנֹשׁ בַּמֶּה שֶׁיִּרְצוּ \u0005(שָׁם וּבְשֵׁם תְּשׁוּבַת הַגָּאוֹן)\u0006 כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ב'. וְדַוְקָא בְּדִינֵי נְפָשׁוֹת הַצְּרִיכִין בֵּית דִּין, אֲבָל הַנֶּהֱרָגִין בְּלֹא בֵּית דִּין נִדּוֹנִין גַּם עַתָּה, כְּמוֹ שֶׁיִּתְבָּאֵר \u0005(טוּר שָׁם)\u0006 . הָרוֹדֵף אֶת חֲבֵרוֹ לְהָרְגוֹ, \u0010y2\u0011 וְהִזְהִירוּהוּ, וַהֲרֵי הוּא רוֹדֵף אַחֲרָיו, אֲפִלּוּ הָיָה הָרוֹדֵף קָטָן, \u0010y3\u0011 הֲרֵי כָּל יִשְׂרָאֵל מְצֻוִּים לְהַצִּילוֹ בְּאֵבֶר מֵאֶבְרֵי הָרוֹדֵף. וְאִם אֵינָם יְכוֹלִים לְכַוֵּן וְלֹא לְהַצִּילוֹ אֶלָּא אִם כֵּן יַהַרְגוּ לָרוֹדֵף, הֲרֵי אֵלּוּ הוֹרְגִים אוֹתוֹ \u0010y4\u0011 אַף עַל פִּי שֶׁעֲדַיִן לֹא הָרַג. \u0005הַגָּה: (טוּר ס\"ז)\u0006 \u0010y5\u0011 הַבָּא בַּמַּחְתֶּרֶת לִגְנֹב גַּם כֵּן דִּינוֹ כְּרוֹדֵף. וְאִם יָדוּעַ שֶׁלֹּא בָּא רַק עַל עֵסֶק מָמוֹן, וְאַף אִם יַעֲמֹד בַּעַל הַמָּמוֹן נֶגְדּוֹ לֹא יַהַרְגֵהוּ, אָסוּר לְהָרְגוֹ. וְעַיֵּן בְּדִבְרֵי הַטּוּר בְּסִימָן זֶה. מִי שֶׁמְּסַכֵּן רַבִּים, כְּגוֹן \u0010y6\u0011 שֶׁעוֹסֵק בְּזִיּוּפִים בְּמָקוֹם שֶׁהַמַּלְכֻיּוֹת מַקְפִּידוֹת, דִּינוֹ כְּרוֹדֵף וּמֻתָּר לְמָסְרוֹ לַמַּלְכוּת \u0005(נִמּוּקֵי מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שפ\"ח סי\"ב:\nלְפִיכָךְ, הַמְעֻבֶּרֶת שֶׁהִיא מַקְשָׁה לֵילֵד, מֻתָּר לַחְתֹּךְ הָעֻבָּר בְּמֵעֶיהָ, בֵּין בְּסַם בֵּין בַּיָּד, מִפְּנֵי שֶׁהוּא כְּרוֹדֵף אַחֲרֶיהָ לְהָרְגָהּ. וְאִם הוֹצִיא רֹאשׁוֹ, אֵין נוֹגְעִין בּוֹ, שֶׁאֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ \u0010y7\u0011 וְזֶהוּ טִבְעוֹ שֶׁל עוֹלָם.\nוְכֵן הָרוֹדֵף אַחַר הַזָּכָר אוֹ אַחַר אַחַת מִכָּל הָעֲרָיוֹת \u0005לְאָנְסָהּ,\u0006 \u0010y8\u0011 חוּץ מֵהַבְּהֵמָה, מַצִּילִין אוֹתוֹ אֲפִלּוּ בְּנֶפֶשׁ הָרוֹדֵף. וְאִם רָדַף אַחַר עֶרְוָה וְתָפַס וְשָׁכַב עִמָּהּ, \u0010y9\u0011 כֵּיוָן שֶׁהֶעֱרָה בָּהּ, אַף עַל פִּי שֶׁלֹּא גָמַר בִּיאָתוֹ, אֵין מְמִיתִין אוֹתוֹ עַד עָמְדוֹ בַּדִּין.\nרָדַף אַחַר עֶרְוָה, וַאֲחֵרִים הָיוּ רוֹדְפִים אַחֲרָיו לְהַצִּילָהּ, וְאָמְרָה לָהֶם: הַנִּיחוּהוּ \u0010y10\u0011 כְּדֵי שֶׁלֹּא יַהַרְגֵנִי, \u0010y11\u0011 אֵין שׁוֹמְעִין לָהּ, אֶלָּא מַבְהִילִין אוֹתוֹ וּמוֹנְעִין אוֹתוֹ עַל יְדֵי הַכָּאַת אֵבָרָיו, וְאִם אֵינָם יְכוֹלִים בְּאֵבָרָיו אֲפִלּוּ בְּנַפְשׁוֹ. \u0005הַגָּה: הַבָּא עַל הַגּוֹיָה בְּפַרְהֶסְיָא לְעֵינֵי עֲשָׂרָה יִשְׂרְאֵלִים, \u0010y12\u0011 קַנָּאִין פּוֹגְעִים בּוֹ וּמֻתָּרִין לְהָרְגוֹ. וְדַוְקָא בִּשְׁעַת מַעֲשֶׂה, אֲבָל אִם פֵּרַשׁ אָסוּר לְהָרְגוֹ. וְדַוְקָא שֶׁהִתְרוּ בּוֹ וְלֹא פֵרַשׁ. וְדַוְקָא שֶׁבָּא הַקַּנַּאי לְהָרְגוֹ מֵעַצְמוֹ, אֲבָל אִם שָׁאַל לְבֵית דִּין \u0010y13\u0011 אֵין מוֹרִין לוֹ כָּךְ:\u0006 \u0010y14\u0011\n\u0005(אֶפִּיקוֹרוֹס מִ)\u0006 [מִּינֵי] יִשְׂרָאֵל, וְהֵם עוֹבְדֵי עֲכּוּ\"ם; אוֹ עוֹשֶׂה עֲבֵרוֹת לְהַכְעִיס, אֲפִלּוּ אָכַל נְבֵלָה אוֹ לָבַשׁ שַׁעַטְנֵז לְהַכְעִיס, \u0005(הֲרֵי זֶה)\u0006 \u0005(אֶפִּיקוֹרוֹס)\u0006 ; [מִּין] וְהַכּוֹפְרִים בַּתּוֹרָה וּבַנְּבוּאָה; מִיִּשְׂרָאֵל מִצְוָה לְהָרְגָן. אִם יֵשׁ בְּיָדוֹ \u0010y15\u0011 כֹּחַ לְהָרְגָן בְּסַיִף בְּפַרְהֶסְיָא, הוֹרֵג; וְאִם לָאו, יָבֹא עֲלֵיהֶם בַּעֲלִילוֹת עַד שֶׁיְּסַבֵּב הֲרִיגָתָן. כֵּיצַד, רָאָה אֶחָד מֵהֶם שֶׁנָּפַל לִבְאֵר, וְהַסֻלָּם בַּבְּאֵר, \u0010y16\u0011 קוֹדֵם וּמְסַלְּקוֹ, וְאוֹמֵר: הֲרֵינִי טָרוּד לְהוֹרִיד בְּנִי מֵהַגַּג וְאַחֲזִירֶנּוּ לְךָ, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. אֲבָל \u0010y17\u0011 הַגּוֹיִים שֶׁאֵין בֵּינֵינוּ וּבֵינָם מִלְחָמָה, וְרוֹעֶה בְּהֵמָה דַקָּה מִיִּשְׂרָאֵל \u0010y18\u0011 בְּמָקוֹם שֶׁהַשָּׂדוֹת הֵם שֶׁל יִשְׂרָאֵל, וְכַיּוֹצֵא בָּהֶם, אֵין מְסוֹבְּבִין לָהֶם הַמִּיתָה, וְאָסוּר לַהֲצִילָן. \u0005(שָׁם [פ\"ד מֵרוֹצֵח] וי\"א ע\"ל סל\"ד סי\"ג וּבְסִימָן ת\"ט)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּיִשְׂרָאֵל בַּעַל עֲבֵרוֹת וְהוּא עוֹמֵד בְּרִשְׁעוֹ וְשׁוֹנֶה בּוֹ תָּמִיד, כְּגוֹן רוֹעֶה בְּהֵמָה דַקָּה שֶׁפָּקְרוּ בְּגָזֵל וְהֵם הוֹלְכִים בְּאִוַּלְתָּם; אֲבָל יִשְׂרָאֵל בַּעַל עֲבֵרוֹת שֶׁאֵינוֹ עוֹמֵד בְּרִשְׁעוֹ תָּמִיד, אֶלָּא עוֹשֶׂה עֲבֵרוֹת לַהֲנָאַת עַצְמוֹ, \u0010y19\u0011 כְּגוֹן אוֹכֵל נְבֵלוֹת לְתֵיאָבוֹן, \u0010y20\u0011 \u0010c0\u0011 מִצְוָה לְהַצִּילוֹ, וְאָסוּר לַעֲמֹד עַל דָּמוֹ. \u0005(שָׁם ד\"ג)\u0006 \u0005עַיֵּן בְּיוֹרֶה דֵעָה סִימָן קנ\"ח.\u0006",["\u0003כל חייבי מיתות ב\"ד בזמן הזה אין בידינו להלקותו כו' \u0004 כל' זה כ' ג\"כ הטור בשם רב נטרונאי גאון והא דכ' בחייבי מיתות וכ' עליהן להלקותן ולחבטן כתבתי בפרישה דנראה דה\"ק ל\"מ דאין דנין הד' מיתות עצמן כל א' כפי מה שצותה התורה אלא אפי' לעשות במקומו עונש אחר לדונו אין בידינו מצד הדין כ\"א מצד מגדר מילתא ע\"ש:","\u0003ומגדר מילתא כו' \u0004 פי' לעשות דין לזה שכבר נרצח או מוכה אין לנו לעשותו אבל למגדר מילתא אם יש לחוש שיעשהו ג\"כ אחרים להבא יגדרוהו כדי שלא יעשוהו עוד ועפ\"ר:","\u0003והזהירוהו כו'. \u0004 פי' א\"צ לעשות בו התראה ממש ושיקבל ההתראה אלא אמרינן לו זה שאתה רודף אחריו ישראל הוא והתורה אמרה שופך דם האדם באדם דמו ישפך ובדיעבד אפי' לא אמרו לו אפי' זה אפ\"ה מצילין הנרדף בנפשו של רודף וראיה מקטן שרודף דאיני בר הבחנת האזהרה הוא וקאמר גם כן הורגין אתו להציל ממנו ועפ\"ר:","\u0003הרי כל ישראל מצווי' להצילו. \u0004 למדו זה מדכתיב [בפרשת כי תצא] ולנערה לא תעשה דבר צעקה (בשדה) ואין מושיע לה משמע הא אם יש לה מושיע להצילה מזה הבא לאונסה היינו מצווין להושיע אותה מידו במאי דאפשר וממנו למדנו דין רודף להרוג לחבירו כי בתר קרא הנ\"ל מיד כתיב כי כאשר יקום איש על רעהו כו' ודרשו ואמרו ה\"ז בא ללמד ונמצא למד רוצח מנערה המאורס' מה נער' המאורס' ניתן להציל' בנפש זה הבא לאונסה וכמ\"ש כן דינו של הרודף אחר חבירו להרגו וגם למדנו נערה המאורס' מרוצח ואין כאן מקומו לכתבו:","\u0003אע\"פ שעדיין לא הרג \u0004 לאו למימרא דמכ\"ש אם כבר הרגו דחוזרים והורגים להרוצח דז\"א בזמנינו דאין דנין מיתת ב\"ד אלא ל' הרמב\"ם תפס והוא כ\"כ אמ\"ש שם לפני זה דין רוצח שאין הורגין אותו עד שיגמור דינו למיתה אחר שהרג אזה כתב דברודף אין הדין כן אלא ממיתין אותו אע\"פ שלא הרג ולא נגמר דינו בשום דבר:","\u0003הבא במחתרת כו'. \u0004 דין למדו מדכתיב בפ' משפטים] אם במחתרת ימצא הגנב והכה ומת אין לו דמים [פי' כאלו אין לו דם לזה הנרצח והוא מת מעיקרא] אם זרחה השמש עליו דמים לו והטעם דאין לו דמים מפני שכל גנב יודע שאין אדם עומד ורואה שגונבים ממנו ממונו ושותק ומתחלה בא אדעתא דהכי שבאם יעמוד בע\"ה לנגדו למחות בידו אזי יעמוד עליו להרגו וה\"ז כרודף ומותר להציל עצמו בנפשו ומ\"ש אם זרחה עליו השמש פשוטו של מקרא הוא דאם נמצא הגנב במחתרת ביום בעת זריחת השמש אז אמרינן דודאי לא בא הגנב על עסקי מיתה כי יודע שביום יהיו עוזרים הרבה לזה הנגנב כשיעמוד עליו להרגו ובודאי לא בא אלא אם יראה שיהיה הב\"ה במקום שגונב שישמיט ויצא אלא דא\"כ לא הל\"ל אלא ואם זרחה השמש \"עליו למה לי מ\"ה דרשו דבא ללמדינו שאם הוא ברור לנו כשמש שלא בא להרוג לב\"ה שבא לגנוב ממנו כגון שידוע הוא שאוהב נאמן הוא לו או שחתר האב לבנו דאז אפי' אין ידוע לנו אלא מסתמא אמרי' דהאב לבנו אינו בא להרוג אלא לגנוב יש לו דמים לאביו או לאוהב הנאמן בהריגתן כשבאו במחתרת אבל בן הבא על אביו לא אמרי' מסתמא שלא בא להרוג כן הוא בגמ' ועיין בטור מ\"ש עוד מזה פלוגתות ודעות:","\u0003שעוסק בזיופי' \u0004 כתב שם כגון מגזמי' בדליק' או שעוסקי' בחתיכות המטבעות ומ\"ש שהמלכיות מקפידות דקדק לכתוב שהמלכיות מקפידות דאל\"כ אין דינו כרודף וכ\"כ בהדיא שם בנימוקי מהר\"ם מרוזב\"ורק.","\u0003וזה טבעו של עולם \u0004 הוצרך לכתוב זה של\"ת הולד הרי הוא רודף ויצילו את אמו בנפשו קמ\"ל כיון שטבע של עולם בכך אין דין רודף עליו ואעפ\"כ בעודו במיעיה מותר לחתכו אע\"פ שהוא חי שכל שלא יצא לאויר העולם אין שם נפש עליו והא ראייה דהנוגף אשה הרה ויצאו ילדיה ומתו משלם דמי הולדות ואין שם רוצח ומיתה עליו וכמ\"ש לעיל סי' תכ\"ג:","\u0003חוץ מהבהמה \u0004 בגמ' ס\"פ בן סורר ומורה ילפי' דאין ניתן להצילו בנפשו של רודף אלא ערוה שיש בו קלון ופגם לנרדף כגון נערה המאורסה שנפגמה וזכר שאינו עומד להשתמש בו ויש בו קלון טובא וילפינין להו מדכתיב ולנערה לא תעשה דבר כו' עד ואין מושיע לה וכנ\"ל וכתיב נער וקרינן נערה ודרשינן הקרי והכתיב דנער ר\"ל הזכר ומיתורא דהמקרא דרשי' אפי' שאר עריות ויש בו גם כן מיעוט וממעטינן מיניה הרודף אחר הבהמה או לחלל שבת כו' דלית בהו קלון ופגם כלל:","\u0003כיון שהערה בה \u0004 דאין הורגין אותו אלא קודם שנפגמה ועפ\"ר:","\u0003כדי שלא יהרגני \u0004 פי' קודם שתשיגהו ימית אותי כשיראה שאת' רוצים להמית אותו בשבילי:","\u0003אין שומעין לה \u0004 משמע דוקא בכה\"ג דנוכל לומר דמקפדת על פגמה אלא שחשה לנפשה שמא ימיתנה ולכן אין שומעין לה דהתורה הקפיד' אפגם כזה שלא יעשה אבל אם אומרת הניחוהו ואל תהרגהו דנראה מדבריה שאינה חוששת אפגמ' בזה שומעין לה וכן משמע לשון הברייתא והרמב\"ם שכתבו שלא יהרגיני כמ\"ש המחבר אבל בטור כתב דאפי' בכה\"ג אין שומעין לה וכתב הב\"י דס\"ל דאפי' בכה\"ג י\"ל דמקפד' שלא יפגמה אלא שאינה רוצה שיהרג הרודף על ידה:","\u0003קנאין פוגעין בו. \u0004 ל' הטורמי שמקנה לשם יכול להורגו עכ\"ל והוא נלמד ממעשה דפנחס עם זמרי והוא הלכה למשה מסיני:","\u0003אין מורין לו \u0004 בטור מסיים וכ' ז\"ל ואפי' אם לא פירש והרג הבועל להמקנא אינו נהרג עליו עכ\"ל והוא מימר' בגמ' והתימא שהשמיטו מור\"ם ז\"ל ואפשר דמשום דהטור סיים וכ' אחר זה עוד ז\"ל הרג אדם אחר להמקנא נהרג עליו עכ\"ל וכ' ב\"י עליו דהוא פשוט ולא ניתן להכתב מרוב פשיטות ואגב שיטפא שהשמיט מור\"ם לאותו דין מרוב פשיטתו השמיט עמו ג\"כ זה דבחדא בבא כתבינהו הטור ע\"ש והיותר נרא' דמ\"ה השמיטו משום דלא כ' המחבר אלא הני עניני מיתה דיש בהן מגדר מילת' משא\"כ בזה דהבועל יכול לפרוש ולהרוג להמקנא דאין בו מגדר מילתא ואדרבה הטור אגב שיטפא לרבותא כתבו וק\"ל:","\u0003אפיקורס מישראל והם כו' \u0004 המחבר נמשך אחר נוסחת הרמב\"ם שבדפוס כסף משנה דספ\"ד דהל' רוצח ושמירת נפש אלא ששם לא כתב אחר זה כמ\"ש המחבר ז\"ל והאפיקורסי' והם שכופרי' בתורה כו' דלפ\"ז היא לשון שאינו מדוקדק דהרי כבר כ' דהאפיקורס הוא עכו\"ם כו' אלא כ' שם ז\"ל האפיקורסי' הן שעובדי' עכו\"ם כו' עד שעטנז להכעיס ה\"ז אפיקורס ושכופרין בתורה כו' ע\"ש אבל נוסח זה אינו עולה יפה דלפ\"ז הא שכ' ושכופרין בתורה אמאי קאי לכך נראה יותר מדוקדק נוסח ל' הרמב\"ם דדפוס גדול דכתב בו ז\"ל המינים מישראל והן ע\"א כו' עד ה\"ז אפיקורס והן שכופרים כו' וכן מצאתי בדפוס ישן נושן של הרמב\"ם וכן הוא לשון הטור ע\"ש:","\u0003להעבירן \u0004 בע\"ש כתב דנראה לו הטעם דמצוה להעבירן לכתחלה דומי' דעיר הנידחת וזה אינו נרא' לי דדוק' ביושבי עיר כולה או רובה הנידחת מצות' בסייף אבל ביחידי' בעובדי כו\"ם דינם בסקילה אלא שאין אנו לע\"ע דנין דין ד' מיתות האמורים בתורה מ\"ה קאמר מעבירין ונראה דל\"ד קאמר אלא כאלו אמר אם יש בידינו כח להעבירן הרי מצוה עלינו להעבירן לעין כל והנשארי' ישמעו וייראו ואם לאו לפחות יסבבו להן וכדמסיק:","\u0003קודם ומסלקו \u0004 כל' זה כ\"כ במיימוני ולפי הנראה היה נ\"ל למחוק הוי\"ו ומסלקו וה\"ק אם הסולם בבור קודם בואו אזי מסלקו משם ואומר הריני טרוד כו' ולפי הנוסח שלפנינו צריכין לפרש קודם ל' מקדים דמקדים נפשו ומסלקו:","\u0003שאין בינם ובינינו מלחמה \u0004 דאלו יש מלחמה ע\"ז אמרו טוב שבעכו\"ם הרוג והיינו מצו' להורידן ולסבב עליהן המיתה וכ\"כ התו' ועיין בספר שבט יהודה כ' בזה תשובה למינים והוא שטוב שבמדות העכו\"ם הוא זה שדנין דין הריגה ומיתה לחוטאין ואין מחפשין זכות לעושי עולה ועיין בי\"ד סי' קנ\"ח מדינים אלו:","\u0003במקום שהשדות הן של ישראל \u0004 פי' ל\"ד ארץ ישראל אלא בכ\"מ שיש לישראל שדות וכ\"כ לעיל סי' ל\"ד סי\"ג ואע\"ג דהמחבר כ' לעיל סי' ת\"ט דמותר לגדל בסוריא ומדברות בהמה דקה ומשמע לכאורה דאפי' דיש להישראל הדרים שם שדות דאל\"כ אפי' בא\"י נמי שרי וכדמסיק שם הרי לפנינו דדוקא בא\"י אסור היינו לענין איסור גידול בהמה דקה ומשום גזירה שמא יבא לרעות בשדות ישראל דלא גזרו כולי האי אלא בא\"י ומשום פסידא דא\"י אבל ודאי דאסור לרעותן בשדות של ישראל אפילו בשאר ארצות ובבהמה דקה החמירו ארועה שלהן דמסתמא אפי' אין רואה אותו שמרעה אותן בשדות ישראל כיון דהן קופצין ואזלי מעצמן ה\"ל לסלק מרעייתן ואף דלעיל סימן ל\"ד סי\"ג כ' הטור והמחבר שם הרועים בהמה גסה נמי פסולים הא כ' שם בצדו דהיינו דוקא בהמות של עצמן ומשום דחשדינן ליה שיניחם לרעות בשדות ישראל להנאתו משא\"כ כאן דמיירי גם ברועה בהמות של אחרים א\"נ לענין דאסור להצילם לא אמרו כי אם בהמה דקה ועמ\"ש עוד שם בסי' ל\"ד:","\u0003כגון אוכל נבילות לתיאבון. \u0004 פי' כשאינו מוצא בשר כשר כזה אוכל נבילות למלאות תאותו ולהכעיס מקרי שיש בנמצא בשר כזה ואוכל נבילה להכעיס מצות בוראו ית':","\u0003מצוה להצילו. \u0004 הב\"י כתב החילוק שיש בין מומר אוכל נבילות לתיאבון ובין רועה בהמה דקה (דאף שגם רועה לתאבון ולהנאת עצמו מניחו לרעות בשדות ישראל) דהרועה עושה עבירה מידי יום ביום וכל היום משא\"כ אוכל נבילות לתאבון ובפריש' כתבתי עוד חילוק והוא דהאוכל נבילות לתאבון אינו חוטא אלא להש\"י משא\"כ רועה דגוזל וחוטא לחבירו ישראל ע\"ש:"],["\u0003 מצוה להצילו כו'. \u0004 ומ\"מ אין מחויב לפדותו אם נשבע אלא דאם רוצה לפדותו אין איסור בדבר ב\"י ומור\"ם בי\"ד סי' רנ\"א ס\"ב ובסי' רנ\"ב שם סעיף ו' וב\"ח שם:"]],["הָרוֹאֶה אֶת חֲבֵרוֹ טוֹבֵעַ בַּיָּם, אוֹ לִסְטִים בָּאִין עָלָיו, אוֹ חַיָּה רָעָה בָּאָה עָלָיו, וְיָכוֹל לְהַצִּילוֹ הוּא בְּעַצְמוֹ \u0010y0\u0011 \u0010c0\u0011 אוֹ שֶׁיִּשְׂכֹּר אֲחֵרִים לְהַצִּיל, וְלֹא הִצִּיל; אוֹ שֶׁשָּׁמַע גּוֹיִם אוֹ מוֹסְרִים מְחַשְּׁבִים עָלָיו רָעָה, אוֹ טוֹמְנִים לוֹ פַּח וְלֹא גִלָּה אֹזֶן חֲבֵרוֹ וְהוֹדִיעוֹ; אוֹ שֶׁיָּדַע בְּגוֹי אוֹ בְּאַנָּס שֶׁהוּא בָּא עַל חֲבֵרוֹ, וְיָכוֹל לְפַיְּסוֹ בִּגְלַל חֲבֵרוֹ וּלְהָסִיר מַה שֶּׁבְּלִבּוֹ וְלֹא פִּיְּסוֹ, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, \u0010y1\u0011 עוֹבֵר עַל לֹא תַעֲמֹד עַל דַּם רֵעֶךָ \u0005(וַיִּקְרָא יט, טז)\u0006.",["\u0003שישכור אחרים. \u0004 דאילו להצילו בגופו מוהשבותו לו נפקא דאבידת גופו של חבירו צריך להשיב לו ומלא תעמוד על דם רעך מרבינן אפי' להוציא ממון ע\"י שישכור אחרים להצילו צריך. וכ' הרא\"ש והטור בסי' זה ז\"ל מיהו אם יש לו ממון להציל עצמו חייב לשלם לחבירו והביאו ברא\"ש ראיה לדבר ומהתימא שהשמיטו המחבר ומור\"ם ז\"ל:","\u0003עובר על לא תעמוד כו'. \u0004 ובהג\"מ כתבו דבירושלמי מסיק דצריך אפילו להכניס עצמו בספק סכנה עבור זה והביאו הב\"י וכ' ז\"ל ונראה שהטעם הוא מפני שהלה ודאי והוא ספק עכ\"ל גם זה השמיטו המחבר ומור\"ם ז\"ל ובזה י\"ל כיון שהפוסקים הרי\"ף והרמב\"ם והרא\"ש והטור לא הביאו בפסקיהן מ\"ה השמיטוהו ג\"כ:"],["\u0003 או שישכור אחרים כו' \u0004 עיין בסמ\"ע ס\"ק א' עד ומהתימה שהשמיטו המחבר ומור\"ם ז\"ל כו' כבר כתבו מור\"ם בי\"ד סי' רנ\"ג [רנ\"ב] ס\"ס י\"ב בהגהה בשם מרדכי ע\"ש וע\"ש בב\"י סכ\"ב בשם מהרי\"ו:"]],["\u0010y0\u0011 מִצְוֹת עֲשֵׂה לַעֲשׂוֹת אָדָם מַעֲקֶה לְגַגּוֹ, שֶׁנֶּאֱמַר: וְעָשִׂיתָ מַעֲקֶה לְגַגֶּךָ \u0010y1\u0011 \u0005(דְּבָרִים כב, ח)\u0006. וְהוּא שֶׁיִּהְיֶה בֵּית דִּירָה; אֲבָל בֵּית הָאוֹצָרוֹת וּבֵית הַבָּקָר וְכַיּוֹצֵא בָּהֶן, \u0010c0\u0011 אֵינוֹ זָקוּק לוֹ.\nכָּל בַּיִת \u0010y2\u0011 שֶׁאֵין בּוֹ ד' אַמּוֹת עַל ד' אַמּוֹת, פָּטוּר מִמַּעֲקֶה.\nבַּיִת \u0010y3\u0011 \u0010c1\u0011 שֶׁל שְׁנֵי שֻׁתָּפִים, חַיָּבִים בַּמַּעֲקֶה, שֶׁנֶּאֱמַר: כִּי יִפּוֹל הַנּוֹפֵל מִמֶּנּוּ \u0005(דְּבָרִים כב, ח)\u0006, לֹא תָּלָה אֶלָּא בַּנּוֹפֵל. אִם כֵּן לָמָּה נֶאֱמַר: גַּגֶּךָ \u0005(דְּבָרִים כב, ח)\u0006, לְמַעֵט בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, \u0010y4\u0011 לְפִי שֶׁאֵינָם עֲשׂוּיִים לְדִירָה.\nהָיְתָה \u0010y5\u0011 רְשׁוּת הָרַבִּים גָּבוֹהַּ מִגַּגּוֹ, \u0010y6\u0011 אֵינוֹ זָקוּק לְמַעֲקֶה, \u0010y7\u0011 שֶׁנֶּאֱמַר: כִּי יִפֹּל הַנוֹפֵל מִמֶּנּוּ \u0005(דְּבָרִים כב, ח)\u0006.\nגֹּבַהּ הַמַּעֲקֶה, אֵין פָּחוֹת \u0010y8\u0011 מִי' טְפָחִים, כְּדֵי שֶׁלֹּא יִפֹּל מִמֶּנּוּ הַנֹּפֵל. וְצָרִיךְ לִהְיוֹת הַמְּחִצָּה חֲזָקָה, כְּדֵי שֶׁיִּשָּׁעֵן אָדָם עָלֶיהָ וְלֹא תִּפֹּל.\nכָּל הַמַּנִּיחַ גַּגּוֹ בְּלֹא מַעֲקֶה בִּטֵּל מִצְוַת עֲשֵׂה; וְעָבַר עַל לֹא תַּעֲשֶׂה, שֶׁנֶּאֱמַר: וְלֹא תָשִׂים דָּמִים בְּבֵיתֶךָ \u0005(דְּבָרִים כב, ח)\u0006.\nאֶחָד הַגַּג \u0010y9\u0011 וְאֶחָד כָּל דָּבָר שֶׁיֵּשׁ בּוֹ סַכָּנָה וְרָאוּי שֶׁיִּכְשֹׁל בָּהּ אָדָם וְיָמוּת, כְּגוֹן שֶׁהָיְתָה לוֹ בְּאֵר \u0005(אוֹ בּוֹר)\u0006 בַּחֲצֵרוֹ, בֵּין שֶׁיֵּשׁ בּוֹ מַיִם בֵּין שֶׁאֵין בּוֹ מַיִם, חַיָּב לַעֲשׂוֹת חוּלְיָא גָבֹהַּ י' טְפָחִים, אוֹ לַעֲשׂוֹת לָהּ כִּסוּי, כְּדֵי שֶׁלֹּא יִפֹּל בָּהּ אָדָם וְיָמוּת.\nוְכֵן כָּל מִכְשׁוֹל שֶׁיֵּשׁ בּוֹ סַכָּנַת נְפָשׁוֹת, מִצְוַת עֲשֵׂה לַהֲסִירוֹ וּלְהִשָּׁמֵר מִמֶּנּוּ וּלְהִזָּהֵר בַּדָּבָר יָפֶה, שֶׁנֶּאֱמַר: הִשָּׁמֶר לְךָ וּשְׁמֹר נַפְשְׁךָ \u0005(דְּבָרִים ד, ט)\u0006. וְאִם לֹא הֵסִיר וְהִנִּיחַ הַמִּכְשׁוֹלוֹת הַמְבִיאִים לִידֵי סַכָּנָה בִּטֵּל מִצְוַת עֲשֵׂה \u0010y10\u0011 וְעָבַר בְּלֹא תָשִׂים דָּמִים \u0010y11\u0011 \u0005(דְּבָרִים ד, ט)\u0006.\nהַרְבֵּה דְּבָרִים אָסְרוּ חֲכָמִים מִפְּנֵי שֶׁיֵּשׁ בָּהֶם סַכָּנַת נְפָשׁוֹת, וּקְצָתָם נִתְבָּאֲרוּ בְּטוּר יו\"ד סִימָן קט\"ז, וְעוֹד יֵשׁ דְּבָרִים אֲחֵרִים, וְאֵלוּ הֵן: לֹא יַנִּיחַ פִּיו עַל הַסִילוֹן הַמְקַלֵּחַ וְיִשְׁתֶּה, וְלֹא יִשְׁתֶּה בַּלַּיְלָה מֵהַבְּאֵרוֹת וּמֵהָאֲגַמִּים, שֶׁמָּא יִבְלַע עֲלוּקָה וְהוּא אֵינוֹ רוֹאֶה. \u0005הַגָּה: וּכְבָר כָּתַבְתִּי דְבָרִים אֵלּוּ סִימָן קט\"ז בְּיוֹרֶה דֵעָה וע\"ש.\u0006\nכָּל הָעוֹבֵר עַל דְּבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶם, וְאָמַר: הֲרֵינִי מְסַכֵּן בְּעַצְמִי וּמַה לַּאֲחֵרִים עָלַי בְּכָךְ, אוֹ: אֵינִי מַקְפִּיד בְּכָךְ, מַכִּין אוֹתוֹ מַכַּת מַרְדוּת. וְהַנִּזְהָר מֵהֶם, עָלָיו תָּבֹא בִּרְכַּת טוֹב:",["\u0003מצות עשה לעשות אדם מעקה. \u0004 כל סימן זה ליתא בטור והמחבר העתיקו מדברי הרמב\"ם שכ' סי' זה אות באות בפי\"א מהל' רוצח ושמירת נפש ומפני שדינים שבסימנים שלפני זה מיירי מדיני רציחה ושמירת נפש כתבן ג\"כ הרמב\"ם שם באותן הלכות מ\"ה סידר וקבע המחבר גם לזה כאן כמו שסידרם הרמב\"ם בהל' א' מ\"ש:","\u0003והוא שיהיה בית דירה \u0004 בסמוך ס\"ג יתבאר דלא נאמר בתורה גגך אלא להוציא בתים שאינם עשויים לדירה ע\"ש וכתב הכ\"מ שם על דברי הרמב\"ם אע\"ג דבספרי מרבינן להני מקרא דחייבים במעקה וכן כתוב הסמ\"ג מ\"מתנאי יש בדבר לענין אם מחוייבים המה במזוזה ופוסק הרמב\"ם כמ\"ד דפטורים המה במזוזה וס\"ל דה\"ה לענין מעקה דלא מקרי ביתך וס\"ל דבספרי דמחייבי אתיא כתנא דס\"ל דגם במזוזה חייב ולית הלכתא כוותיה עכ\"ל בקיצור ואם כן תימא על המחבר שבהל' מזוזה בי\"ד ר\"ס רפ\"ו סתם וכ' דרפת בקר ולולין ובית אוצרות שמן ויין חייבים במזוזה וכדעת הרי\"ף והרא\"ש ודלא כהרמב\"ם וכמ\"ש שם וכאן במעק' סתם המחבר וכתב דאין חייב במעקה ודין מעקה נלמד מדין מזוזה וכמ\"ש ונראה דהרמב\"ם [דהמחב'] הכריע וס\"ל דלענין מעקה כיון דאין דרך בני אדם להיות להן בית תשמיש ע\"ג דבית הבקר ובית האוצר ובית העצים מ\"ה אף אם לפעמים יקרה דידור שם אדם מ\"מ אין יוצאים ונכנסים כ\"כ שם למיחש שיפול משם להצטרך מעקה משא\"כ במזוזה דחייבה התורה בשביל הדר להיות מצות ה' נגד עיניו בביאתו וביציאתו בזה פסק דהדר שם צריך לקבוע מזוזה באותו פתח וק\"ל:","\u0003שאין בו ד' אמות כו'. \u0004 שאז אינו בית תשמיש ואינו ראוי לדירה:","\u0003של שני שותפין כו'. \u0004 פי' אע\"ג דכתיב לגגך מ\"מ מדתלה התורה טעם המעקה משום חשש דיפלו ממנו מה לי שהבית הוא של א' או של שנים:","\u0003לפי שאינם עשויה לדירה ואפילו המחייבים בית בקר ובית אוצרות במעקה וכנ\"ל מ\"מ מודים בזה מפני שבית הכנסת אין שום גגך שייך בו כלל דאף של הבאים מעבר לים היא וכן פירש\"י בפ' ראשית הגז:\u0004","\u0003ר\"ה גבוה כו'. \u0004 פי' ויש לחוש שיפלו מר\"ה ע\"ג הגג:","\u0003אינו זקוק למעקה. \u0004 פי' ול\"ת שיעשה מעקה ע\"ג גגו מלמטה למעלה עד שיהא י' טפחים גבוה מר\"ה דכיון דבני ר\"ה קדירא דבי שותפי נינהו פשיטא דאין עליהן לעשות מעקה לרה\"ר:","\u0003שנאמר כי יפול הנופל ממנו. \u0004 פי' ודרז\"ל ממנו ולא לתוכו וק\"ק ל\"ל מיעוטא דממנו ולא לתוכו הא בלה\"נ יכול הב\"ה לומר אי לא היה ביתי מכ\"ש שהיה נחבט וניזק או מת מנפילתו מגבהות ר\"ה לארץ ובדוחק י\"ל דה\"א דהיו צריכין למלאות במקום ביתו בעפר כדי להשותו ממטה לר\"ה:","\u0003מי' טפחים. \u0004 משמע מכל סביבו והיינו דלא כסמ\"ג ודלא כהראב\"ד בהשגותיו וע\"ש בכ\"מ דמפרש במאי פליגי:","\u0003ואחד כל דבר כו'. \u0004 בספרי מרבה כל הני מדכתי' ולא תשים דמים בביתך:","\u0003ועבר בלא תשים דמים \u0004 וז\"ל ד\"מ בסי' תכ\"ו כ' הרמב\"ם בהל' אבל בפי\"ד מצות עשה מדבריהם ללות אורחים ואמרו רז\"ל כל מי שאינו מלווה כאלו שופך דמים וכופין ללויה כדרך שכופין לצדקה כו' עד אפילו המלווה לחבירו ד' אמות יש לו שכר הרבה וכמה שיעור לויה שחייב אדם בה הרב לתלמיד עד עיבורה של עיר וא' לחבירו עד תחום שבת ותלמיד לרבו עד פרסה ואם היה רבו מובהק עד ג' פרסאות עכ\"ל רמב\"ם. ובילקוט מהר\"ש מצאתי האידנא אין נוהגין ללות תלמיד לרבו עד פרסה משום דבזמן הזה מוחלים על כבודם ויש לילך עמו או עם חבירו עד השער או לכל הפחות ד' אמות עכ\"ל וכ' הרמב\"ם עוד גמילות חסדים שבגופו שאין להן שיעור כגון ביקור חולים וניחום אבלים והוצאת המת והכנסת כלה והלוית אורחים אע\"פ שכל מצות אלו מדבריהם הרי הם בכלל ואהבת לרעך כמוך כל הדברים שאתה רוצה שיעשו אותן לך אחרים עשה אתה לאחיך בתורה ובמצות ושכר הלוית אורחים מרובה מן הכל והוא החוק שחקק אברהם אבינו ודרך החסד שנהג בהם מאכיל עוברי דרכים ומשקה אותן ומלווה אותן וגדולה הכנסת אורחים מקבלת פני השכינה שנאמר וירא והנה שלשה אנשים וירץ לקראתם ולוי תן יותר מהכנסתם עכ\"ל רמב\"ם וכן הוא במדרש בפרשת וירא עכ\"ל ד\"מ:","\u0003הרבה דברים אסרו כו'. \u0004 מדכתיב השמר לך ושמור נפשך מאוד:"],["\u0003 אינו זקוק לו כו'. \u0004 עיין בתשו' מבי\"ט ח\"ב סי' ק\"י:","\u0003 של שני שותפים כו'. \u0004 ובשותף עכו\"ם פסק ביש\"ש פי\"א דחולין דחייב ע\"ש אמנ' לפי מה שפסק מור\"ם בי\"ד סי' רפ\"ו ס\"א בהגה במזוזה דפטור' אפשר דהוא הדין במעקה ולפי המרדכי דע\"ז יש להסתפק:"]]]};
